// Team — the body of the Pull-requests screen's third tab. A review
// radar over open PRs from teammates across the orgs you belong to,
// bucketed by how much you can unblock. Rendered inside the shared
// PullsScreen shell (which owns the PyorWindow + tab bar); this component
// owns the radar's data, filter row, and list, and publishes its chrome
// (subtitle / status / Refresh / tab count) up via usePullsChrome.
//
// Filtering is server-side: every control writes a search param (see
// useRadarFilters), so changing one re-fetches a complete result. The
// filter controls are populated from a scope-only facets query so they
// stay full even when a narrowing filter is applied. Sort, bucketing,
// and author ranking are client-side (not expressible as GitHub search).

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { toast } from 'sonner';
import { openPR } from '../router/nav';
import { GitHubError, requestReviewers } from '../github/client';
import { invalidatePrLists } from '../github/prQueries';
import { bucketTeamPRs, rankAuthors, type TeamPR } from '../github/teamLens';
import {
  useTeamFacets,
  useTeamPRs,
  useViewerLogin,
  useViewerOrgs,
  useViewerRepoActivity,
} from '../pr/team/useTeamData';
import { useRadarFilters } from '../pr/team/useRadarFilters';
import { SORT_LABEL, sortTeamPRs } from '../pr/team/radarSort';
import { buildSecOptions } from '../pr/team/radarSecondary';
import { RadarBody } from '../pr/team/RadarBody';
import { RadarFilterBar } from '../pr/team/RadarFilterBar';
import { RadarToolbar, TeamStatus } from '../pr/team/RadarChrome';
import { usePullsChrome } from '../pr/pullsChrome';

export function TeamRadarBody() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  // Identity + ranking inputs.
  const orgsQuery = useViewerOrgs();
  const loginQuery = useViewerLogin();
  const you = loginQuery.data ?? '';
  const orgs = orgsQuery.data ?? [];
  const repoWeights = useViewerRepoActivity().data ?? {};

  // URL ⇄ filter state + handlers.
  const f = useRadarFilters(orgs);

  // Data — list (server-filtered, paginated) + scope-only facets.
  const prsQuery = useTeamPRs(orgsQuery.data, loginQuery.data, f.filters);
  const allPRs = prsQuery.data?.pages.flatMap((p) => p.items) ?? [];
  const totalAvailable = prsQuery.data?.pages[0]?.total ?? allPRs.length;
  const facets = useTeamFacets(orgsQuery.data, loginQuery.data, f.scope).data ?? {
    rows: [],
    repos: [],
    labels: [],
  };

  // Derived (over the already server-filtered set). Author rail + filter
  // options come from the scope-only facets so they stay populated.
  const authorList = rankAuthors(facets.rows, repoWeights);
  const secOptions = buildSecOptions(facets);
  const buckets = bucketTeamPRs(sortTeamPRs(allPRs, f.sortKey)).filter(
    (b) => b.prs.length > 0,
  );
  const noReviewer = allPRs.filter((p) => p.reviewers.length === 0).length;
  const orgByKey = new Map(orgs.map((o) => [o.key, o]));

  const addMe = useMutation({
    mutationFn: (pr: TeamPR) =>
      requestReviewers(pr.owner, pr.repoName, pr.num, { users: [you] }),
    // Refresh every list the PR just moved between: it leaves the Team
    // "needs a reviewer" bucket AND enters your Reviewing lens. Without the
    // lens invalidation the Reviewing tab stays stale until the 60s poll.
    onSuccess: () => invalidatePrLists(queryClient),
    // The row already hides this action without WRITE+ access; this is a
    // backstop for the race where a stale permission lets the call through.
    onError: (err) =>
      toast.error(
        err instanceof GitHubError && err.status === 403
          ? "You don't have write access to request reviewers on this repo."
          : err instanceof Error
            ? err.message
            : 'Could not request review',
      ),
  });
  const onOpenPR = (pr: TeamPR) =>
    openPR(navigate, {
      owner: pr.owner,
      repo: pr.repoName,
      number: pr.num,
      from: 'pulls',
    });

  // Publish chrome to the shell (titlebar / status / Refresh).
  usePullsChrome(
    {
      subtitle: 'Team · review radar',
      toolbar: <RadarToolbar onRefresh={() => prsQuery.refetch()} />,
      status: (
        <TeamStatus
          you={you}
          orgs={orgs.length}
          sort={SORT_LABEL[f.sortKey].toLowerCase()}
          unassigned={noReviewer}
        />
      ),
    },
    [you, orgs.length, f.sortKey, noReviewer],
  );

  return (
    <>
      <RadarFilterBar
        orgs={orgs}
        org={f.org}
        onOrgChange={f.onOrgChange}
        authorList={authorList}
        authors={f.authors}
        you={you}
        onToggleAuthor={f.toggleAuthor}
        onClearAuthors={f.clearAuthors}
        anyScope={f.anyScope}
        onClearScope={f.clearScope}
        filteredCount={allPRs.length}
        totalCount={totalAvailable}
        sortKey={f.sortKey}
        onPickSort={f.onPickSort}
        secValues={f.secValues}
        secOptions={secOptions}
        onSecChange={f.setSecField}
        onSecReset={f.resetSec}
      />

      <div className="flex min-h-0 flex-1 flex-col bg-card">
        <RadarBody
          loading={prsQuery.isLoading || orgsQuery.isLoading}
          error={prsQuery.error instanceof Error ? prsQuery.error.message : null}
          noOrgs={orgsQuery.isSuccess && orgs.length === 0}
          buckets={buckets}
          orgByKey={orgByKey}
          you={you}
          pendingNum={addMe.isPending ? addMe.variables?.num : undefined}
          onOpen={onOpenPR}
          onAddMe={(pr) => addMe.mutate(pr)}
          onClear={f.showEverything}
          onRetry={() => void prsQuery.refetch()}
          hasNextPage={prsQuery.hasNextPage}
          loadingMore={prsQuery.isFetchingNextPage}
          loadedCount={allPRs.length}
          onLoadMore={() => void prsQuery.fetchNextPage()}
          refreshing={prsQuery.isPlaceholderData}
        />
      </div>
    </>
  );
}
