// AI assistance — NON-SECRET settings (ADR 0026). The enable flag, active
// provider, per-provider model override, the one-time disclosure ack, and
// the review guidelines. These are safe to keep in the same local prefs
// store as diff preferences. Provider KEYS are secret and live in
// aiKeyStore (Keychain on desktop / localStorage on web) — never here, and
// never in the synced preferences file.

export type AiProvider = 'anthropic' | 'openai';

export interface AiSettings {
  /** Master opt-in. Off by default; flips on only after the disclosure ack. */
  enabled: boolean;
  /** The user acknowledged the one-time "what AI can see" disclosure. */
  disclosureAcked: boolean;
  /** Which configured provider the features use (when both keys are set). */
  activeProvider: AiProvider;
  /** Optional advanced model override per provider; '' = provider default. */
  anthropicModel: string;
  openaiModel: string;
  /** Optional OpenAI-compatible base URL (Groq, Gemini, local Ollama, …).
   * '' = the real OpenAI API. Include the version path, e.g.
   * `https://api.groq.com/openai/v1` or `http://localhost:11434/v1`. */
  openaiBaseUrl: string;
  /** Reviewer house-style guidelines (markdown). Shapes inline hints only. */
  guidelines: string;
}

export const DEFAULT_AI_SETTINGS: AiSettings = {
  enabled: false,
  disclosureAcked: false,
  activeProvider: 'anthropic',
  anthropicModel: '',
  openaiModel: '',
  openaiBaseUrl: '',
  guidelines: '',
};

const KEY = 'pyor:aiSettings';

export function loadAiSettings(): AiSettings {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return DEFAULT_AI_SETTINGS;
    const parsed = JSON.parse(raw) as Partial<AiSettings>;
    return { ...DEFAULT_AI_SETTINGS, ...parsed };
  } catch {
    return DEFAULT_AI_SETTINGS;
  }
}

export function saveAiSettings(patch: Partial<AiSettings>): void {
  try {
    const next = { ...loadAiSettings(), ...patch };
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
    // private mode / quota — degrade silently (settings just don't persist)
  }
}
