// Tiny helper for animate-ui primitives: builds a typed context +
// provider whose `use*` hook throws if read outside the provider.
// Keeps the dialog/alert-dialog primitives from silently rendering
// with an undefined context.

import * as React from "react"

function getStrictContext<T>(
  name?: string,
): readonly [
  ({ value, children }: { value: T; children?: React.ReactNode }) => React.JSX.Element,
  () => T,
] {
  const Context = React.createContext<T | undefined>(undefined)

  const Provider = ({
    value,
    children,
  }: {
    value: T
    children?: React.ReactNode
  }) => <Context.Provider value={value}>{children}</Context.Provider>

  const useSafeContext = () => {
    const ctx = React.useContext(Context)
    if (ctx === undefined) {
      throw new Error(`useContext must be used within ${name ?? "a Provider"}`)
    }
    return ctx
  }

  return [Provider, useSafeContext] as const
}

export { getStrictContext }
