// AI provider keys — the SECRET credential class (ADR 0026). Stored exactly
// like the GitHub token: OS Keychain via Electron `safeStorage` on desktop,
// `localStorage` on web. NEVER the synced preferences file. On web it is a
// billing-attached secret in plaintext localStorage — the UI nudges the user
// to set a provider-side spend limit.
//
// Keys must be readable synchronously by the provider adapter at call time,
// but Keychain reads are async — so we keep a hydrated in-memory snapshot
// (loaded once via hydrateAiKeys) and a useSyncExternalStore-friendly
// subscription. Writes update Keychain/localStorage AND the snapshot.

import { bridge } from '@/desktop/electronBridge';
import type { AiProvider } from './aiSettings';

const LS_KEY: Record<AiProvider, string> = {
  anthropic: 'pyor:aiKey:anthropic',
  openai: 'pyor:aiKey:openai',
};

type Snapshot = Record<AiProvider, string | null>;

let snapshot: Snapshot = { anthropic: null, openai: null };
let hydrated = false;
const listeners = new Set<() => void>();

function emit() {
  // New object identity so useSyncExternalStore detects the change.
  snapshot = { ...snapshot };
  listeners.forEach((l) => l());
}

/** Load keys from the platform store into the in-memory snapshot. Call once
 * (e.g. when the settings card mounts, or app boot). Idempotent. */
export async function hydrateAiKeys(): Promise<void> {
  const br = bridge();
  if (br?.aiKeyGet) {
    const [anthropic, openai] = await Promise.all([
      br.aiKeyGet('anthropic').catch(() => null),
      br.aiKeyGet('openai').catch(() => null),
    ]);
    snapshot = { anthropic: anthropic ?? null, openai: openai ?? null };
  } else {
    snapshot = {
      anthropic: safeRead(LS_KEY.anthropic),
      openai: safeRead(LS_KEY.openai),
    };
  }
  hydrated = true;
  emit();
}

function safeRead(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

export function getAiKey(provider: AiProvider): string | null {
  return snapshot[provider];
}

export function getAiKeysSnapshot(): Snapshot {
  return snapshot;
}

export function isHydrated(): boolean {
  return hydrated;
}

export async function setAiKey(provider: AiProvider, key: string): Promise<void> {
  const trimmed = key.trim();
  const br = bridge();
  if (br?.aiKeySet) {
    await br.aiKeySet(provider, trimmed);
  } else {
    try {
      localStorage.setItem(LS_KEY[provider], trimmed);
    } catch {
      throw new Error('Pyor could not persist the AI provider key on this device.');
    }
  }
  snapshot[provider] = trimmed;
  emit();
}

export async function clearAiKey(provider: AiProvider): Promise<void> {
  const br = bridge();
  if (br?.aiKeyClear) {
    await br.aiKeyClear(provider);
  } else {
    try {
      localStorage.removeItem(LS_KEY[provider]);
    } catch {
      /* no-op */
    }
  }
  snapshot[provider] = null;
  emit();
}

export function subscribeAiKeys(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

// One-time eager hydration per page load. Not driven by React Query (whose
// persisted cache would skip the queryFn on reload and leave the snapshot
// empty), just a module-scoped idempotent guard. Safe to call every render.
let hydrationStarted = false;
export function ensureAiKeysHydrated(): void {
  if (hydrationStarted) return;
  hydrationStarted = true;
  void hydrateAiKeys();
}
