// Org scope as a compact segmented glyph control — All · EM · EL · AV.
// Active option gets a white (raised) surface; inactive options dim.

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import type { TeamOrg } from '../../github/teamLens';
import { OrgGlyph } from './TeamBits';

export function OrgSegmented({
  orgs,
  value,
  onChange,
}: {
  orgs: TeamOrg[];
  value: string;
  onChange: (key: string) => void;
}) {
  return (
    <div className="inline-flex items-center gap-0.5 rounded-md bg-muted p-0.5">
      <button
        type="button"
        onClick={() => onChange('all')}
        className={cn(
          'inline-flex h-6 items-center justify-center rounded px-2 text-[11.5px] font-medium transition',
          value === 'all'
            ? 'bg-background text-foreground shadow-sm'
            : 'text-muted-foreground opacity-60 hover:opacity-100',
        )}
      >
        All
      </button>
      {orgs.map((o) => {
        const on = value === o.key;
        return (
          <Tooltip key={o.key}>
            <TooltipTrigger asChild>
              <button
                type="button"
                onClick={() => onChange(o.key)}
                className={cn(
                  'inline-flex h-6 items-center justify-center rounded px-1.5 transition',
                  on
                    ? 'bg-background shadow-sm'
                    : 'opacity-55 hover:opacity-100',
                )}
              >
                <OrgGlyph org={o} className="size-4" text="text-[7px]" />
              </button>
            </TooltipTrigger>
            <TooltipContent>{o.name}</TooltipContent>
          </Tooltip>
        );
      })}
    </div>
  );
}
