// PyorWindow — the app chrome shell.
//
// Flat titlebar with a title/subtitle, optional sidebar slot (per-screen
// only — the app-level sidebar is shadcn's Sidebar primitive at the
// App shell level), optional toolbar region in the titlebar, optional
// status bar.
//
// Shadcn-only per ADR 0011: no useT, no inline static styles.
//
// Title bar placement: inside the app shell the titlebar content is
// portaled into a single full-width strip Shell renders above the navbar
// (see titlebarSlot) — so the bar spans the whole window and the macOS
// traffic-light controls sit in its left gutter. Standalone surfaces
// (pre-auth screens, the design harness) have no shell slot, so the
// titlebar renders inline atop this window, reserving the traffic-light
// width itself via `flushLeft`.

import type { CSSProperties, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { ConnStatusItem } from './connectivity/ConnStatusItem';
import { isElectron } from '../desktop/electronBridge';
import { useTitlebarSlot } from './titlebarSlot';
import { cn } from '@/lib/utils';

interface PyorWindowProps {
  width?: number | string;
  height?: number | string;
  children?: ReactNode;
  title?: string;
  subtitle?: string;
  /** Per-screen secondary sidebar (e.g. Settings nav, file rail).
   * The app-level navigation rail is provided by shadcn's Sidebar
   * primitive at the App shell level — PyorWindow doesn't host it. */
  sidebar?: ReactNode;
  sidebarWidth?: number;
  toolbar?: ReactNode;
  status?: ReactNode;
  /** When true the window fills its parent (no rounded shadow border). */
  fluid?: boolean;
  /** When true the titlebar (title + toolbar slot) is not rendered.
   * Used by surfaces that have moved
   * the title + actions into their own page-level header (e.g.
   * PRHeader's breadcrumb row). Children still render via the
   * `toolbar` prop's sr-only escape hatches (e.g. SkippedBanner's
   * hidden GitHub-URL anchor), so we mount the toolbar node inline
   * with `display:contents` rather than throwing it away. */
  hideTitlebar?: boolean;
  /** Suppress the global bottom status bar (connectivity dot + per-screen
   * status). Used by pre-auth surfaces like Setup, where there's no
   * session to report a connectivity state for. */
  hideStatusBar?: boolean;
  /** True when this window's titlebar is flush against the OS window's
   * left edge — i.e. there's no app navigation rail to its left (the
   * pre-auth surfaces, which render outside the Shell sidebar). On the
   * macOS desktop build the titlebar must then reserve the full
   * traffic-light width itself; with the app rail present, the rail's
   * corner block already covers the controls and only the small overhang
   * needs clearing. No effect on the web build. */
  flushLeft?: boolean;
}

export function PyorWindow({
  width,
  height,
  children,
  title,
  subtitle,
  sidebar,
  sidebarWidth = 232,
  toolbar,
  status,
  fluid = false,
  hideTitlebar = false,
  hideStatusBar = false,
  flushLeft = false,
}: PyorWindowProps) {
  // The titlebar gutter on the left spans the per-screen sidebar
  // (if any) so the title aligns past the rail boundary, not above
  // the rail itself.
  const leftRailsWidth = sidebar ? sidebarWidth : 0;
  // Runtime-dynamic dimensions when not fluid — these come from the
  // design-canvas harness in dev (the artboard widths), so they're
  // legitimately dynamic per ADR 0011's carve-out.
  const containerStyle: CSSProperties | undefined = fluid
    ? undefined
    : { width, height };
  // The bottom status bar hosts the global connectivity dot, which reads
  // app-level query state via useConnectivity → it must only mount inside
  // the real app (under the query providers), not the static design
  // harness. `fluid` is true for every routed app screen and unset in the
  // harness, so it's the correct gate. Pre-auth surfaces (Setup) opt out
  // via `hideStatusBar` — there's no session to report connectivity for.
  // The bar then shows on every authenticated app screen, with or without
  // per-screen `status` content.
  const showStatusBar = fluid && !hideStatusBar;
  // Inside the app shell the titlebar portals into Shell's full-width
  // strip; standalone (undefined slot) it renders inline atop this window.
  const slot = useTitlebarSlot();
  const inApp = slot !== undefined;
  return (
    <div
      className={
        fluid
          ? 'relative flex h-full w-full flex-col bg-background font-sans text-[13px] text-foreground'
          : 'relative flex flex-col overflow-hidden rounded-xl bg-background font-sans text-[13px] text-foreground shadow-[0_24px_60px_rgba(0,0,0,0.22),0_6px_14px_rgba(0,0,0,0.08)] ring-1 ring-black/15'
      }
      style={containerStyle}
    >
      {hideTitlebar ? (
        // Hidden titlebar: keep the toolbar node mounted in a hidden
        // wrapper so sr-only / data-attribute escape hatches (the
        // hidden GitHub URL anchor used by SkippedBanner) still resolve.
        toolbar ? (
          <div className="sr-only" aria-hidden>
            {toolbar}
          </div>
        ) : null
      ) : inApp ? (
        // App shell present: portal the titlebar content into the
        // full-width strip above the navbar. Renders nothing until the
        // strip node mounts (slot becomes non-null).
        slot &&
        createPortal(
          <TitlebarContent
            title={title}
            subtitle={subtitle}
            toolbar={toolbar}
          />,
          slot,
        )
      ) : (
        <Titlebar
          title={title}
          subtitle={subtitle}
          leftRailsWidth={leftRailsWidth}
          toolbar={toolbar}
          flushLeft={flushLeft}
        />
      )}
      <div className="flex min-h-0 flex-1">
        {sidebar && (
          <div
            className="flex min-h-0 shrink-0 flex-col border-r bg-muted/30"
            style={{ width: sidebarWidth }}
          >
            {sidebar}
          </div>
        )}
        <div className="flex min-w-0 flex-1 flex-col bg-background">
          {children}
        </div>
      </div>
      {/* Global bottom status bar. The per-screen `status` content sits
          on the left; the shared connectivity dot (ConnStatusItem) is
          pinned right so every screen carries the same staleness cue
          without wiring it in five places. The bar always renders so the
          connectivity cue is present even on screens with no own status.
          `fluid` gates it to the real app chrome (skips the dev/design
          harness, which mounts PyorWindow outside the app providers). */}
      {showStatusBar && (
        <div className="flex h-[22px] items-center gap-2 border-t bg-muted/30 px-2.5 text-[11px] text-muted-foreground">
          {status}
          <span className="ml-auto flex items-center">
            <ConnStatusItem />
          </span>
        </div>
      )}
    </div>
  );
}

// Inline titlebar bar — the full chrome strip (height + bg + border),
// drawn atop the window by standalone surfaces (pre-auth / harness) that
// have no app shell to portal into.
function Titlebar({
  title,
  subtitle,
  leftRailsWidth,
  toolbar,
  flushLeft,
}: {
  title?: string;
  subtitle?: string;
  leftRailsWidth: number;
  toolbar?: ReactNode;
  flushLeft: boolean;
}) {
  // macOS traffic-light controls span ~66px from the window's left edge.
  // When there's no per-screen sidebar the title sits at the leading edge
  // of the bar, so on the desktop build add left padding to keep the dots
  // clear of the title text. flushLeft (no rail at all) reserves the full
  // control width; otherwise only the overhang past a rail needs clearing.
  const trafficLightGutter = isElectron() && leftRailsWidth === 0;
  const gutterClass = trafficLightGutter
    ? flushLeft
      ? 'pl-[72px]'
      : 'pl-7'
    : '';
  return (
    <div
      className={cn(
        'flex h-[38px] w-full shrink-0 items-stretch border-b bg-muted/40',
        isElectron() && '[-webkit-app-region:drag]',
      )}
    >
      {leftRailsWidth > 0 && (
        // Per-screen sidebar present: an empty left cell spanning the
        // rail width keeps the title aligned past the rail boundary and
        // preserves the rail's right border in the chrome.
        <div
          className="flex items-center border-r"
          style={{ width: leftRailsWidth }}
          aria-hidden
        />
      )}
      <TitlebarContent
        title={title}
        subtitle={subtitle}
        toolbar={toolbar}
        leadingClass={gutterClass}
      />
    </div>
  );
}

// Inner titlebar row — title/subtitle + right-aligned toolbar. Shared by
// the inline bar above and the shell strip (via portal), so it carries no
// height/background of its own. The toolbar is marked no-drag so its
// buttons stay clickable inside the draggable strip.
function TitlebarContent({
  title,
  subtitle,
  toolbar,
  leadingClass = '',
}: {
  title?: string;
  subtitle?: string;
  toolbar?: ReactNode;
  leadingClass?: string;
}) {
  return (
    <div
      className={cn(
        'flex min-w-0 flex-1 items-center gap-3 px-3.5',
        leadingClass,
      )}
    >
      {title && (
        <div className="flex min-w-0 items-baseline gap-2">
          <span className="truncate text-[13px] font-semibold text-foreground">
            {title}
          </span>
          {subtitle && (
            <span className="truncate text-[12px] text-muted-foreground">
              {subtitle}
            </span>
          )}
        </div>
      )}
      <div className="flex-1" />
      {toolbar && (
        <div className="flex items-center gap-3 [-webkit-app-region:no-drag]">
          {toolbar}
        </div>
      )}
    </div>
  );
}
