// Symbol-navigation controller. Single-click highlights a symbol's occurrences
// (read/write/def), ⌘/Ctrl-click jumps to its definition, the floating chip
// cycles occurrences, hovering an identifier shows a faint clickable hint, and
// Esc / off-token click clears. Returns onItemPostRender + the chip overlay.

import { useCallback, useEffect, useRef, type RefObject } from 'react';

import { adoptInto, clearOccurrences, paint, paintFlash, paintHover } from './painter';
import {
  containerForPath,
  diffContainers,
  diffScroller,
  hitTest,
  lineEl,
  occurrenceRect,
  rangeWithinLine,
  lineFlashRange,
  titleOf,
  type DiffSide,
} from './dom';
import { langForPath } from './languages';
import { symbolNav } from './client';
import { expandHunkForLine, type HunkExpandable } from '../../pr/changes/expandHunksForThreads';
import type { Hunk } from '@pierre/diffs';
import type { ChipAnchor } from './SymbolChip';
import type { ChipState, SymbolNavOverlayHandle } from './SymbolNavOverlay';
import type { Occurrence, OutlineSymbol } from './types';

const COACH_KEY = 'pyor-symnav-coach-v1';

export interface SymbolNavOptions {
  enabled: boolean;
  getFileText: (path: string, side: DiffSide) => string | undefined;
  /** Scroll a (possibly virtualized) line into view via the diff's own handle.
   * line is 1-based. Without it, reveal can only flash already-rendered lines. */
  scrollToLine?: (path: string, side: DiffSide, line: number) => void;
  /** Imperative handle to the (sibling) overlay that owns chip/outline/coach
   * state. Driven imperatively so its updates never re-render the diff. */
  overlayRef: RefObject<SymbolNavOverlayHandle | null>;
  /** Emitted when the active symbol selection changes (click / cycle / clear),
   * so a consumer can paint the occurrences on the overview ruler. `lines` are
   * 1-based on `side`; `activeIndex` is the focused occurrence. null on clear.
   * Fired on discrete user actions only (never per scroll frame). */
  onActiveOccurrences?: (
    s: { filename: string; side: DiffSide; lines: number[]; activeIndex: number } | null,
  ) => void;
}

interface ActiveSelection {
  path: string;
  side: DiffSide;
  symbol: string;
  occ: Occurrence[];
  hasDef: boolean;
}

function hashText(t: string): string {
  let h = 5381;
  for (let i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) | 0;
  return `${t.length}:${h}`;
}

export function useSymbolNav(opts: SymbolNavOptions): {
  onItemPostRender: (node: HTMLElement, instance?: unknown) => void;
  cycle: (dir: 1 | -1) => void;
  gotoDef: () => void;
  clear: () => void;
  /** Jump to a specific occurrence index (drives ruler-dot clicks). */
  revealOccurrence: (index: number) => void;
  onSelectSymbol: (s: OutlineSymbol, path: string) => void;
} {
  const optsRef = useRef(opts);
  optsRef.current = opts;
  const activeRef = useRef<ActiveSelection | null>(null);
  const cycleRef = useRef(0);
  // While a programmatic reveal (cycle / go-to-def) is scrolling, don't let the
  // scroll handler close the chip — it should follow to the target instead.
  const suppressScrollCloseUntil = useRef(0);
  const currentFileRef = useRef<string | null>(null);
  // Monotonic click generation — a resolve() that finishes after a newer click
  // (or after the selection was cleared) must not paint/clear over it.
  const clickSeqRef = useRef(0);
  const flashRef = useRef<{ path: string; side: DiffSide; row0: number } | null>(null);
  // Per-file lib instance (for hunk auto-expand on jump), keyed by path.
  const instancesRef = useRef<Map<string, { instance: HunkExpandable; hunks: readonly Hunk[] }>>(
    new Map(),
  );
  // Clickable identifier ranges per `${path}:${side}` — gates the hover hint to
  // referenceable symbols only. Row -> [startCol, endCol][]. Fetched once/file.
  const idCacheRef = useRef<
    Map<string, { version: string; byRow: Map<number, Array<[number, number]>> }>
  >(new Map());
  const idInflightRef = useRef<Set<string>>(new Set());
  const lastHoverRef = useRef<{ path: string; side: DiffSide; row: number; column: number } | null>(
    null,
  );
  // Drive the sibling overlay imperatively — never via local state, so symbol-nav
  // UI changes don't re-render the diff (which breaks its virtualization mid-scroll).
  const setChip = useCallback(
    (s: ChipState | null) => optsRef.current.overlayRef.current?.setChip(s),
    [],
  );
  const setOutline = useCallback(
    (s: { path: string; symbols: OutlineSymbol[] } | null) =>
      optsRef.current.overlayRef.current?.setOutline(s),
    [],
  );
  const setCoach = useCallback(
    (a: ChipAnchor | null) => optsRef.current.overlayRef.current?.setCoach(a),
    [],
  );
  const coachSeenRef = useRef<boolean>(
    typeof localStorage !== 'undefined' && localStorage.getItem(COACH_KEY) === '1',
  );

  const repaint = useCallback(() => {
    const active = activeRef.current;
    if (!active) return;
    const container = containerForPath(active.path);
    if (!container?.shadowRoot) {
      clearOccurrences();
      return;
    }
    adoptInto(document);
    adoptInto(container.shadowRoot);
    const ranges: { range: Range; role: Occurrence['role'] }[] = [];
    for (const o of active.occ) {
      const line = lineEl(container, active.side, o.startRow);
      if (!line) continue;
      const r = rangeWithinLine(line, o.startColumn, o.endColumn);
      if (r) ranges.push({ range: r, role: o.role });
    }
    paint(ranges);
  }, []);

  // Publish the active selection's occurrences (or null) to the consumer, so
  // they can paint them on the overview ruler. Lines are 1-based on the side.
  const publishActive = useCallback((active: ActiveSelection | null, activeIndex: number) => {
    optsRef.current.onActiveOccurrences?.(
      active
        ? {
            filename: active.path,
            side: active.side,
            lines: active.occ.map((o) => o.startRow + 1),
            activeIndex,
          }
        : null,
    );
  }, []);

  const clear = useCallback(() => {
    activeRef.current = null;
    cycleRef.current = 0;
    // Invalidate any in-flight resolve so it can't paint over a cleared state.
    clickSeqRef.current++;
    flashRef.current = null;
    clearOccurrences();
    paintFlash(null);
    setChip(null);
    publishActive(null, 0);
  }, [publishActive]);

  const repaintFlash = useCallback(() => {
    const f = flashRef.current;
    if (!f) return;
    const c = containerForPath(f.path);
    if (!c?.shadowRoot) return;
    adoptInto(c.shadowRoot);
    const r = lineFlashRange(c, f.side, f.row0);
    if (r) paintFlash(r);
  }, []);

  // Scroll a (possibly virtualized / off-screen) line into view via the diff's
  // own handle, then flash it as a Custom Highlight — repainted across the
  // scroll-settle window so the smooth-scroll re-renders can't wipe it, then
  // cleared. (Lines inside collapsed unchanged hunks can't be reached this way.)
  const reveal = useCallback(
    (path: string, side: DiffSide, row0: number) => {
      // This scroll is ours — keep the scroll handler from closing the chip.
      suppressScrollCloseUntil.current = performance.now() + 1000;
      flashRef.current = { path, side, row0 };
      // If the target sits in a collapsed unchanged run, expand it first so the
      // line renders; the expansion triggers a re-render, then we scroll to it.
      const entry = instancesRef.current.get(path);
      const expanded = entry
        ? expandHunkForLine(entry.instance, entry.hunks, side === 'additions', row0 + 1)
        : false;
      const doScroll = () => optsRef.current.scrollToLine?.(path, side, row0 + 1);
      if (expanded) window.setTimeout(doScroll, 80);
      else doScroll();
      let elapsed = 0;
      const tick = () => {
        repaintFlash();
        elapsed += 100;
        if (elapsed < 1000) {
          window.setTimeout(tick, 100);
        } else {
          flashRef.current = null;
          paintFlash(null);
        }
      };
      window.setTimeout(tick, expanded ? 160 : 80);
    },
    [repaintFlash],
  );

  // Position the chip on a specific occurrence (hidden if that token isn't in
  // the diff viewport — e.g. a cycle target that scrolled away).
  const anchorChip = useCallback((active: ActiveSelection, occ: Occurrence) => {
    const container = containerForPath(active.path);
    const rect = container
      ? occurrenceRect(container, active.side, occ.startRow, occ.startColumn, occ.endColumn)
      : null;
    const vp = container ? diffScroller(container)?.getBoundingClientRect() : null;
    const visible = !!rect && (!vp || (rect.bottom > vp.top && rect.top < vp.bottom));
    if (!rect || !visible) {
      setChip(null);
      return;
    }
    setChip({
      id: `${active.path}:${active.side}:${active.symbol}`,
      anchor: { left: rect.left, top: rect.top, bottom: rect.bottom },
      count: active.occ.length,
      hasDef: active.hasDef,
    });
  }, []);

  // Jump to a specific occurrence: reveal it, re-anchor the chip once the
  // scroll/expand settles (a couple of fixed points cover varying scroll
  // durations; not per-frame, so no virtualization thrash), and re-publish the
  // active index so the ruler's focused dot follows.
  const goToOccurrence = useCallback(
    (index: number) => {
      const active = activeRef.current;
      if (!active || index < 0 || index >= active.occ.length) return;
      cycleRef.current = index;
      const o = active.occ[index];
      reveal(active.path, active.side, o.startRow);
      [300, 600].forEach((t) => {
        window.setTimeout(() => {
          if (activeRef.current === active) anchorChip(active, o);
        }, t);
      });
      publishActive(active, index);
    },
    [anchorChip, reveal, publishActive],
  );

  const cycle = useCallback(
    (dir: 1 | -1) => {
      const active = activeRef.current;
      if (!active || active.occ.length < 2) return;
      const n = active.occ.length;
      goToOccurrence((cycleRef.current + dir + n) % n);
    },
    [goToOccurrence],
  );

  const gotoDef = useCallback(() => {
    const active = activeRef.current;
    if (!active?.hasDef) return;
    const defIndex = active.occ.findIndex((o) => o.role === 'definition');
    if (defIndex >= 0) goToOccurrence(defIndex);
  }, [goToOccurrence]);

  const openOutline = useCallback(async () => {
    let path = currentFileRef.current;
    if (!path) {
      const c = diffContainers().find((c) => titleOf(c));
      path = c ? titleOf(c) : null;
    }
    if (!path) return;
    const lang = langForPath(path);
    if (!lang) return;
    const text = optsRef.current.getFileText(path, 'additions');
    if (text == null) return;
    const symbols = await symbolNav.outline({ lang, path, version: hashText(text), text });
    setOutline({ path, symbols });
  }, []);

  const onSelectSymbol = useCallback(
    (s: OutlineSymbol, path: string) => {
      reveal(path, 'additions', s.row);
      setOutline(null);
    },
    [reveal],
  );

  const onItemPostRender = useCallback(
    (node: HTMLElement, instance?: unknown) => {
      // Capture the per-file lib instance so reveal() can auto-expand hunks.
      const fi = instance as
        | (HunkExpandable & { fileDiff?: { name?: string; hunks?: readonly Hunk[] } })
        | undefined;
      const fdPath = fi?.fileDiff?.name;
      const fdHunks = fi?.fileDiff?.hunks;
      if (fi && fdPath && fdHunks) instancesRef.current.set(fdPath, { instance: fi, hunks: fdHunks });

      const hosts =
        node.tagName === 'DIFFS-CONTAINER'
          ? [node]
          : Array.from(node.querySelectorAll<HTMLElement>('diffs-container'));
      for (const dc of hosts) if (dc.shadowRoot) adoptInto(dc.shadowRoot);
      // Only repaint when the file that actually re-rendered is the one we're
      // painting — avoids redundant per-item work while scrolling other files.
      const titles = hosts.map((dc) => titleOf(dc));
      if (activeRef.current && titles.includes(activeRef.current.path)) repaint();
      if (flashRef.current && titles.includes(flashRef.current.path)) repaintFlash();
    },
    [repaint, repaintFlash],
  );

  // click: highlight / toggle / go-to-def
  useEffect(() => {
    if (!opts.enabled) return;
    const inOwnUi = (e: MouseEvent) =>
      (e.target as HTMLElement | null)?.closest?.(
        '[data-symbol-nav-ui],[data-overview-ruler]',
      ) != null;
    const onClick = (e: MouseEvent) => {
      if (e.button !== 0 || e.shiftKey || e.altKey) return;
      if (inOwnUi(e)) return; // clicks on the chip/overlay drive their own handlers
      const goto = e.metaKey || e.ctrlKey;
      const hit = hitTest(e);
      if (!hit) {
        if (!goto && activeRef.current) clear();
        return;
      }
      const lang = langForPath(hit.path);
      if (!lang) return;
      currentFileRef.current = hit.path;
      const text = optsRef.current.getFileText(hit.path, hit.side);
      if (text == null) return;
      const mySeq = ++clickSeqRef.current;
      void (async () => {
        let res;
        try {
          res = await symbolNav.resolve({
            lang,
            path: hit.path,
            version: hashText(text),
            text,
            row: hit.row,
            column: hit.column,
          });
        } catch {
          // worker/parse error — drop this click silently (the worker respawns
          // itself), but only clear if no newer click has superseded this one.
          if (mySeq === clickSeqRef.current && activeRef.current) clear();
          return;
        }
        // A newer click (or a clear) landed while we were parsing — discard.
        if (mySeq !== clickSeqRef.current) return;
        if (!res || res.occurrences.length === 0) {
          clear();
          return;
        }
        const prev = activeRef.current;
        if (
          !goto &&
          prev &&
          prev.path === hit.path &&
          prev.side === hit.side &&
          prev.symbol === res.symbol
        ) {
          clear();
          return;
        }
        const active: ActiveSelection = {
          path: hit.path,
          side: hit.side,
          symbol: res.symbol,
          occ: res.occurrences,
          hasDef: !!res.definition,
        };
        activeRef.current = active;
        repaint();
        const clicked =
          active.occ.find(
            (o) => o.startRow === hit.row && hit.column >= o.startColumn && hit.column <= o.endColumn,
          ) ?? active.occ[0];
        cycleRef.current = active.occ.indexOf(clicked);
        anchorChip(active, clicked);
        // gotoDef() re-publishes the def index, so only publish here when we're
        // not about to jump to the definition (avoids a double publish).
        if (goto) gotoDef();
        else publishActive(active, cycleRef.current);
      })();
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (activeRef.current) clear();
        return;
      }
      if ((e.key === 'o' || e.key === 'O') && !e.metaKey && !e.ctrlKey && !e.altKey) {
        const t = e.target as HTMLElement | null;
        if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
        e.preventDefault();
        void openOutline();
      }
    };
    document.addEventListener('click', onClick, true);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('click', onClick, true);
      document.removeEventListener('keydown', onKey);
      clear();
    };
  }, [opts.enabled, clear, repaint, anchorChip, gotoDef, openOutline]);

  // Underline only a referenceable identifier under the cursor (from the parse
  // tree), not any word — so keywords/strings/punctuation don't get the hint.
  const showHoverHint = useCallback(
    (hit: { path: string; side: DiffSide; row: number; column: number }) => {
      const entry = idCacheRef.current.get(`${hit.path}:${hit.side}`);
      const ranges = entry?.byRow.get(hit.row);
      const m = ranges?.find(([s, e]) => hit.column >= s && hit.column < e);
      const container = containerForPath(hit.path);
      const line = container && lineEl(container, hit.side, hit.row);
      if (!m || !line) {
        paintHover(null);
        return;
      }
      if (container?.shadowRoot) adoptInto(container.shadowRoot);
      const hoverRange = rangeWithinLine(line, m[0], m[1]);
      paintHover(hoverRange);
      if (hoverRange && !coachSeenRef.current) {
        coachSeenRef.current = true;
        try {
          localStorage.setItem(COACH_KEY, '1');
        } catch {
          /* private mode — fine */
        }
        const rect = hoverRange.getBoundingClientRect();
        setCoach({ left: rect.left, top: rect.top, bottom: rect.bottom });
      }
    },
    [],
  );

  // Lazily fetch a file's clickable identifier ranges (cached per path:side).
  // Returns true when the cache is ready & fresh.
  const ensureIdentifiers = useCallback(
    (path: string, side: DiffSide): boolean => {
      const lang = langForPath(path);
      const text = optsRef.current.getFileText(path, side);
      if (!lang || text == null) return false;
      const version = hashText(text);
      const key = `${path}:${side}`;
      const entry = idCacheRef.current.get(key);
      if (entry && entry.version === version) return true;
      if (idInflightRef.current.has(key)) return false;
      idInflightRef.current.add(key);
      void symbolNav
        .identifiers({ lang, path, version, text })
        .then((ranges) => {
          idInflightRef.current.delete(key);
          const byRow = new Map<number, Array<[number, number]>>();
          for (const [r, s, e] of ranges) {
            const arr = byRow.get(r);
            if (arr) arr.push([s, e]);
            else byRow.set(r, [[s, e]]);
          }
          idCacheRef.current.set(key, { version, byRow });
          // paint the hint for the cursor's current position without a re-move
          const lh = lastHoverRef.current;
          if (lh && lh.path === path && lh.side === side) showHoverHint(lh);
        })
        .catch(() => idInflightRef.current.delete(key));
      return false;
    },
    [showHoverHint],
  );

  // hover affordance — faint underline on the referenceable identifier under the cursor
  useEffect(() => {
    if (!opts.enabled) return;
    let raf = 0;
    const onMove = (e: MouseEvent) => {
      // composedPath() is only valid during dispatch — snapshot it now.
      const path = e.composedPath();
      const frozen = { composedPath: () => path, clientX: e.clientX, clientY: e.clientY };
      if (raf) return;
      raf = requestAnimationFrame(() => {
        raf = 0;
        const hit = hitTest(frozen);
        if (!hit || !langForPath(hit.path)) {
          lastHoverRef.current = null;
          paintHover(null);
          return;
        }
        currentFileRef.current = hit.path;
        lastHoverRef.current = hit;
        if (ensureIdentifiers(hit.path, hit.side)) showHoverHint(hit);
        else paintHover(null); // paints on cache arrival via the re-eval above
      });
    };
    const onLeave = () => {
      lastHoverRef.current = null;
      paintHover(null);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseleave', onLeave);
    return () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseleave', onLeave);
      if (raf) cancelAnimationFrame(raf);
      paintHover(null);
    };
  }, [opts.enabled, ensureIdentifiers, showHoverHint]);

  // (Files virtualizing in/out are handled by onItemPostRender, which the lib
  // fires per file render — no global MutationObserver needed. A document-wide
  // observer starves @pierre/diffs' own virtualization on large PRs.)

  // pre-warm the worker (runtime + TS grammar) so the first real click is snappy
  useEffect(() => {
    if (!opts.enabled) return;
    void symbolNav
      .resolve({ lang: 'typescript', path: '__warm__', version: 'w', text: 'const _w=0;_w;', row: 0, column: 6 })
      .catch(() => {});
  }, [opts.enabled]);

  // Close the chip on scroll. (Repositioning it per scroll frame via React state
  // re-rendered the CodeView mid-scroll and broke @pierre/diffs virtualization —
  // rows mis-collapsed into per-line "N unmodified lines". The highlights stay;
  // only the popup closes.) Capture-phase to catch the inner diff scroller.
  useEffect(() => {
    if (!opts.enabled) return;
    const onScroll = () => {
      if (performance.now() < suppressScrollCloseUntil.current) return; // our own reveal scroll
      setChip(null); // overlay bails if already closed — no diff re-render
    };
    document.addEventListener('scroll', onScroll, true);
    return () => document.removeEventListener('scroll', onScroll, true);
  }, [opts.enabled]);

  return { onItemPostRender, cycle, gotoDef, clear, revealOccurrence: goToOccurrence, onSelectSymbol };
}
