// Server-backed in-progress review (ADR 0019).
//
// Drop-in replacement for useDraftReview: returns the same
// { draft, actions } shape so the composer / dock / submit modal keep
// working through the DraftActions seam — but every mutation now hits
// GitHub's pending review instead of localStorage.
//
//   - The viewer's PENDING review IS the source of truth. Its comments
//     come from prPendingReviewOptions (fetched in #91) and are
//     classified back into the DraftReview buckets the UI expects.
//   - Verdict + overall body have no server home until submit, so they
//     stay local React state.
//   - Writes are OPTIMISTIC: the comment renders inline immediately
//     (badged "Pending · saving…"), reconciles to its real id on
//     success, and rolls back with a Retry toast on error.
//   - The create-vs-append fork (the source of GitHub's 422s) is
//     serialised via a mutation scope so two quick comments never both
//     try to create the one-per-PR pending review.

import { useCallback, useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  GitHubError,
  addPendingFileComment,
  addPendingLineComment,
  addPendingReply,
  createPendingReview,
  createPendingReviewWithComment,
  createSingleReviewComment,
  deletePendingComment,
  discardPendingReview,
  replyToReviewComment,
  submitPendingReview,
  submitReview,
  updatePendingComment,
  type PendingReview,
} from '../github/client';
import { prPendingReviewOptions } from '../github/prQueries';
import type { GHReviewComment } from '../github/types';
import type {
  DraftActions,
  DraftFileComment,
  DraftLineComment,
  DraftReply,
  DraftReview,
  Verdict,
} from '../review/reviewDraftTypes';
import { track, Events, repoProps, useOrgIdForOwner } from '../observability';

const STABLE_PER_OPEN_MS = 15_000;

/** Negative, monotonically-decreasing temp ids for optimistic comments —
 * never collide with GitHub's positive ids, and sort last. */
let tempSeq = 0;
const nextTempId = (): number => -(++tempSeq);

interface Viewer {
  login: string;
  avatar_url: string;
}

export interface PendingReviewApi {
  /** The viewer's server pending review (null when none) — fed into the
   * thread index so its comments render inline. */
  pendingReview: PendingReview | null;
  /** DraftReview-shaped view (server comments + local verdict/body) so
   * the dock + submit modal render unchanged. */
  draft: DraftReview;
  /** DraftActions-compatible mutators, server-backed + optimistic. */
  actions: DraftActions;
  /** Submit the pending review with the current verdict + overall body
   * (events endpoint); a pure verdict with no pending comments posts the
   * event directly. Returns the published review's html_url. */
  submit: () => Promise<string>;
  /** Discard the whole pending review on GitHub (DELETE). */
  discard: () => Promise<void>;
  /** True while the viewer has a server pending review with ≥1 comment. */
  hasServerReview: boolean;
}

type AddVars =
  | {
      kind: 'line';
      tempId: number;
      path: string;
      line: number;
      startLine?: number;
      side: 'LEFT' | 'RIGHT';
      body: string;
    }
  | { kind: 'file'; tempId: number; path: string; body: string }
  | {
      kind: 'reply';
      tempId: number;
      inReplyTo: number;
      body: string;
    };

/** Edit/delete shape consumed by ReviewThread's `pendingActions`. */
export interface PendingCommentActions {
  edit: (commentId: number, body: string) => void;
  remove: (commentId: number) => void;
}

/**
 * Edit + delete for the viewer's PENDING review comments, carved out of
 * usePendingReview so any surface can author them WITHOUT subscribing to
 * the pending-review query. It reaches the shared cache through
 * useQueryClient only (no useQuery), so it's cheap to call per-thread in
 * the Conversation timeline — unlike usePendingReview, whose query
 * observer would re-render every thread on any draft change. Returns the
 * `{ edit, remove }` shape ReviewThread expects; usePendingReview reuses
 * it for its DraftActions surface so the GraphQL write lives in one place.
 */
export function usePendingCommentActions(
  owner: string,
  repo: string,
  number: number,
): PendingCommentActions {
  const qc = useQueryClient();
  const key = prPendingReviewOptions(owner, repo, number).queryKey;
  const setPending = (
    updater: (prev: PendingReview | null) => PendingReview | null,
  ): void => {
    qc.setQueryData<PendingReview | null>(key, (prev) => updater(prev ?? null));
  };

  // ── edit a pending comment (GraphQL) ──────────────────────────
  const editMut = useMutation({
    scope: { id: `pending-write:${owner}/${repo}/${number}` },
    onMutate: ({ id, body }: { id: number; body: string }) => {
      const previous = qc.getQueryData<PendingReview | null>(key) ?? null;
      // Bump `updated_at` alongside `body`: the Changes-pane diff renders
      // each thread as a @pierre/diffs annotation whose re-render is gated
      // by `hashAnnotations`, and that hash keys on `updated_at` (not the
      // body) to detect edits. Changing only `body` leaves the hash equal,
      // so CodeView short-circuits and the stale card keeps the old text.
      const editedAt = new Date().toISOString();
      setPending((prev) =>
        prev
          ? {
              ...prev,
              comments: prev.comments.map((c) =>
                c.id === id
                  ? { ...c, body, updated_at: editedAt, optimistic: true }
                  : c,
              ),
            }
          : prev,
      );
      return { previous };
    },
    mutationFn: async ({ id, body }: { id: number; body: string }) => {
      const nodeId = findPendingNodeId(qc, key, id);
      if (!nodeId) throw new GitHubError('Comment not found', 404, '/graphql');
      await updatePendingComment(nodeId, body);
    },
    onError: (err, _v, ctx) => {
      qc.setQueryData<PendingReview | null>(key, ctx?.previous ?? null);
      toast.error('Could not update comment', {
        description: errDescription(err),
      });
    },
    // Don't invalidate on edit success: the comment already has a real
    // id + node_id and the new body is the optimistic value we wrote in
    // onMutate, so there's nothing to learn from the server. A refetch
    // here re-reads the eventually-consistent pending-review side map,
    // which can return the PRE-edit body and visibly revert the comment
    // (the reply-flash failure mode). Instead settle the optimistic flag
    // in place — keeps the edited body and re-enables further edits.
    onSuccess: (_data, { id, body }) => {
      const editedAt = new Date().toISOString();
      setPending((prev) =>
        prev
          ? {
              ...prev,
              comments: prev.comments.map((c) =>
                c.id === id
                  ? { ...c, body, updated_at: editedAt, optimistic: false }
                  : c,
              ),
            }
          : prev,
      );
    },
  });

  // ── delete a pending comment; empty review ⇒ discard it ───────
  // node_id is resolved when `remove` is called (before onMutate filters
  // the comment out of the cache, which would lose it).
  const removeMut = useMutation({
    scope: { id: `pending-write:${owner}/${repo}/${number}` },
    onMutate: ({ id }: { id: number; nodeId?: string }) => {
      const previous = qc.getQueryData<PendingReview | null>(key) ?? null;
      setPending((prev) =>
        prev
          ? { ...prev, comments: prev.comments.filter((c) => c.id !== id) }
          : prev,
      );
      return { previous };
    },
    mutationFn: async ({ nodeId }: { id: number; nodeId?: string }) => {
      if (!nodeId) throw new GitHubError('Comment not found', 404, '/graphql');
      await deletePendingComment(nodeId);
      // Last pending comment removed → delete the now-empty review so the
      // dock + inline pending state clear (ADR 0019 §empty-review cleanup).
      // onMutate already dropped the comment, so the cache length IS the
      // remaining count.
      const current = qc.getQueryData<PendingReview | null>(key);
      if ((current?.comments.length ?? 0) <= 0 && current && current.id) {
        await discardPendingReview(owner, repo, number, current.id);
      }
    },
    onError: (err, _v, ctx) => {
      qc.setQueryData<PendingReview | null>(key, ctx?.previous ?? null);
      toast.error('Could not delete comment', {
        description: errDescription(err),
      });
    },
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: key });
    },
  });

  return useMemo(
    () => ({
      edit: (id: number, body: string) => editMut.mutate({ id, body }),
      remove: (id: number) =>
        removeMut.mutate({ id, nodeId: findPendingNodeId(qc, key, id) }),
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editMut.mutate, removeMut.mutate, qc],
  );
}

export function usePendingReview(
  owner: string,
  repo: string,
  number: number,
  headSha: string | undefined,
  viewer?: Viewer,
): PendingReviewApi {
  const qc = useQueryClient();
  const orgId = useOrgIdForOwner(owner);
  const key = prPendingReviewOptions(owner, repo, number).queryKey;
  const commentsKey = ['pr', owner, repo, number, 'comments'] as const;
  const reviewsKey = ['pr', owner, repo, number, 'reviews'] as const;
  const timelineKey = ['pr', owner, repo, number, 'timeline'] as const;

  // The viewer's own pending review. We DON'T blind-poll it: a pending
  // comment is private, so it never bumps the PR's updated_at (the
  // metadata heartbeat can't see it), and the side-map fetch costs ~100
  // GraphQL points whenever a review is open — too much to run every 15s.
  // Instead it refetches on window focus (catches a draft edited on
  // another device when you switch back) and on the heartbeat's
  // invalidation when the PR sees public activity; same-device edits
  // reconcile synchronously through this hook's mutations.
  const pendingQuery = useQuery({
    ...prPendingReviewOptions(owner, repo, number),
    staleTime: STABLE_PER_OPEN_MS,
    refetchOnWindowFocus: 'always',
    placeholderData: (prev) => prev,
  });
  const pendingReview = pendingQuery.data ?? null;

  // Verdict + overall body live only in the UI until submit.
  const [verdict, setVerdictState] = useState<Verdict>('comment');
  const [overallBody, setOverallBody] = useState('');

  const reconcile = useCallback(() => {
    void qc.invalidateQueries({ queryKey: key });
  }, [qc, key]);

  // ── optimistic-cache helpers ──────────────────────────────────
  const setPending = useCallback(
    (updater: (prev: PendingReview | null) => PendingReview | null) => {
      qc.setQueryData<PendingReview | null>(key, (prev) =>
        updater(prev ?? null),
      );
    },
    [qc, key],
  );

  const makeOptimistic = useCallback(
    (v: AddVars): GHReviewComment => {
      const base: GHReviewComment = {
        id: v.tempId,
        node_id: undefined,
        pull_request_review_id: pendingReview?.id ?? 0,
        user: {
          login: viewer?.login ?? '',
          avatar_url: viewer?.avatar_url ?? '',
        },
        body: v.body,
        path: v.kind === 'reply' ? replyHeadPath(qc, commentsKey, v.inReplyTo) : v.path,
        line: null,
        original_line: null,
        side: 'RIGHT',
        position: null,
        original_position: null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        html_url: '',
        commit_id: headSha ?? '',
        original_commit_id: headSha ?? '',
        status: 'pending',
        optimistic: true,
      };
      if (v.kind === 'line') {
        base.line = v.line;
        base.original_line = v.line;
        base.start_line = v.startLine ?? v.line;
        base.original_start_line = v.startLine ?? v.line;
        base.side = v.side;
        base.subject_type = 'line';
      } else if (v.kind === 'file') {
        base.subject_type = 'file';
      } else {
        // reply — inherit the published head's anchor for rendering
        const head = findComment(qc, commentsKey, v.inReplyTo);
        base.in_reply_to_id = v.inReplyTo;
        base.line = head?.line ?? null;
        base.original_line = head?.original_line ?? null;
        base.side = head?.side ?? 'RIGHT';
      }
      return base;
    },
    [qc, commentsKey, pendingReview?.id, viewer, headSha],
  );

  // ── add (create-or-append), serialised so we never double-create ──
  const addMut = useMutation({
    scope: { id: `pending-write:${owner}/${repo}/${number}` },
    onMutate: (v: AddVars) => {
      const previous = qc.getQueryData<PendingReview | null>(key) ?? null;
      const optimistic = makeOptimistic(v);
      setPending((prev) =>
        prev
          ? { ...prev, comments: [...prev.comments, optimistic] }
          : { id: 0, nodeId: '', comments: [optimistic] },
      );
      return { previous };
    },
    mutationFn: async (v: AddVars) => {
      const current = qc.getQueryData<PendingReview | null>(key);
      const hasReal = !!current && current.nodeId !== '';
      if (!hasReal) {
        // First comment of the review → create it (REST, no event). Only
        // a LINE comment can seed the create-with-comment call; file-level
        // and reply comments aren't accepted in that payload, so for those
        // we create an empty pending review and append via GraphQL.
        if (v.kind === 'line') {
          const review = await createPendingReviewWithComment(
            owner,
            repo,
            number,
            headSha ?? '',
            {
              path: v.path,
              body: v.body,
              line: v.line,
              side: v.side,
              ...(v.startLine && v.startLine !== v.line
                ? { start_line: v.startLine, start_side: v.side }
                : {}),
            },
          );
          writeRealReviewId(qc, key, review);
          return;
        }
        const review = await createEmptyPendingReview(owner, repo, number, headSha);
        writeRealReviewId(qc, key, review);
        if (v.kind === 'file') {
          await addPendingFileComment(review.nodeId, {
            path: v.path,
            body: v.body,
          });
        } else {
          await appendReply(qc, commentsKey, key, review.nodeId, v);
        }
        return;
      }
      // Append to the existing pending review (GraphQL).
      const reviewNodeId = current!.nodeId;
      if (v.kind === 'line') {
        await addPendingLineComment(reviewNodeId, {
          path: v.path,
          body: v.body,
          line: v.line,
          side: v.side,
          startLine: v.startLine,
        });
      } else if (v.kind === 'file') {
        await addPendingFileComment(reviewNodeId, {
          path: v.path,
          body: v.body,
        });
      } else {
        await appendReply(qc, commentsKey, key, reviewNodeId, v);
      }
    },
    onError: (err, v, ctx) => {
      qc.setQueryData<PendingReview | null>(key, ctx?.previous ?? null);
      toast.error('Could not save comment', {
        description: errDescription(err),
        action: { label: 'Retry', onClick: () => addMut.mutate(v) },
      });
    },
    onSuccess: reconcile,
  });

  // Edit + delete live in the shared lean hook (no extra query observer),
  // reused here so the GraphQL write path is identical to the one the
  // Conversation timeline calls directly.
  const commentActions = usePendingCommentActions(owner, repo, number);

  // ── derived DraftReview view ──────────────────────────────────
  const draft = useMemo<DraftReview>(() => {
    const comments = pendingReview?.comments ?? [];
    const lineComments: DraftLineComment[] = [];
    const fileComments: DraftFileComment[] = [];
    const replies: DraftReply[] = [];
    comments.forEach((c) => {
      if (c.in_reply_to_id != null) {
        replies.push({
          id: String(c.id),
          inReplyTo: c.in_reply_to_id,
          body: c.body,
          createdAt: c.created_at,
        });
      } else if (c.subject_type === 'file') {
        fileComments.push({
          id: String(c.id),
          path: c.path,
          body: c.body,
          createdAt: c.created_at,
        });
      } else {
        lineComments.push({
          id: String(c.id),
          path: c.path,
          line: c.line ?? c.original_line ?? 0,
          startLine:
            c.start_line && c.start_line !== c.line ? c.start_line : undefined,
          side: c.side,
          body: c.body,
          createdAt: c.created_at,
        });
      }
    });
    return {
      verdict,
      overallBody,
      lineComments,
      fileComments,
      replies,
      updatedAt: new Date().toISOString(),
    };
  }, [pendingReview, verdict, overallBody]);

  // ── DraftActions surface ──────────────────────────────────────
  const actions = useMemo<DraftActions>(() => {
    const idNum = (id: string): number => Number(id);
    const remove = (id: string) => commentActions.remove(idNum(id));
    return {
      setVerdict: setVerdictState,
      setOverallBody,
      addLineComment: (c) => {
        const tempId = nextTempId();
        addMut.mutate({
          kind: 'line',
          tempId,
          path: c.path,
          line: c.line,
          startLine: c.startLine,
          side: c.side,
          body: c.body,
        });
        return String(tempId);
      },
      updateLineComment: (id, body) => commentActions.edit(idNum(id), body),
      removeLineComment: remove,
      addFileComment: (c) => {
        const tempId = nextTempId();
        addMut.mutate({ kind: 'file', tempId, path: c.path, body: c.body });
        return String(tempId);
      },
      updateFileComment: (id, body) => commentActions.edit(idNum(id), body),
      removeFileComment: remove,
      addReply: (r) => {
        const tempId = nextTempId();
        addMut.mutate({
          kind: 'reply',
          tempId,
          inReplyTo: r.inReplyTo,
          body: r.body,
        });
        return String(tempId);
      },
      updateReply: (id, body) => commentActions.edit(idNum(id), body),
      removeReply: remove,
      reset: () => {
        setVerdictState('comment');
        setOverallBody('');
      },
    };
  }, [addMut, commentActions]);

  const submit = useCallback(async (): Promise<string> => {
    const event: 'APPROVE' | 'REQUEST_CHANGES' | 'COMMENT' =
      verdict === 'approve'
        ? 'APPROVE'
        : verdict === 'changes'
          ? 'REQUEST_CHANGES'
          : 'COMMENT';
    const current = qc.getQueryData<PendingReview | null>(key);
    let result: { html_url: string };
    if (current && current.id) {
      result = await submitPendingReview(
        owner,
        repo,
        number,
        current.id,
        event,
        overallBody,
      );
    } else {
      // Pure verdict, no pending comments → post the event directly.
      result = await submitReview(owner, repo, number, {
        commit_id: headSha,
        body: overallBody.trim() || undefined,
        event,
      });
    }
    track(
      Events.ReviewSubmitted,
      {
        verdict: event,
        comment_count: current?.comments?.length ?? 0,
        ...repoProps({ owner, repo, prNumber: number }),
      },
      { orgId },
    );
    setVerdictState('comment');
    setOverallBody('');
    // Submitting publishes the verdict + any pending comments. Refresh every
    // surface that renders them: the pending draft (`key`) clears, and the
    // verdict/comments/timeline-event now appear in the Conversation timeline
    // and PRHeader. Without `reviews`/`timeline` the verdict would lag until
    // the ~15s metadata heartbeat noticed the PR's updated_at bump.
    await Promise.all(
      (
        [key, commentsKey, reviewsKey, timelineKey] as const
      ).map((k) => qc.invalidateQueries({ queryKey: k })),
    );
    return result.html_url;
  }, [
    qc,
    key,
    commentsKey,
    reviewsKey,
    timelineKey,
    owner,
    repo,
    number,
    headSha,
    verdict,
    overallBody,
    orgId,
  ]);

  const discard = useCallback(async (): Promise<void> => {
    const current = qc.getQueryData<PendingReview | null>(key);
    if (current && current.id) {
      await discardPendingReview(owner, repo, number, current.id);
    }
    setVerdictState('comment');
    setOverallBody('');
    qc.setQueryData<PendingReview | null>(key, null);
    await qc.invalidateQueries({ queryKey: key });
  }, [qc, key, owner, repo, number]);

  return {
    pendingReview,
    draft,
    actions,
    submit,
    discard,
    hasServerReview: !!pendingReview && pendingReview.comments.length > 0,
  };
}

/** Variables for the immediate-publish "Add single comment" path. */
type SingleCommentVars =
  | {
      kind: 'line';
      path: string;
      line: number;
      startLine?: number;
      side: 'LEFT' | 'RIGHT';
      body: string;
    }
  | { kind: 'file'; path: string; body: string }
  | { kind: 'reply'; inReplyTo: number; path: string; body: string };

/**
 * github.com's "Add single comment" — publish a standalone review
 * comment immediately, belonging to no pending review. Optimistic: the
 * comment renders inline as a normal published thread right away,
 * reconciles to its real id on success, and rolls back with a Retry
 * toast on error (ADR 0019). Operates on the published-comments cache,
 * independent of the pending review.
 */
export function useSingleComment(owner: string, repo: string, number: number) {
  const qc = useQueryClient();
  const orgId = useOrgIdForOwner(owner);
  const commentsKey = ['pr', owner, repo, number, 'comments'] as const;
  const metaKey = ['pr', owner, repo, number, 'meta'] as const;
  const pendingKey = prPendingReviewOptions(owner, repo, number).queryKey;

  const mut = useMutation({
    onMutate: (v: SingleCommentVars) => {
      const viewer = qc.getQueryData<Viewer>(['viewer']);
      // A reply can't be REST-single-published while the viewer already has
      // an open pending review — GitHub 422s ("one pending review per PR").
      // Divert it into that review via the same GraphQL append the Changes
      // pane uses, with the optimistic row in the PENDING cache (the
      // timeline merges pending comments into its threads).
      const pending = qc.getQueryData<PendingReview | null>(pendingKey);
      if (v.kind === 'reply' && pending?.nodeId) {
        const head = findComment(qc, commentsKey, v.inReplyTo);
        const optimistic = makePendingReplyOptimistic(v, pending, viewer, head);
        qc.setQueryData<PendingReview | null>(pendingKey, (prev) =>
          prev ? { ...prev, comments: [...prev.comments, optimistic] } : prev,
        );
        return { mode: 'pending' as const, previousPending: pending, tempId: optimistic.id };
      }
      const previous = qc.getQueryData<GHReviewComment[]>(commentsKey) ?? [];
      const head =
        v.kind === 'reply' ? findComment(qc, commentsKey, v.inReplyTo) : undefined;
      const optimistic: GHReviewComment = {
        id: nextTempId(),
        pull_request_review_id: null,
        user: {
          login: viewer?.login ?? '',
          avatar_url: viewer?.avatar_url ?? '',
        },
        body: v.body,
        path: v.path,
        line: v.kind === 'line' ? v.line : (head?.line ?? null),
        original_line: v.kind === 'line' ? v.line : (head?.original_line ?? null),
        start_line:
          v.kind === 'line' && v.startLine && v.startLine !== v.line
            ? v.startLine
            : undefined,
        side: v.kind === 'line' ? v.side : (head?.side ?? 'RIGHT'),
        in_reply_to_id: v.kind === 'reply' ? v.inReplyTo : undefined,
        position: null,
        original_position: null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        html_url: '',
        commit_id: '',
        original_commit_id: '',
        subject_type: v.kind === 'file' ? 'file' : 'line',
        optimistic: true,
      };
      qc.setQueryData<GHReviewComment[]>(commentsKey, [...previous, optimistic]);
      return { mode: 'published' as const, previous, tempId: optimistic.id };
    },
    mutationFn: async (
      v: SingleCommentVars,
    ): Promise<Partial<GHReviewComment> & { id: number }> => {
      const meta = qc.getQueryData<{ head: { sha: string } }>(metaKey);
      const headSha = meta?.head.sha ?? '';
      const pending = qc.getQueryData<PendingReview | null>(pendingKey);
      if (v.kind === 'reply' && pending?.nodeId) {
        // Append to the open pending review (GraphQL) — mirrors addMut.
        await appendReply(qc, commentsKey, pendingKey, pending.nodeId, {
          kind: 'reply',
          tempId: 0,
          inReplyTo: v.inReplyTo,
          body: v.body,
        });
        return { id: 0 };
      }
      if (v.kind === 'reply') {
        const reply = await replyToReviewComment(
          owner,
          repo,
          number,
          v.inReplyTo,
          v.body,
        );
        return {
          id: reply.id,
          body: reply.body,
          user: reply.user,
          created_at: reply.created_at,
          updated_at: reply.created_at,
        };
      }
      if (v.kind === 'file') {
        return createSingleReviewComment(owner, repo, number, headSha, {
          path: v.path,
          body: v.body,
          subjectType: 'file',
        });
      }
      return createSingleReviewComment(owner, repo, number, headSha, {
        path: v.path,
        body: v.body,
        line: v.line,
        side: v.side,
        startLine: v.startLine,
      });
    },
    onError: (err, v, ctx) => {
      if (ctx?.mode === 'pending') {
        qc.setQueryData<PendingReview | null>(pendingKey, ctx.previousPending);
      } else {
        qc.setQueryData<GHReviewComment[]>(commentsKey, ctx?.previous ?? []);
      }
      toast.error('Could not add comment', {
        description: errDescription(err),
        action: { label: 'Retry', onClick: () => mut.mutate(v) },
      });
    },
    onSuccess: (real, v, ctx) => {
      track(
        v.kind === 'reply' ? Events.ThreadReplied : Events.CommentPosted,
        { comment_type: v.kind, ...repoProps({ owner, repo, prNumber: number }) },
        { orgId },
      );
      // Reply diverted into the pending review → reconcile the pending cache
      // (refetch its real ids), exactly like addMut.
      if (ctx?.mode === 'pending') {
        void qc.invalidateQueries({ queryKey: pendingKey });
        return;
      }
      // Reconcile the optimistic temp row to the server's real id in place.
      // Invalidating instead would refetch GitHub's review-comments list,
      // which is eventually-consistent and routinely omits a just-posted
      // reply — so the optimistic row would vanish and then reappear once
      // GitHub caught up (the visible flash). Background window-focus / poll
      // refetch canonicalises reactions etc. once the list is consistent.
      qc.setQueryData<GHReviewComment[]>(commentsKey, (cur) =>
        (cur ?? []).map((c) =>
          c.id === ctx?.tempId ? { ...c, ...real, optimistic: false } : c,
        ),
      );
    },
  });
  return mut;
}

// ── module helpers ────────────────────────────────────────────

function errDescription(err: unknown): string {
  if (err instanceof GitHubError) return `${err.status}: ${err.message}`;
  if (err instanceof Error) return err.message;
  return String(err);
}

/** Write the real review id/nodeId onto the optimistic cache entry so
 * the next serialised add appends instead of creating again. */
function writeRealReviewId(
  qc: ReturnType<typeof useQueryClient>,
  key: readonly unknown[],
  review: { id: number; nodeId: string },
): void {
  qc.setQueryData<PendingReview | null>(key, (prev) =>
    prev ? { ...prev, id: review.id, nodeId: review.nodeId } : prev,
  );
}

function findComment(
  qc: ReturnType<typeof useQueryClient>,
  commentsKey: readonly unknown[],
  id: number,
): GHReviewComment | undefined {
  const published = qc.getQueryData<GHReviewComment[]>(commentsKey) ?? [];
  return published.find((c) => c.id === id);
}

function replyHeadPath(
  qc: ReturnType<typeof useQueryClient>,
  commentsKey: readonly unknown[],
  id: number,
): string {
  return findComment(qc, commentsKey, id)?.path ?? '';
}

function findPendingNodeId(
  qc: ReturnType<typeof useQueryClient>,
  key: readonly unknown[],
  id: number,
): string | undefined {
  const current = qc.getQueryData<PendingReview | null>(key);
  return current?.comments.find((c) => c.id === id)?.node_id;
}

/** Optimistic PENDING reply row, appended to the pending-review cache when
 * useSingleComment diverts a reply into an open pending review (GitHub
 * forbids a REST single-publish reply while one exists). Mirrors the reply
 * branch of usePendingReview's makeOptimistic so both render identically. */
function makePendingReplyOptimistic(
  v: Extract<SingleCommentVars, { kind: 'reply' }>,
  pending: PendingReview,
  viewer: Viewer | undefined,
  head: GHReviewComment | undefined,
): GHReviewComment {
  return {
    id: nextTempId(),
    node_id: undefined,
    pull_request_review_id: pending.id ?? 0,
    user: {
      login: viewer?.login ?? '',
      avatar_url: viewer?.avatar_url ?? '',
    },
    body: v.body,
    path: head?.path ?? '',
    line: head?.line ?? null,
    original_line: head?.original_line ?? null,
    side: head?.side ?? 'RIGHT',
    in_reply_to_id: v.inReplyTo,
    position: null,
    original_position: null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    html_url: '',
    commit_id: '',
    original_commit_id: '',
    status: 'pending',
    optimistic: true,
  };
}

/** Resolve the head comment's GraphQL node id and append a pending reply
 * to it (GraphQL inReplyTo). The head can be either a PUBLISHED comment
 * (look it up in the comments cache) or another PENDING comment in this
 * same review (look it up in the pending-review cache) — replying to a
 * pending comment must thread under it, not 404. */
async function appendReply(
  qc: ReturnType<typeof useQueryClient>,
  commentsKey: readonly unknown[],
  pendingKey: readonly unknown[],
  reviewNodeId: string,
  v: Extract<AddVars, { kind: 'reply' }>,
): Promise<void> {
  const headNodeId =
    findComment(qc, commentsKey, v.inReplyTo)?.node_id ??
    findPendingNodeId(qc, pendingKey, v.inReplyTo);
  if (!headNodeId) {
    throw new GitHubError(
      'Cannot resolve the comment being replied to',
      404,
      '/graphql',
    );
  }
  await addPendingReply(reviewNodeId, headNodeId, v.body);
}

/** Create an empty PENDING review (REST, no event, no comments) — used
 * only when the first pending action is a reply (which can't seed the
 * create-with-comment call). */
function createEmptyPendingReview(
  owner: string,
  repo: string,
  number: number,
  headSha: string | undefined,
): Promise<{ id: number; nodeId: string }> {
  return createPendingReview(owner, repo, number, headSha);
}
