// Run AI grouping: build the diff context (capped, largest-first), call the
// provider for schema-validated clusters, validate with valibot. Grouping is
// purely structural — review guidelines do NOT affect it (ADR 0026).

import * as v from 'valibot';
import type { GHPullRequestFile } from '@/github/types';
import type { FileContents } from '@/github/fetchPRFileContents';
import type { ProviderAdapter, TokenUsage } from '../provider';
import { buildContext, GROUPING_LIMITS } from '../engine/context';
import { GROUPING_SYSTEM } from '../engine/basePrompt';
import { AI_GROUPING_JSON_SCHEMA, AiGroupingResultSchema, type AiGroupingResult } from './schema';

export interface GroupingRun {
  result: AiGroupingResult;
  usage: TokenUsage;
  model: string;
  capped: { analyzed: number; totalFiles: number } | null;
}

export async function runGrouping(
  adapter: ProviderAdapter,
  files: GHPullRequestFile[],
  contents: Map<string, FileContents> | undefined,
  signal?: AbortSignal,
): Promise<GroupingRun> {
  const ctx = buildContext(files, contents, GROUPING_LIMITS);
  const instruction = `${GROUPING_SYSTEM}\n\nThere are ${ctx.includedFiles.length} files to group${
    ctx.capped ? ` (the ${ctx.capped.analyzed} largest of ${ctx.capped.totalFiles})` : ''
  }. Every file path you place in a group must be one of the paths shown above.`;

  const { data, usage, model } = await adapter.complete<unknown>({
    contextBlock: `Here is the pull request to group.\n\n${ctx.text}`,
    instruction,
    schema: AI_GROUPING_JSON_SCHEMA,
    schemaName: 'ai_grouping',
    maxTokens: 2048,
    signal,
  });

  const result = v.parse(AiGroupingResultSchema, data);
  return { result, usage, model, capped: ctx.capped };
}
