// The "Group files by" control at the top of the file rail (ADR 0022 +
// ADR 0026). A full-width labeled dropdown — "Group by <value>" — with a rich
// menu: each option carries an icon + one-line description; the AI option gets
// a "New" badge (enabled) or a locked mark + "Set up AI →" affordance (off).
// Replaces the old icon-only GroupingMenu so the control reads like the design.

import {
  CheckIcon,
  ChevronDownIcon,
  FileIcon,
  GaugeIcon,
  GitCompareIcon,
  ListIcon,
  Lock as LockIcon,
  type LucideIcon,
} from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { cn } from '@/lib/utils';
import { AiMark, AiSetupAffordance } from '@/ai/aikit';
import type { GroupingDimension } from '@/pr/changes/grouping/types';

type Option = {
  id: GroupingDimension;
  icon: LucideIcon | null; // null = AI mark
  label: string;
  desc: string;
  ai?: boolean;
};

const OPTIONS: Option[] = [
  { id: 'none', icon: ListIcon, label: 'None', desc: 'Flat list, no grouping' },
  { id: 'file-type', icon: FileIcon, label: 'File type', desc: 'Folder tree by path' },
  { id: 'similar', icon: GitCompareIcon, label: 'Similar', desc: 'Files that changed together' },
  { id: 'change-size', icon: GaugeIcon, label: 'Change size', desc: 'Largest diffs first' },
  { id: 'ai', icon: null, label: 'AI', desc: 'Cluster review-worthy vs. noise', ai: true },
];

export function AiGroupByControl({
  dimension,
  onDimensionChange,
  aiEnabled = false,
  onSetupAi,
}: {
  dimension: GroupingDimension;
  onDimensionChange: (d: GroupingDimension) => void;
  aiEnabled?: boolean;
  onSetupAi?: () => void;
}) {
  const cur = OPTIONS.find((o) => o.id === dimension) ?? OPTIONS[0];
  const curAi = !!cur.ai && aiEnabled;
  const CurIcon = cur.icon;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          aria-label="Group files by"
          className={cn(
            'flex h-7 w-full items-center gap-1.5 rounded-md border px-2 text-[12px] font-medium transition-colors',
            curAi
              ? 'border-violet-300 bg-violet-50 text-violet-700 hover:bg-violet-100 dark:border-violet-500/40 dark:bg-violet-500/15 dark:text-violet-200'
              : 'border-input bg-background text-foreground hover:bg-accent',
          )}
        >
          {curAi ? (
            <AiMark className="size-3.5 text-violet-600 dark:text-violet-300" />
          ) : CurIcon ? (
            <CurIcon className="size-3.5 text-muted-foreground" />
          ) : null}
          <span className="text-muted-foreground">Group by</span>
          <span className={curAi ? 'font-semibold text-violet-700 dark:text-violet-200' : 'font-semibold text-foreground'}>
            {cur.label}
          </span>
          <ChevronDownIcon className="ml-auto size-3 text-muted-foreground/70" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-[var(--radix-dropdown-menu-trigger-width)] p-1">
        <DropdownMenuLabel className="px-2 py-1 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">
          Group files by
        </DropdownMenuLabel>
        {OPTIONS.map((o) => {
          const active = o.id === dimension && (!o.ai || aiEnabled);
          const locked = !!o.ai && !aiEnabled;
          const Icon = o.icon;
          return (
            <DropdownMenuItem
              key={o.id}
              onSelect={(e) => {
                if (locked) {
                  e.preventDefault();
                  onSetupAi?.();
                  return;
                }
                onDimensionChange(o.id);
              }}
              className={cn(
                'flex items-start gap-2.5 px-2 py-1.5',
                active && (o.ai ? 'bg-violet-50 dark:bg-violet-500/15' : 'bg-accent'),
              )}
            >
              <span className={cn('mt-0.5 shrink-0', o.ai ? (locked ? 'text-muted-foreground' : 'text-violet-600 dark:text-violet-300') : 'text-muted-foreground')}>
                {o.ai ? (
                  locked ? (
                    <span className="relative inline-flex">
                      <AiMark className="size-4" />
                      <LockIcon className="absolute -bottom-1 -right-1 size-2.5" />
                    </span>
                  ) : (
                    <AiMark className="size-4" />
                  )
                ) : (
                  Icon && <Icon className="size-4" />
                )}
              </span>
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-1.5">
                  <span className={cn('text-[12.5px] font-medium', o.ai ? (locked ? 'text-foreground' : 'text-violet-700 dark:text-violet-200') : 'text-foreground')}>
                    {o.label}
                  </span>
                  {o.ai && !locked && (
                    <span className="rounded bg-violet-100 px-1 py-px text-[9px] font-semibold uppercase tracking-wide text-violet-600 dark:bg-violet-500/20 dark:text-violet-300">
                      New
                    </span>
                  )}
                  {locked && (
                    <span className="inline-flex items-center gap-0.5 text-[10px] font-medium text-muted-foreground">
                      <LockIcon className="size-2.5" />
                      off
                    </span>
                  )}
                </span>
                <span className="mt-0.5 block text-[11px] text-muted-foreground">{o.desc}</span>
                {locked && (
                  <span className="mt-1 inline-block">
                    <AiSetupAffordance size="sm" onClick={onSetupAi} />
                  </span>
                )}
              </span>
              {active && (
                <CheckIcon className={cn('mt-0.5 size-3.5 shrink-0', o.ai ? 'text-violet-600 dark:text-violet-300' : 'text-foreground')} />
              )}
            </DropdownMenuItem>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
