// Compact "settled comment" UI for Conversation Focus mode.
//
// `CompactSettledRow` is an extremely compact (~30px) one-line stand-in for
// a settled comment/thread — resolved, outdated, or stale — shown only in
// Focus mode so the open/pending discussion reads without the dead weight:
//   status dot · avatar · author · [file:line] · faded summary · [verdict]
//   · status tag · reply count · age · expand chevron.
// Click → expand back to the full thread (currently exits Focus, matching
// EventsCollapsed; a single-row in-place expand is a stretch follow-up).
//
// `SettledBand` wraps a consecutive run of those rows in one quiet card so
// a cluster reads as a single skippable zone. Parity: gh-comments.jsx ·
// GhCompactComment + GhSettledBand.

import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Icon, type IconName } from '../../ui/Icon';
import type { SettledCompact, SettledStatus } from './settled';

const SETTLED_META: Record<
  SettledStatus,
  { label: string; dot: string; tag: string; icon: IconName }
> = {
  resolved: {
    label: 'Resolved',
    dot: 'bg-emerald-500',
    tag: 'border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900 dark:bg-emerald-950/50 dark:text-emerald-300',
    icon: 'check-circle',
  },
  outdated: {
    label: 'Outdated',
    dot: 'bg-amber-500',
    tag: 'border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900 dark:bg-amber-950/50 dark:text-amber-300',
    icon: 'reload',
  },
  stale: {
    label: 'Stale',
    dot: 'bg-zinc-400',
    tag: 'border-zinc-200 bg-zinc-100 text-zinc-500 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-400',
    icon: 'clock',
  },
  handled: {
    label: 'Replied',
    dot: 'bg-sky-500',
    tag: 'border-sky-200 bg-sky-50 text-sky-700 dark:border-sky-900 dark:bg-sky-950/50 dark:text-sky-300',
    icon: 'check',
  },
};

function initialsOf(login: string): string {
  return login
    .split(/[\s-]+/)
    .map((s) => s[0] ?? '')
    .slice(0, 2)
    .join('')
    .toUpperCase();
}

export function CompactSettledRow({
  status,
  author,
  authorAvatarUrl,
  age,
  summary,
  replies = 0,
  file,
  line,
  reviewState,
  onExpand,
}: SettledCompact & { onExpand?: () => void }) {
  const meta = SETTLED_META[status];
  return (
    <button
      type="button"
      onClick={onExpand}
      title={`${meta.label} — click to expand`}
      className="group flex w-full items-center gap-2 rounded-md border border-transparent px-2.5 py-1 text-left transition-colors hover:border-border hover:bg-card"
    >
      <span className={`size-1.5 shrink-0 rounded-full ${meta.dot}`} />
      <Avatar className="size-4 shrink-0">
        {authorAvatarUrl && <AvatarImage src={authorAvatarUrl} alt={author} />}
        <AvatarFallback style={{ fontSize: 7 }}>
          {initialsOf(author)}
        </AvatarFallback>
      </Avatar>
      <span className="shrink-0 text-[12px] font-medium text-muted-foreground">
        {author}
      </span>
      {file && (
        <span className="hidden shrink-0 items-center gap-1 font-mono text-[10.5px] text-muted-foreground/70 sm:inline-flex">
          <Icon name="comment" size={12} />
          {file.split('/').pop()}
          {line != null ? `:${line}` : ''}
        </span>
      )}
      <span className="min-w-0 flex-1 truncate text-[12px] text-muted-foreground/70">
        {summary}
      </span>
      {reviewState && (
        <span
          className={`hidden shrink-0 text-[11px] font-medium md:inline ${
            reviewState === 'changes' ? 'text-amber-600' : 'text-emerald-600'
          }`}
        >
          {reviewState === 'changes' ? 'changes' : 'approved'}
        </span>
      )}
      <span
        className={`inline-flex shrink-0 items-center gap-1 rounded-full border px-1.5 py-0 text-[10px] font-medium ${meta.tag}`}
      >
        <Icon name={meta.icon} size={10} />
        {meta.label}
      </span>
      {replies > 0 && (
        <span className="inline-flex shrink-0 items-center gap-1 text-[11px] text-muted-foreground/70">
          <Icon name="comment" size={12} />
          {replies}
        </span>
      )}
      {age && (
        <span className="shrink-0 text-[11px] tabular-nums text-muted-foreground/70">
          {age}
        </span>
      )}
      <Icon
        name="chevron-right"
        size={14}
        style={{ flexShrink: 0 }}
        color="hsl(var(--muted-foreground))"
      />
    </button>
  );
}

export function SettledBand({
  count,
  onExpandAll,
  children,
}: {
  count: number;
  onExpandAll?: () => void;
  children: React.ReactNode;
}) {
  return (
    <div className="relative z-[1] my-2 overflow-hidden rounded-lg border bg-muted/30">
      <div className="flex items-center gap-2 px-2.5 py-1 text-[11px] text-muted-foreground/80">
        <Icon name="check" size={14} />
        <span className="font-medium uppercase tracking-wide">
          {count} settled · collapsed
        </span>
        {onExpandAll && (
          <button
            type="button"
            onClick={onExpandAll}
            className="ml-auto rounded px-1.5 py-0.5 text-[11px] font-medium text-muted-foreground hover:bg-card hover:text-foreground"
          >
            Expand all
          </button>
        )}
      </div>
      <div className="border-t p-1">{children}</div>
    </div>
  );
}
