// GhReactions — emoji reaction strip + add-reaction picker + a
// "who reacted" tooltip.
//
// Design parity: gh-comments.jsx · GhReactions. Renders the eight
// canonical reactions GitHub returns inline on every comment payload
// (`+1`, `-1`, `laugh`, `hooray`, `confused`, `heart`, `rocket`,
// `eyes`). Counts come from the API's per-comment `reactions` summary
// — the reactor *names* (and whether the viewer is among them) live
// behind a separate `/reactions` endpoint that we fetch up front on
// mount, not on hover, so the viewer's own reactions are outlined
// immediately on load. Cached per-mount and refetched after a toggle.
//
// The "+" affordance opens a Popover with the eight pickable emoji.
// `onAdd` is wired by the caller so the post / delete mutation stays
// out of the component (issue comments vs review comments take
// different endpoints).

import { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { SmileIcon } from 'lucide-react';
import type { GHReactions as GHReactionsData } from '../../github/types';
import type { GHReactor } from '../../github/client';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

/** The eight canonical reactions, in the order GitHub renders them in
 * its own picker. `key` matches the GHReactions field on the API
 * payload; `name` is the slash-command name (`:rocket:`). */
const GH_REACTIONS: Array<{
  glyph: string;
  key: keyof GHReactionsData;
  name: string;
  /** API content value returned by the /reactions list endpoint.
   * Differs from `key` only for `+1` / `-1` — the summary uses
   * `+1` (string field name) but the list response also uses `+1`
   * for content. They line up, but routing through this constant
   * documents the contract. */
  content: string;
}> = [
  { glyph: '👍', key: '+1', name: '+1', content: '+1' },
  { glyph: '👎', key: '-1', name: '-1', content: '-1' },
  { glyph: '😄', key: 'laugh', name: 'laugh', content: 'laugh' },
  { glyph: '🎉', key: 'hooray', name: 'hooray', content: 'hooray' },
  { glyph: '😕', key: 'confused', name: 'confused', content: 'confused' },
  { glyph: '❤️', key: 'heart', name: 'heart', content: 'heart' },
  { glyph: '🚀', key: 'rocket', name: 'rocket', content: 'rocket' },
  { glyph: '👀', key: 'eyes', name: 'eyes', content: 'eyes' },
];

export function GhReactions({
  reactions,
  onAdd,
  onRemove,
  listReactors,
  reactorCacheKey,
  viewerLogin,
}: {
  reactions?: GHReactionsData;
  /** Add the viewer's reaction. May return a promise; when it does,
   * `togglePick` awaits it before invalidating the reactor query so the
   * refetch doesn't race the POST. */
  onAdd?: (key: keyof GHReactionsData) => void | Promise<void>;
  /** Wired by caller to DELETE the viewer's reaction. Receives both
   * the content key (so the caller can decrement the matching counter
   * optimistically) and the GitHub reaction id (the reactor list carries
   * it; the DELETE endpoint needs the id, not the content). May return a
   * promise — awaited like `onAdd`. When omitted, the picker / badge
   * becomes add-only and clicking an emoji the viewer has already
   * reacted with is a no-op. */
  onRemove?: (
    key: keyof GHReactionsData,
    reactionId: number,
  ) => void | Promise<void>;
  /** Fetch the full reactor list for this comment. Called once up front
   * on mount (and again after a toggle), not on hover, so the viewer's
   * own reactions are outlined immediately. The result is cached on this
   * component and shared by every reaction button's tooltip. Returns the
   * raw array GitHub gives us — we group by `content` for display. */
  listReactors?: () => Promise<GHReactor[]>;
  /** Stable identity for the comment this strip belongs to (the
   * comment's `html_url`) — the React Query key for its reactor list
   * (`['pr-reactors', reactorCacheKey]`). Callers rebuild `listReactors`
   * as a fresh closure every render (it's built inside per-comment
   * mappers), so the key can't be the closure; this stable id keeps the
   * cache slot fixed across renders. Required for the reactor query to
   * run — when omitted the strip shows counts only (no outline). */
  reactorCacheKey?: string;
  /** Viewer login — used to render "You" instead of the username at
   * the head of the reactor list, matching GitHub's wording. */
  viewerLogin?: string;
}) {
  const [pickerOpen, setPickerOpen] = useState(false);
  const qc = useQueryClient();

  const visible = GH_REACTIONS.filter((r) => {
    const v = reactions?.[r.key];
    return typeof v === 'number' && v > 0;
  });
  const hasReactions = visible.length > 0;

  // Reactor list (names + reaction ids) for this comment, held in React
  // Query so it loads up front — not on hover — is cached per comment,
  // and reconciles via invalidation after a toggle. `placeholderData`
  // keeps the prior list on screen across that refetch (no flash to
  // empty). The optimistic cache patch in `togglePick` flips the "you
  // reacted" outline on click without waiting for the round-trip, so no
  // mirror state lives in the component.
  const reactorsKey = ['pr-reactors', reactorCacheKey] as const;
  const { data: reactors, isPending: reactorsPending } = useQuery({
    queryKey: reactorsKey,
    queryFn: () => listReactors!(),
    enabled: !!reactorCacheKey && !!listReactors && hasReactions,
    staleTime: 30_000,
    placeholderData: (prev) => prev,
  });

  // Nothing to show, and no add affordance is needed when reactions
  // can't be posted (no callback wired). Returning null keeps the
  // footer flush against the body for read-only contexts.
  if (!hasReactions && !onAdd) return null;

  /** Toggle the viewer's reaction for `key`. Reads the cached reactor
   * list to decide add vs. remove (the REST DELETE needs the reaction
   * id it carries), optimistically patches that cache so the outline
   * flips immediately, fires the caller's mutation, then invalidates the
   * reactor query to refetch the authoritative list. Counts are left to
   * the caller's optimistic update (withOptimisticReaction), which the
   * codebase deliberately does NOT invalidate — natural refetch cadence
   * reconciles them. */
  const togglePick = async (key: keyof GHReactionsData) => {
    setPickerOpen(false);
    const content = GH_REACTIONS.find((r) => r.key === key)?.content;
    if (!content) return;
    // Make sure we hold the current list (with reaction ids) before
    // deciding add vs. remove — usually a warm cache hit after the
    // mount fetch; ensureQueryData covers a click before it resolved.
    const rs =
      reactorCacheKey && listReactors
        ? await qc.ensureQueryData({
            queryKey: reactorsKey,
            queryFn: () => listReactors(),
          })
        : (reactors ?? []);
    const mine = viewerLogin
      ? rs.find((x) => x.content === content && x.user.login === viewerLogin)
      : undefined;

    // Optimistically flip the outline by patching the reactor cache (id 0
    // is a placeholder until the refetch supplies the real one).
    if (viewerLogin)
      qc.setQueryData<GHReactor[]>(reactorsKey, (prev = []) =>
        mine
          ? prev.filter((x) => x !== mine)
          : [
              ...prev,
              {
                id: 0,
                content,
                user: { login: viewerLogin, avatar_url: '' },
                created_at: '',
              },
            ],
      );

    const result = mine && onRemove ? onRemove(key, mine.id) : onAdd?.(key);

    // Reconcile once the mutation settles. Awaiting first keeps the
    // refetch from racing the POST (a refetch that landed before GitHub
    // registered the reaction would clobber the optimistic outline); the
    // `finally` resyncs on failure too, undoing the optimistic patch.
    try {
      await Promise.resolve(result);
    } finally {
      void qc.invalidateQueries({ queryKey: reactorsKey });
    }
  };

  return (
    <TooltipProvider delayDuration={250}>
      <div className="flex flex-wrap items-center gap-1.5">
        {visible.map((r) => {
          const count = reactions?.[r.key] as number;
          const matching = (reactors ?? []).filter((x) => x.content === r.content);
          // Highlight when the viewer reacted — read straight from the
          // reactor cache, which `togglePick` patches optimistically so
          // the outline flips on click before the refetch lands.
          const isMine =
            !!viewerLogin && matching.some((x) => x.user.login === viewerLogin);
          return (
            <Tooltip key={r.key as string}>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  onClick={() => void togglePick(r.key)}
                  disabled={!onAdd && !onRemove}
                  // Server doesn't tell us in the summary whether the
                  // viewer is one of the reactors — we infer it from
                  // the lazy-loaded list when available. Click toggles
                  // the viewer's own reaction (add or remove).
                  className={cn(
                    'inline-flex h-6 items-center gap-1 rounded-full border bg-card px-2 text-[12px] font-medium text-foreground hover:bg-muted disabled:cursor-default disabled:hover:bg-card',
                    isMine && 'border-primary/60 bg-primary/10 text-primary',
                  )}
                >
                  <span className="leading-none">{r.glyph}</span>
                  <span className="tabular-nums">{count}</span>
                </button>
              </TooltipTrigger>
              <TooltipContent
                side="top"
                className="max-w-[260px] text-[11.5px] leading-snug"
              >
                {renderReactorTooltip({
                  glyph: r.glyph,
                  name: r.name,
                  count,
                  reactors: matching,
                  loading: reactorsPending,
                  viewerLogin,
                })}
              </TooltipContent>
            </Tooltip>
          );
        })}
        {onAdd && (
          <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
            <PopoverTrigger asChild>
              <button
                type="button"
                className="inline-flex h-6 items-center gap-0.5 rounded-full border border-dashed bg-card px-1.5 text-muted-foreground hover:border-foreground/40 hover:bg-muted hover:text-foreground"
                title="Add reaction"
              >
                <SmileIcon className="size-3.5" />
                <span className="text-[10.5px] leading-none">+</span>
              </button>
            </PopoverTrigger>
            <PopoverContent
              align="start"
              sideOffset={6}
              className="w-auto rounded-lg px-1.5 py-1.5"
            >
              <div className="flex items-center gap-0.5">
                {GH_REACTIONS.map((r) => {
                  // "Mine" from the reactor cache (optimistically patched
                  // on click). Without a known viewer we can only guess
                  // from the summary count.
                  const reactorsForKey = (reactors ?? []).filter(
                    (x) => x.content === r.content,
                  );
                  const summaryMine =
                    typeof reactions?.[r.key] === 'number' &&
                    (reactions[r.key] as number) > 0;
                  const isMine = !viewerLogin
                    ? summaryMine
                    : reactorsForKey.some((x) => x.user.login === viewerLogin);
                  return (
                    <button
                      key={r.key as string}
                      type="button"
                      onClick={() => void togglePick(r.key)}
                      title={
                        isMine
                          ? `Remove :${r.name}: reaction`
                          : `:${r.name}:`
                      }
                      className={cn(
                        'inline-flex size-7 items-center justify-center rounded-md text-[16px] hover:bg-muted',
                        isMine && 'bg-primary/10 ring-1 ring-primary/40',
                      )}
                    >
                      {r.glyph}
                    </button>
                  );
                })}
              </div>
            </PopoverContent>
          </Popover>
        )}
      </div>
    </TooltipProvider>
  );
}

/** Format the reactor list the way GitHub does: comma-separated
 * names with "You" hoisted to the front, then "and N more" if the
 * list is longer than four. Falls back to a count-only line while
 * the lazy fetch is in flight, or when there's no fetcher wired. */
function renderReactorTooltip({
  glyph,
  name,
  count,
  reactors,
  loading,
  viewerLogin,
}: {
  glyph: string;
  name: string;
  count: number;
  reactors: GHReactor[];
  loading: boolean;
  viewerLogin?: string;
}) {
  if (loading) {
    return (
      <span>
        Loading reactors for {glyph} {name}…
      </span>
    );
  }
  if (reactors.length === 0) {
    return (
      <span>
        {count} {count === 1 ? 'person' : 'people'} reacted with {glyph} {name}
      </span>
    );
  }
  // Hoist "You" to the front so the viewer's own reaction is
  // immediately visible — matches GitHub's behaviour.
  const names = reactors.map((r) => r.user.login);
  const withYou = viewerLogin
    ? [
        ...(names.includes(viewerLogin) ? ['You'] : []),
        ...names.filter((n) => n !== viewerLogin),
      ]
    : names;
  const visible = withYou.slice(0, 4);
  const overflow = withYou.length - visible.length;
  const list = overflow > 0
    ? `${visible.join(', ')} and ${overflow} more`
    : visible.length > 1
      ? `${visible.slice(0, -1).join(', ')} and ${visible[visible.length - 1]}`
      : visible[0];
  return (
    <span>
      <b className="font-semibold">{list}</b> reacted with {glyph} {name}
    </span>
  );
}
