// Markdown renderer wrapping react-markdown + remark-gfm (tables,
// strikethrough, task lists, autolinks) + rehype-sanitize. Sanitization
// is non-negotiable — PR bodies + comments are user-controlled input
// and can contain arbitrary HTML.
//
// Styled minimally to match Pyor's typography (SF Pro for prose, SF
// Mono for code chips, single accent for links). The bulk of the
// styling rides on the surrounding tab card; this component only
// shapes the document tree.
//
// Per ADR 0011: no useT(), no theme/tokens.ts imports, no static
// inline styles — everything below is Tailwind utilities consuming
// the CSS variables in styles/tailwind.css.

import React, { Children, isValidElement, memo, type ReactNode } from 'react';
import {
  AlertTriangleIcon,
  CheckIcon,
  InfoIcon,
  LightbulbIcon,
  OctagonAlertIcon,
  ShieldAlertIcon,
} from 'lucide-react';
import { CopyIconMorph } from '@/components/ui/copy-icon';
import { ProxiedImg } from './ProxiedImg';
import ReactMarkdown, { defaultUrlTransform } from 'react-markdown';
import rehypeRaw from 'rehype-raw';
import rehypeSanitize, { defaultSchema } from 'rehype-sanitize';
import remarkGfm from 'remark-gfm';
import { EXTENSION_TO_FILE_FORMAT } from '@pierre/diffs';
import {
  useDiffSnippetHighlight,
  type DiffSnippetHighlight,
  type HighlightLine,
} from '../pr/conversation/useDiffSnippetHighlight';

// A fenced block's info-string is a language identifier, but the shared
// highlighter resolves grammars from a *file name* via the lib's
// `getFiletypeFromFileName`, which only understands file *extensions*.
// A fence almost always carries the language *name* (```python,
// ```javascript) rather than an extension (```py, ```js), so the naive
// `code.<lang>` synthetic name resolved to plain text and the block
// rendered uncoloured. Reverse the lib's own extension→format table
// (first extension wins) so a language name maps back to a
// representative extension the resolver understands — both forms then
// resolve to the right grammar.
const FORMAT_TO_EXTENSION: Record<string, string> = Object.entries(
  EXTENSION_TO_FILE_FORMAT as Record<string, string>,
).reduce<Record<string, string>>((acc, [ext, format]) => {
  acc[format] ??= ext;
  return acc;
}, {});

/** Synthetic file name the shared highlighter can resolve from a fence
 * language token. Accepts both `python` (a format name) and `py` (an
 * extension); falls back to plain text for an empty or unknown token. */
function fenceLangFileName(lang: string): string {
  if (!lang) return 'code.txt';
  if (lang in (EXTENSION_TO_FILE_FORMAT as Record<string, string>))
    return `code.${lang}`;
  const ext = FORMAT_TO_EXTENSION[lang];
  return ext ? `code.${ext}` : `code.${lang}`;
}

// Code-fence copy button. Stateful so the icon can morph copy→check on
// success; copies the fence's source text passed in by the caller.
function CodeCopyButton({ text }: { text: string }) {
  const [copied, setCopied] = React.useState(false);
  return (
    <button
      type="button"
      onClick={() => {
        // Copy the fence's source text directly. The earlier DOM-scrape
        // (`closest('[data-pyor-code-block]')`) never worked: the button
        // lives in the header strip while the <pre> is its *sibling*, so
        // closest() — which only walks ancestors — always returned null.
        void navigator.clipboard?.writeText(text);
        setCopied(true);
        window.setTimeout(() => setCopied(false), 1500);
      }}
      className="ml-auto inline-flex items-center gap-1 rounded px-1.5 py-0.5 hover:bg-muted hover:text-foreground"
      title={copied ? 'Copied' : 'Copy'}
    >
      <CopyIconMorph copied={copied} className="size-3" />
      {copied ? 'Copied' : 'Copy'}
    </button>
  );
}

// GitHub alert block config — > [!NOTE], > [!TIP], etc.
const ALERTS = {
  NOTE:      { title: 'Note',      icon: <InfoIcon className="size-3.5" />,         border: 'border-blue-400/60',   bg: 'bg-blue-50/60 dark:bg-blue-950/20',   text: 'text-blue-600 dark:text-blue-400' },
  TIP:       { title: 'Tip',       icon: <LightbulbIcon className="size-3.5" />,    border: 'border-emerald-400/60',bg: 'bg-emerald-50/60 dark:bg-emerald-950/20', text: 'text-emerald-600 dark:text-emerald-400' },
  IMPORTANT: { title: 'Important', icon: <ShieldAlertIcon className="size-3.5" />,  border: 'border-violet-400/60', bg: 'bg-violet-50/60 dark:bg-violet-950/20', text: 'text-violet-600 dark:text-violet-400' },
  WARNING:   { title: 'Warning',   icon: <AlertTriangleIcon className="size-3.5" />,border: 'border-amber-400/60',  bg: 'bg-amber-50/60 dark:bg-amber-950/20',  text: 'text-amber-600 dark:text-amber-400' },
  CAUTION:   { title: 'Caution',   icon: <OctagonAlertIcon className="size-3.5" />, border: 'border-red-400/60',    bg: 'bg-red-50/60 dark:bg-red-950/20',     text: 'text-red-600 dark:text-red-400' },
} as const;

// ADR 0012 Phase 5 — Local Review Comments embed pasted images as
// `pyor-attachment://…` URLs, served by the Electron main process's
// custom protocol handler. rehype-sanitize's default GitHub schema
// only allows `http` / `https` for <img src>, which would strip our
// URLs at sanitize time. Extend the schema's `src` protocol list to
// include `pyor-attachment`. The scheme is locked to local userData
// reads by the main-process handler, so widening the renderer's
// allow-list is safe — there's no remote fetch path.
// GitHub's bot comments (github-actions, dependabot, etc.) often ship
// pure HTML bodies — <h2 align="center"><table align="center">… — not
// markdown. Without rehype-raw, react-markdown treats the raw HTML
// source as text and shows nothing. Adding rehype-raw + a sanitize
// schema that allows the deprecated `align` attribute on layout
// elements lets these bot comments render as intended without
// opening the door to XSS.
const sanitizeSchema = {
  ...defaultSchema,
  attributes: {
    ...(defaultSchema.attributes ?? {}),
    h1: [...((defaultSchema.attributes?.h1 as unknown[]) ?? []), 'align'],
    h2: [...((defaultSchema.attributes?.h2 as unknown[]) ?? []), 'align'],
    h3: [...((defaultSchema.attributes?.h3 as unknown[]) ?? []), 'align'],
    h4: [...((defaultSchema.attributes?.h4 as unknown[]) ?? []), 'align'],
    p: [...((defaultSchema.attributes?.p as unknown[]) ?? []), 'align'],
    div: [
      ...((defaultSchema.attributes?.div as unknown[]) ?? []),
      'align',
      'className',
    ],
    table: [
      ...((defaultSchema.attributes?.table as unknown[]) ?? []),
      'align',
    ],
    img: [
      ...((defaultSchema.attributes?.img as unknown[]) ?? []),
      'align',
      'width',
      'height',
    ],
    details: [
      ...((defaultSchema.attributes?.details as unknown[]) ?? []),
      'open',
    ],
  },
  protocols: {
    ...(defaultSchema.protocols ?? {}),
    src: [...(defaultSchema.protocols?.src ?? []), 'pyor-attachment'],
  },
};

// react-markdown runs its OWN url sanitiser (`urlTransform`) BEFORE
// rehype-sanitize sees the tree, and its default strips any non-
// http/https/mailto/tel/relative URL to "" — which silently blanked our
// local-comment `pyor-attachment://` images (the `<img src="">` bug).
// Preserve that scheme; defer everything else to the default.
function pyorUrlTransform(url: string): string {
  if (url.startsWith('pyor-attachment://')) return url;
  return defaultUrlTransform(url);
}

// Minimal structural view of the hast nodes we walk — avoids a direct
// dependency on `hast`/`unified` types (both are transitive only).
interface HastNode {
  type?: string;
  tagName?: string;
  properties?: Record<string, unknown>;
  position?: { start?: { line?: number } };
  children?: HastNode[];
}

// rehype plugin: stamp each GFM task-list checkbox <input> with the
// 1-based source line of its owning <li>, as `data-line`. remark-gfm
// synthesizes the checkbox without any position of its own, but its <li>
// keeps one — and it survives rehype-raw + rehype-sanitize intact. The
// line lets the toggle handler rewrite the exact marker the user clicked
// (see web/src/pr/taskList.ts), instead of counting task lines with a
// regex that drifts on fenced code blocks / ordered-list task items.
// Runs AFTER sanitize so the added attribute isn't stripped.
function rehypeStampTaskLines() {
  const walk = (node: HastNode, liLine?: number) => {
    const line =
      node.tagName === 'li' ? node.position?.start?.line ?? liLine : liLine;
    const isCheckbox =
      node.tagName === 'input' && node.properties?.type === 'checkbox';
    if (isCheckbox && line != null) node.properties!['data-line'] = line;
    node.children?.forEach((child) => walk(child, line));
  };
  return (tree: HastNode) => walk(tree);
}

interface Props {
  source: string;
  /** Smaller default font + relaxed line-height for the dense card
   * variant (PR description). */
  size?: 'sm' | 'md';
  /** Hint for the host file's language so ```suggestion fences (which
   * GitHub renders in the file's own language, but ship no `language-`
   * class) can be syntax-highlighted. Pass the file's extension or a
   * Shiki-bundled lang name (`tsx`, `py`, `rs`, …). Most callers
   * don't need this — only those rendering comments attached to a
   * specific file (inline review threads), where ```suggestion has
   * obvious-from-context meaning. */
  fileLang?: string;
  /** Original line(s) a ```suggestion block replaces — lets the
   * suggestion render as a real before→after diff (removed baseline →
   * added suggestion) instead of a green box showing only the new code.
   * Composer preview passes the commented line (suggestionSeed); posted
   * comments derive it from the anchored `diff_hunk` (see
   * baselineFromHunk). Omitted → the suggestion renders as additions
   * only (no removed lines). */
  suggestionBaseline?: string;
  /** Makes GFM task-list checkboxes (`- [ ]`/`- [x]`) interactive.
   * Called with the 1-based SOURCE LINE of the clicked checkbox (stamped
   * by rehypeStampTaskLines from the owning <li>'s position) and its next
   * checked state. When omitted (every caller except the editable PR
   * description), checkboxes stay disabled/read-only exactly as remark-gfm
   * emits them. The line — not an ordinal index — is the contract, so it
   * stays correct even when the body mixes fenced code blocks or
   * ordered-list task items (see web/src/pr/taskList.ts). */
  onToggleTask?: (sourceLine: number, nextChecked: boolean) => void;
}

// Memoised: react-markdown re-parses the full body on every render, so an
// unrelated re-render (e.g. a window-focus background refetch that returns
// the same body string) would otherwise re-parse and momentarily flash the
// controlled task-list checkboxes. With `source` a string and `onToggleTask`
// stabilised by the caller, the shallow compare skips the re-parse when the
// content hasn't actually changed.
export const Markdown = memo(function Markdown({
  source,
  size = 'md',
  fileLang,
  suggestionBaseline,
  onToggleTask,
}: Props) {
  // Size-derived classes. The original component computed everything
  // off a numeric `fontSize` (12.5 for sm, 13.5 for md); the values
  // below encode the same arithmetic as static class pairs.
  const sm = size === 'sm';

  const rootSize = sm ? 'text-[12.5px]' : 'text-[13.5px]';
  const codeSize = sm ? 'text-[11px]' : 'text-[12px]';
  const tableSize = sm ? 'text-[11.5px]' : 'text-[12.5px]';
  const suggestionLabelSize = sm ? 'text-[10.5px]' : 'text-[11.5px]';
  const h1Size = sm ? 'text-[18.5px]' : 'text-[19.5px]';
  const h2Size = sm ? 'text-[16.5px]' : 'text-[17.5px]';
  const h3Size = sm ? 'text-[14px]' : 'text-[15px]';

  return (
    <div
      className={`${rootSize} leading-[1.55] text-foreground break-words`}
    >
      <ReactMarkdown
        urlTransform={pyorUrlTransform}
        remarkPlugins={[remarkGfm]}
        // Order matters: rehype-raw parses inline HTML in the source
        // into the syntax tree, then rehype-sanitize strips anything
        // disallowed by the schema. Reversing the order would let raw
        // HTML through unsanitised. rehypeStampTaskLines runs LAST (only
        // when checkboxes are interactive) so its `data-line` attribute
        // survives sanitize — see the plugin's note.
        rehypePlugins={[
          rehypeRaw,
          [rehypeSanitize, sanitizeSchema],
          ...(onToggleTask ? [rehypeStampTaskLines] : []),
        ]}
        components={{
          // GFM task-list checkbox. remark-gfm emits these as
          // `<input type="checkbox" disabled>` inside the <li>. When the
          // caller threads `onToggleTask` (only the editable PR
          // description), render the checkbox enabled + controlled and
          // wire its onChange to the box's source line (stamped on
          // `data-line` by rehypeStampTaskLines). The onChange is a React
          // handler we own — it isn't raw HTML — so rehype-sanitize
          // (which strips handlers from raw HTML only) leaves it intact.
          // Absent the prop, fall through to the default disabled render
          // so every other surface stays read-only.
          input: ({ node: _node, type, checked, ...props }) => {
            const rawLine = (props as Record<string, unknown>)['data-line'];
            const line = Number(rawLine);
            if (type === 'checkbox' && onToggleTask && Number.isFinite(line)) {
              return (
                // GitHub-style box: a clearly bordered, filled-on-check
                // control with a real checkmark — far higher contrast
                // than the native `accent-color` box. Pulled left into the
                // list's padding (where the bullet would sit) so the text
                // still lines up; the <li> drops its disc for task items.
                <span className="relative -ml-[1.45em] mr-1.5 inline-flex size-[15px] translate-y-[2px]">
                  <input
                    type="checkbox"
                    checked={!!checked}
                    onChange={(e) => onToggleTask(line, e.target.checked)}
                    className="peer size-full cursor-pointer appearance-none rounded-[4px] border border-foreground/30 bg-background shadow-sm transition-colors hover:border-primary/70 checked:border-primary checked:bg-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1 focus-visible:ring-offset-background"
                  />
                  <CheckIcon
                    strokeWidth={3.5}
                    className="pointer-events-none absolute inset-0 m-auto size-[11px] text-primary-foreground opacity-0 transition-opacity peer-checked:opacity-100"
                  />
                </span>
              );
            }
            // Read-only default (and any non-checkbox input): keep the
            // sanitized markup as-is, disabled.
            return <input type={type} checked={checked} disabled {...props} />;
          },
          a: ({ node: _node, ...props }) => (
            <a
              {...props}
              className="text-pyor-link no-underline hover:underline"
              target="_blank"
              rel="noopener noreferrer"
            />
          ),
          code: ({ node: _node, className, children, ...props }) => {
            const isBlock = (className ?? '').startsWith('language-');
            const isSuggestion = className === 'language-suggestion';
            // GitHub-style `\`\`\`suggestion`-fenced block: render as a
            // green-tinted "Suggested change" card so it's visually
            // distinct from a regular code block. v1 is read-only —
            // no "Apply suggestion" button (would need write access
            // to the PR head + commit-creation flow).
            if (isSuggestion) {
              // ```suggestion fences replace line(s) in the host file.
              // Render a real before→after diff: the original line(s)
              // (`suggestionBaseline`, when known) as removed, the
              // suggestion as added — both syntax-highlighted via the
              // shared @pierre/diffs highlighter. v1 is read-only — no
              // "Apply suggestion" button (needs write + commit flow).
              return (
                <div className="my-2 overflow-hidden rounded-md border-[0.5px] border-pyor-pass/60">
                  <div
                    className={`flex items-center gap-1.5 border-b-[0.5px] border-pyor-pass/60 bg-pyor-pass/15 px-2.5 py-[5px] font-semibold uppercase tracking-[0.2px] text-pyor-pass ${suggestionLabelSize}`}
                  >
                    <span className="inline-block size-1.5 rounded-[1px] bg-pyor-pass" />
                    Suggested change
                  </div>
                  <SuggestionDiff
                    baseline={suggestionBaseline}
                    suggestion={nodeText(children)}
                    lang={fileLang}
                    codeSize={codeSize}
                  />
                </div>
              );
            }
            if (isBlock) {
              // Match design parity (gh-comments.jsx · GhCodeBlock):
              // fenced code blocks get a header strip with the language
              // badge + Copy button so they read as proper code embeds
              // rather than tabular pre tags. The language is parsed
              // from the GFM `language-xyz` class; absent it, the strip
              // is still rendered (so spacing stays consistent) but the
              // badge falls back to "code".
              //
              // Token coloring + theme bg/fg ride on the shared
              // @pierre/diffs highlighter via <HighlightedCode>, so
              // fenced blocks in comment bodies render in the same
              // theme the Files-tab CodeView uses. The Markdown
              // surface doesn't know the parent file's path, so the
              // language hint here is the only signal — falls back to
              // plain text when the fence omits one (```\n...).
              const lang = (className ?? '')
                .replace(/^language-/, '')
                .toLowerCase()
                .trim();
              const langLabel = lang || 'code';
              return (
                <div className="my-2 overflow-hidden rounded-md border-[0.5px] border-border">
                  <div className="flex items-center gap-2 border-b-[0.5px] border-border bg-muted/50 px-2.5 py-1 text-[10.5px] text-muted-foreground">
                    <span className="rounded-sm bg-muted px-1.5 py-0 font-medium uppercase tracking-wide">
                      {langLabel}
                    </span>
                    <CodeCopyButton text={nodeText(children)} />
                  </div>
                  <HighlightedCode
                    lang={lang}
                    className={className}
                    codeSize={codeSize}
                  >
                    {children}
                  </HighlightedCode>
                </div>
              );
            }
            return (
              <code
                className={`rounded-[3px] bg-muted px-[5px] py-px font-mono ${codeSize}`}
                {...props}
              >
                {children}
              </code>
            );
          },
          h1: ({ node: _node, ...props }) => (
            <h1
              {...props}
              className={`mb-3 mt-5 border-b border-border pb-2 font-bold tracking-[-0.2px] first:mt-0 ${h1Size}`}
            />
          ),
          h2: ({ node: _node, ...props }) => (
            <h2
              {...props}
              className={`mb-3 mt-5 border-b border-border pb-2 font-bold tracking-[-0.1px] first:mt-0 ${h2Size}`}
            />
          ),
          h3: ({ node: _node, ...props }) => (
            <h3
              {...props}
              className={`mb-2 mt-4 font-semibold first:mt-0 ${h3Size}`}
            />
          ),
          p: ({ node: _node, ...props }) => (
            <p {...props} className="mb-3 mt-0 whitespace-pre-wrap last:mb-0" />
          ),
          ul: ({ node: _node, ...props }) => (
            <ul
              {...props}
              className="mb-4 mt-0 list-disc pl-8 last:mb-0
                [&_ol]:mb-0 [&_ol]:mt-0 [&_ol]:list-[lower-roman]
                [&_ul]:mb-0 [&_ul]:mt-0 [&_ul]:list-[circle]
                [&_ul_ul]:list-[square]"
            />
          ),
          ol: ({ node: _node, ...props }) => (
            <ol
              {...props}
              className="mb-4 mt-0 list-decimal pl-8 last:mb-0
                [&_ol]:mb-0 [&_ol]:mt-0
                [&_ul]:mb-0 [&_ul]:mt-0 [&_ul]:list-[circle]"
            />
          ),
          li: ({ node: _node, className, ...props }) => {
            // Task-list items drop their disc bullet (the checkbox stands
            // in for it, GitHub-style). remark-gfm marks them with the
            // `task-list-item` class; the explicit className below would
            // otherwise clobber it, so detect it from the incoming value.
            const isTask =
              typeof className === 'string' &&
              className.includes('task-list-item');
            return (
              <li
                {...props}
                className={`mt-1 first:mt-0 [&>p]:mt-3 [&>p:first-child]:mt-0 [&>p:last-child]:mb-0${isTask ? ' list-none' : ''}`}
              />
            );
          },
          blockquote: ({ node: _node, children, ...props }) => {
            // Detect GitHub alert syntax: > [!NOTE] / [!TIP] / etc.
            const kids = Children.toArray(children);
            const firstP = kids.find(
              (k): k is React.ReactElement<{ children?: ReactNode }> =>
                isValidElement(k) && (k as React.ReactElement).type === 'p',
            );
            if (firstP) {
              const txt = Children.toArray(firstP.props.children)
                .map(c => (typeof c === 'string' ? c : ''))
                .join('')
                .trim();
              const m = txt.match(/^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\]$/i);
              if (m) {
                const cfg = ALERTS[m[1].toUpperCase() as keyof typeof ALERTS];
                return (
                  <div className={`my-3 rounded-md border px-3.5 py-3 ${cfg.border} ${cfg.bg}`}>
                    <div className={`mb-2 flex items-center gap-1.5 text-[12.5px] font-semibold ${cfg.text}`}>
                      {cfg.icon}{cfg.title}
                    </div>
                    <div>{kids.filter(k => k !== firstP)}</div>
                  </div>
                );
              }
            }
            return (
              <blockquote
                {...props}
                className="my-3 border-l-[3px] border-border pl-4 text-muted-foreground"
              >
                {children}
              </blockquote>
            );
          },
          hr: ({ node: _node, ...props }) => (
            <hr
              {...props}
              className="my-4 border-0 border-t border-border"
            />
          ),
          img: ({ node: _node, ...props }) => (
            <ProxiedImg
              {...props}
              className="my-1.5 h-auto max-h-[320px] w-auto max-w-full rounded-[4px] object-contain sm:max-w-[420px]"
            />
          ),
          table: ({ node: _node, ...props }) => (
            <div className="my-2 overflow-auto">
              <table
                {...props}
                className={`w-max max-w-full border-collapse ${tableSize}`}
              />
            </div>
          ),
          th: ({ node: _node, ...props }) => (
            <th
              {...props}
              className="border-[0.5px] border-border bg-panel px-2.5 py-1.5 text-left font-semibold"
            />
          ),
          td: ({ node: _node, ...props }) => (
            <td
              {...props}
              className="border-[0.5px] border-border px-2.5 py-[5px]"
            />
          ),
        }}
      >
        {source}
      </ReactMarkdown>
    </div>
  );
});

/** One-line, inline-only markdown render for the collapsed-comment header
 * preview. Reuses the same parser + sanitize schema as <Markdown>, but maps
 * every block element to an inline span and renders code as a small chip —
 * so a comment like ``avoid `as const`?`` keeps its code styling on a single
 * line instead of being stripped to "avoid ?" (the old plain-text preview).
 *
 * The caller clamps width + truncates; we collapse whitespace and cap the
 * source first so a huge body isn't parsed in full just to show a teaser.
 * Links lose their href (no navigation from a header), and block-only
 * content — images, rules, task checkboxes — drops out. */
export function InlineMarkdown({ source }: { source: string }) {
  // Keep newlines so fenced ```code blocks still parse as code (collapsing
  // them first would turn the fence into inline text and leak the language
  // label). The header clamps to one line via CSS, where the newlines
  // render as spaces. Cap length so a long body isn't parsed in full.
  const teaser = source.trim().slice(0, 280);
  const codeChip = 'rounded-[3px] bg-muted px-[5px] py-px font-mono text-[0.9em]';
  return (
    <ReactMarkdown
      urlTransform={pyorUrlTransform}
      remarkPlugins={[remarkGfm]}
      rehypePlugins={[rehypeRaw, [rehypeSanitize, sanitizeSchema]]}
      components={{
        // Block elements → inline spans with a trailing space so adjacent
        // blocks don't run together once flattened onto one line.
        p: ({ children }) => <span>{children} </span>,
        h1: ({ children }) => <span className="font-semibold">{children} </span>,
        h2: ({ children }) => <span className="font-semibold">{children} </span>,
        h3: ({ children }) => <span className="font-semibold">{children} </span>,
        h4: ({ children }) => <span className="font-semibold">{children} </span>,
        h5: ({ children }) => <span className="font-semibold">{children} </span>,
        h6: ({ children }) => <span className="font-semibold">{children} </span>,
        ul: ({ children }) => <span>{children}</span>,
        ol: ({ children }) => <span>{children}</span>,
        li: ({ children }) => <span>{children} </span>,
        blockquote: ({ children }) => (
          <span className="text-muted-foreground">{children} </span>
        ),
        pre: ({ children }) => <>{children}</>,
        table: ({ children }) => <span>{children} </span>,
        thead: ({ children }) => <span>{children}</span>,
        tbody: ({ children }) => <span>{children}</span>,
        tr: ({ children }) => <span>{children} </span>,
        th: ({ children }) => <span>{children} </span>,
        td: ({ children }) => <span>{children} </span>,
        // Inline marks keep their styling. Both inline and fenced code
        // collapse to the same chip — faithful enough for a teaser.
        code: ({ children }) => <code className={codeChip}>{children}</code>,
        strong: ({ children }) => <strong className="font-semibold">{children}</strong>,
        em: ({ children }) => <em className="italic">{children}</em>,
        del: ({ children }) => <del>{children}</del>,
        a: ({ children }) => <span className="text-primary">{children}</span>,
        br: () => <> </>,
        hr: () => null,
        img: ({ alt }) =>
          alt ? <span className="text-muted-foreground/70">{alt}</span> : null,
        input: () => null,
      }}
    >
      {teaser}
    </ReactMarkdown>
  );
}

/** Before→after diff body for a ```suggestion block. Renders the
 * original line(s) (`baseline`) as removed rows and the suggestion as
 * added rows, each tokenised with the shared @pierre/diffs highlighter
 * (so colors + theme bg match the Files-tab diff). When `baseline` is
 * absent we show only the added rows — still a diff-style view, just with
 * nothing to remove. The "Suggested change" header is rendered by the
 * caller. */
function SuggestionDiff({
  baseline,
  suggestion,
  lang,
  codeSize,
}: {
  baseline: string | undefined;
  suggestion: string;
  lang: string | undefined;
  codeSize: string;
}) {
  const filePath = fenceLangFileName(lang ?? '');
  const baseText = (baseline ?? '').replace(/\n$/, '');
  const suggText = suggestion.replace(/\n$/, '');
  // Two unconditional hook calls (rules of hooks); baseText is '' when
  // there's no baseline, which the highlighter handles fine.
  const base = useDiffSnippetHighlight(baseText, filePath);
  const sugg = useDiffSnippetHighlight(suggText, filePath);
  const hasBaseline = (baseline ?? '').length > 0;
  const bg = sugg.themeBg ?? base.themeBg ?? undefined;

  const rows = (hl: DiffSnippetHighlight, rawText: string, kind: 'del' | 'add') => {
    const fallback: HighlightLine[] = rawText
      .split('\n')
      .map((t) => ({ tokens: [{ content: t }] }));
    const lines = hl.lines && hl.lines.length > 0 ? hl.lines : fallback;
    const isDel = kind === 'del';
    return lines.map((line, i) => (
      <div
        key={`${kind}-${i}`}
        className={`flex ${isDel ? 'bg-pyor-fail/10' : 'bg-pyor-pass/10'}`}
      >
        <span
          aria-hidden
          className={`shrink-0 select-none px-2 ${isDel ? 'text-pyor-fail' : 'text-pyor-pass'}`}
        >
          {isDel ? '−' : '+'}
        </span>
        <span className="flex-1 whitespace-pre pr-2">
          {line.tokens.map((tok, j) => (
            <span key={j} style={tok.color ? { color: tok.color } : undefined}>
              {tok.content}
            </span>
          ))}
        </span>
      </div>
    ));
  };

  return (
    <div
      className={`overflow-auto py-1 font-mono leading-[1.5] ${codeSize}`}
      style={{ backgroundColor: bg ?? undefined }}
    >
      {hasBaseline && rows(base, baseText, 'del')}
      {rows(sugg, suggText, 'add')}
    </div>
  );
}

/** Body of a fenced code block, syntax-highlighted via the shared
 * @pierre/diffs highlighter so the colors + theme bg match the
 * Files-tab CodeView. Falls back to a plain `<pre><code>` while the
 * highlighter is loading the grammar — or permanently when the
 * fence doesn't declare a language (the lib can't infer it from
 * comment context).
 *
 * Synthetic file name `code.<lang>` is what the lib's
 * `getFiletypeFromFileName` expects: it maps extensions to the
 * Shiki-supported language set, so passing `'code.tsx'` resolves to
 * TSX. When `lang` is empty (bare ```\n…), we feed `code.txt` which
 * resolves to plain text — Shiki returns one untokenised line per
 * source line, indistinguishable from the fallback render. */
function HighlightedCode({
  lang,
  className,
  codeSize,
  children,
}: {
  lang: string;
  className: string | undefined;
  codeSize: string;
  children: ReactNode;
}) {
  const text = nodeText(children).replace(/\n$/, '');
  const filePath = fenceLangFileName(lang);
  const { lines: tokenLines, themeFg, themeBg } = useDiffSnippetHighlight(
    text,
    filePath,
  );
  return (
    <pre
      data-pyor-code-block
      className={`m-0 overflow-auto px-3 py-2 font-mono ${codeSize}`}
      style={{
        backgroundColor: themeBg ?? undefined,
        color: themeFg ?? undefined,
      }}
    >
      <code className={className}>
        {tokenLines && tokenLines.length > 0 ? (
          tokenLines.map((line, i) => (
            <span key={i}>
              {line.tokens.map((tok, j) => (
                <span
                  key={j}
                  style={tok.color ? { color: tok.color } : undefined}
                >
                  {tok.content}
                </span>
              ))}
              {/* Re-emit the explicit newline between lines so the
               * <pre> preserves the original line breaks. The last
               * line doesn't get one (matches the trailing-newline
               * strip on `text` above). */}
              {i < tokenLines.length - 1 && '\n'}
            </span>
          ))
        ) : (
          children
        )}
      </code>
    </pre>
  );
}

/** Recursively flatten React children into a plain string. The Markdown
 * code-block handler usually receives a single string child, but
 * remark-gfm + rehype-raw can occasionally hand us nested elements
 * (e.g. inline highlights inserted by other rehype plugins). Walking
 * the tree keeps us safe against that without committing to a
 * specific upstream shape. */
function nodeText(n: ReactNode): string {
  if (n == null || typeof n === 'boolean') return '';
  if (typeof n === 'string') return n;
  if (typeof n === 'number') return String(n);
  if (Array.isArray(n)) return n.map(nodeText).join('');
  if (isValidElement(n)) {
    const props = n.props as { children?: ReactNode };
    return nodeText(props.children);
  }
  return '';
}
