// OpenAI provider adapter — `openai` SDK, run client-side with
// dangerouslyAllowBrowser (the user's own key). Structured output via
// response_format json_schema (strict). No token-count endpoint, so the
// pre-run figure is an estimate (chars/4) and the UI always renders it as "~".

import OpenAI from 'openai';
import { AiError } from './types';
import type {
  CompleteArgs,
  CompleteResult,
  CuratedModel,
  ProviderAdapter,
} from './types';
import { DEFAULT_MODEL, FALLBACK_MODELS } from './models';

function mapError(err: unknown): AiError {
  if (err instanceof OpenAI.APIError) {
    const retryAfter = Number((err.headers as Record<string, string>)?.['retry-after']) || undefined;
    if (err.status === 401 || err.status === 403) {
      return new AiError('invalid-key', 'The OpenAI key was rejected.');
    }
    // `insufficient_quota` is a billing/quota-exhaustion error that OpenAI
    // returns with a 429 status — distinct from a transient rate limit.
    // Retrying won't help; the user must add credit. Classify as billing.
    if (err.code === 'insufficient_quota' || err.type === 'insufficient_quota') {
      return new AiError('billing', 'Your OpenAI account is out of quota or credit.');
    }
    if (err.status === 429) {
      return new AiError('rate-limited', 'OpenAI is rate-limiting requests.', retryAfter);
    }
    if (err.status === 529 || (err.status ?? 0) >= 500) {
      return new AiError('overloaded', 'OpenAI is overloaded. Try again shortly.');
    }
    return new AiError('unknown', err.message);
  }
  if (err instanceof OpenAI.APIConnectionError) {
    return new AiError('network', "Couldn't reach OpenAI.");
  }
  return new AiError('unknown', err instanceof Error ? err.message : 'Unknown error');
}

/** Some OpenAI-compatible endpoints (local models, older Groq models) reject
 * the strict `json_schema` response_format with a 400. Detect that so we can
 * retry in plain json_object mode instead of failing the run. */
function isSchemaUnsupported(err: unknown): boolean {
  return (
    err instanceof OpenAI.APIError &&
    err.status === 400 &&
    /response_format|json_schema|schema|not supported|unsupported|invalid/i.test(
      err.message ?? '',
    )
  );
}

/** Tolerant JSON parse — json_object mode is usually clean, but some
 * compatible endpoints wrap the object in ```json fences. */
function parseLooseJson<T>(raw: string): T {
  let s = raw.trim();
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) s = fence[1].trim();
  try {
    return JSON.parse(s) as T;
  } catch {
    throw new AiError('unknown', 'The model returned malformed JSON.');
  }
}

export function makeOpenAIAdapter(
  key: string,
  model?: string,
  baseUrl?: string,
): ProviderAdapter {
  // baseUrl !== '' → an OpenAI-compatible endpoint (Groq, Gemini, Ollama, …).
  // Such endpoints use arbitrary model ids and varying structured-output
  // support, so the curation + json_schema paths adapt below.
  const custom = !!baseUrl;
  const client = new OpenAI({
    apiKey: key,
    baseURL: baseUrl || undefined,
    dangerouslyAllowBrowser: true,
  });
  const resolvedModel = model || DEFAULT_MODEL.openai;

  return {
    provider: 'openai',
    defaultModel: resolvedModel,

    async testKey() {
      try {
        await client.models.list();
      } catch (err) {
        throw mapError(err);
      }
    },

    async listModels(): Promise<CuratedModel[]> {
      try {
        const res = await client.models.list();
        // Keep chat-capable text models; drop embeddings/audio/image/etc. and
        // the non-chat `-instruct` line. Sort NEWEST-first by the `created`
        // timestamp (not alphabetically — that surfaced the oldest gpt-3.5
        // models and hid current ones).
        const EXCLUDE =
          /(instruct|embedding|audio|realtime|transcribe|tts|whisper|image|dall-e|moderation|search|vision-preview|guard|computer-use|codex|davinci|babbage)/;
        // On a custom endpoint the ids are arbitrary (llama-*, gemini-*, …),
        // so drop the gpt-only filter and just hide obvious non-chat models.
        const models = res.data
          .filter((m) =>
            custom
              ? !EXCLUDE.test(m.id)
              : /^(gpt-|o\d|chatgpt-)/.test(m.id) && !EXCLUDE.test(m.id),
          )
          .sort((a, b) => (b.created ?? 0) - (a.created ?? 0));
        if (models.length === 0) {
          return custom ? res.data.map((m) => ({ id: m.id, label: m.id })) : FALLBACK_MODELS.openai;
        }
        return models.slice(0, 20).map((m) => ({ id: m.id, label: m.id }));
      } catch {
        return custom ? [] : FALLBACK_MODELS.openai;
      }
    },

    async complete<T = unknown>(args: CompleteArgs): Promise<CompleteResult<T>> {
      // Context first (helps OpenAI's automatic prefix caching), then the small
      // feature instruction. The closing user turn is replaced in the fallback.
      const baseMessages = [
        { role: 'system' as const, content: args.contextBlock },
        { role: 'system' as const, content: args.instruction },
      ];
      try {
        let res;
        try {
          res = await client.chat.completions.create(
            {
              model: resolvedModel,
              messages: [
                ...baseMessages,
                { role: 'user', content: 'Produce the result as JSON matching the schema.' },
              ],
              response_format: {
                type: 'json_schema',
                json_schema: { name: args.schemaName, schema: args.schema, strict: true },
              },
            },
            { signal: args.signal },
          );
        } catch (err) {
          // Endpoint doesn't support strict json_schema → retry in plain
          // json_object mode, inlining the schema so the model knows the shape.
          if (!isSchemaUnsupported(err)) throw err;
          res = await client.chat.completions.create(
            {
              model: resolvedModel,
              messages: [
                ...baseMessages,
                {
                  role: 'user',
                  content: `Produce ONLY a JSON object matching this JSON Schema — no prose, no markdown fences:\n${JSON.stringify(args.schema)}`,
                },
              ],
              response_format: { type: 'json_object' },
            },
            { signal: args.signal },
          );
        }
        const raw = res.choices[0]?.message?.content ?? '';
        return {
          data: parseLooseJson<T>(raw),
          model: res.model,
          usage: {
            inputTokens: res.usage?.prompt_tokens ?? 0,
            outputTokens: res.usage?.completion_tokens ?? 0,
          },
        };
      } catch (err) {
        if (err instanceof AiError) throw err;
        throw mapError(err);
      }
    },

    async countInputTokens(contextBlock: string, instruction: string) {
      // OpenAI has no count endpoint — estimate only.
      return {
        tokens: Math.ceil((contextBlock.length + instruction.length) / 4),
        exact: false,
      };
    },
  };
}
