import { useEffect } from 'react';

type Entry = { url: string; refs: number; revokeTimer: number | null };
const entries = new WeakMap<Blob, Entry>();

function entryFor(blob: Blob): Entry {
  let e = entries.get(blob);
  if (!e) {
    e = { url: URL.createObjectURL(blob), refs: 0, revokeTimer: null };
    entries.set(blob, e);
  }
  return e;
}

/**
 * A stable object URL for `blob`, shared across every mount of the same
 * (reference-stable, React-Query-cached) Blob. Unlike `URL.createObjectURL`
 * in a per-component `useMemo`, a remount — Virtuoso scroll-eviction, a
 * <Collapse> open-flip, a tab round-trip — reuses the existing URL instead
 * of minting a fresh one, so the browser never re-loads the `blob:` URL.
 *
 * Revocation is deferred + ref-counted: the URL is freed ~30s after the last
 * consumer unmounts, so churny remounts within that window reuse it. This
 * matters because an un-revoked object URL pins its Blob in memory, so we
 * must still revoke — just not on every unmount.
 */
export function useObjectUrl(blob: Blob | null | undefined): string | null {
  // Resolve synchronously so a warm cache paints on the first frame (no
  // placeholder flash on remount). createObjectURL is idempotent here — the
  // WeakMap returns the same URL for a given Blob.
  const url = blob ? entryFor(blob).url : null;

  useEffect(() => {
    if (!blob) return;
    const e = entryFor(blob);
    e.refs += 1;
    if (e.revokeTimer != null) {
      clearTimeout(e.revokeTimer);
      e.revokeTimer = null;
    }
    return () => {
      e.refs -= 1;
      if (e.refs <= 0 && e.revokeTimer == null) {
        e.revokeTimer = window.setTimeout(() => {
          URL.revokeObjectURL(e.url);
          entries.delete(blob);
        }, 30_000);
      }
    };
  }, [blob]);

  return url;
}
