// Shared rail derivations — used by BOTH the @pierre/trees rail
// (PierreFileTree) and the bespoke AI-grouped rail (AiGroupedRail), so the
// comment-count + folder viewed-rollup logic lives in one place.

import type { ThreadIndex } from '@/github/threads';

/** Per-file comment count for the rail badge. Local counts win; otherwise
 * derived from GitHub threads EXCLUDING outdated ones (they don't render in
 * the diff pane, so counting them gave clean files a phantom badge). */
export function commentCountFor(
  filename: string,
  commentCountByPath?: ReadonlyMap<string, number>,
  threadIndex?: ThreadIndex,
): number {
  if (commentCountByPath) return commentCountByPath.get(filename) ?? 0;
  return (threadIndex?.byPath.get(filename) ?? [])
    .filter((t) => !t.outdated)
    .reduce((sum, t) => sum + t.comments.length, 0);
}

export type FolderViewedState = 'none' | 'partial' | 'full';

/** Tri-state rolled-up viewed state for a folder's member files. */
export function folderViewedState(
  members: readonly string[],
  viewedSet?: ReadonlySet<string>,
): FolderViewedState {
  const total = members.length;
  if (total === 0) return 'none';
  const viewed = members.filter((p) => viewedSet?.has(p)).length;
  return viewed === 0 ? 'none' : viewed === total ? 'full' : 'partial';
}
