// Per-PR review arrangement, persisted to localStorage. Mirrors
// collapseStore / conversationFocusStore: local-only, never synced to
// GitHub (there's no remote counterpart — it's a private review aid).
//
//   pyor:arrangement:pr:{owner}/{repo}/{number}
//     → { dimension }
//
// useSyncExternalStore-friendly: snapshot() returns a stable reference
// that only changes identity when the arrangement actually changes.

import {
  prReviewId,
  storageKey,
  type ReviewId,
} from '../../../review/reviewId';
import {
  EMPTY_ARRANGEMENT,
  GROUPING_DIMENSIONS,
  type Arrangement,
} from './types';

function read(id: ReviewId): Arrangement {
  try {
    const raw = localStorage.getItem(storageKey('arrangement', id));
    if (!raw) return EMPTY_ARRANGEMENT;
    const parsed = JSON.parse(raw) as Partial<Arrangement>;
    // Sanitize legacy/removed dimensions (e.g. a persisted 'generated') → none.
    const dimension =
      parsed.dimension && GROUPING_DIMENSIONS.includes(parsed.dimension)
        ? parsed.dimension
        : 'none';
    return { dimension };
  } catch {
    return EMPTY_ARRANGEMENT;
  }
}

function write(id: ReviewId, value: Arrangement): void {
  try {
    localStorage.setItem(storageKey('arrangement', id), JSON.stringify(value));
  } catch {
    // ignore — same private-mode degradation as the other stores
  }
}

export interface ArrangementStore {
  snapshot(): Arrangement;
  set(next: Arrangement): void;
  subscribe(listener: () => void): () => void;
}

export function makeArrangementStore(
  owner: string,
  repo: string,
  number: number,
): ArrangementStore {
  const id = prReviewId(owner, repo, number);
  let current = read(id);
  const listeners = new Set<() => void>();
  return {
    snapshot: () => current,
    set(next) {
      if (next === current) return;
      current = next;
      write(id, next);
      listeners.forEach((l) => l());
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}
