// agentPrompt — builds the "Copy for agent" clipboard payload.
//
// The feature lets a reviewer take one inline review comment and paste
// it straight into an AI coding agent, so the agent can address *that
// one comment in isolation, but with full context*. The payload bundles
// three things: the file + line the comment is anchored to, the exact
// code line being commented on, and the reviewer's comment as plain
// text.
//
// Output shape (refined from the original handoff per reviewer feedback
// 2026-06-01 — no boilerplate intro, no "Reviewer comment — @author"
// label, and the body kept as raw Markdown so blockquotes and code
// fences survive):
//
//   File: src/diff/VirtualHunk.tsx  (line 20)
//
//   Line commented on:
//   ```
//   const totalH = hunk.lines.length * lineHeight;
//   ```
//
//   > a quoted line stays a blockquote
//
//   the rest of the comment, with ```suggestion fences intact
//
// Rules:
//   • The `File:` line is present only when a file is known; the
//     `(line N)` suffix only when a line number exists.
//   • The fenced "Line commented on" block is omitted entirely when
//     there is no anchored code.
//   • `bodyText` is the comment's RAW Markdown source — NOT the rendered
//     innerText — so `>` blockquotes and ```suggestion / ``` code fences
//     come through verbatim (the rendered DOM drops those markers). Falls
//     back to `(no text)` when empty.
//   • For a non-anchored comment (no file, no code) the prompt is just
//     the body.

export interface AgentPromptInput {
  /** File path the comment is anchored to. Omit for non-anchored
   * comments (top-level conversation comments, PR description). */
  file?: string | null;
  /** End line of the anchored range (or the single commented line).
   * Drives the `(line N)` / `(lines A–B)` suffix. */
  line?: number | null;
  /** Start line when the comment spans a multi-line range. Equal to
   * `line` (or null) for a single-line comment. */
  startLine?: number | null;
  /** The exact source line(s) being commented on — multiple lines joined
   * by `\n` for a range. When absent the fenced code block is dropped. */
  code?: string | null;
  /** Raw Markdown source of the comment body. */
  bodyText?: string | null;
}

// Normalise a comment's anchor to a [lo, hi] line span (lo === hi for a
// single line; both null when unanchored). `isRange` flags a multi-line span.
function anchorSpan(
  line: number | null | undefined,
  startLine: number | null | undefined,
): { lo: number | null; hi: number | null; isRange: boolean } {
  const lo =
    startLine != null && line != null
      ? Math.min(startLine, line)
      : (line ?? startLine ?? null);
  const hi =
    startLine != null && line != null
      ? Math.max(startLine, line)
      : (line ?? startLine ?? null);
  return { lo, hi, isRange: lo != null && hi != null && lo !== hi };
}

// "  (lines A–B)" / "  (line N)" / "" for the File: header.
function lineSuffix(
  lo: number | null,
  hi: number | null,
  isRange: boolean,
): string {
  if (isRange) return `  (lines ${lo}–${hi})`;
  return hi != null ? `  (line ${hi})` : '';
}

export function buildAgentPrompt({
  file,
  line,
  startLine,
  code,
  bodyText,
}: AgentPromptInput): string {
  const out: string[] = [];
  const { lo, hi, isRange } = anchorSpan(line, startLine);
  if (file) {
    out.push(`File: ${file}${lineSuffix(lo, hi, isRange)}`);
  }
  if (code) {
    if (out.length) out.push('');
    out.push(isRange ? 'Lines commented on:' : 'Line commented on:');
    out.push('```');
    out.push(String(code).replace(/\n+$/, ''));
    out.push('```');
  }
  if (out.length) out.push('');
  out.push((bodyText || '').trim() || '(no text)');
  return out.join('\n');
}

/** The line-anchored review comment's `diff_hunk` is the small unified
 * diff GitHub returns around the comment. Its row numbers are counted
 * from the `@@ -a +c @@` header — matching the commit the comment was
 * made on (i.e. the `original_*` lines), NOT the live `line`. We walk the
 * hunk the same way DiffHunkSnippet's parser does and collect every row
 * whose line number on `side` falls within `[fromLine, toLine]`, joined
 * by `\n`. A single-line comment passes `fromLine === toLine` (or omits
 * `toLine`) and gets one line back. Returns null when the hunk is missing
 * or no row in the span can be located (→ the fenced block is then
 * omitted from the prompt).
 *
 * Note: the span is clipped to what the `diff_hunk` actually contains —
 * if GitHub truncated the hunk before the range start, the earliest lines
 * may be absent. Typical review hunks include the whole commented span. */
export function anchorCodeFromHunk(
  diffHunk: string | null | undefined,
  fromLine: number | null | undefined,
  toLine?: number | null | undefined,
  side: 'LEFT' | 'RIGHT' = 'RIGHT',
): string | null {
  if (!diffHunk || fromLine == null) return null;
  const end = toLine ?? fromLine;
  const lo = Math.min(fromLine, end);
  const hi = Math.max(fromLine, end);
  let leftCursor = 0;
  let rightCursor = 0;
  let inBody = false;
  const collected: string[] = [];
  diffHunk.split('\n').forEach((raw) => {
    const step = anchorHunkStep(raw, leftCursor, rightCursor, inBody, side, lo, hi);
    leftCursor = step.leftCursor;
    rightCursor = step.rightCursor;
    inBody = step.inBody;
    if (step.emit !== undefined) collected.push(step.emit);
  });
  return collected.length ? collected.join('\n') : null;
}

// Advance the left/right cursors for one diff-hunk line and decide whether it
// contributes to the anchored span on `side`. `inBody` tracks whether we're
// past the @@ header (which can be absent in a truncated hunk).
function anchorHunkStep(
  raw: string,
  leftCursor: number,
  rightCursor: number,
  inBody: boolean,
  side: 'LEFT' | 'RIGHT',
  lo: number,
  hi: number,
): { leftCursor: number; rightCursor: number; inBody: boolean; emit?: string } {
  if (!inBody) {
    const m = raw.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (m) {
      return {
        leftCursor: parseInt(m[1], 10),
        rightCursor: parseInt(m[2], 10),
        inBody: true,
      };
    }
    // No header — fall through and process this line as body.
  }
  if (raw.startsWith('\\')) {
    // "\ No newline at end of file" — carries no line number.
    return { leftCursor, rightCursor, inBody: true };
  }
  const inSpan = (n: number) => n >= lo && n <= hi;
  if (raw.startsWith('+')) {
    return {
      leftCursor,
      rightCursor: rightCursor + 1,
      inBody: true,
      emit: side === 'RIGHT' && inSpan(rightCursor) ? raw.slice(1) : undefined,
    };
  }
  if (raw.startsWith('-')) {
    return {
      leftCursor: leftCursor + 1,
      rightCursor,
      inBody: true,
      emit: side === 'LEFT' && inSpan(leftCursor) ? raw.slice(1) : undefined,
    };
  }
  const content = raw.startsWith(' ') ? raw.slice(1) : raw;
  const n = side === 'LEFT' ? leftCursor : rightCursor;
  return {
    leftCursor: leftCursor + 1,
    rightCursor: rightCursor + 1,
    inBody: true,
    emit: inSpan(n) ? content : undefined,
  };
}
