// One-time consent gate for the public `pyor-assets` attachment repo
// (ADR 0018 §4 trade-offs). The first time a user uploads an image to a
// GitHub-bound comment we must disclose that Pyor will create a PUBLIC
// repo on their account and that pasted images become world-readable.
//
// Backed by a zustand store (no React Context). A single
// <AssetsConsentHost/> mounted near the app root (App.tsx, beside
// ConfirmHost) renders the disclosure dialog so any composer can request
// consent imperatively without each call site rendering its own dialog.
// `requestConsent()` resolves true once the user accepts (persisted in
// localStorage), or immediately on subsequent uploads; it resolves false
// if they decline or dismiss.

import { create } from 'zustand';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';

const CONSENT_KEY = 'pyor:assets-consent';

function hasConsented(): boolean {
  try {
    return localStorage.getItem(CONSENT_KEY) === 'granted';
  } catch {
    return false;
  }
}

interface AssetsConsentStore {
  open: boolean;
  /** The pending requestConsent() resolver, settled by the dialog. */
  resolve: ((granted: boolean) => void) | null;
  /** Resolve true when the user may upload to the public assets repo.
   * Shows the disclosure dialog on first use; remembers the choice. */
  requestConsent: () => Promise<boolean>;
  /** Resolve the outstanding promise once, then close. Persists on grant. */
  settle: (granted: boolean) => void;
}

const useAssetsConsentStore = create<AssetsConsentStore>((set, get) => ({
  open: false,
  resolve: null,
  requestConsent: () => {
    if (hasConsented()) return Promise.resolve(true);
    return new Promise<boolean>((resolve) => {
      // If a previous prompt is still open (overlapping callers), settle
      // its promise false before taking over — otherwise that awaiter
      // would hang once its resolver is replaced.
      get().resolve?.(false);
      set({ open: true, resolve });
    });
  },
  settle: (granted) => {
    if (granted) {
      try {
        localStorage.setItem(CONSENT_KEY, 'granted');
      } catch {
        // private mode / disabled storage — proceed for this session only
      }
    }
    get().resolve?.(granted);
    set({ open: false, resolve: null });
  },
}));

interface AssetsConsentValue {
  /** Resolve true when the user may upload to the public assets repo.
   * Shows the disclosure dialog on first use; remembers the choice. */
  requestConsent: () => Promise<boolean>;
}

/** Returns the stable promise-based requestConsent action. */
export function useAssetsConsent(): AssetsConsentValue {
  const requestConsent = useAssetsConsentStore((s) => s.requestConsent);
  return { requestConsent };
}

/** Mounts the disclosure dialog. Render once at the app root. */
export function AssetsConsentHost() {
  const open = useAssetsConsentStore((s) => s.open);
  const settle = useAssetsConsentStore((s) => s.settle);
  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        // Closing the dialog any other way (Esc, overlay, X) declines.
        if (!next) settle(false);
      }}
    >
      <DialogContent className="sm:max-w-[460px]">
        <DialogHeader>
          <DialogTitle>Upload images to a public repo?</DialogTitle>
          <DialogDescription className="space-y-2 text-[13px] leading-relaxed">
            <span className="block">
              To attach images to GitHub comments, Pyor creates a public
              repository <code className="font-mono">pyor-assets</code> on
              your account and commits pasted images there.
            </span>
            <span className="block">
              Anyone with the image URL can view it — pasted screenshots
              will be <b>publicly readable</b>. This is what lets the image
              render for everyone on the pull request.
            </span>
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="ghost" size="sm" onClick={() => settle(false)}>
            Cancel
          </Button>
          <Button size="sm" onClick={() => settle(true)}>
            Create repo &amp; upload
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
