/** Active-lens refetch cadence. Matches the prior REST poll. */
const PULLS_POLL_MS = 60_000;

// The lens-list body of the Pull-requests screen's My PRs / Reviewing
// tabs. Rendered inside the shared PullsScreen shell (which owns the
// PyorWindow + tab bar); this component owns the lens query, filter row,
// and list, and publishes its chrome (subtitle / status / Refresh / tab
// count) up via usePullsChrome.
export function PullRequestsBody() {
  const navigate = useNavigate();
  // Open a PR via the typed router. `from: 'pulls'` records the origin
  // so the PR's back affordance + sidebar highlight resolve to Pulls.
  const onOpenPR = (pr: PRListItem) =>
    openPR(navigate, {
      owner: pr.owner,
      repo: pr.repoName,
      number: pr.num,
      from: 'pulls',
    });

  // Every filter / sort / search lives in the URL (the route's typed
  // Valibot search params), so the whole view is shareable + reload-
  // stable and the back button restores it. View-state defaults (tab /
  // status / date / sort) are always present in the URL; the narrowing
  // filters (repo / author / label / reviewer / ci / q) serialise only
  // when applied. `patch` merges a partial change and re-cleans, using
  // replace history (a filter tweak isn't a back-button step).
  const search = useSearch({ from: '/pulls' });
  const patch = (next: Partial<PullsSearch>) =>
    void navigate({
      to: '/pulls',
      search: cleanSearch({ ...search, ...next }),
      replace: true,
    });

  const lens: Lens = search.tab === 'reviewing' ? 'inbox' : 'mine';

  const repoFilter = search.repo ?? null;
  const authorFilter = search.author ?? null;
  const labelFilter = search.label ?? null;
  const reviewerFilter = search.reviewer ?? null;
  const ciFilter: LensFilters['ci'] = search.ci ?? null;
  const statusFilter: StatusFilter = search.status;
  const dateRange: DateRangePreset = search.date;
  const sort: Sort = search.sort;
  const searchQuery = search.q ?? '';

  const setRepoFilter = (r: string | null) => patch({ repo: r ?? undefined });
  const setAuthorFilter = (a: string | null) =>
    patch({ author: a ?? undefined });
  const setLabelFilter = (l: string | null) => patch({ label: l ?? undefined });
  const setReviewerFilter = (r: string | null) =>
    patch({ reviewer: r ?? undefined });
  const setCIFilter = (c: LensFilters['ci']) => patch({ ci: c ?? undefined });
  const setStatusFilter = (s: StatusFilter) => patch({ status: s });
  const setSort = (s: Sort) => patch({ sort: s });

  // Per-org gate (ADR 0020) — hides PRs from blocked (installed, unseated) orgs.
  const { isOrgAccessible, blockedOrgLogins } = useOrgGate();
  // Sorted, stable list for the queryKey + `-org:` exclusions.
  const excludeOrgs = useMemo(
    () => [...blockedOrgLogins].sort(),
    [blockedOrgLogins],
  );

  // Server-side filters folded into the GraphQL search query. `since`
  // snaps to UTC midnight via DateRangeChip's helper so the queryKey
  // stays stable across same-day calls. Blocked orgs are excluded
  // server-side (`-org:`) so counts + pagination stay correct.
  const serverFilters: LensFilters = useMemo(
    () => ({
      status: statusFilter,
      since: presetToSinceISO(dateRange),
      reviewer: reviewerFilter,
      ci: ciFilter,
      excludeOrgs,
    }),
    [statusFilter, dateRange, reviewerFilter, ciFilter, excludeOrgs],
  );
  const filtersFp = filtersKey(serverFilters);

  // Active-lens cursor-paginated query. Inactive lens still gets a
  // cheap count-only fetch so its tab badge renders accurately.
  const queryClient = useQueryClient();
  const activeInfinite = useInfiniteQuery({
    queryKey: ['lens', lens, filtersFp],
    queryFn: ({ pageParam }) => fetchLensPage(lens, serverFilters, pageParam),
    initialPageParam: null as string | null,
    getNextPageParam: (last) => (last.hasNextPage ? last.endCursor : null),
    refetchInterval: PULLS_POLL_MS,
    // Don't poll while the tab is backgrounded. fetchLensPage is GraphQL
    // (search, ~6 points/page, can't 304), so without this an app left
    // open in a background tab keeps spending ~360 points/hour forever.
    // Polling resumes on refocus (and refetchOnWindowFocus catches up
    // any change missed while away).
    refetchIntervalInBackground: false,
    // Keep the previous list visible while a new (lens/filter) query
    // resolves. Without this, every Status / Date range / Author chip
    // change flashes the "Loading PRs…" skeleton even though we still
    // have a perfectly-good prior result on screen.
    placeholderData: (prev) => prev,
  });

  // 401 handling. The GraphQL endpoint returns a structured error;
  // the REST client wraps it as GitHubError(401) when the token is
  // missing / revoked. Rather than silently bouncing to /welcome, we
  // surface the dedicated auth-expired card (same as PR detail) so the
  // user sees *why* — its "Sign in again" button does the signOut +
  // navigate deliberately. A dead token 401s every query, so it takes
  // over the whole content area.
  const authExpired =
    activeInfinite.error instanceof GitHubError &&
    activeInfinite.error.status === 401;

  // Flatten paged data + headline counts. Blocked orgs (ADR 0020) are hidden
  // here — the gate removes rows whose owner is an installed org without a live
  // seat, so a blocked team's PRs never appear in any lens.
  const allItems: PRListItem[] = useMemo(() => {
    const pages = activeInfinite.data?.pages ?? [];
    return pages.flatMap((p) => p.items).filter((i) => isOrgAccessible(i.owner));
  }, [activeInfinite.data, isOrgAccessible]);
  const activeTotal = activeInfinite.data?.pages[0]?.total ?? 0;
  const pagesLoaded = activeInfinite.data?.pages.length ?? 0;

  // Debounced hover-prefetch — unchanged from the prior implementation.
  const hoverPrefetchTimer = useRef<number | null>(null);
  const prefetchPRDetail = (pr: PRListItem) => {
    if (hoverPrefetchTimer.current != null) {
      window.clearTimeout(hoverPrefetchTimer.current);
    }
    hoverPrefetchTimer.current = window.setTimeout(() => {
      hoverPrefetchTimer.current = null;
      const meta = prMetaOptions(pr.owner, pr.repoName, pr.num);
      // Chain the merge-base off meta: it needs base.sha + head.sha, which
      // only land once meta resolves. The merge-base is the SHA GitHub
      // diffs against, and it gates the (expensive) contents fetch on
      // arrival — warming it on hover removes that one REST round-trip
      // from the critical path so contents can start the moment the PR
      // mounts. Cheap ETag-cacheable compare call, SHA-keyed, so a
      // force-push between hover and open just re-resolves.
      void queryClient.prefetchQuery(meta).then(() => {
        const m = queryClient.getQueryData<GHPullRequest>(meta.queryKey);
        if (!m) return;
        void queryClient.prefetchQuery(
          prMergeBaseOptions(
            pr.owner,
            pr.repoName,
            pr.num,
            m.base.sha,
            m.head.sha,
          ),
        );
      });
      void queryClient.prefetchQuery(
        prFilesOptions(pr.owner, pr.repoName, pr.num),
      );
      void queryClient.prefetchQuery(
        prCommentsOptions(pr.owner, pr.repoName, pr.num),
      );
      // NB: deliberately NOT prefetching prThreadsOptions here. It's the
      // only GraphQL query in this set (~21 points each, never 304s), and
      // hovering a list of PRs would spend points per row — browsing one
      // screenful could eat a fifth of the hourly GraphQL budget. The
      // resolved-thread state isn't needed to render the initial PR view;
      // PRDetailScreen/DescriptionTab fetch it via useQuery on mount, so
      // it loads the moment the PR actually opens. The three REST
      // prefetches above (ETag-cacheable) are what deliver the instant-open
      // feel; threads cost is paid once, on real open, not per hover.
      void import('./PRDetailScreen');
    }, 200);
  };
  const cancelPrefetchTimer = () => {
    if (hoverPrefetchTimer.current != null) {
      window.clearTimeout(hoverPrefetchTimer.current);
      hoverPrefetchTimer.current = null;
    }
  };

  // Derived author / label / repo / reviewer options for the dropdown
  // chips. Computed from already-fetched rows; reviewer comes from PR
  // detail meta cached during hover/click — for v1 we expose the rows'
  // current user logins as candidate reviewers (best-effort; covers
  // the common case of filtering to "PRs Bob has been asked to look
  // at" once Bob's PRs are visible).
  const repoCounts = useMemo(
    () =>
      countByKey(allItems, (pr) => pr.repo).sort(
        (a, b) => b[1] - a[1] || a[0].localeCompare(b[0]),
      ),
    [allItems],
  );
  const authorCounts = useMemo(
    () =>
      countByKey(allItems, (pr) => pr.author).sort(
        (a, b) => b[1] - a[1] || a[0].localeCompare(b[0]),
      ),
    [allItems],
  );
  const labelCounts = useMemo(() => {
    const counts = new Map<string, number>();
    for (const pr of allItems) {
      for (const l of pr.labels) {
        counts.set(l.name, (counts.get(l.name) ?? 0) + 1);
      }
    }
    return Array.from(counts.entries()).sort(
      (a, b) => b[1] - a[1] || a[0].localeCompare(b[0]),
    );
  }, [allItems]);

  // Client-side filters: repo / author / label / text search. These
  // narrow the already-fetched rows without re-querying. Reviewer + CI
  // + DateRange are server-side (see serverFilters above).
  const filteredItems = useMemo(() => {
    let items = allItems;
    if (repoFilter) items = items.filter((pr) => pr.repo === repoFilter);
    if (authorFilter) items = items.filter((pr) => pr.author === authorFilter);
    if (labelFilter) {
      items = items.filter((pr) => pr.labels.some((l) => l.name === labelFilter));
    }
    const q = searchQuery.trim().toLowerCase();
    if (q) {
      items = items.filter((pr) => {
        const hay = `${pr.title} ${pr.repo} ${pr.author} #${pr.num}`.toLowerCase();
        return hay.includes(q);
      });
    }
    return sortItems(items, sort);
  }, [allItems, repoFilter, authorFilter, labelFilter, sort, searchQuery]);

  const clientFilterActive = Boolean(
    repoFilter || authorFilter || labelFilter || searchQuery.trim(),
  );
  // The default 30d date range + 'open' status are "always on" — don't
  // surface either as a user-applied filter (the chips themselves show
  // the current preset). Only non-default values count toward the
  // Clear-all / "filtered empty state" decision.
  const serverFilterActive = Boolean(
    serverFilters.reviewer ||
      serverFilters.ci ||
      dateRange !== '30d' ||
      statusFilter !== 'open',
  );
  const anyFilter = clientFilterActive || serverFilterActive;

  const tabLabel = lens === 'mine' ? 'Authored by you' : 'In your review queue';
  const isLoading = activeInfinite.isLoading;
  // Subtitle matches the design: just the tab role. Per-filter counts
  // live in the chip-row suffix on the right (`/search/issues · X of ~Y`).
  const subtitle = isLoading
    ? `${tabLabel} · loading…`
    : activeInfinite.error
      ? `${tabLabel} · load failed`
      : tabLabel;

  const fetchedAt = activeInfinite.dataUpdatedAt
    ? new Date(activeInfinite.dataUpdatedAt)
    : null;

  // Reset every narrowing filter + the status/date view defaults in one
  // navigation. Tab + sort are preserved (clearing filters shouldn't
  // jump you to another queue or reorder the list).
  const onClearAll = () =>
    patch({
      status: 'open',
      date: '30d',
      repo: undefined,
      author: undefined,
      label: undefined,
      reviewer: undefined,
      ci: undefined,
      q: undefined,
    });

  // Infinite-footer state machine.
  const footerState: 'loading' | 'idle' | 'end' = activeInfinite.isFetchingNextPage
    ? 'loading'
    : activeInfinite.hasNextPage
      ? 'idle'
      : 'end';

  // Publish chrome to the shell (titlebar / status / Refresh).
  usePullsChrome(
    {
      subtitle,
      toolbar: <PullsToolbar onRefresh={() => activeInfinite.refetch()} />,
      status: <PullsStatus fetchedAt={fetchedAt} />,
    },
    [subtitle, fetchedAt?.getTime() ?? 0],
  );

  if (authExpired) {
    return (
      <PRErrorPane
        error={activeInfinite.error}
        endpoint="/search/issues"
        layout="full"
        onRetry={() => void activeInfinite.refetch()}
      />
    );
  }

  return (
    <>
      <PullsFilterChips
        lens={lens}
        sort={sort}
        setSort={setSort}
        statusFilter={statusFilter}
        setStatusFilter={setStatusFilter}
        repoCounts={repoCounts}
        repoFilter={repoFilter}
        setRepoFilter={setRepoFilter}
        authorCounts={authorCounts}
        authorFilter={authorFilter}
        setAuthorFilter={setAuthorFilter}
        reviewerFilter={reviewerFilter}
        setReviewerFilter={setReviewerFilter}
        ciFilter={ciFilter}
        setCIFilter={setCIFilter}
        labelCounts={labelCounts}
        labelFilter={labelFilter}
        setLabelFilter={setLabelFilter}
        anyFilter={anyFilter}
        onClearAll={onClearAll}
        shown={filteredItems.length}
        total={activeTotal}
      />
      <PullsBody
        loading={isLoading}
        error={
          activeInfinite.error instanceof Error
            ? activeInfinite.error.message
            : null
        }
        items={filteredItems}
        lens={lens}
        clientFilterActive={clientFilterActive}
        anyFilter={anyFilter}
        blockedOrgCount={blockedOrgLogins.size}
        onOpenPR={onOpenPR}
        onHoverPR={prefetchPRDetail}
        onLeavePR={cancelPrefetchTimer}
        onRetry={() => void activeInfinite.refetch()}
        onClearFilters={onClearAll}
        footerState={footerState}
        shown={filteredItems.length}
        pagesLoaded={pagesLoaded}
        estimatedTotal={activeTotal}
        onLoadMore={() => void activeInfinite.fetchNextPage()}
        refreshing={activeInfinite.isPlaceholderData}
      />
    </>
  );
}

// ── Toolbar ────────────────────────────────────────────────────
// Search + DateRangeChip migrated onto the tabs bar (PullsTabsBar);
// Sort moved down to the filter-chip row, so the title-bar toolbar
// keeps only Refresh now.

function PullsToolbar({ onRefresh }: { onRefresh: () => Promise<unknown> }) {
  return (
    <div className="flex items-center gap-2">
      <RefreshButton onRefresh={onRefresh} />
    </div>
  );
}

function PullsStatus({ fetchedAt }: { fetchedAt: Date | null }) {
  // Tick once a second so the "Ns ago" stays accurate without
  // re-rendering the parent on every refresh.
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((n) => n + 1), 1000);
    return () => clearInterval(id);
  }, []);
  const queryClient = useQueryClient();
  // Cache stats — distinct PRs + a real byte-size estimate of the
  // cached payloads. Subscribes to the query cache so we recompute on
  // mutation rather than on every parent render; throttled to once
  // per 2s so a flurry of cache writes during streaming doesn't
  // hammer the stringifier. JSON.stringify gives byte accuracy at
  // the cost of one O(n) walk per recompute — fine at the throttle
  // cadence, far better than the previous 4 KB-per-entry placeholder.
  const cacheStats = useCacheStats(queryClient);
  const ago = fetchedAt
    ? Math.max(0, Math.round((Date.now() - fetchedAt.getTime()) / 1000))
    : null;
  return (
    <>
      <span className="inline-flex items-center gap-1.5">
        <span
          className={cn(
            'size-1.5 rounded-full',
            fetchedAt ? 'bg-pyor-pass' : 'bg-muted-foreground/50',
          )}
        />
        Live polling · {Math.round(PULLS_POLL_MS / 1000)}s
      </span>
      <span className="mx-3 text-border">│</span>
      <span>
        {ago === null
          ? 'first fetch pending…'
          : ago < 5
            ? 'just polled'
            : ago < 60
              ? `polled ${ago}s ago`
              : `polled ${Math.round(ago / 60)}m ago`}
      </span>
      <span className="flex-1" />
      <span className="text-muted-foreground/80">
        <span className="tabular-nums">{cacheStats.prs}</span> PRs cached ·{' '}
        <span className="tabular-nums">{formatBytes(cacheStats.bytes)}</span>{' '}
        · GraphQL search · 1000-row cap
      </span>
    </>
  );
}

/** Subscribe to the TanStack QueryClient's cache + walk every entry
 * each time the cache mutates. We measure with JSON.stringify(data)
 * — one O(payload) pass per recompute, accurate to the byte. To
 * keep streaming PRs (where wave-2 content writes can fire dozens of
 * times in a second) from monopolising the main thread, the cache
 * subscription is debounced through `requestAnimationFrame` so we
 * collapse adjacent mutations into one recompute per paint.
 *
 * `bytes` here is "what's in memory according to the JSON shape" —
 * the actual heap retained per query is bigger (object headers,
 * Map/Set wrappers, callback closures) but JSON length is a
 * reasonable user-facing proxy for "how much PR data am I carrying
 * around." */
function useCacheStats(qc: ReturnType<typeof useQueryClient>): {
  prs: number;
  bytes: number;
} {
  const [stats, setStats] = useState<{ prs: number; bytes: number }>({
    prs: 0,
    bytes: 0,
  });
  useEffect(() => {
    let rafId = 0;
    let cancelled = false;
    const recompute = () => {
      if (cancelled) return;
      const all = qc.getQueryCache().getAll();
      const prKeys = new Set<string>();
      let bytes = 0;
      for (const q of all) {
        const k = q.queryKey as unknown[];
        if (Array.isArray(k) && k[0] === 'pr' && k.length >= 4) {
          prKeys.add(`${k[1]}/${k[2]}#${k[3]}`);
        }
        const data = q.state.data;
        if (data === undefined) continue;
        // JSON.stringify throws on circular refs (shouldn't exist in
        // serializable query data, but be defensive — drop the entry
        // rather than crashing the status bar).
        try {
          bytes += JSON.stringify(data).length;
        } catch {
          /* skip non-serialisable entries */
        }
      }
      setStats({ prs: prKeys.size, bytes });
    };
    const schedule = () => {
      if (rafId) return;
      rafId = requestAnimationFrame(() => {
        rafId = 0;
        recompute();
      });
    };
    schedule();
    const unsub = qc.getQueryCache().subscribe(schedule);
    return () => {
      cancelled = true;
      if (rafId) cancelAnimationFrame(rafId);
      unsub();
    };
  }, [qc]);
  return stats;
}

/** Format a byte count for the status-bar — KB up to 1 MB, MB
 * thereafter. Round to one decimal on MB so the value flickers less
 * during streaming writes. */
function formatBytes(b: number): string {
  if (b < 1024) return `${b} B`;
  if (b < 1024 * 1024) return `${Math.round(b / 1024)} KB`;
  return `${(Math.round((b / 1024 / 1024) * 10) / 10).toFixed(1)} MB`;
}

// ── Filter chip row ────────────────────────────────────────────

function PullsFilterChips({
  lens,
  sort,
  setSort,
  statusFilter,
  setStatusFilter,
  repoCounts,
  repoFilter,
  setRepoFilter,
  authorCounts,
  authorFilter,
  setAuthorFilter,
  reviewerFilter,
  setReviewerFilter,
  ciFilter,
  setCIFilter,
  labelCounts,
  labelFilter,
  setLabelFilter,
  anyFilter,
  onClearAll,
  shown,
  total,
}: {
  lens: Lens;
  sort: Sort;
  setSort: (s: Sort) => void;
  statusFilter: StatusFilter;
  setStatusFilter: (s: StatusFilter) => void;
  repoCounts: [string, number][];
  repoFilter: string | null;
  setRepoFilter: (r: string | null) => void;
  authorCounts: [string, number][];
  authorFilter: string | null;
  setAuthorFilter: (a: string | null) => void;
  reviewerFilter: string | null;
  setReviewerFilter: (r: string | null) => void;
  ciFilter: LensFilters['ci'];
  setCIFilter: (c: LensFilters['ci']) => void;
  labelCounts: [string, number][];
  labelFilter: string | null;
  setLabelFilter: (l: string | null) => void;
  anyFilter: boolean;
  onClearAll: () => void;
  shown: number;
  total: number;
}) {
  const values: Record<string, string> = {
    status: statusFilter,
    repo: repoFilter ?? 'any',
    author: authorFilter ?? 'any',
    reviewer: reviewerFilter ?? 'any',
    ci: ciFilter ?? 'any',
    label: labelFilter ?? 'any',
  };
  const ANY: FilterOption = { value: 'any', label: 'Any' };
  const options: Record<string, FilterOption[]> = {
    status: [
      { value: 'open', label: 'Open' },
      { value: 'draft', label: 'Draft' },
      { value: 'closed', label: 'Closed' },
      { value: 'merged', label: 'Merged' },
      { value: 'all', label: 'All' },
    ],
    repo: [ANY, ...repoCounts.map(([r, c]) => ({ value: r, label: r, count: c }))],
    author: [ANY, ...authorCounts.map(([a, c]) => ({ value: a, label: a, count: c }))],
    // Reviewer candidates are best-effort: the people active in your queue.
    reviewer: [ANY, ...authorCounts.map(([a]) => ({ value: a, label: a }))],
    ci: [
      ANY,
      { value: 'success', label: 'Passing' },
      { value: 'failure', label: 'Failing' },
      { value: 'pending', label: 'Pending' },
    ],
    label: [ANY, ...labelCounts.map(([l, c]) => ({ value: l, label: l, count: c }))],
  };
  const onChange = (key: string, value: string) => {
    const off = value === 'any' ? null : value;
    if (key === 'status') setStatusFilter(value as StatusFilter);
    else if (key === 'repo') setRepoFilter(off);
    else if (key === 'author') setAuthorFilter(off);
    else if (key === 'reviewer') setReviewerFilter(off);
    else if (key === 'ci') setCIFilter(off as LensFilters['ci']);
    else if (key === 'label') setLabelFilter(off);
  };
  const sortOptions: FilterOption[] = (Object.keys(SORT_LABELS) as Sort[]).map(
    (k) => ({ value: k, label: SORT_LABELS[k] }),
  );
  // My PRs are all authored by you, so an Author filter is meaningless there.
  const fields =
    lens === 'mine'
      ? PULLS_FILTER_FIELDS.filter((f) => f.key !== 'author')
      : PULLS_FILTER_FIELDS;

  return (
    <div className="flex shrink-0 items-center gap-2.5 border-b border-border bg-muted/30 px-5 py-2">
      <div className="ml-auto flex items-center gap-2.5">
        {anyFilter && (
          <button
            type="button"
            onClick={onClearAll}
            className="inline-flex items-center gap-1 text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground"
          >
            <XCircleIcon className="size-3" />
            Clear all
          </button>
        )}
        <span className="text-[11.5px] text-muted-foreground">
          <span className="tabular-nums font-medium text-foreground">{shown}</span>{' '}
          of ~{total}
        </span>
        <Separator orientation="vertical" className="h-6" />
        <FiltersButton
          fields={fields}
          values={values}
          options={options}
          defaults={PULLS_FILTER_DEFAULTS}
          onChange={onChange}
          onReset={onClearAll}
        />
        <SortButton
          options={sortOptions}
          value={sort}
          onChange={(v) => setSort(v as Sort)}
        />
      </div>
    </div>
  );
}

const PULLS_FILTER_FIELDS: FilterField[] = [
  { key: 'status', icon: CircleDotIcon, label: 'Status' },
  { key: 'repo', icon: FolderIcon, label: 'Repository' },
  { key: 'author', icon: UserIcon, label: 'Author' },
  { key: 'reviewer', icon: UsersIcon, label: 'Reviewer' },
  { key: 'ci', icon: CheckCircleIcon, label: 'CI status' },
  { key: 'label', icon: TagIcon, label: 'Label' },
];
// Status defaults to Open (not counted as an active filter).
const PULLS_FILTER_DEFAULTS: Record<string, string> = { status: 'open' };

// ── Sort ─────────────────────────────────────────────────────

type Sort = 'updated-desc' | 'created-desc' | 'created-asc' | 'comments-desc';

const SORT_LABELS: Record<Sort, string> = {
  'updated-desc': 'Recently updated',
  'created-desc': 'Newest',
  'created-asc': 'Oldest',
  'comments-desc': 'Most commented',
};

function sortItems(items: PRListItem[], sort: Sort): PRListItem[] {
  const out = [...items];
  switch (sort) {
    case 'updated-desc':
      return out.sort(
        (a, b) =>
          new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
      );
    case 'created-desc':
      return out.sort(
        (a, b) =>
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      );
    case 'created-asc':
      return out.sort(
        (a, b) =>
          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
      );
    case 'comments-desc':
      return out.sort((a, b) => b.comments - a.comments);
  }
}

function countByKey<T>(
  items: T[],
  keyFn: (item: T) => string,
): [string, number][] {
  const counts = new Map<string, number>();
  for (const it of items) {
    const k = keyFn(it);
    counts.set(k, (counts.get(k) ?? 0) + 1);
  }
  return Array.from(counts.entries());
}

// ── List body ─────────────────────────────────────────────────

function PullsBody({
  loading,
  error,
  items,
  lens,
  clientFilterActive,
  anyFilter,
  onOpenPR,
  onHoverPR,
  onLeavePR,
  onRetry,
  onClearFilters,
  footerState,
  shown,
  pagesLoaded,
  estimatedTotal,
  onLoadMore,
  refreshing,
  blockedOrgCount,
}: {
  loading: boolean;
  error: string | null;
  items: PRListItem[];
  lens: Lens;
  clientFilterActive: boolean;
  anyFilter: boolean;
  blockedOrgCount: number;
  onOpenPR?: (pr: PRListItem) => void;
  onHoverPR?: (pr: PRListItem) => void;
  onLeavePR?: () => void;
  onRetry: () => void;
  onClearFilters: () => void;
  footerState: 'loading' | 'idle' | 'end';
  shown: number;
  pagesLoaded: number;
  estimatedTotal: number;
  onLoadMore: () => void;
  /** A server-side filter/refetch is in flight while the prior list stays
   * visible — show a thin pulsing bar (matches the Team radar). */
  refreshing: boolean;
}) {
  if (loading && items.length === 0) {
    return (
      <ListMessage>
        <Loader2Icon className="size-4 animate-spin" /> Loading PRs…
      </ListMessage>
    );
  }
  if (error) {
    return (
      <EmptyState
        icon={XCircleIcon}
        iconClassName="text-destructive"
        title="Couldn't load PRs"
        body={error}
        action={
          <RefreshButton variant="default" onRefresh={onRetry} label="Retry" />
        }
      />
    );
  }
  if (items.length === 0) {
    // Everything you can see is gated (ADR 0020) — explain, don't show a bare
    // "no PRs". Only when unfiltered and there's actually a blocked org.
    if (!anyFilter && blockedOrgCount > 0) {
      return <GatedListEmptyState />;
    }
    // Filtered → "filtered" empty state with Clear-all CTA.
    if (anyFilter) {
      return (
        <EmptyState
          icon={SlidersHorizontalIcon}
          title="No PRs match these filters."
          body={
            clientFilterActive
              ? 'Clear them to see the full list, or adjust the chips above.'
              : 'Try a wider date range, or clear the server-side filters.'
          }
          action={
            <Button variant="outline" size="sm" onClick={onClearFilters}>
              Clear all filters
            </Button>
          }
        />
      );
    }
    // Per-lens empty copy — matches design shell-pulls-empty-mine /
    // shell-pulls-empty-reviewing.
    return lens === 'mine' ? (
      <EmptyState
        icon={GitPullRequestIcon}
        title="No open PRs you authored."
        body="Open one in your terminal and refresh — Pyor picks them up as soon as the API does."
        action={
          <RefreshButton variant="outline" onRefresh={onRetry} />
        }
        secondary={<InstallMoreOrgsLink />}
      />
    ) : (
      <EmptyState
        icon={EyeIcon}
        iconClassName="text-emerald-600"
        title="Nothing in your review queue."
        body="PRs you're a requested reviewer on, have commented on, or are subscribed to will show up here."
        action={
          <RefreshButton variant="outline" onRefresh={onRetry} />
        }
        secondary={<InstallMoreOrgsLink />}
      />
    );
  }
  // Flat virtualized list. Earlier revisions partitioned by `reviewerOf`
  // (direct / team / participating) and rendered "REQUESTED DIRECTLY" /
  // "OPEN PRS" group headers — but the headers carried no signal beyond
  // the row icon + the lens tab, so they were noise. Drop them and
  // let Virtuoso handle the 1000-row worst case cleanly.
  //
  // J/K keyboard nav across the visible rows. State here so the parent
  // doesn't have to thread it; the focused row scrolls into view via
  // Virtuoso's imperative `scrollIntoView` handle. Resets to 0 when
  // the list shrinks past the current cursor (e.g. user typed a
  // filter that hides the focused row).
  const virtuosoRef = useRef<VirtuosoHandle | null>(null);
  // -1 = nothing focused. Starting at 0 made the first row render
  // pre-selected (tinted bg + left accent bar) on every load even
  // though the user hadn't navigated. The first j/k press selects
  // row 0; until then no row is highlighted.
  const [focusedIndex, setFocusedIndex] = useState(-1);
  useEffect(() => {
    if (focusedIndex >= items.length) setFocusedIndex(-1);
  }, [items.length, focusedIndex]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // Don't hijack J/K/Enter while the user is typing — only act
      // when the keydown landed on the body (not an input, textarea,
      // or contenteditable). Standard nav-binding rule.
      const t = e.target as HTMLElement | null;
      if (t) {
        const tag = t.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
        if (t.isContentEditable) return;
      }
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (items.length === 0) return;
      const k = e.key;
      if (k === 'j' || k === 'J') {
        e.preventDefault();
        setFocusedIndex((i) => {
          const next = Math.min(items.length - 1, i + 1);
          virtuosoRef.current?.scrollIntoView({ index: next });
          return next;
        });
      } else if (k === 'k' || k === 'K') {
        e.preventDefault();
        setFocusedIndex((i) => {
          const next = Math.max(0, i - 1);
          virtuosoRef.current?.scrollIntoView({ index: next });
          return next;
        });
      } else if (k === 'Enter') {
        const pr = items[focusedIndex];
        if (pr && onOpenPR) {
          e.preventDefault();
          onOpenPR(pr);
        }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [items, focusedIndex, onOpenPR]);

  return (
    <>
      {/* Server-side filter/refetch in flight — the prior list stays put,
          so a thin pulsing bar signals it's updating. */}
      <FetchingBar active={refreshing} />
      <Virtuoso
        ref={virtuosoRef}
        className={cn(
          'flex-1 min-h-0 bg-card transition-opacity',
          refreshing && 'opacity-60',
        )}
        data={items}
      // Render up to a viewport's worth synchronously on first paint —
      // otherwise Virtuoso's useLayoutEffect mount leaves a single-frame
      // blank where the Footer is the only visible thing.
      initialItemCount={Math.min(items.length, 12)}
      overscan={400}
      endReached={() => {
        if (footerState === 'idle') onLoadMore();
      }}
      itemContent={(i, pr) =>
        // Virtuoso can transiently hand us an out-of-range (undefined)
        // item for a frame while the list shrinks — e.g. when a filter
        // narrows the rows. Guard so a render never dereferences it.
        pr ? (
          <PRRow
            pr={pr}
            selected={i === focusedIndex}
            linkProps={prLinkProps({
              owner: pr.owner,
              repo: pr.repoName,
              number: pr.num,
              from: 'pulls',
            })}
            onSelect={() => setFocusedIndex(i)}
            onHover={() => onHoverPR?.(pr)}
            onLeave={onLeavePR}
          />
        ) : null
      }
      components={{
        Footer: () => (
          <>
            <InfiniteFooter
              state={footerState}
              shown={shown}
              pagesLoaded={pagesLoaded}
              estimatedTotal={estimatedTotal}
              onLoadMore={onLoadMore}
              caption="Scroll to auto-load · GraphQL cursor pagination · 50 / page"
            />
            {/* A GitHub-App token only sees installed accounts, so PRs from
             * un-installed orgs never reach this list. Persistent nudge at
             * the tail covers the "some PRs, but missing ones" case the
             * empty state can't (the list isn't empty). */}
            <div className="flex justify-center pb-6 pt-1">
              <InstallMoreOrgsLink />
            </div>
          </>
        ),
      }}
      />
    </>
  );
}

function ListMessage({ children }: { children: ReactNode }) {
  return (
    <div className="flex flex-1 items-center justify-center bg-card p-10">
      <div className="flex max-w-[480px] items-start gap-3 text-[13px] text-foreground">
        {children}
      </div>
    </div>
  );
}

// ── PR row ─────────────────────────────────────────────────────
// PR is the row shape consumed by PRRow. It's identical to PRListItem
// from the lens layer; aliased here so any future row-only fields stay
// local to the screen.
type PR = PRListItem;

function PRRowAvatar({ name, url }: { name: string; url?: string }) {
  const initials = name
    .split(/[\s-]+/)
    .map((s) => s[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();
  return (
    <Avatar className="size-4">
      {url && (
        <img
          src={url}
          alt=""
          className="size-full rounded-full object-cover"
        />
      )}
      <AvatarFallback className="text-[8px] font-semibold">
        {initials || '·'}
      </AvatarFallback>
    </Avatar>
  );
}

function CheckSummary({
  pass,
  fail,
  pending,
}: {
  pass: number;
  fail: number;
  pending: number;
}) {
  return (
    <span className="inline-flex items-center gap-1.5 text-[12px] text-muted-foreground">
      {pass > 0 && (
        <span className="inline-flex items-center gap-0.5">
          <span className="inline-flex text-pyor-pass">
            <Icon name="check-circle" size={13} />
          </span>
          {pass}
        </span>
      )}
      {fail > 0 && (
        <span className="inline-flex items-center gap-0.5">
          <span className="inline-flex text-pyor-fail">
            <Icon name="x-circle" size={13} />
          </span>
          {fail}
        </span>
      )}
      {pending > 0 && (
        <span className="inline-flex items-center gap-0.5">
          <span className="inline-flex text-pyor-warn">
            <Icon name="dot-circle" size={13} />
          </span>
          {pending}
        </span>
      )}
    </span>
  );
}

function statusColorClass(status: PR['status'], draft: boolean): string {
  if (draft) return 'text-muted-foreground';
  switch (status) {
    case 'open':
      return 'text-pyor-pass';
    case 'merged':
      return 'text-purple-600 dark:text-purple-400';
    case 'closed':
      return 'text-pyor-fail';
    case 'draft':
      return 'text-muted-foreground';
  }
}

// Priority for truncating the reviewer stack: surface actioned
// verdicts (changes / approved) ahead of passive ones so a "changes
// requested" reviewer never hides behind pending placeholders.
const REVIEWER_STATE_RANK: Record<ReviewerStateRow['state'], number> = {
  changes: 0,
  approved: 1,
  commented: 2,
  pending: 3,
};

/** Compact overlapping avatar stack showing who's reviewing and their
 * verdict (status dot: green approved · red changes · gray commented ·
 * amber pending). Each chip is the same hover-scale + HoverCard the PR
 * header uses — name, role, status/age, comment count, and last-comment
 * preview. Read-only here (no jump/management actions — clicking the row
 * opens the PR), so the popup's footer collapses. Caps at 4 chips with a
 * +N overflow so a crowded PR doesn't blow out the row. */
function RowReviewers({ reviewers }: { reviewers: ReviewerStateRow[] }) {
  if (reviewers.length === 0) {
    return <span className="text-[12px] text-muted-foreground/60">—</span>;
  }
  const ordered = [...reviewers].sort(
    (a, b) => REVIEWER_STATE_RANK[a.state] - REVIEWER_STATE_RANK[b.state],
  );
  const shown = ordered.slice(0, 4);
  const extra = ordered.length - shown.length;
  return (
    <div
      className="flex items-center"
      // The row is a click target; keep chip hovers/clicks from opening
      // the PR so the popup can be read.
      onClick={(e) => e.stopPropagation()}
    >
      {shown.map((r, i) => (
        <ReviewerChipHover key={r.login} row={r} first={i === 0} />
      ))}
      {extra > 0 && (
        <span className="ml-1 text-[11px] text-muted-foreground/80">
          +{extra}
        </span>
      )}
    </div>
  );
}

function PRRow({
  pr: stubPR,
  selected,
  linkProps,
  onSelect,
  onHover,
  onLeave,
}: {
  pr: PR;
  selected?: boolean;
  linkProps: ReturnType<typeof prLinkProps>;
  onSelect?: () => void;
  onHover?: () => void;
  onLeave?: () => void;
}) {
  // Hydrate the row's diff stats / branch from the PR-detail endpoint.
  // GraphQL `search` doesn't carry these, so without this useQuery every
  // row would render "0 files +0 −0" with an empty branch. TanStack
  // dedupes against the on-hover prefetcher and against PRDetailScreen's
  // own useQuery on click, so the request runs once per unique PR per
  // session and 304s on poll thanks to the ETag layer.
  const metaQuery = useQuery({
    ...prMetaOptions(stubPR.owner, stubPR.repoName, stubPR.num),
    staleTime: 5 * 60_000,
  });
  const meta = metaQuery.data;
  const checksQuery = useQuery({
    queryKey: [
      'pr',
      stubPR.owner,
      stubPR.repoName,
      stubPR.num,
      'checks',
      meta?.head.sha,
    ],
    queryFn: () =>
      meta
        ? getCheckRuns(stubPR.owner, stubPR.repoName, meta.head.sha)
        : Promise.resolve({ total_count: 0, check_runs: [] }),
    enabled: !!meta,
    staleTime: 60_000,
  });
  const reviewsQuery = useQuery({
    queryKey: ['pr', stubPR.owner, stubPR.repoName, stubPR.num, 'reviews'],
    queryFn: () => getReviews(stubPR.owner, stubPR.repoName, stubPR.num),
    staleTime: 60_000,
  });
  const viewerQuery = useQuery({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: Infinity,
  });
  // Inline review comments — only needed to enrich the reviewer
  // HoverCard's "last comment" preview (and to surface reviewers who
  // left only line-comments). Gated on a review signal so PRs with no
  // reviewers/requests skip the fetch; bounded to visible rows by the
  // virtualizer, same as the meta/checks/reviews queries above.
  const hasReviewSignal =
    (reviewsQuery.data?.length ?? 0) > 0 ||
    (meta?.requested_reviewers.length ?? 0) > 0;
  const reviewCommentsQuery = useQuery({
    ...prCommentsOptions(stubPR.owner, stubPR.repoName, stubPR.num),
    enabled: hasReviewSignal,
    staleTime: 60_000,
  });
  const viewerLogin = viewerQuery.data?.login;
  const myLatestVerdict = (() => {
    if (!viewerLogin) return null;
    const mine = (reviewsQuery.data ?? [])
      .filter((r) => r.user?.login === viewerLogin && r.submitted_at)
      .sort(
        (a, b) =>
          new Date(b.submitted_at!).getTime() -
          new Date(a.submitted_at!).getTime(),
      );
    return mine[0]?.state ?? null;
  })();
  const checks = (() => {
    const cr = checksQuery.data?.check_runs ?? [];
    let pass = 0;
    let fail = 0;
    let pending = 0;
    for (const c of cr) {
      if (c.status !== 'completed') {
        pending++;
      } else if (
        c.conclusion === 'success' ||
        c.conclusion === 'neutral' ||
        c.conclusion === 'skipped'
      ) {
        pass++;
      } else if (
        c.conclusion === 'failure' ||
        c.conclusion === 'cancelled' ||
        c.conclusion === 'timed_out' ||
        c.conclusion === 'action_required'
      ) {
        fail++;
      }
    }
    return { pass, fail, pending };
  })();
  const pr: PR = meta
    ? {
        ...stubPR,
        branch: meta.head.ref,
        additions: meta.additions,
        deletions: meta.deletions,
        files: meta.changed_files,
        reviews: {
          ...stubPR.reviews,
          req: meta.requested_reviewers.length,
        },
        checks,
        approved: myLatestVerdict === 'APPROVED',
        changes: myLatestVerdict === 'CHANGES_REQUESTED',
      }
    : stubPR;
  // Per-reviewer verdicts (who's reviewing + their state) — reuses the
  // same aggregation + HoverCard the PR header uses. `meta` carries the
  // author + requested_reviewers; `reviewsQuery` the submitted verdicts;
  // `reviewCommentsQuery` the inline comments that power the popup's
  // last-comment preview.
  const reviewers = collectReviewerStates(
    meta,
    reviewsQuery.data ?? [],
    reviewCommentsQuery.data ?? [],
  );
  const statusIcon: IconName = pr.draft ? 'pr-draft' : 'pr-open';
  return (
    <div
      onMouseEnter={onHover}
      onMouseLeave={onLeave}
      className={cn(
        'relative flex items-start gap-2.5 border-b border-border/60 px-4 py-2.5',
        selected ? 'bg-primary/[0.07]' : 'bg-transparent',
      )}
    >
      <Link
        {...linkProps}
        onClick={onSelect}
        aria-label={`PR #${pr.num}: ${pr.title}`}
        className="absolute inset-0 z-0 cursor-pointer"
      />
      {selected && (
        <div className="pointer-events-none absolute bottom-0 left-0 top-0 w-0.5 bg-primary" />
      )}

      <div className="w-2 shrink-0 pt-1.5">
        {pr.unread > 0 && (
          <div className="size-[7px] rounded-full bg-pyor-unread" />
        )}
      </div>

      <div className={cn('shrink-0 pt-0.5', statusColorClass(pr.status, pr.draft))}>
        <Icon name={statusIcon} size={15} />
      </div>

      <div className="min-w-0 flex-1">
        <div className="mb-[3px] flex flex-wrap items-baseline gap-x-2 gap-y-1">
          {/* Status badge — leads the row so the state reads first,
              ahead of the title. Mutually exclusive: draft > merged >
              closed > open. */}
          {pr.draft ? (
            <Badge variant="secondary" className="shrink-0 px-1.5 py-0 text-[10px]">
              draft
            </Badge>
          ) : pr.status === 'merged' ? (
            <Badge
              variant="secondary"
              className="shrink-0 border-purple-200 bg-purple-100 px-1.5 py-0 text-[10px] text-purple-700 dark:border-purple-900 dark:bg-purple-900/40 dark:text-purple-300"
            >
              merged
            </Badge>
          ) : pr.status === 'closed' ? (
            <Badge variant="destructive" className="shrink-0 px-1.5 py-0 text-[10px]">
              closed
            </Badge>
          ) : (
            <Badge
              variant="secondary"
              className="shrink-0 border-emerald-200 bg-emerald-100 px-1.5 py-0 text-[10px] text-emerald-700 dark:border-emerald-900 dark:bg-emerald-900/40 dark:text-emerald-300"
            >
              open
            </Badge>
          )}
          <span
            className={cn(
              'min-w-0 max-w-full truncate text-[13px] text-foreground',
              pr.unread ? 'font-semibold' : 'font-medium',
            )}
          >
            {pr.title}
          </span>
          {pr.changes && (
            <Badge variant="destructive" className="px-1.5 py-0 text-[10px]">
              changes requested
            </Badge>
          )}
          {pr.approved && (
            <Badge variant="secondary" className="px-1.5 py-0 text-[10px]">
              approved by you
            </Badge>
          )}
          {pr.bot && (
            <Badge variant="outline" className="px-1.5 py-0 text-[10px]">
              bot
            </Badge>
          )}
          {pr.labels.map((l) => (
            <Label key={l.name} color={`#${l.color}`} text={l.name} />
          ))}
        </div>
        <div className="flex min-w-0 items-center gap-2 overflow-hidden whitespace-nowrap text-[12px] text-muted-foreground">
          <span className="shrink-0 font-mono text-[11px] text-muted-foreground/80">
            #{pr.num}
          </span>
          <span className="shrink-0">{pr.repo}</span>
          <span className="shrink-0 text-muted-foreground/60">·</span>
          <span className="inline-flex shrink-0 items-center gap-1.5">
            <PRRowAvatar name={pr.author} url={pr.authorAvatarUrl || undefined} />
            {pr.author}
          </span>
          {pr.branch && (
            <>
              <span className="shrink-0 text-muted-foreground/60">·</span>
              <span className="inline-flex min-w-0 shrink items-center gap-1">
                <Icon name="branch" size={11} />
                <span className="min-w-0 truncate font-mono text-[11px]">
                  {pr.branch}
                </span>
              </span>
            </>
          )}
        </div>
      </div>

      <div className="hidden shrink-0 items-center gap-3.5 text-[12px] tabular-nums text-muted-foreground sm:flex">
        {/* Diff stats — first to drop at narrow widths (hidden < md). */}
        <div className="hidden min-w-[80px] text-right md:block">
          <div className="text-[11px] text-muted-foreground/80">
            {pr.files} files
          </div>
          <DiffStat
            additions={pr.additions}
            deletions={pr.deletions}
            className="text-[11px]"
          />
        </div>

        <div className="hidden min-w-[64px] lg:block">
          <CheckSummary
            pass={pr.checks.pass}
            fail={pr.checks.fail}
            pending={pr.checks.pending}
          />
        </div>

        <div className="relative z-10 hidden min-w-[72px] items-center lg:flex">
          <RowReviewers reviewers={reviewers} />
        </div>

        <div className="min-w-[36px]">
          {pr.comments > 0 ? (
            <span
              className={cn(
                'inline-flex items-center gap-[3px]',
                pr.unread > 0 ? 'text-pyor-unread' : 'text-muted-foreground/80',
              )}
            >
              <Icon
                name={pr.unread > 0 ? 'comment-fill' : 'comment'}
                size={12}
              />
              <span
                className={cn(
                  pr.unread > 0
                    ? 'font-semibold text-pyor-unread'
                    : 'font-normal text-muted-foreground',
                )}
              >
                {pr.comments}
                {pr.unread > 0 ? ` (${pr.unread})` : ''}
              </span>
            </span>
          ) : (
            <span className="text-muted-foreground/60">—</span>
          )}
        </div>

        <div className="min-w-[28px] text-right text-muted-foreground/80">
          {pr.age}
        </div>
      </div>
    </div>
  );
}

