// PostHog init for the authenticated product (ADR 0021).
//
// Posture, encoded as config:
//   • autocapture OFF + session recording OFF — both would pull code / comment
//     DOM text into analytics, breaching "your code never leaves your machine".
//   • capture_pageview OFF — routes are `/owner/repo/123`; raw paths leak
//     private repo names. We emit curated screen events with a HASHED repo id
//     instead (see events.ts).
//   • persistence 'localStorage' — no cookies, keeping the "cookieless" promise.
//   • person_profiles 'identified_only' — anonymous visitors don't create
//     person profiles until they sign in (stitching happens on identify()).
//   • sanitize_properties — belt-and-suspenders: strip any URL-bearing property
//     from EVERY event so a stray $current_url can never carry a repo path.
//   • api_host — the first-party reverse proxy, never *.posthog.com directly.

import posthog from 'posthog-js';
import {
  POSTHOG_KEY,
  POSTHOG_HOST,
  POSTHOG_UI_HOST,
  analyticsConfigured,
} from './config';
import { isAnalyticsOptedOut } from './consent';

// Properties PostHog auto-attaches that can carry a repo path → blanked.
const URL_PROPS = [
  '$current_url',
  '$pathname',
  '$referrer',
  '$referring_domain',
  'title',
];

function scrubUrlProps(
  props: Record<string, unknown>,
): Record<string, unknown> {
  URL_PROPS.forEach((k) => {
    if (k in props) delete props[k];
  });
  return props;
}

let started = false;

export function initPostHog(): void {
  if (started || !analyticsConfigured || !POSTHOG_KEY) return;
  started = true;

  posthog.init(POSTHOG_KEY, {
    api_host: POSTHOG_HOST,
    ui_host: POSTHOG_UI_HOST,
    persistence: 'localStorage',
    autocapture: false,
    capture_pageview: false,
    capture_pageleave: false,
    disable_session_recording: true,
    person_profiles: 'identified_only',
    // Honour the opt-out from the very first event of the session.
    opt_out_capturing_by_default: isAnalyticsOptedOut(),
    sanitize_properties: (props) => scrubUrlProps(props ?? {}),
    // We tunnel through our own origin; PostHog's own external-asset fetches
    // are unnecessary for a curated, no-autocapture, no-replay setup.
    disable_external_dependency_loading: true,
  });
}

export { posthog };
