interface LocalReviewsScreenProps {
  fluid?: boolean;
  /** Optional — when provided, the list row click navigates via this
   * callback (driven by the App-level router, route kind
   * `'local-review'`). When absent, falls back to the legacy in-
   * component `Mode` state machine so the screen still works standalone
   * (tests, stories). Phase B/C will collapse the fallback once the
   * surface branch in this file is removed. */
  onOpenReview?: (reviewId: string) => void;
}

type Mode =
  | { kind: 'list' }
  | { kind: 'wizard' }
  | { kind: 'surface'; review: LocalReview };

/** Add-repo dialog state machine. Three terminal kinds:
 *   - 'valid' / 'not-git' / 'no-base' — single-repo path (the picked
 *     folder IS a git repo).
 *   - 'multi' — the picked folder contained more than one git repo
 *     under it (discoverRepos returned >1 entries). The dialog renders
 *     the list and offers "Add all N".
 * Plus the two transient states 'idle' (Browse-to-start) and 'picking'
 * (native picker open). */
type AddRepoState =
  | 'idle'
  | 'picking'
  | LocalRepoValidation
  | { kind: 'multi'; folderPath: string; repos: DiscoveredRepo[] };

export function LocalReviewsScreen({
  fluid,
  onOpenReview: onOpenReviewProp,
}: LocalReviewsScreenProps) {
  // When no explicit handler is passed (the normal app path), open the
  // per-review surface via the router (`/local/:reviewId`). The prop
  // override is kept for tests/stories that render the screen
  // standalone.
  const navigate = useNavigate();
  const onOpenReview =
    onOpenReviewProp ??
    ((reviewId: string) =>
      void navigate({
        to: '/local/$reviewId',
        params: { reviewId },
      }));
  const [mode, setMode] = useState<Mode>({ kind: 'list' });
  // Add-repo flow is reused from the existing dialog. It can be opened
  // from either the list page's empty state, the list toolbar's
  // "Create new local review" path, or the wizard's "+ Add new repo…"
  // select option.
  //  - 'idle'    — dialog open, no folder picked yet (Browse-to-start)
  //  - 'picking' — native folder picker is open
  //  - kind=valid/not-git/no-base — single-repo validation card
  //  - kind=multi — discovered N>1 repos under the picked folder
  //  - null      — dialog closed
  const [adding, setAdding] = useState<AddRepoState | null>(null);
  // Keep AddRepoDialog mounted through its close animation: retain the
  // last state so the dialog stays in the tree (driven by `open`) while
  // it animates out, instead of unmounting instantly on `setAdding(null)`.
  const lastAddingRef = useRef<AddRepoState | null>(null);
  if (adding) lastAddingRef.current = adding;
  const addingState = adding ?? lastAddingRef.current;
  // Confirmation state for deleting a review row.
  const [pendingDelete, setPendingDelete] = useState<LocalReview | null>(null);

  const deleteReview = useDeleteLocalReview();

  // Open the in-app add-repo dialog (reused from the v1 design). The
  // wizard hooks into this through `onRequestAddRepo` so the user can
  // jump from "+ Add new repo…" in the Repo select straight into the
  // native folder picker without losing the wizard surface.
  // Opens the dialog in its `idle` state — the design wants the
  // Folder field empty until the user clicks Browse, NOT auto-picker.
  const onAddRepo = () => setAdding('idle');
  // Browse action from inside the dialog. Fires the native picker, then
  // runs discoverRepos on the chosen path. Three resulting shapes:
  //   - 0 results → 'not-git' validation card (path isn't a repo and
  //     contains none under it)
  //   - 1 result → run the single-path validate so we also get the
  //     no-base check, then render the existing single-repo card
  //   - N > 1   → new 'multi' state lists the discovered repos for the
  //     user to confirm before bulk-registering
  const onBrowseInDialog = async () => {
    const b = bridge();
    if (!b) return;
    const prior = adding;
    setAdding('picking');
    try {
      const chosen = await b.localRepoPickFolder();
      if (!chosen) {
        // Cancelled — restore the prior state (idle, or a previously
        // validated card). Don't close the whole dialog.
        setAdding(prior === 'picking' ? 'idle' : prior);
        return;
      }
      const discovered = await b.localRepoDiscoverInFolder(chosen);
      if (discovered.length === 0) {
        // No git repos here — surface the same 'not-git' card the
        // single-path flow uses.
        setAdding({ kind: 'not-git', path: chosen });
        return;
      }
      if (discovered.length === 1) {
        // Single repo — run the single-path validate so we get the
        // suggestedBase / no-base check too, then render the existing
        // single-repo card. The discovered entry's path may be the
        // picked folder itself or a nested subdir — validate the real
        // repo path.
        const single = await b.localRepoValidate(discovered[0].path);
        setAdding(single);
        return;
      }
      setAdding({
        kind: 'multi',
        folderPath: chosen,
        repos: discovered,
      });
    } catch (e) {
      toast.error('Could not open folder picker', {
        description: e instanceof Error ? e.message : String(e),
      });
      setAdding(prior === 'picking' ? 'idle' : prior);
    }
  };
  const queryClient = useQueryClient();
  const onConfirmAddRepo = async (path: string) => {
    const b = bridge();
    if (!b) return;
    await b.localRepoRegister(path);
    // Refresh anything keyed on the repo list — the launcher dropdown,
    // the status-bar worktree count, etc.
    await queryClient.invalidateQueries({ queryKey: ['local-repo-list'] });
    await queryClient.invalidateQueries({ queryKey: ['local-worktree-count'] });
    setAdding(null);
  };
  // Bulk-register every repo discovered under a picked folder. Each
  // register call is idempotent on the registry, so partial failures
  // leave the user with whatever succeeded — they can re-Browse to
  // re-attempt the rest. Toast counts the successes.
  const onConfirmAddRepos = async (paths: string[]) => {
    const b = bridge();
    if (!b) return;
    let ok = 0;
    for (const p of paths) {
      try {
        await b.localRepoRegister(p);
        ok += 1;
      } catch (e) {
        // eslint-disable-next-line no-console
        console.warn('localRepoRegister failed for', p, e);
      }
    }
    await queryClient.invalidateQueries({ queryKey: ['local-repo-list'] });
    await queryClient.invalidateQueries({ queryKey: ['local-worktree-count'] });
    if (ok > 0) {
      toast.success(`Added ${ok} repo${ok === 1 ? '' : 's'}`);
    }
    if (ok < paths.length) {
      toast.error(
        `${paths.length - ok} repo${paths.length - ok === 1 ? '' : 's'} could not be added`,
      );
    }
    setAdding(null);
  };

  const onConfirmDelete = async () => {
    if (!pendingDelete) return;
    try {
      await deleteReview.mutateAsync(pendingDelete.id);
      toast.success('Local review deleted');
      // If the deleted review is currently open, bounce to the list.
      if (mode.kind === 'surface' && mode.review.id === pendingDelete.id) {
        setMode({ kind: 'list' });
      }
    } finally {
      setPendingDelete(null);
    }
  };

  // Web-build branch — no bridge, no list/wizard.
  if (!isElectron()) {
    return (
      <PyorWindow fluid={fluid} title="Local reviews">
        <WebBuildEmpty />
      </PyorWindow>
    );
  }

  if (mode.kind === 'surface') {
    return (
      <LocalReviewSurface
        review={mode.review}
        onBack={() => setMode({ kind: 'list' })}
        onRequestDelete={() => setPendingDelete(mode.review)}
        fluid={fluid}
      />
    );
  }

  if (mode.kind === 'wizard') {
    return (
      <>
        <LauncherWizard
          onCancel={() => setMode({ kind: 'list' })}
          onStart={(review) => {
            // Phase A: prefer the App-level route when wired (proper
            // history, bookmarkable URL); fall back to the legacy
            // in-component surface for standalone usage.
            if (onOpenReview) onOpenReview(review.id);
            else setMode({ kind: 'surface', review });
          }}
          onRequestAddRepo={() => void onAddRepo()}
          fluid={fluid}
        />
        {addingState && (
          <AddRepoDialog
            open={!!adding}
            state={addingState}
            onClose={() => setAdding(null)}
            onBrowse={() => void onBrowseInDialog()}
            onConfirm={onConfirmAddRepo}
            onConfirmBulk={onConfirmAddRepos}
          />
        )}
        <DeleteReviewDialog
          review={pendingDelete}
          onCancel={() => setPendingDelete(null)}
          onConfirm={() => void onConfirmDelete()}
          pending={deleteReview.isPending}
        />
      </>
    );
  }

  return (
    <>
      <LocalReviewsListScreen
        fluid={fluid}
        onCreate={() => setMode({ kind: 'wizard' })}
        onOpen={(review) => {
          if (onOpenReview) onOpenReview(review.id);
          else setMode({ kind: 'surface', review });
        }}
        onDelete={(review) => setPendingDelete(review)}
        onAddRepo={onAddRepo}
      />
      {addingState && (
        <AddRepoDialog
          open={!!adding}
          state={addingState}
          onClose={() => setAdding(null)}
          onBrowse={() => void onBrowseInDialog()}
          onConfirm={onConfirmAddRepo}
          onConfirmBulk={onConfirmAddRepos}
        />
      )}
      <DeleteReviewDialog
        review={pendingDelete}
        onCancel={() => setPendingDelete(null)}
        onConfirm={() => void onConfirmDelete()}
        pending={deleteReview.isPending}
      />
    </>
  );
}

