/** Sort options for the Local Reviews list (ADR 0012 Phase 7). The
 *  default "Last activity ↓" sorts by `createdAt` as a v1 proxy —
 *  LocalReview has no `updatedAt` field yet; lifting "any comment edit
 *  bumps activity" is layered later. */
type SortKey =
  | 'lastActivity'
  | 'aheadDesc'
  | 'behindDesc'
  | 'notesDesc';

const SORT_LABELS: Record<SortKey, string> = {
  lastActivity: 'Last activity',
  aheadDesc: 'Ahead descending',
  behindDesc: 'Behind descending',
  notesDesc: 'Notes descending',
};

const SORT_STORAGE_KEY = 'pyor:local-reviews-sort';
const FILTERS_STORAGE_KEY = 'pyor:local-reviews-filters';

interface PersistedFilters {
  status: 'any' | LocalReviewStatus;
  repo: 'any' | string;
  base: 'any' | string;
}

function readPersistedFilters(): PersistedFilters {
  const fallback: PersistedFilters = { status: 'any', repo: 'any', base: 'any' };
  if (typeof localStorage === 'undefined') return fallback;
  try {
    const raw = localStorage.getItem(FILTERS_STORAGE_KEY);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    // Defensive: keys may be stale strings (e.g. a repo that was
    // since removed). We accept the saved value verbatim — the
    // dropdown will fall back to "any" rendering if the option is
    // gone, and the user can re-pick.
    return {
      status: parsed?.status ?? 'any',
      repo: parsed?.repo ?? 'any',
      base: parsed?.base ?? 'any',
    };
  } catch {
    return fallback;
  }
}

function readPersistedSort(): SortKey {
  if (typeof localStorage === 'undefined') return 'lastActivity';
  try {
    const raw = localStorage.getItem(SORT_STORAGE_KEY);
    if (raw === 'lastActivity' || raw === 'aheadDesc' || raw === 'behindDesc' || raw === 'notesDesc') {
      return raw;
    }
  } catch {
    // localStorage disabled / quota errors — fall through.
  }
  return 'lastActivity';
}

function LocalReviewsListScreen({
  fluid,
  onCreate,
  onOpen,
  onDelete,
  onAddRepo,
}: {
  fluid?: boolean;
  onCreate: () => void;
  onOpen: (review: LocalReview) => void;
  onDelete: (review: LocalReview) => void;
  /** Open the Add-repo dialog in its `idle` state. Threaded from the
   * parent so the empty-state CTA + the Repo-chip's "Add another repo"
   * action both route through the same flow as the wizard's
   * "+ Add new repo…" entry point. */
  onAddRepo: () => void;
}) {
  const reviewsQuery = useLocalReviewsList();
  const reviews = reviewsQuery.data ?? [];
  // Registered repos drive the "no repos yet" empty state — the list
  // page can have reviews but zero registered repos (e.g. all repos
  // were removed; soft-deleted reviews remain), or zero of either
  // (first-run).
  const reposQuery = useQuery({
    queryKey: ['local-repo-list'] as const,
    queryFn: async () => (await bridge()?.localRepoList()) ?? [],
    staleTime: Infinity,
    enabled: isElectron(),
  });
  const registeredRepos = reposQuery.data ?? [];
  // Soft-deleted reviews stay in the list (so the user can clean them
  // up explicitly) but get visually dimmed + click-disabled. The
  // "really no reviews" check ignores them so the empty state still
  // fires when everything is soft-deleted.
  const liveReviews = useMemo(
    () => reviews.filter((r) => !r.deleted),
    [reviews],
  );
  const removeRepo = useRemoveLocalRepo();
  const [filter, setFilter] = useState('');
  // ADR 0012 Phase 7 / Phase 8 polish — filter chip state. Each chip
  // narrows the row list by Status / Repo / Base. Persisted to
  // localStorage as one JSON blob so the user's working filter set
  // survives reloads. Sort persists separately (older key).
  const initialFilters = useMemo(() => readPersistedFilters(), []);
  const [statusFilter, setStatusFilter] = useState<'any' | LocalReviewStatus>(
    initialFilters.status,
  );
  const [repoFilter, setRepoFilter] = useState<'any' | string>(
    initialFilters.repo,
  );
  const [baseFilter, setBaseFilter] = useState<'any' | string>(
    initialFilters.base,
  );
  const [sort, setSort] = useState<SortKey>(() => readPersistedSort());
  // Persist sort to localStorage so it survives reloads.
  useEffect(() => {
    if (typeof localStorage === 'undefined') return;
    try {
      localStorage.setItem(SORT_STORAGE_KEY, sort);
    } catch {
      // Quota / disabled storage — best-effort, ignore.
    }
  }, [sort]);
  // Persist filter chip selections.
  useEffect(() => {
    if (typeof localStorage === 'undefined') return;
    try {
      localStorage.setItem(
        FILTERS_STORAGE_KEY,
        JSON.stringify({
          status: statusFilter,
          repo: repoFilter,
          base: baseFilter,
        } satisfies PersistedFilters),
      );
    } catch {
      // Quota / disabled storage — best-effort, ignore.
    }
  }, [statusFilter, repoFilter, baseFilter]);

  // Per-row state (status, ahead/behind, notes counts, PR detection).
  // Fanned out as a single `useQueries` at the list level so the filter
  // / sort layer can read every row's status without each row mounting
  // its own query. Rows receive their state by prop (no extra hook
  // call inside the row component).
  const rowStates = useLocalReviewRowStates(reviews);

  // Worktree count across all registered repos — drives the status-bar
  // line. Computed lazily; on failure we fall back to "git OK" without
  // the count rather than blocking the screen.
  const worktreeCount = useWorktreeCount();

  // Filter options derived from the dataset.
  const repoOptions = useMemo(() => {
    const set = new Set<string>();
    for (const r of reviews) set.add(r.repoPath);
    return Array.from(set).sort();
  }, [reviews]);
  const baseOptions = useMemo(() => {
    const set = new Set<string>();
    for (const r of reviews) set.add(r.base);
    return Array.from(set).sort();
  }, [reviews]);

  const anyFilterActive =
    statusFilter !== 'any' ||
    repoFilter !== 'any' ||
    baseFilter !== 'any' ||
    filter.trim() !== '';
  const clearAllFilters = () => {
    setStatusFilter('any');
    setRepoFilter('any');
    setBaseFilter('any');
    setFilter('');
  };

  const filtered = useMemo(() => {
    const needle = filter.trim().toLowerCase();
    const matchesNeedle = (r: LocalReview) => {
      if (!needle) return true;
      const hay = [r.title ?? '', r.branch, r.base, r.repoPath]
        .join(' ')
        .toLowerCase();
      return hay.includes(needle);
    };
    const matchesChips = (r: LocalReview) => {
      if (repoFilter !== 'any' && r.repoPath !== repoFilter) return false;
      if (baseFilter !== 'any' && r.base !== baseFilter) return false;
      if (statusFilter !== 'any') {
        const st = rowStates.get(r.id)?.status ?? 'ready';
        if (st !== statusFilter) return false;
      }
      return true;
    };
    const rows = reviews.filter((r) => matchesNeedle(r) && matchesChips(r));
    // Sort. `lastActivity` is the default; other keys read off the row
    // state map. Ties fall through to `createdAt` desc so the order is
    // stable for rows with equal counts.
    const byActivityDesc = (a: LocalReview, b: LocalReview) =>
      b.createdAt.localeCompare(a.createdAt);
    const sorters: Record<SortKey, (a: LocalReview, b: LocalReview) => number> = {
      lastActivity: byActivityDesc,
      aheadDesc: (a, b) => {
        const av = rowStates.get(a.id)?.ahead ?? 0;
        const bv = rowStates.get(b.id)?.ahead ?? 0;
        if (bv !== av) return bv - av;
        return byActivityDesc(a, b);
      },
      behindDesc: (a, b) => {
        const av = rowStates.get(a.id)?.behind ?? 0;
        const bv = rowStates.get(b.id)?.behind ?? 0;
        if (bv !== av) return bv - av;
        return byActivityDesc(a, b);
      },
      notesDesc: (a, b) => {
        const av = rowStates.get(a.id)?.notesTotal ?? 0;
        const bv = rowStates.get(b.id)?.notesTotal ?? 0;
        if (bv !== av) return bv - av;
        return byActivityDesc(a, b);
      },
    };
    return [...rows].sort(sorters[sort]);
  }, [reviews, filter, repoFilter, baseFilter, statusFilter, sort, rowStates]);

  // Three list-page states drive both the body and the toolbar CTA:
  //   1. no repos + no reviews — first-run; show the NoReposEmptyState.
  //      The "Create new local review" toolbar CTA is HIDDEN because
  //      clicking it would open a launcher with an empty Repo dropdown.
  //   2. repos but no live reviews — show the existing
  //      LocalReviewsListEmpty (with the Create CTA available).
  //   3. has live reviews — populated list with filter chips etc.
  const showNoReposEmpty =
    isElectron() &&
    reviews.length === 0 &&
    registeredRepos.length === 0 &&
    !reposQuery.isLoading;
  const showNoReviewsEmpty = !showNoReposEmpty && liveReviews.length === 0;
  const showCreateCta = !showNoReposEmpty;

  return (
    <PyorWindow
      fluid={fluid}
      title="Local reviews"
      subtitle={
        reviewsQuery.isLoading
          ? 'Loading…'
          : showNoReposEmpty
            ? 'No repos yet'
            : liveReviews.length === 0
              ? 'None yet'
              : `${liveReviews.length} on this machine`
      }
      toolbar={
        <>
          <div className="relative">
            <SearchIcon className="pointer-events-none absolute left-2 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              placeholder="Filter local reviews"
              className="h-8 w-56 pl-7 pr-10 text-[12.5px]"
            />
            <Kbd className="pointer-events-none absolute right-2 top-1/2 -translate-y-1/2">
              ⌘F
            </Kbd>
          </div>
          <RefreshButton
            onRefresh={() => void reviewsQuery.refetch()}
            spinning={reviewsQuery.isFetching}
          />
          {showCreateCta && (
            <Button size="sm" onClick={onCreate}>
              <PlusIcon /> Create new local review
            </Button>
          )}
        </>
      }
      status={
        <>
          <span className="inline-flex items-center gap-1.5">
            <span className="size-1.5 rounded-full bg-pyor-pass" />
            git OK
            {worktreeCount != null && ` · ${worktreeCount} worktrees discovered`}
          </span>
          <span className="ml-auto">
            No GitHub round-trips · everything below is local
          </span>
        </>
      }
    >
      {!showNoReposEmpty && !showNoReviewsEmpty && (
        <FilterChipsStrip
          statusFilter={statusFilter}
          onStatusChange={setStatusFilter}
          repoFilter={repoFilter}
          onRepoChange={setRepoFilter}
          repoOptions={repoOptions}
          baseFilter={baseFilter}
          onBaseChange={setBaseFilter}
          baseOptions={baseOptions}
          registeredRepos={registeredRepos}
          onAddRepo={onAddRepo}
          onRemoveRepo={(repoPath) => {
            void removeRepo
              .mutateAsync(repoPath)
              .then(({ softDeletedCount }) => {
                const label = repoLabelFromPath(repoPath);
                toast.success(`Removed ${label}`, {
                  description:
                    softDeletedCount > 0
                      ? `${softDeletedCount} local review${softDeletedCount === 1 ? '' : 's'} marked as deleted.`
                      : 'No local reviews were attached to this repo.',
                });
                // If the Repo filter was scoped to the removed repo,
                // reset it so the list isn't stuck on an empty view.
                if (repoFilter === repoPath) setRepoFilter('any');
              })
              .catch((e) => {
                toast.error('Could not remove repo', {
                  description: e instanceof Error ? e.message : String(e),
                });
              });
          }}
          sort={sort}
          onSortChange={setSort}
          showClear={anyFilterActive}
          onClearAll={clearAllFilters}
        />
      )}
      {showNoReposEmpty ? (
        <NoReposEmptyState onAddRepo={onAddRepo} />
      ) : showNoReviewsEmpty ? (
        <LocalReviewsListEmpty onCreate={onCreate} />
      ) : filtered.length === 0 ? (
        <EmptyState
          icon={SearchIcon}
          title="No local reviews match this filter."
          body={
            filter.trim()
              ? `Nothing matches “${filter}”. Clear filters to see the full list.`
              : 'Clear filters to see the full list.'
          }
          action={
            <Button variant="outline" size="sm" onClick={clearAllFilters}>
              Clear filters
            </Button>
          }
        />
      ) : (
        <div className="flex-1 overflow-auto">
          {filtered.map((r) => (
            <LocalReviewRow
              key={r.id}
              review={r}
              rowState={rowStates.get(r.id)}
              onOpen={() => onOpen(r)}
              onDelete={() => onDelete(r)}
            />
          ))}
        </div>
      )}
    </PyorWindow>
  );
}

/** Filter chip strip — Status / Repo / Base dropdowns + sort dropdown.
 *  Each chip wraps a shadcn `DropdownMenu`; active filters tint the
 *  chip per the design's `SChip` active state. "Clear all" only renders
 *  when at least one chip is non-default. */
function FilterChipsStrip({
  statusFilter,
  onStatusChange,
  repoFilter,
  onRepoChange,
  repoOptions,
  baseFilter,
  onBaseChange,
  baseOptions,
  registeredRepos,
  onAddRepo,
  onRemoveRepo,
  sort,
  onSortChange,
  showClear,
  onClearAll,
}: {
  statusFilter: 'any' | LocalReviewStatus;
  onStatusChange: (v: 'any' | LocalReviewStatus) => void;
  repoFilter: 'any' | string;
  onRepoChange: (v: 'any' | string) => void;
  repoOptions: string[];
  baseFilter: 'any' | string;
  onBaseChange: (v: 'any' | string) => void;
  baseOptions: string[];
  /** Full registered-repo list. The Repo chip's dropdown shows EVERY
   * registered repo (not just the subset that currently has reviews)
   * so the user can also reach repos they registered but haven't yet
   * created a review for, and so the "Remove from Pyor" action is
   * available even for repos with zero reviews. */
  registeredRepos: LocalRepo[];
  onAddRepo: () => void;
  /** Cascade-remove a repo: soft-deletes its LocalReviews and drops it
   * from the registry. Caller surfaces the result toast. */
  onRemoveRepo: (repoPath: string) => void;
  sort: SortKey;
  onSortChange: (s: SortKey) => void;
  showClear: boolean;
  onClearAll: () => void;
}) {
  // Union of "registered repos" and "repo paths that show up in the
  // current review list" — soft-deleted reviews still appear in the
  // list, so their repoPath might already be removed from the registry
  // but still needs to be a filter option (so the user can scope to
  // their leftover ghost reviews).
  const allRepoPaths = useMemo(() => {
    const s = new Set<string>();
    for (const r of registeredRepos) s.add(r.path);
    for (const p of repoOptions) s.add(p);
    return Array.from(s).sort();
  }, [registeredRepos, repoOptions]);
  const registeredSet = useMemo(
    () => new Set(registeredRepos.map((r) => r.path)),
    [registeredRepos],
  );
  return (
    <div className="flex items-center gap-2 border-b bg-muted/30 px-4 py-2">
      <FilterChipMenu
        label="Status"
        active={statusFilter !== 'any'}
        value={statusFilter === 'any' ? 'any' : STATUS_CFG[statusFilter].label}
        items={[
          { value: 'any', label: 'Any status' },
          { value: 'ready', label: STATUS_CFG.ready.label },
          { value: 'in-progress', label: STATUS_CFG['in-progress'].label },
          { value: 'stale', label: STATUS_CFG.stale.label },
          { value: 'pr-opened', label: STATUS_CFG['pr-opened'].label },
        ]}
        onSelect={(v) => onStatusChange(v as 'any' | LocalReviewStatus)}
      />
      <RepoFilterChipMenu
        repoFilter={repoFilter}
        onRepoChange={onRepoChange}
        repoPaths={allRepoPaths}
        registeredSet={registeredSet}
        onAddRepo={onAddRepo}
        onRemoveRepo={onRemoveRepo}
      />
      <FilterChipMenu
        label="Base"
        active={baseFilter !== 'any'}
        value={baseFilter === 'any' ? 'any' : baseFilter}
        items={[
          { value: 'any', label: 'Any base' },
          ...baseOptions.map((b) => ({ value: b, label: b })),
        ]}
        onSelect={onBaseChange}
      />
      {showClear && (
        <Button
          variant="link"
          size="xs"
          className="px-1 text-[11.5px]"
          onClick={onClearAll}
        >
          Clear all
        </Button>
      )}
      <div className="ml-auto inline-flex items-center gap-1">
        <span className="text-[11.5px] text-muted-foreground">Sorted by</span>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="xs"
              className="gap-1 px-1.5 text-[11.5px] font-medium text-foreground"
            >
              {SORT_LABELS[sort]} ↓
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {(Object.keys(SORT_LABELS) as SortKey[]).map((k) => (
              <DropdownMenuItem key={k} onSelect={() => onSortChange(k)}>
                {SORT_LABELS[k]}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
}

/** Single filter chip + its dropdown. The trigger styling mirrors the
 *  design's `SChip`: outlined when inactive, tinted when active. */
function FilterChipMenu({
  label,
  value,
  active,
  items,
  onSelect,
}: {
  label: string;
  value: string;
  active: boolean;
  items: { value: string; label: string }[];
  onSelect: (value: string) => void;
}) {
  // Mirrors the v4 design's SChip: rounded-md outline, `Label:value` text,
  // chevron-down affordance; active state inverts to filled foreground.
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          data-active={active || undefined}
          className="h-7 gap-1 rounded-md px-2.5 text-[12px] font-medium text-foreground data-[active]:border-foreground data-[active]:bg-foreground data-[active]:text-background"
        >
          <span>{label}</span>
          <span
            className={
              active
                ? 'text-background/70'
                : 'text-muted-foreground/70'
            }
          >
            :
          </span>
          <span className={active ? 'text-background' : 'text-foreground'}>
            {value}
          </span>
          <ChevronDownIcon className="size-3 opacity-60" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start">
        {items.map((it) => (
          <DropdownMenuItem key={it.value} onSelect={() => onSelect(it.value)}>
            {it.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** Repo filter chip — like `FilterChipMenu` but with two extra actions
 * at the bottom of the dropdown: "Add another repo…" + a per-repo
 * "Remove from Pyor" item. The latter cascades into soft-deleting all
 * LocalReviews bound to that repo (see `useRemoveLocalRepo`). */
function RepoFilterChipMenu({
  repoFilter,
  onRepoChange,
  repoPaths,
  registeredSet,
  onAddRepo,
  onRemoveRepo,
}: {
  repoFilter: 'any' | string;
  onRepoChange: (v: 'any' | string) => void;
  repoPaths: string[];
  registeredSet: Set<string>;
  onAddRepo: () => void;
  onRemoveRepo: (repoPath: string) => void;
}) {
  const active = repoFilter !== 'any';
  const valueLabel =
    repoFilter === 'any' ? 'any' : repoLabelFromPath(repoFilter);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          data-active={active || undefined}
          className="h-7 gap-1 rounded-md px-2.5 text-[12px] font-medium text-foreground data-[active]:border-foreground data-[active]:bg-foreground data-[active]:text-background"
        >
          <span>Repo</span>
          <span
            className={
              active ? 'text-background/70' : 'text-muted-foreground/70'
            }
          >
            :
          </span>
          <span className={active ? 'text-background' : 'text-foreground'}>
            {valueLabel}
          </span>
          <ChevronDownIcon className="size-3 opacity-60" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-[240px]">
        <DropdownMenuItem onSelect={() => onRepoChange('any')}>
          Any repo
        </DropdownMenuItem>
        {repoPaths.length > 0 && <DropdownMenuSeparator />}
        {repoPaths.map((p) => {
          const isRegistered = registeredSet.has(p);
          return (
            <div
              key={p}
              className="flex items-center gap-1 pl-2 pr-1 py-0.5"
            >
              <button
                type="button"
                onClick={() => onRepoChange(p)}
                className="flex-1 truncate rounded-sm px-1.5 py-1 text-left text-[12.5px] hover:bg-muted/60"
              >
                {repoLabelFromPath(p)}
                {!isRegistered && (
                  <span className="ml-1.5 text-[10.5px] text-muted-foreground">
                    (deleted)
                  </span>
                )}
              </button>
              {isRegistered && (
                <Button
                  variant="ghost"
                  size="icon"
                  className="size-6 text-muted-foreground hover:text-pyor-fail"
                  aria-label={`Remove ${repoLabelFromPath(p)} from Pyor`}
                  title="Remove from Pyor"
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveRepo(p);
                  }}
                >
                  <Trash2Icon className="size-3.5" />
                </Button>
              )}
            </div>
          );
        })}
        <DropdownMenuSeparator />
        <DropdownMenuItem onSelect={onAddRepo}>
          <FolderPlusIcon /> Add another repo…
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** First-run empty state — the user has no registered repos yet, so
 * there's no point in showing the launcher. Mirrors the design's
 * `ShadcnPrePRLauncherEmptyScreen` minus the "Watched paths" card
 * (dropped per product direction: discovery is a one-shot folder pick,
 * not a persistent watched-paths registry). */
function NoReposEmptyState({ onAddRepo }: { onAddRepo: () => void }) {
  return (
    <div className="flex-1 overflow-auto bg-muted/20 p-8">
      <div className="mx-auto max-w-2xl space-y-5">
        <EmptyState
          icon={FolderIcon}
          title="Add a repo to start your first local review."
          body="Pyor looks for git repos in the folder you pick. Got multiple repos in one place? Pyor finds them all."
          action={
            <Button size="sm" onClick={onAddRepo}>
              <PlusIcon /> Add repo…
            </Button>
          }
        />
        <Card>
          <div className="flex items-start gap-2.5 p-4">
            <InfoIcon className="mt-0.5 size-4 shrink-0 text-blue-600" />
            <div className="text-[12.5px] leading-relaxed text-muted-foreground">
              <b className="font-semibold text-foreground">Heads up:</b> local
              reviews stay local. Pyor never reads files outside the
              worktrees you've added, and never makes a GitHub request from
              this screen.
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
}

function LocalReviewsListEmpty({ onCreate }: { onCreate: () => void }) {
  return (
    <EmptyState
      icon={MonitorIcon}
      title="No local reviews yet."
      body="Local reviews let you walk your own branch diff before opening a PR. Notes you leave migrate as review comments when you ship it."
      action={
        <Button size="sm" onClick={onCreate}>
          <PlusIcon /> Create new local review
        </Button>
      }
    />
  );
}

// ── Row ──────────────────────────────────────────────────────────

function LocalReviewRow({
  review,
  rowState,
  onOpen,
  onDelete,
}: {
  review: LocalReview;
  /** Computed by `useLocalReviewRowStates` at the list level. Undefined
   *  on the web build (no bridge) — we render the default-state badge
   *  then. */
  rowState: LocalReviewRowState | undefined;
  onOpen: () => void;
  onDelete: () => void;
}) {
  // Phase 3 wired the live notes count via a per-row hook. Phase 7
  // batches that read into `useLocalReviewRowStates` at the list level
  // so each row receives state by prop. Keep `useLocalReviewCommentCount`
  // as a fallback for the (no-bridge) web build's count rendering.
  const fallbackCount = useLocalReviewCommentCount(review.id);
  const isDeleted = review.deleted === true;
  // Soft-deleted rows override the computed status badge with a dim
  // "Deleted" pill (the underlying status is meaningless when the repo
  // is gone — no diff to compute, no PR to check).
  const status = isDeleted ? 'ready' : (rowState?.status ?? 'ready');
  const ahead = rowState?.ahead ?? 0;
  const behind = rowState?.behind ?? 0;
  const notesTotal = rowState?.notesTotal ?? fallbackCount;
  const prNumber = rowState?.prNumber;
  const prHtmlUrl = rowState?.prHtmlUrl;
  const cfg = STATUS_CFG[status];
  const StatusIcon = cfg.icon;
  // Viewed-state tracking isn't part of local reviews v1; the column
  // renders `0 / 0` as a deliberate placeholder.
  const viewed = 0;
  const viewedOf = 0;
  const title = review.title ?? review.branch;
  const repoLabel = repoLabelFromPath(review.repoPath);

  const onOpenPR = () => {
    if (prHtmlUrl) window.open(prHtmlUrl, '_blank', 'noopener,noreferrer');
  };

  return (
    <div
      role={isDeleted ? undefined : 'button'}
      tabIndex={isDeleted ? -1 : 0}
      onClick={isDeleted ? undefined : onOpen}
      onKeyDown={
        isDeleted
          ? undefined
          : (e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onOpen();
              }
            }
      }
      className={
        isDeleted
          ? 'relative flex items-start gap-3 border-b px-5 py-3 opacity-60'
          : 'relative flex cursor-pointer items-start gap-3 border-b px-5 py-3 hover:bg-muted/40 focus:bg-muted/40 focus:outline-none'
      }
    >
      <StatusIcon className={`mt-0.5 size-4 shrink-0 ${cfg.iconColor}`} />
      <div className="min-w-0 flex-1">
        <div className="flex items-baseline gap-2">
          <span className="max-w-[540px] truncate text-[13.5px] font-semibold tracking-tight text-foreground">
            {title}
          </span>
          {isDeleted ? (
            <Badge variant="secondary">Deleted</Badge>
          ) : (
            <Badge variant={cfg.variant} className={cfg.badgeClass}>
              {cfg.label}
            </Badge>
          )}
          {/* `N behind` chip on stale rows (design's LOCAL_REVIEWS lr6
              shows a "142 behind" pill next to the Stale badge). */}
          {status === 'stale' && behind > 0 && (
            <Badge
              variant="outline"
              className="gap-1 border-pyor-warn/40 bg-pyor-warn/10 text-pyor-warn"
            >
              <ArrowDownIcon className="size-2.5" />
              {behind} behind
            </Badge>
          )}
          {/* PR-opened rows get a small "#<num>" chip per the design's
              LOCAL_REVIEWS fixture (the `pr-opened` entry shows
              `prNum: 1183`). */}
          {status === 'pr-opened' && prNumber != null && (
            <Badge variant="outline" className="gap-1 font-mono">
              <GitPullRequestIcon className="size-2.5" />#{prNumber}
            </Badge>
          )}
        </div>
        <div className="mt-1 flex items-center gap-2 text-[12px] text-muted-foreground">
          <span className="truncate" title={review.repoPath}>
            {repoLabel}
          </span>
          <span className="text-border">·</span>
          <span className="inline-flex items-center gap-1.5">
            <FolderIcon className="size-3 text-muted-foreground" />
            <span className="font-mono text-[11px] text-foreground">
              {review.branch}
            </span>
            <ChevronRightIcon className="size-2.5 text-muted-foreground" />
            <span className="font-mono text-[11px]">{review.base}</span>
          </span>
        </div>
      </div>
      <div className="flex shrink-0 items-center gap-4 text-[12px] tabular-nums text-muted-foreground">
        {/* Ahead / behind — design uses ↑N (emerald) ↓N (amber when >0,
            muted when 0). Phase 7 wires real counts via the row-state
            hook. */}
        <div className="min-w-[68px] text-right">
          <div className="text-[10.5px] text-muted-foreground/70">commits</div>
          <div className="font-mono text-[10.5px]">
            <span className={ahead > 0 ? 'text-pyor-pass' : 'text-muted-foreground/40'}>
              ↑{ahead}
            </span>{' '}
            <span className={behind > 0 ? 'text-pyor-warn' : 'text-muted-foreground/40'}>
              ↓{behind}
            </span>
          </div>
        </div>
        {/* +/− and files remain a v1 placeholder. Wiring this would mean
            running a full diff per row at list-render time — too
            expensive; defer to v2 if needed. */}
        <div className="min-w-[80px] text-right">
          <div className="text-[10.5px] text-muted-foreground/70">files</div>
          <div className="font-mono text-[10.5px] text-muted-foreground/50">
            —
          </div>
        </div>
        {/* Viewed progress — local reviews don't track viewed-state in
            v1 (PR-only concept today). Static 0/0 placeholder. */}
        <div className="min-w-[88px]">
          <div className="mb-0.5 flex items-baseline justify-between text-[10.5px] text-muted-foreground/70">
            <span>Viewed</span>
            <span className="font-mono tabular-nums">
              {viewed}/{viewedOf}
            </span>
          </div>
          <div className="h-1 overflow-hidden rounded-full bg-muted">
            <div className="h-full w-0 bg-foreground" />
          </div>
        </div>
        {/* Notes — wired in Phase 3, now reads off rowState.notesTotal
            (which counts both active + dismissed). */}
        <div className="min-w-[36px]">
          {notesTotal > 0 ? (
            <span className="inline-flex items-center gap-1">
              <MessageSquareIcon className="size-3.5 text-muted-foreground" />
              <span>{notesTotal}</span>
            </span>
          ) : (
            <span className="text-muted-foreground/50">—</span>
          )}
        </div>
        <div className="min-w-[64px] text-right text-muted-foreground/70" title={fullDate(review.createdAt)}>
          {timeAgo(review.createdAt)}
        </div>
      </div>
      <div onClick={(e) => e.stopPropagation()}>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="size-7 text-muted-foreground"
              aria-label="More actions"
            >
              <MoreHorizontalIcon />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            {!isDeleted && (
              <DropdownMenuItem onSelect={onOpen}>Open</DropdownMenuItem>
            )}
            {!isDeleted && prHtmlUrl && (
              <DropdownMenuItem onSelect={onOpenPR}>
                <ExternalLinkIcon /> Open PR on github.com
              </DropdownMenuItem>
            )}
            {!isDeleted && <DropdownMenuSeparator />}
            <DropdownMenuItem
              onSelect={onDelete}
              className="text-pyor-fail focus:text-pyor-fail"
            >
              <Trash2Icon /> Delete review
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
}

// ── Launcher wizard (full-surface, matches artboard 3 / 3a) ──────

function LauncherWizard({
  onCancel,
  onStart,
  onRequestAddRepo,
  fluid,
}: {
  onCancel: () => void;
  onStart: (review: LocalReview) => void;
  onRequestAddRepo: () => void;
  fluid?: boolean;
}) {
  // TanStack-cached repo list — keyed so `onConfirmAddRepo` can
  // invalidate via the same key and the launcher dropdown updates
  // without a full page reload.
  const repoListQuery = useQuery({
    queryKey: ['local-repo-list'] as const,
    queryFn: async () => {
      const b = bridge();
      return b ? b.localRepoList() : [];
    },
    staleTime: Infinity,
  });
  const repos = repoListQuery.data ?? null;
  const [selectedRepoPath, setSelectedRepoPath] = useState<string | null>(null);
  const [worktrees, setWorktrees] = useState<LocalWorktree[] | null>(null);
  const [selectedWorktreePath, setSelectedWorktreePath] = useState<
    string | null
  >(null);
  const [branches, setBranches] = useState<LocalBranch[] | null>(null);
  const [head, setHead] = useState<string | null>(null);
  const [base, setBase] = useState<string | null>(null);
  // Optional title for the review (shown like a PR title). Empty = the UI
  // falls back to the head branch name (the placeholder previews this).
  const [title, setTitle] = useState('');
  const createReview = useCreateLocalReview();
  // Cross-repo worktree count for the status bar — matches the design's
  // `git OK · N repos · M worktrees discovered` line.
  const worktreeCount = useWorktreeCount();

  // Auto-select the first repo once the list resolves (or after an
  // add: when the user picks a repo, registers, and the query
  // invalidates, the newly-added repo lands in the list — leave the
  // user's existing selection in place if any).
  useEffect(() => {
    if (!repos || repos.length === 0) return;
    if (selectedRepoPath && repos.some((r) => r.path === selectedRepoPath)) {
      return;
    }
    setSelectedRepoPath(repos[0].path);
    // selectedRepoPath intentionally excluded — first-resolve default only.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repos]);

  // When repo changes, fetch worktrees.
  useEffect(() => {
    if (!selectedRepoPath) {
      setWorktrees(null);
      setSelectedWorktreePath(null);
      return;
    }
    const b = bridge();
    if (!b) return;
    let cancelled = false;
    void b.localRepoWorktrees(selectedRepoPath).then((ws) => {
      if (cancelled) return;
      setWorktrees(ws);
      // Default to the main worktree (or the first one).
      const def = ws.find((w) => w.isMain) ?? ws[0];
      setSelectedWorktreePath(def?.path ?? null);
    });
    return () => {
      cancelled = true;
    };
  }, [selectedRepoPath]);

  // When worktree changes, fetch branches.
  useEffect(() => {
    if (!selectedWorktreePath) {
      setBranches(null);
      setHead(null);
      setBase(null);
      return;
    }
    const b = bridge();
    if (!b) return;
    let cancelled = false;
    void b.localRepoBranches(selectedWorktreePath).then((bs) => {
      if (cancelled) return;
      setBranches(bs);
      // Default head = the worktree's current branch (its `branch`
      // field), falling back to the first branch with isHead=true,
      // then the first branch in the list.
      const wt = worktrees?.find((w) => w.path === selectedWorktreePath);
      const defaultHead =
        wt?.branch ?? bs.find((b) => b.isHead)?.name ?? bs[0]?.name ?? null;
      setHead(defaultHead);
      // Default base = main / master / trunk, skipping the head.
      const defaultBase =
        bs.find(
          (b) =>
            (b.name === 'main' || b.name === 'master' || b.name === 'trunk') &&
            b.name !== defaultHead,
        )?.name ??
        bs.find((b) => b.name !== defaultHead)?.name ??
        null;
      setBase(defaultBase);
    });
    return () => {
      cancelled = true;
    };
  }, [selectedWorktreePath, worktrees]);

  const swap = () => {
    if (!head || !base) return;
    setHead(base);
    setBase(head);
  };

  const ready =
    !!selectedRepoPath &&
    !!selectedWorktreePath &&
    !!head &&
    !!base &&
    head !== base;

  const start = async () => {
    if (!ready) return;
    const trimmedTitle = title.trim();
    const review = await createReview.mutateAsync({
      repoPath: selectedRepoPath!,
      worktreePath: selectedWorktreePath!,
      branch: head!,
      base: base!,
      title: trimmedTitle ? trimmedTitle : undefined,
    });
    onStart(review);
  };

  // ⌘⏎ to confirm.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') {
        if (ready) {
          e.preventDefault();
          void start();
        }
      } else if (e.key === 'Escape') {
        onCancel();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ready, selectedRepoPath, selectedWorktreePath, head, base]);

  const selectedWorktree =
    worktrees?.find((w) => w.path === selectedWorktreePath) ?? null;
  const zeroWorktrees = worktrees != null && worktrees.length === 0;

  // Live working-tree diff for the selected worktree — drives the dirty
  // warning card. Cheap query; the bridge already memoises git output.
  const dirtyQuery = useQuery({
    queryKey: ['launcher-dirty', selectedWorktreePath],
    queryFn: async (): Promise<LocalDiffFile[]> => {
      const b = bridge();
      if (!b || !selectedWorktreePath) return [];
      return b.localRepoWorkingTreeDiff(selectedWorktreePath);
    },
    enabled: isElectron() && !!selectedWorktreePath,
  });
  const uncommittedCount = dirtyQuery.data?.length ?? 0;

  // Ahead/behind preview for the footer summary card. Same bridge call
  // the row state hook uses; cached separately by (worktree, base, head).
  const aheadBehindQuery = useQuery({
    queryKey: ['launcher-ahead-behind', selectedWorktreePath, base, head],
    queryFn: async () => {
      const b = bridge();
      if (!b || !selectedWorktreePath || !base || !head)
        return { ahead: 0, behind: 0 };
      return b.localRepoAheadBehind(selectedWorktreePath, base, head);
    },
    enabled:
      isElectron() && !!selectedWorktreePath && !!base && !!head && base !== head,
  });
  const aheadCount = aheadBehindQuery.data?.ahead ?? null;
  const behindCount = aheadBehindQuery.data?.behind ?? null;

  // Real commits preview for the "Commits to review" card. Cached per
  // (worktree, base, head); refetched when the user reshuffles refs.
  // Capped at 6 to match the design's "+ N earlier commits" footer.
  const COMMITS_PREVIEW_LIMIT = 6;
  const commitsQuery = useQuery({
    queryKey: [
      'launcher-commits',
      selectedWorktreePath,
      base,
      head,
      COMMITS_PREVIEW_LIMIT,
    ],
    queryFn: async () => {
      const b = bridge();
      if (!b || !selectedWorktreePath || !base || !head) return [];
      return b.localRepoCommits(
        selectedWorktreePath,
        base,
        head,
        COMMITS_PREVIEW_LIMIT,
      );
    },
    enabled:
      isElectron() &&
      !!selectedWorktreePath &&
      !!base &&
      !!head &&
      base !== head,
  });
  const commitsPreview = commitsQuery.data ?? [];

  // Status bar dot tinting per the launcher-empty artboard: amber when
  // there are zero worktrees discovered (the user needs to add a repo).
  const noWorktreesAtAll = worktreeCount === 0;
  return (
    <PyorWindow
      fluid={fluid}
      title="Local reviews"
      subtitle={
        noWorktreesAtAll
          ? 'No worktrees discovered'
          : 'Self-review before opening a PR'
      }
      status={
        <>
          <span className="inline-flex items-center gap-1.5">
            <span
              className={
                noWorktreesAtAll
                  ? 'size-1.5 rounded-full bg-pyor-warn'
                  : 'size-1.5 rounded-full bg-pyor-pass'
              }
            />
            git OK
            {repos != null && ` · ${repos.length} repos`}
            {worktreeCount != null &&
              ` · ${worktreeCount} worktrees discovered`}
          </span>
          <span className="ml-auto">
            No GitHub round-trip · everything below is local
          </span>
        </>
      }
    >
      <div className="flex-1 overflow-auto bg-muted/20 p-8">
        <div className="mx-auto max-w-2xl space-y-5">
          <div>
            <div className="mb-1 text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
              New local review
            </div>
            <h1 className="text-xl font-semibold tracking-tight">
              Review a local branch before opening a PR
            </h1>
            <p className="mt-1 text-[13px] leading-relaxed text-muted-foreground">
              Pick a repo, a worktree, and a head/base pair. Pyor renders the
              diff exactly like a real PR. Notes stay local until you open
              the PR — then they migrate.
            </p>
          </div>

          {zeroWorktrees ? (
            <LauncherEmptyState onAddRepo={onRequestAddRepo} />
          ) : (
            <Card>
              <CardHeader>
                <CardTitle>Repo, worktree &amp; refs</CardTitle>
                <CardDescription>
                  {repos != null && `${repos.length} repos registered`}
                  {worktreeCount != null &&
                    ` · ${worktreeCount} worktrees discovered on this machine.`}
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                <WizardField label="Title (optional)">
                  <Input
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder={head ?? 'A title for this review'}
                    className="h-9"
                  />
                </WizardField>
                <WizardField label="Repo">
                  <Select
                    value={selectedRepoPath ?? ''}
                    onValueChange={(v) => {
                      if (v === '__add__') {
                        onRequestAddRepo();
                        return;
                      }
                      setSelectedRepoPath(v);
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Pick a repo" />
                    </SelectTrigger>
                    <SelectContent>
                      {(repos ?? []).map((r) => (
                        <SelectItem key={r.path} value={r.path}>
                          <span className="inline-flex items-center gap-2">
                            <Laptop2Icon className="size-3.5 text-muted-foreground" />
                            <span>{r.name}</span>
                          </span>
                        </SelectItem>
                      ))}
                      <SelectItem value="__add__">
                        <span className="inline-flex items-center gap-2 text-foreground">
                          <FolderPlusIcon className="size-3.5" />
                          Add new repo…
                        </span>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </WizardField>

                {worktrees != null && worktrees.length > 1 && (
                  <WizardField label="Worktree">
                    <Select
                      value={selectedWorktreePath ?? ''}
                      onValueChange={setSelectedWorktreePath}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Pick a worktree" />
                      </SelectTrigger>
                      <SelectContent>
                        {worktrees.map((w) => (
                          <SelectItem key={w.path} value={w.path}>
                            <span className="inline-flex items-center gap-2">
                              <FolderIcon className="size-3.5 text-muted-foreground" />
                              <span className="font-mono text-[12px]">
                                {w.path}
                              </span>
                              {w.isMain && (
                                <Badge variant="outline" className="ml-1">
                                  main
                                </Badge>
                              )}
                            </span>
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </WizardField>
                )}
                {worktrees != null &&
                  worktrees.length === 1 &&
                  selectedWorktree && (
                    <WizardField label="Worktree">
                      <div className="flex items-center gap-2 rounded-md border bg-muted/30 px-3 py-2 text-[12.5px]">
                        <FolderIcon className="size-3.5 text-muted-foreground" />
                        <span className="truncate font-mono text-[12px]">
                          {selectedWorktree.path}
                        </span>
                      </div>
                    </WizardField>
                  )}

                <WizardField label="Head (the branch you're reviewing)">
                  <BranchPicker
                    branches={branches ?? []}
                    value={head}
                    onChange={setHead}
                    placeholder="Pick a head branch"
                  />
                </WizardField>

                <div className="flex justify-end">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={swap}
                    disabled={!head || !base}
                  >
                    <ArrowUpDownIcon /> Swap
                  </Button>
                </div>

                <WizardField label="Base (compare against)">
                  <BranchPicker
                    branches={(branches ?? []).filter((b) => b.name !== head)}
                    value={base}
                    onChange={setBase}
                    placeholder="Pick a base branch"
                  />
                </WizardField>
              </CardContent>
            </Card>
          )}

          {!zeroWorktrees && uncommittedCount > 0 && (
            <Card className="border-pyor-warn/30 bg-pyor-warn/10">
              <div className="flex items-start gap-2.5 p-3.5">
                <AlertTriangleIcon className="mt-0.5 size-4 shrink-0 text-pyor-warn" />
                <div className="flex-1 text-[12.5px] leading-relaxed text-pyor-warn">
                  <b className="font-semibold">
                    {uncommittedCount} uncommitted change
                    {uncommittedCount === 1 ? '' : 's'}
                  </b>{' '}
                  in this worktree. Pre-PR review compares{' '}
                  <code className="rounded bg-background/70 px-1 py-0.5 font-mono text-[11px]">
                    HEAD
                  </code>{' '}
                  against{' '}
                  <code className="rounded bg-background/70 px-1 py-0.5 font-mono text-[11px]">
                    {base ?? 'main'}
                  </code>{' '}
                  — uncommitted edits won't be in the committed diff. They
                  appear in the Uncommitted bucket of the review surface.
                </div>
              </div>
            </Card>
          )}

          {/* "Commits to review" — newest-first list, capped + "+N more"
              footer when the count exceeds the preview limit. Mirrors
              the ShadcnPrePRLauncherScreen card visual. */}
          {!zeroWorktrees && ready && (
            <div>
              <div className="mb-2 flex items-center gap-2">
                <span className="text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Commits to review
                </span>
                {aheadCount != null && (
                  <Badge variant="secondary">{aheadCount}</Badge>
                )}
              </div>
              <Card className="overflow-hidden">
                {commitsQuery.isPending && (
                  <div className="px-3.5 py-4 text-center text-[11.5px] text-muted-foreground">
                    Computing range…
                  </div>
                )}
                {!commitsQuery.isPending && commitsPreview.length === 0 && (
                  <div className="px-3.5 py-4 text-center text-[11.5px] text-muted-foreground">
                    {aheadCount === 0
                      ? `No new commits on ${head} relative to ${base}.`
                      : `${aheadCount ?? 0} commit${aheadCount === 1 ? '' : 's'} between ${base} and ${head}.`}
                  </div>
                )}
                {!commitsQuery.isPending && commitsPreview.length > 0 && (
                  <>
                    {commitsPreview.map((c, i) => (
                      <div
                        key={c.sha}
                        className={`flex items-center gap-3 px-3.5 py-2 text-[12.5px] ${
                          i > 0 ? 'border-t border-border/60' : ''
                        }`}
                      >
                        <code className="w-16 shrink-0 font-mono text-[11px] text-muted-foreground">
                          {c.sha.slice(0, 7)}
                        </code>
                        <span className="flex-1 truncate text-foreground">
                          {c.subject}
                        </span>
                        <span className="shrink-0 text-[11px] text-muted-foreground">
                          {c.ago}
                        </span>
                        <DiffStat
                          additions={c.additions}
                          deletions={c.deletions}
                          addClassName="text-pyor-pass"
                          delClassName="text-pyor-fail"
                          className="w-20 shrink-0 justify-end text-right text-[11px]"
                        />
                      </div>
                    ))}
                    {aheadCount != null &&
                      aheadCount > commitsPreview.length && (
                        <div className="border-t border-border/60 bg-muted/40 px-3.5 py-1.5 text-center text-[11.5px] text-muted-foreground">
                          + {aheadCount - commitsPreview.length} earlier
                          commit
                          {aheadCount - commitsPreview.length === 1
                            ? ''
                            : 's'}
                        </div>
                      )}
                  </>
                )}
              </Card>
            </div>
          )}

          {!zeroWorktrees && (
            <Card>
              <div className="flex flex-wrap items-center gap-3 p-4">
                <div className="min-w-0 flex-1">
                  <div className="text-[12.5px] text-muted-foreground">
                    You're about to review
                  </div>
                  <div className="mt-1 flex flex-wrap items-center gap-2 text-[13.5px] font-semibold">
                    <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-[12px]">
                      {head ?? '—'}
                    </code>
                    <ChevronRightIcon className="size-3 text-muted-foreground" />
                    <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-[12px]">
                      {base ?? '—'}
                    </code>
                    {aheadCount != null && (
                      <span className="text-[12px] font-normal text-muted-foreground">
                        · {aheadCount} commit{aheadCount === 1 ? '' : 's'}
                      </span>
                    )}
                    {/* TODO Phase 8: file + +/- stats once the diff
                        preview lands at launcher time (currently the
                        diff query only runs on the review surface). */}
                  </div>
                  {behindCount != null && behindCount > 0 && (
                    <div className="mt-1 text-[11.5px] text-pyor-warn">
                      {behindCount} behind {base} — consider rebasing first.
                    </div>
                  )}
                </div>
                <Button variant="ghost" size="sm" onClick={onCancel}>
                  Cancel
                </Button>
                <Button
                  size="sm"
                  onClick={() => void start()}
                  disabled={!ready || createReview.isPending}
                >
                  <PlayIcon /> Start review
                  <span className="ml-1.5 inline-flex gap-0.5">
                    <Kbd>⌘</Kbd>
                    <Kbd>⏎</Kbd>
                  </span>
                </Button>
              </div>
            </Card>
          )}
        </div>
      </div>
    </PyorWindow>
  );
}

/** Searchable branch picker for the launcher. Branches are sorted
 * most-recent-first (by committer date) and each row shows its age; the
 * cmdk input filters by name. Replaces the plain Select so a repo with
 * hundreds of branches stays navigable. */
function BranchPicker({
  branches,
  value,
  onChange,
  placeholder,
}: {
  branches: LocalBranch[];
  value: string | null;
  onChange: (name: string) => void;
  placeholder: string;
}) {
  const [open, setOpen] = useState(false);
  const sorted = useMemo(
    () =>
      [...branches].sort((a, b) => (b.date ?? '').localeCompare(a.date ?? '')),
    [branches],
  );
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className="h-9 w-full justify-between font-normal"
        >
          <span className="inline-flex min-w-0 items-center gap-2">
            <GitBranchIcon className="size-3.5 shrink-0 text-muted-foreground" />
            <span
              className={`truncate font-mono text-[12px] ${
                value ? '' : 'text-muted-foreground'
              }`}
            >
              {value ?? placeholder}
            </span>
          </span>
          <ChevronDownIcon className="size-3.5 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className="w-[var(--radix-popover-trigger-width)] p-0"
        align="start"
      >
        <Command>
          <CommandInput placeholder="Search branches…" className="h-9" />
          <CommandList>
            <CommandEmpty>No branches found.</CommandEmpty>
            <CommandGroup>
              {sorted.map((b) => (
                <CommandItem
                  key={b.name}
                  value={b.name}
                  onSelect={() => {
                    onChange(b.name);
                    setOpen(false);
                  }}
                  className="gap-2"
                >
                  <GitBranchIcon className="size-3.5 shrink-0 text-muted-foreground" />
                  <span className="truncate font-mono text-[12px]">
                    {b.name}
                  </span>
                  {b.isHead && (
                    <Badge variant="outline" className="ml-1 shrink-0">
                      HEAD
                    </Badge>
                  )}
                  {b.date && (
                    <span
                      className="ml-auto shrink-0 text-[11px] text-muted-foreground"
                      title={fullDate(b.date)}
                    >
                      {relTime(b.date)}
                    </span>
                  )}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

function WizardField({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}) {
  return (
    <div className="space-y-1.5">
      <label className="text-[12px] font-semibold text-muted-foreground">
        {label}
      </label>
      {children}
    </div>
  );
}

function LauncherEmptyState({ onAddRepo }: { onAddRepo: () => void }) {
  return (
    <>
      <EmptyState
        icon={FolderIcon}
        title="Add a repo to start your first local review."
        body="Pyor looks for git repos in the folder you pick. Got multiple repos in one place? Pyor finds them all."
        action={
          <Button size="sm" onClick={onAddRepo}>
            <PlusIcon /> Add repo…
          </Button>
        }
      />
      <Card>
        <div className="flex items-start gap-2.5 p-4">
          <InfoIcon className="mt-0.5 size-4 shrink-0 text-blue-600" />
          <div className="text-[12.5px] leading-relaxed text-muted-foreground">
            <b className="font-semibold text-foreground">Heads up:</b> local
            reviews stay local. Pyor never reads files outside the worktrees
            you've added, and never makes a GitHub request from this screen.
          </div>
        </div>
      </Card>
    </>
  );
}

// ── Delete confirmation ──────────────────────────────────────────

function DeleteReviewDialog({
  review,
  onCancel,
  onConfirm,
  pending,
}: {
  review: LocalReview | null;
  onCancel: () => void;
  onConfirm: () => void;
  pending: boolean;
}) {
  return (
    <AlertDialog open={!!review} onOpenChange={(o) => !o && onCancel()}>
      <AlertDialogContent className="max-w-[440px]">
        <AlertDialogHeader>
          <AlertDialogTitle>Delete this local review?</AlertDialogTitle>
          <AlertDialogDescription>
            The review entry is removed from Pyor. Comments attached to it
            (Phase 3) would also be deleted. Your git branch is not touched.
          </AlertDialogDescription>
        </AlertDialogHeader>
        {review && (
          <div className="rounded-md border bg-muted/30 p-3">
            <div className="truncate text-[13px] font-semibold">
              {review.title ?? review.branch}
            </div>
            <div className="mt-1 truncate font-mono text-[11.5px] text-muted-foreground">
              {review.branch} → {review.base}
            </div>
          </div>
        )}
        <AlertDialogFooter>
          <AlertDialogCancel asChild>
            <Button variant="ghost" size="sm">
              Cancel
            </Button>
          </AlertDialogCancel>
          {/* preventDefault: keep open while the delete mutation runs;
              the caller closes it once it resolves. */}
          <AlertDialogAction asChild>
            <Button
              variant="destructive"
              size="sm"
              onClick={(e) => {
                e.preventDefault();
                onConfirm();
              }}
              disabled={pending}
            >
              <Trash2Icon /> Delete
            </Button>
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

// ── Add-repo dialog (reused from v1) ──────────────────────────────
//
// Three visual states, gated by the validation kind:
//   - picking   — spinner while the native folder picker is open
//   - valid     — confirm card with the discovered repo info
//   - not-git   — error card with "Try another folder"
//   - no-base   — warning card explaining no base branch was found
//
// Per ADR 0011 the dialog is built from shadcn primitives only;
// tints come from the existing pyor-pass / pyor-warn / pyor-fail
// CSS variables exposed as Tailwind utilities.

function AddRepoDialog({
  open,
  state,
  onClose,
  onBrowse,
  onConfirm,
  onConfirmBulk,
}: {
  /** Drives the dialog; the parent keeps this mounted while it animates
   * closed (see `addingState`/`lastAddingRef`). */
  open: boolean;
  state: AddRepoState;
  onClose: () => void;
  onBrowse: () => void;
  onConfirm: (path: string) => void | Promise<void>;
  /** Bulk-register every discovered repo when the multi-repo card
   * confirms. Called with the absolute path of each discovered repo. */
  onConfirmBulk: (paths: string[]) => void | Promise<void>;
}) {
  // The design treats the dialog as a multi-field form, not a
  // confirmation card. Folder input + Browse, colored validation
  // card per state, default base branch, watch settings, footer
  // metadata line. The picker fires from inside via Browse.
  //
  // Watch settings are currently visual-only — no persistence
  // layer yet for per-repo prefs. Wiring lands in a follow-up once
  // we have a place to store them (per-repo Settings or a section
  // in user prefs).
  //
  // The 'multi' branch short-circuits everything below the input row
  // (no per-repo base branch, no watch settings) since the user is
  // bulk-registering — those settings are per-repo and would have to
  // be edited individually anyway, post-add.
  const multiState =
    state !== 'idle' && state !== 'picking' && state.kind === 'multi'
      ? state
      : null;
  const isMulti = multiState !== null;
  const pathFromState =
    state === 'idle' || state === 'picking'
      ? ''
      : state.kind === 'multi'
        ? state.folderPath
        : state.path;
  const validatedKind =
    state === 'idle' || state === 'picking' ? null : state.kind;
  const suggestedBase =
    state !== 'idle' && state !== 'picking' && state.kind === 'valid'
      ? state.suggestedBase ?? ''
      : '';
  const [baseInput, setBaseInput] = useState(suggestedBase);
  const [watchFolder, setWatchFolder] = useState(true);
  const [includeUncommitted, setIncludeUncommitted] = useState(true);
  const [autoFetch, setAutoFetch] = useState(false);
  // Re-sync `baseInput` whenever the validation result changes
  // (different picker → different suggested base).
  useEffect(() => {
    setBaseInput(suggestedBase);
  }, [suggestedBase]);
  const canAdd =
    validatedKind === 'valid' ||
    validatedKind === 'no-base' ||
    validatedKind === 'multi';
  const validation = validationFor(state);
  const multiCount =
    state !== 'idle' && state !== 'picking' && state.kind === 'multi'
      ? state.repos.length
      : 0;
  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-w-[580px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FolderPlusIcon className="size-4 text-muted-foreground" />
            Add a repository
          </DialogTitle>
          <DialogDescription>
            Pyor indexes git repos under the path you pick. Got multiple?
            Pyor finds them all.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-3.5">
          {/* Folder input + Browse */}
          <div className="space-y-1.5">
            <Label htmlFor="add-repo-folder">Folder</Label>
            <div className="flex items-center gap-2">
              <div className="relative flex-1">
                <FolderPlusIcon className="absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
                <Input
                  id="add-repo-folder"
                  value={pathFromState}
                  placeholder="Click Browse… or paste an absolute path"
                  readOnly
                  className="pl-7 font-mono text-[12px]"
                />
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={onBrowse}
                disabled={state === 'picking'}
              >
                {state === 'picking' ? (
                  <>
                    <Loader2 className="animate-spin" /> Browsing…
                  </>
                ) : (
                  'Browse…'
                )}
              </Button>
            </div>
          </div>
          {/* Multi-repo card — emerald-tinted summary + scrollable list
              of every discovered repo under the picked folder. */}
          {multiState && (
            <div className="space-y-2">
              <div className="flex items-start gap-2.5 rounded-md border border-pyor-pass/40 bg-pyor-pass/10 p-3">
                <CheckCircle2Icon className="mt-0.5 size-4 shrink-0 text-pyor-pass" />
                <div className="min-w-0 flex-1 space-y-0.5">
                  <div className="text-[13px] font-semibold">
                    Found {multiState.repos.length} git repos under this path
                  </div>
                  <div className="text-[12.5px] text-muted-foreground leading-relaxed">
                    Pyor will register each repo. You can start a local
                    review on any of them from the launcher.
                  </div>
                </div>
              </div>
              <div className="max-h-[260px] overflow-auto rounded-md border">
                  {multiState.repos.map((r, i) => (
                    <div
                      key={r.path}
                      className={
                        i > 0
                          ? 'flex items-center gap-2 border-t px-3 py-2 text-[12.5px]'
                          : 'flex items-center gap-2 px-3 py-2 text-[12.5px]'
                      }
                    >
                      <FolderIcon className="size-3.5 shrink-0 text-muted-foreground" />
                      <div className="min-w-0 flex-1">
                        <div className="truncate font-medium">{r.name}</div>
                        <div className="truncate font-mono text-[10.5px] text-muted-foreground">
                          {r.path}
                        </div>
                      </div>
                      {r.currentBranch && (
                        <Badge variant="outline" className="gap-1 font-mono">
                          <GitBranchIcon className="size-2.5" />
                          {r.currentBranch}
                        </Badge>
                      )}
                      {r.dirty && (
                        <Badge
                          variant="outline"
                          className="border-pyor-warn/40 bg-pyor-warn/10 text-pyor-warn"
                        >
                          dirty
                        </Badge>
                      )}
                    </div>
                  ))}
                </div>
            </div>
          )}
          {/* Single-repo validation card — only after a path is chosen
              and we're NOT in the multi-repo branch. */}
          {!isMulti && validation && (
            <div
              className={`flex items-start gap-2.5 rounded-md border p-3 ${validation.tint}`}
            >
              <validation.Icon
                className={`mt-0.5 size-4 shrink-0 ${validation.iconClass}`}
              />
              <div className="min-w-0 flex-1 space-y-0.5">
                <div className="text-[13px] font-semibold">
                  {validation.title}
                </div>
                <div className="text-[12.5px] text-muted-foreground leading-relaxed">
                  {validation.body}
                </div>
              </div>
            </div>
          )}
          {/* Default base branch + watch settings — only shown in the
              single-repo flow; multi-repo skips these since they're
              per-repo settings and would have to be edited individually
              after registration anyway. */}
          {!isMulti && (
            <>
              <div className="space-y-1.5">
                <Label htmlFor="add-repo-base">Default base branch</Label>
                <div className="relative">
                  <GitBranchIcon className="absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    id="add-repo-base"
                    value={baseInput}
                    placeholder={
                      validatedKind === 'no-base' ? '— none —' : 'main'
                    }
                    onChange={(e) => setBaseInput(e.target.value)}
                    disabled={!validatedKind}
                    className="pl-7 font-mono text-[12px]"
                  />
                </div>
                <p className="text-[11.5px] text-muted-foreground">
                  Used as the comparison base when you start a local review.
                </p>
              </div>
              <div className="space-y-2 rounded-md border bg-muted/40 p-3">
                <label className="flex cursor-pointer items-center gap-2 text-[12px]">
                  <Checkbox
                    checked={watchFolder}
                    onCheckedChange={(c) => setWatchFolder(c === true)}
                  />
                  <span>Watch this folder for new branches</span>
                </label>
                <label className="flex cursor-pointer items-center gap-2 text-[12px]">
                  <Checkbox
                    checked={includeUncommitted}
                    onCheckedChange={(c) => setIncludeUncommitted(c === true)}
                  />
                  <span>Include uncommitted edits in diff by default</span>
                </label>
                <label className="flex cursor-pointer items-center gap-2 text-[12px]">
                  <Checkbox
                    checked={autoFetch}
                    onCheckedChange={(c) => setAutoFetch(c === true)}
                  />
                  <span>Auto-fetch every 5 minutes</span>
                </label>
              </div>
            </>
          )}
        </div>
        <DialogFooter className="!justify-between">
          <span className="hidden text-[11.5px] text-muted-foreground sm:inline">
            Stored at{' '}
            <code className="font-mono">
              ~/Library/Application Support/Pyor/local-repos.json
            </code>
          </span>
          <div className="ml-auto flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={onClose}>
              Cancel
            </Button>
            <Button
              size="sm"
              disabled={!canAdd}
              onClick={() => {
                if (state === 'idle' || state === 'picking') return;
                if (state.kind === 'multi') {
                  void onConfirmBulk(state.repos.map((r) => r.path));
                  return;
                }
                void onConfirm(state.path);
              }}
            >
              <FolderPlusIcon />{' '}
              {isMulti ? `Add ${multiCount} repos` : 'Add repo'}
            </Button>
          </div>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

interface ValidationView {
  title: string;
  body: React.ReactNode;
  /** Tailwind classes for the card chrome (border + bg). */
  tint: string;
  /** Tailwind text color class for the leading icon. */
  iconClass: string;
  /** Lucide icon component. */
  Icon: typeof CheckCircle2Icon;
}

function validationFor(state: AddRepoState): ValidationView | null {
  if (state === 'idle' || state === 'picking') return null;
  // Multi-repo gets its own custom card in the dialog body; this helper
  // only produces single-repo validation chrome.
  if (state.kind === 'multi') return null;
  switch (state.kind) {
    case 'valid': {
      const meta = state.meta;
      return {
        Icon: CheckCircle2Icon,
        title: 'Valid repository',
        body: (
          <>
            git repo
            {meta.currentBranch && (
              <>
                {' · '}current branch{' '}
                <span className="font-mono text-foreground">
                  {meta.currentBranch}
                </span>
              </>
            )}
            {state.suggestedBase && (
              <>
                {' · '}suggested base{' '}
                <span className="font-mono text-foreground">
                  {state.suggestedBase}
                </span>
              </>
            )}
            {meta.dirty
              ? ' · working tree has uncommitted changes'
              : ' · clean working tree'}
          </>
        ),
        tint: 'border-pyor-pass/40 bg-pyor-pass/10',
        iconClass: 'text-pyor-pass',
      };
    }
    case 'not-git':
      return {
        Icon: XCircleIcon,
        title: 'Not a git repository',
        body: (
          <>
            No{' '}
            <code className="rounded bg-background/60 px-1 py-0.5 font-mono text-[11px]">
              .git
            </code>{' '}
            directory found in the selected folder. Run{' '}
            <code className="rounded bg-background/60 px-1 py-0.5 font-mono text-[11px]">
              git init
            </code>{' '}
            or pick a different path.
          </>
        ),
        tint: 'border-pyor-fail/40 bg-pyor-fail/10',
        iconClass: 'text-pyor-fail',
      };
    case 'no-base':
      return {
        Icon: AlertTriangleIcon,
        title: 'No remote base branch',
        body: (
          <>
            The repo doesn&apos;t track a remote — Pyor can show you local
            diffs but can&apos;t help open a PR until you{' '}
            <code className="rounded bg-background/60 px-1 py-0.5 font-mono text-[11px]">
              git push -u origin main
            </code>
            .
          </>
        ),
        tint: 'border-pyor-warn/40 bg-pyor-warn/10',
        iconClass: 'text-pyor-warn',
      };
  }
}

/** Local pre-PR review surface — the chrome (toolbar, status bar,
 * watcher, Create-PR + export actions) + the PrePR header, with the
 * Changes body delegated to <LocalReviewChanges>, which drives the SAME
 * production ChangesTab the GitHub PR detail uses (file rail + diff +
 * inline comments), offline, via the native-git batch bridge. The commit
 * dropdown in that toolbar is the single scope control (all changes / a
 * commit-range / uncommitted) — superseding the old rail-scope tabs.
 *
 * The chokidar watcher invalidates the diff / working-tree / wt-contents
 * queries on FS change so the diff + staleness chips stay reactive. No
 * manual "Refresh diff" button — the design is reactive (per ADR).
 */
// Stable empty file list. The Changes body withholds files until contents
// are ready, but an INLINE `[]` fallback would mint a fresh array every
// render — churning ChangesTab's `files`→`activeFiles`→`matchSummary`, which
// re-fires the search-summary effect on every render and blows React's
// update-depth limit during a slow load. One shared reference fixes it.
const EMPTY_GH_FILES: never[] = [];
export function LocalReviewSurface({
  review,
  onBack,
  onRequestDelete,
  fluid,
}: {
  review: LocalReview;
  onBack: () => void;
  onRequestDelete: () => void;
  fluid?: boolean;
}) {
  const repoPath = review.worktreePath;
  const head = review.branch;
  const base = review.base;
  const qc = useQueryClient();
  const headerScroll = useHeaderScroll();
  const [tab, setTab] = useState<LocalTab>('changes');
  const [pushing, setPushing] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const exportReview = useExportLocalReview(review);
  const handleRef = useRef<string | null>(null);
  const [watching, setWatching] = useState(false);

  // Changes-tab scope + toolbar UI state — owned HERE (mirrors
  // PRDetailScreen owning `tab` + the commit scope together) so the commit
  // dropdown can live in the tab strip and the Commits tab can drive it.
  const [scopeSel, setScopeSel] = useState<CommitScopeSelection>(null);
  const [diffMode, setDiffMode] = useState<DiffMode>('split');
  const [search, setSearch] = useState<string | null>(null);
  const [fileFilter, setFileFilter] = useState<string | undefined>(undefined);
  const [railMode, setRailMode] = useState<'tree' | 'list'>('tree');
  const [searchSummary, setSearchSummary] = useState({ count: 0, fileCount: 0 });

  const rowStateForReview = useLocalReviewRowState(review);
  // The data engine: local-git queries + scope resolution + native-git
  // content load + viewed-state + the local annotation layer.
  const changes = useLocalChanges({ review, repoPath, base, head, scopeSel });

  // Per-file comment counts for the file-rail badge (mirrors the PR detail
  // rail). React Query dedupes this with the annotation layer's own read.
  const reviewComments = useLocalReviewComments(review.id);
  const commentCountByPath = useMemo(() => {
    const m = new Map<string, number>();
    (reviewComments.data ?? []).forEach((c) => {
      if (c.dismissed) return; // addressed notes don't badge the rail
      m.set(c.path, (m.get(c.path) ?? 0) + 1);
    });
    return m;
  }, [reviewComments.data]);

  // Origin-on-remote detection (ADR 0012 Phase 8): real ls-remote call.
  const branchOnOriginQuery = useQuery({
    queryKey: ['local-branch-on-origin', review.worktreePath, review.branch],
    queryFn: async () => {
      const b = bridge();
      if (!b) return false;
      return b.localRepoBranchOnOrigin(review.worktreePath, review.branch);
    },
    enabled: isElectron(),
    staleTime: 5 * 60 * 1000,
    refetchOnWindowFocus: true,
  });

  // ── Watcher wiring ─────────────────────────────────────────────────
  // Chokidar watcher rooted at the worktree; FS-change events invalidate
  // the diff / working-tree / commit-list / wt-contents queries so the
  // diff + staleness chips stay reactive (200ms debounce in main.ts).
  useEffect(() => {
    const b = bridge();
    if (!b) return;
    let cancelled = false;
    let unsubscribe: (() => void) | null = null;
    (async () => {
      try {
        const handle = await b.localRepoWatch(repoPath);
        if (cancelled) {
          void b.localRepoUnwatch(handle);
          return;
        }
        handleRef.current = handle;
        setWatching(true);
        unsubscribe = b.onLocalRepoChange((payload) => {
          if (payload.handleId !== handle) return;
          // A change under `.git/` (commit / fetch / ref update) is the
          // only signal the committed diff + commit list may have moved;
          // working-tree edits only touch the uncommitted bucket.
          const isGitMeta =
            payload.path.includes('/.git/') || payload.path.endsWith('/.git');
          if (isGitMeta) {
            void qc.invalidateQueries({
              queryKey: ['local-review', review.id, 'diff'],
            });
            void qc.invalidateQueries({
              queryKey: ['local-review', review.id, 'commit-list'],
            });
          }
          void qc.invalidateQueries({
            queryKey: ['local-review', review.id, 'working-tree'],
          });
          void qc.invalidateQueries({
            queryKey: ['local-review', review.id, 'wt-contents'],
          });
        });
      } catch (e) {
        // eslint-disable-next-line no-console
        console.warn('localRepoWatch failed', e);
      }
    })();
    return () => {
      cancelled = true;
      if (unsubscribe) unsubscribe();
      const h = handleRef.current;
      handleRef.current = null;
      setWatching(false);
      if (h) void b.localRepoUnwatch(h);
    };
  }, [repoPath, review.id, qc]);

  // On tab switch the new tab restores its own scroll without firing a
  // scroll event — re-read it so the morph reflects it (mirrors PR detail).
  const headerResync = headerScroll.resync;
  useEffect(() => {
    const id = window.setTimeout(() => headerResync(), 60);
    return () => window.clearTimeout(id);
  }, [tab, headerResync]);

  // Soft-deleted review — guard rendered AFTER all hooks (so hook order
  // stays stable) when the repo Pyor indexed is gone.
  if (review.deleted) {
    return (
      <PyorWindow fluid={fluid} title="Local review" subtitle="Deleted">
        <EmptyState
          icon={Laptop2Icon}
          iconClassName="text-muted-foreground"
          title="This repo isn't registered anymore"
          body="Delete this local review, or re-add the repo to make this surface usable again."
          action={
            <>
              <Button variant="outline" size="sm" onClick={onBack}>
                Back
              </Button>
              <Button variant="destructive" size="sm" onClick={onRequestDelete}>
                <Trash2Icon /> Delete this local review
              </Button>
            </>
          }
        />
      </PyorWindow>
    );
  }

  const diff = changes.diff;
  const error = changes.error;
  const pushed =
    branchOnOriginQuery.data === true ||
    rowStateForReview.data?.prNumber != null;
  const totalAdditions = diff?.files.reduce((s, f) => s + f.additions, 0) ?? 0;
  const totalDeletions = diff?.files.reduce((s, f) => s + f.deletions, 0) ?? 0;

  const onCreatePR = async () => {
    const b = bridge();
    if (!b) return;
    setPushing(true);
    try {
      await b.localRepoOpenCreatePR(repoPath, head, base);
      toast.success('Push complete', {
        description: 'Opening the GitHub Create-PR page in your browser…',
      });
    } catch (e) {
      toast.error('Could not push branch', {
        description: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setPushing(false);
    }
  };

  const onExport = async () => {
    setExporting(true);
    try {
      await exportReview({
        headSha: diff?.head ?? '',
        fileCount: diff?.files.length,
      });
    } catch {
      // Hook already surfaced an error toast.
    } finally {
      setExporting(false);
    }
  };

  // Commits-tab → Changes: scope the diff to a single commit.
  const scopeToCommit = (sha: string) => {
    setTab('changes');
    setScopeSel(new Set([sha]));
  };

  const allPaths = changes.files.map((f) => f.filename);

  // The Changes-tab toolbar — lives in the tab strip's right slot (like
  // the GitHub PR path). The commit dropdown is the single scope control.
  const changesToolbar = (
    <CompactChangesToolbar
      diffMode={diffMode}
      onDiffModeChange={setDiffMode}
      search={search}
      onSearchChange={setSearch}
      searchMatchCount={searchSummary.count}
      searchMatchFileCount={searchSummary.fileCount}
      commits={changes.commitCount}
      viewed={changes.viewedCount}
      totalFiles={changes.totalFiles}
      overallViewed={changes.overallViewedCount}
      overallTotal={changes.overallTotalFiles}
      scoped={changes.isScoped}
      commitList={changes.commitList}
      showUncommittedOption
      selectedCommitShas={scopeSel}
      onSelectedCommitShasChange={setScopeSel}
      baseRef={base}
      headRef={head}
      baseSha={changes.oldRef}
      headSha={changes.anchorHead}
      contentsProgress={
        changes.contentsProgress.total > 0 &&
        changes.contentsProgress.resolved < changes.contentsProgress.total
          ? changes.contentsProgress
          : undefined
      }
      isFilesLoading={changes.filesLoading}
      onCollapseAll={
        allPaths.length > 0
          ? () => changes.collapseState.collapseAll(allPaths)
          : undefined
      }
      onExpandAll={
        allPaths.length > 0
          ? () => changes.collapseState.expandAll(allPaths)
          : undefined
      }
      onResetCollapse={changes.collapseState.resetAll}
    />
  );

  const headerActions = (
    <>
      <Button
        variant="ghost"
        size="sm"
        onClick={() => void onExport()}
        disabled={exporting}
      >
        <DownloadIcon />
        {exporting ? 'Exporting…' : 'Export…'}
      </Button>
      <Button size="sm" onClick={() => setCreateOpen(true)} disabled={pushing}>
        <GitPullRequestIcon />
        {pushed ? 'Create PR…' : 'Push & PR…'}
      </Button>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="size-7 text-muted-foreground"
            aria-label="More actions"
          >
            <MoreHorizontalIcon />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem
            onSelect={onRequestDelete}
            className="text-pyor-fail focus:text-pyor-fail"
          >
            <Trash2Icon /> Delete review
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </>
  );

  return (
    <ReviewLayout
      fluid={fluid}
      status={
        <LocalSurfaceStatusBar
          watching={watching}
          base={base}
          head={head}
          baseSha={diff?.base ?? null}
          headSha={diff?.head ?? null}
          pushed={pushed}
        />
      }
      overlay={
        <CreatePRDialog
          open={createOpen}
          onOpenChange={setCreateOpen}
          review={review}
          head={head}
          base={base}
          pushed={pushed}
          pushing={pushing}
          noteCount={rowStateForReview.data?.notesActive ?? 0}
          onConfirm={async () => {
            await onCreatePR();
            setCreateOpen(false);
          }}
        />
      }
    >
      {error ? (
        <EmptyState
          icon={Laptop2Icon}
          iconClassName="text-destructive"
          title="Couldn't compute diff"
          body={error}
          action={
            <Button variant="outline" size="sm" onClick={onBack}>
              Back
            </Button>
          }
        />
      ) : !diff ? (
        <div className="flex-1 p-6 text-center text-[13px] text-muted-foreground">
          Computing diff…
        </div>
      ) : (
        <ReviewLayoutHeader
          scroll={headerScroll}
          full={
            <>
              <PrePRHeader
                review={review}
                head={head}
                base={base}
                ahead={rowStateForReview.data?.ahead ?? null}
                behind={rowStateForReview.data?.behind ?? null}
                additions={totalAdditions}
                deletions={totalDeletions}
                files={diff.files.length}
                uncommitted={changes.uncommittedCount}
                pushed={pushed}
                onBack={onBack}
                actions={headerActions}
              />
              <LocalReviewTabStrip
                active={tab}
                onChange={setTab}
                changesCount={changes.totalFiles}
                commitsCount={changes.commitCount}
                toolbar={changesToolbar}
              />
            </>
          }
          compact={
            <LocalCompactHeader
              head={head}
              base={base}
              additions={totalAdditions}
              deletions={totalDeletions}
              activeTab={tab}
              onTabChange={setTab}
              onBack={onBack}
              changesControls={
                <>
                  <CommitSelector
                    commits={changes.commitCount}
                    baseRef={base}
                    headRef={head}
                    baseSha={changes.oldRef}
                    headSha={changes.anchorHead}
                    selectedShas={scopeSel}
                    onSelectedShasChange={setScopeSel}
                    commitList={changes.commitList}
                    showUncommittedOption
                  />
                  <Separator orientation="vertical" className="h-4" />
                  <ScopedViewed
                    overallViewed={changes.overallViewedCount}
                    overallTotal={changes.overallTotalFiles}
                    scopeViewed={changes.viewedCount}
                    scopeTotal={changes.totalFiles}
                    scoped={changes.isScoped}
                  />
                  <Separator orientation="vertical" className="h-4" />
                  <CompactDiffModeToggle
                    value={diffMode}
                    onChange={setDiffMode}
                  />
                </>
              }
            />
          }
        >
          {/* Overview */}
          <div
            className={
              'absolute inset-0 flex min-h-0 flex-col' +
              (tab === 'overview' ? '' : ' pointer-events-none invisible')
            }
          >
            <LocalOverviewPanel
              reviewId={review.id}
              viewerLogin={changes.viewerLogin}
              anchorHead={changes.anchorHead ?? diff.head}
              worktreePath={repoPath}
              fileContents={changes.fileContents}
              patchByPath={changes.patchByPath}
              head={head}
              base={base}
              ahead={rowStateForReview.data?.ahead ?? null}
              behind={rowStateForReview.data?.behind ?? null}
              additions={totalAdditions}
              deletions={totalDeletions}
              files={diff.files.length}
              uncommitted={changes.uncommittedCount}
              pushed={pushed}
              onExport={() => void onExport()}
              onCreatePR={() => setCreateOpen(true)}
              exporting={exporting}
            />
          </div>
          {/* Commits */}
          <div
            className={
              'absolute inset-0 flex min-h-0 flex-col' +
              (tab === 'commits' ? '' : ' pointer-events-none invisible')
            }
          >
            <LocalCommitsPanel
              commits={changes.commitList}
              onSelectCommit={scopeToCommit}
            />
          </div>
          {/* Changes — kept mounted (content-visibility) so the diff
              virtualizer keeps its geometry + scroll across tab switches. */}
          <div
            className={
              'absolute inset-0 flex min-h-0 flex-col' +
              (tab === 'changes'
                ? ''
                : ' pointer-events-none [content-visibility:hidden]')
            }
          >
            <ChangesTab
              // Remount when the loaded content version changes (scope
              // switch / load complete) so the diff renders fresh from the
              // full contents — @pierre/diffs leaves stale file-header
              // counts in the DOM across an in-place placeholder→real swap
              // (the "deploy-pages.yml shows +1" desync); a clean mount
              // sidesteps it, matching the PR path's remount-on-change fix.
              key={changes.modelHeadSha ?? 'local-changes'}
              active={tab === 'changes'}
              externalScope
              annotationLayer={changes.annotationLayer}
              commentCountByPath={commentCountByPath}
              readOnly={false}
              // Withhold files until contents are ready so buildDiffItems
              // runs ONCE with full content (no placeholder→real pass that
              // desyncs @pierre/diffs' file-header counts vs body). The
              // rail/diff show a skeleton during the (fast) load instead.
              files={changes.fileContents ? changes.files : EMPTY_GH_FILES}
              fileContents={changes.fileContents}
              patchByPath={changes.patchByPath}
              isFilesLoading={changes.filesLoading || !changes.fileContents}
              isContentsLoading={changes.contentsLoading}
              viewedState={changes.viewedState}
              collapseState={changes.collapseState}
              baseSha={changes.modelBaseSha}
              headSha={changes.modelHeadSha}
              baseRef={base}
              headRef={head}
              commitCount={changes.commitCount}
              viewerLogin={changes.viewerLogin}
              diffMode={diffMode}
              onDiffModeChange={setDiffMode}
              searchQuery={search ?? undefined}
              onSearchQueryChange={(q) => setSearch(q ?? null)}
              fileFilter={fileFilter}
              onFileFilterChange={setFileFilter}
              railMode={railMode}
              onRailModeChange={setRailMode}
              onSearchSummaryChange={setSearchSummary}
            />
          </div>
        </ReviewLayoutHeader>
      )}
    </ReviewLayout>
  );
}

