// Provider-adapter interface (ADR 0026). Feature code (grouping / hints /
// chat) stays provider-agnostic; each provider (Anthropic, OpenAI) is one
// implementation behind this. We use the two official first-party SDKs
// rather than a unification lib specifically to keep Anthropic prompt
// caching (cache_control) on the shared diff+file-context prefix.

import type { AiProvider } from '../settings/aiSettings';

/** Normalized error kinds → mapped to AiRunState / AiKeyStatus in the UI.
 * Errors use amber+zinc, never red. */
export type AiErrorKind =
  | 'invalid-key'
  | 'billing'
  | 'rate-limited'
  | 'overloaded'
  | 'network'
  | 'unknown';

export class AiError extends Error {
  kind: AiErrorKind;
  /** Seconds to wait, when the provider returned a Retry-After. */
  retryAfter?: number;
  constructor(kind: AiErrorKind, message: string, retryAfter?: number) {
    super(message);
    this.kind = kind;
    this.retryAfter = retryAfter;
  }
}

export interface TokenUsage {
  inputTokens: number;
  outputTokens: number;
  /** Anthropic only — tokens served from the prompt cache (~0.1× cost). */
  cacheReadTokens?: number;
}

export interface CompleteResult<T> {
  data: T;
  usage: TokenUsage;
  /** The concrete model id the provider actually ran. */
  model: string;
}

export interface CompleteArgs {
  /** Large, stable-for-one-SHA prefix (diff + file context). Cached on
   * Anthropic via cache_control; benefits OpenAI's automatic prefix cache. */
  contextBlock: string;
  /** The feature-specific instruction (small, varies grouping vs hints). */
  instruction: string;
  /** JSON Schema the response must satisfy (validated by the caller). */
  schema: Record<string, unknown>;
  /** Schema name (OpenAI requires one). */
  schemaName: string;
  maxTokens?: number;
  signal?: AbortSignal;
}

export interface CuratedModel {
  id: string;
  label: string;
}

export interface ProviderAdapter {
  provider: AiProvider;
  /** The concrete default model id used when the user hasn't overridden. */
  defaultModel: string;
  /** Validate the key with a cheap call. Throws AiError on failure. */
  testKey(): Promise<void>;
  /** A short curated list of the provider's current models for the override
   * select. Best-effort from the live models endpoint; falls back to a
   * static seed. Never throws. */
  listModels(): Promise<CuratedModel[]>;
  /** Schema-validated structured completion (grouping clusters / hints). */
  complete<T = unknown>(args: CompleteArgs): Promise<CompleteResult<T>>;
  /** Pre-run input-token count. Exact for Anthropic (count_tokens), an
   * estimate for OpenAI (no count endpoint) — `exact` flags which. */
  countInputTokens(contextBlock: string, instruction: string): Promise<{ tokens: number; exact: boolean }>;
}
