// Open a URL in the user's real browser.
//
// On Electron we must hand off to the OS browser (the GitHub authorize page,
// Polar checkout) rather than navigating the app window — via the
// `openExternal` bridge method. On web, a plain new tab.

import { bridge } from './electronBridge';

export function openExternalUrl(url: string): void {
  const b = bridge();
  if (b) {
    void b.openExternal(url);
    return;
  }
  window.open(url, '_blank', 'noopener,noreferrer');
}
