// Display card for a saved LocalReviewComment. Renders one card per
// comment — multiple comments on the same anchor stack vertically.
//
// Design parity: gh-comments.jsx · GhComment — the same rich card the
// PR threads use. Per ADR 0012 the local surface stays single-body (no
// thread chrome, no reply, no reactions, no resolve), so the card
// passes none of those handlers; it keeps the local-only affordances
// instead: a "Mark as addressed" kebab item, a delete confirm, and the
// staleness chip. The stack is wrapped in a pyor-warn rail so it stays
// visually distinct from GitHub PR threads (which use a blue accent).
//   - Addressed comments tint green (GhComment highlight="resolved")
//     and carry an "addressed" chip.
//   - Edit swaps the body for a GhComposer (⌘⏎ saves, Esc cancels,
//     paste-to-attach preserved).
//   - Delete confirms via a shadcn Dialog.

import { useState } from 'react';
import { humanAge } from '../../util/relTime';
import { CheckCircle2 } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { DropdownMenuItem } from '@/components/ui/dropdown-menu';
import { Markdown } from '../../ui/Markdown';
import { plainTextPreview } from '../../github/reactionHelpers';
import { GhComment } from '../conversation/GhComment';
import { GhComposer } from '../conversation/GhComposer';
import type { LocalReviewComment } from '../../review/localReviewComments';
import type { StalenessResult } from '../../review/localReviewStaleness';
import { localReviewUploader } from '../../review/pasteAttachment';
import { fullDate } from '../../util/relTime';
import {
  useDeleteLocalReviewComment,
  useUpdateLocalReviewComment,
} from '../../review/useLocalReviewComments';

interface Props {
  comment: LocalReviewComment;
  /** ADR 0012 Phase 4 — optional staleness classification for this
   * comment. When undefined, no chip renders. `fresh` also renders no
   * chip — the chip only surfaces when the anchor has drifted
   * (`moved`) or detached (`stale`). */
  staleness?: StalenessResult;
  /** Diff context rendered INSIDE the comment body (the shared
   * `DiffHunkSnippet`), exactly like the GitHub thread card. */
  diffSlice?: React.ReactNode;
}

export function LocalCommentCard({ comment, staleness, diffSlice }: Props) {
  const [editing, setEditing] = useState(false);
  const [confirmingDelete, setConfirmingDelete] = useState(false);

  const update = useUpdateLocalReviewComment();
  const del = useDeleteLocalReviewComment();

  const isEdited = comment.updatedAt !== comment.createdAt;
  const showStaleness = staleness && staleness.state !== 'fresh';

  const onToggleDismissed = () => {
    update.mutate({
      reviewId: comment.reviewId,
      commentId: comment.id,
      patch: { dismissed: !comment.dismissed },
    });
  };

  const onDelete = () => {
    del.mutate(
      { reviewId: comment.reviewId, commentId: comment.id },
      { onSuccess: () => setConfirmingDelete(false) },
    );
  };

  const verdictChip =
    comment.dismissed || showStaleness ? (
      <div className="flex items-center gap-1.5">
        {showStaleness && <StalenessChip staleness={staleness} />}
        {comment.dismissed && (
          <Badge
            variant="outline"
            className="gap-1 border-transparent bg-pyor-pass/15 px-1.5 py-0 text-[10px] font-semibold text-pyor-pass"
          >
            <CheckCircle2 className="size-2.5" />
            addressed
          </Badge>
        )}
      </div>
    ) : undefined;

  return (
    <>
      <GhComment
        author={comment.authorLogin}
        age={`${humanAge(comment.createdAt)} ago`}
        ageTitle={fullDate(comment.createdAt)}
        edited={isEdited ? humanAge(comment.updatedAt) : null}
        editedTitle={fullDate(comment.updatedAt)}
        highlight={comment.dismissed ? 'resolved' : null}
        verdictChip={verdictChip}
        preview={plainTextPreview(comment.body)}
        previewSource={comment.body}
        diffSlice={diffSlice}
        canEdit
        onEdit={() => setEditing(true)}
        onDelete={() => setConfirmingDelete(true)}
        showModerationItems={false}
        extraMenuItems={
          <DropdownMenuItem onClick={onToggleDismissed}>
            <CheckCircle2 className="size-3.5" />
            {comment.dismissed ? 'Mark as unaddressed' : 'Mark as addressed'}
          </DropdownMenuItem>
        }
        editing={editing}
        editor={
          <GhComposer
            variant="inline"
            draftKey={`local:${comment.reviewId}:edit:${comment.id}`}
            initialBody={comment.body}
            submitLabel="Save"
            submitIcon="check"
            autoFocus
            minHeight={84}
            onUploadImage={localReviewUploader(comment.reviewId, comment.id)}
            onCancel={() => setEditing(false)}
            onSubmit={async (body) => {
              const next = body.trim();
              if (!next || next === comment.body) {
                setEditing(false);
                return;
              }
              await update.mutateAsync({
                reviewId: comment.reviewId,
                commentId: comment.id,
                patch: { body: next },
              });
              setEditing(false);
            }}
          />
        }
      >
        <div className={comment.dismissed ? 'opacity-60' : ''}>
          <Markdown source={comment.body} size="sm" />
        </div>
      </GhComment>

      <AlertDialog
        open={confirmingDelete}
        onOpenChange={(o) => !o && setConfirmingDelete(false)}
      >
        <AlertDialogContent className="max-w-[420px]">
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this note?</AlertDialogTitle>
            <AlertDialogDescription>
              The note is removed from this local review. This can't be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel asChild>
              <Button variant="ghost" size="sm" disabled={del.isPending}>
                Cancel
              </Button>
            </AlertDialogCancel>
            {/* preventDefault: keep the dialog open until the delete
                mutation succeeds (onDelete closes it via onSuccess). */}
            <AlertDialogAction asChild>
              <Button
                variant="destructive"
                size="sm"
                onClick={(e) => {
                  e.preventDefault();
                  onDelete();
                }}
                disabled={del.isPending}
              >
                Delete
              </Button>
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

/** A stack of local-comment cards in the SAME card shell the GitHub
 * inline threads use (ReviewThread, no-anchor variant): a bordered,
 * rounded `bg-card` container with the `font-sans whitespace-normal`
 * reset that undoes the diff CodeView's mono/pre context. Keeps the
 * surfaces visually identical — only the card body (the shared GhComment)
 * was ever common before. */
export function LocalCommentStack({
  comments,
  stalenessFor,
  diffSliceFor,
}: {
  comments: LocalReviewComment[];
  /** ADR 0012 Phase 4 — optional per-comment staleness lookup. When
   * omitted, no chips render (back-compat with non-local callers). */
  stalenessFor?: (commentId: string) => StalenessResult | undefined;
  /** Diff context for the anchor. Like the GitHub thread, the hunk shows
   * on the FIRST comment only (the rest share the same anchor). */
  diffSliceFor?: (comment: LocalReviewComment) => React.ReactNode;
}) {
  if (comments.length === 0) return null;
  return (
    <div className="mx-3 mb-3 mt-1.5 box-border max-w-full overflow-hidden whitespace-normal rounded-lg border bg-card font-sans text-[13px] shadow-sm dark:shadow-none">
      <div className="space-y-2 p-2">
        {comments.map((c, i) => (
          <LocalCommentCard
            key={c.id}
            comment={c}
            staleness={stalenessFor?.(c.id)}
            diffSlice={i === 0 ? diffSliceFor?.(c) : undefined}
          />
        ))}
      </div>
    </div>
  );
}

/** Per-comment chip surfacing a non-fresh staleness state next to the
 * author row. Colour-coded per ADR 0012 Phase 4:
 *   - `moved` → amber (pyor-warn) "Moved · was @ N"
 *   - `stale` → red (pyor-fail) "Stale"
 * `fresh` never renders a chip (caller filters it out). */
function StalenessChip({ staleness }: { staleness: StalenessResult }) {
  if (staleness.state === 'moved') {
    return (
      <Badge
        variant="secondary"
        className="border-pyor-warn/40 bg-pyor-warn/10 px-1.5 py-0 text-[10.5px] font-medium text-pyor-warn"
        title={`This note was anchored at line ${staleness.wasLine}; the matching text now lives at line ${staleness.nowLine}.`}
      >
        Moved · was @ {staleness.wasLine}
      </Badge>
    );
  }
  return (
    <Badge
      variant="secondary"
      className="border-pyor-fail/40 bg-pyor-fail/10 px-1.5 py-0 text-[10.5px] font-medium text-pyor-fail"
      title="The line this note anchored to was changed by a later commit — the original text is no longer present."
    >
      Outdated
    </Badge>
  );
}

