// App shell — the persistent chrome around the routed <Outlet/>.
//
// Replaces the old App.tsx `Shell()` state machine (AFK plan 26). The
// URL is now the source of truth; this component only:
//   - renders the persistent sidebar (hidden on /setup) and computes
//     the active nav highlight from the current route,
//   - wires the cross-cutting keyboard + command-palette navigation
//     to the router (`navigate()` / `router.history.back()`),
//   - mounts the worker-pool prewarm on the post-Setup surfaces,
//   - relays the Electron notification deep-link into a navigate.

import { lazy, Suspense, useEffect, useState } from 'react';
import {
  useNavigate,
  useRouterState,
  useCanGoBack,
  useRouter,
} from '@tanstack/react-router';
import { useTheme } from '../theme/ThemeProvider';
import { useDiffThemeSync } from '../theme/useDiffThemeSync';
import { AppNavProvider, type AppNavCtx } from './AppNav';
import { AppSidebar, type AppNavKey } from './AppSidebar';
import { TooltipProvider } from '@/components/ui/tooltip';
import { OfflineBanner } from './OfflineBanner';
import { useRegisterCommand } from './CommandPalette';
import { TitlebarSlotContext } from './titlebarSlot';
import { bridge, isElectron } from '../desktop/electronBridge';
import { cn } from '@/lib/utils';
import { useDeepLink } from '../desktop/useDeepLink';
import { useQueryClient } from '@tanstack/react-query';
import type { GHNotification } from '../github/types';
import type { PRTab } from '../pr/PRTabs';
import { openPR } from '../router/nav';
import { INBOX_DEFAULTS, PULLS_DEFAULTS } from '../router/search';
import { HelperNudge } from '../onboarding/HelperNudge';

const WorkerPoolPrewarm = lazy(() =>
  import('../pr/changes/WorkerPoolPrewarm').then((m) => ({
    default: m.WorkerPoolPrewarm,
  })),
);

/** Map the current pathname to the sidebar nav-key (or null when the
 * route has no sidebar representation, e.g. /setup). PR detail keeps
 * the inbox/pulls item active based on its `from` search param. */
function activeNavKey(
  pathname: string,
  from: 'inbox' | 'pulls' | undefined,
): AppNavKey | null {
  if (pathname.startsWith('/inbox')) return 'inbox';
  if (pathname.startsWith('/pulls')) return 'pulls';
  if (pathname.startsWith('/local')) return 'local';
  if (pathname.startsWith('/settings')) return 'settings';
  if (pathname === '/setup') return null;
  // PR detail (`/owner/repo/number`) — highlight where the user came
  // from. Default to pulls (historical back affordance).
  return from === 'inbox' ? 'inbox' : 'pulls';
}

export function Shell({ children }: { children: React.ReactNode }) {
  const { dark, setDark } = useTheme();
  // Bind the diff code viewer's Shiki theme to the app's light/dark mode
  // (pierre-dark / pierre-light). Renders nothing. (Carried over from #34,
  // which called this in the pre-router Shell in App.tsx.)
  useDiffThemeSync();
  const navigate = useNavigate();
  const router = useRouter();
  const canGoBack = useCanGoBack();
  const queryClient = useQueryClient();
  // DOM node of the full-width titlebar strip — screens portal their
  // titlebar content here via PyorWindow (see titlebarSlot). A state-backed
  // callback ref so consumers re-render once the strip mounts.
  const [titlebarSlot, setTitlebarSlot] = useState<HTMLElement | null>(null);

  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const search = useRouterState({ select: (s) => s.location.search }) as {
    from?: 'inbox' | 'pulls';
  };
  const isSetup = pathname === '/setup';
  // Pre-auth screens render chromeless (no sidebar): the PAT setup screen
  // plus the GitHub sign-in flow (/welcome, /connect/*). ADR 0019.
  const isPreAuth =
    isSetup || pathname === '/welcome' || pathname.startsWith('/connect');
  const isPRDetail =
    !isPreAuth &&
    !pathname.startsWith('/inbox') &&
    !pathname.startsWith('/pulls') &&
    !pathname.startsWith('/local') &&
    !pathname.startsWith('/settings') &&
    pathname !== '/';
  const activeKey = activeNavKey(pathname, search.from);
  // Prewarm the @pierre/diffs worker pool on the surfaces that lead
  // into a diff view (Pulls / PR detail / local review / Settings
  // preview) — exactly the set the pre-router App.tsx gated on. The
  // Inbox is deliberately excluded: it never renders a diff, and
  // eagerly importing @pierre/diffs there pulls its CJS deps before
  // anything needs them (see vite optimizeDeps note for the lru_map /
  // @pierre/theme interop this avoids triggering early).
  const wantPrewarm =
    isPRDetail ||
    pathname.startsWith('/pulls') ||
    pathname.startsWith('/local') ||
    pathname.startsWith('/settings');

  // Native notification deep-link (Electron only). The main process
  // sends `notification:click` with the notification's GitHub thread
  // id (== GHNotification.id). We resolve the corresponding cached
  // notification to extract owner/repo/number + sensible tab, then
  // navigate. If the notification isn't in cache we fall back to the
  // Inbox so the user can see the activity.
  useEffect(() => {
    const b = bridge();
    if (!b) return;
    const off = b.onNotificationClick((threadId) => {
      const items = queryClient.getQueryData<GHNotification[]>([
        'notifications',
      ]);
      const n = items?.find((x) => x.id === threadId);
      if (!n) {
        void navigate({ to: '/inbox', search: INBOX_DEFAULTS });
        return;
      }
      const m = n.subject.url?.match(
        /\/repos\/([^/]+)\/([^/]+)\/pulls\/(\d+)/,
      );
      if (!m) {
        void navigate({ to: '/inbox', search: INBOX_DEFAULTS });
        return;
      }
      const tab: PRTab =
        n.reason === 'review_requested' ? 'changes' : 'description';
      openPR(navigate, {
        owner: m[1],
        repo: m[2],
        number: Number(m[3]),
        tab,
        from: 'inbox',
      });
    });
    return off;
  }, [queryClient, navigate]);

  // ADR 0019 — `pyor://` OAuth callback deep-links → /connect/callback.
  useDeepLink();

  // Command-palette navigation commands → router navigate.
  useRegisterCommand(
    {
      id: 'nav:inbox',
      label: 'Go to Inbox',
      hint: 'Notifications feed',
      action: () => void navigate({ to: '/inbox', search: INBOX_DEFAULTS }),
      keywords: 'inbox notifications',
    },
    [navigate],
  );
  useRegisterCommand(
    {
      id: 'nav:pulls',
      label: 'Go to Pull requests',
      hint: 'My PRs · Reviewing',
      action: () => void navigate({ to: '/pulls', search: PULLS_DEFAULTS }),
      keywords: 'pulls pr pull requests',
    },
    [navigate],
  );
  useRegisterCommand(
    {
      id: 'nav:local',
      label: 'Go to Local reviews',
      hint: 'Pre-PR review',
      action: () => void navigate({ to: '/local' }),
      keywords: 'local pre-pr',
    },
    [navigate],
  );
  useRegisterCommand(
    {
      id: 'nav:settings',
      label: 'Go to Settings',
      action: () => void navigate({ to: '/settings' }),
      keywords: 'settings preferences',
    },
    [navigate],
  );
  useRegisterCommand(
    {
      id: 'theme:toggle',
      label: 'Toggle theme',
      hint: 'Light / Dark',
      action: () => setDark(!dark),
      shortcut: '⌘⇧T',
      keywords: 'theme dark light',
    },
    [dark, setDark],
  );

  // ⌘⇧T theme toggle (cheap dev affordance, retained from App.tsx).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (
        e.shiftKey &&
        (e.metaKey || e.ctrlKey) &&
        e.key.toLowerCase() === 't'
      ) {
        e.preventDefault();
        setDark(!dark);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [dark, setDark]);

  // ⇧⌘B — back. PRHeaderActions renders the visible "← Inbox" button;
  // this is the matching keyboard path for power users. Routes through
  // the router history so it mirrors the browser back button.
  useEffect(() => {
    if (!isPRDetail) return;
    const onKey = (e: KeyboardEvent) => {
      if (
        e.shiftKey &&
        (e.metaKey || e.ctrlKey) &&
        e.key.toLowerCase() === 'b'
      ) {
        e.preventDefault();
        if (canGoBack) {
          router.history.back();
        } else if (search.from === 'inbox') {
          // No prior history entry (cold deep-link) — fall back to
          // the origin screen recorded in `from`.
          void navigate({ to: '/inbox', search: INBOX_DEFAULTS });
        } else {
          void navigate({ to: '/pulls', search: PULLS_DEFAULTS });
        }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [isPRDetail, canGoBack, router, navigate, search.from]);

  // Shared navigation context for the sidebar. null on /setup (no
  // sidebar there). The sidebar now navigates via typed <Link>s that
  // carry each route's default search params (see AppSidebar), so this
  // context only conveys optional badge counts.
  const appNav: AppNavCtx | null = isPreAuth ? null : {};

  // Pre-auth screens (setup + GitHub sign-in flow) render without the
  // persistent sidebar.
  if (isPreAuth) {
    return (
      <TooltipProvider delayDuration={0}>
        <AppNavProvider value={appNav}>
          <div className="fixed inset-0 flex flex-col bg-background font-sans">
            {children}
          </div>
        </AppNavProvider>
      </TooltipProvider>
    );
  }

  // Full-width titlebar strip across the top, above the navbar. Screens
  // portal their title/toolbar into the slot below (see titlebarSlot). The
  // slot self-sizes: on web it collapses to nothing when empty (`:empty`)
  // so screens with their own page header — PR detail (hideTitlebar) —
  // show no bar; on desktop it always keeps the bar so the macOS
  // traffic-light controls have a home and the window stays draggable.
  const electron = isElectron();
  return (
    <TooltipProvider delayDuration={0}>
      <AppNavProvider value={appNav}>
        <TitlebarSlotContext.Provider value={titlebarSlot}>
          <div className="fixed inset-0 flex flex-col bg-background font-sans">
            <div
              ref={setTitlebarSlot}
              className={cn(
                'flex w-full min-w-0 shrink-0 items-stretch',
                electron
                  ? // Desktop: persistent bar; left padding clears the
                    // traffic-light controls (~66px from the window edge);
                    // whole strip drags (toolbar opts out in TitlebarContent).
                    'h-[38px] border-b bg-muted/40 pl-[60px] [-webkit-app-region:drag]'
                  : // Web: only a bar when a screen actually fills it.
                    '[&:not(:empty)]:h-[38px] [&:not(:empty)]:border-b [&:not(:empty)]:bg-muted/40',
              )}
            />
            <div className="flex min-h-0 flex-1">
              <AppSidebar active={activeKey ?? 'inbox'} badges={appNav?.badges} />
              <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
                <OfflineBanner />
                {/* Prewarm the @pierre/diffs worker pool on diff-adjacent
                    surfaces. Renders nothing; keeps the singleton alive
                    across navigation so the first PR open isn't a flash of
                    unhighlighted code. Gated to match the pre-router
                    App.tsx (Inbox excluded — see wantPrewarm). */}
                {wantPrewarm && (
                  <Suspense fallback={null}>
                    <WorkerPoolPrewarm />
                  </Suspense>
                )}
                <div className="min-h-0 flex-1 overflow-hidden">{children}</div>
              </div>
            </div>
            {/* Pyor Helper first-run nudge (ADR 0024) — desktop-only,
                show-once, and self-gating (renders nothing on web, on an
                unsupported default browser, or once dismissed). Kept out of
                the pre-auth flow. */}
            {!isPreAuth && <HelperNudge />}
          </div>
        </TitlebarSlotContext.Provider>
      </AppNavProvider>
    </TooltipProvider>
  );
}
