// Navigation helpers shared across screens.
//
// Centralises the "open a PR" navigation shape so the Inbox, Pulls,
// command palette, and the Electron notification deep-link all build
// the same path + search params. The built search carries the route's
// explicit defaults (tab + diff) so the resulting link is already
// canonical — `/owner/repo/123?tab=description&diff=split` — and the
// route's `beforeLoad` has nothing to fix up on arrival.

import { linkOptions, type useNavigate } from '@tanstack/react-router';
import type { PRTab } from '../pr/PRTabs';
import type { PRSearch } from './search';
import { PR_DEFAULTS } from './search';

type NavigateFn = ReturnType<typeof useNavigate>;

/** A live diff anchor written to the URL on interaction. A comment
 * anchor sets `commentId` (acid) — which wins precedence over a bare
 * line on restore. `null` clears the anchor entirely. */
export interface DiffAnchor {
  path: string;
  line?: number | null;
  side?: 'LEFT' | 'RIGHT' | null;
  /** Numeric review-comment id (thread head). */
  commentId?: number;
}

export interface OpenPRArgs {
  owner: string;
  repo: string;
  number: number;
  tab?: PRTab;
  from?: 'inbox' | 'pulls';
  anchor?: {
    path: string;
    line?: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
    commentId?: number;
  };
}

/** Build the PR-detail search params from an open-PR request, seeded
 * with the route defaults so the link is canonical (defaults explicit). */
function prSearchFromArgs(args: OpenPRArgs): PRSearch {
  const search: PRSearch = {
    ...PR_DEFAULTS,
    tab: args.tab ?? PR_DEFAULTS.tab,
  };
  if (args.from) search.from = args.from;
  if (args.anchor) {
    search.apath = args.anchor.path;
    if (args.anchor.line != null) search.aline = args.anchor.line;
    if (args.anchor.diffSide) search.aside = args.anchor.diffSide;
    if (args.anchor.commentId) search.acid = args.anchor.commentId;
  }
  return search;
}

export function prLinkProps(args: OpenPRArgs) {
  return linkOptions({
    to: '/$owner/$repo/$number',
    params: {
      owner: args.owner,
      repo: args.repo,
      number: String(args.number),
    },
    search: prSearchFromArgs(args),
  });
}

/** Navigate to a PR detail. Used by every "open this PR" call-site. */
export function openPR(navigate: NavigateFn, args: OpenPRArgs): void {
  void navigate(prLinkProps(args));
}
