// React Query hooks for the Team review-radar. The orgs query is the
// keystone: the teammate-PR search depends on the viewer's org logins, so
// it chains off `useViewerOrgs`.

import { useInfiniteQuery, useQuery } from '@tanstack/react-query';
import { getViewer } from '../../github/client';
import {
  fetchTeamFacets,
  fetchTeamPRs,
  fetchViewerOrgs,
  fetchViewerRepoActivity,
  type TeamFilters,
  type TeamOrg,
} from '../../github/teamLens';

/** Matches the Pulls list poll cadence. */
const TEAM_POLL_MS = 60_000;

/** Orgs the viewer belongs to. Long stale time — membership rarely
 * changes within a session, and both the PR search and the badge fan
 * out from this. */
export function useViewerOrgs() {
  return useQuery({
    queryKey: ['team', 'orgs'],
    queryFn: fetchViewerOrgs,
    staleTime: 5 * 60_000,
  });
}

/** Your per-repo activity weights — drive the author-rail ranking
 * (collaborators in the repos you actually work in surface first).
 * Changes slowly; cache long. */
export function useViewerRepoActivity() {
  return useQuery({
    queryKey: ['team', 'viewer-activity'],
    queryFn: fetchViewerRepoActivity,
    staleTime: 30 * 60_000,
  });
}

/** The authenticated user's login — replaces the handoff's `YOU`. */
export function useViewerLogin() {
  return useQuery({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: Infinity,
    select: (v) => v.login,
  });
}

/** Teammate PRs across the viewer's orgs, filtered server-side and
 * cursor-paginated for infinite scroll. Every filter is in the query
 * key, so changing one re-fetches a complete (not page-limited) result.
 * Polls while the tab is foregrounded, like the Pulls list. */
export function useTeamPRs(
  orgs: TeamOrg[] | undefined,
  you: string | undefined,
  filters: TeamFilters,
) {
  const orgLogins = (orgs ?? []).map((o) => o.key);
  return useInfiniteQuery({
    // `v2` namespaces the paginated shape away from any persisted cache
    // written by the earlier non-paginated (plain-array) version of this
    // query — hydrating that old shape would crash getNextPageParam.
    // Still prefix-matched by the `['team','prs']` invalidation below.
    queryKey: ['team', 'prs', 'v2', orgLogins, you, filters],
    queryFn: ({ pageParam }) =>
      fetchTeamPRs(orgLogins, you ?? '', filters, pageParam),
    initialPageParam: null as string | null,
    getNextPageParam: (last) => (last.hasNextPage ? last.endCursor : null),
    enabled: orgLogins.length > 0 && !!you,
    refetchInterval: TEAM_POLL_MS,
    refetchIntervalInBackground: false,
    placeholderData: (prev) => prev,
  });
}

/** Candidate authors / repos / labels for the filter controls, scoped
 * only by org + status + date (not by the narrowing filters). Re-fetches
 * when that scope changes. */
export function useTeamFacets(
  orgs: TeamOrg[] | undefined,
  you: string | undefined,
  scope: TeamFilters,
) {
  const orgLogins = (orgs ?? []).map((o) => o.key);
  return useQuery({
    queryKey: ['team', 'facets', orgLogins, you, scope],
    queryFn: () => fetchTeamFacets(orgLogins, scope, you ?? ''),
    enabled: orgLogins.length > 0 && !!you,
    staleTime: TEAM_POLL_MS,
    placeholderData: (prev) => prev,
  });
}
