// Pyor Helper first-run nudge (ADR 0024, design screen 5).
//
// A one-time, show-once moment inside the desktop app offering the browser
// Helper for the user's DEFAULT browser (detected in the main process via
// `app.getApplicationNameForProtocol('https://')`). One CTA → the browser's
// store listing; dismiss → never shown again. Desktop-only, and only when
// the default browser is one we can target (Safari/unknown → nothing).
//
// There is no app↔extension channel, so we can't detect whether the Helper
// is already installed — hence show-once + manual dismiss rather than
// install-aware gating.

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ShieldCheckIcon } from 'lucide-react';
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { PyorMark } from '../auth/PyorMark';
import { bridge, isElectron } from '../desktop/electronBridge';
import { openExternalUrl } from '../desktop/openExternal';
import { BrowserGlyph } from './BrowserGlyph';

const SEEN_KEY = 'pyor:helper-nudge-seen';

function readSeen(): boolean {
  try {
    return localStorage.getItem(SEEN_KEY) === '1';
  } catch {
    return false;
  }
}

export function HelperNudge() {
  // Seeded from localStorage so a returning user never re-opens it; the only
  // local state, since "seen" must persist across launches.
  const [dismissed, setDismissed] = useState(readSeen);

  const { data } = useQuery({
    queryKey: ['helper', 'default-browser'],
    queryFn: () => bridge()!.helperDefaultBrowser(),
    enabled: isElectron() && !dismissed,
    staleTime: Infinity,
  });

  const open = !dismissed && !!data?.supported;

  const dismiss = () => {
    try {
      localStorage.setItem(SEEN_KEY, '1');
    } catch {
      /* ignore */
    }
    setDismissed(true);
  };

  const addToBrowser = () => {
    if (data?.url) openExternalUrl(data.url);
    dismiss();
  };

  if (!data?.supported) return null;

  return (
    <Dialog open={open} onOpenChange={(o) => !o && dismiss()}>
      <DialogContent
        showCloseButton={false}
        from="bottom"
        className="gap-0 overflow-hidden p-0 sm:max-w-[400px]"
      >
        {/* Visual header — brand wash, mark → browser glyph */}
        <div className="relative flex h-28 items-center justify-center gap-4 border-b bg-gradient-to-b from-emerald-500/15 to-muted/40">
          <PyorMark size={48} className="rounded-[12px]" />
          <span className="flex items-center gap-1.5">
            {[0, 1, 2].map((i) => (
              <span
                key={i}
                className="size-[5px] rounded-full bg-emerald-500"
                style={{ opacity: 0.3 + i * 0.3 }}
              />
            ))}
          </span>
          <span className="inline-flex size-14 items-center justify-center rounded-[15px] border bg-card shadow-sm">
            <BrowserGlyph kind={data.glyph} size={34} />
          </span>
        </div>

        {/* Body */}
        <div className="px-5 pb-5 pt-[18px]">
          <div className="mb-2.5 inline-flex items-center gap-1.5 text-[10.5px] font-semibold uppercase tracking-[0.6px] text-emerald-700 dark:text-emerald-400">
            <span className="size-[5px] rounded-full bg-emerald-500" />
            One-time setup
          </div>
          <DialogTitle className="text-[19px] font-semibold tracking-tight">
            Add Pyor to {data.name}
          </DialogTitle>
          <DialogDescription className="mt-2 text-[13px] leading-relaxed text-muted-foreground">
            Open PR links in Pyor automatically. The Helper sends{' '}
            <code className="font-mono text-[11px]">github.com</code> pull
            requests straight here — no more bouncing through GitHub's heavy PR
            UI.
          </DialogDescription>

          <div className="mt-[18px] flex gap-2.5">
            <Button className="h-10 flex-1 gap-2" onClick={addToBrowser}>
              <BrowserGlyph kind={data.glyph} size={18} />
              Add to {data.name}
            </Button>
            <Button
              variant="outline"
              className="h-10 px-4 text-muted-foreground"
              onClick={dismiss}
            >
              Not now
            </Button>
          </div>

          <div className="mt-3 flex items-center gap-1.5 text-[11px] text-muted-foreground/80">
            <ShieldCheckIcon className="size-3" />
            Opens the {data.store} · we never see your code
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
