// Titlebar portal slot — lets the app shell host a single full-width
// title bar above the navbar while each screen still declares its own
// title/subtitle/toolbar through PyorWindow.
//
// Shell renders the strip and exposes its inner DOM node here; PyorWindow
// reads it and portals its titlebar content into it. The screen's React
// tree is preserved (handlers/state intact) — only the DOM target moves.
//
// Value contract:
//   undefined  → no app shell (pre-auth / design harness): PyorWindow
//                renders its titlebar inline atop its own window.
//   null       → app shell present, strip node not yet mounted.
//   HTMLElement→ portal target for the per-screen titlebar content.

import { createContext, useContext } from 'react';

export const TitlebarSlotContext = createContext<
  HTMLElement | null | undefined
>(undefined);

export function useTitlebarSlot() {
  return useContext(TitlebarSlotContext);
}
