// Shared desktop update lifecycle state (ADR 0023). Subscribes to the
// background updater events (download → install → ready) broadcast from the
// Electron main process and exposes them as a single value. Consumed by both
// the sidebar UpdateGauge widget and the Settings "About" row so they read one
// source of truth. Returns `{ kind: 'idle' }` on web (no bridge).

import { useEffect, useState } from 'react';
import { bridge } from './electronBridge';

export type UpdateState =
  | { kind: 'idle' }
  | { kind: 'download'; percent: number }
  | { kind: 'install' }
  | { kind: 'ready'; via: 'staged' | 'downloaded'; version?: string };

export function useUpdateState(): UpdateState {
  const [state, setState] = useState<UpdateState>({ kind: 'idle' });
  useEffect(() => {
    const b = bridge();
    if (!b) return;
    const offProgress = b.onUpdateProgress((p) =>
      setState(
        p.phase === 'error'
          ? { kind: 'idle' }
          : p.phase === 'install'
            ? { kind: 'install' }
            : { kind: 'download', percent: p.percent },
      ),
    );
    const offStaged = b.onUpdateStaged((version) =>
      setState({ kind: 'ready', via: 'staged', version }),
    );
    const offDownloaded = b.onUpdateDownloaded(() =>
      setState({ kind: 'ready', via: 'downloaded' }),
    );
    return () => {
      offProgress();
      offStaged();
      offDownloaded();
    };
  }, []);
  return state;
}
