// The "Review with AI" trigger as it rides the Changes header — both the
// steady tab-bar toolbar (next to the commits dropdown) and the collapsed
// CompactHeader. A thin AiReviewTrigger wrapped in a rich tooltip that carries
// the one-line "what it does" + the pre-run token/cost estimate, so the body
// no longer needs a full-width idle banner (ADR 0026).

import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { AiDisclaimer, AiMark, AiReviewTrigger } from '../aikit';
import type { AiCompactTrigger } from './useAiHints';

const BLURB = 'Drops a few high-signal hints on the lines that matter.';

export function AiReviewHeaderButton({
  state,
  done,
  total,
  count,
  estimate,
  onActivate,
  compact = false,
}: AiCompactTrigger & { compact?: boolean }) {
  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <span className="inline-flex">
            <AiReviewTrigger
              state={state}
              done={done}
              total={total}
              count={count}
              onClick={onActivate}
              compact={compact}
            />
          </span>
        </TooltipTrigger>
        {/* Neutralise the base tooltip bubble (bg-primary / px / shadow) and
            paint the real surface on an inner wrapper — that way the solid
            popover background + border are guaranteed regardless of how the
            base/override classes merge on the Radix Content node. */}
        <TooltipContent
          side="bottom"
          align="end"
          sideOffset={8}
          className="max-w-none border-0 bg-transparent p-0 text-popover-foreground shadow-none"
        >
          <div className="w-[252px] overflow-hidden rounded-lg border border-border bg-popover text-popover-foreground shadow-lg">
            <div className="flex flex-col gap-1.5 px-3 py-2.5">
              <span className="inline-flex items-center gap-2 text-[12.5px] font-semibold text-foreground">
                <span className="inline-flex size-5 shrink-0 items-center justify-center rounded-md bg-violet-100 text-violet-600">
                  <AiMark className="size-3" />
                </span>
                {state === 'running'
                  ? 'Reviewing the diff…'
                  : state === 'done'
                    ? `${count} AI ${count === 1 ? 'hint' : 'hints'}`
                    : 'Review with AI'}
              </span>
              <p className="text-[11.5px] leading-relaxed text-muted-foreground">
                {state === 'done'
                  ? 'Private reading aids on specific lines — click to jump to them.'
                  : BLURB}
              </p>
              {state === 'ready' && estimate && (
                <span className="mt-0.5 inline-flex w-fit items-center gap-1 rounded-md bg-violet-50 px-1.5 py-0.5 font-mono text-[10.5px] tabular-nums text-violet-700">
                  ~{estimate.tokens} tokens · ~{estimate.cost} est.
                </span>
              )}
            </div>
            <div className="border-t border-border bg-muted/40 px-3 py-1.5">
              <AiDisclaimer size="sm" />
            </div>
          </div>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}
