// React Query as the signal store for AI settings (same pattern as usePrefs /
// diffPreferences). All consumers read the ['ai-settings'] key, so a write in
// the Settings card instantly propagates to the grouping/hints triggers.
// Secret keys come from the separate aiKeyStore snapshot via useSyncExternalStore.

import { useSyncExternalStore } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import {
  DEFAULT_AI_SETTINGS,
  loadAiSettings,
  saveAiSettings,
  type AiProvider,
  type AiSettings,
} from './aiSettings';
import { ensureAiKeysHydrated, getAiKeysSnapshot, isHydrated, subscribeAiKeys } from './aiKeyStore';

const AI_SETTINGS_KEY = ['ai-settings'] as const;

export interface UseAiSettings {
  settings: AiSettings;
  setSettings: (patch: Partial<AiSettings>) => void;
  /** Which providers have a key configured. */
  hasKey: Record<AiProvider, boolean>;
  bothKeys: boolean;
  anyKey: boolean;
  /** The provider the features will use right now (active if configured,
   * else the only configured one). null when no key at all. */
  effectiveProvider: AiProvider | null;
  /** AI is on AND a usable key exists — features can actually run. */
  ready: boolean;
}

export function useAiSettings(): UseAiSettings {
  const queryClient = useQueryClient();
  const query = useQuery({
    queryKey: AI_SETTINGS_KEY,
    queryFn: () => loadAiSettings(),
    staleTime: Infinity,
    gcTime: Infinity,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
  });
  const settings: AiSettings = { ...DEFAULT_AI_SETTINGS, ...(query.data ?? {}) };

  // Hydrate the secret-key snapshot from Keychain/localStorage once per page
  // load (module-guarded, not React-Query-cached — a persisted query would
  // skip its queryFn on reload and leave the snapshot empty). The aiKeyStore
  // subscription below re-renders consumers when hydration completes.
  ensureAiKeysHydrated();

  const setSettings = (patch: Partial<AiSettings>) => {
    saveAiSettings(patch);
    queryClient.setQueryData<AiSettings>(AI_SETTINGS_KEY, loadAiSettings());
  };

  // Secret-key presence drives gating but the values never enter React state.
  useSyncExternalStore(subscribeAiKeys, getAiKeysSnapshot, getAiKeysSnapshot);
  const keys = getAiKeysSnapshot();
  const hasKey: Record<AiProvider, boolean> = {
    anthropic: !!keys.anthropic,
    openai: !!keys.openai,
  };
  const bothKeys = hasKey.anthropic && hasKey.openai;
  const anyKey = hasKey.anthropic || hasKey.openai;

  const effectiveProvider: AiProvider | null = bothKeys
    ? settings.activeProvider
    : hasKey.anthropic
      ? 'anthropic'
      : hasKey.openai
        ? 'openai'
        : null;

  // Before hydration we can't know — treat as not-ready (the rail shows the
  // idle/locked state, never a false "ready").
  const ready = settings.enabled && isHydrated() && effectiveProvider !== null;

  return { settings, setSettings, hasKey, bothKeys, anyKey, effectiveProvider, ready };
}
