// Before/after preview for a single binary image file (PNG, JPG, GIF,
// WebP, SVG, …). Rendered inline in the diff stream via the `image`
// line annotation (see LiveDiffPane.renderAnnotation), occupying the
// space where the synthetic code body would be (that body is hidden by
// the `data-pyor-image` shadow-CSS rule in DiffBody).
//
// Image bytes are fetched through the authenticated Contents API and
// wrapped in object URLs — pointing an <img> straight at
// raw.githubusercontent.com 404s for private repos because that host
// rejects the bearer token.
//
// Two tiers of format (kept in sync with IMAGE_EXTENSIONS in buildDiff):
//   • browser-renderable (PNG/JPG/GIF/WebP/AVIF/BMP/ICO/SVG/…) — we
//     fetch the bytes and show the real image.
//   • image-like but NOT browser-decodable (PSD/TIFF/ICNS) — browsers
//     can't paint these in an <img>, so we skip the fetch entirely and
//     show an "Open on GitHub" card. They still appear inline in file
//     order rather than vanishing into the skipped banner.

import { useQuery } from '@tanstack/react-query';
import { ImageIcon, Loader2Icon, ExternalLinkIcon } from 'lucide-react';
import { fetchRawImageBlob } from '../../github/client';
import { useObjectUrl } from '../../util/useObjectUrl';

export interface ImageDiffFile {
  filename: string;
  status: string;
  previousFilename?: string;
}

/** Extensions a browser can decode in an <img>. Subset of buildDiff's
 *  IMAGE_EXTENSIONS — the rest (.psd/.tiff/.icns) are image-like but
 *  not paintable, so they get the Open-on-GitHub fallback. */
const BROWSER_RENDERABLE = new Set([
  '.png', '.apng', '.jpg', '.jpeg', '.jfif', '.pjpeg', '.pjp',
  '.gif', '.bmp', '.webp', '.avif', '.ico', '.cur', '.svg',
]);

function isBrowserRenderableImage(filename: string): boolean {
  const dot = filename.lastIndexOf('.');
  if (dot === -1) return false;
  return BROWSER_RENDERABLE.has(filename.slice(dot).toLowerCase());
}

/** Fetch the image bytes via React Query (cached + deduped across
 *  re-renders and panes that share a ref/path), then derive a shared,
 *  ref-counted object URL for the <img> (util/useObjectUrl — reused across
 *  remounts instead of re-minted). `enabled: false` (non-renderable format,
 *  or N/A side like the "before" of an added file) skips the request
 *  entirely. */
function useImageObjectUrl(
  owner: string | undefined,
  repo: string | undefined,
  ref: string | null,
  path: string | null,
  enabled: boolean,
): { url: string | null; isLoading: boolean; isError: boolean } {
  const active = enabled && !!owner && !!repo && !!ref && !!path;
  const query = useQuery({
    queryKey: ['raw-image-blob', owner, repo, ref, path],
    queryFn: () => fetchRawImageBlob(owner!, repo!, path!, ref!),
    enabled: active,
    staleTime: Infinity,
    gcTime: 10 * 60_000,
    retry: 1,
  });
  // Guard `instanceof Blob` (parity with ProxiedImg): a non-Blob can't reach
  // createObjectURL. Shared ref-counted URL reused across remounts — see
  // util/useObjectUrl.
  const blob = query.data instanceof Blob ? query.data : null;
  const url = useObjectUrl(blob);
  return { url, isLoading: active && query.isLoading, isError: query.isError };
}

function ImagePane({
  owner,
  repo,
  imgRef,
  path,
  label,
  side,
  loadImage,
}: {
  owner: string | undefined;
  repo: string | undefined;
  imgRef: string | null;
  path: string | null;
  label: string;
  side: 'old' | 'new';
  /** Local pre-PR surface: resolve image bytes offline (returns a
   * `data:` URL or null) instead of the GitHub Contents API. When set,
   * the GitHub fetch + object-URL path is bypassed. */
  loadImage?: (path: string, ref: string | null) => Promise<string | null>;
}) {
  const renderable = path ? isBrowserRenderableImage(path) : false;
  const isLocal = !!loadImage;
  // GitHub fetch (object URL) — disabled in local mode. Both hooks are
  // always called (rules of hooks); `enabled` gates which one runs.
  const gh = useImageObjectUrl(owner, repo, imgRef, path, renderable && !isLocal);
  const localQuery = useQuery({
    queryKey: ['local-image', imgRef, path],
    queryFn: () => loadImage!(path!, imgRef),
    enabled: renderable && isLocal && !!path,
    staleTime: Infinity,
    gcTime: 10 * 60_000,
    retry: 0,
  });
  const local = {
    url: typeof localQuery.data === 'string' ? localQuery.data : null,
    isLoading: renderable && isLocal && !!path && localQuery.isLoading,
    isError: localQuery.isError,
  };
  const { url, isLoading, isError } = isLocal ? local : gh;

  const accent =
    side === 'old'
      ? 'border-red-200 dark:border-red-900/60 bg-red-50/30 dark:bg-red-950/20'
      : 'border-emerald-200 dark:border-emerald-900/60 bg-emerald-50/30 dark:bg-emerald-950/20';
  const labelColor =
    side === 'old'
      ? 'text-red-600 dark:text-red-400'
      : 'text-emerald-600 dark:text-emerald-400';

  const githubUrl =
    !isLocal && owner && repo && imgRef && path
      ? `https://github.com/${owner}/${repo}/blob/${imgRef}/${path}`
      : null;

  const showFallback = !renderable || isError;

  return (
    <div className={`flex flex-1 flex-col overflow-hidden rounded-md border ${accent}`}>
      <div
        className={`border-b px-3 py-1.5 text-[11px] font-semibold uppercase tracking-wide ${labelColor}`}
      >
        {label}
      </div>
      <div className="flex min-h-[80px] items-center justify-center p-3">
        {showFallback ? (
          <div className="flex flex-col items-center gap-2 py-4 text-muted-foreground">
            <ImageIcon className="size-6 opacity-40" />
            <span className="text-[12px]">
              {!renderable
                ? "Can't preview this format here"
                : "Couldn't load image"}
            </span>
            {githubUrl && (
              <a
                href={githubUrl}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center gap-1 text-[12px] font-medium text-foreground underline-offset-2 hover:underline"
              >
                <ExternalLinkIcon className="size-3" />
                Open on GitHub
              </a>
            )}
          </div>
        ) : isLoading || !url ? (
          <Loader2Icon className="size-5 animate-spin text-muted-foreground/60" />
        ) : (
          <img
            src={url}
            alt={`${label} — ${path ?? ''}`}
            className="max-h-72 max-w-full rounded object-contain"
          />
        )}
      </div>
    </div>
  );
}

export function ImageDiffCard({
  file,
  owner,
  repo,
  baseSha,
  headSha,
  loadImage,
}: {
  file: ImageDiffFile;
  owner?: string;
  repo?: string;
  baseSha?: string;
  headSha?: string;
  /** Local pre-PR surface: resolve image bytes offline. When provided,
   * the GitHub Contents-API fetch is bypassed and `imgRef` is passed
   * straight to this resolver (old side = baseSha/oldRef, new side =
   * headSha/newRef; null ref = working tree). */
  loadImage?: (path: string, ref: string | null) => Promise<string | null>;
}) {
  const oldPath = file.previousFilename ?? file.filename;
  const showBefore = file.status !== 'added';
  const showAfter = file.status !== 'removed';

  return (
    <div className="border-y bg-muted/20 px-4 py-4">
      <div className="flex gap-3">
        {showBefore && (
          <ImagePane
            owner={owner}
            repo={repo}
            imgRef={baseSha ?? null}
            path={oldPath}
            label={showAfter ? 'Before' : 'Removed'}
            side="old"
            loadImage={loadImage}
          />
        )}
        {showAfter && (
          <ImagePane
            owner={owner}
            repo={repo}
            imgRef={headSha ?? null}
            path={file.filename}
            label={showBefore ? 'After' : 'Added'}
            side="new"
            loadImage={loadImage}
          />
        )}
      </div>
    </div>
  );
}
