"use no memo";

// Custom progress toast for bulk mark/unmark-as-viewed runs.
//
// One card, three states (running · throttled · done) so the whole run —
// progress, a rate-limit pause, and the final success — reads as the same
// surface rather than swapping to a separate sonner toast at the end. It's
// rendered via toast.custom with a per-toast `style` that strips sonner's
// own li chrome, so THIS card is the only card (no nested-card look).
//
// The count and bar are motion-driven: GitHub only confirms 25 files at a
// time, so on each chunk we animate from the old value to the new one —
// the number ticks up and the bar glides instead of jumping by 25, giving
// the illusion of file-by-file movement. The tween duration adapts to the
// gap between chunks (see COUNT_TWEEN_* ) so it paces itself. While
// throttled
// the bar turns amber, a highlight shimmers across it, and the copy counts
// down to resume. On finish the bar fills emerald and the icon swaps to a
// check.

import { useEffect, useRef } from 'react';
import { animate, motion, useMotionValue, useTransform } from 'motion/react';
import { CheckCircle2, Clock, Eye, EyeOff } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

// Count-up pacing. Each chunk's tween runs a bit LONGER than the gap since
// the previous chunk (× OVERSHOOT), so it's still mid-count when the next
// chunk lands — motion then retargets from the in-between value and the
// number keeps moving instead of stalling at each 25-file boundary. The
// count trails ~a third of a chunk behind and catches up at completion
// (the done state forces it to the total). Clamped so the first chunk (no
// prior gap) and the post-throttle resume (a huge gap) stay sane.
const COUNT_TWEEN_MIN_MS = 250;
const COUNT_TWEEN_MAX_MS = 2000;
const COUNT_TWEEN_DEFAULT_MS = 900;
const COUNT_TWEEN_OVERSHOOT = 1.6;

interface ViewedProgressState {
  verb: 'Mark' | 'Unmark';
  done: number;
  total: number;
  /** Seconds until a throttled run retries the current chunk. Undefined
   * while running normally; 0 means "retrying now". Ignored when
   * `complete` is set. */
  resumeInSec?: number;
  /** Run finished — render the emerald success variant (bar full, check
   * icon). Takes precedence over `resumeInSec`. */
  complete?: boolean;
}

type Tone = {
  chip: string;
  bar: string;
  track: string;
  icon: LucideIcon;
  pulseIcon: boolean;
};

function ViewedProgressToast({
  verb,
  done,
  total,
  resumeInSec,
  complete,
}: ViewedProgressState) {
  const status = complete
    ? 'done'
    : resumeInSec !== undefined
      ? 'throttled'
      : 'running';

  // Animate the displayed count toward the confirmed total. done jumps in
  // chunks of 25; motion fills the gap one-by-one so it reads as fast,
  // continuous progress. The bar width derives from the same value, so
  // number and bar move in lockstep.
  const target = status === 'done' ? total : done;
  const count = useMotionValue(target);
  // Adaptive duration: time the gap between chunk updates and tween over
  // that, so the count keeps pace with however fast GitHub is confirming.
  const lastTickAt = useRef<number | undefined>(undefined);
  useEffect(() => {
    const now = performance.now();
    const gap =
      lastTickAt.current !== undefined
        ? now - lastTickAt.current
        : COUNT_TWEEN_DEFAULT_MS;
    lastTickAt.current = now;
    const duration =
      Math.min(
        COUNT_TWEEN_MAX_MS,
        Math.max(COUNT_TWEEN_MIN_MS, gap * COUNT_TWEEN_OVERSHOOT),
      ) / 1000;
    const controls = animate(count, target, { duration, ease: 'linear' });
    return () => controls.stop();
  }, [target, count]);
  const shownCount = useTransform(count, (v) => String(Math.round(v)));
  const barWidth = useTransform(count, (v) =>
    total > 0 ? `${Math.min(100, (v / total) * 100)}%` : '0%',
  );
  const shownPct = useTransform(count, (v) =>
    total > 0 ? `${Math.min(100, Math.round((v / total) * 100))}% complete` : '',
  );

  const tone: Tone = {
    running: {
      chip: 'bg-primary/10 text-primary ring-primary/25',
      bar: 'bg-primary',
      track: 'bg-primary/10',
      icon: verb === 'Mark' ? Eye : EyeOff,
      pulseIcon: false,
    },
    throttled: {
      chip: 'bg-amber-500/10 text-amber-600 ring-amber-500/30 dark:text-amber-400',
      bar: 'bg-amber-500',
      track: 'bg-amber-500/10',
      icon: Clock,
      pulseIcon: true,
    },
    done: {
      chip: 'bg-pyor-pass/10 text-pyor-pass ring-pyor-pass/30',
      bar: 'bg-pyor-pass',
      track: 'bg-pyor-pass/15',
      icon: CheckCircle2,
      pulseIcon: false,
    },
  }[status];

  const action = verb === 'Mark' ? 'Marking' : 'Unmarking';
  const pastAction = verb === 'Mark' ? 'Marked' : 'Unmarked';

  const title =
    status === 'done'
      ? `${pastAction} ${total} file${total === 1 ? '' : 's'} as viewed`
      : status === 'throttled'
        ? 'Paused by GitHub'
        : `${action} files as viewed`;

  const Icon = tone.icon;

  return (
    <div
      role="status"
      aria-live="polite"
      className="w-[360px] overflow-hidden rounded-xl border border-border bg-background shadow-lg"
    >
      <div className="flex items-center gap-3 p-3.5">
        <div
          className={cn(
            'flex size-8 shrink-0 items-center justify-center rounded-[9px] ring-1 ring-inset transition-colors',
            tone.chip,
          )}
        >
          <Icon
            className={cn('size-[18px]', tone.pulseIcon && 'animate-pulse')}
            strokeWidth={2}
          />
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex items-baseline justify-between gap-2">
            <span className="truncate text-[13px] font-semibold tracking-[-0.1px] text-foreground">
              {title}
            </span>
            {status !== 'done' ? (
              <span className="shrink-0 text-[11px] font-medium tabular-nums text-muted-foreground">
                <motion.span>{shownCount}</motion.span>/{total}
              </span>
            ) : null}
          </div>
          {status === 'running' ? (
            <motion.p className="mt-0.5 truncate text-[11.5px] leading-normal text-muted-foreground">
              {shownPct}
            </motion.p>
          ) : status === 'throttled' ? (
            <p className="mt-0.5 truncate text-[11.5px] leading-normal text-muted-foreground">
              {resumeInSec && resumeInSec > 0
                ? `Rate limit hit — resuming in ${resumeInSec}s…`
                : 'Rate limit hit — resuming…'}
            </p>
          ) : null}
        </div>
      </div>

      {/* Smooth determinate bar — motion drives the width so it glides with
       * the count. Shimmer overlay only while throttled (bar is otherwise
       * stalled at the current %, so the sweep is the "still working"
       * signal). */}
      <div
        className={cn(
          'relative h-[3px] w-full overflow-hidden transition-colors',
          tone.track,
        )}
      >
        <motion.div
          className={cn(
            'h-full rounded-r-full transition-colors',
            tone.bar,
          )}
          style={{ width: barWidth }}
        />
        {status === 'throttled' ? (
          <div className="motion-reduce:hidden pointer-events-none absolute inset-y-0 left-0 w-1/3 animate-viewed-shimmer bg-gradient-to-r from-transparent via-foreground/20 to-transparent" />
        ) : null}
      </div>
    </div>
  );
}

// Files above which the toast appears immediately (instant feedback on a
// clearly-big op); smaller runs stay silent unless they outlive the reveal
// delay or get throttled.
const PROGRESS_REVEAL_AT_FILES = 80;
const PROGRESS_REVEAL_AFTER_MS = 2_500;

/** Imperative handle over one bulk-viewed run's toast. Owns the lazy
 * reveal, the throttle countdown ticker, and the running → done/error
 * transitions, so the caller just maps mutation callbacks to methods. */
export interface ViewedProgressHandle {
  /** A chunk landed — `done` files now confirmed. */
  progress(done: number): void;
  /** Throttled; will retry in ~`waitMs`. `done` = files confirmed so far. */
  throttle(waitMs: number, done: number): void;
  /** Run finished — resolve to the emerald done card (auto-dismisses). */
  succeed(): void;
  /** Run failed — replace the card with a fresh error toast + Retry. */
  fail(opts: { headline: string; description: string; onRetry: () => void }): void;
  /** Superseded — tear the toast down silently. */
  dismiss(): void;
}

/** Drive a bulk-viewed progress toast. Lazy: the toast only appears for a
 * big run, a run that outlives the reveal delay, or one that gets
 * throttled — quick toggles stay silent. */
export function showViewedProgress(
  verb: 'Mark' | 'Unmark',
  total: number,
): ViewedProgressHandle {
  let toastId: string | number | undefined;
  let done = 0;
  let revealTimer: ReturnType<typeof setTimeout> | undefined;
  let throttleTimer: ReturnType<typeof setInterval> | undefined;

  const clearReveal = () => {
    if (revealTimer !== undefined) clearTimeout(revealTimer);
    revealTimer = undefined;
  };
  const clearThrottle = () => {
    if (throttleTimer !== undefined) clearInterval(throttleTimer);
    throttleTimer = undefined;
  };

  // Create-or-update the custom card. The per-toast `style` strips sonner's
  // own li chrome (bg/border/shadow from the global classNames.toast) so
  // this card is the ONLY card — inline style wins over the class chrome.
  const render = (o: { resumeInSec?: number; complete?: boolean } = {}) => {
    const opts = {
      duration: o.complete ? 3_500 : Infinity,
      style: { background: 'transparent', border: 'none', boxShadow: 'none' },
    };
    toastId = toast.custom(
      () => (
        <ViewedProgressToast
          verb={verb}
          done={done}
          total={total}
          resumeInSec={o.resumeInSec}
          complete={o.complete}
        />
      ),
      toastId != null ? { ...opts, id: toastId } : opts,
    );
  };

  if (total > PROGRESS_REVEAL_AT_FILES) render();
  else
    revealTimer = setTimeout(() => {
      revealTimer = undefined;
      render();
    }, PROGRESS_REVEAL_AFTER_MS);

  return {
    progress(d) {
      done = d;
      clearThrottle();
      // Only refresh an already-visible toast — don't reveal on progress,
      // or a fast small run would flash a toast just to dismiss it.
      if (toastId != null) render();
    },
    throttle(waitMs, d) {
      done = d;
      clearReveal();
      clearThrottle();
      let secs = Math.max(1, Math.round(waitMs / 1000));
      const tick = () => {
        render({ resumeInSec: Math.max(0, secs) });
        if (secs <= 0) clearThrottle();
        else secs -= 1;
      };
      tick();
      throttleTimer = setInterval(tick, 1000);
    },
    succeed() {
      clearReveal();
      clearThrottle();
      if (toastId != null) {
        done = total;
        render({ complete: true });
      }
    },
    fail({ headline, description, onRetry }) {
      clearReveal();
      clearThrottle();
      // Fresh error toast — reusing the custom id would inherit the
      // chrome-stripping `style` and render as floating, card-less text.
      if (toastId != null) toast.dismiss(toastId);
      toast.error(headline, {
        duration: 10_000,
        description,
        action: { label: 'Retry', onClick: onRetry },
      });
    },
    dismiss() {
      clearReveal();
      clearThrottle();
      if (toastId != null) toast.dismiss(toastId);
    },
  };
}
