// Global 404 — wired as the router's `defaultNotFoundComponent`, so any
// address that matches no route lands here. It renders inside the root
// Outlet, so the persistent app sidebar stays visible and the user is
// never stranded: one click goes back to Pull requests or the Inbox.
//
// Built on the same EmptyState surface every other "nothing here" screen
// uses (Inbox zero, no PRs, …) wrapped in the standard fluid PyorWindow
// chrome, so a 404 reads as a calm in-app state rather than a crash.

import { CompassIcon } from 'lucide-react';
import { Link, useRouterState } from '@tanstack/react-router';
import { Button } from '@/components/ui/button';
import { EmptyState } from '../ui/EmptyState';
import { PyorWindow } from '../ui/PyorWindow';
import { INBOX_DEFAULTS, PULLS_DEFAULTS } from '../router/search';

export function NotFoundScreen() {
  // Surface the address that missed — honest about what was attempted,
  // and a useful hint when it's a fat-fingered or stale deep link.
  const pathname = useRouterState({ select: (s) => s.location.pathname });

  return (
    <PyorWindow fluid title="Not found" subtitle={pathname}>
      <EmptyState
        icon={CompassIcon}
        title="Page not found"
        body={
          <>
            Nothing lives at{' '}
            <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-[12px] text-foreground">
              {pathname}
            </code>
            . The link may be mistyped, or the page has moved.
          </>
        }
        action={
          <>
            <Button asChild size="sm">
              <Link to="/pulls" search={PULLS_DEFAULTS}>
                Go to Pull requests
              </Link>
            </Button>
            <Button asChild variant="outline" size="sm">
              <Link to="/inbox" search={INBOX_DEFAULTS}>
                Open Inbox
              </Link>
            </Button>
          </>
        }
      />
    </PyorWindow>
  );
}
