// Inline composer for authoring a new line-level Local Review Comment.
// Opened by clicking the "+" gutter affordance on a hovered diff line
// inside a LocalReviewSurface. Save persists straight to localStorage
// via `useCreateLocalReviewComment` — no batching, no draft staging:
// local reviews are personal note pads, every save is a real save.
//
// Design parity: gh-comments.jsx · GhComposer — the same rich
// Write/Preview composer the PR thread uses, prefixed with a compact
// anchor label. SINGLE-body (no thread chrome) per ADR 0012's "single
// comment per anchor" decision; the pyor-warn accent + "local" badge
// keep it visually distinct from the GitHub-draft surface so a reader
// can tell at a glance which surface they're commenting on.

import { useState } from 'react';
import { PlusIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { localReviewUploader } from '../../review/pasteAttachment';
import { useCreateLocalReviewComment } from '../../review/useLocalReviewComments';
import { GhComposer } from '../conversation/GhComposer';

export interface LocalLineComposerProps {
  /** Owning LocalReview. */
  reviewId: string;
  /** File path (relative to the worktree). */
  path: string;
  /** Diff side the line lives on. */
  side: 'LEFT' | 'RIGHT';
  /** Anchor line number. */
  line: number;
  /** Range start (multi-line selection). Optional. */
  startLine?: number;
  /** Committed head SHA for committed-diff comments, or
   * `WORKING_TREE_ANCHOR` for uncommitted-diff comments. Decided by the
   * caller based on which bucket the file is in. Phase 4's staleness
   * algorithm reads this. */
  anchorSha: string;
  /** Line text at write time (trimEnd, first 200 chars). null is
   * legal but discouraged for line comments — the snippet is the
   * fingerprint Phase 4 compares against. */
  contentSnippet: string | null;
  /** Viewer login at write time. Defaults to 'you' if unavailable. */
  authorLogin?: string;
  onClose: () => void;
}

export function LocalLineCommentComposer({
  reviewId,
  path,
  side,
  line,
  startLine,
  anchorSha,
  contentSnippet,
  authorLogin,
  onClose,
}: LocalLineComposerProps) {
  // ADR 0012 Phase 5 — pre-generate the commentId at mount so a
  // paste-attach during composition can write to the correct
  // <reviewId>/<commentId>/ dir before the comment is persisted. The
  // same id is reused on save so the embedded `pyor-attachment://`
  // URLs resolve. Stable across re-renders via useState's lazy init.
  const [pendingCommentId] = useState(() => crypto.randomUUID());
  const create = useCreateLocalReviewComment();
  const isRange = startLine !== undefined && startLine !== line;
  const author = authorLogin ?? 'you';

  return (
    <div className="mx-3 mb-3 mt-1.5 box-border max-w-full">
      <div className="mb-1.5 flex items-center gap-2 px-0.5 text-[11.5px] text-foreground">
        <PlusIcon className="size-[12px] text-pyor-warn" />
        <span className="font-semibold">
          New {isRange ? 'range' : 'line'} note
        </span>
        <span className="text-muted-foreground">
          ·{' '}
          {isRange ? (
            <>
              lines{' '}
              <b className="font-mono text-foreground">
                {startLine}–{line}
              </b>
            </>
          ) : (
            <>
              line <b className="font-mono text-foreground">{line}</b>
            </>
          )}
        </span>
        <Badge
          variant="secondary"
          className="bg-pyor-warn/10 font-semibold text-pyor-warn"
        >
          local
        </Badge>
      </div>
      <GhComposer
        draftKey={`local:${reviewId}:line:${side}:${path}:${startLine ?? line}-${line}`}
        placeholder="Note… (Markdown · paste images · ⌘⏎ to save · Esc to cancel)"
        submitLabel="Save note"
        submitIcon="check"
        draftHint="Stays in this local review until you delete it"
        autoFocus
        minHeight={84}
        onUploadImage={localReviewUploader(reviewId, pendingCommentId)}
        onCancel={onClose}
        onSubmit={async (body) => {
          if (!body.trim()) return;
          // Close the composer BEFORE the new comment renders. @pierre/diffs
          // mis-reconciles when an annotation is swapped for another at the
          // SAME line in one tick (composer → saved card), leaving stale
          // DOM (the "composer won't close / expand+cancel dead" bug). The
          // GitHub path dodges this because its comment arrives async; we
          // reproduce that ordering: remove the composer first (line goes
          // empty), then create (card mounts fresh). The body is already
          // draft-persisted, so a create failure doesn't lose it.
          onClose();
          await create.mutateAsync({
            id: pendingCommentId,
            reviewId,
            path,
            side,
            line,
            startLine: isRange ? startLine : undefined,
            anchorSha,
            contentSnippet,
            body,
            authorLogin: author,
          });
        }}
      />
    </div>
  );
}
