// Curated event catalog + emitter (ADR 0021).
//
// Naming: object_action, past tense, snake_case. NO autocapture — every event
// here is intentional. High-frequency interactions (file-viewed toggles, tab
// switches, diff search) are NOT individual events; they roll up into summary
// events (e.g. pr_review_completed) to respect the free-tier ceiling.
//
// Repo identity is always a HASH + visibility flag — a raw private repo name
// never reaches PostHog. Org attribution is attached per-event via `orgId`.

import { analyticsConfigured, groupAnalyticsEnabled } from './config';
import { posthog } from './posthog';

export const Events = {
  // Onboarding / activation
  AppOpened: 'app_opened',
  AuthStarted: 'auth_started',
  AuthCompleted: 'auth_completed',
  EntitlementResolved: 'entitlement_resolved',
  // Conversion
  OrgBlockedHit: 'org_blocked_hit',
  UpgradeClicked: 'upgrade_clicked',
  CheckoutStarted: 'checkout_started',
  // List / lens
  LensViewed: 'lens_viewed',
  ListFiltered: 'list_filtered',
  ListSorted: 'list_sorted',
  PrOpened: 'pr_opened',
  // Review reading
  PrViewed: 'pr_viewed',
  PrReviewCompleted: 'pr_review_completed', // SUMMARY: rolls up viewed/tab/search
  FocusModeToggled: 'focus_mode_toggled',
  CommandPaletteOpened: 'command_palette_opened',
  // Review writing
  CommentPosted: 'comment_posted',
  ThreadReplied: 'thread_replied',
  ReviewSubmitted: 'review_submitted',
  AttachmentUploaded: 'attachment_uploaded',
  // Lifecycle
  PrMerged: 'pr_merged',
  PrStateChanged: 'pr_state_changed',
  BranchUpdated: 'branch_updated',
  ReviewerChanged: 'reviewer_changed',
  // Inbox
  NotificationClicked: 'notification_clicked',
  // Pre-PR / Local
  LocalReviewCreated: 'local_review_created',
  ReviewExportedToAgent: 'review_exported_to_agent',
  // Settings
  AnalyticsOptoutToggled: 'analytics_optout_toggled',
} as const;

export type EventName = (typeof Events)[keyof typeof Events];

type Props = Record<string, unknown>;

/**
 * Stable, one-way-ish hash of `owner/repo` (FNV-1a, 32-bit). Lets PostHog count
 * distinct repos and build per-repo funnels WITHOUT ever storing the name.
 */
export function hashRepo(owner: string, repo: string): string {
  const input = `${owner}/${repo}`.toLowerCase();
  const h = Array.from(input).reduce(
    (acc, ch) => Math.imul(acc ^ ch.charCodeAt(0), 0x01000193),
    0x811c9dc5,
  );
  return (h >>> 0).toString(16).padStart(8, '0');
}

/** Build the sanitized repo property bundle every PR-scoped event carries.
 *  `repo_visibility` is included ONLY when `isPrivate` is known — omitted is
 *  honest, defaulting it to "public" would mislabel private repos. */
export function repoProps(args: {
  owner: string;
  repo: string;
  isPrivate?: boolean;
  prNumber?: number;
}): Props {
  return {
    repo_hash: hashRepo(args.owner, args.repo),
    ...(args.isPrivate != null
      ? { repo_visibility: args.isPrivate ? 'private' : 'public' }
      : {}),
    ...(args.prNumber != null ? { pr_number: args.prNumber } : {}),
  };
}

/**
 * Emit a curated event. No-op when analytics isn't configured or the user has
 * opted out (PostHog enforces opt-out internally).
 *
 * `orgId` attaches org context. It always rides as an `org_id` PROPERTY (free
 * tier: break down/filter any insight by org). When group analytics is enabled
 * (paid), it ALSO attaches `$groups` for the dedicated org group timeline —
 * per-event, so a multi-org member's events aren't mis-attributed.
 */
export function track(
  event: EventName,
  properties?: Props,
  opts?: { orgId?: number | null },
): void {
  if (!analyticsConfigured) return;
  const hasOrg = opts?.orgId != null;
  const orgProps = hasOrg ? { org_id: String(opts!.orgId) } : {};
  const groups =
    hasOrg && groupAnalyticsEnabled ? { $groups: { org: String(opts!.orgId) } } : {};
  posthog.capture(event, { ...properties, ...orgProps, ...groups });
}
