// PR merge box — the single home for lifecycle actions, pinned to the
// foot of the Conversation tab below the comment composer (design:
// shell-pr-conv / shell-pr-conv-merge). Three stacked sections inside
// one card: a status header, a per-gate status checklist, and an
// action bar with the split merge button + method dropdown.
//
// Gating is derived from live PR state — reviewer verdicts
// (collectReviewerStates), check-run counts (getCheckRuns), and
// GitHub's own mergeable / mergeable_state. The merge button is enabled
// iff every required gate passes; otherwise the box renders blocked.

import { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  AlertCircleIcon,
  AlertTriangleIcon,
  CheckCircle2Icon,
  ChevronDownIcon,
  GitBranchIcon,
  GitCommitHorizontalIcon,
  GitMergeIcon,
  Loader2,
  RefreshCwIcon,
  XCircleIcon,
} from 'lucide-react';
import {
  countRollup,
  disablePullRequestAutoMerge,
  enablePullRequestAutoMerge,
  mergePullRequest,
  setPullRequestState,
  updatePullRequestBranch,
} from '../../github/client';
import { checkBucketIcon } from '../checkBucketIcon';
import { allowedMergeMethods, type MergeMethod } from '../../github/lifecycle';
import {
  invalidatePrLists,
  prCheckRollupOptions,
  repoMergeConfigOptions,
} from '../../github/prQueries';
import {
  readStoredMergeMethod,
  reconcileMergeMethod,
  storeMergeMethod,
} from '../../util/mergeMethodStore';
import type {
  GHPullRequest,
  GHReview,
  GHReviewComment,
  RollupCheck,
} from '../../github/types';
import { collectReviewerStates } from '../PRHeader';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Collapse, CollapseChevron } from '@/components/ui/collapse';

interface MethodDef {
  id: MergeMethod;
  /** Verb shown on the split button's primary face. */
  label: string;
  /** One-line description shown in the dropdown. */
  hint: string;
  icon: typeof GitMergeIcon;
}

const METHODS: MethodDef[] = [
  {
    id: 'merge',
    label: 'Create a merge commit',
    hint: 'All commits from this branch are added to the base branch via a merge commit.',
    icon: GitMergeIcon,
  },
  {
    id: 'squash',
    label: 'Squash and merge',
    hint: 'The commits are combined into one commit in the base branch.',
    icon: GitCommitHorizontalIcon,
  },
  {
    id: 'rebase',
    label: 'Rebase and merge',
    hint: 'The commits are rebased and added to the base branch individually.',
    icon: GitBranchIcon,
  },
];

type GateTone = 'ok' | 'warn' | 'fail';

interface Gate {
  tone: GateTone;
  label: string;
  detail: string;
}

export function MergeBox({
  pr,
  owner,
  repo,
  number,
  reviews,
  reviewComments,
}: {
  pr: GHPullRequest;
  owner: string;
  repo: string;
  number: number;
  reviews: GHReview[];
  reviewComments: GHReviewComment[];
}) {
  const qc = useQueryClient();
  const [busy, setBusy] = useState<
    null | 'merge' | 'close' | 'update' | 'autoMerge'
  >(null);
  const [confirmClose, setConfirmClose] = useState(false);
  const [method, setMethod] = useState<MergeMethod>(readStoredMergeMethod);

  // Repo merge settings drive which methods are offered + the default.
  // GitHub has no "default method" field — the first allowed method (in
  // [merge, squash, rebase] order) is github.com's default, which
  // `allowedMergeMethods` mirrors. While the config read resolves we
  // optimistically offer all three, then reconcile.
  const mergeConfigQuery = useQuery(repoMergeConfigOptions(owner, repo));
  const allowed: MergeMethod[] = mergeConfigQuery.data
    ? allowedMergeMethods(mergeConfigQuery.data)
    : ['merge', 'squash', 'rebase'];
  // Honour the stored / sticky pick while the repo still allows it;
  // otherwise fall back to the repo's default (first allowed) method.
  const effectiveMethod = reconcileMergeMethod(method, allowed);

  // Unified check rollup (check-runs + commit statuses) — same shared
  // query key PRHeader + ChecksTab use, so it's one deduped round trip
  // and the gate matches what those surfaces show.
  const rollupQuery = useQuery(
    prCheckRollupOptions(owner, repo, number, pr.head.sha),
  );
  const rollupChecks = rollupQuery.data?.checks ?? [];
  const checks = countRollup(rollupChecks);
  const [checksOpen, setChecksOpen] = useState(true);

  // ── Derive each gate ──────────────────────────────────────────
  const reviewerStates = collectReviewerStates(pr, reviews, reviewComments);
  const changesCount = reviewerStates.filter((r) => r.state === 'changes').length;
  const approvedCount = reviewerStates.filter((r) => r.state === 'approved').length;
  const reviewsFail = changesCount > 0;

  const conflicts = pr.mergeable === false || pr.mergeable_state === 'dirty';
  const behind = pr.mergeable_state === 'behind';
  const blockedByPolicy = pr.mergeable_state === 'blocked';

  // Auto-merge: arm the merge to fire once requirements pass. Mirrors the
  // lifecycle resolver — offered (when the repo allows it) only while the
  // PR can't merge right now but isn't a hard conflict / already mergeable.
  const allowAutoMerge = mergeConfigQuery.data?.allowAutoMerge ?? false;
  const autoMergeEnabled = pr.auto_merge != null;
  const autoMergeBy = pr.auto_merge?.enabled_by?.login;
  const ms = pr.mergeable_state;
  const canEnableAutoMerge =
    allowAutoMerge &&
    !autoMergeEnabled &&
    ms !== 'clean' &&
    ms !== 'has_hooks' &&
    ms !== 'dirty';

  const baseRef = pr.base.ref;

  const reviewGate: Gate = reviewsFail
    ? {
        tone: 'fail',
        label: 'Changes requested',
        detail: `${changesCount} reviewer${changesCount === 1 ? '' : 's'} requested changes`,
      }
    : approvedCount > 0
      ? {
          tone: 'ok',
          label: 'Review approved',
          detail: `${approvedCount} approving review${approvedCount === 1 ? '' : 's'}`,
        }
      : {
          tone: 'warn',
          label: 'Review required',
          detail: 'Awaiting a required approving review',
        };

  const checkGate: Gate = (() => {
    const total = checks.pass + checks.fail + checks.pending;
    if (checks.fail > 0) {
      return {
        tone: 'fail',
        label: 'Some checks failing',
        detail: `${checks.fail} of ${total} checks failing`,
      };
    }
    if (checks.pending > 0) {
      return {
        tone: 'warn',
        label: 'Checks still running',
        detail: `${checks.pending} of ${total} checks pending`,
      };
    }
    if (total > 0) {
      return {
        tone: 'ok',
        label: 'All checks passed',
        detail: `${checks.pass} check${checks.pass === 1 ? '' : 's'} passed`,
      };
    }
    return {
      tone: 'ok',
      label: 'No checks required',
      detail: 'No status checks report on this commit',
    };
  })();

  const freshnessGate: Gate = behind
    ? {
        tone: 'warn',
        label: 'Out of date with base',
        detail: `This branch is behind ${baseRef}`,
      }
    : {
        tone: 'ok',
        label: 'Branch is up to date',
        detail: `Even with ${baseRef}`,
      };

  const conflictGate: Gate = conflicts
    ? {
        tone: 'fail',
        label: 'Conflicts must be resolved',
        detail: `This branch conflicts with ${baseRef}`,
      }
    : {
        tone: 'ok',
        label: 'No merge conflicts',
        detail: `Can be merged cleanly into ${baseRef}`,
      };

  // Enable the button exactly when GitHub itself would accept the merge,
  // rather than re-deriving a stricter rule from raw check counts. GitHub
  // already encodes "a REQUIRED check or review is failing/missing" as
  // mergeable_state === 'blocked' (→ blockedByPolicy); non-required reds
  // surface as 'unstable', which GitHub still lets you merge. So failing /
  // pending checks here are informational (they still drive checkGate's
  // tone below) but are NOT a hard stop — otherwise an always-red,
  // non-required check (e.g. the Vercel preview deploy that fails on every
  // PR for account reasons) would block merges the app should permit.
  const ready = !reviewsFail && !conflicts && !blockedByPolicy;
  const state: 'ready' | 'blocked' = ready ? 'ready' : 'blocked';

  // ── Mutations ─────────────────────────────────────────────────
  // Invalidating the whole ['pr', owner, repo, number] subtree
  // refreshes the header pills, rail status, and timeline at once.
  const refreshPR = () =>
    void qc.invalidateQueries({ queryKey: ['pr', owner, repo, number] });

  const onMerge = async () => {
    setBusy('merge');
    try {
      await mergePullRequest(owner, repo, number, { method: effectiveMethod });
      // GitHub's PR-meta GET can lag a beat behind the merge, so the
      // refreshPR() refetch may return stale "open" data. Optimistically
      // flip the cached meta to merged so the header + this box update at
      // once (the box swaps to MergeOutcomeBox); the refetch reconciles.
      qc.setQueryData<GHPullRequest>(
        ['pr', owner, repo, number, 'meta'],
        (old) =>
          old
            ? { ...old, state: 'closed', merged_at: new Date().toISOString() }
            : old,
      );
      // Refresh the PR-list lenses too: the merged PR drops out of the
      // open lists / flips its state chip, but those live under a separate
      // ['lens', …] query that refreshPR()'s ['pr', …] prefix doesn't
      // reach (it's also unmounted behind this screen, so this just marks
      // it stale to refetch on return).
      void invalidatePrLists(qc);
      toast.success('Pull request merged');
      refreshPR();
    } catch (e) {
      toast.error('Could not merge', {
        description: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setBusy(null);
    }
  };

  const onUpdateBranch = async () => {
    setBusy('update');
    try {
      await updatePullRequestBranch(owner, repo, number);
      toast.success('Branch update started', {
        description: `Merging ${baseRef} into ${pr.head.ref}.`,
      });
      refreshPR();
    } catch (e) {
      toast.error('Could not update branch', {
        description: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setBusy(null);
    }
  };

  const onEnableAutoMerge = async () => {
    setBusy('autoMerge');
    try {
      await enablePullRequestAutoMerge(owner, repo, number, effectiveMethod);
      toast.success('Auto-merge enabled', {
        description: 'This pull request will merge automatically once all requirements pass.',
      });
      refreshPR();
    } catch (e) {
      toast.error('Could not enable auto-merge', {
        description: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setBusy(null);
    }
  };

  const onDisableAutoMerge = async () => {
    setBusy('autoMerge');
    try {
      await disablePullRequestAutoMerge(owner, repo, number);
      toast.success('Auto-merge disabled');
      refreshPR();
    } catch (e) {
      toast.error('Could not disable auto-merge', {
        description: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setBusy(null);
    }
  };

  const onClose = async () => {
    setBusy('close');
    try {
      await setPullRequestState(owner, repo, number, 'closed');
      toast.success('Pull request closed');
      refreshPR();
    } catch (e) {
      toast.error('Could not close pull request', {
        description: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setBusy(null);
      setConfirmClose(false);
    }
  };

  const cur = METHODS.find((m) => m.id === effectiveMethod) ?? METHODS[0];
  const CurIcon = cur.icon;
  const headerTone =
    state === 'ready'
      ? 'border-pyor-pass/30 bg-pyor-pass/10'
      : 'border-pyor-warn/30 bg-pyor-warn/10';

  return (
    <div
      id="pr-merge-box"
      className="mt-4 scroll-mt-4 overflow-hidden rounded-lg border bg-card"
    >
      {/* 1 · Status header — colored strip + circular icon + title */}
      <div className={`flex items-center gap-3 border-b px-4 py-3 ${headerTone}`}>
        <span
          className={`inline-flex size-9 shrink-0 items-center justify-center rounded-full ${
            state === 'ready'
              ? 'bg-pyor-pass/20 text-pyor-pass'
              : 'bg-pyor-warn/20 text-pyor-warn'
          }`}
        >
          {state === 'ready' ? (
            <GitMergeIcon className="size-[18px]" />
          ) : (
            <AlertTriangleIcon className="size-[18px]" />
          )}
        </span>
        <div className="min-w-0 flex-1">
          <div className="text-[14px] font-semibold tracking-tight text-foreground">
            {state === 'ready' ? 'Ready to merge' : 'Merging is blocked'}
          </div>
          <div className="mt-0.5 text-[12px] text-muted-foreground">
            {state === 'ready'
              ? 'All checks passed and there are no conflicts.'
              : 'Required reviews and checks must pass before merging.'}
          </div>
        </div>
      </div>

      {/* 2 · Status checklist — one row per gate. The checks gate is
          expandable into the individual check list (à la GitHub). */}
      <div className="flex flex-col gap-2 px-4 py-3">
        <StatusRow gate={reviewGate} />
        <ChecksGate
          gate={checkGate}
          checks={rollupChecks}
          open={checksOpen}
          onToggle={() => setChecksOpen((o) => !o)}
        />
        <StatusRow gate={freshnessGate} />
        <StatusRow gate={conflictGate} />
      </div>

      {/* 3 · Action bar */}
      <div className="flex flex-wrap items-center gap-2 border-t bg-muted/30 px-4 py-3">
        <SplitMergeButton
          method={cur}
          options={METHODS}
          allowed={allowed}
          disabled={!ready || busy !== null}
          merging={busy === 'merge'}
          onMerge={onMerge}
          selected={effectiveMethod}
          onSelect={(m) => {
            setMethod(m);
            storeMergeMethod(m);
          }}
        />

        <div className="ml-auto flex items-center gap-1.5">
          {canEnableAutoMerge && (
            <Button
              variant="outline"
              size="sm"
              disabled={busy !== null}
              onClick={onEnableAutoMerge}
            >
              {busy === 'autoMerge' ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <GitMergeIcon className="size-3.5" />
              )}
              Enable auto-merge
            </Button>
          )}
          {autoMergeEnabled && (
            <Button
              variant="outline"
              size="sm"
              disabled={busy !== null}
              onClick={onDisableAutoMerge}
            >
              {busy === 'autoMerge' ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <XCircleIcon className="size-3.5" />
              )}
              Disable auto-merge
            </Button>
          )}
          {state === 'blocked' && behind && (
            <Button
              variant="outline"
              size="sm"
              disabled={busy !== null}
              onClick={onUpdateBranch}
            >
              {busy === 'update' ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <RefreshCwIcon className="size-3.5" />
              )}
              Update branch
            </Button>
          )}
          <Button
            variant="ghost"
            size="sm"
            disabled={busy !== null}
            onClick={() => setConfirmClose(true)}
            className="text-pyor-fail hover:bg-pyor-fail/10 hover:text-pyor-fail"
          >
            <XCircleIcon className="size-3.5" />
            Close pull request
          </Button>
        </div>

        {autoMergeEnabled && (
          <p className="flex w-full items-center gap-1.5 text-[11.5px] text-muted-foreground">
            <GitMergeIcon className="size-3.5 text-pyor-pass" />
            Auto-merge is on{autoMergeBy ? ` (enabled by ${autoMergeBy})` : ''} —
            this pull request will merge automatically once all requirements
            pass.
          </p>
        )}
        {!autoMergeEnabled && state === 'blocked' && (
          <p className="flex w-full items-center gap-1.5 text-[11.5px] text-muted-foreground">
            <AlertCircleIcon className="size-3.5 text-pyor-warn" />
            Resolve required reviews &amp; checks to enable merge.
          </p>
        )}
      </div>

      <CloseConfirmDialog
        open={confirmClose}
        onOpenChange={(o) => !o && setConfirmClose(false)}
        prNumber={number}
        busy={busy === 'close'}
        onConfirm={onClose}
      />
    </div>
  );
}

// One gate row: tone-colored icon + label + detail. Mirrors
// ShadcnMergeStatusRow (check-circle / alert-triangle / x-circle).
function StatusRow({ gate }: { gate: Gate }) {
  const { Icon, color } =
    gate.tone === 'ok'
      ? { Icon: CheckCircle2Icon, color: 'text-pyor-pass' }
      : gate.tone === 'warn'
        ? { Icon: AlertTriangleIcon, color: 'text-pyor-warn' }
        : { Icon: XCircleIcon, color: 'text-pyor-fail' };
  return (
    <div className="flex items-center gap-2.5">
      <Icon className={`size-4 shrink-0 ${color}`} />
      <span className="text-[12.5px] font-medium text-foreground">
        {gate.label}
      </span>
      <span className="ml-auto truncate text-[11.5px] text-muted-foreground">
        {gate.detail}
      </span>
    </div>
  );
}

// The checks gate — a StatusRow summary that expands into the
// individual check list (GitHub's merge-box behaviour). Falls back to a
// plain row when there are no checks to list.
function ChecksGate({
  gate,
  checks,
  open,
  onToggle,
}: {
  gate: Gate;
  checks: RollupCheck[];
  open: boolean;
  onToggle: () => void;
}) {
  const { Icon, color } =
    gate.tone === 'ok'
      ? { Icon: CheckCircle2Icon, color: 'text-pyor-pass' }
      : gate.tone === 'warn'
        ? { Icon: AlertTriangleIcon, color: 'text-pyor-warn' }
        : { Icon: XCircleIcon, color: 'text-pyor-fail' };
  if (checks.length === 0) return <StatusRow gate={gate} />;
  return (
    <div>
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-2.5 text-left"
        aria-expanded={open}
      >
        <Icon className={`size-4 shrink-0 ${color}`} />
        <span className="text-[12.5px] font-medium text-foreground">
          {gate.label}
        </span>
        <span className="ml-auto truncate text-[11.5px] text-muted-foreground">
          {gate.detail}
        </span>
        <CollapseChevron open={open} className="size-3.5 text-muted-foreground" />
      </button>
      <Collapse open={open} className="mt-2 overflow-hidden rounded-md border">
        {checks.map((c, i) => (
          <MergeCheckRow key={`${c.kind}:${c.name}`} check={c} border={i > 0} />
        ))}
      </Collapse>
    </div>
  );
}

// One row in the expanded check list — status icon, provider logo,
// name, optional Required badge, and a Details link to the provider.
// Exported so the read-only MergeOutcomeBox (merged/closed PRs) can show
// the same per-check list as a historical record.
export function MergeCheckRow({
  check,
  border,
}: {
  check: RollupCheck;
  border: boolean;
}) {
  const { Icon, color } = checkBucketIcon(check.bucket);
  return (
    <div
      className={`flex items-center gap-2 bg-card px-3 py-1.5 ${
        border ? 'border-t' : ''
      }`}
    >
      <Icon className={`size-3.5 shrink-0 ${color}`} />
      {check.providerIcon && (
        <img
          src={check.providerIcon}
          alt=""
          className="size-3.5 shrink-0 rounded-sm object-contain"
        />
      )}
      <span className="truncate text-[12px] text-foreground">{check.name}</span>
      {check.required && (
        <span className="shrink-0 rounded-sm bg-muted px-1.5 py-0.5 text-[9.5px] font-semibold uppercase tracking-wide text-muted-foreground">
          Required
        </span>
      )}
      {check.detail && (
        <span className="hidden min-w-0 flex-1 truncate text-[11px] text-muted-foreground sm:block">
          {firstLine(check.detail)}
        </span>
      )}
      {check.url && (
        <a
          href={check.url}
          target="_blank"
          rel="noopener noreferrer"
          className="ml-auto shrink-0 text-[11px] font-medium text-primary hover:underline"
        >
          Details
        </a>
      )}
    </div>
  );
}

// Split merge button: primary face (selected method) + chevron that
// opens the method dropdown. Green + enabled only when ready.
function SplitMergeButton({
  method,
  options,
  allowed,
  disabled,
  merging,
  onMerge,
  selected,
  onSelect,
}: {
  method: MethodDef;
  /** Every method, shown in github.com preference order. */
  options: MethodDef[];
  /** Subset the repo actually permits — the rest render disabled. */
  allowed: MergeMethod[];
  disabled: boolean;
  merging: boolean;
  onMerge: () => void;
  selected: MergeMethod;
  onSelect: (m: MergeMethod) => void;
}) {
  const PrimaryIcon = method.icon;
  const tone = disabled
    ? 'bg-muted text-muted-foreground cursor-not-allowed'
    : 'bg-pyor-pass text-white hover:bg-pyor-pass/90';
  return (
    <div className="inline-flex items-stretch overflow-hidden rounded-md shadow-sm">
      <button
        type="button"
        disabled={disabled}
        onClick={onMerge}
        className={`inline-flex h-8 items-center gap-1.5 px-3 text-[12.5px] font-semibold transition-colors ${tone}`}
      >
        {merging ? (
          <Loader2 className="size-3.5 animate-spin" />
        ) : (
          <PrimaryIcon className="size-3.5" />
        )}
        <span>{method.label}</span>
      </button>
      <span
        className={`w-px self-stretch ${disabled ? 'bg-border' : 'bg-white/25'}`}
      />
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            type="button"
            disabled={disabled}
            title="Choose merge method"
            className={`inline-flex h-8 items-center justify-center px-2 transition-colors ${tone}`}
          >
            <ChevronDownIcon className="size-3.5" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-[340px] p-1">
          <div className="px-2 pb-1 pt-1.5 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/70">
            Merge method
          </div>
          {options.map((m) => {
            const isAllowed = allowed.includes(m.id);
            const on = m.id === selected;
            const MIcon = m.icon;
            return (
              <DropdownMenuItem
                key={m.id}
                disabled={!isAllowed}
                onSelect={isAllowed ? () => onSelect(m.id) : undefined}
                className={`flex items-start gap-2 ${on ? 'bg-accent' : ''}`}
              >
                <span
                  className={`mt-0.5 inline-flex size-4 shrink-0 items-center justify-center ${
                    on ? 'text-foreground' : 'text-muted-foreground/60'
                  }`}
                >
                  {on ? (
                    <CheckCircle2Icon className="size-3.5" />
                  ) : (
                    <MIcon className="size-3.5" />
                  )}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-1.5 text-[12.5px] font-medium text-foreground">
                    {m.label}
                    {!isAllowed && (
                      <span className="rounded-sm bg-muted px-1 py-0.5 text-[9.5px] font-semibold uppercase tracking-wide text-muted-foreground">
                        Not enabled
                      </span>
                    )}
                  </span>
                  <span className="block text-[11px] leading-snug text-muted-foreground">
                    {isAllowed
                      ? m.hint
                      : 'Disabled in this repository’s merge settings.'}
                  </span>
                </span>
              </DropdownMenuItem>
            );
          })}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

function CloseConfirmDialog({
  open,
  onOpenChange,
  prNumber,
  busy,
  onConfirm,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  prNumber: number;
  busy: boolean;
  onConfirm: () => void;
}) {
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent className="max-w-[440px]">
        <AlertDialogHeader>
          <AlertDialogTitle>Close pull request #{prNumber}?</AlertDialogTitle>
          <AlertDialogDescription>
            The branch will not be merged. You can reopen this pull request
            later — comments and reviews are preserved.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel asChild>
            <Button variant="ghost" size="sm" disabled={busy}>
              Cancel
            </Button>
          </AlertDialogCancel>
          {/* preventDefault: stay open while the close mutation runs;
              the parent closes the dialog once it resolves. */}
          <AlertDialogAction asChild>
            <Button
              variant="destructive"
              size="sm"
              disabled={busy}
              onClick={(e) => {
                e.preventDefault();
                onConfirm();
              }}
            >
              {busy ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <XCircleIcon className="size-3.5" />
              )}
              Close pull request
            </Button>
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

// ── Helpers ─────────────────────────────────────────────────────

/** First non-empty line of a (possibly multi-line) check summary. */
function firstLine(text: string): string {
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (t) return t;
  }
  return '';
}
