// Pure grouping classifiers — one per dimension. Each maps a file to an
// AutoAssignment (group id + label + sort order) from data already on
// GHPullRequestFile (filename / additions / deletions). No clone, no
// static analysis — ADR 0002 safe. The "similar changes" dimension lives
// in similarity.ts because it needs the whole file set at once.

import type { GHPullRequestFile } from '../../../github/types';
import type { AutoAssignment, GroupingDimension } from './types';

/** Lowercased final extension (e.g. "tsx"), or '' for extension-less. */
function extensionOf(filename: string): string {
  const base = filename.slice(filename.lastIndexOf('/') + 1);
  const dot = base.lastIndexOf('.');
  return dot > 0 ? base.slice(dot + 1).toLowerCase() : '';
}

// extension → language category. A handful of common families collapse
// together (ts+tsx → TypeScript) so the rail shows meaningful folders
// rather than one-per-extension noise.
const EXT_CATEGORY: Record<string, string> = {
  ts: 'TypeScript', mts: 'TypeScript', cts: 'TypeScript',
  tsx: 'TSX',
  js: 'JavaScript', mjs: 'JavaScript', cjs: 'JavaScript',
  jsx: 'JSX',
  css: 'Styles', scss: 'Styles', sass: 'Styles', less: 'Styles',
  html: 'HTML', htm: 'HTML',
  json: 'JSON',
  yaml: 'YAML', yml: 'YAML',
  toml: 'Config', ini: 'Config', env: 'Config',
  md: 'Markdown', mdx: 'Markdown',
  py: 'Python',
  go: 'Go',
  rs: 'Rust',
  rb: 'Ruby',
  java: 'Java', kt: 'Kotlin', kts: 'Kotlin',
  swift: 'Swift',
  c: 'C/C++', h: 'C/C++', cc: 'C/C++', cpp: 'C/C++', hpp: 'C/C++', cxx: 'C/C++',
  cs: 'C#',
  php: 'PHP',
  sh: 'Shell', bash: 'Shell', zsh: 'Shell',
  sql: 'SQL',
  graphql: 'GraphQL', gql: 'GraphQL',
  proto: 'Protobuf',
  png: 'Images', jpg: 'Images', jpeg: 'Images', gif: 'Images',
  svg: 'Images', webp: 'Images', ico: 'Images',
};

// Some files are a cross-cutting *kind* rather than a language: a `.test.ts`,
// a `.stories.tsx`, or a `.d.ts` is review noise sitting next to real `.ts`
// source. We pull each kind into its own folder rather than inflating the
// source-language group. These overrides win over the extension map and all
// sort below the source groups (order 1) — checked most-specific first, since
// a story/type file is also valid TS.
function isTestFile(filename: string): boolean {
  // Filename suffix only — NOT the containing directory. A `__tests__/` or
  // `__mocks__/` folder routinely holds real component files (fixtures, mock
  // implementations like ColorPicker.jsx) that are not themselves tests.
  const base = filename.slice(filename.lastIndexOf('/') + 1);
  return (
    /\.(test|spec)\.[mc]?[jt]sx?$/i.test(base) || // JS/TS: foo.test.tsx, bar.spec.mjs
    /^test_.+\.py$/i.test(base) || // Python: test_foo.py
    /_test\.py$/i.test(base) || // Python: foo_test.py
    base.toLowerCase() === 'conftest.py' || // Python: pytest fixtures
    /_test\.go$/i.test(base) || // Go: foo_test.go
    /_(spec|test)\.rb$/i.test(base) || // Ruby: foo_spec.rb, foo_test.rb
    /(Test|Tests|Spec|Specs)\.(java|kt|cs|swift)$/.test(base) // JVM/C#/Swift camelCase
  );
}

/** Cross-cutting kind override, or null to fall through to the language map.
 * Order is intentional: tests beat stories beat types (a `foo.stories.tsx`
 * is also TS; a test of a story should still read as a test). */
function classifyByKind(filename: string): string | null {
  if (isTestFile(filename)) return 'Tests';
  const base = filename.slice(filename.lastIndexOf('/') + 1);
  if (/\.stories\.[mc]?[jt]sx?$/i.test(base)) return 'Stories'; // Storybook
  if (/\.mdx$/i.test(base) && /\.stories\./i.test(base)) return 'Stories';
  if (/\.d\.[mc]?ts$/i.test(base)) return 'Types'; // ambient type decls
  return null;
}

/** Group by language category. Heuristic dimension (singletons dissolve
 * to root via the ≥2 rule in arrange.ts). Cross-cutting kinds (Tests,
 * Stories, Types) route to their own folder (order 1 → below source). */
export function assignFileType(file: GHPullRequestFile): AutoAssignment {
  const kind = classifyByKind(file.filename);
  if (kind) return { groupId: `ft:${kind}`, groupLabel: kind, order: 1 };
  const ext = extensionOf(file.filename);
  const label = EXT_CATEGORY[ext] ?? 'Other';
  return { groupId: `ft:${label}`, groupLabel: label, order: 0 };
}

// Change-size buckets, smallest → largest. `order` drives folder order.
const SIZE_BUCKETS: ReadonlyArray<{ label: string; max: number }> = [
  { label: 'XS · ≤9 lines', max: 9 },
  { label: 'S · 10–49 lines', max: 49 },
  { label: 'M · 50–199 lines', max: 199 },
  { label: 'L · 200–499 lines', max: 499 },
  { label: 'XL · 500+ lines', max: Infinity },
];

/** Group by total changed lines (additions + deletions). Fixed-bucket
 * dimension — even a single-file bucket renders as a folder. */
export function assignChangeSize(file: GHPullRequestFile): AutoAssignment {
  const total = file.additions + file.deletions;
  const order = SIZE_BUCKETS.findIndex((b) => total <= b.max);
  const bucket = SIZE_BUCKETS[order] ?? SIZE_BUCKETS[SIZE_BUCKETS.length - 1];
  return { groupId: `sz:${bucket.label}`, groupLabel: bucket.label, order };
}

/** Whether a dimension always shows a folder even for a single member
 * (fixed buckets) vs dissolving singletons to loose-at-root (heuristic). */
export function alwaysBuckets(dimension: GroupingDimension): boolean {
  // change-size has fixed buckets; AI groups are authored by the model and
  // respected even when a group has a single member.
  return dimension === 'change-size' || dimension === 'ai';
}

export const DIMENSION_LABELS: Record<GroupingDimension, string> = {
  none: 'None (flat list)',
  'file-type': 'File type',
  similar: 'Similar changes',
  'change-size': 'Change size',
  ai: 'AI',
};
