// Shared "note row" shell for content-less diff items — the body card shown
// in place of a hidden synthetic diff body (pure rename/move, non-image
// binary, and any future no-diff-to-show case). All three share the same
// chrome: a hatched backdrop, a centered `bg-card` row with an icon circle,
// a title + one-line note, and right-aligned actions. Only the accent, icon,
// copy, and actions vary — so they live here once and the per-kind modules
// (renameTreatment, binaryTreatment) stay thin.
//
// NOT for the image diff (before/after preview panes — structurally
// different); that's ImageDiffSection.

import type { LucideIcon } from 'lucide-react';
import type { ReactNode } from 'react';

/** Diagonal hatch behind the card — signals "intentionally empty body". */
const HATCH =
  'repeating-linear-gradient(135deg, hsl(var(--muted-foreground) / 0.05) 0 7px, transparent 7px 14px)';

/** Icon-circle accent. `link` = the rename blue (a real status change);
 *  `muted` = neutral grey (nothing to render). */
type Accent = 'muted' | 'link';

const ACCENT: Record<Accent, { bg: string; fg: string }> = {
  muted: { bg: 'bg-muted', fg: 'text-muted-foreground' },
  link: { bg: 'bg-pyor-link/10', fg: 'text-pyor-link' },
};

export function DiffNoteCard({
  icon: Icon,
  accent = 'muted',
  title,
  note,
  actions,
}: {
  icon: LucideIcon;
  accent?: Accent;
  title: string;
  note: string;
  /** Right-aligned action controls (use `DiffNoteAction`). Omit for none. */
  actions?: ReactNode;
}) {
  const { bg, fg } = ACCENT[accent];
  return (
    <div className="px-3 py-3.5" style={{ backgroundImage: HATCH }}>
      <div className="mx-auto flex items-center gap-3 rounded-md border bg-card px-3.5 py-2.5">
        <span
          className={`inline-flex size-7 shrink-0 items-center justify-center rounded-full ${bg}`}
        >
          <Icon className={`size-3.5 ${fg}`} />
        </span>
        <div className="min-w-0">
          <div className="text-[12.5px] font-medium text-foreground">
            {title}
          </div>
          <div className="text-[12px] leading-snug text-muted-foreground">
            {note}
          </div>
        </div>
        {actions && (
          <div className="ml-auto flex shrink-0 items-center gap-2">
            {actions}
          </div>
        )}
      </div>
    </div>
  );
}

/** One action in a `DiffNoteCard` — renders an external link when `href` is
 *  set, otherwise a button. Same chrome either way. */
export function DiffNoteAction({
  icon: Icon,
  label,
  href,
  onClick,
}: {
  icon: LucideIcon;
  label: string;
  href?: string;
  onClick?: () => void;
}) {
  const className =
    'inline-flex items-center gap-1.5 rounded-md border bg-card px-2.5 py-1 text-[11.5px] font-medium text-muted-foreground hover:text-foreground';
  if (href) {
    return (
      <a href={href} target="_blank" rel="noreferrer" className={className}>
        <Icon className="size-3.5" />
        {label}
      </a>
    );
  }
  return (
    <button type="button" onClick={onClick} className={className}>
      <Icon className="size-3.5" />
      {label}
    </button>
  );
}
