// Per-row state hook for the Local Reviews list (ADR 0012 Phase 7).
//
// Every row's status badge + commits column needs four signals:
//   - prOpened    — `GET /repos/{owner}/{repo}/pulls?head=…&state=open`
//   - behind      — `git rev-list --count base..head`
//   - ahead       — `git rev-list --count head..base` (computed together
//                    with `behind` in a single subprocess via
//                    `aheadBehind`)
//   - notesActive — count of !dismissed LocalReviewComments
//
// We fan all of these out from a single `useQuery` keyed by
// `(reviewId, branch, base, worktreePath)`. The list-level helper
// `useLocalReviewRowStates(reviews)` batches across the visible rows
// via `useQueries` so the filter/sort layer can read every row's status
// without each row mounting its own hook.
//
// Caching:
//   - `staleTime: 5 * 60 * 1000` — matches the ADR's "TanStack-cached
//     5min" commitment so we don't re-poll GitHub on every render.
//   - `refetchOnWindowFocus: true` — the user coming back to the app is
//     the right moment to recheck (a PR may have been opened from the
//     CLI in the meantime).
//
// Cross-window note count: the notes count lives on the LocalReview
// comments storage key. The `useLocalReviewComments` hook already
// subscribes to the `storage` event for cross-window sync; we read the
// count synchronously from localStorage inside the queryFn AND surface
// the comments-list query so React re-renders when comments change in
// any window.

import {
  useQueries,
  useQuery,
  type UseQueryResult,
} from '@tanstack/react-query';
import { useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { bridge, isElectron } from '../desktop/electronBridge';
import { findOpenPRForBranch } from '../github/client';
import { listLocalReviewComments } from './localReviewComments';
import type { LocalReview } from './localReviews';
import {
  computeLocalReviewStatus,
  type LocalReviewStatus,
} from './localReviewStatus';

export interface LocalReviewRowState {
  status: LocalReviewStatus;
  ahead: number;
  behind: number;
  /** Count of !dismissed comments — drives `in-progress`. */
  notesActive: number;
  /** Total comment count (dismissed + active) — what the row's notes
   * column displays. */
  notesTotal: number;
  /** Open PR number, when one was detected for this (branch, base). */
  prNumber?: number;
  /** Open PR HTML URL — for the "Open PR" action. */
  prHtmlUrl?: string;
}

const FIVE_MIN = 5 * 60 * 1000;

/** Internal — synchronous comment count read off localStorage. The
 * `storage` event listener wired below invalidates the row query when
 * the count changes in another window. */
function readNoteCounts(reviewId: string): {
  notesActive: number;
  notesTotal: number;
} {
  const list = listLocalReviewComments(reviewId);
  let active = 0;
  for (const c of list) if (!c.dismissed) active += 1;
  return { notesActive: active, notesTotal: list.length };
}

/** Default state used while the query is pending or on the web build
 * (no bridge). `status: 'ready'` matches `computeLocalReviewStatus`'s
 * default fallback so badge variants are stable. */
const DEFAULT_STATE: LocalReviewRowState = {
  status: 'ready',
  ahead: 0,
  behind: 0,
  notesActive: 0,
  notesTotal: 0,
};

/** Build the queryKey for one row. Exposed for the cross-window
 * invalidation hook below; keep `reviewId` first so it's the cheap
 * partial-match prefix. */
function rowKey(review: LocalReview) {
  return [
    'local-review-row',
    review.id,
    review.branch,
    review.base,
    review.worktreePath,
  ] as const;
}

/** Fetch all four signals for a single row. Pure async — caller wires
 * it into either `useQuery` (single row) or `useQueries` (list). */
async function fetchRowState(
  review: LocalReview,
): Promise<LocalReviewRowState> {
  const b = bridge();
  // No bridge: return defaults + notes counts (notes are renderer-side
  // localStorage, still available on web). PR detection / ahead-behind
  // require the bridge.
  const noteCounts = readNoteCounts(review.id);
  if (!b) {
    return {
      ...DEFAULT_STATE,
      ...noteCounts,
      status: computeLocalReviewStatus({
        prOpened: false,
        behind: 0,
        ahead: 0,
        notesActive: noteCounts.notesActive,
      }),
    };
  }

  // Ahead/behind + origin slug fan out in parallel — neither depends
  // on the other. PR detection waits on the slug.
  const [counts, slug] = await Promise.all([
    b
      .localRepoAheadBehind(review.worktreePath, review.base, review.branch)
      .catch(() => ({ ahead: 0, behind: 0 })),
    b.localRepoOriginSlug(review.repoPath).catch(() => null),
  ]);

  let prNumber: number | undefined;
  let prHtmlUrl: string | undefined;
  if (slug) {
    const [owner, repo] = slug.split('/');
    if (owner && repo) {
      try {
        const found = await findOpenPRForBranch(
          owner,
          repo,
          review.branch,
          review.base,
        );
        if (found) {
          prNumber = found.number;
          prHtmlUrl = found.html_url;
        }
      } catch {
        // Network down / no token / 403 — silently treat as "no PR".
        // The row stays informative; the status badge falls back to
        // ahead/behind/notes-driven values.
      }
    }
  }

  const status = computeLocalReviewStatus({
    prOpened: prNumber != null,
    behind: counts.behind,
    ahead: counts.ahead,
    notesActive: noteCounts.notesActive,
  });

  return {
    status,
    ahead: counts.ahead,
    behind: counts.behind,
    ...noteCounts,
    prNumber,
    prHtmlUrl,
  };
}

/** Subscribe to localStorage `storage` events for a review's comments
 * key. Invalidates the per-row query when comments change in another
 * window so the notes count + `in-progress` status stay current. The
 * list-level batch hook calls this once per review. */
function useStorageInvalidation(reviews: LocalReview[]): void {
  const qc = useQueryClient();
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const expected = new Map<string, LocalReview>();
    for (const r of reviews) {
      expected.set(`pyor:local-review-comments:${r.id}`, r);
    }
    const onStorage = (e: StorageEvent) => {
      // null key fires on `localStorage.clear()` — invalidate everyone.
      if (e.key === null) {
        for (const r of reviews) {
          void qc.invalidateQueries({ queryKey: rowKey(r) });
        }
        return;
      }
      const r = expected.get(e.key);
      if (r) void qc.invalidateQueries({ queryKey: rowKey(r) });
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, [qc, reviews]);
}

/** Single-row hook. Mostly here for one-off callsites; the list page
 * uses the batch helper below. */
export function useLocalReviewRowState(
  review: LocalReview,
): UseQueryResult<LocalReviewRowState> {
  useStorageInvalidation([review]);
  return useQuery({
    queryKey: rowKey(review),
    queryFn: () => fetchRowState(review),
    enabled: isElectron(),
    staleTime: FIVE_MIN,
    refetchOnWindowFocus: true,
  });
}

/** Batched variant — fans out a `useQueries` over every row. The list
 * page uses this so the filter + sort layer can read every row's
 * status synchronously without each row mounting its own query. */
export function useLocalReviewRowStates(
  reviews: LocalReview[],
): Map<string, LocalReviewRowState> {
  useStorageInvalidation(reviews);
  const results = useQueries({
    queries: reviews.map((review) => ({
      queryKey: rowKey(review),
      queryFn: () => fetchRowState(review),
      enabled: isElectron(),
      staleTime: FIVE_MIN,
      refetchOnWindowFocus: true,
    })),
  });
  const out = new Map<string, LocalReviewRowState>();
  for (let i = 0; i < reviews.length; i += 1) {
    const r = reviews[i];
    const res = results[i];
    out.set(r.id, res.data ?? DEFAULT_STATE);
  }
  return out;
}
