// Small shared building blocks for the Team radar — the codebase's
// equivalents of the handoff's OrgGlyph / SAvatar / ReviewerCluster.

import { CheckIcon } from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import type { TeamOrg, TeamReviewer } from '../../github/teamLens';

/** GitHub serves a public avatar for any login at `/{login}.png`. */
function avatarFor(login: string): string {
  return `https://github.com/${login}.png?size=48`;
}

function initials(name: string): string {
  return (
    name
      .split(/[\s-]+/)
      .map((s) => s[0])
      .slice(0, 2)
      .join('')
      .toUpperCase() || '·'
  );
}

export function TeamAvatar({
  login,
  url,
  className,
}: {
  login: string;
  url?: string;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-6', className)}>
      <AvatarImage src={url || avatarFor(login)} alt={login} />
      <AvatarFallback className="text-[8px] font-semibold">
        {initials(login)}
      </AvatarFallback>
    </Avatar>
  );
}

/** The org's real avatar/logo (rounded square), falling back to a flat
 * neutral two-letter glyph when the org has no avatar URL. */
export function OrgGlyph({
  org,
  className = 'size-6',
  text = 'text-[10px]',
}: {
  org: TeamOrg | undefined;
  className?: string;
  text?: string;
}) {
  if (org?.avatarUrl) {
    return (
      <img
        src={org.avatarUrl}
        alt={org.name}
        className={cn('shrink-0 rounded-md object-cover', className)}
      />
    );
  }
  return (
    <span
      className={cn(
        'inline-flex shrink-0 items-center justify-center rounded-md bg-zinc-900 font-semibold tracking-tight text-white dark:bg-zinc-100 dark:text-zinc-900',
        className,
        text,
      )}
    >
      {org?.glyph ?? '?'}
    </span>
  );
}

const RING: Record<TeamReviewer['state'], string> = {
  approved: 'ring-emerald-500',
  changes: 'ring-red-500',
  pending: 'ring-zinc-300',
  commented: 'ring-blue-400',
};

const STATE_LABEL: Record<TeamReviewer['state'], string> = {
  approved: 'approved',
  changes: 'requested changes',
  pending: 'review pending',
  commented: 'commented',
};

/** Overlapping reviewer avatars, each ringed by its review state. */
export function ReviewerCluster({
  reviewers,
  you,
}: {
  reviewers: TeamReviewer[];
  you: string;
}) {
  if (reviewers.length === 0) {
    return <span className="text-[11px] text-muted-foreground">—</span>;
  }
  return (
    // `isolate` keeps the per-avatar z-index (used only for their mutual
    // overlap) in a local stacking context, so they don't paint over the
    // sticky bucket headers as a row scrolls underneath one.
    <div className="isolate flex items-center -space-x-1.5">
      {reviewers.map((r, i) => (
        <Tooltip key={`${r.name}-${i}`}>
          <TooltipTrigger asChild>
            <span
              className={cn('relative inline-block rounded-full ring-2', RING[r.state])}
              style={{ zIndex: 10 - i }}
            >
              <TeamAvatar login={r.name} className="size-5" />
              {r.state === 'approved' && (
                <span className="absolute -bottom-0.5 -right-0.5 inline-flex size-2.5 items-center justify-center rounded-full bg-emerald-500 ring-2 ring-card">
                  <CheckIcon className="size-1.5 text-white" strokeWidth={4} />
                </span>
              )}
              {r.state === 'changes' && (
                <span className="absolute -bottom-0.5 -right-0.5 size-2.5 rounded-full bg-red-500 ring-2 ring-card" />
              )}
            </span>
          </TooltipTrigger>
          <TooltipContent>
            {r.name === you ? 'you' : r.name} · {STATE_LABEL[r.state]}
          </TooltipContent>
        </Tooltip>
      ))}
    </div>
  );
}
