import {
  CheckCircle2Icon,
  Loader2,
  XCircleIcon,
  type LucideIcon,
} from 'lucide-react';
import type { RollupBucket } from '../github/types';

// Single source of truth for the status icon + colour of a check-run
// bucket. Shared by the MergeBox check list (foot of Conversation) and
// the ChecksHoverCard (PR header) so pending/neutral never get
// mis-rendered as a green pass in one surface but not the other.
//
// `historical` mutes the alarm colours for merged/closed PRs, where the
// list is a frozen record rather than a live signal.
export function checkBucketIcon(
  bucket: RollupBucket,
  historical = false,
): { Icon: LucideIcon; color: string } {
  if (historical) {
    const Icon =
      bucket === 'fail'
        ? XCircleIcon
        : bucket === 'pending'
          ? Loader2
          : CheckCircle2Icon;
    return { Icon, color: 'text-muted-foreground' };
  }
  switch (bucket) {
    case 'pass':
      return { Icon: CheckCircle2Icon, color: 'text-pyor-pass' };
    case 'fail':
      return { Icon: XCircleIcon, color: 'text-pyor-fail' };
    case 'pending':
      return { Icon: Loader2, color: 'text-pyor-warn animate-spin' };
    default:
      return { Icon: CheckCircle2Icon, color: 'text-muted-foreground/60' };
  }
}
