// TanStack hooks over the LocalReviewComment localStorage store.
// Same pattern as useLocalReviews.ts — synchronous reads wrapped in
// useQuery so mutations + cross-window storage events drive
// re-renders.

import {
  useMutation,
  useQuery,
  useQueryClient,
  type UseQueryResult,
} from '@tanstack/react-query';
import { useEffect } from 'react';
import {
  createLocalReviewComment,
  deleteLocalReviewComment,
  listLocalReviewComments,
  updateLocalReviewComment,
  type LocalReviewComment,
} from './localReviewComments';

const KEY = (reviewId: string) => ['local-review-comments', reviewId] as const;

export function useLocalReviewComments(
  reviewId: string | null,
): UseQueryResult<LocalReviewComment[]> {
  const qc = useQueryClient();
  useEffect(() => {
    if (!reviewId) return;
    const expected = `pyor:local-review-comments:${reviewId}`;
    const onStorage = (e: StorageEvent) => {
      if (e.key === expected || e.key === null) {
        void qc.invalidateQueries({ queryKey: KEY(reviewId) });
      }
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, [qc, reviewId]);
  return useQuery({
    queryKey: KEY(reviewId ?? '__none__'),
    queryFn: () => (reviewId ? listLocalReviewComments(reviewId) : []),
    enabled: !!reviewId,
    staleTime: Infinity,
  });
}

/** Lightweight count-only helper for the Local Reviews list rows.
 * Skips the full useQuery wiring — reads localStorage directly per
 * row render. Cheap enough at v1 scale. */
export function useLocalReviewCommentCount(reviewId: string): number {
  // Subscribes via useQuery so the count updates when comments change.
  const { data } = useLocalReviewComments(reviewId);
  return data?.length ?? 0;
}

export function useCreateLocalReviewComment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (input: Parameters<typeof createLocalReviewComment>[0]) =>
      Promise.resolve(createLocalReviewComment(input)),
    onSuccess: (created) => {
      void qc.invalidateQueries({ queryKey: KEY(created.reviewId) });
    },
  });
}

export function useUpdateLocalReviewComment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({
      reviewId,
      commentId,
      patch,
    }: {
      reviewId: string;
      commentId: string;
      patch: Parameters<typeof updateLocalReviewComment>[2];
    }) => Promise.resolve(updateLocalReviewComment(reviewId, commentId, patch)),
    onSuccess: (_, vars) => {
      void qc.invalidateQueries({ queryKey: KEY(vars.reviewId) });
    },
  });
}

export function useDeleteLocalReviewComment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({
      reviewId,
      commentId,
    }: {
      reviewId: string;
      commentId: string;
    }) => Promise.resolve(deleteLocalReviewComment(reviewId, commentId)),
    onSuccess: (_, vars) => {
      void qc.invalidateQueries({ queryKey: KEY(vars.reviewId) });
    },
  });
}
