// Theme bridge for @pierre/trees.
//
// The lib renders inside a shadow root so our stylesheet rules don't
// reach inside. The lib reads its palette from CSS custom properties
// on the host element, in this fallback order:
//
//   1. --trees-*-override            (explicit, what we set here)
//   2. --trees-theme-*               (Shiki/VS Code-style tokens)
//   3. lib defaults
//
// We use overrides because:
//   - They take precedence over theme tokens, so the Pyor app theme
//     wins regardless of what theme Shiki has loaded for the diff.
//   - They mean we don't need to import Shiki here or wait for the
//     highlighter to resolve.
//
// Post-ADR 0011: the values are sourced from the shadcn CSS variables
// published in `styles/tailwind.css` (`--foreground`, `--card`,
// `--primary`, `--pyor-pass`, etc). Light/dark flip via the
// `.pyor-dark` class on the body; the bridge stays palette-agnostic.

import type { CSSProperties } from 'react';

/** Build the CSS-variable override style for a single PierreFileTree
 * host. Values resolve through Tailwind's HSL-channel custom properties
 * so they flip automatically with the active palette. */
export function treeThemeStyle(): CSSProperties {
  // CSS custom properties aren't typed in React's CSSProperties — we
  // cast through Record<string,string> for the bridge, same pattern we
  // use elsewhere for var(--token) injection.
  return {
    // Compact the row spacing — lib default is 1.
    '--trees-density-override': '0.3',

    '--trees-fg-override': 'hsl(var(--foreground))',
    '--trees-fg-muted-override': 'hsl(var(--muted-foreground))',
    '--trees-bg-override': 'hsl(var(--background))',
    '--trees-bg-muted-override': 'hsl(var(--card))',
    '--trees-accent-override': 'hsl(var(--primary))',
    '--trees-border-color-override': 'hsl(var(--border))',

    '--trees-focus-ring-color-override': 'hsl(var(--primary))',

    '--trees-search-fg-override': 'hsl(var(--foreground))',
    '--trees-search-bg-override': 'hsl(var(--background))',

    '--trees-selected-fg-override': 'hsl(var(--foreground))',
    // Alpha-modulated primary works for both palettes — the underlying
    // --primary already shifts between #0a84ff (light) and #5aa9ff (dark)
    // via the .pyor-dark scope, so 15% opacity reads correctly in both.
    '--trees-selected-bg-override': 'hsl(var(--primary) / 0.15)',
    '--trees-selected-focused-border-color-override': 'hsl(var(--primary))',

    // Git-status lane — line up with our diff palette so an added
    // file row and an added-line are the same green.
    '--trees-status-added-override': 'hsl(var(--pyor-pass))',
    '--trees-status-modified-override': 'hsl(var(--pyor-warn))',
    '--trees-status-deleted-override': 'hsl(var(--pyor-fail))',
    '--trees-status-renamed-override': 'hsl(var(--primary))',
    '--trees-status-untracked-override': 'hsl(var(--muted-foreground) / 0.7)',
    '--trees-status-ignored-override': 'hsl(var(--muted-foreground) / 0.5)',
  } as CSSProperties;
}
