// Leaf module: the broker error contract, with no implementation imports.
//
// `BrokerError` lived in oauthBroker.ts, which also imports the mock/real
// broker implementations. Those implementations import `BrokerError` back,
// creating a value-level import cycle (oauthBroker → {mock,real}Broker →
// oauthBroker) that can break module-init order and defeat tree-shaking.
// Keeping the error + its kind here, with zero broker imports, breaks the cycle.

/** The five terminal error states the sign-in flow can land in. */
export type AuthErrorKind =
  | 'expired'
  | 'cancelled'
  | 'no-repos'
  | 'org-approval'
  | 'offline';

export class BrokerError extends Error {
  constructor(
    public kind: AuthErrorKind,
    message?: string,
  ) {
    super(message ?? kind);
    this.name = 'BrokerError';
  }
}
