/**
 * Decide the effective `collapsed` for each item:
 *   manualOverride('open')   → expanded
 *   manualOverride('closed') → collapsed
 *   no override               → fall back to viewedSet.has(path)
 *
 * Mark-viewed auto-collapses; the chevron in the file header lets the
 * user override either direction without touching viewed-state.
 *
 * `collapsed` is part of CodeViewDiffItem so the lib treats it as
 * controlled state — same `version`-bump trap as the annotations one
 * (CodeView.js:815). We flip a high bit in the version when collapsed
 * flips so the lib's syncItemRecord actually re-renders.
 */
export function withCollapsedFromViewed(
  items: ThreadDiffItem[],
  viewedSet: ReadonlySet<string> | undefined,
  collapseOverrides?: ReadonlyMap<string, 'open' | 'closed'>,
  /** Loading placeholders — always force-collapsed regardless of
   * viewedSet / overrides. The synthetic fileDiff body is a stub
   * that should never be shown to the user; we replace the item
   * with the real diff on the next buildDiff pass once content
   * lands, at which point this set no longer contains the path
   * and normal viewedSet / override logic resumes. */
  loadingFilenames?: ReadonlySet<string>,
): ThreadDiffItem[] {
  const hasViewed = !!viewedSet && viewedSet.size > 0;
  const hasOverrides = !!collapseOverrides && collapseOverrides.size > 0;
  const hasLoading = !!loadingFilenames && loadingFilenames.size > 0;
  if (!hasViewed && !hasOverrides && !hasLoading) return items;
  return items.map((item) => {
    const baseHash = hashAnnotations(item.annotations ?? []);
    if (hasLoading && loadingFilenames!.has(item.id)) {
      // Loading placeholders are always collapsed AND need a
      // distinct version sentinel from the loaded-collapsed case.
      // Without this, the next buildDiff pass (with the file's
      // real content) would produce an item whose version XOR'd
      // by ~viewed/override math matches the placeholder's
      // version exactly → CodeView's syncItemRecord short-circuits
      // (item.version === nextItem.version → return false), never
      // calls setOptions on the underlying File, and the body
      // never renders. The placeholder header just stays glued
      // there with "Loading…" forever.
      const placeholderVersion = baseHash ^ 0x20000000;
      if (item.collapsed === true && item.version === placeholderVersion) {
        return item;
      }
      return {
        ...item,
        collapsed: true,
        version: placeholderVersion,
      };
    }
    const auto = hasViewed ? viewedSet!.has(item.id) : false;
    const override = collapseOverrides?.get(item.id);
    const shouldCollapse =
      override === 'open' ? false : override === 'closed' ? true : auto;
    if (item.collapsed === shouldCollapse) return item;
    return {
      ...item,
      collapsed: shouldCollapse,
      version: shouldCollapse ? baseHash ^ 0x40000000 : baseHash,
    };
  });
}

