// shadcn's standard className composer — merge Tailwind classes with
// tailwind-merge's conflict resolution so e.g. `cn('p-2', 'p-4')` →
// 'p-4' instead of the both-classes-applied mess clsx alone gives.

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
