// Browser logos for the Helper first-run nudge. Official vendor marks
// (Chrome/Firefox/Edge/Brave/Vivaldi/Opera/Chromium from alrra/browser-logos,
// Arc from svgl, Zen from simple-icons) — nominative use for an "Add Pyor to
// <Browser>" CTA. One per browser the default-browser detector recognises.
// Imported as URLs (Vite default; no svgr) and rendered via <img> so the
// multi-gradient SVGs can't collide on shared <defs> ids when the glyph appears
// more than once on screen.

import chromeLogo from './logos/chrome.svg';
import chromiumLogo from './logos/chromium.svg';
import edgeLogo from './logos/edge.svg';
import braveLogo from './logos/brave.svg';
import vivaldiLogo from './logos/vivaldi.svg';
import operaLogo from './logos/opera.svg';
import firefoxLogo from './logos/firefox.svg';
import arcLogo from './logos/arc.svg';
import zenLogo from './logos/zen.svg';

type BrowserGlyphKind =
  | 'chrome'
  | 'chromium'
  | 'edge'
  | 'brave'
  | 'vivaldi'
  | 'opera'
  | 'firefox'
  | 'arc'
  | 'zen';

const LOGOS: Record<BrowserGlyphKind, string> = {
  chrome: chromeLogo,
  chromium: chromiumLogo,
  edge: edgeLogo,
  brave: braveLogo,
  vivaldi: vivaldiLogo,
  opera: operaLogo,
  firefox: firefoxLogo,
  arc: arcLogo,
  zen: zenLogo,
};

interface Props {
  kind: BrowserGlyphKind;
  size?: number;
}

export function BrowserGlyph({ kind, size = 20 }: Props) {
  return (
    <img
      src={LOGOS[kind]}
      width={size}
      height={size}
      alt=""
      aria-hidden
      draggable={false}
      style={{ display: 'block', objectFit: 'contain' }}
    />
  );
}
