// AI brand-layer primitives (ADR 0026 / design spec). Violet is AI-only;
// errors use amber+zinc (never red — red is CI status); empty hint result
// is a positive outcome (emerald). Ported 1:1 from the approved prototype
// to real shadcn/lucide/Tailwind-v4 conventions.

import { useState, type ReactNode } from 'react';
import {
  AlertTriangle,
  ArrowRight,
  CheckCircle2,
  ChevronDown,
  Clock,
  Gauge,
  Info,
  KeyRound,
  Lock,
  MessageSquarePlus,
  RefreshCw,
  ServerCrash,
  WifiOff,
  X,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { AiMark } from './AiMark';
import { AiTypeIcon } from './AiTypeIcon';
import { AI_HINT_TYPES, AI_SEVERITY, type AiHintType, type AiSeverity } from './taxonomy';

// ── Severity bar — 3 segments, NOT color alone (colorblind-safe) ──────
export function AiSeverityBar({
  severity = 'warn',
  className = '',
}: {
  severity?: AiSeverity;
  className?: string;
}) {
  const level = AI_SEVERITY[severity]?.level ?? 2;
  return (
    <span
      className={cn('inline-flex items-end gap-[2px]', className)}
      title={`Severity · ${AI_SEVERITY[severity]?.label}`}
    >
      {[1, 2, 3].map((i) => (
        <span
          key={i}
          className={cn('w-[3px] rounded-[1px]', i <= level ? 'bg-violet-500' : 'bg-violet-200')}
          style={{ height: 4 + i * 2 }}
        />
      ))}
    </span>
  );
}

// ── Type pill — hint header + filter bar ──────────────────────────────
export function AiTypePill({
  type,
  severity,
  active = true,
  className = '',
  onClick,
}: {
  type: AiHintType;
  severity?: AiSeverity;
  active?: boolean;
  className?: string;
  onClick?: () => void;
}) {
  const t = AI_HINT_TYPES[type] ?? { label: type, short: type };
  return (
    <span
      onClick={onClick}
      className={cn(
        'inline-flex items-center gap-1.5 rounded-md px-1.5 py-0.5 text-[11px] font-medium',
        active ? 'bg-violet-100 text-violet-700' : 'bg-muted text-muted-foreground',
        onClick && 'cursor-pointer',
        className,
      )}
    >
      <AiTypeIcon type={type} className="size-3" />
      {t.short}
      {severity && <AiSeverityBar severity={severity} className="ml-0.5" />}
    </span>
  );
}

// ── "AI-generated · may be inaccurate" — always present on output ─────
export function AiDisclaimer({
  size = 'sm',
  className = '',
}: {
  size?: 'sm' | 'md';
  className?: string;
}) {
  const sm = size === 'sm';
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 font-medium text-violet-600',
        sm ? 'text-[10.5px]' : 'text-[11.5px]',
        className,
      )}
    >
      <AiMark className={sm ? 'size-3' : 'size-3.5'} />
      <span>
        AI-generated<span className="text-violet-400"> · may be inaccurate</span>
      </span>
    </span>
  );
}

// ── Cost / token meter — estimate before a run, actuals after ─────────
export function AiCostMeter({
  mode = 'estimate',
  tokens,
  cost,
  secs,
  provider,
  model,
  className = '',
}: {
  mode?: 'estimate' | 'actual';
  tokens?: string;
  cost?: string;
  secs?: string;
  provider?: string;
  model?: string;
  className?: string;
}) {
  const est = mode === 'estimate';
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 font-mono text-[10.5px] tabular-nums text-muted-foreground',
        className,
      )}
    >
      <Gauge className="size-3 text-muted-foreground" />
      {est ? (
        <span>
          ~{tokens ?? '12k'} tokens · ~{cost ?? '$0.04'} <span className="text-muted-foreground/70">est.</span>
        </span>
      ) : (
        <span>
          {tokens ?? '11.8k'} tokens · {cost ?? '$0.038'}
          {secs ? ` · ${secs}` : ''}
        </span>
      )}
      {(provider || model) && <span className="text-muted-foreground/70">·</span>}
      {(provider || model) && <span className="text-muted-foreground">{model || provider}</span>}
    </span>
  );
}

// ── AI button — violet sibling of the app Button (AI CTAs only) ───────
export function AiButton({
  variant = 'solid',
  size = 'sm',
  icon,
  mark = false,
  children,
  className = '',
  disabled = false,
  onClick,
  title,
}: {
  variant?: 'solid' | 'outline' | 'ghost' | 'subtle';
  size?: 'xs' | 'sm' | 'lg';
  icon?: 'refresh' | 'draft';
  mark?: boolean;
  children?: ReactNode;
  className?: string;
  disabled?: boolean;
  onClick?: () => void;
  title?: string;
}) {
  const h =
    size === 'sm'
      ? 'h-7 px-2.5 text-[12px]'
      : size === 'xs'
        ? 'h-6 px-2 text-[11.5px]'
        : 'h-8 px-3 text-[13px]';
  const styles = {
    solid: 'bg-violet-600 text-white hover:bg-violet-700 shadow-sm',
    outline: 'border border-violet-300 bg-background text-violet-700 hover:bg-violet-50',
    ghost: 'text-violet-700 hover:bg-violet-50',
    subtle: 'bg-violet-100 text-violet-700 hover:bg-violet-200',
  }[variant];
  const iconSize = size === 'lg' ? 'size-4' : 'size-3.5';
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      title={title}
      className={cn(
        'inline-flex items-center justify-center gap-1.5 rounded-md font-medium transition-colors',
        h,
        styles,
        disabled && 'cursor-not-allowed opacity-50',
        className,
      )}
    >
      {mark && <AiMark className={iconSize} solid={variant === 'solid'} />}
      {icon === 'refresh' && !mark && <RefreshCw className={iconSize} />}
      {icon === 'draft' && !mark && <MessageSquarePlus className={iconSize} />}
      {children}
    </button>
  );
}

// ── Stale / re-run banner — shown after a new commit lands ────────────
export function AiStaleBanner({
  kind = 'inline',
  onRun,
  commit = 'e2b9c14',
  dismissible = true,
  onDismiss,
  className = '',
}: {
  kind?: 'inline' | 'compact';
  onRun?: () => void;
  commit?: string;
  /** Show a trailing × that clears the banner for the session. Default true. */
  dismissible?: boolean;
  onDismiss?: () => void;
  className?: string;
}) {
  const compact = kind === 'compact';
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;
  return (
    <div
      className={cn(
        'flex items-center gap-2 rounded-md border border-amber-300/70 bg-amber-50 px-2.5 dark:border-amber-500/40 dark:bg-amber-500/10',
        compact ? 'py-1' : 'py-1.5',
        className,
      )}
    >
      <AlertTriangle className="size-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
      <span
        className={cn(
          'flex-1 text-amber-800 dark:text-amber-300',
          compact ? 'text-[11px]' : 'text-[11.5px]',
        )}
      >
        Diff changed since this ran{' '}
        <span className="font-mono text-amber-700/80 dark:text-amber-400/80">
          · new commit {commit}
        </span>
      </span>
      <AiButton
        variant="outline"
        size="xs"
        icon="refresh"
        onClick={onRun}
        className="border-amber-300 text-amber-800 hover:bg-amber-100 dark:text-amber-300 dark:hover:bg-amber-500/20"
      >
        Re-run
      </AiButton>
      {dismissible && (
        <button
          type="button"
          title="Dismiss"
          onClick={() => {
            setDismissed(true);
            onDismiss?.();
          }}
          className="-mr-0.5 inline-flex size-5 shrink-0 items-center justify-center rounded text-amber-700/70 hover:bg-amber-100 hover:text-amber-800 dark:text-amber-400/70 dark:hover:bg-amber-500/20 dark:hover:text-amber-300"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  );
}

// ── Indeterminate "thinking" shimmer for loading states ───────────────
export function AiThinking({
  label = 'Analyzing the diff…',
  sub,
  className = '',
}: {
  label?: string;
  sub?: string;
  className?: string;
}) {
  return (
    <div className={cn('inline-flex items-center gap-2', className)}>
      <span className="relative inline-flex size-4 items-center justify-center text-violet-600">
        <AiMark className="size-4 ai-pulse" />
      </span>
      <span className="text-[12px] font-medium text-violet-700">{label}</span>
      {sub && <span className="text-[11.5px] text-muted-foreground">{sub}</span>}
    </div>
  );
}

// ── Set-up affordance — deep-links to Settings · AI assistance ────────
export function AiSetupAffordance({
  size = 'sm',
  label = 'Set up AI',
  className = '',
  onClick,
}: {
  size?: 'sm' | 'md';
  label?: string;
  className?: string;
  onClick?: () => void;
}) {
  const sm = size === 'sm';
  return (
    <span
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') onClick?.();
      }}
      className={cn(
        'inline-flex cursor-pointer items-center gap-1 font-medium text-violet-700 hover:text-violet-800 hover:underline',
        sm ? 'text-[11.5px]' : 'text-[12.5px]',
        className,
      )}
    >
      <AiMark className={sm ? 'size-3' : 'size-3.5'} />
      {label}
      <ArrowRight className={sm ? 'size-3' : 'size-3.5'} />
    </span>
  );
}

// ── Per-file progress — runs chunk over files, with capped disclosure ─
export function AiProgress({
  label = 'Analyzing',
  total = 0,
  capped = null,
  onCancel,
  className = '',
}: {
  label?: string;
  /** Files being analyzed this run (for the count label). */
  total?: number;
  capped?: { analyzed: number; totalFiles: number } | null;
  onCancel?: () => void;
  className?: string;
}) {
  // Grouping/hints are a single request over the whole PR — there's no real
  // per-file progress to report, so the bar is indeterminate and the label
  // shows the count of files being analyzed, not a fake fraction.
  const n = capped?.analyzed ?? total;
  return (
    <div className={cn('w-full', className)}>
      <div className="flex items-center gap-2">
        <AiMark className="size-4 shrink-0 text-violet-600 ai-pulse" />
        <span className="text-[12px] font-medium text-violet-700">{label}</span>
        <span className="text-[11.5px] tabular-nums text-muted-foreground">
          {n} {n === 1 ? 'file' : 'files'}
        </span>
        <button
          type="button"
          onClick={onCancel}
          className="ml-auto inline-flex items-center gap-1 rounded border border-border bg-background px-1.5 py-0.5 text-[10.5px] font-medium text-muted-foreground hover:bg-muted/50"
        >
          <X className="size-3" />
          Cancel
        </button>
      </div>
      <div className="relative mt-1.5 h-1.5 overflow-hidden rounded-full bg-violet-100">
        <div className="ai-progress-seg absolute inset-y-0 left-0 w-2/5 rounded-full bg-violet-500" />
      </div>
      {capped && (
        <div className="mt-2 flex items-start gap-1.5 rounded-md border border-border bg-muted/50 px-2 py-1.5 text-[10.5px] leading-snug text-muted-foreground">
          <Info className="mt-px size-3 shrink-0 text-muted-foreground" />
          <span>
            Large PR — analyzing the {capped.analyzed} largest &amp; most-changed of{' '}
            {capped.totalFiles} files. The rest stay ungrouped.
          </span>
        </div>
      )}
    </div>
  );
}

// ── Run states — locked / errors / empty (grouping · hints · chat) ────
export type AiRunStateKind =
  | 'locked'
  | 'no-key'
  | 'invalid-key'
  | 'billing'
  | 'rate-limited'
  | 'overloaded'
  | 'network'
  | 'empty';

const AI_RUN_STATES: Record<
  AiRunStateKind,
  {
    icon: typeof Lock;
    tone: 'zinc' | 'amber' | 'good';
    title: string;
    body: string;
    setup?: boolean;
    setupLabel?: string;
    retry?: boolean;
    wait?: string;
    empty?: boolean;
  }
> = {
  locked: {
    icon: Lock,
    tone: 'zinc',
    title: 'AI assistance is off',
    body: 'Turn it on in Settings to group files and get inline review hints.',
    setup: true,
  },
  'no-key': {
    icon: KeyRound,
    tone: 'zinc',
    title: 'No provider key yet',
    body: 'Add an OpenAI or Anthropic key to run AI features. Your key stays on your device.',
    setup: true,
  },
  'invalid-key': {
    icon: AlertTriangle,
    tone: 'amber',
    title: 'Provider key rejected',
    body: 'The configured key was rejected. Check it in Settings · AI assistance.',
    setup: true,
    setupLabel: 'Open Settings',
  },
  billing: {
    icon: AlertTriangle,
    tone: 'amber',
    title: 'Provider account out of credit',
    body: 'Your key is valid, but the account has no remaining credit or quota. Add billing in your provider dashboard, then re-run — retrying alone won’t help.',
    retry: true,
  },
  'rate-limited': {
    icon: Clock,
    tone: 'amber',
    title: 'Rate-limited by provider',
    body: 'Too many requests right now.',
    retry: true,
    wait: '~40s',
  },
  overloaded: {
    icon: ServerCrash,
    tone: 'amber',
    title: 'Provider is overloaded',
    body: 'The model provider is busy. This is on their side, not yours.',
    retry: true,
  },
  network: {
    icon: WifiOff,
    tone: 'amber',
    title: "Couldn't reach the provider",
    body: 'Check your connection and try again.',
    retry: true,
  },
  empty: {
    icon: CheckCircle2,
    tone: 'good',
    title: 'No high-signal issues found',
    body: "AI read the diff and didn't flag anything worth a hint. That's a good sign — review as normal.",
    empty: true,
  },
};

export function AiRunState({
  kind = 'empty',
  layout = 'panel',
  wait,
  onRetry,
  onSetup,
  onDismiss,
  className = '',
}: {
  kind?: AiRunStateKind;
  layout?: 'panel' | 'rail' | 'inline';
  wait?: string;
  onRetry?: () => void;
  onSetup?: () => void;
  /** When set, a × rides inside the card's top-right (inset by the card
   * padding) to dismiss the notice. */
  onDismiss?: () => void;
  className?: string;
}) {
  const s = AI_RUN_STATES[kind] ?? AI_RUN_STATES.empty;
  const Icon = s.icon;
  const ring =
    s.tone === 'amber'
      ? 'border-amber-200 bg-amber-50/60 dark:border-amber-500/40 dark:bg-amber-500/10'
      : s.tone === 'good'
        ? 'border-emerald-200 bg-emerald-50/50 dark:border-emerald-500/40 dark:bg-emerald-500/10'
        : 'border-border bg-muted/40';
  const iconWrap =
    s.tone === 'amber'
      ? 'bg-amber-100 text-amber-600 dark:bg-amber-500/20'
      : s.tone === 'good'
        ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-500/20'
        : 'bg-violet-100 text-violet-600';
  const compact = layout === 'rail' || layout === 'inline';
  const showMarkLock = kind === 'locked' || kind === 'no-key';
  return (
    <div
      className={cn(
        'flex rounded-lg border',
        compact ? 'flex-row items-start gap-2.5 text-left' : 'flex-col items-center text-center',
        ring,
        compact ? 'p-3' : 'px-5 py-6',
        className,
      )}
    >
      <span
        className={cn(
          'inline-flex shrink-0 items-center justify-center rounded-xl',
          compact ? 'size-7' : 'mb-3 size-11',
          iconWrap,
        )}
      >
        {showMarkLock ? (
          <span className="relative inline-flex">
            <AiMark className={compact ? 'size-3.5' : 'size-5'} />
            <Icon className={cn('absolute -bottom-1 -right-1', compact ? 'size-2.5' : 'size-3')} />
          </span>
        ) : (
          <Icon className={compact ? 'size-4' : 'size-5'} />
        )}
      </span>
      <div className={compact ? 'min-w-0 flex-1' : 'max-w-xs'}>
        <div className={cn('font-semibold text-foreground', compact ? 'text-[12.5px]' : 'text-[14px]')}>
          {s.title}
        </div>
        <p
          className={cn(
            'mt-1 leading-relaxed text-muted-foreground',
            compact ? 'text-[11.5px]' : 'text-[12.5px]',
          )}
        >
          {s.body}
        </p>
        <div className={cn('mt-2.5 flex items-center gap-2', !compact && 'justify-center')}>
          {s.setup && (
            <AiButton variant="solid" size={compact ? 'xs' : 'sm'} mark onClick={onSetup}>
              {s.setupLabel ?? 'Set up AI'}
            </AiButton>
          )}
          {s.retry && (
            <AiButton variant="outline" size={compact ? 'xs' : 'sm'} icon="refresh" onClick={onRetry}>
              {wait ?? s.wait ? `Retry in ${wait ?? s.wait}` : 'Try again'}
            </AiButton>
          )}
          {s.empty && <AiDisclaimer size="sm" />}
        </div>
      </div>
      {onDismiss && (
        <button
          type="button"
          title="Dismiss"
          onClick={onDismiss}
          className="inline-flex size-5 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-foreground/10 hover:text-foreground"
        >
          <X className="size-3.5" />
        </button>
      )}
    </div>
  );
}

// ── "Review with AI" trigger — the home for inline hints ──────────────
export function AiReviewTrigger({
  state = 'ready',
  done = 0,
  total = 7,
  count,
  onClick,
  compact = false,
}: {
  state?: 'ready' | 'locked' | 'running' | 'done';
  done?: number;
  total?: number;
  count?: number;
  onClick?: () => void;
  /** Icon-only square button for the collapsed CompactHeader — drops the
   * label/count text (the wrapping tooltip already carries that). */
  compact?: boolean;
}) {
  if (compact) {
    const tone =
      state === 'locked'
        ? 'border-dashed border-border bg-background text-muted-foreground hover:border-violet-300 hover:text-violet-700'
        : state === 'done'
          ? 'border-violet-300 bg-violet-100 text-violet-700'
          : 'border-violet-300 bg-violet-50 text-violet-700 hover:bg-violet-100';
    return (
      <button
        type="button"
        onClick={onClick}
        aria-label="Review with AI"
        className={cn(
          'inline-flex size-7 shrink-0 items-center justify-center rounded-md border transition-colors',
          tone,
        )}
      >
        {state === 'locked' ? (
          <span className="relative inline-flex">
            <AiMark className="size-3.5" />
            <Lock className="absolute -bottom-1 -right-1 size-2.5" />
          </span>
        ) : (
          <AiMark className={cn('size-3.5', state === 'running' && 'ai-pulse')} />
        )}
      </button>
    );
  }
  if (state === 'locked') {
    return (
      <button
        type="button"
        onClick={onClick}
        title="AI assistance is off — set it up in Settings"
        className="inline-flex h-7 items-center gap-1.5 rounded-md border border-dashed border-border bg-background px-2 text-[12px] font-medium text-muted-foreground hover:border-violet-300 hover:text-violet-700"
      >
        <span className="relative inline-flex">
          <AiMark className="size-3.5 text-muted-foreground" />
          <Lock className="absolute -bottom-1 -right-1 size-2.5 text-muted-foreground" />
        </span>
        Review with AI
        <span className="ml-0.5 inline-flex items-center gap-0.5 text-[10.5px] text-violet-600">
          · Set up <ArrowRight className="size-2.5" />
        </span>
      </button>
    );
  }
  if (state === 'running') {
    return (
      <button
        type="button"
        onClick={onClick}
        className="inline-flex h-7 items-center gap-1.5 rounded-md border border-violet-300 bg-violet-50 px-2 text-[12px] font-medium text-violet-700"
      >
        <AiMark className="size-3.5 ai-pulse" />
        Reviewing… <span className="tabular-nums text-violet-500">{done}/{total}</span>
      </button>
    );
  }
  if (state === 'done') {
    return (
      <button
        type="button"
        onClick={onClick}
        className="inline-flex h-7 items-center gap-1.5 rounded-md border border-violet-300 bg-violet-100 px-2 text-[12px] font-medium text-violet-700"
      >
        <AiMark className="size-3.5" />
        {count ?? 0} hints
        <ChevronDown className="size-3 text-violet-500" />
      </button>
    );
  }
  return (
    <button
      type="button"
      onClick={onClick}
      className="inline-flex h-7 items-center gap-1.5 rounded-md border border-violet-300 bg-violet-50 px-2 text-[12px] font-medium text-violet-700 hover:bg-violet-100"
    >
      <AiMark className="size-3.5" />
      Review with AI
    </button>
  );
}
