// AI grouping result — the schema-validated structured output (ADR 0026).
// The LLM returns clusters of changed files with a name, one-line
// description, and a signal/noise classification. Order = array order
// (important groups first, per the system prompt).

import * as v from 'valibot';

export const AiGroupSchema = v.object({
  name: v.string(),
  description: v.string(),
  kind: v.picklist(['important', 'noise']),
  files: v.array(v.string()),
});

export const AiGroupingResultSchema = v.object({
  groups: v.array(AiGroupSchema),
});

export type AiGroup = v.InferOutput<typeof AiGroupSchema>;
export type AiGroupingResult = v.InferOutput<typeof AiGroupingResultSchema>;

/** JSON Schema handed to the provider's structured-output API. */
export const AI_GROUPING_JSON_SCHEMA: Record<string, unknown> = {
  type: 'object',
  additionalProperties: false,
  required: ['groups'],
  properties: {
    groups: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'description', 'kind', 'files'],
        properties: {
          name: { type: 'string', description: '2–4 word group name' },
          description: {
            type: 'string',
            description: 'One sentence: what this group contains and why it matters',
          },
          kind: {
            type: 'string',
            enum: ['important', 'noise'],
            description: 'important = review-worthy, noise = safe to skim/skip',
          },
          files: {
            type: 'array',
            items: { type: 'string' },
            description: 'Exact file paths from the diff that belong to this group',
          },
        },
      },
    },
  },
};
