// SHA-keyed AI result cache (ADR 0026). Results cache locally keyed by
// (owner, repo, number, head SHA) — mirrors arrangementStore's localStorage
// per-PR pattern. Reopening a PR is free (fresh hit on the same SHA); a new
// commit keeps the result but marks it STALE with a one-click re-run, rather
// than auto-spending.

export type ShaCacheState<T> =
  | { status: 'none' }
  | { status: 'fresh'; result: T; sha: string; ranAt: number }
  | { status: 'stale'; result: T; sha: string; ranAt: number };

export interface ShaCacheEntry<T> {
  sha: string;
  ranAt: number;
  result: T;
}

export interface PrId {
  owner: string;
  repo: string;
  number: number;
}

function key(kind: string, id: PrId): string {
  return `pyor:ai:${kind}:${id.owner}/${id.repo}/${id.number}`;
}

export function makeShaCache<T>(kind: string) {
  return {
    /** Read the cached entry and classify it against the current head SHA. */
    read(id: PrId, headSha: string | undefined): ShaCacheState<T> {
      if (!headSha) return { status: 'none' };
      try {
        const raw = localStorage.getItem(key(kind, id));
        if (!raw) return { status: 'none' };
        const entry = JSON.parse(raw) as ShaCacheEntry<T>;
        if (!entry || typeof entry.sha !== 'string') return { status: 'none' };
        return entry.sha === headSha
          ? { status: 'fresh', result: entry.result, sha: entry.sha, ranAt: entry.ranAt }
          : { status: 'stale', result: entry.result, sha: entry.sha, ranAt: entry.ranAt };
      } catch {
        return { status: 'none' };
      }
    },

    write(id: PrId, headSha: string, result: T): void {
      try {
        const entry: ShaCacheEntry<T> = { sha: headSha, ranAt: Date.now(), result };
        localStorage.setItem(key(kind, id), JSON.stringify(entry));
      } catch {
        // quota / private mode — degrade to in-session only.
      }
    },

    clear(id: PrId): void {
      try {
        localStorage.removeItem(key(kind, id));
      } catch {
        /* no-op */
      }
    },
  };
}
