// The diff context shown INSIDE a local comment's body — the same
// `DiffHunkSnippet` the GitHub Conversation/Changes threads embed via
// `GhComment.diffSlice`. GitHub passes the real `diff_hunk` string; we
// reproduce that by pulling the matching hunk out of the file's native git
// patch (`patchByPath`), so the snippet carries real +/- markers (and thus
// the green/red diff colouring + intra-line overlay) and Shiki syntax
// highlighting — identical to the PR surface. Falls back to a synthesised
// context hunk from the file text when no patch hunk covers the line.

import { DiffHunkSnippet } from '../conversation/DiffHunkSnippet';
import type { LocalReviewComment } from '../../review/localReviewComments';

const HUNK_HEADER = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/;

/** Pull the single hunk that covers `line` (on `side`) out of a file's
 * unified git patch. Returns just that `@@ … @@` block (header + body),
 * which is what DiffHunkSnippet parses. null when no hunk covers the line
 * (e.g. the comment sits in an unchanged region outside every hunk). */
function extractHunkForLine(
  patch: string,
  line: number,
  side: 'LEFT' | 'RIGHT',
): string | null {
  interface Hunk {
    oldStart: number;
    oldCount: number;
    newStart: number;
    newCount: number;
    text: string[];
  }
  const hunks: Hunk[] = [];
  patch.split('\n').forEach((l) => {
    const m = l.match(HUNK_HEADER);
    if (m) {
      hunks.push({
        oldStart: +m[1],
        oldCount: m[2] ? +m[2] : 1,
        newStart: +m[3],
        newCount: m[4] ? +m[4] : 1,
        text: [l],
      });
      return;
    }
    // Body rows only attach once we're inside a hunk; the patch preamble
    // (diff --git / index / --- / +++) is ignored.
    const cur = hunks[hunks.length - 1];
    if (
      cur &&
      (l.startsWith(' ') ||
        l.startsWith('+') ||
        l.startsWith('-') ||
        l.startsWith('\\'))
    ) {
      cur.text.push(l);
    }
  });
  const hit = hunks.find((h) =>
    side === 'LEFT'
      ? line >= h.oldStart && line < h.oldStart + h.oldCount
      : line >= h.newStart && line < h.newStart + h.newCount,
  );
  return hit ? hit.text.join('\n') : null;
}

export function LocalDiffSlice({
  comment,
  oldText,
  newText,
  patch,
}: {
  comment: LocalReviewComment;
  /** Old/new file text for in-snippet context expansion. Omit (or null)
   * when unavailable — the frozen one-line snippet still renders. */
  oldText?: string | null;
  newText?: string | null;
  /** The file's native git patch (from the diff load). When a hunk covers
   * the comment's line we render THAT — real markers, real diff colour. */
  patch?: string | null;
}): React.ReactNode {
  if (comment.line == null) return null; // file-level note → no diff context
  const line = comment.line;
  const start = comment.startLine ?? line;

  // Prefer the real git hunk (carries +/- markers → diff colouring).
  let diffHunk = patch ? extractHunkForLine(patch, line, comment.side) : null;
  if (!diffHunk) {
    // Fallback: synthesise a context hunk from file text so multi-line
    // ranges still show every line; single frozen snippet when no content.
    const sourceText = comment.side === 'LEFT' ? oldText : newText;
    const fileLines = sourceText ? sourceText.split('\n') : null;
    if (fileLines && line <= fileLines.length) {
      const from = Math.max(1, start);
      const rangeRows = fileLines
        .slice(from - 1, line)
        .map((l) => ` ${l}`)
        .join('\n');
      const count = line - from + 1;
      diffHunk = `@@ -${from},${count} +${from},${count} @@\n${rangeRows}`;
    } else {
      diffHunk = `@@ -${line},1 +${line},1 @@\n ${comment.contentSnippet ?? ''}`;
    }
  }

  const lineLabel = start !== line ? `L${start}–L${line}` : `L${line}`;
  return (
    <DiffHunkSnippet
      diffHunk={diffHunk}
      file={comment.path}
      line={line}
      anchorStart={start}
      anchorEnd={line}
      side={comment.side}
      newText={newText ?? null}
      oldText={oldText ?? null}
      embedded
      lineLabel={lineLabel}
      copyAnchor={{ path: comment.path, line, side: comment.side }}
    />
  );
}
