// Copy-path button for inline review-thread cards (#14). Copies the
// thread's repo-relative `path:line` (via the pure copyPath formatter)
// so a reviewer can paste an exact "fix this spot" reference into an
// editor jump or an LLM coding-agent prompt. shadcn-only (ADR 0011).
//
// Icon-only: the affordance is a single copy glyph (→ check on
// success) with the full `Copy path:line` label moved into a hover
// tooltip, so the button stays compact in tight headers where the
// file path needs the room.

import { useState } from 'react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { CopyIconMorph } from '@/components/ui/copy-icon';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { formatCopyPath, type ThreadAnchor } from '../../github/copyPath';

export function CopyPathButton({
  anchor,
  compact = false,
}: {
  anchor: ThreadAnchor;
  /** Tighter, borderless glyph for cramped headers (e.g. the inline
   * thread's diff-header row). size-4 / size-2.5 icon vs the default
   * size-6 bordered button. */
  compact?: boolean;
}) {
  const [copied, setCopied] = useState(false);
  const text = formatCopyPath(anchor);

  const onCopy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error('Could not copy to clipboard');
    }
  };

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            type="button"
            onClick={onCopy}
            aria-label={`Copy path ${text}`}
            className={cn(
              'inline-flex shrink-0 items-center justify-center rounded-md transition-colors',
              compact ? 'size-4 rounded' : 'size-6 border',
              copied
                ? compact
                  ? 'text-emerald-600 dark:text-emerald-300'
                  : 'border-emerald-500/30 bg-emerald-500/10 text-emerald-600 dark:text-emerald-300'
                : compact
                  ? 'text-muted-foreground hover:bg-muted hover:text-foreground'
                  : 'border-border bg-background text-muted-foreground hover:bg-muted hover:text-foreground',
            )}
          >
            <CopyIconMorph
              copied={copied}
              className={compact ? 'size-2.5' : 'size-3'}
            />
          </button>
        </TooltipTrigger>
        <TooltipContent side="bottom" className="text-[11.5px]">
          {copied ? 'Copied!' : `Copy ${text}`}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}
