// Lets the active tab's body feed per-tab chrome (titlebar subtitle,
// Refresh toolbar, status-footer) up to the shared PullsScreen shell — so
// the shell can keep the PyorWindow + tab bar mounted across tab switches
// while each body still owns its own subtitle/status/refresh.

import {
  createContext,
  useContext,
  useEffect,
  type DependencyList,
  type ReactNode,
} from 'react';

export interface PullsChrome {
  subtitle: string;
  toolbar: ReactNode;
  status: ReactNode;
}

export const PullsChromeContext = createContext<(c: PullsChrome) => void>(
  () => {},
);

/** Publish this body's chrome to the shell. `deps` should list the
 * primitive inputs the chrome depends on — the chrome nodes are only
 * re-pushed when one changes, which avoids a set-state render loop. */
export function usePullsChrome(chrome: PullsChrome, deps: DependencyList) {
  const set = useContext(PullsChromeContext);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => set(chrome), deps);
}
