// Changes tab - the dominant review surface (per CONTEXT.md / ADR 0008
// as amended). Two columns: file rail (left) + diff (centre). The
// persistent right inspector that ADR 0008 originally specified was
// removed at the user's request after a UX review - its content
// (verdict, pending count, viewed-stats, labels) was duplicative with
// the dock + submit modal, and dropping it gives the diff full
// horizontal width.
//
// When `files` is provided (the real PR-detail flow), the centre pane
// renders via @pierre/diffs's CodeView with the actual fetched patches.
// When omitted (legacy static path), it falls back to the design's
// hand-built diff renderer for parity with the original mocks.

import {
  useCallback,
  useDeferredValue,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  FileRail,
  FileRailCollapsed,
  type FileRailHandle,
  type RailMode,
} from "./FileRail";
import type { DiffMode } from "./diffMode";
import {
  LiveDiffPane,
  type LiveDiffPaneHandle,
  type DiffAnnotationLayer,
} from "./LiveDiffPane";
import { JumpWidget } from "../JumpWidget";
import { PRErrorPane } from "../PRErrorPane";
import { ReviewDock } from "./ReviewDock";
import { forEachPatchBodyLine, matchRowFractions } from "./searchRuler";
import {
  useIsFetching,
  useQueries,
  useQuery,
  useQueryClient,
} from "@tanstack/react-query";
import { structuredPatch } from "diff";
import { getCommitDetail, getCompareFiles } from "../../github/client";
import { fetchPRFileContents } from "../../github/fetchPRFileContents";
import { buildDiffItems } from "../../github/buildDiff";
import { useArrangement } from "./grouping/useArrangement";
import { deriveArrangedView } from "./grouping/arrange";
import { useNavigate } from "@tanstack/react-router";
import { useAiGrouping } from "../../ai/grouping/useAiGrouping";
import { useAiHints, type AiCompactTrigger } from "../../ai/hints/useAiHints";
import { useAiSettings } from "../../ai/settings/useAiSettings";
import { AiHintsBar } from "../../ai/hints/AiHintsBar";
import type { AiHintAnchor } from "../../github/buildDiff";
import {
  reconcileThreadAnchors,
  type ThreadIndex,
} from "../../github/threads";
import type { DiffAnchor } from "../../router/nav";
import type { GHPullRequestFile } from "../../github/types";
import type { DraftActions, DraftReview } from "../../review/reviewDraftTypes";
import type { ViewedHookValue } from "../../review/viewedHooks";
import { Resizer, useResizableWidth } from "../../ui/Resizer";
import { FetchingBar } from "@/components/ui/fetching-bar";
import { usePrefs } from "../../util/usePrefs";
import type { CollapseHookValue } from "./collapseHooks";

interface ChangesTabProps {
  /** Optional - the local pre-PR surface has no review-submit modal. */
  onOpenModal?: () => void;
  /** Local-review annotation pipeline (saved comments + composers +
   * staleness chips). When set it's forwarded to LiveDiffPane, which
   * uses it INSTEAD of the GitHub thread/composer machinery. */
  annotationLayer?: DiffAnnotationLayer;
  /** When true the diff scope is resolved EXTERNALLY (the local screen
   * picks files/contents/SHAs per its commit dropdown). Forces the
   * internal GitHub scope queries off and uses the model props directly
   * as the active diff inputs. */
  externalScope?: boolean;
  /** Pre-computed native-git patches per path (local surface). Threaded
   * into buildDiffItems on the no-scope branch so the diff renders from
   * git's own patch instead of the JS Myers parse. GitHub never sets it. */
  patchByPath?: Map<string, string>;
  /** False when the Changes tab is mounted-but-hidden (kept alive
   * behind another tab to preserve scroll). Gates the window keyboard
   * shortcuts so j/k / ⌘F don't fire while you're on another tab. */
  active?: boolean;
  /** Read-only "demo" mode (AFK plan 22). Hides the ReviewDock (no
   * draft submission) and suppresses per-file mark-as-viewed toggles
   * (those fire an immediate GraphQL mutation). Diffs + inline threads
   * still render. */
  readOnly?: boolean;
  /** Live PR files (paginated from GitHub). Optional so the shell
   * can mount before the /files endpoint resolves - the rail
   * shows skeletons and the diff pane renders nothing. */
  files?: GHPullRequestFile[];
  /** Full old + new contents per file, fetched by PRDetailScreen via
   * GraphQL batching. Required for parseDiffFromFile - the only path
   * with ignoreWhitespace support per @pierre/diffs issue #366.
   * Empty Map while the second-wave fetch is still in flight. */
  fileContents?: Map<
    string,
    import("../../github/fetchPRFileContents").FileContents
  >;
  /** Progress of the file-contents GraphQL batch fetch - drives the
   * small "computing diffs… N/M" indicator until resolved=total. */
  contentsProgress?: { resolved: number; total: number };
  /** True while the wave-2 file-contents fetch is in flight. While
   * loading, files without content yet are treated as "still
   * resolving" rather than "skipped - content fetch failed", so
   * the SkippedNotice doesn't flash a misleading 569-files message
   * during the first second of progressive rendering. */
  isContentsLoading?: boolean;
  /** Set when the file-contents fetch terminally failed (outage /
   * rate-limit / paused-on-hidden-tab) while the file LIST loaded fine.
   * The rail + toolbar stay populated and the diff column is replaced by
   * the inline outage card - so the failure reads as scoped to the diff
   * bodies, not the whole tab. Distinct from a files-list failure, which
   * the parent handles with a whole-tab takeover (no rail to show). */
  contentsError?: unknown;
  /** Last successful sync, threaded into the inline outage card's
   * "Last synced" line. */
  lastSyncedAt?: Date | null;
  /** Retry handler for the inline outage card (re-invalidates the PR
   * queries). Owned by the parent, which holds the queryClient. */
  onRetryContents?: () => void;
  /** True while the /files endpoint is still paginating. When true
   * FileRail renders skeleton rows so the user sees structure
   * immediately instead of an empty rail. */
  isFilesLoading?: boolean;
  /** Focus mode (⇧M). When true, inline review-comment threads in
   * the diff are replaced with a one-line "Thread hidden" pill so
   * the reviewer can scan the code without comment chrome. */
  focusMode?: boolean;
  /** Pre-built thread index for review comments anchored to lines.
   * Optional - when omitted the diff renders without comment threads. */
  threadIndex?: ThreadIndex;
  /** Per-file comment count for the rail badge (local pre-PR surface,
   * which has no GitHub `threadIndex`). */
  commentCountByPath?: ReadonlyMap<string, number>;
  /** In-progress review draft, owned by PRDetailScreen so both this
   * tab and the submit modal share one source of truth. Optional - the
   * local pre-PR surface owns commenting via `annotationLayer` and passes
   * none, which gates off the ReviewDock + GitHub composers. */
  draft?: DraftReview;
  draftActions?: DraftActions;
  /** Discard the whole in-progress review on GitHub (ADR 0019) - wired
   * to the dock's Discard. */
  onDiscardReview?: () => Promise<void>;
  /** Per-PR file viewed-state, owned by PRDetailScreen. */
  viewedState?: ViewedHookValue;
  /** Per-PR manual collapse overrides - chevron toggles + the
   * SubToolbar "Collapse / Expand all" buttons go through this. */
  collapseState?: CollapseHookValue;
  /** Required for inline-thread reply POSTs. Optional only so this
   * component stays renderable during the design-fixture fallback. */
  owner?: string;
  repo?: string;
  number?: number;
  /** Head/base SHAs - passed down so line-number clicks can build
   * a github.com/blob/{sha}/... permalink that lands on the right
   * commit. Optional only so the spike harness still builds. */
  headSha?: string;
  baseSha?: string;
  /** Base/head branch names - surfaced in the commits-picker
   * popover's base/head meta block. */
  baseRef?: string;
  headRef?: string;
  /** Total commits in the PR - drives the SubToolbar commit pill. */
  commitCount?: number;
  /** Login of the current authenticated user - surfaced in the "new
   * comment" composer's avatar slot. */
  viewerLogin?: string;
  /** PR author's login - drives the "Author"/"Reviewer" role pill on
   * inline-thread comment headers (forwarded to LiveDiffPane). */
  prAuthorLogin?: string;
  /** Parent (PRDetailScreen) fires this to refetch comments after
   * any successful inline action. */
  onChanged?: () => void;
  /** Persisted file selection - when set, the rail + diff jump to
   * this path on mount instead of the first file. */
  initialPath?: string | null;
  /** Deep-link anchor: scroll the diff to this specific line (in
   * combination with `initialPath`) on mount. Originates from the
   * Inbox · Comments tab → row click. Best-effort: if the line isn't
   * in the rendered hunks yet, we fall back to the file-level scroll
   * already performed via `initialPath`. */
  initialLine?: number | null;
  /** Which diff column the anchored line lives on. RIGHT = additions
   * (new file), LEFT = deletions (original). In split-view both
   * columns render their own `[data-line="N"]`; without this hint
   * we'd land on whichever came first in DOM order. */
  initialDiffSide?: "LEFT" | "RIGHT" | null;
  /** Deep-link / restored comment anchor (`acid`). When present it
   * WINS precedence over a bare line on restore: the diff scrolls to
   * the comment's thread (resolved via threadIndex) rather than the
   * standalone `initialLine`. */
  initialCommentId?: number | null;
  /** Reviewer-HoverCard "View comment" jump to an inline comment.
   * Unlike `initial*` (consumed once on mount), this RE-fires on every
   * new object: a fresh click switches to the Changes tab and scrolls
   * to + highlights the line again, even though the tab stayed mounted.
   * A new object per click (PRDetailScreen mints one). */
  jumpToDiff?: {
    path: string;
    line: number | null;
    diffSide?: "LEFT" | "RIGHT" | null;
  } | null;
  /** Live anchor writer - clicking a line or a comment in the diff
   * reports the shareable anchor so the parent can persist it in the
   * URL. Omitted on the legacy/fixture path. */
  onAnchorChange?: (anchor: DiffAnchor | null) => void;
  /** Fires when the active file changes (j/k or click). The parent
   * persists this so a reload returns to the same file. */
  onCurrentPathChange?: (path: string) => void;
  /** Persisted scroll offset within the diff. When set, the diff
   * scrolls to this absolute position on mount instead of the
   * first file's top. Wins over `initialPath` for placement -
   * `initialPath` still drives the rail highlight + j/k anchor. */
  initialScrollTop?: number;
  /** Fires (debounced) on every scroll. Parent persists this so a
   * reload returns to the exact scroll position. */
  onScrollChange?: (scrollTop: number) => void;
  /** Diff mode lifted to the URL (AFK plan 26). When provided, this is
   * controlled - the value comes from the PR route's `diff` search
   * param and changes write back via `onDiffModeChange`. When omitted
   * (legacy / fixture path) the tab keeps its own internal state. */
  diffMode?: DiffMode;
  onDiffModeChange?: (mode: DiffMode) => void;
  /** Commit-filter lifted to the URL as a comma-joined SHA string.
   * When provided this is controlled (the `commits` search param);
   * `undefined`/empty means "all commits". `onCommitsChange` writes the
   * comma-joined string back (or undefined to clear). */
  commits?: string;
  onCommitsChange?: (commits: string | undefined) => void;
  /** "Search diff content" lifted to the URL (`?dq=`). When supplied,
   * the search value is initialised from + synced to it (so a reload /
   * shared link restores it). Omitted on the legacy/fixture path. */
  searchQuery?: string;
  onSearchQueryChange?: (q: string | undefined) => void;
  /** File-rail "Filter files" lifted to the URL (`?fq=`), forwarded to
   * FileRail. Same controlled-with-fallback shape. */
  fileFilter?: string;
  onFileFilterChange?: (q: string | undefined) => void;
  /** File-rail mode (tree | list) lifted to the URL (`?rail=`).
   * Controlled-with-fallback like diffMode. */
  railMode?: RailMode;
  onRailModeChange?: (mode: RailMode) => void;
  /** Reports the diff-search hit totals up to the parent so the
   * tab-bar toolbar (CompactChangesToolbar) can show the "N in M files"
   * counter - matchSummary is computed here (needs the parsed patches),
   * but the search box lives up in PRDetailScreen's tab strip. */
  onSearchSummaryChange?: (summary: {
    count: number;
    fileCount: number;
  }) => void;
  /** Diff-search "current hit" index, lifted so the toolbar's prev/next
   * arrows + "X of N" counter can drive it. Controlled-with-fallback: when
   * `searchMatchIndex` is provided the parent owns it (and resets it to 0
   * on a new query); otherwise ChangesTab keeps it in local state. */
  searchMatchIndex?: number;
  onSearchMatchIndexChange?: (index: number) => void;
  /** Publishes the "Review with AI" trigger state up so the collapsed PR
   * header can render it (one shared useAiHints instance feeds both). Null
   * when AI is off - the locked discovery stays in the body hints bar. */
  onAiTrigger?: (trigger: AiCompactTrigger | null) => void;
}

export function ChangesTab({
  onOpenModal,
  onDiscardReview,
  annotationLayer,
  commentCountByPath,
  externalScope = false,
  patchByPath,
  active = true,
  readOnly = false,
  files,
  fileContents,
  contentsProgress,
  isContentsLoading,
  isFilesLoading,
  contentsError,
  lastSyncedAt,
  onRetryContents,
  focusMode = false,
  threadIndex,
  draft,
  draftActions,
  viewedState,
  collapseState,
  owner,
  repo,
  number,
  headSha,
  baseSha,
  baseRef,
  headRef,
  commitCount,
  viewerLogin,
  prAuthorLogin,
  onChanged,
  initialPath,
  initialLine,
  initialDiffSide,
  initialCommentId,
  jumpToDiff,
  onAnchorChange,
  onCurrentPathChange,
  initialScrollTop,
  onScrollChange,
  diffMode,
  onDiffModeChange,
  commits,
  onCommitsChange,
  searchQuery,
  onSearchQueryChange,
  fileFilter,
  onFileFilterChange,
  railMode,
  onRailModeChange,
  onSearchSummaryChange,
  searchMatchIndex,
  onSearchMatchIndexChange,
  onAiTrigger,
}: ChangesTabProps) {
  // File-rail mode (tree | list). Controlled by the URL (`?rail=`) when
  // the router supplies railMode/onRailModeChange; else local state.
  const [railLocal, setRailLocal] = useState<RailMode>("tree");
  const rail = onRailModeChange ? (railMode ?? "tree") : railLocal;
  const setRail = (mode: RailMode) => {
    if (onRailModeChange) onRailModeChange(mode);
    else setRailLocal(mode);
  };
  // Diff mode. Split is the default - better fit for the @pierre/diffs
  // renderer on wide PR-detail windows, and matches the convention most
  // reviewers expect coming from Graphite / GitHub's side-by-side
  // toggle. Users can flip to inline from the SubToolbar.
  //
  // Since AFK plan 26 this is lifted to the URL: when `diffMode` /
  // `onDiffModeChange` are supplied (the router path) the value is
  // controlled by the `?diff=` search param; otherwise it falls back to
  // local state (legacy / design-fixture path).
  const [diffLocal, setDiffLocal] = useState<DiffMode>("split");
  const diff = diffMode ?? diffLocal;
  const setDiff = (mode: DiffMode) => {
    if (onDiffModeChange) onDiffModeChange(mode);
    else setDiffLocal(mode);
  };
  // "Search diff content" - local state owns the active/empty (null =
  // closed) interaction, but it's initialised from + synced to the URL
  // (`?dq=`) when the router supplies searchQuery/onSearchQueryChange,
  // so a reload or shared link restores the query.
  const [searchLocal, setSearchLocal] = useState<string | null>(
    searchQuery ?? null,
  );
  const search = searchLocal;
  const setSearch = (next: string | null) => {
    setSearchLocal(next);
    onSearchQueryChange?.(next && next.trim() ? next : undefined);
  };
  // Follow the controlled query (the `?dq=` param, written by the tab-bar
  // toolbar's search box). This MUST include the cleared case: clearing
  // the box drops `dq` to undefined, and if we ignored that the diff would
  // keep filtering + highlighting the stale query (the box now lives in the
  // toolbar, so this prop is our only channel). `undefined` → null = "no
  // search"; the toolbar owns whether the (possibly empty) box stays open.
  useEffect(() => {
    const next = searchQuery ?? null;
    setSearchLocal((cur) => (cur === next ? cur : next));
  }, [searchQuery]);
  // Multi-select commit picker - null means "all commits" (the full
  // PR diff). When a Set is set, the diff renders only files touched by
  // those commits. Lifted to the URL (`?commits=sha,sha`) when
  // `commits`/`onCommitsChange` are supplied (router path); otherwise
  // local state. The picker itself is fully interactive per
  // shadcn-app.jsx · ShadcnCommitsPopover.
  const [selectedCommitShasLocal, setSelectedCommitShasLocal] =
    useState<ReadonlySet<string> | null>(null);
  const selectedCommitShas: ReadonlySet<string> | null = useMemo(() => {
    if (onCommitsChange === undefined) return selectedCommitShasLocal;
    if (!commits) return null;
    const parts = commits
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    return parts.length > 0 ? new Set(parts) : null;
  }, [onCommitsChange, commits, selectedCommitShasLocal]);
  const setSelectedCommitShas = (next: ReadonlySet<string> | null) => {
    if (onCommitsChange) {
      onCommitsChange(
        next && next.size > 0 ? Array.from(next).join(",") : undefined,
      );
    } else {
      setSelectedCommitShasLocal(next);
    }
  };
  // Look-and-feel prefs (theme + intra-line-diff style) are read-only
  // here - settings now live in the Settings screen. usePrefs gives us
  // live re-renders when the user tweaks them there.
  const { prefs } = usePrefs();
  const { theme, lineDiffStyle, fontSize, lineHeight } = prefs;
  // Effective scroll anchor with comment-precedence: a comment anchor
  // (`initialCommentId` / acid) WINS over a bare line - resolve the
  // comment's current path/line/side from the thread index so we land
  // on the thread even if a stale `initialLine` disagrees. Falls back
  // to the line anchor, then a path-only anchor. (Comment anchors also
  // carry their line in `initialLine`, so they still scroll correctly
  // before the thread index has loaded.)
  const resolvedAnchor = useMemo<{
    path: string | null;
    line: number | null;
    side: "LEFT" | "RIGHT" | null;
  } | null>(() => {
    if (initialCommentId != null && threadIndex) {
      for (const threads of threadIndex.byPath.values()) {
        for (const t of threads) {
          if (t.headId === initialCommentId) {
            return { path: t.path, line: t.line, side: t.side };
          }
        }
      }
    }
    if (initialLine != null) {
      return {
        path: initialPath ?? null,
        line: initialLine,
        side: initialDiffSide ?? null,
      };
    }
    if (initialPath) return { path: initialPath, line: null, side: null };
    return null;
  }, [
    initialCommentId,
    threadIndex,
    initialLine,
    initialPath,
    initialDiffSide,
  ]);
  const [currentPath, _setCurrentPath] = useState<string | null>(
    resolvedAnchor?.path ?? initialPath ?? null,
  );
  const setCurrentPath = (path: string | null) => {
    _setCurrentPath(path);
    if (path) onCurrentPathChange?.(path);
  };
  const codeViewRef = useRef<LiveDiffPaneHandle | null>(null);
  const fileRailRef = useRef<FileRailHandle | null>(null);
  const restoredRef = useRef(false);
  // Incremental-diff cache: built diff items keyed by (path, SHAs), so
  // streaming waves only reparse newly-arrived files instead of the
  // whole PR every time (see buildDiffItems). Cleared when the PR or its
  // head/base SHA changes (force-push) so stale content can't be reused.
  const diffItemCacheRef = useRef<
    Map<string, import("@pierre/diffs").CodeViewDiffItem>
  >(new Map());
  useEffect(() => {
    diffItemCacheRef.current.clear();
  }, [owner, repo, number, headSha, baseSha]);

  // Resizable file rail width. Persisted per-user so a chosen layout
  // survives reload. Clamped 180–600 px.
  const {
    width: railWidth,
    startDrag: startRailDrag,
    dragging: railDragging,
  } = useResizableWidth("file-rail", 280, 180, 600);

  // Whether the file rail is collapsed into a thin strip. Persisted
  // so a deliberate "give me more diff" toggle survives reloads.
  const [railCollapsed, _setRailCollapsed] = useState<boolean>(() => {
    try {
      return localStorage.getItem("pyor:rail-collapsed") === "1";
    } catch {
      return false;
    }
  });
  const setRailCollapsed = (next: boolean) => {
    _setRailCollapsed(next);
    try {
      localStorage.setItem("pyor:rail-collapsed", next ? "1" : "0");
    } catch {
      // ignore
    }
  };

  // Reconstructed-patch cache for files whose GitHub patch was elided
  // (huge lockfiles etc.). Keyed by (file, baseSha, headSha) via
  // `reconPatchKey` so a search term that hits such a file only pays the
  // diff-reconstruction cost on the first keystroke, not every one. A
  // bounded LRU is overkill - there are at most a handful of elided files
  // per PR and the keys are SHA-scoped, so stale entries are simply unused.
  const reconPatchRef = useRef(new Map<string, string>());

  // Seed currentPath to the first file once files arrive (unless the
  // user has a persisted file from last session, in which case keep
  // that - assuming it's still in the file list).
  useEffect(() => {
    if (!files || files.length === 0) return;
    _setCurrentPath((prev) => {
      if (prev && files.some((f) => f.filename === prev)) return prev;
      return files[0].filename;
    });
  }, [files]);

  // On first paint after files arrive, restore the user's exact spot.
  // Prefer absolute scrollTop (returns to the same pixel offset). Fall
  // back to scrollTo({type:'item'}) on the persisted file so the
  // first session - and any session that pre-dates scrollTop being
  // persisted - still lands somewhere sensible.
  //
  // Exception: when a deep-link anchor (`initialLine`) is present -
  // i.e. the user clicked an inbox comment to jump straight to a
  // specific line - the anchor takes precedence over the saved scroll
  // position. Otherwise the saved spot from the prior session would
  // drop us at whatever pixel offset they left off (possibly a
  // completely different file), and the line-scroll effect below
  // would never find its target in the rendered hunks.
  useEffect(() => {
    if (restoredRef.current) return;
    if (!files || files.length === 0) return;
    if (!currentPath) return;
    if (!files.some((f) => f.filename === currentPath)) return;
    // RAF + setTimeout: the @pierre/diffs virtualizer needs a paint
    // before scrollTo's measured-height layout is ready. (Tab switches
    // no longer rely on this - the Changes tab is kept mounted, so its
    // scroll survives natively; this only restores on a cold mount /
    // deep-link.)
    const id = window.setTimeout(() => {
      const anchorActive = resolvedAnchor?.line != null;
      if (initialScrollTop && initialScrollTop > 0 && !anchorActive) {
        codeViewRef.current?.scrollTo({
          type: "position",
          position: initialScrollTop,
          behavior: "instant",
        });
      } else {
        codeViewRef.current?.scrollTo({
          type: "item",
          id: currentPath,
          align: "start",
          behavior: "instant",
        });
      }
      restoredRef.current = true;
    }, 50);
    return () => window.clearTimeout(id);
  }, [files, currentPath, initialScrollTop, resolvedAnchor?.line]);

  // Reviewer-HoverCard "View comment" → jump to an inline comment. This
  // is the RE-firing counterpart to the one-shot anchor restore above:
  // the Changes tab is kept mounted, so `initial*` props (consumed once)
  // and `anchorRestoredRef` (set once per PR-open) can't drive a fresh
  // jump when the user clicks "View comment" from another tab. A new
  // `jumpToDiff` object per click re-runs this effect, which selects the
  // file, drives the virtualizer to the line (works even for an unmounted
  // hunk), and leaves the native line highlight. Re-pins a couple of
  // times as the diff - just revealed from `content-visibility:hidden` -
  // settles its row heights.
  useEffect(() => {
    if (!jumpToDiff?.path) return;
    const path = jumpToDiff.path;
    const line = jumpToDiff.line;
    const sideToken: "deletions" | "additions" =
      jumpToDiff.diffSide === "LEFT" ? "deletions" : "additions";
    setCurrentPath(path);
    const go = () => {
      codeViewRef.current?.scrollTo({
        type: "item",
        id: path,
        align: "start",
        behavior: "instant",
      });
      if (line != null) {
        codeViewRef.current?.scrollTo({
          type: "line",
          id: path,
          lineNumber: line,
          side: sideToken,
          align: "center",
          behavior: "smooth",
        });
        codeViewRef.current?.setSelectedLines({
          id: path,
          range: {
            start: line,
            end: line,
            side: sideToken,
            endSide: sideToken,
          },
        });
      }
    };
    const raf = requestAnimationFrame(go);
    const t1 = window.setTimeout(go, 140);
    const t2 = window.setTimeout(go, 380);
    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(t1);
      window.clearTimeout(t2);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [jumpToDiff]);

  // Keyboard shortcuts. CONTEXT.md v1 subset: j/k next/prev file,
  // v toggle viewed, ⌘⏎ submit review. Skip when focus is in an
  // editable surface so typing comments doesn't navigate the diff.
  useEffect(() => {
    if (!files || files.length === 0) return;
    if (!active) return; // mounted-but-hidden behind another tab
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const isEditing =
        target &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.isContentEditable);

      // Bail first while focus is in an editable surface. This covers ⌘⏎
      // too: a comment composer handles ⌘⏎ with its own keymap (it adds the
      // comment), so if this window handler also ran it would double up and
      // pop the submit-review modal on top of the just-added comment.
      if (isEditing) return;

      // ⌘⏎ opens the submit-review modal (github.com convention) - only
      // outside a composer, per the guard above. No-op on the local
      // surface, which has no submit modal (onOpenModal undefined).
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
        if (!onOpenModal) return;
        e.preventDefault();
        onOpenModal();
        return;
      }

      const idx = currentPath
        ? files.findIndex((f) => f.filename === currentPath)
        : -1;

      const go = (delta: number) => {
        const next = files[(idx + delta + files.length) % files.length];
        if (!next) return;
        setCurrentPath(next.filename);
        codeViewRef.current?.scrollTo({
          type: "item",
          id: next.filename,
          align: "start",
          behavior: "smooth",
        });
      };

      // n / p / r - comment-thread navigation + reply. Threads are
      // tagged with data-pyor-thread-id by ReviewThread; the
      // "focused" thread is whichever marked element is closest to
      // the top of the viewport.
      const focusedThreadEl = (): HTMLElement | null => {
        const all = Array.from(
          document.querySelectorAll<HTMLElement>("[data-pyor-thread-id]"),
        );
        if (all.length === 0) return null;
        let idx = all.findIndex((el) => {
          const r = el.getBoundingClientRect();
          return r.top >= 0 && r.top < window.innerHeight;
        });
        if (idx === -1) idx = 0;
        return all[idx] ?? null;
      };
      const goThread = (delta: 1 | -1) => {
        const all = Array.from(
          document.querySelectorAll<HTMLElement>("[data-pyor-thread-id]"),
        );
        if (all.length === 0) return;
        // Find currently focused - the first thread whose top is
        // within the viewport (or just above it). Fallback to 0.
        let activeIdx = all.findIndex((el) => {
          const r = el.getBoundingClientRect();
          return r.top >= 0 && r.top < window.innerHeight;
        });
        if (activeIdx === -1) activeIdx = 0;
        const next = all[(activeIdx + delta + all.length) % all.length];
        next.scrollIntoView({ behavior: "smooth", block: "center" });
        // Highlight briefly so the user sees what got focused.
        next.style.transition = "outline 200ms";
        next.style.outline = "2px solid currentColor";
        setTimeout(() => {
          next.style.outline = "";
        }, 700);
      };

      switch (e.key) {
        case "j":
        case "J":
          e.preventDefault();
          go(1);
          break;
        case "k":
        case "K":
          e.preventDefault();
          go(-1);
          break;
        case "v":
        case "V":
          // Mark-as-viewed is a write - suppressed in read-only demo
          // mode (AFK plan 22).
          if (currentPath && viewedState && !readOnly) {
            e.preventDefault();
            viewedState.toggle(currentPath);
          }
          break;
        case "n":
        case "N":
          e.preventDefault();
          goThread(1);
          break;
        case "p":
        case "P":
          e.preventDefault();
          goThread(-1);
          break;
        case "r":
        case "R": {
          // r - open the reply composer on the focused thread. The
          // collapsed-form thread renders a Reply button as the last
          // [data-pyor-thread-reply] inside the thread element; the
          // expanded form has a textarea we focus directly.
          const el = focusedThreadEl();
          if (!el) break;
          e.preventDefault();
          // The composer is now a CodeMirror editor, not a textarea - the
          // marker rides on its contenteditable `.cm-content` div. Focus
          // whatever element carries it.
          const composeEl = el.querySelector<HTMLElement>(
            "[data-pyor-thread-compose]",
          );
          if (composeEl) {
            composeEl.focus();
            break;
          }
          const replyBtn = el.querySelector<HTMLButtonElement>(
            "[data-pyor-thread-reply] button",
          );
          replyBtn?.click();
          break;
        }
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [files, currentPath, viewedState, onOpenModal, active, readOnly]);

  // Commit-selection scope - when `selectedCommitShas` is a non-null
  // set (user picked specific commits in the picker), the diff must show
  // the changes introduced by those commits ONLY, not the cumulative PR
  // diff. GitHub computes this as a compare across a span: from the
  // parent of the earliest-selected commit to the latest-selected
  // commit (single commit ⇒ parent…commit = `git show`; a multi-select
  // ⇒ the spanning range, matching GitHub's compare view).
  //
  // The diff pipeline (fetchPRFileContents → buildDiffItems) is fully
  // base/head-agnostic, so scoping is just a matter of swapping its
  // inputs: the span's file list (compare), the span's file contents
  // (blobs at scope base/head), and the span's base/head SHAs. We keep
  // the PR-level inputs (props) untouched and select between them below.
  // `externalScope` (local pre-PR surface): the scope is resolved
  // upstream - the screen feeds already-scoped files/contents/SHAs as the
  // model props, so force the internal GitHub scope queries off and use
  // those props directly as the active inputs below.
  const scopeActive =
    !externalScope && !!selectedCommitShas && selectedCommitShas.size > 0;
  const selectedShaArray = useMemo(() => {
    if (!selectedCommitShas) return [];
    return Array.from(selectedCommitShas).sort();
  }, [selectedCommitShas]);

  // Per-commit detail (first-parent SHA + committer date) for each
  // selected commit, fetched DIRECTLY from `/commits/{sha}` - not the
  // PR's commit list. This resolves any reachable SHA, including stale
  // pre-rebase commits that GitHub's `/pull/N/changes/<sha>` view still
  // renders but which no longer appear in the PR's current commit list.
  const commitDetailQueries = useQueries({
    queries: selectedShaArray.map((sha) => ({
      queryKey: ["pr", owner!, repo!, "commit-detail", sha],
      queryFn: () => getCommitDetail(owner!, repo!, sha),
      enabled: scopeActive && !!(owner && repo),
      staleTime: 5 * 60_000,
    })),
  });
  // True while a scope is active but not every selected commit's detail
  // has resolved yet - used to hold the loading state instead of
  // flashing the full PR file set.
  const commitDetailsLoading =
    scopeActive && !commitDetailQueries.every((q) => q.data != null);
  // Stable key over the resolved details so the scope memo only recomputes
  // when the actual (sha, parent, date) data changes - not on every render
  // (useQueries returns a fresh array each time).
  const commitDetailsKey = commitDetailQueries
    .map((q) =>
      q.data ? `${q.data.sha}:${q.data.parentSha}:${q.data.date}` : "∅",
    )
    .join("|");

  // Resolve the span endpoints from the selected commits' details.
  // head = the LATEST selected commit; base = the first-parent of the
  // EARLIEST selected commit. Single commit ⇒ parent…commit (= `git
  // show`); a multi-select ⇒ the spanning range (matches GitHub's
  // compare view). Null until all details resolve.
  //
  // Order TOPOLOGICALLY via the parent chain, NOT committer dates - a
  // rebase rewrites committer dates out of order, which would scramble
  // the endpoints (e.g. pick base===head===a middle commit → an empty
  // compare). In a contiguous selection each commit's parent is the
  // previous commit, so:
  //   earliest = the commit whose parent is NOT in the selection
  //   latest   = the commit that is NOT any selected commit's parent
  const scope = useMemo(() => {
    if (!scopeActive || commitDetailsLoading) return null;
    const details = commitDetailQueries
      .map((q) => q.data)
      .filter((d): d is NonNullable<typeof d> => d != null);
    if (details.length === 0) return null;
    const shaSet = new Set(details.map((d) => d.sha));
    const parentSet = new Set(
      details.map((d) => d.parentSha).filter((p): p is string => !!p),
    );
    const earliest =
      details.find((d) => !d.parentSha || !shaSet.has(d.parentSha)) ??
      details[0];
    const latest =
      details.find((d) => !parentSet.has(d.sha)) ?? details[details.length - 1];
    if (!earliest.parentSha) return null; // root commit - no base to diff
    return { baseSha: earliest.parentSha, headSha: latest.sha };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scopeActive, commitDetailsLoading, commitDetailsKey]);

  // Scoped file list - the net changes across the span, with GitHub's
  // status + previous_filename per file (drops straight into
  // fetchPRFileContents + buildDiffItems). Separate query from contents,
  // keyed by the resolved span so it caches per (base, head).
  //
  // The result carries its own (baseSha, headSha) alongside the files so
  // the displayed span travels as ONE unit. `placeholderData` then keeps
  // the PRIOR span's files+SHAs on screen while the next span fetches -
  // so switching commits never flashes the rows empty. First load (no
  // prior data) still falls through to the skeleton; only a background
  // *re*fetch shows the stale-then-fresh swap, flagged by the pulsing bar.
  const scopeFilesQuery = useQuery({
    queryKey: [
      "pr",
      owner!,
      repo!,
      "commit-scope-files",
      scope?.baseSha,
      scope?.headSha,
    ],
    queryFn: async () => ({
      baseSha: scope!.baseSha,
      headSha: scope!.headSha,
      files: await getCompareFiles(
        owner!,
        repo!,
        scope!.baseSha,
        scope!.headSha,
      ),
    }),
    enabled: scopeActive && !!scope && !!(owner && repo),
    placeholderData: (prev) => prev,
    staleTime: 5 * 60_000,
  });

  // The span actually backing the on-screen rows - rides with the files
  // query (its placeholderData keeps the prior span during a switch), so
  // files, SHAs, and (below) contents are always one coherent unit even
  // while the next span's details/files are still in flight.
  const displayedSpan = scopeFilesQuery.data;
  const scopeFiles = displayedSpan?.files;

  // Scoped file contents - old+new blobs at the span's base/head,
  // fetched with the SAME batched GraphQL fetcher PRDetailScreen uses
  // for the PR-level contents. Keyed off `displayedSpan` (NOT the live
  // `scope`) so its blobs always match the file list on screen; with
  // placeholderData it keeps the prior span's contents during a switch.
  const scopeContentsQuery = useQuery({
    queryKey: [
      "pr",
      owner!,
      repo!,
      "commit-scope-contents",
      displayedSpan?.baseSha,
      displayedSpan?.headSha,
    ],
    queryFn: () =>
      fetchPRFileContents(
        owner!,
        repo!,
        displayedSpan!.files,
        displayedSpan!.headSha,
        displayedSpan!.baseSha,
      ),
    enabled: scopeActive && !!displayedSpan && !!(owner && repo),
    placeholderData: (prev) => prev,
    staleTime: 5 * 60_000,
  });

  // The scope memo resolves to null once commit details are in but no
  // span can be formed (root commit / all details failed) → fall back to
  // the full PR file set, exactly as before.
  const scopeUnresolvable = scopeActive && !commitDetailsLoading && scope == null;
  const scopeContentsReady = scopeContentsQuery.data != null;
  // A coherent span is on screen (files + matching contents). True during
  // a background switch too, because both queries hold placeholder data.
  const scopeUsable =
    scopeActive && !scopeUnresolvable && !!displayedSpan && scopeContentsReady;
  // Skeleton ONLY while a scope has nothing to show yet - its very first
  // file-list / contents load. A switch keeps the prior rows instead (see
  // the pulsing bar), so we must NOT flash the full PR file set here.
  const scopeLoading = scopeActive && !scopeUnresolvable && !scopeUsable;
  // Background *re*fetch of an already-shown span - drives the pulsing
  // bar. Never true on first load (nothing is shown yet to keep).
  const scopeRefetching =
    scopeUsable &&
    (scopeFilesQuery.isFetching || scopeContentsQuery.isFetching);

  // Effective diff inputs. When a scope is active:
  //   - usable → the span's files/contents/SHAs (possibly placeholder)
  //   - first load → `undefined` (loading UI, no flash)
  //   - unresolvable → fall back to the full PR
  // When no scope is active → the PR-level props.
  const activeFiles = !scopeActive
    ? files
    : scopeUnresolvable
      ? files
      : scopeUsable
        ? scopeFiles
        : undefined;
  const activeContents =
    !scopeActive || scopeUnresolvable ? fileContents : scopeContentsQuery.data;
  const activeBaseSha =
    !scopeActive || scopeUnresolvable
      ? baseSha
      : displayedSpan?.baseSha ?? baseSha;
  const activeHeadSha =
    !scopeActive || scopeUnresolvable
      ? headSha
      : displayedSpan?.headSha ?? headSha;

  // File-list "still loading" signal for the rail + diff + toolbar:
  // either the PR /files endpoint is paginating, or a commit scope is
  // resolving its span / files / contents.
  const filesLoading = isFilesLoading || scopeLoading;

  // Reconcile thread anchors against the file contents on screen.
  //   - OUTDATED threads: re-anchor onto the deletion (old) side where the
  //     removed code now lives, so the card sits in context next to it
  //     (else float with the frozen snippet). Done in BOTH views.
  //   - NON-outdated threads: only meaningful in a commit-scoped view,
  //     where the selected commit's line numbers differ from PR head -
  //     relocate to the matching line, flag 'approximate', or float when
  //     the line falls outside this commit's file (would otherwise vanish).
  //     Left untouched in the full-PR view (GitHub's head line is correct).
  const activeThreadIndex = useMemo(() => {
    if (!threadIndex) return threadIndex;
    if (scopeUsable && scopeFiles && activeContents) {
      const scopedPaths = new Set(scopeFiles.map((f) => f.filename));
      return reconcileThreadAnchors(threadIndex, scopedPaths, activeContents, {
        outdatedOnly: false,
      });
    }
    if (activeContents) {
      const allPaths = new Set(threadIndex.byPath.keys());
      return reconcileThreadAnchors(threadIndex, allPaths, activeContents, {
        outdatedOnly: true,
      });
    }
    return threadIndex;
  }, [scopeUsable, threadIndex, scopeFiles, activeContents]);
  // "Search in diff" - case-insensitive content search across each
  // file's unified patch (added/removed/context lines). Filenames are
  // NOT searched - the file rail's own filter covers that.
  //
  // Each match is captured at line granularity so prev/next can jump
  // hit-by-hit (not just file-by-file). Lines come from the unified
  // patch headers (@@ -A,B +C,D @@) - we walk the patch and track
  // both sides' line counters in lockstep.
  const { filteredFiles, matchSummary } = useMemo(() => {
    if (!activeFiles) {
      return {
        filteredFiles: activeFiles,
        matchSummary: { matches: [] as DiffMatch[], byFile: new Set<string>() },
      };
    }
    const q = (search ?? "").trim().toLowerCase();
    if (!q) {
      return {
        filteredFiles: activeFiles,
        matchSummary: { matches: [] as DiffMatch[], byFile: new Set<string>() },
      };
    }
    const matches: DiffMatch[] = [];
    const byFile = new Set<string>();
    const out = activeFiles.filter((f) => {
      // Effective patch: GitHub's when present, else one reconstructed from
      // the full file contents. GitHub elides the patch for huge files
      // (lockfiles / generated output), but the diff is still rendered from
      // those contents - so reconstructing the patch gives search REAL line
      // numbers that land on the actual match, instead of the old coarse
      // "line 1" landmark that always scrolled to the file head.
      //
      // For a NORMAL file we deliberately do NOT search the full contents:
      // its patch already is the entire visible diff, and matching unchanged
      // (un-rendered, un-highlightable) regions would inflate the count with
      // jumps that go nowhere.
      let patch = f.patch ?? "";
      if (!patch) {
        const c = activeContents?.get(f.filename);
        const oldText = c?.oldText;
        const newText = c?.newText;
        const cheapHit =
          !!c &&
          !c.isBinary &&
          ((oldText?.toLowerCase().includes(q) ?? false) ||
            (newText?.toLowerCase().includes(q) ?? false));
        if (
          cheapHit &&
          oldText != null &&
          newText != null &&
          oldText !== newText
        ) {
          const key = reconPatchKey(f.filename, activeBaseSha, activeHeadSha);
          let recon = reconPatchRef.current.get(key);
          if (recon == null) {
            try {
              recon = reconstructUnifiedPatch(oldText, newText);
            } catch {
              recon = "";
            }
            reconPatchRef.current.set(key, recon);
          }
          patch = recon;
        }
      }
      const found = parsePatchForMatches(f.filename, patch, q);
      if (found.length > 0) {
        found.forEach((m) => matches.push(m));
        byFile.add(f.filename);
        return true;
      }
      return false;
    });
    return { filteredFiles: out, matchSummary: { matches, byFile } };
  }, [activeFiles, activeContents, activeBaseSha, activeHeadSha, search]);

  // Grouped list (ADR 0022 / "Grouped list"). The arrangement reorders the
  // file list into group folders; `view.orderedFiles` is the single ordered
  // sequence that feeds BOTH the rail and buildDiffItems, so the diff pane
  // and rail are always in lockstep. When ungrouped, orderedFiles === the
  // input list (same ref), so nothing changes.
  const arrangement = useArrangement(owner, repo, number, filteredFiles ?? []);

  // AI grouping (ADR 0026) - the async, non-deterministic dimension. The
  // store dimension drives `active`; the hook owns the LLM call + SHA cache
  // and produces the assignments/meta. We re-derive the view here with that
  // input so the rail + diff stay in lockstep (orderedFiles). When AI isn't
  // the active dimension the hook short-circuits to a cheap idle object.
  const navigate = useNavigate();
  const aiSettings = useAiSettings();
  const onSetupAi = useCallback(
    () => navigate({ to: '/settings', hash: 'ai-assistance' }),
    [navigate],
  );
  const aiDimensionActive =
    rail !== 'tree' && arrangement.arrangement.dimension === 'ai';
  const aiGrouping = useAiGrouping({
    active: aiDimensionActive,
    owner,
    repo,
    number,
    headSha: activeHeadSha,
    files: filteredFiles ?? [],
    contents: activeContents,
  });
  const arrangedView = useMemo(
    () =>
      aiDimensionActive
        ? deriveArrangedView(filteredFiles ?? [], arrangement.arrangement, aiGrouping.input)
        : arrangement.view,
    [aiDimensionActive, filteredFiles, arrangement.arrangement, arrangement.view, aiGrouping.input],
  );

  // AI inline review hints (ADR 0026) - triggered from the hints bar; the
  // hook owns the LLM call + SHA cache + view state. Its visible hints are
  // injected into the diff as NEW-side line annotations via LiveDiffPane.
  const aiHints = useAiHints({
    owner,
    repo,
    number,
    headSha: activeHeadSha,
    files: filteredFiles ?? [],
    contents: activeContents,
  });
  const aiHintsByFile = useMemo(() => {
    const m = new Map<string, AiHintAnchor[]>();
    aiHints.byFile.forEach((list, path) => {
      m.set(
        path,
        list.map((h) => ({
          id: h.id,
          line: h.line,
          type: h.type,
          severity: h.severity,
          title: h.title,
          body: h.body,
          guideline: h.guideline,
        })),
      );
    });
    return m;
  }, [aiHints.byFile]);

  // Publish the "Review with AI" trigger up to PRDetailScreen so the collapsed
  // (compact) PR header can ride the same control. One useAiHints instance
  // feeds both surfaces, so the count + running state never diverge. Locked
  // (AI off) → null: the discovery path stays in the body hints bar, not the
  // header. `done` mirrors the bar's progress heuristic.
  //
  // The activate callback reads the hook through a ref so it stays stable -
  // `aiHints.run` is re-created every render (its useCallback closes over a
  // fresh prId object), and depending on it here would publish a new trigger
  // each render and loop the parent setState. So the memo depends only on the
  // primitive status/count/fileCount.
  const aiHintsRef = useRef(aiHints);
  aiHintsRef.current = aiHints;
  const onAiActivate = useCallback(() => {
    const h = aiHintsRef.current;
    if (h.status === 'loading') return;
    // Hints already present → reveal the in-diff bar (also scrolls to the top,
    // re-expanding the header). Otherwise kick off the run.
    if (h.status === 'ready' || h.status === 'stale') {
      document
        .getElementById('ai-hints-bar')
        ?.scrollIntoView({ behavior: 'auto', block: 'start' });
      return;
    }
    h.run();
  }, []);
  const aiTriggerFileCount = (filteredFiles ?? []).length;
  const aiTrigger = useMemo<AiCompactTrigger | null>(() => {
    if (aiHints.status === 'locked') return null;
    const state: AiCompactTrigger['state'] =
      aiHints.status === 'loading'
        ? 'running'
        : aiHints.status === 'ready' || aiHints.status === 'stale'
          ? 'done'
          : 'ready';
    return {
      state,
      done: Math.round(aiTriggerFileCount / 2),
      total: aiTriggerFileCount,
      count: aiHints.total,
      estimate: aiHints.estimate,
      onActivate: onAiActivate,
    };
  }, [
    aiHints.status,
    aiHints.total,
    aiHints.estimate?.tokens,
    aiHints.estimate?.cost,
    aiTriggerFileCount,
    onAiActivate,
  ]);
  useEffect(() => {
    onAiTrigger?.(aiTrigger);
  }, [onAiTrigger, aiTrigger]);

  // Grouping is a list-view concept (the GroupingMenu only renders in
  // list mode). In tree mode the arrangement is inapplicable - the tree
  // shows path order, and letting the grouped order keep driving the
  // diff would put the two surfaces out of lockstep (ADR 0022). Derive
  // the effective arrangement from the rail mode rather than syncing the
  // store: the persisted dimension survives a trip through tree mode and
  // resumes on return to list, and `?rail=tree` deep links with a stored
  // arrangement render path order from the first frame.
  const grouped = rail !== 'tree' && arrangedView.grouped;
  const effectiveDimension = grouped
    ? arrangement.arrangement.dimension
    : 'none';
  // AI grouping resolves asynchronously and reorders `orderedFiles` without
  // changing effectiveDimension ('ai' the whole time), so the diff-pane
  // remount key below would NOT change when the result lands - leaving
  // @pierre/diffs to reorder items in place (the documented geometry-desync
  // trap). Fold the AI folder order into the key so the pane remounts when
  // the clustering appears or a re-run changes it.
  const aiArrangementSig = aiDimensionActive
    ? `:ai:${aiGrouping.status}:${arrangedView.folderOrder.join('~')}`
    : '';
  const orderedFiles = grouped
    ? arrangedView.orderedFiles
    : filteredFiles;

  // Matches in DISPLAY order (top → bottom of the rendered diff), not the
  // raw activeFiles order `matchSummary` is built in. Grouping/arrangement
  // can reorder files, so without this "result 1" wouldn't be the topmost
  // hit and next/prev (and the ruler dots) would jump around instead of
  // walking down the page. Stable sort by each file's position in
  // `orderedFiles` keeps within-file (line) order intact.
  const orderedMatches = useMemo(() => {
    const matches = matchSummary.matches;
    if (matches.length === 0) return matches;
    const pos = new Map(
      (orderedFiles ?? []).map((f, i) => [f.filename, i] as const),
    );
    return [...matches].sort(
      (a, b) =>
        (pos.get(a.filename) ?? Number.MAX_SAFE_INTEGER) -
        (pos.get(b.filename) ?? Number.MAX_SAFE_INTEGER),
    );
  }, [matchSummary, orderedFiles]);

  // Per-file hit counts, derived from matchSummary.matches. Drives
  // the "N matches" badge in each affected file's header (rendered
  // via LiveDiffPane's `searchMatchesByFile`). One Map allocation
  // per matchSummary change; lookup is O(1) per file header.
  const searchMatchesByFile = useMemo(() => {
    const m = new Map<string, number>();
    for (const hit of matchSummary.matches) {
      m.set(hit.filename, (m.get(hit.filename) ?? 0) + 1);
    }
    return m;
  }, [matchSummary]);

  // Surface the hit totals to the parent for the tab-bar toolbar's
  // "N in M files" search counter. Guarded to fire ONLY when the numbers
  // actually change: `matchSummary` is a fresh object whenever its inputs
  // re-derive, so an unguarded effect would push a new summary object (and
  // a parent setState) on every render - a self-sustaining update loop if
  // any upstream dep churns. The ref compares the scalar counts instead.
  const lastSummaryRef = useRef<{ count: number; fileCount: number } | null>(
    null,
  );
  useEffect(() => {
    const next = {
      count: matchSummary.matches.length,
      fileCount: matchSummary.byFile.size,
    };
    const prev = lastSummaryRef.current;
    if (prev && prev.count === next.count && prev.fileCount === next.fileCount) {
      return;
    }
    lastSummaryRef.current = next;
    onSearchSummaryChange?.(next);
  }, [matchSummary, onSearchSummaryChange]);

  // Findings index - incremented by the SubToolbar's prev/next
  // buttons; clamped + wrapped against matchSummary.matches. Resets
  // whenever the search query changes so a fresh search starts at
  // the first match.
  // Controlled-with-fallback: the parent (PRDetailScreen) owns the index
  // when it wires the toolbar's prev/next arrows; otherwise we keep it
  // locally. `setMatchIndex` routes to whichever owns it.
  const [internalMatchIndex, setInternalMatchIndex] = useState(0);
  const matchIndex = searchMatchIndex ?? internalMatchIndex;
  // Bumped on every explicit "go to this match" request (e.g. a ruler-dot
  // click). Re-selecting the CURRENT match leaves the index/coordinate
  // unchanged, so the coordinate-keyed scroll effect wouldn't re-fire and the
  // gesture would feel dead after you've scrolled away. Folding this into the
  // effect key makes a same-match request re-center.
  const [scrollNonce, setScrollNonce] = useState(0);
  const setMatchIndex = useCallback(
    (index: number) => {
      // Re-selecting the current match leaves the index (and coordinate key)
      // unchanged, so only then do we bump the nonce to force a re-scroll. A
      // new index drives the scroll via its coordinate key on its own, so
      // bumping the nonce there too would scroll twice (once to the old hit
      // before the index prop propagates, then to the new one).
      if (index === matchIndex) setScrollNonce((n) => n + 1);
      onSearchMatchIndexChange?.(index);
      if (searchMatchIndex == null) setInternalMatchIndex(index);
    },
    [onSearchMatchIndexChange, searchMatchIndex, matchIndex],
  );

  // Inputs for the scrollbar overview-ruler (VSCode-style dots). We supply
  // each match's filename + its position WITHIN its file (rowFrac, from the
  // patch); DiffBody turns that into accurate vertical dots using the
  // renderer's real per-file layout. Index-aligned with matchSummary.matches
  // so a dot click maps straight back to matchIndex. Empty when search is
  // off → DiffBody renders no rail.
  const searchMatches = useMemo(() => {
    if (!(search ?? "").trim()) return [];
    // Feed the ruler the SAME effective patch the match-finder used, so a
    // dot's vertical position inside an elided-patch file (yarn.lock) is the
    // real row fraction rather than the 0.5 fallback. The reconstruction is
    // already cached in `reconPatchRef` from the matchSummary pass above.
    const filesForFracs = (orderedFiles ?? []).map((f) =>
      f.patch
        ? f
        : {
            ...f,
            patch:
              reconPatchRef.current.get(
                reconPatchKey(f.filename, activeBaseSha, activeHeadSha),
              ) ?? f.patch,
          },
    );
    const fracs = matchRowFractions(filesForFracs, orderedMatches);
    return orderedMatches.map((m, i) => ({
      filename: m.filename,
      rowFrac: fracs[i] ?? 0.5,
    }));
  }, [search, orderedFiles, orderedMatches, activeBaseSha, activeHeadSha]);
  // Reset to the first hit on a new query. Only the uncontrolled (local)
  // index is reset here; when the parent controls the index it resets its
  // own on query change. Guarded so a navigation (which changes
  // searchMatchIndex, not search) never snaps back to 0.
  useEffect(() => {
    if (searchMatchIndex == null) setInternalMatchIndex(0);
  }, [search, searchMatchIndex]);
  // Scroll-to-target whenever the focused match changes.
  // Two-step so ARBITRARY jumps (a far click on the search ruler, or a
  // big prev/next step) land correctly, not just adjacent ones:
  //   1. `type:'item'` brings the file into view. This resolves even when
  //      the file is still virtualized/unrendered - whereas `type:'line'`
  //      can't resolve a line offset inside an unmeasured file and the lib
  //      falls back to scrollTop 0 (the whole diff jumps to the top).
  //   2. once the file has rendered + measured (next frame), `type:'line'`
  //      smooth-centres the exact matched line.
  // Then setSelectedLines for the lib's whole-line emphasis so the user
  // immediately sees which line matched - complementing the per-token
  // <mark> highlight from LiveDiffPane.
  const currentMatch = orderedMatches[matchIndex] ?? null;
  // Key the scroll effect on the match COORDINATE, not [matchIndex, search].
  // On a fresh query the patch matches aren't parsed yet, so currentMatch is
  // null and the scroll bails; by the time they resolve neither matchIndex nor
  // search has changed, so an index-keyed effect would never fire (the first
  // result would never scroll into view). The coordinate key flips from null
  // to a hit identity exactly when the first match becomes available, so we
  // scroll to result 1 right away; subsequent hits stay 1:1. Joined with a
  // space so distinct (lineNumber, hitInLine) pairs can never run together
  // into one key (e.g. line 1/hit 23 vs line 12/hit 3).
  const currentMatchKey = currentMatch
    ? [
        currentMatch.filename,
        currentMatch.side,
        currentMatch.lineNumber,
        currentMatch.hitInLine,
      ].join(" ")
    : null;
  // Whether the focused match's file CONTENT is loaded (and therefore its
  // diff is parsed). The lib can only resolve a line offset once the file's
  // diff exists; until then `scrollTo({type:'line'})` no-ops and we land on
  // the file head. For a huge file that streams in late (e.g. yarn.lock) the
  // content arrives well after the item does, so we re-fire the scroll when
  // it lands - keying on this flips false -> true exactly once per match.
  const currentMatchLoaded =
    !!currentMatch && !!activeContents?.has(currentMatch.filename);
  useEffect(() => {
    if (!currentMatch) return;
    const m = currentMatch;
    setCurrentPath(m.filename);
    const view = codeViewRef.current;
    if (!view) return;
    let frame = 0;
    let cancelled = false;
    let attempts = 0;
    let didItemScroll = false;
    let headTop: number | null = null;
    // INSTANT scroll, retried until it actually lands on the line. We tried
    // handing this to the lib's smooth pendingScrollTarget (the deeper fix),
    // but its spring does not take while the diff is re-rendering during
    // streaming, so it failed to scroll at all on big PRs. Instant snapping is
    // what reliably lands, and it doubles as the mask for the residual
    // estimate-then-measure correction jump.
    //
    // Two phases, because the lib lazily parses each file's diff only once the
    // file renders:
    //  1. getTopForItem resolves as soon as the item exists (estimated
    //     height), but getLinePosition needs the file's PARSED diff. So we
    //     first scroll the file into view (type:"item") to trigger its
    //     render+parse.
    //  2. Then we retry scrollTo({type:"line"}) every frame. Before the parse
    //     completes it no-ops and we sit at the file head; once it resolves it
    //     jumps to the exact line (deep lines in a huge file like yarn.lock
    //     resolve from metrics, no need to render them first). We detect the
    //     landing (scroll moved off the file-head position) and stop.
    // The first attempt runs synchronously so the common case is not lost to an
    // effect re-run cancelling the rAF.
    const run = () => {
      if (cancelled) return;
      const inst = view.getInstance();
      const scrollEl = inst?.getContainerElement?.() ?? null;
      if (!inst || inst.getTopForItem(m.filename) == null) {
        // The filtered item list is still rebuilding (fresh query); the lib
        // no-ops a scroll to an unknown id, so just wait for the item.
        if (attempts < 180) {
          attempts += 1;
          frame = requestAnimationFrame(run);
        }
        return;
      }
      if (!didItemScroll) {
        view.scrollTo({
          type: "item",
          id: m.filename,
          align: "center",
          behavior: "instant",
        });
        didItemScroll = true;
        if (attempts < 180) {
          attempts += 1;
          frame = requestAnimationFrame(run);
        }
        return;
      }
      if (headTop === null) headTop = scrollEl ? scrollEl.scrollTop : 0;
      view.scrollTo({
        type: "line",
        id: m.filename,
        lineNumber: m.lineNumber,
        side: m.side,
        align: "center",
        behavior: "instant",
      });
      // Whole-line emphasis (built-in lib selection); clears on the next
      // match jump because setSelectedLines is single-range.
      inst.setSelectedLines({
        id: m.filename,
        range: { start: m.lineNumber, end: m.lineNumber, side: m.side },
      });
      // Landed once the line target resolved and moved the viewport off the
      // file head; until then keep retrying (the file may still be parsing).
      const landed = scrollEl != null && scrollEl.scrollTop !== headTop;
      if (!landed && attempts < 180) {
        attempts += 1;
        frame = requestAnimationFrame(run);
      }
    };
    run();
    return () => {
      cancelled = true;
      cancelAnimationFrame(frame);
    };
    // Also re-fire when streaming completes: the diff remounts once
    // `isContentsLoading` flips (the remount key flips loading->ready),
    // which resets the scroll to the top, so we re-apply the scroll-to-match
    // against the fresh instance afterward.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentMatchKey, scrollNonce, currentMatchLoaded, isContentsLoading]);


  // Build CodeView items via parseDiffFromFile. Re-runs whenever the
  // files list OR file-contents map changes - typically twice per PR
  // open: once with empty contents (renders nothing per-file, the
  // file rail still works), once when the GraphQL-batched second
  // wave lands. ignoreWhitespace is hard-on per the maintainer's
  // guidance in pierre issue #366 (this is the only documented knob
  // for whitespace-blind diffs in @pierre/diffs).
  // Defer the streamed contents so the diff rebuild (the O(files) item
  // build + downstream annotate pipeline, even with the parse cache) runs
  // at LOW priority. React keeps the previous diff on screen and lets the
  // rebuild be interrupted by urgent work - tab switches, scrolling, the
  // Conversation tab - instead of janking them on every streaming wave.
  // The hidden-tab case is free (stale is invisible); the active diff just
  // catches up a frame later, which is fine while it's still loading.
  // Defer the ACTIVE contents (scoped span when a commit filter is on,
  // else the PR-level map) so the scoped diff rebuilds at low priority
  // just like the full-PR path.
  const deferredActiveContents = useDeferredValue(activeContents);
  // Native-git patches (local surface) only apply on the no-scope branch
  // - that's the only path whose `activeContents` come straight from the
  // model. A GitHub commit-scope swap recomputes contents itself and stays
  // on parseDiffFromFile. Deferred alongside the contents so the diff
  // rebuild runs at low priority.
  const activePatchByPath = !scopeActive ? patchByPath : undefined;
  const deferredPatchByPath = useDeferredValue(activePatchByPath);

  // Seed for the composer's `/suggestion` block - the current text of the
  // commented diff line(s) on the relevant side, so a suggestion pre-fills
  // GitHub-style instead of starting empty. Line numbers are 1-based.
  // Reads the ACTIVE contents so line numbers match the rendered diff
  // (the scoped span's head when a commit filter is active).
  const getSuggestionSeed = useCallback(
    (
      path: string,
      side: "LEFT" | "RIGHT",
      startLine: number,
      endLine: number,
    ): string | undefined => {
      const c = activeContents?.get(path);
      const text = side === "LEFT" ? c?.oldText : c?.newText;
      if (text == null) return undefined;
      const lines = text.split("\n");
      const from = Math.max(1, Math.min(startLine, endLine));
      const to = Math.min(lines.length, Math.max(startLine, endLine));
      if (from > lines.length) return undefined;
      return lines.slice(from - 1, to).join("\n");
    },
    [activeContents],
  );
  const live = useMemo(
    () =>
      buildDiffItems(
        orderedFiles ?? [],
        deferredActiveContents ?? new Map(),
        {
          ignoreWhitespace: true,
          headSha: activeHeadSha,
          baseSha: activeBaseSha,
          patchByPath: deferredPatchByPath,
        },
        diffItemCacheRef.current,
      ),
    [
      orderedFiles,
      deferredActiveContents,
      activeHeadSha,
      activeBaseSha,
      deferredPatchByPath,
    ],
  );

  return (
    <>
      {/* Background refetch with the prior diff still on screen - a commit
          span switch (scopeRefetching), or the PR-level /files poll when no
          scope is active (the full-PR view is what's shown then). The
          files-poll half lives in its own leaf component: it flips on
          every 15s heartbeat, and as a ChangesTab prop it re-rendered the
          entire diff chain per tick just to pulse this strip. */}
      <PrFilesFetchingBar
        owner={owner}
        repo={repo}
        number={number}
        scopeRefetching={scopeRefetching}
        pollVisible={!scopeActive || scopeUnresolvable}
      />
      {/* AI review hints bar (ADR 0026) - the "Review with AI" trigger + the
       * filter/cost/hide controls once hints exist. Locked when AI is off. */}
      <div id="ai-hints-bar">
        <AiHintsBar hints={aiHints} fileCount={(filteredFiles ?? []).length} onSetupAi={onSetupAi} />
      </div>
      <div className="relative flex min-h-0 flex-1">
        {railCollapsed ? (
          <FileRailCollapsed
            files={orderedFiles}
            viewedSet={viewedState?.viewed}
            threadIndex={activeThreadIndex}
            currentPath={currentPath}
            onSelect={(path) => {
              setCurrentPath(path);
              // Re-anchor to the newly-selected file and reset the
              // line/comment selection to its first line (top).
              onAnchorChange?.({ path });
              codeViewRef.current?.scrollTo({
                type: "item",
                id: path,
                align: "start",
                behavior: "smooth",
              });
            }}
            onExpand={() => setRailCollapsed(false)}
          />
        ) : (
          <>
            <FileRail
              ref={fileRailRef}
              active={active}
              mode={rail}
              onModeChange={setRail}
              filterQuery={fileFilter}
              onFilterQueryChange={onFileFilterChange}
              files={orderedFiles}
              // Grouping is a local-only review aid (localStorage; never
              // synced) - available even on read-only PRs, unlike viewed-state.
              arranged={grouped ? arrangedView : undefined}
              dimension={arrangement.arrangement.dimension}
              onDimensionChange={arrangement.setDimension}
              aiEnabled={aiSettings.ready}
              onSetupAi={onSetupAi}
              // The bespoke AI-grouped rail (design `ai-grouping.jsx`) renders
              // in place of the @pierre/trees rail when the `ai` dimension is
              // active. FileRail drives it from this hook + the arrangement.
              aiGrouping={aiDimensionActive ? aiGrouping : undefined}
              isFilesLoading={filesLoading}
              threadIndex={activeThreadIndex}
              commentCountByPath={commentCountByPath}
              viewedSet={viewedState?.viewed}
              loadingFilenames={live.loadingFilenames}
              onToggleViewed={readOnly ? undefined : viewedState?.toggle}
              onSetFolderViewed={readOnly ? undefined : viewedState?.setMany}
              currentPath={currentPath}
              onSelect={(path) => {
                // Click in the rail: update currentPath + scroll the
                // diff to that file. We don't touch the visible-file
                // marker directly - the diff's onScroll will fire as
                // the scroll settles and the marker follows the
                // header that lands at the top, per user spec.
                setCurrentPath(path);
                // Re-anchor to the newly-selected file and reset the
                // line/comment selection to its first line (top).
                onAnchorChange?.({ path });
                codeViewRef.current?.scrollTo({
                  type: "item",
                  id: path,
                  align: "start",
                  behavior: "smooth",
                });
              }}
              onCollapse={() => setRailCollapsed(true)}
              width={railWidth}
              owner={owner}
              repo={repo}
              headSha={headSha}
            />
            <Resizer onPointerDown={startRailDrag} dragging={railDragging} />
          </>
        )}
        {contentsError ? (
          // File LIST loaded (rail + toolbar above stay populated), but the
          // diff bodies failed → scope the outage card to the diff column
          // instead of taking over the whole tab. `flex-1` so it fills the
          // space LiveDiffPane would have occupied, right of the rail.
          <div className="flex min-h-0 flex-1 flex-col bg-card">
            <PRErrorPane
              error={contentsError}
              endpoint={`/repos/${owner}/${repo}/pulls/${number}/files`}
              layout="inline"
              lastSyncedAt={lastSyncedAt}
              onRetry={onRetryContents}
              onOpenOnGithub={() =>
                window.open(
                  `https://github.com/${owner}/${repo}/pull/${number}/files`,
                  "_blank",
                )
              }
            />
          </div>
        ) : (
          <>
            <LiveDiffPane
              annotationLayer={annotationLayer}
              aiHints={aiHintsByFile}
              onDismissHint={aiHints.dismiss}
              // Remount the whole diff pane whenever the grouping
              // arrangement, the displayed revision, or the contents-load
              // state changes. Updating @pierre/diffs items in place has
              // produced a family of record/DOM height desyncs (parts of
              // the diff render static, or the bodies stay frozen on the
              // OLD commit until a full page reload) - a fresh mount is the
              // one operation proven to produce correct geometry.
              //   - effectiveDimension: grouping flips.
              //   - activeHeadSha/activeBaseSha: a commit-scope change that
              //     shifts the displayed span.
              //   - isContentsLoading: a new commit / amend / force push.
              //     The diff data updates via React Query, but @pierre/diffs
              //     ignores the changed `build` prop without a remount.
              //     Keying on head.sha alone remounts too EARLY - the SHA
              //     flips when the poll detects the commit, ~1s before the
              //     blob contents finish fetching, so the early mount shows
              //     the prior diff and the later content arrival is dropped
              //     (verified live). The isFetching true→false edge remounts
              //     again the instant the new contents settle. isFetching
              //     only toggles on a content-affecting refetch (head/base/
              //     file-set change), never on a no-op 15s poll, so
              //     steady-state polling causes no remount churn; a
              //     multi-batch stream stays true throughout and flips once
              //     at completion (one remount, not per batch).
              // The parsed-diff cache (diffItemCacheRef) lives in this
              // component and survives, so the remount re-uses parsed
              // patches and costs a single commit, not a PR re-parse.
              key={`arrangement:${effectiveDimension}${aiArrangementSig}:${activeHeadSha}:${activeBaseSha}:${isContentsLoading ? 'loading' : 'ready'}`}
              ref={codeViewRef}
              readOnly={readOnly}
              build={live}
              isContentsLoading={isContentsLoading}
              isFilesLoading={filesLoading}
              focusMode={focusMode}
              threadIndex={activeThreadIndex}
              owner={owner}
              repo={repo}
              number={number}
              getSuggestionSeed={getSuggestionSeed}
              getFileText={(path, side) => {
                const c = activeContents?.get(path);
                return (side === 'additions' ? c?.newText : c?.oldText) ?? undefined;
              }}
              scrollToLine={(path, side, line) => {
                // Scroll the (possibly virtualized) line into view. No item-to-top
                // jump — go-to-def stays within the already-visible file.
                codeViewRef.current?.scrollTo({
                  type: "line",
                  id: path,
                  lineNumber: line,
                  side,
                  align: "center",
                  behavior: "smooth",
                });
              }}
              getFilePatch={(filename) => {
                const f = (orderedFiles ?? []).find(
                  (x) => x.filename === filename,
                );
                if (!f) return undefined;
                // Same effective patch the ruler uses for search (elided-patch
                // files fall back to the cached reconstruction).
                return (
                  f.patch ??
                  reconPatchRef.current.get(
                    reconPatchKey(filename, activeBaseSha, activeHeadSha),
                  )
                );
              }}
              headSha={headSha}
              baseSha={baseSha}
              onReplied={onChanged}
              onAnchorChange={onAnchorChange}
              draftActions={draftActions}
              viewerLogin={viewerLogin}
              prAuthorLogin={prAuthorLogin}
              viewedState={viewedState}
              diffStyle={diff === "split" ? "split" : "unified"}
              searchQuery={search}
              searchMatchesByFile={searchMatchesByFile}
              activeMatch={currentMatch}
              searchMatches={searchMatches}
              activeMatchIndex={matchIndex}
              onSelectMatch={setMatchIndex}
              shikiTheme={theme}
              lineDiffStyle={lineDiffStyle}
              fontSize={fontSize}
              lineHeight={lineHeight}
              collapseState={collapseState}
              onScrollChange={onScrollChange}
              // Track the topmost visible file in the diff and highlight
              // its row in the rail. The receiver does a direct shadow-
              // DOM (tree) or light-DOM (list) attribute mutation, no
              // React state, no re-renders. Safe to call on every scroll
              // frame - the callback short-circuits when the path hasn't
              // changed since last call.
              onVisibleFileChange={(path) =>
                fileRailRef.current?.setVisiblePath(path)
              }
            />
            <JumpWidget
              onScrollTop={() =>
                codeViewRef.current?.scrollTo({
                  type: "position",
                  position: 0,
                  behavior: "smooth",
                })
              }
              onScrollBottom={() => {
                const last = orderedFiles?.[orderedFiles.length - 1];
                if (last)
                  codeViewRef.current?.scrollTo({
                    type: "item",
                    id: last.filename,
                    align: "end",
                    behavior: "smooth",
                  });
              }}
            />
          </>
        )}
      </div>
      {/* Review submission dock - hidden in read-only demo mode (AFK
          plan 22): no draft can be submitted without a token. Also hidden
          on the local pre-PR surface, which passes no draft (commenting is
          owned by the annotation layer, batched to localStorage). */}
      {!readOnly && draft && onOpenModal && onDiscardReview && (
        <ReviewDock
          draft={draft}
          onOpenModal={onOpenModal}
          onDiscard={() => void onDiscardReview()}
        />
      )}
    </>
  );
}

/** A single hit from "Search in diff" - file + line + which side
 * of the diff the line lives on + the 0-based occurrence index
 * within that line (so multiple hits on the same line are
 * individually addressable). Drives the lib's line-scroll target
 * and the active-mark emphasis on prev/next jumps. */
interface DiffMatch {
  filename: string;
  lineNumber: number;
  side: "additions" | "deletions";
  hitInLine: number;
}

/** Cache key for a reconstructed patch, scoped to the file's content
 *  identity (path + the two SHAs being compared) so a commit-scope change
 *  never reuses a stale reconstruction. */
function reconPatchKey(
  filename: string,
  baseSha: string | undefined,
  headSha: string | undefined,
): string {
  return `${filename}@${baseSha ?? ""}..${headSha ?? ""}`;
}

/** GitHub elides the `patch` for huge files (lockfiles, generated output),
 *  but the diff is still RENDERED from the full file contents we fetch
 *  separately. Reconstruct a unified patch from those same contents so
 *  search match-finding (and the ruler) get REAL line numbers that line up
 *  with what's on screen - instead of a single coarse "line 1" landmark
 *  that always scrolls to the file head.
 *
 *  Emits only the @@-headers + body lines (no ---/+++ file-header lines,
 *  which start with -/+ and would corrupt the +/- line counting in
 *  `forEachPatchBodyLine`). `ignoreWhitespace` mirrors the renderer
 *  (buildDiffItems) so the reconstructed hunks match the rendered ones. */
function reconstructUnifiedPatch(oldText: string, newText: string): string {
  const { hunks } = structuredPatch("a", "b", oldText, newText, "", "", {
    context: 4,
    ignoreWhitespace: true,
  });
  return hunks
    .map(
      (h) =>
        `@@ -${h.oldStart},${h.oldLines} +${h.newStart},${h.newLines} @@\n` +
        h.lines.join("\n"),
    )
    .join("\n");
}

/** Walk a unified-diff patch line-by-line tracking both sides' line
 * counters. For each line whose body contains `q` (case-insensitive,
 * lowercased by the caller is fine - we re-lowercase inline), record
 * one DiffMatch with the line number on the side that line belongs
 * to. Multiple matches on the same line still emit a single match -
 * the per-token <mark> highlight inside the line makes finer
 * granularity unnecessary for jump targets. */
function parsePatchForMatches(
  filename: string,
  patch: string,
  q: string,
): DiffMatch[] {
  if (!patch || !q) return [];
  const qLower = q.toLowerCase();
  const out: DiffMatch[] = [];
  // Walk the patch via the shared body-line iterator (single source of
  // line numbering, also used by the ruler's row-fraction map). Deletions
  // anchor on the old side; additions and context anchor on the new side
  // (context prefers additions so prev/next emphasis lands on the modern
  // line numbers in split mode).
  forEachPatchBodyLine(patch, (l) => {
    const side: DiffMatch["side"] =
      l.marker === "-" ? "deletions" : "additions";
    const lineNumber = l.marker === "-" ? l.delLineNo : l.addLineNo;
    // Push one DiffMatch per occurrence in the line body, not one per
    // matching line, so navigating walks individual hits 1:1 with the
    // <mark> elements LiveDiffPane wraps in the rendered shadow DOM.
    // hitInLine: occurrence ordinal within this line (0-based).
    const lower = l.body.toLowerCase();
    let i = 0;
    let hitInLine = 0;
    while (i < lower.length) {
      const found = lower.indexOf(qLower, i);
      if (found === -1) break;
      out.push({ filename, lineNumber, side, hitInLine });
      hitInLine++;
      i = found + qLower.length;
    }
  });
  return out;
}

/** A file "has comments" for the purposes of bulk-collapse iff it has
 * at least one *unresolved* inline thread. Resolved threads collapse
 * to a one-line stub in the diff and don't visually carry comments,
 * so the user thinks of those files as comment-less - counting them as
 * having comments would silently exclude them from "Collapse files
 * without comments" and the action would feel half-broken.
 *
 * isResolved is undefined while the GraphQL thread query is still in
 * flight; treat undefined as "unresolved" (conservative - we'd rather
 * leave a file expanded than collapse one with unread feedback). */
function fileHasOpenComments(
  filename: string,
  threadIndex: ThreadIndex | undefined,
): boolean {
  const threads = threadIndex?.byPath.get(filename);
  if (!threads || threads.length === 0) return false;
  return threads.some((t) => t.isResolved !== true);
}

/** The pulsing fetch bar above the diff. Subscribes to the /files
 * query's fetch state HERE - at the strip that displays it - via
 * useIsFetching, so the every-15s poll flip re-renders only this
 * component. (As a `filesRefetching` prop from PRDetailScreen it
 * re-rendered ChangesTab → LiveDiffPane → DiffBody per tick.)
 * data/error are read non-reactively: the bar re-renders on every
 * fetch-count change anyway, which is exactly when they can move. */
function PrFilesFetchingBar({
  owner,
  repo,
  number,
  scopeRefetching,
  pollVisible,
}: {
  /** PR coords are optional on ChangesTab itself; without them the
   *  poll half of the bar simply never shows. */
  owner?: string;
  repo?: string;
  number?: number;
  /** Commit-span switch refetch - always shows the bar. */
  scopeRefetching: boolean;
  /** Whether the full-PR view (the thing the files poll refreshes) is
   *  what's on screen - no scope active, or the scope is unresolvable. */
  pollVisible: boolean;
}) {
  const queryClient = useQueryClient();
  const filesKey = ["pr", owner ?? "", repo ?? "", number ?? 0, "files"] as const;
  const fetching =
    useIsFetching({ queryKey: filesKey, exact: true }) > 0;
  const state = queryClient.getQueryState(filesKey);
  // Background refetch only: rows already on screen (data) and not in
  // an error state - the cold load shows the skeleton instead.
  const filesRefetching =
    fetching && state?.data !== undefined && state?.error == null;
  return (
    <FetchingBar
      active={scopeRefetching || (pollVisible && filesRefetching)}
    />
  );
}

/** Count of files in this PR that the user has marked viewed. Bounded
 * to files actually present in the current /files response - a stale
 * viewed-set entry for a removed file shouldn't bump the numerator
 * past the denominator. */
function countViewedInFiles(
  viewed: Set<string> | undefined,
  files: GHPullRequestFile[] | undefined,
): number {
  if (!viewed || !files) return 0;
  let n = 0;
  for (const f of files) if (viewed.has(f.filename)) n++;
  return n;
}
