// Product analytics consent (ADR 0021).
//
// The authenticated product runs PostHog under LEGITIMATE INTEREST with a
// prominent OPT-OUT (distinct from the landing's strict opt-in gate). This is
// the kill switch: when set, capture stops immediately and stays off across
// reloads. The toggle that drives it lives in Settings. Error tracking
// (Sentry) is unaffected — it runs on a stability/security basis.
//
// Implemented as a tiny external store so React reads it via
// `useSyncExternalStore` (no useEffect, no prop-drilling).

import posthog from 'posthog-js';
import { analyticsConfigured } from './config';

const KEY = 'pyor:analytics-optout';

function read(): boolean {
  try {
    return localStorage.getItem(KEY) === '1';
  } catch {
    return false;
  }
}

const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());

export function isAnalyticsOptedOut(): boolean {
  return read();
}

/** Persist the choice and apply it to the live PostHog instance immediately. */
export function setAnalyticsOptOut(optedOut: boolean): void {
  try {
    optedOut ? localStorage.setItem(KEY, '1') : localStorage.removeItem(KEY);
  } catch {
    /* storage disabled — choice won't persist, but apply for this session. */
  }
  if (analyticsConfigured) {
    optedOut ? posthog.opt_out_capturing() : posthog.opt_in_capturing();
  }
  emit();
}

function subscribe(cb: () => void): () => void {
  listeners.add(cb);
  return () => listeners.delete(cb);
}

/** React binding for the Settings toggle. */
export function subscribeOptOut(cb: () => void): () => void {
  return subscribe(cb);
}
export const getOptOutSnapshot = read;
