// The lockstep core. deriveArrangedView() turns (files, arrangement) into
// one ordered file list plus the synthetic display-path map the rail's
// @pierre/trees model consumes. BOTH the rail and buildDiffItems read
// `orderedFiles`, so the diff pane and the rail are always in the same
// sequence (ADR 0022). Pure — no React, no I/O.
//
// Groups are modeled as native tree folders via synthetic display paths
// ("<folder>/<basename>"). A single level only: folders contain files,
// never sub-folders. Ordering is driven explicitly by orderIndexByKey +
// a sort comparator (not the flat list's invisible-prefix hack).
//
// Folders here are all dimension-derived ("auto"). Drag-to-recategorize and
// reviewer-created custom folders are deferred (see ADR 0022), so a file's
// folder is fully determined by the dimension.

import type { GHPullRequestFile } from '../../../github/types';
import {
  alwaysBuckets,
  assignChangeSize,
  assignFileType,
} from './dimensions';
import { clusterSimilar } from './similarity';
import type { AiFolderMeta, Arrangement, AutoAssignment } from './types';

/** Injected AI grouping inputs for the async `ai` dimension. The
 * assignments map file → group; the meta map carries each group's
 * description + signal/noise kind keyed by groupId. */
export interface AiGroupingInput {
  assignments: Map<string, AutoAssignment>;
  groupMeta: Map<string, { name: string; description: string; kind: 'important' | 'noise' }>;
}

/** Invisible disambiguator for colliding folder/file display segments. */
const ZWSP = '​';

/** Per-folder composition tallies, keyed by display folder segment. The
 * rail's composition bar + per-folder % badge read these. `changed` is the
 * lines metric (additions + deletions); `pctLines` is that folder's share of
 * the PR's total changed lines (0–100, 0 when the PR has no line churn). */
export interface FolderStat {
  files: number;
  additions: number;
  deletions: number;
  changed: number;
  pctLines: number;
}

export interface ArrangedView {
  /** True when a grouping dimension is active. */
  grouped: boolean;
  /** The single ordered file list — feeds the rail AND buildDiffItems. */
  orderedFiles: GHPullRequestFile[];
  /** All file display paths fed to the lib. */
  displayPaths: string[];
  realToDisplay: Map<string, string>;
  displayToReal: Map<string, string>;
  /** Display path (folder segment, "folder/base", or "base") → sort index. */
  orderIndexByKey: Map<string, number>;
  /** Folder display segment → its member real paths (for viewed rollup). */
  folderMembers: Map<string, string[]>;
  /** Folder display segments, in visual order (footer count). */
  folderOrder: string[];
  /** Per-folder composition tallies (lines + file counts), keyed by display
   * folder segment. Drives the composition bar + per-folder % badge. */
  folderStats: Map<string, FolderStat>;
  /** Total changed lines (additions + deletions) across ALL files — the
   * denominator for every folder's `pctLines`. Loose/ungrouped files are
   * included, so the folders' shares never sum past 100%. */
  totalChanged: number;
  /** AI dimension only — per-folder description + signal/noise, keyed by
   * the display folder segment. Empty for the deterministic dimensions. */
  folderMeta: Map<string, AiFolderMeta>;
}

/** Per-file auto assignment for the active dimension. `similar` needs the
 * whole set, the rest are per-file. Files with no assignment → undefined. */
function autoAssignments(
  files: GHPullRequestFile[],
  dimension: Arrangement['dimension'],
  ai?: AiGroupingInput,
): Map<string, AutoAssignment> {
  if (dimension === 'ai') return ai?.assignments ?? new Map();
  if (dimension === 'similar') return clusterSimilar(files);
  const fn =
    dimension === 'file-type'
      ? assignFileType
      : dimension === 'change-size'
        ? assignChangeSize
        : null;
  if (!fn) return new Map();
  return new Map(files.map((f) => [f.filename, fn(f)]));
}

function basenameOf(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1);
}

/** Make `seg` unique within `used`, appending ZWSPs (invisible) on clash. */
function uniqueSegment(seg: string, used: Set<string>): string {
  let out = seg;
  while (used.has(out)) out += ZWSP;
  used.add(out);
  return out;
}

export function deriveArrangedView(
  files: GHPullRequestFile[],
  arrangement: Arrangement,
  ai?: AiGroupingInput,
): ArrangedView {
  const grouped = arrangement.dimension !== 'none';

  if (!grouped) {
    return {
      grouped: false,
      orderedFiles: files,
      displayPaths: files.map((f) => f.filename),
      realToDisplay: new Map(),
      displayToReal: new Map(),
      orderIndexByKey: new Map(),
      folderMembers: new Map(),
      folderOrder: [],
      folderStats: new Map(),
      totalChanged: 0,
      folderMeta: new Map(),
    };
  }

  const auto = autoAssignments(files, arrangement.dimension, ai);
  // Track which groupId each retained auto group came from so we can map
  // the AI per-group meta (description/kind) onto the display folder segment.
  const groupIdByFolderSeg = new Map<string, string>();
  const folderMeta = new Map<string, AiFolderMeta>();

  // Bucket files by their dimension assignment (preserving incoming order
  // within each bucket); unassigned files go loose at root.
  const autoMembers = new Map<string, string[]>();
  const autoMetaById = new Map<string, { label: string; order: number }>();
  let loose: string[] = [];

  files.forEach((f) => {
    const a = auto.get(f.filename);
    if (!a) {
      loose.push(f.filename);
      return;
    }
    const list = autoMembers.get(a.groupId);
    if (list) list.push(f.filename);
    else autoMembers.set(a.groupId, [f.filename]);
    autoMetaById.set(a.groupId, { label: a.groupLabel, order: a.order });
  });

  // ≥2 rule: heuristic dimensions dissolve single-file auto groups to
  // loose. Fixed-bucket dimensions (change-size) keep them.
  if (!alwaysBuckets(arrangement.dimension)) {
    [...autoMembers.entries()]
      .filter(([, m]) => m.length < 2)
      .forEach(([id, m]) => {
        loose.push(...m);
        autoMembers.delete(id);
      });
    // Restore loose to incoming file order (dissolved members were appended).
    const order = new Map(files.map((f, i) => [f.filename, i]));
    loose = loose.sort((a, b) => (order.get(a) ?? 0) - (order.get(b) ?? 0));
  }

  // Top-level order: auto groups (order asc, label asc), then loose files.
  const usedRootSegments = new Set<string>();
  const realToDisplay = new Map<string, string>();
  const displayToReal = new Map<string, string>();
  const orderIndexByKey = new Map<string, number>();
  const folderMembers = new Map<string, string[]>();
  const folderOrder: string[] = [];
  const folderStats = new Map<string, FolderStat>();
  const displayPaths: string[] = [];
  const orderedFiles: GHPullRequestFile[] = [];
  const byName = new Map(files.map((f) => [f.filename, f]));
  // Lines metric denominator: every changed line in the PR (loose included).
  const totalChanged = files.reduce(
    (sum, f) => sum + f.additions + f.deletions,
    0,
  );
  let idx = 0;

  [...autoMembers.keys()]
    .sort((a, b) => {
      const ma = autoMetaById.get(a)!;
      const mb = autoMetaById.get(b)!;
      return ma.order - mb.order || ma.label.localeCompare(mb.label);
    })
    .forEach((id) => {
      const meta = autoMetaById.get(id)!;
      const folderSeg = uniqueSegment(meta.label, usedRootSegments);
      groupIdByFolderSeg.set(folderSeg, id);
      folderOrder.push(folderSeg);
      const members = autoMembers.get(id) ?? [];
      folderMembers.set(folderSeg, members);
      const tally = members.reduce(
        (acc, real) => {
          const file = byName.get(real);
          if (file) {
            acc.additions += file.additions;
            acc.deletions += file.deletions;
          }
          return acc;
        },
        { additions: 0, deletions: 0 },
      );
      const changed = tally.additions + tally.deletions;
      folderStats.set(folderSeg, {
        files: members.length,
        additions: tally.additions,
        deletions: tally.deletions,
        changed,
        pctLines: totalChanged > 0 ? (changed / totalChanged) * 100 : 0,
      });
      orderIndexByKey.set(folderSeg, idx++);
      const usedInFolder = new Set<string>();
      members.forEach((real) => {
        const base = uniqueSegment(basenameOf(real), usedInFolder);
        const display = `${folderSeg}/${base}`;
        realToDisplay.set(real, display);
        displayToReal.set(display, real);
        orderIndexByKey.set(display, idx++);
        displayPaths.push(display);
        const file = byName.get(real);
        if (file) orderedFiles.push(file);
      });
    });

  // Loose files at root (after all folders).
  loose.forEach((real) => {
    const base = uniqueSegment(basenameOf(real), usedRootSegments);
    realToDisplay.set(real, base);
    displayToReal.set(base, real);
    orderIndexByKey.set(base, idx++);
    displayPaths.push(base);
    const file = byName.get(real);
    if (file) orderedFiles.push(file);
  });

  // Map the AI per-group meta onto display folder segments (AI dimension).
  if (ai) {
    folderOrder.forEach((seg, i) => {
      const gid = groupIdByFolderSeg.get(seg);
      const m = gid ? ai.groupMeta.get(gid) : undefined;
      if (m) {
        folderMeta.set(seg, { name: m.name, description: m.description, kind: m.kind, order: i });
      }
    });
  }

  return {
    grouped: true,
    orderedFiles,
    displayPaths,
    realToDisplay,
    displayToReal,
    orderIndexByKey,
    folderMembers,
    folderOrder,
    folderStats,
    totalChanged,
    folderMeta,
  };
}
