// Electron `pyor://` deep links → router (ADR 0019, ADR 0024).
//
// Three hosts:
//   - pyor://callback?code=…&state=…    OAuth sign-in return (the backend 302s
//     the system browser here after the user approves the GitHub App).
//   - pyor://installed?installation_id=…  post-INSTALL return. The install flow
//     drops our CSRF state, so the broker can't route it back to the app — the
//     web /connect/installed page offers a "Return to Pyor" button that opens
//     this deep link. We're already signed in, so we just refresh the
//     repo-derived caches and land on the PR list.
//   - pyor://pull/owner/repo/N          Browser-Helper handoff (ADR 0024). The
//     Pyor Helper extension fires this when intercepting a github.com PR page,
//     so a PR link clicked anywhere opens directly in the app. We route it
//     through the same `openPR()` every in-app "open this PR" call-site uses.
//
// The main process forwards every `pyor://` URL on the `deep-link` channel
// (forwardDeepLink in main.ts), so no native change is needed per host.

import { useEffect } from 'react';
import { useNavigate } from '@tanstack/react-router';
import { bridge } from './electronBridge';
import { queryClient } from '../lib/queryClient';
import { PULLS_DEFAULTS } from '../router/search';
import { openPR } from '../router/nav';
import { parsePrParam } from '../util/parsePrParam';

export function useDeepLink(): void {
  const navigate = useNavigate();
  useEffect(() => {
    const b = bridge();
    if (!b) return;
    return b.onDeepLink((url) => {
      let parsed: URL;
      try {
        parsed = new URL(url);
      } catch {
        return;
      }
      if (parsed.host === 'callback') {
        void navigate({
          to: '/connect/callback',
          search: {
            code: parsed.searchParams.get('code') ?? undefined,
            state: parsed.searchParams.get('state') ?? undefined,
            error: parsed.searchParams.get('error') ?? undefined,
          },
        });
        return;
      }
      if (parsed.host === 'installed') {
        // Newly-granted repos just became visible — drop the cached PR-search
        // results so the lists refetch against the widened installation.
        void queryClient.invalidateQueries();
        void navigate({ to: '/pulls', search: PULLS_DEFAULTS });
        return;
      }
      if (parsed.host === 'pull') {
        // Browser-Helper handoff (ADR 0024). The standard `pyor://` scheme
        // parses `pyor://pull/owner/repo/N` as host=`pull`,
        // pathname=`/owner/repo/N` — strip the leading slash and reuse the
        // same parser the `?pr=` demo deep-link uses. A malformed payload
        // (parse → null) is ignored, same as an unknown host.
        const coords = parsePrParam(parsed.pathname.replace(/^\//, ''));
        if (coords) openPR(navigate, coords);
        return;
      }
    });
  }, [navigate]);
}
