// Banner shown above the Changes tab while a force-push refetch is
// in flight. Matches shell-pr-loading-force-push: amber, dismissible,
// shows old → new SHA + progress + Show new diff CTA.
//
// We don't try to enumerate per-file changes (rewritten / new /
// unchanged) here — that would require a base/head files diff we
// don't currently compute. The summary text leaves room for that
// future work without misrepresenting what we know today.

import { GitPullRequestIcon, XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';

export interface ForcePushInfo {
  prevSha: string;
  newSha: string;
  detectedAt: number;
  refetchProgress?: { resolved: number; total: number };
}

export function ForcePushBanner({
  info,
  pendingDraftCount,
  onDismiss,
}: {
  info: ForcePushInfo;
  pendingDraftCount?: number;
  onDismiss?: () => void;
}) {
  const ageSec = Math.max(
    0,
    Math.round((Date.now() - info.detectedAt) / 1000),
  );
  const pct =
    info.refetchProgress && info.refetchProgress.total > 0
      ? Math.round(
          (info.refetchProgress.resolved / info.refetchProgress.total) * 100,
        )
      : null;
  return (
    <div className="border-b border-amber-200 bg-amber-50/60 dark:border-amber-900 dark:bg-amber-950/30">
      <div className="flex items-start gap-3 px-5 py-3 text-[12.5px]">
        <div className="mt-0.5 inline-flex size-7 shrink-0 items-center justify-center rounded-md border border-amber-300 bg-card dark:border-amber-700">
          <GitPullRequestIcon className="size-3.5 text-amber-700 dark:text-amber-400" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-baseline gap-2">
            <b className="text-[13px] font-semibold text-amber-900 dark:text-amber-200">
              Force-push detected · {ageSec}s ago
            </b>
            <span className="font-mono text-[11.5px] text-amber-800/70 dark:text-amber-300/70">
              {info.prevSha.slice(0, 7)} → {info.newSha.slice(0, 7)}
            </span>
          </div>
          <div className="mt-0.5 text-[12px] leading-relaxed text-amber-800/90 dark:text-amber-300/90">
            We're keeping the prior diff on screen until the new content
            arrives so you don't lose your place.
            {pendingDraftCount && pendingDraftCount > 0 ? (
              <>
                {' '}
                Your draft is safe ({pendingDraftCount} pending comment
                {pendingDraftCount === 1 ? '' : 's'}).
              </>
            ) : null}
          </div>
          {pct !== null && (
            <div className="mt-2 flex items-center gap-2">
              <div className="relative h-1 w-44 overflow-hidden rounded-full bg-amber-200 dark:bg-amber-900">
                <div
                  className="absolute inset-y-0 left-0 bg-amber-700 transition-[width] dark:bg-amber-400"
                  style={{ width: `${pct}%` }}
                />
              </div>
              <span className="font-mono text-[11px] tabular-nums text-amber-800 dark:text-amber-300">
                {info.refetchProgress!.resolved} /{' '}
                {info.refetchProgress!.total} files
              </span>
            </div>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-1.5">
          {onDismiss && (
            <Button
              variant="ghost"
              size="icon"
              onClick={onDismiss}
              title="Dismiss"
            >
              <XIcon />
            </Button>
          )}
        </div>
      </div>
      {/* Inline range-compare strip — at-a-glance "what changed in the
       *  push". The per-file badges (rewritten / new / untouched) would
       *  ideally come from a base→head files diff against the prior SHA;
       *  until that's computed, render the design's generic reassurance
       *  copy so the strip still appears and the user sees the affordance. */}
      <div className="flex flex-wrap items-center gap-2 border-t border-amber-200/60 bg-amber-50/30 px-5 py-1.5 text-[11.5px] text-amber-900/80 dark:border-amber-900/60 dark:bg-amber-950/20 dark:text-amber-300/80">
        <span className="text-amber-700 dark:text-amber-400">
          In the new push:
        </span>
        <Badge
          variant="outline"
          className="gap-1 border-amber-300 bg-card text-amber-900 dark:border-amber-700 dark:text-amber-200"
        >
          <span className="font-mono">
            {info.newSha.slice(0, 7)}
          </span>
          <span className="text-amber-600 dark:text-amber-400">head</span>
        </Badge>
        <Badge
          variant="outline"
          className="gap-1 border-amber-300 bg-card text-amber-900 dark:border-amber-700 dark:text-amber-200"
        >
          <span className="font-mono">
            {info.prevSha.slice(0, 7)}
          </span>
          <span className="text-amber-600 dark:text-amber-400">was</span>
        </Badge>
        <span className="ml-auto text-[11px] text-amber-700/70 dark:text-amber-400/70">
          Drafts re-anchor by line content — should survive the rewrite
        </span>
      </div>
    </div>
  );
}
