// Scroll signals for the collapsing "smart header".
//
// The header hides as you scroll DOWN and slides back as you scroll UP. We
// drive that from WHEEL/trackpad input (`deltaY`), NOT from scrollTop deltas:
// the header collapsing resizes the scroll container, which makes
// react-virtuoso re-adjust scrollTop — and reading THAT as "the user
// scrolled" creates a feedback loop (the header fights itself). Wheel input
// is the user's actual intent and is immune to that reflow.
//
//   wheelY   — accumulated wheel deltaY (down = +, up = −); drives hide/reveal
//   scrollTop — the active scroller's position; used only to keep the header
//               fully shown at the very top (clamp), where reflow is minimal
//
// One CAPTURE-phase listener pair on the shared tab-body container catches
// events from whichever tab's scroller is active (CodeView / Virtuoso).
// Wired via a CALLBACK ref because the tab-body mounts after the PR loads.

import { useCallback, useRef } from 'react';
import { useMotionValue, type MotionValue } from 'motion/react';

const MIN_SCROLLABLE = 40;

export interface HeaderScroll {
  scrollTop: MotionValue<number>;
  /** Accumulated wheel deltaY across the active scroller. */
  wheelY: MotionValue<number>;
  containerRef: (el: HTMLDivElement | null) => void;
  resync: () => void;
}

export function useHeaderScroll(): HeaderScroll {
  const scrollTop = useMotionValue(0);
  const wheelY = useMotionValue(0);
  const elRef = useRef<HTMLDivElement | null>(null);
  const cleanupRef = useRef<(() => void) | null>(null);

  const isMainScroller = (n: HTMLElement) =>
    typeof n.scrollTop === 'number' &&
    n.scrollHeight - n.clientHeight >= MIN_SCROLLABLE &&
    n.offsetParent !== null;

  const containerRef = useCallback(
    (el: HTMLDivElement | null) => {
      cleanupRef.current?.();
      cleanupRef.current = null;
      elRef.current = el;
      if (!el) return;

      const onScroll = (e: Event) => {
        const tgt = e.target as HTMLElement | null;
        if (!tgt || !isMainScroller(tgt)) return;
        scrollTop.set(tgt.scrollTop);
      };
      const onWheel = (e: WheelEvent) => {
        let dy = e.deltaY;
        if (e.deltaMode === 1) dy *= 16; // lines → ~px
        else if (e.deltaMode === 2) dy *= el.clientHeight; // pages → px
        wheelY.set(wheelY.get() + dy);
      };
      el.addEventListener('scroll', onScroll, { capture: true, passive: true });
      el.addEventListener('wheel', onWheel, { capture: true, passive: true });
      cleanupRef.current = () => {
        el.removeEventListener('scroll', onScroll, { capture: true });
        el.removeEventListener('wheel', onWheel, { capture: true });
      };
    },
    [scrollTop, wheelY],
  );

  const resync = useCallback(() => {
    const el = elRef.current;
    if (!el) return;
    const top = Array.from(el.querySelectorAll<HTMLElement>('*'))
      .filter(isMainScroller)
      .reduce((max, n) => Math.max(max, n.scrollTop), 0);
    scrollTop.set(top);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrollTop]);

  return { scrollTop, wheelY, containerRef, resync };
}
