// Floating "N references" chip, anchored to the clicked symbol. Matches the
// imported design spec: shadcn popover chrome, count · prev/next · go-to-def ·
// dismiss. Rendered into a body portal so the diff's overflow can't clip it.

import { createPortal } from 'react-dom';
import { ChevronDown, ChevronUp, Crosshair, Loader2, MousePointerClick, X } from 'lucide-react';
import { Kbd } from '@/ui/Kbd';

export interface ChipAnchor {
  left: number;
  top: number;
  bottom: number;
}

export interface SymbolChipProps {
  anchor: ChipAnchor;
  count: number; // total occurrences (incl. definition)
  hasDef: boolean;
  parsing?: boolean;
  onPrev: () => void;
  onNext: () => void;
  onGotoDef: () => void;
  onClose: () => void;
}

const btn =
  'inline-flex h-6 min-w-6 items-center justify-center gap-1.5 rounded-md px-1.5 ' +
  'text-popover-foreground/80 hover:bg-accent disabled:opacity-35 disabled:hover:bg-transparent';

export function SymbolChip(props: SymbolChipProps) {
  const { anchor, count, hasDef, parsing, onPrev, onNext, onGotoDef, onClose } = props;
  const otherUses = count - (hasDef ? 1 : 0);
  const flipBelow = anchor.top < 84;
  const top = flipBelow ? anchor.bottom + 8 : anchor.top - 40;
  const cycleDisabled = count < 2;

  const label =
    hasDef && otherUses === 0
      ? 'Definition · 0 references'
      : `${count} ${count === 1 ? 'reference' : 'references'}`;

  const divider = <span className="mx-0 my-1.5 w-px self-stretch bg-border" />;

  return createPortal(
    <div
      data-symbol-nav-ui=""
      className="fixed z-50 flex h-8 items-center rounded-lg border border-border bg-popover text-xs text-popover-foreground shadow-md animate-in fade-in-0 [animation-duration:150ms] transition-[top,left] [transition-duration:200ms] ease-out motion-reduce:transition-none motion-reduce:animate-none"
      style={{ left: Math.max(8, anchor.left), top }}
      role="toolbar"
      aria-label="Symbol occurrences"
      onMouseDown={(e) => e.preventDefault()}
    >
      {parsing ? (
        <span className="flex h-8 items-center gap-2 px-3 text-muted-foreground">
          <Loader2 className="size-3.5 animate-spin" /> Parsing symbols…
        </span>
      ) : (
        <>
          <span className="flex items-center px-2.5 font-medium whitespace-nowrap">
            {hasDef && otherUses === 0 ? (
              label
            ) : (
              <>
                <span className="text-[hsl(var(--pyor-link))]">{count}</span>
                &nbsp;{count === 1 ? 'reference' : 'references'}
              </>
            )}
          </span>
          {divider}
          <span className="flex items-center gap-0.5 px-1">
            <button className={btn} onClick={onPrev} disabled={cycleDisabled} title="Previous (⇧F3)">
              <ChevronUp className="size-3.5" />
            </button>
            <button className={btn} onClick={onNext} disabled={cycleDisabled} title="Next (F3)">
              <ChevronDown className="size-3.5" />
            </button>
          </span>
          {divider}
          <button
            className={`${btn} mx-1 px-2 font-medium`}
            onClick={onGotoDef}
            disabled={!hasDef}
            title="Go to definition (⌘-click)"
          >
            <Crosshair className="size-3.5" />
            <Kbd className="gap-1 px-1.5">
              ⌘
              <MousePointerClick className="size-3" />
            </Kbd>
          </button>
          {divider}
          <button className={`${btn} mx-1`} onClick={onClose} title="Dismiss (Esc)">
            <X className="size-3.5" />
          </button>
        </>
      )}
    </div>,
    document.body,
  );
}
