// Verification + freshness for the broker's signed entitlement token.
//
// Enforcement is soft by design (client-side app — ADR 0019/0020): the ES256
// signature makes the entitlement authoritative and tamper-evident against a
// malicious broker/network response, not unbreakable against local tampering.

import { compactVerify, importSPKI } from 'jose';
import { isMockBroker, type Entitlement } from '../auth/oauthBroker';

const PUBKEY = (
  import.meta.env.VITE_ENTITLEMENT_PUBKEY as string | undefined
)?.trim();

// Import the ES256 public key once. Env vars often flatten newlines, so restore
// real newlines before parsing the SPKI PEM ("BEGIN PUBLIC KEY").
let keyPromise: ReturnType<typeof importSPKI> | null = null;
function publicKey() {
  if (!keyPromise) {
    keyPromise = importSPKI((PUBKEY as string).replace(/\\n/g, '\n'), 'ES256');
  }
  return keyPromise;
}

/** Within the assertion's validity, or the offline-grace window. */
export function isEntitlementFresh(e: Entitlement): boolean {
  const now = Date.now();
  return now <= e.expiresAt || now <= e.graceUntil;
}

/** Stable, key-order-independent serialization for claim comparison. */
function canonical(v: unknown): string {
  return JSON.stringify(v, (_k, val) =>
    val && typeof val === 'object' && !Array.isArray(val)
      ? Object.fromEntries(Object.entries(val).sort(([a], [b]) => a.localeCompare(b)))
      : val,
  );
}

/**
 * Verify the signed entitlement JWT. THROWS on a bad signature or a
 * claims↔structured-fields mismatch — the caller (resolveEntitlement) treats a
 * throw as "don't trust this", falling back to the last-good cached entitlement.
 *
 * - Mock broker (local dev): nothing real to verify → accept.
 * - No public key configured: can't verify → accept, but warn loudly (in prod
 *   the key is required, so this signals a misconfig rather than a bypass).
 * - Otherwise: verify the ES256 signature of `e.signedToken`, then assert its
 *   claims equal the structured fields the client actually gates on (`plan`,
 *   `seats`, `seatsFull`) — a tampered response that keeps a valid old token but
 *   swaps the access set must not slip through.
 *
 * Uses `compactVerify` (signature only), NOT `jwtVerify`, on purpose: an
 * expired-but-within-grace token must still verify — temporal validity is owned
 * by `isEntitlementFresh` / the `graceUntil` window, not by this check.
 */
export async function verifyEntitlementToken(e: Entitlement): Promise<boolean> {
  if (isMockBroker) return true;
  if (!PUBKEY) {
    console.warn(
      'VITE_ENTITLEMENT_PUBKEY is not set — entitlement signature is NOT being verified.',
    );
    return true;
  }

  let claims: Record<string, unknown>;
  try {
    const { payload } = await compactVerify(e.signedToken, await publicKey());
    claims = JSON.parse(new TextDecoder().decode(payload)) as Record<string, unknown>;
  } catch {
    throw new Error('entitlement_signature_invalid');
  }

  const matches =
    claims.plan === e.plan &&
    canonical(claims.seats ?? []) === canonical(e.seats ?? []) &&
    canonical(claims.seatsFull ?? []) === canonical(e.seatsFull ?? []);
  if (!matches) throw new Error('entitlement_claims_mismatch');

  return true;
}
