// Global connectivity status for the persistent top strip + status dot.
//
// Tracks three things, in priority order:
//   1. offline       — the browser reports no network (navigator.onLine)
//   2. reconnecting   — just came back online; revalidating live queries
//   3. github-down    — online, but GitHub itself is erroring for us:
//                       the most recent settled queries failed with
//                       outage-class GitHubErrors (5xx / status 0 / fetch
//                       failure). Recovers the instant any query succeeds.
//
// The github-down read is deliberately conservative: a one-off 404 or a
// single blip must NOT flip the whole app to "GitHub is down". We only
// raise it when there's a recently-observed outage failure AND nothing
// has succeeded since — so a healthy poll clears it immediately.
//
// On top of that we *debounce* the raise: an outage failure must remain
// the most-recent settled event continuously for OUTAGE_CONFIRM_MS before
// the strip appears. A transient 5xx / fetch stutter clears well within
// that window the moment any query succeeds, so the banner never flickers
// on a single blip. Recovery is NOT debounced: any success hides it at
// once.

import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from 'react';
import { useQueryClient, type QueryClient } from '@tanstack/react-query';
import { GitHubError } from '../../github/client';

export type ConnStatus = 'healthy' | 'offline' | 'reconnecting' | 'github-down';

/** How long to show "Reconnecting…" after the browser reports online
 * again, while the live queries refetch. */
const RECONNECT_WINDOW_MS = 3000;

/** How long an outage-class failure must stay the most-recent settled
 * event before we flip the whole app to "GitHub is unavailable". A single
 * transient 5xx / status-0 / fetch blip clears inside this window as soon
 * as any query succeeds again, so the strip never flickers on a one-off
 * error. Recovery is immediate: this only delays *raising* the banner. */
const OUTAGE_CONFIRM_MS = 5000;

/** An error counts as a GitHub *outage* (not a user/permission problem)
 * when it's a server error or the request never reached a response.
 * 401/403/404 are explicitly NOT outages — they're handled at the
 * per-query failure surface (auth-expired / rate-limit / not-found). */
function isOutageError(err: unknown): boolean {
  if (err instanceof GitHubError) {
    return err.status >= 500 || err.status === 0;
  }
  // A bare fetch rejection (TypeError) while online → couldn't reach GitHub.
  if (err instanceof TypeError) return true;
  return false;
}

// --- online/offline: subscribe to the browser's network events ---------
// Module-level so the subscribe/getSnapshot identities stay stable across
// renders (a requirement of useSyncExternalStore).
function subscribeOnline(onChange: () => void): () => void {
  window.addEventListener('online', onChange);
  window.addEventListener('offline', onChange);
  return () => {
    window.removeEventListener('online', onChange);
    window.removeEventListener('offline', onChange);
  };
}
const getOnlineSnapshot = () => navigator.onLine;
const getOnlineServerSnapshot = () => true;

// --- GitHub-outage detection over the query cache ----------------------
// "Are we showing stale data because GitHub itself is erroring?" — true
// only when an outage-class failure is the most recent settled event and
// nothing has succeeded since. `lastSyncedMs` is the newest successful
// fetch across the whole cache.
type GithubSnapshot = { githubDown: boolean; lastSyncedMs: number };

function computeGithubSnapshot(qc: QueryClient): GithubSnapshot {
  let worstFailureAt = 0;
  let lastSuccessAt = 0;
  let sawOutage = false;
  qc.getQueryCache()
    .getAll()
    .forEach((q) => {
      const s = q.state;
      if (s.dataUpdatedAt > lastSuccessAt) lastSuccessAt = s.dataUpdatedAt;
      if (s.status !== 'error' || s.errorUpdatedAt === 0) return;
      if (!isOutageError(s.error)) return;
      sawOutage = true;
      if (s.errorUpdatedAt > worstFailureAt) worstFailureAt = s.errorUpdatedAt;
    });
  // Down only if an outage failure is the most recent thing that
  // happened — any later success clears it.
  return {
    githubDown: sawOutage && worstFailureAt > lastSuccessAt,
    lastSyncedMs: lastSuccessAt,
  };
}

export function useConnectivity(): {
  status: ConnStatus;
  /** Most recent successful fetch across the whole query cache, or null
   * if nothing has loaded yet. Drives the "Cached from [time]" / "Synced
   * [ago]" readout on the global status dot. */
  lastSyncedAt: Date | null;
  retry: () => void;
} {
  const qc = useQueryClient();

  // Online/offline and GitHub-outage state are both *external* stores
  // (browser network events / the React Query cache). Reading them via
  // useSyncExternalStore lets React schedule the updates safely — the old
  // `cache.subscribe(setState)` fired synchronously while unrelated
  // components were rendering, producing "Cannot update a component while
  // rendering a different component" warnings across the whole tree.
  const online = useSyncExternalStore(
    subscribeOnline,
    getOnlineSnapshot,
    getOnlineServerSnapshot,
  );

  // Cache the computed snapshot so getSnapshot returns a stable reference
  // when nothing changed (required to avoid an infinite render loop).
  const githubSnapshot = useRef<GithubSnapshot>({
    githubDown: false,
    lastSyncedMs: 0,
  });
  const getGithubSnapshot = useCallback(() => {
    const next = computeGithubSnapshot(qc);
    const prev = githubSnapshot.current;
    if (prev.githubDown === next.githubDown && prev.lastSyncedMs === next.lastSyncedMs) {
      return prev;
    }
    githubSnapshot.current = next;
    return next;
  }, [qc]);
  const subscribeGithub = useCallback(
    (onChange: () => void) => qc.getQueryCache().subscribe(onChange),
    [qc],
  );
  const { githubDown, lastSyncedMs } = useSyncExternalStore(
    subscribeGithub,
    getGithubSnapshot,
  );

  // Debounce the raw outage signal: commit to "github-down" only once an
  // outage failure has been the most-recent settled event continuously for
  // OUTAGE_CONFIRM_MS. Any success in the meantime drops `githubDown` back
  // to false, which clears the pending timer and aborts the flip, so a
  // single transient blip never reaches the banner. The cache subscription
  // above keeps re-firing while an outage persists, so a passive failure
  // still resolves once the window elapses.
  const [outageConfirmed, setOutageConfirmed] = useState(false);
  useEffect(() => {
    if (!githubDown) {
      setOutageConfirmed(false);
      return;
    }
    const timer = setTimeout(() => setOutageConfirmed(true), OUTAGE_CONFIRM_MS);
    return () => clearTimeout(timer);
  }, [githubDown]);

  // Reconnect window: when the browser comes back online, show
  // "Reconnecting…" briefly and kick the live feeds. These setStates only
  // ever run from event handlers / timeouts, never during render.
  const [reconnecting, setReconnecting] = useState(false);
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | null = null;
    const onOnline = () => {
      setReconnecting(true);
      // Kick the live feeds so the user sees fresh data immediately
      // instead of waiting for the next poll tick.
      void qc.invalidateQueries({ queryKey: ['inbox'] });
      void qc.invalidateQueries({ queryKey: ['notifications'] });
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => setReconnecting(false), RECONNECT_WINDOW_MS);
    };
    const onOffline = () => {
      setReconnecting(false);
      if (timer) clearTimeout(timer);
    };
    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);
    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
      if (timer) clearTimeout(timer);
    };
  }, [qc]);

  const status: ConnStatus = !online
    ? 'offline'
    : reconnecting
      ? 'reconnecting'
      : outageConfirmed
        ? 'github-down'
        : 'healthy';

  return {
    status,
    lastSyncedAt: lastSyncedMs > 0 ? new Date(lastSyncedMs) : null,
    retry: () => void qc.invalidateQueries(),
  };
}
