// First-run discovery coachmark. Appears once, anchored to the first identifier
// the user hovers; dismissal is persisted. Subtle — no full-screen onboarding.

import { createPortal } from 'react-dom';
import { MousePointerClick } from 'lucide-react';
import { Kbd } from '@/ui/Kbd';
import type { ChipAnchor } from './SymbolChip';

export interface SymbolCoachProps {
  anchor: ChipAnchor;
  onDismiss: () => void;
}

export function SymbolCoach({ anchor, onDismiss }: SymbolCoachProps) {
  const top = anchor.bottom + 8;
  return createPortal(
    <div
      data-symbol-nav-ui=""
      className="fixed z-50 w-[280px] rounded-xl border border-border bg-popover p-3.5 text-popover-foreground shadow-lg"
      style={{ left: Math.max(8, anchor.left), top }}
      role="dialog"
      aria-label="Symbol navigation tip"
    >
      <div className="flex items-center gap-2 text-[13px] font-semibold">
        <span className="inline-flex size-[18px] items-center justify-center rounded-md bg-[hsl(var(--pyor-link)/0.14)] text-[hsl(var(--pyor-link))]">
          <MousePointerClick className="size-3" />
        </span>
        Symbol navigation
      </div>
      <p className="mt-1.5 mb-2.5 text-[12.5px] leading-relaxed text-muted-foreground">
        Click any symbol to see everywhere it’s used — and ⌘-click to jump to where
        it’s defined. Press <Kbd>o</Kbd> for the file outline.
      </p>
      <div className="flex items-center justify-end">
        <button
          className="rounded-md bg-[hsl(var(--pyor-link))] px-3 py-1.5 text-xs font-semibold text-white"
          onClick={onDismiss}
        >
          Got it
        </button>
      </div>
    </div>,
    document.body,
  );
}
