// Sync localStorage cache of the last-good entitlement (ADR 0019).
//
// Kept sync (mirrors tokenStore) so plan/paywall checks never block, and so
// the offline-grace window can be honored on a cold launch with no network.

import type { Entitlement } from '../auth/oauthBroker';

const KEY = 'pyor:entitlement';

export function setCachedEntitlement(e: Entitlement): void {
  try {
    localStorage.setItem(KEY, JSON.stringify(e));
  } catch {
    // Non-fatal: entitlement re-resolves on next online launch.
  }
}

export function readCachedEntitlement(): Entitlement | null {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return null;
    const e = JSON.parse(raw) as Entitlement;
    // A cache written before the per-org seat arrays existed (ADR 0020) lacks
    // `seats` / `seatsFull`. Normalize so every consumer can rely on them being
    // arrays — otherwise the first paywall check (`ent.seats.find`) crashes the
    // Settings page on the first post-upgrade load.
    return { ...e, seats: e.seats ?? [], seatsFull: e.seatsFull ?? [] };
  } catch {
    return null;
  }
}

function clearEntitlement(): void {
  try {
    localStorage.removeItem(KEY);
  } catch {
    // No-op.
  }
}
