// Chrome + helpers for the bespoke AI-grouped rail (AiGroupedRail): the
// scroll-body wrapper and the run-meta footer (varies by state), plus two
// small pure helpers. Split out to keep AiGroupedRail focused on the grouped
// body itself.

import { AiButton, AiCostMeter, AiMark, AiMarkTile, AiProgress, type AiRunStateKind } from '../aikit';
import type { UseAiGrouping } from './useAiGrouping';

/** Idle: the "Group with AI" run CTA card. */
export function IdleCta({
  fileCount,
  estimate,
  onRun,
}: {
  fileCount: number;
  estimate: UseAiGrouping['estimate'];
  onRun: () => void;
}) {
  return (
    <div className="ai-sweep rounded-lg border border-violet-200 bg-violet-50/70 p-3 dark:border-violet-500/30 dark:bg-violet-500/[0.08]">
      <div className="flex items-center gap-2">
        <AiMarkTile size="size-7" />
        <div className="min-w-0">
          <div className="text-[12.5px] font-semibold text-violet-800 dark:text-violet-200">Group with AI</div>
          <div className="text-[11px] text-violet-700/80 dark:text-violet-300/80">Cluster review-worthy files vs. noise</div>
        </div>
      </div>
      <p className="mt-2 text-[11.5px] leading-relaxed text-muted-foreground">
        Sends this PR's diff to your provider to sort {fileCount} changed files into what needs a close read vs.
        generated, renamed, and formatting-only files.
      </p>
      <div className="mt-2.5 flex items-center justify-between gap-2">
        <AiButton variant="solid" size="sm" mark onClick={onRun}>Run</AiButton>
        {estimate && <AiCostMeter mode="estimate" tokens={estimate.tokens} cost={estimate.cost} />}
      </div>
    </div>
  );
}

/** Loading: per-file progress + shimmer skeleton group rows. */
export function LoadingBody({
  capped,
  fileCount,
  onCancel,
}: {
  capped: UseAiGrouping['capped'];
  fileCount: number;
  onCancel: () => void;
}) {
  return (
    <div className="p-3">
      <div className="mb-3 rounded-md border border-violet-200 bg-violet-50/60 p-2.5 dark:border-violet-500/30 dark:bg-violet-500/[0.08]">
        <AiProgress label="Grouping" total={capped?.analyzed ?? fileCount} capped={capped} onCancel={onCancel} />
      </div>
      {[0, 1, 2].map((i) => (
        <div key={i} className="mb-3">
          <div className="ai-sweep flex items-center gap-1.5">
            <div className="size-3.5 rounded bg-muted" />
            <div className="h-2.5 rounded bg-muted" style={{ width: `${60 - i * 12}%` }} />
          </div>
          <div className="ai-sweep mt-1 h-2 rounded bg-muted/70" style={{ width: '80%' }} />
        </div>
      ))}
    </div>
  );
}

export function ago(ts: number | null): string {
  if (!ts) return '';
  const s = Math.round((Date.now() - ts) / 1000);
  if (s < 60) return 'just now';
  const m = Math.round(s / 60);
  if (m < 60) return `${m}m ago`;
  return `${Math.round(m / 60)}h ago`;
}

export function errorRunKind(k: UseAiGrouping['errorKind']): AiRunStateKind {
  if (k === 'invalid-key') return 'invalid-key';
  if (k === 'billing') return 'billing';
  if (k === 'rate-limited') return 'rate-limited';
  if (k === 'network') return 'network';
  return 'overloaded';
}

export function AiRailFooter({
  status,
  fileCount,
  ranAt,
  cost,
}: {
  status: UseAiGrouping['status'];
  fileCount: number;
  ranAt: number | null;
  cost: UseAiGrouping['cost'];
}) {
  const cls = 'flex items-center gap-1.5 border-t border-border px-3 py-2 text-[11px] text-muted-foreground';
  if (status === 'idle' || status === 'locked') {
    return <div className={cls}><span>{fileCount} files</span></div>;
  }
  if (status === 'loading') {
    return <div className={cls}><AiMark className="size-3 text-violet-400 ai-pulse" /><span>Working…</span></div>;
  }
  if (status === 'error' || status === 'empty') {
    return (
      <div className={cls}>
        <AiMark className="size-3 text-violet-400" />
        <span>{status === 'empty' ? 'Nothing to cluster' : 'Run didn’t finish'}</span>
      </div>
    );
  }
  return (
    <div className={cls}>
      <AiMark className="size-3 text-violet-500" />
      <span>Grouped by AI</span>
      <span className="text-muted-foreground/60">·</span>
      <span>{status === 'stale' ? 'stale' : ago(ranAt)}</span>
      {cost && <AiCostMeter mode="actual" tokens={cost.tokens} cost={cost.cost} secs={cost.secs} className="ml-auto" />}
    </div>
  );
}
