// Root app host. Mounts the real client-side router (TanStack Router,
// hash history — see src/router/router.tsx) inside the global
// providers. The route tree + the persistent shell live in
// src/router + src/ui/Shell; this file is now just provider wiring +
// the boot-time legacy-route migration.
//
// Migrated from the hand-rolled `routeStore` + `App.tsx` state machine
// in AFK plan 26: the URL is now the single source of truth for
// screen + view-state.

import { useEffect } from 'react';
import { RouterProvider } from '@tanstack/react-router';
// Side-effect import: loading the theme store applies the `pyor-dark`
// body class at module load, before any consumer (Shell, Settings) mounts.
import './theme/ThemeProvider';
import { Toaster } from '@/components/ui/sonner';
import { triggerPlanToast } from './components/PlanToast';
import { queryClient } from './lib/queryClient';
import { fetchUserInstallations, toAppInstallations } from './github/client';
import { CommandPaletteHost } from './ui/CommandPalette';
import { ConfirmHost } from './components/confirm';
import { AssetsConsentHost } from './pr/conversation/composer/AssetsConsentProvider';
import { useDesktopUpdates } from './desktop/useDesktopUpdates';
import { router } from './router/router';
import { TrialReminder } from './billing/TrialReminder';
import { PatIdentityReporter } from './auth/PatIdentityReporter';
import { ObservabilityProvider } from './observability/ObservabilityProvider';

// The one-time boot migration of the pre-router `pyor:route`
// localStorage blob is handled inside the index route's `beforeLoad`
// (see src/router/router.tsx → legacyRouteTarget) so the router itself
// performs the redirect — keeping the hash + history in sync.

// Resolve a freshly-installed installation id → its org login for the
// post-install toast. Only orgs are named (a personal account is always free,
// so the "needs a plan" copy stays generic for it). Any failure (PAT token,
// network) falls back to undefined → the generic toast. Shares the
// ['installations'] cache with the Settings → Organizations section.
async function resolveInstalledOrgLogin(
  installationId: number,
): Promise<string | undefined> {
  try {
    const page = await queryClient.fetchQuery({
      queryKey: ['installations'],
      queryFn: fetchUserInstallations,
    });
    const match = toAppInstallations(page).find((i) => i.id === installationId);
    return match?.account.type === 'Organization'
      ? match.account.login
      : undefined;
  } catch {
    return undefined;
  }
}

export function App() {
  // Wire the Electron update events to toasts (ADR 0023). No-op on web.
  useDesktopUpdates();

  // Post-install nudge (ADR 0020 #7). The install redirect-back flags this with
  // the installation id; a freshly-installed org has no plan and is hidden
  // everywhere, so we surface the one thread that pulls a confused user to the
  // Settings explainer — naming the org when we can resolve it.
  useEffect(() => {
    let raw: string | null = null;
    try {
      raw = sessionStorage.getItem('pyor:post-install');
      if (raw) sessionStorage.removeItem('pyor:post-install');
    } catch {
      /* storage disabled — nothing to show. */
    }
    if (!raw) return;

    const open = () => void router.navigate({ to: '/settings' });
    const installId = Number(raw);
    // Legacy '1' sentinel / no id → fire the generic toast immediately.
    if (!Number.isFinite(installId) || installId <= 1) {
      triggerPlanToast({ onOpenSettings: open });
      return;
    }
    // Resolve the installed org's login so the toast can name it.
    void resolveInstalledOrgLogin(installId).then((orgLogin) =>
      triggerPlanToast({ orgLogin, onOpenSettings: open }),
    );
  }, []);

  return (
    <>
      <RouterProvider router={router} />
      {/* Late-trial reminder (ADR 0020) — fires a quiet toast when a seated
       * org's trial is ≤3 days out. Renders nothing itself. */}
      <TrialReminder />
      {/* Records a PAT user's unverified identity once per session (never
       * the token). Renders nothing. */}
      <PatIdentityReporter />
      {/* ADR 0021: syncs viewer + entitlement into PostHog (person + org
       * groups) and Sentry (user). Renders nothing. */}
      <ObservabilityProvider />
      {/* ⌘K command palette. Screens register commands via
       * `useRegisterCommand` (zustand-backed); this host mounts the dialog
       * and binds the global shortcut. */}
      <CommandPaletteHost />
      {/* One-time public-assets upload consent. Composers call
       * `useAssetsConsent().requestConsent()` (zustand-backed); this host
       * mounts the disclosure dialog. */}
      <AssetsConsentHost />
      {/* Global confirm dialog. Code anywhere calls `confirm(...)` /
       * `useConfirm()` from components/confirm (zustand-backed); this
       * host mounts the actual modal. */}
      <ConfirmHost />
      {/* Global toast surface. Components anywhere in the tree call
       * `toast(...)` from sonner — the Toaster mounts the actual
       * portal that displays them. */}
      <Toaster richColors closeButton position="bottom-right" />
    </>
  );
}
