// Empty state shown when a list (lens / comments dashboard) is empty *because*
// every org the viewer can see is blocked (ADR 0020, Copy doc #7) — e.g. a free
// user invited only to unpaid orgs. Names the free personal path first so it
// never reads as "you did something wrong". Only rendered when there's actually
// ≥1 blocked org, so it doesn't replace the genuine "no PRs" empty state.

import { Building2 } from 'lucide-react';
import { useNavigate } from '@tanstack/react-router';
import { Button } from '@/components/ui/button';
import { EmptyState } from '../ui/EmptyState';

export function GatedListEmptyState() {
  const navigate = useNavigate();
  return (
    <EmptyState
      icon={Building2}
      title="Your organizations need a plan to appear here"
      body="Pyor is free for your personal repositories. Organizations show their pull requests once they have a plan — ask an admin, or set one up if you own the org."
      action={
        <Button variant="outline" size="sm" onClick={() => void navigate({ to: '/settings' })}>
          Manage organizations
        </Button>
      }
    />
  );
}
