// Dev-only observability for the PR-detail query graph (ADR 0005 poll +
// ADR 0019 invalidation). Subscribes to the TanStack query cache and
// logs every fetch / success / invalidate for the focused PR's queries,
// with a one-line signal per query (head.sha, comment count, contents
// size, …) so you can SEE whether the 15s meta tick is firing, whether
// it lands a fresh SHA, and which downstream queries it cascades into.
//
// No-op in production. Enable noise control with `localStorage.setItem(
// 'pyor:pollDebug','0')` to silence, or it's on by default in dev.

import { useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import type { Query } from '@tanstack/react-query';

/** Short, human-readable signal for a PR sub-query's current data, so a
 * log line tells you not just THAT it refetched but whether anything
 * actually changed. */
function signalFor(sub: string, query: Query): string {
  const data = query.state.data as unknown;
  if (data == null) return '∅';
  if (sub === 'meta') {
    const d = data as { head?: { sha?: string }; updated_at?: string };
    return `head=${d.head?.sha?.slice(0, 7) ?? '?'} updated_at=${d.updated_at ?? '?'}`;
  }
  if (sub === 'pendingReview') {
    const d = data as { comments?: unknown[] } | null;
    return d ? `${d.comments?.length ?? 0} pending` : 'none';
  }
  if (data instanceof Map) return `${data.size} files`;
  if (Array.isArray(data)) return `${data.length} items`;
  return 'data';
}

export function usePrPollDebug(
  owner: string,
  repo: string,
  number: number,
): void {
  const qc = useQueryClient();
  useEffect(() => {
    if (!import.meta.env.DEV) return;
    if (localStorage.getItem('pyor:pollDebug') === '0') return;
    const cache = qc.getQueryCache();
    const unsub = cache.subscribe((event) => {
      if (event.type !== 'updated') return;
      const key = event.query.queryKey;
      // Only this PR's queries: ['pr', owner, repo, number, <sub>, …].
      if (
        !Array.isArray(key) ||
        key[0] !== 'pr' ||
        key[1] !== owner ||
        key[2] !== repo ||
        key[3] !== number
      ) {
        return;
      }
      const sub = String(key[4] ?? '?');
      const action = event.action.type;
      if (action === 'fetch') {
        // eslint-disable-next-line no-console
        console.debug(`%c[pr-poll] ↻ fetch  ${sub}`, 'color:#888');
      } else if (action === 'success') {
        // eslint-disable-next-line no-console
        console.debug(
          `%c[pr-poll] ✓ ${sub}%c  ${signalFor(sub, event.query)}`,
          'color:#6b9bd1;font-weight:600',
          'color:inherit',
        );
      } else if (action === 'invalidate') {
        // eslint-disable-next-line no-console
        console.debug(`%c[pr-poll] ✗ invalidate  ${sub}`, 'color:#c08a3e');
      } else if (action === 'error') {
        // eslint-disable-next-line no-console
        console.debug(`%c[pr-poll] ⚠ error  ${sub}`, 'color:#c0564a');
      }
    });
    return unsub;
  }, [qc, owner, repo, number]);
}
