// Assembles the CodeMirror 6 extension set for the GhComposer editor.
// Built once per composer instance (the React component memoises it) and
// reads its callbacks through refs/getters so the editor never needs
// reconfiguring as props change.
//
// shadcn-strict (ADR 0011): the editor chrome + markdown token colors are
// driven entirely by the app's CSS variables (the same approach
// @pierre/diffs uses for its host element) — no token imports, no static
// color literals.

import { type MutableRefObject } from 'react';
import { type Extension } from '@codemirror/state';
import {
  EditorView,
  keymap,
  placeholder as cmPlaceholder,
  tooltips,
} from '@codemirror/view';
import { history, historyKeymap, defaultKeymap } from '@codemirror/commands';
import { markdown, markdownLanguage, markdownKeymap } from '@codemirror/lang-markdown';
import { HighlightStyle, syntaxHighlighting } from '@codemirror/language';
import { autocompletion, completionKeymap, startCompletion } from '@codemirror/autocomplete';
import { tags } from '@lezer/highlight';
import { buildCompletionSources } from './completions';
import { wrapSelection, insertLinePrefix } from './formatCommands';
import { imageFilesFromDataTransfer, insertImageUploads } from './imageUpload';
import type { MentionContext } from './types';

/** Markdown token styling. Markers (`#`, `**`, fences) read muted; the
 * styled spans (headings, emphasis, links) carry weight/colour so the
 * source is scannable without leaving raw-markdown mode. */
const pyorHighlight = HighlightStyle.define([
  { tag: tags.heading, color: 'var(--foreground)', fontWeight: '600' },
  { tag: tags.strong, fontWeight: '700' },
  { tag: tags.emphasis, fontStyle: 'italic' },
  { tag: tags.strikethrough, textDecoration: 'line-through' },
  { tag: tags.link, color: 'var(--primary)' },
  { tag: tags.url, color: 'var(--primary)', textDecoration: 'underline' },
  { tag: tags.monospace, color: 'var(--muted-foreground)' },
  { tag: tags.quote, color: 'var(--muted-foreground)', fontStyle: 'italic' },
  {
    tag: [tags.processingInstruction, tags.meta, tags.list, tags.contentSeparator],
    color: 'var(--muted-foreground)',
  },
]);

/** Editor chrome. Transparent background (the surrounding card paints it),
 * sans-serif body matching the rendered comment, popover styling for the
 * autocomplete tooltip — all via CSS variables. */
// The app's color tokens are HSL triples (e.g. `--foreground: 0 0% 9%`),
// so they must be wrapped in `hsl(...)` — a bare `var(--foreground)` is an
// invalid color and silently falls back. (`--font-mono` is a real font
// stack, used directly.) The autocomplete-popover styling lives in
// tailwind.css instead: the popover is parented to <body>, and this theme
// doesn't apply at all when the composer mounts inside the @pierre/diffs
// CodeView, so a global rule is the reliable home for it.
const pyorTheme = EditorView.theme({
  '&': { backgroundColor: 'transparent', color: 'hsl(var(--foreground))', fontSize: '12.5px' },
  '&.cm-focused': { outline: 'none' },
  '.cm-scroller': {
    fontFamily: 'var(--font-sans)',
    lineHeight: '1.6',
  },
  '.cm-content': { padding: '12px', caretColor: 'hsl(var(--foreground))' },
  '.cm-cursor, .cm-dropCursor': { borderLeftColor: 'hsl(var(--foreground))' },
  '.cm-placeholder': { color: 'hsl(var(--muted-foreground))' },
  '&.cm-focused .cm-selectionBackground, .cm-selectionBackground, .cm-content ::selection':
    { backgroundColor: 'hsl(var(--accent))' },
}, { dark: false });

export interface ComposerExtensionOpts {
  /** Called on ⌘⏎. Reads `.current` so it always sees the latest closure. */
  submitRef: MutableRefObject<() => void>;
  /** Called on Esc when a cancel affordance exists. */
  cancelRef: MutableRefObject<(() => void) | undefined>;
  /** Called on ⌘P to flip Write↔Preview. */
  togglePreviewRef: MutableRefObject<() => void>;
  /** Injected upload strategy; absent → image paste/drop is a no-op. */
  uploadRef: MutableRefObject<((file: File) => Promise<string>) | undefined>;
  /** Lazy repo coordinates for `@`/`#` autocomplete. */
  getMentionContext: () => MentionContext | undefined;
  /** Lazy seed text for `/suggestion` — the commented diff line(s), so
   * the suggestion block pre-fills GitHub-style. Returns undefined on
   * surfaces with no line context (the block inserts empty). */
  getSuggestionSeed: () => string | undefined;
  /** Tag the content DOM with `data-pyor-thread-compose` for the Changes
   * tab's `R`-to-reply keymap. */
  threadCompose: boolean;
  placeholderText: string;
  /** Minimum height (px) of the editable area. Applied to `.cm-content`
   * so the whole typing surface is multi-line + clickable, not just the
   * one line @uiw's `minHeight` (which only sizes the editor root) gives. */
  minHeight: number;
}

export function buildComposerExtensions(opts: ComposerExtensionOpts): Extension[] {
  const {
    submitRef,
    cancelRef,
    togglePreviewRef,
    uploadRef,
    getMentionContext,
    getSuggestionSeed,
    threadCompose,
    placeholderText,
    minHeight,
  } = opts;

  // Format shortcuts mirror the toolbar's kbd hints. Each returns true so
  // CM calls preventDefault — but, like the old textarea, does NOT
  // stopPropagation, so ChangesTab's window-level ⌘⏎ stays unchanged.
  const formatKeymap = keymap.of([
    { key: 'Mod-b', run: (v) => (wrapSelection(v, '**', '**', 'bold text'), true) },
    { key: 'Mod-i', run: (v) => (wrapSelection(v, '_', '_', 'italic text'), true) },
    { key: 'Mod-e', run: (v) => (wrapSelection(v, '`', '`', 'code'), true) },
    { key: 'Mod-k', run: (v) => (wrapSelection(v, '[', '](url)', 'text'), true) },
    { key: 'Mod-Shift-7', run: (v) => (insertLinePrefix(v, '1. '), true) },
    { key: 'Mod-Shift-8', run: (v) => (insertLinePrefix(v, '- '), true) },
    { key: 'Mod-Shift-.', run: (v) => (insertLinePrefix(v, '> '), true) },
    { key: 'Mod-Enter', preventDefault: true, run: () => (submitRef.current(), true) },
    {
      key: 'Mod-p',
      preventDefault: true,
      run: () => (togglePreviewRef.current(), true),
    },
    {
      key: 'Escape',
      run: () => {
        const cancel = cancelRef.current;
        if (!cancel) return false;
        cancel();
        return true;
      },
    },
  ]);

  const uploadHandlers = EditorView.domEventHandlers({
    paste(event, view) {
      const upload = uploadRef.current;
      if (!upload) return false;
      const files = imageFilesFromDataTransfer(event.clipboardData);
      if (files.length === 0) return false;
      event.preventDefault();
      insertImageUploads(view, files, upload);
      return true;
    },
    drop(event, view) {
      const upload = uploadRef.current;
      if (!upload) return false;
      const files = imageFilesFromDataTransfer(event.dataTransfer);
      if (files.length === 0) return false;
      event.preventDefault();
      const pos = view.posAtCoords({ x: event.clientX, y: event.clientY });
      if (pos != null) view.dispatch({ selection: { anchor: pos } });
      insertImageUploads(view, files, upload);
      return true;
    },
  });

  return [
    history(),
    EditorView.lineWrapping,
    // The editable area itself is at least `minHeight` tall (and so the
    // whole box is clickable + visibly multi-line); @uiw only sizes the
    // editor root, leaving an empty one-line content area.
    EditorView.theme({ '.cm-content': { minHeight: `${minHeight}px` } }),
    // Render tooltips (the autocomplete popovers) under document.body so
    // they aren't clipped by the composer's overflow-hidden wrappers.
    tooltips({ parent: document.body }),
    markdown({ base: markdownLanguage }),
    syntaxHighlighting(pyorHighlight),
    cmPlaceholder(placeholderText),
    autocompletion({
      override: buildCompletionSources(getMentionContext, getSuggestionSeed),
      icons: false,
      defaultKeymap: true,
      activateOnTyping: true,
    }),
    uploadHandlers,
    // Order matters: completionKeymap (Esc closes an open popover, Enter
    // accepts) sits ahead of our Esc→cancel + Enter handling so the
    // popover wins while it's open. markdownKeymap continues lists on
    // Enter; our format keys come before defaultKeymap.
    keymap.of(completionKeymap),
    formatKeymap,
    keymap.of(markdownKeymap),
    keymap.of([...historyKeymap, ...defaultKeymap]),
    pyorTheme,
    threadCompose
      ? EditorView.contentAttributes.of({ 'data-pyor-thread-compose': '' })
      : [],
  ];
}

/** Re-export so the toolbar's mention/reference/emoji/slash buttons can
 * open the popover after inserting their trigger char. */
export { startCompletion };
