import { cn } from '@/lib/utils';

/**
 * Additions/deletions diff stat (`+1,234 −5,678`).
 *
 * Centralizes the thousands-separator formatting and the green/red signed
 * spans shared across the PR list, commit rows, toolbars, and local review.
 * Colors default to emerald/destructive; override via `addClassName` /
 * `delClassName` to match a surface that uses different tokens.
 */
export function DiffStat({
  additions,
  deletions,
  layout = 'inline',
  className,
  addClassName,
  delClassName,
}: {
  additions: number;
  deletions: number;
  layout?: 'inline' | 'stacked';
  className?: string;
  addClassName?: string;
  delClassName?: string;
}) {
  return (
    <span
      className={cn(
        'font-mono tabular-nums',
        layout === 'stacked'
          ? 'flex flex-col items-end'
          : 'inline-flex items-baseline gap-1.5',
        className,
      )}
    >
      <span className={cn('text-emerald-600', addClassName)}>
        +{additions.toLocaleString()}
      </span>
      <span className={cn('text-destructive', delClassName)}>
        −{deletions.toLocaleString()}
      </span>
    </span>
  );
}
