// Reviewer picker popover (#18). Searches the repo's collaborators and
// requests a review from the chosen person. Wraps an arbitrary trigger
// (the "+ Add reviewer" chip). shadcn Command + Popover (ADR 0011).

import { useState, type ReactNode } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { listRepoCollaborators } from '../../github/client';

export function ReviewerPicker({
  owner,
  repo,
  excludeLogins,
  onPick,
  children,
}: {
  owner: string;
  repo: string;
  /** Logins already requested / reviewing — filtered out of the list. */
  excludeLogins: string[];
  onPick: (login: string) => void;
  children: ReactNode;
}) {
  const [open, setOpen] = useState(false);

  const collaborators = useQuery({
    queryKey: ['repo', owner, repo, 'collaborators'],
    queryFn: () => listRepoCollaborators(owner, repo),
    enabled: open,
    staleTime: 5 * 60 * 1000,
  });

  const exclude = new Set(excludeLogins);
  const candidates = (collaborators.data ?? []).filter(
    (c) => !exclude.has(c.login),
  );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>{children}</PopoverTrigger>
      <PopoverContent align="start" className="w-[320px] p-0">
        <Command>
          <CommandInput placeholder="Add reviewer…" />
          <CommandList>
            <CommandEmpty>
              {collaborators.isLoading ? 'Loading…' : 'No people found.'}
            </CommandEmpty>
            <CommandGroup heading="People">
              {candidates.map((c) => (
                <CommandItem
                  key={c.login}
                  value={c.login}
                  onSelect={() => {
                    onPick(c.login);
                    setOpen(false);
                  }}
                  className="gap-2"
                >
                  <Avatar className="size-6">
                    <AvatarImage src={c.avatar_url} alt={c.login} />
                    <AvatarFallback className="text-[9px]">
                      {c.login.slice(0, 2).toUpperCase()}
                    </AvatarFallback>
                  </Avatar>
                  <span className="truncate text-[12.5px] font-medium">
                    {c.login}
                  </span>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
