// Reports a PAT user's self-asserted identity to the backend once per session
// (ADR 0019/0020) — covers both a fresh /setup sign-in and a returning PAT
// session (stored token, skips /setup). GitHub-App sessions are verified through
// the OAuth exchange and never go through here. Renders nothing; mounted once in
// App, inside the providers.
//
// We read the viewer from the shared ['viewer'] query (its login/id/email come
// from GET /user with the stored PAT) and post {githubUserId, login, email} —
// never the token. Guarded by sessionStorage so it fires at most once per
// session per user.

import { useEffect, useRef } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getCredential } from './tokenStore';
import { getViewer } from '../github/client';
import { selfAssertIdentity } from './selfAssertIdentity';

export function PatIdentityReporter() {
  const isPat = getCredential()?.method === 'pat';
  const viewer = useQuery({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    enabled: isPat,
    staleTime: 5 * 60_000,
  });
  const sent = useRef(false);

  useEffect(() => {
    if (!isPat || sent.current || !viewer.data) return;
    const key = `pyor:pat-identity:${viewer.data.id}`;
    try {
      if (sessionStorage.getItem(key) === '1') {
        sent.current = true;
        return;
      }
      sessionStorage.setItem(key, '1');
    } catch {
      /* storage disabled — still report (once per mount via the ref). */
    }
    sent.current = true;
    selfAssertIdentity({
      githubUserId: viewer.data.id,
      login: viewer.data.login,
      email: viewer.data.email,
    });
  }, [isPat, viewer.data]);

  return null;
}
