// Commits tab — rich, GitHub-grade commit list (designer redesign).
//
// Commits are date-grouped on a vertical timeline rail whose node IS the
// per-commit CI status dot (pass / fail / pending / none). Each row
// carries the author avatar + committed-by line, a Verified badge, a
// merge tag, a copyable short-SHA pill, a files-changed count, and a
// proportional +/- diffstat bar. Clicking a row expands a detail panel
// (full description, CI + Details, GPG line, files/diffstat, merge
// parents, full SHA, and Browse-files / View-diff / View-on-GitHub
// actions). A sub-toolbar shows branch context, verified/failing counts,
// a working author filter, and Expand-all / Collapse-all.
//
// Data comes from `getPullRequestCommitsWithStats` (one GraphQL query),
// shared with the Changes-tab commits range-picker.

import { useEffect, useMemo, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  CheckCircle2Icon,
  CheckIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  CircleDashedIcon,
  CircleDotIcon,
  Code2Icon,
  CopyIcon,
  FileIcon,
  FilterIcon,
  GitBranchIcon,
  GitCommitIcon,
  GitCompareIcon,
  GitMergeIcon,
  Loader2,
  ShieldCheckIcon,
  UsersIcon,
  XCircleIcon,
  XIcon,
} from 'lucide-react';
import { PRErrorPane } from './PRErrorPane';
import {
  GitHubError,
  type CommitCheckState,
  type PRCommitWithStats,
} from '../github/client';
import { prCommitsStatsOptions } from '../github/prQueries';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Collapse, CollapseChevron } from '@/components/ui/collapse';
import { CopyIconMorph } from '@/components/ui/copy-icon';
import { FetchingBar } from '@/components/ui/fetching-bar';
import { Separator } from '@/components/ui/separator';
import { GithubMark } from '../ui/GithubMark';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { cn } from '@/lib/utils';
import { fullDate, relTime } from '../util/relTime';

interface CommitsTabProps {
  owner?: string;
  repo?: string;
  number?: number;
  /** Total commits + branch — surfaced in the sub-toolbar + loading
   * header. Both optional. */
  commitCount?: number;
  branch?: string;
  /** Fired by a row's "View diff" action — the parent scopes the
   * Files-changed diff to this single commit. */
  onSelectCommit?: (sha: string) => void;
  /** Persisted scroll position to restore on mount (per-PR localStorage,
   * owned by PRDetailScreen). This list isn't virtualized, so the value
   * is the container's `scrollTop` in px — the parent treats it as an
   * opaque number. */
  initialScrollIndex?: number;
  /** Fires (debounced) with the container's scrollTop so the caller can
   * persist it per PR. */
  onScrollIndexChange?: (index: number) => void;
}

// ── CI status meta — the rail node + the expanded-panel icon ──────────
type CIBucket = 'pass' | 'fail' | 'pending' | 'none';
function ciBucket(state: CommitCheckState): CIBucket {
  switch (state) {
    case 'SUCCESS':
      return 'pass';
    case 'FAILURE':
    case 'ERROR':
      return 'fail';
    case 'PENDING':
    case 'EXPECTED':
      return 'pending';
    default:
      return 'none';
  }
}
const CI_META: Record<
  CIBucket,
  {
    dot: string;
    ring: string;
    Icon: typeof CheckCircle2Icon;
    tone: string;
    label: string;
  }
> = {
  pass: {
    dot: 'bg-pyor-pass',
    ring: 'ring-pyor-pass/15',
    Icon: CheckCircle2Icon,
    tone: 'text-pyor-pass',
    label: 'All checks passed',
  },
  fail: {
    dot: 'bg-pyor-fail',
    ring: 'ring-pyor-fail/15',
    Icon: XCircleIcon,
    tone: 'text-pyor-fail',
    label: '1 check failing',
  },
  pending: {
    dot: 'bg-pyor-warn',
    ring: 'ring-pyor-warn/15',
    Icon: CircleDotIcon,
    tone: 'text-pyor-warn',
    label: 'Checks running',
  },
  none: {
    dot: 'bg-muted-foreground/40',
    ring: 'ring-transparent',
    Icon: CircleDashedIcon,
    tone: 'text-muted-foreground',
    label: 'No checks reported',
  },
};

const DAY_FMT = new Intl.DateTimeFormat(undefined, {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
});
function formatDay(iso: string): string {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? '—' : DAY_FMT.format(d);
}

/** Co-author names parsed from the message's `Co-authored-by:` trailers. */
function parseCoAuthors(message: string): string[] {
  const out: string[] = [];
  const re = /^co-authored-by:\s*([^<\n]+?)\s*</gim;
  let m: RegExpExecArray | null;
  while ((m = re.exec(message)) !== null) out.push(m[1].trim());
  return out;
}

export function CommitsTab({
  owner,
  repo,
  number,
  commitCount,
  branch,
  onSelectCommit,
  initialScrollIndex,
  onScrollIndexChange,
}: CommitsTabProps = {}) {
  // Scroll-position persistence. The list isn't virtualized, so we
  // restore/persist the container's pixel `scrollTop` directly (the
  // parent stores it as an opaque number). Restore once after the list
  // first has content; persist on scroll (debounced).
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const restoredRef = useRef(false);
  const persistTimer = useRef<number | undefined>(undefined);
  const onScroll = () => {
    if (!restoredRef.current || !onScrollIndexChange) return;
    window.clearTimeout(persistTimer.current);
    persistTimer.current = window.setTimeout(() => {
      onScrollIndexChange(scrollRef.current?.scrollTop ?? 0);
    }, 200);
  };
  useEffect(
    () => () => window.clearTimeout(persistTimer.current),
    [],
  );

  const query = useQuery({
    ...prCommitsStatsOptions(owner!, repo!, number!),
    enabled: !!(owner && repo && number),
    staleTime: 60_000,
    // Keep the prior PR's commits on screen while the next PR's land
    // (matches PRDetailScreen's per-PR queries) — the pulsing bar below
    // signals the background refetch.
    placeholderData: (prev) => prev,
  });
  // Background refetch (PR switch / focus / invalidation) with rows
  // already on screen — drives the pulsing bar. Cold load shows the
  // skeleton instead (early return below), so never both at once.
  const refreshing = query.isFetching && !query.isPending;
  // 401 → surface the dedicated auth-expired card (its "Sign in again"
  // button does the signOut + navigate); don't silently bounce.
  const authExpired =
    query.error instanceof GitHubError && query.error.status === 401;

  const commits = useMemo(() => query.data ?? [], [query.data]);
  const error =
    query.error && !authExpired
      ? query.error instanceof Error
        ? query.error.message
        : String(query.error)
      : null;

  // Restore the saved scroll position once the list first has content.
  useEffect(() => {
    if (restoredRef.current || commits.length === 0 || !scrollRef.current) {
      return;
    }
    scrollRef.current.scrollTop = initialScrollIndex ?? 0;
    restoredRef.current = true;
  }, [commits.length, initialScrollIndex]);

  // Expand state (set of SHAs). Author filter (login/name).
  const [open, setOpen] = useState<Set<string>>(() => new Set());
  const [authorFilter, setAuthorFilter] = useState<string | null>(null);
  const toggle = (sha: string) =>
    setOpen((prev) => {
      const next = new Set(prev);
      if (next.has(sha)) next.delete(sha);
      else next.add(sha);
      return next;
    });

  // Distinct authors for the filter menu.
  const authors = useMemo(() => {
    const seen = new Map<string, { name: string; avatarUrl: string | null }>();
    for (const c of commits) {
      const name = c.authorLogin ?? c.authorName;
      if (name && !seen.has(name))
        seen.set(name, { name, avatarUrl: c.avatarUrl });
    }
    return [...seen.values()];
  }, [commits]);

  const filtered = useMemo(
    () =>
      authorFilter
        ? commits.filter((c) => (c.authorLogin ?? c.authorName) === authorFilter)
        : commits,
    [commits, authorFilter],
  );

  const verifiedCount = useMemo(
    () => filtered.filter((c) => c.verified).length,
    [filtered],
  );
  const failingCount = useMemo(
    () => filtered.filter((c) => ciBucket(c.checkState) === 'fail').length,
    [filtered],
  );

  // Date groups, order preserved.
  const groups = useMemo(() => {
    const gs: { date: string; items: PRCommitWithStats[] }[] = [];
    for (const c of filtered) {
      const date = formatDay(c.date);
      const g = gs[gs.length - 1];
      if (g && g.date === date) g.items.push(c);
      else gs.push({ date, items: [c] });
    }
    return gs;
  }, [filtered]);

  const allOpen = filtered.length > 0 && open.size >= filtered.length;
  const expandAll = () =>
    setOpen(allOpen ? new Set() : new Set(filtered.map((c) => c.sha)));

  const total =
    typeof commitCount === 'number' && commitCount > 0 ? commitCount : null;
  const capped =
    !query.isFetching && total != null && commits.length < total;

  if (authExpired) {
    return (
      <PRErrorPane
        error={query.error}
        endpoint="/commits"
        layout="full"
        onRetry={() => void query.refetch()}
      />
    );
  }

  // Cold load — skeleton.
  if (
    query.data === undefined &&
    query.isPending &&
    !!(owner && repo && number)
  ) {
    return <CommitsSkeleton commitCount={commitCount} branch={branch} />;
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col bg-card">
      <FetchingBar active={refreshing} />
      {error && (
        <div className="p-7">
          <CenteredMessage>
            <XCircleIcon className="size-4 text-pyor-fail" />
            <div>
              <div className="font-semibold text-foreground">
                Couldn't load commits
              </div>
              <div className="mt-1 text-xs text-muted-foreground">{error}</div>
            </div>
          </CenteredMessage>
        </div>
      )}

      {!error && commits.length === 0 && (
        <div className="p-7">
          <CenteredMessage>No commits to show.</CenteredMessage>
        </div>
      )}

      {!error && commits.length > 0 && (
        <>
          {/* Sub-toolbar */}
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5 border-b bg-muted/40 px-5 py-2 text-[12px] text-muted-foreground">
            <GitBranchIcon className="size-3.5 text-muted-foreground" />
            <span>
              <b className="font-semibold text-foreground">
                {total ?? commits.length}
              </b>{' '}
              commits
              {branch && (
                <>
                  {' on '}
                  <code className="rounded bg-muted px-1 py-0.5 font-mono text-[11px]">
                    {branch}
                  </code>
                </>
              )}
            </span>
            {(verifiedCount > 0 || failingCount > 0) && (
              <Separator orientation="vertical" className="h-4" />
            )}
            {verifiedCount > 0 && (
              <span className="inline-flex items-center gap-1.5">
                <ShieldCheckIcon className="size-3.5 text-pyor-pass" />
                <span>
                  <b className="font-semibold text-foreground">
                    {verifiedCount}
                  </b>{' '}
                  verified
                </span>
              </span>
            )}
            {failingCount > 0 && (
              <span className="inline-flex items-center gap-1.5">
                <XCircleIcon className="size-3.5 text-pyor-fail" />
                <span>
                  <b className="font-semibold text-foreground">
                    {failingCount}
                  </b>{' '}
                  failing
                </span>
              </span>
            )}

            <div className="ml-auto flex items-center gap-2">
              {authorFilter ? (
                <button
                  type="button"
                  onClick={() => setAuthorFilter(null)}
                  className="inline-flex h-7 items-center gap-1.5 rounded-md border border-primary bg-primary px-2.5 text-[12px] font-medium text-primary-foreground"
                  title="Clear author filter"
                >
                  <Avatar className="size-4">
                    {authors.find((a) => a.name === authorFilter)?.avatarUrl && (
                      <AvatarImage
                        src={
                          authors.find((a) => a.name === authorFilter)!
                            .avatarUrl!
                        }
                        alt={authorFilter}
                      />
                    )}
                    <AvatarFallback className="text-[8px]">
                      {authorFilter.slice(0, 2).toUpperCase()}
                    </AvatarFallback>
                  </Avatar>
                  {authorFilter}
                  <XIcon className="size-3 opacity-70" />
                </button>
              ) : (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button
                      type="button"
                      className="inline-flex h-7 items-center gap-2 rounded-md border bg-background px-2.5 text-[12px] text-muted-foreground transition-colors hover:bg-muted/50"
                    >
                      <FilterIcon className="size-3.5 text-muted-foreground/70" />
                      Filter author…
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="max-h-72 overflow-auto">
                    {authors.map((a) => (
                      <DropdownMenuItem
                        key={a.name}
                        onSelect={() => setAuthorFilter(a.name)}
                        className="gap-2"
                      >
                        <Avatar className="size-4">
                          {a.avatarUrl && (
                            <AvatarImage src={a.avatarUrl} alt={a.name} />
                          )}
                          <AvatarFallback className="text-[8px]">
                            {a.name.slice(0, 2).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        {a.name}
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuContent>
                </DropdownMenu>
              )}
              <Button
                variant="outline"
                size="xs"
                onClick={expandAll}
              >
                {allOpen ? (
                  <ChevronUpIcon className="text-muted-foreground/70" />
                ) : (
                  <ChevronDownIcon className="text-muted-foreground/70" />
                )}
                {allOpen ? 'Collapse all' : 'Expand all'}
              </Button>
            </div>
          </div>

          {/* Grouped commit list */}
          <div
            ref={scrollRef}
            onScroll={onScroll}
            className="min-h-0 flex-1 overflow-auto"
          >
            {groups.map((g) => (
              <div key={g.date}>
                <CommitDateHeader date={g.date} count={g.items.length} />
                {g.items.map((c, i) => (
                  <CommitRow
                    key={c.sha}
                    c={c}
                    first={i === 0}
                    last={i === g.items.length - 1}
                    open={open.has(c.sha)}
                    onToggle={() => toggle(c.sha)}
                    owner={owner}
                    repo={repo}
                    onViewDiff={onSelectCommit}
                  />
                ))}
              </div>
            ))}
            {capped && (
              <div className="border-t px-5 py-3 text-[11.5px] text-muted-foreground">
                GitHub's API lists at most 250 commits
                {total ? ` of ${total}` : ''} — showing the most recent.
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ── Diffstat bar — proportional green/red split ──────────────────────
function DiffStatBar({ add, del }: { add: number; del: number }) {
  const total = add + del;
  const aPct = total === 0 ? 0 : Math.round((add / total) * 100);
  return (
    <span className="inline-flex items-center gap-2">
      <span className="font-mono text-[11px] tabular-nums">
        <span className="text-emerald-600 dark:text-emerald-500">
          +{add.toLocaleString()}
        </span>{' '}
        <span className="text-red-600 dark:text-red-500">
          −{del.toLocaleString()}
        </span>
      </span>
      <span className="inline-flex h-2 w-14 overflow-hidden rounded-full bg-muted ring-1 ring-inset ring-border">
        <span
          className="h-full bg-emerald-500"
          style={{ width: `${aPct}%` }}
        />
        <span className="h-full bg-red-500" style={{ width: `${100 - aPct}%` }} />
      </span>
    </span>
  );
}

// ── SHA pill — mono, click-to-copy ───────────────────────────────────
function ShaPill({ sha }: { sha: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <span
      onClick={(e) => {
        e.stopPropagation();
        void navigator.clipboard?.writeText(sha);
        setCopied(true);
        window.setTimeout(() => setCopied(false), 1200);
      }}
      title={copied ? 'Copied!' : `Copy ${sha.slice(0, 7)}`}
      className="group/sha inline-flex cursor-pointer items-center gap-1 rounded-md border bg-muted/40 py-0.5 pl-1.5 pr-1 font-mono text-[11px] text-muted-foreground transition-colors hover:bg-muted"
    >
      <span>{sha.slice(0, 7)}</span>
      <CopyIconMorph
        copied={copied}
        successIcon={<CheckIcon className="size-3 text-pyor-pass" />}
        idleIcon={
          <CopyIcon className="size-3 text-muted-foreground/60 group-hover/sha:text-foreground" />
        }
      />
    </span>
  );
}

function VerifiedBadge() {
  return (
    <Badge
      variant="outline"
      className="shrink-0 gap-1 border-transparent bg-pyor-pass/15 px-1.5 py-[1px] text-[10px] font-semibold uppercase tracking-wide text-pyor-pass"
    >
      <ShieldCheckIcon className="size-3" />
      Verified
    </Badge>
  );
}

// ── A single commit row (collapsible) ────────────────────────────────
function CommitRow({
  c,
  first,
  last,
  open,
  onToggle,
  owner,
  repo,
  onViewDiff,
}: {
  c: PRCommitWithStats;
  first: boolean;
  last: boolean;
  open: boolean;
  onToggle: () => void;
  owner?: string;
  repo?: string;
  onViewDiff?: (sha: string) => void;
}) {
  const meta = CI_META[ciBucket(c.checkState)];
  const bucket = ciBucket(c.checkState);
  const author = c.authorLogin ?? c.authorName;
  const committer = c.committerLogin ?? c.committerName;
  const committerDiffers = !!committer && committer !== author;
  const isMerge = c.parentCount > 1;
  // Description = everything after the subject line of the full message.
  // Derived from `message`, NOT GitHub's `messageBody` (which holds the
  // tail of an API-truncated headline — the cut-off end of the title,
  // not a real description).
  const body = c.message.split('\n').slice(1).join('\n').trim();
  const coAuthors = useMemo(() => parseCoAuthors(c.message), [c.message]);
  const initials = author.slice(0, 2).toUpperCase();

  return (
    <div
      className={cn(
        'relative transition-colors',
        open ? 'bg-muted/40' : 'hover:bg-muted/30',
      )}
    >
      {/* Timeline rail — vertical line through the group, clipped at the
          group's first/last node. The CI dot sits on it. */}
      <div
        aria-hidden
        className="absolute left-[34px] w-px bg-border"
        style={{ top: first ? '50%' : 0, bottom: last && !open ? '50%' : 0 }}
      />
      <button
        onClick={onToggle}
        className="group/row relative flex w-full items-center gap-3 px-5 py-3 text-left outline-none focus-visible:bg-muted/40"
      >
        {/* CI status node on the rail (centered in a w-7 cell → x=34px) */}
        <span className="relative z-10 flex w-7 shrink-0 justify-center">
          <span
            title={meta.label}
            className={cn(
              'grid size-3.5 place-items-center rounded-full ring-4',
              meta.dot,
              meta.ring,
            )}
          >
            {bucket === 'pending' && (
              <span className="size-1.5 rounded-full bg-background/90" />
            )}
          </span>
        </span>

        <Avatar className="size-6 shrink-0">
          {c.avatarUrl && <AvatarImage src={c.avatarUrl} alt={author} />}
          <AvatarFallback className="text-[9px]">{initials}</AvatarFallback>
        </Avatar>

        {/* Subject + committed-by */}
        <span className="min-w-0 flex-1">
          <span className="flex min-w-0 items-center gap-2">
            <span className="truncate text-[13.5px] font-medium text-foreground">
              {/* Full subject — `message`'s first line, NOT `headline`
                  (GitHub's messageHeadline is API-truncated with an "…").
                  CSS `truncate` clips only when the window is too narrow. */}
              {c.message.split('\n')[0]}
            </span>
            {c.verified && <VerifiedBadge />}
            {isMerge && (
              <Badge
                variant="secondary"
                className="shrink-0 gap-1 px-1.5 py-[1px] text-[10px] font-semibold"
              >
                <GitMergeIcon className="size-3" />
                Merge
              </Badge>
            )}
          </span>
          <span className="mt-0.5 flex items-center gap-1.5 text-[11.5px] text-muted-foreground">
            <span className="truncate font-medium text-foreground/80">
              {author}
            </span>
            {committerDiffers ? (
              <span className="whitespace-nowrap">
                authored ·{' '}
                <span className="font-medium text-foreground/80">
                  {committer}
                </span>{' '}
                committed
              </span>
            ) : (
              <span>committed</span>
            )}
            <span className="text-muted-foreground/40">·</span>
            <span className="whitespace-nowrap" title={fullDate(c.date)}>
              {relTime(c.date)}
            </span>
            {coAuthors.length > 0 && (
              <>
                <span className="text-muted-foreground/40">·</span>
                <span className="inline-flex items-center gap-1 whitespace-nowrap">
                  <UsersIcon className="size-3 text-muted-foreground/70" />+
                  {coAuthors.length} co-author
                </span>
              </>
            )}
          </span>
        </span>

        {/* Right cluster — files · diffstat · sha · expand. No `ml-auto`:
            the flex-1 subject column must keep the free space so long
            titles use the full width and truncate only when the window
            is genuinely too narrow (auto margins would steal that space
            and clip the title early). */}
        <span className="flex shrink-0 items-center gap-3">
          {!isMerge && c.changedFiles != null && (
            <span className="hidden items-center gap-1.5 text-[11.5px] text-muted-foreground sm:inline-flex">
              <FileIcon className="size-3.5 text-muted-foreground/70" />
              <span className="tabular-nums">{c.changedFiles}</span>
            </span>
          )}
          {isMerge ? (
            <span className="text-[11px] text-muted-foreground/70">
              no file changes
            </span>
          ) : (
            <DiffStatBar add={c.additions} del={c.deletions} />
          )}
          <Separator orientation="vertical" className="h-4" />
          <ShaPill sha={c.sha} />
          <span
            className={cn(
              'grid size-6 place-items-center rounded-md text-muted-foreground/70 transition-colors group-hover/row:text-foreground',
              open && 'bg-muted text-foreground',
            )}
          >
            <CollapseChevron open={open} />
          </span>
        </span>
      </button>

      {/* Expanded detail */}
      <Collapse open={open} className="relative pb-4 pl-[60px] pr-5">
        <div className="rounded-lg border bg-card p-3.5 shadow-sm">
            {body ? (
              <pre className="whitespace-pre-wrap break-words font-mono text-[12px] leading-relaxed text-foreground/80">
                {body}
              </pre>
            ) : (
              <span className="text-[12px] italic text-muted-foreground/70">
                No extended description provided.
              </span>
            )}

            <Separator className="my-3" />

            {/* Meta grid */}
            <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-[11.5px] text-muted-foreground">
              <span className="inline-flex items-center gap-1.5">
                <meta.Icon className={cn('size-3.5', meta.tone)} />
                <span className={meta.tone}>{meta.label}</span>
                {bucket !== 'none' && (
                  <a
                    href={`${c.url}/checks`}
                    target="_blank"
                    rel="noreferrer"
                    onClick={(e) => e.stopPropagation()}
                    className="ml-0.5 font-medium text-foreground underline-offset-2 hover:underline"
                  >
                    Details
                  </a>
                )}
              </span>
              {c.verified && (
                <span className="inline-flex items-center gap-1.5">
                  <ShieldCheckIcon className="size-3.5 text-pyor-pass" />
                  <span>
                    GPG-signed ·{' '}
                    <span className="font-mono text-foreground/70">verified</span>
                  </span>
                </span>
              )}
              {!isMerge && c.changedFiles != null && (
                <span className="inline-flex items-center gap-1.5">
                  <FileIcon className="size-3.5 text-muted-foreground/70" />
                  <span>
                    <b className="font-semibold text-foreground/80">
                      {c.changedFiles}
                    </b>{' '}
                    file{c.changedFiles === 1 ? '' : 's'} changed
                  </span>
                  <span className="ml-1">
                    <DiffStatBar add={c.additions} del={c.deletions} />
                  </span>
                </span>
              )}
              {isMerge && c.parentShas.length > 0 && (
                <span className="inline-flex items-center gap-1.5">
                  <GitMergeIcon className="size-3.5 text-muted-foreground/70" />
                  <span>
                    Parents{' '}
                    <span className="font-mono text-foreground/70">
                      {c.parentShas.map((s) => s.slice(0, 7)).join(' + ')}
                    </span>
                  </span>
                </span>
              )}
              <span className="inline-flex items-center gap-1.5">
                <GitCommitIcon className="size-3.5 text-muted-foreground/70" />
                <span className="break-all font-mono text-foreground/70">
                  {c.sha}
                </span>
              </span>
            </div>

            {/* Actions */}
            <div className="mt-3 flex flex-wrap items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() =>
                  window.open(
                    `https://github.com/${owner}/${repo}/tree/${c.sha}`,
                    '_blank',
                  )
                }
              >
                <Code2Icon />
                Browse files
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() => onViewDiff?.(c.sha)}
                disabled={!onViewDiff}
              >
                <GitCompareIcon />
                View diff
              </Button>
              <Button
                variant="ghost"
                size="icon"
                className="size-8"
                onClick={() => window.open(c.url, '_blank')}
                title="View on GitHub"
                aria-label="View on GitHub"
              >
                <GithubMark className="size-4" />
              </Button>
            </div>
          </div>
      </Collapse>
    </div>
  );
}

// ── Date-group header (on the rail) ──────────────────────────────────
function CommitDateHeader({ date, count }: { date: string; count: number }) {
  return (
    <div className="flex items-center gap-3 border-y bg-muted/40 px-5 py-2">
      <span className="relative z-10 flex w-7 justify-center">
        <span className="absolute left-1/2 top-0 h-1/2 w-px -translate-x-1/2 bg-border" />
        <span className="absolute bottom-0 left-1/2 h-1/2 w-px -translate-x-1/2 bg-border" />
        <span className="relative z-10 grid size-5 place-items-center rounded-full border bg-card">
          <GitCommitIcon className="size-3 text-muted-foreground" />
        </span>
      </span>
      <span className="text-[12px] font-semibold text-foreground/80">
        Commits on {date}
      </span>
      <span className="text-[11.5px] text-muted-foreground/70">
        · {count} commit{count === 1 ? '' : 's'}
      </span>
    </div>
  );
}

// ── Loading skeleton ─────────────────────────────────────────────────
function CommitsSkeleton({
  commitCount,
  branch,
}: {
  commitCount?: number;
  branch?: string;
}) {
  const showCount = typeof commitCount === 'number' && commitCount > 0;
  return (
    <div className="flex flex-1 flex-col overflow-hidden bg-card">
      <div className="flex items-center gap-3 border-b bg-muted/40 px-5 py-2 text-[12px] text-muted-foreground">
        <GitBranchIcon className="size-3.5 text-muted-foreground" />
        <span>
          {showCount ? (
            <>
              <b className="font-semibold text-foreground">{commitCount}</b>{' '}
              commits
              {branch ? (
                <>
                  {' on '}
                  <code className="rounded bg-muted px-1 py-0.5 font-mono text-[11px]">
                    {branch}
                  </code>
                </>
              ) : null}
            </>
          ) : (
            'Listing commits…'
          )}
        </span>
        <span className="inline-flex items-center gap-1.5 text-muted-foreground">
          <Loader2 className="size-3 animate-spin" />
          Pulling commit details
        </span>
      </div>
      <div className="relative flex-1 overflow-hidden">
        <div className="absolute left-[34px] top-0 h-full w-px bg-border" />
        {Array.from({ length: 9 }).map((_, i) => (
          <div
            key={i}
            className="relative flex items-center gap-3 px-5 py-3"
          >
            <span className="relative z-10 flex w-7 shrink-0 justify-center">
              <span className="size-3.5 rounded-full bg-muted ring-4 ring-muted/40" />
            </span>
            <span className="size-6 shrink-0 animate-pulse rounded-full bg-muted" />
            <span className="min-w-0 flex-1">
              <span
                className="block h-3 animate-pulse rounded bg-muted"
                style={{ width: `${45 + ((i * 7) % 35)}%` }}
              />
              <span className="mt-1.5 block h-2.5 w-40 animate-pulse rounded bg-muted/70" />
            </span>
            <span className="h-2 w-14 shrink-0 animate-pulse rounded-full bg-muted" />
          </div>
        ))}
      </div>
    </div>
  );
}

function CenteredMessage({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex items-center justify-center gap-3 rounded-lg border bg-card p-8 text-[13px] text-foreground">
      {children}
    </div>
  );
}
