/** Peek at the persisted theme without applying defaults — returns
 * the saved Shiki theme name, or null if the user has never saved a
 * theme. Used by useDiffThemeSync to tell "fresh install" apart from
 * "explicit pick" on first paint. */
export function peekSavedTheme(): ShikiThemeName | null {
  try {
    const raw = localStorage.getItem(PREFS_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<DiffPreferences>;
    return typeof parsed.theme === "string" && parsed.theme.length > 0
      ? parsed.theme
      : null;
  } catch {
    return null;
  }
}

export function loadPrefs(): DiffPreferences {
  try {
    const raw = localStorage.getItem(PREFS_KEY);
    if (!raw) return DEFAULT_PREFS;
    const parsed = JSON.parse(raw) as Partial<DiffPreferences>;
    return {
      theme:
        typeof parsed.theme === "string" && parsed.theme.length > 0
          ? parsed.theme
          : DEFAULT_PREFS.theme,
      lineDiffStyle: isLineDiffStyle(parsed.lineDiffStyle)
        ? parsed.lineDiffStyle
        : DEFAULT_PREFS.lineDiffStyle,
      density: isDensity(parsed.density)
        ? parsed.density
        : DEFAULT_PREFS.density,
      fontSize: clampInt(
        parsed.fontSize,
        FONT_SIZE_MIN,
        FONT_SIZE_MAX,
        DEFAULT_PREFS.fontSize,
      ),
      lineHeight: clampInt(
        parsed.lineHeight,
        LINE_HEIGHT_MIN,
        LINE_HEIGHT_MAX,
        DEFAULT_PREFS.lineHeight,
      ),
    };
  } catch {
    return DEFAULT_PREFS;
  }
}

function clampInt(
  v: unknown,
  min: number,
  max: number,
  fallback: number,
): number {
  if (typeof v !== "number" || !Number.isFinite(v)) return fallback;
  return Math.min(max, Math.max(min, Math.round(v)));
}

export function savePrefs(patch: Partial<DiffPreferences>): void {
  try {
    const next: DiffPreferences = { ...loadPrefs(), ...patch };
    localStorage.setItem(PREFS_KEY, JSON.stringify(next));
  } catch {
    // ignore — same-shape failure mode as the rest of our stores
  }
}

function isLineDiffStyle(v: unknown): v is LineDiffStyle {
  return v === "word-alt" || v === "word" || v === "char" || v === "none";
}

function isDensity(v: unknown): v is DensityPreset {
  return v === "compact" || v === "default" || v === "relaxed";
}
