// Turn the GitHub references inside a plain-text string (a commit
// subject, a status description…) into links, the way GitHub renders
// them in a timeline. Commit messages are NOT markdown — GitHub shows
// them verbatim and only autolinks references — so this deliberately
// does plain-text → React nodes, never a markdown pass (which would
// mangle `_x_`, backticks, `*` in a subject).
//
// Covered, matching GitHub's autolinker:
//   • bare URLs            https://… (trailing punctuation peeled off)
//   • cross-repo issue/PR  owner/repo#123
//   • issue/PR refs        #123        (needs owner/repo for the URL)
//   • @mentions            @login
//
// NOT covered: repo-configured custom autolink references (e.g. a
// Jira `EXP-1234`). Those live behind the admin-only autolinks API and
// would need GitHub's server-side `/markdown` render to resolve — out
// of scope until a repo that uses them turns up.

import React from 'react';

const GITHUB = 'https://github.com';

// One alternation, scanned left-to-right. URL first so a `#123` inside a
// URL fragment isn't stolen; cross-repo ref before the bare `#123`.
const REF_RE =
  /(https?:\/\/[^\s<]+)|([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+#\d+)|(#\d+)|(@[A-Za-z0-9](?:[A-Za-z0-9-]{0,38}))/g;

function RefLink({ href, text }: { href: string; text: string }) {
  return (
    <a
      href={href}
      // Stop the click bubbling to an enclosing clickable row (the
      // commit row scopes the diff) — the link should just open GitHub.
      onClick={(e) => e.stopPropagation()}
      target="_blank"
      rel="noopener noreferrer"
      className="text-primary no-underline hover:underline"
    >
      {text}
    </a>
  );
}

/** Render `text` with its GitHub references linkified. `owner`/`repo`
 * are needed to resolve bare `#123` refs; without them those stay plain
 * text (URLs, cross-repo refs and @mentions still link). */
export function linkifyRefs(
  text: string,
  { owner, repo }: { owner?: string; repo?: string } = {},
): React.ReactNode[] {
  const matches = Array.from(text.matchAll(REF_RE));
  const out: React.ReactNode[] = [];
  let cursor = 0;
  matches.forEach((m, i) => {
    const start = m.index ?? 0;
    if (start > cursor) out.push(text.slice(cursor, start));
    const [raw, url, xref, ref, mention] = m;
    let token = raw;
    let trailing = '';
    if (url) {
      // GitHub excludes trailing sentence/bracket punctuation from the
      // link: `(https://x.com).` links only the URL.
      const peel = token.match(/[).,;:!?]+$/);
      if (peel) {
        trailing = peel[0];
        token = token.slice(0, -trailing.length);
      }
    }
    const href = url
      ? token
      : xref
        ? `${GITHUB}/${xref.replace('#', '/issues/')}`
        : ref && owner && repo
          ? `${GITHUB}/${owner}/${repo}/issues/${ref.slice(1)}`
          : mention
            ? `${GITHUB}/${mention.slice(1)}`
            : null;
    out.push(href ? <RefLink key={i} href={href} text={token} /> : token);
    if (trailing) out.push(trailing);
    cursor = start + raw.length;
  });
  if (cursor < text.length) out.push(text.slice(cursor));
  return out;
}
