// ReviewThread — the single inline review-comment thread component shared
// by BOTH the Changes tab (diff pane) and the Conversation tab (timeline).
//
// Supersedes the former split between `changes/InlineCommentThread` and
// `conversation/GhInlineThread` (see ADR 0008's 2026-06 amendment). One
// component now owns body rendering (Markdown + ```suggestion before→after
// diff), comment edit/delete, reply, resolve, the unified "outdated" muted
// treatment, and the shared GhComment / ThreadResolveFooter chrome.
//
// The ONLY surface difference is contextual and driven by `withAnchor`:
//   • Conversation timeline (`withAnchor`): renders a
//     "{author} started a thread" header + embeds the DiffHunkSnippet in
//     the head comment, because the timeline has no surrounding diff.
//   • Changes diff pane (no `withAnchor`): omits both — the diff line the
//     thread is anchored to is already on screen right above the card.
//
// Reactions are INJECTED (each surface patches its own query cache);
// resolve is owned here via `useResolveThread`. DOM markers
// (`data-pyor-thread-id` / `-reply` / `-compose`) are preserved for the
// Changes-tab `j/k/n/p/r` keymap.

import { useState } from 'react';
import { humanAge } from '../../util/relTime';
import { useQuery } from '@tanstack/react-query';
import { getFiletypeFromFileName } from '@pierre/diffs';
import { toast } from 'sonner';
import {
  AlertTriangleIcon,
  CheckIcon,
  CodeIcon,
  ExternalLinkIcon,
  InfoIcon,
  MessageSquareIcon,
  ReplyIcon,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import {
  deleteReviewComment,
  editReviewComment,
  GitHubError,
} from '../../github/client';
import { prPendingReviewOptions } from '../../github/prQueries';
import { useSingleComment } from '../usePendingReview';
import {
  OfflineComposerNotice,
  useComposerOffline,
} from './OfflineComposerNotice';
import type { GHReactor } from '../../github/client';
import type { CommentThread } from '../../github/threads';
import type { GHReactions, GHReviewComment } from '../../github/types';
import { plainTextPreview } from '../../github/reactionHelpers';
import { baselineFromHunk } from '../../github/suggestionBaseline';
import { Markdown } from '../../ui/Markdown';
import { fullDate } from '../../util/relTime';
import { GhComment, type AgentCopyContext } from './GhComment';
import { prRoleFor } from '../prRole';
import { GhComposer } from './GhComposer';
import { DiffHunkSnippet } from './DiffHunkSnippet';
import { CopyPathButton } from '../changes/CopyPathButton';
import { ThreadResolveFooter } from './ThreadResolveFooter';
import { useGithubAssetsUploader } from './composer/useGithubAssetsUploader';
import { useConfirm } from '@/components/confirm';
import { Trash2Icon } from 'lucide-react';
import { useResolveThread } from '../useResolveThread';
import type { CollapsedCommentsValue } from './useCollapsedComments';
import { anchorCodeFromHunk } from '../../util/agentPrompt';

/** Per-comment reaction handlers. Injected so each surface updates its own
 * query cache optimistically — the Changes tab patches
 * `['pr',o,r,n,'comments']`; the Conversation tab patches the prThreads
 * query. The component just renders the reaction UI + calls these. */
export interface ReviewThreadReactions {
  onAdd: (commentId: number, key: keyof GHReactions) => void | Promise<void>;
  onRemove: (
    commentId: number,
    key: keyof GHReactions,
    reactionId: number,
  ) => void | Promise<void>;
  listReactors: (commentId: number) => Promise<GHReactor[]>;
}

interface ReviewThreadProps {
  thread: CommentThread;
  owner: string;
  repo: string;
  number: number;
  viewerLogin?: string;
  /** PR author's login — lets each comment's header show the PR-relative
   * role pill ("Author" for the opener, "Reviewer" for everyone else,
   * since inline-thread comments are reviews by definition). */
  prAuthorLogin?: string;
  /** Shared per-PR collapse store (thread:/reply: keys), so collapse is
   * consistent across both tabs. */
  collapse: CollapsedCommentsValue;
  /** Fires after a successful reply / edit / delete so the caller can
   * refetch its comment query and reconcile. */
  onChanged?: () => void;
  reactions: ReviewThreadReactions;
  /** Edit/delete handlers for the viewer's PENDING comments (ADR 0019).
   * Pending comments mutate via GraphQL, so they can't reuse the REST
   * edit/delete this component uses for published comments — the caller
   * (which owns the pending-review hook) passes these. Omit on surfaces
   * that shouldn't author (e.g. the read-only timeline); pending
   * edit/delete then stay hidden. */
  pendingActions?: {
    edit: (commentId: number, body: string) => void;
    remove: (commentId: number) => void;
  };
  /** Author a PENDING reply to this thread's head (ADR 0019), wired on
   * authoring surfaces (the Changes pane, via the pending-review hook).
   * When present the reply composer offers github.com's Start-a-review /
   * Add-single-comment duality; when absent (the read-only timeline) it
   * falls back to an immediate published reply. */
  onAddPendingReply?: (headId: number, body: string) => void;
  /** Conversation "Focus: Comments" is on → outdated threads (the code
   * they point at has changed) collapse to their one-line stub by default
   * so they recede without disappearing; the reviewer can still expand
   * any of them. Resolved threads already auto-collapse regardless. */
  focusMode?: boolean;
  /** Conversation timeline → render the anchor header + embed the
   * diff-hunk snippet (no surrounding diff there). Omit in the Changes
   * pane (the diff is visible above the card). */
  withAnchor?: boolean;
  /** Whether the anchor card embeds the frozen diff_hunk snippet. Default
   * true (the Conversation timeline, which has no surrounding diff). The
   * Changes pane passes false for its floating outdated cards: that surface
   * is already a diff view, so re-rendering a mini-diff inside the comment
   * is redundant — the card falls back to a compact path · line reference. */
  embedHunk?: boolean;
  /** Full file blobs for the embedded hunk — only needed with `withAnchor`. */
  newText?: string | null;
  oldText?: string | null;
  /** Conversation timeline → "Show in diff" action in the anchor header.
   * Wired by PRDetailScreen to switch to the Changes tab + scroll the diff
   * to this thread's anchor line (same {path, line, diffSide} jump target
   * the Checks/reviewer-HoverCard navigation uses). Omitted in the Changes
   * pane, where the diff is already on screen. */
  onShowInDiff?: (target: {
    path: string;
    line: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
  }) => void;
}

export function ReviewThread({
  thread,
  owner,
  repo,
  number,
  viewerLogin,
  prAuthorLogin,
  collapse,
  onChanged,
  reactions,
  pendingActions,
  onAddPendingReply,
  focusMode = false,
  withAnchor = false,
  embedHunk = true,
  newText,
  oldText,
  onShowInDiff,
}: ReviewThreadProps) {
  const toggleResolved = useResolveThread(owner, repo, number);
  const resolved = thread.isResolved === true;
  const outdated = thread.outdated === true;
  // Default-collapsed when resolved (always) or — under Conversation
  // Focus — outdated. The store still lets the user pin either open.
  const autoCollapsed = resolved || (focusMode && outdated);
  // Commit-scoped diff only: the anchor was remapped onto the selected
  // commit's line numbers ('repositioned') or couldn't be matched and
  // may be on the wrong line ('approximate'). Undefined in full-PR view.
  const scopedAnchor = thread.scopedAnchor;
  const threadKey = `thread:${thread.headId}`;
  const threadCollapsed = collapse.isCollapsed(threadKey, autoCollapsed);
  const fileLang = getFiletypeFromFileName(thread.path);

  const head = thread.comments[0];
  const replies = thread.comments.slice(1);
  const replyCount = replies.length;

  // Stable id for the global n/p thread-navigation + R-to-reply keymap
  // (see ChangesTab). Unused in the Conversation tab but harmless there.
  const threadDomId = `t${thread.headId ?? `${thread.path}:${thread.line}`}`;

  // Anchor numbers for the embedded hunk (withAnchor only). diff_hunk is
  // numbered against the commit the comment was made on, matching the
  // `original_*` lines — fall back to live numbers if absent.
  const anchorEnd = head.original_line ?? head.line ?? null;
  const anchorStart = head.original_start_line ?? head.start_line ?? null;
  const isRange =
    anchorStart != null && anchorEnd != null && anchorStart !== anchorEnd;
  const lineLabel = isRange
    ? `L${Math.min(anchorStart!, anchorEnd!)}–L${Math.max(anchorStart!, anchorEnd!)}`
    : anchorEnd != null
      ? `L${anchorEnd}`
      : 'L?';
  const hasHunk =
    withAnchor && embedHunk && !!head.diff_hunk && head.diff_hunk.trim() !== '';

  // Changes diff pane: surface the commented line(s) in the head comment's
  // header — a single line ("L14") or the live span ("L16–L20"). Uses the
  // live thread.startLine/line so it matches the rows on screen.
  const diffLineLabel =
    thread.startLine !== thread.line
      ? `L${Math.min(thread.startLine, thread.line)}–L${Math.max(thread.startLine, thread.line)}`
      : `L${thread.line}`;

  // Diff-anchor context for "Copy for agent", shared by every comment in
  // the thread (replies inherit the head's anchor on both surfaces). The
  // displayed line(s) are the head's live numbers (falling back to the
  // originals when outdated); the anchored code is pulled from the head's
  // diff_hunk across the whole [anchorStart, anchorEnd] span, which is
  // numbered against the comment's commit and so matches the hunk's own
  // row numbering. Multi-line comments thus copy every commented line.
  const copyContext: AgentCopyContext = {
    file: thread.path,
    line: head.line ?? head.original_line ?? null,
    startLine: head.start_line ?? head.original_start_line ?? null,
    code: anchorCodeFromHunk(
      head.diff_hunk,
      anchorStart ?? anchorEnd,
      anchorEnd,
      head.side,
    ),
  };

  const renderComment = (
    c: GHReviewComment,
    variant: 'default' | 'reply',
    collapsed: boolean,
    onCollapsedChange: () => void,
    diffSlice?: React.ReactNode,
    lineRangeLabel?: string,
  ) => (
    <ReviewComment
      key={c.id}
      comment={c}
      owner={owner}
      repo={repo}
      variant={variant}
      fileLang={fileLang}
      viewerLogin={viewerLogin}
      prAuthorLogin={prAuthorLogin}
      collapsed={collapsed}
      onCollapsedChange={onCollapsedChange}
      reactions={reactions}
      onChanged={onChanged}
      pendingActions={pendingActions}
      diffSlice={diffSlice}
      copyContext={copyContext}
      lineRangeLabel={lineRangeLabel}
    />
  );

  return (
    <div
      data-pyor-thread-id={threadDomId}
      data-pyor-thread-resolved={resolved ? '1' : '0'}
      className={cn(
        // Reset the two styles the card would otherwise inherit from the
        // @pierre/diffs CodeView when it renders as a diff-pane annotation
        // (a code context): `font-sans` (else the header + prose body show
        // in the diff's mono font) and `whitespace-normal` (else the diff's
        // `white-space: pre-wrap` turns the newlines in loose-list markup —
        // `<li>\n<p>…` — into real breaks, dropping the bullet onto its own
        // line). Code chips, fenced blocks, and the embedded hunk set their
        // own mono + `white-space`, so they're unaffected. No-ops in the
        // Conversation timeline, which is already a normal sans context.
        'box-border max-w-full overflow-hidden border font-sans whitespace-normal text-[13px]',
        // Positioning differs by context: the timeline card flows
        // vertically; the diff-pane card is inset under its line.
        withAnchor ? 'mb-3 rounded-[10px]' : 'mx-3 mb-3 mt-1.5 rounded-lg',
        // Unified outdated treatment (was Conversation-only): the card
        // steps back — muted fill, no shadow — so the amber chip + footer
        // are the loud signals.
        outdated ? 'bg-muted/40' : 'bg-card shadow-sm dark:shadow-none',
      )}
    >
      {/* Conversation timeline: anchor header. The file path · line +
       * copy-path button ride inside the embedded hunk, so this strip
       * just names who opened the thread + the resolved/reply-count. */}
      {withAnchor && (
        <div className="flex items-center gap-2 border-b bg-muted/40 px-3 py-2 text-[12px] text-muted-foreground">
          <MessageSquareIcon className="size-3.5 shrink-0 text-muted-foreground/70" />
          <span className="truncate text-foreground/90">
            <b className="font-semibold text-foreground">{head.user.login}</b>{' '}
            started a thread
          </span>
          {outdated && (
            <>
              <Badge
                variant="outline"
                className="shrink-0 gap-1 border-transparent bg-pyor-warn/15 px-1.5 py-0 text-[10px] font-semibold text-pyor-warn"
              >
                <AlertTriangleIcon className="size-2.5" />
                Outdated
              </Badge>
              <span className="truncate text-[11px] text-muted-foreground/70">
                line drifted off the latest diff
              </span>
            </>
          )}
          <div className="ml-auto flex shrink-0 items-center gap-2.5">
            {onShowInDiff && (
              <button
                type="button"
                onClick={() =>
                  onShowInDiff({
                    path: thread.path,
                    line: head.line ?? head.original_line ?? null,
                    diffSide: head.side ?? null,
                  })
                }
                className="inline-flex items-center gap-1 rounded text-[11.5px] text-muted-foreground hover:text-foreground"
              >
                <ExternalLinkIcon className="size-3" />
                Show in diff
              </button>
            )}
            {resolved ? (
              <Badge
                variant="outline"
                className="gap-1 border-transparent bg-pyor-pass/15 px-1.5 py-0 text-[10px] font-semibold text-pyor-pass"
              >
                <CheckIcon className="size-2.5" />
                Resolved
              </Badge>
            ) : (
              <span className="text-[11.5px] text-muted-foreground/80">
                {replyCount} {replyCount === 1 ? 'reply' : 'replies'} · open
              </span>
            )}
          </div>
        </div>
      )}

      <div className={cn('space-y-2 p-2', outdated && 'opacity-70')}>
        {/* Changes pane: no header, so a compact badges row carries the
         * resolved / outdated / scoped-anchor signal. */}
        {!withAnchor && (resolved || outdated || scopedAnchor) && (
          <div className="flex flex-wrap items-center gap-1.5">
            {resolved && (
              <Badge
                variant="outline"
                className="gap-1 border-transparent bg-pyor-pass/15 px-1.5 py-0 text-[10px] font-semibold text-pyor-pass"
              >
                <CheckIcon className="size-2.5" />
                Resolved
              </Badge>
            )}
            {outdated && (
              <Badge
                variant="outline"
                className="gap-1 border-transparent bg-pyor-warn/15 px-1.5 py-0 text-[10px] font-semibold text-pyor-warn"
              >
                <AlertTriangleIcon className="size-2.5" />
                Outdated
              </Badge>
            )}
            {/* Commit-scoped diff: the comment was made against the full
             * PR diff, so its line may not line up with this commit's
             * view. We re-anchored it by matching the commented line's
             * text ('repositioned'), or couldn't and left it where it
             * was ('approximate'). The tooltip gives the reviewer the
             * why on hover. */}
            {scopedAnchor && (
              <TooltipProvider delayDuration={200}>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="inline-flex">
                      <Badge
                        variant="outline"
                        className="cursor-help gap-1 border-transparent bg-muted px-1.5 py-0 text-[10px] font-semibold text-muted-foreground"
                      >
                        <InfoIcon className="size-2.5" />
                        {scopedAnchor === 'repositioned'
                          ? 'Repositioned'
                          : 'May be off'}
                      </Badge>
                    </span>
                  </TooltipTrigger>
                  <TooltipContent className="max-w-[260px] text-center">
                    {scopedAnchor === 'repositioned'
                      ? 'This comment was made against the full PR diff. It’s been re-anchored to the matching line in this commit’s view — its position here is approximate.'
                      : 'This comment was made against the full PR diff and may appear on a different line in this commit’s view — the commented line couldn’t be located in this commit.'}
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}
          </div>
        )}

        {/* Head comment — embeds the diff hunk when withAnchor. Its
         * chevron folds the whole thread (head + replies + composer). */}
        {renderComment(
          head,
          'default',
          threadCollapsed,
          () => collapse.toggle(threadKey, autoCollapsed),
          hasHunk ? (
            <DiffHunkSnippet
              diffHunk={head.diff_hunk!}
              file={thread.path}
              line={head.line}
              anchorStart={anchorStart}
              anchorEnd={anchorEnd}
              side={head.side}
              newText={newText}
              oldText={oldText}
              embedded
              lineLabel={lineLabel}
              copyAnchor={{
                path: thread.path,
                // The LAST line of the comment's range, using the same
                // basis as the visible `lineLabel` (anchorEnd =
                // original_line ?? line) so it matches what the user
                // sees — not the live `head.line`, which can have
                // drifted (e.g. showing 75 for a comment labelled …–L77).
                line: anchorEnd,
                side: head.side,
              }}
            />
          ) : withAnchor && embedHunk ? (
            // No diff_hunk to embed (e.g. an outdated comment whose hunk
            // GitHub no longer returns). The file path · line + copy-path
            // button normally ride inside DiffHunkSnippet's header, so
            // without it the timeline card would name only the author and
            // drop the file reference entirely. Render the same
            // path-reference strip on its own so the comment still says
            // WHERE it points. Gated on `embedHunk` so the Changes pane —
            // where the file path is already on screen above the diff —
            // drops this strip too, not just the embedded mini-diff.
            <div
              className={cn(
                'flex items-center gap-2 border bg-muted/40 px-2.5 py-1 text-[10.5px] text-muted-foreground',
                head.subject_type !== 'file' && 'rounded-md',
              )}
            >
              <CodeIcon className="size-3 shrink-0 text-muted-foreground/70" />
              <code className="truncate rounded bg-muted px-1.5 py-0.5 font-mono text-[10.5px] text-foreground">
                {thread.path}
              </code>
              {anchorEnd != null && head.subject_type !== 'file' && (
                <>
                  <span className="shrink-0 text-muted-foreground/50">·</span>
                  <span className="shrink-0 font-mono text-[10.5px] text-muted-foreground">
                    {lineLabel}
                  </span>
                </>
              )}
              <CopyPathButton
                anchor={{
                  path: thread.path,
                  line: head.subject_type === 'file' ? null : anchorEnd,
                  side: head.side,
                }}
                compact
              />
            </div>
          ) : undefined,
          // Commented line(s) label in the head comment's header (Changes
          // pane only — the timeline already carries it in the embedded
          // hunk).
          withAnchor ? undefined : diffLineLabel,
        )}

        {/* Replies + composer fold away with the head comment. */}
        {!threadCollapsed && replies.length > 0 && (
          <div className="relative ml-5 space-y-2 border-l-2 border-border pl-5 pb-1">
            {replies.map((r) => (
              <div key={r.id} className="relative">
                <span className="pointer-events-none absolute -left-5 top-4 h-px w-3.5 bg-border" />
                {renderComment(r, 'reply', collapse.isCollapsed(`reply:${r.id}`), () =>
                  collapse.toggle(`reply:${r.id}`),
                )}
              </div>
            ))}
          </div>
        )}

        {!threadCollapsed && (
          <div className="ml-5">
            <ReplyComposer
              owner={owner}
              repo={repo}
              number={number}
              headId={thread.headId}
              onAddPendingReply={onAddPendingReply}
            />
          </div>
        )}
      </div>

      {/* Conversation-level resolve / unresolve footer. */}
      <ThreadResolveFooter
        resolved={resolved}
        outdated={outdated}
        resolvedBy={thread.resolvedBy}
        canResolve={thread.viewerCanResolve}
        canUnresolve={thread.viewerCanUnresolve}
        ready={!!thread.graphqlNodeId}
        onToggle={() =>
          thread.graphqlNodeId
            ? toggleResolved({
                graphqlNodeId: thread.graphqlNodeId,
                resolve: !resolved,
                viewerLogin,
              })
            : undefined
        }
      />
    </div>
  );
}

function ReviewComment({
  comment,
  owner,
  repo,
  variant,
  fileLang,
  viewerLogin,
  prAuthorLogin,
  collapsed,
  onCollapsedChange,
  reactions,
  onChanged,
  pendingActions,
  diffSlice,
  copyContext,
  lineRangeLabel,
}: {
  comment: GHReviewComment;
  owner: string;
  repo: string;
  variant: 'default' | 'reply';
  fileLang: string;
  viewerLogin?: string;
  prAuthorLogin?: string;
  collapsed: boolean;
  onCollapsedChange: () => void;
  reactions: ReviewThreadReactions;
  onChanged?: () => void;
  pendingActions?: {
    edit: (commentId: number, body: string) => void;
    remove: (commentId: number) => void;
  };
  /** Embedded diff hunk for the head comment (Conversation tab only). */
  diffSlice?: React.ReactNode;
  /** Shared thread anchor for "Copy for agent" (file/line/code). */
  copyContext: AgentCopyContext;
  /** Compact "L16–L20" span shown in the header after the age (head
   * comment of a multi-line thread, Changes pane only). */
  lineRangeLabel?: string;
}) {
  const [editing, setEditing] = useState(false);
  const uploadImage = useGithubAssetsUploader();
  const confirm = useConfirm();
  // Original line(s) this comment is anchored to — the baseline a
  // ```suggestion in its body replaces.
  const suggestionBaseline = baselineFromHunk(
    comment.diff_hunk,
    comment.side,
    comment.original_start_line ?? comment.start_line,
    comment.original_line ?? comment.line,
  );
  const isYou = !!viewerLogin && comment.user.login === viewerLogin;
  // Pending = belongs to the viewer's in-progress GitHub review (ADR
  // 0019): private until submitted, badged "Pending" (or "Pending ·
  // saving…" while the optimistic save is still in flight).
  const isPending = comment.status === 'pending';
  const pendingChip = isPending ? (
    <Badge
      variant="outline"
      className="shrink-0 whitespace-nowrap border-pyor-warn/40 px-1 py-0 text-[9.5px] uppercase tracking-wider text-pyor-warn"
    >
      {comment.optimistic ? 'Pending · saving…' : 'Pending'}
    </Badge>
  ) : undefined;
  const ago = comment.created_at ? `${humanAge(comment.created_at)} ago` : undefined;
  const edited =
    comment.updated_at &&
    comment.created_at &&
    comment.updated_at !== comment.created_at
      ? humanAge(comment.updated_at)
      : null;

  // Pending comments are editable/deletable only when the caller wired
  // pendingActions (the Changes pane, which owns the pending-review
  // hook). They dispatch to GraphQL there — REST 404s on pending. While
  // a save is still in flight the comment has no real id/node_id yet, so
  // hold the affordances until it reconciles.
  const canMutatePending = isPending && !!pendingActions && !comment.optimistic;
  const canMutate = isYou && (!isPending || canMutatePending);

  const onDelete = async () => {
    if (canMutatePending) {
      // Optimistic + empty-review cleanup live in the hook; deleting an
      // unsent draft comment needs no heavy confirm.
      pendingActions!.remove(comment.id);
      return;
    }
    const ok = await confirm({
      title: 'Delete comment?',
      description: `Delete this comment by ${comment.user.login}? This can't be undone.`,
      confirmLabel: 'Delete',
      confirmIcon: Trash2Icon,
      tone: 'destructive',
    });
    if (!ok) return;
    try {
      await deleteReviewComment(owner, repo, comment.id);
      onChanged?.();
      toast.success('Comment deleted');
    } catch (e) {
      toast.error('Could not delete comment', {
        description:
          e instanceof GitHubError
            ? `${e.status}: ${e.message}`
            : e instanceof Error
              ? e.message
              : String(e),
      });
    }
  };

  return (
    <GhComment
      author={comment.user.login}
      authorAvatarUrl={comment.user.avatar_url}
      association={comment.author_association}
      prRole={prRoleFor(comment.user.login, prAuthorLogin, true)}
      age={ago}
      ageTitle={fullDate(comment.created_at)}
      edited={edited}
      editedTitle={fullDate(comment.updated_at)}
      isYou={isYou}
      lineRangeLabel={lineRangeLabel}
      highlight={isPending ? 'pending' : undefined}
      verdictChip={pendingChip}
      htmlUrl={comment.html_url}
      // Reactions don't exist on a pending comment — it isn't public yet,
      // and the reactions endpoint 404s on its id. Suppress the strip +
      // add-picker until the review is submitted (GhReactions renders
      // nothing with no reactions and no onAdd).
      reactions={isPending ? undefined : comment.reactions}
      onAddReaction={
        isPending ? undefined : (key) => reactions.onAdd(comment.id, key)
      }
      onRemoveReaction={
        isPending
          ? undefined
          : (key, reactionId) =>
              reactions.onRemove(comment.id, key, reactionId)
      }
      listReactors={
        isPending ? undefined : () => reactions.listReactors(comment.id)
      }
      viewerLogin={viewerLogin}
      variant={variant}
      preview={plainTextPreview(comment.body ?? '')}
      previewSource={comment.body ?? ''}
      collapsed={collapsed}
      onCollapsedChange={onCollapsedChange}
      diffSlice={diffSlice}
      copyContext={copyContext}
      copyBody={comment.body ?? ''}
      canEdit={canMutate}
      onEdit={canMutate ? () => setEditing(true) : undefined}
      onDelete={canMutate ? onDelete : undefined}
      editing={editing}
      editor={
        <GhComposer
          variant="inline"
          draftKey={`${owner}/${repo}:edit:${comment.id}`}
          initialBody={comment.body ?? ''}
          submitLabel="Update comment"
          submitIcon="check"
          autoFocus
          minHeight={96}
          onUploadImage={uploadImage}
          mentionContext={{ owner, repo }}
          suggestionSeed={suggestionBaseline}
          fileLang={fileLang}
          onCancel={() => setEditing(false)}
          onSubmit={async (body) => {
            if (!body.trim() || body === comment.body) {
              setEditing(false);
              return;
            }
            if (canMutatePending) {
              // Pending edit → GraphQL via the hook (optimistic + toast
              // handled there). Close immediately.
              pendingActions!.edit(comment.id, body);
              setEditing(false);
              return;
            }
            try {
              await editReviewComment(owner, repo, comment.id, body);
              setEditing(false);
              onChanged?.();
              toast.success('Comment updated');
            } catch (e) {
              toast.error('Could not update comment', {
                description: e instanceof Error ? e.message : String(e),
              });
              throw e;
            }
          }}
        />
      }
    >
      <Markdown
        source={comment.body ?? ''}
        size="sm"
        fileLang={fileLang}
        suggestionBaseline={suggestionBaseline}
      />
    </GhComment>
  );
}

function ReplyComposer({
  owner,
  repo,
  number,
  headId,
  onAddPendingReply,
}: {
  owner: string;
  repo: string;
  number: number;
  headId: number;
  onAddPendingReply?: (headId: number, body: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const uploadImage = useGithubAssetsUploader();
  const offline = useComposerOffline();
  const single = useSingleComment(owner, repo, number);
  // Whether the viewer already has an open pending review — read on EVERY
  // surface (not just authoring ones), because a reply always joins an
  // open review: on authoring surfaces via onAddPendingReply, and on the
  // timeline via useSingleComment's pending-aware path (GitHub forbids a
  // standalone published reply while a review is open). So the submit
  // label must read "Add review comment" wherever a review is open. The
  // query is already maintained by the Changes pane / Conversation tab, so
  // this just subscribes to the shared cache.
  const pendingQuery = useQuery({
    ...prPendingReviewOptions(owner, repo, number),
    enabled: !!(owner && repo && number),
    staleTime: 30_000,
  });
  const hasPendingReview = !!pendingQuery.data;
  const canAuthorPending = !!onAddPendingReply;

  const replySingle = (body: string) => {
    // The mutation owns the optimistic add + reconcile to the real id.
    // Don't invalidate the comments query here — refetching GitHub's
    // eventually-consistent list would drop the just-added reply and
    // flash it back in once GitHub caught up.
    single.mutate({ kind: 'reply', inReplyTo: headId, path: '', body });
    setOpen(false);
  };
  const replyPending = (body: string) => {
    onAddPendingReply?.(headId, body);
    setOpen(false);
  };

  // Offline → no authoring; show the reconnect pill in place of the
  // reply affordance (cached comments above stay readable).
  if (offline) {
    return (
      <span data-pyor-thread-reply>
        <OfflineComposerNotice variant="inline" />
      </span>
    );
  }

  if (!open) {
    return (
      <span data-pyor-thread-reply>
        <button
          type="button"
          onClick={() => setOpen(true)}
          className="inline-flex items-center gap-1.5 rounded-md border border-dashed bg-muted/20 px-2.5 py-1 text-[12px] text-muted-foreground hover:border-foreground/40 hover:text-foreground"
        >
          <ReplyIcon className="size-3.5" />
          Reply to thread…
        </button>
      </span>
    );
  }

  return (
    <GhComposer
      variant="inline"
      draftKey={`${owner}/${repo}/${number}:reply:${headId}`}
      placeholder="Reply… (Markdown · ⌘⏎ to send)"
      submitLabel={
        hasPendingReview
          ? 'Add review comment'
          : canAuthorPending
            ? 'Start a review'
            : 'Reply'
      }
      autoFocus
      minHeight={84}
      threadCompose
      onUploadImage={uploadImage}
      mentionContext={{ owner, repo, number }}
      onCancel={() => setOpen(false)}
      onSubmit={canAuthorPending ? replyPending : replySingle}
      secondaryAction={
        canAuthorPending && !hasPendingReview
          ? { label: 'Add single comment', onClick: replySingle }
          : undefined
      }
    />
  );
}

