// Parse the `?pr=` demo deep-link param (AFK plan 22).
//
// Accepts two forms:
//   - `owner/repo/123`
//   - a full GitHub PR URL `https://github.com/<owner>/<repo>/pull/<number>`
//     (also tolerates `/pulls/` and a trailing `/files`, `#discussion`, etc.)
//
// Returns the resolved coordinates or `null` when the value doesn't
// parse — callers treat `null` as "no demo deep-link" and fall through
// to the normal boot path.

export interface ParsedPr {
  owner: string;
  repo: string;
  number: number;
}

// Mirrors the URL regex style the desktop notification deep-link uses
// (Shell.tsx: `/\/repos\/([^/]+)\/([^/]+)\/pulls\/(\d+)/`) — accepts the
// human github.com URL with `pull` or `pulls`.
const PR_URL_RE = /github\.com\/([^/]+)\/([^/]+)\/pulls?\/(\d+)/i;
// Bare `owner/repo/123` form. Owner/repo can't contain a slash; number
// is the trailing segment.
const SHORT_RE = /^([^/\s]+)\/([^/\s]+)\/(\d+)$/;

/** Parse a raw `?pr=` value into PR coordinates, or null when invalid. */
export function parsePrParam(raw: string | null | undefined): ParsedPr | null {
  if (!raw) return null;
  const value = raw.trim();
  if (!value) return null;

  // Full GitHub PR URL (decode first so an encoded `?pr=https%3A%2F%2F…`
  // round-trips). URLSearchParams.get already decodes, but a hand-built
  // link or double-encoding shouldn't break it.
  const urlMatch = value.match(PR_URL_RE);
  if (urlMatch) {
    const number = Number(urlMatch[3]);
    if (Number.isInteger(number) && number > 0) {
      return { owner: urlMatch[1], repo: urlMatch[2], number };
    }
    return null;
  }

  // Bare owner/repo/number form.
  const shortMatch = value.match(SHORT_RE);
  if (shortMatch) {
    const number = Number(shortMatch[3]);
    if (Number.isInteger(number) && number > 0) {
      return { owner: shortMatch[1], repo: shortMatch[2], number };
    }
  }
  return null;
}

/** Read + parse the `?pr=` param from the root URL search string. The
 * demo param is a CONVENTIONAL search param on the root URL (before the
 * hash) so the link stays shareable; the hash router never sees it. */
export function readPrParam(): ParsedPr | null {
  if (typeof window === 'undefined') return null;
  try {
    return parsePrParam(new URLSearchParams(window.location.search).get('pr'));
  } catch {
    return null;
  }
}
