// Main-thread client for the symbol-navigation worker. Singleton; lazily spawns
// the worker on first use. Request/response correlated by reqId.

import SymWorker from './worker?worker';
import type {
  IdentifierRange,
  OutlineSymbol,
  ResolveResult,
  SymLang,
  SymWorkerResponse,
} from './types';

interface Pending {
  resolve: (r: SymWorkerResponse) => void;
  reject: (e: Error) => void;
}

class SymbolNavClient {
  private worker: Worker | null = null;
  private seq = 0;
  private pending = new Map<number, Pending>();

  private ensure(): Worker {
    if (this.worker) return this.worker;
    const worker = new SymWorker({ name: 'symbol-nav' });
    worker.onmessage = (e: MessageEvent<SymWorkerResponse>) => {
      const p = this.pending.get(e.data.reqId);
      if (!p) return;
      this.pending.delete(e.data.reqId);
      p.resolve(e.data);
    };
    // On a fatal worker error, reject every in-flight request AND tear the
    // worker down so the next ensure() respawns a fresh one. Without the
    // terminate+null, ensure() would keep handing back the dead instance and
    // every later request would post into the void (its promise never settling).
    const die = (message: string) => {
      const err = new Error(message);
      this.pending.forEach((p) => p.reject(err));
      this.pending.clear();
      worker.terminate();
      if (this.worker === worker) this.worker = null;
    };
    worker.onerror = (e) => die(e.message || 'symbol-nav worker error');
    worker.onmessageerror = () => die('symbol-nav worker message error');
    this.worker = worker;
    return worker;
  }

  /** Post one request to the worker and await its correlated response. */
  private request(type: string, args: object): Promise<SymWorkerResponse> {
    const reqId = ++this.seq;
    const worker = this.ensure();
    return new Promise<SymWorkerResponse>((resolve, reject) => {
      this.pending.set(reqId, { resolve, reject });
      worker.postMessage({ type, reqId, ...args });
    });
  }

  async resolve(args: {
    lang: SymLang;
    path: string;
    version: string;
    text: string;
    row: number;
    column: number;
  }): Promise<ResolveResult | null> {
    const res = await this.request('resolve', args);
    if (!res.ok) throw new Error(res.error ?? 'resolve failed');
    return res.resolve ?? null;
  }

  async outline(args: {
    lang: SymLang;
    path: string;
    version: string;
    text: string;
  }): Promise<OutlineSymbol[]> {
    const res = await this.request('outline', args);
    if (!res.ok) throw new Error(res.error ?? 'outline failed');
    return res.outline ?? [];
  }

  async identifiers(args: {
    lang: SymLang;
    path: string;
    version: string;
    text: string;
  }): Promise<IdentifierRange[]> {
    const res = await this.request('identifiers', args);
    if (!res.ok) throw new Error(res.error ?? 'identifiers failed');
    return res.identifiers ?? [];
  }
}

export const symbolNav = new SymbolNavClient();
