// Team radar sort — URL slug ⇄ human label, plus the comparator each
// applies within a bucket. 'unblock' (default) surfaces the stalest PRs
// first so the most-overdue reviews lead each section.

import type { RadarSortKey } from '../../router/search';
import { waitDays, type TeamPR } from '../../github/teamLens';
import type { FilterOption } from '../FilterMenu';

export const SORT_LABEL: Record<RadarSortKey, string> = {
  unblock: 'Unblock value',
  oldest: 'Oldest first',
  newest: 'Newest',
  comments: 'Most comments',
  diff: 'Largest diff',
};

/** Sort options for the shared SortButton (value = URL slug). */
export const RADAR_SORT_OPTIONS: FilterOption[] = (
  Object.keys(SORT_LABEL) as RadarSortKey[]
).map((key) => ({ value: key, label: SORT_LABEL[key] }));

const COMPARATORS: Record<RadarSortKey, (a: TeamPR, b: TeamPR) => number> = {
  unblock: (a, b) => waitDays(b.waiting) - waitDays(a.waiting),
  oldest: (a, b) =>
    new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
  newest: (a, b) =>
    new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
  comments: (a, b) => b.comments - a.comments,
  diff: (a, b) => b.additions + b.deletions - (a.additions + a.deletions),
};

export function sortTeamPRs(prs: TeamPR[], key: RadarSortKey): TeamPR[] {
  const cmp = COMPARATORS[key];
  // Bot-authored PRs always sink to the bottom — within each bucket, after
  // bucketing preserves this order — so they stay visible but least-prominent.
  return [...prs].sort(
    (a, b) => Number(a.isBot) - Number(b.isBot) || cmp(a, b),
  );
}
