// Reusable empty-state surface used by every "nothing here" screen
// (Inbox zero, no PRs, filtered-to-nothing, no-token, etc.) and also
// by the auth-error / offline variants which are conceptually the
// same shape with extra structure below the body.
//
// Matches design section 02 (docs/designs/handoff/project/shadcn-app.jsx
// `EmptyState`): centered card icon, semibold title, muted body, optional
// primary + secondary slot. Built on shadcn primitives only — no inline
// theme tokens.

import type { ReactNode } from 'react';
import type { LucideIcon } from 'lucide-react';

export interface EmptyStateProps {
  /** Lucide icon component (e.g. CheckIcon, InboxIcon). */
  icon: LucideIcon;
  /** Tailwind class for the icon stroke. Defaults to muted-foreground. */
  iconClassName?: string;
  title: string;
  /** One short paragraph. Kept under ~180 chars in practice. */
  body?: ReactNode;
  /** Primary action (and any siblings) shown below the body. */
  action?: ReactNode;
  /** Optional second row below action — used by the "filtered" variant
   * to show the active filter chips inline. */
  secondary?: ReactNode;
  className?: string;
}

export function EmptyState({
  icon: Icon,
  iconClassName = 'text-muted-foreground',
  title,
  body,
  action,
  secondary,
  className = '',
}: EmptyStateProps) {
  return (
    <div
      className={`flex flex-1 flex-col items-center justify-center bg-muted/30 p-12 text-center ${className}`}
    >
      <div className="mb-4 inline-flex size-14 items-center justify-center rounded-2xl border bg-background shadow-sm">
        <Icon className={`size-7 ${iconClassName}`} strokeWidth={1.7} />
      </div>
      <h2 className="text-xl font-semibold tracking-tight text-foreground">
        {title}
      </h2>
      {body && (
        <p className="mt-2 max-w-md text-[13px] leading-relaxed text-muted-foreground">
          {body}
        </p>
      )}
      {action && <div className="mt-5 flex items-center gap-2">{action}</div>}
      {secondary && <div className="mt-4">{secondary}</div>}
    </div>
  );
}
