import * as React from "react"
import * as TabsPrimitive from "@radix-ui/react-tabs"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

// Sliding-indicator spring — matches smoothui's animated-tabs feel and
// the UnderlineTabs strip, so every tab surface animates consistently.
const TABS_SPRING = { type: "spring" as const, duration: 0.25, bounce: 0.05 }

const Tabs = TabsPrimitive.Root

type IndicatorRect = {
  left: number
  top: number
  width: number
  height: number
  radius: string
}

type TabsListProps = React.ComponentPropsWithoutRef<typeof TabsPrimitive.List> & {
  /** Renders an animated indicator that slides to the active trigger.
   * 'pill' = filled rounded background (segmented control); 'underline'
   * = a 2px bottom bar. Omit for no indicator (static styling). The
   * active trigger is found from the DOM (`[data-state="active"]`), so
   * this works regardless of how the parent controls Tabs state. */
  indicator?: "pill" | "underline"
}

const TabsList = React.forwardRef<
  React.ElementRef<typeof TabsPrimitive.List>,
  TabsListProps
>(({ className, indicator, children, ...props }, ref) => {
  // React Compiler memoization interferes with motion's layout tracking
  // and the observer effect below; opt this component out.
  "use no memo"
  const innerRef = React.useRef<HTMLDivElement | null>(null)
  const reduce = useReducedMotion()
  const [rect, setRect] = React.useState<IndicatorRect | null>(null)

  const setRefs = React.useCallback(
    (node: HTMLDivElement | null) => {
      innerRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref)
        (ref as React.MutableRefObject<HTMLDivElement | null>).current = node
    },
    [ref],
  )

  // Track the active trigger's box and re-measure when it changes
  // (data-state flips) or the list resizes. Pure DOM measurement keeps
  // the indicator decoupled from how Tabs state is owned.
  React.useLayoutEffect(() => {
    const list = innerRef.current
    if (!list || !indicator) return
    const measure = () => {
      const active = list.querySelector<HTMLElement>('[data-state="active"]')
      if (!active) return
      setRect({
        left: active.offsetLeft,
        top: active.offsetTop,
        width: active.offsetWidth,
        height: active.offsetHeight,
        radius: getComputedStyle(active).borderTopLeftRadius,
      })
    }
    measure()
    const mo = new MutationObserver(measure)
    mo.observe(list, {
      attributes: true,
      subtree: true,
      attributeFilter: ["data-state"],
    })
    const ro = new ResizeObserver(measure)
    ro.observe(list)
    return () => {
      mo.disconnect()
      ro.disconnect()
    }
  }, [indicator])

  return (
    <TabsPrimitive.List
      ref={setRefs}
      className={cn(
        "relative inline-flex h-9 items-center justify-center rounded-lg bg-muted p-1 text-muted-foreground",
        className,
      )}
      {...props}
    >
      {indicator && rect && (
        <motion.span
          aria-hidden
          className={cn(
            "pointer-events-none absolute z-0",
            indicator === "pill" && "bg-background shadow",
            indicator === "underline" && "bg-foreground",
          )}
          initial={false}
          animate={
            indicator === "pill"
              ? {
                  left: rect.left,
                  top: rect.top,
                  width: rect.width,
                  height: rect.height,
                }
              : { left: rect.left, width: rect.width }
          }
          style={
            indicator === "pill"
              ? { borderRadius: rect.radius }
              : { bottom: 0, height: 2 }
          }
          transition={reduce ? { duration: 0 } : TABS_SPRING}
        />
      )}
      {children}
    </TabsPrimitive.List>
  )
})
TabsList.displayName = TabsPrimitive.List.displayName

const TabsTrigger = React.forwardRef<
  React.ElementRef<typeof TabsPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof TabsPrimitive.Trigger>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Trigger
    ref={ref}
    className={cn(
      // relative z-[1] keeps the trigger's content above the sliding
      // indicator (which sits at z-0 in TabsList).
      // [&_svg]:size-3.5 matches the trigger's text scale; mirrors the
      // svg-defaults pattern shadcn ships on Button so call sites
      // don't have to remember to size lucide icons individually.
      "relative z-[1] inline-flex items-center justify-center gap-1.5 whitespace-nowrap rounded-md px-3 py-1 text-sm font-medium ring-offset-background transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow [&_svg]:pointer-events-none [&_svg]:size-3.5 [&_svg]:shrink-0",
      className
    )}
    {...props}
  />
))
TabsTrigger.displayName = TabsPrimitive.Trigger.displayName

const TabsContent = React.forwardRef<
  React.ElementRef<typeof TabsPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof TabsPrimitive.Content>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Content
    ref={ref}
    className={cn(
      "mt-2 ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
      className
    )}
    {...props}
  />
))
TabsContent.displayName = TabsPrimitive.Content.displayName

export { Tabs, TabsList, TabsTrigger }
