// The Changes-pane AI hints bar (ADR 0026 / design hint-* artboards). The
// home for the "Review with AI" trigger and, once hints exist, the filter
// bar (per-type pills + counts), the cost meter, the hide toggle, and re-run.
// Locked when AI is off (discovery path); calm empty state; amber error that
// never blocks plain review. Sits above the rail+diff split.

import { useState } from 'react';
import { Eye, EyeOff, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import {
  AiButton,
  AiCostMeter,
  AiMark,
  AiProgress,
  AiRunState,
  AiSetupAffordance,
  AiTypeIcon,
  AI_HINT_ORDER,
} from '../aikit';
import type { UseAiHints } from './useAiHints';

export function AiHintsBar({
  hints,
  fileCount,
  onSetupAi,
}: {
  hints: UseAiHints;
  fileCount: number;
  onSetupAi?: () => void;
}) {
  const {
    status,
    total,
    countsByType,
    cost,
    capped,
    errorKind,
    retryAfter,
    activeTypes,
    toggleType,
    hiddenFiles,
    setFileHidden,
    run,
    cancel,
  } = hints;

  // Session-local dismissal for the non-progress notice bars (locked / empty /
  // error). The loading bar is never dismissible — it's in-progress.
  const [barDismissed, setBarDismissed] = useState(false);

  if (status === 'locked') {
    if (barDismissed) return null;
    return (
      <div className="flex items-center gap-2 border-b border-border/60 bg-muted/40 px-4 py-2 text-[12px] text-muted-foreground">
        <span className="relative inline-flex">
          <AiMark className="size-3.5 text-muted-foreground" />
        </span>
        <span>Inline review hints are off.</span>
        <AiSetupAffordance size="sm" className="ml-1" onClick={onSetupAi} />
        <DismissButton onClick={() => setBarDismissed(true)} className="ml-auto" />
      </div>
    );
  }

  if (status === 'idle') {
    // No body banner — the "Review with AI" trigger (with its rich tooltip
    // carrying this blurb + the estimate) lives in the Changes header now,
    // next to the commits dropdown.
    return null;
  }

  if (status === 'loading') {
    return (
      <div className="border-b border-border/60 bg-violet-50/30 px-4 py-2">
        <AiProgress label="Reviewing" total={fileCount} capped={capped} onCancel={cancel} />
      </div>
    );
  }

  if (status === 'error') {
    if (barDismissed) return null;
    return (
      <div className="border-b border-border/60 bg-muted/30 px-4 py-3">
        <AiRunState
          kind={errorKind === 'invalid-key' ? 'invalid-key' : errorKind === 'billing' ? 'billing' : errorKind === 'rate-limited' ? 'rate-limited' : errorKind === 'network' ? 'network' : 'overloaded'}
          layout="inline"
          wait={retryAfter ? `${retryAfter}s` : undefined}
          onRetry={run}
          onSetup={onSetupAi}
          onDismiss={() => setBarDismissed(true)}
        />
      </div>
    );
  }

  if (status === 'empty') {
    if (barDismissed) return null;
    return (
      <div className="border-b border-border/60 bg-muted/30 px-4 py-3">
        <AiRunState kind="empty" layout="inline" onDismiss={() => setBarDismissed(true)} />
      </div>
    );
  }

  // ready | stale — the filter bar.
  const allPaths = new Set(hints.hints.map((h) => h.path));
  const allHidden = allPaths.size > 0 && [...allPaths].every((p) => hiddenFiles.has(p));
  const toggleHideAll = () => allPaths.forEach((p) => setFileHidden(p, !allHidden));

  return (
    <div className="flex items-center gap-2 border-b border-border/60 bg-violet-50/40 px-4 py-1.5">
      <span className="inline-flex items-center gap-1.5 text-[12px] font-semibold text-violet-700">
        <AiMark className="size-3.5" />
        {total} hints
      </span>
      {status === 'stale' && (
        <span className="rounded bg-amber-100 px-1.5 py-px text-[10px] font-medium text-amber-700 dark:bg-amber-500/20 dark:text-amber-300">
          diff changed
        </span>
      )}
      <span className="text-muted-foreground/70">·</span>
      <div className="flex items-center gap-1">
        {AI_HINT_ORDER.map((type) => {
          const n = countsByType[type];
          const on = activeTypes.has(type) && n > 0;
          return (
            <button
              key={type}
              type="button"
              disabled={n === 0}
              onClick={() => toggleType(type)}
              className={`inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[11px] font-medium transition-colors ${
                n === 0
                  ? 'cursor-default text-muted-foreground/70'
                  : on
                    ? 'bg-violet-100 text-violet-700'
                    : 'text-muted-foreground hover:bg-accent'
              }`}
              title={type}
            >
              <AiTypeIcon type={type} className="size-3" />
              <span className="tabular-nums">{n}</span>
            </button>
          );
        })}
      </div>
      <div className="ml-auto flex items-center gap-2">
        {cost && <AiCostMeter mode="actual" tokens={cost.tokens} cost={cost.cost} secs={cost.secs} />}
        <button
          type="button"
          onClick={toggleHideAll}
          className="inline-flex items-center gap-1.5 text-[11.5px] font-medium text-muted-foreground hover:text-foreground"
        >
          {allHidden ? <Eye className="size-3.5" /> : <EyeOff className="size-3.5" />}
          {allHidden ? 'Show hints' : 'Hide hints'}
        </button>
        <AiButton variant="outline" size="xs" icon="refresh" onClick={run}>
          Re-run
        </AiButton>
      </div>
    </div>
  );
}

// Shared × for the dismissible notice bars (locked / empty / error). Sized to
// match the bar chrome; callers pass `ml-auto` (single-line) or `mt-0.5`
// (top-aligned beside a multi-line AiRunState card).
function DismissButton({
  onClick,
  className,
}: {
  onClick: () => void;
  className?: string;
}) {
  return (
    <button
      type="button"
      title="Dismiss"
      onClick={onClick}
      className={cn(
        'inline-flex size-5 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-accent hover:text-foreground',
        className,
      )}
    >
      <X className="size-3.5" />
    </button>
  );
}
