export type ConnMode = 'offline' | 'github-down' | 'rate-limit' | 'auth-expired';
export type ConnTone = 'amber' | 'red';

/** A connectivity strip can additionally be in a transient "reconnecting"
 * state (online again, revalidating) which has no failure card. */
export type ConnBarVariant = 'reconnecting' | 'offline' | 'github-down';

