export interface ConnAction {
  label: string;
  icon: LucideIcon;
  /** Where an external fallback points (rendered as a muted suffix). */
  href?: string;
}

export interface ConnModeConfig {
  tone: ConnTone;
  icon: LucideIcon;
  /** Short label for the status-bar dot / inline badge. */
  dotLabel: string;
  /** One-word "whose fault" reassurance chip on the full-screen card. */
  reassure: { tone: ConnTone; text: string };
  full: {
    headline: string;
    explain: string;
    /** Fallback action (the secondary). Primary is built dynamically so
     * the rate-limit countdown can be live. `null` → no secondary (e.g.
     * auth-expired offers only "Sign in again": we don't let the user
     * dismiss into cached browsing; the token must be reset first). */
    fallback: ConnAction | null;
  };
  inline: {
    title: string;
    explain: string;
    fallback: ConnAction;
  };
}

