/** The primary action per mode. Built as a factory because the
 * rate-limit primary is a live, disabled countdown. */
export interface ConnPrimary {
  label: string;
  icon: LucideIcon;
  disabled?: boolean;
  /** Annotated motion intent for the MotionNote pill. */
  motion?: string;
}

export function connPrimary(mode: ConnMode, countdown?: string): ConnPrimary {
  switch (mode) {
    case 'offline':
      return {
        label: 'Retry connection',
        icon: RefreshCwIcon,
        motion: 'spins while retrying',
      };
    case 'github-down':
      return { label: 'Retry', icon: RefreshCwIcon, motion: 'spins while retrying' };
    case 'rate-limit':
      return {
        label: countdown ? `Retry available in ${countdown}` : 'Waiting for reset…',
        icon: ClockIcon,
        disabled: true,
        motion: 'counts down to reset',
      };
    case 'auth-expired':
      return { label: 'Sign in again', icon: KeyRoundIcon };
  }
}

/**
 * Map an arbitrary thrown error + the browser's online state to one of
 * the four connectivity modes, or null when it isn't an outage we model
 * (e.g. a 404 — the caller falls back to a generic "couldn't load").
 *
 * Reuses GitHubError status codes rather than string-matching, per the
 * design handoff. Offline always wins: if the browser says we're offline
 * the error is moot, it's an offline state.
 */
// Map a GitHubError to a connectivity mode by status code.
function classifyGitHubError(err: GitHubError): ConnMode | null {
  if (err.status === 401) return 'auth-expired';
  if (err.status === 403) {
    // 403 is GitHub's rate-limit signal (remaining 0) AND its SSO/
    // permission signal. Prefer the client's authoritative `rateLimited`
    // flag (set at throw time from x-ratelimit-remaining: 0); fall back
    // to the headers/message when an older error didn't carry it.
    // Otherwise it's a credential problem the user must act on.
    const rateLimited =
      err.rateLimited === true ||
      err.rateRemaining === 0 ||
      /rate limit/i.test(err.message);
    return rateLimited ? 'rate-limit' : 'auth-expired';
  }
  if (err.status >= 500 && err.status < 600) return 'github-down';
  // status 0 == fetch never reached a response. Online but no API =
  // GitHub (or the path between us and it) is down.
  if (err.status === 0) return 'github-down';
  return null;
}

export function detectConnMode(
  err: unknown,
  online: boolean = typeof navigator === 'undefined' ? true : navigator.onLine,
): ConnMode | null {
  if (!online) return 'offline';
  if (err instanceof GitHubError) return classifyGitHubError(err);

  // Plain fetch rejection (TypeError) while online → can't reach GitHub.
  if (err instanceof TypeError) return 'github-down';
  const msg = err instanceof Error ? err.message.toLowerCase() : String(err);
  if (
    msg.includes('failed to fetch') ||
    msg.includes('network') ||
    msg.includes('timeout') ||
    msg.includes('timed out')
  ) {
    return 'github-down';
  }
  return null;
}

/** Pull the rate-limit reset timestamp off an error, if it carries one. */
export function rateResetFrom(err: unknown): Date | undefined {
  return err instanceof GitHubError ? err.rateResetAt : undefined;
}
