// Animated collapse primitives — adapted from smoothui (educlopez, MIT)
// basic-accordion's expand/collapse motion, copied in and wired to our
// conventions. The app has many hand-rolled "header row + toggle body"
// surfaces (comment cards, commit rows, gate-check lists, …); these give
// them a consistent smooth height/opacity collapse + a rotating chevron.
//
// `"use no memo"` on the motion components: the project runs React
// Compiler on all src/** (vite.config.ts), whose memoization makes
// AnimatePresence miss the child removal and silently kills the exit
// (close) animation. The directive opts these out so close animates too.

import * as React from "react"
import { ChevronDownIcon } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

type CollapseProps = {
  /** When true the body is expanded; false collapses it (animated). */
  open: boolean
  children: React.ReactNode
  /** Applied to the inner content wrapper (padding/spacing live here, so
   * the height animation measures the real content box). */
  className?: string
}

/** Smoothly expands/collapses its body via height+opacity. Keep this
 * component mounted and just flip `open` — it owns the AnimatePresence so
 * the collapse animation plays on the way out too. */
function Collapse({ open, children, className }: CollapseProps) {
  "use no memo"
  const reduce = useReducedMotion()
  return (
    <AnimatePresence initial={false}>
      {open && (
        <motion.div
          className="overflow-hidden"
          initial={
            reduce ? { height: "auto", opacity: 1 } : { height: 0, opacity: 0 }
          }
          animate={
            reduce
              ? { height: "auto", opacity: 1 }
              : {
                  height: "auto",
                  opacity: 1,
                  transition: {
                    height: { type: "spring", stiffness: 500, damping: 40 },
                    opacity: { duration: 0.2 },
                  },
                }
          }
          exit={
            reduce
              ? { height: 0, opacity: 0, transition: { duration: 0 } }
              : {
                  height: 0,
                  opacity: 0,
                  transition: {
                    height: { duration: 0.2 },
                    opacity: { duration: 0.15 },
                  },
                }
          }
        >
          <div className={className}>{children}</div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

type CollapseChevronProps = {
  /** Rotates the chevron 180° when true. */
  open: boolean
  className?: string
}

/** A down-chevron that rotates to point up when `open`. Replaces the
 * app's manual ChevronUp/ChevronDown icon swaps so the affordance turns
 * smoothly instead of snapping. */
function CollapseChevron({ open, className }: CollapseChevronProps) {
  "use no memo"
  const reduce = useReducedMotion()
  return (
    <motion.span
      className="inline-flex shrink-0"
      animate={{ rotate: open ? 180 : 0 }}
      transition={{ duration: reduce ? 0 : 0.2 }}
    >
      <ChevronDownIcon className={cn("size-4", className)} />
    </motion.span>
  )
}

export { Collapse, CollapseChevron }
