// The one "refetching in the background" indicator. Every list whose
// React Query key changes on user interaction (filter, scope, search)
// keeps the prior rows in place via `placeholderData: (prev) => prev`
// and renders this thin pulsing bar above them so the stale-then-fresh
// swap reads as a deliberate update rather than a flash.
//
// Always rendered (opacity toggles), so flipping `active` never shifts
// layout. Decorative — `aria-hidden`. The bar is `h-px bg-primary` by
// default; pass `className` for surface tweaks (e.g. `w-full
// rounded-full` inside a card header).
//
// Two layers on purpose: the wrapper owns the opacity fade (always-on
// transition, so toggling `active` cross-fades over 500ms instead of
// snapping), while an inner layer owns the pulse. Keeping them separate
// stops the fade's duration from speeding up the pulse and stops the
// pulse keyframes from pre-empting the fade-out.

import { cn } from '@/lib/utils';

export function FetchingBar({
  active,
  className,
}: {
  /** True while a background refetch is in flight (e.g. a query's
   *  `isPlaceholderData`, or `isFetching && !isPending`). */
  active: boolean;
  className?: string;
}) {
  return (
    <div
      aria-hidden
      className={cn(
        'h-px shrink-0 overflow-hidden transition-opacity duration-500 ease-out',
        active ? 'opacity-100' : 'opacity-0',
        className,
      )}
    >
      <div className={cn('size-full bg-primary', active && 'animate-pulse')} />
    </div>
  );
}
