// TanStack hooks over the LocalReview localStorage store. Wraps the
// synchronous CRUD in `localReviews.ts` so screens get reactive
// re-renders when reviews are added / removed, and so cross-screen
// observers (Local Reviews list + the active surface) stay in sync
// through query invalidation.
//
// The `cross-tab storage event` is also wired here — when the same
// app runs in multiple Electron BrowserWindows (or in two browser
// tabs in the web build), edits in one window propagate to the others
// via the standard `storage` event.

import {
  useMutation,
  useQuery,
  useQueryClient,
  type UseQueryResult,
} from '@tanstack/react-query';
import { useEffect } from 'react';
import {
  createLocalReview,
  deleteLocalReview,
  listLocalReviews,
  softDeleteLocalReviewsForRepo,
  type LocalReview,
} from './localReviews';
import { bridge } from '../desktop/electronBridge';

const LIST_KEY = ['local-reviews'] as const;

export function useLocalReviewsList(): UseQueryResult<LocalReview[]> {
  const qc = useQueryClient();
  // Cross-tab/window sync: localStorage `storage` events fire in
  // OTHER windows when a key changes. Invalidate the query so the
  // list re-renders with the latest state.
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === 'pyor:local-reviews' || e.key === null) {
        void qc.invalidateQueries({ queryKey: LIST_KEY });
      }
    };
    window.addEventListener('storage', onStorage);
    return () => window.removeEventListener('storage', onStorage);
  }, [qc]);
  return useQuery({
    queryKey: LIST_KEY,
    queryFn: () => listLocalReviews(),
    // Reads are sync + cheap; no need for refetchInterval / staleTime
    // tuning. The mutations + storage events keep things current.
    staleTime: Infinity,
  });
}

export function useCreateLocalReview() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (input: Parameters<typeof createLocalReview>[0]) =>
      Promise.resolve(createLocalReview(input)),
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: LIST_KEY });
    },
  });
}

export function useDeleteLocalReview() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => Promise.resolve(deleteLocalReview(id)),
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: LIST_KEY });
    },
  });
}

/** Remove a repo from the Pyor registry. Cascades into the saved
 * LocalReviews for that repo: each is soft-deleted (status badge flips
 * to "Deleted", the row's click handler is disabled) rather than
 * destroyed, so the user can see the history and decide whether to
 * delete-for-real with the existing per-row Delete action.
 *
 * The soft-delete runs BEFORE the registry write so the cascade
 * completes even if the bridge call fails mid-flight (the user still
 * gets the right list-page state). Returns the count of newly soft-
 * deleted reviews so the caller can show "Removed N reviews" UI. */
export function useRemoveLocalRepo() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (repoPath: string) => {
      const softDeletedCount = softDeleteLocalReviewsForRepo(repoPath);
      const b = bridge();
      if (b) await b.localRepoRemove(repoPath);
      return { repoPath, softDeletedCount };
    },
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: LIST_KEY });
      void qc.invalidateQueries({ queryKey: ['local-repo-list'] });
      void qc.invalidateQueries({ queryKey: ['local-worktree-count'] });
    },
  });
}
