// The GitHub-bound `onUploadImage` strategy (ADR 0018 §4). Wire this into
// every GitHub comment surface (PR description, top-level comments, both
// inline-thread reply/edit composers). It gates on the one-time public-
// repo consent, ensures `<viewer>/pyor-assets` exists, then commits the
// image and returns its stable raw URL.
//
// Local Review surfaces use a different strategy (localReviewUploader,
// pyor-attachment://) — never this one.

import { useCallback } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getViewer } from '../../../github/client';
import type { Viewer } from '../../../github/types';
import { ensurePierAssetsRepo, uploadAssetImage } from '../../../github/assets';
import { useAssetsConsent } from './AssetsConsentProvider';

/**
 * Returns a stable `onUploadImage(file) => url` to pass straight to
 * `GhComposer`. Throws {@link UploadCancelled} when the user declines the
 * consent dialog (the composer drops the placeholder silently), and a
 * real error on any API failure (the composer toasts).
 */
export function useGithubAssetsUploader(): (file: File) => Promise<string> {
  const { requestConsent } = useAssetsConsent();
  // The viewer is fetched once on launch and cached under ['viewer'];
  // reading it here is a cache hit, so we don't refetch per composer.
  const viewerQuery = useQuery<Viewer>({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: Infinity,
  });

  return useCallback(
    async (file: File): Promise<string> => {
      const login = viewerQuery.data?.login;
      if (!login) {
        throw new Error('Not signed in — can’t upload attachments.');
      }
      // Consent is requested INSIDE ensure — and only when the assets repo
      // doesn't yet exist. An existing repo means prior consent, so the
      // modal never reappears (even on a new device / cleared storage).
      await ensurePierAssetsRepo(login, requestConsent);
      return uploadAssetImage(login, file);
    },
    [requestConsent, viewerQuery.data?.login],
  );
}
