// useResolveThread — shared resolve/unresolve mutation for review
// threads, used by the shared ReviewThread component (rendered on both
// the Changes tab and the Conversation tab).
//
// Both surfaces derive a thread's resolution from the SAME query: the
// `threadIds` GraphQL list (prThreadsOptions). The Changes tab folds
// it into a CommentThread via buildThreadIndex; the Conversation tab
// reads it directly. So one optimistic patch on that query cache
// updates every surface at once — no per-surface bookkeeping.
//
// The mutation:
//   1. Snapshot the threadIds cache.
//   2. Optimistically flip isResolved / resolvedBy / viewerCan* on the
//      matching thread node so the footer + badge update instantly.
//   3. Fire resolveReviewThread / unresolveReviewThread.
//   4. Roll back + toast on error.
//   5. Invalidate on success so the server's authoritative resolvedBy
//      (and any parallel reactor changes) reconcile on the next read.

import { useCallback } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  resolveReviewThread,
  unresolveReviewThread,
  type ResolvableThread,
} from '../github/client';
import { prThreadsOptions } from '../github/prQueries';

export type ToggleResolved = (args: {
  /** GraphQL node id of the thread (CommentThread.graphqlNodeId). */
  graphqlNodeId: string;
  /** Whether to resolve (true) or unresolve (false). */
  resolve: boolean;
  /** Viewer login — used to fill the optimistic `resolvedBy` so the
   * footer reads "{you} marked this resolved" before the refetch. */
  viewerLogin?: string;
}) => Promise<void>;

export function useResolveThread(
  owner?: string,
  repo?: string,
  number?: number,
): ToggleResolved {
  const qc = useQueryClient();
  return useCallback(
    async ({ graphqlNodeId, resolve, viewerLogin }) => {
      if (!owner || !repo || !number) return;
      const key = prThreadsOptions(owner, repo, number).queryKey;
      const snapshot = qc.getQueryData<ResolvableThread[]>(key);
      // Optimistically flip the matching thread. The viewer just
      // performed the action, so they're permitted to do the inverse
      // next — swap the can-resolve / can-unresolve flags accordingly.
      qc.setQueryData<ResolvableThread[]>(key, (curr) =>
        curr?.map((t) =>
          t.id === graphqlNodeId
            ? {
                ...t,
                isResolved: resolve,
                resolvedBy: resolve ? (viewerLogin ?? t.resolvedBy) : null,
                viewerCanResolve: !resolve,
                viewerCanUnresolve: resolve,
              }
            : t,
        ),
      );
      try {
        if (resolve) {
          await resolveReviewThread(graphqlNodeId);
        } else {
          await unresolveReviewThread(graphqlNodeId);
        }
        // Reconcile resolvedBy + any parallel updates from the server.
        void qc.invalidateQueries({ queryKey: key });
      } catch (e) {
        qc.setQueryData<ResolvableThread[]>(key, snapshot);
        toast.error(
          resolve ? 'Could not resolve thread' : 'Could not unresolve thread',
          { description: e instanceof Error ? e.message : String(e) },
        );
        throw e;
      }
    },
    [qc, owner, repo, number],
  );
}
