// DateRangeChip — popover-backed "Updated within" filter chip.
//
// Shared by the Inbox Comments toolbar and the Pull-requests tabs bar.
// Renders four presets (24h / 7d / 30d / All time); custom range UI
// shows a mini calendar for visual context but the data path is a
// single `since: ISO` string the caller translates into its query
// language (`updated:>YYYY-MM-DD` for GraphQL search, `?since=` for
// REST). Spec lives in design's inbox-comments.jsx → DateRangeChip.

import { CalendarIcon, ChevronDownIcon } from 'lucide-react';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { cn } from '@/lib/utils';

export type DateRangePreset = '24h' | '7d' | '30d' | 'all';

const DATE_RANGE_LABELS: Record<DateRangePreset, string> = {
  '24h': 'Last 24 hours',
  '7d': 'Last 7 days',
  '30d': 'Last 30 days',
  all: 'All time',
};

/** Convert a preset to an ISO `since:` string. `'all'` returns null —
 * the caller drops the filter from its query.
 *
 * Snaps to UTC midnight so two consecutive calls within the same day
 * return the same string. Critical for TanStack queryKey stability:
 * `presetToSinceISO('7d')` is used inside `useInfiniteQuery`'s key, so
 * any drift causes a cache miss on remount and re-shows the loading
 * skeleton. The user-facing GraphQL token is `updated:>YYYY-MM-DD`
 * anyway — sub-day precision was never needed. */
export function presetToSinceISO(preset: DateRangePreset): string | null {
  if (preset === 'all') return null;
  const days = preset === '24h' ? 1 : preset === '7d' ? 7 : 30;
  const now = new Date();
  const utcMidnight = Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate() - days,
  );
  return new Date(utcMidnight).toISOString();
}

interface DateRangeChipProps {
  value: DateRangePreset;
  onChange: (v: DateRangePreset) => void;
  /** Optional per-preset count overlay shown to the right of each
   * preset label. Used by the Inbox Comments toolbar; the Pulls
   * variant typically passes nothing. */
  counts?: Partial<Record<DateRangePreset, number>>;
  /** Controlled-open hook so the parent can drive screenshot variants
   * (matches the design's `dateRangeOpen: true` view prop). */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function DateRangeChip({
  value,
  onChange,
  counts,
  open,
  onOpenChange,
}: DateRangeChipProps) {
  const active = value !== 'all';
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="xs"
          className={cn(
            'gap-1.5 px-2.5 text-[12px] font-medium',
            active
              ? 'border-primary bg-primary text-primary-foreground hover:bg-primary/90 hover:text-primary-foreground'
              : 'border-border bg-background text-foreground',
          )}
        >
          <CalendarIcon className="size-3" />
          Date range
          <span className={active ? 'text-primary-foreground/70' : 'text-muted-foreground'}>:</span>
          <span>{DATE_RANGE_LABELS[value]}</span>
          <ChevronDownIcon className="size-3 opacity-60" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-[340px] p-0">
        <div className="px-3 py-2.5">
          <div className="mb-2 text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
            Updated within
          </div>
          <div className="grid grid-cols-2 gap-1.5">
            {(['24h', '7d', '30d', 'all'] as DateRangePreset[]).map((p) => {
              const isActive = p === value;
              return (
                <button
                  key={p}
                  type="button"
                  onClick={() => {
                    onChange(p);
                    onOpenChange?.(false);
                  }}
                  className={cn(
                    'flex items-center justify-between rounded-md border px-2.5 py-1.5 text-[12px] font-medium transition-colors',
                    isActive
                      ? 'border-primary bg-primary text-primary-foreground'
                      : 'border-border bg-background text-foreground hover:bg-accent',
                  )}
                >
                  <span>{DATE_RANGE_LABELS[p]}</span>
                  {counts?.[p] != null && (
                    <span
                      className={cn(
                        'tabular-nums text-[10.5px]',
                        isActive ? 'text-primary-foreground/70' : 'text-muted-foreground',
                      )}
                    >
                      {counts[p]}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        </div>
        <Separator />
        <div className="px-3 py-2.5">
          <div className="mb-1.5 flex items-center justify-between">
            <div className="text-[10.5px] font-semibold uppercase tracking-wider text-muted-foreground">
              Custom range
            </div>
            <span className="text-[10.5px] text-muted-foreground">
              {monthLabel(new Date())}
            </span>
          </div>
          <MiniCalendar preset={value} />
          <div className="mt-2 text-[10px] text-muted-foreground">
            Custom date pickers arrive with saved-search support in v2 —
            today the presets above drive the `since:` query.
          </div>
        </div>
        <Separator />
        <div className="flex items-center gap-2 bg-muted/40 px-3 py-2 text-[11px] text-muted-foreground">
          <code className="font-mono text-[10.5px]">
            {presetToSinceISO(value)?.slice(0, 10) ?? 'no filter'}
          </code>
          <Button
            variant="ghost"
            size="sm"
            className="ml-auto h-6 px-2 text-[11.5px]"
            onClick={() => {
              onChange('all');
              onOpenChange?.(false);
            }}
          >
            Clear
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

// ── MiniCalendar ───────────────────────────────────────────────
// Visual current-month grid with the preset's resolved `since` →
// today range tinted. Read-only — clicks are no-ops (custom range
// picker is v2). Matches the design's calendar visual in
// inbox-comments.jsx → MiniCalendar.
function MiniCalendar({ preset }: { preset: DateRangePreset }) {
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth(); // 0-11
  const sinceISO = presetToSinceISO(preset);
  const since = sinceISO ? new Date(sinceISO) : null;
  // Build a 7-col grid for the current month.
  const firstOfMonth = new Date(year, month, 1);
  const padDays = firstOfMonth.getDay(); // Sun = 0
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells: ({ day: number } | { pad: true })[] = [];
  for (let i = 0; i < padDays; i++) cells.push({ pad: true });
  for (let d = 1; d <= daysInMonth; d++) cells.push({ day: d });
  const inRange = (day: number): boolean => {
    if (!since) return false;
    const d = new Date(year, month, day);
    return d >= since && d <= today;
  };
  return (
    <div className="text-[10.5px] text-muted-foreground">
      <div className="mb-1 grid grid-cols-7 gap-0.5 text-center font-medium text-muted-foreground/70">
        {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((d, i) => (
          <span key={i}>{d}</span>
        ))}
      </div>
      <div className="grid grid-cols-7 gap-0.5">
        {cells.map((c, i) => {
          if ('pad' in c) return <span key={i} />;
          const isToday = c.day === today.getDate();
          const range = inRange(c.day);
          return (
            <span
              key={i}
              className={cn(
                'inline-flex h-6 items-center justify-center rounded-md text-[11px] font-medium tabular-nums',
                isToday
                  ? 'bg-primary text-primary-foreground'
                  : range
                    ? 'bg-accent text-foreground'
                    : 'text-muted-foreground/80',
              )}
            >
              {c.day}
            </span>
          );
        })}
      </div>
    </div>
  );
}

const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

function monthLabel(d: Date): string {
  return `${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}
