// The compact filter toolbar under the tab bar — org segmented control,
// author multi-select, result count, Clear-scope, Filters + Sort.

import { XIcon } from 'lucide-react';
import { Separator } from '@/components/ui/separator';
import type { TeamOrg } from '../../github/teamLens';
import { FiltersButton, SortButton, type FilterOption } from '../FilterMenu';
import { OrgSegmented } from './OrgSegmented';
import { AuthorMultiSelect } from './AuthorMultiSelect';
import {
  RADAR_FILTER_FIELDS,
  SEC_NON_ACTIVE,
  type SecField,
  type SecOption,
  type SecValues,
} from './RadarFilters';
import { RADAR_SORT_OPTIONS } from './radarSort';

export function RadarFilterBar({
  orgs,
  org,
  onOrgChange,
  authorList,
  authors,
  you,
  onToggleAuthor,
  onClearAuthors,
  anyScope,
  onClearScope,
  filteredCount,
  totalCount,
  sortKey,
  onPickSort,
  secValues,
  secOptions,
  onSecChange,
  onSecReset,
}: {
  orgs: TeamOrg[];
  org: string;
  onOrgChange: (key: string) => void;
  authorList: string[];
  authors: Set<string>;
  you: string;
  onToggleAuthor: (login: string) => void;
  onClearAuthors: () => void;
  anyScope: boolean;
  onClearScope: () => void;
  filteredCount: number;
  totalCount: number;
  sortKey: string;
  onPickSort: (slug: string) => void;
  secValues: SecValues;
  secOptions: Record<SecField, SecOption[]>;
  onSecChange: (field: SecField, value: string) => void;
  onSecReset: () => void;
}) {
  return (
    <div className="flex items-center gap-3 border-b border-border bg-muted/30 px-5 py-2">
      <div className="flex items-center gap-2">
        <span className="text-[10.5px] font-semibold uppercase tracking-wide text-muted-foreground">
          Org
        </span>
        <OrgSegmented orgs={orgs} value={org} onChange={onOrgChange} />
      </div>
      <Separator orientation="vertical" className="h-6" />
      <AuthorMultiSelect
        authors={authorList}
        selected={authors}
        you={you}
        onToggle={onToggleAuthor}
        onClear={onClearAuthors}
      />
      <div className="ml-auto flex items-center gap-2.5">
        {anyScope && (
          <button
            type="button"
            onClick={onClearScope}
            className="inline-flex items-center gap-1 text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground"
          >
            <XIcon className="size-3" />
            Clear scope
          </button>
        )}
        <span className="text-[11.5px] text-muted-foreground">
          <span className="tabular-nums font-medium text-foreground">
            {filteredCount}
          </span>{' '}
          of {totalCount}
        </span>
        <Separator orientation="vertical" className="h-6" />
        <FiltersButton
          fields={RADAR_FILTER_FIELDS}
          values={secValues}
          options={secOptions as Record<string, FilterOption[]>}
          defaults={SEC_NON_ACTIVE}
          onChange={(k, v) => onSecChange(k as SecField, v)}
          onReset={onSecReset}
        />
        <SortButton
          options={RADAR_SORT_OPTIONS}
          value={sortKey}
          onChange={onPickSort}
        />
      </div>
    </div>
  );
}
