// Renderer-side wrapper around the Electron preload bridge exposed
// in /desktop/src/preload.ts as `window.pyor`. Centralises the
// `isElectron()` check + types so callers don't have to repeat
// the `window.pyor?.…` dance and don't need to know the bridge
// shape.
//
// Web build hits the `null` branches and behaves as if no Electron
// is present — no runtime errors when this loads in the browser.

// Local-repo types — mirrored from /desktop/src/preload.ts.
export interface LocalRepo {
  path: string;
  name: string;
  currentBranch: string | null;
  dirty: boolean;
}
export interface DiscoveredRepo {
  /** Absolute path to the repo root. */
  path: string;
  /** owner/name from origin slug if available, else the basename. */
  name: string;
  /** Current HEAD branch, null when detached. */
  currentBranch: string | null;
  /** True when the working tree has unstaged or staged changes. */
  dirty: boolean;
}
export interface LocalBranch {
  name: string;
  sha: string;
  isHead: boolean;
  /** ISO-8601 committer date of the branch tip (sort + age label). */
  date: string;
}
export interface LocalWorktree {
  /** Absolute path to this worktree on disk. */
  path: string;
  /** SHA the worktree's HEAD points at. */
  head: string;
  /** Branch currently checked out, or null when detached. */
  branch: string | null;
  /** True for the repo's main worktree. */
  isMain: boolean;
}
export interface LocalDiffFile {
  path: string;
  status: 'added' | 'modified' | 'deleted' | 'renamed' | 'copied';
  previousPath?: string;
  patch: string | null;
  additions: number;
  deletions: number;
  /** True when git's `--numstat` reported the file as binary
   * (`-\t-`). The renderer skips the `git show` content fetch for
   * these — a binary blob through IPC easily reaches 16 MB and
   * blocks the UI. Surfaces as a "binary file" placeholder. */
  isBinary?: boolean;
}
export interface LocalDiff {
  head: string;
  base: string;
  /** Real merge-base SHA between `base` and `head` — the point the
   * THREE-DOT `git diff base...head` anchors against (falls back to
   * `base` when git merge-base fails). The renderer anchors OLD-side
   * blob reads here so they match what the diff shows. */
  mergeBase: string;
  files: LocalDiffFile[];
}

/** Validation outcome from the split add-repo flow. The renderer renders
 * a shadcn Dialog per kind. Mirrors `/desktop/src/preload.ts`. */
export type LocalRepoValidation =
  | { kind: 'valid'; path: string; meta: LocalRepo; suggestedBase: string | null }
  | { kind: 'not-git'; path: string }
  | { kind: 'no-base'; path: string; meta: LocalRepo };

/** Default browser + its Pyor Helper store target (ADR 0024) for the
 * first-run nudge. `supported:false` (Safari/unknown) → no nudge. Mirrors
 * `/desktop/src/preload.ts`. */
type HelperBrowserGlyph =
  | 'chrome'
  | 'chromium'
  | 'edge'
  | 'brave'
  | 'vivaldi'
  | 'opera'
  | 'arc'
  | 'firefox'
  | 'zen';

interface HelperBrowserInfo {
  supported: boolean;
  name: string;
  glyph: HelperBrowserGlyph;
  store: string;
  url: string;
}

interface PyorBridge {
  keychainGet(): Promise<string | null>;
  keychainSet(token: string): Promise<boolean>;
  keychainClear(): Promise<boolean>;
  /** ADR 0026 — AI provider keys in the OS keychain (via safeStorage),
   * one entry per provider. Separate from the GitHub token so each can be
   * cleared independently. Optional on the type so a web build (or an older
   * desktop build) falls back to localStorage in aiKeyStore. */
  aiKeyGet?(provider: 'anthropic' | 'openai'): Promise<string | null>;
  aiKeySet?(provider: 'anthropic' | 'openai', key: string): Promise<boolean>;
  aiKeyClear?(provider: 'anthropic' | 'openai'): Promise<boolean>;
  notify(opts: {
    title: string;
    body: string;
    threadId?: string;
  }): Promise<boolean>;
  onNotificationClick(handler: (threadId: string) => void): () => void;
  /** Silent-auto-update platforms (Win/Linux-AppImage): an update was
   * downloaded and is ready to install via `quitAndInstall`. */
  onUpdateDownloaded(handler: () => void): () => void;
  /** Update Notifier platforms (macOS + Linux .deb, ADR 0023): a newer
   * version exists; the payload is its version string. No in-place
   * install — the renderer prompts a manual re-download. */
  onUpdateAvailable(handler: (version: string) => void): () => void;
  /** Running app version, for the Settings version row. */
  appVersion(): Promise<string>;
  /** Manual "Check for updates" — see preload.ts for the result shape. */
  checkForUpdates(): Promise<
    | { channel: 'auto' }
    | { channel: 'notifier'; available?: boolean; version?: string }
  >;
  /** Relaunch into the downloaded update (silent platforms only). */
  quitAndInstall(): Promise<void>;
  /** macOS silent self-update (ADR 0023 amendment): a newer version was
   * downloaded + staged and applies automatically on quit. Payload = version. */
  onUpdateStaged(handler: (version: string) => void): () => void;
  /** "Restart now" — apply the staged update immediately + relaunch. */
  applyUpdate(): Promise<{ ok: boolean }>;
  /** Live background-update progress (all platforms) for the in-app bar. */
  onUpdateProgress(
    handler: (p: {
      phase: 'download' | 'install' | 'error';
      percent: number;
    }) => void,
  ): () => void;
  /** Open a URL in the user's real browser (GitHub authorize, Polar
   * checkout). On web this path isn't used — see desktop/openExternal.ts. */
  openExternal(url: string): Promise<void>;
  /** Fetch a private GitHub comment-attachment's bytes in the main process
   * (no CORS; the token can't ride on an <img>). Desktop deliberately keeps
   * these OFF the api — the web build proxies via `/img`, but on desktop
   * repo content never reaches the backend. See web/src/github/attachments.ts. */
  fetchRemoteAttachment(
    url: string,
    token: string | null,
  ): Promise<{ bytes: ArrayBuffer; mime: string }>;
  /** ADR 0024 — the OS default browser + its Pyor Helper store listing,
   * for the desktop first-run nudge. */
  helperDefaultBrowser(): Promise<HelperBrowserInfo>;
  /** ADR 0019 — `pyor://` OAuth callback delivered to the renderer. */
  onDeepLink(handler: (url: string) => void): () => void;
  localRepoList(): Promise<LocalRepo[]>;
  localRepoAdd(): Promise<LocalRepo | null>;
  /** Split add — step 1. Native folder picker; returns the chosen path
   * (or null on cancel). No validation, no registry write. */
  localRepoPickFolder(): Promise<string | null>;
  /** Split add — step 2. Classify the folder as 'valid'/'not-git'/'no-base'. */
  localRepoValidate(path: string): Promise<LocalRepoValidation>;
  /** Split add — step 3. Persist the validated path to the registry. */
  localRepoRegister(path: string): Promise<LocalRepo | null>;
  /** Walk a folder for git repos. If the folder IS a repo, returns just
   * it; otherwise BFS-walks subdirectories (capped at depth 4, 50
   * results). Used by the Add-repo flow's multi-repo detection. */
  localRepoDiscoverInFolder(folderPath: string): Promise<DiscoveredRepo[]>;
  localRepoRemove(p: string): Promise<boolean>;
  localRepoBranches(p: string): Promise<LocalBranch[]>;
  /** Enumerate worktrees attached to a repo (main first, then linked). */
  localRepoWorktrees(p: string): Promise<LocalWorktree[]>;
  localRepoDiff(p: string, base: string, head: string): Promise<LocalDiff>;
  /** `git show <ref>:<filePath>` — raw contents at a given ref, or null
   * if the path doesn't exist there. Feeds @pierre/diffs's old + new
   * content inputs in the Pre-PR Review surface. */
  localRepoShow(p: string, ref: string, filePath: string): Promise<string | null>;
  /** Batch `git show <ref>:<path>` for many files in one IPC round-trip
   * (bounded concurrency pool in main). Returns a `{ path: contents }`
   * map; a file absent at the ref / too big / binary is `null`. The
   * OLD-side blob source for the Pre-PR Review diff pipeline. */
  localRepoBatchShow(
    repoPath: string,
    ref: string,
    paths: string[],
  ): Promise<Record<string, string | null>>;
  /** Batch working-tree read (`fs.readFile`) for many files in one IPC
   * round-trip. Returns a `{ path: contents }` map; missing / too big /
   * binary / path-traversal → `null`. The NEW-side source for the
   * Pre-PR Review diff pipeline when diffing against the working tree. */
  localRepoBatchReadWorktree(
    worktreePath: string,
    paths: string[],
  ): Promise<Record<string, string | null>>;
  /** Batch unified patch — ONE `git diff` split per-file by new path.
   * `newRef` null → diff the working tree; `paths` null → whole repo.
   * Returns a `{ newPath: patch }` map; a chunk with no `@@` hunk (pure
   * rename / mode-only) → `null`. Feeds buildDiff's git-native patch
   * path (`processFile`). */
  localRepoBatchDiff(
    repoPath: string,
    oldRef: string,
    newRef: string | null,
    paths: string[] | null,
    opts: { ignoreWhitespace?: boolean },
  ): Promise<Record<string, string | null>>;
  /** ADR 0012 Phase 4 — read a file from the worktree's working copy
   * (live filesystem, not a git ref). Used by the staleness algorithm
   * for WORKING_TREE-anchored comments. Returns null if the path
   * doesn't exist on disk. Rejects path-traversal attempts. */
  localRepoReadWorktreeFile(
    worktreePath: string,
    relPath: string,
  ): Promise<string | null>;
  /** Read a local image file's bytes as a base64 `data:` URL for
   * offline image preview. `ref` null → the working-tree file (path-
   * traversal hardened); a string → `git show <ref>:<relPath>`. Returns
   * null when the path is missing / too big (>8 MB) / git fails. */
  localRepoReadImage(
    repoPath: string,
    ref: string | null,
    relPath: string,
  ): Promise<string | null>;
  localRepoOpenCreatePR(
    p: string,
    branch: string,
    base: string,
  ): Promise<boolean>;
  /** ADR 0012 Phase 2 — working-tree (uncommitted) file list against
   * HEAD. Same shape as `localRepoDiff().files`. */
  localRepoWorkingTreeDiff(worktreePath: string): Promise<LocalDiffFile[]>;
  /** ADR 0012 Phase 7 — cheap ahead/behind counts between `base` and
   * `head`. Used by the Local Reviews list status hook to drive the
   * `stale` badge (behind > 0) and the row-displayed counts. */
  localRepoAheadBehind(
    repoPath: string,
    base: string,
    head: string,
  ): Promise<{ ahead: number; behind: number }>;
  /** ADR 0012 Phase 7 — `owner/name` slug from the repo's `origin`
   * remote. Returns null when origin is missing or the URL isn't a
   * GitHub pattern we recognise; the row hook then skips PR detection. */
  localRepoOriginSlug(repoPath: string): Promise<string | null>;
  /** Commits between `base..head` (newest-first, capped at `limit`,
   * default 50). Drives the launcher's "Commits to review" preview. */
  localRepoCommits(
    repoPath: string,
    base: string,
    head: string,
    limit?: number,
  ): Promise<
    {
      sha: string;
      subject: string;
      ago: string;
      additions: number;
      deletions: number;
    }[]
  >;
  /** ADR 0012 Phase 8 — true when `branch` exists on the `origin`
   * remote. Drives the review surface's pushed-state CTA so it stops
   * proxying off PR existence. */
  localRepoBranchOnOrigin(p: string, branch: string): Promise<boolean>;
  /** Open the worktree path in the user's preferred terminal. macOS:
   * iTerm if installed, else Terminal.app; other platforms: Finder. */
  localRepoOpenInTerminal(path: string): Promise<string | null>;
  /** Open a chokidar watcher rooted at the worktree path. Returns an
   * opaque handle id; pair with `localRepoUnwatch` on unmount. */
  localRepoWatch(worktreePath: string): Promise<string>;
  /** Close a watcher opened by `localRepoWatch`. */
  localRepoUnwatch(handleId: string): Promise<boolean>;
  /** Subscribe to debounced (200ms) filesystem-change events. The
   * payload carries the originating watcher's handle id so multiple
   * surfaces can multiplex onto a single listener. */
  onLocalRepoChange(
    handler: (payload: { handleId: string; path: string }) => void,
  ): () => void;
  /** ADR 0012 Phase 5 — persist a pasted image as an attachment on
   * disk. Returns the generated filename so the renderer can compose
   * the `pyor-attachment://<reviewId>/<commentId>/<filename>` URL it
   * embeds in the comment body. */
  localReviewAttachmentSave(
    reviewId: string,
    commentId: string,
    mime: string,
    bytes: ArrayBuffer,
  ): Promise<{ filename: string }>;
  /** ADR 0012 Phase 5 — read a saved attachment back as a `data:` URL
   * (null if missing / invalid). */
  localReviewAttachmentRead(
    reviewId: string,
    commentId: string,
    filename: string,
  ): Promise<string | null>;
  /** ADR 0012 Phase 5 — sweep attachment storage. With `commentId`,
   * removes just that comment's dir. Without, sweeps the entire
   * review's dir. Idempotent. */
  localReviewAttachmentDelete(
    reviewId: string,
    commentId?: string,
  ): Promise<boolean>;
  /** ADR 0012 Phase 6 — open a native folder picker for the export
   * bundle's *parent* directory. Returns the absolute path or null on
   * cancel. */
  localReviewPickExportParent(): Promise<string | null>;
  /** ADR 0012 Phase 6 — write the LLM-export bundle to disk. The
   * renderer pre-renders the three text artefacts (so generation stays
   * pure); main does the dir creation, file writes, and recursive copy
   * of the attachments source dir. Returns the absolute bundle path. */
  localReviewExport(args: {
    reviewId: string;
    bundleDirName: string;
    parentDir: string;
    commentsMarkdown: string;
    commentsJson: string;
    readme: string;
  }): Promise<string>;
  /** ADR 0012 Phase 6 — reveal a path in Finder / Explorer (used to
   * land the user on a freshly-written export bundle). */
  shellReveal(absolutePath: string): Promise<boolean>;
  readonly isElectron: true;
  /** Same string Node's `process.platform` returns; we type as a
   * union here so we don't need to pull in @types/node into the web
   * bundle just for this. */
  readonly platform:
    | 'aix'
    | 'darwin'
    | 'freebsd'
    | 'linux'
    | 'openbsd'
    | 'sunos'
    | 'win32'
    | 'cygwin'
    | 'netbsd';
}

declare global {
  interface Window {
    pyor?: PyorBridge;
  }
}

export function bridge(): PyorBridge | null {
  return typeof window !== 'undefined' && window.pyor ? window.pyor : null;
}

export function isElectron(): boolean {
  return !!bridge();
}
