// Dexie-backed IndexedDB store for TanStack Query's persistence layer.
//
// Why not localStorage:
//   - localStorage is synchronous and capped at ~5 MB (browser-dependent).
//     A single 569-file PR's blob contents alone can be 5+ MB.
//   - localStorage blocks the main thread on every write.
//   - IndexedDB is async, has GB-scale quotas, and is the documented
//     persistence target for TanStack Query's `AsyncStoragePersister`.
//
// What TanStack actually stores in here: a single JSON-serialised
// snapshot of the whole query client cache, written on every cache
// mutation (debounced internally by the persister). One row per
// "snapshot version" — we only ever read/write key "primary" since
// AsyncStoragePersister is single-key.

import Dexie, { type Table } from 'dexie';

/** One row = one cache snapshot. We only use the `primary` key today
 * but Dexie lets us bump the schema later if we want to shard the
 * cache (e.g. one snapshot per repo). */
interface QuerySnapshotRow {
  key: string;
  value: string;
  updatedAt: number;
}

class PyorQueryDB extends Dexie {
  snapshots!: Table<QuerySnapshotRow, string>;

  constructor() {
    super('pyor-query-cache');
    // v1 schema — only the `key` field is indexed. `value` is a big
    // JSON blob, `updatedAt` is informational.
    this.version(1).stores({
      snapshots: 'key',
    });
  }
}

const db = new PyorQueryDB();

/** Storage adapter shape TanStack's `createAsyncStoragePersister`
 * expects. Three async methods over a single primary key. */
export const queryAsyncStorage = {
  async getItem(key: string): Promise<string | null> {
    const row = await db.snapshots.get(key);
    return row?.value ?? null;
  },
  async setItem(key: string, value: string): Promise<void> {
    await db.snapshots.put({ key, value, updatedAt: Date.now() });
  },
  async removeItem(key: string): Promise<void> {
    await db.snapshots.delete(key);
  },
};

/** Wipe every persisted snapshot. Used on sign-out so the next user
 * doesn't see flashes of the previous user's cached PRs while the
 * fresh fetch is in flight. */
export async function clearQueryStore(): Promise<void> {
  await db.snapshots.clear();
}
