// Shared reaction-mutation primitives.
//
// These were originally inline in DescriptionTab (Conversation tab),
// but the Changes-tab inline thread now wires interactive reactions
// too — so the optimistic-update plumbing lives here, imported by both
// surfaces. Pure data helpers + a tiny cache wrapper; no React.

import type { QueryClient } from '@tanstack/react-query';
import type { ReactionContent } from './client';
import type { GHReactions } from './types';

/** Narrow `keyof GHReactions` (which includes the `url` /
 * `total_count` metadata fields) down to the eight reaction-content
 * values the GitHub POST endpoint accepts. Returns null for keys
 * that aren't actual reactions, so callers can early-out. */
export function asReactionContent(
  key: keyof GHReactions,
): ReactionContent | null {
  switch (key) {
    case '+1':
    case '-1':
    case 'laugh':
    case 'confused':
    case 'heart':
    case 'hooray':
    case 'rocket':
    case 'eyes':
      return key;
    default:
      return null;
  }
}

/** Apply ±1 to one of a reactions summary's eight counters + the
 * total_count, returning a new object. Optimistic-update primitive
 * — reaches into a freshly-cloned GHReactions and bumps the matching
 * field, falling back to a fresh zeroed shape when the source row
 * never had any reactions yet (the summary is absent on a row that
 * has never been reacted to). */
export function bumpReactionCount(
  current: GHReactions | undefined,
  content: ReactionContent,
  delta: 1 | -1,
): GHReactions {
  const base: GHReactions = current ?? {
    url: '',
    total_count: 0,
    '+1': 0,
    '-1': 0,
    laugh: 0,
    hooray: 0,
    confused: 0,
    heart: 0,
    rocket: 0,
    eyes: 0,
  };
  return {
    ...base,
    [content]: Math.max(0, (base[content] as number) + delta),
    total_count: Math.max(0, base.total_count + delta),
  };
}

/** Snapshot the cache, apply an optimistic patch via `setQueryData`,
 * fire the network mutation, and roll back if it throws.
 *
 * Skips the post-success invalidate on purpose — the optimistic patch
 * IS the truth from the client's perspective. The natural refetch
 * cadence (poll, window-focus, stale-time) reconciles with the server
 * if other reactors land an update in parallel. */
export async function withOptimisticReaction<T>(
  qc: QueryClient,
  queryKey: readonly unknown[],
  patch: (curr: T | undefined) => T | undefined,
  mutate: () => Promise<unknown>,
): Promise<void> {
  const snapshot = qc.getQueryData<T>(queryKey);
  qc.setQueryData<T>(queryKey, patch(snapshot));
  try {
    await mutate();
  } catch (e) {
    qc.setQueryData<T>(queryKey, snapshot);
    throw e;
  }
}

/** Strip markdown noise + collapse whitespace, then truncate. Used
 * for the one-line `preview` shown next to the author name when a
 * comment card is collapsed. We don't try to render the markdown —
 * the preview is supposed to be skimable, not faithful. */
export function plainTextPreview(md: string, max = 120): string {
  const text = md
    // Fenced code: drop the ``` fences + optional language label, but
    // keep the code itself so a code-only comment still previews instead
    // of collapsing to an empty string.
    .replace(/```[^\n`]*\n?([\s\S]*?)```/g, ' $1 ')
    // Inline code: keep the content, drop the surrounding backticks.
    .replace(/`([^`]*)`/g, '$1')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/[#>*_~]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
}
