// Symbol-navigation overlay (chip + outline + coachmark). Owns the UI state and
// is driven imperatively by the controller (useSymbolNav) via a ref. This MUST
// be a sibling of <DiffBody>, never its parent: state updates here re-render only
// this small component, so they never re-render the @pierre/diffs CodeView. (A
// state update during scroll that DID re-render the diff broke its virtualization
// — rows collapsed into a "N unmodified lines" separator between every line.)

import { forwardRef, useImperativeHandle, useState } from 'react';

import { SymbolChip, type ChipAnchor } from './SymbolChip';
import { SymbolOutline } from './SymbolOutline';
import { SymbolCoach } from './SymbolCoach';
import type { OutlineSymbol } from './types';

export interface ChipState {
  // Identity of the symbol the chip belongs to (path:side:symbol). Used as the
  // React key so cycling within one symbol reuses the node (top/left transition
  // glides), while clicking a different symbol remounts (instant placement, no
  // slide across the file).
  id: string;
  anchor: ChipAnchor;
  count: number;
  hasDef: boolean;
}

interface OutlineState {
  path: string;
  symbols: OutlineSymbol[];
}

export interface SymbolNavOverlayHandle {
  setChip: (s: ChipState | null) => void;
  setOutline: (s: OutlineState | null) => void;
  setCoach: (a: ChipAnchor | null) => void;
}

interface SymbolNavOverlayProps {
  onPrev: () => void;
  onNext: () => void;
  onGotoDef: () => void;
  onClose: () => void;
  onSelectSymbol: (s: OutlineSymbol, path: string) => void;
}

export const SymbolNavOverlay = forwardRef<SymbolNavOverlayHandle, SymbolNavOverlayProps>(
  function SymbolNavOverlay({ onPrev, onNext, onGotoDef, onClose, onSelectSymbol }, ref) {
    const [chip, setChip] = useState<ChipState | null>(null);
    const [outline, setOutline] = useState<OutlineState | null>(null);
    const [coach, setCoach] = useState<ChipAnchor | null>(null);

    useImperativeHandle(ref, () => ({ setChip, setOutline, setCoach }), []);

    return (
      <>
        {chip && (
          <SymbolChip
            key={chip.id}
            anchor={chip.anchor}
            count={chip.count}
            hasDef={chip.hasDef}
            onPrev={onPrev}
            onNext={onNext}
            onGotoDef={onGotoDef}
            onClose={onClose}
          />
        )}
        {outline && (
          <SymbolOutline
            open
            onOpenChange={(o) => {
              if (!o) setOutline(null);
            }}
            path={outline.path}
            symbols={outline.symbols}
            onSelect={(s) => onSelectSymbol(s, outline.path)}
          />
        )}
        {coach && <SymbolCoach anchor={coach} onDismiss={() => setCoach(null)} />}
      </>
    );
  },
);
