// Lightweight per-extension file icon for the bespoke AI rail. @pierre/trees
// ships colored language icons but only inside its shadow root (not reusable),
// so this maps the common extensions to a colored lucide glyph — enough to
// scan file types at a glance, matching the look of the tree rail.

import {
  FileIcon,
  FileCode2Icon,
  FileJson2Icon,
  FileTextIcon,
  FileImageIcon,
  FileType2Icon,
  FileCogIcon,
  type LucideIcon,
} from 'lucide-react';
import { cn } from '@/lib/utils';

type Entry = { Icon: LucideIcon; cls: string };

const BY_EXT: Record<string, Entry> = {
  ts: { Icon: FileCode2Icon, cls: 'text-blue-500 dark:text-blue-400' },
  tsx: { Icon: FileCode2Icon, cls: 'text-blue-500 dark:text-blue-400' },
  js: { Icon: FileCode2Icon, cls: 'text-amber-500' },
  jsx: { Icon: FileCode2Icon, cls: 'text-amber-500' },
  mjs: { Icon: FileCode2Icon, cls: 'text-amber-500' },
  cjs: { Icon: FileCode2Icon, cls: 'text-amber-500' },
  py: { Icon: FileCode2Icon, cls: 'text-sky-500' },
  go: { Icon: FileCode2Icon, cls: 'text-cyan-500' },
  rs: { Icon: FileCode2Icon, cls: 'text-orange-500' },
  rb: { Icon: FileCode2Icon, cls: 'text-red-500' },
  html: { Icon: FileCode2Icon, cls: 'text-orange-500' },
  vue: { Icon: FileCode2Icon, cls: 'text-emerald-500' },
  svelte: { Icon: FileCode2Icon, cls: 'text-orange-500' },
  json: { Icon: FileJson2Icon, cls: 'text-amber-500' },
  css: { Icon: FileType2Icon, cls: 'text-sky-500' },
  scss: { Icon: FileType2Icon, cls: 'text-pink-500' },
  less: { Icon: FileType2Icon, cls: 'text-sky-500' },
  md: { Icon: FileTextIcon, cls: 'text-muted-foreground' },
  mdx: { Icon: FileTextIcon, cls: 'text-muted-foreground' },
  txt: { Icon: FileTextIcon, cls: 'text-muted-foreground' },
  yml: { Icon: FileCogIcon, cls: 'text-muted-foreground' },
  yaml: { Icon: FileCogIcon, cls: 'text-muted-foreground' },
  toml: { Icon: FileCogIcon, cls: 'text-muted-foreground' },
  lock: { Icon: FileCogIcon, cls: 'text-muted-foreground/70' },
  png: { Icon: FileImageIcon, cls: 'text-emerald-500' },
  jpg: { Icon: FileImageIcon, cls: 'text-emerald-500' },
  jpeg: { Icon: FileImageIcon, cls: 'text-emerald-500' },
  gif: { Icon: FileImageIcon, cls: 'text-emerald-500' },
  svg: { Icon: FileImageIcon, cls: 'text-emerald-500' },
  webp: { Icon: FileImageIcon, cls: 'text-emerald-500' },
};

const DEFAULT: Entry = { Icon: FileIcon, cls: 'text-muted-foreground/70' };

export function FileTypeIcon({ path, className }: { path: string; className?: string }) {
  const base = path.split('/').pop() ?? path;
  const ext = base.includes('.') ? base.slice(base.lastIndexOf('.') + 1).toLowerCase() : '';
  const { Icon, cls } = BY_EXT[ext] ?? DEFAULT;
  return <Icon className={cn('size-3.5 shrink-0', cls, className)} />;
}
