// Pyor brand mark — the official app icon (green squircle + plus glyph).
// Inline SVG so it stays crisp at any size and inherits no external asset.

interface Props {
  size?: number;
  className?: string;
}

export function PyorMark({ size = 48, className = '' }: Props) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 1024 1024"
      className={`shrink-0 ${className}`}
      role="img"
      aria-label="Pyor"
    >
      <linearGradient id="pyorMarkGreen" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stopColor="#6ad97c" />
        <stop offset="1" stopColor="#2f8f43" />
      </linearGradient>
      <rect width="1024" height="1024" rx="224" fill="url(#pyorMarkGreen)" />
      <g stroke="#08160c" strokeWidth="153.6" strokeLinecap="round">
        <line x1="512" y1="276.48" x2="512" y2="747.52" />
        <line x1="276.48" y1="512" x2="747.52" y2="512" />
      </g>
    </svg>
  );
}
