// The /pulls shell. Owns the persistent chrome — PyorWindow + the tab
// bar (My PRs · Reviewing · Team) with its search + date-range controls —
// and swaps only the BODY underneath by tab. Keeping the tab bar mounted
// across every switch (not just My PRs↔Reviewing) means its animated
// underline slides instead of remounting.
//
// Each body (the lens list / the team radar) still owns its own data,
// filter row, subtitle, status, and Refresh — it publishes those up via
// usePullsChrome so the shell can render them without remounting.

import { useEffect, useRef, useState } from 'react';
import { useNavigate, useSearch } from '@tanstack/react-router';
import { cleanSearch, type PullsSearch } from '../router/search';
import { type DateRangePreset } from '../ui/DateRangeChip';
import { PyorWindow } from '../ui/PyorWindow';
import { PullsTabsBar, type PullsTabId } from '../pr/PullsTabsBar';
import { PullsChromeContext, type PullsChrome } from '../pr/pullsChrome';
import { PullRequestsBody } from './PullRequestsScreen';
import { TeamRadarBody } from './TeamRadarScreen';
import { track, Events } from '../observability';

interface PullsScreenProps {
  fluid?: boolean;
  width?: number;
  height?: number;
}

export function PullsScreen({
  fluid = false,
  width = 1320,
  height = 820,
}: PullsScreenProps) {
  const navigate = useNavigate();
  const search = useSearch({ from: '/pulls' });
  const patch = (next: Partial<PullsSearch>) =>
    void navigate({
      to: '/pulls',
      search: cleanSearch({ ...search, ...next }),
      replace: true,
    });

  const active: PullsTabId =
    search.tab === 'team' ? 'team' : search.tab === 'reviewing' ? 'reviewing' : 'mine';

  // Lens engagement (ADR 0021): fires on initial view + each lens switch.
  useEffect(() => {
    track(Events.LensViewed, { lens: active });
  }, [active]);

  // Switching tabs drops every narrowing filter (team scope + lens chips)
  // so the destination opens clean; the tab-bar controls (status / date /
  // search / sort) persist as global view prefs.
  const selectTab = (id: PullsTabId) =>
    patch({
      tab: id,
      org: undefined,
      authors: undefined,
      tsort: undefined,
      repo: undefined,
      author: undefined,
      label: undefined,
      reviewer: undefined,
      ci: undefined,
    });

  // ⌘F focuses the shared search input.
  const searchRef = useRef<HTMLInputElement | null>(null);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'f') {
        e.preventDefault();
        searchRef.current?.focus();
        searchRef.current?.select();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  // Per-tab chrome, published by the active body.
  const [chrome, setChrome] = useState<PullsChrome>({
    subtitle: 'Pull requests',
    toolbar: null,
    status: null,
  });

  return (
    <PyorWindow
      width={width}
      height={height}
      title="Pull requests"
      subtitle={chrome.subtitle}
      toolbar={chrome.toolbar}
      status={chrome.status}
      fluid={fluid}
    >
      <PullsTabsBar
        active={active}
        onSelect={selectTab}
        searchQuery={search.q ?? ''}
        setSearchQuery={(v) => patch({ q: v || undefined })}
        searchRef={searchRef}
        dateRange={search.date as DateRangePreset}
        setDateRange={(d) => patch({ date: d })}
      />
      <PullsChromeContext.Provider value={setChrome}>
        {active === 'team' ? <TeamRadarBody /> : <PullRequestsBody />}
      </PullsChromeContext.Provider>
    </PyorWindow>
  );
}
