// Team lens — open PRs from *other* members of the organizations you
// belong to. Powers the Pull-requests screen's third tab ("Team"), a
// review radar bucketed by how much you can unblock.
//
// Two GraphQL round-trips, mirroring lenses.ts:
//   1. `viewer.organizations` → the orgs you're a member of.
//   2. `search(is:pr is:open org:A org:B … -author:@me)` → teammates'
//      open PRs across those orgs, with the reviewer + review-state +
//      CI-rollup data the radar buckets and rows need.
//
// The handoff shipped invented fixtures (TEAM_ORGS / TEAM_PRS); this is
// the real query that returns the same row shape. Limitations noted
// inline (single page; CI rollup collapsed to a single state) are the
// "decisions to revisit" the handoff calls out.

import { graphql } from './client';
import { hasWriteAccess, type ViewerPermission } from './lifecycle';

// ── Row shape (matches the handoff's TEAM_PRS rows) ──────────────────

export type ReviewState = 'approved' | 'changes' | 'pending' | 'commented';

export interface TeamReviewer {
  name: string;
  state: ReviewState;
}

/** Your tie to a teammate's PR. `team` (touches code your team owns) is
 * not derivable from GitHub search alone, so the production query only
 * ever sets `reviewer` (you were requested) or `null`. */
export type TeamRelation = 'reviewer' | 'mentioned' | 'team' | null;

export interface TeamPR {
  org: string;
  repo: string;
  owner: string;
  repoName: string;
  num: number;
  author: string;
  authorAvatarUrl: string;
  status: 'open' | 'draft' | 'merged' | 'closed';
  title: string;
  branch: string;
  additions: number;
  deletions: number;
  files: number;
  checks: { p: number; f: number; pe: number };
  comments: number;
  /** Human relative string, e.g. "2d ago". */
  opened: string;
  /** Time since last activity, e.g. "2h" / "3d" — drives staleness. */
  waiting: string;
  relation: TeamRelation;
  /** Author is an app/bot (dependabot, github-actions, …). Shown, but
   * sorted to the bottom of the rail and each bucket as least-important. */
  isBot: boolean;
  labels: { name: string; color: string }[];
  reviewers: TeamReviewer[];
  /** Viewer has WRITE+ on this PR's repo — i.e. GitHub will let them
   * request reviewers. Gates the row's "Add me as reviewer" action;
   * without it the request returns 403 "Resource not accessible by
   * integration". Read from `Repository.viewerPermission` in the same
   * search query (no extra round-trip). */
  canManage: boolean;
  /** ISO timestamps — not displayed, used by the Sort dropdown. */
  createdAt: string;
  updatedAt: string;
}

export interface TeamOrg {
  key: string;
  name: string;
  glyph: string;
  /** Org avatar/logo URL — empty string falls back to the glyph. */
  avatarUrl: string;
}

// ── Derived helpers (ported verbatim from the handoff) ───────────────

function teamReviewState(
  pr: TeamPR,
  you: string,
): 'needs-reviewer' | 'changes' | 'approved' | 'awaiting' {
  if (pr.reviewers.length === 0) return 'needs-reviewer';
  if (pr.reviewers.some((r) => r.state === 'changes')) return 'changes';
  const others = pr.reviewers.filter((r) => r.name !== you);
  if (others.length && others.every((r) => r.state === 'approved')) {
    return 'approved';
  }
  return 'awaiting';
}

/** Parse a `waiting` string ('12m' | '2h' | '3d') into days. */
export function waitDays(w: string): number {
  const m = /(\d+)\s*(m|h|d)/.exec(w || '');
  if (!m) return 0;
  const n = +m[1];
  return m[2] === 'd' ? n : m[2] === 'h' ? n / 24 : n / 1440;
}

/** Staleness colour pair from a `waiting` string. */
export function waitTone(w: string): { dot: string; text: string } {
  const d = waitDays(w);
  if (d >= 5) return { dot: 'bg-red-500', text: 'text-red-600' };
  if (d >= 3) return { dot: 'bg-amber-500', text: 'text-amber-600' };
  if (d >= 1) return { dot: 'bg-zinc-400', text: 'text-muted-foreground' };
  return { dot: 'bg-emerald-500', text: 'text-muted-foreground' };
}

// ── Buckets (first match wins, in order) ─────────────────────────────

export interface TeamBucket {
  id: 'needs' | 'yours' | 'team' | 'moving';
  icon: string;
  accent: 'amber' | 'blue' | 'zinc';
  title: string;
  why: string;
  test: (pr: TeamPR) => boolean;
}

const TEAM_RADAR_BUCKETS: TeamBucket[] = [
  {
    id: 'needs',
    icon: 'alert-triangle',
    accent: 'amber',
    title: 'Needs a first reviewer',
    why: 'No one is on these yet — claiming one unblocks a teammate.',
    test: (pr) => pr.reviewers.length === 0,
  },
  {
    id: 'yours',
    icon: 'eye',
    accent: 'blue',
    title: 'Your review was requested',
    why: 'You were added as a reviewer.',
    test: (pr) => pr.relation === 'reviewer',
  },
  {
    id: 'team',
    icon: 'users',
    accent: 'zinc',
    title: "In your team's areas",
    why: 'Touches code your team owns.',
    test: (pr) => pr.relation === 'team',
  },
  {
    id: 'moving',
    icon: 'git-pull-request',
    accent: 'zinc',
    title: 'Already in review',
    why: 'Has reviewers and is progressing.',
    test: () => true,
  },
];

/** Split PRs into ordered buckets — each PR lands in exactly one. */
export function bucketTeamPRs(
  source: TeamPR[],
): { bucket: TeamBucket; prs: TeamPR[] }[] {
  const seen = new Set<number>();
  return TEAM_RADAR_BUCKETS.map((bucket) => {
    const prs = source.filter((pr) => !seen.has(pr.num) && bucket.test(pr));
    prs.forEach((pr) => seen.add(pr.num));
    return { bucket, prs };
  });
}

/** Rank teammate authors by how closely they work with you, so the
 * author rail surfaces your closest collaborators first (and the rest
 * fall into the "+N" overflow).
 *
 * The dominant signal is **shared activity**: for each repo a teammate
 * has a PR in, we add *your own* activity weight in that repo
 * (`repoWeight`, from fetchViewerRepoActivity). A teammate working in
 * the repos you actually work in scores high; one working only in repos
 * you never touch scores ~0 — regardless of how many PRs they have. We
 * sum over their *distinct* repos (not per-PR) so volume can't inflate
 * the score, and add a strong bonus when they requested your review.
 * Bot authors always sort below humans; ties break by PR count, then
 * alphabetically. */
export function rankAuthors(
  rows: FacetRow[],
  repoWeight: RepoWeights,
): string[] {
  const repos = new Map<string, Set<string>>();
  const reqYou = new Map<string, number>();
  const count = new Map<string, number>();
  const bot = new Map<string, boolean>();
  rows.forEach((r) => {
    const set = repos.get(r.author) ?? new Set<string>();
    set.add(r.repo);
    repos.set(r.author, set);
    count.set(r.author, (count.get(r.author) ?? 0) + 1);
    if (r.isBot) bot.set(r.author, true);
    if (r.reqYou) reqYou.set(r.author, (reqYou.get(r.author) ?? 0) + 1);
  });
  const score = (a: string) => {
    let w = 0;
    repos.get(a)?.forEach((r) => (w += repoWeight[r] ?? 0));
    return w + (reqYou.get(a) ?? 0) * 5;
  };
  return [...new Set(rows.map((r) => r.author))].sort(
    (a, b) =>
      // Bots always sink below humans, then by collaboration score.
      Number(!!bot.get(a)) - Number(!!bot.get(b)) ||
      score(b) - score(a) ||
      (count.get(b) ?? 0) - (count.get(a) ?? 0) ||
      a.localeCompare(b),
  );
}

// ── Org membership ───────────────────────────────────────────────────

const ORGS_QUERY = /* GraphQL */ `
  query ViewerOrgs {
    rateLimit { cost remaining limit }
    viewer {
      login
      organizations(first: 50) {
        nodes { login name avatarUrl }
      }
    }
  }
`;

export async function fetchViewerOrgs(): Promise<TeamOrg[]> {
  const data = await graphql<{
    viewer: {
      organizations: {
        nodes: { login: string; name: string | null; avatarUrl: string }[];
      };
    };
  }>(ORGS_QUERY, {});
  return data.viewer.organizations.nodes.map((o) => ({
    key: o.login,
    name: o.name || o.login,
    glyph: glyphFor(o.login),
    avatarUrl: o.avatarUrl ?? '',
  }));
}

// Your per-repo activity weight — the backbone of the author ranking.
// We tally the repos across your own PRs (authored / reviewed / involved),
// so the repos you actually work in score highest and the ones you've only
// brushed against score low or zero. This is what makes a teammate in *your*
// area (e.g. a fellow frontend dev) outrank a prolific author working in a
// repo you never touch — "ever contributed once" was too coarse, and raw
// PR counts let volume dominate.
const VIEWER_ACTIVITY_QUERY = /* GraphQL */ `
  query ViewerActivity {
    rateLimit { cost remaining limit }
    search(query: "is:pr involves:@me", type: ISSUE, first: 100) {
      nodes {
        ... on PullRequest {
          repository { nameWithOwner }
        }
      }
    }
  }
`;

/** Map of "owner/name" → how many of your recent PRs touch that repo. */
export type RepoWeights = Record<string, number>;

export async function fetchViewerRepoActivity(): Promise<RepoWeights> {
  const data = await graphql<{
    search: { nodes: ({ repository?: { nameWithOwner: string } } | null)[] };
  }>(VIEWER_ACTIVITY_QUERY, {});
  const weights: RepoWeights = {};
  data.search.nodes.forEach((n) => {
    const repo = n?.repository?.nameWithOwner;
    if (repo) weights[repo] = (weights[repo] ?? 0) + 1;
  });
  return weights;
}

/** Two-letter glyph for an org — first two alnum chars, uppercased. */
function glyphFor(login: string): string {
  const parts = login.split(/[^a-zA-Z0-9]+/).filter(Boolean);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return login.replace(/[^a-zA-Z0-9]/g, '').slice(0, 2).toUpperCase() || '?';
}

// ── Teammate-PR search ───────────────────────────────────────────────

const TEAM_SEARCH_QUERY = /* GraphQL */ `
  query TeamSearch($q: String!, $cursor: String) {
    rateLimit { cost remaining limit }
    search(query: $q, type: ISSUE, first: 50, after: $cursor) {
      issueCount
      pageInfo { endCursor hasNextPage }
      nodes {
        __typename
        ... on PullRequest {
          number
          title
          isDraft
          state
          createdAt
          updatedAt
          additions
          deletions
          changedFiles
          author { __typename login avatarUrl }
          headRefName
          repository {
            nameWithOwner
            owner { login }
            name
            viewerPermission
          }
          labels(first: 5) { nodes { name color } }
          comments { totalCount }
          reviewRequests(first: 20) {
            nodes {
              requestedReviewer {
                __typename
                ... on User { login }
              }
            }
          }
          latestReviews(first: 20) {
            nodes {
              author { login }
              state
            }
          }
          commits(last: 1) {
            nodes { commit { statusCheckRollup { state } } }
          }
        }
      }
    }
  }
`;

interface RawTeamNode {
  __typename: string;
  number: number;
  title: string;
  isDraft: boolean;
  state: 'OPEN' | 'CLOSED' | 'MERGED';
  createdAt: string;
  updatedAt: string;
  additions: number;
  deletions: number;
  changedFiles: number;
  author: { __typename: string; login: string; avatarUrl?: string } | null;
  headRefName: string;
  repository: {
    nameWithOwner: string;
    owner: { login: string };
    name: string;
    viewerPermission: string | null;
  };
  labels: { nodes: { name: string; color: string }[] };
  comments: { totalCount: number };
  reviewRequests: {
    nodes: { requestedReviewer: { __typename: string; login?: string } | null }[];
  };
  latestReviews: { nodes: { author: { login: string } | null; state: string }[] };
  commits: {
    nodes: { commit: { statusCheckRollup: { state: string } | null } }[];
  };
}

/** PR-state scope for the team query — mirrors the Pulls lens. */
export type TeamStatus = 'open' | 'draft' | 'closed' | 'merged' | 'all';
export type TeamCI = 'success' | 'failure' | 'pending';

/** All server-side filters folded into the team search query. Org,
 * author, repo, reviewer, CI, label, and date are GitHub search
 * qualifiers, so changing any of them re-fetches (and the result is
 * complete, not limited to already-loaded pages). */
export interface TeamFilters {
  /** 'all' → every org the viewer belongs to; otherwise one org login. */
  org: string;
  /** Selected author logins — multiple `author:` qualifiers (OR). */
  authors: string[];
  status: TeamStatus;
  /** ISO date — emits `updated:>YYYY-MM-DD` (null = no bound). */
  since: string | null;
  repo: string | null;
  reviewer: string | null;
  ci: TeamCI | null;
  label: string | null;
  /** Free-text — appended raw; GitHub searches title/body. */
  q: string | null;
}

/** Build the teammate-PR search query from a full filter set.
 * `closed` pairs `is:unmerged` so Closed and Merged stay disjoint;
 * Open is ready-only (drafts have their own filter). */
function buildTeamQuery(orgLogins: string[], f: TeamFilters): string {
  const parts = ['is:pr', '-author:@me'];
  // GitHub ORs scope qualifiers: `org:X repo:X/Y` returns the whole org,
  // not the repo. So a repo filter replaces the org scope (the repo
  // already implies its org); otherwise scope by the selected org(s).
  if (f.repo) {
    parts.push(`repo:${f.repo}`);
  } else {
    const orgs = f.org === 'all' ? orgLogins : [f.org];
    parts.push(...orgs.map((o) => `org:${o}`));
  }
  if (f.status === 'open') parts.push('is:open', 'draft:false');
  else if (f.status === 'draft') parts.push('is:open', 'draft:true');
  else if (f.status === 'closed') parts.push('is:closed', 'is:unmerged');
  else if (f.status === 'merged') parts.push('is:merged');
  // 'all' → no status token
  f.authors.forEach((a) => parts.push(`author:${a}`));
  if (f.reviewer) parts.push(`review-requested:${f.reviewer}`);
  if (f.ci) parts.push(`status:${f.ci}`);
  if (f.label) parts.push(`label:"${f.label}"`);
  if (f.since) parts.push(`updated:>${f.since.slice(0, 10)}`);
  let q = parts.join(' ');
  const text = f.q?.trim();
  if (text) q += ` ${text}`;
  return q;
}

/** Filters that scope the candidate pool (facets) — i.e. everything
 * except the narrowing qualifiers the facets must stay blind to. */
export function scopeFilters(
  org: string,
  status: TeamStatus,
  since: string | null,
): TeamFilters {
  return {
    org,
    status,
    since,
    authors: [],
    repo: null,
    reviewer: null,
    ci: null,
    label: null,
    q: null,
  };
}

const REVIEW_STATE: Record<string, ReviewState> = {
  APPROVED: 'approved',
  CHANGES_REQUESTED: 'changes',
  COMMENTED: 'commented',
  DISMISSED: 'pending',
  PENDING: 'pending',
};

// CI rollup collapses to a single indicator — GraphQL's StatusCheckRollup
// has no per-conclusion counts without paging every context, which would
// blow the per-row GraphQL budget. The radar only needs "is anything
// failing / pending", so we map the aggregate state to a 1-in-one-bucket
// count. Revisit if exact pass/fail tallies are needed on the row.
const ROLLUP_CHECKS: Record<string, { p: number; f: number; pe: number }> = {
  SUCCESS: { p: 1, f: 0, pe: 0 },
  FAILURE: { p: 0, f: 1, pe: 0 },
  ERROR: { p: 0, f: 1, pe: 0 },
  PENDING: { p: 0, f: 0, pe: 1 },
  EXPECTED: { p: 0, f: 0, pe: 1 },
};

/** True for app/bot authors (dependabot, renovate, github-actions, …).
 * These stay in the list but are flagged so they sort to the bottom. */
function isBotAuthor(author: RawTeamNode['author']): boolean {
  return (
    !!author &&
    (author.__typename === 'Bot' || /\[bot\]$/.test(author.login ?? ''))
  );
}

/** One page of teammate PRs + the cursor/total for infinite scroll. */
export interface TeamPage {
  items: TeamPR[];
  endCursor: string | null;
  hasNextPage: boolean;
  /** GitHub's reported total for the query. */
  total: number;
}

export async function fetchTeamPRs(
  orgLogins: string[],
  you: string,
  filters: TeamFilters,
  cursor: string | null = null,
): Promise<TeamPage> {
  if (orgLogins.length === 0) {
    return { items: [], endCursor: null, hasNextPage: false, total: 0 };
  }
  const data = await graphql<{
    search: {
      issueCount: number;
      pageInfo: { endCursor: string | null; hasNextPage: boolean };
      nodes: (RawTeamNode | null)[];
    };
  }>(TEAM_SEARCH_QUERY, { q: buildTeamQuery(orgLogins, filters), cursor });
  const items = data.search.nodes
    .filter((n): n is RawTeamNode => !!n && n.__typename === 'PullRequest')
    .map((n) => normalizeTeamPR(n, you));
  return {
    items,
    endCursor: data.search.pageInfo.endCursor,
    hasNextPage: data.search.pageInfo.hasNextPage,
    total: data.search.issueCount,
  };
}

// ── Facets — candidate authors / repos / labels for the filter UI ────
// Once results are server-filtered, the option lists (author rail, repo
// & label dropdowns) can't be derived from the results. This lightweight
// query is scoped only by org/status/date — blind to author/repo/label/
// reviewer/ci/q — so it surfaces the full candidate pool for those
// controls (capped at one 100-PR page; enough for the rail + dropdowns).

export interface FacetRow {
  author: string;
  repo: string;
  isBot: boolean;
  /** Viewer is a requested reviewer — boosts author ranking. */
  reqYou: boolean;
}

export interface TeamFacets {
  rows: FacetRow[];
  /** [repo, count] / [label, count], most-frequent first. */
  repos: [string, number][];
  labels: [string, number][];
}

const FACETS_QUERY = /* GraphQL */ `
  query TeamFacets($q: String!) {
    rateLimit { cost remaining limit }
    search(query: $q, type: ISSUE, first: 100) {
      nodes {
        __typename
        ... on PullRequest {
          author { __typename login }
          repository { nameWithOwner }
          labels(first: 5) { nodes { name } }
          reviewRequests(first: 10) {
            nodes { requestedReviewer { __typename ... on User { login } } }
          }
        }
      }
    }
  }
`;

interface RawFacetNode {
  __typename: string;
  author: { __typename: string; login: string } | null;
  repository: { nameWithOwner: string };
  labels: { nodes: { name: string }[] };
  reviewRequests: {
    nodes: { requestedReviewer: { __typename: string; login?: string } | null }[];
  };
}

export async function fetchTeamFacets(
  orgLogins: string[],
  scope: TeamFilters,
  you: string,
): Promise<TeamFacets> {
  if (orgLogins.length === 0) return { rows: [], repos: [], labels: [] };
  const data = await graphql<{ search: { nodes: (RawFacetNode | null)[] } }>(
    FACETS_QUERY,
    { q: buildTeamQuery(orgLogins, scope) },
  );
  const rows: FacetRow[] = [];
  const repoCounts = new Map<string, number>();
  const labelCounts = new Map<string, number>();
  data.search.nodes
    .filter((n): n is RawFacetNode => !!n && n.__typename === 'PullRequest')
    .forEach((n) => {
      const repo = n.repository.nameWithOwner;
      rows.push({
        author: n.author?.login ?? 'ghost',
        repo,
        isBot: isBotAuthor(n.author),
        reqYou: n.reviewRequests.nodes.some(
          (r) => r.requestedReviewer?.login === you,
        ),
      });
      repoCounts.set(repo, (repoCounts.get(repo) ?? 0) + 1);
      n.labels.nodes.forEach((l) =>
        labelCounts.set(l.name, (labelCounts.get(l.name) ?? 0) + 1),
      );
    });
  const sortCount = (m: Map<string, number>): [string, number][] =>
    [...m.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  return { rows, repos: sortCount(repoCounts), labels: sortCount(labelCounts) };
}

function normalizeTeamPR(n: RawTeamNode, you: string): TeamPR {
  const requested = n.reviewRequests.nodes
    .map((r) => r.requestedReviewer)
    .filter((u): u is { __typename: string; login: string } =>
      Boolean(u && u.__typename === 'User' && u.login),
    )
    .map((u) => u.login);

  const reviewed = n.latestReviews.nodes
    .filter((r) => r.author?.login)
    .map((r) => ({
      name: r.author!.login,
      state: REVIEW_STATE[r.state] ?? 'pending',
    }));
  const reviewedNames = new Set(reviewed.map((r) => r.name));
  const pendingRequested = requested
    .filter((login) => !reviewedNames.has(login))
    .map((login) => ({ name: login, state: 'pending' as ReviewState }));
  const reviewers = [...reviewed, ...pendingRequested];

  const youAreReviewer =
    requested.includes(you) || reviewedNames.has(you);

  const rollupState = n.commits.nodes[0]?.commit.statusCheckRollup?.state;
  const checks = ROLLUP_CHECKS[rollupState ?? ''] ?? { p: 0, f: 0, pe: 0 };

  return {
    org: n.repository.owner.login,
    repo: n.repository.nameWithOwner,
    owner: n.repository.owner.login,
    repoName: n.repository.name,
    num: n.number,
    author: n.author?.login ?? 'ghost',
    authorAvatarUrl: n.author?.avatarUrl ?? '',
    status: n.isDraft
      ? 'draft'
      : n.state === 'MERGED'
        ? 'merged'
        : n.state === 'CLOSED'
          ? 'closed'
          : 'open',
    title: n.title,
    branch: n.headRefName,
    additions: n.additions,
    deletions: n.deletions,
    files: n.changedFiles,
    checks,
    comments: n.comments.totalCount,
    opened: `${relativeAge(n.createdAt)} ago`,
    waiting: relativeAge(n.updatedAt),
    relation: youAreReviewer ? 'reviewer' : null,
    isBot: isBotAuthor(n.author),
    labels: n.labels.nodes,
    reviewers,
    canManage: hasWriteAccess(
      (n.repository.viewerPermission ?? 'NONE') as ViewerPermission,
    ),
    createdAt: n.createdAt,
    updatedAt: n.updatedAt,
  };
}

function relativeAge(iso: string): string {
  const ms = Date.now() - new Date(iso).getTime();
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${Math.max(1, s)}s`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  return `${Math.floor(h / 24)}d`;
}
