// In-memory mock broker — used when VITE_AUTH_BROKER_URL is unset.
//
// Lets the entire sign-in flow and every screen run with no real GitHub or
// Polar. Drive the outcome with env knobs (all optional):
//   VITE_MOCK_AUTH_RESULT = 'gh-free' | 'gh-paid'      (default 'gh-free')
//   VITE_MOCK_ROLE        = 'owner' | 'admin' | 'member' (default 'owner')
//   VITE_MOCK_AUTH_ERROR  = <AuthErrorKind>             (default: none)
//   VITE_MOCK_AUTH_DELAY_MS = number                    (default 600)
//   VITE_MOCK_REAUTH      = 'true'                       (returning user)
//   VITE_MOCK_GH_TOKEN    = a real PAT, so getViewer can hit real GitHub

import type {
  Entitlement,
  OAuthBroker,
  OrgRole,
  StartSignInResult,
  TokenSet,
} from './oauthBroker';
import { BrokerError, type AuthErrorKind } from './brokerError';

const E = import.meta.env as unknown as Record<string, string | undefined>;

const HOUR = 3_600_000;
const DAY = 86_400_000;

function delayMs(): number {
  const n = Number(E.VITE_MOCK_AUTH_DELAY_MS);
  return Number.isFinite(n) && n >= 0 ? n : 600;
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

function newState(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `mock-${Math.floor(performance.now())}`;
  }
}

/** Identity the controller uses in mock mode (no real getViewer call). */
export const mockViewer = {
  login: 'alex-cho',
  name: 'Alex Cho',
  email: 'alex@example.com',
  avatar_url: '',
};

export const mockBroker: OAuthBroker = {
  async startSignIn(opts): Promise<StartSignInResult> {
    return {
      authorizeUrl: 'https://github.com/apps/get-pyor/installations/new',
      state: newState(),
      reauth: opts?.reauth ?? E.VITE_MOCK_REAUTH === 'true',
    };
  },

  async completeSignIn(_code, _state): Promise<TokenSet> {
    await sleep(delayMs());
    const errKind = E.VITE_MOCK_AUTH_ERROR as AuthErrorKind | undefined;
    if (errKind) throw new BrokerError(errKind, `mock error: ${errKind}`);
    return {
      accessToken: E.VITE_MOCK_GH_TOKEN || 'mock-access-token',
      refreshToken: 'mock-refresh-token',
      expiresAt: Date.now() + 8 * HOUR,
      method: 'github-app',
    };
  },

  async refresh(_refreshToken): Promise<TokenSet> {
    return {
      accessToken: E.VITE_MOCK_GH_TOKEN || 'mock-access-token',
      refreshToken: 'mock-refresh-token',
      expiresAt: Date.now() + 8 * HOUR,
      method: 'github-app',
    };
  },

  async getEntitlement(_accessToken): Promise<Entitlement> {
    await sleep(Math.min(delayMs(), 300));
    const now = Date.now();
    const base = {
      signedToken: 'mock.entitlement.jwt',
      expiresAt: now + DAY,
      graceUntil: now + 14 * DAY,
    };
    if (E.VITE_MOCK_AUTH_RESULT === 'gh-paid') {
      const role = (E.VITE_MOCK_ROLE as OrgRole) || 'owner';
      const trialing = E.VITE_MOCK_TRIAL === 'true';
      return {
        ...base,
        plan: 'pro',
        seats: [
          {
            githubOrgId: 9999001,
            login: 'AcmeCorp',
            name: 'AcmeCorp',
            index: 4,
            total: 10,
            status: trialing ? 'trialing' : 'active',
            currentPeriodEnd: now + (trialing ? 14 : 30) * DAY,
            role,
          },
        ],
        seatsFull: [],
      };
    }
    return { ...base, plan: 'free', seats: [], seatsFull: [] };
  },
};
