// ConnStatusItem — the always-on connectivity dot for the global bottom
// status bar (design `ConnStatusBar`, surface #3's persistent part).
//
// Mounted once inside PyorWindow's status slot so every screen gets the
// same cue with no per-screen wiring. Pairs with the top ConnBar strip:
//   healthy       → green dot · "Connected" (the only cue; no strip)
//   reconnecting  → amber pulsing dot · "Reconnecting…" · cached time
//   offline       → amber dot · "You're offline" · cached time · Read-only
//   github-down   → red dot · "GitHub is down" · cached time · Read-only
//
// Read-only scope: when stale we say so plainly and never imply queued
// writes. Self-contained — reads global state from useConnectivity, so
// screens pass nothing.

import { useEffect, useState } from 'react';
import { Separator } from '@/components/ui/separator';
import { useConnectivity, type ConnStatus } from './useConnectivity';
import { CONN_MODES, CONN_TONE } from './connModes';

const LABEL: Record<Exclude<ConnStatus, 'healthy'>, string> = {
  reconnecting: 'Reconnecting…',
  offline: CONN_MODES.offline.dotLabel,
  'github-down': CONN_MODES['github-down'].dotLabel,
};

function formatClock(d: Date): string {
  return d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
}

function formatAgo(d: Date): string {
  const s = Math.max(0, Math.round((Date.now() - d.getTime()) / 1000));
  if (s < 5) return 'just now';
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  return `${h}h ago`;
}

export function ConnStatusItem() {
  const { status, lastSyncedAt } = useConnectivity();

  // Keep the relative "ago" readout live without leaning on a poll tick.
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((n) => n + 1), 1000);
    return () => clearInterval(id);
  }, []);

  if (status === 'healthy') {
    return (
      <span className="inline-flex items-center gap-1.5 whitespace-nowrap">
        <span className="size-1.5 rounded-full bg-emerald-500" />
        Connected
        {lastSyncedAt && (
          <span
            className="text-muted-foreground/70"
            title="How long ago the app last fetched anything from GitHub successfully (across every screen). The app-wide connection/freshness signal — not specific to the PR you're viewing."
          >
            · synced {formatAgo(lastSyncedAt)}
          </span>
        )}
      </span>
    );
  }

  const tone = status === 'github-down' ? CONN_TONE.red : CONN_TONE.amber;
  const pulse = status === 'reconnecting';

  return (
    <span className="inline-flex items-center gap-1.5 whitespace-nowrap">
      <span className={`inline-flex items-center gap-1.5 font-medium ${tone.nodeFg}`}>
        {pulse ? (
          <span className="relative inline-flex size-1.5">
            <span
              className={`absolute inline-flex size-full animate-ping rounded-full ${tone.dot} opacity-60`}
            />
            <span className={`relative inline-flex size-1.5 rounded-full ${tone.dot}`} />
          </span>
        ) : (
          <span className={`size-1.5 rounded-full ${tone.dot}`} />
        )}
        {LABEL[status]}
      </span>
      {lastSyncedAt && (
        <>
          <Separator orientation="vertical" className="mx-1 h-3" />
          <span>
            Cached from{' '}
            <span className="text-foreground">{formatClock(lastSyncedAt)}</span>
          </span>
        </>
      )}
      <Separator orientation="vertical" className="mx-1 h-3" />
      <span className="text-muted-foreground/70">Read-only</span>
    </span>
  );
}
