// Provider-adapter factory. Resolves the right adapter from the active
// provider + its configured key + optional model override. Returns null
// when no usable key is configured (callers gate on this).

import type { AiProvider, AiSettings } from '../settings/aiSettings';
import { getAiKey } from '../settings/aiKeyStore';
import { makeAnthropicAdapter } from './anthropic';
import { makeOpenAIAdapter } from './openai';
import type { ProviderAdapter } from './types';

export function makeAdapter(
  provider: AiProvider,
  key: string,
  model?: string,
  /** OpenAI-compatible base URL override (OpenAI provider only). */
  baseUrl?: string,
): ProviderAdapter {
  return provider === 'anthropic'
    ? makeAnthropicAdapter(key, model)
    : makeOpenAIAdapter(key, model, baseUrl);
}

/** Build the adapter for the effective provider given current settings +
 * the in-memory key snapshot. null when no key is configured. */
export function adapterFor(
  provider: AiProvider | null,
  settings: AiSettings,
): ProviderAdapter | null {
  if (!provider) return null;
  const key = getAiKey(provider);
  if (!key) return null;
  const model = provider === 'anthropic' ? settings.anthropicModel : settings.openaiModel;
  const baseUrl = provider === 'openai' ? settings.openaiBaseUrl : undefined;
  return makeAdapter(provider, key, model || undefined, baseUrl || undefined);
}

export * from './types';
export { DEFAULT_MODEL, FALLBACK_MODELS, fmtTokens, fmtCost, estimateCost } from './models';
