// Observability public surface (ADR 0021). Import from here, not the internals.
//
//   initObservability()  — call once, as early as possible (main.tsx).
//   track / Events        — curated product analytics (PostHog).
//   identifyUser / reset  — identity bridge (person + org groups + Sentry user).
//   Sentry                — for manual exception capture / error boundary.
//   consent helpers       — the Settings opt-out toggle binds to these.

import { initSentry } from './sentry';
import { initPostHog } from './posthog';

/** Initialise error tracking + product analytics. Safe to call once; no-ops
 *  for any surface whose key/DSN is unset (dev / mock). */
export function initObservability(): void {
  // Sentry first so it can capture errors thrown during PostHog init.
  initSentry();
  initPostHog();
}

export { Sentry } from './sentry';
export { track, Events, repoProps, hashRepo } from './events';
export { useOrgIdForOwner } from './useOrgId';
export { identifyUser } from './identify';
export {
  setAnalyticsOptOut,
  subscribeOptOut,
  getOptOutSnapshot,
} from './consent';
export { analyticsConfigured } from './config';
