// ConnBar — the persistent colored strip directly under the title bar,
// shown while we're serving cached data so the user always knows it's
// stale. Three variants; healthy shows no strip at all.
//
//   reconnecting (amber) — online again, revalidating; pulses
//   offline      (amber) — browser is offline
//   github-down  (red)   — GitHub unreachable while online
//
// Read-only: copy never implies we'll save/post offline work.

import {
  ExternalLinkIcon,
  Loader2Icon,
  RefreshCwIcon,
  ServerCrashIcon,
  WifiOffIcon,
  type LucideIcon,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { CONN_TONE, type ConnBarVariant } from './connModes';

interface VariantCfg {
  tone: 'amber' | 'red';
  icon: LucideIcon;
  spin?: boolean;
  label: string;
  sub: (time?: string) => string;
  action: { label: string; icon: LucideIcon };
}

const VARIANTS: Record<ConnBarVariant, VariantCfg> = {
  reconnecting: {
    tone: 'amber',
    icon: Loader2Icon,
    spin: true,
    label: 'Reconnecting…',
    sub: (t) => (t ? `showing data from ${t}` : 'revalidating cached data'),
    action: { label: 'Retry now', icon: RefreshCwIcon },
  },
  offline: {
    tone: 'amber',
    icon: WifiOffIcon,
    label: "You're offline",
    sub: (t) => (t ? `showing cached data from ${t}` : 'showing cached data'),
    action: { label: 'Retry', icon: RefreshCwIcon },
  },
  'github-down': {
    tone: 'red',
    icon: ServerCrashIcon,
    label: 'GitHub is unavailable',
    sub: (t) => (t ? `cached data from ${t}` : 'showing cached data'),
    action: { label: 'Status page', icon: ExternalLinkIcon },
  },
};

export function ConnBar({
  variant,
  lastSyncedAt,
  onAction,
}: {
  variant: ConnBarVariant;
  lastSyncedAt?: Date | null;
  onAction?: () => void;
}) {
  const V = VARIANTS[variant];
  const tone = CONN_TONE[V.tone];
  const Icon = V.icon;
  const ActionIcon = V.action.icon;
  const time = lastSyncedAt
    ? lastSyncedAt.toLocaleTimeString(undefined, {
        hour: 'numeric',
        minute: '2-digit',
      })
    : undefined;

  const handleAction = () => {
    if (variant === 'github-down') {
      window.open('https://www.githubstatus.com', '_blank', 'noopener');
      return;
    }
    onAction?.();
  };

  return (
    <div
      className={`flex shrink-0 items-center gap-2.5 border-b px-4 py-2 ${tone.barBd} ${tone.barBg} ${tone.barFg}`}
    >
      <Icon
        className={`size-4 shrink-0 ${tone.icon} ${V.spin ? 'animate-spin' : ''}`}
      />
      <span className="text-[12.5px] font-semibold">{V.label}</span>
      {variant !== 'reconnecting' && (
        <span className={`size-1 rounded-full ${tone.dot} opacity-50`} />
      )}
      <span className={`text-[12px] ${tone.barSub}`}>{V.sub(time)}</span>
      {variant === 'reconnecting' && (
        <span className="ml-1 inline-flex items-center gap-1 text-[11px] text-amber-700/70 dark:text-amber-300/60">
          <span className="relative inline-flex size-2">
            <span className="absolute inline-flex size-full animate-ping rounded-full bg-amber-400 opacity-60" />
            <span className="relative inline-flex size-2 rounded-full bg-amber-500" />
          </span>
          retrying every 15s
        </span>
      )}
      <div className="ml-auto flex items-center gap-2">
        <span className="hidden text-[11px] text-muted-foreground sm:inline">
          Read-only until reconnected
        </span>
        <Button
          variant="outline"
          size="sm"
          onClick={handleAction}
          className={tone.cardBd}
        >
          <ActionIcon />
          {V.action.label}
        </Button>
      </div>
    </div>
  );
}
