/** Sentinel selection: the "Uncommitted changes" entry (local pre-PR
 * surface). Reported by the commit dropdown's selection callback to mean
 * "diff only the not-yet-committed working-tree changes" - exclusive with
 * a commit/range selection. GitHub never produces it. */
export const UNCOMMITTED_SHA = 'UNCOMMITTED';

/** The commit-dropdown selection union. `null` = all changes; a Set =
 * a commit/range scope; `UNCOMMITTED_SHA` = uncommitted-only. */
export type CommitScopeSelection =
  | ReadonlySet<string>
  | null
  | typeof UNCOMMITTED_SHA;

/** Minimal commit shape the dropdown renders. The GitHub source
 * (`PRCommitWithStats`) is a structural superset, so it feeds the same
 * field; the local surface supplies its own newest-first list. */
export interface LocalCommitListItem {
  sha: string;
  message: string;
  authorName: string;
  authorLogin: string | null;
  avatarUrl: string | null;
  date: string;
  additions: number;
  deletions: number;
  changedFiles: number | null;
}

// Small keystroke hint built on shadcn Badge. Replaces the legacy
// `Kbd` from `ui/primitives` (ADR 0011 - shadcn-only UI surface).
function Kbd({ children }: { children: ReactNode }) {
  return (
    <Badge
      variant="outline"
      className="h-[18px] min-w-[18px] justify-center rounded px-1 py-0 text-[10.5px] font-medium text-muted-foreground"
    >
      {children}
    </Badge>
  );
}

// ── Commit selector ───────────────────────────────────────────────
//
// Multi-select picker per shadcn-app.jsx · ShadcnCommitsPopover.
// Selection model:
//   • `applied` (string Set | null) is the committed selection lifted
//     to the parent. null = "all commits" (the full PR diff). A set
//     equal to the full commit list also reads as "all" in the UI.
//   • `staged` is the popover's working set. Mutated freely while the
//     popover is open. Discarded on Cancel; flushed to `applied` on
//     "Show diff".
// Range footer: shows oldest→newest selected SHA, git-convention
// ordering. Cancels apply only the committed selection - the trigger
// label reflects `applied`.

function relativeAgo(iso: string): string {
  const t = new Date(iso).getTime();
  if (!Number.isFinite(t)) return '';
  const s = Math.max(0, (Date.now() - t) / 1000);
  if (s < 60) return `${Math.round(s)}s`;
  if (s < 3600) return `${Math.round(s / 60)}m`;
  if (s < 86400) return `${Math.round(s / 3600)}h`;
  return `${Math.round(s / 86400)}d`;
}

// Commit-picker popover persisted size. Module-scope so `readSavedSize`
// and the ref callback that uses it can be stable (see popoverRefCallback).
const SIZE_LS_KEY = 'pyor:commits-picker-size:v1';

function readSavedSize(): { w: number; h: number } | null {
  try {
    const raw = localStorage.getItem(SIZE_LS_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (
      typeof parsed?.w === 'number' &&
      typeof parsed?.h === 'number' &&
      parsed.w > 0 &&
      parsed.h > 0
    ) {
      return { w: parsed.w, h: parsed.h };
    }
  } catch {
    /* ignore */
  }
  return null;
}

export function CommitSelector({
  commits,
  owner,
  repo,
  number,
  baseRef,
  headRef,
  baseSha,
  headSha,
  selectedShas,
  onSelectedShasChange,
  commitList,
  showUncommittedOption,
}: {
  commits: number;
  owner?: string;
  repo?: string;
  number?: number;
  baseRef?: string;
  headRef?: string;
  baseSha?: string;
  headSha?: string;
  selectedShas: CommitScopeSelection;
  onSelectedShasChange?: (sel: CommitScopeSelection) => void;
  /** Local-surface commit list (newest-first). When supplied it REPLACES
   * the GitHub commits query as the dropdown's source. */
  commitList?: ReadonlyArray<LocalCommitListItem>;
  /** Local-surface: render a pinned "Uncommitted changes" entry, exclusive
   * with any commit/range selection. */
  showUncommittedOption?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const [filter, setFilter] = useState('');
  // Whether the popover's working selection is the "Uncommitted changes"
  // entry (exclusive with `staged` commits). Local-surface only.
  const [uncommittedStaged, setUncommittedStaged] = useState(false);
  // Inclusion model: `null` = "all changes" (no filter, nothing checked);
  // a Set = scope the diff to exactly those commits (empty Set = hide
  // every file). Representing "all" as a sentinel - rather than a fully
  // materialized set of every SHA - is what lets this picker work
  // WITHOUT ever holding the complete commit list, so it can lazily
  // paginate like the Commits tab instead of eager-fetching up to 250.
  const [staged, setStaged] = useState<Set<string> | null>(null);

  // Hover index (display order) - drives the range PREVIEW banding while a
  // single commit is picked (telegraphs the range a second click makes).
  const [hover, setHover] = useState<number | null>(null);

  // Full commit list (GitHub caps at 250), fetched on open. The range
  // picker needs the COMPLETE ordered set - to fill every commit between
  // two endpoints and to label the newest/oldest ends - so it loads the
  // whole list rather than lazily paginating. Shares ChangesTab's
  // `all-commits` cache key.
  const commitsQuery = useQuery({
    ...prCommitsStatsOptions(owner!, repo!, number!),
    enabled: open && !commitList && !!(owner && repo && number),
    staleTime: 60_000,
  });
  // Newest → oldest (index 0 = top = newest), per the range-picker design.
  // GitHub returns commits oldest-first, so reverse for display + the
  // endpoint index math below. The local surface supplies its own
  // newest-first list, used verbatim.
  const displayCommits = useMemo<LocalCommitListItem[]>(
    () =>
      commitList ? [...commitList] : [...(commitsQuery.data ?? [])].reverse(),
    [commitList, commitsQuery.data],
  );

  // Sync staged ← applied whenever the popover opens, so a Cancel
  // reverts cleanly. We mirror applied as a concrete Set; null is
  // represented as "all SHAs known so far".
  function openPopover(next: boolean) {
    if (next) {
      // Reflect the applied filter: the uncommitted sentinel, a concrete
      // Set when a commit scope is active, else null ("all changes").
      const isUncommitted = selectedShas === UNCOMMITTED_SHA;
      setUncommittedStaged(isUncommitted);
      setStaged(
        selectedShas && selectedShas !== UNCOMMITTED_SHA
          ? new Set(selectedShas)
          : null,
      );
    } else {
      setStaged(null);
      setUncommittedStaged(false);
    }
    setOpen(next);
  }

  // null = "all changes"; a Set = explicit inclusion (empty = hide all).
  // "No filter" = all changes, represented by EITHER the null sentinel
  // or an empty selection - so unchecking every commit is the natural
  // reset (no bulk "all changes" button needed). A non-empty Set scopes
  // the diff to exactly those commits.
  // The diff is ALWAYS a contiguous span: GitHub renders
  // `compare(parent(earliest)…latest)`, which folds in every commit
  // between the earliest and latest selected. So the picker selection is
  // modelled as a contiguous range - `effectiveStaged` fills `staged` to
  // its hull over the chronological commit list, so what's checked
  // exactly matches what the diff shows (no misleading "I only picked 2"
  // when 6 are actually rendered). `staged` itself stays a hull after
  // every interaction; this memo also repairs a hand-edited/non-contiguous
  // URL once the commit list loads.
  const orderShas = displayCommits.map((c) => c.sha);
  const effectiveStaged = useMemo<Set<string> | null>(() => {
    if (!staged || staged.size === 0) return staged;
    const idxs = orderShas
      .map((s, i) => (staged.has(s) ? i : -1))
      .filter((i) => i >= 0);
    if (idxs.length === 0) return staged; // none loaded yet → show as-is
    const lo = idxs[0];
    const hi = idxs[idxs.length - 1];
    const hull = new Set<string>();
    for (let i = lo; i <= hi; i++) hull.add(orderShas[i]);
    staged.forEach((s) => hull.add(s)); // keep any not-yet-loaded picks
    return hull;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [staged, displayCommits]);

  const stagedSize = effectiveStaged?.size ?? 0;
  const isAllChanges = stagedSize === 0;

  // Endpoint indices (in newest→oldest display order) of the current
  // selection: `lo` = newer end (top), `hi` = older end (bottom). These
  // drive the range rail, the newest/oldest labels, and the live
  // base..head + footer SHAs.
  const selIdxs = orderShas
    .map((s, i) => (effectiveStaged?.has(s) ? i : -1))
    .filter((i) => i >= 0);
  const lo = selIdxs.length ? selIdxs[0] : null;
  const hi = selIdxs.length ? selIdxs[selIdxs.length - 1] : null;
  const single = stagedSize === 1;
  const hasRange = stagedSize > 1;
  const newSha = lo !== null ? displayCommits[lo]?.sha : undefined; // newest
  const oldSha = hi !== null ? displayCommits[hi]?.sha : undefined; // oldest

  // Summed diff stats across the selected range - the total lines the
  // picked commits add/remove (sum of each commit's own +/-).
  const tot = useMemo(() => {
    if (lo === null || hi === null) return { add: 0, del: 0 };
    let add = 0;
    let del = 0;
    for (let i = lo; i <= hi; i++) {
      add += displayCommits[i]?.additions ?? 0;
      del += displayCommits[i]?.deletions ?? 0;
    }
    return { add, del };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lo, hi, displayCommits]);

  // Range PREVIEW while a single commit is picked: hovering another row
  // telegraphs the range a second click would create.
  const preview =
    single && hover !== null && lo !== null && hover !== lo
      ? { lo: Math.min(lo, hover), hi: Math.max(lo, hover) }
      : null;
  const previewCount = preview ? preview.hi - preview.lo + 1 : 0;
  const inRange = (i: number) => lo !== null && hi !== null && i >= lo && i <= hi;
  const inPreview = (i: number) => !!preview && i >= preview.lo && i <= preview.hi;

  // Persisted resize. The popover uses native CSS `resize: both`, so
  // the *browser* owns the inline `width`/`height` style during the
  // drag. React must not own those properties: a controlled style
  // prop fights the drag (a ResizeObserver fires after every drag
  // tick, which triggers a re-render that snaps the element back to
  // the previously-observed value, blocking further dragging).
  // Instead we set the saved size *imperatively* via a ref callback
  // on each mount, then let the browser drive subsequent changes,
  // and persist deltas through a ResizeObserver that writes straight
  // to localStorage without touching React state.
  const popoverContentRef = useRef<HTMLDivElement | null>(null);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);
  // Callback ref invoked by Radix when PopoverContent (re)mounts.
  // Restores the saved size and attaches a fresh observer. MUST be stable
  // (useCallback, empty deps - it only touches stable refs + module-scope
  // helpers): Radix composes this with its own state-setter refs, so a
  // fresh identity each render would make React re-run the whole composed
  // ref every commit, looping its internal setState → "Maximum update
  // depth exceeded".
  const popoverRefCallback = useCallback((el: HTMLDivElement | null) => {
    popoverContentRef.current = el;
    // Tear down any prior observer (e.g. on close - Radix calls the
    // ref with `null` when unmounting).
    if (resizeObserverRef.current) {
      resizeObserverRef.current.disconnect();
      resizeObserverRef.current = null;
    }
    if (!el) return;
    const saved = readSavedSize();
    if (saved) {
      el.style.width = `${saved.w}px`;
      el.style.height = `${saved.h}px`;
    } else {
      el.style.width = '480px';
      el.style.height = '480px';
    }
    const ro = new ResizeObserver(() => {
      const w = el.offsetWidth;
      const h = el.offsetHeight;
      if (w <= 0 || h <= 0) return;
      try {
        localStorage.setItem(SIZE_LS_KEY, JSON.stringify({ w, h }));
      } catch {
        /* ignore */
      }
    });
    ro.observe(el);
    resizeObserverRef.current = ro;
  }, []);

  // Contiguous-range selection. Because the diff is always the span
  // parent(earliest)…latest, the selection can only ever BE a contiguous
  // range, so a click adjusts the range rather than toggling one commit.
  //
  // Dynamic-anchor model: the anchor is recomputed on EVERY click as the
  // current endpoint FARTHEST from the clicked commit; the near endpoint
  // jumps to the click. New range = [min(anchor, click) .. max(anchor,
  // click)]. This changes the fewest commits possible, in either
  // direction:
  //   - click OUTSIDE the range → extends out to the clicked commit
  //   - click INSIDE near an edge → trims only that edge in to the click
  //   - click the lone selected commit again → clear
  // Exact-middle tie → keep the low end as anchor (trims the older side).
  // `order` is the display commit list (newest→oldest); ranges are
  // computed by index against it, so they're stable under filtering +
  // virtualization. No stored anchor needed - it's derived each click.
  function activate(sha: string) {
    // Picking a commit cancels the exclusive "Uncommitted changes" entry.
    setUncommittedStaged(false);
    const order = orderShas;
    const k = order.indexOf(sha);
    if (k < 0) return; // commit not loaded yet - ignore
    const cur = effectiveStaged ?? new Set<string>();
    const idxs = order
      .map((s, i) => (cur.has(s) ? i : -1))
      .filter((i) => i >= 0);

    // Nothing selected → start a single-commit selection.
    if (idxs.length === 0) {
      setStaged(new Set([sha]));
      return;
    }

    const curLo = idxs[0];
    const curHi = idxs[idxs.length - 1];

    // Clicking the lone selected commit again clears the filter.
    if (curLo === curHi && k === curLo) {
      setStaged(null);
      return;
    }

    // Anchor = the endpoint farther from the click (tie → low end).
    const anchorIdx = Math.abs(k - curLo) >= Math.abs(k - curHi) ? curLo : curHi;
    const newLo = Math.min(anchorIdx, k);
    const newHi = Math.max(anchorIdx, k);
    const next = new Set<string>();
    for (let i = newLo; i <= newHi; i++) next.add(order[i]);
    setStaged(next);
  }
  const clearSel = () => {
    setStaged(null);
    setHover(null);
    setUncommittedStaged(false);
  };
  const selectAll = () => {
    setStaged(new Set(orderShas));
    setUncommittedStaged(false);
  };
  const pickUncommitted = () => {
    setUncommittedStaged(true);
    setStaged(null);
    setHover(null);
  };

  function showDiff() {
    if (uncommittedStaged) {
      onSelectedShasChange?.(UNCOMMITTED_SHA);
      setOpen(false);
      return;
    }
    // Empty selection → "all changes" (null applied). Otherwise apply the
    // FULL contiguous range (effectiveStaged), so the applied selection,
    // the checkboxes, and the rendered diff all agree.
    onSelectedShasChange?.(
      !effectiveStaged || effectiveStaged.size === 0
        ? null
        : new Set(effectiveStaged),
    );
    setOpen(false);
  }
  function cancel() {
    setOpen(false);
  }

  // Trigger label reflects the *applied* selection. Compare the sentinel
  // directly so TS narrows `selectedShas` to `Set | null` in the else.
  const appliedUncommitted = selectedShas === UNCOMMITTED_SHA;
  const appliedSet: ReadonlySet<string> | null =
    selectedShas === UNCOMMITTED_SHA ? null : selectedShas;
  const appliedAll = !appliedUncommitted && appliedSet == null;
  const appliedCount = appliedSet?.size ?? 0;
  const label = (() => {
    if (appliedUncommitted) return 'Uncommitted changes';
    if (commits === 0) {
      return showUncommittedOption ? 'All changes' : '- commits';
    }
    if (appliedAll) return `${commits} ${commits === 1 ? 'commit' : 'commits'}`;
    return `${appliedCount} of ${commits}`;
  })();

  const filtered = displayCommits.filter((c) => {
    if (!filter) return true;
    const q = filter.toLowerCase();
    return (
      c.message.toLowerCase().includes(q) ||
      c.sha.startsWith(q) ||
      c.authorName.toLowerCase().includes(q) ||
      (c.authorLogin?.toLowerCase().includes(q) ?? false)
    );
  });

  return (
    <Popover open={open} onOpenChange={openPopover}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="xs"
          disabled={commits === 0 && !showUncommittedOption}
          title={
            commits === 0 && !showUncommittedOption
              ? 'No commits to pick from'
              : 'Pick the commit / uncommitted scope for the diff'
          }
        >
          <GitCommitIcon />
          <span className={appliedAll ? '' : 'font-semibold text-primary'}>
            {label}
          </span>
          {appliedAll && commits > 0 && (
            <span className="text-muted-foreground/70">· all changes</span>
          )}
          <ChevronDownIcon className="text-muted-foreground/70" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        ref={popoverRefCallback}
        align="start"
        sideOffset={6}
        className="flex flex-col overflow-hidden p-0 resize"
        style={{
          minWidth: 380,
          minHeight: 360,
          maxWidth: 'min(900px, 96vw)',
          maxHeight: 'min(800px, 80vh)',
        }}
      >
        {/* Header - title + live mode pill + count + clear / select-all */}
        <div className="flex items-center gap-2 border-b px-3.5 py-2.5">
          <GitCommitIcon className="size-3.5 text-muted-foreground" />
          <span className="text-[13px] font-semibold tracking-tight">
            {hasRange ? 'Comparing a range' : 'Comparing commits'}
          </span>
          {hasRange ? (
            <span className="inline-flex items-center gap-1 rounded-full bg-primary px-2 py-0.5 text-[10px] font-medium text-primary-foreground">
              <ArrowUpDownIcon className="size-2.5" />
              range
            </span>
          ) : single ? (
            <span className="rounded-full border px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
              single
            </span>
          ) : null}
          <span className="ml-auto text-[11.5px] tabular-nums text-muted-foreground">
            {stagedSize} of {commits} selected
          </span>
          {isAllChanges ? (
            <button
              type="button"
              onClick={selectAll}
              className="text-[12px] font-medium hover:underline"
            >
              Select all
            </button>
          ) : (
            <button
              type="button"
              onClick={clearSel}
              className="text-[12px] font-medium hover:underline"
            >
              Clear
            </button>
          )}
        </div>

        {/* Selection summary - base..head reflecting the LIVE range:
            head = newest selected, base = parent of the oldest (`~1`). */}
        <div className="grid grid-cols-[60px_1fr] gap-y-1.5 border-b px-3.5 py-2.5 text-[12px]">
          <span className="self-center text-[10.5px] uppercase tracking-wider text-muted-foreground">
            Base
          </span>
          <span className="inline-flex items-center gap-1.5">
            <GitBranchIcon className="size-3 text-muted-foreground" />
            <span className="font-mono text-[11.5px]">{baseRef ?? '-'}</span>
            <span className="text-muted-foreground/40">@</span>
            <span className="font-mono text-[11.5px] text-muted-foreground">
              {oldSha
                ? `${oldSha.slice(0, 7)}~1`
                : (baseSha?.slice(0, 7) ?? '-')}
            </span>
          </span>
          <span className="self-center text-[10.5px] uppercase tracking-wider text-muted-foreground">
            Head
          </span>
          <span className="inline-flex items-center gap-1.5">
            <GitBranchIcon className="size-3 text-muted-foreground" />
            <span className="font-mono text-[11.5px]">{headRef ?? '-'}</span>
            <span className="text-muted-foreground/40">@</span>
            <span className="font-mono text-[11.5px] text-muted-foreground">
              {newSha ? newSha.slice(0, 7) : (headSha?.slice(0, 7) ?? '-')}
            </span>
          </span>
        </div>

        {/* Filter */}
        <div className="flex items-center gap-2 border-b px-3.5 py-2">
          <div className="flex h-7 flex-1 items-center gap-2 rounded-md border bg-background px-2.5">
            <SearchIcon className="size-3.5 text-muted-foreground" />
            <input
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              placeholder="Filter commits"
              className="flex-1 border-0 bg-transparent p-0 text-[12px] outline-none placeholder:text-muted-foreground"
            />
          </div>
        </div>

        {/* Pinned "Uncommitted changes" entry (local surface) - exclusive
            with any commit/range pick. Always visible above the list. */}
        {showUncommittedOption && (
          // role=button (not a real <button>) so the nested Checkbox - which
          // renders its own <button> - doesn't produce an invalid
          // button-in-button. Mirrors the commit rows below.
          <div
            role="button"
            tabIndex={0}
            onClick={pickUncommitted}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                pickUncommitted();
              }
            }}
            className={cn(
              'flex w-full cursor-pointer items-center gap-2.5 border-b px-3.5 py-2.5 text-left outline-none hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring',
              uncommittedStaged ? 'bg-muted/60' : '',
            )}
          >
            <span className="relative w-9 shrink-0 self-stretch">
              <span className="absolute left-[18px] top-1/2 -translate-x-1/2 -translate-y-1/2">
                <Checkbox
                  checked={uncommittedStaged}
                  onCheckedChange={pickUncommitted}
                  onClick={(e) => e.stopPropagation()}
                  aria-label="Uncommitted changes"
                />
              </span>
            </span>
            <FileDiffIcon className="size-4 shrink-0 text-muted-foreground" />
            <div className="min-w-0 flex-1">
              <div className="text-[12.5px] font-medium text-foreground">
                Uncommitted changes
              </div>
              <div className="mt-0.5 text-[11px] text-muted-foreground">
                Working tree vs the last commit
              </div>
            </div>
          </div>
        )}

        {/* Commit list - virtualized over the full (≤250) list. The left
            cell is a checkbox in empty/single mode and MORPHS into a
            vertical range rail (connecting line + endpoint handles +
            in-range dots) once a range exists. */}
        <div className="min-h-0 flex-1">
          {!commitList && commitsQuery.isPending ? (
            <div className="px-3 py-6 text-center text-[12.5px] text-muted-foreground">
              Loading commits…
            </div>
          ) : !commitList && commitsQuery.error ? (
            <div className="px-3 py-6 text-center text-[12.5px] text-destructive">
              {(commitsQuery.error as Error).message}
            </div>
          ) : filtered.length === 0 ? (
            <div className="px-3 py-6 text-center text-[12.5px] text-muted-foreground">
              {filter ? 'No matching commits' : 'No commits'}
            </div>
          ) : (
            <Virtuoso
              style={{ height: '100%', width: '100%' }}
              data={filtered}
              computeItemKey={(_, c) => c.sha}
              itemContent={(index, c) => {
                // True display index - the filtered index differs from the
                // display index while a search filter is active.
                const i = orderShas.indexOf(c.sha);
                const within = inRange(i);
                const isLo = i === lo;
                const isHi = i === hi;
                const isEdge = within && (isLo || isHi);
                const prev = inPreview(i);
                return (
                  <div
                    role="button"
                    tabIndex={0}
                    onClick={() => activate(c.sha)}
                    onMouseEnter={() => setHover(i)}
                    onMouseLeave={() =>
                      setHover((h) => (h === i ? null : h))
                    }
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        activate(c.sha);
                      }
                    }}
                    className={cn(
                      'group/cm relative flex w-full cursor-pointer items-start gap-2.5 py-2 pr-3.5 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring',
                      within
                        ? 'bg-muted/60'
                        : prev
                          ? 'bg-muted/30'
                          : '',
                      index ? 'border-t' : '',
                      'hover:bg-muted/50',
                    )}
                  >
                    {/* Left cell: checkbox (empty/single) OR range rail */}
                    <div className="relative w-9 shrink-0 self-stretch">
                      {hasRange ? (
                        <>
                          {/* connecting line - solid through the range,
                              faint outside */}
                          <span
                            className={cn(
                              'absolute left-[18px] top-0 h-1/2 w-0.5 -translate-x-1/2',
                              within && i > lo! ? 'bg-primary' : 'bg-border',
                            )}
                          />
                          <span
                            className={cn(
                              'absolute left-[18px] bottom-0 h-1/2 w-0.5 -translate-x-1/2',
                              within && i < hi! ? 'bg-primary' : 'bg-border',
                            )}
                          />
                          {/* node: endpoint handle / in-range dot / hollow */}
                          {isEdge ? (
                            <span className="absolute left-[18px] top-1/2 flex size-4 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-primary shadow-sm ring-2 ring-background">
                              <span className="size-1.5 rounded-full bg-background" />
                            </span>
                          ) : within ? (
                            <span className="absolute left-[18px] top-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary" />
                          ) : (
                            <span className="absolute left-[18px] top-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full border border-muted-foreground/40 bg-background group-hover/cm:border-muted-foreground/70" />
                          )}
                        </>
                      ) : (
                        <span className="absolute left-[18px] top-1/2 -translate-x-1/2 -translate-y-1/2">
                          <Checkbox
                            checked={single && isLo}
                            onCheckedChange={() => activate(c.sha)}
                            onClick={(e) => e.stopPropagation()}
                            aria-label={`Select commit ${c.sha.slice(0, 7)}`}
                          />
                        </span>
                      )}
                    </div>
                    <Avatar className="mt-0.5 size-5">
                      {c.avatarUrl && (
                        <AvatarImage
                          src={c.avatarUrl}
                          alt={c.authorLogin ?? c.authorName}
                        />
                      )}
                      <AvatarFallback className="text-[9px]">
                        {(c.authorLogin ?? c.authorName)
                          .slice(0, 2)
                          .toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                    <div className="min-w-0 flex-1">
                      <div className="truncate text-[12.5px] text-foreground">
                        {c.message.split('\n')[0]}
                      </div>
                      <div className="mt-0.5 flex items-center gap-1.5 text-[11px] text-muted-foreground">
                        <span className="font-mono text-foreground/80">
                          {c.sha.slice(0, 7)}
                        </span>
                        <span className="text-muted-foreground/30">·</span>
                        <span className="truncate">
                          {c.authorLogin ?? c.authorName}
                        </span>
                        <span className="text-muted-foreground/30">·</span>
                        <span className="whitespace-nowrap">
                          {relativeAgo(c.date)}
                        </span>
                        {isEdge && (
                          <Badge
                            variant="outline"
                            className="ml-0.5 px-1 py-0 text-[9.5px] font-medium"
                          >
                            {isLo ? 'newest' : 'oldest'}
                          </Badge>
                        )}
                      </div>
                    </div>
                    {/* Per-commit diff stats */}
                    <span className="mt-0.5 shrink-0 whitespace-nowrap font-mono text-[10.5px] tabular-nums">
                      <DiffStat
                        additions={c.additions}
                        deletions={c.deletions}
                        addClassName="text-emerald-600 dark:text-emerald-500"
                        delClassName="text-red-600 dark:text-red-500"
                      />
                      {c.changedFiles != null && (
                        <span
                          className="ml-1.5 inline-flex items-center gap-0.5 align-middle text-muted-foreground"
                          title={`${c.changedFiles} file${c.changedFiles === 1 ? '' : 's'} changed`}
                        >
                          <FileDiffIcon className="size-3" />
                          {c.changedFiles}
                        </span>
                      )}
                    </span>
                  </div>
                );
              }}
            />
          )}
        </div>

        {/* Footer - contextual hint / range summary + action */}
        <div className="flex items-center gap-2 border-t bg-muted/40 px-3.5 py-2.5">
          <span className="min-w-0 flex-1 truncate text-[11.5px] text-muted-foreground">
            {uncommittedStaged ? (
              'Diff the uncommitted working-tree changes only'
            ) : isAllChanges ? (
              'Pick a commit, then pick another to compare a range'
            ) : preview ? (
              <>
                Select range ·{' '}
                <span className="font-medium text-foreground">
                  {previewCount} commits
                </span>
              </>
            ) : single ? (
              <>
                1 commit ·{' '}
                <span className="font-mono text-foreground">
                  {newSha?.slice(0, 7)}
                </span>{' '}
                - click another to make a range
              </>
            ) : (
              <>
                <span className="font-mono text-foreground">
                  {oldSha?.slice(0, 7)}..{newSha?.slice(0, 7)}
                </span>{' '}
                ·{' '}
                <span className="font-mono text-emerald-600 dark:text-emerald-500">
                  +{tot.add}
                </span>{' '}
                <span className="font-mono text-red-600 dark:text-red-500">
                  −{tot.del}
                </span>
              </>
            )}
          </span>
          <Button variant="ghost" size="sm" onClick={cancel}>
            Cancel
          </Button>
          <Button
            variant="default"
            size="sm"
            onClick={showDiff}
            disabled={commits === 0 && !uncommittedStaged}
          >
            <GitCommitIcon />
            {uncommittedStaged
              ? 'Show uncommitted changes'
              : isAllChanges
                ? 'Show all changes'
                : `Show diff · ${stagedSize} commit${stagedSize === 1 ? '' : 's'}`}
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

// ── Search in diff ────────────────────────────────────────────────

function DiffSearchControl({
  active,
  query,
  onActivate,
  onClose,
  onChange,
  matchCount,
  matchFileCount,
  matchIndex,
  onNext,
  onPrev,
}: {
  active: boolean;
  query: string;
  onActivate: () => void;
  onClose: () => void;
  onChange: (s: string) => void;
  matchCount?: number;
  matchFileCount?: number;
  matchIndex: number | null;
  onNext?: () => void;
  onPrev?: () => void;
}) {
  if (!active) {
    return (
      <Button
        variant="outline"
        size="xs"
        onClick={onActivate}
        className="min-w-[180px] justify-start text-muted-foreground"
      >
        <SearchIcon className="text-muted-foreground" />
        <span className="flex-1 text-left">Search in diff</span>
        <Kbd>⌘/</Kbd>
      </Button>
    );
  }
  return (
    <ActiveDiffSearch
      query={query}
      onClose={onClose}
      onChange={onChange}
      matchCount={matchCount}
      matchFileCount={matchFileCount}
      matchIndex={matchIndex}
      onNext={onNext}
      onPrev={onPrev}
    />
  );
}

// The active search field buffers its value in LOCAL state rather than
// reading it straight from the URL-backed `query` prop. Each keystroke
// used to route through the router (the `dq` search param) AND trigger a
// synchronous diff-highlight recompute across every file - on a real PR
// that froze the main thread per keystroke, so the caret felt stuck,
// arrow keys and deletes felt broken, and characters dropped. The buffer
// keeps typing instant; the URL (and the highlight pass it drives) update
// on a short debounce. This component only mounts while search is open,
// so `useState(query)` reseeds on every open - a fresh open after a close
// (where the parent has cleared `dq`) correctly starts empty, and a
// deep-link that opens with an existing `dq` seeds from it.
function ActiveDiffSearch({
  query,
  onClose,
  onChange,
  matchCount,
  matchFileCount,
  matchIndex,
  onNext,
  onPrev,
}: {
  query: string;
  onClose: () => void;
  onChange: (s: string) => void;
  matchCount?: number;
  matchFileCount?: number;
  matchIndex: number | null;
  onNext?: () => void;
  onPrev?: () => void;
}) {
  const [value, setValue] = useState(query);
  const pushTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cancelPush = () => {
    if (pushTimer.current) clearTimeout(pushTimer.current);
    pushTimer.current = null;
  };
  const schedulePush = (next: string) => {
    setValue(next);
    cancelPush();
    pushTimer.current = setTimeout(() => onChange(next), 150);
  };
  // Enter navigates matches, so the pending value must land first.
  const flushPush = () => {
    cancelPush();
    onChange(value);
  };
  const close = () => {
    cancelPush();
    onClose();
  };
  const hasQuery = value.trim().length > 0;
  const hasMatches = (matchCount ?? 0) > 0;
  // Prev/next navigation only renders when handlers are wired. The
  // compact toolbar shows the match *count* but no jump buttons, so it
  // omits them and the counter reads "N in M files" rather than "X of N".
  const showNav = !!(onNext || onPrev);
  const fileLabel = `file${matchFileCount === 1 ? '' : 's'}`;
  // Clamp the displayed hit number to the live count. The owned index resets
  // only on query change, but the count can shrink for other reasons (e.g.
  // contents finish streaming and a fallback match drops), which would
  // otherwise render "Hit 6 of 3" for a frame.
  const displayHit = Math.min((matchIndex ?? 0) + 1, matchCount ?? 0);
  return (
    <div className="inline-flex h-7 min-w-[260px] items-center gap-1 rounded-md border border-primary bg-background pl-2 pr-1 shadow-[0_0_0_3px_rgba(10,132,255,0.12)] dark:shadow-[0_0_0_3px_rgba(90,169,255,0.18)]">
      <SearchIcon className="size-3.5 text-primary" />
      <Input
        autoFocus
        value={value}
        onChange={(e) => schedulePush(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' && onNext) {
            e.preventDefault();
            flushPush();
            if (e.shiftKey) onPrev?.();
            else onNext();
          } else if (e.key === 'Escape') {
            e.preventDefault();
            close();
          }
        }}
        placeholder="Search diff content"
        className="h-7 flex-1 border-0 bg-transparent px-1 text-[12px] shadow-none focus-visible:ring-0"
      />
      {hasQuery && (
        <span
          className={`shrink-0 whitespace-nowrap px-1.5 text-[11px] tabular-nums ${
            hasMatches ? 'text-muted-foreground' : 'text-destructive'
          }`}
          title={
            hasMatches
              ? showNav
                ? `Hit ${displayHit} of ${matchCount} across ${matchFileCount} ${fileLabel}`
                : `${matchCount} match${matchCount === 1 ? '' : 'es'} across ${matchFileCount} ${fileLabel}`
              : 'No matches in this PR'
          }
        >
          {!hasMatches ? (
            'No matches'
          ) : showNav ? (
            <>
              <span className="font-semibold text-foreground">
                {displayHit}
              </span>
              <span className="text-muted-foreground/60"> of </span>
              {matchCount}
            </>
          ) : (
            <>
              <span className="font-semibold text-foreground">{matchCount}</span>
              <span className="text-muted-foreground/60"> in </span>
              {matchFileCount} {fileLabel}
            </>
          )}
        </span>
      )}
      {showNav && (
        <>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-6"
            disabled={!hasMatches}
            onClick={onPrev}
            title="Previous match (Shift+Enter)"
          >
            <ChevronUpIcon />
          </Button>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="size-6"
            disabled={!hasMatches}
            onClick={onNext}
            title="Next match (Enter)"
          >
            <ChevronDownIcon />
          </Button>
        </>
      )}
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="size-6"
        onClick={close}
      >
        <XIcon />
      </Button>
    </div>
  );
}

// ── Bulk collapse controls ────────────────────────────────────────
// One compact dropdown replaces what used to be three side-by-side
// buttons. The trigger is icon + chevron only - collapse actions are
// secondary controls, so saving toolbar real estate matters more than
// one-click access.

export function CollapseControls({
  onCollapseAll,
  onExpandAll,
  onResetCollapse,
  onCollapseWithoutComments,
  filesWithoutCommentsCount,
}: {
  onCollapseAll?: () => void;
  onExpandAll?: () => void;
  onResetCollapse?: () => void;
  onCollapseWithoutComments?: () => void;
  filesWithoutCommentsCount?: number;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="xs"
          className="gap-1"
          aria-label="Bulk collapse controls"
          title="Bulk collapse / expand"
        >
          <FoldVerticalIcon />
          <ChevronDownIcon className="text-muted-foreground/70" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-[240px]">
        {onCollapseAll && (
          <DropdownMenuItem onSelect={onCollapseAll}>
            <FoldVerticalIcon />
            <span>Collapse all files</span>
          </DropdownMenuItem>
        )}
        {onExpandAll && (
          <DropdownMenuItem onSelect={onExpandAll}>
            <UnfoldVerticalIcon />
            <span>Expand all files</span>
          </DropdownMenuItem>
        )}
        {onCollapseWithoutComments && (
          <DropdownMenuItem
            onSelect={onCollapseWithoutComments}
            disabled={filesWithoutCommentsCount === 0}
          >
            <MessageSquareOffIcon />
            <span className="flex-1">Collapse files without comments</span>
            {typeof filesWithoutCommentsCount === 'number' && (
              <span className="ml-2 text-[11px] tabular-nums text-muted-foreground">
                {filesWithoutCommentsCount}
              </span>
            )}
          </DropdownMenuItem>
        )}
        {onResetCollapse && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem onSelect={onResetCollapse}>
              <RotateCcwIcon />
              <span>Reset to viewed-state</span>
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

// ── Compact toolbar (tab-bar slot variant) ────────────────────────
// Rendered in the PRTabStrip's right slot when the Changes tab is
// active - the live Changes-tab toolbar.

export interface CompactChangesToolbarProps {
  /** The "Review with AI" trigger (with its rich tooltip), shown next to the
   * commits dropdown. Null off the Changes tab or when AI is off. */
  aiReviewTrigger?: ReactNode;
  diffMode: DiffMode;
  onDiffModeChange: (m: DiffMode) => void;
  search: string | null;
  onSearchChange: (s: string | null) => void;
  /** Total diff-search hits + the number of files they span. With
   * `onSearchNext`/`onSearchPrev` wired the box shows "X of N" + prev/next
   * arrows (Enter / Shift+Enter); without them it shows "N in M files". */
  searchMatchCount?: number;
  searchMatchFileCount?: number;
  /** Current hit index (0-based) for the "X of N" counter. */
  searchMatchIndex?: number;
  /** Jump to the next / previous hit. Also enables the in-box arrows and
   * makes Enter / Shift+Enter navigate. */
  onSearchNext?: () => void;
  onSearchPrev?: () => void;
  commits?: number;
  viewed?: number;
  totalFiles?: number;
  /** Local pre-PR surface: the all-changes rollup viewed-state + whether a
   * commit scope is active. When `overallViewed` is set, the toolbar shows
   * the dual `ScopedViewed` indicator instead of the single ring. */
  overallViewed?: number;
  overallTotal?: number;
  scoped?: boolean;
  contentsProgress?: { resolved: number; total: number };
  isFilesLoading?: boolean;
  owner?: string;
  repo?: string;
  number?: number;
  baseRef?: string;
  headRef?: string;
  baseSha?: string;
  headSha?: string;
  selectedCommitShas?: CommitScopeSelection;
  onSelectedCommitShasChange?: (sel: CommitScopeSelection) => void;
  /** Local-surface commit source (newest-first). Replaces the GitHub
   * commits query when supplied. */
  commitList?: ReadonlyArray<LocalCommitListItem>;
  /** Local-surface: render the pinned "Uncommitted changes" entry. */
  showUncommittedOption?: boolean;
  /** Bulk collapse / expand / reset overrides - drive the
   * FoldVertical dropdown (same as the full SubToolbar's). When none
   * are provided the dropdown is omitted. */
  onCollapseAll?: () => void;
  onExpandAll?: () => void;
  onResetCollapse?: () => void;
  onCollapseWithoutComments?: () => void;
  filesWithoutCommentsCount?: number;
}

export function CompactChangesToolbar({
  aiReviewTrigger,
  diffMode,
  onDiffModeChange,
  search,
  onSearchChange,
  searchMatchCount,
  searchMatchFileCount,
  searchMatchIndex,
  onSearchNext,
  onSearchPrev,
  commits,
  viewed = 0,
  totalFiles = 0,
  overallViewed,
  overallTotal,
  scoped = false,
  contentsProgress,
  isFilesLoading,
  owner,
  repo,
  number,
  baseRef,
  headRef,
  baseSha,
  headSha,
  selectedCommitShas,
  onSelectedCommitShasChange,
  commitList,
  showUncommittedOption,
  onCollapseAll,
  onExpandAll,
  onResetCollapse,
  onCollapseWithoutComments,
  filesWithoutCommentsCount,
}: CompactChangesToolbarProps) {
  const [searchOpen, setSearchOpen] = useState(search !== null);
  // sync searchOpen from URL-driven search prop (e.g. shared link landing)
  useEffect(() => {
    if (search !== null) setSearchOpen(true);
  }, [search]);

  const isStreaming =
    !!contentsProgress &&
    contentsProgress.total > 0 &&
    contentsProgress.resolved < contentsProgress.total;

  if (isFilesLoading && !isStreaming) return <CompactPaginating />;
  if (isStreaming)
    return (
      <CompactStreaming
        done={contentsProgress!.resolved}
        total={contentsProgress!.total}
      />
    );

  return (
    <div className="flex items-center gap-2">
      <CommitSelector
        commits={commits ?? 0}
        owner={owner}
        repo={repo}
        number={number}
        baseRef={baseRef}
        headRef={headRef}
        baseSha={baseSha}
        headSha={headSha}
        selectedShas={selectedCommitShas ?? null}
        onSelectedShasChange={onSelectedCommitShasChange}
        commitList={commitList}
        showUncommittedOption={showUncommittedOption}
      />
      {aiReviewTrigger && (
        <>
          <Separator orientation="vertical" className="h-4" />
          {aiReviewTrigger}
        </>
      )}
      <Separator orientation="vertical" className="h-4" />
      {overallViewed != null ? (
        <ScopedViewed
          overallViewed={overallViewed}
          overallTotal={overallTotal ?? 0}
          scopeViewed={viewed}
          scopeTotal={totalFiles}
          scoped={scoped}
        />
      ) : (
        <CompactViewedProgress viewed={viewed} total={totalFiles} />
      )}
      <Separator orientation="vertical" className="h-4" />
      <DiffSearchControl
        active={searchOpen}
        query={search ?? ''}
        onActivate={() => setSearchOpen(true)}
        onClose={() => {
          setSearchOpen(false);
          onSearchChange(null);
        }}
        onChange={onSearchChange}
        matchCount={searchMatchCount}
        matchFileCount={searchMatchFileCount}
        matchIndex={searchMatchIndex ?? null}
        onNext={onSearchNext}
        onPrev={onSearchPrev}
      />
      {(onCollapseAll ||
        onExpandAll ||
        onResetCollapse ||
        onCollapseWithoutComments) && (
        <>
          <Separator orientation="vertical" className="h-4" />
          <CollapseControls
            onCollapseAll={onCollapseAll}
            onExpandAll={onExpandAll}
            onResetCollapse={onResetCollapse}
            onCollapseWithoutComments={onCollapseWithoutComments}
            filesWithoutCommentsCount={filesWithoutCommentsCount}
          />
        </>
      )}
      <CompactDiffModeToggle value={diffMode} onChange={onDiffModeChange} />
    </div>
  );
}

function CompactPaginating() {
  return (
    <div className="flex items-center gap-1.5 text-[11.5px] text-muted-foreground">
      <Loader2Icon className="size-3 animate-spin" />
      <span>listing files</span>
    </div>
  );
}

function CompactStreaming({ done, total }: { done: number; total: number }) {
  const pct = total > 0 ? (done / total) * 100 : 0;
  return (
    <div className="flex items-center gap-1.5 text-[11.5px] text-muted-foreground">
      <Loader2Icon className="size-3 animate-spin" />
      <span>computing diffs</span>
      <span className="tabular-nums">
        {done}/{total}
      </span>
      <div className="relative h-1 w-16 overflow-hidden rounded-full bg-muted">
        <div
          className="absolute inset-y-0 left-0 bg-foreground transition-[width] duration-500"
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

export function CompactViewedProgress({
  viewed,
  total,
  label,
}: {
  viewed: number;
  total: number;
  /** Optional leading text (e.g. "All", "Commit") so two rings can be
   * shown side by side without ambiguity. */
  label?: string;
}) {
  const frac = total > 0 ? viewed / total : 0;
  const R = 6;
  const C = 2 * Math.PI * R;
  return (
    <div className="flex items-center gap-1.5">
      {label && (
        <span className="text-[10.5px] uppercase tracking-wide text-muted-foreground/70">
          {label}
        </span>
      )}
      <EyeIcon className="size-3 text-muted-foreground" />
      {/* circular progress ring */}
      <svg viewBox="0 0 16 16" className="size-3.5 shrink-0 -rotate-90">
        <circle
          cx="8"
          cy="8"
          r={R}
          fill="none"
          strokeWidth="2"
          className="stroke-muted"
        />
        <circle
          cx="8"
          cy="8"
          r={R}
          fill="none"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={C}
          strokeDashoffset={C * (1 - frac)}
          className="stroke-foreground transition-[stroke-dashoffset] duration-300"
        />
      </svg>
      <span className="text-[11px] tabular-nums text-muted-foreground">
        <b className="font-semibold text-foreground">{viewed}</b>/{total}
      </span>
    </div>
  );
}

/** Dual viewed indicator for the local pre-PR surface, where viewed-state
 * is tracked per (commit, path): the OVERALL rollup is always shown, and
 * when a single commit / range / uncommitted scope is active the per-scope
 * ring is shown beside it. In the all-changes view they'd be identical, so
 * only the single (unlabelled) ring renders. */
export function ScopedViewed({
  overallViewed,
  overallTotal,
  scopeViewed,
  scopeTotal,
  scoped,
}: {
  overallViewed: number;
  overallTotal: number;
  scopeViewed: number;
  scopeTotal: number;
  scoped: boolean;
}) {
  if (!scoped) {
    return <CompactViewedProgress viewed={overallViewed} total={overallTotal} />;
  }
  return (
    <div className="flex items-center gap-2">
      <CompactViewedProgress
        viewed={overallViewed}
        total={overallTotal}
        label="All"
      />
      <Separator orientation="vertical" className="h-4" />
      <CompactViewedProgress
        viewed={scopeViewed}
        total={scopeTotal}
        label="Scope"
      />
    </div>
  );
}

export function CompactDiffModeToggle({
  value,
  onChange,
}: {
  value: DiffMode;
  onChange: (m: DiffMode) => void;
}) {
  return (
    <Tabs value={value} onValueChange={(v) => onChange(v as DiffMode)}>
      <TabsList indicator="pill" className="h-7 p-0.5">
        <TabsTrigger
          value="inline"
          title="Inline diff · ⌘⇧I"
          aria-label="Inline diff"
          className="h-6 w-7 p-0 data-[state=active]:bg-transparent data-[state=active]:shadow-none"
        >
          <RowsIcon className="size-3.5" />
        </TabsTrigger>
        <TabsTrigger
          value="split"
          title="Split diff · ⌘⇧S"
          aria-label="Split diff"
          className="h-6 w-7 p-0 data-[state=active]:bg-transparent data-[state=active]:shadow-none"
        >
          <ColumnsIcon className="size-3.5" />
        </TabsTrigger>
      </TabsList>
    </Tabs>
  );
}
