// Changes-tab left rail: file tree / list with viewed-state checkboxes,
// unread dots, +adds −dels stats, filter input, tree/list toggle.
//
// Driven by the live PR's files. When the /files endpoint is still
// paginating (isFilesLoading) we render skeleton rows so the rail has
// visible structure during the cold-fetch window; once files arrive
// the @pierre/trees model takes over.
//
// Built on shadcn primitives + Tailwind utilities consuming the CSS
// variables defined in styles/tailwind.css. The only call into the
// legacy theme tokens here is the `useT()` that feeds `treeThemeStyle`
// — that pipe stays because @pierre/trees renders inside a shadow root
// and reads its palette from CSS custom properties on the host element
// (see treeThemeBridge.ts).

import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';
import type { ForwardedRef } from 'react';
import {
  ChevronLeftIcon,
  EyeIcon,
  FileIcon,
  FolderTreeIcon,
  ListIcon,
  PanelLeftOpenIcon,
  SearchIcon,
  XIcon,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Skeleton } from '@/components/ui/skeleton';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import type { GHPullRequestFile } from '../../github/types';
import type { ThreadIndex } from '../../github/threads';
import { usePrefs } from '../../util/usePrefs';
import { PierreFileTree, type PierreFileTreeHandle } from './PierreFileTree';
import { treeThemeStyle } from './treeThemeBridge';
import { AiGroupByControl } from '@/ai/grouping/AiGroupByControl';
import { AiGroupedRail, type AiGroupedRailHandle } from '@/ai/grouping/AiGroupedRail';
import type { UseAiGrouping } from '@/ai/grouping/useAiGrouping';
import type { ArrangedView } from './grouping/arrange';
import type { GroupingDimension } from './grouping/types';

/** Imperative handle the parent uses to drive the rail without
 * re-rendering it. Today that's only the visible-in-diff highlight;
 * other surface-level controls (scroll-to, search) stay declarative. */
export interface FileRailHandle {
  /** Highlight the row that matches the file the user is currently
   * viewing in the diff pane. Pass null to clear. Implemented via
   * shadow-DOM mutation in tree mode; list mode no-ops for now. */
  setVisiblePath(path: string | null): void;
}

export type RailMode = 'tree' | 'list';

interface FileRailProps {
  mode: RailMode;
  onModeChange: (m: RailMode) => void;
  /** Live PR files. When omitted, the static design fixture is used so
   * the layout still renders during initial paint. */
  files?: GHPullRequestFile[];
  /** True while the /files endpoint is still paginating. When true
   * AND files is empty we render skeleton rows so the rail has
   * visible structure during the cold-fetch window instead of an
   * empty column. */
  isFilesLoading?: boolean;
  threadIndex?: ThreadIndex;
  /** Per-file comment count (local pre-PR surface). Replaces the
   * threadIndex-derived count for the rail badge when provided. */
  commentCountByPath?: ReadonlyMap<string, number>;
  /** Snapshot of paths the user has marked viewed (per-PR, persisted). */
  viewedSet?: Set<string>;
  /** Files whose diff contents haven't streamed in yet. Forwarded to
   *  PierreFileTree so each row swaps its viewed-eye decoration for
   *  a spinner until the file's content lands. */
  loadingFilenames?: ReadonlySet<string>;
  /** Click handler for the per-file viewed checkbox. */
  onToggleViewed?: (path: string) => void;
  /** Click handler for the folder-level viewed checkbox; receives the
   * full set of descendant file paths the cascade should toggle. */
  onSetFolderViewed?: (paths: string[], viewed: boolean) => void;
  /** Path of the file the user has selected (gets the blue marker). */
  currentPath?: string | null;
  /** Fires when the user clicks a file row. */
  onSelect?: (path: string) => void;
  /** Width of the rail in px. Parent owns the resizable behaviour
   * (so the divider can sit between the rail and the diff in the
   * shared flex parent). Defaults to 280. */
  width?: number;
  /** Fires when the user clicks the chevron in the rail header to
   * collapse the whole sidebar. Parent swaps to a thin strip. When
   * omitted the chevron isn't rendered. */
  onCollapse?: () => void;
  /** Owner / repo / headSha — passed to the row context menu for
   * the permalink + "Open on GitHub" actions. Hidden from the menu
   * when any is missing. */
  owner?: string;
  repo?: string;
  headSha?: string;
  /** "Filter files" text lifted to the URL (`?fq=`). When supplied, the
   * input is initialised from + synced to it so a reload/share keeps the
   * filter. Omitted on the legacy/fixture path (falls back to local). */
  filterQuery?: string;
  onFilterQueryChange?: (q: string | undefined) => void;
  /** False when the rail is mounted-but-hidden behind another tab —
   * gates the ⌘F / `/` filter-focus shortcut. */
  active?: boolean;
  // ── Grouped list (list mode only) ──────────────────────────────
  /** The derived arrangement view. When `arranged.grouped` is true the
   * rail renders group folders instead of the flat list. */
  arranged?: ArrangedView;
  /** The active grouping dimension (drives the control's radio). */
  dimension?: GroupingDimension;
  onDimensionChange?: (d: GroupingDimension) => void;
  /** AI grouping hook (ADR 0026). When the `ai` dimension is active in list
   * mode, the rail renders the bespoke AI-grouped rail (two-line folders +
   * inline descriptions + run states) driven by this, in place of the tree. */
  aiGrouping?: UseAiGrouping;
  /** Whether AI assistance is configured (drives the group-by AI option). */
  aiEnabled?: boolean;
  /** Open Settings · AI assistance (locked-option discovery path). */
  onSetupAi?: () => void;
}

export const FileRail = forwardRef(function FileRail(
  {
    mode,
    onModeChange,
    files,
    isFilesLoading,
    threadIndex,
    commentCountByPath,
    viewedSet,
    loadingFilenames,
    onToggleViewed,
    onSetFolderViewed,
    currentPath,
    onSelect,
    width = 280,
    onCollapse,
    owner,
    repo,
    headSha,
    filterQuery,
    onFilterQueryChange,
    active = true,
    arranged,
    dimension = 'none',
    onDimensionChange,
    aiGrouping,
    aiEnabled,
    onSetupAi,
  }: FileRailProps,
  ref: ForwardedRef<FileRailHandle>,
) {
  const grouped = !!arranged?.grouped;
  // The bespoke AI-grouped rail (design `ai-grouping.jsx`) takes over the rail
  // body in list mode when the `ai` dimension is selected.
  const aiRailActive = mode === 'list' && dimension === 'ai';
  // The rail integrates @pierre/trees, which renders into a shadow
  // root; we feed it CSS-variable overrides via treeThemeStyle() so the
  // tree palette tracks the active shadcn theme. Everything else here
  // is a Tailwind utility class reading the same CSS variables directly.
  // "Filter files" — local state, but initialised from + synced to the
  // URL (`?fq=`) when the router supplies filterQuery/onFilterQueryChange,
  // so a reload or shared link restores it.
  const [filterLocal, setFilterLocal] = useState(filterQuery ?? '');
  const filter = filterLocal;
  const setFilter = (next: string) => {
    setFilterLocal(next);
    onFilterQueryChange?.(next ? next : undefined);
  };
  // Re-sync from the URL (shared link / back-forward). Empty → leave local.
  useEffect(() => {
    if (filterQuery === undefined) return;
    setFilterLocal((cur) => (cur === filterQuery ? cur : filterQuery));
  }, [filterQuery]);
  const { prefs } = usePrefs();
  // The rail's filter input is the only search surface. In BOTH tree
  // and list mode we forward its value into the lib via setSearch();
  // `filter` is also passed down to PierreFileTree so the lib's search
  // can be re-asserted after any path/selection reset (otherwise a
  // click would snap the list back to the full set).
  const pierreRef = useRef<PierreFileTreeHandle | null>(null);
  const aiRailRef = useRef<AiGroupedRailHandle | null>(null);
  const filterInputRef = useRef<HTMLInputElement | null>(null);

  // Keep the lib's path set in sync when files reload. Belt-and-
  // braces: PierreFileTree's internal effect already does this; this
  // makes sure scrollToPath works the moment a fresh PR mounts.
  useEffect(() => {
    if (!files || files.length === 0) return;
    // Grouped mode feeds synthetic display paths from PierreFileTree's own
    // pathMap effect — calling resetPaths with raw filenames here would drop
    // folders/ordering.
    if (grouped) return;
    pierreRef.current?.resetPaths(files.map((f) => f.filename));
  }, [files, grouped]);

  // Apply the (possibly URL-restored) filter to the tree engine. The
  // input's onChange covers live typing; this covers mount-from-URL,
  // external (back/forward) changes, and files arriving after a cold
  // open. List mode narrows its own array from `filter` directly.
  useEffect(() => {
    if (mode !== 'tree') return;
    pierreRef.current?.setSearch(filter.length > 0 ? filter : null);
  }, [filter, mode, files]);

  // Both layouts go through the lib now, so the rail just forwards
  // the visible-path highlight to PierreFileTree (which writes the
  // attribute inside the shadow root with no React state change).
  useImperativeHandle(
    ref,
    () => ({
      setVisiblePath(path: string | null) {
        // Route to whichever rail is mounted (the other ref is null).
        pierreRef.current?.setVisiblePath(path);
        aiRailRef.current?.setVisiblePath(path);
      },
    }),
    [],
  );

  // ⌘F and `/` both focus the rail filter input. CONTEXT.md v1
  // keyboard subset specifies `/`; ⌘F is the macOS browser-find
  // convention we hijack so the OS dialog doesn't fight us. Both
  // modes share the same surface — each pipes through to
  // model.setSearch() so the behaviour is mode-agnostic.
  useEffect(() => {
    if (!active) return; // mounted-but-hidden behind another tab
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const isEditing =
        !!target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.isContentEditable);
      const isCmdF =
        (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'f';
      // Plain `/` only fires when not editing — typing `/` in a
      // comment composer should stay a literal slash.
      const isSlash = e.key === '/' && !e.metaKey && !e.ctrlKey && !isEditing;
      if (!isCmdF && !isSlash) return;
      if (isCmdF && isEditing) return;
      e.preventDefault();
      filterInputRef.current?.focus();
      filterInputRef.current?.select();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [active]);

  // Counters for the footer chips. Derived directly from the live
  // PR file list + viewedSet + threadIndex now that the lib owns
  // row rendering — there's no intermediate tree to walk.
  const { fileCount, folderCount, viewedCount, unreadCount } =
    useMemo(() => {
      const safeFiles = files ?? [];
      const folderSet = new Set<string>();
      let viewed = 0;
      let unread = 0;
      for (const f of safeFiles) {
        const parts = f.filename.split('/');
        for (let i = 0; i < parts.length - 1; i++) {
          folderSet.add(parts.slice(0, i + 1).join('/'));
        }
        if (viewedSet?.has(f.filename)) viewed++;
        const threads = threadIndex?.byPath.get(f.filename) ?? [];
        for (const t of threads) unread += t.comments.length;
      }
      return {
        fileCount: safeFiles.length,
        folderCount: folderSet.size,
        viewedCount: viewed,
        unreadCount: unread,
      };
    }, [files, viewedSet, threadIndex]);
  return (
    <div
      // Width is runtime-driven by the parent's resizer — keep it
      // inline. The flex/layout/border styling moves to Tailwind.
      style={{ width }}
      className="flex shrink-0 flex-col overflow-hidden min-h-0 border-r-[0.5px] border-border bg-card"
    >
      <div className="flex flex-col gap-1.5 border-b-[0.5px] border-border px-3 py-2">
       <div className="flex items-center gap-1.5">
        <div className="flex h-[22px] min-w-0 flex-1 items-center gap-1.5 rounded-[5px] border-[0.5px] border-input bg-background px-2">
          <SearchIcon className="size-[11px] shrink-0 text-muted-foreground" />
          <input
            ref={filterInputRef}
            value={filter}
            onChange={(e) => {
              setFilter(e.target.value);
              // Both layouts render through @pierre/trees, whose search
              // engine is alive but whose own UI is hidden. We drive its
              // match state straight from this input in BOTH modes so
              // there's one visible search field with identical
              // behaviour. Empty string clears.
              pierreRef.current?.setSearch(
                e.target.value.length > 0 ? e.target.value : null,
              );
            }}
            placeholder="Filter files"
            className="min-w-0 flex-1 border-0 bg-transparent p-0 text-[11.5px] text-foreground placeholder:text-muted-foreground focus:outline-none"
          />
          {filter.length > 0 && (
            <button
              type="button"
              onClick={() => {
                setFilter('');
                pierreRef.current?.setSearch(null);
                filterInputRef.current?.focus();
              }}
              title="Clear filter"
              aria-label="Clear filter"
              className="shrink-0 text-muted-foreground transition-colors hover:text-foreground"
            >
              <XIcon className="size-[11px]" />
            </button>
          )}
        </div>
        {/* Segmented Tabs control (same primitive as SubToolbar's
         * Inline/Split DiffModeSegmented). Radix Tabs always emits a
         * value on trigger click — but we keep the `v &&` guard for
         * safety so the rail stays in a defined mode at all times.
         * className overrides keep the list/triggers the same compact
         * 22px size as the old ToggleGroup so the header doesn't grow. */}
        <Tabs
          value={mode}
          onValueChange={(v) => v && onModeChange(v as RailMode)}
          className="shrink-0"
        >
          {/* List first so it sits next to the grouping button (which is
           * list-mode only). Tree second. */}
          <TabsList indicator="pill" className="h-[22px] gap-0.5 rounded-[5px] p-0.5">
            <TabsTrigger
              value="list"
              title="List · ⌘2"
              aria-label="List view"
              className="size-[18px] rounded-[3px] p-0 data-[state=active]:bg-transparent data-[state=active]:shadow-none [&_svg]:size-[11px]"
            >
              <ListIcon />
            </TabsTrigger>
            <TabsTrigger
              value="tree"
              title="Tree · ⌘1"
              aria-label="Tree view"
              className="size-[18px] rounded-[3px] p-0 data-[state=active]:bg-transparent data-[state=active]:shadow-none [&_svg]:size-[11px]"
            >
              <FolderTreeIcon />
            </TabsTrigger>
          </TabsList>
        </Tabs>
        {onCollapse && (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            title="Collapse sidebar"
            aria-label="Collapse sidebar"
            onClick={onCollapse}
            className="size-[22px] shrink-0 rounded-[4px] text-muted-foreground [&_svg]:size-3"
          >
            <ChevronLeftIcon />
          </Button>
        )}
       </div>
       {/* Full-width "Group files by" control (list mode), per the design.
        * Replaces the old icon-only menu. */}
       {mode === 'list' && onDimensionChange && (
         <AiGroupByControl
           dimension={dimension}
           onDimensionChange={onDimensionChange}
           aiEnabled={aiEnabled}
           onSetupAi={onSetupAi}
         />
       )}
      </div>

      {/* AI dimension (list mode): the bespoke AI-grouped rail owns the body +
       * its own run-meta footer. Skeleton stays during the cold-fetch. */}
      {aiRailActive && aiGrouping && arranged ? (
        (!files || files.length === 0) && isFilesLoading ? (
          <FileRailSkeleton count={14} density={prefs.density} flat />
        ) : (
          <AiGroupedRail
            ref={aiRailRef}
            grouping={aiGrouping}
            view={arranged}
            files={files ?? []}
            fileCount={files?.length ?? 0}
            viewedSet={viewedSet}
            loadingFilenames={loadingFilenames}
            commentCountByPath={commentCountByPath}
            threadIndex={threadIndex}
            currentPath={currentPath}
            filter={filter}
            onSelect={onSelect}
            onToggleViewed={onToggleViewed}
            onSetFolderViewed={onSetFolderViewed}
            onSetupAi={onSetupAi}
          />
        )
      ) : (
       <>
      {/* Tree mode is owned by @pierre/trees, which manages its own
       * virtualised scroll container. Both layouts use the lib's
       * scroller, so the rail's outer scroll is suppressed to avoid
       * doubling. */}
      <div className="flex min-h-0 flex-1 flex-col overflow-hidden p-0">
        {(!files || files.length === 0) && isFilesLoading && (
          <FileRailSkeleton count={14} density={prefs.density} flat={mode === 'list'} />
        )}
        {files && files.length > 0 && (
          // key on layout so the lib remounts with the right path
          // shape when the user flips tree <-> list. Mutating the
          // path set in place would also work but the layout
          // semantics differ enough (basename map, no folders) that
          // a clean remount keeps the wrapper's logic simpler.
          <PierreFileTree
            // Remount when flipping tree/list OR toggling grouping on/off,
            // since `sort` and `initialExpansion` are mount-time options. A
            // dimension switch keeps grouped=true → no remount → expansion/
            // scroll preserved (re-derive via resetPaths).
            key={`${mode}:${grouped ? 'g' : 'f'}`}
            ref={pierreRef}
            files={files}
            arranged={arranged}
            threadIndex={threadIndex}
            commentCountByPath={commentCountByPath}
            viewedSet={viewedSet}
            loadingFilenames={loadingFilenames}
            currentPath={currentPath}
            searchValue={filter}
            onSelect={onSelect}
            onToggleViewed={onToggleViewed}
            onSetFolderViewed={onSetFolderViewed}
            density={prefs.density}
            themeStyle={treeThemeStyle()}
            layout={mode === 'list' ? 'flat' : 'tree'}
            owner={owner}
            repo={repo}
            headSha={headSha}
            onSwitchToTree={
              mode === 'list' ? () => onModeChange('tree') : undefined
            }
          />
        )}
      </div>

      <div className="flex justify-between border-t-[0.5px] border-border px-3 py-2 text-[11px] text-muted-foreground">
        <span>
          {fileCount} file{fileCount === 1 ? '' : 's'} ·{' '}
          {grouped ? (arranged?.folderOrder.length ?? 0) : folderCount} folder
          {(grouped ? arranged?.folderOrder.length : folderCount) === 1
            ? ''
            : 's'}
        </span>
        <span className="inline-flex items-center gap-1.5">
          <EyeIcon className="size-[11px]" /> {viewedCount} viewed
          <span className="text-muted-foreground/60">·</span>
          <span className="text-pyor-unread">{unreadCount} unread</span>
        </span>
      </div>
       </>
      )}
    </div>
  );
});

/** Narrow icon-rail shown in place of FileRail when collapsed. Per
 * the Phase-3 design (`shell-pr-rail-collapsed`): a 44px-wide column
 * with one icon button per file. Current file gets a left-edge accent
 * stripe, files with unread inline-review comments get a small badge
 * in the top-right corner of their icon button. Viewed files dim to
 * 50% opacity. A bottom footer shows the viewed/total counter so the
 * progress info from SubToolbar's ViewedProgress isn't lost while
 * collapsed. */
export function FileRailCollapsed({
  files,
  viewedSet,
  threadIndex,
  currentPath,
  onSelect,
  onExpand,
}: {
  files?: GHPullRequestFile[];
  viewedSet?: Set<string>;
  threadIndex?: ThreadIndex;
  currentPath?: string | null;
  onSelect?: (path: string) => void;
  onExpand: () => void;
}) {
  const safeFiles = files ?? [];
  const viewedCount = useMemo(() => {
    if (!viewedSet) return 0;
    let n = 0;
    for (const f of safeFiles) if (viewedSet.has(f.filename)) n++;
    return n;
  }, [safeFiles, viewedSet]);
  return (
    <aside className="flex w-11 shrink-0 flex-col border-r-[0.5px] border-border bg-card">
      <div className="flex h-9 shrink-0 items-center justify-center border-b-[0.5px] border-border">
        <button
          type="button"
          title="Expand file rail"
          aria-label="Expand file rail"
          onClick={onExpand}
          className="inline-flex size-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
        >
          <PanelLeftOpenIcon className="size-4" />
        </button>
      </div>
      <div className="flex-1 space-y-0.5 overflow-auto py-1">
        {safeFiles.map((f) => {
          const isCurrent = f.filename === currentPath;
          const isViewed = viewedSet?.has(f.filename) ?? false;
          const threads = threadIndex?.byPath.get(f.filename) ?? [];
          let unread = 0;
          for (const t of threads) unread += t.comments.length;
          const basename = f.filename.split('/').pop() ?? f.filename;
          return (
            <button
              key={f.filename}
              type="button"
              title={f.filename}
              onClick={() => onSelect?.(f.filename)}
              className={`relative mx-auto flex size-8 items-center justify-center rounded-md ${
                isCurrent ? 'bg-muted' : 'hover:bg-muted/60'
              } ${isViewed && !isCurrent ? 'opacity-50' : ''}`}
              aria-current={isCurrent}
              aria-label={basename}
            >
              {isCurrent && (
                <span className="absolute bottom-1 left-0 top-1 w-0.5 rounded-r bg-foreground" />
              )}
              <FileIcon
                className={`size-4 ${
                  isCurrent ? 'text-foreground' : 'text-muted-foreground'
                }`}
              />
              {unread > 0 && (
                <span className="absolute right-0.5 top-0.5 inline-flex h-[14px] min-w-[14px] items-center justify-center rounded-full bg-primary px-1 text-[9px] font-semibold leading-none text-primary-foreground ring-2 ring-card">
                  {unread > 9 ? '9+' : unread}
                </span>
              )}
            </button>
          );
        })}
      </div>
      <div className="border-t-[0.5px] border-border px-1 py-1.5 text-center text-[10px] text-muted-foreground">
        <div className="font-mono tabular-nums">
          {viewedCount}/{safeFiles.length}
        </div>
      </div>
    </aside>
  );
}

/**
 * Skeleton rows for the file rail while /files is still paginating.
 * Renders N placeholder bars at varying widths to suggest the
 * eventual structure (some folder rows, some file rows). Backed by
 * shadcn's `Skeleton` primitive — it adds a subtle pulse, which we
 * keep because the colour is muted enough that the motion reads as
 * "loading" rather than "look at me".
 */
// Row heights match @pierre/trees' density presets so the skeleton rows
// line up 1:1 with the real list/tree rows that replace them — no height
// jump on load. (FILE_TREE_DENSITY_PRESETS: compact 24 / default 30 /
// relaxed 36.)
const SKELETON_ROW_HEIGHT: Record<string, number> = {
  compact: 24,
  default: 30,
  relaxed: 36,
};

export function FileRailSkeleton({
  count,
  density = 'default',
  flat = false,
}: {
  count: number;
  /** Match the active tree density so the rows are the same height as the
   * real ones (avoids a layout jump when files land). */
  density?: 'compact' | 'default' | 'relaxed';
  /** List (flat) mode has no folder indents — give every row the same
   * left offset. Tree mode varies the indent to suggest nesting. */
  flat?: boolean;
}) {
  // Pre-generated widths give the row list visual rhythm without
  // looking randomly jumpy on re-render. Cycle through.
  const widths = [70, 88, 60, 82, 55, 92, 65, 78, 50, 86, 72, 58];
  // Indent pattern (tree only) — a couple of nesting levels so the
  // skeleton reads as a folder tree rather than a flat list.
  const indents = flat ? [] : [0, 12, 12, 24, 12, 0, 12, 24, 24, 0, 12, 12, 24, 0];
  const rowHeight = SKELETON_ROW_HEIGHT[density] ?? 30;
  return (
    <div aria-label="Loading files…" aria-busy>
      {Array.from({ length: count }, (_, i) => (
        <div
          key={i}
          className="flex items-center gap-2 px-3"
          style={{ height: rowHeight, paddingLeft: 12 + (indents[i] ?? 0) }}
        >
          {/* status / file-type icon */}
          <Skeleton className="size-3.5 shrink-0 rounded-[3px]" />
          {/* filename */}
          <Skeleton
            style={{ maxWidth: widths[i % widths.length] }}
            className="h-2.5 flex-1 rounded-[3px]"
          />
          {/* right-side decoration (added/deleted stats + viewed eye) */}
          <Skeleton className="ml-auto h-2 w-6 shrink-0 rounded-[3px]" />
          <Skeleton className="size-3.5 shrink-0 rounded-[3px]" />
        </div>
      ))}
    </div>
  );
}
