// Unified review detail entry point — single screen that handles
// both online GitHub PR reviews and local pre-PR reviews. Routed to
// from `route.kind === 'pr'` and `route.kind === 'local-review'`.
//
// Phase A scaffold (current): branches on `source.kind` and renders
// the existing PRDetailScreen / LocalReviewSurface contents. Same
// visible behaviour as before, but the import point is unified so
// later phases can move logic into a shared layout shell, tab
// adapter, and file rail without re-plumbing the router.
//
// Phase B+ will:
//   - Extract `<ReviewLayout>` shell (PyorWindow + slots, keyboard
//     nav, scroll persist, visible-file tracking).
//   - Drive tabs through a per-source adapter (PR: Description /
//     Commits / Checks / Files; Local: Commits / Working tree / Files).
//   - Unify the file rail and the comment surface so local comments
//     render inline like PR threads.
//
// See task #80 + ADR 0012 + the cross-screen unification plan in
// chat history (May 2026).

import { useMemo } from 'react';
import { PRDetailScreen } from './PRDetailScreen';
import { LocalReviewSurface } from './LocalReviewsScreen';
import { EmptyState } from '../ui/EmptyState';
import { Button } from '@/components/ui/button';
import { Laptop2Icon } from 'lucide-react';
import { PyorWindow } from '../ui/PyorWindow';
import { useLocalReviewsList, useDeleteLocalReview } from '../review/useLocalReviews';
import type { PRTab } from '../pr/PRTabs';
import {
  useNavigate,
  useCanGoBack,
  useRouter,
  getRouteApi,
} from '@tanstack/react-router';
import { INBOX_DEFAULTS, PULLS_DEFAULTS, type PRSearch } from '../router/search';
import type { DiffAnchor } from '../router/nav';
import type { DiffMode } from '../pr/changes/diffMode';

interface Props {
  /** Which review surface to render. The router supplies this; the
   * screen reads its own path params + search from the router. */
  kind: 'github-pr' | 'local-review';
  fluid?: boolean;
}

// Decoupled from the route objects (importing them back from router.tsx
// formed import cycles); the typed APIs are resolved by route id instead.
const prApi = getRouteApi('/$owner/$repo/$number');
const localReviewApi = getRouteApi('/local/$reviewId');

/** Unified entry point. Reads route params/search from the router and
 * dispatches to the existing screens by kind. Each branch keeps its
 * current behaviour intact. */
export function ReviewDetailScreen(props: Props) {
  if (props.kind === 'github-pr') {
    return <PRBranch fluid={props.fluid} />;
  }
  return <LocalReviewRouteBranch fluid={props.fluid} />;
}

/** GitHub-PR branch — reads owner/repo/number from the path and
 * tab/diff/commits/from/anchor from the search params, writing tab +
 * diff back to the URL on change (replace history for view-state
 * toggles). Back routes through router history (mirrors ⇧⌘B + the
 * browser back button), falling back to the recorded origin screen on
 * a cold deep-link. */
function PRBranch({ fluid }: { fluid?: boolean }) {
  const { owner, repo, number } = prApi.useParams();
  const search = prApi.useSearch();
  const navigate = useNavigate();
  const router = useRouter();
  const canGoBack = useCanGoBack();

  const num = Number(number);
  const anchor = search.apath
    ? {
        path: search.apath,
        line: search.aline ?? null,
        diffSide: search.aside ?? null,
        commentId: search.acid,
      }
    : undefined;

  // Every PR-detail view-state setter merges its change into the LIVE
  // URL search via the navigate updater (`prev`) — NOT this component's
  // captured `search` from render. This is load-bearing: the file tree
  // (@pierre/trees) captures its onSelect callback at mount, which can
  // happen mid tab-switch (open PR on Conversation → click Files
  // changed → tree mounts) while `search` still holds the previous tab.
  // Reading `prev` at navigate time means a stale captured setter can
  // never resurrect an old tab/anchor. Replace history — view toggles,
  // not back-button steps.
  const patchSearch = (next: Partial<PRSearch>) => {
    void navigate({
      to: '/$owner/$repo/$number',
      params: { owner, repo, number },
      search: (prev) => ({ ...(prev as PRSearch), ...next }),
      replace: true,
    });
  };
  // Switching tabs clears the line/comment selection (aline/aside/acid)
  // so returning to Changes restores the saved scroll spot instead of
  // force-scrolling to a stale anchor. apath (current file) is kept.
  const setTab = (tab: PRTab) =>
    patchSearch({ tab, aline: undefined, aside: undefined, acid: undefined });
  const setDiff = (diff: DiffMode) => patchSearch({ diff });
  const setCommits = (next: string | undefined) =>
    patchSearch({ commits: next || undefined });
  // Changes-tab inputs (persist + share): fq = file-rail filter, dq =
  // in-diff content search.
  const setFileFilter = (q: string | undefined) =>
    patchSearch({ fq: q || undefined });
  const setDiffSearch = (q: string | undefined) =>
    patchSearch({ dq: q || undefined });
  // File-rail mode ('tree' → omitted). (Focus mode is NOT in the URL —
  // it's a private per-PR preference persisted to localStorage instead.)
  const setRail = (mode: 'tree' | 'list') =>
    patchSearch({ rail: mode === 'tree' ? undefined : mode });
  // Live diff anchors — clicking a line or a comment writes the
  // shareable anchor. A comment carries `acid` (wins precedence on
  // restore); a bare line sets aline/aside and clears acid. `null`
  // clears the whole anchor.
  const setAnchor = (a: DiffAnchor | null) =>
    patchSearch({
      apath: a?.path || undefined,
      aline: a && a.line != null ? a.line : undefined,
      aside: a?.side ?? undefined,
      acid: a?.commentId ?? undefined,
    });
  // Commits tab → Files-changed jump scoped to one commit. Both search
  // params land in a SINGLE replace-navigation (via patchSearch) — replace,
  // not push, so the browser Back button skips this intra-PR view toggle
  // and returns to wherever the PR was opened from (the list), matching
  // every other view-state setter here.
  const scopeToCommit = (sha: string) =>
    patchSearch({ tab: 'changes', commits: sha });

  const onBack = () => {
    if (canGoBack) {
      router.history.back();
    } else if (search.from === 'inbox') {
      void navigate({ to: '/inbox', search: INBOX_DEFAULTS });
    } else {
      void navigate({ to: '/pulls', search: PULLS_DEFAULTS });
    }
  };

  return (
    <PRDetailScreen
      fluid={fluid}
      owner={owner}
      repo={repo}
      number={num}
      readOnly={search.demo === true}
      initialTab={search.tab}
      initialAnchor={anchor}
      diffMode={search.diff}
      onDiffModeChange={setDiff}
      commits={search.commits}
      onCommitsChange={setCommits}
      onScopeToCommit={scopeToCommit}
      fileFilter={search.fq}
      onFileFilterChange={setFileFilter}
      diffSearch={search.dq}
      onDiffSearchChange={setDiffSearch}
      railMode={search.rail}
      onRailModeChange={setRail}
      onAnchorChange={setAnchor}
      onTabChange={setTab}
      onBack={onBack}
      backLabel={search.from === 'inbox' ? 'Inbox' : 'Pull requests'}
    />
  );
}

/** Local-review branch wrapper — reads the reviewId from the path and
 * wires the back action to the local-reviews list. */
function LocalReviewRouteBranch({ fluid }: { fluid?: boolean }) {
  const { reviewId } = localReviewApi.useParams();
  const navigate = useNavigate();
  return (
    <LocalReviewBranch
      reviewId={reviewId}
      onBack={() => void navigate({ to: '/local' })}
      fluid={fluid}
    />
  );
}

/** Local branch — looks up the LocalReview by id + renders the
 * existing surface. Separated so it can own the lookup query +
 * delete-confirmation handler without polluting the dispatcher. */
function LocalReviewBranch({
  reviewId,
  onBack,
  fluid,
}: {
  reviewId: string;
  onBack: () => void;
  fluid?: boolean;
}) {
  const listQuery = useLocalReviewsList();
  const review = useMemo(
    () => listQuery.data?.find((r) => r.id === reviewId),
    [listQuery.data, reviewId],
  );
  const deleteReview = useDeleteLocalReview();
  if (listQuery.isLoading) {
    // Cheap pass-through while the list query resolves — the in-app
    // shell already shows a spinner, this just avoids flashing an
    // empty state for a frame.
    return null;
  }
  if (!review) {
    return (
      <PyorWindow fluid={fluid} title="Local review" subtitle="Not found">
        <EmptyState
          icon={Laptop2Icon}
          iconClassName="text-muted-foreground"
          title="Review not found"
          body="This local review was deleted or its repo was removed. Go back to the list to pick another."
          action={
            <Button variant="outline" size="sm" onClick={onBack}>
              Back to local reviews
            </Button>
          }
        />
      </PyorWindow>
    );
  }
  return (
    <LocalReviewSurface
      review={review}
      onBack={onBack}
      onRequestDelete={() => {
        // Phase A keeps the legacy "confirm-and-delete" delegated to
        // the surface itself by reusing the same callback shape the
        // pre-route version used. Phase B's shared shell will move
        // this into a Dialog at the route level.
        void deleteReview
          .mutateAsync(review.id)
          .then(() => onBack())
          .catch(() => undefined);
      }}
      fluid={fluid}
    />
  );
}
