// Local Review Comment export — pure generators for the LLM bundle.
//
// ADR 0012 Phase 6. Given a LocalReview, its comments, and a
// staleness lookup, produce the strings that go into the export
// bundle:
//
//   <bundle>/
//   ├── README.md         ← orient the agent
//   ├── comments.md       ← prompt-ready document (this module's main job)
//   ├── comments.json     ← structured backup of the same data
//   └── attachments/<commentId>/<filename>
//
// The bridge writes the directory + copies attachments; this module
// only produces the in-memory strings. Keeps the generator pure +
// testable + reusable for "preview before export" if we add that
// later.
//
// `pyor-attachment://<reviewId>/<commentId>/<filename>` URLs in comment
// bodies are rewritten to `./attachments/<commentId>/<filename>`
// relative paths so the LLM agent can resolve them from the bundle
// directory.

import type { LocalReview } from './localReviews';
import type { LocalReviewComment } from './localReviewComments';
import { WORKING_TREE_ANCHOR } from './localReviewComments';
import type { StalenessResult } from './localReviewStaleness';

/** A render-time view of one comment for the export. The staleness
 * lookup is the caller's responsibility (the surface already
 * computes it for the in-app chips). */
export interface ExportCommentView {
  comment: LocalReviewComment;
  /** undefined when staleness wasn't computed (e.g. headless export
   * with no file contents available). The generator falls back to
   * "(unknown)" in the heading. */
  staleness: StalenessResult | undefined;
}

export interface ExportMeta {
  review: LocalReview;
  /** SHA the export was generated against. Used in the comments.md
   * header line. */
  headSha: string;
  /** ISO timestamp of the export. */
  exportedAt: string;
  /** Optional commit count for the header summary line. */
  commitCount?: number;
  /** Optional file count for the header summary line. */
  fileCount?: number;
}

/**
 * Build `comments.md` — the prompt-ready Markdown document the LLM
 * agent will read. Dismissed comments are EXCLUDED entirely.
 *
 * Shape per ADR 0012 Q17b: H1 header with metadata, then one
 * `## N. path:line · staleness` section per remaining comment.
 */
export function renderCommentsMarkdown(
  meta: ExportMeta,
  views: ExportCommentView[],
): string {
  const active = views.filter((v) => !v.comment.dismissed);
  const out: string[] = [];
  out.push(`# Local review · ${meta.review.branch} → ${meta.review.base}`);
  const headerBits = [
    `Exported ${meta.exportedAt}`,
    `head ${shortSha(meta.headSha)}`,
    `base ${meta.review.base}`,
  ];
  if (meta.commitCount != null) {
    headerBits.push(`${meta.commitCount} ${pluralize(meta.commitCount, 'commit')}`);
  }
  if (meta.fileCount != null) {
    headerBits.push(`${meta.fileCount} ${pluralize(meta.fileCount, 'file')}`);
  }
  out.push(headerBits.join(' · '));
  out.push('');
  if (active.length === 0) {
    out.push('_No active notes — every comment has been dismissed or none were authored._');
    out.push('');
    return out.join('\n');
  }
  active.forEach((v, idx) => {
    out.push('---');
    out.push('');
    out.push(`## ${idx + 1}. ${renderHeading(v)}`);
    out.push('');
    const metaLine = renderMetaLine(v.comment);
    if (metaLine) {
      out.push(metaLine);
      out.push('');
    }
    if (v.comment.contentSnippet !== null) {
      out.push('**Anchor snippet:**');
      out.push('```');
      out.push(v.comment.contentSnippet);
      out.push('```');
      out.push('');
    }
    out.push(rewriteAttachmentLinks(v.comment.body));
    out.push('');
  });
  return out.join('\n');
}

/** Build `comments.json` — the structured backup. Same set as
 * `renderCommentsMarkdown` (dismissed excluded). Surfaces every
 * field of the saved comment plus the computed staleness, so
 * downstream tooling has both the raw data and the agent's hint. */
export function renderCommentsJson(
  meta: ExportMeta,
  views: ExportCommentView[],
): string {
  const active = views.filter((v) => !v.comment.dismissed);
  const payload = {
    review: {
      id: meta.review.id,
      branch: meta.review.branch,
      base: meta.review.base,
      title: meta.review.title ?? null,
      createdAt: meta.review.createdAt,
    },
    headSha: meta.headSha,
    exportedAt: meta.exportedAt,
    commitCount: meta.commitCount ?? null,
    fileCount: meta.fileCount ?? null,
    comments: active.map((v) => ({
      id: v.comment.id,
      path: v.comment.path,
      side: v.comment.side,
      line: v.comment.line,
      startLine: v.comment.startLine ?? null,
      anchorSha: v.comment.anchorSha,
      contentSnippet: v.comment.contentSnippet,
      body: rewriteAttachmentLinks(v.comment.body),
      authorLogin: v.comment.authorLogin,
      createdAt: v.comment.createdAt,
      updatedAt: v.comment.updatedAt,
      staleness: v.staleness ?? null,
    })),
  };
  return JSON.stringify(payload, null, 2);
}

/** Build `README.md` — short agent-oriented intro. */
export function renderReadme(meta: ExportMeta, commentCount: number): string {
  return [
    `# Pyor local review — ${meta.review.branch} → ${meta.review.base}`,
    '',
    `This directory contains ${commentCount} note${commentCount === 1 ? '' : 's'} the developer wants addressed before opening a PR for \`${meta.review.branch}\`.`,
    '',
    '**Files:**',
    '',
    '- `comments.md` — prompt-ready Markdown. Each `## N. …` section is one note. Read this first.',
    '- `comments.json` — structured copy of the same data.',
    `- \`attachments/<commentId>/<filename>\` — screenshots / images referenced in comment bodies.`,
    '',
    '**Staleness markers** (in each comment heading):',
    '',
    '- `fresh` — the target line is unchanged since the developer wrote the note.',
    '- `moved · was @ N` — the snippet still exists but at a different line. The note still applies; the line number drifted.',
    '- `stale` — the target line was edited or removed. The developer may have already partially addressed it; reread the snippet to decide.',
    '',
    `Exported ${meta.exportedAt} · head ${shortSha(meta.headSha)}`,
    '',
  ].join('\n');
}

// ── Internals ──────────────────────────────────────────────────

function renderHeading(v: ExportCommentView): string {
  const { comment, staleness } = v;
  const where = renderPathSegment(comment);
  const stalenessLabel = staleness ? labelForStaleness(staleness) : '(unknown)';
  return `\`${where}\` · ${stalenessLabel}`;
}

function renderPathSegment(c: LocalReviewComment): string {
  if (c.line === null) return c.path;
  if (c.startLine && c.startLine !== c.line) {
    return `${c.path}:${c.startLine}-${c.line}`;
  }
  return `${c.path}:${c.line}`;
}

function labelForStaleness(s: StalenessResult): string {
  switch (s.state) {
    case 'fresh':
      return 'fresh';
    case 'moved':
      return `moved · was @ line ${s.wasLine}, now @ line ${s.nowLine}`;
    case 'stale':
      return 'stale';
  }
}

function renderMetaLine(c: LocalReviewComment): string {
  const parts: string[] = [];
  if (c.side) parts.push(`**Side:** ${c.side}`);
  parts.push(
    `**Anchored at:** ${
      c.anchorSha === WORKING_TREE_ANCHOR ? 'working tree' : shortSha(c.anchorSha)
    }`,
  );
  return parts.join(' · ');
}

/** Rewrite in-app pyor-attachment:// URLs to bundle-relative paths
 * (`./attachments/<commentId>/<filename>`). The regex is tight so
 * we don't accidentally rewrite arbitrary text. */
function rewriteAttachmentLinks(body: string): string {
  return body.replace(
    /pyor-attachment:\/\/([\w-]+)\/([\w-]+)\/([^)\s]+)/g,
    (_full, _reviewId: string, commentId: string, filename: string) =>
      `./attachments/${commentId}/${filename}`,
  );
}

function shortSha(sha: string): string {
  if (sha === WORKING_TREE_ANCHOR) return 'working tree';
  return sha.length > 8 ? sha.slice(0, 8) : sha;
}

function pluralize(n: number, word: string): string {
  return n === 1 ? word : `${word}s`;
}
