// Sentry init for the product (web + Electron renderer) — ADR 0021.
//
//   • Errors-only: NO performance tracing for now (tracesSampleRate 0) to stay
//     on the free tier.
//   • Replay errors-only + MASKED: healthy sessions are never recorded
//     (replaysSessionSampleRate 0); on an error the rolling buffer is captured
//     with maskAllText + blockAllMedia, so code shows as blocks, not text.
//   • Mandatory scrubbing: beforeSend / beforeBreadcrumb redact every token,
//     the entitlement JWT, secret-named headers, and all request/response
//     bodies (code/comments) before anything leaves the device.
//   • Tunnelled first-party (adblock dodge), tagged with release + environment.

import * as Sentry from '@sentry/react';
import {
  SENTRY_DSN,
  SENTRY_TUNNEL,
  ENVIRONMENT,
  RELEASE,
  errorTrackingConfigured,
} from './config';
import { scrubString, scrubDeep, stripBodies } from './redact';

function scrubEvent(event: Sentry.ErrorEvent): Sentry.ErrorEvent {
  if (event.message) event.message = scrubString(event.message);

  event.exception?.values?.forEach((ex) => {
    if (ex.value) ex.value = scrubString(ex.value);
  });

  event.breadcrumbs?.forEach((b) => {
    if (b.message) b.message = scrubString(b.message);
    if (b.data) b.data = scrubDeep(b.data) as Record<string, unknown>;
  });

  stripBodies(event as unknown as Record<string, unknown>);
  if (event.extra) event.extra = scrubDeep(event.extra) as Record<string, unknown>;
  if (event.contexts)
    event.contexts = scrubDeep(event.contexts) as typeof event.contexts;
  return event;
}

let started = false;

export function initSentry(): void {
  if (started || !errorTrackingConfigured || !SENTRY_DSN) return;
  started = true;

  Sentry.init({
    dsn: SENTRY_DSN,
    environment: ENVIRONMENT,
    release: RELEASE,
    tunnel: SENTRY_TUNNEL,
    // Identity is attached selectively in identify.ts — never by default.
    sendDefaultPii: false,
    // Errors only. No tracing on the free tier.
    tracesSampleRate: 0,
    // Replay: never on healthy sessions; full buffer on error, masked.
    replaysSessionSampleRate: 0,
    replaysOnErrorSampleRate: 1,
    integrations: [
      Sentry.replayIntegration({
        maskAllText: true,
        blockAllMedia: true,
        maskAllInputs: true,
      }),
    ],
    beforeSend: (event) => scrubEvent(event),
    beforeBreadcrumb: (crumb) => {
      if (crumb.message) crumb.message = scrubString(crumb.message);
      if (crumb.data) crumb.data = scrubDeep(crumb.data) as Record<string, unknown>;
      return crumb;
    },
  });
}

export { Sentry };
