// Real client-side router (replaces the ad-hoc routeStore state
// machine in App.tsx — see AFK plan 26).
//
// History mode is per build target (the actual selection is at the
// bottom of this file; flag from web/vite.config.ts):
//   - WEB (default): BROWSER history → clean URLs (`/owner/repo/123`, no
//     `#`). Deep links resolve assets from the absolute base `/`, and the
//     GitHub Pages deploy serves the SPA for any path via its 404.html
//     fallback.
//   - ELECTRON (`__PIER_ELECTRON__`): HASH history. The renderer is loaded
//     from disk via `loadFile('index.html')` (see desktop/src/main.ts);
//     under `file://`, HTML5 history paths + absolute asset paths don't
//     resolve, so the whole route lives in the URL fragment
//     (`index.html#/owner/repo/123?tab=changes`), never hitting the loader.
//     This is the Electron-safety guarantee the plan calls out.
// Either way URLs stay shareable (copy → reopen restores the same view),
// which is the whole point of this migration.
//
// Identity lives in the PATH; ephemeral view-state lives in SEARCH
// params. Search-param schemas + defaults live in `./search.ts`
// (Valibot). Defaults are EXPLICIT: each route's `beforeLoad`
// canonicalises the address bar so the full default query string is
// always present + shareable (`/pulls?tab=mine&status=open&date=30d&
// sort=updated-desc`) — and every navigation/link carries those
// defaults too. Narrowing filters (repo/author/…) serialise only when
// applied.

import {
  createRootRoute,
  createRoute,
  createRouter,
  createHashHistory,
  createBrowserHistory,
  redirect,
  Outlet,
} from '@tanstack/react-router';
import { lazy, Suspense } from 'react';
import { hasToken } from '../auth/tokenStore';
import { useOrgGate } from '../billing/orgGate';
import { queryClient } from '../lib/queryClient';
import {
  validateInboxSearch,
  validatePullsSearch,
  validatePRSearch,
  needsCanonical,
  cleanSearch,
  PULLS_DEFAULTS,
  PR_DEFAULTS,
} from './search';
import { readPrParam } from '../util/parsePrParam';
import { Shell } from '../ui/Shell';
import { RouteErrorBoundary } from '../ui/RouteErrorBoundary';
import { NotFoundScreen } from '../screens/NotFoundScreen';
import { PRDetailLoading } from '../ui/PRDetailLoading';
import { PullsScreen } from '../screens/PullsScreen';
// EAGER (not lazy): the PR-detail screen is the app's core surface and the
// most common reload / deep-link target. Lazy-loading it meant a hard
// reload onto a PR showed the `PRDetailLoading` Suspense fallback (a full
// skeleton) while its chunk downloaded — a *code*-loading state no cache
// (persister / placeholderData / isRestoring) can touch, since the screen's
// code isn't in memory yet. A surgical "eager shell, lazy diff" split was
// ruled out: @pierre/diffs + @pierre/trees are needed across all three
// tabs (the Conversation tab renders diff snippets), the file rail, and the
// worker provider, so isolating them saved ~30KB. Shipping the screen in
// the main bundle (~640KB gzip) is the only way to render it instantly on
// reload; its own (isRestoring-gated) loading states take over from there.
// The diff renderer's per-language syntax-highlight chunks stay lazy.
import { ReviewDetailScreen } from '../screens/ReviewDetailScreen';

// ── Lazy screens (mirror the existing App.tsx code-splits) ─────────

const LocalReviewsScreen = lazy(() =>
  import('../screens/LocalReviewsScreen').then((m) => ({
    default: m.LocalReviewsScreen,
  })),
);
const NotificationsScreen = lazy(() =>
  import('../screens/NotificationsScreen').then((m) => ({
    default: m.NotificationsScreen,
  })),
);
const SettingsScreen = lazy(() =>
  import('../screens/SettingsScreen').then((m) => ({
    default: m.SettingsScreen,
  })),
);
const SetupScreen = lazy(() =>
  import('../screens/SetupScreen').then((m) => ({ default: m.SetupScreen })),
);
const WelcomeScreen = lazy(() =>
  import('../screens/WelcomeScreen').then((m) => ({ default: m.WelcomeScreen })),
);
const ConnectController = lazy(() =>
  import('../screens/connect/ConnectController').then((m) => ({
    default: m.ConnectController,
  })),
);
const InstalledLanding = lazy(() =>
  import('../screens/connect/InstalledLanding').then((m) => ({
    default: m.InstalledLanding,
  })),
);
const BlockedOrgScreen = lazy(() =>
  import('../billing/BlockedOrgScreen').then((m) => ({
    default: m.BlockedOrgScreen,
  })),
);

// ── Route tree ─────────────────────────────────────────────────────

const rootRoute = createRootRoute({
  component: RootComponent,
});

function RootComponent() {
  // The Shell owns the persistent sidebar chrome + cross-cutting
  // wiring (command palette nav, ⇧⌘B, theme toggle, Electron
  // notification deep-link). The active route renders into <Outlet/>.
  return (
    <Shell>
      <Outlet />
    </Shell>
  );
}

// `/` → boot entry. No token → /setup. Otherwise land on the default
// home screen: Pull requests. Every screen now has its own shareable
// URL (the URL is the source of truth), so `/` is purely "take me
// home" — there's no last-spot to restore here; a deep link restores
// its own view directly.
const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  beforeLoad: () => {
    // Public-PR demo deep-link (AFK plan 22). HIGHEST priority — runs
    // before the token gate so `?pr=owner/repo/123` opens read-only
    // with no Setup screen, even with no token. The `?pr=` value is a
    // conventional search param on the root URL (before the hash); we
    // redirect into the hash PR route carrying `demo: true`. The root
    // `?pr=` stays in `location.search` (hash history doesn't touch it)
    // so the link remains shareable. A token user is unaffected by the
    // read-only flag beyond the deep-link itself — they still send
    // Authorization (better rate limit), the mode is just read-only.
    const demoPr = readPrParam();
    if (demoPr) {
      throw redirect({
        to: '/$owner/$repo/$number',
        params: {
          owner: demoPr.owner,
          repo: demoPr.repo,
          number: String(demoPr.number),
        },
        search: { ...PR_DEFAULTS, demo: true },
      });
    }
    // No credential → the first-launch choice screen (GitHub sign-in is
    // recommended; the PAT path lives one click away at /setup). ADR 0019.
    if (!hasToken()) throw redirect({ to: '/welcome' });
    throw redirect({ to: '/pulls', search: PULLS_DEFAULTS });
  },
});

const setupRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/setup',
  component: function SetupRouteComponent() {
    return (
      <Suspense fallback={null}>
        <SetupScreen fluid />
      </Suspense>
    );
  },
});

// First-launch choice screen (GitHub sign-in vs PAT). It's the pre-auth
// entry, but an already-signed-in user (PAT or GitHub App — `hasToken()`
// covers both) shouldn't be asked to sign in again: send them straight
// into the app, matching the `/` boot redirect.
const welcomeRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/welcome',
  beforeLoad: () => {
    if (hasToken()) throw redirect({ to: '/pulls', search: PULLS_DEFAULTS });
  },
  component: function WelcomeRouteComponent() {
    return (
      <Suspense fallback={null}>
        <WelcomeScreen fluid />
      </Suspense>
    );
  },
});

// GitHub-App sign-in flow. `/connect` starts it; `/connect/callback` is the
// re-entry from the backend redirect (web) or the pyor:// deep-link (desktop),
// carrying the one-time code + CSRF state.
const connectRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/connect',
  component: function ConnectRouteComponent() {
    return (
      <Suspense fallback={null}>
        <ConnectController />
      </Suspense>
    );
  },
});

const connectCallbackRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/connect/callback',
  validateSearch: (s: Record<string, unknown>) => ({
    code: typeof s.code === 'string' ? s.code : undefined,
    state: typeof s.state === 'string' ? s.state : undefined,
    error: typeof s.error === 'string' ? s.error : undefined,
  }),
  component: function ConnectCallbackRouteComponent() {
    const search = connectCallbackRoute.useSearch();
    return (
      <Suspense fallback={null}>
        <ConnectController callback={search} />
      </Suspense>
    );
  },
});

// Post-install landing. GitHub's OAuth-during-install redirect drops our CSRF
// `state` and carries `installation_id` + `setup_action`, so the broker can't
// route it through the normal callback — it sends the browser here instead.
// The installation already succeeded server-side; we just finish locally.
const connectInstalledRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/connect/installed',
  // GitHub appends `installation_id` + `setup_action` to this redirect. Capture
  // the id so the post-install toast can name the org the install belongs to.
  validateSearch: (s: Record<string, unknown>) => ({
    installation_id: s.installation_id == null ? undefined : Number(s.installation_id),
  }),
  beforeLoad: ({ search }) => {
    // Signed-in (web) → the install already succeeded server-side; drop the
    // cached PR-search results so newly-granted repos appear, then into the app.
    if (hasToken()) {
      // ADR 0020 #7: a freshly-installed org has no plan yet and is blocked
      // (hidden everywhere). Flag a one-time nudge → App shows the toast that
      // points the confused user to the Settings explainer. Store the
      // installation id (not a bare '1' sentinel) so App can resolve the org
      // login; fall back to '1' when GitHub didn't send one (desktop / stray).
      try {
        const id = Number.isFinite(search.installation_id)
          ? String(search.installation_id)
          : '1';
        sessionStorage.setItem('pyor:post-install', id);
      } catch {
        /* private mode / storage disabled — skip the nudge, not fatal. */
      }
      void queryClient.invalidateQueries();
      throw redirect({ to: '/pulls', search: PULLS_DEFAULTS });
    }
    // No token here → the desktop installer's SYSTEM browser (its token lives
    // in the Electron app), or a stray web visit. Fall through to the landing,
    // which deep-links back into the app via pyor://installed.
  },
  component: function ConnectInstalledRouteComponent() {
    return (
      <Suspense fallback={null}>
        <InstalledLanding fluid />
      </Suspense>
    );
  },
});

const inboxRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/inbox',
  validateSearch: validateInboxSearch,
  beforeLoad: ({ search, location }) => {
    if (!hasToken()) throw redirect({ to: '/welcome' });
    if (needsCanonical(search, location.search)) {
      throw redirect({ to: '/inbox', search: cleanSearch(search), replace: true });
    }
  },
  component: function InboxRouteComponent() {
    return (
      <Suspense fallback={<PRDetailLoading />}>
        <NotificationsScreen fluid />
      </Suspense>
    );
  },
});

const pullsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/pulls',
  validateSearch: validatePullsSearch,
  beforeLoad: ({ search, location }) => {
    if (!hasToken()) throw redirect({ to: '/welcome' });
    if (needsCanonical(search, location.search)) {
      throw redirect({ to: '/pulls', search: cleanSearch(search), replace: true });
    }
  },
  component: function PullsRouteComponent() {
    // One shell for all three tabs (My PRs · Reviewing · Team). It keeps
    // the PyorWindow + tab bar mounted and swaps only the body by `tab`,
    // so switching tabs never remounts the bar.
    return <PullsScreen fluid />;
  },
});

const localRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/local',
  beforeLoad: () => {
    if (!hasToken()) throw redirect({ to: '/welcome' });
  },
  component: function LocalRouteComponent() {
    return (
      <Suspense fallback={<PRDetailLoading />}>
        <LocalReviewsScreen fluid />
      </Suspense>
    );
  },
});

const localReviewRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/local/$reviewId',
  beforeLoad: () => {
    if (!hasToken()) throw redirect({ to: '/welcome' });
  },
  component: function LocalReviewRouteComponent() {
    return (
      <Suspense fallback={<PRDetailLoading />}>
        <ReviewDetailScreen fluid kind="local-review" />
      </Suspense>
    );
  },
});

const settingsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/settings',
  beforeLoad: () => {
    if (!hasToken()) throw redirect({ to: '/welcome' });
  },
  component: function SettingsRouteComponent() {
    return (
      <Suspense fallback={<PRDetailLoading />}>
        <SettingsScreen fluid />
      </Suspense>
    );
  },
});

// PR detail. Path carries identity (owner/repo/number); the rest of
// the view-state rides in the search params validated above.
const prRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/$owner/$repo/$number',
  validateSearch: validatePRSearch,
  beforeLoad: ({ search, location, params }) => {
    // Demo deep-link (`?pr=` → `demo: true`) opens read-only with no
    // token — skip the Setup gate (and the canonical-redirect check) so
    // a cold reload of the shared link still resolves. Token users
    // hitting a non-demo PR route keep the gate.
    if (search.demo) return;
    if (!hasToken()) throw redirect({ to: '/welcome' });
    if (needsCanonical(search, location.search)) {
      throw redirect({
        to: '/$owner/$repo/$number',
        params,
        search: cleanSearch(search),
        replace: true,
      });
    }
  },
  component: PRRouteComponent,
});

// Per-org gate (ADR 0020 #8): a deep link to a blocked org's PR lands on the
// explainer, not the PR (or a 404). Demo deep-links are public — always allowed.
// Fail-open while the gate's data loads, so a seated org's PR never flickers the
// explainer.
function PRRouteComponent() {
  const { owner } = prRoute.useParams();
  const { demo } = prRoute.useSearch();
  const { isOrgAccessible } = useOrgGate();
  const blocked = !demo && !isOrgAccessible(owner);
  return (
    <Suspense fallback={<PRDetailLoading />}>
      {blocked ? (
        <BlockedOrgScreen owner={owner} />
      ) : (
        <ReviewDetailScreen fluid kind="github-pr" />
      )}
    </Suspense>
  );
}

const routeTree = rootRoute.addChildren([
  indexRoute,
  setupRoute,
  welcomeRoute,
  connectRoute,
  connectCallbackRoute,
  connectInstalledRoute,
  inboxRoute,
  pullsRoute,
  localRoute,
  localReviewRoute,
  settingsRoute,
  prRoute,
]);

// History mode depends on the build target (see vite.config.ts):
//   - Electron (`__PIER_ELECTRON__`): HASH history. The renderer is loaded
//     from disk via `file://`, where HTML5 history paths don't resolve — so
//     the whole route lives in the URL fragment (the Electron-safety guarantee).
//   - Web (default): BROWSER history → clean URLs (`/owner/repo/123`, no `#`).
//     Deep links work because the GitHub Pages deploy serves the SPA for any
//     path (index.html → 404.html fallback) and assets use an absolute base.
//
// Hash mode only: seed an empty fragment to `#/` *before* the history is
// instantiated, so the boot redirect is written to the URL instead of running
// in-memory (which a reload would lose). Browser history needs no seeding.
declare const __PIER_ELECTRON__: boolean;
if (
  __PIER_ELECTRON__ &&
  typeof window !== 'undefined' &&
  !window.location.hash
) {
  window.location.hash = '#/';
}
const history = __PIER_ELECTRON__
  ? createHashHistory()
  : createBrowserHistory();

export const router = createRouter({
  routeTree,
  history,
  // We render our own loading skeletons inside each route's Suspense
  // boundary; the global pending component would double them up.
  defaultPreload: false,
  // Any error thrown while rendering a route lands here (replacing
  // TanStack's bare "Something went wrong!"); in dev it surfaces the
  // React component stack so render-loop crashes are easy to locate.
  defaultErrorComponent: RouteErrorBoundary,
  // Any address that matches no route renders the global 404 inside the
  // root Outlet (sidebar stays visible) instead of a blank screen.
  defaultNotFoundComponent: NotFoundScreen,
});

// Route objects stay internal to this module: call-sites elsewhere read
// typed params/search via `getRouteApi(routeId)` rather than importing the
// route objects (which formed router ↔ screen import cycles).

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}
