// The viewer's sticky merge-method preference, persisted to
// localStorage. Shared so the merge box (the picker) and the status-pill
// popup (the lightweight twin) agree on which method is "current" — the
// popup mirrors whatever you last chose in the box rather than always
// showing the repo default. Failures (private mode, quota) degrade to
// `merge`, github.com's own default when the repo allows it.

import type { MergeMethod } from '../github/lifecycle';

const KEY = 'pyor:merge-method';

/** The last-picked method, or `merge` when nothing valid is stored. */
export function readStoredMergeMethod(): MergeMethod {
  try {
    const v = localStorage.getItem(KEY);
    if (v === 'merge' || v === 'squash' || v === 'rebase') return v;
  } catch {
    // localStorage unavailable (private mode / SSR) — fall through.
  }
  return 'merge';
}

/** Persist the picked method. Best-effort — ignores quota/availability. */
export function storeMergeMethod(m: MergeMethod): void {
  try {
    localStorage.setItem(KEY, m);
  } catch {
    // best-effort persistence; ignore quota / availability errors.
  }
}

/** Reconcile a pick against the repo-allowed methods: the pick when the
 * repo still allows it, else the repo default (first allowed), else
 * `merge`. Single source of the box ↔ popup agreement. */
export function reconcileMergeMethod(
  pick: MergeMethod,
  allowed: MergeMethod[],
): MergeMethod {
  return allowed.includes(pick) ? pick : (allowed[0] ?? 'merge');
}
