// Slim review dock above the status bar. Summarises the current
// draft and exposes ⌘⏎ to open the submit modal.
//
// Both this dock + ReviewModal read the same `useDraftReview(owner,
// repo, number)` hook upstream, so they stay in sync without prop
// drilling: the parent ChangesTab passes (draft, actions) to both.
//
// Built on shadcn primitives — Button, Badge. No `useT()` / inline
// theme tokens (ADR 0011 — shadcn-only UI surface). The single
// remaining `style={...}` carries verdict-specific tint vars
// (API-shaped #hex per verdict / per theme), mirroring the pattern
// in ReviewModal.

import { CheckIcon, CheckCircle2Icon, MessageSquareIcon, Trash2Icon, XCircleIcon } from 'lucide-react';
import { useState, type ReactNode } from 'react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import type { DraftReview } from '../../review/reviewDraftTypes';
import { ConfirmModal } from '../lifecycle/ConfirmModal';
import { VERDICTS, type Verdict } from './review';

interface Props {
  draft: DraftReview;
  onOpenModal: () => void;
  onDiscard: () => void;
}

export function ReviewDock({ draft, onOpenModal, onDiscard }: Props) {
  // Discarding deletes the whole pending review on GitHub (ADR 0019), so
  // confirm first — it's destructive and can't be undone.
  const [confirmOpen, setConfirmOpen] = useState(false);
  const v = VERDICTS[draft.verdict];
  const lineCount = draft.lineComments.filter((c) => !c.startLine).length;
  const rangeCount = draft.lineComments.filter((c) => c.startLine).length;
  const fileCount = draft.fileComments.length;
  const replyCount = draft.replies.length;
  const totalPending = lineCount + rangeCount + fileCount + replyCount;
  const hasDraft = totalPending > 0 || draft.overallBody.trim() !== '';

  // Verdict tints are API-shaped (#hex per verdict + per theme) —
  // hoist them to CSS variables on the verdict chip so child rules
  // read one source. Same pattern as ReviewModal's VerdictPicker.
  const tintVars = {
    '--tint': v.color,
    '--tint-dark': v.colorDark,
  } as React.CSSProperties;

  const pendingBreakdown = [
    lineCount > 0 && `${lineCount} line`,
    rangeCount > 0 && `${rangeCount} range`,
    fileCount > 0 && `${fileCount} file-level`,
    replyCount > 0 && `${replyCount} repl${replyCount === 1 ? 'y' : 'ies'}`,
  ]
    .filter(Boolean)
    .join(' · ');

  return (
    <div className="flex h-[38px] shrink-0 items-center gap-3 border-t bg-[hsl(var(--background))] px-3.5 text-[12.5px] text-foreground">
      <span className="inline-flex items-center gap-1.5">
        <span
          className={[
            'size-[7px] rounded-full',
            hasDraft ? 'bg-primary' : 'bg-muted-foreground/40',
          ].join(' ')}
        />
        <b className="font-semibold">Review draft</b>
        <span className="text-muted-foreground">
          · {totalPending} pending
          {!hasDraft && ' — start by leaving a comment or opening submit'}
        </span>
      </span>
      {totalPending > 0 && (
        <>
          <span className="text-muted-foreground/40">·</span>
          <span className="text-muted-foreground">{pendingBreakdown}</span>
        </>
      )}
      <span className="text-muted-foreground/40">·</span>
      <span
        className="inline-flex items-center gap-1.5 [--tint-current:var(--tint)] dark:[--tint-current:var(--tint-dark)]"
        style={tintVars}
      >
        <VerdictIcon
          verdict={v.id}
          className="size-3 text-[color:var(--tint-current)]"
        />
        <span className="font-semibold text-[color:var(--tint-current)]">
          {v.label}
        </span>
      </span>
      <div className="flex-1" />
      {hasDraft && (
        <Button variant="ghost" size="xs" onClick={() => setConfirmOpen(true)}>
          Discard
        </Button>
      )}
      <Button size="xs" onClick={onOpenModal}>
        <CheckIcon />
        Submit review
        <Kbd>⌘⏎</Kbd>
      </Button>
      <ConfirmModal
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        title="Discard review?"
        description="This deletes your in-progress review on GitHub — every pending comment is removed. This can't be undone."
        tone="destructive"
        icon={Trash2Icon}
        confirmLabel="Discard review"
        confirmIcon={Trash2Icon}
        onConfirm={() => {
          setConfirmOpen(false);
          onDiscard();
        }}
      />
    </div>
  );
}

// Mirrors ReviewModal's VerdictIcon — same lucide mapping so the
// dock and the modal show the same glyph per verdict.
function VerdictIcon({
  verdict,
  className,
}: {
  verdict: Verdict;
  className?: string;
}) {
  if (verdict === 'approve') return <CheckCircle2Icon className={className} />;
  if (verdict === 'changes') return <XCircleIcon className={className} />;
  return <MessageSquareIcon className={className} />;
}

// Inline keystroke hint built on shadcn Badge. Replaces the legacy
// `Kbd` from `ui/primitives` (ADR 0011 — shadcn-only UI surface).
function Kbd({ children }: { children: ReactNode }) {
  return (
    <Badge
      variant="outline"
      className="ml-1 h-4 min-w-4 justify-center rounded-sm border-current/30 bg-current/20 px-1 py-0 text-[10.5px] font-medium text-primary-foreground"
    >
      {children}
    </Badge>
  );
}
