// Shared UI for non-image binary files in the diff pane (.wasm, compiled
// objects, fonts, archives, …). These have no text diff and aren't an image
// we can preview, so — like the content-less rename treatment — we replace
// the (hidden) synthetic body with:
//
//   - a "Binary" PILL in the header metadata slot (BinaryBadge), and
//   - a body NOTE row in the empty body (BinaryFileCard) that explains why
//     there's no diff and offers "Open on GitHub" + "Comment on file".
//
// Surface-agnostic: both the PR diff (LiveDiffPane) and the local pre-PR diff
// render the same chrome from these pieces. Neutral muted accent (not the
// rename blue) so it reads as "nothing to show here", not a status change.

import {
  BinaryIcon,
  ExternalLinkIcon,
  MessageCirclePlusIcon,
} from 'lucide-react';
import { DiffNoteCard, DiffNoteAction } from './DiffNoteCard';

/** Small "Binary" chip for the file-header metadata slot — replaces the
 *  lib's bogus +1/−0 counts (hidden via the `data-pyor-binary` shadow CSS),
 *  signalling the empty body is intentional. */
export function BinaryBadge() {
  return (
    <span
      className="inline-flex items-center gap-1 whitespace-nowrap rounded border bg-card px-1.5 py-px text-[11px] font-medium text-muted-foreground"
      title="Binary file — no text diff to render"
    >
      <BinaryIcon className="size-3" />
      Binary
    </span>
  );
}

/** Body note row rendered in the empty diff body (the annotation slot).
 *  Explains the absent diff and re-offers the valid actions: view the raw
 *  bytes on GitHub (`githubUrl`) and leave a file-level comment (`onComment`).
 *  Omit either to hide its affordance (e.g. read-only, or the local surface
 *  with no GitHub URL). */
export function BinaryFileCard({
  githubUrl,
  onComment,
}: {
  githubUrl?: string | null;
  onComment?: () => void;
}) {
  return (
    <DiffNoteCard
      icon={BinaryIcon}
      title="Binary file"
      note="This file is binary, so there's no text diff to show."
      actions={
        (githubUrl || onComment) && (
          <>
            {githubUrl && (
              <DiffNoteAction
                icon={ExternalLinkIcon}
                label="Open on GitHub"
                href={githubUrl}
              />
            )}
            {onComment && (
              <DiffNoteAction
                icon={MessageCirclePlusIcon}
                label="Comment on file"
                onClick={onComment}
              />
            )}
          </>
        )
      }
    />
  );
}
