// Entry point — mounts the full Pyor app under TanStack Query
// (with IndexedDB persistence) + the existing ThemeProvider.
//
// React.StrictMode is intentionally OFF for now. It double-mounts
// every component in dev, which doubles the cost of the
// @pierre/diffs renderer instantiation per Phase 0 spike. We'll
// re-enable StrictMode once the spike has validated steady-state
// perf and the double-mount is a useful correctness check, not a
// perf footgun.
//
// Persistence: `PersistQueryClientProvider` hydrates the in-memory
// QueryClient cache from IndexedDB before the tree renders, then
// flushes mutations back on every cache update (debounced inside
// the persister). Means re-opening Pyor — or refreshing a PR
// you've already reviewed — comes back already-warm: no network
// roundtrips for blob contents, file lists, PR metadata until
// staleTime elapses or you force-refresh.

import ReactDOM from 'react-dom/client';
// Tailwind base + shadcn CSS variables. Loaded first so shadcn
// primitives have their tokens defined by the time React mounts.
import './styles/tailwind.css';

import { defaultShouldDehydrateQuery } from '@tanstack/react-query';
import { PersistQueryClientProvider } from '@tanstack/react-query-persist-client';
import { createAsyncStoragePersister } from '@tanstack/query-async-storage-persister';
import type { PersistedClient } from '@tanstack/react-query-persist-client';
import { App } from './App';
import { purgePrDraftLocalStorage } from './review/purgePrDrafts';
import { queryClient } from './lib/queryClient';
import { queryAsyncStorage } from './lib/queryStore';
import { shouldPersistQuery } from './lib/persistGate';
import { initObservability, Sentry } from './observability';

// ADR 0021: initialise error tracking + product analytics as early as
// possible, before any app code runs. No-ops when keys/DSN are unset.
initObservability();

// JSON.stringify doesn't natively serialize Map (collapses to `{}`)
// or Set (collapses to `{}`) or Date (collapses to ISO string).
// fetchPRFileContents returns a Map<filename, FileContents> as one
// of our cached query values, so the default persister breaks on
// rehydrate: the deserialized value is `{}` and any
// `.get(filename)` call throws "fileContents.get is not a function".
//
// Wrap the default serializer with Map<->Array round-tripping. We
// emit a tagged envelope `{$type:'Map', entries:[...]}` so the
// reverse pass knows what to reconstruct. Set + Date round-tripping
// added preemptively — if a future query returns one, the persister
// won't surprise us.
type Tagged =
  | { $type: 'Map'; entries: [unknown, unknown][] }
  | { $type: 'Set'; values: unknown[] };

const stringify = (value: unknown): string =>
  JSON.stringify(value, (_key, v) => {
    if (v instanceof Map) {
      return { $type: 'Map', entries: Array.from(v.entries()) } satisfies Tagged;
    }
    if (v instanceof Set) {
      return { $type: 'Set', values: Array.from(v.values()) } satisfies Tagged;
    }
    return v;
  });

const parse = (text: string): PersistedClient =>
  JSON.parse(text, (_key, v) => {
    if (v && typeof v === 'object' && '$type' in v) {
      const tagged = v as Tagged;
      if (tagged.$type === 'Map') return new Map(tagged.entries);
      if (tagged.$type === 'Set') return new Set(tagged.values);
    }
    return v;
  }) as PersistedClient;

const persister = createAsyncStoragePersister({
  storage: queryAsyncStorage,
  // Map-aware serializer — see comment above.
  serialize: stringify,
  deserialize: parse,
  key: 'pyor:query-cache',
  // Persisting is EXPENSIVE on the main thread: every write re-runs
  // dehydrate + JSON.stringify over the ENTIRE cache snapshot — measured
  // at 105 MB / ~250 ms-plus-GC on a profile with a day's PRs in it —
  // and a persist fires on every cache 'updated' event, which includes
  // the no-op fetchStatus flips of the 15s heartbeat. At 1s this wrote
  // the full snapshot several times per poll cycle and was the largest
  // single contributor to multi-second scroll freezes on big PRs. 15s
  // (one write per heartbeat at most) keeps the same durability story —
  // this is a refetchable cache and review drafts live server-side
  // (ADR 0019) — a hard crash just costs up to 15s of cache freshness.
  throttleTime: 15_000,
});

// In dev, log the React component stack for any error caught by a
// boundary (and any uncaught one). TanStack Router's errorComponent
// doesn't forward `componentStack`, so this root-level hook is what
// actually names the component that blew up — invaluable for locating
// render-loop crashes ("Maximum update depth exceeded"). No-op in prod.
// React boundary errors are swallowed by the router's error component, so
// Sentry's global handlers never see them — forward them explicitly here. In
// dev we also log the component stack (TanStack Router's errorComponent doesn't
// forward it), invaluable for locating render-loop crashes.
const reportReactError =
  (kind: 'caught' | 'uncaught') =>
  (error: unknown, errorInfo: { componentStack?: string }) => {
    Sentry.captureException(error, {
      contexts: { react: { componentStack: errorInfo.componentStack } },
      tags: { react_error: kind },
    });
    if (import.meta.env.DEV)
      console.error(
        `[react] ${kind} error:\n`,
        error,
        '\n\nCOMPONENT STACK:\n',
        errorInfo.componentStack,
      );
  };

const rootOptions = {
  onCaughtError: reportReactError('caught'),
  onUncaughtError: reportReactError('uncaught'),
};

// Stale-chunk recovery after a deploy. Vite emits new hashed chunk
// filenames every build; a tab still holding the previous index.html
// requests the old hashes, which no longer exist on the production
// alias. Vercel's catch-all rewrite then serves index.html for the
// missing .js → MIME "text/html" mismatch → "Failed to fetch
// dynamically imported module" → users land on the error page.
//
// Vite fires `vite:preloadError` for precisely this failure. Reload
// once to fetch the fresh index.html + chunk graph. The timestamp
// guard caps recovery at one reload per 10s, so a chunk that's
// genuinely gone falls through to the error boundary instead of
// looping. No-op in Electron (assets are local, loaded from disk).
const PRELOAD_RELOAD_KEY = 'pyor:preload-reload';
window.addEventListener('vite:preloadError', (event) => {
  event.preventDefault();
  const last = Number(sessionStorage.getItem(PRELOAD_RELOAD_KEY) ?? 0);
  if (Date.now() - last < 10_000) return;
  sessionStorage.setItem(PRELOAD_RELOAD_KEY, String(Date.now()));
  window.location.reload();
});

// ADR 0019: the in-progress PR review is now GitHub's server-side
// pending review. Drop any stale localStorage draft entries on load.
purgePrDraftLocalStorage();

ReactDOM.createRoot(document.getElementById('root')!, rootOptions).render(
  <PersistQueryClientProvider
    client={queryClient}
    persistOptions={{
      persister,
      // Bump this version when we make a breaking change to query
      // shapes OR persister behaviour (e.g. swapping the serializer).
      // Mismatched versions clear the persisted cache — safer than
      // hydrating stale shapes into newer code.
      //
      //   v1 → initial, default JSON serializer (broke Map round-trip)
      //   v2 → custom serializer with Map/Set/Date support
      //   v3 → stop persisting Blob queries (they collapsed to `{}` and
      //        crashed URL.createObjectURL on restore); clears any snapshot
      //        already poisoned with a serialized-blob entry
      buster: 'v3',
      // Keep persisted entries alive as long as the in-memory gcTime
      // (24h, see queryClient.ts). The persister's default maxAge is
      // also 24h, but we set it explicitly next to `buster` so the
      // contract is visible: a future `gcTime` bump must bump this in
      // lockstep, or restored entries older than maxAge get silently
      // dropped as "too old" and the warm-cache no-flash open breaks.
      maxAge: 24 * 60 * 60 * 1000,
      // Throttling above bounds how OFTEN the snapshot is serialized;
      // this gate bounds how BIG it is. File-blob queries (contents /
      // files) from PRs the user has moved on from fall out of the
      // snapshot after 2h, so yesterday's 90 MB PR can't keep costing
      // ~1s of main-thread serialize on every poll tick of today's
      // review. See lib/persistGate.ts for the full contract (it also
      // absorbs the app-version exclusion that used to live here).
      dehydrateOptions: {
        shouldDehydrateQuery: (q) =>
          defaultShouldDehydrateQuery(q) && shouldPersistQuery(q),
      },
    }}
  >
    <App />
  </PersistQueryClientProvider>,
);
