// AppSidebar — fixed w-12 icon-only rail with radial SVG rate-limit gauges.
//
// Compact redesign (PR compact-redesign): replaces shadcn's collapsible
// Sidebar primitive with a plain fixed-width aside. Each nav item is a
// Tooltip-wrapped Link; badges render as tiny pill overlays.
// Rate-limit gauges use radial SVG arcs (no Progress bars).
// TooltipProvider lives in Shell.tsx (wraps the whole app) — this file
// only uses TooltipTrigger / TooltipContent.

import { useQuery } from '@tanstack/react-query';
import { Link, linkOptions } from '@tanstack/react-router';
import {
  Bell,
  GitPullRequest,
  Laptop2,
  Settings as SettingsIcon,
} from 'lucide-react';
import { INBOX_DEFAULTS, PULLS_DEFAULTS } from '../router/search';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { getRateLimit, getViewer } from '../github/client';
import { UpdateGauge } from '../desktop/UpdateGauge';
import type { Viewer } from '../github/types';

export type AppNavKey = 'inbox' | 'pulls' | 'local' | 'settings';

interface AppSidebarProps {
  active: AppNavKey;
  badges?: Partial<Record<AppNavKey, number>>;
}

// Typed link targets — each carries the route's explicit default search
// params, so every sidebar link is canonical and type-checked.
const NAV_LINKS = {
  inbox: linkOptions({ to: '/inbox', search: INBOX_DEFAULTS }),
  pulls: linkOptions({ to: '/pulls', search: PULLS_DEFAULTS }),
  local: linkOptions({ to: '/local' }),
  settings: linkOptions({ to: '/settings' }),
};

const REVIEWS_ITEMS: {
  id: AppNavKey;
  label: string;
  icon: typeof Bell;
  beta?: boolean;
}[] = [
  { id: 'inbox', label: 'Inbox', icon: Bell },
  { id: 'pulls', label: 'Pull requests', icon: GitPullRequest },
  { id: 'local', label: 'Local reviews', icon: Laptop2, beta: true },
];

export function AppSidebar({ active, badges }: AppSidebarProps) {
  return (
    <aside className="flex h-full w-12 shrink-0 flex-col border-r bg-sidebar text-sidebar-foreground">
      <nav className="flex flex-1 flex-col gap-0.5 px-1.5 py-2">
        {REVIEWS_ITEMS.map((item) => {
          const Icon = item.icon;
          const badge = badges?.[item.id];
          const isActive = active === item.id;
          return (
            <Tooltip key={item.id}>
              <TooltipTrigger asChild>
                <Link
                  {...NAV_LINKS[item.id]}
                  className={
                    'relative flex size-8 items-center justify-center rounded-md text-sm transition-colors ' +
                    (isActive
                      ? 'bg-sidebar-accent text-sidebar-accent-foreground'
                      : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground')
                  }
                  aria-label={item.label}
                >
                  <Icon className="size-4" />
                  {badge != null && badge > 0 && (
                    <span className="absolute right-0.5 top-0.5 flex h-[14px] min-w-[14px] items-center justify-center rounded-full bg-primary px-[3px] text-[9px] font-semibold text-primary-foreground ring-2 ring-sidebar">
                      {badge > 99 ? '99+' : badge}
                    </span>
                  )}
                </Link>
              </TooltipTrigger>
              <TooltipContent side="right" className="text-xs">
                {item.label}
                {item.beta && (
                  <span className="ml-1 rounded bg-muted px-1 py-px text-[10px] font-medium text-muted-foreground">
                    Beta
                  </span>
                )}
              </TooltipContent>
            </Tooltip>
          );
        })}
      </nav>
      <div className="flex shrink-0 flex-col items-center gap-1 border-t px-1.5 py-2">
        <UpdateGauge />
        <RateLimitGauges />
        <Tooltip>
          <TooltipTrigger asChild>
            <Link
              {...NAV_LINKS.settings}
              className={
                'flex size-8 items-center justify-center rounded-md text-sm transition-colors ' +
                (active === 'settings'
                  ? 'bg-sidebar-accent text-sidebar-accent-foreground'
                  : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground')
              }
              aria-label="Settings"
            >
              <SettingsIcon className="size-4" />
            </Link>
          </TooltipTrigger>
          <TooltipContent side="right" className="text-xs">
            Settings
          </TooltipContent>
        </Tooltip>
        <ViewerAvatarBlock />
      </div>
    </aside>
  );
}

// ── Rate-limit gauges (radial SVG) ──────────────────────────────

function RateLimitGauges() {
  const rateQuery = useQuery({
    queryKey: ['rate_limit'],
    queryFn: () => getRateLimit(),
    refetchInterval: 60_000,
    staleTime: 30_000,
  });
  const r = rateQuery.data?.resources;
  if (!r) return null;
  const resetsInSec = r.core.reset
    ? Math.max(0, r.core.reset - Math.floor(Date.now() / 1000))
    : 0;
  return (
    <>
      <RadialGauge
        label="REST"
        shortLabel="R"
        used={r.core.used}
        limit={r.core.limit}
        resetsInSec={resetsInSec}
      />
      <RadialGauge
        label="GraphQL"
        shortLabel="G"
        used={r.graphql.used}
        limit={r.graphql.limit}
        resetsInSec={resetsInSec}
      />
    </>
  );
}

function RadialGauge({
  label,
  shortLabel,
  used,
  limit,
  resetsInSec,
}: {
  label: string;
  shortLabel: string;
  used: number;
  limit: number;
  resetsInSec: number;
}) {
  const pct = limit > 0 ? Math.min(1, used / limit) : 0;
  const radius = 7;
  const circ = 2 * Math.PI * radius;
  const dashOffset = circ * (1 - pct);
  const strokeClass =
    pct > 0.85
      ? 'stroke-destructive'
      : pct > 0.6
        ? 'stroke-amber-500'
        : 'stroke-foreground/70';
  const resetsLabel = (() => {
    if (resetsInSec <= 0) return 'soon';
    const m = Math.round(resetsInSec / 60);
    return m < 60 ? `${m}m` : `${Math.round(m / 60)}h`;
  })();
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          className="relative flex size-8 items-center justify-center"
          aria-label={`${label} API usage`}
        >
          <svg
            className="size-[18px] -rotate-90"
            viewBox="0 0 18 18"
            fill="none"
          >
            <circle
              cx="9"
              cy="9"
              r={radius}
              strokeWidth={2}
              className="stroke-muted"
            />
            <circle
              cx="9"
              cy="9"
              r={radius}
              strokeWidth={2}
              strokeDasharray={`${circ} ${circ}`}
              strokeDashoffset={dashOffset}
              strokeLinecap="round"
              className={`transition-[stroke-dashoffset] duration-500 ${strokeClass}`}
            />
          </svg>
          <span className="absolute text-[8px] font-semibold leading-none text-muted-foreground">
            {shortLabel}
          </span>
        </button>
      </TooltipTrigger>
      <TooltipContent side="right" className="text-xs">
        {label} API · {used.toLocaleString()} / {limit.toLocaleString()} ·
        resets in {resetsLabel}
      </TooltipContent>
    </Tooltip>
  );
}

// ── Viewer avatar ──────────────────────────────────────────────

function ViewerAvatarBlock() {
  const viewerQuery = useQuery<Viewer>({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: 5 * 60_000,
  });
  const v = viewerQuery.data;
  const display = v?.name?.trim() || v?.login || '…';
  const handle = v?.login ? `@${v.login}` : '';
  const initials = display
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((s) => s[0]?.toUpperCase() ?? '')
    .join('');
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          className="flex size-8 items-center justify-center"
          aria-label={`${display} ${handle}`}
        >
          <Avatar className="size-6">
            <AvatarImage src={v?.avatar_url} alt={display} />
            <AvatarFallback className="text-[10px]">
              {initials || '–'}
            </AvatarFallback>
          </Avatar>
        </button>
      </TooltipTrigger>
      <TooltipContent side="right" className="text-xs">
        {display} {handle}
      </TooltipContent>
    </Tooltip>
  );
}
