// useLocalChanges — the data engine behind the local pre-PR review's
// "Changes" surface. Owns the local-git queries, the commit-dropdown
// scope resolution (all / commit-range / uncommitted), the native-git
// content load (with streaming progress), the per-(commit,path) viewed
// state, and the local annotation layer — and returns a normalized model
// the surface feeds into the SAME production `ChangesTab` + LiveDiffPane
// the GitHub PR detail uses.
//
// The toolbar + scope/diff/search UI state live in the SURFACE
// (LocalReviewSurface) so the commit dropdown can sit in the tab strip
// and the Commits tab can drive it — mirroring PRDetailScreen, which owns
// `tab` + the commit scope together. This hook takes `scopeSel` as a
// controlled input and returns everything else.

import { useEffect, useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import {
  UNCOMMITTED_SHA,
  type CommitScopeSelection,
  type LocalCommitListItem,
} from "../pr/changes/SubToolbar";
import { localFileToGh } from "../pr/changes/changesModel";
import { useCollapseState } from "../pr/changes/collapseHooks";
import type { CollapseHookValue } from "../pr/changes/collapseHooks";
import type { DiffAnnotationLayer } from "../pr/changes/LiveDiffPane";
import { useLocalAnnotationLayer } from "../pr/local/useLocalAnnotationLayer";
import { useLocalReviewViewed } from "../review/useLocalReviewViewed";
import type { ViewedHookValue } from "../review/viewedHooks";
import {
  ALL_SCOPE_COMMIT,
  WORKING_TREE_COMMIT,
} from "../review/localReviewViewed";
import { WORKING_TREE_ANCHOR } from "../review/localReviewComments";
import type { ImageFileEntry } from "../github/buildDiff";
import type { FileContents } from "../github/fetchPRFileContents";
import type { GHPullRequestFile } from "../github/types";
import { sortFilesTreeOrder } from "../util/sortFilesTreeOrder";
import {
  bridge,
  isElectron,
  type LocalDiff,
  type LocalDiffFile,
} from "../desktop/electronBridge";
import { getViewer } from "../github/client";

const EMPTY_CONTENTS: Map<string, FileContents> = new Map();

const IMAGE_EXT =
  /\.(png|apng|jpe?g|jfif|pjpe?g?|gif|bmp|webp|avif|ico|cur|psd|tiff?|icns)$/i;
const SVG_EXT = /\.svg$/i;

/** Files loaded per native-git batch round. Tune for streaming feel vs
 * concurrency: chunks run sequentially so at most one chunk's bounded
 * `git show` pool is in flight, and progress updates per chunk. */
const LOAD_CHUNK = 60;

function ghStatus(s: LocalDiffFile["status"]): string {
  return s === "deleted" ? "removed" : s;
}

/** Union the committed (merge-base..head) file list with the working-tree
 * (head..working-tree) list for the "all changes" scope. A path present in
 * BOTH keeps the committed entry's add/delete-ness (a file added vs the
 * base is still net-added after a later uncommitted edit) but takes the
 * latest stats; WT-only files are appended. The final list is tree-sorted
 * downstream, so insertion order here doesn't affect display. */
function mergeLocalFiles(
  committed: LocalDiffFile[],
  wt: LocalDiffFile[],
): LocalDiffFile[] {
  const byPath = new Map<string, LocalDiffFile>();
  committed.forEach((f) => byPath.set(f.path, f));
  wt.forEach((f) => {
    const prior = byPath.get(f.path);
    if (prior && (prior.status === "added" || prior.status === "deleted")) {
      // Preserve net add/delete vs base; refresh the line stats from WT.
      byPath.set(f.path, { ...prior, additions: f.additions, deletions: f.deletions });
    } else {
      byPath.set(f.path, f);
    }
  });
  return [...byPath.values()];
}

interface ScopeLoad {
  contents: Map<string, FileContents>;
  patchByPath: Map<string, string>;
}

/** In-memory LRU of computed scope loads, keyed by repo + refs + the file
 * set's path/stat signature. Reopening the same review — or flipping back
 * to a previously-viewed commit scope — reuses the result instead of
 * re-reading every blob through the native-git bridge (the "recomputes
 * everything on every open" complaint). Survives component remounts within
 * the session; the watcher's query invalidation changes the file signature
 * whenever the diff actually moves, so a stale entry can't win. */
const SCOPE_LOAD_CACHE = new Map<string, ScopeLoad>();
const SCOPE_LOAD_CACHE_MAX = 32;
function scopeCacheKey(repoPath: string, r: ResolvedScope): string {
  const sig = r.files
    .map(
      (f) =>
        `${f.path}:${f.status}:${f.additions}:${f.deletions}:${f.previousPath ?? ""}`,
    )
    .join("|");
  return `${repoPath}�${r.oldRef}�${r.newRef ?? "WT"}�${sig}`;
}
function rememberScopeLoad(key: string, val: ScopeLoad): void {
  SCOPE_LOAD_CACHE.delete(key); // re-insert as most-recent
  SCOPE_LOAD_CACHE.set(key, val);
  if (SCOPE_LOAD_CACHE.size > SCOPE_LOAD_CACHE_MAX) {
    const oldest = SCOPE_LOAD_CACHE.keys().next().value;
    if (oldest !== undefined) SCOPE_LOAD_CACHE.delete(oldest);
  }
}

/** Load one scope's diff via the native-git batch bridge, in sequential
 * chunks so progress streams and the diff renders progressively. OLD via
 * `batchShow(oldRef)`, NEW via `batchReadWorktree` (working-tree scopes)
 * or `batchShow(newRef)` (committed span), patches via `batchDiff`. */
async function loadScopeDiff(
  repoPath: string,
  oldRef: string,
  newRef: string | null,
  files: LocalDiffFile[],
  signal: AbortSignal,
  onProgress?: (resolved: number, total: number) => void,
): Promise<ScopeLoad> {
  const contents = new Map<string, FileContents>();
  const patchByPath = new Map<string, string>();
  const b = bridge();
  const total = files.length;
  if (!b || total === 0) {
    onProgress?.(0, 0);
    return { contents, patchByPath };
  }
  const chunks = Array.from(
    { length: Math.ceil(total / LOAD_CHUNK) },
    (_, i) => files.slice(i * LOAD_CHUNK, (i + 1) * LOAD_CHUNK),
  );
  // Sequential chunks (reduce-over-promises, no for-loops) — bounds the
  // concurrent `git show` pool to one chunk + reports progress. We do NOT
  // flush partial contents per chunk: the caller sets the whole map ONCE
  // at the end, so the diff renders all-real in a single pass with no
  // placeholder→real churn (which desyncs @pierre/diffs' file-header
  // counts vs body — the "deploy-pages.yml shows +1" bug).
  await chunks.reduce(async (prev, chunk) => {
    await prev;
    if (signal.aborted) return;
    const paths = chunk.map((f) => f.path);
    const oldPaths = [...new Set(chunk.map((f) => f.previousPath ?? f.path))];
    const [oldRec, newRec, patchRec] = await Promise.all([
      b.localRepoBatchShow(repoPath, oldRef, oldPaths),
      newRef === null
        ? b.localRepoBatchReadWorktree(repoPath, paths)
        : b.localRepoBatchShow(repoPath, newRef, paths),
      // VS Code-matching diff: show whitespace changes (no -w). Paired
      // with the histogram algorithm set in the native batchDiff.
      b.localRepoBatchDiff(repoPath, oldRef, newRef, paths, {
        ignoreWhitespace: false,
      }),
    ]);
    if (signal.aborted) return;
    chunk.forEach((f) => {
      const isAdded = f.status === "added";
      const isDeleted = f.status === "deleted";
      // Raw blob reads — null = unreadable (binary/oversize) or absent at
      // the ref. CONTENT-based classification: if both meaningful sides
      // decode as text, render as a text diff regardless of git's numstat
      // binary flag (git false-flags some text files, e.g. ones with an
      // earlier binary-looking blob, as `-\t-`). (BUG A1)
      const oldRaw = oldRec[f.previousPath ?? f.path] ?? null;
      const newRaw = newRec[f.path] ?? null;
      const oldText = isAdded ? "" : oldRaw;
      const newText = isDeleted ? "" : newRaw;
      // A null read on a side that SHOULD have content (not the empty side
      // of an add/delete) means the blob was unreadable as text — binary or
      // oversize. git's numstat misses this for untracked files (an added
      // image in the uncommitted scope reads `isBinary:false`), so we infer
      // it from the failed decode instead of trusting the flag alone.
      const oldUnreadable = !isAdded && oldRaw === null;
      const newUnreadable = !isDeleted && newRaw === null;
      if (oldText !== null && newText !== null) {
        // Both meaningful sides decoded as text → render a text diff
        // regardless of git's numstat binary flag (git false-flags some
        // text files, e.g. ones with an earlier binary-looking blob). (A1)
        contents.set(f.path, { oldText, newText, isBinary: false });
      } else if (f.isBinary === true || oldUnreadable || newUnreadable) {
        // git says binary, OR a side that should have content couldn't be
        // decoded → treat as a binary blob (image preview / skipped banner).
        contents.set(f.path, { oldText: "", newText: "", isBinary: true });
      } else {
        // Remaining nulls are legitimately-empty sides (added-vs-base or a
        // removed file) → empty that side, render as text.
        contents.set(f.path, {
          oldText: oldText ?? "",
          newText: newText ?? "",
          isBinary: false,
        });
      }
      const patch = patchRec[f.path];
      if (patch) patchByPath.set(f.path, patch);
    });
    onProgress?.(contents.size, total);
  }, Promise.resolve());
  return { contents, patchByPath };
}

interface ResolvedScope {
  mode: "all" | "uncommitted" | "span";
  files: LocalDiffFile[];
  oldRef: string;
  /** null = diff the working tree. */
  newRef: string | null;
  commitKey: string;
  /** Real committed head SHA — staleness anchor for committed comments. */
  anchorHead: string;
}

export interface LocalChangesController {
  diff: LocalDiff | null;
  error: string | null;
  commitList: LocalCommitListItem[];
  commitCount: number;
  viewedCount: number;
  totalFiles: number;
  /** Viewed across ALL changes (the no-scope rollup), independent of the
   * active commit scope. */
  overallViewedCount: number;
  overallTotalFiles: number;
  /** True when the active scope is a single commit / range / uncommitted
   * (i.e. not the all-changes rollup) — drives whether to also show a
   * per-commit viewed indicator next to the overall one. */
  isScoped: boolean;
  uncommittedCount: number;
  viewedState: ViewedHookValue;
  collapseState: CollapseHookValue;
  annotationLayer: DiffAnnotationLayer;
  files: GHPullRequestFile[];
  fileContents: Map<string, FileContents> | undefined;
  patchByPath: Map<string, string> | undefined;
  modelBaseSha: string | undefined;
  modelHeadSha: string | undefined;
  baseRef: string;
  headRef: string;
  oldRef: string | undefined;
  anchorHead: string | undefined;
  filesLoading: boolean;
  contentsLoading: boolean;
  contentsProgress: { resolved: number; total: number };
  viewerLogin: string | undefined;
}

export function useLocalChanges({
  review,
  repoPath,
  base,
  head,
  scopeSel,
}: {
  review: { id: string };
  repoPath: string;
  base: string;
  head: string;
  scopeSel: CommitScopeSelection;
}): LocalChangesController {
  const diffQuery = useQuery({
    queryKey: ["local-review", review.id, "diff", repoPath, base, head, "v2"],
    queryFn: async (): Promise<LocalDiff> => {
      const b = bridge();
      if (!b) throw new Error("Bridge unavailable");
      return b.localRepoDiff(repoPath, base, head);
    },
    enabled: isElectron(),
    // The chokidar watcher invalidates this on any FS/.git change, so the
    // cached result stays valid until something actually moves — no need to
    // refetch on every remount (reopening the same review is then instant).
    staleTime: Infinity,
    gcTime: 30 * 60_000,
  });
  const workingTreeQuery = useQuery({
    queryKey: ["local-review", review.id, "working-tree", repoPath],
    queryFn: async (): Promise<LocalDiffFile[]> => {
      const b = bridge();
      if (!b) throw new Error("Bridge unavailable");
      return b.localRepoWorkingTreeDiff(repoPath);
    },
    enabled: isElectron(),
    staleTime: Infinity,
    gcTime: 30 * 60_000,
  });
  const commitsQuery = useQuery({
    queryKey: ["local-review", review.id, "commit-list", repoPath, base, head],
    queryFn: async () => {
      const b = bridge();
      if (!b) return [];
      return b.localRepoCommits(repoPath, base, head, 250);
    },
    enabled: isElectron(),
    staleTime: 60_000,
  });
  const viewerQuery = useQuery({
    queryKey: ["viewer"],
    queryFn: () => getViewer(),
    enabled: isElectron(),
    staleTime: 5 * 60_000,
  });
  const viewerLogin = viewerQuery.data?.login;

  const diff = diffQuery.data ?? null;
  const uncommittedFiles = useMemo(
    () => workingTreeQuery.data ?? [],
    [workingTreeQuery.data],
  );

  const commitList = useMemo<LocalCommitListItem[]>(
    () =>
      (commitsQuery.data ?? []).map((c) => ({
        sha: c.sha,
        message: c.subject,
        authorName: "",
        authorLogin: null,
        avatarUrl: null,
        date: c.ago,
        additions: c.additions,
        deletions: c.deletions,
        changedFiles: null,
      })),
    [commitsQuery.data],
  );

  // Resolve a commit/range selection → span endpoints (`<sha>~1`..latest).
  const span = useMemo(() => {
    if (!(scopeSel instanceof Set) || scopeSel.size === 0) return null;
    const order = commitList.map((c) => c.sha);
    const idxs = order
      .map((s, i) => (scopeSel.has(s) ? i : -1))
      .filter((i) => i >= 0)
      .sort((a, b) => a - b);
    if (idxs.length === 0) return null;
    const newest = order[idxs[0]];
    const oldest = order[idxs[idxs.length - 1]];
    return { oldRef: `${oldest}~1`, newRef: newest, headSha: newest };
  }, [scopeSel, commitList]);

  const spanDiffQuery = useQuery({
    queryKey: [
      "local-review",
      review.id,
      "span-diff",
      repoPath,
      span?.oldRef,
      span?.newRef,
    ],
    queryFn: async (): Promise<LocalDiff> => {
      const b = bridge();
      if (!b) throw new Error("Bridge unavailable");
      return b.localRepoDiff(repoPath, span!.oldRef, span!.newRef);
    },
    enabled: isElectron() && !!span,
  });

  const committedPaths = useMemo(
    () => new Set((diff?.files ?? []).map((f) => f.path)),
    [diff],
  );
  const uncommittedOnlyPaths = useMemo(() => {
    const s = new Set<string>();
    uncommittedFiles.forEach((f) => {
      if (!committedPaths.has(f.path)) s.add(f.path);
    });
    return s;
  }, [uncommittedFiles, committedPaths]);

  const resolved = useMemo<ResolvedScope | null>(() => {
    if (scopeSel === UNCOMMITTED_SHA) {
      return {
        mode: "uncommitted",
        files: uncommittedFiles,
        oldRef: "HEAD",
        newRef: null,
        commitKey: WORKING_TREE_COMMIT,
        anchorHead: diff?.head ?? "HEAD",
      };
    }
    if (scopeSel instanceof Set && scopeSel.size > 0) {
      if (!span || !spanDiffQuery.data) return null;
      return {
        mode: "span",
        files: spanDiffQuery.data.files,
        oldRef: span.oldRef,
        newRef: span.newRef,
        commitKey: span.headSha,
        anchorHead: span.headSha,
      };
    }
    if (!diff) return null;
    return {
      mode: "all",
      files: mergeLocalFiles(diff.files, uncommittedFiles),
      // Anchor the OLD side on the MERGE-BASE so it matches the three-dot
      // file list + stats (BUG A2). Falls back to base if unavailable.
      oldRef: diff.mergeBase || diff.base,
      newRef: null,
      commitKey: ALL_SCOPE_COMMIT,
      anchorHead: diff.head,
    };
  }, [scopeSel, span, spanDiffQuery.data, diff, uncommittedFiles]);

  const anchorForPath = useMemo(() => {
    return (path: string): string => {
      if (!resolved) return WORKING_TREE_ANCHOR;
      if (resolved.mode === "uncommitted") return WORKING_TREE_ANCHOR;
      if (resolved.mode === "span") return resolved.anchorHead;
      return uncommittedOnlyPaths.has(path)
        ? WORKING_TREE_ANCHOR
        : resolved.anchorHead;
    };
  }, [resolved, uncommittedOnlyPaths]);

  // ── Content load (chunked, streaming progress) ─────────────────────
  const [scopeLoad, setScopeLoad] = useState<ScopeLoad | null>(null);
  const [contentNonce, setContentNonce] = useState(0);
  const [contentsProgress, setContentsProgress] = useState({
    resolved: 0,
    total: 0,
  });
  useEffect(() => {
    if (!resolved) {
      setScopeLoad(null);
      setContentsProgress({ resolved: 0, total: 0 });
      return;
    }
    // Cache hit → flush instantly, skip the native-git re-read entirely.
    const key = scopeCacheKey(repoPath, resolved);
    const cached = SCOPE_LOAD_CACHE.get(key);
    if (cached) {
      rememberScopeLoad(key, cached); // bump recency
      setScopeLoad(cached);
      setContentsProgress({
        resolved: cached.contents.size,
        total: cached.contents.size,
      });
      setContentNonce((n) => n + 1);
      return;
    }
    setScopeLoad(null);
    setContentsProgress({ resolved: 0, total: resolved.files.length });
    const ctrl = new AbortController();
    loadScopeDiff(
      repoPath,
      resolved.oldRef,
      resolved.newRef,
      resolved.files,
      ctrl.signal,
      (resolvedN, total) => {
        if (ctrl.signal.aborted) return;
        setContentsProgress({ resolved: resolvedN, total });
      },
    )
      .then((res) => {
        if (ctrl.signal.aborted) return;
        rememberScopeLoad(key, res);
        // Single flush — the whole contents map lands at once, so the diff
        // renders all-real in one pass (no placeholder→real header desync).
        setScopeLoad(res);
        setContentsProgress({
          resolved: res.contents.size,
          total: res.contents.size,
        });
        setContentNonce((n) => n + 1);
      })
      .catch((e) => {
        if ((e as Error).name === "AbortError") return;
        // eslint-disable-next-line no-console
        console.warn("local scope load failed", e);
      });
    return () => ctrl.abort();
  }, [resolved, repoPath]);

  // ── Viewed-state (per commit, path) ────────────────────────────────
  const commitKey = resolved?.commitKey ?? ALL_SCOPE_COMMIT;
  const viewedState = useLocalReviewViewed(review.id, commitKey);
  const collapseState = useCollapseState("local-review", review.id, 0);

  // Overall (all-changes rollup) viewed-state — independent of the active
  // scope, since viewed is keyed per (commit, path). Lets the toolbar show
  // both "viewed across all changes" AND "viewed in this commit".
  const overallViewedState = useLocalReviewViewed(review.id, ALL_SCOPE_COMMIT);
  const allScopePaths = useMemo(
    () =>
      diff
        ? mergeLocalFiles(diff.files, uncommittedFiles).map((f) => f.path)
        : [],
    [diff, uncommittedFiles],
  );
  const overallTotalFiles = allScopePaths.length;
  const overallViewedCount = useMemo(
    () => allScopePaths.filter((p) => overallViewedState.isViewed(p)).length,
    [allScopePaths, overallViewedState],
  );
  const isScoped = commitKey !== ALL_SCOPE_COMMIT;

  // ── Image / SVG / rename / binary classification for the annotation layer ─
  const { renamedFiles, imageFiles, svgFiles, binaryFiles } = useMemo(() => {
    const renamed: ImageFileEntry[] = [];
    const images: ImageFileEntry[] = [];
    const svgs: ImageFileEntry[] = [];
    const binaries: ImageFileEntry[] = [];
    const list = resolved?.files ?? [];
    const contents = scopeLoad?.contents;
    list.forEach((f) => {
      const c = contents?.get(f.path);
      const entry: ImageFileEntry = {
        filename: f.path,
        status: ghStatus(f.status),
        ...(f.previousPath ? { previousFilename: f.previousPath } : {}),
      };
      if (SVG_EXT.test(f.path) && !c?.isBinary) {
        svgs.push(entry);
        return;
      }
      // Image preview only for image-extension binaries.
      if (IMAGE_EXT.test(f.path) && (c?.isBinary || f.isBinary)) {
        images.push(entry);
        return;
      }
      // Other binaries (.wasm, blobs, archives) → "Binary file" note card,
      // matching buildDiff's binaryFiles path on the GitHub surface.
      if (c?.isBinary || f.isBinary) {
        binaries.push(entry);
        return;
      }
      if (
        c &&
        c.oldText === c.newText &&
        (f.previousPath || f.status === "renamed" || f.status === "copied")
      ) {
        renamed.push(entry);
      }
    });
    return {
      renamedFiles: renamed,
      imageFiles: images,
      svgFiles: svgs,
      binaryFiles: binaries,
    };
  }, [resolved, scopeLoad]);

  const annotationLayer = useLocalAnnotationLayer({
    reviewId: review.id,
    contents: scopeLoad?.contents ?? EMPTY_CONTENTS,
    worktreePath: repoPath,
    headSha: resolved?.anchorHead ?? diff?.head ?? "HEAD",
    anchorForPath,
    renamedFiles,
    imageFiles,
    svgFiles,
    binaryFiles,
    oldRef: resolved?.oldRef ?? "HEAD",
    newRef: resolved?.newRef ?? null,
    viewerLogin,
    viewedState,
    collapseState,
  });

  // ── Model → ChangesTab props ───────────────────────────────────────
  // Tree-sort so the rail + diff stream stay in lockstep (BUG D2).
  const files = useMemo(
    () => sortFilesTreeOrder((resolved?.files ?? []).map(localFileToGh)),
    [resolved],
  );
  const commitCount = commitList.length;
  const viewedCount = useMemo(
    () => files.filter((f) => viewedState.isViewed(f.filename)).length,
    [files, viewedState],
  );

  const modelBaseSha = resolved ? `local:${resolved.oldRef}` : undefined;
  const modelHeadSha = resolved
    ? `local:${resolved.newRef ?? "WT"}:${contentNonce}`
    : undefined;

  const filesLoading =
    !resolved || (resolved.mode === "span" && spanDiffQuery.isPending);
  const contentsLoading = !!resolved && scopeLoad === null;

  const error = diffQuery.error
    ? diffQuery.error instanceof Error
      ? diffQuery.error.message
      : String(diffQuery.error)
    : null;

  return {
    diff,
    error,
    commitList,
    commitCount,
    viewedCount,
    totalFiles: files.length,
    overallViewedCount,
    overallTotalFiles,
    isScoped,
    uncommittedCount: uncommittedFiles.length,
    viewedState,
    collapseState,
    annotationLayer,
    files,
    fileContents: scopeLoad?.contents,
    patchByPath: scopeLoad?.patchByPath,
    modelBaseSha,
    modelHeadSha,
    baseRef: base,
    headRef: head,
    oldRef: resolved?.oldRef,
    anchorHead: resolved?.anchorHead,
    filesLoading,
    contentsLoading,
    contentsProgress,
    viewerLogin,
  };
}
