// Per-file symbol outline as a cmdk command palette (design's recommended
// direction). Grouped by kind, fuzzy-filtered, keyboard-navigable; selecting an
// entry jumps to it in the diff.

import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command';
import type { OutlineSymbol, SymbolKind } from './types';

export interface SymbolOutlineProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  path: string;
  symbols: OutlineSymbol[];
  onSelect: (symbol: OutlineSymbol) => void;
}

const KIND_TILE: Record<SymbolKind, { glyph: string; cls: string }> = {
  function: { glyph: 'ƒ', cls: 'bg-[hsl(var(--pyor-link)/0.14)] text-[hsl(var(--pyor-link))]' },
  method: { glyph: 'M', cls: 'bg-[hsl(262_83%_58%/0.14)] text-[#7c3aed] dark:text-[#c4b5fd]' },
  class: { glyph: 'C', cls: 'bg-[hsl(var(--pyor-warn)/0.16)] text-[hsl(var(--pyor-warn))]' },
  interface: { glyph: 'I', cls: 'bg-[hsl(var(--pyor-warn)/0.16)] text-[hsl(var(--pyor-warn))]' },
  type: { glyph: 'T', cls: 'bg-[hsl(190_90%_40%/0.16)] text-[#0e7490] dark:text-[#67e8f9]' },
  constant: { glyph: '#', cls: 'bg-[hsl(var(--pyor-pass)/0.15)] text-[hsl(var(--pyor-pass))]' },
  variable: { glyph: '#', cls: 'bg-[hsl(var(--pyor-pass)/0.15)] text-[hsl(var(--pyor-pass))]' },
  property: { glyph: '.', cls: 'bg-muted text-muted-foreground' },
};

const GROUP_ORDER: { kind: SymbolKind; label: string }[] = [
  { kind: 'function', label: 'Functions' },
  { kind: 'class', label: 'Classes' },
  { kind: 'interface', label: 'Interfaces' },
  { kind: 'type', label: 'Types' },
  { kind: 'method', label: 'Methods' },
  { kind: 'constant', label: 'Constants' },
  { kind: 'variable', label: 'Variables' },
  { kind: 'property', label: 'Properties' },
];

export function SymbolOutline(props: SymbolOutlineProps) {
  const { open, onOpenChange, path, symbols, onSelect } = props;
  const groups = GROUP_ORDER.map((g) => ({
    ...g,
    items: symbols.filter((s) => s.kind === g.kind),
  })).filter((g) => g.items.length > 0);

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title="Symbol outline"
      description={`Jump to a symbol in ${path}`}
    >
      <div data-symbol-nav-ui="" className="contents">
      <CommandInput placeholder="Jump to symbol…" />
      <CommandList>
        <CommandEmpty>No symbols in this file.</CommandEmpty>
        {groups.map((g) => (
          <CommandGroup key={g.kind} heading={g.label}>
            {g.items.map((s, i) => {
              const tile = KIND_TILE[s.kind];
              return (
                <CommandItem
                  key={`${s.name}:${s.row}:${i}`}
                  value={`${s.name} ${s.signature}`}
                  onSelect={() => onSelect(s)}
                  className="gap-2.5"
                >
                  <span
                    className={`inline-flex size-5 shrink-0 items-center justify-center rounded-md font-mono text-xs font-semibold ${tile.cls}`}
                    style={{ marginLeft: s.depth ? s.depth * 12 : 0 }}
                  >
                    {tile.glyph}
                  </span>
                  <span className="font-mono text-sm">{s.name}</span>
                  {s.signature && (
                    <span className="font-mono text-xs text-muted-foreground">{s.signature}</span>
                  )}
                  <span className="ml-auto font-mono text-xs text-muted-foreground">
                    {s.row + 1}
                  </span>
                </CommandItem>
              );
            })}
          </CommandGroup>
        ))}
      </CommandList>
      </div>
    </CommandDialog>
  );
}
