// AI review-hint result — schema-validated structured output (ADR 0026).
// Each hint is typed + severity-ranked and anchored to a NEW-side diff line.

import * as v from 'valibot';

export const AiHintSchema = v.object({
  path: v.string(),
  line: v.number(),
  type: v.picklist(['bug', 'security', 'risk', 'complexity', 'test-gap']),
  severity: v.picklist(['info', 'warn', 'high']),
  title: v.string(),
  body: v.string(),
  guideline: v.optional(v.string()),
});

export const AiHintsResultSchema = v.object({
  hints: v.array(AiHintSchema),
});

export type AiHintData = v.InferOutput<typeof AiHintSchema>;
export type AiHintsResult = v.InferOutput<typeof AiHintsResultSchema>;

export const AI_HINTS_JSON_SCHEMA: Record<string, unknown> = {
  type: 'object',
  additionalProperties: false,
  required: ['hints'],
  properties: {
    hints: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['path', 'line', 'type', 'severity', 'title', 'body'],
        properties: {
          path: { type: 'string', description: 'Exact file path from the diff' },
          line: {
            type: 'integer',
            description: '1-based line number in the NEW (head) file',
          },
          type: {
            type: 'string',
            enum: ['bug', 'security', 'risk', 'complexity', 'test-gap'],
          },
          severity: { type: 'string', enum: ['info', 'warn', 'high'] },
          title: { type: 'string', description: 'One-line summary' },
          body: { type: 'string', description: '1–3 sentence explanation' },
          guideline: {
            type: 'string',
            description: 'Optional: the reviewer guideline this reflects',
          },
        },
      },
    },
  },
};
