// Lifecycle controller — binds the pure resolver (lifecycle.ts) to the
// live data reads (viewer permission + repo merge config + viewer
// login) and the mutation surface, with cache invalidation + toasts in
// one place. Every lifecycle UI surface (status-pill menu, merge
// control) consumes this so the GitHub state machine lives in the pure
// module and the wiring lives here — components stay declarative.

import { useCallback, useMemo, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  convertPullRequestToDraft,
  deleteBranch,
  disablePullRequestAutoMerge,
  enablePullRequestAutoMerge,
  getViewer,
  markPullRequestReadyForReview,
  mergePullRequest,
  setPullRequestState,
  updatePullRequestBranch,
} from '../../github/client';
import {
  invalidatePrLists,
  repoMergeConfigOptions,
  viewerPermissionOptions,
} from '../../github/prQueries';
import {
  resolveLifecycleActions,
  type LifecycleActionKind,
  type MergeMethod,
  type RepoMergeConfig,
  type ResolvedLifecycle,
  type ViewerPermission,
} from '../../github/lifecycle';
import type { GHPullRequest } from '../../github/types';
import { track, Events, hashRepo } from '../../observability';

// Map a completed lifecycle action to a curated analytics event (ADR 0021).
// Repo is sent as a hash + PR number only — never the raw name. Visibility is
// omitted (the PR meta doesn't carry it) rather than mislabelled. Auto-merge /
// reviewer actions are tracked elsewhere; unmapped kinds are skipped.
function reportLifecycle(
  kind: LifecycleActionKind,
  owner: string | undefined,
  repo: string | undefined,
  prNumber: number | undefined,
): void {
  if (!owner || !repo) return;
  const props = { repo_hash: hashRepo(owner, repo), pr_number: prNumber };
  const stateActions: LifecycleActionKind[] = [
    'close',
    'reopen',
    'convertToDraft',
    'markReady',
  ];
  if (kind === 'merge') track(Events.PrMerged, props);
  if (kind === 'updateBranch') track(Events.BranchUpdated, props);
  if (stateActions.includes(kind))
    track(Events.PrStateChanged, { ...props, action: kind });
}

/** Conservative defaults while the cached reads resolve: no write
 * permission (so we never flash a control we'd later hide) and
 * GitHub's own merge defaults. */
const DEFAULT_REPO_CONFIG: RepoMergeConfig = {
  allowMergeCommit: true,
  allowSquashMerge: true,
  allowRebaseMerge: true,
  allowAutoMerge: false,
  deleteBranchOnMerge: false,
  // Empty until the repo read resolves — keeps the base-ref highlight from
  // flashing on before we actually know the default branch.
  defaultBranch: '',
};

export interface MergeOptions {
  method: MergeMethod;
  commitTitle?: string;
  commitMessage?: string;
  /** Delete the head branch after a successful merge — the merge
   * endpoint can't do this, so we follow up with a ref delete. */
  deleteBranch?: boolean;
}

export interface LifecycleController {
  resolved: ResolvedLifecycle;
  viewerLogin?: string;
  viewerPermission: ViewerPermission;
  repoConfig: RepoMergeConfig;
  /** Both cached reads have resolved — controls can render their full
   * action set without risk of a flash-then-hide. */
  ready: boolean;
  /** Which action is mid-flight (drives spinners / disabled state), or
   * null. */
  pending: LifecycleActionKind | null;
  close: () => Promise<void>;
  reopen: () => Promise<void>;
  convertToDraft: () => Promise<void>;
  markReady: () => Promise<void>;
  merge: (opts: MergeOptions) => Promise<void>;
  updateBranch: () => Promise<void>;
  enableAutoMerge: (method: MergeMethod) => Promise<void>;
  disableAutoMerge: () => Promise<void>;
}

const EMPTY_RESOLVED: ResolvedLifecycle = {
  actions: [],
  merge: null,
  conflict: false,
};

export function useLifecycle(
  pr: GHPullRequest | undefined,
  owner: string | undefined,
  repo: string | undefined,
  opts: { readOnly?: boolean } = {},
): LifecycleController {
  const readOnly = opts.readOnly ?? false;
  const queryClient = useQueryClient();
  const [pending, setPending] = useState<LifecycleActionKind | null>(null);
  // In read-only demo mode (AFK plan 22) we never offer a lifecycle
  // action, so skip the viewer / permission / merge-config reads
  // entirely — they'd 401/403 unauthenticated and add nothing.
  const enabled = !!(owner && repo) && !readOnly;

  const viewerQuery = useQuery({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: Infinity,
    enabled: !readOnly,
  });
  const permissionQuery = useQuery({
    ...viewerPermissionOptions(owner ?? '', repo ?? ''),
    enabled,
  });
  const mergeConfigQuery = useQuery({
    ...repoMergeConfigOptions(owner ?? '', repo ?? ''),
    enabled,
  });

  // Read-only forces a no-permission, no-identity state: every write
  // affordance derives from `viewerPermission` / `viewerLogin`, so
  // forcing NONE + undefined collapses the resolved action set to empty
  // (no merge, no close, no reviewer mgmt, no edit pencil).
  const viewerLogin = readOnly ? undefined : viewerQuery.data?.login;
  const viewerPermission: ViewerPermission = readOnly
    ? 'NONE'
    : permissionQuery.data ?? 'NONE';
  const repoConfig = mergeConfigQuery.data ?? DEFAULT_REPO_CONFIG;
  const ready = readOnly
    ? true
    : permissionQuery.isSuccess && mergeConfigQuery.isSuccess;

  const resolved = useMemo(
    () =>
      pr
        ? resolveLifecycleActions(
            {
              state: pr.state,
              draft: pr.draft,
              merged: pr.merged_at != null,
              mergeable: pr.mergeable,
              mergeableState: pr.mergeable_state,
              authorLogin: pr.user.login,
              autoMergeEnabled: pr.auto_merge != null,
            },
            repoConfig,
            viewerPermission,
            viewerLogin ?? '',
          )
        : EMPTY_RESOLVED,
    [pr, repoConfig, viewerPermission, viewerLogin],
  );

  // After any state change, refetch the PR meta (and the reviews /
  // checks that hang off the same ['pr', owner, repo, number] prefix)
  // so the header reflects the new state immediately — plus the PR-list
  // lenses, since merge / close / reopen / ready / draft all change a
  // PR's list membership or state chip and those lists live under a
  // separate ['lens', …] query the prefix above doesn't reach.
  const invalidate = useCallback(() => {
    return Promise.all([
      queryClient.invalidateQueries({
        queryKey: ['pr', owner, repo, pr?.number],
      }),
      invalidatePrLists(queryClient),
    ]);
  }, [queryClient, owner, repo, pr?.number]);

  const run = useMutation({
    mutationFn: async (job: {
      kind: LifecycleActionKind;
      fn: () => Promise<unknown>;
      success: string;
    }) => {
      setPending(job.kind);
      try {
        await job.fn();
      } finally {
        setPending(null);
      }
      return job.success;
    },
    onSuccess: async (success, job) => {
      reportLifecycle(job.kind, owner, repo, pr?.number);
      await invalidate();
      toast.success(success);
    },
    onError: (err) => {
      toast.error(
        err instanceof Error ? err.message : 'Action failed — please retry',
      );
    },
  });

  const exec = useCallback(
    (kind: LifecycleActionKind, fn: () => Promise<unknown>, success: string) => {
      if (!enabled || !pr) return Promise.resolve();
      return run.mutateAsync({ kind, fn, success }).then(() => undefined);
    },
    [run, enabled, pr],
  );

  return {
    resolved,
    viewerLogin,
    viewerPermission,
    repoConfig,
    ready,
    pending,
    close: () =>
      exec(
        'close',
        () => setPullRequestState(owner!, repo!, pr!.number, 'closed'),
        'Pull request closed',
      ),
    reopen: () =>
      exec(
        'reopen',
        () => setPullRequestState(owner!, repo!, pr!.number, 'open'),
        'Pull request reopened',
      ),
    convertToDraft: () =>
      exec(
        'convertToDraft',
        () => convertPullRequestToDraft(owner!, repo!, pr!.number),
        'Converted to draft',
      ),
    markReady: () =>
      exec(
        'markReady',
        () => markPullRequestReadyForReview(owner!, repo!, pr!.number),
        'Marked ready for review',
      ),
    merge: (opts) =>
      exec(
        'merge',
        async () => {
          await mergePullRequest(owner!, repo!, pr!.number, opts);
          // GitHub's PR-meta GET can still report the PR open for a beat
          // after a successful merge, so the invalidate() below may
          // refetch stale data. Optimistically flip the cached meta to
          // merged so the header pill, status menu, and merge box all
          // update the instant the merge returns; the refetch reconciles.
          queryClient.setQueryData<GHPullRequest>(
            ['pr', owner, repo, pr!.number, 'meta'],
            (old) =>
              old
                ? { ...old, state: 'closed', merged_at: new Date().toISOString() }
                : old,
          );
          if (opts.deleteBranch) {
            // Best-effort: a failed branch delete shouldn't surface as a
            // merge failure (the merge already landed).
            try {
              await deleteBranch(owner!, repo!, pr!.head.ref);
            } catch {
              /* branch already gone or protected — ignore */
            }
          }
        },
        'Pull request merged',
      ),
    updateBranch: () =>
      exec(
        'updateBranch',
        () => updatePullRequestBranch(owner!, repo!, pr!.number),
        'Branch update started',
      ),
    enableAutoMerge: (method) =>
      exec(
        'enableAutoMerge',
        () => enablePullRequestAutoMerge(owner!, repo!, pr!.number, method),
        'Auto-merge enabled',
      ),
    disableAutoMerge: () =>
      exec(
        'disableAutoMerge',
        () => disablePullRequestAutoMerge(owner!, repo!, pr!.number),
        'Auto-merge disabled',
      ),
  };
}
