// Inline composer for authoring a new line comment from the diff.
// Opened by clicking the "+" gutter affordance on a hovered diff line.
// "Start a review" (or "Add review comment" once a pending review
// exists) adds the comment to the viewer's GitHub pending review — it
// renders inline optimistically (badged Pending) and publishes with the
// rest of the batch on submit (ADR 0019). Cancel just closes.
//
// Design parity: gh-comments.jsx · GhComposer — the same rich
// Write/Preview composer the thread reply + edit flows use, prefixed
// with a compact anchor label (line/range + "Pending" badge) so the
// reviewer knows what the comment will attach to.

import { PlusIcon } from 'lucide-react';
import { getFiletypeFromFileName } from '@pierre/diffs';
import { useQuery } from '@tanstack/react-query';
import { Badge } from '@/components/ui/badge';
import type { ComposerSpec } from '../../github/buildDiff';
import type { DraftActions } from '../../review/reviewDraftTypes';
import { prPendingReviewOptions } from '../../github/prQueries';
import { GhComposer } from '../conversation/GhComposer';
import {
  OfflineComposerNotice,
  useComposerOffline,
} from '../conversation/OfflineComposerNotice';
import { useSingleComment } from '../usePendingReview';
import { useGithubAssetsUploader } from '../conversation/composer/useGithubAssetsUploader';

interface Props {
  spec: ComposerSpec;
  draftActions: DraftActions;
  viewerLogin?: string;
  /** PR coordinates for `@`/`#` autocomplete (threaded from LiveDiffPane). */
  owner?: string;
  repo?: string;
  number?: number;
  /** Text of the commented diff line(s) — pre-fills `/suggestion`. */
  suggestionSeed?: string;
  /** Pre-fill the composer body — used by "Draft a comment from this hint"
   * (ADR 0026). Ignored if a saved draft exists for this line. */
  initialBody?: string;
  onClose: () => void;
}

export function NewCommentComposer({
  spec,
  draftActions,
  viewerLogin,
  owner,
  repo,
  number,
  suggestionSeed,
  initialBody,
  onClose,
}: Props) {
  void viewerLogin; // composer no longer renders an avatar
  const uploadImage = useGithubAssetsUploader();
  const offline = useComposerOffline();
  const isRange =
    spec.startLine !== undefined && spec.startLine !== spec.line;

  // Whether the viewer already has a pending review — picks github.com's
  // "Start a review" (none yet) vs "Add review comment" (in progress)
  // wording. Reads the cached query; no extra request.
  const pendingQuery = useQuery({
    ...prPendingReviewOptions(owner ?? '', repo ?? '', number ?? 0),
    enabled: !!owner && !!repo && !!number,
  });
  const hasPendingReview = !!pendingQuery.data;
  const single = useSingleComment(owner ?? '', repo ?? '', number ?? 0);

  const save = (body: string) => {
    if (!body.trim()) return;
    draftActions.addLineComment({
      path: spec.path,
      line: spec.line,
      startLine: isRange ? spec.startLine : undefined,
      side: spec.side,
      body,
    });
    onClose();
  };

  // "Add single comment" — publish immediately (no pending review).
  // github.com only offers it when no review is in progress (you can't
  // single-publish a line while a pending review exists — it 422s), so
  // we hide it once a pending review is open.
  const publishSingle = (body: string) => {
    if (!body.trim()) return;
    single.mutate({
      kind: 'line',
      path: spec.path,
      line: spec.line,
      startLine: isRange ? spec.startLine : undefined,
      side: spec.side,
      body,
    });
    onClose();
  };

  // Offline → no authoring (the in-progress review is server-held).
  if (offline) {
    return (
      <div className="font-sans whitespace-normal">
        <OfflineComposerNotice onCancel={onClose} />
      </div>
    );
  }

  return (
    // font-sans + whitespace-normal: this composer mounts inside the
    // @pierre/diffs CodeView (mono + pre-wrap), so reset the context's code
    // styles on the label row too (GhComposer resets its own).
    <div className="mx-3 mb-3 mt-1.5 box-border max-w-full font-sans whitespace-normal">
      <div className="mb-1.5 flex items-center gap-2 px-0.5 text-[11.5px] text-foreground">
        <PlusIcon className="size-[12px] text-primary" />
        <span className="font-semibold">
          New {isRange ? 'range' : 'line'} comment
        </span>
        <span className="text-muted-foreground">
          ·{' '}
          {isRange ? (
            <>
              lines{' '}
              <b className="font-mono text-foreground">
                {spec.startLine}–{spec.line}
              </b>
            </>
          ) : (
            <>
              line <b className="font-mono text-foreground">{spec.line}</b>
            </>
          )}
        </span>
        <Badge
          variant="outline"
          className="border-pyor-warn/40 font-semibold text-pyor-warn"
        >
          Pending
        </Badge>
      </div>
      <GhComposer
        draftKey={
          owner && repo
            ? `${owner}/${repo}/${number}:line:${spec.side}:${spec.path}:${spec.startLine ?? spec.line}-${spec.line}`
            : undefined
        }
        placeholder="Comment…"
        initialBody={initialBody}
        submitLabel={hasPendingReview ? 'Add review comment' : 'Start a review'}
        submitIcon="check"
        autoFocus
        minHeight={84}
        threadCompose
        onUploadImage={uploadImage}
        mentionContext={owner && repo ? { owner, repo, number } : undefined}
        suggestionSeed={suggestionSeed}
        fileLang={getFiletypeFromFileName(spec.path)}
        onCancel={onClose}
        onSubmit={save}
        secondaryAction={
          hasPendingReview
            ? undefined
            : { label: 'Add single comment', onClick: publishSingle }
        }
      />
    </div>
  );
}
