// Extract the original line(s) that a ```suggestion block replaces, so
// the composer + comment renderers can show a real before→after diff
// (ADR 0018 follow-up) instead of a green box with only the new code.
//
// A GitHub review comment carries a `diff_hunk` — a unified-diff excerpt
// ending at the anchored line — plus the anchored line number(s) on a
// side. The baseline of a suggestion is exactly those line(s). The hunk
// is numbered against the commit the comment was made on, which matches
// the comment's `original_line` / `original_start_line` (not the live
// `line`, which drifts as the file changes around it).

// Advance the old/new line counters for one unified-diff line and decide
// whether that line contributes to the baseline on `side` within [lo, hi].
function hunkLineStep(
  raw: string,
  oldNo: number,
  newNo: number,
  side: 'LEFT' | 'RIGHT',
  lo: number,
  hi: number,
): { oldNo: number; newNo: number; emit?: string } {
  const header = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(raw);
  if (header) return { oldNo: Number(header[1]), newNo: Number(header[2]) };
  if (raw.length === 0) return { oldNo, newNo };
  const content = raw.slice(1);
  const inRange = (n: number) => n >= lo && n <= hi;
  switch (raw[0]) {
    case ' ': {
      const n = side === 'LEFT' ? oldNo : newNo;
      return {
        oldNo: oldNo + 1,
        newNo: newNo + 1,
        emit: inRange(n) ? content : undefined,
      };
    }
    case '+':
      return {
        oldNo,
        newNo: newNo + 1,
        emit: side === 'RIGHT' && inRange(newNo) ? content : undefined,
      };
    case '-':
      return {
        oldNo: oldNo + 1,
        newNo,
        emit: side === 'LEFT' && inRange(oldNo) ? content : undefined,
      };
    default:
      // '\' (no-newline-at-eof) and any other markers carry no line number.
      return { oldNo, newNo };
  }
}

/**
 * Resolve the text of lines `[startLine, endLine]` on `side` from a
 * unified `diff_hunk`. Returns the joined line text (no +/-/space
 * prefixes), or undefined when the hunk/line info is missing or no line
 * matches. Handles single-line and multi-line (range) suggestions.
 */
export function baselineFromHunk(
  diffHunk: string | null | undefined,
  side: 'LEFT' | 'RIGHT',
  startLine: number | null | undefined,
  endLine: number | null | undefined,
): string | undefined {
  if (!diffHunk) return undefined;
  const end = endLine ?? startLine;
  if (end == null) return undefined;
  const start = startLine ?? end;
  const lo = Math.min(start, end);
  const hi = Math.max(start, end);

  let oldNo = 0;
  let newNo = 0;
  const out: string[] = [];
  diffHunk.split('\n').forEach((raw) => {
    const step = hunkLineStep(raw, oldNo, newNo, side, lo, hi);
    oldNo = step.oldNo;
    newNo = step.newNo;
    if (step.emit !== undefined) out.push(step.emit);
  });
  return out.length > 0 ? out.join('\n') : undefined;
}
