// Shared tab strip for the Pull-requests screen — My PRs · Reviewing ·
// Team. All three tabs render this same bar (tabs left, search + date
// range right) so switching tabs is seamless — same controls, same spot.

import { EyeIcon, UserIcon, UsersIcon } from 'lucide-react';
import { UnderlineTabs } from '../ui/UnderlineTabs';
import { Icon } from '../ui/Icon';
import { Kbd } from '../ui/Kbd';
import { Button } from '@/components/ui/button';
import { DateRangeChip, type DateRangePreset } from '../ui/DateRangeChip';

export type PullsTabId = 'mine' | 'reviewing' | 'team';

export function PullsTabsBar({
  active,
  onSelect,
  searchQuery,
  setSearchQuery,
  searchRef,
  dateRange,
  setDateRange,
}: {
  active: PullsTabId;
  onSelect: (id: PullsTabId) => void;
  searchQuery: string;
  setSearchQuery: (q: string) => void;
  searchRef?: React.RefObject<HTMLInputElement | null>;
  dateRange: DateRangePreset;
  setDateRange: (p: DateRangePreset) => void;
}) {
  return (
    <UnderlineTabs
      tabs={[
        { id: 'mine', label: 'My PRs', icon: UserIcon },
        { id: 'reviewing', label: 'Reviewing', icon: EyeIcon },
        { id: 'team', label: 'Team', icon: UsersIcon },
      ]}
      active={active}
      onChange={onSelect}
      right={
        <>
          <div className="flex h-7 w-72 items-center gap-1.5 rounded-md border border-border bg-background px-2.5 lg:w-80">
            <span className="text-muted-foreground">
              <Icon name="search" size={12} />
            </span>
            <input
              ref={searchRef}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Filter PRs · title, repo, author, label…"
              className="min-w-0 flex-1 border-none bg-transparent text-[12px] text-foreground outline-none placeholder:text-muted-foreground"
            />
            {searchQuery ? (
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setSearchQuery('')}
                title="Clear filter"
                aria-label="Clear filter"
                className="size-4 text-muted-foreground [&_svg]:size-3"
              >
                <Icon name="x-circle" size={12} />
              </Button>
            ) : (
              <Kbd className="px-1">⌘F</Kbd>
            )}
          </div>
          <DateRangeChip value={dateRange} onChange={setDateRange} />
        </>
      }
    />
  );
}
