// Reconnect state shown in place of a comment composer while offline
// (ADR 0019). The in-progress review is server-held, so authoring
// requires connectivity — there is no offline outbox. Reading cached
// comments still works; only the write surface is gated. Re-enables
// automatically on reconnect (useConnectivity is reactive), no reload.

import { WifiOffIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useConnectivity } from '../../ui/connectivity/useConnectivity';

/** True while the browser reports no network — the one state in which we
 * disable comment authoring. Server outages (github-down) still let the
 * optimistic mutation fire and surface their own toast on failure. */
export function useComposerOffline(): boolean {
  return useConnectivity().status === 'offline';
}

export function OfflineComposerNotice({
  onCancel,
  variant = 'block',
}: {
  onCancel?: () => void;
  /** 'block' fills the composer slot; 'inline' is the compact reply pill. */
  variant?: 'block' | 'inline';
}) {
  return (
    <div
      className={
        variant === 'inline'
          ? 'inline-flex items-center gap-1.5 rounded-md border border-dashed bg-muted/20 px-2.5 py-1 text-[12px] text-muted-foreground'
          : 'mx-3 mb-3 mt-1.5 flex items-center gap-2 rounded-lg border border-dashed bg-muted/20 px-3 py-2.5 text-[12.5px] text-muted-foreground'
      }
    >
      <WifiOffIcon className="size-3.5 shrink-0" />
      <span>Reconnect to comment — you’re offline.</span>
      {onCancel && variant === 'block' && (
        <Button
          variant="ghost"
          size="sm"
          className="ml-auto h-6 px-2 text-[11.5px]"
          onClick={onCancel}
        >
          Cancel
        </Button>
      )}
    </div>
  );
}
