// SVG icon library. Ported from chrome.jsx's Icon component.
// All icons live on a 16x16 viewBox, rendered as stroke-only by default
// (fills only where explicitly noted, e.g. filled circles for status dots).

import type { CSSProperties } from 'react';

export type IconName =
  | 'pr-open'
  | 'pr-draft'
  | 'pr-merged'
  | 'pr-closed'
  | 'check'
  | 'x'
  | 'dot'
  | 'clock'
  | 'comment'
  | 'comment-fill'
  | 'eye'
  | 'eye-off'
  | 'file'
  | 'folder'
  | 'folder-open'
  | 'chevron-right'
  | 'chevron-down'
  | 'chevron-up'
  | 'chevron-left'
  | 'search'
  | 'refresh'
  | 'filter'
  | 'plus'
  | 'external'
  | 'kebab'
  | 'list'
  | 'tree'
  | 'split'
  | 'inline'
  | 'arrow-up'
  | 'arrow-down'
  | 'arrow-up-line'
  | 'arrow-down-line'
  | 'trash'
  | 'sliders'
  | 'commit'
  | 'branch'
  | 'check-circle'
  | 'x-circle'
  | 'dot-circle'
  | 'lock'
  | 'key'
  | 'warning'
  | 'info'
  | 'reload'
  | 'gear';

interface Props {
  name: IconName;
  size?: number;
  color?: string;
  strokeWidth?: number;
  style?: CSSProperties;
}

export function Icon({
  name,
  size = 14,
  color = 'currentColor',
  strokeWidth = 1.5,
  style,
}: Props) {
  const common = {
    width: size,
    height: size,
    viewBox: '0 0 16 16',
    fill: 'none' as const,
    stroke: color,
    strokeWidth,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    style,
  };
  switch (name) {
    case 'pr-open':
      return (
        <svg {...common}>
          <circle cx="5" cy="4" r="1.6" fill={color} />
          <circle cx="5" cy="12" r="1.6" fill={color} />
          <circle cx="11" cy="12" r="1.6" fill={color} />
          <path d="M5 5.6V10.4M5 5.6c0 3 3 3 6 3v1.8" />
        </svg>
      );
    case 'pr-draft':
      return (
        <svg {...common}>
          <circle cx="5" cy="4" r="1.6" />
          <circle cx="5" cy="12" r="1.6" />
          <circle cx="11" cy="12" r="1.6" />
          <path
            d="M5 5.6V10.4M5 5.6c0 3 3 3 6 3v1.8"
            strokeDasharray="1.5 1.5"
          />
        </svg>
      );
    case 'pr-merged':
      return (
        <svg {...common}>
          <circle cx="5" cy="4" r="1.6" fill={color} />
          <circle cx="11" cy="12" r="1.6" fill={color} />
          <path d="M5 5.6V12M5 12c0-3 3-3 6-3V10.4" />
        </svg>
      );
    case 'pr-closed':
      return (
        <svg {...common}>
          <circle cx="5" cy="4" r="1.6" fill={color} />
          <circle cx="11" cy="12" r="1.6" fill={color} />
          <path d="M5 5.6V12M11 5l-3 3M8 5l3 3" />
        </svg>
      );
    case 'check':
      return (
        <svg {...common}>
          <path d="M3 8.5l3 3 7-7" />
        </svg>
      );
    case 'x':
      return (
        <svg {...common}>
          <path d="M3.5 3.5l9 9M12.5 3.5l-9 9" />
        </svg>
      );
    case 'dot':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="3" fill={color} stroke="none" />
        </svg>
      );
    case 'clock':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="5.5" />
          <path d="M8 5v3l2 1.5" />
        </svg>
      );
    case 'comment':
      return (
        <svg {...common}>
          <path d="M2.5 3.5h11v7h-5l-3 2.5v-2.5h-3z" />
        </svg>
      );
    case 'comment-fill':
      return (
        <svg {...common} fill={color} stroke="none">
          <path d="M2.5 3.5h11v7h-5l-3 2.5v-2.5h-3z" />
        </svg>
      );
    case 'eye':
      return (
        <svg {...common}>
          <path d="M1.5 8s2.5-4 6.5-4 6.5 4 6.5 4-2.5 4-6.5 4-6.5-4-6.5-4z" />
          <circle cx="8" cy="8" r="1.5" />
        </svg>
      );
    case 'eye-off':
      return (
        <svg {...common}>
          <path d="M2.5 4.5s2 3.5 5.5 3.5 5.5-3.5 5.5-3.5M5 8.5l-1.5 2M11 8.5l1.5 2M8 9.5V12" />
        </svg>
      );
    case 'file':
      return (
        <svg {...common}>
          <path d="M3.5 1.5h6L13 5v9.5H3.5z" />
          <path d="M9.5 1.5V5H13" />
        </svg>
      );
    case 'folder':
      return (
        <svg {...common}>
          <path d="M1.5 4.5L3 3h3.5l1.5 1.5h6V13H1.5z" />
        </svg>
      );
    case 'folder-open':
      return (
        <svg {...common}>
          <path d="M1.5 4.5L3 3h3.5l1.5 1.5h6V6H1.5z" />
          <path d="M1.5 6L3 13h11l1.5-7z" />
        </svg>
      );
    case 'chevron-right':
      return (
        <svg {...common}>
          <path d="M6 3.5L10.5 8 6 12.5" />
        </svg>
      );
    case 'chevron-down':
      return (
        <svg {...common}>
          <path d="M3.5 6L8 10.5 12.5 6" />
        </svg>
      );
    case 'chevron-up':
      return (
        <svg {...common}>
          <path d="M3.5 10L8 5.5 12.5 10" />
        </svg>
      );
    case 'chevron-left':
      return (
        <svg {...common}>
          <path d="M10 3.5L5.5 8 10 12.5" />
        </svg>
      );
    case 'search':
      return (
        <svg {...common}>
          <circle cx="7" cy="7" r="4.5" />
          <path d="M10.5 10.5L14 14" />
        </svg>
      );
    case 'refresh':
      return (
        <svg {...common}>
          <path d="M13.5 3.5v3h-3M2.5 12.5v-3h3M13.2 7a5.5 5.5 0 00-10.4-1M2.8 9a5.5 5.5 0 0010.4 1" />
        </svg>
      );
    case 'filter':
      return (
        <svg {...common}>
          <path d="M2 3.5h12L9.5 9v4l-3-1V9z" />
        </svg>
      );
    case 'plus':
      return (
        <svg {...common}>
          <path d="M8 3v10M3 8h10" />
        </svg>
      );
    case 'external':
      return (
        <svg {...common}>
          <path d="M9 2.5h4.5V7M13 3l-6 6M11 9v3.5H3.5V5H7" />
        </svg>
      );
    case 'kebab':
      return (
        <svg {...common}>
          <circle cx="8" cy="3.5" r="0.9" fill={color} stroke="none" />
          <circle cx="8" cy="8" r="0.9" fill={color} stroke="none" />
          <circle cx="8" cy="12.5" r="0.9" fill={color} stroke="none" />
        </svg>
      );
    case 'list':
      return (
        <svg {...common}>
          <path d="M2 4h12M2 8h12M2 12h12" />
        </svg>
      );
    case 'tree':
      return (
        <svg {...common}>
          <path d="M3 3h4v3H3zM9 7h4v3H9zM9 11h4v3H9zM5 6v8M5 9h4M5 13h4" />
        </svg>
      );
    case 'split':
      return (
        <svg {...common}>
          <rect x="2" y="3" width="5.5" height="10" rx="1" />
          <rect x="8.5" y="3" width="5.5" height="10" rx="1" />
        </svg>
      );
    case 'inline':
      return (
        <svg {...common}>
          <rect x="2" y="3" width="12" height="10" rx="1" />
          <path d="M2 8h12" />
        </svg>
      );
    case 'arrow-up':
      return (
        <svg {...common}>
          <path d="M8 13V3M3.5 7.5L8 3l4.5 4.5" />
        </svg>
      );
    case 'arrow-down':
      return (
        <svg {...common}>
          <path d="M8 3v10M3.5 8.5L8 13l4.5-4.5" />
        </svg>
      );
    case 'arrow-up-line':
      return (
        <svg {...common}>
          <path d="M2 13.5h12M8 11V3M4.5 6.5L8 3l3.5 3.5" />
        </svg>
      );
    case 'arrow-down-line':
      return (
        <svg {...common}>
          <path d="M2 2.5h12M8 5v8M4.5 9.5L8 13l3.5-3.5" />
        </svg>
      );
    case 'trash':
      return (
        <svg {...common}>
          <path d="M2.5 4h11M6 4V2.5h4V4M4 4l.5 9.5h7L12 4M6.5 6.5v5M9.5 6.5v5" />
        </svg>
      );
    case 'sliders':
      return (
        <svg {...common}>
          <path d="M2 4h6M11 4h3M2 8h2M7 8h7M2 12h9M14 12h0" />
          <circle cx="9.5" cy="4" r="1.5" fill={color} />
          <circle cx="5.5" cy="8" r="1.5" fill={color} />
          <circle cx="12.5" cy="12" r="1.5" fill={color} />
        </svg>
      );
    case 'commit':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="3" />
          <path d="M2 8h3M11 8h3" />
        </svg>
      );
    case 'branch':
      return (
        <svg {...common}>
          <circle cx="4" cy="3" r="1.6" />
          <circle cx="4" cy="13" r="1.6" />
          <circle cx="12" cy="6" r="1.6" />
          <path d="M4 4.6v6.8M4 8h4a4 4 0 004-4v0" />
        </svg>
      );
    case 'check-circle':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="6" fill={color} stroke="none" />
          <path d="M5 8l2.5 2.5L11 6.5" stroke="white" />
        </svg>
      );
    case 'x-circle':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="6" fill={color} stroke="none" />
          <path d="M5.5 5.5l5 5M10.5 5.5l-5 5" stroke="white" />
        </svg>
      );
    case 'dot-circle':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="6" fill={color} stroke="none" />
          <circle cx="8" cy="8" r="1.5" fill="white" stroke="none" />
        </svg>
      );
    case 'lock':
      return (
        <svg {...common}>
          <rect x="3" y="7" width="10" height="7" rx="1.5" />
          <path d="M5 7V5a3 3 0 016 0v2" />
        </svg>
      );
    case 'key':
      return (
        <svg {...common}>
          <circle cx="5" cy="11" r="2.5" />
          <path d="M6.8 9.2l5.7-5.7M10.5 5.5l2 2M12 4l1.5 1.5" />
        </svg>
      );
    case 'warning':
      return (
        <svg {...common}>
          <path d="M8 2.5l6 11H2z" />
          <path d="M8 7v3M8 12v.5" />
        </svg>
      );
    case 'info':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="6" />
          <path d="M8 7.5v3.5M8 5.5v.5" />
        </svg>
      );
    case 'reload':
      return (
        <svg {...common}>
          <path d="M3 8a5 5 0 019-3M13 8a5 5 0 01-9 3" />
          <path d="M11 2v3h-3M5 14v-3h3" />
        </svg>
      );
    case 'gear':
      return (
        <svg {...common}>
          <circle cx="8" cy="8" r="2.2" />
          <path d="M8 1.5v2M8 12.5v2M1.5 8h2M12.5 8h2M3.4 3.4l1.4 1.4M11.2 11.2l1.4 1.4M3.4 12.6l1.4-1.4M11.2 4.8l1.4-1.4" />
        </svg>
      );
  }
}
