// The PR status pill, as a menu — and the quick-access twin of the
// merge box (the box lives at the foot of the Conversation tab; PR #32
// removed the header's inline merge split-button and left this chip as
// the lightweight twin). The "Open" chip carries:
//   - a status one-liner (ready / blocked) mirroring the box header,
//   - a primary merge action that merges directly with the same method
//     the box would use (the viewer's sticky pick, reconciled to the
//     repo-allowed methods); the box stays the home of the method
//     picker, reachable via "Jump to merge box" for anyone who wants to
//     choose a different one,
//   - the lifecycle change-status actions (close / reopen / draft),
//   - update-branch when behind,
//   - and an explicit "Jump to merge box".
// Same summary-of-the-other discipline: the chip reads as PR state; the
// box stays the full-detail home. Every transition confirms through the
// shared ConfirmModal.

import { useRef, useState } from 'react';
import {
  AlertTriangleIcon,
  ArrowDownIcon,
  CheckCircle2Icon,
  ChevronDownIcon,
  GitMergeIcon,
  GitPullRequestDraftIcon,
  GitPullRequestIcon,
  Loader2,
  RefreshCwIcon,
  XCircleIcon,
  type LucideProps,
} from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { ConfirmModal, type ConfirmModalProps } from './ConfirmModal';
import { findAction, type LifecycleActionKind, type MergeMethod } from '../../github/lifecycle';
import type { LifecycleController } from './useLifecycle';
import type { GHPullRequest } from '../../github/types';
import { relTime, fullDate } from '../../util/relTime';
import {
  readStoredMergeMethod,
  reconcileMergeMethod,
} from '../../util/mergeMethodStore';
import type { ComponentType } from 'react';

type PillStatus = 'open' | 'merged' | 'draft' | 'closed';

/** One-line merge readiness summary surfaced in the condensed menu. */
export interface MergeSummary {
  ready: boolean;
  line: string;
}

const MERGE_LABEL: Record<MergeMethod, string> = {
  merge: 'Create a merge commit',
  squash: 'Squash and merge',
  rebase: 'Rebase and merge',
};

const PILL: Record<
  PillStatus,
  { Icon: ComponentType<LucideProps>; label: string; className: string }
> = {
  open: {
    Icon: GitPullRequestIcon,
    label: 'Open',
    className:
      'border-emerald-600/30 bg-emerald-600 text-white hover:bg-emerald-600/90',
  },
  draft: {
    Icon: GitPullRequestDraftIcon,
    label: 'Draft',
    className: 'border-border bg-secondary text-secondary-foreground hover:bg-secondary/80',
  },
  merged: {
    Icon: GitMergeIcon,
    label: 'Merged',
    className:
      'border-violet-600/30 bg-violet-600 text-white hover:bg-violet-600/90',
  },
  closed: {
    Icon: XCircleIcon,
    label: 'Closed',
    className:
      'border-destructive/30 bg-destructive text-destructive-foreground hover:bg-destructive/90',
  },
};

/** Confirm-modal copy per draft/close/reopen transition. */
type ConfirmKind = Extract<
  LifecycleActionKind,
  'close' | 'reopen' | 'convertToDraft' | 'markReady'
>;

const CONFIRM_COPY: Record<
  ConfirmKind,
  Pick<
    ConfirmModalProps,
    'title' | 'description' | 'tone' | 'confirmLabel' | 'confirmIcon' | 'icon'
  >
> = {
  close: {
    title: 'Close this pull request?',
    description:
      'The branch will not be merged. You can reopen this pull request later — comments and reviews are preserved.',
    tone: 'destructive',
    confirmLabel: 'Close pull request',
    confirmIcon: XCircleIcon,
    icon: XCircleIcon,
  },
  reopen: {
    title: 'Reopen this pull request?',
    description:
      'This moves the pull request back to open so it can be reviewed and merged again.',
    tone: 'neutral',
    confirmLabel: 'Reopen pull request',
    confirmIcon: GitPullRequestIcon,
    icon: GitPullRequestIcon,
  },
  convertToDraft: {
    title: 'Convert to draft?',
    description:
      "Draft pull requests can't be merged, and reviewers are signalled that it's not yet ready for review.",
    tone: 'neutral',
    confirmLabel: 'Convert to draft',
    confirmIcon: GitPullRequestDraftIcon,
    icon: GitPullRequestDraftIcon,
  },
  markReady: {
    title: 'Mark ready for review?',
    description:
      'Reviewers will be notified that this pull request is ready for review.',
    tone: 'neutral',
    confirmLabel: 'Mark ready for review',
    confirmIcon: CheckCircle2Icon,
    icon: CheckCircle2Icon,
  },
};

export function StatusPillMenu({
  status,
  lifecycle,
  pr,
  mergeSummary,
  onJumpToMergeBox,
}: {
  status: PillStatus;
  lifecycle: LifecycleController;
  /** Live PR — needed for the update-branch confirm copy. */
  pr?: GHPullRequest;
  /** One-line readiness summary; absent when the PR isn't open. */
  mergeSummary?: MergeSummary;
  /** Switches to the Conversation tab and scrolls to the full merge
   * box. The condensed menu's primary merge action + "Jump to merge
   * box" both route here — the box is the single merge surface. */
  onJumpToMergeBox?: () => void;
}) {
  const [confirm, setConfirm] = useState<ConfirmKind | null>(null);
  const [confirmUpdate, setConfirmUpdate] = useState(false);
  // Retain the last kind so the ConfirmModal stays mounted (with its
  // copy intact) while it animates closed — otherwise unmounting on
  // `setConfirm(null)` tears it out before the exit animation plays.
  const lastConfirmRef = useRef<ConfirmKind | null>(null);
  if (confirm) lastConfirmRef.current = confirm;
  const confirmKind = confirm ?? lastConfirmRef.current;
  const cfg = PILL[status];
  const Icon = cfg.Icon;

  const close = findAction(lifecycle.resolved, 'close');
  const reopen = findAction(lifecycle.resolved, 'reopen');
  const toDraft = findAction(lifecycle.resolved, 'convertToDraft');
  const markReady = findAction(lifecycle.resolved, 'markReady');
  const updateBranch = findAction(lifecycle.resolved, 'updateBranch');

  // The condensed merge surface shows when the PR is open (we have a
  // summary). Even a read-only viewer sees the summary + "jump to box".
  const showMerge = status === 'open' && !!mergeSummary;
  const hasStatusActions = !!(close || reopen || toDraft || markReady);
  // Terminal states (merged / closed) have no merge surface and usually
  // no status actions, which left the dropdown showing nothing but a
  // stray "Jump to merge box". Render a one-line outcome summary instead
  // so the menu is never empty.
  const isTerminal = status === 'merged' || status === 'closed';
  const showTerminal = isTerminal && !!pr;
  const hasMenu = hasStatusActions || showMerge || showTerminal || !!onJumpToMergeBox;
  // Whether anything renders above the "Jump to merge box" item — drives
  // its leading separator so it doesn't float alone under an empty menu.
  const hasContentAboveJump =
    showMerge || showTerminal || hasStatusActions || !!updateBranch;

  const pillInner = (
    <>
      <Icon className="size-3" />
      <span>{cfg.label}</span>
      {hasMenu && <ChevronDownIcon className="-mr-0.5 size-3 opacity-70" />}
    </>
  );
  const pillClass = `inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[11px] font-medium transition-colors ${cfg.className}`;

  // Merged (or no actions + no summary, e.g. read-only on a closed PR) →
  // static pill.
  if (!hasMenu) {
    return <span className={pillClass}>{pillInner}</span>;
  }

  const runConfirm = () => {
    if (!confirm) return;
    const action = {
      close: lifecycle.close,
      reopen: lifecycle.reopen,
      convertToDraft: lifecycle.convertToDraft,
      markReady: lifecycle.markReady,
    }[confirm];
    void action().then(() => setConfirm(null));
  };

  const ready = !!mergeSummary?.ready;
  // Mirror the merge box: the viewer's sticky pick reconciled against the
  // repo-allowed methods (else the repo default, else `merge`). So the
  // popup's one-click button merges with exactly what the box would.
  const method: MergeMethod = reconcileMergeMethod(
    readStoredMergeMethod(),
    lifecycle.resolved.merge?.methods ?? [],
  );
  const merging = lifecycle.pending === 'merge';

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button type="button" className={pillClass} aria-label="Pull request status & actions">
            {pillInner}
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-[304px]">
          {/* Terminal outcome (merged / closed) — keeps the menu from
              rendering empty once the PR can no longer be merged. */}
          {showTerminal && pr && (
            <div className="mb-1 flex items-start gap-2 rounded-md bg-muted/60 px-2 py-2">
              {status === 'merged' ? (
                <GitMergeIcon className="mt-0.5 size-4 shrink-0 text-violet-600 dark:text-violet-400" />
              ) : (
                <XCircleIcon className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
              )}
              <div className="min-w-0">
                <div className="text-[12.5px] font-semibold text-foreground">
                  {status === 'merged' ? 'Merged' : 'Closed without merging'}
                </div>
                <div
                  className="text-[11px] leading-snug text-muted-foreground"
                  title={status === 'merged' ? fullDate(pr.merged_at) : undefined}
                >
                  {status === 'merged'
                    ? `${pr.merged_at ? `${relTime(pr.merged_at)} · ` : ''}into ${pr.base.ref}`
                    : `Not merged into ${pr.base.ref}`}
                </div>
              </div>
            </div>
          )}

          {/* Status summary — mirrors the merge box's header strip. */}
          {showMerge && mergeSummary && (
            <div
              className={`mb-1 flex items-start gap-2 rounded-md px-2 py-2 ${
                ready
                  ? 'bg-emerald-50/70 dark:bg-emerald-950/30'
                  : 'bg-amber-50/70 dark:bg-amber-950/30'
              }`}
            >
              {ready ? (
                <CheckCircle2Icon className="mt-0.5 size-4 shrink-0 text-emerald-600 dark:text-emerald-400" />
              ) : (
                <AlertTriangleIcon className="mt-0.5 size-4 shrink-0 text-amber-600 dark:text-amber-400" />
              )}
              <div className="min-w-0">
                <div
                  className={`text-[12.5px] font-semibold ${
                    ready
                      ? 'text-emerald-900 dark:text-emerald-200'
                      : 'text-amber-900 dark:text-amber-200'
                  }`}
                >
                  {ready ? 'Ready to merge' : 'Merging is blocked'}
                </div>
                <div
                  className={`text-[11px] leading-snug ${
                    ready
                      ? 'text-emerald-700/80 dark:text-emerald-300/80'
                      : 'text-amber-700/80 dark:text-amber-300/80'
                  }`}
                >
                  {mergeSummary.line}
                </div>
              </div>
            </div>
          )}

          {/* Primary action — initiates the merge directly with the
              method shown on the label. The box still owns the method
              picker; "Jump to merge box" below remains for that detail. */}
          {showMerge && (
            <div className="px-1 pb-1">
              <button
                type="button"
                disabled={!ready || merging}
                onClick={
                  ready && !merging ? () => void lifecycle.merge({ method }) : undefined
                }
                className={`flex h-8 w-full items-center justify-center gap-2 rounded-md text-[12.5px] font-semibold transition-colors ${
                  ready
                    ? 'bg-emerald-600 text-white hover:bg-emerald-700'
                    : 'cursor-not-allowed border bg-muted text-muted-foreground'
                }`}
              >
                {merging ? (
                  <Loader2 className="size-3.5 animate-spin" />
                ) : (
                  <GitMergeIcon className="size-3.5" />
                )}
                {ready ? MERGE_LABEL[method] : 'Merge blocked'}
              </button>
              {!ready && (
                <div className="px-0.5 pt-1 text-[10.5px] leading-snug text-muted-foreground">
                  Resolve required reviews &amp; checks below to enable merge.
                </div>
              )}
            </div>
          )}

          {(showMerge && (hasStatusActions || updateBranch)) && (
            <DropdownMenuSeparator />
          )}

          {hasStatusActions && (
            <DropdownMenuLabel className="text-[11px] uppercase tracking-wider text-muted-foreground">
              Change status
            </DropdownMenuLabel>
          )}
          {updateBranch && (
            <DropdownMenuItem onSelect={() => setConfirmUpdate(true)}>
              <RefreshCwIcon className="size-3.5" />
              Update branch
            </DropdownMenuItem>
          )}
          {markReady && (
            <DropdownMenuItem onSelect={() => setConfirm('markReady')}>
              <CheckCircle2Icon className="size-3.5" />
              Mark as ready for review
            </DropdownMenuItem>
          )}
          {toDraft && (
            <DropdownMenuItem onSelect={() => setConfirm('convertToDraft')}>
              <GitPullRequestDraftIcon className="size-3.5" />
              Convert to draft
            </DropdownMenuItem>
          )}
          {reopen && (
            <DropdownMenuItem onSelect={() => setConfirm('reopen')}>
              <GitPullRequestIcon className="size-3.5" />
              Reopen pull request
            </DropdownMenuItem>
          )}
          {close && (
            <DropdownMenuItem
              onSelect={() => setConfirm('close')}
              className="text-red-600 focus:text-red-600 dark:text-red-400 dark:focus:text-red-400"
            >
              <XCircleIcon className="size-3.5" />
              Close pull request
            </DropdownMenuItem>
          )}

          {onJumpToMergeBox && (
            <>
              {hasContentAboveJump && <DropdownMenuSeparator />}
              <DropdownMenuItem onSelect={() => onJumpToMergeBox()}>
                <ArrowDownIcon className="size-3.5" />
                Jump to merge box
              </DropdownMenuItem>
            </>
          )}
        </DropdownMenuContent>
      </DropdownMenu>

      {confirmKind && (
        <ConfirmModal
          open={!!confirm}
          onOpenChange={(o) => {
            if (!o) setConfirm(null);
          }}
          pending={lifecycle.pending === confirmKind}
          onConfirm={runConfirm}
          {...CONFIRM_COPY[confirmKind]}
        />
      )}

      {pr && updateBranch && (
        <ConfirmModal
          open={confirmUpdate}
          onOpenChange={setConfirmUpdate}
          tone="neutral"
          icon={RefreshCwIcon}
          title="Update this branch?"
          description={`This merges the latest changes from ${pr.base.ref} into ${pr.head.ref} so the pull request is up to date.`}
          confirmLabel="Update branch"
          confirmIcon={RefreshCwIcon}
          pending={lifecycle.pending === 'updateBranch'}
          onConfirm={() => {
            void lifecycle.updateBranch().then(() => setConfirmUpdate(false));
          }}
        />
      )}
    </>
  );
}
