// Entitlement resolution + billing entry points (ADR 0020).
//
// Access is PER-ORG: the entitlement carries the SET of orgs the viewer holds a
// live seat in (`entitlement.seats`). A seat unlocks only that org — never
// global. Billing actions (checkout / seat management) are owner-gated — only an
// org's owners/admins ever reach Polar. The accessibility predicate that hides
// blocked orgs everywhere lives in ./orgGate (it needs the installations list to
// bridge owner-login → org-id).

import { useMutation, useQuery } from '@tanstack/react-query';
import {
  broker,
  type Entitlement,
  type OrgRole,
  type SeatAssignment,
} from '../auth/oauthBroker';
import { toast } from 'sonner';
import { getToken, getCredential } from '../auth/tokenStore';
import { openExternalUrl } from '../desktop/openExternal';
import { track, Events } from '../observability';
import {
  isEntitlementFresh,
  verifyEntitlementToken,
} from './entitlementToken';
import {
  readCachedEntitlement,
  setCachedEntitlement,
} from './entitlementStore';

const POLAR_CHECKOUT_URL = (
  import.meta.env.VITE_POLAR_CHECKOUT_URL as string | undefined
)?.trim();

/** Owner-gated billing: only owners/admins may manage seats / check out. */
export function canManageBilling(role: OrgRole): boolean {
  return role === 'owner' || role === 'admin';
}

/**
 * Resolve the Viewer's entitlement via the broker, verify + cache it. Falls
 * back to the cached entitlement within its offline-grace window when the
 * broker is unreachable.
 */
export async function resolveEntitlement(accessToken: string): Promise<Entitlement> {
  try {
    const e = await broker.getEntitlement(accessToken);
    await verifyEntitlementToken(e);
    setCachedEntitlement(e);
    return e;
  } catch (err) {
    const cached = readCachedEntitlement();
    if (cached && Date.now() <= cached.graceUntil) return cached;
    throw err;
  }
}

/** Last-good entitlement if still fresh / in grace — sync, for paywalls. */
function getCachedEntitlement(): Entitlement | null {
  const e = readCachedEntitlement();
  return e && isEntitlementFresh(e) ? e : null;
}

/**
 * Reactive view of the viewer's entitlement, React-Query-backed so it updates
 * everywhere when re-resolved (ADR 0020 #9). Seeded from the cache for an
 * instant first paint, then:
 *   - `refetchOnWindowFocus: 'always'` re-resolves on focus so a real
 *     cancellation / trial-expiry takes effect within ~a day, not the 14-day
 *     offline grace.
 *   - `networkMode: 'online'` skips the refetch when offline, leaving the
 *     cached entitlement untouched (fail-open-to-cache). `resolveEntitlement`
 *     itself also falls back to cache within grace on any broker error.
 */
// A PAT is personal-only and can NEVER hold a seat or unlock an org (ADR 0020).
// It resolves to free entirely on-device — the broker is never called, so the
// backend never receives the PAT and never records a (verified) identity for it.
const PAT_FREE: Entitlement = {
  plan: 'free',
  seats: [],
  seatsFull: [],
  signedToken: '',
  expiresAt: 0,
  graceUntil: 0,
};

function useEntitlementQuery() {
  const cred = getCredential();
  // Only the GitHub-App credential is brokered. PAT (and signed-out) never hit
  // the entitlement endpoint — `enabled: false` keeps the PAT off the wire.
  const isApp = cred?.method === 'github-app';
  return useQuery({
    queryKey: ['entitlement'],
    queryFn: () => resolveEntitlement(cred!.accessToken),
    enabled: isApp,
    initialData: () => getCachedEntitlement() ?? undefined,
    placeholderData: (prev) => prev,
    staleTime: 60_000,
    refetchOnWindowFocus: 'always',
    networkMode: 'online',
  });
}

export function useEntitlement(): Entitlement | null {
  const cred = getCredential();
  const q = useEntitlementQuery();
  // PAT → always free, resolved locally (never via the backend). Signed out → null.
  if (cred?.method !== 'github-app') return cred ? PAT_FREE : null;
  return q.data ?? getCachedEntitlement();
}

/**
 * Whether the entitlement is still in its FIRST resolution (no cache to seed
 * from, fetch in flight). Drives the "Checking plan…" state so the UI never
 * flashes "No plan" before the answer is known (ADR 0020). Only ever true for a
 * GitHub-App session — a PAT is free immediately with no resolution.
 */
export function useEntitlementLoading(): boolean {
  const cred = getCredential();
  const { isPending, data } = useEntitlementQuery();
  return cred?.method === 'github-app' && isPending && !data;
}

/** The viewer's seat in a given org, if any (i.e. the org is accessible). */
export function seatForOrg(
  ent: Entitlement | null,
  githubOrgId: number,
): SeatAssignment | undefined {
  return ent?.seats?.find((s) => s.githubOrgId === githubOrgId);
}

/** Days remaining in a seat's current period (trial countdown), or null. */
export function daysLeft(seat: SeatAssignment): number | null {
  if (!seat.currentPeriodEnd) return null;
  const ms = seat.currentPeriodEnd - Date.now();
  return ms <= 0 ? 0 : Math.ceil(ms / 86_400_000);
}

const BROKER_URL = (
  import.meta.env.VITE_AUTH_BROKER_URL as string | undefined
)?.trim();

/** Ask the broker for a billing URL (owner-gated server-side), then open it.
 * Surfaces a toast on any failure — opening Polar is a user-initiated click, so
 * a silent no-op reads as "nothing happened / the button's broken". */
async function openBrokerBillingUrl(
  path: '/billing/portal' | '/billing/checkout',
  githubOrgId: number,
): Promise<void> {
  if (!BROKER_URL) {
    toast.error('Billing isn’t available right now.');
    return;
  }
  const token = getToken();
  try {
    const res = await fetch(`${BROKER_URL}${path}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: JSON.stringify({ githubOrgId }),
    });
    const data = (await res.json().catch(() => ({}))) as { url?: string };
    if (res.ok && data.url) {
      openExternalUrl(data.url);
      return;
    }
    toast.error('Couldn’t open billing', {
      description: 'Something went wrong setting up your billing session. Please try again in a moment.',
    });
  } catch {
    toast.error('Couldn’t reach billing', {
      description: 'Check your connection and try again.',
    });
  }
}

/** Open the Polar customer portal to manage an org's seats (owner/admin only).
 * Resolves once the broker round-trip finishes (tab opened, or error toasted) —
 * await it to drive a button's loading state. */
export function openManageSeats(githubOrgId: number): Promise<void> {
  return openBrokerBillingUrl('/billing/portal', githubOrgId);
}

/** Start a hosted checkout to buy seats for an org (owner/admin only). Resolves
 * when the broker round-trip finishes — see `openManageSeats`. */
export function openOrgCheckout(githubOrgId: number): Promise<void> {
  track(Events.CheckoutStarted, {}, { orgId: githubOrgId });
  return openBrokerBillingUrl('/billing/checkout', githubOrgId);
}

/** Billing-button helper: React Query mutations over the checkout/portal
 * actions so a button can show a spinner during the broker round-trip (the
 * action opens an external Polar tab on success, or toasts on failure — it
 * never rejects, so there's no onError to wire). One mutation each; a card/panel
 * renders a single billing button, so `pending` covering both is fine. */
export function useBillingAction(): {
  pending: boolean;
  manageSeats: (githubOrgId: number) => void;
  checkout: (githubOrgId: number) => void;
} {
  const manage = useMutation({ mutationFn: openManageSeats });
  const checkout = useMutation({ mutationFn: openOrgCheckout });
  return {
    pending: manage.isPending || checkout.isPending,
    manageSeats: manage.mutate,
    checkout: checkout.mutate,
  };
}

/** Open the plan-comparison / upgrade page (free-tier nudge, no org context). */
export function openComparePlans(): void {
  track(Events.UpgradeClicked, { source: 'compare_plans' });
  openExternalUrl(POLAR_CHECKOUT_URL || 'https://pyor.review/pricing');
}
