// AI inline review hints — state machine + SHA-keyed cache (ADR 0026).
// Hints are private reading aids: triggered explicitly, cached per head SHA,
// stale on a new commit. View state (type filter, per-file hide, per-hint
// dismiss) lives here so the trigger, filter bar, rail indicator, and the
// in-diff annotations all read one source.

import { useCallback, useMemo, useRef, useState } from 'react';
import type { GHPullRequestFile } from '@/github/types';
import type { FileContents } from '@/github/fetchPRFileContents';
import { useAiSettings } from '../settings/useAiSettings';
import { adapterFor } from '../provider';
import { AiError, type AiErrorKind } from '../provider/types';
import { estimateCost, fmtCost, fmtTokens } from '../provider/models';
import { buildContext, HINTS_LIMITS } from '../engine/context';
import { makeShaCache } from '../engine/shaCache';
import type { AiHintType } from '../aikit';
import { runHints } from './runHints';
import type { AiHintData, AiHintsResult } from './schema';

const cache = makeShaCache<AiHintsResult>('hints');

export type AiHintsStatus =
  | 'locked'
  | 'idle'
  | 'loading'
  | 'ready'
  | 'stale'
  | 'empty'
  | 'error';

/** A hint plus a stable id for collapse/dismiss/annotation keys. */
export interface AnchoredHint extends AiHintData {
  id: string;
}

export interface UseAiHints {
  status: AiHintsStatus;
  /** All hints (post-dismiss), with stable ids. */
  hints: AnchoredHint[];
  /** Visible hints after type-filter + per-file hide, grouped by path. */
  byFile: Map<string, AnchoredHint[]>;
  /** Total visible count + per-type counts (for the filter bar). */
  total: number;
  countsByType: Record<AiHintType, number>;
  capped: { analyzed: number; totalFiles: number } | null;
  errorKind?: AiErrorKind;
  retryAfter?: number;
  cost: { tokens: string; cost: string; secs: string } | null;
  estimate: { tokens: string; cost: string } | null;
  ranAt: number | null;
  // View state
  activeTypes: Set<AiHintType>;
  toggleType: (t: AiHintType) => void;
  hiddenFiles: Set<string>;
  setFileHidden: (path: string, hidden: boolean) => void;
  dismiss: (id: string) => void;
  run: () => void;
  cancel: () => void;
}

/** Compact descriptor the Changes tab publishes up so the collapsed PR header
 * can ride the same "Review with AI" trigger (the body hints bar and the
 * compact header read one hook instance — see ChangesTab → PRDetailScreen). */
export interface AiCompactTrigger {
  state: 'ready' | 'running' | 'done';
  /** Files analyzed / total — for the "Reviewing… n/m" running label. */
  done: number;
  total: number;
  /** Visible hint count — for the "n hints" done label. */
  count: number;
  /** Pre-run token/cost estimate, surfaced in the trigger's rich tooltip
   * (only present in the ready/idle state — null once a run has happened). */
  estimate: { tokens: string; cost: string } | null;
  onActivate: () => void;
}

const ALL_TYPES: AiHintType[] = ['bug', 'security', 'risk', 'complexity', 'test-gap'];

function hintId(h: AiHintData): string {
  return `${h.path}:${h.line}:${h.type}:${h.title.slice(0, 24)}`;
}

export function useAiHints(args: {
  owner: string | undefined;
  repo: string | undefined;
  number: number | undefined;
  headSha: string | undefined;
  files: GHPullRequestFile[];
  contents: Map<string, FileContents> | undefined;
}): UseAiHints {
  const { owner, repo, number, headSha, files, contents } = args;
  const { settings, ready, effectiveProvider } = useAiSettings();

  const [running, setRunning] = useState(false);
  const [errorKind, setErrorKind] = useState<AiErrorKind | undefined>();
  const [retryAfter, setRetryAfter] = useState<number | undefined>();
  const [cost, setCost] = useState<UseAiHints['cost']>(null);
  const [version, setVersion] = useState(0);
  const [activeTypes, setActiveTypes] = useState<Set<AiHintType>>(new Set(ALL_TYPES));
  const [hiddenFiles, setHiddenFiles] = useState<Set<string>>(new Set());
  const [dismissed, setDismissed] = useState<Set<string>>(new Set());
  const abortRef = useRef<AbortController | null>(null);

  const prId = owner && repo && number != null ? { owner, repo, number } : null;

  const cached = useMemo(() => {
    if (!prId) return { status: 'none' as const };
    return cache.read(prId, headSha);
  }, [prId?.owner, prId?.repo, prId?.number, headSha, version]);

  const allHints: AnchoredHint[] = useMemo(() => {
    if (cached.status !== 'fresh' && cached.status !== 'stale') return [];
    return cached.result.hints
      .map((h) => ({ ...h, id: hintId(h) }))
      .filter((h) => !dismissed.has(h.id));
  }, [cached, dismissed]);

  const status: AiHintsStatus = running
    ? 'loading'
    : errorKind
      ? 'error'
      : !ready
        ? 'locked'
        : cached.status === 'stale'
          ? 'stale'
          : cached.status === 'fresh'
            ? allHints.length === 0
              ? 'empty'
              : 'ready'
            : 'idle';

  const byFile = useMemo(() => {
    const m = new Map<string, AnchoredHint[]>();
    allHints.forEach((h) => {
      if (!activeTypes.has(h.type)) return;
      if (hiddenFiles.has(h.path)) return;
      const list = m.get(h.path);
      if (list) list.push(h);
      else m.set(h.path, [h]);
    });
    return m;
  }, [allHints, activeTypes, hiddenFiles]);

  const countsByType = useMemo(() => {
    const c: Record<AiHintType, number> = {
      bug: 0,
      security: 0,
      risk: 0,
      complexity: 0,
      'test-gap': 0,
    };
    allHints.forEach((h) => {
      c[h.type] += 1;
    });
    return c;
  }, [allHints]);

  const total = useMemo(
    () => [...byFile.values()].reduce((n, l) => n + l.length, 0),
    [byFile],
  );

  const estimate = useMemo(() => {
    if (!effectiveProvider || (status !== 'idle' && status !== 'stale')) return null;
    const ctx = buildContext(files, contents, HINTS_LIMITS);
    const tokens = Math.ceil(ctx.text.length / 4) + 600;
    return {
      tokens: fmtTokens(tokens),
      cost: fmtCost(estimateCost(effectiveProvider, tokens, 1200)),
    };
  }, [effectiveProvider, status, files, contents]);

  const ranAt = cached.status === 'fresh' || cached.status === 'stale' ? cached.ranAt : null;

  const run = useCallback(() => {
    if (!prId || !headSha || !effectiveProvider) return;
    const adapter = adapterFor(effectiveProvider, settings);
    if (!adapter) return;
    const ctrl = new AbortController();
    abortRef.current = ctrl;
    setErrorKind(undefined);
    setRetryAfter(undefined);
    setRunning(true);
    const startedAt = Date.now();
    void runHints(adapter, files, contents, settings.guidelines, ctrl.signal)
      .then((res) => {
        if (ctrl.signal.aborted) return;
        cache.write(prId, headSha, { hints: res.hints });
        const secs = ((Date.now() - startedAt) / 1000).toFixed(1);
        setCost({
          tokens: fmtTokens(res.usage.inputTokens + res.usage.outputTokens),
          cost: fmtCost(estimateCost(effectiveProvider, res.usage.inputTokens, res.usage.outputTokens)),
          secs: `${secs}s`,
        });
        setDismissed(new Set());
        setVersion((v) => v + 1);
      })
      .catch((err: unknown) => {
        if (ctrl.signal.aborted) return;
        if (err instanceof AiError) {
          setErrorKind(err.kind);
          setRetryAfter(err.retryAfter);
        } else {
          setErrorKind('unknown');
        }
      })
      .finally(() => {
        if (!ctrl.signal.aborted) setRunning(false);
      });
  }, [prId, headSha, effectiveProvider, settings, files, contents]);

  const cancel = useCallback(() => {
    abortRef.current?.abort();
    setRunning(false);
  }, []);

  const toggleType = useCallback((t: AiHintType) => {
    setActiveTypes((prev) => {
      const next = new Set(prev);
      if (next.has(t)) next.delete(t);
      else next.add(t);
      return next;
    });
  }, []);

  const setFileHidden = useCallback((path: string, hidden: boolean) => {
    setHiddenFiles((prev) => {
      const next = new Set(prev);
      if (hidden) next.add(path);
      else next.delete(path);
      return next;
    });
  }, []);

  const dismiss = useCallback((id: string) => {
    setDismissed((prev) => new Set(prev).add(id));
  }, []);

  return {
    status,
    hints: allHints,
    byFile,
    total,
    countsByType,
    capped: null,
    errorKind,
    retryAfter,
    cost,
    estimate,
    ranAt,
    activeTypes,
    toggleType,
    hiddenFiles,
    setFileHidden,
    dismiss,
    run,
    cancel,
  };
}
