// Anthropic provider adapter — @anthropic-ai/sdk, run client-side with
// dangerouslyAllowBrowser (the user's own key, in Keychain/localStorage,
// never proxied — same trust boundary as the GitHub token). Keeps prompt
// caching: the large diff+file-context goes in a cache_control system block
// so grouping + hints for one head SHA bill the shared prefix at ~0.1×.

import Anthropic from '@anthropic-ai/sdk';
import { AiError } from './types';
import type {
  CompleteArgs,
  CompleteResult,
  CuratedModel,
  ProviderAdapter,
} from './types';
import { DEFAULT_MODEL, FALLBACK_MODELS } from './models';

function mapError(err: unknown): AiError {
  if (err instanceof Anthropic.APIError) {
    const retryAfter = Number(err.headers?.get?.('retry-after')) || undefined;
    // Anthropic returns "credit balance is too low" as a 400 invalid_request —
    // a billing problem, not a malformed request. Surface it as billing so the
    // UI tells the user to top up rather than implying a retry will fix it.
    if (/credit balance|billing|insufficient/i.test(err.message)) {
      return new AiError('billing', 'Your Anthropic account is out of credit.');
    }
    if (err.status === 401 || err.status === 403) {
      return new AiError('invalid-key', 'The Anthropic key was rejected.');
    }
    if (err.status === 429) {
      return new AiError('rate-limited', 'Anthropic is rate-limiting requests.', retryAfter);
    }
    if (err.status === 529 || (err.status ?? 0) >= 500) {
      return new AiError('overloaded', 'Anthropic is overloaded. Try again shortly.');
    }
    return new AiError('unknown', err.message);
  }
  if (err instanceof Anthropic.APIConnectionError) {
    return new AiError('network', "Couldn't reach Anthropic.");
  }
  return new AiError('unknown', err instanceof Error ? err.message : 'Unknown error');
}

export function makeAnthropicAdapter(key: string, model?: string): ProviderAdapter {
  const client = new Anthropic({ apiKey: key, dangerouslyAllowBrowser: true });
  const resolvedModel = model || DEFAULT_MODEL.anthropic;

  return {
    provider: 'anthropic',
    defaultModel: resolvedModel,

    async testKey() {
      try {
        // Cheapest possible call that exercises auth.
        await client.messages.create({
          model: resolvedModel,
          max_tokens: 1,
          messages: [{ role: 'user', content: 'ping' }],
        });
      } catch (err) {
        // A 400 (e.g. odd model) still proves the key authenticated.
        if (err instanceof Anthropic.APIError && (err.status === 400)) return;
        throw mapError(err);
      }
    },

    async listModels(): Promise<CuratedModel[]> {
      try {
        const res = await client.models.list();
        // Newest-first by created_at; prefer the human display_name as the
        // label, fall back to the id.
        const models = res.data
          .filter((m) => m.id.startsWith('claude-'))
          .sort((a, b) => (b.created_at ?? '').localeCompare(a.created_at ?? ''));
        if (models.length === 0) return FALLBACK_MODELS.anthropic;
        return models.slice(0, 8).map((m) => ({ id: m.id, label: m.display_name || m.id }));
      } catch {
        return FALLBACK_MODELS.anthropic;
      }
    },

    async complete<T = unknown>(args: CompleteArgs): Promise<CompleteResult<T>> {
      try {
        const res = await client.messages.create(
          {
            model: resolvedModel,
            max_tokens: args.maxTokens ?? 4096,
            // System: the big context first (cached), then the small
            // feature instruction. cache_control on the context block makes
            // the shared prefix reusable across grouping & hints per SHA.
            system: [
              {
                type: 'text',
                text: args.contextBlock,
                cache_control: { type: 'ephemeral' },
              },
              { type: 'text', text: args.instruction },
            ],
            messages: [
              {
                role: 'user',
                content: 'Produce the result as JSON matching the required schema.',
              },
            ],
            output_config: {
              format: { type: 'json_schema', schema: args.schema },
            },
          } as Anthropic.MessageCreateParamsNonStreaming,
          { signal: args.signal },
        );
        const textBlock = res.content.find((b) => b.type === 'text');
        const raw = textBlock && 'text' in textBlock ? textBlock.text : '';
        let data: T;
        try {
          data = JSON.parse(raw) as T;
        } catch {
          throw new AiError('unknown', 'The model returned malformed JSON.');
        }
        return {
          data,
          model: res.model,
          usage: {
            inputTokens: res.usage.input_tokens,
            outputTokens: res.usage.output_tokens,
            cacheReadTokens: res.usage.cache_read_input_tokens ?? undefined,
          },
        };
      } catch (err) {
        if (err instanceof AiError) throw err;
        throw mapError(err);
      }
    },

    async countInputTokens(contextBlock: string, instruction: string) {
      try {
        const res = await client.messages.countTokens({
          model: resolvedModel,
          system: [
            { type: 'text', text: contextBlock },
            { type: 'text', text: instruction },
          ],
          messages: [{ role: 'user', content: 'Produce the result as JSON.' }],
        });
        return { tokens: res.input_tokens, exact: true };
      } catch {
        // Estimate fallback if count_tokens is unavailable.
        return { tokens: Math.ceil((contextBlock.length + instruction.length) / 4), exact: false };
      }
    },
  };
}
