// Kbd — keyboard-key hint chip.
//
// Project composition over shadcn `Badge variant="outline"` would lose
// the semantic `<kbd>` tag, and shadcn's registry doesn't ship a Kbd.
// So this is a tiny first-class composition: keep the semantic HTML
// element, attach the (shared) chip styling once, and let call sites
// stay one-liners.
//
// Usage:
//   <Kbd>R</Kbd>           — single key
//   <Kbd>⌘</Kbd><Kbd>⏎</Kbd> — combo (each in its own pill)

import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';

export function Kbd({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <kbd
      className={cn(
        // System (sans) font, not mono: SF Mono renders the macOS
        // modifier glyphs (⌘ ⇧ ⌥ ⏎) thin/misshapen, while the system UI
        // font has the crisp filled versions.
        'inline-flex h-[18px] min-w-[18px] items-center justify-center rounded border-[0.5px] border-border bg-muted px-1 text-[10.5px] font-medium text-muted-foreground [font-family:inherit]',
        className,
      )}
    >
      {children}
    </kbd>
  );
}
