// Per-PR conversation Focus-mode state, persisted to localStorage.
//
// Focus mode is deliberately NOT in the URL: it's a private viewing
// preference, not a shareable part of the route, and it's remembered
// PER PR (each pull request keeps its own on/off) so returning to a PR
// restores how you last read it. Keyed by `owner/repo/number` under a
// single small map. Failures (private mode, quota) degrade to "off".

const KEY = 'pyor:conv-focus';
// Changes-tab "Focus: Code" on/off. Tracked INDEPENDENTLY of the
// Conversation comment-focus above (its own per-PR flag, own key) so
// toggling Focus on one tab never touches the other.
const CODE_KEY = 'pyor:code-focus';
// Which comment-focus VARIANT the Conversation pill is set to: "New
// comments" (only threads awaiting the viewer's reply) vs the default
// "All comments". Stored as a per-PR flag (present = "new") under its
// own key, remembered independently of whether Focus is currently on —
// but it only takes EFFECT while Focus is active (see PRDetailScreen).
const NEW_COMMENTS_KEY = 'pyor:conv-newcomments';

type FocusMap = Record<string, true>;

function read(key: string): FocusMap {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as FocusMap) : {};
  } catch {
    return {};
  }
}

function prKey(owner: string, repo: string, number: number): string {
  return `${owner}/${repo}/${number}`;
}

function readFlag(
  key: string,
  owner: string,
  repo: string,
  number: number,
): boolean {
  return read(key)[prKey(owner, repo, number)] === true;
}

/** Persist a per-PR boolean preference, storing only the `true` keys so
 * the map stays small (off = default = absent). */
function writeFlag(
  key: string,
  owner: string,
  repo: string,
  number: number,
  on: boolean,
): void {
  const map = read(key);
  const k = prKey(owner, repo, number);
  if (on) map[k] = true;
  else delete map[k];
  try {
    localStorage.setItem(key, JSON.stringify(map));
  } catch {
    // private mode / quota — the preference just won't persist this session.
  }
}

/** Whether comments-only Focus mode is on for this PR. Defaults off. */
export function getConversationFocus(
  owner: string,
  repo: string,
  number: number,
): boolean {
  return readFlag(KEY, owner, repo, number);
}

/** Persist the Focus on/off for this PR. */
export function setConversationFocus(
  owner: string,
  repo: string,
  number: number,
  on: boolean,
): void {
  writeFlag(KEY, owner, repo, number, on);
}

/** Whether the Changes-tab "Focus: Code" is on for this PR. Defaults off. */
export function getCodeFocus(
  owner: string,
  repo: string,
  number: number,
): boolean {
  return readFlag(CODE_KEY, owner, repo, number);
}

/** Persist the Changes-tab "Focus: Code" on/off for this PR. */
export function setCodeFocus(
  owner: string,
  repo: string,
  number: number,
  on: boolean,
): void {
  writeFlag(CODE_KEY, owner, repo, number, on);
}

/** Whether the Conversation comment-focus variant is "New comments"
 * (vs the default "All comments") for this PR. */
export function getNewCommentsFocus(
  owner: string,
  repo: string,
  number: number,
): boolean {
  return readFlag(NEW_COMMENTS_KEY, owner, repo, number);
}

/** Persist the comment-focus variant for this PR (true = "New comments"). */
export function setNewCommentsFocus(
  owner: string,
  repo: string,
  number: number,
  isNew: boolean,
): void {
  writeFlag(NEW_COMMENTS_KEY, owner, repo, number, isNew);
}
