// Fresh, self-owned CSS Custom Highlight painter for symbol occurrences.
// Independent of the (broken, being-removed) diff-search painter. Paints read /
// write / definition roles via ::highlight() using the --sym-* design tokens.
//
// ::highlight() only supports background-color, color, text-decoration and a few
// others — the design respects that (fills + underlines only). Custom properties
// inherit across the shadow boundary, so var(--sym-*) resolves on shadow text.

import type { OccurrenceRole } from './types';

const NAME: Record<OccurrenceRole, string> = {
  read: 'pyor-sym-read',
  write: 'pyor-sym-write',
  definition: 'pyor-sym-def',
};

const HOVER = 'pyor-sym-hover';
const FLASH = 'pyor-sym-flash';

const CSS = `
::highlight(${NAME.read}){background-color:var(--sym-read-fill);}
::highlight(${NAME.write}){
  background-color:var(--sym-write-fill);
  text-decoration-line:underline;text-decoration-color:var(--sym-write-line);
  text-decoration-thickness:1.5px;text-underline-offset:3px;
}
::highlight(${NAME.definition}){
  background-color:var(--sym-def-fill);color:var(--sym-def-ink);
  text-decoration-line:underline;text-decoration-color:var(--sym-def-line);
  text-decoration-thickness:2.5px;text-underline-offset:3px;
}
::highlight(${HOVER}){
  text-decoration-line:underline;text-decoration-color:var(--sym-hover-line);
  text-decoration-thickness:1px;text-underline-offset:3px;
}
::highlight(${FLASH}){background-color:var(--sym-flash);}`;

const SUPPORTED =
  typeof CSS !== 'undefined' &&
  typeof window !== 'undefined' &&
  'highlights' in window.CSS &&
  typeof Highlight !== 'undefined' &&
  typeof Range !== 'undefined';

interface Registry {
  read: Highlight;
  write: Highlight;
  definition: Highlight;
  hover: Highlight;
  flash: Highlight;
  sheet: CSSStyleSheet;
}

let reg: Registry | null = null;

function ensure(): Registry | null {
  if (!SUPPORTED) return null;
  if (reg) return reg;
  const read = new Highlight();
  const write = new Highlight();
  const definition = new Highlight();
  const hover = new Highlight();
  const flash = new Highlight();
  read.priority = 0;
  hover.priority = 0;
  write.priority = 1;
  definition.priority = 2;
  flash.priority = 3;
  window.CSS.highlights.set(NAME.read, read);
  window.CSS.highlights.set(NAME.write, write);
  window.CSS.highlights.set(NAME.definition, definition);
  window.CSS.highlights.set(HOVER, hover);
  window.CSS.highlights.set(FLASH, flash);
  const sheet = new CSSStyleSheet();
  sheet.replaceSync(CSS);
  reg = { read, write, definition, hover, flash, sheet };
  return reg;
}

/** Adopt the ::highlight() rules into a tree scope (document or a shadow root). */
export function adoptInto(scope: Document | ShadowRoot): void {
  const r = ensure();
  if (!r) return;
  try {
    if (!scope.adoptedStyleSheets.includes(r.sheet)) {
      scope.adoptedStyleSheets = [...scope.adoptedStyleSheets, r.sheet];
    }
  } catch {
    /* adoptedStyleSheets unsupported — ignore */
  }
}

/** Replace the painted occurrence ranges. */
export function paint(ranges: { range: Range; role: OccurrenceRole }[]): void {
  const r = ensure();
  if (!r) return;
  r.read.clear();
  r.write.clear();
  r.definition.clear();
  for (const { range, role } of ranges) r[role].add(range);
}

/** Replace the single hover-affordance range (or clear with null). */
export function paintHover(range: Range | null): void {
  const r = ensure();
  if (!r) return;
  r.hover.clear();
  if (range) r.hover.add(range);
}

/** Replace the go-to-definition flash range (or clear with null). Survives diff
 * re-renders because callers repaint it on each onItemPostRender until cleared. */
export function paintFlash(range: Range | null): void {
  const r = ensure();
  if (!r) return;
  r.flash.clear();
  if (range) r.flash.add(range);
}

export function clearOccurrences(): void {
  if (!reg) return;
  reg.read.clear();
  reg.write.clear();
  reg.definition.clear();
}
