// The viewed-state eye glyphs, identical to the @pierre/trees rail's
// `pyor-eye-*` sprites (PierreFileTree.tsx) so the bespoke AI rail shows the
// SAME eye on files and folders as the older list. open = not viewed,
// closed = viewed ("case closed"), half = partially-viewed folder.

import { cn } from '@/lib/utils';

export type EyeState = 'open' | 'half' | 'closed';

export function ViewedEye({ state, className }: { state: EyeState; className?: string }) {
  const common = {
    viewBox: '0 0 24 24',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 2,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    className: cn('size-3.5', className),
    'aria-hidden': true,
  };
  if (state === 'closed') {
    return (
      <svg {...common}>
        <path d="M2 8a10.645 10.645 0 0 0 20 0" />
        <path d="m20 15-1.726-2.05" />
        <path d="m4 15 1.726-2.05" />
        <path d="m9 18 .722-3.25" />
        <path d="m15 18-.722-3.25" />
      </svg>
    );
  }
  if (state === 'half') {
    return (
      <svg {...common}>
        <path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0" />
        <path d="M3.5 9.8 Q12 2 20.5 9.8 L23 12.2 Q12 13 1 12.2 Z" fill="currentColor" stroke="none" />
        <path d="M9 12a3 3 0 0 0 6 0" />
      </svg>
    );
  }
  return (
    <svg {...common}>
      <path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0" />
      <circle cx="12" cy="12" r="3" />
    </svg>
  );
}
