// InfiniteFooter — bottom-of-list states for paginated feeds.
//
// Two states:
//   - `loading`: spinner + "Loading page N+1…" + "X of ~Y"
//   - `idle`:    "X shown · N pages loaded" + Load more + auto-scroll caption
//
// Callers wire the sentinel with an IntersectionObserver to call
// `onLoadMore` when it enters the viewport. The component itself
// renders the sentinel — pass `sentinelRef` to mount the observer.
//
// Shared by Inbox Comments and Pull-requests lists.

import { useEffect, useRef } from 'react';
import { CheckCheckIcon, ChevronDownIcon, Loader2Icon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';

interface InfiniteFooterProps {
  state: 'loading' | 'idle' | 'end';
  shown: number;
  pagesLoaded: number;
  estimatedTotal?: number;
  /** Triggered by both the Load-more button and the IntersectionObserver
   * when the sentinel scrolls into view. */
  onLoadMore?: () => void;
  /** Footnote shown under the load-more button. Defaults to GitHub's
   * 5,000 req/h budget for the Pulls page; callers override for the
   * Comments tab which uses a different cap. */
  caption?: string;
}

export function InfiniteFooter({
  state,
  shown,
  pagesLoaded,
  estimatedTotal,
  onLoadMore,
  caption = 'Scroll to auto-load · GitHub returns 100 / page · 5,000 req/h budget',
}: InfiniteFooterProps) {
  const sentinelRef = useRef<HTMLDivElement | null>(null);
  // Auto-load when the sentinel becomes visible. Only wires when idle
  // — once loading or end, the observer is dormant.
  useEffect(() => {
    if (state !== 'idle' || !onLoadMore) return;
    const node = sentinelRef.current;
    if (!node) return;
    const obs = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) onLoadMore();
      },
      { rootMargin: '120px' },
    );
    obs.observe(node);
    return () => obs.disconnect();
  }, [state, onLoadMore]);

  if (state === 'loading') {
    return (
      <div className="flex items-center justify-center gap-2 border-t px-4 py-5 text-[12px] text-muted-foreground">
        <Loader2Icon className="size-3.5 animate-spin" />
        <span>Loading page {pagesLoaded + 1}…</span>
        {estimatedTotal != null && (
          <>
            <span className="text-border">·</span>
            <span className="tabular-nums">
              {shown} of ~{estimatedTotal}
            </span>
          </>
        )}
      </div>
    );
  }
  if (state === 'end') {
    return (
      <div className="border-t px-4 py-5 text-center text-[11.5px] text-muted-foreground">
        End of feed · {shown} {shown === 1 ? 'item' : 'items'} ·{' '}
        {pagesLoaded} {pagesLoaded === 1 ? 'page' : 'pages'} loaded
      </div>
    );
  }
  return (
    <div className="flex flex-col items-center gap-1.5 border-t px-4 py-5">
      <div className="flex items-center gap-3 text-[12px] text-muted-foreground">
        <span className="inline-flex items-center gap-1.5">
          <CheckCheckIcon className="size-3.5 text-muted-foreground/70" />
          <span>
            <span className="tabular-nums text-foreground">{shown}</span> shown ·{' '}
            {pagesLoaded} {pagesLoaded === 1 ? 'page' : 'pages'} loaded
          </span>
        </span>
        <Separator orientation="vertical" className="h-3" />
        <Button
          variant="outline"
          size="xs"
          className="gap-1.5 px-2.5 text-[12px]"
          onClick={onLoadMore}
        >
          <ChevronDownIcon className="size-3.5" />
          Load more
        </Button>
      </div>
      <span className="text-[10.5px] text-muted-foreground">{caption}</span>
      <div ref={sentinelRef} aria-hidden className="h-px w-px" />
    </div>
  );
}
