// AI assistance — the hint taxonomy + severity scale (ADR 0026).
// The five hint types are fixed and the output contract; severity is a
// 3-level scale shown as a bar (never color alone). Shared by hints,
// the filter bar, and the provider schema.

export type AiHintType = 'bug' | 'security' | 'risk' | 'complexity' | 'test-gap';

export type AiSeverity = 'info' | 'warn' | 'high';

export const AI_HINT_TYPES: Record<AiHintType, { label: string; short: string }> = {
  bug: { label: 'Possible bug', short: 'Bug' },
  security: { label: 'Security', short: 'Security' },
  risk: { label: 'Risk', short: 'Risk' },
  complexity: { label: 'Complexity', short: 'Complexity' },
  'test-gap': { label: 'Test gap', short: 'Test gap' },
};

export const AI_HINT_ORDER: AiHintType[] = [
  'bug',
  'security',
  'risk',
  'complexity',
  'test-gap',
];

export const AI_SEVERITY: Record<AiSeverity, { label: string; level: 1 | 2 | 3 }> = {
  info: { label: 'Info', level: 1 },
  warn: { label: 'Worth a look', level: 2 },
  high: { label: 'High', level: 3 },
};
