// Cause-aware error pane for PR fetch failures.
//
// This now renders the connectivity/outage design (section 06): it maps
// the thrown error + the browser's online state onto one of four modes
// (offline · github-down · rate-limit · auth-expired) and shows the
// shared <ConnFailureState> — full-screen by default, or compact inline
// when it fills a single pane (the diff/file body).
//
// `detectErrorCause` / `ErrorCause` are kept (unchanged) because the PR
// status-bar pill consumes them; the visual is the only thing that moved.

import { useCallback } from 'react';
import { useNavigate } from '@tanstack/react-router';
import { useQueryClient } from '@tanstack/react-query';
import { RotateCcwIcon, ExternalLinkIcon, ServerCrashIcon } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { RefreshButton } from '@/components/ui/refresh-button';
import { GitHubError } from '../github/client';
import { signOut } from '../auth/signOut';
import {
  ConnFailureState,
} from '../ui/connectivity/ConnFailureState';
import { detectConnMode, rateResetFrom } from '../ui/connectivity/connModes';

// ── Legacy cause model (status-bar pill still reads this) ────────────
export type ErrorCause = 'rate-limit' | 'network' | 'server-500' | 'unknown';

export function detectErrorCause(err: unknown): ErrorCause {
  if (err instanceof GitHubError) {
    if (err.status === 403) return 'rate-limit';
    if (err.status >= 500 && err.status < 600) return 'server-500';
    if (err.status === 0) return 'network';
    return 'unknown';
  }
  if (err instanceof TypeError) return 'network';
  const msg = err instanceof Error ? err.message.toLowerCase() : String(err);
  if (
    msg.includes('failed to fetch') ||
    msg.includes('network') ||
    msg.includes('timeout') ||
    msg.includes('timed out')
  )
    return 'network';
  return 'unknown';
}

interface Props {
  error: unknown;
  endpoint?: string;
  /** 'full' fills the content area (nothing loaded); 'inline' is the
   * compact card for a single failed pane (header + rail stay visible). */
  layout?: 'full' | 'inline';
  /** Last successful sync, if known (drives the "Last synced" line). */
  lastSyncedAt?: Date | null;
  onRetry?: () => void;
  /** Auth-expired primary. Defaults to sign-out + bounce to Welcome. */
  onReauth?: () => void;
  onOpenOnGithub?: () => void;
}

export function PRErrorPane({
  error,
  endpoint = '/pulls',
  layout = 'full',
  lastSyncedAt = null,
  onRetry,
  onReauth,
  onOpenOnGithub,
}: Props) {
  const navigate = useNavigate();
  const qc = useQueryClient();

  const defaultReauth = useCallback(() => {
    void (async () => {
      await signOut(qc);
      void navigate({ to: '/welcome' });
    })();
  }, [qc, navigate]);

  const mode = detectConnMode(error);

  // Not one of the four modeled outages (e.g. a 404 / unexpected) —
  // keep a plain, honest fallback so we never dead-end.
  if (mode === null) {
    return (
      <div className="flex flex-1 items-center justify-center bg-muted/30 p-10">
        <Card className={`w-[460px] overflow-hidden p-0`}>
          <div className="flex items-start gap-3 p-5">
            <div className="inline-flex size-11 shrink-0 items-center justify-center rounded-lg border bg-card">
              <ServerCrashIcon className="size-5 text-muted-foreground" strokeWidth={1.8} />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-[15px] font-semibold tracking-tight text-foreground">
                Couldn&rsquo;t load this view
              </div>
              <div className="mt-1 text-[12.5px] leading-relaxed text-muted-foreground">
                {error instanceof Error ? error.message : String(error)}
              </div>
              <div className="mt-2 font-mono text-[11px] text-muted-foreground">
                {endpoint}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2 border-t bg-muted/40 p-3">
            <Button variant="ghost" size="sm" onClick={onOpenOnGithub}>
              <ExternalLinkIcon />
              Open on GitHub
            </Button>
            <RefreshButton
              variant="default"
              className="ml-auto"
              onRefresh={onRetry}
              icon={RotateCcwIcon}
              label="Retry"
            />
          </div>
        </Card>
      </div>
    );
  }

  return (
    <ConnFailureState
      mode={mode}
      layout={layout}
      endpoint={endpoint}
      lastSyncedAt={lastSyncedAt}
      rateResetAt={rateResetFrom(error)}
      onRetry={onRetry}
      onReauth={onReauth ?? defaultReauth}
      onFallback={onOpenOnGithub}
    />
  );
}
