interface PRHeaderActionsProps {
  prHtmlUrl?: string;
}

export function PRHeaderActions({
  prHtmlUrl,
}: PRHeaderActionsProps = {}) {
  // PR-detail actions used to live in the macOS titlebar — the design
  // moves them into PRHeader proper (next to the FocusToggle), so the
  // titlebar's only job is window chrome. The Approve / Request-
  // changes / Open-on-GitHub buttons are rendered inline by PRHeader
  // via PRDetailActions; this stub only persists the hidden anchor
  // that lets SkippedBanner find the PR URL by querySelector.
  if (!prHtmlUrl) return null;
  return (
    <a
      data-pyor-pr-html-url
      href={prHtmlUrl}
      className="sr-only"
      tabIndex={-1}
      aria-hidden
    >
      GitHub
    </a>
  );
}

interface PRDetailActionsProps {
  prHtmlUrl?: string;
  onSubmitWithVerdict?: (verdict: 'changes' | 'approve') => void;
}

/** Approve button. Rendered inline in the PRHeader breadcrumb row
 * alongside the FocusToggle. Request-changes lives inside the submit-
 * review modal (verdict picker) — the breadcrumb only surfaces the
 * positive primary action, the negative paths flow through the dock /
 * modal so the user is forced to write context before blocking a PR.
 * Open-on-GitHub moved to row 1 (under the PR age) so the chrome
 * stays single-purpose: approve action right of focus mode, deep-
 * links + meta on the row below. */
function PRDetailActions({
  onSubmitWithVerdict,
}: PRDetailActionsProps = {}) {
  return (
    <div className="flex items-center gap-1.5">
      <Button
        size="sm"
        onClick={
          onSubmitWithVerdict
            ? () => onSubmitWithVerdict('approve')
            : undefined
        }
      >
        <CheckCircle2Icon /> Approve · ⌘⏎
      </Button>
    </div>
  );
}

interface PRHeaderProps {
  /** Optional during loading; once the fetch resolves the screen
   * re-renders with a populated PR. */
  pr?: GHPullRequest;
  owner?: string;
  repo?: string;
  /** Whether focus-mode is on (inline-thread chrome hidden). Renders
   * the `FocusToggle` pill in its active state. Optional only so the
   * spike harness still builds without the toggle wired. */
  focusMode?: boolean;
  /** Click handler for the `FocusToggle` pill. Toggles focus mode in
   * the parent state. When omitted the pill renders as a no-op
   * (still keyboard-driven via ⇧M). */
  onToggleFocusMode?: () => void;
  /** Conversation comment-focus variant ("New comments" vs "All
   * comments") + its picker, exposed in the FocusToggle caret menu. */
  commentFocusIsNew?: boolean;
  onSelectCommentFocus?: (isNew: boolean) => void;
  /** Counts shown on the Focus pill: `all` discussions vs `pending`
   * threads awaiting the viewer. Conversation tab only. */
  commentCounts?: { all: number; pending: number };
  /** Click handler for the breadcrumb back-link. Falls back to no
   * link when omitted (PR-detail still renders inside the macOS
   * window chrome). */
  onBack?: () => void;
  /** Label for the back-link breadcrumb segment — typically "Inbox"
   * or "Pull requests" depending on where the user came from. */
  backLabel?: string;
  /** Approve / Request-changes click handler. When omitted those
   * buttons are hidden (e.g. spike harness). */
  onSubmitWithVerdict?: (verdict: 'changes' | 'approve') => void;
  /** Active PR-detail tab. Drives the unified Focus pill's label —
   * "Focus: Comments" on the Conversation tab, "Focus: Code" elsewhere. */
  activeTab?: 'description' | 'commits' | 'changes';
  /** Switches to the Conversation tab + scrolls to the merge box. Wired
   * by PRDetailScreen; powers the status-chip twin's "Jump to merge
   * box" item. */
  onJumpToMergeBox?: () => void;
  /** Reviewer HoverCard's "View comment" action (AFK plan 11). Wired by
   * PRDetailScreen to `() => { setTab('changes'); setJumpTarget(target); }`
   * — exactly the shape ChecksTab.onJumpToAnnotation uses — so the diff
   * scrolls to + flash-pulses the reviewer's line-anchored comment
   * instead of opening GitHub. */
  onJumpToComment?: (target: {
    // Line-anchored inline comment → jump in the diff (Changes tab).
    path?: string;
    line?: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
    // PR-level review summary (no diff anchor) → jump to it in the
    // Conversation timeline by review id.
    reviewId?: number;
  }) => void;
  /** Read-only "demo" mode (AFK plan 22). Forces the lifecycle
   * controller to a no-permission state so the StatusPillMenu actions,
   * merge controls, reviewer management, and title-edit pencil all
   * disappear; also renders the "Demo (read-only)" badge. */
  readOnly?: boolean;
}

export function PRHeader({
  pr,
  owner,
  repo,
  focusMode = false,
  onToggleFocusMode,
  commentFocusIsNew = false,
  onSelectCommentFocus,
  commentCounts,
  onBack,
  backLabel = 'Inbox',
  onSubmitWithVerdict,
  activeTab,
  onJumpToMergeBox,
  onJumpToComment,
  readOnly = false,
}: PRHeaderProps = {}) {
  // Once prMeta resolves we have everything we need. Until then render
  // dashes; the parent already covers pre-paint with LoadingPane.
  const liveAuthor = pr?.user.login ?? '—';
  const liveBase = pr?.base.ref ?? '—';
  const liveHead = pr?.head.ref ?? '—';
  const liveCommits = pr?.commits ?? 0;
  const liveAdditions = pr?.additions ?? 0;
  const liveDeletions = pr?.deletions ?? 0;
  const liveFiles = pr?.changed_files ?? 0;
  const liveStatus: 'open' | 'merged' | 'draft' | 'closed' = pr?.draft
    ? 'draft'
    : pr?.merged_at
      ? 'merged'
      : pr?.state ?? 'open';
  // Merged/closed → checks are a historical record, shown without the
  // failing/pending alarm colours.
  const checksHistorical = liveStatus === 'merged' || liveStatus === 'closed';
  const liveOpenedAt = pr ? humanAge(pr.created_at) : '—';
  const liveSyncedAt = pr ? humanAge(pr.updated_at) : '—';

  // Lifecycle controller — resolves which Lifecycle actions render
  // (status-pill menu, merge control) from the viewer's permission +
  // repo merge config + PR state. Tolerates an undefined pr during the
  // initial load (returns an empty action set).
  const lifecycle = useLifecycle(pr, owner, repo, { readOnly });

  // Mirror GitHub's amber base-ref highlight: when the PR targets a branch
  // other than the repo's default, flag the base chip so reviewers notice
  // they aren't merging into the default branch. Empty default branch (the
  // repo read hasn't resolved) → no highlight, so it never flashes on.
  const defaultBranch = lifecycle.repoConfig.defaultBranch;
  const baseIsNonDefault =
    liveBase !== '—' && !!defaultBranch && liveBase !== defaultBranch;

  // Reviewer management (#18 / #19) — request / re-request / remove /
  // dismiss. Gated on WRITE+; controls that would 403 aren't rendered.
  const canManageReviewers = hasWriteAccess(lifecycle.viewerPermission);
  const reviewerMgmt = useReviewerManagement(
    owner ?? '',
    repo ?? '',
    pr?.number ?? 0,
  );

  // Reviewers — combine pr.requested_reviewers (people we asked but
  // who haven't acted) with /pulls/{n}/reviews (each user's latest
  // verdict). Same dedup/ETag story as the PullRequestsScreen row queries.
  const reviewsQuery = useQuery({
    queryKey: ['pr', owner!, repo!, pr?.number!, 'reviews'],
    queryFn: () => getReviews(owner!, repo!, pr!.number),
    enabled: !!(owner && repo && pr),
    staleTime: 60_000,
  });
  // Pull line-anchored review comments too so the reviewer HoverCard's
  // last-comment preview can fall back to "your last inline note" when
  // the reviewer never left a review-summary body. Shares the canonical
  // `['pr',owner,repo,n,'comments']` key (prCommentsOptions) so the fetch
  // is deduped across the Changes diff, Conversation, and this header.
  const reviewCommentsQuery = useQuery({
    queryKey: ['pr', owner!, repo!, pr?.number!, 'comments'],
    queryFn: () => getReviewComments(owner!, repo!, pr!.number),
    enabled: !!(owner && repo && pr),
    staleTime: 60_000,
  });
  const reviewerStates = useMemo(
    () =>
      collectReviewerStates(
        pr,
        reviewsQuery.data ?? [],
        reviewCommentsQuery.data ?? [],
      ),
    [pr, reviewsQuery.data, reviewCommentsQuery.data],
  );

  // Checks — unified rollup (check-runs + commit statuses) so the
  // strip counts the same set GitHub's PR page shows. Shared query key
  // with the merge box + Checks tab, so it's one deduped round trip.
  const checksQuery = useQuery({
    ...prCheckRollupOptions(owner!, repo!, pr?.number!, pr?.head.sha),
    enabled: !!(owner && repo && pr?.head.sha),
  });
  const checkCounts = useMemo(
    () => countRollup(checksQuery.data?.checks ?? []),
    [checksQuery.data],
  );

  // Condensed merge readiness summary for the status-chip twin. Mirrors
  // the gates the full merge box checklists out (reviews · checks ·
  // branch freshness · conflicts) so the chip and box never disagree.
  const mergeSummary: MergeSummary | undefined = useMemo(() => {
    if (!pr || liveStatus !== 'open') return undefined;
    const approvals = reviewerStates.filter((r) => r.state === 'approved').length;
    const changesReq = reviewerStates.filter((r) => r.state === 'changes').length;
    const conflicts = pr.mergeable === false || pr.mergeable_state === 'dirty';
    const behind = pr.mergeable_state === 'behind';
    const blocked = pr.mergeable_state === 'blocked';
    const ready =
      changesReq === 0 &&
      checkCounts.fail === 0 &&
      checkCounts.pending === 0 &&
      !conflicts &&
      !blocked;
    if (ready) {
      return {
        ready: true,
        line: `${checkCounts.pass > 0 ? `All ${checkCounts.pass} checks passed` : 'No required checks'} · ${approvals} approval${approvals === 1 ? '' : 's'} · no conflicts`,
      };
    }
    const parts: string[] = [];
    if (checkCounts.fail > 0) parts.push(`${checkCounts.fail} checks failing`);
    if (changesReq > 0) parts.push('changes requested');
    if (conflicts) parts.push('conflicts');
    else if (behind) parts.push('behind base');
    if (checkCounts.pending > 0) parts.push(`${checkCounts.pending} pending`);
    return {
      ready: false,
      line: parts.length > 0 ? parts.join(' · ') : 'merge requirements not met',
    };
  }, [pr, liveStatus, reviewerStates, checkCounts]);

  return (
    <div className="shrink-0 border-b bg-card px-[18px] pt-3">
      {/* Row 0 — Breadcrumb-merged title. The back-link + slash + title
          + #number read as a single hierarchy crumb, so the title itself
          functions as the deepest segment of the page's location. The
          FocusToggle anchors the right edge alongside any optional
          actions (View on GitHub lives in the macOS toolbar). */}
      <div className="mb-2 flex items-start gap-3">
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-baseline gap-x-2 gap-y-1">
            {onBack ? (
              <button
                type="button"
                onClick={onBack}
                className="inline-flex cursor-pointer items-center gap-0.5 text-[13px] font-medium text-muted-foreground transition-colors hover:text-foreground"
              >
                <ChevronLeftIcon className="-ml-0.5 size-3.5" />
                <span>{backLabel}</span>
              </button>
            ) : (
              <span className="inline-flex items-center gap-0.5 text-[13px] font-medium text-muted-foreground">
                <ChevronLeftIcon className="-ml-0.5 size-3.5" />
                <span>{backLabel}</span>
              </span>
            )}
            <span className="text-[15px] font-light text-muted-foreground/40">/</span>
            {pr && owner && repo ? (
              // PRTitle renders the title, the #number, and the edit
              // pencil (in that order — pencil after the number).
              <PRTitle
                pr={pr}
                owner={owner}
                repo={repo}
                canEdit={lifecycle.viewerLogin === pr.user.login}
              />
            ) : (
              <h1 className="text-[18px] font-semibold leading-tight tracking-tight text-foreground">
                {pr?.title ?? 'Loading…'}
              </h1>
            )}
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-1.5">
          {readOnly && (
            <span
              className="inline-flex items-center gap-1.5 rounded-full border border-amber-300 bg-amber-50 px-2.5 py-1 text-[11.5px] font-medium text-amber-700 dark:border-amber-900 dark:bg-amber-950/40 dark:text-amber-400"
              title="Public PR opened via a ?pr= demo link. Sign in to review, comment, or merge."
            >
              <EyeIcon className="size-3.5" strokeWidth={2} />
              Demo (read-only)
            </span>
          )}
          {onToggleFocusMode && (
            <FocusToggle
              mode={activeTab === 'description' ? 'comments' : 'code'}
              active={focusMode}
              onToggle={onToggleFocusMode}
              commentFocusIsNew={commentFocusIsNew}
              onSelectCommentFocus={onSelectCommentFocus ?? (() => {})}
              commentCounts={commentCounts}
            />
          )}
          {/* Open on GitHub — a proper button sitting just right of the
              Focus toggle. Native `title` tooltip (matches FocusToggle). */}
          {pr?.html_url && (
            <Button
              asChild
              variant="outline"
              size="icon"
              className="size-7"
              title="Open on GitHub"
            >
              <a
                href={markGithubPassthrough(pr.html_url)}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="Open on GitHub"
              >
                <GithubMark className="size-3.5" />
              </a>
            </Button>
          )}
          {/* The header Approve button was removed by request. Review
              verdicts (Approve / Comment / Request-changes, ⌘⏎) flow
              through the footer review dock + submit modal. Note: that
              dock currently mounts only on the Changes tab. */}
        </div>
      </div>
      {/* Row 1 — Compact status band: pill + author + branches + reviewers
          + checks hover card + diff stats + age + labels + GitHub link.
          Everything that used to span rows 1+2 now sits in one flex-wrap row. */}
      <div className="flex flex-wrap items-center gap-x-2 gap-y-1 pb-2.5 text-[12px]">
        {/* Status pill */}
        <StatusPillMenu
          status={liveStatus}
          lifecycle={lifecycle}
          pr={pr}
          mergeSummary={mergeSummary}
          onJumpToMergeBox={onJumpToMergeBox}
        />

        {/* Author: small avatar + login */}
        <span className="inline-flex items-center gap-1 text-muted-foreground">
          <Avatar className="size-[14px]">
            {pr?.user.avatar_url && (
              <AvatarImage src={pr.user.avatar_url} alt={liveAuthor} />
            )}
            <AvatarFallback className="text-[7px]">
              {liveAuthor.slice(0, 2).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <span className="font-medium text-foreground">{liveAuthor}</span>
        </span>

        <Separator orientation="vertical" className="h-3" />

        {/* Base ← head (CopyBranchBadge). The base chip turns amber when the
            PR targets a non-default branch, mirroring GitHub. */}
        <div className="inline-flex items-center gap-1 font-mono text-[11px]">
          <span
            title={
              baseIsNonDefault
                ? `Merging into ${liveBase}, not the default branch (${defaultBranch})`
                : undefined
            }
            className={cn(
              'rounded-[3px] px-1.5 py-px',
              baseIsNonDefault
                ? 'bg-amber-400/20 text-amber-700 ring-1 ring-inset ring-amber-500/40 dark:text-amber-300'
                : 'bg-muted text-foreground',
            )}
          >
            {liveBase}
          </span>
          <span className="font-sans text-muted-foreground/60">←</span>
          <CopyBranchBadge branch={liveHead} />
        </div>

        <Separator orientation="vertical" className="h-3" />

        {/* Reviewer cluster */}
        <div className="inline-flex items-center gap-1.5">
          {reviewerStates.length === 0 ? (
            <>
              <span className="text-muted-foreground/70">No reviewers</span>
              <AddReviewerChip
                first
                prHtmlUrl={pr?.html_url}
                owner={owner}
                repo={repo}
                canManage={canManageReviewers}
                excludeLogins={reviewerStates.map((r) => r.login)}
                onPick={(login) => void reviewerMgmt.requestReviewer(login)}
              />
            </>
          ) : (
            <>
              {reviewerStates.map((r, i) => (
                <ReviewerChipHover
                  key={r.login}
                  row={r}
                  first={i === 0}
                  canManage={canManageReviewers}
                  reviewerMgmt={reviewerMgmt}
                  onJumpToComment={onJumpToComment}
                />
              ))}
              <AddReviewerChip
                prHtmlUrl={pr?.html_url}
                owner={owner}
                repo={repo}
                canManage={canManageReviewers}
                excludeLogins={reviewerStates.map((r) => r.login)}
                onPick={(login) => void reviewerMgmt.requestReviewer(login)}
              />
            </>
          )}
        </div>

        <Separator orientation="vertical" className="h-3" />

        {/* Checks hover card */}
        {checkCounts.fail > 0 ||
        checkCounts.pass > 0 ||
        checkCounts.pending > 0 ? (
          <ChecksHoverCard
            checks={checksQuery.data?.checks ?? []}
            fail={checkCounts.fail}
            pass={checkCounts.pass}
            pending={checkCounts.pending}
            historical={checksHistorical}
            onJumpToMergeBox={onJumpToMergeBox}
          />
        ) : (
          <span className="text-muted-foreground/70">No checks</span>
        )}

        <Separator orientation="vertical" className="h-3" />

        {/* Diff stats */}
        <span className="font-mono">
          <span
            className={
              checksHistorical ? 'text-muted-foreground' : 'text-emerald-600'
            }
          >
            +{liveAdditions.toLocaleString()}
          </span>{' '}
          <span
            className={
              checksHistorical ? 'text-muted-foreground' : 'text-destructive'
            }
          >
            −{liveDeletions.toLocaleString()}
          </span>{' '}
          <span className="text-muted-foreground">
            · {liveFiles} file{liveFiles === 1 ? '' : 's'}
          </span>
        </span>

        {/* Age + sync — right-aligned */}
        <span
          className="ml-auto inline-flex cursor-default items-center gap-2 text-[12px] text-muted-foreground/80"
          title={
            pr
              ? `PR opened · ${exactDate(pr.created_at)}\nLast synced · ${exactDate(pr.updated_at)}`
              : undefined
          }
        >
          <span className="inline-flex items-center gap-1">
            <GitPullRequestCreateArrowIcon className="size-3.5" />
            {liveOpenedAt} ago
          </span>
          <span className="text-muted-foreground/40">·</span>
          <span className="inline-flex items-center gap-1">
            <CloudSyncIcon className="size-3.5" />
            {liveSyncedAt} ago
          </span>
        </span>

      </div>
    </div>
  );
}

// ── ChecksHoverCard ───────────────────────────────────────────────
// Hover card showing CI check status in the status band. Replaces the
// old Checks tab — check counts now surface inline in the header.

type CheckItem = {
  name: string;
  bucket: 'fail' | 'pass' | 'pending' | 'neutral';
  url?: string | null;
};

export function ChecksHoverCard({
  checks,
  fail,
  pass,
  pending,
  historical,
  onJumpToMergeBox,
  compact = false,
}: {
  checks: CheckItem[];
  fail: number;
  pass: number;
  pending: number;
  /** Merged/closed → mute alarm colours. */
  historical?: boolean;
  /** Scroll to the in-app MergeBox (foot of Conversation) instead of GitHub. */
  onJumpToMergeBox?: () => void;
  /** Compact header: show only the at-risk signal (✗N, or a single ✓ when
   * all-green); the pending + passing detail stays in the hover card. */
  compact?: boolean;
}) {
  const failing = checks.filter((c) => c.bucket === 'fail');
  const pendingChecks = checks.filter((c) => c.bucket === 'pending');
  // neutral checks are counted as pass by countRollup — include them here too.
  const passing = checks.filter(
    (c) => c.bucket === 'pass' || c.bucket === 'neutral',
  );
  const PASS_SHOWN = 4;
  const extraPass = Math.max(0, passing.length - PASS_SHOWN);
  return (
    <HoverCard openDelay={200} closeDelay={100}>
      <HoverCardTrigger asChild>
        <button
          type="button"
          className="inline-flex items-center gap-1.5 text-[12px] transition-colors hover:text-foreground"
        >
          {fail > 0 && (
            <span
              className={`inline-flex items-center gap-0.5 ${historical ? 'text-muted-foreground' : 'text-destructive'}`}
            >
              <XCircleIcon className="size-3.5" />
              <b className="font-semibold">{fail}</b>
            </span>
          )}
          {/* All-green signal in the compact bar (count + pending hidden). */}
          {compact && fail === 0 && pass > 0 && (
            <CheckCircle2Icon
              className={`size-3.5 ${historical ? 'text-muted-foreground' : 'text-emerald-600'}`}
            />
          )}
          {!compact && pending > 0 && (
            <span
              className={`inline-flex items-center gap-0.5 ${historical ? 'text-muted-foreground' : 'text-amber-500'}`}
            >
              <ClockIcon className="size-3.5" />
              {pending}
            </span>
          )}
          {!compact && pass > 0 && (
            <span
              className={`inline-flex items-center gap-0.5 ${historical ? 'text-muted-foreground' : 'text-emerald-600'}`}
            >
              <CheckCircle2Icon className="size-3.5" />
              {pass}
            </span>
          )}
        </button>
      </HoverCardTrigger>
      <HoverCardContent align="start" sideOffset={8} className="w-80 p-0">
        <div className="border-b px-3 py-2.5 text-[12px] font-semibold">
          Checks
        </div>
        <div className="max-h-[280px] overflow-auto py-1">
          {failing.map((c) => (
            <CheckRow key={c.name} check={c} historical={historical} />
          ))}
          {pendingChecks.map((c) => (
            <CheckRow key={c.name} check={c} historical={historical} />
          ))}
          {passing.slice(0, PASS_SHOWN).map((c) => (
            <CheckRow key={c.name} check={c} historical={historical} />
          ))}
          {extraPass > 0 && (
            <div className="px-3 py-1.5 text-[11.5px] text-muted-foreground">
              +{extraPass} more passed
            </div>
          )}
          {checks.length === 0 && (
            <div className="px-3 py-2 text-[12px] text-muted-foreground">
              Loading checks…
            </div>
          )}
        </div>
        {onJumpToMergeBox && (
          <div className="border-t px-3 py-2">
            <Button
              variant="outline"
              size="sm"
              className="w-full"
              onClick={() => onJumpToMergeBox()}
            >
              View all checks
            </Button>
          </div>
        )}
      </HoverCardContent>
    </HoverCard>
  );
}

function CheckRow({
  check,
  historical,
}: {
  check: CheckItem;
  historical?: boolean;
}) {
  const isFail = check.bucket === 'fail';
  const { Icon, color } = checkBucketIcon(check.bucket, historical);
  return (
    <div
      className={`flex items-center gap-2 px-3 py-1.5 text-[12px] ${isFail && !historical ? 'bg-destructive/5' : ''}`}
    >
      <Icon className={`size-3.5 shrink-0 ${color}`} />
      <span
        className={`flex-1 truncate ${isFail && !historical ? 'font-medium' : 'text-muted-foreground'}`}
      >
        {check.name}
      </span>
      {check.url && isFail && !historical && (
        <a
          href={check.url}
          target="_blank"
          rel="noopener noreferrer"
          className="shrink-0 text-[11px] text-primary hover:underline"
        >
          Details
        </a>
      )}
    </div>
  );
}

/** Inline "ref pill" used in the "wants to merge X into <base> from
 * <head>" sentence — mono font, subtle background. */
function RefBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="mx-1 rounded-[3px] bg-muted px-1.5 py-px font-mono text-[11.5px] text-foreground">
      {children}
    </span>
  );
}

/** The head-branch ref pill, made fully clickable to copy. Same chip
 * styling as RefBadge, but the whole chip is a button and carries an
 * always-visible copy icon inside it; clicking anywhere copies the raw
 * branch ref (sonner toast + a 1.5s checkmark). Mirrors CopyPathButton's
 * copied-flag mechanics. Falls back to a plain RefBadge for the "—"
 * placeholder (nothing to copy). */
export function CopyBranchBadge({ branch }: { branch: string }) {
  const [copied, setCopied] = useState(false);

  if (branch === '—') return <RefBadge>{branch}</RefBadge>;

  const onCopy = async () => {
    try {
      await navigator.clipboard.writeText(branch);
      setCopied(true);
      toast.success('Branch name copied to clipboard');
      setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error('Could not copy to clipboard');
    }
  };

  return (
    <button
      type="button"
      onClick={onCopy}
      title={copied ? 'Copied' : `Copy branch name ${branch}`}
      aria-label={copied ? 'Copied' : `Copy branch name ${branch}`}
      className="mx-1 inline-flex cursor-pointer items-center gap-1 rounded-[3px] bg-muted px-1.5 py-px align-middle font-mono text-[11.5px] text-foreground transition-colors hover:bg-muted-foreground/20"
    >
      {branch}
      <CopyIconMorph
        copied={copied}
        successIcon={
          <CheckIcon className="size-3 shrink-0 text-emerald-600 dark:text-emerald-300" />
        }
        idleIcon={<CopyIcon className="size-3 shrink-0 text-muted-foreground" />}
      />
    </button>
  );
}

function MetaItem({
  label,
  children,
  mono,
}: {
  label: string;
  children: React.ReactNode;
  mono?: boolean;
}) {
  return (
    <div
      className={`flex items-center gap-1.5 text-[12px] text-foreground ${
        mono ? 'font-mono' : ''
      }`}
    >
      <span className="mr-0.5 font-sans text-[11px] text-muted-foreground/80">
        {label}
      </span>
      <span className="inline-flex items-center gap-1.5">{children}</span>
    </div>
  );
}

type ReviewerState = 'pending' | 'approved' | 'changes' | 'commented';

/** Per-reviewer aggregate used by both PRHeader's chip row and
 * DescriptionTab's right-rail list. `lastReview` is the latest body-
 * bearing review by that reviewer — surfaced in the HoverCard as a
 * preview so the reviewer doesn't have to click through. */
export interface ReviewerStateRow {
  login: string;
  state: ReviewerState;
  /** GitHub avatar URL — sourced from whichever endpoint surfaced the
   * user first (requested_reviewers vs reviews). Optional only so old
   * cached payloads without an avatar still render. */
  avatarUrl?: string;
  /** Number of body-bearing reviews this user has left. GitHub's REST
   * /reviews endpoint counts every submit as one review, regardless of
   * how many line-comments are attached — so this is a "review-event"
   * count, not an "inline comment" count. We surface it in the chip
   * HoverCard + sidebar as the headline activity number; per-line
   * counts would need /pulls/{n}/comments aggregated by user_id which
   * is a separate concern. */
  commentCount: number;
  /** Database id of this user's latest submitted review — the review a
   * "Dismiss" action targets (#19). Undefined for reviewers who only
   * appear via requested_reviewers (no review yet). */
  reviewId?: number;
  lastReview?: {
    body: string;
    submittedAt: string;
    htmlUrl: string;
    /** When the latest activity is a line-anchored inline review
     * comment, these carry its diff location so the HoverCard's view
     * action can jump to + flash-pulse it in the Changes tab (AFK plan
     * 11) instead of bouncing to GitHub. Undefined for review-summary
     * activity (no line anchor). */
    path?: string;
    line?: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
    commentId?: string;
    /** Database id of the review whose summary body this is. Set only
     * for PR-level (no-path) review summaries, so the HoverCard's view
     * action can jump to + flash it in the Conversation timeline. */
    reviewId?: number;
  };
}

/** Roll up requested reviewers + every review into the per-user
 * latest verdict. Order:
 *   1. Anyone who submitted APPROVED / CHANGES_REQUESTED (latest wins)
 *   2. Anyone who only commented
 *   3. Requested reviewers who haven't acted yet (pending)
 *
 * The PR author is excluded — GitHub treats their own self-reviews as
 * conversational comments, not as a reviewer verdict, and the
 * Reviewers field on github.com mirrors that. Including the author
 * would double-count them with the explicit "Author" meta-item. */
// Per-user accumulators built up across reviews, inline comments, and
// requested reviewers. Mutated in place by the three apply* helpers below.
interface ReviewerAccum {
  byUser: Map<string, ReviewerState>;
  lastReviewByUser: Map<string, ReviewerStateRow['lastReview']>;
  avatarByUser: Map<string, string>;
  commentCountByUser: Map<string, number>;
  reviewIdByUser: Map<string, number>;
}

// Apply submitted reviews oldest → newest, so the latest verdict wins and
// the last body-bearing review is the one kept for the HoverCard preview.
function applyReviews(
  acc: ReviewerAccum,
  reviews: GHReview[],
  authorLogin: string,
): void {
  const sorted = [...reviews]
    .filter((r) => r.user && r.submitted_at && r.user.login !== authorLogin)
    .sort(
      (a, b) =>
        new Date(a.submitted_at!).getTime() -
        new Date(b.submitted_at!).getTime(),
    );
  sorted.forEach((r) => {
    const login = r.user!.login;
    if (r.state === 'APPROVED') acc.byUser.set(login, 'approved');
    else if (r.state === 'CHANGES_REQUESTED') acc.byUser.set(login, 'changes');
    else if (r.state === 'COMMENTED' && !acc.byUser.has(login)) {
      acc.byUser.set(login, 'commented');
    }
    // Latest submitted review wins (oldest → newest) — the one a Dismiss
    // action targets.
    acc.reviewIdByUser.set(login, r.id);
    if (r.user!.avatar_url && !acc.avatarByUser.has(login)) {
      acc.avatarByUser.set(login, r.user!.avatar_url);
    }
    // Track the latest body-bearing review for the HoverCard preview; the
    // comment count tracks the same set ("spoke up N times").
    if (r.body && r.body.trim() && r.submitted_at) {
      acc.lastReviewByUser.set(login, {
        body: r.body,
        submittedAt: r.submitted_at,
        htmlUrl: r.html_url,
        reviewId: r.id,
      });
      acc.commentCountByUser.set(
        login,
        (acc.commentCountByUser.get(login) ?? 0) + 1,
      );
    }
  });
}

// Layer in inline review comments. Overwrites `lastReviewByUser` only when
// the inline comment is strictly newer than the stored summary — a
// reviewer's most recent thought wins regardless of source.
function applyReviewComments(
  acc: ReviewerAccum,
  reviewComments: GHReviewComment[],
  authorLogin: string,
): void {
  const sortedComments = [...reviewComments]
    .filter((c) => c.user && c.user.login !== authorLogin)
    .sort(
      (a, b) =>
        new Date(a.created_at).getTime() - new Date(b.created_at).getTime(),
    );
  sortedComments.forEach((c) => {
    const login = c.user.login;
    // Inline comments alone can't flip the verdict, but they're enough to
    // call an otherwise-pending reviewer "Commented".
    if (!acc.byUser.has(login)) acc.byUser.set(login, 'commented');
    if (c.user.avatar_url && !acc.avatarByUser.has(login)) {
      acc.avatarByUser.set(login, c.user.avatar_url);
    }
    if (!c.body || c.body.trim() === '') return;
    const existing = acc.lastReviewByUser.get(login);
    const existingTs = existing?.submittedAt
      ? new Date(existing.submittedAt).getTime()
      : -Infinity;
    const newTs = new Date(c.created_at).getTime();
    if (newTs > existingTs) {
      // This inline comment is the reviewer's most recent activity, so
      // carry its diff anchor (path / line / side) — that's what lets the
      // HoverCard's "View comment" action scroll to + flash-pulse the exact
      // line in the Changes tab. `line ?? original_line` survives the head
      // moving under an outdated comment.
      acc.lastReviewByUser.set(login, {
        body: c.body,
        submittedAt: c.created_at,
        htmlUrl: c.html_url,
        path: c.path,
        line: c.line ?? c.original_line,
        diffSide: c.side,
        commentId: String(c.id),
      });
    }
    acc.commentCountByUser.set(
      login,
      (acc.commentCountByUser.get(login) ?? 0) + 1,
    );
  });
}

// Add requested reviewers who haven't acted yet (pending).
function applyRequestedReviewers(
  acc: ReviewerAccum,
  requested: GHPullRequest['requested_reviewers'],
  authorLogin: string,
): void {
  requested.forEach((rr) => {
    if (rr.login === authorLogin) return;
    if (!acc.byUser.has(rr.login)) acc.byUser.set(rr.login, 'pending');
    if (rr.avatar_url && !acc.avatarByUser.has(rr.login)) {
      acc.avatarByUser.set(rr.login, rr.avatar_url);
    }
  });
}

export function collectReviewerStates(
  pr: GHPullRequest | undefined,
  reviews: GHReview[],
  /** Line-anchored review comments. Many reviewers leave only inline
   * comments (no review-summary body), so factoring these in is the
   * only way the HoverCard's last-comment preview shows anything for
   * those folks. Optional so callers that don't yet have the data
   * (legacy paths) keep working with summary-only previews. */
  reviewComments: GHReviewComment[] = [],
): ReviewerStateRow[] {
  if (!pr) return [];
  const authorLogin = pr.user.login;
  const acc: ReviewerAccum = {
    byUser: new Map(),
    lastReviewByUser: new Map(),
    avatarByUser: new Map(),
    commentCountByUser: new Map(),
    reviewIdByUser: new Map(),
  };
  applyReviews(acc, reviews, authorLogin);
  applyReviewComments(acc, reviewComments, authorLogin);
  applyRequestedReviewers(acc, pr.requested_reviewers, authorLogin);
  return Array.from(acc.byUser.entries()).map(([login, state]) => ({
    login,
    state,
    avatarUrl: acc.avatarByUser.get(login),
    commentCount: acc.commentCountByUser.get(login) ?? 0,
    reviewId: acc.reviewIdByUser.get(login),
    lastReview: acc.lastReviewByUser.get(login),
  }));
}

// Tone-box config per reviewer state — surfaced inside the HoverCard
// and via the avatar's bottom-right status dot.
const REVIEWER_STATE_CFG: Record<
  ReviewerState,
  {
    dotClass: string;
    label: string;
    toneBox: string;
    ringClass: string;
  }
> = {
  approved: {
    dotClass: 'bg-emerald-600',
    label: 'Approved this PR',
    toneBox:
      'border-emerald-200 bg-emerald-50/80 text-emerald-800 dark:border-emerald-700/60 dark:bg-emerald-900/30 dark:text-emerald-200',
    ringClass: 'ring-emerald-500/40',
  },
  changes: {
    dotClass: 'bg-destructive',
    label: 'Requested changes',
    toneBox:
      'border-red-200 bg-red-50/80 text-red-800 dark:border-red-700/60 dark:bg-red-900/30 dark:text-red-200',
    ringClass: 'ring-destructive/40',
  },
  pending: {
    dotClass: 'bg-amber-500',
    label: 'Review requested',
    toneBox:
      'border-amber-200 bg-amber-50/80 text-amber-800 dark:border-amber-700/60 dark:bg-amber-900/30 dark:text-amber-200',
    ringClass: 'ring-amber-500/40',
  },
  commented: {
    dotClass: 'bg-muted-foreground/70',
    label: 'Left a comment',
    toneBox:
      'border-border bg-muted/60 text-muted-foreground',
    ringClass: 'ring-foreground/30',
  },
};

/** Legacy chip — kept for callers that don't need the HoverCard (the
 * DescriptionTab right rail today). Now accepts an avatarUrl so the
 * sidebar list of reviewers shows real GitHub photos rather than
 * monogram fallbacks. */
export function ReviewerChip({
  name,
  state,
  avatarUrl,
  size = 4,
}: {
  name: string;
  state: ReviewerState;
  avatarUrl?: string;
  /** Avatar size class number — 4 for the inline header chip (16px),
   * 5 for the rail row (20px). */
  size?: 4 | 5;
}) {
  const cfg = REVIEWER_STATE_CFG[state];
  return (
    <span className="relative inline-flex items-center" title={`${name}: ${state}`}>
      <Avatar className={size === 5 ? 'size-5' : 'size-4'}>
        {avatarUrl && <AvatarImage src={avatarUrl} alt={name} />}
        <AvatarFallback className={size === 5 ? 'text-[9px]' : 'text-[8px]'}>
          {name.slice(0, 2).toUpperCase()}
        </AvatarFallback>
      </Avatar>
      <span
        className={`absolute -bottom-0.5 -right-0.5 size-2 rounded-full ring-[1.5px] ring-background ${cfg.dotClass}`}
      />
    </span>
  );
}

/** Reviewer chip with shadcn HoverCard — name, role, status tone-box,
 * last-comment preview, contextual actions. Design parity: shadcn-app
 * jsx · ShadcnReviewerChipV2. Avatars overlap via -ml-1.5; hovered chip
 * lifts via ring + scale.
 *
 * Note: GitHub's REST API doesn't return a structured "role" (code
 * owner / requested reviewer / etc.) — we infer from the state.
 * Surfacing a richer role would need a CODEOWNERS lookup, which is a
 * separate fetch. v1 ships state-derived labels and keeps the comment
 * preview honest about what data we actually have. */
export function ReviewerChipHover({
  row,
  first = false,
  canManage = false,
  reviewerMgmt,
  onJumpToComment,
}: {
  row: ReviewerStateRow;
  first?: boolean;
  /** WRITE+ — gates the re-request / remove / dismiss actions. */
  canManage?: boolean;
  reviewerMgmt?: ReviewerManagement;
  /** AFK plan 11 — switches to the Changes tab and scrolls to +
   * flash-pulses the reviewer's line-anchored comment in the diff.
   * Replaces the old GitHub view links. */
  onJumpToComment?: (target: {
    // Line-anchored inline comment → jump in the diff (Changes tab).
    path?: string;
    line?: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
    // PR-level review summary (no diff anchor) → jump to it in the
    // Conversation timeline by review id.
    reviewId?: number;
  }) => void;
}) {
  const cfg = REVIEWER_STATE_CFG[row.state];
  const [dismissOpen, setDismissOpen] = useState(false);
  const removing = reviewerMgmt?.pending === `remove:${row.login}`;
  const rerequesting = reviewerMgmt?.pending === `request:${row.login}`;
  const dismissing =
    row.reviewId != null &&
    reviewerMgmt?.pending === `dismiss:${row.reviewId}`;
  // Whether the footer has anything to render. In contexts without
  // reviewer-management or an in-app jump target (e.g. the PR-list row),
  // none of the actions apply — gate the whole bordered strip so it
  // doesn't render as an empty bar under the preview.
  const showPendingMgmt =
    row.state === 'pending' && canManage && !!reviewerMgmt;
  const showJump =
    !!onJumpToComment &&
    (!!row.lastReview?.path || row.lastReview?.reviewId != null);
  const showDismiss =
    row.state === 'changes' &&
    canManage &&
    !!reviewerMgmt &&
    row.reviewId != null;
  const hasActions = showPendingMgmt || showJump || showDismiss;
  return (
    <HoverCard openDelay={120} closeDelay={80}>
      <HoverCardTrigger asChild>
        <button
          type="button"
          className={`group/chip relative inline-flex items-center rounded-full outline-none transition-[transform,box-shadow] hover:z-10 hover:scale-110 focus-visible:z-10 focus-visible:scale-110 focus-visible:ring-2 focus-visible:ring-ring ${
            first ? '' : '-ml-1.5'
          }`}
          aria-label={`${row.login} — ${cfg.label.toLowerCase()}`}
        >
          <Avatar
            className={`size-5 ring-2 ring-background group-hover/chip:ring-2 ${cfg.ringClass}`}
          >
            {row.avatarUrl && (
              <AvatarImage src={row.avatarUrl} alt={row.login} />
            )}
            <AvatarFallback className="text-[9px]">
              {row.login.slice(0, 2).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <span
            className={`absolute -bottom-0.5 -right-0.5 size-2 rounded-full ring-[1.5px] ring-background ${cfg.dotClass}`}
          />
        </button>
      </HoverCardTrigger>
      <HoverCardContent align="start" sideOffset={10} className="w-72 p-0">
        {/* Header */}
        <div className="flex items-start gap-2.5 border-b px-3.5 py-3">
          <Avatar className="size-7">
            {row.avatarUrl && <AvatarImage src={row.avatarUrl} alt={row.login} />}
            <AvatarFallback className="text-[10px]">
              {row.login.slice(0, 2).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <div className="min-w-0 flex-1">
            <div className="truncate text-[13px] font-semibold leading-tight">
              {row.login}
            </div>
            <div className="mt-0.5 text-[11px] text-muted-foreground">
              {reviewerRoleLabel(row.state)}
            </div>
          </div>
        </div>

        {/* Tone box — current status + age */}
        <div className={`mx-3 mt-3 rounded-md border px-2.5 py-2 text-[11.5px] ${cfg.toneBox}`}>
          <div className="flex items-center gap-1.5 font-medium">
            <span className={`size-1.5 rounded-full ${cfg.dotClass}`} />
            <span>{cfg.label}</span>
          </div>
          {row.lastReview?.submittedAt && (
            <div className="mt-0.5 text-[11px] opacity-80" title={exactDate(row.lastReview.submittedAt)}>
              {row.state === 'pending'
                ? `Requested ${humanAge(row.lastReview.submittedAt)} ago`
                : `Reviewed ${humanAge(row.lastReview.submittedAt)} ago`}
            </div>
          )}
          {row.commentCount > 0 && (
            <div
              className="mt-0.5 inline-flex items-center gap-1 text-[11px] opacity-80"
              aria-label={`${row.commentCount} comment${row.commentCount === 1 ? '' : 's'}`}
              title={`${row.commentCount} comment${row.commentCount === 1 ? '' : 's'}`}
            >
              <MessageCircleIcon className="size-3" aria-hidden />
              <span className="tabular-nums">{row.commentCount}</span>
            </div>
          )}
        </div>

        {/* Last-comment preview — only if we have one */}
        {row.lastReview?.body && (
          <div className="mx-3 mt-2.5 rounded-md border bg-muted/40 p-2.5 text-[11.5px] leading-snug text-foreground">
            <div className="mb-1 text-[10px] uppercase tracking-wider text-muted-foreground/80">
              Last comment
            </div>
            <div className="line-clamp-3 whitespace-pre-line">{row.lastReview.body.trim()}</div>
          </div>
        )}

        {/* Actions */}
        {hasActions && (
        <div className="flex flex-wrap items-center gap-1.5 border-t px-3 py-2.5 mt-3">
          {row.state === 'pending' && canManage && reviewerMgmt && (
            <>
              <Button
                variant="outline"
                size="sm"
                disabled={rerequesting}
                onClick={() => void reviewerMgmt.requestReviewer(row.login)}
                title="Re-request a review"
              >
                {rerequesting ? '…' : 'Re-request'}
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={removing}
                onClick={() => void reviewerMgmt.removeReviewer(row.login)}
                title="Remove from reviewers"
              >
                {removing ? '…' : 'Remove'}
              </Button>
            </>
          )}
          {/* In-app "view" action (AFK plan 11). Two jump targets:
              - line-anchored inline comment (lastReview.path) → switch to
                the Changes tab + scroll/flash that line in the diff.
              - PR-level review summary (no path, but reviewId set) →
                switch to the Conversation tab + scroll/flash that review
                in the timeline.
              Either way it's in-app, no GitHub navigation. A row with
              neither (e.g. a still-pending requested reviewer) omits the
              action entirely. */}
          {onJumpToComment &&
            (row.lastReview?.path || row.lastReview?.reviewId != null) && (
              <Button
                variant="outline"
                size="sm"
                title={
                  row.lastReview?.path
                    ? 'Jump to this comment in the diff'
                    : 'Jump to this comment in the conversation'
                }
                onClick={() =>
                  onJumpToComment(
                    row.lastReview!.path
                      ? {
                          path: row.lastReview!.path,
                          line: row.lastReview!.line ?? null,
                          diffSide: row.lastReview!.diffSide ?? null,
                        }
                      : { reviewId: row.lastReview!.reviewId! },
                  )
                }
              >
                {row.lastReview?.path ? (
                  <FileDiffIcon className="mr-1 size-3" />
                ) : (
                  <MessageCircleIcon className="mr-1 size-3" />
                )}
                {viewActionLabel(row.state)}
              </Button>
            )}
          {row.state === 'changes' &&
            canManage &&
            reviewerMgmt &&
            row.reviewId != null && (
              <Button
                variant="ghost"
                size="sm"
                disabled={dismissing}
                onClick={() => setDismissOpen(true)}
                title="Dismiss this review"
              >
                {dismissing ? '…' : 'Dismiss'}
              </Button>
            )}
          <div className="flex-1" />
        </div>
        )}
        {/* No footer → still pad the bottom so the card's last block
            clears the edge symmetrically with the 12px side gutters. */}
        {!hasActions && <div className="h-3" />}
      </HoverCardContent>
      {row.reviewId != null && reviewerMgmt && (
        <ConfirmModal
          open={dismissOpen}
          onOpenChange={setDismissOpen}
          tone="neutral"
          title={`Dismiss ${row.login}'s review?`}
          description="This clears the review's blocking status. GitHub requires a reason, which is recorded on the pull request."
          reasonRequired
          reasonLabel="Reason"
          reasonPlaceholder="Why are you dismissing this review?"
          confirmLabel="Dismiss review"
          pending={dismissing}
          onConfirm={(reason) => {
            if (!reason) return;
            void reviewerMgmt
              .dismiss(row.reviewId!, reason)
              .then(() => setDismissOpen(false));
          }}
        />
      )}
    </HoverCard>
  );
}

/** Label for the in-diff "view" action button, by reviewer state.
 * Mirrors the wording the old GitHub links used (approved → "View
 * review", changes → "View thread", commented → "View comment"). */
function viewActionLabel(state: ReviewerState): string {
  switch (state) {
    case 'approved':
      return 'View review';
    case 'changes':
      return 'View thread';
    default:
      return 'View comment';
  }
}

function reviewerRoleLabel(state: ReviewerState): string {
  switch (state) {
    case 'approved':
      return 'Approver';
    case 'changes':
      return 'Reviewer · requested changes';
    case 'commented':
      return 'Reviewer';
    case 'pending':
      return 'Requested reviewer';
  }
}

/** Dashed "+ Add reviewer" chip. For WRITE+ viewers it opens the
 * in-app reviewer picker (#18) to request a reviewer directly; for
 * everyone else it falls back to opening the PR on GitHub (no 403 — the
 * link just navigates). */
export function AddReviewerChip({
  first = false,
  prHtmlUrl,
  owner,
  repo,
  canManage = false,
  excludeLogins = [],
  onPick,
}: {
  first?: boolean;
  prHtmlUrl?: string;
  owner?: string;
  repo?: string;
  /** WRITE+ — enables the in-app picker instead of the GitHub bounce. */
  canManage?: boolean;
  excludeLogins?: string[];
  onPick?: (login: string) => void;
}) {
  const className = `inline-flex size-5 cursor-pointer items-center justify-center rounded-full border border-dashed border-input bg-card text-muted-foreground transition-colors hover:border-foreground/40 hover:text-foreground ${
    first ? '' : '-ml-1.5'
  }`;

  // WRITE+ → in-app picker.
  if (canManage && owner && repo && onPick) {
    return (
      <ReviewerPicker
        owner={owner}
        repo={repo}
        excludeLogins={excludeLogins}
        onPick={onPick}
      >
        <button
          type="button"
          title="Request a reviewer"
          aria-label="Request a reviewer"
          className={className}
        >
          <PlusIcon className="size-3" />
        </button>
      </ReviewerPicker>
    );
  }

  if (!prHtmlUrl) {
    return (
      <span
        title="Add reviewer (open PR on GitHub once the link loads)"
        className={className.replace('cursor-pointer', 'cursor-default')}
      >
        <PlusIcon className="size-3" />
      </span>
    );
  }
  return (
    <a
      href={markGithubPassthrough(prHtmlUrl)}
      target="_blank"
      rel="noopener noreferrer"
      title="You don't have write access to this repo — request a reviewer on GitHub"
      aria-label="Request a reviewer on GitHub"
      className={className}
    >
      <PlusIcon className="size-3" />
    </a>
  );
}

/** GitHub label — the hex colour comes from the API and seeds three
 * derivatives via `color-mix`. The inline style is the one legitimate
 * runtime-dynamic case in this file. */
export function Label({ color, text }: { color: string; text: string }) {
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-[10px] border px-2 py-px text-[11px] font-medium"
      style={{
        background: `color-mix(in oklch, ${color} 18%, white)`,
        borderColor: `color-mix(in oklch, ${color} 35%, white)`,
        color: `color-mix(in oklch, ${color} 60%, black)`,
      }}
    >
      <span
        className="size-1.5 rounded-full"
        style={{ background: color }}
      />
      {text}
    </span>
  );
}


/** Full, locale-formatted timestamp for the on-hover title on the
 * relative "opened/synced … ago" labels — e.g. "May 1, 2026, 3:24 PM". */
function exactDate(iso: string): string {
  return new Date(iso).toLocaleString(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  });
}

