// Local Review Comment staleness algorithm.
//
// ADR 0012 Phase 4. Pure-function module — given a comment's anchor
// metadata and the current file contents, classify it as:
//   - fresh: line at `path:line` still matches `contentSnippet`
//            (whitespace-trimmed)
//   - moved: snippet found at a *different* line in the current file
//   - stale: snippet not found anywhere in the current file (the line
//            was edited substantially, or the file was renamed / removed)
//
// The current-file content is supplied by the caller — we don't reach
// for the bridge here. That keeps this module synchronous + trivially
// testable; callers (the surface) already maintain a per-file content
// map for the @pierre/diffs render and pass the matching entry in.
//
// File-level comments (`line === null`, `contentSnippet === null`) are
// classified by path presence only: file exists → fresh, file missing
// → stale. No "moved" state for file-level — a rename surfaces as
// stale + the user re-attaches (rename-following is explicitly out of
// scope per the ADR).

import type { LocalReviewComment } from './localReviewComments';
import { WORKING_TREE_ANCHOR } from './localReviewComments';

type StalenessState = 'fresh' | 'moved' | 'stale';

export type StalenessResult =
  | { state: 'fresh' }
  /** Snippet matched a different line than originally anchored.
   * `wasLine` is the comment's original anchor line, `nowLine` is
   * where the snippet currently lives. The chip surfaces both so the
   * user can confirm intent before reading the comment. */
  | { state: 'moved'; wasLine: number; nowLine: number }
  | { state: 'stale' };

/**
 * Classify a comment's staleness against the current file content.
 *
 * @param comment   - the saved comment with its anchor metadata
 * @param currentHeadSha
 *                  - HEAD SHA of the worktree's checked-out branch.
 *                    For comments anchored at a real commit, this is
 *                    compared against `comment.anchorSha` for the
 *                    trivial fresh check. For WORKING_TREE comments
 *                    the SHA is irrelevant (snippet check always runs).
 * @param fileContent
 *                  - the current text of `comment.path` in the file
 *                    being shown to the user. `null` means the file
 *                    doesn't exist at HEAD / working tree (deleted or
 *                    not yet created). Renamed files are handled by
 *                    the caller — `null` here marks them stale.
 */
export function computeStaleness(
  comment: LocalReviewComment,
  currentHeadSha: string,
  fileContent: string | null,
): StalenessResult {
  // File-level comments: presence-only check.
  if (comment.line === null || comment.contentSnippet === null) {
    return fileContent === null ? { state: 'stale' } : { state: 'fresh' };
  }

  // Path missing entirely → stale. (Rename surfaces as stale per the
  // ADR's out-of-scope note on `git log --follow`.)
  if (fileContent === null) return { state: 'stale' };

  // Trivial fresh: real-SHA anchor and the SHA hasn't moved.
  // WORKING_TREE anchors skip this — every keystroke could move them.
  if (
    comment.anchorSha !== WORKING_TREE_ANCHOR &&
    comment.anchorSha === currentHeadSha
  ) {
    return { state: 'fresh' };
  }

  const snippet = comment.contentSnippet.trimEnd();
  if (snippet.length === 0) {
    // Empty snippet (e.g. comment on a blank line) — fall back to
    // line-number presence. If the file still has at least `line`
    // lines, treat as fresh; otherwise stale.
    const lineCount = fileContent.split('\n').length;
    return lineCount >= comment.line ? { state: 'fresh' } : { state: 'stale' };
  }

  // Pull the current text at the original line, normalising for
  // 1-based indexing.
  const lines = fileContent.split('\n');
  const current = lines[comment.line - 1];

  if (current !== undefined && current.trimEnd() === snippet) {
    return { state: 'fresh' };
  }

  // Snippet didn't match at the original line. Search the rest of the file
  // for an exact whitespace-trimmed match (1-based line for display).
  const movedTo = findMovedLine(lines, snippet, comment.line - 1);
  return movedTo === null
    ? { state: 'stale' }
    : { state: 'moved', wasLine: comment.line, nowLine: movedTo };
}

// First line (1-based) whose whitespace-trimmed text equals `snippet`,
// skipping the comment's original line; null when nothing matches.
function findMovedLine(
  lines: string[],
  snippet: string,
  skipIndex: number,
): number | null {
  const idx = lines.findIndex(
    (l, i) => i !== skipIndex && l.trimEnd() === snippet,
  );
  return idx === -1 ? null : idx + 1;
}

/** Build the snippet stored on a comment from a raw line of text.
 * Trims trailing whitespace and caps at 200 chars (ADR 0012 Phase 4).
 * Returns `null` for file-level (caller should pass `null` line text). */
function snippetFromLine(line: string | null): string | null {
  if (line === null) return null;
  const trimmed = line.trimEnd();
  if (trimmed.length === 0) return trimmed; // preserve emptiness as signal
  return trimmed.length > 200 ? trimmed.slice(0, 200) : trimmed;
}
