// CodeMirror 6 transaction helpers that back the GhComposer toolbar +
// markdown keyboard shortcuts. These replace the old textarea
// `wrap(prefix, suffix)` / `insertLinePrefix(prefix)` string-splicing +
// `requestAnimationFrame` caret juggling with real editor transactions:
// selection is preserved through the change mapping, and focus stays in
// the editor without any rAF dance.

import { EditorSelection } from '@codemirror/state';
import { EditorView } from '@codemirror/view';

/**
 * Wrap each selection range in `before`/`after`. When a range is empty
 * we insert `placeholder` between the markers and leave it selected so
 * the user can overtype it (matching the old textarea behaviour). When
 * text is selected it's wrapped and re-selected inside the markers.
 */
export function wrapSelection(
  view: EditorView,
  before: string,
  after: string,
  placeholder = '',
): void {
  const { state } = view;
  const changes = state.changeByRange((range) => {
    const selected = state.sliceDoc(range.from, range.to);
    const inner = selected.length > 0 ? selected : placeholder;
    const insert = before + inner + after;
    const anchor = range.from + before.length;
    const head = anchor + inner.length;
    return {
      changes: { from: range.from, to: range.to, insert },
      range: EditorSelection.range(anchor, head),
    };
  });
  view.dispatch(
    state.update(changes, { scrollIntoView: true, userEvent: 'input.format' }),
  );
  view.focus();
}

/**
 * Prepend `prefix` to the start of every line touched by the selection
 * (just the caret's line when the selection is empty). Used by the
 * heading / quote / list toolbar buttons. Insert-only — matches the old
 * helper, which never toggled the prefix off.
 */
export function insertLinePrefix(view: EditorView, prefix: string): void {
  const { state } = view;
  const seen = new Set<number>();
  const changes: { from: number; insert: string }[] = [];
  for (const range of state.selection.ranges) {
    const firstLine = state.doc.lineAt(range.from).number;
    const lastLine = state.doc.lineAt(range.to).number;
    for (let n = firstLine; n <= lastLine; n++) {
      const line = state.doc.line(n);
      if (seen.has(line.from)) continue;
      seen.add(line.from);
      changes.push({ from: line.from, insert: prefix });
    }
  }
  view.dispatch(state.update({ changes, userEvent: 'input.format' }));
  view.focus();
}
