// Grouped file rail — shared types. See ADR 0022 and the "Grouped list"
// term in CONTEXT.md. The arrangement is the per-PR, local-only review
// aid: just the chosen grouping dimension. Folders are recomputed from the
// files each render. (Drag-to-recategorize and custom folders are deferred —
// see ADR 0022.)

/** The grouping dimension the reviewer picked. `none` = flat list.
 * `ai` is the async, non-deterministic dimension (ADR 0026) — its
 * assignments come from the LLM and are injected into deriveArrangedView. */
export type GroupingDimension =
  | 'none'
  | 'file-type'
  | 'similar'
  | 'change-size'
  | 'ai';

/** Valid dimensions, for sanitizing persisted/legacy values. */
export const GROUPING_DIMENSIONS: GroupingDimension[] = [
  'none',
  'file-type',
  'similar',
  'change-size',
  'ai',
];

/** Per-folder metadata for the AI dimension: the one-line description and
 * the signal/noise classification, surfaced on the rail's AI grouping
 * panel. Keyed by the display folder segment. */
export interface AiFolderMeta {
  name: string;
  description: string;
  kind: 'important' | 'noise';
  order: number;
}

/** The persisted, per-PR review arrangement (local-only, never synced). */
export interface Arrangement {
  dimension: GroupingDimension;
}

export const EMPTY_ARRANGEMENT: Arrangement = { dimension: 'none' };

/** A file's auto-assignment under a dimension. `null` groupId means the
 * file has no meaningful group (leftover → loose at root). */
export interface AutoAssignment {
  groupId: string;
  groupLabel: string;
  /** Sort weight for ordering groups within the dimension. */
  order: number;
}
