// Type-specific hint icons (self-contained SVGs, one per hint type). Kept
// inline rather than mapped to lucide so the set stays exactly the five
// the design specifies. Falls back to the AI mark for unknown types.

import { AiMark } from './AiMark';
import type { AiHintType } from './taxonomy';

export function AiTypeIcon({
  type,
  className = 'size-3.5',
}: {
  type: AiHintType | string;
  className?: string;
}) {
  const c = {
    className,
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 1.7,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    viewBox: '0 0 24 24',
  };
  switch (type) {
    case 'bug':
      return (
        <svg {...c}>
          <path d="m8 2 1.88 1.88M14.12 3.88 16 2M9 7.13v-1a3.003 3.003 0 1 1 6 0v1" />
          <path d="M12 20c-3.3 0-6-2.7-6-6v-3a4 4 0 0 1 4-4h4a4 4 0 0 1 4 4v3c0 3.3-2.7 6-6 6" />
          <path d="M12 20v-9M6.53 9C4.6 8.8 3 7.1 3 5M6 13H2M3 21c0-2.1 1.7-3.9 3.8-4M20.97 5c0 2.1-1.6 3.8-3.5 4M22 13h-4M17.2 17c2.1.1 3.8 1.9 3.8 4" />
        </svg>
      );
    case 'security':
      return (
        <svg {...c}>
          <path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z" />
          <path d="M12 8v4M12 15.5h.01" />
        </svg>
      );
    case 'risk':
      return (
        <svg {...c}>
          <path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z" />
          <path d="M12 9v4M12 17h.01" />
        </svg>
      );
    case 'complexity':
      return (
        <svg {...c}>
          <circle cx="12" cy="4.5" r="2.5" />
          <circle cx="5" cy="19.5" r="2.5" />
          <circle cx="19" cy="19.5" r="2.5" />
          <path d="M12 7v3.5M10.3 12.2 6.3 17.6M13.7 12.2l4 5.4" />
        </svg>
      );
    case 'test-gap':
      return (
        <svg {...c}>
          <path d="M9 3h6M10 3v6.5L5.2 17a2 2 0 0 0 1.7 3h10.2a2 2 0 0 0 1.7-3L14 9.5V3" />
          <path d="M7.5 14h9" />
        </svg>
      );
    default:
      return <AiMark className={className} />;
  }
}
