// Identity bridge (ADR 0021): ties the GitHub Viewer + credential + entitlement
// to PostHog (person + org groups) and Sentry (user), and cross-links the two.
//
// Person key = GitHub user ID (stable; login is renameable). Org GROUPS are
// registered with properties for every seated org, but stickiness is cleared
// immediately — per-event org attribution is done explicitly in events.ts so a
// multi-org member's org-agnostic events aren't mis-attributed to whichever
// org happened to be last.

import type { Viewer } from '../github/types';
import type { Credential } from '../auth/tokenStore';
import type { Entitlement } from '../auth/oauthBroker';
import {
  analyticsConfigured,
  errorTrackingConfigured,
  groupAnalyticsEnabled,
} from './config';
import { posthog } from './posthog';
import { Sentry } from './sentry';

function crossLinkSentryToPostHog(): void {
  if (!errorTrackingConfigured || !analyticsConfigured) return;
  try {
    const sessionId = posthog.get_session_id?.();
    const distinctId = posthog.get_distinct_id?.();
    if (sessionId) Sentry.setTag('posthog_session_id', sessionId);
    Sentry.setContext('posthog', { distinct_id: distinctId, session_id: sessionId });
  } catch {
    /* posthog not ready — link is best-effort. */
  }
}

export function identifyUser(
  viewer: Viewer,
  credential: Credential | null,
  entitlement: Entitlement | null,
): void {
  const id = String(viewer.id);
  const verified = credential?.method === 'github-app';
  const plan = entitlement?.plan ?? 'free';

  if (errorTrackingConfigured) {
    Sentry.setUser({ id, username: viewer.login, email: viewer.email ?? undefined });
  }

  if (analyticsConfigured) {
    posthog.identify(
      id,
      {
        login: viewer.login,
        email: viewer.email ?? undefined,
        plan,
        auth_method: credential?.method ?? 'github-app',
        identity_verified: verified,
        seated_org_count: entitlement?.seats.length ?? 0,
      },
      { first_seen: new Date().toISOString() },
    );

    // Group analytics is a PAID feature (gated). When enabled, register group
    // properties for every seated org, then clear the sticky association
    // (events attach $groups per-call). On the free tier this is skipped and
    // org context rides as the `org_id` event property instead.
    if (groupAnalyticsEnabled) {
      (entitlement?.seats ?? []).forEach((s) =>
        posthog.group('org', String(s.githubOrgId), {
          name: s.name,
          login: s.login,
          plan,
          seat_index: s.index,
          seat_total: s.total,
          status: s.status,
          viewer_role: s.role,
        }),
      );
      posthog.resetGroups();
    }
  }

  crossLinkSentryToPostHog();
}

/** Clear all identity on sign-out so the next user starts a fresh person. */
function resetIdentity(): void {
  if (analyticsConfigured) posthog.reset();
  if (errorTrackingConfigured) Sentry.setUser(null);
}
