// React entry point for the grouped rail. Backs the arrangement on the
// per-PR localStorage store (source of truth) via useSyncExternalStore —
// no useEffect, no local mirror state. Exposes the derived ArrangedView
// (the lockstep ordered list) and the dimension setter. The arrangement is
// just the chosen dimension; folders are recomputed from the files.

import { useCallback, useMemo, useSyncExternalStore } from 'react';
import type { GHPullRequestFile } from '../../../github/types';
import {
  deriveArrangedView,
  type AiGroupingInput,
  type ArrangedView,
} from './arrange';
import {
  makeArrangementStore,
  type ArrangementStore,
} from './arrangementStore';
import {
  EMPTY_ARRANGEMENT,
  type Arrangement,
  type GroupingDimension,
} from './types';

export interface UseArrangement {
  arrangement: Arrangement;
  view: ArrangedView;
  setDimension: (d: GroupingDimension) => void;
}

/** In-memory fallback store for the fixture path (no owner/repo/number). */
function makeMemoryStore(): ArrangementStore {
  let current = EMPTY_ARRANGEMENT;
  const listeners = new Set<() => void>();
  return {
    snapshot: () => current,
    set(next) {
      if (next === current) return;
      current = next;
      listeners.forEach((l) => l());
    },
    subscribe(l) {
      listeners.add(l);
      return () => listeners.delete(l);
    },
  };
}

export function useArrangement(
  owner: string | undefined,
  repo: string | undefined,
  number: number | undefined,
  files: GHPullRequestFile[],
  /** Injected AI grouping (assignments + per-group meta) for the async
   * `ai` dimension. Absent for the deterministic dimensions. */
  ai?: AiGroupingInput,
): UseArrangement {
  const store = useMemo<ArrangementStore>(
    () =>
      owner && repo && number != null
        ? makeArrangementStore(owner, repo, number)
        : makeMemoryStore(),
    [owner, repo, number],
  );

  const arrangement = useSyncExternalStore(store.subscribe, store.snapshot);

  const view = useMemo(
    () => deriveArrangedView(files, arrangement, arrangement.dimension === 'ai' ? ai : undefined),
    [files, arrangement, ai],
  );

  const setDimension = useCallback(
    (d: GroupingDimension) => store.set({ dimension: d }),
    [store],
  );

  return { arrangement, view, setDimension };
}
