// Vertical splitter — drag the right edge of the file rail to resize.
//
// Uses pointer-capture so the drag survives the cursor moving off
// the handle. Width clamped 180–600 px; persisted under a caller-
// supplied storage key so each pane can remember its own width.
//
// The resizer renders as a 4-px hit target absolutely-positioned on
// the right edge of its parent. Wider hover/active state for
// affordance. Visually a 1-px line at rest, 2-px and accent-tinted
// while dragging.

import { useCallback, useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';

const STORAGE_PREFIX = 'pyor:resize:';

export function useResizableWidth(
  storageKey: string,
  defaultWidth: number,
  minWidth: number,
  maxWidth: number,
): { width: number; startDrag: (e: React.PointerEvent) => void; dragging: boolean } {
  const [width, setWidth] = useState<number>(() => {
    try {
      const raw = localStorage.getItem(STORAGE_PREFIX + storageKey);
      if (!raw) return defaultWidth;
      const n = Number(raw);
      if (!Number.isFinite(n)) return defaultWidth;
      return Math.max(minWidth, Math.min(maxWidth, n));
    } catch {
      return defaultWidth;
    }
  });
  const [dragging, setDragging] = useState(false);
  const startXRef = useRef(0);
  const startWRef = useRef(width);

  const persist = useCallback(
    (next: number) => {
      try {
        localStorage.setItem(STORAGE_PREFIX + storageKey, String(next));
      } catch {
        // ignore — width won't survive reload but session stays fine
      }
    },
    [storageKey],
  );

  const startDrag = useCallback(
    (e: React.PointerEvent) => {
      e.preventDefault();
      e.stopPropagation();
      startXRef.current = e.clientX;
      startWRef.current = width;
      setDragging(true);
      const target = e.currentTarget as HTMLElement;
      target.setPointerCapture(e.pointerId);

      const onMove = (ev: PointerEvent) => {
        const dx = ev.clientX - startXRef.current;
        const next = Math.max(
          minWidth,
          Math.min(maxWidth, Math.round(startWRef.current + dx)),
        );
        setWidth(next);
      };
      const onUp = (ev: PointerEvent) => {
        setDragging(false);
        try {
          target.releasePointerCapture(ev.pointerId);
        } catch {
          // ignore
        }
        document.removeEventListener('pointermove', onMove);
        document.removeEventListener('pointerup', onUp);
        document.removeEventListener('pointercancel', onUp);
        // Persist the final width.
        setWidth((w) => {
          persist(w);
          return w;
        });
      };
      document.addEventListener('pointermove', onMove);
      document.addEventListener('pointerup', onUp);
      document.addEventListener('pointercancel', onUp);
    },
    [width, minWidth, maxWidth, persist],
  );

  return { width, startDrag, dragging };
}

interface ResizerProps {
  onPointerDown: (e: React.PointerEvent) => void;
  dragging: boolean;
  /** Visual orientation. 'vertical' (default) lives on the right
   * edge of the left pane. */
  orientation?: 'vertical';
}

/** A 4-px wide drag handle. Render as the last child of a flex
 * container so it sits between two panes. */
export function Resizer({ onPointerDown, dragging }: ResizerProps) {
  const [hover, setHover] = useState(false);
  const active = dragging || hover;
  return (
    <div
      onPointerDown={onPointerDown}
      onPointerEnter={() => setHover(true)}
      onPointerLeave={() => setHover(false)}
      role="separator"
      aria-orientation="vertical"
      className={cn(
        // Layout: 4-px hit target, pulled into the gutter via negative
        // margins so it overlaps both panes without shifting them.
        'relative z-[2] w-1 -mx-0.5 shrink-0 cursor-col-resize',
        // A nudge of fade so the handle reveals on hover without
        // being a flat painted line at rest.
        'transition-colors duration-[80ms] ease',
        // Hairline divider when not dragging, drawn via inset shadow
        // so it doesn't change the layout box.
        active
          ? 'bg-pyor-link shadow-none'
          : 'bg-transparent shadow-[inset_1px_0_0_hsl(var(--border))]',
      )}
    />
  );
}
