// Dark-mode toggle, backed by a zustand store (no React Context).
// Consume via useTheme(); no provider wrapper needed.
//
// Post-ADR 0011 this is the dark-mode toggle and nothing more. The
// per-token palette (`T.text`, `T.surface`, etc.) is gone — all palette
// reads go through the CSS variables published in `styles/tailwind.css`
// and consumed by Tailwind utility classes (`bg-background`,
// `text-muted-foreground`, etc). The `.pyor-dark` class on `body`
// drives the per-variable dark overrides.

import { create } from 'zustand';

const STORAGE_KEY = 'pyor:theme';

function initialDark(): boolean {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'dark') return true;
    if (saved === 'light') return false;
  } catch {
    // localStorage may be unavailable in some test envs — fall through
  }
  return (
    typeof window !== 'undefined' &&
    window.matchMedia?.('(prefers-color-scheme: dark)').matches
  );
}

interface ThemeStore {
  dark: boolean;
  setDark: (d: boolean) => void;
}

const useThemeStore = create<ThemeStore>((set) => ({
  dark: initialDark(),
  setDark: (dark) => {
    document.body.classList.toggle('pyor-dark', dark);
    try {
      localStorage.setItem(STORAGE_KEY, dark ? 'dark' : 'light');
    } catch {
      // ignore — non-fatal
    }
    set({ dark });
  },
}));

// Apply the body class once on load, before any consumer mounts.
// Importing this module (see App.tsx / main.tsx) runs this side effect.
if (typeof document !== 'undefined') {
  document.body.classList.toggle('pyor-dark', useThemeStore.getState().dark);
}

/** Returns the current dark flag + the stable setter. */
export function useTheme(): ThemeStore {
  const dark = useThemeStore((s) => s.dark);
  const setDark = useThemeStore((s) => s.setDark);
  return { dark, setDark };
}
