// Self-assert a PAT user's identity to the backend (ADR 0019/0020).
//
// Sends ONLY {githubUserId, login, email} derived from GitHub's GET /user —
// never the PAT. The backend records it as an UNVERIFIED identity (free-tier,
// never a seat); it's for analytics + later linking when the same GitHub user
// signs in with the App. Best-effort, fire-and-forget: a failure here must
// never affect the user's session.

const BROKER_URL = (
  import.meta.env.VITE_AUTH_BROKER_URL as string | undefined
)?.trim();

export interface SelfAssertedIdentity {
  githubUserId: number;
  login: string;
  email: string | null;
}

export function selfAssertIdentity(id: SelfAssertedIdentity): void {
  // No broker wired (local mock) → nothing to record.
  if (!BROKER_URL) return;
  void fetch(`${BROKER_URL}/identity`, {
    method: 'POST',
    // Deliberately NO Authorization header — the backend never receives the PAT.
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(id),
    // Survive a navigation/unload right after sign-in.
    keepalive: true,
  }).catch(() => {
    /* analytics is best-effort — swallow. */
  });
}
