// Owner-login → numeric GitHub org id resolution for per-event org attribution
// (ADR 0021). PR list rows + PR-scoped events only carry an owner LOGIN, but
// org analytics keys on the numeric org id. The installations list bridges the
// two (login ↔ id), so we read it (same `['installations']` query the org gate
// uses — deduped by key) and expose a lookup.

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { fetchUserInstallations, toAppInstallations } from '../github/client';
import type { AppInstallation } from '../github/client';
import { getCredential } from '../auth/tokenStore';

/** Pure lookup: the numeric org id for an owner login, or null. */
function orgIdForLogin(
  installations: AppInstallation[],
  login: string,
): number | null {
  const acct = installations.find(
    (i) => i.account.login.toLowerCase() === login.toLowerCase(),
  );
  return acct?.account.id ?? null;
}

/**
 * Resolve an owner login to its numeric org id for event attribution. Returns
 * null until installations load (PAT users never enumerate them) — events then
 * simply carry no org_id, which is correct (personal repos have no org).
 */
export function useOrgIdForOwner(login: string | null | undefined): number | null {
  const enabled = getCredential()?.method === 'github-app';
  const { data } = useQuery({
    queryKey: ['installations'],
    queryFn: fetchUserInstallations,
    select: toAppInstallations,
    enabled,
    staleTime: 60_000,
  });
  return useMemo(
    () => (login && data ? orgIdForLogin(data, login) : null),
    [data, login],
  );
}
