// Real broker client — talks to the Pyor `api/` backend (ADR 0019).
// Used when VITE_AUTH_BROKER_URL is set; otherwise the mock is used.

import type {
  Entitlement,
  OAuthBroker,
  StartSignInResult,
  TokenSet,
} from './oauthBroker';
import { BrokerError, type AuthErrorKind } from './brokerError';
import { isElectron } from '../desktop/electronBridge';

const ERROR_KINDS: readonly AuthErrorKind[] = [
  'expired',
  'cancelled',
  'no-repos',
  'org-approval',
  'offline',
];

function toErrorKind(code: unknown): AuthErrorKind {
  if (typeof code === 'string' && (ERROR_KINDS as string[]).includes(code)) {
    return code as AuthErrorKind;
  }
  // GitHub's own device/oauth error codes mapped to our kinds.
  if (code === 'access_denied') return 'cancelled';
  if (code === 'expired_token') return 'expired';
  return 'offline';
}

export function realBroker(baseUrl: string): OAuthBroker {
  const base = baseUrl.replace(/\/$/, '');

  async function post<T>(path: string, body: unknown, token?: string): Promise<T> {
    let res: Response;
    try {
      res = await fetch(`${base}${path}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify(body),
      });
    } catch {
      throw new BrokerError('offline', `Could not reach ${base}${path}`);
    }
    if (!res.ok) {
      const data = (await res.json().catch(() => ({}))) as { error?: string };
      throw new BrokerError(toErrorKind(data.error), data.error ?? `HTTP ${res.status}`);
    }
    return res.json() as Promise<T>;
  }

  async function get<T>(path: string, token: string): Promise<T> {
    let res: Response;
    try {
      res = await fetch(`${base}${path}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch {
      throw new BrokerError('offline', `Could not reach ${base}${path}`);
    }
    if (!res.ok) {
      const data = (await res.json().catch(() => ({}))) as { error?: string };
      throw new BrokerError(toErrorKind(data.error), data.error ?? `HTTP ${res.status}`);
    }
    return res.json() as Promise<T>;
  }

  return {
    startSignIn: (opts) =>
      post<StartSignInResult>('/oauth/start', {
        reauth: opts?.reauth ?? false,
        // Tells the broker where to send the browser back: pyor:// (desktop)
        // vs the web app origin. Without this the callback defaults to desktop.
        platform: isElectron() ? 'desktop' : 'web',
      }),
    completeSignIn: (code, state) =>
      post<TokenSet>('/oauth/complete', { code, state }),
    refresh: (refreshToken) => post<TokenSet>('/oauth/refresh', { refreshToken }),
    getEntitlement: (accessToken) =>
      get<Entitlement>('/entitlement', accessToken),
  };
}
