// Animated copy→check icon — adapted from smoothui (educlopez, MIT)
// button-copy's icon morph, distilled to just the icon swap so it drops
// into the app's existing tiny inline copy buttons (sha pill, footer
// actions, path badge, …) without changing their layout or handlers.
//
// The app's clipboard writes are synchronous, so the smoothui loading
// spinner is intentionally dropped — there's no real async to mask, and
// a fake delay would only slow the affordance. Just idle ⇄ success.
//
// "use no memo": React Compiler memoization makes AnimatePresence miss
// the key swap and skip the exit, so the morph wouldn't play.

import * as React from "react"
import { CheckIcon, CopyIcon } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

type CopyIconMorphProps = {
  /** When true, shows the success (check) icon; otherwise the idle icon. */
  copied: boolean
  /** Applied to the default icons — use it to size/colour them
   * (e.g. "size-3"). Ignored when idleIcon/successIcon are supplied. */
  className?: string
  /** Override the idle icon (e.g. a Sparkles for "Copy for agent"). */
  idleIcon?: React.ReactNode
  /** Override the success icon. */
  successIcon?: React.ReactNode
}

/** Morphs between the idle and success icons (blur + slide) when
 * `copied` flips. Stack both states in one grid cell so the box stays
 * the icon's size and the two glyphs cross-fade in place. */
function CopyIconMorph({
  copied,
  className,
  idleIcon,
  successIcon,
}: CopyIconMorphProps) {
  "use no memo"
  const reduce = useReducedMotion()
  const idle = idleIcon ?? <CopyIcon className={className} />
  const success = successIcon ?? <CheckIcon className={className} />
  return (
    <span className="inline-grid place-items-center [&>*]:[grid-area:1/1]">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          key={copied ? "success" : "idle"}
          className="inline-flex"
          initial={
            reduce ? { opacity: 1 } : { opacity: 0, y: -7, filter: "blur(4px)" }
          }
          animate={
            reduce ? { opacity: 1 } : { opacity: 1, y: 0, filter: "blur(0px)" }
          }
          exit={
            reduce
              ? { opacity: 0, transition: { duration: 0 } }
              : { opacity: 0, y: 7, filter: "blur(4px)" }
          }
          transition={
            reduce ? { duration: 0 } : { type: "spring", duration: 0.25, bounce: 0 }
          }
        >
          {copied ? success : idle}
        </motion.span>
      </AnimatePresence>
    </span>
  )
}

export { CopyIconMorph }
