function PRDescription({
  pr,
  owner,
  repo,
  number,
  viewerLogin,
  collapse,
  focusMode = false,
}: {
  pr: GHPullRequest;
  owner?: string;
  repo?: string;
  number?: number;
  viewerLogin?: string;
  collapse: CollapsedCommentsValue;
  /** Conversation "Focus: Comments" — the description card defaults to
   * collapsed so focus reads as pure discussion. Still expandable from
   * the chevron (the override survives), so it's a default, not a lock. */
  focusMode?: boolean;
}) {
  const qc = useQueryClient();
  // GitHub parity: the author OR anyone with write access to the repo (e.g. a
  // reviewer working the checklist) can edit the description and toggle its
  // task-list checkboxes — GitHub accepts the body PATCH from any write-access
  // collaborator and 403s everyone else. Only the "you" badge stays
  // author-specific.
  const isAuthor = !!viewerLogin && viewerLogin === pr.user.login;
  const { data: viewerPermission } = useQuery({
    ...viewerPermissionOptions(owner ?? '', repo ?? ''),
    enabled: !!owner && !!repo,
  });
  const canEdit = isAuthor || hasWriteAccess(viewerPermission ?? 'NONE');
  const canToggleTasks = canEdit;
  const isYou = isAuthor;
  const [editing, setEditing] = useState(false);
  const uploadImage = useGithubAssetsUploader();

  // Collapse behaviour splits on focus:
  //  • Focus OFF — the persistent per-PR collapse store (chevron state
  //    survives reloads), same as every other card.
  //  • Focus ON — the description folds away as discussion-only noise.
  //    We drive that from EPHEMERAL local state seeded collapsed and
  //    reset on each off→on transition, NOT the store, so (a) turning
  //    focus on always re-collapses it, and (b) a peek doesn't persist
  //    an "open" override that would defeat focus next time. This also
  //    means a stale stored override can't keep it stuck open.
  const [focusPeek, setFocusPeek] = useState(false);
  const prevFocusRef = useRef(focusMode);
  if (focusMode && !prevFocusRef.current) setFocusPeek(false);
  prevFocusRef.current = focusMode;
  const descCollapsed = focusMode
    ? !focusPeek
    : collapse.isCollapsed('pr-description');
  const onToggleDesc = focusMode
    ? () => setFocusPeek((p) => !p)
    : () => collapse.toggle('pr-description');

  // Save handler — wraps the PATCH + cache update + toast so the
  // GhComposer doesn't have to know about the query layer. Throws on
  // failure so the composer keeps the user's text and the toast
  // describes the error.
  const onSave = async (body: string) => {
    if (!owner || !repo || !number) return;
    try {
      await updatePRDescription(owner, repo, number, body);
      // Push the new body into the cached prMeta query so the view
      // updates instantly without a refetch round-trip — then
      // invalidate just the meta key (not the whole PR subtree) so
      // the next refetch confirms it without touching files/contents.
      qc.setQueryData<GHPullRequest>(
        ['pr', owner, repo, number, 'meta'],
        (curr) => (curr ? { ...curr, body } : curr),
      );
      void qc.invalidateQueries({
        queryKey: ['pr', owner, repo, number, 'meta'],
      });
      setEditing(false);
      toast.success('Description updated');
    } catch (e) {
      toast.error('Could not update description', {
        description: e instanceof Error ? e.message : String(e),
      });
      throw e;
    }
  };

  const edited = pr.updated_at !== pr.created_at ? humanAge(pr.updated_at) : null;

  // Reactions on the PR body itself live on the issue resource —
  // GitHub treats PR body reactions as `addIssueReaction` (PRs are
  // issues at this level). The reaction count is part of the prMeta
  // payload (pr.reactions). We patch that key optimistically (+1 / -1
  // on the matching counter + total_count) so the badge moves on the
  // next paint; the network mutation just confirms. On failure the
  // helper rolls back via the captured snapshot + we toast.
  const qc2 = useQueryClient();
  // Memoised so it's a stable dependency for the task-toggle useCallback below
  // (a fresh array each render would defeat the <Markdown> memoisation).
  const metaKey = useMemo(
    () => ['pr', owner, repo, number, 'meta'] as const,
    [owner, repo, number],
  );
  const onAddBodyReaction = owner && repo && number
    ? (key: keyof GHReactions) => {
        const c = asReactionContent(key);
        if (!c) return;
        // Return the promise so GhReactions can await it before
        // invalidating the reactor query (the `.catch` keeps it resolved).
        return withOptimisticReaction<GHPullRequest>(
          qc2,
          metaKey,
          (curr) =>
            curr ? { ...curr, reactions: bumpReactionCount(curr.reactions, c, 1) } : curr,
          () => addIssueReaction(owner, repo, number, c),
        ).catch((e) => {
          toast.error('Could not add reaction', {
            description: e instanceof Error ? e.message : String(e),
          });
        });
      }
    : undefined;
  const onRemoveBodyReaction = owner && repo && number
    ? (key: keyof GHReactions, reactionId: number) => {
        const c = asReactionContent(key);
        if (!c) return;
        return withOptimisticReaction<GHPullRequest>(
          qc2,
          metaKey,
          (curr) =>
            curr ? { ...curr, reactions: bumpReactionCount(curr.reactions, c, -1) } : curr,
          () => removeIssueReaction(owner, repo, number, reactionId),
        ).catch((e) => {
          toast.error('Could not remove reaction', {
            description: e instanceof Error ? e.message : String(e),
          });
        });
      }
    : undefined;

  // Interactive task-list checkboxes in the PR description. The author OR a
  // write-access reviewer (canToggleTasks) may toggle — GitHub accepts the
  // body PATCH from either and 403s everyone else — so the callback is only
  // threaded when canToggleTasks, leaving read-only viewers (and every
  // non-description Markdown surface) disabled.
  //
  // Writes are SERIALIZED via a TanStack mutation `scope`: every toggle
  // for this PR shares one scope id, so the PATCHes run one-at-a-time in
  // click order instead of racing in parallel. That is what fixes "toggle
  // fast → some checks get lost" — concurrent PATCHes could previously
  // land out of order and an earlier body would clobber a later one.
  //
  // The optimistic flip is done in the click handler (not `onMutate`), so
  // the checkbox moves on the very next paint even while an earlier write
  // is still in flight (a scoped `onMutate` would be deferred until the
  // queue drained, lagging the UI). There's no success-time invalidate —
  // each PATCH sends the exact body we already rendered, so refetching
  // would only risk clobbering a still-queued flip. On failure we roll
  // the cache back to the server's truth.
  const taskToggle = useMutation({
    scope: { id: `pr-task-toggle:${owner}/${repo}/${number}` },
    mutationFn: (nextBody: string) =>
      updatePRDescription(owner!, repo!, number!, nextBody),
    onError: (e) => {
      toast.error('Could not update task', {
        description: e instanceof Error ? e.message : String(e),
      });
      void qc.invalidateQueries({ queryKey: metaKey });
    },
  });
  // Stable identity (useCallback) so the memoised <Markdown> doesn't re-render
  // — and thus re-parse + flash its checkboxes — on every unrelated re-render
  // of this card. Reads the live body from the cache (falling back to the prop)
  // so the closure never needs `pr.body` as a dependency.
  const prBody = pr.body;
  const taskMutate = taskToggle.mutate;
  const toggleTask = useCallback(
    (sourceLine: number, nextChecked: boolean) => {
      const currentBody =
        qc.getQueryData<GHPullRequest>(metaKey)?.body ?? prBody ?? '';
      const nextBody = setTaskCheckedAtLine(currentBody, sourceLine, nextChecked);
      if (nextBody === currentBody) return;
      // Optimistic flip: update the cached body so the checkbox moves
      // immediately and the next toggle builds on the latest state.
      qc.setQueryData<GHPullRequest>(metaKey, (c) =>
        c ? { ...c, body: nextBody } : c,
      );
      taskMutate(nextBody);
    },
    [qc, metaKey, prBody, taskMutate],
  );
  const onToggleTask =
    canToggleTasks && owner && repo && number ? toggleTask : undefined;

  const body = pr.body && pr.body.trim() !== '' ? (
    <Markdown source={pr.body} onToggleTask={onToggleTask} />
  ) : (
    <div className="text-[12.5px] italic text-muted-foreground/80">
      No description provided.
    </div>
  );

  return (
    <div className="mb-5">
      <GhComment
        author={pr.user.login}
        authorAvatarUrl={pr.user.avatar_url}
        association={pr.author_association}
        prRole="author"
        age={`${humanAge(pr.created_at)} ago`}
        ageTitle={fullDate(pr.created_at)}
        edited={edited}
        editedTitle={fullDate(pr.updated_at)}
        isYou={isYou}
        htmlUrl={pr.html_url}
        reactions={pr.reactions}
        onAddReaction={onAddBodyReaction}
        onRemoveReaction={onRemoveBodyReaction}
        listReactors={
          owner && repo && number
            ? () => listIssueReactors(owner, repo, number)
            : undefined
        }
        viewerLogin={viewerLogin}
        preview={plainTextPreview(pr.body ?? '')}
        previewSource={pr.body ?? ''}
        collapsed={descCollapsed}
        onCollapsedChange={onToggleDesc}
        canEdit={canEdit}
        editing={editing}
        onEdit={canEdit ? () => setEditing(true) : undefined}
        editor={
          editing ? (
            <GhComposer
              key={`pr-desc-edit-${pr.updated_at}`}
              draftKey={`${owner}/${repo}/${number}:pr-description`}
              initialBody={pr.body ?? ''}
              submitLabel="Update description"
              submitIcon="check"
              draftHint="Autosaved · only you can see this draft"
              onCancel={() => setEditing(false)}
              onSubmit={onSave}
              onUploadImage={uploadImage}
              mentionContext={owner && repo ? { owner, repo, number } : undefined}
              variant="inline"
              minHeight={180}
            />
          ) : null
        }
      >
        {body}
      </GhComment>
    </div>
  );
}

// ── Timeline: chronological mix of events + review verdicts ──────

/** One merged item — a timeline event, a review submission, or an
 * inline review thread (head comment + its in_reply_to chain). */
type Item =
  | { kind: 'event'; event: GHTimelineEvent; ts: number }
  | { kind: 'review'; review: GHReview; ts: number }
  | {
      kind: 'thread';
      head: GHReviewComment;
      replies: GHReviewComment[];
      ts: number;
    };

function Timeline({
  events,
  reviews,
  reviewComments,
  authorLogin,
  viewerLogin,
  owner,
  repo,
  number,
  headSha,
  baseSha,
  collapseEvents = false,
  onlyUnreplied = false,
  onShowAll,
  collapse,
  scrollParent,
  jumpToConversation,
  onJumpConsumed,
  onScopeToCommit,
  onShowInDiff,
}: {
  events: GHTimelineEvent[];
  reviews: GHReview[];
  reviewComments: GHReviewComment[];
  authorLogin?: string;
  viewerLogin?: string;
  onlyUnreplied?: boolean;
  owner?: string;
  repo?: string;
  number?: number;
  headSha?: string;
  baseSha?: string;
  /** Conversation focus ("Focus: Comments") — collapse runs of
   * low-signal timeline events into a single divider, keeping the
   * comments / reviews / inline threads. */
  collapseEvents?: boolean;
  onShowAll?: () => void;
  /** Shared per-PR collapse set (from ConversationMain). Every card
   * in the timeline folds through it so its state persists. */
  collapse: CollapsedCommentsValue;
  /** The ConversationMain scroll div. Handed to Virtuoso as
   * `customScrollParent` so the timeline virtualizes WITHOUT owning the
   * scroll — description + composer + MergeBox keep sharing one
   * scrollbar (plan 17). Null until the div mounts. */
  scrollParent: HTMLDivElement | null;
  /** Reviewer-HoverCard "View comment" jump target for a PR-level
   * review summary — scroll to + flash-pulse the review with this id.
   * Fresh object per click so re-clicking re-fires the scroll effect. */
  jumpToConversation?: { reviewId: number } | null;
  /** Fired once the jump has been handled so the parent can clear the
   * target (prevents a stale re-jump on a later tab re-mount). */
  onJumpConsumed?: () => void;
  /** Open the Changes tab scoped to one commit — wired to commit rows. */
  onScopeToCommit?: (sha: string) => void;
  /** "Show in diff" on an inline thread — open the Changes tab + scroll
   * to the thread's anchor line. */
  onShowInDiff?: (target: {
    path: string;
    line: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
  }) => void;
}) {
  // Resolved state isn't in the REST review-comments payload — it's a
  // GraphQL-only field. Fetch the review-thread ids (same query the
  // Files tab uses, so it dedupes) and map each thread's resolution
  // back onto its head comment id. Without this every thread renders
  // as "open" even when resolved on GitHub.
  const reviewThreadsQuery = useQuery({
    ...prThreadsOptions(owner!, repo!, number!),
    enabled: !!(owner && repo && number),
    // GraphQL — ~100 rate-limit points/fetch and can't 304. Don't let
    // this observer refetch on a stale-timer or window focus; PRDetail's
    // metadata heartbeat invalidates the shared `threadIds` key only when
    // the PR's `updated_at` actually moves. (Both observers must opt out
    // of focus-refetch or the costly query fires anyway.)
    staleTime: STABLE_PER_OPEN_MS,
    refetchOnWindowFocus: false,
  });
  // Map each head comment id → its full GraphQL thread record so the
  // thread item can drive both the Resolved badge AND the resolve
  // footer (node id, resolvedBy, viewer permission flags).
  const threadByHead = useMemo(() => {
    const m = new Map<number, ResolvableThread>();
    for (const t of reviewThreadsQuery.data ?? []) {
      for (const dbId of t.commentDatabaseIds) m.set(dbId, t);
    }
    return m;
  }, [reviewThreadsQuery.data]);
  const merged: Item[] = useMemo(() => {
    const items: Item[] = [];
    for (const e of events) {
      // Skip reviews from the timeline endpoint — we render them from
      // the /reviews call instead, which has the body/state. Also
      // skip line_comment events — same reason, we render those via
      // the /pulls/{n}/comments thread grouping below.
      if (e.event === 'reviewed' || e.event === 'line-commented') continue;
      // `committed` events from the REST timeline carry NO `created_at` /
      // `submitted_at` — their time lives in `author.date`. Without this
      // fallback parseTs returns 0 and every new commit sorts to the very
      // TOP of the timeline instead of chronologically at the bottom, so a
      // push the user just made never appears where they expect it.
      const ts = parseTs(e.created_at ?? e.submitted_at ?? e.author?.date);
      items.push({ kind: 'event', event: e, ts });
    }
    for (const r of reviews) {
      if (r.state === 'PENDING') continue;
      // Skip empty COMMENTED reviews if they have associated inline
      // review comments — those comments will show as threaded cards
      // and the empty "Commented" verdict is just noise next to them.
      // Approvals and Changes-requested still show even when bodyless
      // because the verdict itself is the signal.
      const hasBody = r.body && r.body.trim() !== '';
      if (!hasBody && r.state === 'COMMENTED') continue;
      const ts = parseTs(r.submitted_at);
      items.push({ kind: 'review', review: r, ts });
    }
    // Group review comments into threads: head comments (no
    // in_reply_to_id) are the parents; everything else attaches by
    // pointing at its head's id. GitHub guarantees this chain stays
    // single-depth — replies of replies still link to the original
    // head — so we don't need a recursive walk.
    const heads = reviewComments.filter((c) => !c.in_reply_to_id);
    const repliesByHead = new Map<number, GHReviewComment[]>();
    for (const c of reviewComments) {
      if (c.in_reply_to_id) {
        const arr = repliesByHead.get(c.in_reply_to_id) ?? [];
        arr.push(c);
        repliesByHead.set(c.in_reply_to_id, arr);
      }
    }
    for (const head of heads) {
      const replies = (repliesByHead.get(head.id) ?? []).slice().sort(
        (a, b) => parseTs(a.created_at) - parseTs(b.created_at),
      );
      // "New comments" focus no longer DROPS already-handled threads —
      // it keeps them in the timeline and (via TimelineThreadItem's
      // auto-collapse default) folds them to a stub, so a thread you
      // started but nobody's replied to yet stays visible, just
      // collapsed. Only threads awaiting your reply render expanded.
      const ts = parseTs(head.created_at);
      items.push({ kind: 'thread', head, replies, ts });
    }
    items.sort((a, b) => a.ts - b.ts);
    return items;
  }, [events, reviews, reviewComments]);

  // Group consecutive runs of the same low-signal event (force-push,
  // labeled, assigned, etc.) into a single compact row. PRs in active
  // development often log dozens of force-pushes in a row; rendering
  // them as individual cards drowns out the actual review content.
  //
  // When Conversation focus is on, switch to the more aggressive
  // focus-collapse: every run of non-comment events folds into one
  // "N timeline events hidden" divider.
  // "New changes since you last viewed": the instant the viewer last
  // opened this PR's Conversation. Captured once per session (and re-marks
  // the PR viewed-as-of-now) so the divider stays put across tab switches.
  // Null on a first-ever visit → no divider, matching GitHub.
  const newChangesBaseline =
    owner && repo && number
      ? captureNewChangesBaseline(owner, repo, number, Date.now())
      : null;
  // Settled rows the viewer expanded in place (per-row click / "Expand
  // all" in a band): they leave the band and render as full cards at
  // their chronological position, while the band's other rows stay
  // compact. In-memory + reset on PR navigation — a transient view
  // action, not a persisted preference. `collapse.expand` (below) pins
  // the card itself open so a resolved one shows its body, not a stub.
  const [expandedSettled, setExpandedSettled] = useState<Set<string>>(
    () => new Set(),
  );
  useEffect(() => {
    setExpandedSettled(new Set());
  }, [owner, repo, number]);
  const expandSettled = useCallback(
    (keys: string[]) => {
      setExpandedSettled((prev) => {
        const next = new Set(prev);
        keys.forEach((k) => next.add(k));
        return next;
      });
      keys.forEach((k) => collapse.expand(k));
    },
    [collapse],
  );
  // Captured once per mount so the "stale" heuristic doesn't recompute the
  // compression memo on every render (Date.now() would change each time).
  const nowRef = useRef(Date.now());
  const compressed = useMemo(() => {
    const settledOf = makeSettledOf(
      threadByHead,
      viewerLogin,
      nowRef.current,
      onlyUnreplied,
    );
    const base = collapseEvents
      ? collapseForFocus(merged, settledOf, expandedSettled)
      : groupRuns(merged);
    return insertNewChangesDivider(base, newChangesBaseline);
  }, [
    merged,
    collapseEvents,
    newChangesBaseline,
    threadByHead,
    viewerLogin,
    onlyUnreplied,
    expandedSettled,
  ]);

  // Reviewer-HoverCard "View comment" → scroll the virtualized timeline
  // to the target review and flash-pulse it. The row may be unmounted
  // (Virtuoso only mounts the visible window), so we must scrollToIndex
  // to bring it into view rather than scrollIntoView a missing node.
  //
  // Gated on `scrollParent` (and it's in the deps): when the jump comes
  // from another tab, DescriptionTab + this Timeline mount fresh, and on
  // the first render `scrollParent` is still null so <Virtuoso> — and its
  // handle — doesn't exist yet. Without re-running once the scroll div
  // commits, the first click would only switch tabs and the user would
  // have to click again. The rAF gives Virtuoso a frame to attach +
  // measure before we scroll (a synchronous scrollToIndex on a
  // just-mounted list no-ops). Re-fires whenever `jumpToConversation` is a
  // new object (PRDetailScreen mints one per click).
  const virtuosoRef = useRef<VirtuosoHandle>(null);
  const [flashReviewId, setFlashReviewId] = useState<number | null>(null);
  useEffect(() => {
    if (!jumpToConversation || !scrollParent) return;
    const index = compressed.findIndex(
      (e) =>
        e.kind === 'single' &&
        e.item.kind === 'review' &&
        e.item.review.id === jumpToConversation.reviewId,
    );
    if (index < 0) return;
    const reviewId = jumpToConversation.reviewId;
    const raf = requestAnimationFrame(() => {
      virtuosoRef.current?.scrollToIndex({
        index,
        align: 'center',
        behavior: 'auto',
      });
      setFlashReviewId(reviewId);
      // Clear the parent target now that it's handled, so manually
      // switching back to this tab later doesn't re-jump to a stale
      // review. Done inside the rAF (after the scroll fires) so the
      // resulting re-render's effect-cleanup can't cancel our own rAF.
      onJumpConsumed?.();
    });
    return () => cancelAnimationFrame(raf);
  }, [jumpToConversation, compressed, scrollParent, onJumpConsumed]);
  // Flash auto-clears on its own timer, decoupled from the jump effect
  // above so clearing the parent target can't abort the pulse early.
  useEffect(() => {
    if (flashReviewId == null) return;
    const t = setTimeout(() => setFlashReviewId(null), 1600);
    return () => clearTimeout(t);
  }, [flashReviewId]);

  // Persisted size cache: stable per-row keys give Virtuoso identity to
  // anchor against AND a content signature for the index-based heights we
  // stash per PR. On remount (tab switch / reload) those heights seed
  // `restoreStateFrom` so the first bottom-up scroll doesn't re-measure-jump.
  const itemKeys = useMemo(
    () => compressed.map((entry, i) => entryKey(i, entry)),
    [compressed],
  );
  const restoreState = useConversationListSnapshot({
    owner,
    repo,
    number,
    virtuosoRef,
    scrollParent,
    keys: itemKeys,
  });

  if (compressed.length === 0) {
    return (
      <div className="px-1 text-[12.5px] text-muted-foreground/80">
        No activity yet.
      </div>
    );
  }

  // Wait for the scroll parent before mounting Virtuoso. On the very
  // first render `scrollParent` is still null (the callback ref commits
  // it one render later), so `customScrollParent` would be undefined and
  // Virtuoso would briefly fall back to owning its own scroller inside
  // the height-less max-w column — which it reports as a "Zero-sized
  // element" console error. The parent scroll div always renders, so
  // this only defers the timeline by a single frame (the PR description
  // above is already painted).
  if (!scrollParent) return null;

  // Virtualize the timeline: only the visible compressed entries mount,
  // so a 200-comment PR no longer pays one full card render per item.
  // We do NOT let Virtuoso own the scroll — `customScrollParent` points
  // at ConversationMain's scroll div so the PR description, composer and
  // MergeBox (siblings outside this list) still scroll together under
  // one scrollbar (plan 17 decision). The continuous vertical rail is
  // rendered as a per-row segment behind each node (see TimelineRow);
  // with rows flush against each other the segments read as one
  // unbroken line, matching the previous single absolute rail.
  return (
    <Virtuoso
      ref={virtuosoRef}
      customScrollParent={scrollParent ?? undefined}
      data={compressed}
      // Identity per row (by comment/review/event id) so Virtuoso anchors a
      // node across re-renders instead of by array index, and so the
      // persisted size cache can be validated against the list's shape.
      computeItemKey={entryKey}
      // Seed measured row heights from the last visit (sizes only — the
      // scroll offset is restored by ConversationMain). `undefined` when
      // there's no matching snapshot, so it's a no-op on first-ever visits
      // and whenever the timeline shape changed.
      restoreStateFrom={restoreState}
      // Render a small batch of rows synchronously on first paint so
      // the timeline doesn't flash empty for a frame before Virtuoso's
      // layout effect mounts items (mirrors InboxCommentsList). Kept
      // low (4) because each comment card renders Markdown — mounting a
      // dozen at once produced a ~400 ms synchronous long task on a
      // busy PR. Virtuoso streams the rest in within the overscan
      // window on the next frames, so the visible result is still full.
      initialItemCount={Math.min(compressed.length, 4)}
      // Overscan in px: enough to keep fast scrolling smooth (cards are
      // tall) while bounding the mounted-node count well below total.
      overscan={400}
      itemContent={(i, entry) => (
        <TimelineRow
          entry={entry}
          index={i}
          viewerLogin={viewerLogin}
          authorLogin={authorLogin}
          owner={owner}
          repo={repo}
          number={number}
          headSha={headSha}
          baseSha={baseSha}
          focusMode={collapseEvents}
          onlyUnreplied={onlyUnreplied}
          onShowAll={onShowAll}
          onExpandSettled={expandSettled}
          collapse={collapse}
          flashReviewId={flashReviewId}
          onScopeToCommit={onScopeToCommit}
          onShowInDiff={onShowInDiff}
          gqlThread={
            entry.kind === 'single' && entry.item.kind === 'thread'
              ? threadByHead.get(entry.item.head.id)
              : undefined
          }
        />
      )}
    />
  );
}

/** One virtualized timeline row. Wraps the per-entry render switch
 * (previously inlined in `compressed.map`) and draws the vertical rail
 * segment behind it so the rail spans the full content even though
 * Virtuoso only mounts the visible rows. */
function TimelineRow({
  entry,
  index,
  viewerLogin,
  authorLogin,
  owner,
  repo,
  number,
  headSha,
  baseSha,
  focusMode = false,
  onlyUnreplied = false,
  onShowAll,
  onExpandSettled,
  collapse,
  flashReviewId,
  gqlThread,
  onScopeToCommit,
  onShowInDiff,
}: {
  entry: CompressedEntry;
  index: number;
  viewerLogin?: string;
  authorLogin?: string;
  owner?: string;
  repo?: string;
  number?: number;
  headSha?: string;
  baseSha?: string;
  focusMode?: boolean;
  /** "New comments" focus variant — threads not awaiting the viewer's
   * reply default to collapsed (forwarded to TimelineThreadItem). */
  onlyUnreplied?: boolean;
  onShowAll?: () => void;
  /** Expand the given settled-row keys in place (out of their band). */
  onExpandSettled?: (keys: string[]) => void;
  collapse: CollapsedCommentsValue;
  /** Review id currently being flash-pulsed by a HoverCard jump. */
  flashReviewId?: number | null;
  gqlThread?: ResolvableThread;
  onScopeToCommit?: (sha: string) => void;
  onShowInDiff?: (target: {
    path: string;
    line: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
  }) => void;
}) {
  let inner: React.ReactNode;
  if (entry.kind === 'new-changes') {
    inner = <NewChangesDivider />;
  } else if (entry.kind === 'collapsed') {
    inner = <EventsCollapsed count={entry.count} onShow={onShowAll} />;
  } else if (entry.kind === 'settled-band') {
    const bandRows = entry.rows;
    inner = (
      <SettledBand
        count={bandRows.length}
        onExpandAll={() => onExpandSettled?.(bandRows.map((r) => r.key))}
      >
        {bandRows.map((r) => (
          <CompactSettledRow
            key={r.key}
            {...r.compact}
            onExpand={() => onExpandSettled?.([r.key])}
          />
        ))}
      </SettledBand>
    );
  } else if (entry.kind === 'run') {
    inner = (
      <ForcePushRun
        actor={entry.actor}
        actorAvatarUrl={entry.actorAvatarUrl}
        count={entry.count}
        firstTs={entry.firstTs}
        lastTs={entry.lastTs}
      />
    );
  } else if (entry.item.kind === 'thread') {
    inner = (
      <TimelineThreadItem
        head={entry.item.head}
        replies={entry.item.replies}
        viewerLogin={viewerLogin}
        authorLogin={authorLogin}
        owner={owner}
        repo={repo}
        number={number}
        headSha={headSha}
        baseSha={baseSha}
        focusMode={focusMode}
        onlyUnreplied={onlyUnreplied}
        collapse={collapse}
        gqlThread={gqlThread}
        onShowInDiff={onShowInDiff}
      />
    );
  } else if (entry.item.kind === 'review') {
    inner = (
      <TimelineReviewItem
        review={entry.item.review}
        viewerLogin={viewerLogin}
        authorLogin={authorLogin}
        collapse={collapse}
        onlyUnreplied={onlyUnreplied}
        flash={flashReviewId != null && entry.item.review.id === flashReviewId}
      />
    );
  } else {
    inner = (
      <TimelineEventItem
        event={entry.item.event}
        viewerLogin={viewerLogin}
        authorLogin={authorLogin}
        owner={owner}
        repo={repo}
        number={number}
        collapse={collapse}
        onlyUnreplied={onlyUnreplied}
        onScopeToCommit={onScopeToCommit}
      />
    );
  }
  // The rail segment spans this row's full height at the node centre
  // (left-[15.3px], matching the old single absolute rail). Adjacent rows
  // abut, so the segments form one continuous line. The TimelineNode's
  // box-shadow ring still punches the hole over the line at each node.
  // The settled band is a self-contained card with no rail node, so the
  // line behind it reads as a stray stripe — skip it there.
  // `void index` keeps the param available for future keying without an
  // unused-var lint.
  void index;
  return (
    <div className="relative">
      {entry.kind !== 'settled-band' && (
        <div className="absolute bottom-0 left-[15.3px] top-0 w-px bg-border" />
      )}
      {inner}
    </div>
  );
}

/** Compacted timeline output. A `single` entry renders one Item; a
 * `run` collapses 2+ consecutive force-pushes from the same author
 * into a single condensed row. */
type CompressedEntry =
  | { kind: 'single'; item: Item }
  | {
      kind: 'run';
      actor: string;
      actorAvatarUrl?: string;
      count: number;
      firstTs: string | null;
      lastTs: string | null;
    }
  /** Conversation-focus collapse: a run of N consecutive non-comment
   * events folded into a single divider. */
  | { kind: 'collapsed'; count: number }
  /** Conversation-focus collapse: a run of consecutive SETTLED discussion
   * items (resolved / outdated / stale) demoted to compact one-line rows
   * inside a single quiet band. */
  | { kind: 'settled-band'; rows: SettledRow[] }
  /** "New changes since you last viewed" divider, inserted before the
   * first commit/force-push newer than the viewer's last-viewed instant. */
  | { kind: 'new-changes' };

/** One settled discussion item: its compact-row props plus a stable key
 * (the underlying item's id) for React. */
interface SettledRow {
  key: string;
  compact: SettledCompact;
}

/** Stable per-row identity for Virtuoso's `computeItemKey`. Keying by the
 * underlying comment/review/event id (not the array index) lets Virtuoso
 * anchor a row to the same DOM node across re-renders, which alone tames a
 * lot of the bottom-up jump, and gives `conversationListSnapshot` a content
 * signature its index-based size cache can be validated against. Aggregate
 * rows (runs, settled bands, dividers) fall back to a per-kind key, with the
 * index only as a last resort for the id-less cases. */
function entryKey(index: number, entry: CompressedEntry): string {
  if (entry.kind === 'single') {
    const it = entry.item;
    if (it.kind === 'thread') return `thread:${it.head.id}`;
    if (it.kind === 'review') return `review:${it.review.id}`;
    return `event:${it.event.id ?? `${it.ts}-${index}`}`;
  }
  if (entry.kind === 'run') return `run:${entry.actor}:${entry.firstTs ?? index}`;
  if (entry.kind === 'settled-band') return `band:${entry.rows[0]?.key ?? index}`;
  if (entry.kind === 'new-changes') return 'new-changes';
  return `collapsed:${index}`;
}

/** The "change" timestamp of a compressed entry, or null when it isn't a
 * code change. Only commits and force-pushes count as "new changes" — new
 * comments/reviews are discussion, not changes, so they don't trip the
 * marker (matching GitHub's commit-scoped banner). */
function changeTs(entry: CompressedEntry): number | null {
  if (entry.kind === 'run') return parseTs(entry.firstTs);
  if (entry.kind !== 'single' || entry.item.kind !== 'event') return null;
  const ev = entry.item.event.event;
  return ev === 'committed' || ev === 'head_ref_force_pushed'
    ? entry.item.ts
    : null;
}

/** Drop a single "New changes since you last viewed" divider before the
 * earliest commit/push newer than `baseline`. No-op when the viewer has
 * no baseline (first visit) or nothing is newer than it. */
function insertNewChangesDivider(
  entries: CompressedEntry[],
  baseline: number | null,
): CompressedEntry[] {
  if (!baseline) return entries;
  const idx = entries.findIndex((e) => {
    const ts = changeTs(e);
    return ts != null && ts > baseline;
  });
  if (idx < 0) return entries;
  const out = entries.slice();
  out.splice(idx, 0, { kind: 'new-changes' });
  return out;
}

/** True for timeline items that are "discussion" — comments, review
 * verdicts, and inline threads — which Conversation focus keeps. Every
 * other event (commits, pushes, labels, CI, assigns…) is collapsible
 * noise. */
function isDiscussion(item: Item): boolean {
  if (item.kind === 'review' || item.kind === 'thread') return true;
  return item.kind === 'event' && item.event.event === 'commented';
}

/** Count the timeline events that comments-only focus omits, mirroring
 * the merge in <Timeline>: `reviewed` / `line-commented` are rendered
 * from /reviews + /comments instead (so they never become timeline
 * events), and `commented` is the only event kind focus keeps. Every
 * other event (commits, pushes, labels, assigns, review-requests,
 * CI/bot, renamed, referenced…) is hidden. Reviews and inline threads
 * are always discussion, so they never count toward the hidden total.
 * Used only to fill the FocusCommentsStrip copy. */
function countNonDiscussion(
  events: GHTimelineEvent[],
  _reviews: GHReview[],
  _reviewComments: GHReviewComment[],
): number {
  void _reviews;
  void _reviewComments;
  return events.filter(
    (e) =>
      e.event !== 'reviewed' &&
      e.event !== 'line-commented' &&
      e.event !== 'commented',
  ).length;
}

/** Comments-only focus: OMIT every non-discussion item entirely (no
 * collapse-divider stand-in) so the timeline reads as pure discussion.
 * The escape hatch is the FocusCommentsStrip's "Show all activity"
 * button — which exits focus and restores the full timeline — so we
 * don't render per-run dividers here (AFK plan 09).
 *
 * SETTLED discussion (resolved / outdated / stale) is further demoted:
 * runs of consecutive settled items collapse into one `settled-band` of
 * compact rows, keeping their chronological position (not bucketed),
 * while open/pending items stay full `single` cards between bands. */
function collapseForFocus(
  items: Item[],
  settledOf: (item: Item) => SettledRow | null,
  /** Settled-row keys the viewer has expanded in place — they leave the
   * band and render as full cards at their chronological position, so the
   * band splits around them while its other rows stay compact. */
  expandedSettled: Set<string>,
): CompressedEntry[] {
  const discussion = items.filter(isDiscussion);
  const out: CompressedEntry[] = [];
  const settledRow = (item: Item): SettledRow | null => {
    const row = settledOf(item);
    return row && !expandedSettled.has(row.key) ? row : null;
  };
  let i = 0;
  while (i < discussion.length) {
    if (!settledRow(discussion[i])) {
      out.push({ kind: 'single', item: discussion[i] });
      i++;
      continue;
    }
    const rows: SettledRow[] = [];
    let r: SettledRow | null;
    while (i < discussion.length && (r = settledRow(discussion[i]))) {
      rows.push(r);
      i++;
    }
    out.push({ kind: 'settled-band', rows });
  }
  return out;
}

/** Settle-resolver factory: maps a timeline Item to its compact settled
 * row, or null when the item is still open/pending. Bound to the thread
 * resolution map + viewer + clock so the compression memo can call it. */
function makeSettledOf(
  threadByHead: Map<number, ResolvableThread>,
  viewerLogin: string | undefined,
  now: number,
  /** Pending-comments variant: also compact threads the viewer has
   * already handled (you replied last), not just resolved/outdated/stale. */
  compactHandled: boolean,
): (item: Item) => SettledRow | null {
  return (item) => {
    if (item.kind === 'thread') {
      const compact = settledForThread(
        item.head,
        item.replies,
        threadByHead.get(item.head.id),
        viewerLogin,
        now,
        compactHandled,
      );
      return compact ? { key: `thread:${item.head.id}`, compact } : null;
    }
    if (item.kind === 'review') {
      const compact = settledForReview(item.review, now);
      return compact ? { key: `review:${item.review.id}`, compact } : null;
    }
    const compact = settledForComment(item.event, now);
    return compact
      ? { key: `comment:${item.event.id ?? item.ts}`, compact }
      : null;
  };
}

/** Roll up consecutive `head_ref_force_pushed` rows from the same
 * actor. We deliberately don't collapse other event kinds for v1 —
 * `labeled` / `assigned` / `referenced` runs are rare and the design
 * shows them inline anyway. */
function groupRuns(items: Item[]): CompressedEntry[] {
  const out: CompressedEntry[] = [];
  let i = 0;
  while (i < items.length) {
    const cur = items[i];
    if (
      cur.kind === 'event' &&
      cur.event.event === 'head_ref_force_pushed'
    ) {
      const actor = cur.event.actor?.login ?? 'unknown';
      const actorAvatarUrl = cur.event.actor?.avatar_url;
      let j = i;
      while (
        j < items.length &&
        items[j].kind === 'event' &&
        (items[j] as { kind: 'event'; event: GHTimelineEvent }).event.event ===
          'head_ref_force_pushed' &&
        ((items[j] as { kind: 'event'; event: GHTimelineEvent }).event.actor
          ?.login ?? 'unknown') === actor
      ) {
        j++;
      }
      const count = j - i;
      if (count >= 2) {
        const first = (items[i] as { kind: 'event'; event: GHTimelineEvent })
          .event.created_at ?? null;
        const last =
          (items[j - 1] as { kind: 'event'; event: GHTimelineEvent }).event
            .created_at ?? null;
        out.push({
          kind: 'run',
          actor,
          actorAvatarUrl,
          count,
          firstTs: first,
          lastTs: last,
        });
        i = j;
        continue;
      }
    }
    out.push({ kind: 'single', item: cur });
    i++;
  }
  return out;
}

/** Compact summary row for a run of N consecutive force-pushes from
 * the same author. Reuses the bullet-row style so it sits flush
 * against single force-push rows without a layout jolt. */
function ForcePushRun({
  actor,
  actorAvatarUrl,
  count,
  firstTs,
  lastTs,
}: {
  actor: string;
  actorAvatarUrl?: string;
  count: number;
  firstTs: string | null;
  lastTs: string | null;
}) {
  const span = firstTs && lastTs && firstTs !== lastTs
    ? `${humanAge(firstTs)} → ${humanAge(lastTs)} ago`
    : lastTs
      ? `${humanAge(lastTs)} ago`
      : '';
  const spanTitle = firstTs && lastTs && firstTs !== lastTs
    ? `${fullDate(firstTs)} → ${fullDate(lastTs)}`
    : fullDate(lastTs);
  return (
    <GenericRow
      icon="branch"
      color="hsl(var(--pyor-warn))"
      actor={actor}
      actorAvatarUrl={actorAvatarUrl}
      body={
        <>
          force-pushed the branch{' '}
          <b className="text-foreground tabular-nums">{count} times</b>
        </>
      }
      ts={null}
      tsOverride={span}
      tsTitle={spanTitle}
    />
  );
}

function TimelineNode({
  icon,
  color,
  big,
}: {
  icon: IconName;
  color: string;
  big?: boolean;
}) {
  // Box-shadow ring punches a hole in the rail line at the node so
  // the line doesn't show through the node circle. Width/height/
  // margin-left are pixel-locked to the rail alignment in
  // TimelineBlock — keep them in lockstep.
  return (
    <div
      className="relative z-[1] flex shrink-0 items-center justify-center rounded-full border bg-card shadow-[0_0_0_4px_hsl(var(--panel))]"
      style={{
        width: big ? 36 : 26,
        height: big ? 36 : 26,
        marginLeft: big ? -3 : 3,
        marginBlock: big ? undefined : 4,
      }}
    >
      <Icon name={icon} size={big ? 16 : 12} color={color} />
    </div>
  );
}

function TimelineReviewItem({
  review,
  viewerLogin,
  authorLogin,
  collapse,
  onlyUnreplied = false,
  flash = false,
}: {
  review: GHReview;
  viewerLogin?: string;
  authorLogin?: string;
  collapse: CollapsedCommentsValue;
  /** "New comments" focus — a plain COMMENTED review summary (bot recap,
   * announcement) isn't a thread awaiting a reply, so it defaults
   * collapsed. Actual APPROVED / CHANGES_REQUESTED verdicts stay expanded. */
  onlyUnreplied?: boolean;
  /** Briefly ring-pulse this card after a HoverCard "View comment" jump. */
  flash?: boolean;
}) {
  // Review-state palette: shadcn Badge variants don't cover the
  // "approved/changes/commented" tri-state on their own, so we layer
  // Tailwind utilities that consume the same pyor-pass/pyor-fail
  // CSS vars used elsewhere.
  const meta =
    review.state === 'APPROVED'
      ? {
          icon: 'check-circle' as const,
          color: 'hsl(var(--pyor-pass))',
          chipClass:
            'border-transparent bg-pyor-pass/15 text-pyor-pass font-semibold',
          chipText: 'Approved',
          verb: 'approved these changes',
          highlight: 'approved' as GhCommentHighlight,
        }
      : review.state === 'CHANGES_REQUESTED'
        ? {
            icon: 'x-circle' as const,
            color: 'hsl(var(--pyor-fail))',
            chipClass:
              'border-transparent bg-pyor-fail/15 text-pyor-fail font-semibold',
            chipText: 'Changes requested',
            verb: 'requested changes',
            highlight: 'changes' as GhCommentHighlight,
          }
        : {
            icon: 'comment' as const,
            color: 'hsl(var(--muted-foreground))',
            chipClass:
              'border-transparent bg-muted text-muted-foreground font-semibold',
            chipText: 'Commented',
            verb: 'left a review',
            highlight: null as GhCommentHighlight,
          };
  const isYou = !!viewerLogin && review.user?.login === viewerLogin;
  const hasBody = review.body && review.body.trim() !== '';
  const prRole = prRoleFor(review.user?.login, authorLogin, true);
  // Under "New comments" focus, a plain COMMENTED review summary is just a
  // standalone remark (often a bot recap), so it defaults collapsed like a
  // top-level comment. APPROVED / CHANGES_REQUESTED verdicts are meaningful
  // signals and stay expanded.
  const reviewAutoCollapsed =
    onlyUnreplied &&
    review.state !== 'APPROVED' &&
    review.state !== 'CHANGES_REQUESTED';

  // No write-up → collapse to a condensed one-line pill card instead of a
  // full card with an empty "No comment was left" body (designer handoff:
  // review-verdict-handoff). The verdict node + chip carry the meaning; the
  // full card chrome would just read as a comment that failed to load.
  if (!hasBody) {
    return (
      <div className="flex items-center gap-3 py-1">
        <TimelineNode icon={meta.icon} color={meta.color} big />
        <div
          className={
            'min-w-0 flex-1 rounded-lg transition-shadow duration-500' +
            (flash
              ? ' ring-2 ring-primary ring-offset-2 ring-offset-panel'
              : '')
          }
        >
          <ReviewVerdictRow
            author={review.user?.login ?? 'unknown'}
            authorAvatarUrl={review.user?.avatar_url}
            verb={meta.verb}
            chipClass={meta.chipClass}
            chipText={meta.chipText}
            prRole={prRole}
            isYou={isYou}
            age={
              review.submitted_at
                ? `${humanAge(review.submitted_at)} ago`
                : undefined
            }
            ageTitle={fullDate(review.submitted_at)}
          />
        </div>
      </div>
    );
  }
  return (
    <div className="flex gap-3 py-2">
      <TimelineNode icon={meta.icon} color={meta.color} big />
      <div
        className={
          'min-w-0 flex-1 rounded-lg transition-shadow duration-500' +
          (flash ? ' ring-2 ring-primary ring-offset-2 ring-offset-panel' : '')
        }
      >
        <GhComment
          author={review.user?.login ?? 'unknown'}
          authorAvatarUrl={review.user?.avatar_url}
          association={review.author_association}
          prRole={prRole}
          age={review.submitted_at ? `${humanAge(review.submitted_at)} ago` : undefined}
          ageTitle={fullDate(review.submitted_at)}
          isYou={isYou}
          htmlUrl={review.html_url}
          highlight={meta.highlight}
          verdictChip={
            // `outline` variant carries no background + no hover; the
            // chipClass supplies the verdict colours. The default variant's
            // `hover:bg-primary/80` would otherwise flash on hover even
            // though the chip is non-interactive.
            <Badge variant="outline" className={meta.chipClass}>
              {meta.chipText}
            </Badge>
          }
          reactions={review.reactions}
          preview={plainTextPreview(review.body!)}
          previewSource={review.body!}
          collapsed={collapse.isCollapsed(`review:${review.id}`, reviewAutoCollapsed)}
          onCollapsedChange={() =>
            collapse.toggle(`review:${review.id}`, reviewAutoCollapsed)
          }
        >
          {/* Empty-body reviews never reach here — they render as a slim
           * ReviewVerdictRow above. So the body is always real prose. */}
          <Markdown source={review.body!} size="sm" />
        </GhComment>
      </div>
    </div>
  );
}

/** Condensed one-line "pill card" for a review verdict that carries no
 * written comment — the common "just hit Approve" case. Replaces the
 * old full card whose only body was "No comment was left with this
 * review." (designer handoff: review-verdict-handoff, "pill" variant).
 * A contained bordered surface, lighter than the full GhComment card.
 * The colored rail node is rendered by the caller; this is just the
 * row content: avatar · "<author> <verb>" · verdict chip · role pill · age. */
function ReviewVerdictRow({
  author,
  authorAvatarUrl,
  verb,
  chipClass,
  chipText,
  prRole,
  isYou,
  age,
  ageTitle,
}: {
  author: string;
  authorAvatarUrl?: string;
  verb: string;
  chipClass: string;
  chipText: string;
  prRole?: import('./prRole').PrRole | null;
  isYou?: boolean;
  age?: string;
  ageTitle?: string;
}) {
  const role = prRole === 'author' ? 'Author' : 'Reviewer';
  const initials = author
    .split(/[\s-]+/)
    .map((s) => s[0] ?? '')
    .slice(0, 2)
    .join('')
    .toUpperCase();
  return (
    <div className="flex items-center gap-2 rounded-lg border bg-card px-2.5 py-1.5 text-[13px] shadow-sm dark:shadow-none">
      <Avatar className="size-5 shrink-0">
        {authorAvatarUrl && <AvatarImage src={authorAvatarUrl} alt={author} />}
        <AvatarFallback style={{ fontSize: 9 }}>{initials}</AvatarFallback>
      </Avatar>
      <span className="min-w-0 truncate whitespace-nowrap text-muted-foreground">
        <span className="font-semibold text-foreground">{author}</span> {verb}
      </span>
      <Badge variant="outline" className={`shrink-0 ${chipClass}`}>
        {chipText}
      </Badge>
      <span
        className={
          'shrink-0 whitespace-nowrap rounded-full border px-1.5 py-0 text-[9.5px] font-medium uppercase tracking-wider ' +
          (prRole === 'author'
            ? 'border-primary/40 bg-primary/10 text-primary'
            : 'border-transparent text-muted-foreground')
        }
      >
        {isYou ? 'You' : role}
      </span>
      {age && (
        <span
          className="ml-auto shrink-0 whitespace-nowrap text-[12px] tabular-nums text-muted-foreground"
          title={ageTitle}
        >
          {age}
        </span>
      )}
    </div>
  );
}

/** Render a line-anchored review thread (head comment + replies) as
 * a GhInlineThread card hung off the timeline rail. The rail node
 * uses the same speech-bubble icon as inline comments so the eye
 * tracks the thread to its file/line anchor. */
function TimelineThreadItem({
  head,
  replies,
  viewerLogin,
  authorLogin,
  owner,
  repo,
  number,
  headSha,
  baseSha,
  focusMode = false,
  onlyUnreplied = false,
  collapse,
  gqlThread,
  onShowInDiff,
}: {
  head: GHReviewComment;
  replies: GHReviewComment[];
  viewerLogin?: string;
  authorLogin?: string;
  owner?: string;
  repo?: string;
  number?: number;
  /** Head + base SHA from the PR. Used to look up the cached file
   * content for the thread's anchor file via the same query key
   * PRDetailScreen populates. */
  headSha?: string;
  baseSha?: string;
  /** Conversation "Focus: Comments" — outdated threads collapse to a
   * stub by default. Forwarded to ReviewThread. */
  focusMode?: boolean;
  /** "New comments" focus variant — when on, a thread whose latest
   * comment is the viewer's own (nothing awaiting their reply) defaults
   * to collapsed instead of being dropped from the timeline. */
  onlyUnreplied?: boolean;
  /** Shared per-PR collapse set — the head folds the whole thread
   * (`thread:<id>`), each reply folds itself (`reply:<id>`). */
  collapse: CollapsedCommentsValue;
  /** GraphQL thread record (node id + resolution + viewer permission
   * flags). Drives the Resolved badge, the resolve footer, AND makes a
   * resolved thread default to collapsed (matching GitHub) until the
   * user explicitly expands it. Undefined until the threadIds query
   * lands. */
  gqlThread?: ResolvableThread;
  /** "Show in diff" — jump to the Changes tab + scroll to this thread's
   * anchor. Forwarded to ReviewThread's anchor header. */
  onShowInDiff?: (target: {
    path: string;
    line: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
  }) => void;
}) {
  const qc = useQueryClient();
  const resolved = gqlThread?.isResolved === true;
  // Reach into the Files tab's content cache to find this thread's
  // anchor file. The query key is set up in PRDetailScreen; we read
  // it without subscribing because we only need the snapshot at
  // render time (no need to re-render on streaming updates — the
  // snippet picks the latest snapshot on its next paint). If the
  // user opened Conversation before Files contents streamed in,
  // `fileEntry` will be undefined and DiffHunkSnippet degrades to
  // the bare-hunk rendering until contents land.
  const fileContents = owner && repo && number && headSha && baseSha
    ? qc.getQueryData<Map<string, FileContents>>([
        'pr',
        owner,
        repo,
        number,
        'contents',
        headSha,
        baseSha,
      ])
    : undefined;
  const outdated = head.line == null && head.original_line != null;
  // The diff_hunk is ALWAYS numbered against the commit the comment was made
  // on (`original_commit_id`), not the PR head — true even for a "live"
  // comment whose anchor line has drifted but still maps into the latest diff
  // (`head.line` set yet ≠ `original_line`). So source the snippet's file
  // content from that commit, and only reuse the head/base Files-tab cache
  // when the comment was made on the head commit (the SHAs match), where the
  // two are identical. Pulling head content for a drifted comment would not
  // line up with the frozen hunk and the file-context expanders would vanish.
  const rightSha = head.original_commit_id || headSha;
  const cachedEntry =
    rightSha === headSha ? fileContents?.get(head.path) : undefined;
  // If the Files-tab content cache doesn't have this file yet (the
  // common case on the Conversation tab), lazily fetch just this one
  // file's blobs so the snippet can expand context *after* the
  // commented line — `diff_hunk` is truncated at the comment, so the
  // tail only exists in the full file content. Gated on the thread
  // being expanded so collapsed threads cost nothing.
  const threadKey = `thread:${head.id}`;
  // Auto-collapse when the thread is resolved OR, under "New comments"
  // focus, when it isn't awaiting the viewer's reply (handled, or one
  // the viewer started that's had no reply yet). The user can still
  // expand any of these from the chevron — the override survives.
  const autoCollapsed =
    resolved ||
    (onlyUnreplied && !threadAwaitsViewer([head, ...replies], viewerLogin));
  const threadCollapsed = collapse.isCollapsed(threadKey, autoCollapsed);
  const enableFileFetch =
    !cachedEntry &&
    !threadCollapsed &&
    !!(owner && repo && number && rightSha && baseSha) &&
    !!head.diff_hunk;
  const singleFileQuery = useQuery({
    queryKey: [
      'pr',
      owner,
      repo,
      number,
      'thread-file',
      head.path,
      rightSha,
      baseSha,
    ],
    queryFn: () =>
      fetchSingleFileContents(owner!, repo!, head.path, rightSha!, baseSha!),
    enabled: enableFileFetch,
    staleTime: Infinity,
  });
  const fileEntry = cachedEntry ?? singleFileQuery.data;
  // Review-comment reactions live on the GHReviewComment row inside
  // the shared `comments` query. Optimistic update finds the comment
  // by id + bumps its reactions counter; reply posts still go through
  // a plain invalidate (a new row doesn't have a stable shape to
  // patch in client-side).
  const reviewCommentsKey = ['pr', owner, repo, number, 'comments'] as const;
  const invalidateReviewComments = () =>
    void qc.invalidateQueries({ queryKey: reviewCommentsKey });
  const patchReviewComment = (
    commentId: number,
    content: ReactionContent,
    delta: 1 | -1,
  ) => (curr: GHReviewComment[] | undefined) =>
    curr?.map((c) =>
      c.id === commentId
        ? { ...c, reactions: bumpReactionCount(c.reactions, content, delta) }
        : c,
    );
  const onAddReaction = owner && repo && number
    ? async (commentId: number, key: keyof GHReactions) => {
        const c = asReactionContent(key);
        if (!c) return;
        try {
          await withOptimisticReaction<GHReviewComment[]>(
            qc,
            reviewCommentsKey,
            patchReviewComment(commentId, c, 1),
            () => addReviewCommentReaction(owner, repo, commentId, c),
          );
        } catch (e) {
          toast.error('Could not add reaction', {
            description: e instanceof Error ? e.message : String(e),
          });
        }
      }
    : undefined;
  const onRemoveReaction = owner && repo && number
    ? async (commentId: number, key: keyof GHReactions, reactionId: number) => {
        const c = asReactionContent(key);
        if (!c) return;
        try {
          await withOptimisticReaction<GHReviewComment[]>(
            qc,
            reviewCommentsKey,
            patchReviewComment(commentId, c, -1),
            () =>
              removeReviewCommentReaction(owner, repo, commentId, reactionId),
          );
        } catch (e) {
          toast.error('Could not remove reaction', {
            description: e instanceof Error ? e.message : String(e),
          });
        }
      }
    : undefined;
  // Normalised thread the shared ReviewThread consumes (same component the
  // Changes tab renders). `withAnchor` makes it draw the "{author} started a
  // thread" header + embed the diff-hunk snippet, since the timeline has no
  // surrounding diff. `threadCollapsed` above still gates the lazy hunk-file
  // fetch.
  const reviewThread: CommentThread = {
    headId: head.id,
    path: head.path,
    line: head.line ?? head.original_line ?? 0,
    side: head.side,
    startLine: head.start_line ?? head.line ?? head.original_line ?? 0,
    comments: [head, ...replies],
    outdated,
    isFileLevel: head.subject_type === 'file',
    graphqlNodeId: gqlThread?.id,
    isResolved: resolved,
    resolvedBy: gqlThread?.resolvedBy,
    viewerCanResolve: gqlThread?.viewerCanResolve,
    viewerCanUnresolve: gqlThread?.viewerCanUnresolve,
  };
  const reviewReactions: ReviewThreadReactions = {
    onAdd: (commentId, key) => onAddReaction?.(commentId, key),
    onRemove: (commentId, key, reactionId) =>
      onRemoveReaction?.(commentId, key, reactionId),
    listReactors: (commentId) =>
      owner && repo
        ? listReviewCommentReactors(owner, repo, commentId)
        : Promise.resolve([]),
  };
  // Edit/delete for the viewer's PENDING comments shown in the timeline.
  // The lean hook only touches the shared cache (no query subscription),
  // so calling it per-thread adds no re-render pressure. ReviewThread
  // shows the affordances only on the viewer's own pending comments.
  const pendingActions = usePendingCommentActions(owner ?? '', repo ?? '', number ?? 0);
  return (
    <div className="flex gap-3 py-2">
      <TimelineNode
        icon="comment"
        color="hsl(var(--muted-foreground))"
      />
      <div className="min-w-0 flex-1">
        <ReviewThread
          thread={reviewThread}
          owner={owner!}
          repo={repo!}
          number={number!}
          viewerLogin={viewerLogin}
          prAuthorLogin={authorLogin}
          collapse={collapse}
          focusMode={focusMode}
          onChanged={invalidateReviewComments}
          reactions={reviewReactions}
          pendingActions={pendingActions}
          withAnchor
          newText={fileEntry?.newText}
          oldText={fileEntry?.oldText}
          onShowInDiff={onShowInDiff}
        />
      </div>
    </div>
  );
}

function TimelineEventItem({
  event,
  viewerLogin,
  authorLogin,
  owner,
  repo,
  number,
  collapse,
  onlyUnreplied = false,
  onScopeToCommit,
}: {
  event: GHTimelineEvent;
  viewerLogin?: string;
  authorLogin?: string;
  owner?: string;
  repo?: string;
  number?: number;
  collapse: CollapsedCommentsValue;
  /** "New comments" focus variant — forwarded to CommentItem so a
   * top-level comment the viewer authored (handled) defaults collapsed. */
  onlyUnreplied?: boolean;
  onScopeToCommit?: (sha: string) => void;
}) {
  // Faint vs. semantic colors map to CSS-variable HSL refs (read
  // directly from CSS rather than tokens.ts now that useT is gone).
  const faint = 'hsl(var(--muted-foreground) / 0.6)';
  const pass = 'hsl(var(--pyor-pass))';
  const fail = 'hsl(var(--pyor-fail))';
  const warn = 'hsl(var(--pyor-warn))';
  switch (event.event) {
    case 'commented':
      return (
        <CommentItem
          event={event}
          viewerLogin={viewerLogin}
          authorLogin={authorLogin}
          owner={owner}
          repo={repo}
          number={number}
          collapse={collapse}
          onlyUnreplied={onlyUnreplied}
        />
      );
    case 'committed':
      return (
        <CommitItem
          event={event}
          owner={owner}
          repo={repo}
          number={number}
          onScopeToCommit={onScopeToCommit}
        />
      );
    case 'labeled':
    case 'unlabeled':
      return (
        <GenericRow
          icon="dot"
          color={faint}
          actor={
            event.actor?.login ??
            event.user?.login ??
            'unknown'
          }
          actorAvatarUrl={event.actor?.avatar_url ?? event.user?.avatar_url}
          body={
            <>
              {event.event === 'labeled' ? 'added' : 'removed'}{' '}
              {event.label ? (
                <Label color={`#${event.label.color}`} text={event.label.name} />
              ) : (
                <em>a label</em>
              )}
            </>
          }
          ts={event.created_at}
        />
      );
    case 'assigned':
    case 'unassigned':
      return (
        <GenericRow
          icon="eye"
          color={faint}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={
            <>
              {event.event === 'assigned' ? 'assigned' : 'unassigned'}{' '}
              <b className="text-foreground">
                {event.assignee?.login ?? 'someone'}
              </b>
            </>
          }
          ts={event.created_at}
        />
      );
    case 'review_requested':
    case 'review_request_removed':
      return (
        <GenericRow
          icon="eye"
          color={faint}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={
            <>
              {event.event === 'review_requested'
                ? 'requested a review from'
                : 'removed a review request for'}{' '}
              <b className="text-foreground">
                {event.requested_reviewer?.login ?? 'someone'}
              </b>
            </>
          }
          ts={event.created_at}
        />
      );
    case 'referenced':
    case 'cross-referenced': {
      const src = event.source?.issue;
      return (
        <GenericRow
          icon="external"
          color={faint}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={
            <>
              referenced this in{' '}
              {src ? (
                <span className="font-mono text-[11.5px]">
                  {src.repository?.full_name ?? ''}#{src.number}
                </span>
              ) : (
                'another issue'
              )}
            </>
          }
          ts={event.created_at}
        />
      );
    }
    case 'closed':
      return (
        <GenericRow
          icon="x"
          color={fail}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={<>closed this</>}
          ts={event.created_at}
        />
      );
    case 'reopened':
      return (
        <GenericRow
          icon="pr-open"
          color={pass}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={<>reopened this</>}
          ts={event.created_at}
        />
      );
    case 'merged':
      return (
        <GenericRow
          icon="pr-merged"
          color="hsl(var(--primary))"
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={
            <>
              merged commit{' '}
              <span className="font-mono text-[11.5px]">
                {(event.sha ?? '').slice(0, 7)}
              </span>
            </>
          }
          ts={event.created_at}
        />
      );
    case 'head_ref_force_pushed':
      return (
        <GenericRow
          icon="branch"
          color={warn}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={<>force-pushed the branch</>}
          ts={event.created_at}
        />
      );
    case 'head_ref_deleted':
      return (
        <GenericRow
          icon="branch"
          color={faint}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={<>deleted the head branch</>}
          ts={event.created_at}
        />
      );
    case 'renamed':
      return (
        <GenericRow
          icon="info"
          color={faint}
          actor={event.actor?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url}
          body={
            <>
              renamed the title{' '}
              {event.rename && (
                <>
                  from <i>{event.rename.from}</i> to <i>{event.rename.to}</i>
                </>
              )}
            </>
          }
          ts={event.created_at}
        />
      );
    case 'mentioned':
    case 'subscribed':
      // Low-signal events — skip rendering to keep the timeline scannable.
      return null;
    default:
      // Unknown event: render a faint generic row so it's at least visible.
      return (
        <GenericRow
          icon="dot"
          color={faint}
          actor={event.actor?.login ?? event.user?.login ?? 'unknown'}
          actorAvatarUrl={event.actor?.avatar_url ?? event.user?.avatar_url}
          body={<em>{event.event}</em>}
          ts={event.created_at}
        />
      );
  }
}

function CommentItem({
  event,
  viewerLogin,
  authorLogin,
  owner,
  repo,
  number,
  collapse,
  onlyUnreplied = false,
}: {
  event: GHTimelineEvent;
  viewerLogin?: string;
  authorLogin?: string;
  owner?: string;
  repo?: string;
  number?: number;
  collapse: CollapsedCommentsValue;
  /** "New comments" focus variant — when on, a top-level comment the
   * viewer authored (already handled) defaults to collapsed, mirroring a
   * review thread whose latest reply is the viewer's. */
  onlyUnreplied?: boolean;
}) {
  const qc = useQueryClient();
  const confirm = useConfirm();
  const who = event.user?.login ?? event.actor?.login ?? 'unknown';
  const avatarUrl = event.user?.avatar_url ?? event.actor?.avatar_url;
  const isYou = !!viewerLogin && who === viewerLogin;
  const body = event.body ?? '';
  const edited =
    event.updated_at && event.created_at && event.updated_at !== event.created_at
      ? humanAge(event.updated_at)
      : null;
  // Top-level conversation comments live inside the timeline array
  // — patch the matching event's reactions in place. The reaction-
  // API endpoint takes the comment's REST id (event.id, set on
  // `commented` items by the timeline endpoint).
  const timelineKey = [
    'pr',
    owner,
    repo,
    number,
    'timeline',
  ] as const;
  const patchTimelineComment = (
    eventId: number,
    content: ReactionContent,
    delta: 1 | -1,
  ) => (curr: GHTimelineEvent[] | undefined) =>
    curr?.map((e) =>
      e.id === eventId
        ? { ...e, reactions: bumpReactionCount(e.reactions, content, delta) }
        : e,
    );
  const onAddReaction = owner && repo && number && event.id
    ? (key: keyof GHReactions) => {
        const c = asReactionContent(key);
        if (!c) return;
        return withOptimisticReaction<GHTimelineEvent[]>(
          qc,
          timelineKey,
          patchTimelineComment(event.id as number, c, 1),
          () => addIssueCommentReaction(owner, repo, event.id as number, c),
        ).catch((e) => {
          toast.error('Could not add reaction', {
            description: e instanceof Error ? e.message : String(e),
          });
        });
      }
    : undefined;
  const onRemoveReaction = owner && repo && number && event.id
    ? (key: keyof GHReactions, reactionId: number) => {
        const c = asReactionContent(key);
        if (!c) return;
        return withOptimisticReaction<GHTimelineEvent[]>(
          qc,
          timelineKey,
          patchTimelineComment(event.id as number, c, -1),
          () =>
            removeIssueCommentReaction(
              owner,
              repo,
              event.id as number,
              reactionId,
            ),
        ).catch((e) => {
          toast.error('Could not remove reaction', {
            description: e instanceof Error ? e.message : String(e),
          });
        });
      }
    : undefined;
  // Author-only delete for the viewer's own conversation comments —
  // optimistically drop the event from the timeline, then DELETE via the
  // issue-comments endpoint; roll back + toast on failure.
  const canDelete = isYou && !!owner && !!repo && !!event.id;
  const onDelete = canDelete
    ? async () => {
        const ok = await confirm({
          title: 'Delete comment?',
          description: "Delete this comment? This can't be undone.",
          confirmLabel: 'Delete',
          confirmIcon: Trash2Icon,
          tone: 'destructive',
        });
        if (!ok) return;
        const prev = qc.getQueryData<GHTimelineEvent[]>(timelineKey);
        qc.setQueryData<GHTimelineEvent[]>(timelineKey, (curr) =>
          curr?.filter((e) => e.id !== event.id),
        );
        try {
          await deleteIssueComment(owner!, repo!, event.id as number);
          toast.success('Comment deleted');
        } catch (e) {
          if (prev) qc.setQueryData(timelineKey, prev);
          toast.error('Could not delete comment', {
            description: e instanceof Error ? e.message : String(e),
          });
        }
      }
    : undefined;
  const commentKey = `comment:${event.id ?? `${who}-${event.created_at}`}`;
  // Under "New comments" focus, top-level PR comments (announcements, bot
  // summaries, deploy previews) aren't threads awaiting a reply, so they
  // default collapsed — the mode is for the unresolved threads that need
  // the viewer. The chevron override still wins, and the same default is
  // passed to toggle() so the first click expands.
  const autoCollapsed = onlyUnreplied;
  return (
    <div className="flex gap-3 py-2">
      <TimelineNode
        icon="comment"
        color="hsl(var(--muted-foreground))"
        big
      />
      <div className="min-w-0 flex-1">
        <GhComment
          author={who}
          authorAvatarUrl={avatarUrl}
          association={event.author_association}
          prRole={prRoleFor(who, authorLogin)}
          age={event.created_at ? `${humanAge(event.created_at)} ago` : undefined}
          ageTitle={fullDate(event.created_at)}
          edited={edited}
          editedTitle={fullDate(event.updated_at)}
          isYou={isYou}
          canEdit={canDelete}
          onDelete={onDelete}
          htmlUrl={event.html_url}
          reactions={event.reactions}
          onAddReaction={onAddReaction}
          onRemoveReaction={onRemoveReaction}
          listReactors={
            owner && repo && number && event.id
              ? () => listIssueCommentReactors(owner, repo, event.id as number)
              : undefined
          }
          viewerLogin={viewerLogin}
          preview={plainTextPreview(body)}
          previewSource={body}
          collapsed={collapse.isCollapsed(commentKey, autoCollapsed)}
          onCollapsedChange={() => collapse.toggle(commentKey, autoCollapsed)}
        >
          <Markdown source={body} size="sm" />
        </GhComment>
      </div>
    </div>
  );
}

function CommitItem({
  event,
  owner,
  repo,
  number,
  onScopeToCommit,
}: {
  event: GHTimelineEvent;
  owner?: string;
  repo?: string;
  number?: number;
  /** Click the row → open the Changes tab scoped to this one commit. */
  onScopeToCommit?: (sha: string) => void;
}) {
  // The `committed` timeline event carries only the git author (name /
  // email) — no GitHub identity, so no avatar. Resolve it by SHA from the
  // PR's REST commit list (shares the `commits` cache the fingerprint
  // refreshes on a new push), falling back to the git name when GitHub
  // can't match the commit to a user.
  const commitsQuery = useQuery({
    ...prCommitsOptions(owner!, repo!, number!),
    enabled: !!(owner && repo && number),
    staleTime: 30_000,
  });
  const ghAuthor = commitsQuery.data?.find((c) => c.sha === event.sha)?.author;
  const sha = event.sha ?? '';
  const subject = (event.message ?? '').split('\n')[0];
  const clickable = !!(onScopeToCommit && sha);
  return (
    <div className="flex gap-3 py-1">
      <TimelineNode icon="commit" color="hsl(var(--muted-foreground))" />
      <div
        className={
          'group flex min-w-0 flex-1 items-center gap-2 rounded text-[12.5px] text-muted-foreground' +
          (clickable
            ? ' -mx-1 cursor-pointer px-1 transition-colors hover:bg-muted/50'
            : '')
        }
        role={clickable ? 'button' : undefined}
        tabIndex={clickable ? 0 : undefined}
        title={clickable ? "View this commit's changes" : undefined}
        onClick={clickable ? () => onScopeToCommit?.(sha) : undefined}
        onKeyDown={
          clickable
            ? (e) => {
                if (e.key !== 'Enter' && e.key !== ' ') return;
                e.preventDefault();
                onScopeToCommit?.(sha);
              }
            : undefined
        }
      >
        <UserAvatar
          login={ghAuthor?.login ?? event.author?.name ?? 'unknown'}
          avatarUrl={ghAuthor?.avatar_url}
          size="xs"
        />
        <span className="shrink-0 font-mono text-[11px] text-muted-foreground/70">
          {sha.slice(0, 7)}
        </span>
        {/* Linkify GitHub refs (#123, @user, URLs) the way GitHub renders
            a commit subject — plain text, not markdown. */}
        <span className="min-w-0 flex-1 truncate text-foreground group-hover:text-foreground">
          {linkifyRefs(subject, { owner, repo })}
        </span>
        <span className="ml-auto text-[11.5px] text-muted-foreground/70" title={fullDate(event.author?.date)}>
          {event.author?.date ? humanAge(event.author.date) + ' ago' : ''}
        </span>
      </div>
    </div>
  );
}

function GenericRow({
  icon,
  color,
  actor,
  actorAvatarUrl,
  body,
  ts,
  tsOverride,
  tsTitle,
}: {
  icon: IconName;
  color: string;
  actor: string;
  actorAvatarUrl?: string;
  body: React.ReactNode;
  ts?: string | null;
  /** Pre-formatted timestamp string. Used by ForcePushRun to render
   * a "first → last ago" range that humanAge can't produce on its
   * own. When set, suppresses the ts-derived label. */
  tsOverride?: string;
  /** Literal date for the timestamp span's hover title. When omitted,
   * a `ts`-derived date is used. */
  tsTitle?: string;
}) {
  return (
    <div className="flex items-center gap-3 py-1">
      <TimelineNode icon={icon} color={color} />
      <div className="flex flex-1 items-center gap-2 text-[12.5px] text-muted-foreground">
        <UserAvatar login={actor} avatarUrl={actorAvatarUrl} size="xs" />
        <span>
          <b className="text-foreground">{actor}</b> {body}
        </span>
        {(tsOverride || ts) && (
          <span
            className="ml-auto text-[11.5px] text-muted-foreground/70"
            title={tsTitle ?? fullDate(ts)}
          >
            {tsOverride ?? `${humanAge(ts as string)} ago`}
          </span>
        )}
      </div>
    </div>
  );
}

// ── Right rail: metadata ────────────────────────────────────────

function ConversationRail({ pr }: { pr?: GHPullRequest }) {
  const labels = pr?.labels ?? [];
  // Parse owner/repo/number out of pr.html_url so we can key these
  // queries off the same `['pr', owner, repo, number, …]` shape that
  // PRHeader + the new timeline/reviews/review-comments fetches up-
  // top use. TanStack Query dedupes on key, so the rail's `useQuery`
  // shares one round trip with the rest of the surface.
  const prCoords = useMemo(() => {
    if (!pr?.html_url) return null;
    const m = pr.html_url.match(
      /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/,
    );
    return m ? { owner: m[1], repo: m[2], number: Number(m[3]) } : null;
  }, [pr?.html_url]);
  const reviewsQuery = useQuery({
    queryKey: prCoords
      ? ['pr', prCoords.owner, prCoords.repo, prCoords.number, 'reviews']
      : ['pr-rail-reviews-disabled'],
    queryFn: () => getReviews(prCoords!.owner, prCoords!.repo, prCoords!.number),
    enabled: !!prCoords,
    staleTime: 30_000,
  });
  const railReviewCommentsQuery = useQuery({
    queryKey: prCoords
      ? ['pr', prCoords.owner, prCoords.repo, prCoords.number, 'comments']
      : ['pr-rail-review-comments-disabled'],
    queryFn: () =>
      getReviewComments(prCoords!.owner, prCoords!.repo, prCoords!.number),
    enabled: !!prCoords,
    staleTime: 30_000,
  });
  const reviewerStates = useMemo(
    () =>
      collectReviewerStates(
        pr,
        reviewsQuery.data ?? [],
        railReviewCommentsQuery.data ?? [],
      ),
    [pr, reviewsQuery.data, railReviewCommentsQuery.data],
  );
  const assignees = pr?.assignees ?? [];
  const milestone = pr?.milestone ?? null;
  // GitHub milestone progress = closed / (closed + open). When both
  // counts are zero (newly-created milestone), default to 0% so we
  // don't divide-by-zero.
  const msTotal = (milestone?.closed_issues ?? 0) + (milestone?.open_issues ?? 0);
  const msPct = milestone && msTotal > 0
    ? Math.round((milestone.closed_issues / msTotal) * 100)
    : 0;
  return (
    <div className="w-[280px] shrink-0 overflow-auto border-l bg-card px-[18px] py-4">
      {assignees.length > 0 && (
        <RailSection title="Assignees">
          {assignees.map((a) => (
            <RailRow key={a.login}>
              <ReviewerChip
                name={a.login}
                state="pending"
                avatarUrl={a.avatar_url}
                size={5}
              />
              <RailName>{a.login}</RailName>
            </RailRow>
          ))}
        </RailSection>
      )}

      <RailSection title="Reviewers">
        {reviewerStates.length === 0 ? (
          <RailEmpty>None requested</RailEmpty>
        ) : (
          reviewerStates.map((r) => {
            const stateLabel =
              r.state === 'approved'
                ? 'Approved'
                : r.state === 'changes'
                  ? 'Changes'
                  : r.state === 'commented'
                    ? 'Commented'
                    : 'Pending';
            const stateClass =
              r.state === 'approved'
                ? 'text-pyor-pass'
                : r.state === 'changes'
                  ? 'text-pyor-fail'
                  : r.state === 'commented'
                    ? 'text-muted-foreground/70'
                    : 'text-pyor-warn';
            return (
              <RailRow key={r.login}>
                <ReviewerChip
                  name={r.login}
                  state={r.state}
                  avatarUrl={r.avatarUrl}
                  size={5}
                />
                <RailName>{r.login}</RailName>
                {r.commentCount === 0 ? (
                  <span className="text-[11px] tabular-nums text-muted-foreground/70">
                    —
                  </span>
                ) : (
                  <span
                    className="inline-flex items-center gap-1 text-[11px] text-muted-foreground/70"
                    aria-label={`${r.commentCount} comment${r.commentCount === 1 ? '' : 's'}`}
                    title={`${r.commentCount} comment${r.commentCount === 1 ? '' : 's'}`}
                  >
                    <MessageCircleIcon className="size-3" aria-hidden />
                    <span className="tabular-nums">{r.commentCount}</span>
                  </span>
                )}
                <RailState className={stateClass}>{stateLabel}</RailState>
              </RailRow>
            );
          })
        )}
      </RailSection>

      <RailSection title="Labels">
        {labels.length === 0 ? (
          <RailEmpty>None</RailEmpty>
        ) : (
          <div className="flex flex-wrap gap-1">
            {labels.map((l) => (
              <Label
                key={l.name}
                color={`#${l.color}`}
                text={l.name}
              />
            ))}
          </div>
        )}
      </RailSection>

      <RailSection title="Branches">
        <RailRow>
          <Icon name="branch" size={13} color="hsl(var(--muted-foreground))" />
          <span className="truncate font-mono text-[11.5px] text-foreground">
            {pr?.head.ref ?? '—'}
          </span>
        </RailRow>
        <RailRow>
          <Icon
            name="branch"
            size={13}
            color="hsl(var(--muted-foreground) / 0.7)"
          />
          <span className="truncate font-mono text-[11.5px] text-muted-foreground">
            {pr?.base.ref ?? '—'}
          </span>
        </RailRow>
      </RailSection>

      {milestone && (
        <RailSection title="Milestone">
          <a
            href={milestone.html_url}
            target="_blank"
            rel="noopener noreferrer"
            className="block truncate text-[12.5px] text-foreground hover:text-primary"
            title={milestone.title}
          >
            {milestone.title}
          </a>
          <div className="mt-1 h-1 overflow-hidden rounded-full bg-muted">
            <div
              className="h-full bg-foreground"
              style={{ width: `${msPct}%` }}
            />
          </div>
          <div className="mt-1 text-[11px] text-muted-foreground">
            {milestone.closed_issues} of {msTotal} done
            {milestone.due_on && (
              <span className="ml-1" title={fullDate(milestone.due_on)}>
                · due {humanAge(milestone.due_on)}
              </span>
            )}
          </div>
        </RailSection>
      )}

      <RailSection title="Status">
        <RailRow>
          <span className="text-[12.5px] text-muted-foreground">Mergeable</span>
          <span className="ml-auto text-xs text-foreground">
            {pr?.mergeable === null
              ? 'checking…'
              : pr?.mergeable
                ? 'yes'
                : 'no'}
          </span>
        </RailRow>
        <RailRow>
          <span className="text-[12.5px] text-muted-foreground">State</span>
          <span
            className={`ml-auto text-xs ${
              pr?.mergeable_state === 'clean'
                ? 'text-pyor-pass'
                : pr?.mergeable_state === 'blocked'
                  ? 'text-pyor-warn'
                  : pr?.mergeable_state === 'dirty'
                    ? 'text-pyor-fail'
                    : 'text-foreground'
            }`}
          >
            {pr?.mergeable_state ?? '—'}
          </span>
        </RailRow>
      </RailSection>
    </div>
  );
}

function RailSection({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}) {
  return (
    <div className="mb-[18px]">
      <div className="mb-2 flex items-center justify-between text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/70">
        <span>{title}</span>
      </div>
      <div className="flex flex-col gap-1.5">{children}</div>
    </div>
  );
}

function RailRow({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex items-center gap-2 text-[12.5px]">{children}</div>
  );
}

function RailEmpty({ children }: { children: React.ReactNode }) {
  return (
    <span className="text-xs italic text-muted-foreground/70">{children}</span>
  );
}

function RailName({ children }: { children: React.ReactNode }) {
  return (
    <span className="flex-1 truncate font-sans text-foreground">
      {children}
    </span>
  );
}

function RailState({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <span className={`text-[11.5px] font-medium ${className ?? ''}`}>
      {children}
    </span>
  );
}

// ── Helpers ─────────────────────────────────────────────────────

/** Wraps shadcn <Avatar> with the project's three timeline sizes
 * (xs/sm/md). Inline `style` for the pixel-exact size is unavoidable
 * — these sizes don't map to round Tailwind size utilities, and the
 * dimensions are stable per call site, but we keep the override
 * scoped here so the rest of the file stays utility-only. */
function UserAvatar({
  login,
  avatarUrl,
  size,
}: {
  login: string;
  avatarUrl?: string;
  size: 'xs' | 'sm' | 'md';
}) {
  const px = size === 'xs' ? 16 : size === 'sm' ? 18 : 20;
  const fontPx = Math.round(px * 0.42);
  const initials = login
    .split(/[\s-]+/)
    .map((s) => s[0] ?? '')
    .slice(0, 2)
    .join('')
    .toUpperCase();
  return (
    <Avatar
      className="shrink-0"
      style={{ width: px, height: px }}
    >
      {avatarUrl && <AvatarImage src={avatarUrl} alt={login} />}
      <AvatarFallback style={{ fontSize: fontPx }}>{initials}</AvatarFallback>
    </Avatar>
  );
}


function parseTs(iso?: string | null): number {
  if (!iso) return 0;
  const t = new Date(iso).getTime();
  return Number.isFinite(t) ? t : 0;
}

// ── Top-level conversation composer ─────────────────────────────
//
// The "Add a comment" affordance at the bottom of the timeline.
// Uses the shared GhComposer (Write/Preview tabs, RTE toolbar). The
// network round-trip + cache invalidation lives here so the composer
// stays presentational and reusable for replies / inline editors.
function TopLevelCommentComposer({
  owner,
  repo,
  number,
}: {
  owner: string;
  repo: string;
  number: number;
}) {
  const qc = useQueryClient();
  const uploadImage = useGithubAssetsUploader();
  const post = async (body: string) => {
    try {
      await createIssueComment(owner, repo, number, body);
      // New issue comment lands in the timeline query — invalidate
      // just that key so reviews / review-comments / files / contents
      // don't refetch needlessly.
      void qc.invalidateQueries({
        queryKey: ['pr', owner, repo, number, 'timeline'],
      });
      toast.success('Comment posted');
    } catch (e) {
      toast.error('Could not post comment', {
        description: e instanceof Error ? e.message : String(e),
      });
      throw e;
    }
  };
  return (
    <div className="mt-6">
      <GhComposer
        draftKey={`${owner}/${repo}/${number}:new-comment`}
        placeholder="Leave a comment. Markdown supported · ⌘⏎ to submit."
        submitLabel="Comment"
        onSubmit={post}
        onUploadImage={uploadImage}
        mentionContext={{ owner, repo, number }}
      />
    </div>
  );
}

