// Per-PR collapse state for every comment-like card in the
// Conversation tab — the PR description, top-level comments, review-
// summary cards, inline-thread head comments, and their replies.
//
// Each collapsible card folds from its own chevron; the state is
// persisted to localStorage so a reload restores exactly what the
// reviewer folded away. Purely UI state, never synced to GitHub.
//
// Tri-state, mirroring the Files-tab collapse store: a card has an
// effective collapsed state = explicit override ('open' | 'closed')
// OR, absent an override, an auto-derived default the caller passes
// in (e.g. resolved review threads default to collapsed). Storing the
// override direction explicitly is what lets "expand a resolved
// thread" survive a reload without also pinning every unresolved one.
//
// Storage shape (own `collapsed` namespace so it never tangles with
// the Files-tab file-collapse blob):
//   pyor:collapsed:pr:{owner}/{repo}/{number} → { [id]: 'open'|'closed' }
//
// Ids are type-prefixed by the caller (`comment:`, `review:`,
// `thread:`, `reply:`, `pr-description`) so the independent GitHub id
// sequences can't collide.
//
// One instance should be created per PR surface and shared by all the
// cards below it: each write rewrites the whole map, so two
// independent instances pointed at the same key would clobber each
// other.

import { useCallback, useEffect, useMemo, useState } from 'react';

type Override = 'open' | 'closed';

const PREFIX = 'pyor:collapsed:pr:';

function keyFor(
  owner?: string,
  repo?: string,
  number?: number,
): string | null {
  if (!owner || !repo || !number) return null;
  return `${PREFIX}${owner}/${repo}/${number}`;
}

function read(key: string | null): Record<string, Override> {
  if (!key) return {};
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as unknown;
    // Legacy migration: the first cut stored a flat array of collapsed
    // ids. Treat each as an explicit 'closed' override.
    if (Array.isArray(parsed)) {
      const out: Record<string, Override> = {};
      for (const id of parsed) out[String(id)] = 'closed';
      return out;
    }
    if (parsed && typeof parsed === 'object') {
      const out: Record<string, Override> = {};
      for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
        if (v === 'open' || v === 'closed') out[k] = v;
      }
      return out;
    }
    return {};
  } catch {
    return {};
  }
}

function write(key: string | null, map: Record<string, Override>): void {
  if (!key) return;
  try {
    localStorage.setItem(key, JSON.stringify(map));
  } catch {
    // ignore — same best-effort persistence as the sibling stores
  }
}

export interface CollapsedCommentsValue {
  /** Effective collapsed state for `id`. `autoCollapsed` is the
   * default used when the user hasn't explicitly toggled this card
   * (e.g. pass `true` for resolved threads). */
  isCollapsed(id: string, autoCollapsed?: boolean): boolean;
  /** Flip the effective state and persist. Clears the override when
   * the new state matches `autoCollapsed`, so a card that's back at
   * its default doesn't carry dead state. */
  toggle(id: string, autoCollapsed?: boolean): void;
  /** Force `id` open regardless of its auto-default — used when
   * expanding a settled card out of its compact band so the full card
   * shows its body even if it would otherwise auto-collapse (resolved). */
  expand(id: string): void;
}

export function useCollapsedComments(
  owner?: string,
  repo?: string,
  number?: number,
): CollapsedCommentsValue {
  const key = useMemo(() => keyFor(owner, repo, number), [owner, repo, number]);
  const [overrides, setOverrides] = useState<Record<string, Override>>(() =>
    read(key),
  );

  // Re-seed from storage when the PR coords (and thus the key) change.
  useEffect(() => {
    setOverrides(read(key));
  }, [key]);

  const isCollapsed = useCallback(
    (id: string, autoCollapsed = false) => {
      const o = overrides[id];
      if (o === 'closed') return true;
      if (o === 'open') return false;
      return autoCollapsed;
    },
    [overrides],
  );

  const toggle = useCallback(
    (id: string, autoCollapsed = false) => {
      setOverrides((prev) => {
        const cur = prev[id];
        const effective =
          cur === 'closed' ? true : cur === 'open' ? false : autoCollapsed;
        const nextCollapsed = !effective;
        const next = { ...prev };
        // If the flip lands back on the auto default, drop the override
        // so the card tracks its default again; otherwise pin it.
        if (nextCollapsed === autoCollapsed) {
          delete next[id];
        } else {
          next[id] = nextCollapsed ? 'closed' : 'open';
        }
        write(key, next);
        return next;
      });
    },
    [key],
  );

  const expand = useCallback(
    (id: string) => {
      setOverrides((prev) => {
        if (prev[id] === 'open') return prev;
        const next = { ...prev, [id]: 'open' as Override };
        write(key, next);
        return next;
      });
    },
    [key],
  );

  return useMemo(
    () => ({ isCollapsed, toggle, expand }),
    [isCollapsed, toggle, expand],
  );
}
