// localStorage primitives for the local pre-PR review's per-file
// viewed-state. Unlike the GitHub surface (where GitHub is the source of
// truth), the local surface has no server — viewed-state lives entirely
// in localStorage, keyed per **(commit, path)** so a file marked viewed
// while scoped to one commit stays independent of the same file under a
// different scope. The "all changes" scope rolls up under a stable
// `ALL` commit token; the uncommitted scope under `WORKING_TREE`.
//
// Storage shape: one key per review holding a flat string[] of
// `"<commit>�<path>"` entries (NUL separator — never appears in a
// SHA token or a repo path). Mirrors the localReviewComments store style.

const KEY = (reviewId: string) => `pyor:local-review-viewed:${reviewId}`;
const SEP = "�";

/** Synthetic commit token for the "all changes" (no scope) view. */
export const ALL_SCOPE_COMMIT = "ALL";
/** Synthetic commit token for the "uncommitted changes" scope. */
export const WORKING_TREE_COMMIT = "WORKING_TREE";

function viewedKey(commit: string, path: string): string {
  return `${commit}${SEP}${path}`;
}

function parseViewedKey(
  key: string,
): { commit: string; path: string } | null {
  const idx = key.indexOf(SEP);
  if (idx === -1) return null;
  return { commit: key.slice(0, idx), path: key.slice(idx + 1) };
}

/** All viewed (commit,path) keys for a review. */
function listViewedKeys(reviewId: string): Set<string> {
  try {
    const raw = localStorage.getItem(KEY(reviewId));
    if (!raw) return new Set();
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? new Set(arr.filter((x) => typeof x === "string")) : new Set();
  } catch {
    return new Set();
  }
}

function writeKeys(reviewId: string, keys: Set<string>): void {
  try {
    localStorage.setItem(KEY(reviewId), JSON.stringify([...keys]));
  } catch {
    // quota / private mode — best-effort.
  }
}

export function setViewedKey(
  reviewId: string,
  commit: string,
  path: string,
  viewed: boolean,
): void {
  const keys = listViewedKeys(reviewId);
  const k = viewedKey(commit, path);
  if (viewed) keys.add(k);
  else keys.delete(k);
  writeKeys(reviewId, keys);
}

export function setManyViewedKeys(
  reviewId: string,
  commit: string,
  paths: string[],
  viewed: boolean,
): void {
  const keys = listViewedKeys(reviewId);
  paths.forEach((p) => {
    const k = viewedKey(commit, p);
    if (viewed) keys.add(k);
    else keys.delete(k);
  });
  writeKeys(reviewId, keys);
}

/** Paths viewed under a given commit scope. */
export function viewedPathsForCommit(
  reviewId: string,
  commit: string,
): Set<string> {
  const out = new Set<string>();
  listViewedKeys(reviewId).forEach((k) => {
    const parsed = parseViewedKey(k);
    if (parsed && parsed.commit === commit) out.add(parsed.path);
  });
  return out;
}

/**
 * @expected-unused — clears a local review's viewed-state, intended for the
 * review-delete path of the in-flight local-review feature. No caller yet;
 * fallow will flag this tag as stale once one wires it up.
 */
export function clearViewedForReview(reviewId: string): void {
  try {
    localStorage.removeItem(KEY(reviewId));
  } catch {
    // ignore
  }
}
