// Changes-tab reaction adapter for ReviewThread. Patches the diff pane's
// review-comment cache (['pr',o,r,n,'comments']) optimistically, then fires
// the mutation; PRDetailScreen rebuilds the thread index from that cache so
// the strip updates without a refetch. Extracted from the former
// InlineCommentThread so the merged ReviewThread can stay surface-agnostic
// (the Conversation tab injects its own adapter against a different cache).

import { useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  addReviewCommentReaction,
  listReviewCommentReactors,
  removeReviewCommentReaction,
  type ReactionContent,
} from '../../github/client';
import type { GHReactions, GHReviewComment } from '../../github/types';
import {
  asReactionContent,
  bumpReactionCount,
  withOptimisticReaction,
} from '../../github/reactionHelpers';
import type { ReviewThreadReactions } from '../conversation/ReviewThread';

export function useReviewCommentReactions(
  owner: string | undefined,
  repo: string | undefined,
  number: number | undefined,
): ReviewThreadReactions {
  const qc = useQueryClient();
  const commentsKey = ['pr', owner, repo, number, 'comments'] as const;
  const patch =
    (commentId: number, content: ReactionContent, delta: 1 | -1) =>
    (curr: GHReviewComment[] | undefined) =>
      curr?.map((c) =>
        c.id === commentId
          ? { ...c, reactions: bumpReactionCount(c.reactions, content, delta) }
          : c,
      );

  return {
    onAdd: async (commentId, key: keyof GHReactions) => {
      if (!owner || !repo) return;
      const c = asReactionContent(key);
      if (!c) return;
      try {
        await withOptimisticReaction<GHReviewComment[]>(
          qc,
          commentsKey,
          patch(commentId, c, 1),
          () => addReviewCommentReaction(owner, repo, commentId, c),
        );
      } catch (e) {
        toast.error('Could not add reaction', {
          description: e instanceof Error ? e.message : String(e),
        });
      }
    },
    onRemove: async (commentId, key: keyof GHReactions, reactionId) => {
      if (!owner || !repo) return;
      const c = asReactionContent(key);
      if (!c) return;
      try {
        await withOptimisticReaction<GHReviewComment[]>(
          qc,
          commentsKey,
          patch(commentId, c, -1),
          () => removeReviewCommentReaction(owner, repo, commentId, reactionId),
        );
      } catch (e) {
        toast.error('Could not remove reaction', {
          description: e instanceof Error ? e.message : String(e),
        });
      }
    },
    listReactors: (commentId) =>
      owner && repo
        ? listReviewCommentReactors(owner, repo, commentId)
        : Promise.resolve([]),
  };
}
