// Per-(commit, path) viewed-state provider for the local pre-PR review.
//
// Returns a `ViewedHookValue` shaped exactly like the GitHub
// `useViewedState`, so the shared FileRail viewed-toggle + the diff
// header checkmark + the `v` keyboard shortcut all work unchanged. Unlike
// GitHub (server-backed), this is localStorage-only, keyed by the active
// scope's `commitKey` so each scope (a commit/range, uncommitted, or the
// "all" rollup) keeps its own viewed set.
//
// React Query is the source of truth (per the repo convention): a query
// holds the Set, toggles write localStorage AND `setQueryData`
// optimistically, and a cross-window `storage` listener invalidates.

import { useEffect, useMemo } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import type { ViewedHookValue } from "./viewedHooks";
import {
  setManyViewedKeys,
  setViewedKey,
  viewedPathsForCommit,
} from "./localReviewViewed";

const EMPTY: ReadonlySet<string> = new Set();

const queryKey = (reviewId: string, commitKey: string) =>
  ["local-review-viewed", reviewId, commitKey] as const;

/**
 * @param reviewId  the local review id
 * @param commitKey the active scope's commit identity — a resolved head
 *   SHA for a commit/range scope, `WORKING_TREE_COMMIT` for uncommitted,
 *   or `ALL_SCOPE_COMMIT` for the no-scope rollup.
 */
export function useLocalReviewViewed(
  reviewId: string,
  commitKey: string,
): ViewedHookValue {
  const qc = useQueryClient();
  const key = useMemo(
    () => queryKey(reviewId, commitKey),
    [reviewId, commitKey],
  );

  // Cross-window sync: another window toggling viewed writes the per-review
  // localStorage key; invalidate so this query re-reads.
  useEffect(() => {
    if (!reviewId) return;
    const expected = `pyor:local-review-viewed:${reviewId}`;
    const onStorage = (e: StorageEvent) => {
      if (e.key === expected || e.key === null) {
        void qc.invalidateQueries({
          queryKey: ["local-review-viewed", reviewId],
        });
      }
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [qc, reviewId]);

  const query = useQuery({
    queryKey: key,
    queryFn: () => viewedPathsForCommit(reviewId, commitKey),
    enabled: !!reviewId && !!commitKey,
    staleTime: Infinity,
  });

  const viewed = (query.data ?? EMPTY) as Set<string>;

  return useMemo<ViewedHookValue>(() => {
    const setViewed = (path: string, isViewed: boolean) => {
      setViewedKey(reviewId, commitKey, path, isViewed);
      qc.setQueryData<Set<string>>(key, (prev) => {
        const next = new Set(prev ?? []);
        if (isViewed) next.add(path);
        else next.delete(path);
        return next;
      });
    };
    const setMany = (paths: string[], isViewed: boolean) => {
      setManyViewedKeys(reviewId, commitKey, paths, isViewed);
      qc.setQueryData<Set<string>>(key, (prev) => {
        const next = new Set(prev ?? []);
        paths.forEach((p) => (isViewed ? next.add(p) : next.delete(p)));
        return next;
      });
    };
    return {
      viewed,
      isViewed: (path: string) => viewed.has(path),
      toggle: (path: string) => setViewed(path, !viewed.has(path)),
      setViewed,
      setMany,
    };
  }, [viewed, reviewId, commitKey, qc, key]);
}
