// ThreadResolveFooter — the conversation-level resolve / unresolve
// footer that sits at the foot of a review thread. Rendered by the
// shared ReviewThread component on both the Changes + Conversation tabs.
//
// Design parity: gh-comments.jsx · GhInlineThread footer and
// shadcn-app.jsx · GhConvInlineRef footer.
//   • Open thread:     hint on the left, primary "Resolve conversation"
//                      button (check icon) on the right.
//   • Resolved thread: green strip, check badge + "{resolvedBy} marked
//                      this conversation as resolved." on the left, an
//                      outline "Unresolve conversation" button (reply
//                      icon) on the right.
//
// Only review threads get this — top-level conversation/issue comments
// don't (the caller decides whether to render it). The buttons are
// gated on the viewer's GitHub permissions (viewerCanResolve /
// viewerCanUnresolve) and on the GraphQL node id having loaded; until
// then the relevant button is disabled with an explanatory tooltip.

import { useState } from 'react';
import { AlertTriangleIcon, CheckIcon, Loader2, ReplyIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

interface ThreadResolveFooterProps {
  resolved: boolean;
  /** The thread's anchored line has drifted off the latest diff. When
   * true (and the thread isn't already resolved) the footer renders an
   * amber-tinted band explaining the staleness — part of the outdated
   * "treatment B" de-emphasis. `resolved` still wins if both hold. */
  outdated?: boolean;
  /** Login of whoever resolved it — shown in the resolved strip. */
  resolvedBy?: string | null;
  /** GitHub permission flags. When the matching button's flag is
   * false, it's disabled (the viewer can't perform that action). */
  canResolve?: boolean;
  canUnresolve?: boolean;
  /** False while the thread's GraphQL node id is still loading — both
   * buttons disable with a "still loading" tooltip since the mutation
   * has nothing to target yet. */
  ready?: boolean;
  /** Fires the resolve (when open) or unresolve (when resolved)
   * mutation. May be async; the footer shows a spinner while it runs.
   * Errors are surfaced by the caller's mutation (toast) — the footer
   * just stops spinning. */
  onToggle: () => void | Promise<void>;
}

export function ThreadResolveFooter({
  resolved,
  outdated = false,
  resolvedBy,
  canResolve = true,
  canUnresolve = true,
  ready = true,
  onToggle,
}: ThreadResolveFooterProps) {
  const [busy, setBusy] = useState(false);
  const run = async () => {
    if (busy) return;
    setBusy(true);
    try {
      await onToggle();
    } finally {
      setBusy(false);
    }
  };

  const allowed = resolved ? canUnresolve : canResolve;
  const disabled = busy || !ready || !allowed;
  const disabledReason = !ready
    ? 'Thread is still loading…'
    : !allowed
      ? resolved
        ? "You don't have permission to unresolve this thread"
        : "You don't have permission to resolve this thread"
      : undefined;

  return (
    <div
      className={cn(
        'flex items-center gap-2 border-t px-3 py-1',
        resolved
          ? 'border-pyor-pass/30 bg-pyor-pass/10'
          : outdated
            ? 'border-pyor-warn/30 bg-pyor-warn/10'
            : 'bg-muted/40',
      )}
    >
      {resolved ? (
        <>
          <span className="inline-flex size-4 shrink-0 items-center justify-center rounded-full bg-pyor-pass/20 text-pyor-pass">
            <CheckIcon className="size-2.5" />
          </span>
          <span className="min-w-0 text-[11.5px] text-muted-foreground">
            {resolvedBy ? (
              <>
                <b className="font-semibold text-foreground">{resolvedBy}</b>{' '}
                marked this conversation as resolved.
              </>
            ) : (
              'This conversation is resolved.'
            )}
          </span>
          <ResolveButton
            label="Unresolve"
            icon="reply"
            variant="outline"
            busy={busy}
            disabled={disabled}
            disabledReason={disabledReason}
            onClick={run}
          />
        </>
      ) : outdated ? (
        <>
          <AlertTriangleIcon className="size-3.5 shrink-0 text-pyor-warn" />
          <span className="min-w-0 text-[11.5px] text-muted-foreground">
            This thread is outdated — the code it points to has changed since.
          </span>
          <ResolveButton
            label="Resolve"
            icon="check"
            variant="outline"
            busy={busy}
            disabled={disabled}
            disabledReason={disabledReason}
            onClick={run}
          />
        </>
      ) : (
        <>
          <CheckIcon className="size-3 shrink-0 text-muted-foreground/60" />
          <span className="min-w-0 text-[11.5px] text-muted-foreground">
            Mark the thread resolved to collapse it.
          </span>
          <ResolveButton
            label="Resolve"
            icon="check"
            variant="default"
            busy={busy}
            disabled={disabled}
            disabledReason={disabledReason}
            onClick={run}
          />
        </>
      )}
    </div>
  );
}

function ResolveButton({
  label,
  icon,
  variant,
  busy,
  disabled,
  disabledReason,
  onClick,
}: {
  label: string;
  icon: 'check' | 'reply';
  variant: 'default' | 'outline';
  busy: boolean;
  disabled: boolean;
  disabledReason?: string;
  onClick: () => void;
}) {
  const btn = (
    <Button
      variant={variant}
      size="sm"
      onClick={onClick}
      disabled={disabled}
      className="ml-auto h-6 gap-1 px-2.5 text-[11.5px]"
    >
      {busy ? (
        <Loader2 className="size-3.5 animate-spin" />
      ) : icon === 'check' ? (
        <CheckIcon className="size-3.5" />
      ) : (
        <ReplyIcon className="size-3.5" />
      )}
      {label}
    </Button>
  );
  // Wrap a disabled button so the tooltip still fires (disabled
  // buttons swallow pointer events). Only bother when there's a reason.
  if (disabled && disabledReason) {
    return (
      <TooltipProvider delayDuration={300}>
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="ml-auto inline-flex cursor-not-allowed">{btn}</span>
          </TooltipTrigger>
          <TooltipContent side="top" className="text-[11px]">
            {disabledReason}
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }
  return btn;
}
