// Reusable confirm modal for lifecycle state changes — the spine's
// "every state change is confirmed" requirement (ADR 0016). Close /
// reopen / draft-toggle / update-branch confirm through here; dismiss-
// review reuses it with `reasonRequired` for the GitHub-mandated
// message (#19). Built on the animated AlertDialog (role="alertdialog")
// — confirm/cancel is exactly what an alert dialog is for.

import { useEffect, useState, type ComponentType } from 'react';
import { AlertTriangleIcon, type LucideProps } from 'lucide-react';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';

export interface ConfirmModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description: string;
  /** 'destructive' tints the icon + confirm button red; 'neutral' uses
   * the default primary. */
  tone?: 'destructive' | 'neutral';
  icon?: ComponentType<LucideProps>;
  confirmLabel: string;
  confirmIcon?: ComponentType<LucideProps>;
  cancelLabel?: string;
  /** When true, a non-empty reason is required before confirm enables.
   * The reason is passed to onConfirm. */
  reasonRequired?: boolean;
  reasonLabel?: string;
  reasonHint?: string;
  reasonPlaceholder?: string;
  /** Disables the confirm button + shows a busy label while the
   * mutation runs. The modal stays open until the caller closes it. */
  pending?: boolean;
  onConfirm: (reason?: string) => void;
}

export function ConfirmModal({
  open,
  onOpenChange,
  title,
  description,
  tone = 'destructive',
  icon: Icon = AlertTriangleIcon,
  confirmLabel,
  confirmIcon: ConfirmIcon,
  cancelLabel = 'Cancel',
  reasonRequired = false,
  reasonLabel = 'Reason',
  reasonHint = 'Required · shared with the reviewer.',
  reasonPlaceholder = 'Why are you dismissing this review?',
  pending = false,
  onConfirm,
}: ConfirmModalProps) {
  const [reason, setReason] = useState('');
  // Clear the reason whenever the modal reopens so a previous attempt's
  // text doesn't leak into the next confirmation.
  useEffect(() => {
    if (open) setReason('');
  }, [open]);

  const reasonOk = !reasonRequired || reason.trim().length > 0;
  // --destructive is a dark/muddy red in this project's dark theme
  // (it's a fill token, not a text token), so the icon wraps use the
  // explicit red/amber palette with dark: variants — matching the
  // reviewer tone-boxes — instead of the semantic token.
  const iconWrap =
    tone === 'destructive'
      ? 'bg-red-100 text-red-600 ring-red-50 dark:bg-red-900/40 dark:text-red-300 dark:ring-red-900/20'
      : 'bg-amber-100 text-amber-600 ring-amber-50 dark:bg-amber-900/40 dark:text-amber-300 dark:ring-amber-900/20';

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      {/* text-foreground is required: AlertDialogContent sets
          bg-background but not a text color, and Radix portals the
          dialog to <body> (outside the app-root that sets foreground),
          so inherited text would be body's black — invisible on the
          dark surface. */}
      <AlertDialogContent className="max-w-[460px] gap-0 p-0 text-foreground">
        <div className="flex items-start gap-3 px-4 py-4">
          <span
            className={`inline-flex size-9 shrink-0 items-center justify-center rounded-full ring-4 ${iconWrap}`}
          >
            <Icon className="size-4" />
          </span>
          <div className="min-w-0 flex-1">
            <AlertDialogTitle className="text-[14.5px] font-semibold tracking-tight">
              {title}
            </AlertDialogTitle>
            <AlertDialogDescription className="mt-1 text-[12.5px] leading-relaxed">
              {description}
            </AlertDialogDescription>
            {reasonRequired && (
              <div className="mt-3">
                <div className="mb-1.5 flex items-baseline justify-between">
                  <Label className="text-[12px]">{reasonLabel}</Label>
                  <span className="text-[10.5px] text-muted-foreground">
                    {reasonHint}
                  </span>
                </div>
                <Textarea
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder={reasonPlaceholder}
                  className="min-h-16 text-[12.5px]"
                  autoFocus
                />
              </div>
            )}
          </div>
        </div>
        <AlertDialogFooter className="border-t px-4 py-3">
          {/* asChild so the confirm reuses our Button tones; preventDefault
              keeps the dialog open while the mutation runs — the caller
              closes it on success (pending/!reasonOk also gate it). */}
          <AlertDialogCancel asChild>
            <Button variant="ghost" size="sm" disabled={pending}>
              {cancelLabel}
            </Button>
          </AlertDialogCancel>
          <AlertDialogAction asChild className="ml-auto">
            <Button
              size="sm"
              variant={tone === 'destructive' ? 'destructive' : 'default'}
              disabled={pending || !reasonOk}
              onClick={(e) => {
                e.preventDefault();
                onConfirm(reasonRequired ? reason.trim() : undefined);
              }}
            >
              {ConfirmIcon && <ConfirmIcon className="size-3.5" />}
              {pending ? 'Working…' : confirmLabel}
            </Button>
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
