// The inline AI hint card (ADR 0026 / design hint-card ★). Anchored exactly
// like a human comment bubble, but unmistakably AI and private: violet
// left-accent, marked head (no avatar slot), no reply composer, one action
// ("Draft a comment"), an always-present disclaimer + "private · not posted"
// note. Quiet collapsed resting state keeps a multi-hint file calm.

import { useState } from 'react';
import { ChevronDown, ChevronUp, Lock, X } from 'lucide-react';
import {
  AiButton,
  AiDisclaimer,
  AiMark,
  AiMarkTile,
  AiSeverityBar,
  AiTypeIcon,
  AiTypePill,
  AI_HINT_TYPES,
} from '../aikit';
import type { AnchoredHint } from './useAiHints';

/** The text pre-filled into the composer for "Draft a comment from this". */
export function formatHintDraft(hint: AnchoredHint): string {
  return `${hint.title}\n\n${hint.body}`;
}

export function AiHintCard({
  hint,
  drafting = false,
  onDraft,
  onDismiss,
}: {
  hint: AnchoredHint;
  /** True once a draft has been pushed to the composer for this hint. */
  drafting?: boolean;
  onDraft: () => void;
  onDismiss: () => void;
}) {
  const [collapsed, setCollapsed] = useState(false);
  const t = AI_HINT_TYPES[hint.type];

  if (collapsed) {
    return (
      <button
        type="button"
        onClick={() => setCollapsed(false)}
        className="mx-3 my-1 flex w-[calc(100%-1.5rem)] items-center gap-2 rounded-md border border-violet-200/70 bg-violet-50/50 px-2.5 py-1 text-left hover:bg-violet-50"
      >
        <AiMark className="size-3.5 shrink-0 text-violet-500" />
        <AiTypeIcon type={hint.type} className="size-3.5 shrink-0 text-violet-600" />
        <span className="text-[11.5px] font-medium text-violet-700">{t.short}</span>
        <span className="truncate text-[11.5px] text-muted-foreground">{hint.title}</span>
        <AiSeverityBar severity={hint.severity} className="ml-auto shrink-0" />
        <ChevronDown className="size-3.5 shrink-0 text-muted-foreground" />
      </button>
    );
  }

  return (
    <div
      className="mx-3 my-1.5 overflow-hidden rounded-lg border border-violet-200 bg-violet-50/60 shadow-sm"
      style={{ borderLeftWidth: 2, borderLeftColor: '#8b5cf6' }}
    >
      <div className="flex items-start gap-2.5 p-2.5">
        <AiMarkTile size="size-6" />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <AiTypePill type={hint.type} severity={hint.severity} />
            <span className="truncate text-[12px] font-semibold text-foreground">{t.label}</span>
            <span className="ml-auto flex shrink-0 items-center gap-0.5">
              <button
                type="button"
                title="Collapse"
                onClick={() => setCollapsed(true)}
                className="inline-flex size-5 items-center justify-center rounded text-muted-foreground hover:bg-violet-100 hover:text-violet-700"
              >
                <ChevronUp className="size-3.5" />
              </button>
              <button
                type="button"
                title="Dismiss hint"
                onClick={onDismiss}
                className="inline-flex size-5 items-center justify-center rounded text-muted-foreground hover:bg-violet-100 hover:text-violet-700"
              >
                <X className="size-3.5" />
              </button>
            </span>
          </div>
          <div className="mt-1 text-[12.5px] font-medium text-foreground">{hint.title}</div>
          <div className="mt-0.5 whitespace-pre-wrap text-[12.5px] leading-relaxed text-muted-foreground">
            {hint.body}
          </div>
          {hint.guideline && (
            <div className="mt-1.5 inline-flex items-center gap-1 text-[10.5px] text-violet-600">
              <AiMark className="size-3" />
              <span>from your guideline · “{hint.guideline}”</span>
            </div>
          )}
        </div>
      </div>
      <div className="flex items-center gap-2 border-t border-violet-200/70 bg-violet-50/80 px-2.5 py-1.5">
        <AiDisclaimer size="sm" />
        <span className="inline-flex items-center gap-1 text-[10.5px] text-muted-foreground">
          <Lock className="size-3" />
          private · not posted
        </span>
        <div className="ml-auto flex items-center gap-2">
          {drafting ? (
            <span className="inline-flex items-center gap-1 text-[11px] font-medium text-violet-700">
              Drafted below
            </span>
          ) : (
            <AiButton variant="outline" size="xs" icon="draft" onClick={onDraft}>
              Draft a comment
            </AiButton>
          )}
        </div>
      </div>
    </div>
  );
}
