/** GitHub GraphQL ReactionContent enum (distinct from the REST inline
 * summary keys). */
export type GqlReactionContent =
  | 'THUMBS_UP'
  | 'THUMBS_DOWN'
  | 'LAUGH'
  | 'HOORAY'
  | 'CONFUSED'
  | 'HEART'
  | 'ROCKET'
  | 'EYES';

/**
 * Add / remove the viewer's reaction by GraphQL node id. Unlike the REST
 * helpers above (which need the numeric id + a different endpoint per
 * comment kind), `addReaction`/`removeReaction` work on ANY Reactable by
 * its `subjectId` — so the Inbox can react to every comment surface with
 * the node id it already has, and `removeReaction` keys off the content
 * (no reaction-id round trip needed). */
export async function setReactionByNodeId(
  subjectId: string,
  content: GqlReactionContent,
  add: boolean,
): Promise<void> {
  const mutation = add
    ? /* GraphQL */ `mutation($s: ID!, $c: ReactionContent!) {
        addReaction(input: { subjectId: $s, content: $c }) { clientMutationId }
      }`
    : /* GraphQL */ `mutation($s: ID!, $c: ReactionContent!) {
        removeReaction(input: { subjectId: $s, content: $c }) { clientMutationId }
      }`;
  await graphql(mutation, { s: subjectId, c: content });
}

