// ── Pending review (in-progress review — ADR 0019) ─────────────
//
// GitHub holds the viewer's in-progress review as a server-side
// *pending review* (one per viewer per PR). Its comments are NOT
// returned by GET /pulls/{n}/comments — they come back only via this
// review-scoped read, and we merge them into the unified comment list
// tagged `pending` so they render inline through the same GhComment.
//
// Why GraphQL and not the REST review-scoped endpoint: REST returns
// pending comments in the legacy `position`-only shape (line/side are
// null), so we can't anchor them. GraphQL exposes real `line`,
// `startLine`, `subjectType`, `state` and `replyTo` at the comment
// level — and `diffSide` at the thread level (the one field comments
// lack). So a cheap reviews(states:[PENDING]) read gives everything but
// side; a second reviewThreads read maps databaseId → side, paid ONLY
// when a pending review actually exists (the rare case). The common "no
// pending review" path costs ~1 GraphQL point.

export interface PendingReview {
  /** REST numeric id — used for submit (events) and discard (DELETE). */
  id: number;
  /** GraphQL node id (`PRR_…`) — used to append comments via
   * addPullRequestReviewThread / addPullRequestReviewComment. */
  nodeId: string;
  /** The pending comments, synthesised into GHReviewComment shape and
   * tagged `status:'pending'`, ready to fold into buildThreadIndex. */
  comments: GHReviewComment[];
}

interface PendingReviewGqlComment {
  databaseId: number;
  node_id?: string;
  body: string;
  path: string;
  line: number | null;
  startLine: number | null;
  subjectType: 'LINE' | 'FILE' | null;
  outdated: boolean;
  diffHunk: string | null;
  createdAt: string;
  lastEditedAt: string | null;
  author: { login: string; avatarUrl: string } | null;
  replyTo: { databaseId: number } | null;
}

/**
 * The viewer's in-progress (PENDING) review for a PR, or null when none
 * exists. The returned comments are tagged `pending` and carry real
 * line/side so they anchor on the diff exactly like published threads.
 */
export async function getPendingReview(
  owner: string,
  repo: string,
  number: number,
): Promise<PendingReview | null> {
  const data: {
    repository?: {
      pullRequest?: {
        reviews: {
          nodes: {
            id: string;
            databaseId: number;
            comments: { nodes: PendingReviewGqlComment[] };
          }[];
        };
      };
    };
  } = await graphql(
    `
      query PendingReview($owner: String!, $repo: String!, $number: Int!) {
        rateLimit { cost remaining limit }
        repository(owner: $owner, name: $repo) {
          pullRequest(number: $number) {
            reviews(first: 1, states: [PENDING]) {
              nodes {
                id
                databaseId
                comments(first: 100) {
                  nodes {
                    databaseId
                    node_id: id
                    body
                    path
                    line
                    startLine
                    subjectType
                    outdated
                    diffHunk
                    createdAt
                    lastEditedAt
                    author { login avatarUrl }
                    replyTo { databaseId }
                  }
                }
              }
            }
          }
        }
      }
    `,
    { owner, repo, number },
  );
  const review = data.repository?.pullRequest?.reviews.nodes[0];
  if (!review) return null;

  // Side lives only on the thread. Build databaseId → side for the
  // head comments (new pending threads contain exactly their own head,
  // so the first-comment id maps a pending head comment to its side).
  // Pending replies inherit their published head's anchor in
  // buildThreadIndex, so their own side is irrelevant.
  const sideByCommentId = await pendingThreadSideMap(owner, repo, number);

  const comments = review.comments.nodes.map((c): GHReviewComment =>
    pendingGqlToReviewComment(c, review.databaseId, sideByCommentId),
  );
  return { id: review.databaseId, nodeId: review.id, comments };
}

/** Map a pending GraphQL review comment into the REST-shaped
 * GHReviewComment the thread/diff pipeline consumes, tagged `pending`. */
function pendingGqlToReviewComment(
  c: PendingReviewGqlComment,
  reviewId: number,
  sideByCommentId: Map<number, 'LEFT' | 'RIGHT'>,
): GHReviewComment {
  const line = c.line ?? null;
  const startLine = c.startLine ?? line;
  return {
    id: c.databaseId,
    node_id: c.node_id,
    pull_request_review_id: reviewId,
    user: {
      login: c.author?.login ?? '',
      avatar_url: c.author?.avatarUrl ?? '',
    },
    body: c.body,
    path: c.path,
    line,
    original_line: line,
    start_line: startLine,
    original_start_line: startLine,
    side: sideByCommentId.get(c.databaseId) ?? 'RIGHT',
    in_reply_to_id: c.replyTo?.databaseId,
    position: null,
    original_position: null,
    created_at: c.createdAt,
    updated_at: c.lastEditedAt ?? c.createdAt,
    html_url: '',
    commit_id: '',
    original_commit_id: '',
    diff_hunk: c.diffHunk ?? undefined,
    subject_type: c.subjectType === 'FILE' ? 'file' : 'line',
    status: 'pending',
  };
}

/** databaseId → diffSide for every review thread's head comment. Paid
 * only when a pending review exists. Paginates like getReviewThreadIds. */
async function pendingThreadSideMap(
  owner: string,
  repo: string,
  number: number,
): Promise<Map<number, 'LEFT' | 'RIGHT'>> {
  const map = new Map<number, 'LEFT' | 'RIGHT'>();
  let cursor: string | null = null;
  for (let page = 0; page < 6; page++) {
    const data: {
      repository?: {
        pullRequest?: {
          reviewThreads: {
            pageInfo: { hasNextPage: boolean; endCursor: string | null };
            nodes: {
              diffSide: 'LEFT' | 'RIGHT';
              comments: { nodes: { databaseId: number }[] };
            }[];
          };
        };
      };
    } = await graphql(
      `
        query PendingThreadSides(
          $owner: String!
          $repo: String!
          $number: Int!
          $cursor: String
        ) {
          rateLimit { cost remaining limit }
          repository(owner: $owner, name: $repo) {
            pullRequest(number: $number) {
              reviewThreads(first: 100, after: $cursor) {
                pageInfo { hasNextPage endCursor }
                nodes {
                  diffSide
                  comments(first: 1) { nodes { databaseId } }
                }
              }
            }
          }
        }
      `,
      { owner, repo, number, cursor },
    );
    const conn = data.repository?.pullRequest?.reviewThreads;
    if (!conn) break;
    for (const t of conn.nodes) {
      const head = t.comments.nodes[0];
      if (head) map.set(head.databaseId, t.diffSide);
    }
    if (!conn.pageInfo.hasNextPage) break;
    cursor = conn.pageInfo.endCursor;
    if (!cursor) break;
  }
  return map;
}

// ── Pending review mutations (ADR 0019) ────────────────────────
//
// The split that causes GitHub's "well-known 422s" (verified live):
//   - CREATE the pending review (first comment): REST POST /reviews
//     with NO event → PENDING. A second create 422s, so callers must
//     create-once then append.
//   - APPEND to an existing pending review: GraphQL ONLY. REST
//     POST /pulls/{n}/comments 422s ("one pending review per PR").
//       · line comment → addPullRequestReviewThread(line, side)
//       · file comment → addPullRequestReviewThread(subjectType: FILE)
//       · reply        → addPullRequestReviewComment(inReplyTo)
//   - EDIT / DELETE a pending comment: GraphQL (REST PATCH/DELETE 404
//     on pending). Published comments still use the REST helpers above.
//   - SUBMIT: REST POST /reviews/{id}/events with the verdict.
//   - DISCARD / empty-review cleanup: REST DELETE /reviews/{id}.

/** id pair returned by every pending-comment create — the numeric
 * databaseId (used as GHReviewComment.id + REST fallbacks) and the
 * GraphQL node id (used for subsequent update/delete mutations). */
export interface PendingCommentIds {
  id: number;
  nodeId: string;
}

/** Create an empty pending review (REST, no `event`, no comments) ⇒
 * PENDING. Used only when the first pending action is a reply, which
 * can't seed createPendingReviewWithComment. */
export async function createPendingReview(
  owner: string,
  repo: string,
  number: number,
  commitId: string | undefined,
): Promise<{ id: number; nodeId: string }> {
  const { data } = await request<{ id: number; node_id: string }>(
    `/repos/${owner}/${repo}/pulls/${number}/reviews`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(commitId ? { commit_id: commitId } : {}),
    },
  );
  return { id: data.id, nodeId: data.node_id };
}

/** Create the viewer's pending review with its first line comment (REST,
 * no `event` ⇒ PENDING). Returns the review's id + node id so the next
 * comment appends via GraphQL. */
export async function createPendingReviewWithComment(
  owner: string,
  repo: string,
  number: number,
  commitId: string,
  comment: SubmitReviewComment,
): Promise<{ id: number; nodeId: string }> {
  const { data } = await request<{ id: number; node_id: string }>(
    `/repos/${owner}/${repo}/pulls/${number}/reviews`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ commit_id: commitId, comments: [comment] }),
    },
  );
  return { id: data.id, nodeId: data.node_id };
}

/** Append a line comment to an existing pending review (GraphQL — REST
 * 422s while a pending review exists). */
export async function addPendingLineComment(
  reviewNodeId: string,
  input: {
    path: string;
    body: string;
    line: number;
    side: 'LEFT' | 'RIGHT';
    startLine?: number;
    startSide?: 'LEFT' | 'RIGHT';
  },
): Promise<PendingCommentIds> {
  const data: {
    addPullRequestReviewThread: {
      thread: { comments: { nodes: { databaseId: number; id: string }[] } };
    };
  } = await graphql(
    `
      mutation AddPendingLine(
        $reviewId: ID!
        $path: String!
        $body: String!
        $line: Int!
        $side: DiffSide!
        $startLine: Int
        $startSide: DiffSide
      ) {
        addPullRequestReviewThread(
          input: {
            pullRequestReviewId: $reviewId
            path: $path
            body: $body
            line: $line
            side: $side
            startLine: $startLine
            startSide: $startSide
          }
        ) {
          thread { comments(first: 1) { nodes { databaseId id } } }
        }
      }
    `,
    {
      reviewId: reviewNodeId,
      path: input.path,
      body: input.body,
      line: input.line,
      side: input.side,
      startLine: input.startLine ?? null,
      startSide: input.startLine ? input.startSide ?? input.side : null,
    },
  );
  const node = data.addPullRequestReviewThread.thread.comments.nodes[0];
  return { id: node.databaseId, nodeId: node.id };
}

/** Append a whole-file (subject_type=file) comment to a pending review
 * (GraphQL subjectType: FILE; verified to work in pending state). */
export async function addPendingFileComment(
  reviewNodeId: string,
  input: { path: string; body: string },
): Promise<PendingCommentIds> {
  const data: {
    addPullRequestReviewThread: {
      thread: { comments: { nodes: { databaseId: number; id: string }[] } };
    };
  } = await graphql(
    `
      mutation AddPendingFile($reviewId: ID!, $path: String!, $body: String!) {
        addPullRequestReviewThread(
          input: {
            pullRequestReviewId: $reviewId
            path: $path
            body: $body
            subjectType: FILE
          }
        ) {
          thread { comments(first: 1) { nodes { databaseId id } } }
        }
      }
    `,
    { reviewId: reviewNodeId, path: input.path, body: input.body },
  );
  const node = data.addPullRequestReviewThread.thread.comments.nodes[0];
  return { id: node.databaseId, nodeId: node.id };
}

/** Append a pending reply to an existing thread (GraphQL inReplyTo —
 * REST in_reply_to 422s while pending). `inReplyToNodeId` is the head
 * comment's GraphQL node id. */
export async function addPendingReply(
  reviewNodeId: string,
  inReplyToNodeId: string,
  body: string,
): Promise<PendingCommentIds> {
  const data: {
    addPullRequestReviewComment: {
      comment: { databaseId: number; id: string };
    };
  } = await graphql(
    `
      mutation AddPendingReply($reviewId: ID!, $reply: ID!, $body: String!) {
        addPullRequestReviewComment(
          input: {
            pullRequestReviewId: $reviewId
            inReplyTo: $reply
            body: $body
          }
        ) {
          comment { databaseId id }
        }
      }
    `,
    { reviewId: reviewNodeId, reply: inReplyToNodeId, body },
  );
  const c = data.addPullRequestReviewComment.comment;
  return { id: c.databaseId, nodeId: c.id };
}

/** Edit a pending comment body (GraphQL — REST PATCH 404s on pending). */
export async function updatePendingComment(
  commentNodeId: string,
  body: string,
): Promise<void> {
  await graphql(
    `
      mutation UpdatePending($id: ID!, $body: String!) {
        updatePullRequestReviewComment(
          input: { pullRequestReviewCommentId: $id, body: $body }
        ) {
          pullRequestReviewComment { databaseId }
        }
      }
    `,
    { id: commentNodeId, body },
  );
}

/** Delete a pending comment (GraphQL). Note: deleting the last comment
 * does NOT auto-delete the review — callers must discardPendingReview
 * when the count hits zero (ADR 0019 §empty-review cleanup). */
export async function deletePendingComment(
  commentNodeId: string,
): Promise<void> {
  await graphql(
    `
      mutation DeletePending($id: ID!) {
        deletePullRequestReviewComment(input: { id: $id }) {
          pullRequestReview { databaseId }
        }
      }
    `,
    { id: commentNodeId },
  );
}

/** Submit the pending review with a verdict (REST events endpoint) —
 * publishes the whole batch at once. */
export async function submitPendingReview(
  owner: string,
  repo: string,
  number: number,
  reviewId: number,
  event: 'APPROVE' | 'REQUEST_CHANGES' | 'COMMENT',
  body?: string,
): Promise<{ id: number; state: string; html_url: string }> {
  const { data } = await request<{
    id: number;
    state: string;
    html_url: string;
  }>(`/repos/${owner}/${repo}/pulls/${number}/reviews/${reviewId}/events`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ event, body: body?.trim() || undefined }),
  });
  return data;
}

/** Discard the pending review (REST DELETE). Also used for empty-review
 * cleanup when the last pending comment is deleted. */
export async function discardPendingReview(
  owner: string,
  repo: string,
  number: number,
  reviewId: number,
): Promise<void> {
  await request<void>(
    `/repos/${owner}/${repo}/pulls/${number}/reviews/${reviewId}`,
    { method: 'DELETE' },
  );
}

/** "Add single comment" — publish a standalone line comment immediately,
 * belonging to no pending review (REST; only valid when the viewer has
 * NO pending review, else GitHub 422s). Renders as a normal published
 * thread. */
export async function createSingleReviewComment(
  owner: string,
  repo: string,
  number: number,
  commitId: string,
  input: {
    path: string;
    body: string;
    line?: number;
    side?: 'LEFT' | 'RIGHT';
    startLine?: number;
    startSide?: 'LEFT' | 'RIGHT';
    subjectType?: 'line' | 'file';
  },
): Promise<GHReviewComment> {
  const body: Record<string, unknown> = {
    commit_id: commitId,
    path: input.path,
    body: input.body,
  };
  if (input.subjectType === 'file') {
    body.subject_type = 'file';
  } else {
    body.line = input.line;
    body.side = input.side;
    if (input.startLine && input.startLine !== input.line) {
      body.start_line = input.startLine;
      body.start_side = input.startSide ?? input.side;
    }
  }
  const { data } = await request<GHReviewComment>(
    `/repos/${owner}/${repo}/pulls/${number}/comments`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    },
  );
  return data;
}

/**
 * Review comments — line-anchored conversation threads. These are the
 * comments that get overlaid on diff lines in the Changes tab via
 * @pierre/diffs's annotation API.
 *
 * Paginated; cap at 500 for v1 (PRs with more comments than that are
 * rare and we can lift later).
 */
export async function getReviewComments(
  owner: string,
  repo: string,
  number: number,
): Promise<GHReviewComment[]> {
  const all: GHReviewComment[] = [];
  for (let page = 1; page <= 5; page++) {
    const { data } = await request<GHReviewComment[]>(
      `/repos/${owner}/${repo}/pulls/${number}/comments?per_page=100&page=${page}`,
    );
    all.push(...data);
    if (data.length < 100) break;
  }
  return all;
}

// ── Attachment upload: public assets repo (ADR 0018 §4) ─────────
//
// Image attachments on GitHub-bound comments can't reach GitHub's native
// CDN with a PAT (it's web-session-only), so we commit them to a public
// `<viewer>/pyor-assets` repo via the Contents API and embed the stable
// raw URL. Repo-create + contents-write are both covered by the existing
// classic `repo` scope — no new scope. These three primitives use the
// shared `request` wrapper (auth, error shaping); the orchestration +
// base64/path logic lives in src/github/assets.ts.

/** True if the repo exists and is readable; false on 404. Other errors
 * (401/403/network) propagate so callers don't mistake an auth failure
 * for "needs creating". */
export async function repoExists(owner: string, repo: string): Promise<boolean> {
  try {
    await request<unknown>(`/repos/${owner}/${repo}`);
    return true;
  } catch (e) {
    if (e instanceof GitHubError && e.status === 404) return false;
    throw e;
  }
}

/** Create a repo on the authenticated user's account. `auto_init` writes
 * an initial commit so the default `main` branch exists immediately —
 * required for the `raw.githubusercontent.com/.../main/...` URLs to
 * resolve right after the first upload. */
export async function createUserRepo(
  name: string,
  opts: { private: boolean; description?: string },
): Promise<void> {
  await request<unknown>('/user/repos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name,
      private: opts.private,
      auto_init: true,
      description: opts.description,
    }),
  });
}

/** PUT a file into a repo via the Contents API. `contentBase64` is the
 * base64-encoded bytes (the wire format the endpoint requires). Returns
 * the created blob's download URL fields are ignored — callers build the
 * stable raw URL themselves. */
export async function putRepoFile(
  owner: string,
  repo: string,
  path: string,
  contentBase64: string,
  message: string,
): Promise<void> {
  await request<unknown>(
    `/repos/${owner}/${repo}/contents/${path
      .split('/')
      .map(encodeURIComponent)
      .join('/')}`,
    {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message, content: contentBase64 }),
    },
  );
}
