// UnderlineTabs — shadcn-styled underline tab strip.
//
// Matches design's STabsUnderline: a horizontal bar with bottom border,
// each tab a clickable button with optional icon + label + count badge,
// and an optional "failing N" pill (used by the Checks tab in PR
// detail). The active tab gets a bold label and a 2px underline that
// sits flush with the bar's bottom border.
//
// Implemented as a controlled component (value + onValueChange) instead
// of Radix Tabs because the only Radix feature we'd need is keyboard
// nav within the strip — and these strips already hand keyboard
// navigation off to the surrounding screen (J/K, arrow keys handled
// at the list level). Keeping it as plain buttons makes integration
// with hashed routes / counts / icons trivial.

import { useId, type ReactNode } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import type { LucideIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

// Sliding-underline spring — matches smoothui's animated-tabs feel.
const TABS_SPRING = { type: 'spring' as const, duration: 0.25, bounce: 0.05 };

export interface UnderlineTab<Id extends string> {
  id: Id;
  label: string;
  icon?: LucideIcon;
  /** Item count shown as a small badge to the right of the label. */
  count?: number;
  /** "N failing" destructive pill — used by the Checks tab in PR detail. */
  failing?: number;
}

interface UnderlineTabsProps<Id extends string> {
  tabs: UnderlineTab<Id>[];
  active: Id;
  onChange?: (id: Id) => void;
  /** Right-aligned slot — used by the Pulls tabs bar to host the
   * search input + DateRangeChip on the same row as the tabs. */
  right?: ReactNode;
  className?: string;
}

export function UnderlineTabs<Id extends string>({
  tabs,
  active,
  onChange,
  right,
  className,
}: UnderlineTabsProps<Id>) {
  // Shared layoutId so the active underline slides between tabs; useId
  // keeps each strip independent (PR tabs vs Pulls tabs on screen at once).
  // "use no memo": React Compiler memoization interferes with motion's
  // layout-animation tracking, so opt this component out.
  "use no memo";
  const reduce = useReducedMotion();
  const underlineId = useId();
  return (
    <div
      className={cn(
        'flex items-center border-b px-5',
        right ? 'gap-3' : null,
        className,
      )}
    >
      <div className="flex items-center">
        {tabs.map((t) => {
          const isActive = t.id === active;
          const Icon = t.icon;
          return (
            <button
              key={t.id}
              type="button"
              onClick={() => onChange?.(t.id)}
              className={cn(
                'relative flex shrink-0 items-center gap-1.5 whitespace-nowrap px-3 py-2.5 text-[13px] transition-colors',
                isActive
                  ? 'font-semibold text-foreground'
                  : 'font-medium text-muted-foreground hover:text-foreground',
              )}
            >
              {isActive && (
                <motion.span
                  layoutId={underlineId}
                  className="absolute inset-x-0 -bottom-px h-0.5 bg-foreground"
                  transition={reduce ? { duration: 0 } : TABS_SPRING}
                />
              )}
              {Icon && (
                <Icon
                  className={cn(
                    'size-3.5',
                    isActive ? '' : 'text-muted-foreground/70',
                  )}
                />
              )}
              {t.label}
              {t.count != null && (
                <Badge
                  variant={isActive ? 'secondary' : 'outline'}
                  className="ml-0.5 px-1.5 py-0 text-[10px] tabular-nums"
                >
                  {t.count}
                </Badge>
              )}
              {t.failing != null && t.failing > 0 && (
                <Badge
                  variant="destructive"
                  className="px-1.5 py-0 text-[10px] tabular-nums"
                >
                  {t.failing} failing
                </Badge>
              )}
            </button>
          );
        })}
      </div>
      {right && <div className="ml-auto flex items-center gap-2 py-1.5">{right}</div>}
    </div>
  );
}
