// Desktop update toasts (ADR 0023). No-op on web — `bridge()` returns null.
//
// The download/install/ready lifecycle is shown by the sidebar UpdateGauge
// widget. This hook only handles the one case the gauge can't: a newer version
// exists but can't be auto-installed (macOS non-writable bundle, or Linux .deb)
// → prompt a manual download.

import { useEffect } from 'react';
import { toast } from 'sonner';
import { bridge } from './electronBridge';

const DOWNLOAD_URL = 'https://pyor.review/download';

export function useDesktopUpdates(): void {
  useEffect(() => {
    const b = bridge();
    if (!b) return;
    return b.onUpdateAvailable((version) => {
      toast.message(`Pyor v${version} is available`, {
        description: 'Download the new version to update.',
        action: {
          label: 'Download',
          onClick: () => void b.openExternal(DOWNLOAD_URL),
        },
        duration: Infinity,
      });
    });
  }, []);
}
