// Local-review-specific annotation glue for @pierre/diffs.
//
// Mirrors the (PR-side) helpers in `src/github/buildDiff.ts` —
// attachThreadsToItems / withComposerAnnotation / withFileComposerAnnotation —
// but keyed to the LocalReviewComment shape and a single,
// local-only ComposerSpec discriminant. Lives under `pr/local/` so the
// shared GitHub-domain types stay clean of local-review concerns
// (ADR 0011 / 0012 separation of mental models).
//
// Annotation kinds:
//   - `local-comments`: a stack of one or more saved LocalReviewComments
//     anchored at `(path, line, side)`. Renders LocalCommentStack.
//   - `local-line-composer`: an open line-level composer.
//   - `local-file-composer`: an open file-level composer (anchored to
//     the file's first available line, like the PR-side file composer).

import type {
  CodeViewDiffItem,
  DiffLineAnnotation,
} from '@pierre/diffs/react';
import type { LocalReviewComment } from '../../review/localReviewComments';

export type LocalAnnotationMeta =
  | { kind: 'local-comments'; comments: LocalReviewComment[] }
  | {
      kind: 'local-line-composer';
      path: string;
      line: number;
      startLine?: number;
      side: 'LEFT' | 'RIGHT';
      anchorSha: string;
      contentSnippet: string | null;
    }
  | { kind: 'local-file-composer'; path: string; anchorSha: string }
  | {
      /** Content-less rename / move / mode-only file. Always-on note row
       * rendered in the empty body (mirrors the PR-side `rename-note`). */
      kind: 'local-rename-note';
      path: string;
      previousFilename?: string;
    }
  | {
      /** OUTDATED line comments whose anchored snippet no longer exists in
       * the file (a later commit changed the line). Like the PR detail page,
       * these float at the file's first line and render the FROZEN snippet
       * captured at write time, rather than mis-anchoring on a stale line. */
      kind: 'local-outdated';
      path: string;
      comments: LocalReviewComment[];
    };

type LocalAnnotation = DiffLineAnnotation<LocalAnnotationMeta>;
export type LocalDiffItem = CodeViewDiffItem<LocalAnnotationMeta>;

/** Spec for the one open line-composer. The user only ever has a single
 * composer open at a time — opening a new one closes the previous. */
export interface LocalLineComposerSpec {
  path: string;
  line: number;
  startLine?: number;
  side: 'LEFT' | 'RIGHT';
  anchorSha: string;
  contentSnippet: string | null;
}

/** Group comments by their (path, line, side) anchor. File-level
 * comments (line == null) bucket separately by path — they don't show
 * on any specific line, they show in the header. */
export interface GroupedComments {
  /** path → line → side → comments. */
  byLine: Map<string, Map<number, { LEFT: LocalReviewComment[]; RIGHT: LocalReviewComment[] }>>;
  /** path → comments. */
  byFile: Map<string, LocalReviewComment[]>;
}

export function groupComments(comments: LocalReviewComment[]): GroupedComments {
  const byLine = new Map<
    string,
    Map<number, { LEFT: LocalReviewComment[]; RIGHT: LocalReviewComment[] }>
  >();
  const byFile = new Map<string, LocalReviewComment[]>();
  for (const c of comments) {
    if (c.line == null) {
      const arr = byFile.get(c.path) ?? [];
      arr.push(c);
      byFile.set(c.path, arr);
      continue;
    }
    let perPath = byLine.get(c.path);
    if (!perPath) {
      perPath = new Map();
      byLine.set(c.path, perPath);
    }
    let perLine = perPath.get(c.line);
    if (!perLine) {
      perLine = { LEFT: [], RIGHT: [] };
      perPath.set(c.line, perLine);
    }
    perLine[c.side].push(c);
  }
  return { byLine, byFile };
}

/** Weak hash so CodeView's syncItemRecord can decide whether an item
 * actually changed. Same djb2-ish strategy as buildDiff.ts hashAnnotations
 * — narrow surface, cheap, collision pressure negligible. */
// Fold one annotation's metadata into the running hash `h`.
function hashMeta(h: number, meta: LocalAnnotation['metadata']): number {
  if (!meta) return h;
  if (meta.kind === 'local-comments') {
    h = ((h << 5) + h) ^ 1;
    h = ((h << 5) + h) ^ (meta.comments.length | 0);
    meta.comments.forEach((c) => {
      // Capture id-length + updatedAt-length so edit/delete trigger a
      // re-render (the body itself is too expensive to hash on every
      // scroll; the per-comment surface re-mount on rerender would
      // otherwise read the stale value).
      h = ((h << 5) + h) ^ c.id.length;
      h = ((h << 5) + h) ^ c.updatedAt.length;
      h = ((h << 5) + h) ^ (c.dismissed ? 1 : 0);
    });
    return h;
  }
  if (meta.kind === 'local-line-composer') {
    h = ((h << 5) + h) ^ 2;
    h = ((h << 5) + h) ^ (meta.startLine ?? 0);
    h = ((h << 5) + h) ^ (meta.side === 'LEFT' ? 0 : 1);
    return h;
  }
  if (meta.kind === 'local-outdated') {
    h = ((h << 5) + h) ^ 4;
    h = ((h << 5) + h) ^ (meta.comments.length | 0);
    meta.comments.forEach((c) => {
      h = ((h << 5) + h) ^ c.id.length;
      h = ((h << 5) + h) ^ c.updatedAt.length;
      h = ((h << 5) + h) ^ (c.dismissed ? 1 : 0);
    });
    return h;
  }
  return ((h << 5) + h) ^ 3;
}

function hashAnnotations(annotations: LocalAnnotation[]): number {
  let h = 5381;
  annotations.forEach((a) => {
    h = ((h << 5) + h) ^ (a.lineNumber | 0);
    h = ((h << 5) + h) ^ (a.side === 'deletions' ? 0 : 1);
    h = hashMeta(h, a.metadata);
  });
  return h | 0;
}

/** Attach saved-comment annotations to items. Empty-input items pass
 * through with identity preserved so React diff skips them. */
export function attachLocalCommentsToItems(
  items: CodeViewDiffItem[],
  grouped: GroupedComments,
): LocalDiffItem[] {
  return items.map((item) => {
    const perPath = grouped.byLine.get(item.id);
    if (!perPath) return item as LocalDiffItem;
    const annotations: LocalAnnotation[] = [];
    for (const [line, sides] of perPath) {
      if (sides.LEFT.length > 0) {
        annotations.push({
          lineNumber: line,
          side: 'deletions',
          metadata: { kind: 'local-comments', comments: sides.LEFT },
        });
      }
      if (sides.RIGHT.length > 0) {
        annotations.push({
          lineNumber: line,
          side: 'additions',
          metadata: { kind: 'local-comments', comments: sides.RIGHT },
        });
      }
    }
    if (annotations.length === 0) return item as LocalDiffItem;
    return {
      ...item,
      annotations,
      version: hashAnnotations(annotations),
    } as LocalDiffItem;
  });
}

/** Merge a single open line-composer into the items list. */
export function withLocalLineComposerAnnotation(
  items: LocalDiffItem[],
  spec: LocalLineComposerSpec | null,
): LocalDiffItem[] {
  if (!spec) return items;
  return items.map((item) => {
    if (item.id !== spec.path) return item;
    const existing = item.annotations ?? [];
    const composerAnnotation: LocalAnnotation = {
      lineNumber: spec.line,
      side: spec.side === 'LEFT' ? 'deletions' : 'additions',
      metadata: {
        kind: 'local-line-composer',
        path: spec.path,
        line: spec.line,
        startLine: spec.startLine,
        side: spec.side,
        anchorSha: spec.anchorSha,
        contentSnippet: spec.contentSnippet,
      },
    };
    const annotations = [...existing, composerAnnotation];
    return {
      ...item,
      annotations,
      version: hashAnnotations(annotations),
    };
  });
}

/** Merge a single open file-level composer into the items list. The
 * annotation anchors to the file's first available line (same strategy
 * as the PR-side withFileComposerAnnotation — we don't have a real line
 * for file-level, but the lib needs one to render the annotation). */
export function withLocalFileComposerAnnotation(
  items: LocalDiffItem[],
  filePath: string | null,
  anchorShaForPath: (path: string) => string,
): LocalDiffItem[] {
  if (!filePath) return items;
  return items.map((item) => {
    if (item.id !== filePath) return item;
    if (item.type !== 'diff') return item;
    const hunks = item.fileDiff.hunks;
    let lineNumber = 1;
    let side: 'deletions' | 'additions' = 'additions';
    if (hunks.length > 0) {
      const h = hunks[0];
      if (h.additionCount > 0 && h.additionStart > 0) {
        lineNumber = h.additionStart;
      } else if (h.deletionCount > 0 && h.deletionStart > 0) {
        lineNumber = h.deletionStart;
        side = 'deletions';
      } else {
        lineNumber = h.additionStart || h.deletionStart || 1;
      }
    }
    const existing = item.annotations ?? [];
    const fileAnnotation: LocalAnnotation = {
      lineNumber,
      side,
      metadata: {
        kind: 'local-file-composer',
        path: filePath,
        anchorSha: anchorShaForPath(filePath),
      },
    };
    const annotations = [...existing, fileAnnotation];
    return {
      ...item,
      annotations,
      version: hashAnnotations(annotations),
    };
  });
}

/** Anchor OUTDATED line comments at the SAME line they were written on
 * (their snippet no longer matches because a later commit changed that
 * line). Unlike a fresh `local-comments` annotation, this renders the
 * FROZEN snippet captured at write time alongside the card + Outdated chip,
 * so the reviewer sees what the note originally referred to — pinned in
 * place, not floated. One annotation per (line, side) carries that anchor's
 * outdated comments. */
export function withLocalOutdatedComments(
  items: LocalDiffItem[],
  outdatedByPath: Map<string, LocalReviewComment[]>,
): LocalDiffItem[] {
  if (outdatedByPath.size === 0) return items;
  return items.map((item) => {
    const comments = outdatedByPath.get(item.id);
    if (!comments || comments.length === 0 || item.type !== 'diff') return item;
    // Bucket by the comment's own (line, side) so each pins to its anchor.
    const byAnchor = new Map<string, LocalReviewComment[]>();
    for (const c of comments) {
      if (c.line == null) continue;
      const key = `${c.line}:${c.side}`;
      const arr = byAnchor.get(key) ?? [];
      arr.push(c);
      byAnchor.set(key, arr);
    }
    if (byAnchor.size === 0) return item;
    const existing = item.annotations ?? [];
    const outdatedAnnotations: LocalAnnotation[] = [];
    for (const group of byAnchor.values()) {
      const first = group[0];
      outdatedAnnotations.push({
        lineNumber: first.line as number,
        side: first.side === 'LEFT' ? 'deletions' : 'additions',
        metadata: { kind: 'local-outdated', path: item.id, comments: group },
      });
    }
    const annotations = [...existing, ...outdatedAnnotations];
    return {
      ...item,
      annotations,
      version: hashAnnotations(annotations),
    };
  });
}

/** Attach an always-on `local-rename-note` annotation to each
 * content-less rename/move item so the "No content changes" note row
 * renders in the empty body. Mirrors the PR-side `withRenameNoteAnnotations`.
 * Anchored to the placeholder's first line (line 1). */
export function withLocalRenameNoteAnnotations(
  items: LocalDiffItem[],
  renamedFiles: { filename: string; previousFilename?: string }[],
): LocalDiffItem[] {
  if (renamedFiles.length === 0) return items;
  const byPath = new Map(renamedFiles.map((f) => [f.filename, f]));
  return items.map((item) => {
    const entry = byPath.get(item.id);
    if (!entry || item.type !== 'diff') return item;
    const existing = item.annotations ?? [];
    const noteAnnotation: LocalAnnotation = {
      lineNumber: 1,
      side: 'additions',
      metadata: {
        kind: 'local-rename-note',
        path: entry.filename,
        ...(entry.previousFilename
          ? { previousFilename: entry.previousFilename }
          : {}),
      },
    };
    const annotations = [...existing, noteAnnotation];
    return {
      ...item,
      annotations,
      version: hashAnnotations(annotations),
    };
  });
}

/** Pull the line text at `(path, line, side)` from the loaded contents
 * map. Used by the gutter-click handler to capture the comment's
 * `contentSnippet` at write time (Phase 4's staleness fingerprint).
 *
 * `side: LEFT` reads the old text; `side: RIGHT` reads the new text.
 * Lines are 1-indexed (matches the @pierre/diffs gutter click semantics
 * + the LocalReviewComment storage shape).
 *
 * Returns null if the file isn't loaded yet, the line is out of range,
 * or the content is binary. Caller passes null straight through to the
 * comment store — the algorithm will treat a missing snippet as
 * conservatively-fresh. */
export function readLineSnippet(
  contents: Map<
    string,
    { oldText: string | null; newText: string | null; isBinary?: boolean }
  >,
  path: string,
  line: number,
  side: 'LEFT' | 'RIGHT',
): string | null {
  const c = contents.get(path);
  if (!c || c.isBinary) return null;
  const text = side === 'LEFT' ? c.oldText : c.newText;
  if (text == null || text === '') return null;
  // String.split('\n') matches the line-number convention the lib uses
  // (1-indexed lines in the original/new sides).
  const lines = text.split('\n');
  const raw = lines[line - 1];
  if (raw == null) return null;
  // Mirror the ADR's storage rule: trimEnd, first 200 chars.
  return raw.trimEnd().slice(0, 200);
}
