// Per-PR manual collapse overrides. Layered on top of the viewed-
// state-derived collapsed flag: a file is collapsed iff
//   manual[path] === 'closed' || (manual[path] === undefined && isViewed(path))
// i.e. clicking the chevron on a viewed file *expands* it (override
// 'open'), and clicking the chevron on an unviewed file *collapses*
// it (override 'closed'). Resetting the override falls back to the
// viewed-derived default.
//
// Persisted to localStorage so a reload preserves what the user
// has expanded / kept collapsed. Not synced to GitHub — purely UI
// state, no remote counterpart.
//
// Storage key shape mirrors viewedStore / draftStore (review-scoped):
//   pyor:collapse:pr:{owner}/{repo}/{number}        (v1 GitHub PR)
//   pyor:collapse:local:{repoPath}#{head}           (v2 Pre-PR Review)
//     → { paths: { [path]: 'open' | 'closed' } }
//
// We track BOTH directions explicitly (rather than just 'closed')
// because we need to remember that a viewed file was manually
// re-opened.

import {
  legacyPrKey,
  prReviewId,
  storageKey,
  type ReviewId,
} from '../../review/reviewId';

export type CollapseOverride = 'open' | 'closed';

interface PersistedShape {
  paths: Record<string, CollapseOverride>;
}

function readRaw(id: ReviewId): PersistedShape {
  const k = storageKey('collapse', id);
  try {
    let raw = localStorage.getItem(k);
    // Legacy migration: previous shape was
    // pyor:collapse:{owner}/{repo}/{number} — PR-only, no Pre-PR
    // ever wrote in the old format.
    if (!raw && id.kind === 'pr') {
      const oldKey = legacyPrKey('collapse', id.owner, id.repo, id.number);
      const oldRaw = localStorage.getItem(oldKey);
      if (oldRaw) {
        localStorage.setItem(k, oldRaw);
        localStorage.removeItem(oldKey);
        raw = oldRaw;
      }
    }
    if (!raw) return { paths: {} };
    const parsed = JSON.parse(raw) as Partial<PersistedShape>;
    return {
      paths:
        parsed && typeof parsed === 'object' && parsed.paths != null
          ? parsed.paths
          : {},
    };
  } catch {
    return { paths: {} };
  }
}

function writeRaw(id: ReviewId, shape: PersistedShape): void {
  try {
    localStorage.setItem(storageKey('collapse', id), JSON.stringify(shape));
  } catch {
    // ignore — same-shape failure mode as the rest of the stores
  }
}

/** Build a stable, mutation-tracking store for one PR. Snapshot is a
 * fresh Map on every change so React state can rely on identity. */
export interface CollapseStore {
  snapshot(): Map<string, CollapseOverride>;
  set(path: string, override: CollapseOverride): void;
  clear(path: string): void;
  setMany(paths: ReadonlyArray<string>, override: CollapseOverride): void;
  clearAll(): void;
}

export function makeCollapseStore(
  owner: string,
  repo: string,
  number: number,
): CollapseStore;
export function makeCollapseStore(id: ReviewId): CollapseStore;
export function makeCollapseStore(
  a: string | ReviewId,
  repo?: string,
  number?: number,
): CollapseStore {
  const id: ReviewId =
    typeof a === 'string' ? prReviewId(a, repo!, number!) : a;
  let cache = readRaw(id).paths;
  const toMap = (): Map<string, CollapseOverride> => {
    const m = new Map<string, CollapseOverride>();
    for (const [k, v] of Object.entries(cache)) m.set(k, v);
    return m;
  };
  const persist = () => writeRaw(id, { paths: cache });
  return {
    snapshot: toMap,
    set(path, override) {
      cache = { ...cache, [path]: override };
      persist();
    },
    clear(path) {
      if (!(path in cache)) return;
      const { [path]: _omit, ...rest } = cache;
      void _omit;
      cache = rest;
      persist();
    },
    setMany(paths, override) {
      const next = { ...cache };
      for (const p of paths) next[p] = override;
      cache = next;
      persist();
    },
    clearAll() {
      cache = {};
      persist();
    },
  };
}
