// Typed search-param schemas — the single source of truth for every
// route's query string (Valibot + TanStack Router).
//
// Design — "explicit defaults, everywhere":
//   - Each route's search is a Valibot object whose *view-state* fields
//     (tab / status / date / sort / diff) carry a `.default`, so parsing
//     an empty URL yields a fully-populated, typed object. The address
//     bar is then canonicalised (see `needsCanonical` + the routes'
//     `beforeLoad`) so those defaults are always visible + shareable —
//     `/pulls?tab=mine&status=open&date=30d&sort=updated-desc`, never a
//     bare `/pulls`.
//   - "Narrowing" filters (repo / author / label / reviewer / ci / q /
//     commits / anchor) have no default: they're absent until applied,
//     and serialise only when set. Their natural default *is* absence,
//     so we don't pollute the URL with `repo=any&author=any&…`.
//
// Valibot gives us: one declaration → runtime validation (with safe
// fallback to defaults on a malformed URL) + the static type via
// `v.InferOutput`. TanStack Router consumes these through each route's
// `validateSearch`, making `useSearch`/`navigate`/`<Link>` fully typed.

import * as v from 'valibot';
import { deepEqual } from '@tanstack/react-router';
import type { PRTab } from '../pr/PRTabs';
import type { DiffMode } from '../pr/changes/diffMode';
import type {
  InboxCommentType,
  InboxRelationship,
  InboxSort,
  InboxState,
} from '../github/inboxComments';

// ── Enums (kept in sync with the domain types they mirror) ─────────
// Inbox is now a single comments-only dashboard (no tabs). Its URL
// carries the server-side "From GitHub" filter band so a query is
// shareable + reload-stable (the client refine band stays local). The
// enums mirror the qualifier unions in github/inboxComments.ts.
const INBOX_REL = [
  'involves',
  'review-requested',
  'mentions',
  'commenter',
  'reviewed-by',
  'assignee',
  'author',
] as const;
const INBOX_STATE = ['open', 'merged', 'closed', 'draft', 'any'] as const;
const INBOX_SORT = ['updated', 'created'] as const;
// Client-side refine band (also URL-persisted): comment surface +
// thread resolution. Both are "narrowing" — absent until applied.
const INBOX_TYPES = [
  'conversation',
  'review-inline',
  'review-summary',
  'file-level',
  'commit',
] as const;
// The `type` filter is defaulted (→ always in the URL), so it needs an
// explicit 'any' member to be selectable; default is 'review-inline'
// since the inbox is a code-review surface.
const INBOX_TYPE_FILTER = [
  'any',
  'conversation',
  'review-inline',
  'review-summary',
  'file-level',
  'commit',
] as const;
const INBOX_THREADS = ['resolved', 'unresolved'] as const;
const PULLS_TABS = ['mine', 'reviewing', 'team'] as const; // 'reviewing' === Lens 'inbox'
// Team review-radar sort keys (short slugs keep the URL tidy; the screen
// maps these to the human "Unblock value" / "Oldest first" / … labels).
const RADAR_SORTS = ['unblock', 'oldest', 'newest', 'comments', 'diff'] as const;
export type RadarSortKey = (typeof RADAR_SORTS)[number];
const STATUSES = ['open', 'draft', 'closed', 'merged', 'all'] as const; // StatusFilter
const DATES = ['24h', '7d', '30d', 'all'] as const; // DateRangePreset
const SORTS = [
  'updated-desc',
  'created-desc',
  'created-asc',
  'comments-desc',
] as const;
const CIS = ['success', 'failure', 'pending'] as const;
const PR_TABS = ['description', 'commits', 'changes'] as const;
const DIFF_MODES = ['split', 'inline'] as const;

// Compile-time guards: the URL enums must stay aligned with the domain
// unions they serialise (PRTab / DiffMode). If either drifts, this fails
// to type-check.
const _prTabCheck: readonly PRTab[] = PR_TABS;
const _diffCheck: readonly DiffMode[] = DIFF_MODES;
const _inboxRelCheck: readonly InboxRelationship[] = INBOX_REL;
const _inboxStateCheck: readonly InboxState[] = INBOX_STATE;
const _inboxSortCheck: readonly InboxSort[] = INBOX_SORT;
const _inboxTypeCheck: readonly InboxCommentType[] = INBOX_TYPES;
void _prTabCheck;
void _diffCheck;
void _inboxRelCheck;
void _inboxStateCheck;
void _inboxSortCheck;
void _inboxTypeCheck;

type PullsTab = (typeof PULLS_TABS)[number];
type PullsStatus = (typeof STATUSES)[number];
type PullsDate = (typeof DATES)[number];
type PullsSort = (typeof SORTS)[number];

// ── Schemas ────────────────────────────────────────────────────────

/** A view-state enum field that is always present with a default. The
 * `v.fallback` makes a *malformed* value recover to the default on its
 * own — without it, one bad enum (e.g. a hand-edited `?status=bogus`)
 * would fail the whole parse and reset every other (valid) param too. */
function enumWithDefault<const T extends readonly [string, ...string[]]>(
  options: T,
  fallback: T[number],
) {
  return v.optional(v.fallback(v.picklist(options), fallback), fallback);
}

// URLs JSON-parse their search values, so a numeric-looking value
// (`?q=123`, a numeric comment id `?acid=42`, `?focus=true`) arrives as
// a number/boolean — NOT a string. The helpers below coerce per-field
// and drop anything unusable, so a single odd value can never fail the
// whole-object parse (which would reset every other param to defaults).

/** Optional free-text param — coerces number/boolean to string. */
const looseString = v.optional(
  v.pipe(v.union([v.string(), v.number(), v.boolean()]), v.transform(String)),
);

/** Optional enum that drops an out-of-range value instead of throwing. */
function optEnum<const T extends readonly [string, ...string[]]>(options: T) {
  return v.optional(
    v.pipe(
      v.unknown(),
      v.transform((x) =>
        options.includes(x as T[number]) ? (x as T[number]) : undefined,
      ),
    ),
  );
}

/** Optional line number — coerces from string, drops non-finite. */
const looseLine = v.optional(
  v.pipe(
    v.unknown(),
    v.transform((x) => {
      const n = typeof x === 'number' ? x : Number(x);
      return Number.isFinite(n) ? n : undefined;
    }),
  ),
);

/** Optional boolean flag — true for true/'true'/1/'1', else dropped. */
const looseBool = v.optional(
  v.pipe(
    v.unknown(),
    v.transform((x) =>
      x === true || x === 'true' || x === 1 || x === '1' ? true : undefined,
    ),
  ),
);

const inboxSearchSchema = v.object({
  // View-state (always defaulted → always in the URL) — the server
  // "From GitHub" band. Changing any of these re-issues the search.
  rel: enumWithDefault(INBOX_REL, 'involves'),
  state: enumWithDefault(INBOX_STATE, 'open'),
  date: enumWithDefault(DATES, '7d'),
  sort: enumWithDefault(INBOX_SORT, 'updated'),
  // Narrowing qualifiers (absent until applied).
  //   scope     = full scope qualifier (`org:foo` / `repo:foo/bar`)
  //   label     = bare label name → `label:"…"`
  //   commenter = comment author → `commenter:LOGIN`
  //   q         = free text → `"…" in:comments`
  scope: looseString,
  label: looseString,
  commenter: looseString,
  q: looseString,
  // Client-side "Refine in Pyor" band — also URL-persisted so the whole
  // filter state is shareable + reload-stable. These filter in memory
  // over the fetched set (no refetch). Absent = unfiltered.
  //   type     = comment surface (defaulted to 'review-inline'; 'any' to widen)
  //   thread   = thread resolution (resolved / unresolved)
  //   unread   = unread-only toggle
  //   hidemine = drop the viewer's own comments (others-only view)
  type: enumWithDefault(INBOX_TYPE_FILTER, 'review-inline'),
  thread: optEnum(INBOX_THREADS),
  unread: looseBool,
  hidemine: looseBool,
});

const pullsSearchSchema = v.object({
  // View-state (always defaulted → always in the URL).
  tab: enumWithDefault(PULLS_TABS, 'mine'),
  status: enumWithDefault(STATUSES, 'open'),
  date: enumWithDefault(DATES, '30d'),
  sort: enumWithDefault(SORTS, 'updated-desc'),
  // Narrowing filters (absent until applied).
  repo: looseString,
  author: looseString,
  label: looseString,
  reviewer: looseString,
  ci: optEnum(CIS),
  q: looseString,
  // Team review-radar scope (tab === 'team' only; absent otherwise):
  //   org     = scoped org login ('all' / absent = every org)
  //   authors = comma-joined teammate logins
  //   tsort   = radar sort key (see RADAR_SORTS)
  org: looseString,
  authors: looseString,
  tsort: optEnum(RADAR_SORTS),
});

const prSearchSchema = v.object({
  tab: enumWithDefault(PR_TABS, 'description'),
  diff: enumWithDefault(DIFF_MODES, 'split'),
  // Comma-joined commit SHAs for the commit filter.
  commits: looseString,
  // Changes-tab inputs, persisted so a reload/share keeps them:
  //   fq = file-rail "Filter files" text, dq = "Search diff content".
  fq: looseString,
  dq: looseString,
  // Changes-tab view toggles (absent = default):
  //   rail  = file-list mode ('list'; 'tree' is the default → omitted).
  // (⇧M focus mode is deliberately NOT in the URL — it's a private
  //  per-PR preference persisted to localStorage, not shareable.)
  rail: optEnum(['tree', 'list']),
  from: optEnum(['inbox', 'pulls']),
  // Live diff anchor (line and/or comment). Short keys keep the URL
  // tidy; written on interaction + carried by Inbox · Comments links.
  // `acid` is a numeric comment id → looseString coerces it.
  apath: looseString,
  aline: looseLine,
  aside: optEnum(['LEFT', 'RIGHT']),
  // Comment id is numeric — keep it a number so the URL stays clean
  // (`acid=42`, not a quoted `acid="42"`).
  acid: looseLine,
  // Public-PR demo deep-link (AFK plan 22, `?pr=` boot branch). When
  // true the PR opens read-only — no Setup gate, no review-submission /
  // approve / merge / mark-viewed affordances. Seeded by the index
  // route's `?pr=` redirect; rides in the hash search so it survives a
  // reload of the deep-link. Only serializes when true.
  demo: looseBool,
});

export type InboxSearch = v.InferOutput<typeof inboxSearchSchema>;
export type PullsSearch = v.InferOutput<typeof pullsSearchSchema>;
export type PRSearch = v.InferOutput<typeof prSearchSchema>;

// ── Cleaning ───────────────────────────────────────────────────────

/** Drop `undefined` / empty-string keys so the serialised URL has no
 * dangling `?repo=` noise and so two searches that differ only by an
 * absent-vs-empty key compare equal. */
export function cleanSearch<T extends Record<string, unknown>>(o: T): T {
  const out: Record<string, unknown> = {};
  for (const key in o) {
    const val = o[key];
    if (val === undefined || val === '') continue;
    out[key] = val;
  }
  return out as T;
}

// ── Validators (TanStack `validateSearch`) ─────────────────────────
// A malformed value for a known key (hand-edited URL) falls back to the
// route defaults rather than erroring the whole route. Unknown keys are
// stripped by `v.object`.

function makeValidator<S extends v.GenericSchema<Record<string, unknown>>>(
  schema: S,
  defaults: v.InferOutput<S>,
) {
  return (raw: Record<string, unknown>): v.InferOutput<S> => {
    const r = v.safeParse(schema, raw);
    return r.success ? (r.output as v.InferOutput<S>) : defaults;
  };
}

// Fully-defaulted, cleaned search objects — the canonical query string
// for a fresh visit. Exported so every navigation/link call-site can
// carry the proper defaults (no redirect bounce on arrival).
export const INBOX_DEFAULTS: InboxSearch = cleanSearch(
  v.parse(inboxSearchSchema, {}),
);
export const PULLS_DEFAULTS: PullsSearch = cleanSearch(
  v.parse(pullsSearchSchema, {}),
);
export const PR_DEFAULTS: PRSearch = cleanSearch(v.parse(prSearchSchema, {}));

export const validateInboxSearch = makeValidator(
  inboxSearchSchema,
  INBOX_DEFAULTS,
);
export const validatePullsSearch = makeValidator(
  pullsSearchSchema,
  PULLS_DEFAULTS,
);
export const validatePRSearch = makeValidator(prSearchSchema, PR_DEFAULTS);

// ── Canonicalisation ───────────────────────────────────────────────

/** True when the address bar's *raw* search differs from the validated
 * (defaulted) search — i.e. the URL is missing defaults or carries junk.
 * Routes use this in `beforeLoad` to redirect to the canonical URL.
 *
 * Self-terminating: after redirecting with `cleanSearch(validated)` the
 * raw parse equals it, so the next pass returns false. */
export function needsCanonical(
  validated: Record<string, unknown>,
  rawSearch: Record<string, unknown>,
): boolean {
  return !deepEqual(cleanSearch(validated), cleanSearch(rawSearch));
}
