// ════════════════════════════════════════════════════════════════════
// ConnFailureState — the shared failure surface for all four modes.
//
//   layout="full"   → nothing could load. Centered hero with the
//                     FaultChain, reassurance chip, per-mode extra
//                     (incident strip / reset bar / auth diag table),
//                     last-synced line, primary + fallback. The caller
//                     keeps the app shell; only the content area fails.
//   layout="inline" → only one pane (the diff/file body) failed. A
//                     compact card with the one-line blame read. The
//                     caller keeps header + file rail visible.
//
// Read-only: copy never promises we save/queue/auto-post offline work.
// ════════════════════════════════════════════════════════════════════

import { useState } from 'react';
import {
  ClockIcon,
  ExternalLinkIcon,
  PlugZapIcon,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { FaultChain, ConnBlameLine, GithubMark } from './FaultChain';
import { useCountdown } from './useCountdown';
import {
  CONN_MODES,
  CONN_TONE,
  connPrimary,
  type ConnMode,
} from './connModes';

export interface ConnFailureStateProps {
  mode: ConnMode;
  layout?: 'full' | 'inline';
  /** Timestamp of the last successful sync, if known. Drives the
   * "Last synced" line and the auth diagnostic. Omitted → line hidden
   * (we never fabricate a time). */
  lastSyncedAt?: Date | null;
  /** Rate-limit reset moment (from GitHubError.rateResetAt). Drives the
   * live countdown + reset bar. */
  rateResetAt?: Date | null;
  /** Failing endpoint, shown in the auth diagnostic. */
  endpoint?: string;
  /** Primary action for offline / github-down (Retry). */
  onRetry?: () => void;
  /** Primary action for auth-expired ("Sign in again"). */
  onReauth?: () => void;
  /** Secondary/fallback action (network settings · lower rate · view on
   * github). Href fallbacks open externally on their own and don't call
   * this; modes with no secondary (auth-expired full) never call it. */
  onFallback?: () => void;
}

function formatClock(d: Date): string {
  return d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
}

function formatAgo(d: Date): string {
  const mins = Math.max(0, Math.round((Date.now() - d.getTime()) / 60000));
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins} minute${mins === 1 ? '' : 's'} ago`;
  const h = Math.floor(mins / 60);
  return `${h} hour${h === 1 ? '' : 's'} ago`;
}

export function ConnFailureState({
  mode,
  layout = 'full',
  lastSyncedAt = null,
  rateResetAt = null,
  endpoint,
  onRetry,
  onReauth,
  onFallback,
}: ConnFailureStateProps) {
  const m = CONN_MODES[mode];
  const tone = CONN_TONE[m.tone];
  const Icon = m.icon;
  const countdown = useCountdown(mode === 'rate-limit' ? rateResetAt : null);
  const primary = connPrimary(mode, countdown.text || undefined);

  // Retry spins on press (annotated motion → real here).
  const [spinning, setSpinning] = useState(false);
  const runPrimary = () => {
    if (mode === 'auth-expired') return onReauth?.();
    if (mode === 'rate-limit') return; // disabled countdown
    setSpinning(true);
    setTimeout(() => setSpinning(false), 900);
    onRetry?.();
  };

  const fallback = layout === 'inline' ? m.inline.fallback : m.full.fallback;
  const runFallback = () => {
    if (!fallback) return;
    if (fallback.href) {
      window.open(`https://www.${fallback.href}`, '_blank', 'noopener');
      return;
    }
    onFallback?.();
  };

  const PrimaryIcon = primary.icon;
  const FallbackIcon = fallback?.icon;
  const actions = (
    <div className="flex flex-col items-center gap-2.5">
      <div className="flex items-center justify-center gap-2">
        <Button
          variant={primary.disabled ? 'outline' : 'default'}
          size={layout === 'inline' ? 'sm' : 'default'}
          disabled={primary.disabled}
          onClick={runPrimary}
          className={primary.disabled ? 'font-mono tabular-nums' : ''}
        >
          <PrimaryIcon className={spinning ? 'animate-spin' : ''} />
          {primary.label}
        </Button>
        {fallback && FallbackIcon && (
          <Button
            variant="ghost"
            size={layout === 'inline' ? 'sm' : 'default'}
            onClick={runFallback}
          >
            <FallbackIcon />
            {fallback.label}
            {fallback.href && (
              <span className="ml-0.5 text-muted-foreground">{fallback.href}</span>
            )}
          </Button>
        )}
      </div>
      {primary.motion && <MotionNote>{`${primary.label.startsWith('Retry') ? 'Retry ' : ''}${primary.motion}`}</MotionNote>}
    </div>
  );

  const lastSynced = lastSyncedAt && (
    <div className="inline-flex items-center gap-1.5 whitespace-nowrap text-[11.5px] text-muted-foreground">
      <ClockIcon className="size-3" />
      Last synced{' '}
      <span className="font-medium text-foreground">{formatClock(lastSyncedAt)}</span>
      <span className="text-border">·</span>
      {formatAgo(lastSyncedAt)}
    </div>
  );

  // ── Inline (compact, single pane) ─────────────────────────────────
  if (layout === 'inline') {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <div
          className={`w-full max-w-[460px] rounded-xl border ${tone.cardBd} ${tone.cardBg} p-6 text-center`}
        >
          <div
            className={`mx-auto mb-3 inline-flex size-11 items-center justify-center rounded-xl border bg-card shadow-sm ${tone.iconBox}`}
          >
            <Icon className={`size-5 ${tone.icon}`} strokeWidth={1.7} />
          </div>
          <h3 className="text-[14px] font-semibold tracking-tight text-foreground">
            {m.inline.title}
          </h3>
          <p className="mx-auto mt-1.5 max-w-[360px] text-[12px] leading-relaxed text-muted-foreground">
            {m.inline.explain}
          </p>
          <ConnBlameLine mode={mode} className="mt-3 justify-center" />
          {lastSynced && <div className="mt-3 flex justify-center">{lastSynced}</div>}
          <div className="mt-4">{actions}</div>
        </div>
      </div>
    );
  }

  // ── Full screen (hero) ────────────────────────────────────────────
  return (
    <div className="flex flex-1 flex-col items-center justify-center overflow-auto bg-muted/30 px-8 py-10 text-center">
      <div className="flex w-full max-w-[560px] flex-col items-center">
        <div
          className={`mb-4 inline-flex size-14 items-center justify-center rounded-2xl border bg-card shadow-sm ${tone.iconBox}`}
        >
          <Icon className={`size-6 ${tone.icon}`} strokeWidth={1.7} />
        </div>

        <div className="flex flex-wrap items-center justify-center gap-2.5">
          <h2 className="text-[20px] font-semibold tracking-tight text-foreground">
            {m.full.headline}
          </h2>
          <ReassureBadge tone={m.reassure.tone}>{m.reassure.text}</ReassureBadge>
        </div>
        <p className="mt-2 max-w-md text-[13px] leading-relaxed text-muted-foreground">
          {m.full.explain}
        </p>

        <FaultChain mode={mode} className="mt-7 w-full max-w-[460px]" />

        {/* per-mode extra context */}
        {mode === 'github-down' && <IncidentStrip />}
        {mode === 'rate-limit' && (
          <ResetBar resetAt={rateResetAt} countdownText={countdown.text} secondsLeft={countdown.secondsLeft} />
        )}
        {mode === 'auth-expired' && (
          <AuthDiagnostic endpoint={endpoint} lastSyncedAt={lastSyncedAt} />
        )}

        {lastSynced && <div className="mt-5">{lastSynced}</div>}

        <div className="mt-5">{actions}</div>
      </div>
    </div>
  );
}

// ── Reassurance chip (the fast "whose fault" read) ──────────────────
function ReassureBadge({
  tone,
  children,
}: {
  tone: 'amber' | 'red';
  children: React.ReactNode;
}) {
  const t = CONN_TONE[tone];
  return (
    <span
      className={`inline-flex items-center whitespace-nowrap rounded-md border px-2 py-0.5 text-[11px] font-semibold ${t.cardBd} ${t.cardBg} ${t.nodeFg}`}
    >
      {children}
    </span>
  );
}

// ── Motion annotation pill (intent for future motion pass) ──────────
function MotionNote({ children }: { children: React.ReactNode }) {
  return (
    <div className="inline-flex items-center gap-1.5 whitespace-nowrap rounded-md border border-dashed border-border bg-muted/40 px-2 py-1 text-[10.5px] text-muted-foreground">
      <PlugZapIcon className="size-3" />
      <span>
        <span className="font-semibold uppercase tracking-wide">motion</span> ·{' '}
        {children}
      </span>
    </div>
  );
}

// ── github-down: incident strip ─────────────────────────────────────
// We don't fabricate an incident feed — we point the user at the source
// of truth so they can confirm in one click.
function IncidentStrip() {
  return (
    <button
      type="button"
      onClick={() =>
        window.open('https://www.githubstatus.com', '_blank', 'noopener')
      }
      className="mt-5 flex w-full max-w-[460px] items-center gap-2.5 rounded-lg border border-red-200 bg-red-50/50 px-3.5 py-2.5 text-left transition-colors hover:bg-red-50 dark:border-red-900 dark:bg-red-950/30 dark:hover:bg-red-950/50"
    >
      <GithubMark className="size-4 shrink-0 text-red-600 dark:text-red-400" />
      <span className="flex-1 text-[12px] text-red-900 dark:text-red-200">
        Check live incident details on githubstatus.com
      </span>
      <ExternalLinkIcon className="size-3.5 shrink-0 text-red-600 dark:text-red-400" />
    </button>
  );
}

// ── rate-limit: reset progress bar ──────────────────────────────────
function ResetBar({
  resetAt,
  countdownText,
  secondsLeft,
}: {
  resetAt?: Date | null;
  countdownText: string;
  secondsLeft: number;
}) {
  // The budget window is hourly; approximate elapsed fraction from how
  // much of the hour is left. Clamped to [2, 100] so the bar always reads.
  const pct = Math.min(100, Math.max(2, Math.round((1 - secondsLeft / 3600) * 100)));
  return (
    <div className="mt-5 w-full max-w-[460px] rounded-lg border border-amber-200 bg-amber-50/60 px-4 py-3 text-left dark:border-amber-900 dark:bg-amber-950/30">
      <div className="flex items-center justify-between text-[12px]">
        <span className="font-semibold text-amber-900 dark:text-amber-200">
          {resetAt ? `Budget resets at ${formatClock(resetAt)}` : 'Budget resets soon'}
        </span>
        {countdownText && (
          <span className="inline-flex items-center gap-1.5 font-mono tabular-nums text-amber-700 dark:text-amber-300">
            <ClockIcon className="size-3" /> {countdownText} left
          </span>
        )}
      </div>
      <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-amber-200 dark:bg-amber-900">
        <div className="h-full rounded-full bg-amber-500" style={{ width: `${pct}%` }} />
      </div>
      <div className="mt-2 flex items-center justify-between text-[11px] text-amber-700/80 dark:text-amber-300/70">
        <span>Hourly request budget spent</span>
        <span>per-token · GitHub REST</span>
      </div>
    </div>
  );
}

// ── auth-expired: diagnostic table ──────────────────────────────────
function AuthDiagnostic({
  endpoint,
  lastSyncedAt,
}: {
  endpoint?: string;
  lastSyncedAt?: Date | null;
}) {
  const isElectron =
    typeof window !== 'undefined' &&
    Boolean((window as { pyor?: { isElectron?: boolean } }).pyor?.isElectron);
  const rows: [string, string, boolean][] = [
    [
      'Last successful call',
      lastSyncedAt ? `${formatClock(lastSyncedAt)} · ${formatAgo(lastSyncedAt)}` : '—',
      false,
    ],
    ['Failing endpoint', endpoint ? `GET ${endpoint}` : 'GET /user', true],
    ['Response', 'HTTP 401 · Bad credentials', true],
    ['Token', isElectron ? 'Keychain' : 'Browser storage', true],
  ];
  return (
    <Card className="mt-5 w-full max-w-[460px] overflow-hidden p-0 text-left text-[12px]">
      {rows.map(([label, value, mono], i) => (
        <div
          key={label}
          className={`flex items-center gap-3 px-4 py-2 ${
            i < rows.length - 1 ? 'border-b' : ''
          }`}
        >
          <span className="w-36 shrink-0 text-muted-foreground">{label}</span>
          <span
            className={`flex-1 text-foreground ${mono ? 'font-mono text-[11.5px]' : ''}`}
          >
            {value}
          </span>
        </div>
      ))}
    </Card>
  );
}
