// ════════════════════════════════════════════════════════════════════
// FaultChain — the "whose fault is it" diagram.
//
//   Pyor ── Your network ── GitHub
//
// with the break placed on the real culprit, so the user never blames
// Pyor for an outage that isn't ours. This is the single most important
// trust device in the connectivity work. A compact one-line variant
// (<ConnBlameLine>) carries the same read where space is tight (inline).
// ════════════════════════════════════════════════════════════════════

import type { ComponentType } from 'react';
import {
  CheckIcon,
  GaugeIcon,
  MonitorIcon,
  WifiIcon,
  WifiOffIcon,
  XIcon,
} from 'lucide-react';
import { CONN_MODES, CONN_TONE, type ConnMode } from './connModes';

/** Icon shape accepted by the FaultChain nodes — lucide icons satisfy
 * it, and so does our inline GitHub mark (lucide dropped brand icons
 * from its type declarations). */
type NodeIcon = ComponentType<{ className?: string; strokeWidth?: number }>;

/** GitHub octocat mark as a filled SVG, so it survives lucide's brand-
 * icon removal. `strokeWidth` is accepted but ignored (it's a fill). */
export function GithubMark({ className }: { className?: string; strokeWidth?: number }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden className={className}>
      <path d="M12 .5C5.37.5 0 5.78 0 12.29c0 5.2 3.44 9.61 8.2 11.17.6.11.82-.25.82-.56 0-.28-.01-1.02-.02-2-3.34.71-4.04-1.6-4.04-1.6-.55-1.38-1.34-1.75-1.34-1.75-1.09-.74.08-.73.08-.73 1.2.08 1.84 1.22 1.84 1.22 1.07 1.8 2.81 1.28 3.5.98.11-.76.42-1.28.76-1.57-2.67-.3-5.47-1.31-5.47-5.83 0-1.29.47-2.34 1.23-3.17-.12-.3-.53-1.52.12-3.16 0 0 1.01-.32 3.3 1.21a11.6 11.6 0 016 0c2.28-1.53 3.29-1.21 3.29-1.21.65 1.64.24 2.86.12 3.16.77.83 1.23 1.88 1.23 3.17 0 4.53-2.81 5.52-5.49 5.81.43.37.81 1.1.81 2.22 0 1.6-.01 2.89-.01 3.28 0 .31.22.68.83.56A12.02 12.02 0 0024 12.29C24 5.78 18.63.5 12 .5z" />
    </svg>
  );
}

type NodeState = 'ok' | 'bad' | 'throttle' | 'unknown';
type LinkState = 'ok' | 'bad' | 'throttle' | 'unknown';

interface ChainCfg {
  net: NodeState;
  c1: LinkState;
  gh: NodeState;
  c2: LinkState;
}

const CHAIN: Record<ConnMode, ChainCfg> = {
  offline: { net: 'bad', c1: 'bad', gh: 'unknown', c2: 'unknown' },
  'github-down': { net: 'ok', c1: 'ok', gh: 'bad', c2: 'bad' },
  'rate-limit': { net: 'ok', c1: 'ok', gh: 'throttle', c2: 'throttle' },
  'auth-expired': { net: 'ok', c1: 'ok', gh: 'bad', c2: 'bad' },
};

const GH_LABEL: Record<ConnMode, string> = {
  offline: "Can't tell",
  'github-down': 'Outage',
  'rate-limit': 'Throttled',
  'auth-expired': 'Rejected',
};

export function FaultChain({
  mode,
  className = '',
}: {
  mode: ConnMode;
  className?: string;
}) {
  const cfg = CHAIN[mode];
  const tone = CONN_TONE[CONN_MODES[mode].tone];
  const netState =
    cfg.net === 'ok' ? 'Connected' : cfg.net === 'bad' ? 'No connection' : '—';

  return (
    <div className={`flex items-stretch justify-center ${className}`}>
      <FaultNode icon={MonitorIcon} name="Pyor" sub="Running" state="ok" tone={tone} />
      <FaultConnector state={cfg.c1} tone={tone} />
      <FaultNode
        icon={cfg.net === 'bad' ? WifiOffIcon : WifiIcon}
        name="Your network"
        sub={netState}
        state={cfg.net}
        tone={tone}
      />
      <FaultConnector state={cfg.c2} tone={tone} />
      <FaultNode
        icon={GithubMark}
        name="GitHub"
        sub={GH_LABEL[mode]}
        state={cfg.gh}
        tone={tone}
      />
    </div>
  );
}

function FaultNode({
  icon: Icon,
  name,
  sub,
  state,
  tone,
}: {
  icon: NodeIcon;
  name: string;
  sub: string;
  state: NodeState;
  tone: (typeof CONN_TONE)[keyof typeof CONN_TONE];
}) {
  const ok = state === 'ok';
  const unknown = state === 'unknown';
  const box = ok
    ? 'border-emerald-200 bg-card dark:border-emerald-900'
    : unknown
      ? 'border-dashed border-border bg-muted/40'
      : `border-transparent bg-card ring-2 ${tone.nodeRing}`;
  const iconC = ok
    ? 'text-emerald-600 dark:text-emerald-400'
    : unknown
      ? 'text-muted-foreground'
      : tone.icon;
  const subC = ok
    ? 'text-emerald-600 dark:text-emerald-400'
    : unknown
      ? 'text-muted-foreground'
      : tone.nodeFg;
  const badgeBg = ok
    ? 'bg-emerald-500'
    : unknown
      ? 'bg-muted-foreground/50'
      : tone.dot;
  return (
    <div
      className={`relative flex w-[124px] flex-col items-center gap-1 rounded-lg border px-3 py-3 text-center shadow-sm ${box}`}
    >
      <span
        className={`absolute -right-1.5 -top-1.5 inline-flex size-4 items-center justify-center rounded-full text-white ${badgeBg}`}
      >
        {ok ? (
          <CheckIcon className="size-3" />
        ) : unknown ? (
          <span className="text-[11px] leading-none">?</span>
        ) : (
          <XIcon className="size-3" />
        )}
      </span>
      <Icon className={`size-5 ${iconC}`} strokeWidth={1.8} />
      <div className="text-[12px] font-semibold leading-none text-foreground">
        {name}
      </div>
      <div className={`text-[10.5px] font-medium leading-none ${subC}`}>{sub}</div>
    </div>
  );
}

function FaultConnector({
  state,
  tone,
}: {
  state: LinkState;
  tone: (typeof CONN_TONE)[keyof typeof CONN_TONE];
}) {
  const ok = state === 'ok';
  const unknown = state === 'unknown';
  const lineC = ok
    ? 'border-emerald-300 dark:border-emerald-800'
    : unknown
      ? 'border-border'
      : tone.line;
  return (
    <div className="relative flex min-w-[34px] flex-1 items-center">
      <div
        className={`w-full border-t-2 ${ok ? '' : 'border-dashed'} ${lineC}`}
      />
      {state === 'bad' && (
        <span
          className={`absolute left-1/2 top-1/2 inline-flex size-4 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full text-white ${tone.dot}`}
        >
          <XIcon className="size-2.5" />
        </span>
      )}
      {state === 'throttle' && (
        <span
          className={`absolute left-1/2 top-1/2 inline-flex size-4 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full text-white ${tone.dot}`}
        >
          <GaugeIcon className="size-2.5" />
        </span>
      )}
    </div>
  );
}

// ── Compact one-line blame read (inline + anywhere tight) ───────────
const BLAME: Record<ConnMode, [string, NodeState][]> = {
  offline: [
    ['Pyor', 'ok'],
    ['Network', 'bad'],
    ['GitHub', 'unknown'],
  ],
  'github-down': [
    ['Pyor', 'ok'],
    ['Network', 'ok'],
    ['GitHub', 'bad'],
  ],
  'rate-limit': [
    ['Pyor', 'ok'],
    ['Network', 'ok'],
    ['GitHub', 'throttle'],
  ],
  'auth-expired': [
    ['Pyor', 'ok'],
    ['Network', 'ok'],
    ['GitHub', 'bad'],
  ],
};

export function ConnBlameLine({
  mode,
  className = '',
}: {
  mode: ConnMode;
  className?: string;
}) {
  const tone = CONN_TONE[CONN_MODES[mode].tone];
  return (
    <div
      className={`inline-flex items-center gap-2 text-[11.5px] font-medium ${className}`}
    >
      {BLAME[mode].map(([label, st], i) => {
        const c =
          st === 'ok'
            ? 'text-emerald-600 dark:text-emerald-400'
            : st === 'unknown'
              ? 'text-muted-foreground'
              : tone.nodeFg;
        return (
          <span key={label} className="inline-flex items-center gap-2">
            {i > 0 && <span className="text-border">·</span>}
            <span className={`inline-flex items-center gap-1 ${c}`}>
              {st === 'ok' ? (
                <CheckIcon className="size-3" />
              ) : st === 'unknown' ? (
                <span className="leading-none">?</span>
              ) : (
                <XIcon className="size-3" />
              )}
              {label}
            </span>
          </span>
        );
      })}
    </div>
  );
}
