// lineDiffOverlay — char-level intra-line diff ranges for the inline
// code snippets (review-thread diff_hunks + Inbox comment snippets).
//
// The Files-tab CodeView paints the *differing portion* of a changed
// line — the words that actually changed between the `-` and `+`
// versions get a stronger background than the rest of the row. That
// emphasis is what makes a one-character rename legible in a 120-char
// line. The snippets only had token colors (no intra-line overlay),
// so this module reproduces CodeView's behaviour for them.
//
// It is a faithful port of @pierre/diffs' internal
// `computeLineDiffDecorations` (dist/utils/renderDiffWithHighlighter.js):
// same `diffWordsWithSpace` / `diffChars` split keyed off the user's
// `lineDiffStyle`, same `word-alt` span-joining heuristic (merge
// adjacent same-kind spans + absorb single-char neutral gaps into a
// surrounding change). Keeping the algorithm identical means the
// snippet emphasis lands on exactly the same characters the Files tab
// highlights for the same pair of lines.
//
// Why port instead of calling the lib: the lib's routine is internal
// and operates on its `FileDiffMetadata` split-view model + emits HAST
// decorations for its shadow-DOM renderer. Our snippets render plain
// React spans over Shiki tokens, so we need character ranges, not
// HAST. The shared primitive that mattered (the highlighter) is
// already reused via useDiffSnippetHighlight; this is the small piece
// the lib doesn't expose.

import { diffChars, diffWordsWithSpace, type Change } from 'diff';
import type { LineDiffStyle } from '../changes/diffPreferences';

/** Half-open `[start, end)` character range within a single line. */
export interface CharRange {
  start: number;
  end: number;
}

/** Mirror of the lib's `maxLineDiffLength` guard — past this the
 * word-diff cost isn't worth it and the overlay adds noise on
 * minified / generated lines. The lib defaults to 1000. */
const MAX_LINE_DIFF_LENGTH = 1000;

// A span the diff is bucketed into: `[changed, text]` where changed
// is 1 for an added/removed run and 0 for a neutral (unchanged) run.
type Span = [0 | 1, string];

/** Port of the lib's `pushOrJoinSpan`. With `enableJoin` (word-alt)
 * it merges a run into the previous span when they share kind, and
 * also folds a single-character neutral run into a preceding change
 * so a lone unchanged char doesn't visually fracture a highlight.
 * Without join (word / char) every run becomes its own span. */
function pushOrJoin(
  arr: Span[],
  value: string,
  isNeutral: boolean,
  enableJoin: boolean,
  isLast: boolean,
): void {
  const last = arr[arr.length - 1];
  if (last == null || isLast || !enableJoin) {
    arr.push([isNeutral ? 0 : 1, value]);
    return;
  }
  const isLastNeutral = last[0] === 0;
  if (
    isNeutral === isLastNeutral ||
    (isNeutral && value.length === 1 && !isLastNeutral)
  ) {
    last[1] += value;
    return;
  }
  arr.push([isNeutral ? 0 : 1, value]);
}

/** Walk bucketed spans, emitting a CharRange for every changed span at
 * its running character offset. */
function spansToRanges(spans: Span[]): CharRange[] {
  const ranges: CharRange[] = [];
  let idx = 0;
  for (const [changed, value] of spans) {
    if (changed === 1) ranges.push({ start: idx, end: idx + value.length });
    idx += value.length;
  }
  return ranges;
}

/** Compute the changed character ranges on the deletion side and the
 * addition side of one `-`/`+` line pair. Returns empty ranges for
 * `none`, for over-long lines, or when the two lines share no
 * common substring worth emphasising. */
function computeChangedRanges(
  delText: string,
  addText: string,
  style: LineDiffStyle,
): { del: CharRange[]; add: CharRange[] } {
  if (style === 'none') return { del: [], add: [] };
  if (
    delText.length > MAX_LINE_DIFF_LENGTH ||
    addText.length > MAX_LINE_DIFF_LENGTH
  ) {
    return { del: [], add: [] };
  }

  const parts: Change[] =
    style === 'char'
      ? diffChars(delText, addText)
      : diffWordsWithSpace(delText, addText);
  const enableJoin = style === 'word-alt';
  const delSpans: Span[] = [];
  const addSpans: Span[] = [];
  const lastPart = parts[parts.length - 1];

  for (const part of parts) {
    const isLast = part === lastPart;
    if (!part.added && !part.removed) {
      pushOrJoin(delSpans, part.value, true, enableJoin, isLast);
      pushOrJoin(addSpans, part.value, true, enableJoin, isLast);
    } else if (part.removed) {
      pushOrJoin(delSpans, part.value, false, enableJoin, isLast);
    } else {
      pushOrJoin(addSpans, part.value, false, enableJoin, isLast);
    }
  }

  return { del: spansToRanges(delSpans), add: spansToRanges(addSpans) };
}

/** Minimal view of a snippet row the overlay needs: whether it's an
 * addition / deletion / neither, and its text. Callers map their own
 * row type onto this. */
export interface OverlayRow {
  kind: 'add' | 'del' | 'other';
  text: string;
}

/** Build a row-index → changed-ranges map for a top-to-bottom list of
 * snippet rows. Mirrors the Files-tab's split-view pairing: within a
 * contiguous change group (a run of only `-`/`+` rows, deletions
 * first then additions, the shape GitHub emits) the k-th deletion is
 * paired with the k-th addition. Pure additions / deletions (no
 * counterpart) and context rows get no overlay. */
export function buildChangeRangeMap(
  rows: ReadonlyArray<OverlayRow>,
  style: LineDiffStyle,
): Map<number, CharRange[]> {
  const map = new Map<number, CharRange[]>();
  if (style === 'none') return map;

  let i = 0;
  while (i < rows.length) {
    if (rows[i].kind === 'other') {
      i++;
      continue;
    }
    // Collect the maximal run of change rows (add/del).
    const dels: number[] = [];
    const adds: number[] = [];
    let j = i;
    while (j < rows.length && rows[j].kind !== 'other') {
      if (rows[j].kind === 'del') dels.push(j);
      else adds.push(j);
      j++;
    }
    const pairs = Math.min(dels.length, adds.length);
    for (let k = 0; k < pairs; k++) {
      const delIdx = dels[k];
      const addIdx = adds[k];
      const { del, add } = computeChangedRanges(
        rows[delIdx].text,
        rows[addIdx].text,
        style,
      );
      if (del.length > 0) map.set(delIdx, del);
      if (add.length > 0) map.set(addIdx, add);
    }
    i = j;
  }
  return map;
}

/** A piece of a token after splitting at change boundaries: the text,
 * the token's Shiki color, and whether it falls inside a changed
 * range (callers paint emphasis on `changed` pieces). */
export interface OverlaySegment {
  text: string;
  color?: string;
  changed: boolean;
}

/** Split one line's Shiki tokens into segments at the boundaries of
 * `ranges`, preserving each token's color. A token that straddles a
 * range boundary is cut so the changed portion can be emphasised
 * independently. `ranges` must be sorted, non-overlapping, in line
 * character coordinates. Returns one segment per maximal same-state
 * run; callers render each as a span. */
export function splitTokensByRanges(
  tokens: ReadonlyArray<{ content: string; color?: string }>,
  ranges: ReadonlyArray<CharRange>,
): OverlaySegment[] {
  if (ranges.length === 0) {
    return tokens.map((t) => ({
      text: t.content,
      color: t.color,
      changed: false,
    }));
  }
  const segs: OverlaySegment[] = [];
  let offset = 0; // absolute char offset of the current token start
  for (const token of tokens) {
    const { content, color } = token;
    let pos = 0; // index within this token
    while (pos < content.length) {
      const abs = offset + pos;
      const inRange = ranges.find((r) => abs >= r.start && abs < r.end);
      if (inRange) {
        const end = Math.min(content.length, inRange.end - offset);
        segs.push({ text: content.slice(pos, end), color, changed: true });
        pos = end;
      } else {
        const next = ranges.find((r) => r.start > abs);
        const nextStart = next ? next.start - offset : content.length;
        const end = Math.min(content.length, nextStart);
        segs.push({ text: content.slice(pos, end), color, changed: false });
        pos = end;
      }
    }
    offset += content.length;
  }
  return segs;
}
