// Persisted scroll/UI spots. localStorage-backed (same store the rest
// of the v1 app uses; ADR 0007 carries Electron-side safeStorage).
//
// Since AFK plan 26 the URL — not this blob — owns route *identity*
// (which screen, which PR, which tab/diff/commit-filter). This store
// is now scoped to the ephemeral scroll positions that aren't part of
// a shareable URL: the per-PR file/scroll `spots` map and the Inbox
// Comments-tab `commentsScrollIndex`. The legacy `pyor:route` blob
// (which also carried the route) is read once on boot by
// `migrateLegacyRoute()` to redirect returning users, then left
// alone (the spot/inbox helpers keep writing into the same key so
// nothing is lost).

import type { PRTab } from '../pr/PRTabs';

const KEY = 'pyor:route';

export interface PersistedPRSpot {
  /** Path of the file the user was viewing — restored as the
   * scroll target on mount. */
  currentPath?: string | null;
  /** Scroll offset within the file (px), captured periodically while
   * the diff is scrolled. Optional — scrolling to the file alone is
   * 80% of the value. */
  scrollTop?: number;
  /** Scroll offset (px) of the Conversation timeline column, captured
   * (debounced) while it's scrolled and restored on mount. Survives a
   * page reload so returning to a PR lands where you left the
   * discussion. */
  conversationScrollTop?: number;
  /** Topmost visible commit-row index in the Commits tab's virtual
   * list. Persisted on scroll and restored via Virtuoso's
   * `initialTopMostItemIndex` (index-based, mirroring the Inbox
   * Comments list — robust to row-height estimation on remount). */
  commitsScrollIndex?: number;
  /** Measured row heights for the Conversation timeline's Virtuoso list,
   * captured (debounced) while scrolling and seeded back via
   * `restoreStateFrom` on remount so the first bottom-up scroll doesn't
   * re-measure-and-jump. `sig` is a hash of the list's item-key order —
   * the `ranges` are index-based, so a changed timeline (new comment,
   * focus toggled) no longer matches and the stale heights are dropped
   * rather than landing on the wrong rows. */
  conversationSnapshot?: ConversationListSnapshot;
}

/** Persisted Virtuoso size cache for the Conversation timeline. Shape
 * mirrors react-virtuoso's `StateSnapshot.ranges` (kept as a plain type
 * here so the store stays free of the library import). */
export interface ConversationListSnapshot {
  /** Hash of the ordered item keys at capture time — restore only seeds
   * the heights when the current list hashes identically. */
  sig: string;
  /** Coalesced contiguous size ranges (Virtuoso merges equal-height
   * neighbours, so this stays compact — not one entry per row). */
  ranges: { startIndex: number; endIndex: number; size: number }[];
}

/** Deep-link anchor inside a PR route. Set when the user opens a PR
 * from the Inbox · Comments tab — the Files tab scrolls to and
 * flash-highlights the matching thread on mount. Persisted alongside
 * the route so a reload after the cold-link still lands on the
 * thread (the user's mental model is "the URL points to this
 * thread", not "this PR"). */
interface PRAnchor {
  path: string;
  line?: number | null;
  /** Which diff column the line lives on. RIGHT = additions (new
   * file), LEFT = deletions (original file). Needed because in
   * split-view both sides render their own `[data-line="N"]`, and
   * scrolling to the wrong one lands the user on the opposite side
   * of the diff. */
  diffSide?: 'LEFT' | 'RIGHT' | null;
  commentId?: string;
}

/** Active tab + scroll spot inside the Inbox screen. Persisted so
 * that navigating to a PR detail and coming back lands on the same
 * tab the user was on, scrolled to the same row. Stored at the
 * route level rather than as component-local state because the
 * NotificationsScreen unmounts every time the route changes. */
export interface InboxSpot {
  /** Index of the topmost visible row in the comments feed's virtual
   * list. Restored via Virtuoso's `initialTopMostItemIndex`. */
  commentsScrollIndex?: number;
}

interface PersistedRoute {
  kind:
    | 'setup'
    | 'inbox'
    | 'pulls'
    | 'pr'
    | 'settings'
    | 'local'
    /** Local pre-PR review surface (the per-review detail page).
     * `'local'` stays the list page; this is the row-detail kind. */
    | 'local-review';
  owner?: string;
  repo?: string;
  number?: number;
  /** Active tab in the PR view. */
  tab?: PRTab;
  /** Comments-tab → PR-detail deep-link anchor. */
  anchor?: PRAnchor;
  /** Local-review surface id — paired with `kind: 'local-review'`. */
  reviewId?: string;
  /** Per-PR spot map keyed by `owner/repo/number`. Lets us remember
   * the file + scroll for *every* PR you've recently opened, not
   * just the active one. */
  spots?: Record<string, PersistedPRSpot>;
  /** Inbox-side preserved state (active tab + scroll position). */
  inbox?: InboxSpot;
}

function loadRoute(): PersistedRoute | null {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as PersistedRoute;
    if (
      parsed.kind !== 'setup' &&
      parsed.kind !== 'inbox' &&
      parsed.kind !== 'pulls' &&
      parsed.kind !== 'pr' &&
      parsed.kind !== 'settings' &&
      parsed.kind !== 'local' &&
      parsed.kind !== 'local-review'
    ) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

function saveRoute(route: PersistedRoute): void {
  try {
    // Preserve cross-route state (spots map, inbox spot) even when
    // the route shape changes (e.g. inbox → pr → inbox) so we don't
    // lose history. Without this, every saveRoute({kind:'inbox'})
    // from App.tsx would wipe out inbox.tab and the scroll index.
    const prior = loadRoute();
    const next: PersistedRoute = {
      ...route,
      spots: { ...(prior?.spots ?? {}), ...(route.spots ?? {}) },
      inbox: { ...(prior?.inbox ?? {}), ...(route.inbox ?? {}) },
    };
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch {
    // ignore — same-shape failure handling as the other stores
  }
}

function clearRoute(): void {
  try {
    localStorage.removeItem(KEY);
  } catch {
    // ignore
  }
}

function spotKey(owner: string, repo: string, number: number): string {
  return `${owner}/${repo}/${number}`;
}

/** Read the saved spot for a specific PR; returns an empty record if
 * none. */
export function getSpot(
  owner: string,
  repo: string,
  number: number,
): PersistedPRSpot {
  return loadRoute()?.spots?.[spotKey(owner, repo, number)] ?? {};
}

/** Merge-update a PR's spot. Keeps every other PR's spot untouched. */
export function saveSpot(
  owner: string,
  repo: string,
  number: number,
  patch: PersistedPRSpot,
): void {
  try {
    const prior = loadRoute() ?? { kind: 'pr' as const };
    const key = spotKey(owner, repo, number);
    const merged: PersistedRoute = {
      ...prior,
      spots: {
        ...(prior.spots ?? {}),
        [key]: { ...(prior.spots?.[key] ?? {}), ...patch },
      },
    };
    localStorage.setItem(KEY, JSON.stringify(merged));
  } catch {
    // ignore
  }
}

/** Read the persisted inbox spot (active tab + scroll position). */
export function getInbox(): InboxSpot {
  return loadRoute()?.inbox ?? {};
}

/** Merge-update the inbox spot. Caller passes a partial patch (e.g.
 * just `{tab: 'comments'}` or `{commentsScrollIndex: 42}`). */
export function saveInbox(patch: InboxSpot): void {
  try {
    const prior = loadRoute() ?? { kind: 'inbox' as const };
    const merged: PersistedRoute = {
      ...prior,
      inbox: { ...(prior.inbox ?? {}), ...patch },
    };
    localStorage.setItem(KEY, JSON.stringify(merged));
  } catch {
    // ignore
  }
}

/** A router-navigable target derived from the legacy `pyor:route`
 * blob — `{ to, params?, search? }` shaped for TanStack's `redirect`. */
interface LegacyRouteTarget {
  to: string;
  params?: Record<string, string>;
  search?: Record<string, string>;
}

/** One-time boot migration (AFK plan 26).
 *
 * Returning users from the pre-router build have their last screen in
 * the `pyor:route` localStorage blob but no URL hash (the old build
 * never wrote one). Translate the persisted `kind` into the equivalent
 * router target so the index route can `redirect` them back to where
 * they left off. View-state like the inbox/PR tab is carried across.
 *
 * Returns `null` when there's nothing to migrate (no blob, or a kind
 * that maps to the default inbox) so the caller can fall through to the
 * normal `/inbox` redirect. The blob itself is NOT cleared — the
 * spots/inbox helpers keep using the same key for scroll state.
 */
function legacyRouteTarget(): LegacyRouteTarget | null {
  try {
    const persisted = loadRoute();
    if (!persisted) return null;
    switch (persisted.kind) {
      case 'pr':
        if (persisted.owner && persisted.repo && persisted.number) {
          return {
            to: '/$owner/$repo/$number',
            params: {
              owner: persisted.owner,
              repo: persisted.repo,
              number: String(persisted.number),
            },
            search:
              persisted.tab && persisted.tab !== 'description'
                ? { tab: persisted.tab }
                : undefined,
          };
        }
        return null;
      case 'local-review':
        return persisted.reviewId
          ? { to: '/local/$reviewId', params: { reviewId: persisted.reviewId } }
          : null;
      case 'pulls':
        return { to: '/pulls' };
      case 'local':
        return { to: '/local' };
      case 'settings':
        return { to: '/settings' };
      case 'inbox':
        // Inbox is a single comments-only dashboard now — no tab to
        // restore. Server filters live in the URL via the route schema.
        return { to: '/inbox' };
      // 'setup' is never persisted; nothing to migrate.
      default:
        return null;
    }
  } catch {
    return null;
  }
}
