// A single teammate-PR row + its bucket header. The hero affordance on
// every row is the one-click review action, which varies by bucket.

import {
  AlertTriangleIcon,
  ExternalLinkIcon,
  EyeIcon,
  GitPullRequestIcon,
  Loader2Icon,
  UserPlusIcon,
  UsersIcon,
  type LucideIcon,
} from 'lucide-react';
import { Link } from '@tanstack/react-router';
import { Icon, type IconName } from '../../ui/Icon';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { waitTone, type TeamBucket, type TeamOrg, type TeamPR } from '../../github/teamLens';
import { OrgGlyph, ReviewerCluster, TeamAvatar } from './TeamBits';
import type { prLinkProps } from '../../router/nav';

const HEADER_ICON: Record<TeamBucket['id'], LucideIcon> = {
  needs: AlertTriangleIcon,
  yours: EyeIcon,
  team: UsersIcon,
  moving: GitPullRequestIcon,
};

const ACCENT_TINT: Record<TeamBucket['accent'], string> = {
  amber: 'text-amber-600',
  blue: 'text-blue-600',
  zinc: 'text-muted-foreground',
};

const ACCENT_BAR: Record<TeamBucket['accent'], string> = {
  amber: 'bg-amber-400',
  blue: 'bg-blue-500',
  zinc: 'bg-transparent',
};

// Per-status icon (+ tint) and badge styling — mirrors the Pulls list.
const STATUS_META: Record<
  TeamPR['status'],
  { icon: IconName; color: string; badgeClass: string; destructive?: boolean }
> = {
  open: {
    icon: 'pr-open',
    color: 'text-pyor-pass',
    badgeClass:
      'border-emerald-200 bg-emerald-100 text-emerald-700 dark:border-emerald-900 dark:bg-emerald-900/40 dark:text-emerald-300',
  },
  draft: { icon: 'pr-draft', color: 'text-muted-foreground', badgeClass: '' },
  merged: {
    icon: 'pr-merged',
    color: 'text-purple-600 dark:text-purple-400',
    badgeClass:
      'border-purple-200 bg-purple-100 text-purple-700 dark:border-purple-900 dark:bg-purple-900/40 dark:text-purple-300',
  },
  closed: { icon: 'pr-closed', color: 'text-pyor-fail', badgeClass: '', destructive: true },
};

function StatusBadge({ status }: { status: TeamPR['status'] }) {
  const m = STATUS_META[status];
  return (
    <Badge
      variant={m.destructive ? 'destructive' : 'secondary'}
      className={cn('px-1.5 py-0 text-[10px]', m.badgeClass)}
    >
      {status}
    </Badge>
  );
}

export function TeamBucketHeader({
  bucket,
  count,
}: {
  bucket: TeamBucket;
  count: number;
}) {
  const HeaderIcon = HEADER_ICON[bucket.id];
  return (
    <div className="flex items-center gap-2.5 border-b border-border bg-muted px-5 py-2">
      <HeaderIcon className={cn('size-3.5', ACCENT_TINT[bucket.accent])} />
      <span className="text-[12.5px] font-semibold text-foreground">{bucket.title}</span>
      <Badge variant="secondary" className="tabular-nums px-1.5 py-0 text-[10px]">
        {count}
      </Badge>
      <span className="text-[11.5px] text-muted-foreground">· {bucket.why}</span>
    </div>
  );
}

export function TeamRadarRow({
  pr,
  bucket,
  org,
  you,
  busy,
  linkProps,
  onOpen,
  onAddMe,
}: {
  pr: TeamPR;
  bucket: TeamBucket;
  org: TeamOrg | undefined;
  you: string;
  busy: boolean;
  linkProps: ReturnType<typeof prLinkProps>;
  onOpen: () => void;
  onAddMe: () => void;
}) {
  const tone = waitTone(pr.waiting);
  const statusMeta = STATUS_META[pr.status];

  return (
    <div className="group relative flex items-center gap-3 border-b border-border/60 px-5 py-3 hover:bg-accent/50">
      <Link
        {...linkProps}
        aria-label={`PR #${pr.num}: ${pr.title}`}
        className="absolute inset-0 z-0 cursor-pointer"
      />
      <span className={cn('pointer-events-none absolute left-0 top-0 h-full w-0.5', ACCENT_BAR[bucket.accent])} />
      <span className={cn('shrink-0', statusMeta.color)}>
        <Icon name={statusMeta.icon} size={16} />
      </span>

      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <StatusBadge status={pr.status} />
          <span
            className="truncate text-[13.5px] font-semibold tracking-tight text-foreground"
            style={{ maxWidth: 460 }}
          >
            {pr.title}
          </span>
          {pr.checks.f > 0 && (
            <Badge variant="destructive" className="px-1.5 py-0 text-[10px]">
              {pr.checks.f} failing
            </Badge>
          )}
        </div>
        <div className="mt-1 flex items-center gap-2 text-[12px] text-muted-foreground">
          <span className="font-mono text-[11px] text-muted-foreground/70">#{pr.num}</span>
          <span className="text-muted-foreground/40">·</span>
          <OrgGlyph org={org} className="size-4" text="text-[7px]" />
          <span className="font-medium text-foreground/80">{pr.repo}</span>
          <span className="text-muted-foreground/40">·</span>
          <span className="inline-flex items-center gap-1.5">
            <TeamAvatar login={pr.author} url={pr.authorAvatarUrl} className="size-4" />
            {pr.author}
          </span>
        </div>
      </div>

      {/* Waiting / staleness */}
      <div className="hidden w-[120px] shrink-0 flex-col items-start gap-0.5 md:flex">
        <span className={cn('inline-flex items-center gap-1.5 text-[11.5px] font-medium', tone.text)}>
          <span className={cn('size-1.5 rounded-full', tone.dot)} />
          waiting {pr.waiting}
        </span>
        <span className="text-[10.5px] text-muted-foreground/70">opened {pr.opened}</span>
      </div>

      {/* Who it's on */}
      <div className="relative z-10 hidden w-[112px] shrink-0 items-center md:flex">
        {pr.reviewers.length === 0 ? (
          <span className="inline-flex items-center gap-1.5 rounded-full border border-dashed border-input px-2 py-0.5 text-[10.5px] text-muted-foreground">
            <UserPlusIcon className="size-3" />
            unassigned
          </span>
        ) : (
          <ReviewerCluster reviewers={pr.reviewers} you={you} />
        )}
      </div>

      <div className="relative z-10 shrink-0">
        <RowAction
          bucketId={bucket.id}
          busy={busy}
          canManage={pr.canManage}
          githubUrl={`https://github.com/${pr.owner}/${pr.repoName}/pull/${pr.num}`}
          onOpen={onOpen}
          onAddMe={onAddMe}
        />
      </div>
    </div>
  );
}

function RowAction({
  bucketId,
  busy,
  canManage,
  githubUrl,
  onOpen,
  onAddMe,
}: {
  bucketId: TeamBucket['id'];
  busy: boolean;
  canManage: boolean;
  githubUrl: string;
  onOpen: () => void;
  onAddMe: () => void;
}) {
  // "Add me" only works with WRITE+ on the PR's repo — GitHub returns
  // 403 otherwise. Without it, degrade to a GitHub link (where the
  // viewer can still request via the github.com UI) instead of firing
  // a doomed request.
  const addMe = (label: string, variant: 'default' | 'outline') => {
    if (!canManage) {
      return (
        <Button asChild variant="outline" size="xs">
          <a
            href={githubUrl}
            target="_blank"
            rel="noopener noreferrer"
            title="You don't have write access to this repo — request a reviewer on GitHub"
          >
            <ExternalLinkIcon />
            On GitHub
          </a>
        </Button>
      );
    }
    return (
      <Button variant={variant} size="xs" onClick={onAddMe} disabled={busy}>
        {busy ? <Loader2Icon className="animate-spin" /> : <UserPlusIcon />}
        {label}
      </Button>
    );
  };

  if (bucketId === 'needs') return addMe('Add me as reviewer', 'default');
  if (bucketId === 'team') return addMe('Add me', 'outline');
  if (bucketId === 'yours') {
    return (
      <Button size="xs" onClick={onOpen}>
        <EyeIcon />
        Start review
      </Button>
    );
  }
  return (
    <Button variant="outline" size="xs" onClick={onOpen}>
      Open
    </Button>
  );
}
