// Persisted composer drafts — so an unsent comment/reply/note survives a
// page reload instead of being lost. localStorage-backed single-key map
// (same pattern as conversationFocusStore's `pyor:conv-focus`), keyed by
// a caller-supplied stable draft id built from PR coordinates plus the
// thread / comment / file-line anchor. Entries auto-expire after 30 days
// so abandoned drafts don't accumulate in storage.
//
// Best-effort by design: every access is wrapped so quota errors or
// private-mode (no localStorage) degrade to "no draft", never throw into
// the composer's render/keystroke path.

const KEY = 'pyor:composer-drafts';
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

interface DraftEntry {
  text: string;
  /** Last-write epoch ms — drives expiry pruning. */
  ts: number;
}

type DraftMap = Record<string, DraftEntry>;

function read(): DraftMap {
  try {
    const raw = localStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as DraftMap) : {};
  } catch {
    return {};
  }
}

function write(map: DraftMap): void {
  try {
    localStorage.setItem(KEY, JSON.stringify(map));
  } catch {
    // quota exceeded / storage unavailable — drafts are non-essential
  }
}

/** Drop entries older than MAX_AGE_MS. Pure — returns a fresh map. */
function prune(map: DraftMap, now: number): DraftMap {
  return Object.fromEntries(
    Object.entries(map).filter(([, entry]) => now - entry.ts < MAX_AGE_MS),
  );
}

/** The saved draft text for `key`, or undefined if none (or empty). */
export function getDraft(key: string): string | undefined {
  return read()[key]?.text || undefined;
}

/** Save (or, when `text` is blank, clear) the draft for `key`. */
export function saveDraft(key: string, text: string): void {
  const now = Date.now();
  const map = prune(read(), now);
  const blank = text.trim().length === 0;
  delete map[key];
  write(blank ? map : { ...map, [key]: { text, ts: now } });
}

/** Remove the draft for `key` (e.g. after a successful submit). */
export function clearDraft(key: string): void {
  const map = read();
  delete map[key];
  write(map);
}
