// DOM <-> source-coordinate mapping for symbol navigation, against the
// @pierre/diffs shadow DOM. Verified live: a [data-content] line's textContent
// equals the source line exactly (no +/- marker prefix), so columns are a plain
// text-node walk. caretRangeFromPoint does NOT pierce the shadow root, so the
// click column is measured per-character against clientX instead.

export type DiffSide = 'additions' | 'deletions';

export interface HitTarget {
  container: HTMLElement; // the <diffs-container> host
  path: string;
  side: DiffSide;
  row: number; // 0-based (tree-sitter)
  column: number; // 0-based
}

/** All <diffs-container> hosts currently in the document. */
export function diffContainers(): HTMLElement[] {
  return Array.from(document.querySelectorAll<HTMLElement>('diffs-container'));
}

export function titleOf(container: HTMLElement): string | null {
  return container.shadowRoot?.querySelector('[data-title]')?.textContent?.trim() ?? null;
}

export function containerForPath(path: string): HTMLElement | null {
  return diffContainers().find((c) => titleOf(c) === path) ?? null;
}

/** The [data-line="N"] code row (inside [data-content]) for a side. */
export function lineEl(
  container: HTMLElement,
  side: DiffSide,
  row0: number,
): HTMLElement | null {
  const root = container.shadowRoot;
  if (!root) return null;
  return root.querySelector<HTMLElement>(
    `[data-${side}] [data-content] [data-line="${row0 + 1}"]`,
  );
}

/** Build a Range spanning [startCol, endCol) within a code line, across the
 * line's (possibly many) text nodes. Null if the columns fall outside. */
export function rangeWithinLine(
  line: HTMLElement,
  startCol: number,
  endCol: number,
): Range | null {
  const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT);
  let acc = 0;
  let startNode: Text | null = null;
  let startOff = 0;
  let endNode: Text | null = null;
  let endOff = 0;
  let n = walker.nextNode() as Text | null;
  while (n) {
    const len = n.length;
    if (startNode === null && startCol < acc + len) {
      startNode = n;
      startOff = startCol - acc;
    }
    if (endCol <= acc + len) {
      endNode = n;
      endOff = endCol - acc;
      break;
    }
    acc += len;
    n = walker.nextNode() as Text | null;
  }
  if (!startNode || !endNode) return null;
  const r = document.createRange();
  r.setStart(startNode, startOff);
  r.setEnd(endNode, endOff);
  return r;
}

/** Nearest scrollable ancestor of the diff container (the CodeView viewport). */
export function diffScroller(container: HTMLElement): HTMLElement | null {
  let el: HTMLElement | null = container.parentElement;
  while (el) {
    const s = getComputedStyle(el);
    if ((s.overflowY === 'auto' || s.overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 4) {
      return el;
    }
    el = el.parentElement;
  }
  return null;
}

/** Viewport rect of an occurrence (for anchoring the chip), or null. */
export function occurrenceRect(
  container: HTMLElement,
  side: DiffSide,
  row0: number,
  startCol: number,
  endCol: number,
): DOMRect | null {
  const line = lineEl(container, side, row0);
  if (!line) return null;
  const r = rangeWithinLine(line, startCol, endCol);
  return r ? r.getBoundingClientRect() : null;
}

/** Range covering a whole line's code text (for the go-to-def flash highlight),
 * or null if the line isn't rendered. */
export function lineFlashRange(
  container: HTMLElement,
  side: DiffSide,
  row0: number,
): Range | null {
  const line = lineEl(container, side, row0);
  if (!line) return null;
  const len = (line.textContent ?? '').length;
  if (len === 0) return null;
  return rangeWithinLine(line, 0, len);
}

/** Character (text node + offset) under clientX/clientY within an element. */
function charAtPoint(el: Element, x: number, y: number): { node: Text; offset: number } | null {
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  let n = walker.nextNode() as Text | null;
  const r = document.createRange();
  while (n) {
    for (let i = 0; i < n.length; i++) {
      r.setStart(n, i);
      r.setEnd(n, i + 1);
      const rect = r.getBoundingClientRect();
      if (x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom) {
        return { node: n, offset: i };
      }
    }
    n = walker.nextNode() as Text | null;
  }
  return null;
}

/** Column (0-based) of (node, offset) within its code line. */
function columnOf(line: HTMLElement, node: Node, offset: number): number {
  const r = document.createRange();
  r.setStart(line, 0);
  r.setEnd(node, offset);
  return r.toString().length;
}

/** Minimal event shape hitTest needs. composedPath() must be captured
 * synchronously by the caller — it returns [] once dispatch has finished. */
export interface PointerSnapshot {
  composedPath(): EventTarget[];
  clientX: number;
  clientY: number;
}

/** Map a pointer event to a source coordinate, or null if not on a code token. */
export function hitTest(e: PointerSnapshot): HitTarget | null {
  const path = e.composedPath();
  let line: HTMLElement | null = null;
  let sideEl: HTMLElement | null = null;
  let container: HTMLElement | null = null;
  for (const t of path) {
    if (!(t instanceof HTMLElement)) continue;
    if (!line && t.hasAttribute('data-line') && t.closest('[data-content]')) line = t;
    if (!sideEl && (t.hasAttribute('data-additions') || t.hasAttribute('data-deletions')))
      sideEl = t;
    if (t.tagName === 'DIFFS-CONTAINER') container = t;
  }
  if (!line || !sideEl) return null;
  if (!container) {
    const root = line.getRootNode();
    container = root instanceof ShadowRoot ? (root.host as HTMLElement) : null;
  }
  if (!container) return null;
  const title = titleOf(container);
  if (!title) return null;
  const side: DiffSide = sideEl.hasAttribute('data-additions') ? 'additions' : 'deletions';
  const row = parseInt(line.getAttribute('data-line') ?? '', 10) - 1;
  if (Number.isNaN(row)) return null;

  const hit = charAtPoint(line, e.clientX, e.clientY);
  if (!hit) return null;
  const column = columnOf(line, hit.node, hit.offset);
  return { container, path: title, side, row, column };
}
