// Floating jump-to-top/bottom widget. Presentational: the parent supplies
// the two scroll callbacks (diff pane or conversation column).

import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { Icon, type IconName } from '../ui/Icon';

export function JumpWidget({
  onScrollTop,
  onScrollBottom,
}: {
  onScrollTop: () => void;
  onScrollBottom: () => void;
}) {
  return (
    <div
      className="absolute right-4 bottom-4 z-[4] flex flex-col overflow-hidden rounded-md border border-border bg-card shadow-md"
    >
      <JumpBtn icon="arrow-up-line" title="Top" kbd="⌘↑" onClick={onScrollTop} />
      <Separator />
      <JumpBtn
        icon="arrow-down-line"
        title="Bottom"
        kbd="⌘↓"
        onClick={onScrollBottom}
      />
    </div>
  );
}

function JumpBtn({
  icon,
  title,
  kbd,
  onClick,
}: {
  icon: IconName;
  title: string;
  kbd: string;
  onClick: () => void;
}) {
  return (
    <Button
      type="button"
      variant="ghost"
      size="xs"
      title={`${title}  ${kbd}`}
      onClick={onClick}
      className="w-[30px] rounded-none p-0 text-muted-foreground"
    >
      <Icon name={icon} size={13} />
    </Button>
  );
}
