// Post-install plan toast (design handoff, 2026-06).
//
// Fires once after the GitHub App is installed on an org with no plan yet
// (ADR 0020 #7). Reads celebratory-but-calm: the install DID succeed (emerald
// check), the "needs a plan" line is informational, not a hard paywall. Inline
// actions (Open Settings primary · Not now ghost) + a top-right × (the
// no-decision "silence now" twin) + a 12s auto-dismiss bar that pauses on
// hover. Rendered via sonner's toast.custom — see triggerPlanToast below.

import { toast } from 'sonner';
import { Building2, CheckCircle2, Settings, X } from 'lucide-react';
import { Button } from '@/components/ui/button';

function PlanToast({
  toastId,
  orgLogin,
  onOpenSettings,
}: {
  toastId: string | number;
  /** Org whose PRs are blocked. Omitted → generic "An organization". */
  orgLogin?: string;
  onOpenSettings: () => void;
}) {
  const dismiss = () => toast.dismiss(toastId);
  return (
    // `group` so the auto-dismiss bar can pause on hover; role=status announces
    // it politely without stealing focus.
    <div
      role="status"
      className="group relative w-[384px] overflow-hidden rounded-xl border border-border bg-background shadow-lg"
    >
      <div className="flex items-start gap-3 p-3.5">
        <div className="mt-px flex size-8 shrink-0 items-center justify-center rounded-[9px] bg-pyor-pass/10 text-pyor-pass ring-1 ring-inset ring-pyor-pass/30">
          <CheckCircle2 className="size-[18px]" strokeWidth={2} />
        </div>

        <div className="min-w-0 flex-1">
          <div className="text-[13px] font-semibold tracking-[-0.1px] text-foreground">
            Installation complete
          </div>
          <p className="mt-1 text-[12px] leading-normal text-muted-foreground">
            {orgLogin ? (
              <span className="font-semibold text-foreground/90">{orgLogin}</span>
            ) : (
              'An organization'
            )}{' '}
            needs a plan before its pull requests appear. Set it up whenever
            you&rsquo;re ready.
          </p>

          <div className="mt-2 inline-flex items-center gap-1.5 text-muted-foreground/80">
            <Building2 className="size-3" strokeWidth={2} />
            <span className="text-[11px]">Personal repos are always free</span>
          </div>

          <div className="mt-3 flex items-center gap-1.5">
            <Button
              size="sm"
              className="h-[30px] gap-1.5 rounded-[7px]"
              onClick={() => {
                onOpenSettings();
                dismiss();
              }}
            >
              <Settings />
              Open Settings
            </Button>
            <Button
              size="sm"
              variant="ghost"
              className="h-[30px] rounded-[7px]"
              onClick={dismiss}
            >
              Not now
            </Button>
          </div>
        </div>

        <button
          type="button"
          title="Dismiss"
          aria-label="Dismiss"
          onClick={dismiss}
          className="-mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground/70 hover:bg-muted hover:text-foreground"
        >
          <X className="size-3.5" strokeWidth={2} />
        </button>
      </div>

      {/* Auto-dismiss bar — shrinks over ~12s, pauses while the toast is hovered
       * (matches sonner's own timer pause). Dropped under reduced-motion. */}
      <div className="h-[2.5px] bg-pyor-pass/15">
        <div className="h-full origin-left bg-pyor-pass/85 animate-toast-progress group-hover:[animation-play-state:paused] motion-reduce:hidden" />
      </div>
    </div>
  );
}

/** Fire the post-install plan toast. ~12s auto-dismiss; sonner pauses the timer
 * on hover, and the bar pauses with it. */
export function triggerPlanToast(opts: {
  orgLogin?: string;
  onOpenSettings: () => void;
}) {
  toast.custom(
    (id) => (
      <PlanToast
        toastId={id}
        orgLogin={opts.orgLogin}
        onOpenSettings={opts.onOpenSettings}
      />
    ),
    { duration: 12_000 },
  );
}
