// CodeMirror 6 autocomplete sources for the composer — the four
// caret-anchored popovers from ADR 0018 §3:
//
//   :word  → emoji (static curated list, no network)
//   @word  → repo mentionable users (GraphQL, cached)
//   #word  → repo issues / PRs (search API, cached)
//   /word  → client-side markdown snippets (line-start only)
//
// `@` and `#` require a MentionContext (repo coordinates). Without one
// they're inert — the source returns null so the trigger char types
// literally. The network sources cache through the shared TanStack
// queryClient so a fast typist fans out at most one request per distinct
// query term.

import {
  type Completion,
  type CompletionContext,
  type CompletionResult,
  type CompletionSource,
  snippetCompletion,
} from '@codemirror/autocomplete';
import { EditorView } from '@codemirror/view';
import { queryClient } from '../../../lib/queryClient';
import {
  searchIssuesForRepo,
  searchMentionableUsers,
} from '../../../github/client';
import { EMOJI } from './emojiList';
import type { MentionContext } from './types';

/** True when a trigger matched a real prefix, or the user explicitly
 * invoked completion (Ctrl-Space / toolbar button) on the bare trigger. */
function active(match: { from: number; to: number }, ctx: CompletionContext): boolean {
  return match.from !== match.to || ctx.explicit;
}

function emojiSource(context: CompletionContext): CompletionResult | null {
  const match = context.matchBefore(/:[\w+-]*/);
  if (!match || !active(match, context)) return null;
  const term = match.text.slice(1).toLowerCase();
  const options: Completion[] = EMOJI.filter(
    (e) => !term || e.name.includes(term),
  )
    .slice(0, 20)
    .map((e) => ({
      label: `:${e.name}:`,
      detail: e.char,
      apply: e.char,
      type: 'text',
    }));
  if (options.length === 0) return null;
  return { from: match.from, to: match.to, options, filter: false };
}

function makeMentionSource(
  getCtx: () => MentionContext | undefined,
): CompletionSource {
  return async (context: CompletionContext): Promise<CompletionResult | null> => {
    const repo = getCtx();
    if (!repo) return null;
    const match = context.matchBefore(/@[\w-]*/);
    if (!match || !active(match, context)) return null;
    const term = match.text.slice(1);
    const users = await queryClient
      .fetchQuery({
        queryKey: ['mentionable', repo.owner, repo.repo, term],
        queryFn: () => searchMentionableUsers(repo.owner, repo.repo, term),
        staleTime: 60_000,
      })
      .catch(() => []);
    const options: Completion[] = users.map((u) => ({
      label: `@${u.login}`,
      detail: u.name ?? undefined,
      apply: `@${u.login} `,
      type: 'variable',
    }));
    if (options.length === 0) return null;
    return { from: match.from, to: match.to, options, filter: false };
  };
}

function makeIssueSource(
  getCtx: () => MentionContext | undefined,
): CompletionSource {
  return async (context: CompletionContext): Promise<CompletionResult | null> => {
    const repo = getCtx();
    if (!repo) return null;
    const match = context.matchBefore(/#\w*/);
    if (!match || !active(match, context)) return null;
    const term = match.text.slice(1);
    const hits = await queryClient
      .fetchQuery({
        queryKey: ['issue-ref', repo.owner, repo.repo, term],
        queryFn: () => searchIssuesForRepo(repo.owner, repo.repo, term),
        staleTime: 60_000,
      })
      .catch(() => []);
    const options: Completion[] = hits.map((h) => ({
      label: `#${h.number}`,
      detail: h.title,
      apply: `#${h.number} `,
      type: h.isPullRequest ? 'class' : 'interface',
    }));
    if (options.length === 0) return null;
    return { from: match.from, to: match.to, options, filter: false };
  };
}

// Client-side markdown snippet inserts. `${}` marks a snippet field the
// user tabs through; `${name}` gives the field a placeholder label.
// `/suggestion` is handled separately (see makeSuggestionCompletion) so it
// can pre-fill the block with the commented diff line(s).
const SLASH_SNIPPETS: { label: string; detail: string; template: string }[] = [
  { label: '/code', detail: 'Fenced code block', template: '```${lang}\n${}\n```\n' },
  {
    label: '/details',
    detail: 'Collapsible details',
    template: '<details>\n<summary>${summary}</summary>\n\n${}\n\n</details>\n',
  },
  {
    label: '/table',
    detail: 'Markdown table',
    template: '| ${col1} | ${col2} |\n| --- | --- |\n| ${} |  |\n',
  },
  { label: '/tasklist', detail: 'Task list item', template: '- [ ] ${}' },
];

const SUGGESTION_OPEN = '```suggestion\n';
const SUGGESTION_CLOSE = '\n```\n';

/** The `/suggestion` completion. When a `seed` is available (the text of
 * the diff line[s] being commented on) the block is pre-filled with it
 * and that text is left selected so the reviewer edits in place — GitHub
 * parity. With no seed it inserts an empty block with the caret between
 * the fences. Uses a custom `apply` (not a snippet) so the seed text is
 * inserted literally without `${…}` field parsing. */
function makeSuggestionCompletion(seed: string | undefined): Completion {
  const body = seed ?? '';
  return {
    label: '/suggestion',
    detail: seed ? 'Suggest an edit to these lines' : 'Suggested change block',
    type: 'keyword',
    apply: (view: EditorView, _completion, from: number, to: number) => {
      const insert = SUGGESTION_OPEN + body + SUGGESTION_CLOSE;
      const anchor = from + SUGGESTION_OPEN.length;
      view.dispatch({
        changes: { from, to, insert },
        // Select the body so the user can overtype it (empty → caret).
        selection: { anchor, head: anchor + body.length },
        scrollIntoView: true,
        userEvent: 'input.complete',
      });
    },
  };
}

function makeSlashSource(
  getSuggestionSeed: () => string | undefined,
): CompletionSource {
  return (context: CompletionContext): CompletionResult | null => {
    const match = context.matchBefore(/\/\w*/);
    if (!match || !active(match, context)) return null;
    // Slash commands only fire when the `/` opens the line (ignoring
    // leading whitespace) — otherwise `path/to/file` would trigger them.
    const line = context.state.doc.lineAt(match.from);
    if (context.state.sliceDoc(line.from, match.from).trim().length > 0) return null;
    const term = match.text.slice(1).toLowerCase();
    const options: Completion[] = [
      makeSuggestionCompletion(getSuggestionSeed()),
      ...SLASH_SNIPPETS.map((s) =>
        snippetCompletion(s.template, {
          label: s.label,
          detail: s.detail,
          type: 'keyword',
        }),
      ),
    ].filter((o) => !term || o.label.slice(1).includes(term));
    if (options.length === 0) return null;
    return { from: match.from, to: match.to, options, filter: false };
  };
}

/** Assemble the override list for `autocompletion({ override })`. The
 * mention/issue sources read repo coordinates lazily through `getCtx`, and
 * `/suggestion` reads the commented-line seed through `getSuggestionSeed`,
 * so the extension can be built once and still see current context. */
export function buildCompletionSources(
  getCtx: () => MentionContext | undefined,
  getSuggestionSeed: () => string | undefined,
): CompletionSource[] {
  return [
    emojiSource,
    makeMentionSource(getCtx),
    makeIssueSource(getCtx),
    makeSlashSource(getSuggestionSeed),
  ];
}
