// Measure an element's height with a ResizeObserver. Returns a callback ref
// and the latest height (0 until measured). Used to size the collapsing
// header zone from the real full/compact header heights.

import { useCallback, useRef, useState } from 'react';

export function useElementHeight(): [
  (el: HTMLElement | null) => void,
  number,
] {
  const [height, setHeight] = useState(0);
  const roRef = useRef<ResizeObserver | null>(null);

  const ref = useCallback((el: HTMLElement | null) => {
    roRef.current?.disconnect();
    roRef.current = null;
    if (!el || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver((entries) => {
      const h = entries[0]?.contentRect.height ?? 0;
      setHeight((prev) => (Math.abs(prev - h) > 0.5 ? h : prev));
    });
    ro.observe(el);
    roRef.current = ro;
    setHeight(el.getBoundingClientRect().height);
  }, []);

  return [ref, height];
}
