// PR tab strip — top tabs across the PR view.
// Tab names per ADR 0008 (amended): Description, Commits, Changes.
// Checks tab removed — check counts moved to ChecksHoverCard in PRHeader.
//
// Composes the shared `UnderlineTabs` component (same primitive that
// powers the Inbox + Pulls tab strips) so all three list surfaces have
// matching tab chrome. The J/K kbd hint OR a toolbarSlot sits in the right slot.

import { useEffect, useState, type ReactNode } from 'react';
import {
  FileIcon,
  GitBranchIcon,
  Loader2Icon,
  MessageSquareIcon,
} from 'lucide-react';
import { UnderlineTabs, type UnderlineTab } from '../ui/UnderlineTabs';
import { usePrLastPolledAt } from './usePrLastPolledAt';
import { Icon } from '../ui/Icon';

export type PRTab = 'description' | 'commits' | 'changes';

export interface PRTabCounts {
  description: number;
  commits: number;
  changes: number;
}

const TABS: UnderlineTab<PRTab>[] = [
  { id: 'description', label: 'Conversation', icon: MessageSquareIcon },
  { id: 'commits', label: 'Commits', icon: GitBranchIcon },
  { id: 'changes', label: 'Files changed', icon: FileIcon },
];

export function PRTabStrip({
  active,
  onChange,
  counts,
  toolbarSlot,
}: {
  active: PRTab;
  onChange?: (tab: PRTab) => void;
  counts?: PRTabCounts;
  /** When `active === 'changes'` and this is provided, renders in the
   * tab bar's right slot instead of the J/K hint. The CompactChangesToolbar
   * lives here in the compact redesign. */
  toolbarSlot?: ReactNode;
}) {
  const c = counts ?? { description: 0, commits: 0, changes: 0 };
  const tabs: UnderlineTab<PRTab>[] = TABS.map((t) => ({
    ...t,
    count: c[t.id],
  }));
  return (
    <UnderlineTabs
      tabs={tabs}
      active={active}
      onChange={onChange}
      right={active === 'changes' ? toolbarSlot : undefined}
    />
  );
}

interface PRStatusBarProps {
  intervalMs?: number;
  /** PR coordinates for the "polled Ns ago" readout. The status bar
   *  subscribes to the poll timestamp ITSELF (usePrLastPolledAt) so the
   *  per-15s dataUpdatedAt churn re-renders this strip only — passing a
   *  Date prop from the screen subscribed the whole PR tree to it. */
  owner?: string;
  repo?: string;
  number?: number;
  pendingDraftCount?: number;
  baseRef?: string;
  baseSha?: string;
  /** When non-null, swaps the "Live polling" indicator for a
   *  "Streaming diffs · resolved / total" pill — the design's
   *  primary in-flight progress signal for the Files tab. */
  contentsProgress?: { resolved: number; total: number } | null;
  /** True while /pulls/{n}/files is still paginating. Wins over
   *  contentsProgress (pagination strictly precedes streaming). */
  isFilesLoading?: boolean;
  /** Active force-push refetch — shows "Head moved · refetching"
   *  with old/new SHA + draft-safety reassurance. */
  forcePush?: {
    prevSha: string;
    newSha: string;
  } | null;
  /** Active fetch error cause. Drives a red/amber accent dot +
   *  cause label + "Cached content stays read-only" reassurance. */
  errorCause?: 'rate-limit' | 'network' | 'server-500' | null;
  /** Current PR tab. Some tabs surface their own fetch in the
   *  status bar (Commits) — the design's per-tab loading
   *  artboard shows "Fetching commits…". Checks tab is removed. */
  tabLoading?: 'commits' | null;
}

export function PRStatusBar({
  intervalMs = 15_000,
  owner,
  repo,
  number,
  pendingDraftCount = 0,
  baseRef,
  baseSha,
  contentsProgress = null,
  isFilesLoading = false,
  forcePush = null,
  errorCause = null,
  tabLoading = null,
}: PRStatusBarProps = {}) {
  const lastPolledAt = usePrLastPolledAt(owner ?? '', repo ?? '', number ?? 0);
  // Tick once a second so the "polled Ns ago" stays accurate without
  // having to re-render the parent.
  const [, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((n) => n + 1), 1000);
    return () => clearInterval(id);
  }, []);
  const ago = lastPolledAt
    ? Math.max(0, Math.round((Date.now() - lastPolledAt.getTime()) / 1000))
    : null;
  const streaming =
    contentsProgress &&
    contentsProgress.total > 0 &&
    contentsProgress.resolved < contentsProgress.total;
  // Priority order from highest to lowest: error > force-push > tab-fetch
  // > files-paginating > content-streaming > steady-poll. Each yields a
  // different left-most pill; everything else (polled-Xs-ago, draft
  // count, base SHA) is appended unchanged.
  const leadPill = (() => {
    if (errorCause) {
      const label =
        errorCause === 'rate-limit'
          ? 'GitHub rate-limit hit'
          : errorCause === 'network'
            ? "Can't reach api.github.com"
            : 'GitHub server error';
      const tone =
        errorCause === 'rate-limit'
          ? 'text-amber-700 dark:text-amber-400'
          : 'text-pyor-fail';
      const dotTone =
        errorCause === 'rate-limit' ? 'bg-amber-500' : 'bg-pyor-fail';
      return (
        <span className={`inline-flex items-center gap-1.5 ${tone}`}>
          <span className={`size-1.5 rounded-full ${dotTone}`} />
          <b className="font-semibold">{label}</b>
        </span>
      );
    }
    if (forcePush) {
      return (
        <span className="inline-flex items-center gap-1.5 text-amber-700 dark:text-amber-400">
          <span className="size-1.5 rounded-full bg-amber-500" />
          <b className="font-semibold">Head moved</b> · refetching diff
        </span>
      );
    }
    if (tabLoading === 'commits') {
      return (
        <span className="inline-flex items-center gap-1.5">
          <Loader2Icon className="size-3 animate-spin" />
          Fetching commits…
        </span>
      );
    }
    if (isFilesLoading && !streaming) {
      return (
        <span className="inline-flex items-center gap-1.5">
          <Loader2Icon className="size-3 animate-spin" />
          Paginating file list · page —
        </span>
      );
    }
    if (streaming) {
      return (
        <span className="inline-flex items-center gap-1.5">
          <Loader2Icon className="size-3 animate-spin" />
          Streaming diffs · {contentsProgress!.resolved} of{' '}
          {contentsProgress!.total} files
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-[5px]">
        <span
          className={`size-[6px] rounded-full ${
            lastPolledAt ? 'bg-pyor-pass' : 'bg-muted-foreground/50'
          }`}
        />
        Live polling · {Math.round(intervalMs / 1000)}s
      </span>
    );
  })();
  // Right-side trail. Force-push uses old→new SHA + draft-safe copy
  // (per design). Error uses "Cached content stays read-only · drafts
  // preserved". Otherwise the usual polled-ago + base SHA.
  const trail = (() => {
    if (forcePush) {
      return (
        <>
          <span className="mx-3 text-border">│</span>
          <span>
            Was{' '}
            <span className="font-mono text-[11px]">
              {forcePush.prevSha.slice(0, 7)}
            </span>{' '}
            · now{' '}
            <span className="font-mono text-[11px]">
              {forcePush.newSha.slice(0, 7)}
            </span>
          </span>
          {pendingDraftCount > 0 && (
            <>
              <span className="mx-3 text-border">│</span>
              <span>
                Your draft is safe ({pendingDraftCount} pending{' '}
                {pendingDraftCount === 1 ? 'comment' : 'comments'})
              </span>
            </>
          )}
        </>
      );
    }
    if (errorCause) {
      return (
        <>
          <span className="mx-3 text-border">│</span>
          <span>Cached content stays read-only · drafts preserved</span>
        </>
      );
    }
    return (
      <>
        <span className="mx-3 text-border">│</span>
        <span
          title="How long ago this PR was last refreshed from GitHub (its metadata, comments, and review threads). Updates on every poll tick, whether or not anything changed."
        >
          {ago === null
            ? 'first poll pending…'
            : ago < 5
              ? 'just polled'
              : `polled ${ago}s ago`}
        </span>
        {pendingDraftCount > 0 && (
          <>
            <span className="mx-3 text-border">│</span>
            <span className="inline-flex items-center gap-1">
              <Icon name="comment" size={11} /> {pendingDraftCount} pending
              in draft review
            </span>
          </>
        )}
        {baseRef && (
          <>
            <span className="mx-3 text-border">│</span>
            <span>
              Base ·{' '}
              <span className="font-mono text-[11px]">
                {baseRef}
                {baseSha ? `@${baseSha.slice(0, 7)}` : ''}
              </span>
            </span>
          </>
        )}
      </>
    );
  })();
  return (
    <>
      {leadPill}
      {trail}
      <span className="flex-1" />
    </>
  );
}
