// File-level Local Review Comment composer. Same shape as the line
// composer, but anchored to a path with no line number — for whole-file
// feedback. Triggered by the "Comment on file" pill in the file header.
//
// Per ADR 0012: file-level comments use `side: 'RIGHT'`, `line: null`,
// `contentSnippet: null`. The storage shape stays uniform so consumers
// (display card, Phase 4 staleness, Phase 6 export) can rely on a single
// presence-check (`line == null`) to route file-level rendering.
//
// Design parity: gh-comments.jsx · GhComposer, prefixed with a compact
// file-anchor label + "local" badge.

import { useState } from 'react';
import { FileIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { localReviewUploader } from '../../review/pasteAttachment';
import { useCreateLocalReviewComment } from '../../review/useLocalReviewComments';
import { GhComposer } from '../conversation/GhComposer';

export interface LocalFileComposerProps {
  reviewId: string;
  path: string;
  /** Committed head SHA or `WORKING_TREE_ANCHOR` — bucket-dependent. */
  anchorSha: string;
  authorLogin?: string;
  onClose: () => void;
}

export function LocalFileCommentComposer({
  reviewId,
  path,
  anchorSha,
  authorLogin,
  onClose,
}: LocalFileComposerProps) {
  // ADR 0012 Phase 5 — pre-generate commentId so paste-attach during
  // composition writes to the right dir; reused on save. See
  // LocalLineCommentComposer for the rationale.
  const [pendingCommentId] = useState(() => crypto.randomUUID());
  const create = useCreateLocalReviewComment();
  const author = authorLogin ?? 'you';

  return (
    <div className="mx-3 mb-3 mt-1.5 box-border max-w-full">
      <div className="mb-1.5 flex min-w-0 items-center gap-2 px-0.5 text-[11.5px] text-foreground">
        <FileIcon className="size-[12px] shrink-0 text-pyor-warn" />
        <span className="shrink-0 font-semibold">New file-level note</span>
        <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-muted-foreground">
          · {path}
        </span>
        <Badge
          variant="secondary"
          className="shrink-0 bg-pyor-warn/10 font-semibold text-pyor-warn"
        >
          local
        </Badge>
      </div>
      <GhComposer
        draftKey={`local:${reviewId}:file:${path}`}
        placeholder="File-level note… (Markdown · paste images · ⌘⏎ to save · Esc to cancel)"
        submitLabel="Save note"
        submitIcon="check"
        draftHint="Stays in this local review until you delete it"
        autoFocus
        minHeight={84}
        onUploadImage={localReviewUploader(reviewId, pendingCommentId)}
        onCancel={onClose}
        onSubmit={async (body) => {
          if (!body.trim()) return;
          // Close BEFORE the card renders — see LocalLineCommentComposer:
          // @pierre/diffs leaves stale DOM when an annotation is swapped at
          // the same line in one tick. Remove the composer first, then create.
          onClose();
          await create.mutateAsync({
            id: pendingCommentId,
            reviewId,
            path,
            side: 'RIGHT',
            line: null,
            anchorSha,
            contentSnippet: null,
            body,
            authorLogin: author,
          });
        }}
      />
    </div>
  );
}
