// Paste/drop → image-attachment plumbing for the CM6 composer. This is
// backend-agnostic: it inserts an "uploading…" placeholder at the caret,
// calls the injected `upload(file) => url` strategy, then swaps the
// placeholder for the final `![alt](url)` markdown (or removes it + a
// toast on failure). The composer wires it from CM6 paste/drop DOM event
// handlers.
//
// The two real strategies — the GitHub `pyor-assets` repo uploader and
// the Local Review `pyor-attachment://` bridge uploader — both reduce to
// "give me a File, get back a URL", so neither is referenced here. See
// ADR 0018 §4 (backends are split by surface, selected via injection).

import { toast } from 'sonner';
import { EditorView } from '@codemirror/view';

/** Thrown by an upload strategy when the user intentionally backs out
 * (e.g. declines the public-repo consent dialog). The placeholder is
 * removed without a failure toast — it wasn't a failure. */
export class UploadCancelled extends Error {
  constructor() {
    super('upload cancelled');
    this.name = 'UploadCancelled';
  }
}

/** Pull image `File`s off a clipboard/drag payload. Non-image items are
 * ignored so plain-text paste falls through to CM6's default handling. */
export function imageFilesFromDataTransfer(
  dt: DataTransfer | null,
): File[] {
  if (!dt) return [];
  const out: File[] = [];
  for (const item of Array.from(dt.items)) {
    if (item.kind === 'file' && item.type.startsWith('image/')) {
      const file = item.getAsFile();
      if (file) out.push(file);
    }
  }
  return out;
}

/** Markdown alt text from a filename — strip the extension, fall back to
 * "image" for clipboard pastes that arrive nameless (e.g. `image.png`). */
function altText(name: string): string {
  const base = name.replace(/\.[^.]+$/, '').trim();
  return base.length > 0 ? base : 'image';
}

/** Replace the first occurrence of `needle` in the live doc with
 * `replacement`. Searches the current document each call (rather than
 * trusting stored offsets) so concurrent edits while the upload is in
 * flight can't corrupt an unrelated range. No-op if the placeholder is
 * gone (user deleted it mid-upload). */
function replaceInDoc(view: EditorView, needle: string, replacement: string): void {
  const idx = view.state.doc.toString().indexOf(needle);
  if (idx < 0) return;
  view.dispatch({
    changes: { from: idx, to: idx + needle.length, insert: replacement },
    userEvent: 'input.attachment',
  });
}

/** Insert `text` at the caret, padding with newlines when we're not at a
 * paragraph boundary so the embedded image renders on its own line. */
function insertAtCaret(view: EditorView, text: string): void {
  const pos = view.state.selection.main.head;
  const before = view.state.sliceDoc(Math.max(0, pos - 1), pos);
  const after = view.state.sliceDoc(pos, pos + 1);
  const lead = pos > 0 && before !== '\n' ? '\n' : '';
  const trail = after.length > 0 && after !== '\n' ? '\n' : '';
  const insert = `${lead}${text}${trail}`;
  view.dispatch({
    changes: { from: pos, insert },
    selection: { anchor: pos + insert.length },
    scrollIntoView: true,
    userEvent: 'input.attachment',
  });
}

/**
 * Insert an uploading-placeholder per file and kick off the uploads. The
 * placeholder carries a unique token so the success/failure swap targets
 * exactly this insertion even if several images are uploading at once.
 * Uploads run concurrently; each resolves independently.
 */
export function insertImageUploads(
  view: EditorView,
  files: File[],
  upload: (file: File) => Promise<string>,
): void {
  for (const file of files) {
    const token = `pyor-uploading-${crypto.randomUUID()}`;
    const alt = altText(file.name);
    const placeholder = `![Uploading ${alt}…](${token})`;
    insertAtCaret(view, placeholder);
    void upload(file).then(
      (url) => replaceInDoc(view, placeholder, `![${alt}](${url})`),
      (err) => {
        replaceInDoc(view, placeholder, '');
        if (err instanceof UploadCancelled) return;
        // eslint-disable-next-line no-console
        console.warn('image upload failed:', err);
        toast.error('Couldn’t upload image. Try again.');
      },
    );
  }
}
