// Centred card shown in the diff pane while /pulls/{n}/files is
// still paginating. Per shell-pr-loading-files-paginating: an SCard
// titled "Resolving changed files" with progress + page counter +
// "N files so far" + hint about the review dock staying usable.

import { Loader2Icon, InfoIcon } from 'lucide-react';
import { Card } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';

export function PaginatingCard({
  owner,
  repo,
  number,
  filesSoFar,
}: {
  owner?: string;
  repo?: string;
  number?: number;
  filesSoFar?: number;
}) {
  return (
    <div className="flex flex-1 items-center justify-center bg-card p-10">
      <Card className="w-[420px] overflow-hidden p-0">
        <div className="flex items-start gap-3 p-4">
          <div className="inline-flex size-8 shrink-0 items-center justify-center rounded-md border bg-muted/40">
            <Loader2Icon className="size-4 animate-spin" />
          </div>
          <div className="min-w-0 flex-1">
            <div className="text-[13px] font-semibold text-foreground">
              Resolving changed files
            </div>
            <div className="mt-0.5 text-[12px] leading-relaxed text-muted-foreground">
              GitHub paginates{' '}
              <code className="rounded bg-muted px-1 py-0.5 font-mono text-[11px]">
                /pulls/{number ?? '—'}/files
              </code>{' '}
              at 30 entries per request. Diffs start rendering as soon as
              the first page lands.
            </div>
            <Progress value={undefined} className="mt-3 h-1 rounded-full" />
            <div className="mt-2 flex items-center justify-between text-[11px] tabular-nums text-muted-foreground">
              <span>
                {owner && repo ? `${owner}/${repo}` : 'fetching'}
                {number ? `#${number}` : ''}
              </span>
              <span>
                {filesSoFar && filesSoFar > 0
                  ? `${filesSoFar} files so far`
                  : 'first page in flight'}
              </span>
            </div>
          </div>
        </div>
        <Separator />
        <div className="flex items-center gap-2 px-4 py-2 text-[11.5px] text-muted-foreground">
          <InfoIcon className="size-3.5" />
          <span>You can keep typing in the review dock — drafts are local.</span>
        </div>
      </Card>
    </div>
  );
}
