// Unified Focus-mode pill — one contextual affordance in the PR header,
// labeled by what you focus ON (never what's hidden), so the same pill
// reads coherently across tabs even though the effect differs:
//
//   - Changes tab      → "Focus: Code"  → hides comment overlays in the
//     diff so the reviewer can read the code.
//   - Conversation tab → "Focus: All comments" / "Focus: New comments"
//     → collapses runs of timeline noise (pushes, labels, CI); the
//     variant chooses WHICH comment threads stay: ALL of them, or only
//     NEW ones (threads whose most recent comment isn't the viewer's —
//     i.e. awaiting a reply). On Conversation the body toggles Focus and
//     a caret picks the variant; the variant only takes effect while
//     Focus is active.
//
// Shared icon language + ⇧M shortcut + header slot. State lives at
// PRDetailScreen so the toggle survives tab switches.
//
// Design parity: gh-comments.jsx · GhFocusToggle.

import { CodeIcon, MessageSquareIcon, ChevronDownIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { cn } from '@/lib/utils';

export type FocusMode = 'code' | 'comments';

export function FocusToggle({
  mode,
  active,
  onToggle,
  commentFocusIsNew,
  onSelectCommentFocus,
  commentCounts,
  compact = false,
}: {
  /** What this pill focuses ON — derived from the active tab. */
  mode: FocusMode;
  active: boolean;
  onToggle: () => void;
  /** Conversation only: whether the "New comments" variant is selected
   * (vs "All comments"). Ignored in `code` mode. */
  commentFocusIsNew: boolean;
  /** Pick the comment-focus variant. Selecting one also activates Focus
   * (you chose a focus mode), so the variant takes effect immediately. */
  onSelectCommentFocus: (isNew: boolean) => void;
  /** Conversation only: `all` = total comment discussions, `pending` =
   * threads awaiting the viewer's reply. Shown on the pill + in the menu
   * so the two variants read distinctly. */
  commentCounts?: { all: number; pending: number };
  /** Compact header: icon-only (label + ⇧M badge hidden). */
  compact?: boolean;
}) {
  const Icon = mode === 'code' ? CodeIcon : MessageSquareIcon;
  const activeCount = commentFocusIsNew
    ? commentCounts?.pending
    : commentCounts?.all;
  const label =
    mode === 'code'
      ? 'Focus: Code'
      : commentFocusIsNew
        ? `Focus: Pending comments${activeCount != null ? ` (${activeCount})` : ''}`
        : `Focus: All comments${activeCount != null ? ` (${activeCount})` : ''}`;
  const effect =
    mode === 'code'
      ? 'Comment overlays are hidden in the diff.'
      : commentFocusIsNew
        ? 'Threads awaiting your reply stay expanded; handled ones collapse; pushes, labels & CI are hidden.'
        : 'All comment threads are shown; pushes, labels & CI are hidden.';
  const tooltip = active
    ? `Focusing. ${effect} Press ⇧M or click to turn off.`
    : `Press ⇧M or click to turn on. ${effect}`;

  const body = (
    <button
      type="button"
      onClick={onToggle}
      aria-pressed={active}
      title={tooltip}
      className={cn(
        'inline-flex h-full items-center gap-1.5 px-2.5 transition-colors',
        mode === 'comments' ? 'rounded-l-md' : 'rounded-md',
        active
          ? 'hover:bg-amber-100 dark:hover:bg-amber-900/50'
          : 'hover:bg-muted',
      )}
    >
      <Icon
        className={cn(
          'size-3.5 shrink-0',
          active ? 'text-amber-700 dark:text-amber-300' : 'text-muted-foreground',
        )}
      />
      {!compact && <span>{label}</span>}
      {!compact && (
        <Badge
          variant="outline"
          className={cn(
            'h-[18px] min-w-[18px] justify-center rounded px-1 py-0 text-[10.5px] font-medium',
            active
              ? 'border-amber-300/60 bg-card text-amber-900 dark:text-amber-200'
              : 'text-muted-foreground',
          )}
        >
          ⇧M
        </Badge>
      )}
    </button>
  );

  // Changes tab: a plain toggle — "Focus: Code" has no comment variants.
  if (mode === 'code') {
    return (
      <div
        className={cn(
          'inline-flex h-7 shrink-0 items-center rounded-md border text-[12px] font-medium transition-colors',
          active
            ? 'border-amber-300/60 bg-amber-50 text-amber-900 dark:border-amber-700/60 dark:bg-amber-900/30 dark:text-amber-200'
            : 'border-input bg-card text-foreground',
        )}
      >
        {body}
      </div>
    );
  }

  // Conversation tab: split control — body toggles Focus, caret picks
  // the "All comments" / "New comments" variant.
  return (
    <div
      className={cn(
        'inline-flex h-7 shrink-0 items-center rounded-md border text-[12px] font-medium transition-colors',
        active
          ? 'border-amber-300/60 bg-amber-50 text-amber-900 dark:border-amber-700/60 dark:bg-amber-900/30 dark:text-amber-200'
          : 'border-input bg-card text-foreground',
      )}
    >
      {body}
      <span
        className={cn(
          'h-4 w-px',
          active ? 'bg-amber-300/60 dark:bg-amber-700/60' : 'bg-input',
        )}
      />
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <button
            type="button"
            title="Choose what to focus on"
            aria-label="Choose comment focus"
            className={cn(
              'inline-flex h-full items-center rounded-r-md px-1 transition-colors',
              active
                ? 'hover:bg-amber-100 dark:hover:bg-amber-900/50'
                : 'hover:bg-muted',
            )}
          >
            <ChevronDownIcon className="size-3.5 opacity-70" />
          </button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-[260px]">
          <DropdownMenuLabel>Focus on…</DropdownMenuLabel>
          <DropdownMenuRadioGroup
            value={commentFocusIsNew ? 'new' : 'all'}
            onValueChange={(v) => onSelectCommentFocus(v === 'new')}
          >
            <DropdownMenuRadioItem value="all">
              <span className="flex-1">All comments</span>
              {commentCounts && (
                <span className="ml-2 tabular-nums text-muted-foreground">
                  {commentCounts.all}
                </span>
              )}
            </DropdownMenuRadioItem>
            <DropdownMenuRadioItem value="new">
              <span className="flex-1">Pending comments</span>
              {commentCounts && (
                <span className="ml-2 tabular-nums text-muted-foreground">
                  {commentCounts.pending}
                </span>
              )}
            </DropdownMenuRadioItem>
          </DropdownMenuRadioGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}
