// Observability config (ADR 0021). Single place that reads the env so the
// rest of the module never touches `import.meta.env` directly.
//
// EVERYTHING here is optional: with no keys set (dev / mock-broker runs) the
// SDKs never initialise and every `track()` / `identify()` is a silent no-op.
// That keeps local development free of network chatter and means a missing
// secret degrades to "no telemetry", never to a crash.

const str = (v: unknown): string | undefined => {
  const s = typeof v === 'string' ? v.trim() : '';
  return s.length > 0 ? s : undefined;
};

// Build-time flag injected via Vite `define` (see vite.config.ts / router.tsx).
declare const __PIER_ELECTRON__: boolean;

const env = import.meta.env;

/** PostHog project key (`phc_…`). Unset → analytics disabled. */
export const POSTHOG_KEY = str(env.VITE_POSTHOG_KEY);

/**
 * Ingest host. Defaults to the first-party reverse-proxy on the
 * identity-billing-plane (ADR 0021) so browsers never hit `*.posthog.com`
 * directly — adblock-resilient + on-posture. Override in dev if needed.
 */
export const POSTHOG_HOST =
  str(env.VITE_POSTHOG_HOST) ?? 'https://api.pyor.review/ingest';

/** Where the PostHog *dashboard* lives — links in the toolbar resolve here. */
export const POSTHOG_UI_HOST = 'https://eu.posthog.com';

/** Sentry DSN for this surface. Unset → error tracking disabled. */
export const SENTRY_DSN = str(env.VITE_SENTRY_DSN);

/**
 * First-party tunnel for Sentry envelopes (same adblock dodge as PostHog).
 * Sentry's ingest hosts are blocklisted too; routing through our own origin
 * keeps error reports flowing for the developer audience.
 */
export const SENTRY_TUNNEL =
  str(env.VITE_SENTRY_TUNNEL) ?? 'https://api.pyor.review/monitoring';

/** production | preview | development — tags every event + error. */
export const ENVIRONMENT =
  str(env.VITE_OBSERVABILITY_ENV) ?? (env.PROD ? 'production' : 'development');

/** Release identifier (git SHA, injected at build). Ties errors to a deploy. */
export const RELEASE = str(env.VITE_RELEASE) ?? 'dev';

/** True only in the packaged Electron desktop build. */
const IS_DESKTOP =
  typeof __PIER_ELECTRON__ !== 'undefined' && __PIER_ELECTRON__ === true;

/**
 * Local development is never reported. Even with real keys in `.env.local`, the
 * dev server (`import.meta.env.DEV`) and anything served from localhost is
 * silenced so test errors don't pollute the Sentry/PostHog projects. A packaged
 * Electron build runs from `file://` (empty hostname) and a preview/prod deploy
 * runs from a real host, so both still report.
 */
const isLocalDev =
  env.DEV ||
  (typeof window !== 'undefined' &&
    /^(localhost|127\.0\.0\.1|\[::1\])$/.test(window.location.hostname));

export const analyticsConfigured = Boolean(POSTHOG_KEY) && !isLocalDev;
export const errorTrackingConfigured = Boolean(SENTRY_DSN) && !isLocalDev;

/**
 * PostHog **group analytics** is a PAID feature. Off by default → org context
 * rides as an `org_id` event PROPERTY instead (free-tier friendly: every insight
 * can still break down / filter by org, just without the dedicated group
 * timeline). Set `VITE_POSTHOG_GROUPS=true` after upgrading to switch on real
 * group analytics (ADR 0021).
 */
export const groupAnalyticsEnabled = str(env.VITE_POSTHOG_GROUPS) === 'true';
