// Pure Lifecycle action resolver — the GitHub PR state machine in one
// place. No React, no network: feed it the PR's state, the repo merge
// config, the viewer's permission, and the viewer login, and get back
// which Lifecycle actions to render and whether each is enabled (with a
// reason when not). See ADR 0016 and CONTEXT.md ("Lifecycle action",
// "Viewer permission").
//
// Kept deliberately dependency-free so a later vitest harness can
// unit-test the whole GitHub state machine in isolation, with no
// mocking — feed a (PR state × repo config × permission) triple and
// assert the resolved action set + disabled reasons.

/** GitHub's repository-level permission ladder. `NONE` covers the
 * "no access / unauthenticated" case GraphQL returns as null. */
export type ViewerPermission =
  | 'NONE'
  | 'READ'
  | 'TRIAGE'
  | 'WRITE'
  | 'MAINTAIN'
  | 'ADMIN';

/** GitHub merge API `merge_method` values. */
export type MergeMethod = 'merge' | 'squash' | 'rebase';

/** Repo-level merge settings (GET /repos/{o}/{r}). GitHub has no
 * single "default merge method" field — github.com defaults to the
 * first allowed in [merge, squash, rebase], which `defaultMergeMethod`
 * below mirrors. */
export interface RepoMergeConfig {
  allowMergeCommit: boolean;
  allowSquashMerge: boolean;
  allowRebaseMerge: boolean;
  allowAutoMerge: boolean;
  deleteBranchOnMerge: boolean;
  /** The repo's default branch (e.g. "main"). Lets the header flag a PR
   * whose base ref isn't the default, mirroring GitHub's amber base-ref
   * highlight. Empty string until the repo read resolves. */
  defaultBranch: string;
}

/** The slice of PR state the resolver reasons about. Derived from the
 * REST PR payload (`merged` = `merged_at != null`, `autoMergeEnabled`
 * = `auto_merge != null`). */
export interface LifecyclePRState {
  state: 'open' | 'closed';
  draft: boolean;
  merged: boolean;
  mergeable: boolean | null;
  /** clean | dirty | behind | blocked | unstable | draft | has_hooks |
   * unknown — GitHub's `mergeable_state`. */
  mergeableState: string;
  authorLogin: string;
  autoMergeEnabled: boolean;
}

export type LifecycleActionKind =
  | 'merge'
  | 'close'
  | 'reopen'
  | 'convertToDraft'
  | 'markReady'
  | 'updateBranch'
  | 'enableAutoMerge'
  | 'disableAutoMerge';

export interface LifecycleAction {
  kind: LifecycleActionKind;
  enabled: boolean;
  /** Present iff `!enabled` — human-readable why the action is shown
   * but not actionable. */
  disabledReason?: string;
}

export interface MergeAction extends LifecycleAction {
  kind: 'merge';
  /** Repo-allowed methods in preference order [merge, squash, rebase]. */
  methods: MergeMethod[];
  defaultMethod: MergeMethod;
  /** Default state of the merge dialog's delete-branch checkbox. */
  deleteBranchDefault: boolean;
}

export interface ResolvedLifecycle {
  /** Render exactly these. Absence of a kind ⇒ do not render that
   * control (it would 403 or doesn't apply to this PR state). */
  actions: LifecycleAction[];
  /** Merge split-button availability, or null when no merge control
   * should render (not open, draft, no write, conflicts, or repo
   * allows no methods). When non-null it's also present in `actions`. */
  merge: MergeAction | null;
  /** dirty + open + non-draft: show the conflict banner where the merge
   * control would be (ADR 0017 — generic banner, no file list). */
  conflict: boolean;
}

const RANK: Record<ViewerPermission, number> = {
  NONE: 0,
  READ: 1,
  TRIAGE: 2,
  WRITE: 3,
  MAINTAIN: 4,
  ADMIN: 5,
};

/** WRITE, MAINTAIN, and ADMIN can act on others' PRs; READ/TRIAGE
 * cannot. */
export function hasWriteAccess(p: ViewerPermission): boolean {
  return RANK[p] >= RANK.WRITE;
}

/** Repo-allowed merge methods in github.com's preference order. The
 * first entry doubles as the default method. */
export function allowedMergeMethods(cfg: RepoMergeConfig): MergeMethod[] {
  const methods: MergeMethod[] = [];
  if (cfg.allowMergeCommit) methods.push('merge');
  if (cfg.allowSquashMerge) methods.push('squash');
  if (cfg.allowRebaseMerge) methods.push('rebase');
  return methods;
}

const MERGE_DISABLED_REASON: Record<string, string> = {
  dirty: 'This branch has conflicts that must be resolved',
  behind: 'This branch is out of date with the base branch',
  blocked: 'Merging is blocked by branch protection rules',
  unstable: 'Required checks have not passed yet',
  unknown: 'GitHub is still checking whether this branch can be merged',
  draft: 'This pull request is still a draft',
};

/**
 * Resolve the full set of Lifecycle actions for a PR. Single entry
 * point for every lifecycle surface — the UI asks "what can I do?"
 * rather than scattering state logic across components.
 */
// Open/closed state actions (close · reopen · draft toggle · update-branch).
// Push order is preserved — it drives the on-screen button order.
function stateActions(
  pr: LifecyclePRState,
  isOpen: boolean,
  canManageState: boolean,
): LifecycleAction[] {
  const actions: LifecycleAction[] = [];
  if (isOpen && canManageState) {
    actions.push({ kind: 'close', enabled: true });
  }
  if (pr.state === 'closed' && !pr.merged && canManageState) {
    actions.push({ kind: 'reopen', enabled: true });
  }
  // Draft toggle.
  if (isOpen && canManageState) {
    actions.push(
      pr.draft
        ? { kind: 'markReady', enabled: true }
        : { kind: 'convertToDraft', enabled: true },
    );
  }
  // Update-branch — only meaningful when the PR is behind base.
  if (isOpen && pr.mergeableState === 'behind' && canManageState) {
    actions.push({ kind: 'updateBranch', enabled: true });
  }
  return actions;
}

// Auto-merge toggle — WRITE+ only and the repo must allow it. Returns the
// single enable/disable action, or nothing when it doesn't apply.
function autoMergeActions(
  pr: LifecyclePRState,
  repo: RepoMergeConfig,
  isOpen: boolean,
  write: boolean,
): LifecycleAction[] {
  if (!(isOpen && !pr.draft && write && repo.allowAutoMerge)) return [];
  if (pr.autoMergeEnabled) {
    return [{ kind: 'disableAutoMerge', enabled: true }];
  }
  if (
    pr.mergeableState !== 'clean' &&
    pr.mergeableState !== 'has_hooks' &&
    pr.mergeableState !== 'dirty'
  ) {
    // Offer auto-merge when the PR can't merge right now but isn't a
    // hard conflict — i.e. checks pending / blocked / behind / unknown.
    return [{ kind: 'enableAutoMerge', enabled: true }];
  }
  return [];
}

// Merge split-button — WRITE+ only, open & non-draft. `has_hooks` is
// "mergeable, but the repo has pre-receive hooks" — github.com treats it as
// mergeable, so we do too. A dirty PR still gets the (disabled) control.
function resolveMergeAction(
  pr: LifecyclePRState,
  repo: RepoMergeConfig,
  isOpen: boolean,
  write: boolean,
): MergeAction | null {
  const methods = allowedMergeMethods(repo);
  if (!(isOpen && !pr.draft && write && methods.length > 0)) return null;
  const mergeableNow =
    pr.mergeable === true &&
    (pr.mergeableState === 'clean' || pr.mergeableState === 'has_hooks');
  return {
    kind: 'merge',
    enabled: mergeableNow,
    disabledReason: mergeableNow
      ? undefined
      : (MERGE_DISABLED_REASON[pr.mergeableState] ??
        'This pull request can’t be merged right now'),
    methods,
    defaultMethod: methods[0],
    deleteBranchDefault: repo.deleteBranchOnMerge,
  };
}

export function resolveLifecycleActions(
  pr: LifecyclePRState,
  repo: RepoMergeConfig,
  viewerPermission: ViewerPermission,
  viewerLogin: string,
): ResolvedLifecycle {
  const write = hasWriteAccess(viewerPermission);
  const isAuthor = !!viewerLogin && viewerLogin === pr.authorLogin;
  // The author can manage their own PR's open/draft/branch state even
  // without repo write; everyone else needs WRITE+.
  const canManageState = write || isAuthor;
  const isOpen = pr.state === 'open' && !pr.merged;

  const actions: LifecycleAction[] = [
    ...stateActions(pr, isOpen, canManageState),
    ...autoMergeActions(pr, repo, isOpen, write),
  ];

  // A dirty PR keeps the merge control but flips it into a blocked
  // "can't merge" state (the `conflict` flag drives the red blocked-button +
  // conflict popover in the UI); the merge action is still emitted (disabled,
  // with the conflict reason) so the button stays in place.
  const conflict = isOpen && !pr.draft && pr.mergeableState === 'dirty';
  const merge = resolveMergeAction(pr, repo, isOpen, write);
  if (merge) actions.push(merge);

  return { actions, merge, conflict };
}

/** Convenience lookup used by the UI surfaces. */
export function findAction(
  resolved: ResolvedLifecycle,
  kind: LifecycleActionKind,
): LifecycleAction | undefined {
  return resolved.actions.find((a) => a.kind === kind);
}
