// Patch-specific helper for the search overview-ruler (the VSCode-style
// dots on the diff scrollbar). Accurate vertical positions need the
// renderer's REAL layout (inline comment threads, soft-wrap and collapsed
// regions all change a file's rendered height, so a patch-line estimate
// drifts - badly for sparse searches). DiffBody owns that: it reads each
// file's true top from @pierre/diffs (`getInstance().getTopForItem`). This
// module supplies the one part DiffBody can't derive itself - where each
// match sits WITHIN its file (0..1 of the file's rendered rows), from the
// patch we already parsed.

/** One body line (+/-/space) of a unified-diff patch. */
export interface PatchBodyLine {
  marker: '+' | '-' | ' ';
  body: string;
  /** New-side line number (valid for '+' and context). */
  addLineNo: number;
  /** Old-side line number (valid for '-' and context). */
  delLineNo: number;
  /** Rendered row index, counting @@ hunk-separator rows, matching what the
   *  diff actually renders. */
  rowIndex: number;
}

/**
 * Walk a unified-diff patch, invoking `visit` once per body line, tracking
 * both sides' line numbers and the rendered row index. Returns the total
 * rendered row count. This is the single source of patch-line numbering,
 * shared by the search match finder (`parsePatchForMatches`) and the ruler
 * row-fraction map, so the two can never drift (CRLF, no-newline markers, a
 * new hunk-header variant) and the dots stay aligned with the highlights.
 */
export function forEachPatchBodyLine(
  patch: string,
  visit: (line: PatchBodyLine) => void,
): number {
  let row = 0;
  let add = 0;
  let del = 0;
  patch.split('\n').forEach((line) => {
    if (line.startsWith('@@')) {
      const m = line.match(/^@@\s+-(\d+)(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s+@@/);
      if (m) {
        del = Number(m[1]) - 1;
        add = Number(m[2]) - 1;
      }
      row += 1;
      return;
    }
    if (line.length === 0) return;
    const marker = line[0];
    const body = line.slice(1);
    if (marker === '+') {
      add += 1;
      visit({ marker, body, addLineNo: add, delLineNo: del, rowIndex: row });
      row += 1;
      return;
    }
    if (marker === '-') {
      del += 1;
      visit({ marker, body, addLineNo: add, delLineNo: del, rowIndex: row });
      row += 1;
      return;
    }
    if (marker === ' ') {
      add += 1;
      del += 1;
      visit({ marker, body, addLineNo: add, delLineNo: del, rowIndex: row });
      row += 1;
    }
    // Other markers (\\ no-newline-at-eof, etc.) are ignored.
  });
  return row;
}

interface RulerMatch {
  filename: string;
  lineNumber: number;
  side: 'additions' | 'deletions';
}

interface RulerFile {
  filename: string;
  patch?: string | null;
}

/** Per-file row index for each (side, lineNumber), plus the file's total
 *  rendered row count - built by walking the unified patch the same way
 *  `parsePatchForMatches` does, so row indices line up with what renders. */
interface FileRowMap {
  rows: Map<string, number>;
  total: number;
}

function buildFileRowMap(patch: string | null | undefined): FileRowMap {
  if (!patch) return { rows: new Map(), total: 1 };
  const rows = new Map<string, number>();
  const total = forEachPatchBodyLine(patch, (l) => {
    if (l.marker !== '-') rows.set(`additions:${l.addLineNo}`, l.rowIndex);
    if (l.marker !== '+') rows.set(`deletions:${l.delLineNo}`, l.rowIndex);
  });
  return { rows, total: Math.max(total, 1) };
}

/**
 * For each match, its fractional position (0..1) within its file's rendered
 * rows. Index-aligned with `matches`. Unknown lines (or elided patches)
 * fall back to the file's mid-point.
 */
export function matchRowFractions(
  orderedFiles: readonly RulerFile[],
  matches: readonly RulerMatch[],
): number[] {
  const perFile = new Map<string, FileRowMap>(
    orderedFiles.map((f) => [f.filename, buildFileRowMap(f.patch)]),
  );
  return matches.map((m) => {
    const pf = perFile.get(m.filename);
    if (!pf) return 0.5;
    const r = pf.rows.get(`${m.side}:${m.lineNumber}`);
    if (r == null) return 0.5;
    return (r + 0.5) / pf.total;
  });
}
