// App-wide route error boundary — wired as the router's
// `defaultErrorComponent`, so any error thrown while rendering a route
// (including render-loop crashes like "Maximum update depth exceeded")
// lands here instead of TanStack Router's bare "Something went wrong!"
// fallback.
//
// In DEV it surfaces the error message AND the React component stack
// (`info.componentStack`) — the single most useful artifact for finding
// which component blew up — and logs the same to the console for copying.
// In PROD it shows a calm recovery card with retry / reload only.

import { useEffect } from 'react';
import type { ErrorComponentProps } from '@tanstack/react-router';
import { AlertTriangleIcon, RotateCcwIcon } from 'lucide-react';
import { RefreshButton } from '@/components/ui/refresh-button';

export function RouteErrorBoundary({ error, reset, info }: ErrorComponentProps) {
  const componentStack = info?.componentStack ?? '';
  const message = error instanceof Error ? error.message : String(error);

  // Mirror the on-screen detail to the console in dev so it can be copied
  // and so it's captured even if the boundary itself re-renders.
  useEffect(() => {
    if (import.meta.env.DEV) {
      console.error(
        '[RouteErrorBoundary] caught:\n',
        error,
        '\n\nCOMPONENT STACK:\n',
        componentStack,
      );
    }
  }, [error, componentStack]);

  return (
    <div className="flex h-full min-h-[60vh] w-full items-start justify-center p-6">
      <div className="w-full max-w-3xl rounded-lg border bg-card p-5 shadow-sm">
        <div className="flex items-start gap-3">
          <span className="mt-0.5 inline-flex size-9 shrink-0 items-center justify-center rounded-full bg-destructive/10 text-destructive">
            <AlertTriangleIcon className="size-[18px]" />
          </span>
          <div className="min-w-0 flex-1">
            <h2 className="text-[15px] font-semibold tracking-tight text-foreground">
              Something went wrong
            </h2>
            <p className="mt-0.5 break-words text-[12.5px] text-muted-foreground">
              {message || 'An unexpected error occurred while rendering this view.'}
            </p>

            <div className="mt-4 flex items-center gap-2">
              <RefreshButton
                variant="default"
                onRefresh={reset}
                icon={RotateCcwIcon}
                iconClassName="size-3.5"
                label="Try again"
              />
              <RefreshButton
                variant="outline"
                onRefresh={() => window.location.reload()}
                iconClassName="size-3.5"
                label="Reload page"
              />
            </div>

            {import.meta.env.DEV && componentStack && (
              <details className="mt-4" open>
                <summary className="cursor-pointer select-none text-[11.5px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Component stack (dev only)
                </summary>
                <pre className="mt-2 max-h-[40vh] overflow-auto rounded-md bg-muted/60 p-3 text-[11px] leading-snug text-foreground">
                  {componentStack.trim()}
                </pre>
              </details>
            )}

            {import.meta.env.DEV && error instanceof Error && error.stack && (
              <details className="mt-2">
                <summary className="cursor-pointer select-none text-[11.5px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Error stack (dev only)
                </summary>
                <pre className="mt-2 max-h-[30vh] overflow-auto rounded-md bg-muted/60 p-3 text-[11px] leading-snug text-foreground">
                  {error.stack}
                </pre>
              </details>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
