// The one refresh/retry/reload button. Every "spin the arrows and
// refetch" affordance in the app routes through here so the motion,
// the minimum-spin duration, and the hover rotate stay identical
// everywhere — whether the surface is a toolbar Refresh, an error-state
// Retry, a query-driven icon button, or a full page reload.
//
// Two ways to drive the spin:
//   • Self-managed (default) — `onRefresh` may return a promise; the
//     icon spins until it settles, but never for less than `minSpinMs`,
//     so an instant (cached / 304) refetch still reads as a deliberate
//     gesture rather than a flicker.
//   • Controlled — pass `spinning` (e.g. a React Query `isFetching`) and
//     the caller owns the spin; the internal timer is skipped.
//
// Idle, the icon nudges 90° on hover (the established affordance). Both
// the spin and the hover rotate are pure CSS, so there's no motion-lib
// memoization caveat to worry about.

import * as React from 'react';
import { RefreshCwIcon } from 'lucide-react';
import { Button, type ButtonProps } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export interface RefreshButtonProps extends Omit<ButtonProps, 'onClick'> {
  /** Fired on click. May return a promise; in self-managed mode the icon
   *  spins until it settles (min `minSpinMs`). Tolerates `undefined` so it
   *  can wrap optional handlers. */
  onRefresh?: () => unknown | Promise<unknown>;
  /** Controlled spin state. When provided, the button spins iff this is
   *  true and the self-managed timer is skipped. */
  spinning?: boolean;
  /** Button label. Omit for an icon-only button. Defaults to "Refresh". */
  label?: React.ReactNode;
  /** Icon component (e.g. RotateCcwIcon for reset/retry semantics).
   *  Defaults to RefreshCwIcon. */
  icon?: React.ComponentType<{ className?: string }>;
  /** Minimum self-managed spin duration in ms. */
  minSpinMs?: number;
  /** Extra classes for the icon (e.g. "size-3.5" to override the default). */
  iconClassName?: string;
}

const RefreshButton = React.forwardRef<HTMLButtonElement, RefreshButtonProps>(
  (
    {
      onRefresh,
      spinning: controlledSpinning,
      label = 'Refresh',
      icon: Icon = RefreshCwIcon,
      minSpinMs = 600,
      iconClassName,
      variant = 'ghost',
      size = 'sm',
      disabled,
      className,
      ...rest
    },
    ref,
  ) => {
    const [selfSpinning, setSelfSpinning] = React.useState(false);
    const isControlled = controlledSpinning !== undefined;
    const spinning = isControlled ? controlledSpinning : selfSpinning;

    const handleClick = () => {
      const result = onRefresh?.();
      if (isControlled) return;
      setSelfSpinning(true);
      void Promise.allSettled([
        Promise.resolve(result),
        new Promise((r) => setTimeout(r, minSpinMs)),
      ]).then(() => setSelfSpinning(false));
    };

    return (
      <Button
        ref={ref}
        variant={variant}
        size={size}
        onClick={handleClick}
        disabled={disabled ?? spinning}
        className={cn('group', className)}
        {...rest}
      >
        <Icon
          className={cn(
            'transition-transform',
            spinning ? 'animate-spin' : 'group-hover:rotate-90',
            iconClassName,
          )}
        />
        {label}
      </Button>
    );
  },
);
RefreshButton.displayName = 'RefreshButton';

export { RefreshButton };
