interface Props {
  owner: string;
  repo: string;
  number: number;
  onBack?: () => void;
  /** Label rendered in the breadcrumb back-link inside PRHeader.
   * Defaults to "Inbox" when omitted. */
  backLabel?: string;
  /** Read-only "demo" mode (AFK plan 22, `?pr=` deep-link). When true,
   * every write affordance is hidden/disabled - review submission, the
   * approve/request-changes verdict, merge + lifecycle controls, the
   * conversation composer, and per-file mark-as-viewed. Diffs,
   * conversation, commits, and checks still render. A small "Demo
   * (read-only)" badge is shown so the mode is obvious. */
  readOnly?: boolean;
  initialTab?: PRTab;
  /** Fired when the user switches tabs - the router persists this in
   * the URL search params so a reload returns to the same tab. */
  onTabChange?: (tab: PRTab) => void;
  /** Files sub-state lifted to the URL (AFK plan 26). `diff` (split |
   * inline) and `commits` (comma-joined commit-filter SHAs) are read
   * from the PR route's search params and written back on change.
   * Undefined when rendered outside the router (legacy / tests). */
  diffMode?: DiffMode;
  onDiffModeChange?: (mode: DiffMode) => void;
  commits?: string;
  onCommitsChange?: (commits: string | undefined) => void;
  /** Commits tab → Files-changed jump scoped to a single commit.
   * Performs ONE navigation that sets `tab=changes` + `commits=<sha>`
   * together (the router owns navigate; doing it in two chained
   * replace-navigations races on the stale search snapshot). */
  onScopeToCommit?: (sha: string) => void;
  /** Changes-tab inputs lifted to the URL (controlled-with-fallback,
   * like `commits`): `fileFilter` = file-rail "Filter files" text;
   * `diffSearch` = "Search diff content" text. */
  fileFilter?: string;
  onFileFilterChange?: (q: string | undefined) => void;
  diffSearch?: string;
  onDiffSearchChange?: (q: string | undefined) => void;
  /** File-rail mode (tree | list) lifted to the URL (`?rail=`). */
  railMode?: "tree" | "list";
  onRailModeChange?: (mode: "tree" | "list") => void;
  /** Live diff anchor writer - fires when the user clicks a line or a
   * comment in the diff. Writes apath/aline/aside/acid to the URL. */
  onAnchorChange?: (anchor: DiffAnchor | null) => void;
  /** Deep-link anchor - passed down to ChangesTab as `initialPath`
   * (plus the optional line/commentId for the planned flash-highlight
   * pass). Originates from the Inbox · Comments tab. */
  initialAnchor?: {
    path: string;
    line?: number | null;
    diffSide?: "LEFT" | "RIGHT" | null;
    commentId?: number;
  };
  fluid?: boolean;
  width?: number;
  height?: number;
}

/** Focused-PR poll cadence per ADR 0005. The "live comments on PR
 * lines" feel works at this speed for human-driven reply traffic;
 * any tighter and we'd burn rate limit unnecessarily. Applied via
 * TanStack's refetchInterval on the queries that can legitimately
 * change while the PR is open (metadata, comments, threads). */
const FOCUSED_POLL_MS = 15_000;

/** Stable empty-contents fallback. MUST be a shared module-level value,
 * not an inline `new Map()` per render: `fileContents` flows into
 * ChangesTab's `activeContents` → the `matchSummary` memo → the
 * search-summary effect, which lifts state to PRDetailScreen. A fresh
 * Map identity each render makes that chain recompute and re-fire every
 * render → setState → re-render → "Maximum update depth exceeded". An
 * empty map is never mutated, so one shared instance is safe. */
const EMPTY_FILE_CONTENTS: Map<string, PRFileContents> = new Map();

/** Shared empty pending-comment list - same stable-identity reason as
 * EMPTY_FILE_CONTENTS, so the threadIndex memo doesn't churn when the
 * viewer has no pending review (the common case). */
const EMPTY_PENDING_COMMENTS: readonly GHReviewComment[] = [];

/** How long to consider files + file-contents fresh. They only change
 * on a force-push (head SHA change), which the metadata poll picks
 * up - and when it does, we use queryClient.invalidateQueries to
 * mark these stale. Until then there's no point repolling. */
const STABLE_PER_OPEN_MS = 24 * 60 * 60 * 1000;

/**
 * A query whose retry has *paused after a failure* never reaches a
 * terminal `error` state on its own - it sits at `status:'pending'` /
 * `fetchStatus:'paused'` with the failure stashed in `failureReason`,
 * forever. TanStack pauses an in-flight retry whenever it can't
 * continue, and `canContinue()` (query-core retryer) gates on
 * `focusManager.isFocused()` *regardless of networkMode* - so a
 * backgrounded/hidden tab pauses the retry even with networkMode
 * 'always' (and a true browser-offline pauses it under the default
 * 'online' mode too). During a GitHub 5xx outage the Changes tab's
 * files/contents query lands exactly here: the "Resolving changed
 * files" skeleton hangs indefinitely because the inline outage card
 * gates on `error`, which stays null while paused.
 *
 * Treat "paused, after at least one failure, with no data yet" as a
 * settled outage and surface the stashed failure so the connectivity /
 * outage card renders instead of an infinite spinner. This is
 * self-correcting: when the tab refocuses (or the browser reconnects)
 * the retry resumes and either succeeds - data replaces the card - or
 * reaches a real terminal `error`. Returns null (not stuck) when the
 * pause is benign: an initial fetch deferred while hidden BEFORE any
 * failure has `failureCount === 0`, so it never trips this.
 */
function stuckPausedError(q: {
  fetchStatus: string;
  failureCount: number;
  failureReason: unknown;
  data: unknown;
}): Error | null {
  if (q.fetchStatus === 'paused' && q.failureCount > 0 && q.data === undefined) {
    return q.failureReason instanceof Error ? q.failureReason : null;
  }
  return null;
}

export function PRDetailScreen({
  owner,
  repo,
  number,
  onBack,
  backLabel,
  readOnly = false,
  initialTab = "changes",
  onTabChange,
  diffMode,
  onDiffModeChange,
  commits,
  onCommitsChange,
  onScopeToCommit,
  fileFilter,
  onFileFilterChange,
  diffSearch,
  onDiffSearchChange,
  railMode,
  onRailModeChange,
  onAnchorChange,
  initialAnchor,
  fluid = false,
  width = 1320,
  height = 900,
}: Props) {
  // Collapsing "landing page" header: the active tab's scrollTop drives the
  // full header scrolling away while the compact header slides down. The
  // listener attaches to the tab-body container below (callback ref).
  const headerScroll = useHeaderScroll();
  const [tab, _setTab] = useState<PRTab>(initialTab);
  const setTab = (t: PRTab) => {
    // Optimistic local update for instant tab feedback; the URL is the
    // source of truth (onTabChange navigates → initialTab prop updates
    // → the sync effect below reconciles). Without the optimistic set
    // the active tab would lag one navigation tick.
    _setTab(t);
    onTabChange?.(t);
  };
  // Keep the active tab in sync with the URL search param. Covers
  // browser back/forward + deep-links, where initialTab changes
  // without setTab having run.
  useEffect(() => {
    _setTab(initialTab);
  }, [initialTab]);
  // On tab switch the new tab restores its own scroll position without
  // firing a scroll event - re-read it so the header reflects it.
  const headerResync = headerScroll.resync;
  useEffect(() => {
    const id = window.setTimeout(() => headerResync(), 60);
    return () => window.clearTimeout(id);
  }, [tab, headerResync]);
  // Jump to the Changes tab with the diff scoped to a single commit.
  // Shared by the Commits tab's "View diff" rows AND the Conversation
  // timeline's commit rows. Routes through the parent's single-navigation
  // helper (tab + commits set together) when available so the two URL
  // params don't race; falls back to the optimistic local setTab +
  // onCommitsChange for the legacy/non-router path.
  const scopeToCommitInChanges = (sha: string) => {
    setTab("changes");
    if (onScopeToCommit) onScopeToCommit(sha);
    else onCommitsChange?.(sha);
  };
  // Keep the Changes tab mounted once visited so its diff + file-list
  // scroll positions survive tab switches (the diff is heavy to rebuild
  // and its virtualized scroll can't be reliably restored after an
  // unmount). It's hidden via CSS when another tab is active; the
  // `active` prop gates its keyboard shortcuts so they don't fire in
  // the background.
  const [changesVisited, setChangesVisited] = useState(
    initialTab === "changes",
  );
  // Likewise keep the Conversation (description) and Commits tabs mounted
  // once visited so their scroll positions survive tab switches. Both
  // lists are virtualized (react-virtuoso), so - like the diff - an exact
  // scroll restore after an unmount isn't reliable; we keep them mounted
  // and hide them when inactive instead. Description is the default tab,
  // so it's usually visited from the first render.
  const [descriptionVisited, setDescriptionVisited] = useState(
    initialTab === "description",
  );
  const [commitsVisited, setCommitsVisited] = useState(
    initialTab === "commits",
  );
  useEffect(() => {
    if (tab === "changes") setChangesVisited(true);
    if (tab === "description") setDescriptionVisited(true);
    if (tab === "commits") setCommitsVisited(true);
  }, [tab]);
  const [modalOpen, setModalOpen] = useState(false);
  // Focus mode (⇧M) - two INDEPENDENT toggles, one per tab:
  //  • Conversation "Focus: comments" shows the timeline as comments-only.
  //  • Changes "Focus: Code" hides inline review threads in the diff.
  // Each has its own per-PR localStorage flag (NOT the URL - a private
  // viewing preference, not a shareable part of the route), so toggling
  // one tab's Focus never touches the other, and each PR remembers how
  // you last read it. Refs keep the ⇧M functional toggles reading the
  // latest value despite the []-dep keydown effect below.
  const [commentsFocus, setCommentsFocusState] = useState(() =>
    owner && repo && number
      ? getConversationFocus(owner, repo, number)
      : false,
  );
  const [codeFocus, setCodeFocusState] = useState(() =>
    owner && repo && number ? getCodeFocus(owner, repo, number) : false,
  );
  const commentsFocusRef = useRef(commentsFocus);
  commentsFocusRef.current = commentsFocus;
  const codeFocusRef = useRef(codeFocus);
  codeFocusRef.current = codeFocus;
  const setCommentsFocus = (next: boolean | ((v: boolean) => boolean)) => {
    const val =
      typeof next === "function" ? next(commentsFocusRef.current) : next;
    setCommentsFocusState(val);
    if (owner && repo && number) {
      setConversationFocus(owner, repo, number, val);
    }
  };
  const setCodeFocus = (next: boolean | ((v: boolean) => boolean)) => {
    const val = typeof next === "function" ? next(codeFocusRef.current) : next;
    setCodeFocusState(val);
    if (owner && repo && number) {
      persistCodeFocus(owner, repo, number, val);
    }
  };
  // The header pill + ⇧M act on whichever tab you're viewing: the
  // Conversation tab drives comments-focus, every other tab drives
  // code-focus (matching FocusToggle's mode = tab==='description'
  // ? 'comments' : 'code').
  const tabFocusActive = tab === "description" ? commentsFocus : codeFocus;
  const toggleTabFocus = () =>
    tab === "description"
      ? setCommentsFocus((v) => !v)
      : setCodeFocus((v) => !v);
  // The keydown effect below has [] deps, so it closes over a stale
  // `tab`; route ⇧M through a ref that always points at the latest
  // toggle (rebuilt each render with the current tab + setters).
  const toggleTabFocusRef = useRef(toggleTabFocus);
  toggleTabFocusRef.current = toggleTabFocus;
  // Conversation comment-focus VARIANT: "New comments" (only threads
  // awaiting the viewer's reply) vs the default "All comments". Persisted
  // per PR, remembered across toggling Focus - but it only takes EFFECT
  // while Focus is active (see `onlyUnreplied` below), so turning Focus
  // off restores the full timeline regardless of the variant.
  const [newCommentsFocus, setNewCommentsFocusState] = useState(() =>
    owner && repo && number ? getNewCommentsFocus(owner, repo, number) : false,
  );
  const selectCommentFocus = (isNew: boolean) => {
    setNewCommentsFocusState(isNew);
    if (owner && repo && number) {
      setNewCommentsFocus(owner, repo, number, isNew);
    }
    // Choosing a variant from the menu means you want that focus - turn
    // comments Focus on so the choice takes effect immediately.
    setCommentsFocus(true);
  };
  useEffect(() => {
    setNewCommentsFocusState(
      owner && repo && number ? getNewCommentsFocus(owner, repo, number) : false,
    );
  }, [owner, repo, number]);
  // The "New comments" filter is only live while comments Focus is on.
  const onlyUnreplied = commentsFocus && newCommentsFocus;
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // Match the design's ⇧M (Shift+M). Accept either case in
      // `e.key` since some virtual keyboards / automation tools emit
      // 'm' even when Shift is held. Skip when an input/textarea/
      // contenteditable is focused so typing a capital M into the
      // composer doesn't toggle.
      const isM = e.key === 'M' || e.key === 'm';
      if (!isM || !e.shiftKey || e.metaKey || e.ctrlKey || e.altKey) {
        return;
      }
      const t = e.target as HTMLElement | null;
      if (t) {
        const tag = t.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
        if (t.isContentEditable) return;
      }
      e.preventDefault();
      toggleTabFocusRef.current();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);
  // On navigation to a different PR, re-seed both focus toggles from
  // THAT PR's persisted values (each PR remembers its own on/off).
  useEffect(() => {
    setCommentsFocusState(
      owner && repo && number
        ? getConversationFocus(owner, repo, number)
        : false,
    );
    setCodeFocusState(
      owner && repo && number ? getCodeFocus(owner, repo, number) : false,
    );
  }, [owner, repo, number]);
  // v2 #55 - when the user clicks an annotation in the Checks tab,
  // we stash {path, line} here and switch to the Changes tab. The
  // ChangesTab reads initialPath from this and (TODO) scrolls to
  // the line via CodeView.scrollTo.
  const [jumpTarget, setJumpTarget] = useState<{
    path: string;
    line: number | null;
    diffSide?: 'LEFT' | 'RIGHT' | null;
  } | null>(null);
  // Conversation-tab jump target - a PR-level review summary the reviewer
  // HoverCard's "View comment" action wants to scroll to + flash in the
  // timeline. A fresh object per click (identity changes) so re-clicking
  // the same reviewer re-fires DescriptionTab's scroll effect.
  const [convJumpTarget, setConvJumpTarget] = useState<{
    reviewId: number;
  } | null>(null);
  // Reset on PR navigation so a stale target from a previous PR
  // doesn't fire when switching.
  useEffect(() => {
    setJumpTarget(null);
    setConvJumpTarget(null);
  }, [owner, repo, number]);
  // File-contents fetch progress lives outside TanStack - it's a
  // side-channel from the queryFn, not part of the query's result.
  // Used by the SubToolbar's "computing diffs… N/M" indicator.
  const [contentsProgress, setContentsProgress] = useState({
    resolved: 0,
    total: 0,
  });
  // Streaming partial file contents - populated batch-by-batch as
  // the GraphQL worker pool resolves. Lets the diff render
  // progressively: ~the first 20 files appear after ~1s, the rest
  // fill in as each batch lands. Without this we'd wait ~25s for the
  // whole spike PR before any diff body appears.
  //
  // Reset on PR navigation OR head/base SHA change (force-push) so
  // we don't briefly show contents from the previous head while the
  // refetch is in flight.
  const [partialContents, setPartialContents] = useState<
    Map<string, PRFileContents>
  >(new Map());
  // Coalesce the per-batch streaming updates. fetchPRFileContents lands
  // ~57 batches on a 587-file PR, and every onBatch/onProgress used to
  // setState immediately - 57 full re-renders of the PR tree during the
  // first minute a big PR is open, which measured as the single worst
  // main-thread siege (the diff list froze for whole seconds while
  // scrolling). First batch flushes instantly (progressive render keeps
  // its "first files in ~1s" feel), the rest coalesce into one state
  // update per 400ms window. The final state always lands regardless:
  // the trailing flush carries the last snapshot, and the finished query
  // result takes over via contentsQuery.data anyway.
  const pendingStreamRef = useRef<{
    progress: { resolved: number; total: number } | null;
    snapshot: Map<string, PRFileContents> | null;
  }>({ progress: null, snapshot: null });
  const streamFlushTimerRef = useRef<number | null>(null);
  const flushStream = useCallback(() => {
    streamFlushTimerRef.current = null;
    const pending = pendingStreamRef.current;
    if (pending.progress) setContentsProgress(pending.progress);
    if (pending.snapshot) setPartialContents(pending.snapshot);
    pendingStreamRef.current = { progress: null, snapshot: null };
  }, []);
  const scheduleStreamFlush = useCallback(() => {
    // Leading + trailing: the first batch after a quiet period flushes
    // immediately, then a 400ms window absorbs the burst; the trailing
    // timer carries whatever accumulated (no-op when nothing did).
    if (streamFlushTimerRef.current != null) return;
    flushStream();
    streamFlushTimerRef.current = window.setTimeout(flushStream, 400);
  }, [flushStream]);
  useEffect(
    () => () => {
      if (streamFlushTimerRef.current != null) {
        window.clearTimeout(streamFlushTimerRef.current);
        streamFlushTimerRef.current = null;
      }
    },
    [],
  );
  const queryClient = useQueryClient();
  // Pre-compute the diff on arrival (#4). The PR opens on the Conversation
  // tab by default, so without this the heavy diff build (buildDiffItems +
  // tokenization) doesn't start until the user first clicks Changes -
  // leaving them waiting then. Instead, once the shell has painted and the
  // browser goes idle, mount ChangesTab eagerly: it renders hidden
  // (content-visibility:hidden) and builds the diff in the background at
  // low priority via the SAME mounted-but-hidden machinery a manual visit
  // uses, so the first switch to Changes is instant. We also warm the
  // commit list the range-picker + Commits tab need - a single GraphQL
  // read, deferred to idle so it never competes with the critical contents
  // fetch. Idle-gated (not on mount) to keep the Conversation's first paint
  // jank-free; fires once, then this effect no-ops.
  useEffect(() => {
    if (changesVisited) return;
    const prewarm = () => {
      setChangesVisited(true);
      void queryClient.prefetchQuery({
        ...prCommitsStatsOptions(owner, repo, number),
        staleTime: 60_000,
      });
    };
    const ric = window.requestIdleCallback;
    if (!ric) {
      const t = window.setTimeout(prewarm, 200);
      return () => window.clearTimeout(t);
    }
    const handle = ric(prewarm, { timeout: 2000 });
    return () => window.cancelIdleCallback(handle);
  }, [changesVisited, queryClient, owner, repo, number]);
  // Dev-only: log the PR query graph's fetch/success/invalidate stream
  // so the 15s meta tick + its downstream cascade are observable in the
  // console. No-op in production. (`localStorage['pyor:pollDebug']='0'`
  // to silence.)
  usePrPollDebug(owner, repo, number);
  // Per-file manual collapse overrides. Layers on top of viewedState
  // so the user can keep a viewed file expanded for re-review or
  // hand-collapse an unviewed one to dismiss it from the scroll.
  // Pure UI state - not synced to GitHub.
  const collapseState = useCollapseState(owner, repo, number);

  // Diff-search hit totals, reported up from ChangesTab (which computes
  // them from the parsed patches) so the tab-bar toolbar can show the
  // "N in M files" search counter.
  const [searchSummary, setSearchSummary] = useState<{
    count: number;
    fileCount: number;
  }>({ count: 0, fileCount: 0 });
  // Diff-search "current hit" index, owned here so the tab-strip search box
  // (CompactChangesToolbar, a sibling of ChangesTab) can drive prev/next +
  // the "X of N" counter. ChangesTab consumes it and runs the scroll-to.
  // Reset to the first hit whenever the query changes.
  const [searchMatchIndex, setSearchMatchIndex] = useState(0);
  useEffect(() => {
    setSearchMatchIndex(0);
  }, [diffSearch]);
  // Keep the index in range when the hit count shrinks WITHOUT a query change
  // (e.g. contents finish streaming and a fallback match drops). Otherwise a
  // stale large index would point past the match list (no scroll) and the box
  // would read "Hit 6 of 3" until the next edit.
  useEffect(() => {
    const n = searchSummary.count;
    setSearchMatchIndex((i) => (n > 0 && i > n - 1 ? n - 1 : i));
  }, [searchSummary.count]);
  // Wrap-around prev/next over the current hit count (from the summary
  // ChangesTab publishes). No-ops when there are no matches.
  const goToMatch = useCallback(
    (delta: number) => {
      setSearchMatchIndex((i) => {
        const n = searchSummary.count;
        if (n <= 0) return 0;
        return (((i + delta) % n) + n) % n;
      });
    },
    [searchSummary.count],
  );

  // "Review with AI" trigger, published up from ChangesTab's single useAiHints
  // instance so the collapsed (compact) PR header can ride the same control
  // (ADR 0026 / hdr-compact-*). Null when AI is off or off the Changes tab.
  const [aiTrigger, setAiTrigger] = useState<AiCompactTrigger | null>(null);

  // Five queries that compose into the full PR detail state. Order
  // matters only for the contents query, which is `enabled`-gated on
  // its dependencies (PR metadata + files list).
  //
  // Polling shape per ADR 0005:
  //   - PR / comments / threads: refetch every 15s (the things that
  //     change while a reviewer is reading).
  //   - Files / contents: 24h staleTime - they only change on
  //     force-push, which the PR-metadata poll surfaces via head.sha;
  //     a later commit will invalidate-on-sha-change explicitly.

  // queryKey + queryFn pairs live in github/prQueries.ts so they're
  // shared with PullRequestsScreen's hover-prefetch - same keys = same
  // cache slot, so a prefetched value from Inbox hover lands in
  // this useQuery's subscription on mount.
  // `placeholderData: (prev) => prev` on the per-PR queries (AFK plan
  // 16): when the queryKey changes as the user navigates PR→PR, the
  // previous PR's data stays on screen for the transition instead of
  // the full-page LoadingPane - `prQuery.isPending` flips false the
  // moment placeholder (or persisted) data exists, so no spinner.
  // SHA-keyed queries (mergeBase, contents) deliberately DON'T get this
  // - placeholderData across a force-push would surface wrong-SHA blobs.
  const prQuery = useQuery({
    ...prMetaOptions(owner, repo, number),
    refetchInterval: FOCUSED_POLL_MS,
    // Keep the heartbeat ticking every 15s even when the window is
    // blurred / backgrounded (TanStack pauses refetchInterval on blur by
    // default). It's an ETag-conditional REST read, so a background tick
    // is a 304 at zero rate-limit cost - and it means a PR left open on a
    // second monitor stays live without needing a refocus.
    refetchIntervalInBackground: true,
    // Refetch the PR meta on every window focus, not just when the 60s
    // staleTime has elapsed: returning to the tab should reflect a merge
    // / status change made elsewhere immediately, regardless of the poll
    // timer. `'always'` overrides the global staleTime-gated focus refetch.
    refetchOnWindowFocus: 'always',
    placeholderData: (prev) => prev,
  });

  // The changed-files list polls directly every 15s. Like `comments`
  // it's a REST + ETag read (free 304 on a no-op tick), so this no longer
  // leans on the head.sha effect / metadata fingerprint to notice a new
  // commit's file set. A 304 returns the identical list ⇒ `filesShape`
  // (below) is unchanged ⇒ the EXPENSIVE contents fetch is NOT re-run; it
  // only re-runs when the file set actually changes. The head.sha effect
  // is kept for the force-push banner + the SHA-keyed contents refetch.
  const filesQuery = useQuery({
    ...prFilesOptions(owner, repo, number),
    refetchInterval: FOCUSED_POLL_MS,
    refetchIntervalInBackground: true,
    refetchOnWindowFocus: 'always',
    placeholderData: (prev) => prev,
  });

  // Review comments + the GraphQL review-thread list used to poll every
  // FOCUSED_POLL_MS. That was wasteful - and ruinous for `threadsQuery`,
  // which is GraphQL: it can't 304, and its nested
  // `reviewThreads(first:100){ comments(first:100) }` shape costs ~100
  // rate-limit points PER fetch, so a 15s timer burned ~24k points/hour
  // from a single open PR and exhausted the 5k/hr GraphQL budget in ~12
  // minutes. Both are now driven by the metadata heartbeat instead (see
  // the fingerprint effect below): the cheap, ETag-conditional `prQuery`
  // poll (free on a 304) detects when `updated_at` / comment counts move
  // and invalidates these explicitly. Net: identical ~15s freshness, but
  // we only pay for the threads query when the PR was actually touched.
  // Review comments poll directly every 15s (ADR 0005's "comments
  // refetch every 15s"). This is a REST + ETag read, so a no-change tick
  // is a 304 at zero rate-limit cost - cheap enough to poll on a blind
  // timer. We deliberately do NOT gate it behind the PR-metadata
  // fingerprint: the PR's `updated_at` / comment counts lag or don't bump
  // promptly for inline review-comment activity (ADR 0019 "Bug 3"), so
  // gating would leave new comments invisible until the next force-push.
  // The EXPENSIVE GraphQL `threadsQuery` stays gated on the fingerprint
  // below - that's the one whose blind polling we're avoiding.
  const commentsQuery = useQuery({
    ...prCommentsOptions(owner, repo, number),
    refetchInterval: FOCUSED_POLL_MS,
    refetchIntervalInBackground: true,
    refetchOnWindowFocus: 'always',
    placeholderData: (prev) => prev,
  });

  const threadsQuery = useQuery({
    ...prThreadsOptions(owner, repo, number),
    staleTime: STABLE_PER_OPEN_MS,
    refetchOnWindowFocus: false,
    placeholderData: (prev) => prev,
  });

  // The authenticated viewer - used to attribute optimistic pending
  // comments (avatar/login) before GitHub confirms them.
  const viewerQuery = useQuery({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    staleTime: Infinity,
  });
  // Counts on the Focus pill so "All comments" vs "Pending comments" read
  // distinctly (total discussions vs threads awaiting your reply). Reads
  // the shared timeline caches - a subscription, not a fetch.
  const commentCounts = useCommentFocusCounts(
    owner,
    repo,
    number,
    viewerQuery.data?.login,
  );

  // Single in-progress review per (owner, repo, number), now backed by
  // GitHub's server pending review (ADR 0019). Replaces the localStorage
  // draft: `draft`/`draftActions` keep the same shape so the dock + submit
  // modal render unchanged, but every mutation hits GitHub optimistically.
  // `pendingReview` folds into the thread index below so pending comments
  // render inline badged "Pending"; `submit`/`discard` drive the modal +
  // dock. Polled with the focused-PR reads so a draft started elsewhere
  // appears without a reload.
  const {
    pendingReview,
    draft,
    actions: draftActions,
    submit: submitReviewNow,
    discard: discardReviewNow,
  } = usePendingReview(
    owner,
    repo,
    number,
    prQuery.data?.head.sha,
    viewerQuery.data
      ? { login: viewerQuery.data.login, avatar_url: viewerQuery.data.avatar_url }
      : undefined,
  );

  // Stable identity of the files list as the contents fetcher sees it.
  // fetchPRFileContents reads filename / status / previous_filename per
  // file (see fetchPRFileContents.ts spec construction) - anything else
  // (additions, deletions, sha) doesn’t affect what gets requested and
  // would just cause needless refetches on no-op polls. Sorted so two
  // identical lists in different order hash the same.
  const filesShape = useMemo(() => {
    if (!filesQuery.data) return null;
    return hashStrings(
      filesQuery.data
        .map(
          (f) => `${f.filename}�${f.status}�${f.previous_filename ?? ""}`,
        )
        .sort(),
    );
  }, [filesQuery.data]);

  // Resolve the merge-base of base.sha and head.sha. GitHub’s PR
  // diff is computed against the merge-base, not the base-branch
  // tip - when the base branch advances independently and those
  // advances overlap with the PR’s edits, the base-tip blob and
  // head blob can be byte-identical for an affected file, which
  // makes the local diff (parseDiffFromFile) compute as empty even
  // though GitHub’s UI shows real changes. Anchoring contents at
  // merge-base mirrors GitHub.
  const mergeBaseQuery = useQuery(
    prMergeBaseOptions(
      owner,
      repo,
      number,
      prQuery.data?.base.sha,
      prQuery.data?.head.sha,
    ),
  );
  const diffBaseSha = mergeBaseQuery.data;

  const contentsQuery = useQuery<Map<string, PRFileContents>>({
    // Keying on head SHA + diff-base (merge-base) SHA + filesShape:
    //  - merge-base (not base.sha) is what GitHub diffs against - see
    //    mergeBaseQuery above. Force-push or base advance that shifts
    //    the merge-base invalidates the cache.
    //  - filesShape closes a race: head.sha flips first on force-push,
    //    so without it `contents` would refetch against the OLD files
    //    list and bake a stale Map (missing newly-added, retaining
    //    removed) into the new cache slot. Once filesQuery refetches
    //    and the shape hash changes, contents refetches against the
    //    right inputs. React Query also aborts the obsolete in-flight
    //    fetch via `signal`.
    queryKey: [
      "pr",
      owner,
      repo,
      number,
      "contents",
      prQuery.data?.head.sha,
      diffBaseSha,
      filesShape,
    ],
    queryFn: ({ signal }) =>
      fetchPRFileContents(
        owner,
        repo,
        filesQuery.data!,
        prQuery.data!.head.sha,
        diffBaseSha!,
        {
          // Progress + partial snapshots feed the coalescer above (one
          // state update per 400ms window) instead of setState per
          // batch - see pendingStreamRef for why.
          onProgress: (resolved, total) => {
            pendingStreamRef.current.progress = { resolved, total };
            scheduleStreamFlush();
          },
          // Stream partial state into React as batches resolve so
          // ChangesTab can render diffs progressively instead of
          // waiting for all ~57 batches to finish before showing any.
          onBatch: (snapshot) => {
            pendingStreamRef.current.snapshot = snapshot;
            scheduleStreamFlush();
          },
          // Cancels the in-flight fetch when the queryKey changes
          // (e.g. filesShape just updated post-force-push) so we don't
          // waste ~25s of GraphQL batches finishing a fetch whose
          // result will be discarded.
          signal,
        },
      ),
    enabled: !!prQuery.data && !!filesQuery.data && !!diffBaseSha,
    staleTime: STABLE_PER_OPEN_MS,
    refetchOnWindowFocus: false,
  });

  // Viewed-state per (PR, path). GitHub is the source of truth per
  // CONTEXT.md - the local store is a cache. The hook hydrates from
  // GitHub on mount via GraphQL viewerViewedState and fires REST
  // mark/unmark mutations on every toggle (fire-and-forget; offline
  // buffer is a v2 follow-up). Threaded headSha so a force-push
  // re-syncs from GitHub (which clears viewed marks automatically).
  const viewedState = useViewedState(owner, repo, number, {
    sync: true,
    headSha: prQuery.data?.head.sha,
  });

  // Unified check rollup for the tab strip ("Checks 18 · 2 failing").
  // Shares the queryKey with PRHeader / the merge box / the Checks tab,
  // so the count, the header strip, and the gate all agree - and it
  // covers commit statuses, not just check-runs.
  const checksQuery = useQuery({
    ...prCheckRollupOptions(owner, repo, number, prQuery.data?.head.sha),
    enabled: !!prQuery.data?.head.sha,
    // Keep the prior rollup on screen while the headSha-keyed key
    // re-resolves (PR→PR nav or force-push) so the tab strip count +
    // Checks tab don't blank to a skeleton mid-transition. (AFK plan 16)
    placeholderData: (prev) => prev,
  });
  const checkCounts = useMemo(() => {
    const checks = checksQuery.data?.checks ?? [];
    return { ...countRollup(checks), total: checks.length };
  }, [checksQuery.data]);

  // 401 → show the auth-expired card, don't silently bounce. Previously
  // any 401 here eagerly called signOut() + redirected before the user
  // understood *why* - so the designed auth-expired surface (FaultChain
  // "GitHub rejected" + diagnostic) never rendered. Now we surface the
  // auth-expired card instead; its "Sign in again" button performs the
  // signOut + navigate to /welcome, so the user sees the explanation
  // first and acts deliberately. Auth expiry breaks the *whole* app (a
  // dead token 401s every query), so it always takes over the full
  // content area as a global card - never the inline diff-pane
  // treatment, which would misleadingly imply the rest of the PR is fine.
  const authExpired = useMemo(() => {
    const errs = [
      prQuery.error,
      filesQuery.error,
      commentsQuery.error,
      threadsQuery.error,
      contentsQuery.error,
    ];
    return errs.some((e) => e instanceof GitHubError && e.status === 401);
  }, [
    prQuery.error,
    filesQuery.error,
    commentsQuery.error,
    threadsQuery.error,
    contentsQuery.error,
  ]);

  // Force-push detection. The PR metadata query polls every
  // FOCUSED_POLL_MS; when it lands a different `head.sha` than we
  // saw last, the diff has shifted under the reviewer's feet. The
  // contents query's queryKey already includes head/base SHAs so
  // it auto-invalidates structurally - but the files list lives
  // under a stable key and would otherwise serve stale data.
  // Invalidate it explicitly here.
  //
  // Per the new design: keep the prior `partialContents` visible
  // (dimmed) while the refetch runs, so the reviewer doesn't lose
  // their place. The banner explains what's happening; the dim is
  // applied inside ChangesTab via `forcePushInfo`.
  const [forcePushInfo, setForcePushInfo] = useState<ForcePushInfo | null>(
    null,
  );
  const lastSeenHeadSha = useRef<string | null>(null);
  useEffect(() => {
    const currentSha = prQuery.data?.head.sha;
    if (currentSha == null) return;
    if (lastSeenHeadSha.current == null) {
      lastSeenHeadSha.current = currentSha;
      return;
    }
    if (lastSeenHeadSha.current !== currentSha) {
      // A moved head SHA means the diff AND the commit list may have
      // changed - a force-push that squashes/rebases/amends rewrites the
      // commit history even when the count is unchanged, so the
      // count-fingerprint path below can't catch it. Invalidate the
      // commit lists here (the Commits tab + range picker read
      // `all-commits-stats`; `commits`/`commits-infinite` are the REST
      // variants) alongside `files`.
      ["files", "commits", "commits-infinite", "all-commits-stats"].forEach(
        (sub) => {
          void queryClient.invalidateQueries({
            queryKey: ["pr", owner, repo, number, sub],
          });
        },
      );
      setForcePushInfo({
        prevSha: lastSeenHeadSha.current,
        newSha: currentSha,
        detectedAt: Date.now(),
      });
      lastSeenHeadSha.current = currentSha;
    }
  }, [prQuery.data?.head.sha, owner, repo, number, queryClient]);

  // ── Metadata heartbeat → selective invalidation ─────────────────
  // `prQuery` polls every FOCUSED_POLL_MS over REST with an ETag, so a
  // no-change tick is a 304 and costs 0 rate-limit points. We use its
  // payload as a change-detector for the EXPENSIVE, non-conditional
  // conversation queries - chiefly the GraphQL review-thread list, which
  // can't 304 and costs ~100 points/fetch - instead of polling each on a
  // blind timer.
  //
  // `updated_at` bumps on essentially any conversation change (new or
  // edited comment, a submitted review, a resolved thread, a label edit);
  // the comment counts catch pure add/delete. `head.sha` (force-push) and
  // the SHA-keyed queries are handled separately above. When the
  // fingerprint moves we invalidate only the conversation sub-keys -
  // never the broad `['pr', owner, repo, number]` prefix, which would
  // also nuke the ~1k-point contents fetch. Most of these are REST (free
  // on a 304); the one genuinely costly refetch - `threadIds` - now fires
  // only when the PR was actually touched.
  const lastConvoFingerprint = useRef<{
    updatedAt: string;
    reviewComments: number;
    comments: number;
    commits: number;
    state: string;
    merged: boolean;
  } | null>(null);
  useEffect(() => {
    const d = prQuery.data;
    if (!d) return;
    const fp = {
      updatedAt: d.updated_at,
      reviewComments: d.review_comments ?? 0,
      comments: d.comments ?? 0,
      commits: d.commits ?? 0,
      state: d.state,
      merged: d.merged_at != null,
    };
    const prev = lastConvoFingerprint.current;
    lastConvoFingerprint.current = fp;
    // First observation for this PR - nothing to diff against yet. Reset
    // to null on PR navigation (effect below) so a new PR's first poll
    // doesn't diff against the previous PR's counts.
    if (!prev) return;
    // Lifecycle state moved (e.g. the PR was closed/merged - by us or by
    // someone else - while we sat on this screen). The lists live under
    // separate `['lens', …]` / `['team','prs', …]` queries with a 60s
    // staleTime, so without this they'd still show the PR as open when the
    // user navigates back inside that window. Mark them stale to refetch.
    if (fp.state !== prev.state || fp.merged !== prev.merged) {
      void invalidatePrLists(queryClient);
    }
    const convoChanged =
      fp.updatedAt !== prev.updatedAt ||
      fp.reviewComments !== prev.reviewComments ||
      fp.comments !== prev.comments;
    if (convoChanged) {
      // The full conversation surface, spread across PRDetailScreen
      // (`comments`, `threadIds`), DescriptionTab (`timeline`, `reviews`,
      // `comments`), and PRHeader (`reviews`, `comments`). The Changes
      // diff, Conversation, and header all share the one `comments` key.
      // invalidateQueries matches by key globally, so one call here
      // refreshes every subscribing component regardless of where it
      // lives. Only `threadIds` is GraphQL; the rest 304 cheaply.
      // `comments` polls on its own timer above, but invalidating it
      // here too is a harmless 304 and makes a fingerprint move refresh
      // it instantly rather than waiting up to 15s. `pendingReview` is
      // the viewer's own server draft - refresh it when the PR sees
      // activity (e.g. a review submitted elsewhere) so its state stays
      // in step. `threadIds` is the one genuinely costly GraphQL refetch
      // we gate behind this fingerprint.
      ['comments', 'pendingReview', 'threadIds', 'timeline', 'reviews'].forEach(
        (sub) => {
        void queryClient.invalidateQueries({
          queryKey: ['pr', owner, repo, number, sub],
        });
      });
    }
    if (fp.commits !== prev.commits) {
      // A new commit changes the file set + diff, not just the commit
      // list - refresh `files` too (contents are head/base-SHA-keyed and
      // re-resolve structurally via the head.sha effect below).
      ['commits', 'commits-infinite', 'all-commits-stats', 'files'].forEach(
        (sub) => {
          void queryClient.invalidateQueries({
            queryKey: ['pr', owner, repo, number, sub],
          });
        },
      );
    }
  }, [prQuery.data, owner, repo, number, queryClient]);

  // Reset the conversation fingerprint when navigating PRs so the first
  // poll of a new PR doesn't diff against the previous PR's counts.
  useEffect(() => {
    lastConvoFingerprint.current = null;
  }, [owner, repo, number]);

  // Clear the banner once the refetch has caught up to the new SHA.
  useEffect(() => {
    if (!forcePushInfo) return;
    if (contentsQuery.data && !contentsQuery.isFetching) {
      // New content for the post-push SHA is fully resolved.
      setForcePushInfo(null);
      // Drop the old partial - its keys may not be in the new file
      // list at all (renames, deletes) so leaving it would confuse
      // ChangesTab's `live` memo on the next render. Also drop any
      // coalesced-but-unflushed snapshot from the aborted stream, or
      // the trailing flush would resurrect old-SHA contents.
      if (streamFlushTimerRef.current != null) {
        window.clearTimeout(streamFlushTimerRef.current);
        streamFlushTimerRef.current = null;
      }
      pendingStreamRef.current = { progress: null, snapshot: null };
      setPartialContents(new Map());
    }
  }, [forcePushInfo, contentsQuery.data, contentsQuery.isFetching]);

  // Reset the streaming partial when navigating between PRs. Same
  // reasoning - old PR's content shouldn't bleed into the new one
  // even for a frame while the new fetch is in flight. (Including a
  // pending coalesced flush from the previous PR's stream.)
  useEffect(() => {
    if (streamFlushTimerRef.current != null) {
      window.clearTimeout(streamFlushTimerRef.current);
      streamFlushTimerRef.current = null;
    }
    pendingStreamRef.current = { progress: null, snapshot: null };
    setPartialContents(new Map());
    setContentsProgress({ resolved: 0, total: 0 });
  }, [owner, repo, number]);

  // Aliases so the JSX below reads the same as before. Once the
  // migration settles we can remove these and reference the
  // queries directly.
  const pr = prQuery.data ?? null;
  // Mirror GitHub's tab title for an open PR, e.g. "Fix flaky test ·
  // owner/repo#123". Restores to the default on unmount (see the hook).
  useDocumentTitle(pr ? `${pr.title} · ${owner}/${repo}#${number}` : null);
  // Sort files in tree-traversal order (directories first at each
  // level, alphabetical within), matching @pierre/trees' default
  // sort. GitHub's /pulls/{n}/files REST endpoint returns files in
  // pure-alphabetical flat order, which interleaves files and
  // folders at each level (`packages/common/.storybook/preview.js`
  // < `packages/common/jest.config.ts` < `packages/common/src/...`).
  // Sorting here makes the rail order and the diff-pane order
  // match - same file appears at the same index in both surfaces,
  // which keeps j/k navigation and the visible-file marker honest.
  const files = useMemo(
    () => sortFilesTreeOrder(filesQuery.data ?? []),
    [filesQuery.data],
  );

  // Aggregated review-session summary (ADR 0021): ONE event when the user
  // leaves the PR, carrying final viewed-progress + duration - instead of an
  // event per file-viewed toggle. Refs hold the latest values so the unmount
  // cleanup reports the final state (the screen mounts per PR, so owner/repo/
  // number are stable for this mount).
  const reviewOrgId = useOrgIdForOwner(owner);
  const reviewStartRef = useRef(Date.now());
  const reviewSummaryRef = useRef<{ total: number; viewed: number; orgId: number | null }>({
    total: 0,
    viewed: 0,
    orgId: null,
  });
  reviewSummaryRef.current = {
    total: files.length,
    viewed: countViewedFiles(viewedState?.viewed, files),
    orgId: reviewOrgId,
  };
  useEffect(() => {
    const startedAt = reviewStartRef.current;
    return () => {
      const s = reviewSummaryRef.current;
      if (s.total === 0) return; // never loaded a diff → not a real session
      track(
        Events.PrReviewCompleted,
        {
          ...repoProps({ owner, repo, prNumber: number }),
          files_total: s.total,
          files_viewed: s.viewed,
          duration_ms: Date.now() - startedAt,
        },
        { orgId: s.orgId },
      );
    };
    // owner/repo/number are stable for this mount (screen is keyed per PR).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Memoized so the empty-array fallback keeps a stable identity while
  // comments load - `reviewComments` is a dep of the `threadIndex` memo
  // below, and a fresh `[]` each render would recompute threadIndex (and
  // the whole diff `live` pipeline it feeds) on every render. Same safe
  // pattern as CommitsTab; mirrors the EMPTY_FILE_CONTENTS fix.
  const reviewComments = useMemo(
    () => commentsQuery.data ?? [],
    [commentsQuery.data],
  );
  // New-comment surface: detect IDs that appeared in this fetch that
  // weren't in the previous one, then surface a Sonner toast naming
  // who commented. Skipped on the very first fetch (no baseline yet)
  // so opening a 30-comment PR doesn't shower the user with toasts.
  const prevCommentIds = useRef<Set<number> | null>(null);
  useEffect(() => {
    // Baseline only off a REAL comments payload. On reload the (eager)
    // screen mounts BEFORE the persisted cache rehydrates, so this fires
    // once with `commentsQuery.data === undefined` (→ empty list). If we
    // baselined then, the whole restored set would land as "new" the
    // moment it hydrates and flood the user with toasts on every reload.
    // Skip until data exists; the first real set becomes the baseline.
    if (commentsQuery.data === undefined) return;
    const curr = new Set(reviewComments.map((c) => c.id));
    if (prevCommentIds.current == null) {
      prevCommentIds.current = curr;
      return;
    }
    const viewerLogin = viewerQuery.data?.login;
    const newOnes = reviewComments.filter(
      (c) =>
        !prevCommentIds.current!.has(c.id) &&
        // Don't toast the viewer about their own comment - they just
        // posted it; a "you commented" snackbar is noise.
        c.user.login !== viewerLogin,
    );
    prevCommentIds.current = curr;
    if (newOnes.length === 0) return;
    // Clicking the toast jumps to the comment in the Changes diff.
    const jumpTo = (c: (typeof newOnes)[number]) => {
      setTab("changes");
      setJumpTarget({
        path: c.path,
        line: c.line ?? c.original_line ?? null,
        diffSide: c.side ?? null,
      });
    };
    if (newOnes.length === 1) {
      const c = newOnes[0];
      toast.message(`${c.user.login} commented`, {
        description: c.body.slice(0, 140) + (c.body.length > 140 ? "…" : ""),
        action: { label: "View", onClick: () => jumpTo(c) },
      });
    } else {
      const authors = Array.from(
        new Set(newOnes.map((c) => c.user.login)),
      ).slice(0, 3);
      toast.message(
        `${newOnes.length} new comments from ${authors.join(", ")}`,
        { action: { label: "View", onClick: () => jumpTo(newOnes[0]) } },
      );
    }
    // Keyed on `data`, not `dataUpdatedAt`: structural sharing keeps the
    // data identity stable across no-op 15s polls (304s), so this only
    // re-runs when the comment list actually changed. dataUpdatedAt bumps
    // on EVERY successful fetch, which both ran this effect needlessly
    // and - worse - subscribed this whole screen to a per-poll render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [commentsQuery.data]);
  // Memoized for the same reason as `reviewComments` above - it's the
  // other `threadIndex` dep, so a fresh `[]` each render would churn.
  const resolvableThreads = useMemo(
    () => threadsQuery.data ?? [],
    [threadsQuery.data],
  );
  // Effective contents: prefer the finalized query result (which
  // covers the "rehydrated from IndexedDB cache" case - instant on
  // re-open of a previously-reviewed PR), else fall back to the
  // streaming partial that grows batch-by-batch during a cold
  // fetch. ChangesTab's `live` useMemo re-runs whenever this
  // reference changes; new files in the Map → new diff bodies
  // appear without a full re-render of the file list.
  const fileContents =
    contentsQuery.data ??
    (partialContents.size > 0 ? partialContents : EMPTY_FILE_CONTENTS);
  const filesProgress = files.length;
  // Only block the whole shell on PR metadata. Once that arrives we
  // know the title/header/tabs and can render them immediately -
  // files + comments + contents stream into their own slots without
  // hiding the chrome behind a full-page spinner. This is what makes
  // a slow-network PR open feel "alive" instead of "frozen for 10s".
  //
  // `isRestoring`: the IndexedDB persister rehydrates the cache
  // ASYNCHRONOUSLY after the tree first mounts - during that window
  // every query reports `pending` even for a PR that IS in the warm
  // cache. Gating the skeleton on it would flash the full LoadingPane on
  // every reload before the cache lands. While restoring we don't yet
  // know if this PR is cold, so we hold the bare window chrome (no
  // skeleton); the instant restore resolves, a cached PR paints straight
  // to content and a genuinely-cold one falls through to the skeleton.
  const isRestoring = useIsRestoring();
  const loading = prQuery.isPending && !isRestoring;
  // Effective files/contents errors: a real terminal `error`, OR the
  // failure stashed on a retry that paused (hidden tab / offline) and
  // would otherwise never settle. See stuckPausedError - this is what
  // keeps the Changes-tab outage card from hanging on its skeleton.
  const filesError = filesQuery.error ?? stuckPausedError(filesQuery);
  const contentsError = contentsQuery.error ?? stuckPausedError(contentsQuery);
  // Don't keep showing the loading skeleton once we've settled on an
  // outage - a paused-after-failure query is still technically `pending`
  // but it's not going to resolve until the tab refocuses.
  // `data === undefined` guard: without it this flag flipped true on
  // every 15s background poll (isFetching), churning a prop that
  // threads through ChangesTab → LiveDiffPane → DiffBody and forcing
  // the whole diff chain to re-render per tick for a skeleton that
  // only ever shows when there are no items. Once data exists the
  // flag is stably false; the cold load (isPending) and the
  // no-data-yet refetch keep their skeleton.
  const isFilesLoading =
    !filesError &&
    (filesQuery.isPending ||
      (filesQuery.data === undefined && filesQuery.isFetching));
  const error =
    prQuery.error instanceof Error
      ? prQuery.error.message
      : filesQuery.error instanceof Error
        ? filesQuery.error.message
        : null;
  // "Last synced" timestamp for the error/outage panes. Computed ONLY
  // while an error is showing, and frozen (memo) while it persists: a
  // live subscription to dataUpdatedAt would re-render this whole
  // screen on every successful 15s poll just to keep a timestamp fresh
  // on panes that aren't even mounted. The status bar's live "polled
  // Ns ago" readout subscribes by itself via usePrLastPolledAt.
  const anyPrError = authExpired || !!error || !!filesError || !!contentsError;
  const lastSyncedAt = useMemo(
    () =>
      anyPrError ? getPrLastPolledAt(queryClient, owner, repo, number) : null,
    [anyPrError, queryClient, owner, repo, number],
  );

  // Group flat comment list into per-line threads so the Changes tab
  // can attach annotations to the matching diff lines. The GraphQL
  // thread index gets folded in here so each thread carries its
  // graphqlNodeId + isResolved for the Resolve button.
  // Pending review comments (ADR 0019) are merged into the SAME flat
  // list before threading: a pending head comment forms its own thread;
  // a pending reply chains onto its published head via in_reply_to_id
  // and renders under it, badged Pending. Tagged `status:'pending'` so
  // GhComment knows to badge + dispatch edits/deletes to GraphQL.
  const pendingComments = pendingReview?.comments ?? EMPTY_PENDING_COMMENTS;
  const threadIndex = useMemo(
    () =>
      buildThreadIndex(
        pendingComments.length > 0
          ? [...reviewComments, ...pendingComments]
          : reviewComments,
        resolvableThreads,
      ),
    [reviewComments, pendingComments, resolvableThreads],
  );
  // (PR title + number used to live in the macOS titlebar; the
  // redesign moved them into PRHeader's breadcrumb row, so neither
  // variable is needed here anymore.)

  // Wrap the PR view in the WorkerPoolContextProvider so @pierre/diffs
  // moves Shiki tokenization off the main thread. A shared pool of
  // workers (default size 8) is set up once per PR-detail mount;
  // CodeView picks the context up automatically. Worker is bundled
  // via Vite's ?worker query in src/pr/changes/diffsWorker.ts.
  //
  // Seed `highlighterOptions` with the user's saved theme +
  // lineDiffStyle so the worker pool's initial renderOptions match
  // their pref. Without this, the pool would init with the lib's
  // default (pierre-dark / word-alt), the first paint would
  // highlight against the wrong theme, then snap to the saved one
  // once LiveDiffPane's setRenderOptions effect fires. The pool is a
  // singleton (getOrCreateWorkerPoolSingleton) so this only runs the
  // very first time it's constructed in a session - but that's
  // exactly when the flash would otherwise be visible.
  return (
    <ReviewLayout
      width={width}
      height={height}
      fluid={fluid}
      // PR detail moved every titlebar concern into the PRHeader
      // breadcrumb row, so the titlebar is hidden chrome. We still mount
      // the toolbar (in an sr-only wrapper, via PyorWindow) so the hidden
      // GitHub-URL anchor that SkippedBanner finds by document.querySelector
      // remains in the DOM.
      toolbar={<PRHeaderActions prHtmlUrl={pr?.html_url} />}
      status={
          <PRStatusBar
            intervalMs={FOCUSED_POLL_MS}
            owner={owner}
            repo={repo}
            number={number}
            pendingDraftCount={
              draft.lineComments.length +
              draft.fileComments.length +
              draft.replies.length
            }
            baseRef={pr?.base.ref}
            baseSha={pr?.base.sha}
            contentsProgress={
              contentsProgress.total > 0 &&
              contentsProgress.resolved < contentsProgress.total
                ? contentsProgress
                : null
            }
            isFilesLoading={
              tab === "changes" && isFilesLoading && filesQuery.data === undefined
            }
            forcePush={
              forcePushInfo
                ? {
                    prevSha: forcePushInfo.prevSha,
                    newSha: forcePushInfo.newSha,
                  }
                : null
            }
            errorCause={(() => {
              const e = prQuery.error ?? filesError ?? contentsError;
              if (!e) return null;
              const cause = detectErrorCause(e);
              return cause === 'unknown' ? null : cause;
            })()}
            tabLoading={null}
          />
        }
      >
        {/* Auth expiry takes over the whole content area as a global
         *  card - never inline. A dead token breaks every query, so an
         *  inline diff-pane treatment (header + rail still rendered)
         *  would falsely imply the rest of the PR is fine. This branch
         *  pre-empts loading / shell / inline-error below. The card's
         *  "Sign in again" signs out + routes to /welcome. */}
        {authExpired ? (
          <PRErrorPane
            error={
              prQuery.error ??
              filesQuery.error ??
              commentsQuery.error ??
              threadsQuery.error ??
              contentsQuery.error
            }
            endpoint={`/repos/${owner}/${repo}/pulls/${number}`}
            layout="full"
            lastSyncedAt={lastSyncedAt}
          />
        ) : (
          <>
        {loading && (
          <LoadingPane
            owner={owner}
            repo={repo}
            number={number}
            filesProgress={filesProgress}
          />
        )}
        {/* Cold-start error - no PR metadata at all yet, can't render
         *  the shell. Fall back to the cause-aware card on its own.
         *  Once `pr` resolves (cached or not), the shell stays live
         *  and we render PRErrorPane in the diff-pane region below
         *  the steady SubToolbar - see further down. */}
        {!loading && !pr && error && (
          <PRErrorPane
            error={prQuery.error ?? filesQuery.error ?? error}
            endpoint={`/repos/${owner}/${repo}/pulls/${number}`}
            lastSyncedAt={lastSyncedAt}
            onRetry={() => {
              void queryClient.invalidateQueries({
                queryKey: ["pr", owner, repo, number],
              });
            }}
            onOpenOnGithub={() =>
              window.open(
                `https://github.com/${owner}/${repo}/pull/${number}`,
                "_blank",
              )
            }
          />
        )}
        {!loading && pr && (
          <ReviewLayoutHeader
            scroll={headerScroll}
            compact={
                <CompactHeader
                  pr={pr}
                  owner={owner}
                  repo={repo}
                  readOnly={readOnly}
                  activeTab={tab}
                  onTabChange={setTab}
                  onBack={onBack}
                  backLabel={backLabel}
                  focusMode={tabFocusActive}
                  onToggleFocusMode={toggleTabFocus}
                  commentFocusIsNew={newCommentsFocus}
                  onSelectCommentFocus={selectCommentFocus}
                  commentCounts={commentCounts}
                  onJumpToMergeBox={() => {
                    setTab('description');
                    setTimeout(() => {
                      document
                        .getElementById('pr-merge-box')
                        ?.scrollIntoView({ behavior: 'auto', block: 'start' });
                    }, 80);
                  }}
                  onJumpToComment={(target) => {
                    if (target.path) {
                      setTab('changes');
                      setJumpTarget({
                        path: target.path,
                        line: target.line ?? null,
                        diffSide: target.diffSide ?? null,
                      });
                    } else if (target.reviewId != null) {
                      setTab('description');
                      setConvJumpTarget({ reviewId: target.reviewId });
                    }
                  }}
                  diffTools={
                    tab === 'changes'
                      ? {
                          diffMode: diffMode ?? 'split',
                          onDiffModeChange: onDiffModeChange ?? (() => {}),
                          viewed: countViewedFiles(viewedState?.viewed, files),
                          totalFiles: files.length,
                          onCollapseAll:
                            files.length > 0
                              ? () =>
                                  collapseState.collapseAll(
                                    files.map((f) => f.filename),
                                  )
                              : undefined,
                          onExpandAll:
                            files.length > 0
                              ? () =>
                                  collapseState.expandAll(
                                    files.map((f) => f.filename),
                                  )
                              : undefined,
                          onResetCollapse: collapseState.resetAll,
                          onCollapseWithoutComments:
                            files.length > 0
                              ? () =>
                                  collapseState.collapseAll(
                                    files
                                      .filter(
                                        (f) =>
                                          !fileHasOpenComments(
                                            f.filename,
                                            threadIndex,
                                          ),
                                      )
                                      .map((f) => f.filename),
                                  )
                              : undefined,
                          filesWithoutCommentsCount:
                            files.length > 0
                              ? files.filter(
                                  (f) =>
                                    !fileHasOpenComments(
                                      f.filename,
                                      threadIndex,
                                    ),
                                ).length
                              : undefined,
                        }
                      : null
                  }
                  aiReviewTrigger={
                    tab === 'changes' && aiTrigger ? (
                      <AiReviewHeaderButton {...aiTrigger} compact />
                    ) : null
                  }
                />
              }
              full={
                <>
            <PRHeader
              pr={pr}
              owner={owner}
              repo={repo}
              readOnly={readOnly}
              focusMode={tabFocusActive}
              onToggleFocusMode={toggleTabFocus}
              commentFocusIsNew={newCommentsFocus}
              onSelectCommentFocus={selectCommentFocus}
              commentCounts={commentCounts}
              activeTab={tab}
              onJumpToMergeBox={() => {
                // The merge box lives at the foot of the Conversation
                // (Description) tab. Switch there first, then scroll once
                // it has mounted.
                setTab("description");
                setTimeout(() => {
                  document
                    .getElementById("pr-merge-box")
                    ?.scrollIntoView({ behavior: "auto", block: "start" });
                }, 80);
              }}
              onJumpToComment={(target) => {
                // AFK plan 11 - reviewer HoverCard's "View comment"
                // action. Two destinations depending on the comment's
                // anchor:
                //  - line-anchored inline comment → Changes tab, stash
                //    the diff anchor so ChangesTab scrolls to + flashes
                //    the line.
                //  - PR-level review summary (no path, reviewId set) →
                //    Conversation tab, stash the review id so the
                //    timeline scrolls to + flashes that review.
                if (target.path) {
                  setTab('changes');
                  setJumpTarget({
                    path: target.path,
                    line: target.line ?? null,
                    diffSide: target.diffSide ?? null,
                  });
                } else if (target.reviewId != null) {
                  setTab('description');
                  setConvJumpTarget({ reviewId: target.reviewId });
                }
              }}
              onBack={onBack}
              backLabel={backLabel}
              onSubmitWithVerdict={readOnly ? undefined : (verdict) => {
                // Pre-seed the draft's verdict + open the submit
                // modal. Same wiring the old PRHeaderActions used.
                draftActions.setVerdict(
                  verdict === "approve" ? "approve" : "changes",
                );
                setModalOpen(true);
              }}
            />
            {/* Collapse so the banner slides in/out instead of snapping.
                The exiting child is retained by AnimatePresence, so the
                old banner stays painted while it animates closed. */}
            <Collapse open={!!forcePushInfo}>
              {forcePushInfo && (
                <ForcePushBanner
                  info={{
                    ...forcePushInfo,
                    refetchProgress:
                      contentsProgress.total > 0
                        ? contentsProgress
                        : undefined,
                  }}
                  pendingDraftCount={
                    draft.lineComments.length +
                    draft.fileComments.length +
                    draft.replies.length
                  }
                  onDismiss={() => setForcePushInfo(null)}
                />
              )}
            </Collapse>
            <PRTabStrip
              active={tab}
              onChange={setTab}
              counts={{
                description: pr.comments + pr.review_comments,
                commits: pr.commits,
                changes: pr.changed_files,
              }}
              toolbarSlot={
                <CompactChangesToolbar
                  aiReviewTrigger={
                    aiTrigger ? <AiReviewHeaderButton {...aiTrigger} /> : null
                  }
                  diffMode={diffMode ?? 'split'}
                  onDiffModeChange={onDiffModeChange ?? (() => {})}
                  search={diffSearch ?? null}
                  onSearchChange={(s) =>
                    onDiffSearchChange?.(s && s.trim() ? s : undefined)
                  }
                  searchMatchCount={searchSummary.count}
                  searchMatchFileCount={searchSummary.fileCount}
                  searchMatchIndex={searchMatchIndex}
                  onSearchNext={() => goToMatch(1)}
                  onSearchPrev={() => goToMatch(-1)}
                  commits={pr.commits}
                  viewed={countViewedFiles(viewedState?.viewed, files)}
                  totalFiles={files.length}
                  contentsProgress={
                    contentsProgress.total > 0 &&
                    contentsProgress.resolved < contentsProgress.total
                      ? contentsProgress
                      : undefined
                  }
                  isFilesLoading={
                    tab === 'changes' &&
                    isFilesLoading &&
                    filesQuery.data === undefined
                  }
                  owner={owner}
                  repo={repo}
                  number={number}
                  baseRef={pr.base.ref}
                  headRef={pr.head.ref}
                  baseSha={diffBaseSha}
                  headSha={pr.head.sha}
                  selectedCommitShas={
                    commits
                      ? new Set(
                          commits
                            .split(',')
                            .map((s) => s.trim())
                            .filter(Boolean),
                        )
                      : null
                  }
                  onSelectedCommitShasChange={(sel) => {
                    // The GitHub PR has no "uncommitted" scope - the
                    // sentinel never fires here (showUncommittedOption is
                    // unset). Guard so the widened type narrows to Set|null.
                    if (sel === UNCOMMITTED_SHA) return;
                    onCommitsChange?.(
                      sel && sel.size > 0
                        ? Array.from(sel).join(',')
                        : undefined,
                    );
                  }}
                  onCollapseAll={
                    files.length > 0
                      ? () =>
                          collapseState.collapseAll(
                            files.map((f) => f.filename),
                          )
                      : undefined
                  }
                  onExpandAll={
                    files.length > 0
                      ? () =>
                          collapseState.expandAll(files.map((f) => f.filename))
                      : undefined
                  }
                  onResetCollapse={collapseState.resetAll}
                  onCollapseWithoutComments={
                    files.length > 0
                      ? () =>
                          collapseState.collapseAll(
                            files
                              .filter(
                                (f) =>
                                  !fileHasOpenComments(f.filename, threadIndex),
                              )
                              .map((f) => f.filename),
                          )
                      : undefined
                  }
                  filesWithoutCommentsCount={
                    files.length > 0
                      ? files.filter(
                          (f) => !fileHasOpenComments(f.filename, threadIndex),
                        ).length
                      : undefined
                  }
                />
              }
            />
                </>
              }
          >
            {descriptionVisited && (
              <div
                // Kept mounted once visited: an `absolute inset-0` layer
                // hidden when another tab is active. NOTE the hide
                // mechanism differs from the Changes layer below - the
                // conversation timeline is virtualized with react-virtuoso,
                // and `content-visibility:hidden` (which the diff layer can
                // use) collapses the scroll container's overflow to zero,
                // so Virtuoso's scroll listener records scrollTop 0 and
                // lands at the top on return. `visibility:hidden` (Tailwind
                // `invisible`) keeps the layer fully laid out - size +
                // scrollTop intact - just unpainted, so the scroll position
                // survives the round-trip exactly. `pointer-events-none`
                // stops the hidden layer intercepting clicks on the tab
                // that's actually showing.
                className={
                  "absolute inset-0 flex min-h-0 flex-col" +
                  (tab === "description"
                    ? ""
                    : " pointer-events-none invisible")
                }
              >
                <DescriptionTab
                  pr={pr}
                  owner={owner}
                  repo={repo}
                  number={number}
                  readOnly={readOnly}
                  onScopeToCommit={scopeToCommitInChanges}
                  onShowInDiff={(target) => {
                    setTab('changes');
                    setJumpTarget(target);
                  }}
                  focusMode={commentsFocus}
                  onlyUnreplied={onlyUnreplied}
                  onExitFocusMode={() => setCommentsFocus(false)}
                  diffBaseSha={diffBaseSha}
                  jumpToConversation={convJumpTarget}
                  onJumpConsumed={() => setConvJumpTarget(null)}
                  initialScrollTop={
                    getSpot(owner, repo, number).conversationScrollTop ?? 0
                  }
                  onScrollChange={(scrollTop) =>
                    saveSpot(owner, repo, number, {
                      conversationScrollTop: scrollTop,
                    })
                  }
                />
              </div>
            )}
            {commitsVisited && (
              <div
                // Same persistent-layer treatment, and like the
                // Conversation layer the commit list is react-virtuoso, so
                // it must hide with `visibility:hidden` (Tailwind
                // `invisible`) rather than content-visibility - see the
                // detailed note on the Description layer above. Keeping it
                // laid out preserves the commit list's scroll position
                // across tab switches.
                className={
                  "absolute inset-0 flex min-h-0 flex-col" +
                  (tab === "commits"
                    ? ""
                    : " pointer-events-none invisible")
                }
              >
              <CommitsTab
                owner={owner}
                repo={repo}
                number={number}
                commitCount={pr.commits}
                branch={pr.head.ref}
                initialScrollIndex={
                  getSpot(owner, repo, number).commitsScrollIndex ?? 0
                }
                onScrollIndexChange={(index) =>
                  saveSpot(owner, repo, number, { commitsScrollIndex: index })
                }
                onSelectCommit={scopeToCommitInChanges}
              />
              </div>
            )}
            {/* Files-LIST failure: there's no file list to populate a
             *  rail with, so the outage card takes over the whole tab
             *  body. (A contents-only failure is handled inside
             *  ChangesTab below - rail stays, card sits in the diff
             *  column.) */}
            {tab === "changes" && filesError && (
              <PRErrorPane
                error={filesError}
                endpoint={`/repos/${owner}/${repo}/pulls/${number}/files`}
                layout="inline"
                lastSyncedAt={lastSyncedAt}
                onRetry={() => {
                  void queryClient.invalidateQueries({
                    queryKey: ["pr", owner, repo, number],
                  });
                }}
                onOpenOnGithub={() =>
                  window.open(
                    `https://github.com/${owner}/${repo}/pull/${number}/files`,
                    "_blank",
                  )
                }
              />
            )}
            {changesVisited && !filesError && (
              <div
                // Kept mounted across tab switches as an `absolute
                // inset-0` layer whose size never changes (it always
                // fills the relative parent above). When another tab is
                // active we hide it with `content-visibility:hidden`, NOT
                // `display:none`: display:none would zero the scroll
                // container and force the virtualizer to re-measure every
                // row on return (scroll drift). content-visibility skips
                // the browser's layout + paint of the diff subtree while
                // hidden (so it stops competing for the main thread when
                // you're reading other tabs) yet caches the rendered
                // state, so the scroll position is preserved EXACTLY and
                // re-showing is instant. `pointer-events-none` keeps the
                // (invisible) layer from intercepting clicks.
                className={
                  "absolute inset-0 flex min-h-0 flex-col" +
                  (tab === "changes"
                    ? ""
                    : " pointer-events-none [content-visibility:hidden]")
                }
              >
              <ChangesTab
                active={tab === "changes"}
                readOnly={readOnly}
                files={files}
                fileContents={fileContents}
                contentsProgress={contentsProgress}
                isContentsLoading={contentsQuery.isFetching}
                isFilesLoading={isFilesLoading}
                contentsError={contentsError}
                lastSyncedAt={lastSyncedAt}
                onRetryContents={() =>
                  void queryClient.invalidateQueries({
                    queryKey: ["pr", owner, repo, number],
                  })
                }
                focusMode={codeFocus}
                threadIndex={threadIndex}
                draft={draft}
                draftActions={draftActions}
                onDiscardReview={discardReviewNow}
                viewedState={viewedState}
                collapseState={collapseState}
                owner={owner}
                repo={repo}
                number={number}
                viewerLogin={viewerQuery.data?.login}
                prAuthorLogin={pr.user.login}
                headSha={pr.head.sha}
                baseSha={diffBaseSha}
                baseRef={pr.base.ref}
                headRef={pr.head.ref}
                commitCount={pr.commits}
                diffMode={diffMode}
                onDiffModeChange={onDiffModeChange}
                commits={commits}
                onCommitsChange={onCommitsChange}
                fileFilter={fileFilter}
                onFileFilterChange={onFileFilterChange}
                searchQuery={diffSearch}
                onSearchQueryChange={onDiffSearchChange}
                railMode={railMode}
                onRailModeChange={onRailModeChange}
                onSearchSummaryChange={setSearchSummary}
                searchMatchIndex={searchMatchIndex}
                onSearchMatchIndexChange={setSearchMatchIndex}
                onAiTrigger={setAiTrigger}
                onAnchorChange={onAnchorChange}
                initialPath={
                  initialAnchor?.path ??
                  getSpot(owner, repo, number).currentPath ??
                  null
                }
                initialLine={initialAnchor?.line ?? null}
                initialDiffSide={initialAnchor?.diffSide ?? null}
                initialCommentId={initialAnchor?.commentId ?? null}
                // Reviewer-HoverCard "View comment" for an inline comment.
                // A dedicated re-firing channel (NOT the mount-only
                // `initial*` props, which the one-shot anchor restore has
                // already consumed by the time the user clicks) so a jump
                // from another tab scrolls + highlights every time.
                jumpToDiff={jumpTarget}
                initialScrollTop={
                  // When a file was explicitly selected in the rail
                  // (apath in the URL), land EXACTLY on that file:
                  // passing 0 makes ChangesTab restore via an item-
                  // scroll (align:'start') instead of an approximate
                  // pixel offset, which drifts by a row when content
                  // heights differ between sessions (landing on the
                  // file above). Plain scroll sessions (no apath)
                  // still restore their exact pixel position.
                  initialAnchor?.path
                    ? 0
                    : (getSpot(owner, repo, number).scrollTop ?? 0)
                }
                onCurrentPathChange={(path) =>
                  saveSpot(owner, repo, number, { currentPath: path })
                }
                onScrollChange={(scrollTop) =>
                  saveSpot(owner, repo, number, { scrollTop })
                }
                onChanged={() =>
                  void queryClient.invalidateQueries({
                    queryKey: ["pr", owner, repo, number],
                  })
                }
                onOpenModal={() => setModalOpen(true)}
              />
              </div>
            )}
          </ReviewLayoutHeader>
        )}
          </>
        )}
        {/* Submit-review dialog. Kept mounted (gated by `open`) so the
            dialog's flip/blur close animation plays; it portals to
            <body> via the Dialog, so its position in the tree is just
            for context, not layout. */}
        <ReviewModal
          owner={owner}
          repo={repo}
          number={number}
          draft={draft}
          actions={draftActions}
          threadIndex={threadIndex}
          onSubmitReview={submitReviewNow}
          onDiscardReview={discardReviewNow}
          headSha={pr?.head.sha}
          authorLogin={pr?.user.login}
          open={modalOpen && !readOnly}
          onClose={() => setModalOpen(false)}
          // Refetch comments + reviews + timeline after a successful
          // submit so the new content appears in the relevant tabs
          // without a manual refresh.
          onSubmitted={() => {
            // Invalidate every query for this PR so the modal's
            // newly-posted comments/threads land in the next tick.
            // TanStack will refetch only the queries that are
            // actively subscribed (mounted).
            void queryClient.invalidateQueries({
              queryKey: ["pr", owner, repo, number],
            });
          }}
        />
    </ReviewLayout>
  );
}

function LoadingPane({
  owner,
  repo,
  number,
  filesProgress,
}: {
  owner: string;
  repo: string;
  number: number;
  filesProgress: number;
}) {
  // Cold-start state - PR metadata still resolving. Matches
  // shell-pr-loading-files-paginating: full-fidelity rail skeleton +
  // centred "Resolving changed files" card with progress + counter +
  // a hint that the review dock is still usable.
  return (
    <div className="flex min-h-0 flex-1">
      <aside className="flex w-72 shrink-0 flex-col border-r bg-muted/30">
        <FileRailSkeleton count={16} />
      </aside>
      <div className="flex flex-1 items-center justify-center bg-card p-10">
        <Card className="w-[420px] overflow-hidden p-0">
          <div className="flex items-start gap-3 p-4">
            <div className="inline-flex size-8 shrink-0 items-center justify-center rounded-md border bg-muted/40">
              <Loader2Icon className="size-4 animate-spin text-foreground" />
            </div>
            <div className="min-w-0 flex-1">
              <div className="text-[13px] font-semibold text-foreground">
                Resolving changed files
              </div>
              <div className="mt-0.5 text-[12px] leading-relaxed text-muted-foreground">
                GitHub paginates{' '}
                <code className="rounded bg-muted px-1 py-0.5 font-mono text-[11px]">
                  /pulls/{number}/files
                </code>{' '}
                at 30 entries per request. Diffs start rendering as soon as the
                first page lands.
              </div>
              <Progress
                value={undefined}
                className="mt-3 h-1 rounded-full"
              />
              <div className="mt-2 flex items-center justify-between text-[11px] tabular-nums text-muted-foreground">
                <span>
                  {owner}/{repo}#{number}
                </span>
                <span>
                  {filesProgress > 0
                    ? `${filesProgress} files so far`
                    : 'fetching PR metadata'}
                </span>
              </div>
            </div>
          </div>
          <Separator />
          <div className="flex items-center gap-2 px-4 py-2 text-[11.5px] text-muted-foreground">
            <InfoIcon className="size-3.5" />
            <span>You can keep typing in the review dock - drafts are local.</span>
          </div>
        </Card>
      </div>
    </div>
  );
}

/** Count of files in this PR that the viewer has marked as viewed.
 * Used by CompactChangesToolbar's viewed-progress indicator. */
function countViewedFiles(
  viewed: Set<string> | undefined,
  files: { filename: string }[],
): number {
  if (!viewed || files.length === 0) return 0;
  let n = 0;
  for (const f of files) if (viewed.has(f.filename)) n++;
  return n;
}

/** True when a file has at least one unresolved review thread. Mirrors
 * the (non-exported) helper in ChangesTab - used to drive the toolbar's
 * "Collapse files without comments" bulk action. */
function fileHasOpenComments(
  filename: string,
  threadIndex: ThreadIndex | undefined,
): boolean {
  const threads = threadIndex?.byPath.get(filename);
  if (!threads || threads.length === 0) return false;
  return threads.some((t) => t.isResolved !== true);
}

// FNV-1a 32-bit. Used to collapse the files list into a stable identity
// for the contents queryKey. Sub-ms on ~600 inputs; deterministic across
// sessions so persisted contents caches still hit on re-open.
function hashStrings(parts: readonly string[]): string {
  let h = 0x811c9dc5;
  for (const s of parts) {
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    // 0x00 separator so ["ab", "c"] and ["a", "bc"] don't collide.
    h ^= 0;
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16);
}
