// Reviewer-management controller (#18 + #19). Request / re-request /
// remove reviewers and dismiss a review, with cache invalidation +
// toasts. Gating (WRITE+) is the caller's job — it has the resolved
// Viewer permission — so this hook just runs the mutations and never
// renders a control that would 403 because the caller doesn't mount it.

import { useCallback, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  dismissReview,
  removeRequestedReviewers,
  requestReviewers,
} from '../../github/client';
import { invalidatePrLists } from '../../github/prQueries';

/** A `kind:login` token identifying the in-flight reviewer action, so a
 * single chip can show a spinner without blocking the others. */
export type ReviewerPending = string | null;

export interface ReviewerManagement {
  pending: ReviewerPending;
  requestReviewer: (login: string) => Promise<void>;
  removeReviewer: (login: string) => Promise<void>;
  dismiss: (reviewId: number, reason: string) => Promise<void>;
}

export function useReviewerManagement(
  owner: string,
  repo: string,
  number: number,
): ReviewerManagement {
  const queryClient = useQueryClient();
  const [pending, setPending] = useState<ReviewerPending>(null);

  const invalidate = useCallback(
    () =>
      Promise.all([
        queryClient.invalidateQueries({
          queryKey: ['pr', owner, repo, number],
        }),
        // Requesting / removing a reviewer (or dismissing a review) changes
        // which PRs land in the Reviewing lens + Team radar — refresh those
        // too, not just this PR's detail.
        invalidatePrLists(queryClient),
      ]),
    [queryClient, owner, repo, number],
  );

  const run = useMutation({
    mutationFn: async (job: {
      token: string;
      fn: () => Promise<unknown>;
      success: string;
    }) => {
      setPending(job.token);
      try {
        await job.fn();
      } finally {
        setPending(null);
      }
      return job.success;
    },
    onSuccess: async (success) => {
      await invalidate();
      toast.success(success);
    },
    onError: (err) =>
      toast.error(err instanceof Error ? err.message : 'Action failed'),
  });

  const exec = useCallback(
    (token: string, fn: () => Promise<unknown>, success: string) =>
      run.mutateAsync({ token, fn, success }).then(() => undefined),
    [run],
  );

  return {
    pending,
    // Request (and re-request — same endpoint) a reviewer.
    requestReviewer: (login) =>
      exec(
        `request:${login}`,
        () => requestReviewers(owner, repo, number, { users: [login] }),
        `Review requested from ${login}`,
      ),
    removeReviewer: (login) =>
      exec(
        `remove:${login}`,
        () => removeRequestedReviewers(owner, repo, number, { users: [login] }),
        `Removed ${login} from reviewers`,
      ),
    dismiss: (reviewId, reason) =>
      exec(
        `dismiss:${reviewId}`,
        () => dismissReview(owner, repo, number, reviewId, reason),
        'Review dismissed',
      ),
  };
}
