// Global confirm dialog, backed by a zustand store (no React Context).
// Bridges the imperative `window.confirm()` call style to the app's
// animated AlertDialog: `const confirm = useConfirm()` then
// `if (!(await confirm({...}))) return;`. A single <ConfirmHost/> mounted
// at the app root renders the actual modal (like the sonner Toaster).
// Backed by the shared ConfirmModal so every confirmation looks like the
// lifecycle ones (ADR 0016) instead of the browser's native blocking
// dialog — which also freezes the renderer under automation.

import { create } from 'zustand';
import type { ComponentType } from 'react';
import type { LucideProps } from 'lucide-react';
import { ConfirmModal } from '@/pr/lifecycle/ConfirmModal';

export interface ConfirmOptions {
  title: string;
  description: string;
  /** Defaults to 'Confirm'. */
  confirmLabel?: string;
  cancelLabel?: string;
  /** 'destructive' (default) tints the icon + confirm button red. */
  tone?: 'destructive' | 'neutral';
  icon?: ComponentType<LucideProps>;
  confirmIcon?: ComponentType<LucideProps>;
}

interface ConfirmStore {
  open: boolean;
  /** Retained through the close animation so the text doesn't blank out
   *  mid-exit; the next confirm() overwrites it before reopening. */
  options: ConfirmOptions | null;
  resolve: ((ok: boolean) => void) | null;
  /** Promise-based confirm. Resolves true on confirm, false on cancel /
   *  dismiss. Callable from anywhere — components, hooks, or plain code. */
  confirm: (options: ConfirmOptions) => Promise<boolean>;
  /** Resolve the outstanding promise once, then close. */
  settle: (ok: boolean) => void;
}

const useConfirmStore = create<ConfirmStore>((set, get) => ({
  open: false,
  options: null,
  resolve: null,
  confirm: (options) =>
    new Promise<boolean>((resolve) => {
      // If a previous prompt is still open (overlapping callers), settle
      // its promise false before taking over — otherwise that awaiter
      // would hang forever once its resolver is replaced.
      get().resolve?.(false);
      set({ open: true, options, resolve });
    }),
  settle: (ok) => {
    get().resolve?.(ok);
    set({ open: false, resolve: null });
  },
}));

/** Imperative confirm callable from non-React code. In components/hooks
 *  prefer `useConfirm()`, which returns this same (stable) action. */
export const confirm = (options: ConfirmOptions): Promise<boolean> =>
  useConfirmStore.getState().confirm(options);

/** Returns the stable promise-based confirm action. */
export function useConfirm(): (options: ConfirmOptions) => Promise<boolean> {
  return useConfirmStore((s) => s.confirm);
}

/** Mounts the actual dialog. Render once at the app root. */
export function ConfirmHost() {
  const open = useConfirmStore((s) => s.open);
  const options = useConfirmStore((s) => s.options);
  const settle = useConfirmStore((s) => s.settle);
  return (
    <ConfirmModal
      open={open}
      onOpenChange={(next) => {
        if (!next) settle(false);
      }}
      title={options?.title ?? ''}
      description={options?.description ?? ''}
      tone={options?.tone ?? 'destructive'}
      icon={options?.icon}
      confirmLabel={options?.confirmLabel ?? 'Confirm'}
      confirmIcon={options?.confirmIcon}
      cancelLabel={options?.cancelLabel}
      onConfirm={() => settle(true)}
    />
  );
}
