// Local Review status badge computation.
//
// ADR 0012 Phase 7. Each Local Review row in the list carries a
// single status badge derived from four signals:
//
//   - prOpened    — `gh pulls --head <branch> --base <base> --state open`
//                    returned ≥1 PR (TanStack-cached upstream).
//   - behind      — `git rev-list --count base..head` > 0
//   - notesActive — at least one LocalReviewComment exists where
//                    !dismissed.
//   - ahead       — `git rev-list --count head..base` > 0; required
//                    for `ready`.
//
// Precedence (highest → lowest), per the ADR's table:
//     pr-opened > stale > in-progress > ready
//
// "ready" is the default — gated on having at least one commit ahead
// and zero unaddressed notes.

export type LocalReviewStatus =
  | 'pr-opened'
  | 'stale'
  | 'in-progress'
  | 'ready';

export interface LocalReviewStatusInputs {
  /** True when a GitHub PR exists open against this (branch, base). */
  prOpened: boolean;
  /** Commits on base not in head (drives `stale`). */
  behind: number;
  /** Commits on head not in base (required for `ready`). */
  ahead: number;
  /** Count of unaddressed (!dismissed) local review comments. */
  notesActive: number;
}

export function computeLocalReviewStatus(
  inputs: LocalReviewStatusInputs,
): LocalReviewStatus {
  if (inputs.prOpened) return 'pr-opened';
  if (inputs.behind > 0) return 'stale';
  if (inputs.notesActive > 0) return 'in-progress';
  // Default: ready — even with 0 commits ahead, the row stays in
  // `ready` rather than inventing a fifth state. The list's column
  // already displays ahead/behind separately.
  if (inputs.ahead >= 0) return 'ready';
  return 'ready';
}
