// Titlebar / tab-bar / status chrome for the Team review radar — the
// small presentational pieces that wrap the bucketed list.

import { RefreshButton } from '@/components/ui/refresh-button';

export function RadarToolbar({ onRefresh }: { onRefresh: () => Promise<unknown> }) {
  return <RefreshButton onRefresh={onRefresh} />;
}

export function TeamStatus({
  you,
  orgs,
  sort,
  unassigned,
}: {
  you: string;
  orgs: number;
  sort: string;
  unassigned: number;
}) {
  return (
    <>
      <span className="inline-flex items-center gap-1.5">
        <span className="size-1.5 rounded-full bg-pyor-pass" />
        Connected · {you || '…'}
      </span>
      <span className="mx-3 text-border">│</span>
      <span>
        {orgs} {orgs === 1 ? 'org' : 'orgs'}
      </span>
      <span className="flex-1" />
      <span className="text-muted-foreground/80">
        Sorted by {sort} · <span className="tabular-nums">{unassigned}</span>{' '}
        unassigned · GraphQL search
      </span>
    </>
  );
}
