// Counts surfaced on the Conversation Focus pill so the two variants read
// distinctly at a glance:
//   all     — total comment discussions (inline threads + top-level
//             comments + reviews that carry a write-up).
//   pending — inline threads awaiting the viewer's reply (unresolved, and
//             someone other than the viewer spoke last) — the actionable
//             subset the "Pending comments" variant is built around.
//
// Reads the same React Query caches the timeline uses (shared keys → one
// round trip serves every surface), so this adds a subscription, not a
// fetch.

import { useQuery } from '@tanstack/react-query';
import {
  getReviewComments,
  getReviews,
  getTimeline,
} from '../../github/client';
import {
  prPendingReviewOptions,
  prThreadsOptions,
} from '../../github/prQueries';
import { threadAwaitsViewer } from './unrepliedFilter';
import type { GHReviewComment } from '../../github/types';

export interface CommentFocusCounts {
  all: number;
  pending: number;
}

export function useCommentFocusCounts(
  owner?: string,
  repo?: string,
  number?: number,
  viewerLogin?: string,
): CommentFocusCounts {
  const enabled = !!(owner && repo && number);
  const reviews = useQuery({
    queryKey: ['pr', owner, repo, number, 'reviews'],
    queryFn: () => getReviews(owner!, repo!, number!),
    enabled,
    staleTime: 30_000,
  });
  const comments = useQuery({
    queryKey: ['pr', owner, repo, number, 'comments'],
    queryFn: () => getReviewComments(owner!, repo!, number!),
    enabled,
    staleTime: 30_000,
  });
  const timeline = useQuery({
    queryKey: ['pr', owner, repo, number, 'timeline'],
    queryFn: () => getTimeline(owner!, repo!, number!),
    enabled,
    staleTime: 30_000,
  });
  const pending = useQuery({
    ...prPendingReviewOptions(owner!, repo!, number!),
    enabled,
    staleTime: 30_000,
  });
  const threads = useQuery({
    ...prThreadsOptions(owner!, repo!, number!),
    enabled,
    staleTime: 30_000,
  });

  const reviewComments: GHReviewComment[] = [
    ...(comments.data ?? []),
    ...(pending.data?.comments ?? []),
  ];
  const heads = reviewComments.filter((c) => !c.in_reply_to_id);
  const repliesByHead = reviewComments.reduce((m, c) => {
    if (c.in_reply_to_id) {
      m.set(c.in_reply_to_id, [...(m.get(c.in_reply_to_id) ?? []), c]);
    }
    return m;
  }, new Map<number, GHReviewComment[]>());
  const resolvedHeads = (threads.data ?? []).reduce((s, t) => {
    if (t.isResolved) t.commentDatabaseIds.forEach((id) => s.add(id));
    return s;
  }, new Set<number>());

  const pendingCount = heads.filter(
    (head) =>
      !resolvedHeads.has(head.id) &&
      threadAwaitsViewer([head, ...(repliesByHead.get(head.id) ?? [])], viewerLogin),
  ).length;

  const topLevelComments = (timeline.data ?? []).filter(
    (e) => e.event === 'commented',
  ).length;
  const reviewsWithBody = (reviews.data ?? []).filter(
    (r) => r.state !== 'PENDING' && !!r.body?.trim(),
  ).length;

  return {
    all: heads.length + topLevelComments + reviewsWithBody,
    pending: pendingCount,
  };
}
