// Builds the diff + file-context text the LLM receives (ADR 0026 input
// scope: "diff + surrounding/changed file contents"). Large PRs are handled
// by selecting the largest / most-changed files up to a hard ceiling and
// disclosing the cap explicitly — never a silent truncation.

import type { GHPullRequestFile } from '@/github/types';
import type { FileContents } from '@/github/fetchPRFileContents';

/** Per-feature ceilings. Grouping needs breadth (patch only); hints need
 * depth (patch + full new file). */
export interface ContextLimits {
  /** Max files included before the cap kicks in. */
  maxFiles: number;
  /** Max chars of full file content appended per file (0 = patch only). */
  maxFileChars: number;
  /** Max chars of patch included per file. */
  maxPatchChars: number;
}

export const GROUPING_LIMITS: ContextLimits = {
  maxFiles: 60,
  maxFileChars: 0,
  maxPatchChars: 6_000,
};

export const HINTS_LIMITS: ContextLimits = {
  maxFiles: 25,
  maxFileChars: 12_000,
  maxPatchChars: 8_000,
};

export interface BuiltContext {
  text: string;
  /** The files actually included (after the cap), in inclusion order. */
  includedFiles: GHPullRequestFile[];
  /** Set when the PR was capped: how many of how many were analyzed. */
  capped: { analyzed: number; totalFiles: number } | null;
}

function clip(s: string, max: number): string {
  if (max <= 0 || s.length <= max) return s;
  return `${s.slice(0, max)}\n… (truncated)`;
}

/** Rank by total churn desc so the cap keeps the most-changed files. */
function byChurn(a: GHPullRequestFile, b: GHPullRequestFile): number {
  return b.additions + b.deletions - (a.additions + a.deletions);
}

export function buildContext(
  files: GHPullRequestFile[],
  contents: Map<string, FileContents> | undefined,
  limits: ContextLimits,
): BuiltContext {
  const ranked = [...files].sort(byChurn);
  const capped = ranked.length > limits.maxFiles;
  const included = ranked.slice(0, limits.maxFiles);

  const parts = included.map((f) => {
    const head = `### ${f.filename}\nstatus: ${f.status} · +${f.additions} −${f.deletions}${
      f.previous_filename ? ` · renamed from ${f.previous_filename}` : ''
    }`;
    const patch = f.patch ? `\n\`\`\`diff\n${clip(f.patch, limits.maxPatchChars)}\n\`\`\`` : '\n(no textual diff)';
    let body = '';
    if (limits.maxFileChars > 0) {
      const c = contents?.get(f.filename);
      if (c?.newText) {
        body = `\nFull file (head):\n\`\`\`\n${clip(c.newText, limits.maxFileChars)}\n\`\`\``;
      }
    }
    return `${head}${patch}${body}`;
  });

  return {
    text: parts.join('\n\n'),
    includedFiles: included,
    capped: capped ? { analyzed: included.length, totalFiles: ranked.length } : null,
  };
}
