// The AI mark — a nested diamond, deliberately NOT the conventional
// 4-point sparkle. One mark brands every AI element (ADR 0026 / design
// spec). `solid` fills the outer diamond and knocks the inner one out.

import { cn } from '@/lib/utils';

export function AiMark({
  className = 'size-4',
  strokeWidth = 1.6,
  solid = false,
}: {
  className?: string;
  strokeWidth?: number;
  solid?: boolean;
}) {
  return (
    <svg viewBox="0 0 24 24" fill="none" className={className} aria-hidden="true">
      <path
        d="M12 2.4 21.6 12 12 21.6 2.4 12Z"
        fill={solid ? 'currentColor' : 'none'}
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinejoin="round"
      />
      <path
        d="M12 8.2 15.8 12 12 15.8 8.2 12Z"
        fill={solid ? 'var(--ai-knockout, #fff)' : 'currentColor'}
      />
    </svg>
  );
}

// Small solid "chip" of the mark on a violet tile — the avatar-equivalent
// at the head of a hint, so a hint never borrows a human avatar slot.
export function AiMarkTile({
  size = 'size-6',
  className = '',
}: {
  size?: string;
  className?: string;
}) {
  return (
    <span
      className={cn(
        'inline-flex shrink-0 items-center justify-center rounded-md bg-violet-600 text-white',
        size,
        className,
      )}
      style={{ ['--ai-knockout' as string]: '#7c3aed' }}
    >
      <AiMark className="size-3.5" solid />
    </span>
  );
}
