// Author filter as a multi-select avatar group — the showcase control.
// Capped to `max` faces with a "+N" overflow popover for the rest;
// selected faces sort to the front so a picked author is never hidden.

import { useState } from 'react';
import { CheckIcon, XIcon } from 'lucide-react';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { TeamAvatar } from './TeamBits';

export function AuthorMultiSelect({
  authors,
  selected,
  you,
  onToggle,
  onClear,
  max = 6,
}: {
  authors: string[];
  selected: Set<string>;
  you: string;
  onToggle: (login: string) => void;
  onClear: () => void;
  max?: number;
}) {
  const [open, setOpen] = useState(false);
  const active = selected.size > 0;
  // Selected-first ordering.
  const ordered = [...authors].sort(
    (a, b) => (selected.has(b) ? 1 : 0) - (selected.has(a) ? 1 : 0),
  );
  const visible = ordered.slice(0, max);
  const overflow = ordered.slice(max);
  const hiddenSelected = overflow.filter((a) => selected.has(a)).length;

  return (
    <div className="flex items-center gap-2">
      <span className="text-[10.5px] font-semibold uppercase tracking-wide text-muted-foreground">
        {active ? `Authors · ${selected.size}` : 'Authors'}
      </span>
      <div className="flex items-center gap-1.5">
        {visible.map((a) => (
          <Face
            key={a}
            login={a}
            you={you}
            on={selected.has(a)}
            anySelected={active}
            onToggle={onToggle}
          />
        ))}
        {overflow.length > 0 && (
          <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
              <button
                type="button"
                className={cn(
                  'relative inline-flex size-6 items-center justify-center rounded-full border text-[9.5px] font-semibold transition-colors',
                  open
                    ? 'border-zinc-400 bg-accent text-foreground'
                    : 'border-dashed border-input bg-background text-muted-foreground hover:border-zinc-400 hover:text-foreground',
                )}
              >
                +{overflow.length}
                {hiddenSelected > 0 && (
                  <span className="absolute -right-0.5 -top-0.5 size-2 rounded-full bg-blue-600 ring-2 ring-card" />
                )}
              </button>
            </PopoverTrigger>
            <PopoverContent align="start" className="w-[216px] p-1.5">
              <div className="max-h-[280px] overflow-auto">
                <div className="px-2 py-1 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                  More authors
                </div>
                {overflow.map((a) => {
                  const on = selected.has(a);
                  return (
                    <button
                      key={a}
                      type="button"
                      onClick={() => onToggle(a)}
                      className="flex w-full items-center gap-2.5 rounded-md px-2 py-1.5 text-left hover:bg-accent"
                    >
                      <TeamAvatar login={a} className="size-6" />
                      <span className="text-[12.5px] text-foreground">
                        {a === you ? 'you' : a}
                      </span>
                      <CheckIcon
                        className={cn(
                          'ml-auto size-3.5',
                          on ? 'text-foreground' : 'text-transparent',
                        )}
                      />
                    </button>
                  );
                })}
              </div>
            </PopoverContent>
          </Popover>
        )}
      </div>
      {active && (
        <button
          type="button"
          onClick={onClear}
          className="inline-flex items-center gap-1 text-[11px] font-medium text-muted-foreground transition-colors hover:text-foreground"
        >
          <XIcon className="size-3" />
          Clear
        </button>
      )}
    </div>
  );
}

function Face({
  login,
  you,
  on,
  anySelected,
  onToggle,
}: {
  login: string;
  you: string;
  on: boolean;
  anySelected: boolean;
  onToggle: (login: string) => void;
}) {
  const dim = anySelected && !on;
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          onClick={() => onToggle(login)}
          className={cn(
            'relative rounded-full outline-none transition duration-150',
            on ? 'ring-2 ring-foreground ring-offset-1 ring-offset-background' : '',
            dim
              ? 'opacity-35 grayscale hover:opacity-100 hover:grayscale-0'
              : 'hover:-translate-y-0.5',
          )}
        >
          <TeamAvatar login={login} className="size-6" />
          {on && (
            <span className="absolute -bottom-0.5 -right-0.5 inline-flex size-3 items-center justify-center rounded-full bg-foreground ring-2 ring-background">
              <CheckIcon className="size-1.5 text-background" strokeWidth={4} />
            </span>
          )}
        </button>
      </TooltipTrigger>
      <TooltipContent>{login === you ? 'you' : login}</TooltipContent>
    </Tooltip>
  );
}
