// useLocalAnnotationLayer — packages the entire local pre-PR comment
// pipeline as a `DiffAnnotationLayer` for the shared LiveDiffPane
// (via ChangesTab). It is the local counterpart to LiveDiffPane's
// built-in GitHub thread/composer machinery: saved comments, the line +
// file composers, staleness chips, content-less rename notes, and binary
// image cards — all rendered through the SAME diff body the GitHub PR
// surface uses.
//
// Lifted out of the old hand-built `LocalReviewDiffBody` so the local
// surface stops reimplementing the diff pane and inherits its polish
// (sticky headers, autoscroll, visible-file tracking, search, etc.).
//
// Type note: the diff pane is generically typed on `ThreadAnnotationMeta`
// (the GitHub union). Local annotations carry `LocalAnnotationMeta`; since
// the diff body never inspects the metadata's shape (it just stores it and
// hands it back to `renderAnnotation`), we cast across the boundary. The
// one shared kind is `image` (from the GitHub `withImageAnnotations`
// helper), which this layer also renders.

import {
  useCallback,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { useQuery } from "@tanstack/react-query";
import { useStableCallback } from "@pierre/diffs/react";
import type {
  CodeViewDiffItem,
  CodeViewItem,
  DiffLineAnnotation,
  LineAnnotation,
  SelectedLineRange,
} from "@pierre/diffs/react";
import {
  AlertTriangleIcon,
  CheckIcon,
  CodeIcon,
  EyeIcon,
  ImageIcon,
  MessageSquareIcon,
  PlusIcon,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import type { DiffBodyItemContext } from "../../diff/DiffBody";
import type {
  DiffAnnotationLayer,
} from "../changes/LiveDiffPane";
import type {
  ThreadAnnotationMeta,
  ThreadDiffItem,
  ImageFileEntry,
} from "../../github/buildDiff";
import {
  withImageAnnotations,
  withBinaryNoteAnnotations,
} from "../../github/buildDiff";
import {
  attachLocalCommentsToItems,
  groupComments,
  readLineSnippet,
  withLocalFileComposerAnnotation,
  withLocalLineComposerAnnotation,
  withLocalOutdatedComments,
  withLocalRenameNoteAnnotations,
  type LocalAnnotationMeta,
  type LocalLineComposerSpec,
} from "./localDiffAnnotations";
import { LocalCommentCard, LocalCommentStack } from "./LocalCommentCard";
import { LocalLineCommentComposer } from "./LocalLineCommentComposer";
import { LocalFileCommentComposer } from "./LocalFileCommentComposer";
import { CopyPathButton } from "../changes/CopyPathButton";
import { ImageDiffCard } from "../changes/ImageDiffSection";
import {
  RenameCounts,
  RenameNoteCard,
  RenamePill,
  resolveRenameKind,
} from "../../diff/renameTreatment";
import { BinaryBadge, BinaryFileCard } from "../../diff/binaryTreatment";
import { useLocalReviewComments } from "../../review/useLocalReviewComments";
import { WORKING_TREE_ANCHOR } from "../../review/localReviewComments";
import {
  computeStaleness,
  type StalenessResult,
} from "../../review/localReviewStaleness";
import type { FileContents } from "../../github/fetchPRFileContents";
import type { ViewedHookValue } from "../../review/viewedHooks";
import type { CollapseHookValue } from "../changes/collapseHooks";
import { bridge } from "../../desktop/electronBridge";

export interface UseLocalAnnotationLayerArgs {
  reviewId: string;
  /** The active scope's resolved old+new contents per path. */
  contents: Map<string, FileContents>;
  /** Worktree root — read for WORKING_TREE-anchored staleness. */
  worktreePath: string;
  /** Resolved committed head SHA of the active scope. Used as the
   * staleness anchor for committed comments (never a WORKTREE sentinel). */
  headSha: string;
  /** Anchor SHA for a NEW comment on `path` in the active scope — the
   * real committed head SHA, or `WORKING_TREE_ANCHOR` for an
   * uncommitted-only path. Owned by the screen (it knows the scope). */
  anchorForPath: (path: string) => string;
  /** Content-less rename/move/mode-only files (note row + pill). */
  renamedFiles: ImageFileEntry[];
  /** Binary image files (rendered as before/after preview; body hidden). */
  imageFiles: ImageFileEntry[];
  /** SVG files (text). Default to rendered preview with a Source toggle,
   * exactly like the GitHub PR path. */
  svgFiles: ImageFileEntry[];
  /** Non-image binary files (.wasm, blobs). Rendered as a "Binary file" note
   * card; body hidden. */
  binaryFiles: ImageFileEntry[];
  /** The active scope's resolved refs — used to load image bytes for the
   * before/after preview (old side = oldRef, new side = newRef; null = the
   * working tree). */
  oldRef: string;
  newRef: string | null;
  /** Viewer login for new-comment attribution. */
  viewerLogin?: string;
  /** Per-(commit,path) viewed-state (drives the header checkmark). */
  viewedState: ViewedHookValue;
  /** Per-file manual collapse overrides (drives the header chevron). */
  collapseState?: CollapseHookValue;
}

/** WORKING_TREE-anchored line snippet read — the wt-contents map is
 * path → raw text (one string), unlike the committed `{oldText,newText}`
 * shape, so `readLineSnippet` doesn't fit. Mirrors the staleness module's
 * trim/cap rule. */
function readWtLineSnippet(
  wtContents: Map<string, string> | null,
  path: string,
  line: number,
): string | null {
  if (!wtContents) return null;
  const text = wtContents.get(path);
  if (text == null || text === "") return null;
  const raw = text.split("\n")[line - 1];
  if (raw == null) return null;
  return raw.trimEnd().slice(0, 200);
}

export function useLocalAnnotationLayer({
  reviewId,
  contents,
  worktreePath,
  headSha,
  anchorForPath,
  renamedFiles,
  imageFiles,
  svgFiles,
  binaryFiles,
  oldRef,
  newRef,
  viewerLogin,
  viewedState,
  collapseState,
}: UseLocalAnnotationLayerArgs): DiffAnnotationLayer {
  const commentsQuery = useLocalReviewComments(reviewId);
  const comments = useMemo(() => commentsQuery.data ?? [], [commentsQuery.data]);
  const grouped = useMemo(() => groupComments(comments), [comments]);

  const [lineComposer, setLineComposer] =
    useState<LocalLineComposerSpec | null>(null);
  const [fileComposerPath, setFileComposerPath] = useState<string | null>(null);
  // SVG files default to rendered-image preview; this holds the paths the
  // user flipped to source-code view (mirrors LiveDiffPane's svgCodeMode).
  const [svgCodeMode, setSvgCodeMode] = useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const toggleSvgMode = useCallback(
    (path: string) =>
      setSvgCodeMode((prev) => {
        const next = new Set(prev);
        if (next.has(path)) next.delete(path);
        else next.add(path);
        return next;
      }),
    [],
  );

  // ── Working-tree contents for WORKING_TREE-anchored staleness ──────
  const wtPathList = useMemo(() => {
    const s = new Set<string>();
    comments.forEach((c) => {
      if (c.anchorSha === WORKING_TREE_ANCHOR) s.add(c.path);
    });
    return [...s].sort();
  }, [comments]);

  const wtContentsQuery = useQuery({
    queryKey: ["local-review", reviewId, "wt-contents", worktreePath, wtPathList],
    queryFn: async (): Promise<Map<string, string>> => {
      const b = bridge();
      if (!b || wtPathList.length === 0) return new Map();
      const rec = await b.localRepoBatchReadWorktree(worktreePath, wtPathList);
      const m = new Map<string, string>();
      Object.entries(rec).forEach(([p, txt]) => {
        if (txt != null) m.set(p, txt);
      });
      return m;
    },
    enabled: wtPathList.length > 0,
    staleTime: 5_000,
  });
  const wtContents = wtContentsQuery.data ?? null;

  // ── Per-comment staleness ──────────────────────────────────────────
  const stalenessById = useMemo(() => {
    const out = new Map<string, StalenessResult>();
    comments.forEach((c) => {
      const isWT = c.anchorSha === WORKING_TREE_ANCHOR;
      let fileContent: string | null;
      if (isWT) {
        fileContent = wtContents?.get(c.path) ?? null;
        if (wtContents == null) {
          out.set(c.id, { state: "fresh" });
          return;
        }
      } else {
        fileContent = contents.get(c.path)?.newText ?? null;
      }
      out.set(c.id, computeStaleness(c, headSha, fileContent));
    });
    return out;
  }, [comments, headSha, contents, wtContents]);

  const stalenessFor = useCallback(
    (commentId: string) => stalenessById.get(commentId),
    [stalenessById],
  );

  // Split LINE comments whose snippet no longer exists (a later commit
  // changed the line) out of the live anchoring: they FLOAT at the file's
  // first line with their frozen snippet, like the PR detail page's
  // outdated threads. File-level comments + fresh/moved comments stay live.
  const { liveGrouped, outdatedByPath } = useMemo(() => {
    const live: typeof comments = [];
    const floating = new Map<string, typeof comments>();
    comments.forEach((c) => {
      const outdated =
        c.line != null && stalenessById.get(c.id)?.state === "stale";
      if (outdated) {
        const arr = floating.get(c.path) ?? [];
        arr.push(c);
        floating.set(c.path, arr);
      } else {
        live.push(c);
      }
    });
    return { liveGrouped: groupComments(live), outdatedByPath: floating };
  }, [comments, stalenessById]);

  const renamedFilenames = useMemo(
    () => new Set(renamedFiles.map((f) => f.filename)),
    [renamedFiles],
  );
  const renameEntryByPath = useMemo(
    () => new Map(renamedFiles.map((f) => [f.filename, f])),
    [renamedFiles],
  );
  // All SVG paths get the preview/source header toggle; the ones NOT in
  // svgCodeMode render as a rendered-image preview (like binary images).
  const svgPaths = useMemo(
    () => new Set(svgFiles.map((f) => f.filename)),
    [svgFiles],
  );
  const previewSvgFiles = useMemo(
    () => svgFiles.filter((f) => !svgCodeMode.has(f.filename)),
    [svgFiles, svgCodeMode],
  );
  // Binary images ALWAYS preview; SVGs preview unless flipped to source.
  const imageEntries = useMemo(
    () => [...imageFiles, ...previewSvgFiles],
    [imageFiles, previewSvgFiles],
  );
  const imageFilenames = useMemo(
    () => new Set(imageEntries.map((f) => f.filename)),
    [imageEntries],
  );
  const binaryFilenames = useMemo(
    () => new Set(binaryFiles.map((f) => f.filename)),
    [binaryFiles],
  );

  // ── attach: compose the diff items with local annotations ──────────
  const attach = useCallback(
    (items: CodeViewDiffItem[]): ThreadDiffItem[] => {
      const withComments = attachLocalCommentsToItems(items, liveGrouped);
      const withLine = withLocalLineComposerAnnotation(withComments, lineComposer);
      const withRenameNote = withLocalRenameNoteAnnotations(withLine, renamedFiles);
      const withFile = withLocalFileComposerAnnotation(
        withRenameNote,
        fileComposerPath,
        anchorForPath,
      );
      // Outdated line comments float at the file's first line (frozen
      // snippet) instead of anchoring on a now-stale line.
      const withOutdated = withLocalOutdatedComments(withFile, outdatedByPath);
      // Local annotations carry LocalAnnotationMeta; cast to the diff
      // body's ThreadAnnotationMeta generic (opaque to the body), then
      // layer the shared `image` annotations on binary images + preview SVGs.
      const cast = withOutdated as unknown as ThreadDiffItem[];
      const withImages = withImageAnnotations(cast, imageEntries);
      return withBinaryNoteAnnotations(withImages, binaryFiles);
    },
    [
      liveGrouped,
      outdatedByPath,
      lineComposer,
      fileComposerPath,
      anchorForPath,
      renamedFiles,
      imageEntries,
      binaryFiles,
    ],
  );

  // ── gutter "+" → open the local line composer ──────────────────────
  const onGutterUtilityClick = useStableCallback(
    (
      range: SelectedLineRange,
      context: DiffBodyItemContext<ThreadAnnotationMeta>,
    ) => {
      if (context.type !== "diff") return;
      const path = context.item.id;
      const start = Math.min(range.start, range.end);
      const end = Math.max(range.start, range.end);
      const side: "LEFT" | "RIGHT" =
        (range.side ?? range.endSide ?? "additions") === "deletions"
          ? "LEFT"
          : "RIGHT";
      const anchorSha = anchorForPath(path);
      const isWT = anchorSha === WORKING_TREE_ANCHOR;
      const snippet = isWT
        ? readWtLineSnippet(wtContents, path, end)
        : readLineSnippet(contents, path, end, side);
      setLineComposer({
        path,
        line: end,
        startLine: start === end ? undefined : start,
        side,
        anchorSha,
        contentSnippet: snippet,
      });
    },
  );

  // ── render-time data via ref so the render callbacks read current
  //    values without churning the memoized layer on every change ─────
  const dataRef = useRef({
    grouped,
    stalenessFor,
    viewerLogin,
    viewedState,
    collapseState,
    renamedFilenames,
    binaryFilenames,
    renameEntryByPath,
    reviewId,
    contents,
    svgPaths,
    svgCodeMode,
    toggleSvgMode,
    worktreePath,
    oldRef,
    newRef,
  });
  dataRef.current = {
    grouped,
    stalenessFor,
    viewerLogin,
    viewedState,
    collapseState,
    renamedFilenames,
    binaryFilenames,
    renameEntryByPath,
    reviewId,
    contents,
    svgPaths,
    svgCodeMode,
    toggleSvgMode,
    worktreePath,
    oldRef,
    newRef,
  };

  const renderAnnotation = useCallback(
    (
      annotation:
        | LineAnnotation<ThreadAnnotationMeta>
        | DiffLineAnnotation<ThreadAnnotationMeta>,
    ): ReactNode => {
      const meta = annotation.metadata as unknown as
        | LocalAnnotationMeta
        | { kind: "image"; path: string; status: string; previousFilename?: string }
        | { kind: "binary-note"; path: string; status: string; previousFilename?: string }
        | undefined;
      if (!meta) return null;
      const d = dataRef.current;
      if (meta.kind === "local-comments") {
        // No embedded diff hunk in the Changes pane — the live diff line
        // is right above the card, so it'd be redundant (mirrors the
        // GitHub thread, which only embeds the hunk in the Conversation
        // timeline via `withAnchor`). The Overview tab embeds it instead.
        return (
          <LocalCommentStack
            comments={meta.comments}
            stalenessFor={d.stalenessFor}
          />
        );
      }
      if (meta.kind === "local-outdated") {
        // Outdated comments pinned at their original line — same card shell
        // as the GitHub inline thread's outdated treatment (muted fill +
        // Outdated badge), plus the FROZEN snippet captured at write time
        // (the live line no longer matches). The container badge carries
        // the outdated signal, so the cards don't repeat the chip.
        return (
          <div className="mx-3 mb-3 mt-1.5 box-border max-w-full overflow-hidden whitespace-normal rounded-lg border bg-muted/40 font-sans text-[13px]">
            <div className="space-y-2 p-2">
              <div className="flex flex-wrap items-center gap-1.5">
                <Badge
                  variant="outline"
                  className="gap-1 border-transparent bg-pyor-warn/15 px-1.5 py-0 text-[10px] font-semibold text-pyor-warn"
                >
                  <AlertTriangleIcon className="size-2.5" />
                  Outdated
                </Badge>
                <span className="text-[11px] text-muted-foreground/70">
                  line changed in a later commit
                </span>
              </div>
              {meta.comments.map((c) => (
                <LocalCommentCard key={c.id} comment={c} />
              ))}
            </div>
          </div>
        );
      }
      if (meta.kind === "local-line-composer") {
        return (
          <LocalLineCommentComposer
            reviewId={d.reviewId}
            path={meta.path}
            side={meta.side}
            line={meta.line}
            startLine={meta.startLine}
            anchorSha={meta.anchorSha}
            contentSnippet={meta.contentSnippet}
            authorLogin={d.viewerLogin}
            onClose={() => setLineComposer(null)}
          />
        );
      }
      if (meta.kind === "local-file-composer") {
        return (
          <LocalFileCommentComposer
            reviewId={d.reviewId}
            path={meta.path}
            anchorSha={meta.anchorSha}
            authorLogin={d.viewerLogin}
            onClose={() => setFileComposerPath(null)}
          />
        );
      }
      if (meta.kind === "local-rename-note") {
        return (
          <RenameNoteCard
            kind={resolveRenameKind(meta.previousFilename, meta.path)}
            onComment={() => setFileComposerPath(meta.path)}
          />
        );
      }
      if (meta.kind === "binary-note") {
        // No GitHub URL on the local surface — the bytes live in the working
        // tree / a local commit, so just the note + file-comment affordance.
        return (
          <BinaryFileCard
            onComment={() => setFileComposerPath(meta.path)}
          />
        );
      }
      if (meta.kind === "image") {
        // Before/after preview, offline: SVG text comes straight from the
        // loaded contents (data: URL); raster bytes via the local bridge.
        // old side = oldRef, new side = newRef (null = working tree).
        const loadImage = (
          p: string,
          ref: string | null,
        ): Promise<string | null> => {
          const isNew = ref === d.newRef;
          if (/\.svg$/i.test(p)) {
            const c = d.contents.get(p);
            const text = isNew ? c?.newText : c?.oldText;
            return Promise.resolve(
              text != null && text !== ""
                ? `data:image/svg+xml;utf8,${encodeURIComponent(text)}`
                : null,
            );
          }
          const b = bridge();
          return b
            ? b.localRepoReadImage(d.worktreePath, ref, p)
            : Promise.resolve(null);
        };
        return (
          <ImageDiffCard
            file={{
              filename: meta.path,
              status: meta.status,
              previousFilename: meta.previousFilename,
            }}
            baseSha={d.oldRef}
            headSha={d.newRef ?? undefined}
            loadImage={loadImage}
          />
        );
      }
      return null;
    },
    [],
  );

  const renderHeaderPrefix = useCallback(
    (item: CodeViewItem<ThreadAnnotationMeta>): ReactNode => {
      const path = item.id;
      const d = dataRef.current;
      const autoCollapsed = d.viewedState.isViewed(path);
      const chevron = d.collapseState ? (
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            d.collapseState!.toggle(path, autoCollapsed);
          }}
          title={
            d.collapseState.isCollapsed(path, autoCollapsed)
              ? "Expand file"
              : "Collapse file"
          }
          className="mr-0.5 inline-flex size-5 items-center justify-center rounded text-muted-foreground hover:bg-muted"
        >
          <span
            className="inline-flex transition-transform duration-[120ms]"
            style={{
              transform: d.collapseState.isCollapsed(path, autoCollapsed)
                ? "rotate(-90deg)"
                : "rotate(0deg)",
            }}
          >
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none">
              <path
                d="m6 9 6 6 6-6"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </span>
        </button>
      ) : null;
      const entry = d.renameEntryByPath.get(path);
      const pill = entry ? (
        <RenamePill kind={resolveRenameKind(entry.previousFilename, path)} />
      ) : null;
      return (
        <span className="contents">
          {(chevron || pill) && (
            <span className="inline-flex items-center gap-2">
              {chevron}
              {pill}
            </span>
          )}
          <span className="inline-flex items-center" style={{ order: 1 }}>
            <CopyPathButton anchor={{ path }} />
          </span>
        </span>
      );
    },
    [],
  );

  const renderHeaderMetadata = useCallback(
    (item: CodeViewItem<ThreadAnnotationMeta>): ReactNode => {
      const path = item.id;
      const d = dataRef.current;
      const isRename = d.renamedFilenames.has(path);
      const isBinary = d.binaryFilenames.has(path);
      const fileLevel = d.grouped.byFile.get(path) ?? [];
      const staleFileLevel = fileLevel.filter(
        (c) => d.stalenessFor(c.id)?.state === "stale",
      ).length;
      const isViewed = d.viewedState.isViewed(path);
      const isSvg = d.svgPaths.has(path);
      const svgInCode = d.svgCodeMode.has(path);
      return (
        <span className="inline-flex items-center gap-1.5 font-sans">
          {isRename && <RenameCounts />}
          {isBinary && <BinaryBadge />}
          {/* SVG preview/source toggle — mirrors the GitHub PR header. */}
          {isSvg && (
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                d.toggleSvgMode(path);
              }}
              className="inline-flex items-center gap-1 rounded border bg-card px-1.5 py-px text-[11px] font-medium text-muted-foreground hover:text-foreground"
              title={svgInCode ? "Show rendered preview" : "Show SVG source"}
            >
              {svgInCode ? (
                <ImageIcon className="size-3" />
              ) : (
                <CodeIcon className="size-3" />
              )}
              {svgInCode ? "Preview" : "Source"}
            </button>
          )}
          {fileLevel.length > 0 && (
            <span
              className="inline-flex items-center gap-1 rounded border border-pyor-warn/40 bg-pyor-warn/10 px-2 py-px text-[11.5px] text-pyor-warn"
              title={`${fileLevel.length} file-level note${fileLevel.length === 1 ? "" : "s"}`}
            >
              <MessageSquareIcon className="size-2.5" />
              {fileLevel.length}
            </span>
          )}
          {staleFileLevel > 0 && (
            <span
              className="inline-flex items-center gap-1 rounded border border-pyor-fail/40 bg-pyor-fail/10 px-2 py-px text-[11.5px] text-pyor-fail"
              title={`${staleFileLevel} stale file-level note${staleFileLevel === 1 ? "" : "s"}`}
            >
              {staleFileLevel} stale
            </span>
          )}
          {/* Comment-on-file */}
          <span
            onClick={(e) => {
              e.stopPropagation();
              setFileComposerPath(path);
            }}
            aria-label="Add a file-level note"
            className="inline-flex size-6 shrink-0 cursor-pointer select-none items-center justify-center rounded-md border bg-background text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
            title="Add a file-level note (local-only)"
          >
            <PlusIcon className="size-3.5" />
          </span>
          {/* Viewed toggle — per (commit, path), localStorage-backed */}
          <span
            onClick={(e) => {
              e.stopPropagation();
              d.viewedState.toggle(path);
            }}
            aria-label={isViewed ? "Mark as not viewed" : "Mark file as viewed"}
            className="inline-flex size-6 shrink-0 cursor-pointer select-none items-center justify-center rounded-md border bg-background text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
            title={isViewed ? "Mark as not viewed" : "Mark file as viewed"}
          >
            {isViewed ? (
              <CheckIcon className="size-3.5 text-pyor-pass" />
            ) : (
              <EyeIcon className="size-3.5" />
            )}
          </span>
        </span>
      );
    },
    [],
  );

  return useMemo<DiffAnnotationLayer>(
    () => ({
      attach,
      renderAnnotation,
      renderHeaderPrefix,
      renderHeaderMetadata,
      enableGutterUtility: true,
      onGutterUtilityClick,
      imageFilenames,
      renamedFilenames,
      binaryFilenames,
    }),
    [
      attach,
      renderAnnotation,
      renderHeaderPrefix,
      renderHeaderMetadata,
      onGutterUtilityClick,
      imageFilenames,
      renamedFilenames,
      binaryFilenames,
    ],
  );
}
