// The bespoke AI-grouped file rail (ADR 0026 / design `ai-grouping.jsx`,
// tinted variant), in place of @pierre/trees when the `ai` dimension is active.
// VIRTUALIZED: grouped/stale uses react-virtuoso `GroupedVirtuoso` so the group
// folders are STICKY (stay pinned while their files scroll under); the other
// states use plain `Virtuoso` over a banner + flat file list. Scales to large
// PRs. Centre-pane lockstep preserved via `view.orderedFiles`.

import { forwardRef, useEffect, useImperativeHandle, useRef, useState, type ReactNode } from 'react';
import { GroupedVirtuoso, Virtuoso, type VirtuosoHandle } from 'react-virtuoso';
import { cn } from '@/lib/utils';
import type { GHPullRequestFile } from '@/github/types';
import type { ThreadIndex } from '@/github/threads';
import type { ArrangedView } from '@/pr/changes/grouping/arrange';
import type { AiFolderMeta } from '@/pr/changes/grouping/types';
import { commentCountFor, folderViewedState } from '@/pr/changes/railDerivations';
import type { UseAiGrouping } from './useAiGrouping';
import { AiRunState, AiStaleBanner } from '../aikit';
import { AiFileRow, AiGroupFolderRow, type ViewedTri } from './AiGroupRow';
import { AiRailFooter, IdleCta, LoadingBody, errorRunKind } from './AiRailChrome';

function pctLabel(stat: { changed: number; pctLines: number } | undefined): string | undefined {
  if (!stat) return undefined;
  if (stat.changed > 0 && stat.pctLines < 1) return '<1%';
  return `${Math.round(stat.pctLines)}%`;
}
const triOf = (members: string[], viewedSet?: Set<string>): ViewedTri => {
  const s = folderViewedState(members, viewedSet);
  return s === 'none' ? 'unchecked' : s === 'full' ? 'checked' : 'partial';
};

// Non-grouped states render a flat item list (banner + files) through Virtuoso.
type RailItem = { t: 'node'; k: string; node: ReactNode } | { t: 'file'; k: string; path: string };

export interface AiGroupedRailProps {
  grouping: UseAiGrouping;
  view: ArrangedView;
  files: GHPullRequestFile[];
  fileCount: number;
  viewedSet?: Set<string>;
  loadingFilenames?: ReadonlySet<string>;
  commentCountByPath?: ReadonlyMap<string, number>;
  threadIndex?: ThreadIndex;
  currentPath?: string | null;
  filter?: string;
  onSelect?: (path: string) => void;
  onToggleViewed?: (path: string) => void;
  onSetFolderViewed?: (paths: string[], viewed: boolean) => void;
  onSetupAi?: () => void;
}

export interface AiGroupedRailHandle {
  setVisiblePath(path: string | null): void;
  scrollToPath(path: string): void;
}

const cssEsc = (s: string) => s.replace(/["\\]/g, '\\$&');

export const AiGroupedRail = forwardRef<AiGroupedRailHandle, AiGroupedRailProps>(function AiGroupedRail({
  grouping, view, files, fileCount, viewedSet, loadingFilenames, commentCountByPath, threadIndex,
  currentPath, filter = '', onSelect, onToggleViewed, onSetFolderViewed, onSetupAi,
}: AiGroupedRailProps, ref) {
  const { status, errorKind, retryAfter, capped, cost, estimate, ranAt, run, cancel } = grouping;
  const [collapsed, setCollapsed] = useState<Record<string, boolean>>({});
  const virtuosoRef = useRef<VirtuosoHandle>(null);
  const styleRef = useRef<HTMLStyleElement>(null);
  const visibleRef = useRef<string | null>(null);

  const fileByName = new Map(files.map((f) => [f.filename, f]));
  const q = filter.trim().toLowerCase();
  const matches = (path: string) => !q || path.toLowerCase().includes(q);
  const isGrouped = status === 'grouped' || status === 'stale';

  // ── Grouped data (sticky groups + their files) ────────────────────
  const groups = isGrouped
    ? view.folderOrder
        .map((seg) => {
          const meta = view.folderMeta.get(seg);
          const members = (view.folderMembers.get(seg) ?? []).filter(matches);
          return meta && members.length ? { seg, meta, members, important: meta.kind === 'important', isNew: meta.name === 'Ungrouped · new' } : null;
        })
        .filter((g): g is { seg: string; meta: AiFolderMeta; members: string[]; important: boolean; isNew: boolean } => !!g)
    : [];
  const isCollapsed = (g: (typeof groups)[number]) => collapsed[g.seg] ?? (!g.important && !g.isNew);
  const groupCounts = groups.map((g) => (isCollapsed(g) ? 0 : g.members.length));
  const flatFiles = groups.flatMap((g) => (isCollapsed(g) ? [] : g.members));
  const firstNoiseIdx = groups.findIndex((g) => !g.important && !g.isNew);

  // ── Non-grouped data (banner + flat files) ────────────────────────
  const rows: RailItem[] = [];
  if (!isGrouped) {
    const pushFlat = () => files.filter((f) => matches(f.filename)).forEach((f) => rows.push({ t: 'file', k: `f:${f.filename}`, path: f.filename }));
    const sectionLabel = <div className="px-3 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">Files · flat</div>;
    if (status === 'locked') {
      rows.push({ t: 'node', k: 'rs', node: <div className="p-3"><AiRunState kind="no-key" layout="rail" onSetup={onSetupAi} /></div> });
      rows.push({ t: 'node', k: 'sec', node: sectionLabel });
      pushFlat();
    } else if (status === 'idle') {
      rows.push({ t: 'node', k: 'cta', node: <div className="p-3"><IdleCta fileCount={fileCount} estimate={estimate} onRun={run} /></div> });
      rows.push({ t: 'node', k: 'sec', node: sectionLabel });
      pushFlat();
    } else if (status === 'error' || status === 'empty') {
      rows.push({ t: 'node', k: 'rs', node: (
        <div className="p-3">
          <AiRunState kind={status === 'empty' ? 'empty' : errorRunKind(errorKind)} layout="rail" wait={retryAfter ? `${retryAfter}s` : undefined} onRetry={run} onSetup={onSetupAi} />
          <p className="mt-2 px-0.5 text-[10.5px] text-muted-foreground">Files stay listed below — the error never blocks plain review.</p>
        </div>
      ) });
      pushFlat();
    }
  }

  // path → item index (Virtuoso item index for grouped; row index otherwise).
  const indexByPath = new Map<string, number>();
  if (isGrouped) flatFiles.forEach((p, i) => indexByPath.set(p, i));
  else rows.forEach((it, i) => { if (it.t === 'file') indexByPath.set(it.path, i); });
  const indexRef = useRef(indexByPath);
  indexRef.current = indexByPath;

  useImperativeHandle(ref, () => ({
    setVisiblePath(path) {
      if (visibleRef.current === path) return;
      visibleRef.current = path;
      if (styleRef.current) styleRef.current.textContent = path ? `[data-ai-file="${cssEsc(path)}"]{box-shadow:inset 2px 0 0 #3b82f6}` : '';
      const i = path != null ? indexRef.current.get(path) : undefined;
      if (i != null) virtuosoRef.current?.scrollIntoView({ index: i, behavior: 'smooth' });
    },
    scrollToPath(path) {
      const i = indexRef.current.get(path);
      if (i != null) virtuosoRef.current?.scrollIntoView({ index: i, behavior: 'smooth' });
    },
  }));
  useEffect(() => {
    if (!currentPath) return;
    const i = indexRef.current.get(currentPath);
    if (i != null) virtuosoRef.current?.scrollIntoView({ index: i, behavior: 'smooth' });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentPath]);

  const renderFile = (path: string) => {
    const f = fileByName.get(path);
    return (
      <AiFileRow
        path={path}
        add={f?.additions ?? 0}
        del={f?.deletions ?? 0}
        status={f?.status}
        viewed={viewedSet?.has(path)}
        loading={loadingFilenames?.has(path)}
        comments={commentCountFor(path, commentCountByPath, threadIndex)}
        current={path === currentPath}
        onSelect={() => onSelect?.(path)}
        onToggleViewed={onToggleViewed ? () => onToggleViewed(path) : undefined}
      />
    );
  };

  const footer = <AiRailFooter status={status} fileCount={fileCount} ranAt={ranAt} cost={cost} />;

  if (status === 'loading') {
    return (
      <>
        <div className="min-h-0 flex-1 overflow-auto"><LoadingBody capped={capped} fileCount={fileCount} onCancel={cancel} /></div>
        {footer}
      </>
    );
  }

  return (
    <>
      <div className="min-h-0 flex-1">
        {isGrouped ? (
          <GroupedVirtuoso
            ref={virtuosoRef}
            style={{ height: '100%' }}
            groupCounts={groupCounts}
            components={status === 'stale' ? { Header: () => <div className="px-2 pb-1.5 pt-1"><AiStaleBanner kind="compact" onRun={run} /></div> } : {}}
            groupContent={(gi) => {
              const g = groups[gi];
              // bg-card keeps the (translucent) sticky header opaque so files
              // scrolling under it don't bleed through; the first noise group
              // gets the important/noise divider as a top border.
              return (
                <div className={cn('bg-card', gi === firstNoiseIdx && 'border-t border-border/70')}>
                  <AiGroupFolderRow
                    name={g.meta.name}
                    description={g.meta.description}
                    important={g.important}
                    isNew={g.isNew}
                    count={g.members.length}
                    pct={pctLabel(view.folderStats.get(g.seg))}
                    viewedState={triOf(g.members, viewedSet)}
                    collapsed={isCollapsed(g)}
                    onToggleCollapse={() => setCollapsed((c) => ({ ...c, [g.seg]: !isCollapsed(g) }))}
                    onToggleViewed={() => onSetFolderViewed?.(g.members, triOf(g.members, viewedSet) !== 'checked')}
                  />
                </div>
              );
            }}
            itemContent={(i) => renderFile(flatFiles[i])}
          />
        ) : (
          <Virtuoso
            ref={virtuosoRef}
            style={{ height: '100%' }}
            data={rows}
            computeItemKey={(_, it) => it.k}
            itemContent={(_, it) => (it.t === 'node' ? it.node : renderFile(it.path))}
          />
        )}
      </div>
      {footer}
      {/* Injected rule for the diff-scroll "visible file" accent — keyed by the
          stable data-ai-file attr so it survives virtualization. */}
      <style ref={styleRef} />
    </>
  );
});
