// ADR 0012 Phase 6 — useExportLocalReview hook.
//
// Wires the Local Review surface's `Export for LLM…` toolbar action to
// the bridge. Pulls comments out of localStorage, runs them through
// the pure generators in `localReviewExport.ts`, prompts the user for
// a destination folder via the bridge's native picker, then asks main
// to write the bundle and (on success) reveal it in Finder/Explorer.
//
// **Staleness v1 simplification:** this hook does NOT recompute
// staleness from file contents. It accepts an optional `stalenessById`
// map from the caller (the surface already memoises one for the in-app
// chips, see `LocalReviewDiffBody.stalenessById`) and falls back to
// `undefined` for any comment without an entry — the generators print
// `(unknown)` for missing staleness. A future enhancement can thread
// the surface's map down to this hook so every comment exports with
// an accurate marker.
//
// Returns a callable async function; the caller owns the pending
// state. Errors are surfaced as Sonner toasts inside the hook and
// also re-thrown so callers can flip their pending flag back off in a
// finally block.

import { useCallback } from 'react';
import { toast } from 'sonner';
import { bridge } from '../desktop/electronBridge';
import type { LocalReview } from './localReviews';
import { listLocalReviewComments } from './localReviewComments';
import type { StalenessResult } from './localReviewStaleness';
import {
  renderCommentsJson,
  renderCommentsMarkdown,
  renderReadme,
  type ExportCommentView,
} from './localReviewExport';

/** Optional metadata the caller can pass through to enrich the
 * exported header line. The surface already has these numbers from
 * its diff query — wiring them through gives the LLM a hint of the
 * change's size without an extra git call. */
export interface ExportLocalReviewExtras {
  /** Current head SHA at export time. Defaults to the empty string
   * (renders as the header without a SHA), but the surface should
   * always pass `diff.head`. */
  headSha?: string;
  /** Optional file count for the header line. */
  fileCount?: number;
  /** Optional commit count for the header line. */
  commitCount?: number;
  /** Per-comment staleness map from the surface's in-memory
   * computation. When omitted, every comment exports with
   * `(unknown)` staleness — still a useful bundle, just without the
   * fresh/moved/stale hint. */
  stalenessById?: Map<string, StalenessResult>;
}

/** Trigger function returned by the hook. Resolves to the absolute
 * bundle path on success, or `null` when the user cancels the folder
 * picker. Errors propagate so the caller can reset pending state. */
export type ExportLocalReviewFn = (
  extras?: ExportLocalReviewExtras,
) => Promise<string | null>;

export function useExportLocalReview(review: LocalReview): ExportLocalReviewFn {
  return useCallback(
    async (extras?: ExportLocalReviewExtras): Promise<string | null> => {
      const b = bridge();
      if (!b) {
        toast.error('Export needs the desktop build');
        return null;
      }
      const comments = listLocalReviewComments(review.id);
      const stalenessById = extras?.stalenessById ?? null;
      const views: ExportCommentView[] = comments.map((c) => ({
        comment: c,
        staleness: stalenessById?.get(c.id),
      }));
      const meta = {
        review,
        headSha: extras?.headSha ?? '',
        exportedAt: new Date().toISOString(),
        commitCount: extras?.commitCount,
        fileCount: extras?.fileCount,
      };
      const commentsMarkdown = renderCommentsMarkdown(meta, views);
      const commentsJson = renderCommentsJson(meta, views);
      // README's commentCount mirrors the generators' "dismissed
      // excluded" rule — count active comments, not the raw total.
      const activeCount = comments.filter((c) => !c.dismissed).length;
      const readme = renderReadme(meta, activeCount);
      const bundleDirName = buildBundleDirName(review.branch);

      let parentDir: string | null;
      try {
        parentDir = await b.localReviewPickExportParent();
      } catch (e) {
        toast.error('Could not open folder picker', {
          description: e instanceof Error ? e.message : String(e),
        });
        throw e;
      }
      if (!parentDir) return null;

      let bundlePath: string;
      try {
        bundlePath = await b.localReviewExport({
          reviewId: review.id,
          bundleDirName,
          parentDir,
          commentsMarkdown,
          commentsJson,
          readme,
        });
      } catch (e) {
        toast.error('Could not export local review', {
          description: e instanceof Error ? e.message : String(e),
        });
        throw e;
      }

      toast.success(
        `Exported ${activeCount} note${activeCount === 1 ? '' : 's'}`,
        { description: bundlePath },
      );
      // Best-effort reveal — if it fails we still consider the export
      // a success (the bundle is on disk).
      try {
        await b.shellReveal(bundlePath);
      } catch (e) {
        // eslint-disable-next-line no-console
        console.warn('shellReveal failed:', e);
      }
      return bundlePath;
    },
    [review],
  );
}

/** Build `local-review-<sanitised-branch>-<YYYYMMDDHHMM>`. The branch
 * sanitisation strips characters that aren't safe across filesystems
 * (slashes, colons, etc.) — git lets you use most of them in branch
 * names but a path component can't contain `/`. The timestamp is
 * minute-precision; bursts of exports inside the same minute land
 * under suffixed `-2`, `-3`, … via main's collision handler. */
function buildBundleDirName(branch: string): string {
  const sanitised = branch.replace(/[^A-Za-z0-9._-]/g, '-');
  // Guard against empty result (e.g. branch was purely special chars
  // — extremely unlikely but cheap to defend).
  const safeBranch = sanitised.length > 0 ? sanitised : 'branch';
  return `local-review-${safeBranch}-${stampNow()}`;
}

function stampNow(): string {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  const hh = String(d.getHours()).padStart(2, '0');
  const mi = String(d.getMinutes()).padStart(2, '0');
  return `${yyyy}${mm}${dd}${hh}${mi}`;
}
