// Inline composer for a file-level comment. Opened by clicking the
// "Comment on file" pill in a diff file header. Same shape as
// NewCommentComposer but anchored to the file as a whole (subject_type
// = file). "Start a review" adds it to the viewer's GitHub pending
// review; "Add single comment" publishes it immediately (ADR 0019).
//
// Design parity: gh-comments.jsx · GhComposer — the rich Write/Preview
// composer, prefixed with a compact file-anchor label + "Pending" badge.

import { useQuery } from '@tanstack/react-query';
import { Badge } from '@/components/ui/badge';
import type { DraftActions } from '../../review/reviewDraftTypes';
import { prPendingReviewOptions } from '../../github/prQueries';
import { Icon } from '../../ui/Icon';
import { GhComposer } from '../conversation/GhComposer';
import {
  OfflineComposerNotice,
  useComposerOffline,
} from '../conversation/OfflineComposerNotice';
import { useSingleComment } from '../usePendingReview';
import { useGithubAssetsUploader } from '../conversation/composer/useGithubAssetsUploader';

interface Props {
  path: string;
  draftActions: DraftActions;
  viewerLogin?: string;
  /** PR coordinates for `@`/`#` autocomplete (threaded from LiveDiffPane). */
  owner?: string;
  repo?: string;
  number?: number;
  onClose: () => void;
}

export function NewFileCommentComposer({
  path,
  draftActions,
  viewerLogin,
  owner,
  repo,
  number,
  onClose,
}: Props) {
  void viewerLogin; // composer no longer renders an avatar
  const uploadImage = useGithubAssetsUploader();
  const offline = useComposerOffline();
  const single = useSingleComment(owner ?? '', repo ?? '', number ?? 0);
  const pendingQuery = useQuery({
    ...prPendingReviewOptions(owner ?? '', repo ?? '', number ?? 0),
    enabled: !!owner && !!repo && !!number,
  });
  const hasPendingReview = !!pendingQuery.data;

  const save = (body: string) => {
    if (!body.trim()) return;
    draftActions.addFileComment({ path, body });
    onClose();
  };

  const publishSingle = (body: string) => {
    if (!body.trim()) return;
    single.mutate({ kind: 'file', path, body });
    onClose();
  };

  if (offline) {
    return (
      <div className="font-sans whitespace-normal">
        <OfflineComposerNotice onCancel={onClose} />
      </div>
    );
  }

  return (
    // font-sans + whitespace-normal: this composer mounts inside the
    // @pierre/diffs CodeView (mono + pre-wrap), so reset the context's code
    // styles on the label row too (GhComposer resets its own).
    <div className="mx-3 mb-3 mt-1.5 box-border max-w-full font-sans whitespace-normal">
      <div className="mb-1.5 flex min-w-0 items-center gap-2 px-0.5 text-[11.5px] text-foreground">
        <Icon name="file" size={12} color="hsl(var(--pyor-warn))" />
        <span className="shrink-0 font-semibold">New file-level comment</span>
        <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-muted-foreground">
          · {path}
        </span>
        <Badge
          variant="outline"
          className="shrink-0 border-pyor-warn/40 font-semibold text-pyor-warn"
        >
          Pending
        </Badge>
      </div>
      <GhComposer
        draftKey={
          owner && repo ? `${owner}/${repo}/${number}:file:${path}` : undefined
        }
        placeholder="File-level feedback… (Markdown · ⌘⏎ to add to your review · Esc to cancel)"
        submitLabel={hasPendingReview ? 'Add review comment' : 'Start a review'}
        submitIcon="check"
        draftHint="File-level comments don't anchor to a line — use them for whole-file feedback"
        autoFocus
        minHeight={84}
        threadCompose
        onUploadImage={uploadImage}
        mentionContext={owner && repo ? { owner, repo, number } : undefined}
        onCancel={onClose}
        onSubmit={save}
        secondaryAction={
          hasPendingReview
            ? undefined
            : { label: 'Add single comment', onClick: publishSingle }
        }
      />
    </div>
  );
}
