// "Settled" derivation for Conversation Focus mode.
//
// In Focus mode the timeline demotes SETTLED discussion — anything you no
// longer need to act on — to a one-line row inside a `SettledBand`, so the
// open/pending discussion reads without the dead weight. A discussion item
// is settled when it is any of three states:
//
//   resolved — the review thread is explicitly marked resolved, OR a
//              PR-level review is an approval (nothing left to act on).
//   outdated — the anchored line moved/changed in a later push, so the
//              comment no longer maps into the current diff.
//   stale    — old discussion or a bot notice with no recent activity that
//              isn't awaiting the viewer's response.
//
// Open / pending items (unresolved threads, changes-requested reviews, your
// own pending draft, recent comments) return `null` and stay full cards.

import type {
  GHReview,
  GHReviewComment,
  GHTimelineEvent,
} from '../../github/types';
import type { ResolvableThread } from '../../github/client';
import { plainTextPreview } from '../../github/reactionHelpers';
import { humanAge } from '../../util/relTime';
import { threadAwaitsViewer } from './unrepliedFilter';

export type SettledStatus = 'resolved' | 'outdated' | 'stale' | 'handled';

/** A discussion item is "stale" once it has had no activity for this long
 * AND nothing awaits the viewer. Tunable — long enough that an actively
 * discussed PR keeps its recent comments full. */
export const STALE_DAYS = 14;
const STALE_MS = STALE_DAYS * 24 * 60 * 60 * 1000;

/** The compact one-line row's props (see `CompactSettledRow`). */
export interface SettledCompact {
  status: SettledStatus;
  author: string;
  authorAvatarUrl?: string;
  /** Already suffixed with " ago" — e.g. "20h ago". */
  age?: string;
  summary: string;
  replies: number;
  /** Present → renders the inline-thread `file:line` reference. */
  file?: string;
  line?: number | null;
  /** PR-level verdict hint shown next to the row. */
  reviewState?: 'approved' | 'changes';
}

function ageMs(iso: string | null | undefined, now: number): number {
  if (!iso) return Infinity;
  const t = Date.parse(iso);
  return Number.isNaN(t) ? Infinity : now - t;
}

/** Bot / automation authors whose notices are stale the moment they land
 * (deploy previews, CI recaps) — independent of the age window. */
function isBot(login: string | undefined): boolean {
  if (!login) return false;
  return (
    login.endsWith('[bot]') ||
    login.endsWith('-bot') ||
    login === 'github-actions'
  );
}

function age(iso: string | null | undefined): string | undefined {
  return iso ? `${humanAge(iso)} ago` : undefined;
}

/** Settled state for an inline review thread, or null when it's still
 * open (unresolved, in-diff, and recently active). */
export function settledForThread(
  head: GHReviewComment,
  replies: GHReviewComment[],
  gqlThread: ResolvableThread | undefined,
  viewerLogin: string | undefined,
  now: number,
  /** Pending-comments variant: also compact threads NOT awaiting the
   * viewer's reply (you spoke last → handled), regardless of age. */
  compactHandled = false,
): SettledCompact | null {
  const comments = [head, ...replies];
  const base = {
    author: head.user.login,
    authorAvatarUrl: head.user.avatar_url,
    age: age(head.created_at),
    summary: plainTextPreview(head.body),
    replies: replies.length,
    file: head.path,
    line: head.line ?? head.original_line,
  };
  if (gqlThread?.isResolved) return { ...base, status: 'resolved' };
  // Outdated: the live anchor line is gone (matches TimelineThreadItem).
  if (head.line == null && head.original_line != null) {
    return { ...base, status: 'outdated' };
  }
  // Nothing awaits the viewer (they spoke last, or it's an old thread
  // nobody's pushing). In Pending mode that's "handled" at any age; in
  // All mode it only compacts once dormant ("stale").
  if (!threadAwaitsViewer(comments, viewerLogin)) {
    if (compactHandled) return { ...base, status: 'handled' };
    const last = comments[comments.length - 1];
    if (ageMs(last.updated_at ?? last.created_at, now) > STALE_MS) {
      return { ...base, status: 'stale' };
    }
  }
  return null;
}

/** Settled state for a PR-level review verdict. Approvals are settled;
 * changes-requested stays open; a plain commented recap goes stale once
 * it's old. */
export function settledForReview(
  review: GHReview,
  now: number,
): SettledCompact | null {
  if (review.state === 'CHANGES_REQUESTED' || review.state === 'PENDING') {
    return null;
  }
  const base = {
    author: review.user?.login ?? 'unknown',
    authorAvatarUrl: review.user?.avatar_url,
    age: age(review.submitted_at),
    summary: plainTextPreview(review.body),
    replies: 0,
    reviewState: 'approved' as const,
  };
  if (review.state === 'APPROVED') return { ...base, status: 'resolved' };
  // COMMENTED / DISMISSED — settled only once dormant.
  if (ageMs(review.submitted_at, now) > STALE_MS) {
    return { ...base, status: 'stale', reviewState: undefined };
  }
  return null;
}

/** Settled state for a top-level (issue) comment event. Only ever stale —
 * a bot notice, or an old remark with no recent activity. */
export function settledForComment(
  event: GHTimelineEvent,
  now: number,
): SettledCompact | null {
  if (event.event !== 'commented') return null;
  const login = event.actor?.login ?? event.user?.login;
  const stale = isBot(login) || ageMs(event.created_at, now) > STALE_MS;
  if (!stale) return null;
  return {
    status: 'stale',
    author: login ?? 'unknown',
    authorAvatarUrl: event.actor?.avatar_url ?? event.user?.avatar_url,
    age: age(event.created_at),
    summary: plainTextPreview(event.body ?? ''),
    replies: 0,
  };
}
