// "Similar changes" clustering — finds files whose edits are near-
// identical (the classic migration PR: the same change repeated across
// many files). Pure, runs on the `patch` strings already fetched — no
// clone, no static analysis (ADR 0002). MinHash/LSH libraries exist but
// are built for millions of docs; a PR has tens, so a direct O(n²)
// Jaccard pass over normalized change-line sets is instant and dependency-
// free.

import type { GHPullRequestFile } from '../../../github/types';
import type { AutoAssignment } from './types';

/** Pull the meaningful changed lines out of a unified-diff patch: keep
 * only added/removed lines, strip the +/- marker and surrounding noise
 * (hunk headers, file markers), and trim. The resulting set is what two
 * files are compared on. */
function normalizeChangedLines(patch: string | undefined): string[] {
  if (!patch) return [];
  return patch
    .split('\n')
    .filter((l) => /^[+-]/.test(l) && !/^(\+\+\+|---)/.test(l))
    .map((l) => l.slice(1).trim())
    .filter((l) => l.length > 0);
}

/** Jaccard similarity of two string sets: |A∩B| / |A∪B|. */
function jaccard(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0;
  const inter = [...a].filter((x) => b.has(x)).length;
  const union = a.size + b.size - inter;
  return union === 0 ? 0 : inter / union;
}

/** Cluster files by patch similarity. Greedy seed-linkage: each unassigned
 * file with changed lines seeds a cluster of every still-unassigned file
 * within `threshold` of it; clusters below `minCluster` dissolve. Returns
 * real path → AutoAssignment for clustered files only (others stay loose). */
export function clusterSimilar(
  files: GHPullRequestFile[],
  threshold = 0.7,
  minCluster = 2,
): Map<string, AutoAssignment> {
  const sets = files.map((f) => new Set(normalizeChangedLines(f.patch)));
  const assigned: boolean[] = files.map(() => false);
  const clusters: number[][] = [];

  files.forEach((_, i) => {
    if (assigned[i] || sets[i].size === 0) return;
    const members = files
      .map((__, j) => j)
      .filter(
        (j) =>
          !assigned[j] &&
          sets[j].size > 0 &&
          (j === i || jaccard(sets[i], sets[j]) >= threshold),
      );
    if (members.length < minCluster) return;
    members.forEach((j) => {
      assigned[j] = true;
    });
    clusters.push(members);
  });

  const result = new Map<string, AutoAssignment>();
  clusters
    .sort((a, b) => b.length - a.length || a[0] - b[0])
    .forEach((members, idx) => {
      const label = `Similar group ${idx + 1} · ${members.length} files`;
      members.forEach((j) =>
        result.set(files[j].filename, {
          groupId: `sim:${idx}`,
          groupLabel: label,
          order: idx,
        }),
      );
    });
  return result;
}
