// CompactHeader — the collapsed PR header that slides down once the full
// header has scrolled away (see CollapsingHeaderZone). A separate one-row
// bar that REUSES the PR-detail leaf components (status menu, checks hover
// card, copy-branch badge, focus toggle, reviewer chips) in their compact
// forms, plus a ⋯ overflow for the metadata that doesn't fit.
//
// Its data layer mirrors PRHeader's (same React Query keys, so it's deduped
// — no extra network). PRHeader stays untouched; we only import its already-
// shared leaf components.

import { useMemo, type ReactNode } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  ChevronLeftIcon,
  CloudSyncIcon,
  FileIcon,
  GitBranchIcon,
  MessageSquareIcon,
  type LucideIcon,
} from 'lucide-react';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { Button } from '@/components/ui/button';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { cn } from '@/lib/utils';
import type { DiffMode } from '../changes/diffMode';
import {
  CompactDiffModeToggle,
  CollapseControls,
  CompactViewedProgress,
} from '../changes/SubToolbar';
import type { GHPullRequest } from '../../github/types';
import {
  countRollup,
  getReviewComments,
  getReviews,
} from '../../github/client';
import { hasWriteAccess } from '../../github/lifecycle';
import { prCheckRollupOptions } from '../../github/prQueries';
import { fullDate, relTime } from '../../util/relTime';
import { GithubMark } from '../../ui/GithubMark';
import { markGithubPassthrough } from '../../util/githubPassthrough';
import type { PRTab } from '../PRTabs';
import { FocusToggle } from '../FocusToggle';
import { useLifecycle } from '../lifecycle/useLifecycle';
import { StatusPillMenu, type MergeSummary } from '../lifecycle/StatusPillMenu';
import { useReviewerManagement } from '../lifecycle/useReviewerManagement';
import {
  ChecksHoverCard,
  CopyBranchBadge,
  ReviewerChipHover,
  AddReviewerChip,
  collectReviewerStates,
} from '../PRHeader';

const TABS: { id: PRTab; label: string; icon: LucideIcon }[] = [
  { id: 'description', label: 'Conversation', icon: MessageSquareIcon },
  { id: 'commits', label: 'Commits', icon: GitBranchIcon },
  { id: 'changes', label: 'Files changed', icon: FileIcon },
];

export interface CompactHeaderProps {
  pr?: GHPullRequest;
  owner?: string;
  repo?: string;
  readOnly?: boolean;
  activeTab?: PRTab;
  onTabChange?: (t: PRTab) => void;
  onBack?: () => void;
  backLabel?: string;
  focusMode?: boolean;
  onToggleFocusMode?: () => void;
  commentFocusIsNew?: boolean;
  onSelectCommentFocus?: (isNew: boolean) => void;
  commentCounts?: { all: number; pending: number };
  onJumpToMergeBox?: () => void;
  onJumpToComment?: Parameters<typeof ReviewerChipHover>[0]['onJumpToComment'];
  /** Files-tab diff controls — the inline/split switcher + collapse dropdown
   * (the same components as the full toolbar). Null/absent off the Changes tab. */
  diffTools?: {
    diffMode: DiffMode;
    onDiffModeChange: (m: DiffMode) => void;
    viewed: number;
    totalFiles: number;
    onCollapseAll?: () => void;
    onExpandAll?: () => void;
    onResetCollapse?: () => void;
    onCollapseWithoutComments?: () => void;
    filesWithoutCommentsCount?: number;
  } | null;
  /** The "Review with AI" trigger, lifted onto the compact bar so the AI
   * review affordance survives the header collapse (ADR 0026 / hdr-compact-*).
   * Built by the Changes tab from its single useAiHints instance; null off the
   * Changes tab or when AI is off. */
  aiReviewTrigger?: ReactNode;
}

export function CompactHeader({
  pr,
  owner,
  repo,
  readOnly = false,
  activeTab,
  onTabChange,
  onBack,
  backLabel = 'Inbox',
  focusMode = false,
  onToggleFocusMode,
  commentFocusIsNew = false,
  onSelectCommentFocus,
  commentCounts,
  onJumpToMergeBox,
  onJumpToComment,
  diffTools,
  aiReviewTrigger,
}: CompactHeaderProps) {
  const liveStatus: 'open' | 'merged' | 'draft' | 'closed' = pr?.draft
    ? 'draft'
    : pr?.merged_at
      ? 'merged'
      : pr?.state ?? 'open';
  const checksHistorical = liveStatus === 'merged' || liveStatus === 'closed';
  const active = activeTab ?? 'description';

  // ── data (mirrors PRHeader; shared query keys → deduped) ──
  const lifecycle = useLifecycle(pr, owner, repo, { readOnly });
  const canManageReviewers = hasWriteAccess(lifecycle.viewerPermission);
  const reviewerMgmt = useReviewerManagement(
    owner ?? '',
    repo ?? '',
    pr?.number ?? 0,
  );
  const reviewsQuery = useQuery({
    queryKey: ['pr', owner!, repo!, pr?.number!, 'reviews'],
    queryFn: () => getReviews(owner!, repo!, pr!.number),
    enabled: !!(owner && repo && pr),
    staleTime: 60_000,
  });
  const reviewCommentsQuery = useQuery({
    queryKey: ['pr', owner!, repo!, pr?.number!, 'comments'],
    queryFn: () => getReviewComments(owner!, repo!, pr!.number),
    enabled: !!(owner && repo && pr),
    staleTime: 60_000,
  });
  const reviewerStates = useMemo(
    () =>
      collectReviewerStates(
        pr,
        reviewsQuery.data ?? [],
        reviewCommentsQuery.data ?? [],
      ),
    [pr, reviewsQuery.data, reviewCommentsQuery.data],
  );
  const checksQuery = useQuery({
    ...prCheckRollupOptions(owner!, repo!, pr?.number!, pr?.head.sha),
    enabled: !!(owner && repo && pr?.head.sha),
  });
  const checkCounts = useMemo(
    () => countRollup(checksQuery.data?.checks ?? []),
    [checksQuery.data],
  );
  const mergeSummary: MergeSummary | undefined = useMemo(() => {
    if (!pr || liveStatus !== 'open') return undefined;
    const approvals = reviewerStates.filter((r) => r.state === 'approved').length;
    const changesReq = reviewerStates.filter((r) => r.state === 'changes').length;
    const conflicts = pr.mergeable === false || pr.mergeable_state === 'dirty';
    const behind = pr.mergeable_state === 'behind';
    const blocked = pr.mergeable_state === 'blocked';
    const ready =
      changesReq === 0 &&
      checkCounts.fail === 0 &&
      checkCounts.pending === 0 &&
      !conflicts &&
      !blocked;
    if (ready) {
      return {
        ready: true,
        line: `${checkCounts.pass > 0 ? `All ${checkCounts.pass} checks passed` : 'No required checks'} · ${approvals} approval${approvals === 1 ? '' : 's'} · no conflicts`,
      };
    }
    const parts: string[] = [];
    if (checkCounts.fail > 0) parts.push(`${checkCounts.fail} checks failing`);
    if (changesReq > 0) parts.push('changes requested');
    if (conflicts) parts.push('conflicts');
    else if (behind) parts.push('behind base');
    if (checkCounts.pending > 0) parts.push(`${checkCounts.pending} pending`);
    return {
      ready: false,
      line: parts.length > 0 ? parts.join(' · ') : 'merge requirements not met',
    };
  }, [pr, liveStatus, reviewerStates, checkCounts]);

  const hasChecks =
    checkCounts.fail > 0 || checkCounts.pass > 0 || checkCounts.pending > 0;
  const liveAuthor = pr?.user.login ?? '—';

  return (
    <div className="flex h-9 items-center gap-2 border-b bg-card px-[18px] text-[12px]">
      {/* back */}
      {onBack ? (
        <button
          type="button"
          onClick={onBack}
          title={backLabel}
          className="inline-flex shrink-0 cursor-pointer items-center text-muted-foreground transition-colors hover:text-foreground"
        >
          <ChevronLeftIcon className="size-4" />
        </button>
      ) : (
        <ChevronLeftIcon className="size-4 shrink-0 text-muted-foreground" />
      )}

      {/* tab segment — same switcher component as the split/inline diff toggle */}
      <Tabs
        value={active}
        onValueChange={(v) => onTabChange?.(v as PRTab)}
        className="shrink-0"
      >
        <TabsList indicator="pill" className="h-7 p-0.5">
          {TABS.map((t) => {
            const Icon = t.icon;
            return (
              <TabsTrigger
                key={t.id}
                value={t.id}
                title={t.label}
                aria-label={t.label}
                className="h-6 w-7 p-0 data-[state=active]:bg-transparent data-[state=active]:shadow-none"
              >
                <Icon className="size-3.5" />
              </TabsTrigger>
            );
          })}
        </TabsList>
      </Tabs>

      {/* status pill — the exact same chip as the full header */}
      <span className="shrink-0">
        <StatusPillMenu
          status={liveStatus}
          lifecycle={lifecycle}
          pr={pr}
          mergeSummary={mergeSummary}
          onJumpToMergeBox={onJumpToMergeBox}
        />
      </span>

      {/* title + number, then the head branch chip (copy-on-click) */}
      <span className="flex min-w-0 flex-1 items-center gap-2 overflow-hidden">
        <span className="flex min-w-0 items-baseline gap-1.5 overflow-hidden">
          <span className="truncate text-[14px] font-semibold text-foreground">
            {pr?.title ?? 'Loading…'}
          </span>
          {pr && (
            <span className="shrink-0 font-mono text-[12px] text-muted-foreground/70">
              #{pr.number}
            </span>
          )}
        </span>
        {pr && (
          <span className="inline-flex shrink-0 items-center whitespace-nowrap font-mono text-[11px]">
            <CopyBranchBadge branch={pr.head.ref} />
          </span>
        )}
        {/* author avatar (avatars-only, name via tooltip) sits next to the branch */}
        {pr && (
          <span
            className="relative inline-flex shrink-0 items-center"
            title={`Author · ${liveAuthor}`}
          >
            <Avatar className="size-5 ring-2 ring-background">
              {pr.user.avatar_url && (
                <AvatarImage src={pr.user.avatar_url} alt={liveAuthor} />
              )}
              <AvatarFallback className="text-[9px]">
                {liveAuthor.slice(0, 2).toUpperCase()}
              </AvatarFallback>
            </Avatar>
          </span>
        )}
      </span>

      {/* reviewers — avatars only (names via hover card) */}
      <span className="inline-flex shrink-0 items-center">
        {reviewerStates.map((r, i) => (
          <ReviewerChipHover
            key={r.login}
            row={r}
            first={i === 0}
            canManage={canManageReviewers}
            reviewerMgmt={reviewerMgmt}
            onJumpToComment={onJumpToComment}
          />
        ))}
        <AddReviewerChip
          first={reviewerStates.length === 0}
          prHtmlUrl={pr?.html_url}
          owner={owner}
          repo={repo}
          canManage={canManageReviewers}
          excludeLogins={reviewerStates.map((r) => r.login)}
          onPick={(login) => void reviewerMgmt.requestReviewer(login)}
        />
      </span>

      {/* checks (failing signal) */}
      {hasChecks && (
        <span className="shrink-0">
          <ChecksHoverCard
            checks={checksQuery.data?.checks ?? []}
            fail={checkCounts.fail}
            pass={checkCounts.pass}
            pending={checkCounts.pending}
            historical={checksHistorical}
            onJumpToMergeBox={onJumpToMergeBox}
            compact
          />
        </span>
      )}

      {/* diff stats — additions stacked over deletions */}
      {pr && (
        <span className="flex shrink-0 flex-col items-end font-mono text-[10px] leading-[1.15]">
          <span className={checksHistorical ? 'text-muted-foreground' : 'text-emerald-600'}>
            +{pr.additions.toLocaleString()}
          </span>
          <span className={checksHistorical ? 'text-muted-foreground' : 'text-destructive'}>
            −{pr.deletions.toLocaleString()}
          </span>
        </span>
      )}

      {/* Files-tab diff controls — same components as the full toolbar:
          the collapse dropdown + the inline/split switcher. */}
      {diffTools && (
        <span className="flex shrink-0 items-center gap-2">
          <CompactViewedProgress
            viewed={diffTools.viewed}
            total={diffTools.totalFiles}
          />
          <CollapseControls
            onCollapseAll={diffTools.onCollapseAll}
            onExpandAll={diffTools.onExpandAll}
            onResetCollapse={diffTools.onResetCollapse}
            onCollapseWithoutComments={diffTools.onCollapseWithoutComments}
            filesWithoutCommentsCount={diffTools.filesWithoutCommentsCount}
          />
          <CompactDiffModeToggle
            value={diffTools.diffMode}
            onChange={diffTools.onDiffModeChange}
          />
        </span>
      )}

      {/* "Review with AI" — rides the compact bar so the trigger survives the
          header collapse (ADR 0026). */}
      {aiReviewTrigger && <span className="shrink-0">{aiReviewTrigger}</span>}

      {/* focus toggle (icon-only) */}
      {onToggleFocusMode && (
        <span className="shrink-0">
          <FocusToggle
            mode={active === 'description' ? 'comments' : 'code'}
            active={focusMode}
            onToggle={onToggleFocusMode}
            commentFocusIsNew={commentFocusIsNew}
            onSelectCommentFocus={onSelectCommentFocus ?? (() => {})}
            commentCounts={commentCounts}
            compact
          />
        </span>
      )}

      {/* timing — last synced only, exact date on hover */}
      {pr && (
        <span
          className="inline-flex shrink-0 cursor-default items-center gap-1 text-[11px] text-muted-foreground/80"
          title={`Last synced · ${fullDate(pr.updated_at)}`}
        >
          <CloudSyncIcon className="size-3.5" />
          {relTime(pr.updated_at)}
        </span>
      )}

      {/* open on GitHub — sits at the very end of the bar */}
      {pr?.html_url && (
        <Button asChild variant="outline" size="icon" className="size-7 shrink-0" title="Open on GitHub">
          <a
            href={markGithubPassthrough(pr.html_url)}
            target="_blank"
            rel="noopener noreferrer"
            aria-label="Open on GitHub"
          >
            <GithubMark className="size-3.5" />
          </a>
        </Button>
      )}
    </div>
  );
}
