// Command palette — ⌘K / Ctrl+K opens a shadcn CommandDialog wrapping
// cmdk's Command. Commands are registered via a zustand store (no React
// Context) so screens can contribute context-specific actions ("Submit
// review" only matters on a PR detail) without the palette needing to
// know about every screen. A single <CommandPaletteHost/> mounted at the
// app root renders the dialog + binds the ⌘K shortcut (like ConfirmHost).
//
// Migrated from a hand-rolled palette to cmdk per Tier-3 of the ADR
// 0011 audit. cmdk owns: substring/fuzzy filtering, keyboard nav
// (Arrow/Enter/Esc), active-item state, mouse-hover sync, scroll-
// into-view. We own: the registration registry, the ⌘K open
// shortcut, and the rAF deferral on the action callback (keeps the
// Dialog close animation from racing whatever the action mounts).

import { useEffect } from 'react';
import { create } from 'zustand';
import {
  CommandDialog,
  CommandEmpty,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from '@/components/ui/command';

/** A single contribution to the palette. Renamed from the previous
 * `Command` interface to avoid colliding with cmdk's `Command`
 * component now that we import it. */
export interface PaletteCommand {
  /** Stable id used as the React key + de-dup key in the registry. */
  id: string;
  /** What the user sees in the list. */
  label: string;
  /** Optional secondary text (e.g. "Pulls · Reviewing tab"). */
  hint?: string;
  /** Optional keyboard hint shown right-aligned (e.g. "G I"). */
  shortcut?: string;
  /** Click handler. Runs after the dialog closes. */
  action: () => void;
  /** Space-separated keywords cmdk feeds into its fuzzy matcher in
   * addition to the label. Optional. */
  keywords?: string;
}

interface PaletteStore {
  open: boolean;
  /** Registered commands keyed by id. In store state (not a ref) so the
   * host re-renders when registrations change. */
  commands: Record<string, PaletteCommand>;
  setOpen: (open: boolean) => void;
  /** Register a command. Returns an unregister function — call in a
   * useEffect cleanup so commands tied to a transient screen disappear
   * when that screen unmounts. */
  register: (c: PaletteCommand) => () => void;
  /** Close the palette, then run the command one frame later so the
   * Dialog close animation doesn't fight whatever the action mounts. */
  run: (c: PaletteCommand) => void;
}

const useCommandPaletteStore = create<PaletteStore>((set, get) => ({
  open: false,
  commands: {},
  setOpen: (open) => set({ open }),
  register: (c) => {
    set((s) => ({ commands: { ...s.commands, [c.id]: c } }));
    return () => {
      set((s) => {
        const { [c.id]: _removed, ...rest } = s.commands;
        return { commands: rest };
      });
    };
  },
  run: (cmd) => {
    set({ open: false });
    // Defer the action one frame so the Dialog close animation
    // doesn't fight with whatever the command does (a navigation,
    // an overlay open, etc).
    requestAnimationFrame(() => cmd.action());
  },
}));

/** Register a command for the lifetime of the mounting component. */
export function useRegisterCommand(
  c: PaletteCommand,
  deps: unknown[] = [],
): void {
  useEffect(() => {
    return useCommandPaletteStore.getState().register(c);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

/** Mounts the palette dialog + binds ⌘K. Render once at the app root. */
export function CommandPaletteHost() {
  const open = useCommandPaletteStore((s) => s.open);
  const commandsMap = useCommandPaletteStore((s) => s.commands);
  const setOpen = useCommandPaletteStore((s) => s.setOpen);
  const run = useCommandPaletteStore((s) => s.run);

  // ⌘K / Ctrl+K opens the palette. Esc closes (shadcn Dialog handles).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        useCommandPaletteStore.getState().setOpen(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const commands = Object.values(commandsMap);

  return (
    <CommandDialog open={open} onOpenChange={setOpen}>
      <CommandInput placeholder="Type a command…" />
      <CommandList>
        <CommandEmpty>No matches.</CommandEmpty>
        {commands.map((c) => (
          <CommandItem
            key={c.id}
            // `value` is what cmdk's matcher reads. Including the
            // hint lets users find "Pulls · Reviewing tab" by
            // typing "reviewing".
            value={`${c.label} ${c.hint ?? ''} ${c.keywords ?? ''}`}
            onSelect={() => run(c)}
          >
            <span className="flex-1 truncate">{c.label}</span>
            {c.hint && (
              <span className="text-[11.5px] text-muted-foreground">
                {c.hint}
              </span>
            )}
            {c.shortcut && <CommandShortcut>{c.shortcut}</CommandShortcut>}
          </CommandItem>
        ))}
      </CommandList>
    </CommandDialog>
  );
}
