// ReviewId — top-level identity for anything Pyor reviews.
//
// CONTEXT.md (v1 implication): "the local cache schema must model
// 'review' as a top-level entity with an optional pull_request_id,
// so v2 isn't a painful refactor."
//
// Two concrete kinds:
//   - pr     — a github.com pull request (the only kind in v1)
//   - local  — a Pre-PR Review (v2; head/base on a local repo)
//
// Storage keys are formed via `reviewKey(id)` so viewed-state, draft
// state, collapse state, and any future per-review caches share the
// same namespace without colliding across kinds.
//
// Migration: callers fall back to the legacy `pyor:<store>:owner/repo/number`
// shape on first read so existing users don't lose state on upgrade.
// Helpers in this file produce both the new key and the legacy key for
// the migration path.

export type ReviewId =
  | { kind: 'pr'; owner: string; repo: string; number: number }
  | { kind: 'local'; repoPath: string; head: string };

/** New-format storage suffix. Examples:
 *   pr:acme/web/9241
 *   local:/Users/x/code/foo/feat-branch
 */
function reviewKey(id: ReviewId): string {
  if (id.kind === 'pr') return `pr:${id.owner}/${id.repo}/${id.number}`;
  // Use a path the user couldn't accidentally collide with another
  // review on the same machine. The path is already absolute.
  return `local:${id.repoPath}#${id.head}`;
}

/** Convenience constructor for the v1-only PR case. */
export function prReviewId(
  owner: string,
  repo: string,
  number: number,
): ReviewId {
  return { kind: 'pr', owner, repo, number };
}

/** Legacy v1 storage key — used only by the migration path inside
 * each store. PR-only (no Pre-PR reviews ever wrote in the old shape). */
export function legacyPrKey(
  store: 'viewed' | 'draft' | 'collapse',
  owner: string,
  repo: string,
  number: number,
): string {
  return `pyor:${store}:${owner}/${repo}/${number}`;
}

/** New storage key including the `pyor:<store>:` prefix. */
export function storageKey(
  store: 'viewed' | 'draft' | 'collapse' | 'arrangement',
  id: ReviewId,
): string {
  return `pyor:${store}:${reviewKey(id)}`;
}
