// Identity sync (ADR 0021). Renders nothing; mounted once in App, inside the
// providers. Reads the shared ['viewer'] query + the entitlement and pushes
// them into PostHog (person + org groups) and Sentry (user) whenever they
// resolve or change. The opt-out and SDK init are handled elsewhere — this is
// purely the identity bridge.

import { useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getViewer } from '../github/client';
import { getCredential, hasToken } from '../auth/tokenStore';
import { useEntitlement } from '../billing/entitlement';
import { identifyUser, track, Events } from './index';

export function ObservabilityProvider() {
  const authed = hasToken();
  const viewer = useQuery({
    queryKey: ['viewer'],
    queryFn: () => getViewer(),
    enabled: authed,
    staleTime: 5 * 60_000,
  });
  const entitlement = useEntitlement();

  // One identify per (user, plan) change. useEffect is the correct tool here:
  // identify is a side effect fired by async data arriving, not render state.
  const viewerId = viewer.data?.id;
  const plan = entitlement?.plan ?? null;
  useEffect(() => {
    if (!viewer.data) return;
    identifyUser(viewer.data, getCredential(), entitlement);
    if (entitlement)
      track(Events.EntitlementResolved, {
        plan: entitlement.plan,
        seated_org_count: entitlement.seats.length,
        seats_full_count: entitlement.seatsFull.length,
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps -- key on stable ids
  }, [viewerId, plan, entitlement?.seats.length]);

  // App-opened, once per mount.
  useEffect(() => {
    track(Events.AppOpened);
  }, []);

  return null;
}
