// Sidebar update widget (ADR 0023). Mirrors the rate-limit RadialGauge: a tiny
// 18px ring in the icon rail, but hover opens a HoverCard with a bigger bar +
// details. Tracks the background update lifecycle (download → install → ready)
// and offers "Restart now" when an update is staged. Desktop-only; renders
// nothing on web (no bridge) or when no update is in flight.

import { ArrowDownToLine, Check, Loader2 } from 'lucide-react';
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from '@/components/ui/hover-card';
import { Button } from '@/components/ui/button';
import { bridge } from './electronBridge';
import { useUpdateState } from './useUpdateState';

// 18px progress ring (matches RadialGauge). pct 0–1; `accent` colours it green.
function Ring({ pct, accent }: { pct: number; accent?: boolean }) {
  const radius = 7;
  const circ = 2 * Math.PI * radius;
  return (
    <svg className="size-[18px] -rotate-90" viewBox="0 0 18 18" fill="none">
      <circle cx="9" cy="9" r={radius} strokeWidth={2} className="stroke-muted" />
      <circle
        cx="9"
        cy="9"
        r={radius}
        strokeWidth={2}
        strokeDasharray={`${circ} ${circ}`}
        strokeDashoffset={circ * (1 - pct)}
        strokeLinecap="round"
        className={`transition-[stroke-dashoffset] duration-300 ${accent ? 'stroke-primary' : 'stroke-foreground/70'}`}
      />
    </svg>
  );
}

export function UpdateGauge() {
  const state = useUpdateState();
  if (state.kind === 'idle') return null;

  const ready = state.kind === 'ready';
  const percent = state.kind === 'download' ? state.percent : 100;
  const title =
    state.kind === 'download'
      ? 'Downloading update'
      : state.kind === 'install'
        ? 'Installing update'
        : 'Update ready';

  const restart = () => {
    const b = bridge();
    if (!b || state.kind !== 'ready') return;
    void (state.via === 'staged' ? b.applyUpdate() : b.quitAndInstall());
  };

  return (
    <HoverCard openDelay={120} closeDelay={80}>
      <HoverCardTrigger asChild>
        <button
          type="button"
          className="relative flex size-8 items-center justify-center"
          aria-label={title}
        >
          <Ring pct={state.kind === 'download' ? percent / 100 : 1} accent={ready} />
          <span className="absolute flex items-center justify-center">
            {state.kind === 'download' && (
              <ArrowDownToLine className="size-2.5 text-muted-foreground" />
            )}
            {state.kind === 'install' && (
              <Loader2 className="size-2.5 animate-spin text-muted-foreground" />
            )}
            {ready && <Check className="size-2.5 text-primary" />}
          </span>
        </button>
      </HoverCardTrigger>
      <HoverCardContent side="right" sideOffset={8} className="w-64">
        <div className="flex items-center gap-2">
          {ready ? (
            <Check className="size-4 text-primary" />
          ) : (
            <ArrowDownToLine className="size-4 text-muted-foreground" />
          )}
          <span className="text-sm font-medium text-foreground">{title}</span>
          {state.kind === 'download' && (
            <span className="ml-auto text-xs tabular-nums text-muted-foreground">
              {percent}%
            </span>
          )}
        </div>

        <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-muted">
          {state.kind === 'install' ? (
            <div className="h-full w-full animate-pulse rounded-full bg-primary" />
          ) : (
            <div
              className="h-full rounded-full bg-primary transition-[width] duration-300"
              style={{ width: `${percent}%` }}
            />
          )}
        </div>

        <p className="mt-2.5 text-[12px] leading-relaxed text-muted-foreground">
          {state.kind === 'download' &&
            'A new version of Pyor is downloading in the background.'}
          {state.kind === 'install' && 'Preparing the new version…'}
          {ready &&
            (state.kind === 'ready' && state.version
              ? `Pyor v${state.version} is ready — it’ll apply when you quit, or restart now.`
              : 'The update is ready — it’ll apply when you quit, or restart now.')}
        </p>

        {ready && (
          <Button size="sm" className="mt-3 w-full" onClick={restart}>
            Restart now
          </Button>
        )}
      </HoverCardContent>
    </HoverCard>
  );
}
