// Read-only outcome card for a terminal (merged / closed) PR. The
// action-oriented MergeBox only renders while a PR is open + unmerged —
// once it's merged or closed there's nothing to act on, which previously
// left the foot of the Conversation tab blank and the status menu's
// "Jump to merge box" landing on nothing. This card gives a record of
// the result — including the checks that ran at merge time — and reuses
// the same `pr-merge-box` anchor id (only one of the two boxes ever
// renders for a given PR), so the jump still works.

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { GitMergeIcon, XCircleIcon } from 'lucide-react';
import { Collapse, CollapseChevron } from '@/components/ui/collapse';
import type { GHPullRequest } from '../../github/types';
import { countRollup } from '../../github/client';
import { prCheckRollupOptions } from '../../github/prQueries';
import { relTime, fullDate } from '../../util/relTime';
import { MergeCheckRow } from './MergeBox';

export function MergeOutcomeBox({
  pr,
  owner,
  repo,
  number,
}: {
  pr: GHPullRequest;
  owner?: string;
  repo?: string;
  number?: number;
}) {
  const merged = !!pr.merged_at;
  const head = pr.head.ref;
  const base = pr.base.ref;

  // Same shared rollup query the header + Checks tab use (deduped, no
  // extra round trip). Shown as a historical record of what CI looked
  // like on the merged/closed head commit — no gating, no alarm tone.
  const rollupQuery = useQuery({
    ...prCheckRollupOptions(owner!, repo!, number!, pr.head.sha),
    enabled: !!(owner && repo && number),
  });
  const checks = rollupQuery.data?.checks ?? [];
  const counts = countRollup(checks);
  const checkSummary =
    counts.fail > 0
      ? `${counts.fail} failing${counts.pass ? ` · ${counts.pass} passed` : ''}${counts.pending ? ` · ${counts.pending} pending` : ''}`
      : counts.pending > 0
        ? `${counts.pending} pending${counts.pass ? ` · ${counts.pass} passed` : ''}`
        : `All ${counts.pass} check${counts.pass === 1 ? '' : 's'} passed`;
  const [checksOpen, setChecksOpen] = useState(false);

  const Branch = ({ name }: { name: string }) => (
    <code className="rounded bg-muted px-1 py-0.5 font-mono text-[11px] text-foreground">
      {name}
    </code>
  );

  return (
    <div
      id="pr-merge-box"
      className="mt-4 scroll-mt-4 overflow-hidden rounded-lg border bg-card"
    >
      {/* Outcome header */}
      <div
        className={`flex items-center gap-3 px-4 py-3 ${
          merged ? 'bg-violet-500/10' : 'bg-muted/40'
        }`}
      >
        <span
          className={`inline-flex size-9 shrink-0 items-center justify-center rounded-full ${
            merged
              ? 'bg-violet-500/20 text-violet-600 dark:text-violet-400'
              : 'bg-muted text-muted-foreground'
          }`}
        >
          {merged ? (
            <GitMergeIcon className="size-[18px]" />
          ) : (
            <XCircleIcon className="size-[18px]" />
          )}
        </span>
        <div className="min-w-0 flex-1">
          <div className="text-[14px] font-semibold tracking-tight text-foreground">
            {merged ? 'Merged' : 'Closed without merging'}
          </div>
          <div className="mt-0.5 text-[12px] text-muted-foreground">
            {merged ? (
              <>
                <Branch name={head} /> was merged into <Branch name={base} />
                {pr.merged_at ? (
                  <span title={fullDate(pr.merged_at)}> {relTime(pr.merged_at)}</span>
                ) : (
                  ''
                )}
                .
              </>
            ) : (
              <>
                This pull request was closed. <Branch name={head} /> was not
                merged into <Branch name={base} />.
              </>
            )}
          </div>
        </div>
      </div>

      {/* Historical checks — the CI state on the head commit at the time
          it was merged/closed. Collapsed by default (it's a record, not
          an action); summary line carries the at-a-glance result. */}
      {checks.length > 0 && (
        <div className="border-t px-4 py-2.5">
          <button
            type="button"
            onClick={() => setChecksOpen((o) => !o)}
            className="flex w-full items-center gap-2.5 text-left"
            aria-expanded={checksOpen}
          >
            <span className="text-[12.5px] font-medium text-foreground">
              Checks at merge
            </span>
            <span className="ml-auto truncate text-[11.5px] text-muted-foreground">
              {checkSummary}
            </span>
            <CollapseChevron
              open={checksOpen}
              className="size-3.5 text-muted-foreground"
            />
          </button>
          <Collapse
            open={checksOpen}
            className="mt-2 overflow-hidden rounded-md border"
          >
            {checks.map((c, i) => (
              <MergeCheckRow
                key={`${c.kind}:${c.name}`}
                check={c}
                border={i > 0}
              />
            ))}
          </Collapse>
        </div>
      )}
    </div>
  );
}
