// The scrolling bucketed list (+ its loading / error / empty states)
// for the Team review radar. Virtualised with GroupedVirtuoso so the
// 1000-PR worst case stays smooth, and the bucket headers stick to the
// top of the viewport as you scroll through each section.

import { forwardRef, useMemo, type HTMLAttributes } from 'react';
import { GroupedVirtuoso } from 'react-virtuoso';
import { Loader2Icon, UsersIcon } from 'lucide-react';
import { EmptyState } from '../../ui/EmptyState';
import { Button } from '@/components/ui/button';
import { RefreshButton } from '@/components/ui/refresh-button';
import { FetchingBar } from '@/components/ui/fetching-bar';
import { bucketTeamPRs, type TeamOrg, type TeamPR } from '../../github/teamLens';
import { TeamBucketHeader, TeamRadarRow } from './TeamRadarRow';
import { prLinkProps } from '../../router/nav';
import { cn } from '@/lib/utils';

// Virtuoso's default Group wrapper renders `position: sticky` but leaves
// `top` unset and pins an inline `z-index: 1` — so headers never pin and
// row content (e.g. reviewer avatars carrying their own z-index) paints
// over them. Force `top-0` via class and override the inline z-index so
// the sticky header always sits above the rows scrolling under it.
const StickyGroup = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(
  ({ className, style, ...props }, ref) => (
    <div
      ref={ref}
      {...props}
      style={{ ...style, zIndex: 30 }}
      className={cn('sticky top-0', className)}
    />
  ),
);
StickyGroup.displayName = 'StickyGroup';

export function RadarBody({
  loading,
  error,
  noOrgs,
  buckets,
  orgByKey,
  you,
  pendingNum,
  onOpen,
  onAddMe,
  onClear,
  onRetry,
  hasNextPage,
  loadingMore,
  loadedCount,
  onLoadMore,
  refreshing,
}: {
  loading: boolean;
  error: string | null;
  noOrgs: boolean;
  buckets: ReturnType<typeof bucketTeamPRs>;
  orgByKey: Map<string, TeamOrg>;
  you: string;
  pendingNum: number | undefined;
  onOpen: (pr: TeamPR) => void;
  onAddMe: (pr: TeamPR) => void;
  onClear: () => void;
  onRetry: () => void;
  hasNextPage: boolean;
  loadingMore: boolean;
  loadedCount: number;
  onLoadMore: () => void;
  /** A filter/refetch is in flight while the prior list stays visible. */
  refreshing: boolean;
}) {
  // Opt out of React Compiler memoization for this virtualizer wrapper —
  // react-virtuoso drives its own render cycle off scroll/resize, and the
  // compiler's auto-memo can interfere with the per-render itemContent /
  // groupContent closures. Same escape hatch UnderlineTabs uses for motion.
  'use no memo';
  // Flatten for the virtualizer: one ordered list of PRs + per-bucket
  // counts. Memoised on a stable signature so the arrays keep their
  // identity across the radar's frequent re-renders (query polling, etc.)
  // — GroupedVirtuoso resets its measured size whenever groupCounts
  // changes by reference, which otherwise pins it to a single screenful.
  const sig = buckets
    .map((b) => `${b.bucket.id}:${b.prs.map((p) => p.num).join(',')}`)
    .join('|');
  const { groupCounts, flatPRs } = useMemo(
    () => ({
      groupCounts: buckets.map((b) => b.prs.length),
      flatPRs: buckets.flatMap((b) => b.prs),
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [sig],
  );

  if (loading) {
    return (
      <div className="flex flex-1 items-center justify-center bg-card p-10 text-[13px] text-muted-foreground">
        Loading teammate PRs…
      </div>
    );
  }
  if (error) {
    return (
      <EmptyState
        icon={UsersIcon}
        title="Couldn't load teammate PRs"
        body={error}
        action={
          <RefreshButton variant="default" onRefresh={onRetry} label="Retry" />
        }
      />
    );
  }
  if (noOrgs) {
    return (
      <EmptyState
        icon={UsersIcon}
        title="You're not a member of any organizations."
        body="The Team radar shows open PRs from teammates across your GitHub orgs. Join an org (or check your token's org access) and refresh."
      />
    );
  }
  if (buckets.length === 0) {
    return (
      <EmptyState
        icon={UsersIcon}
        title="No teammate PRs match these filters."
        body="Try widening the org scope or clearing the selected authors."
        action={
          <Button variant="outline" size="sm" onClick={onClear}>
            Clear all filters
          </Button>
        }
      />
    );
  }
  return (
    <>
      {/* Filter/refetch in flight — the prior list stays put, so a thin
          pulsing bar signals it's updating. */}
      <FetchingBar active={refreshing} />
      <GroupedVirtuoso
        className={cn(
          'min-h-0 flex-1 bg-card transition-opacity',
          refreshing && 'opacity-60',
        )}
        groupCounts={groupCounts}
      // Two guards, both required inside a flex container:
      //  • initialItemCount seeds the first paint — without it the grouped
      //    list renders zero rows, reads its height as 0 before layout
      //    settles, and stays stuck empty.
      //  • defaultItemHeight reserves space for not-yet-measured rows so
      //    the scrollbar spans the whole list. Without it only the first
      //    screenful gets height and you can't scroll far enough to bring
      //    (and measure) the rest — capping the list at one bucket.
      initialItemCount={Math.min(flatPRs.length, 12)}
      defaultItemHeight={64}
      overscan={600}
      endReached={() => {
        if (hasNextPage && !loadingMore) onLoadMore();
      }}
      components={{
        Group: StickyGroup,
        Footer: () => (
          <RadarFooter
            hasNextPage={hasNextPage}
            loadingMore={loadingMore}
            loadedCount={loadedCount}
          />
        ),
      }}
      groupContent={(index) => (
        <TeamBucketHeader
          bucket={buckets[index].bucket}
          count={buckets[index].prs.length}
        />
      )}
      itemContent={(index, groupIndex) => {
        const pr = flatPRs[index];
        if (!pr) return null;
        return (
          <TeamRadarRow
            pr={pr}
            bucket={buckets[groupIndex].bucket}
            org={orgByKey.get(pr.org)}
            you={you}
            busy={pendingNum === pr.num}
            linkProps={prLinkProps({
              owner: pr.owner,
              repo: pr.repoName,
              number: pr.num,
              from: 'pulls',
            })}
            onOpen={() => onOpen(pr)}
            onAddMe={() => onAddMe(pr)}
          />
        );
      }}
      />
    </>
  );
}

// Infinite-scroll footer: spinner while a page loads, a quiet end-cap
// once every teammate PR is in.
function RadarFooter({
  hasNextPage,
  loadingMore,
  loadedCount,
}: {
  hasNextPage: boolean;
  loadingMore: boolean;
  loadedCount: number;
}) {
  if (loadingMore) {
    return (
      <div className="flex items-center justify-center gap-2 bg-card py-3 text-[12px] text-muted-foreground">
        <Loader2Icon className="size-3.5 animate-spin" /> Loading more…
      </div>
    );
  }
  if (hasNextPage) return <div className="h-2 bg-card" />;
  return (
    <div className="bg-card py-3 text-center text-[11.5px] text-muted-foreground/70">
      All {loadedCount} teammate PRs loaded
    </div>
  );
}
