// The persistent connectivity strip under the title bar (surface #3 of
// the connectivity/outage design). Renders nothing while healthy; shows
// the amber "offline" / "reconnecting" strip when the browser loses the
// network. GitHub-outage (red) strips are surfaced per-query at the
// failure pane; this strip only knows the browser's online state.
//
// Read-only scope: we never promise to queue or auto-post offline work.
// (This replaces the old banner, which falsely claimed writes would be
// "queued and posted when GitHub is reachable again.")

import { useRef } from 'react';
import { useConnectivity } from './connectivity/useConnectivity';
import { ConnBar } from './connectivity/ConnBar';
import type { ConnBarVariant } from './connectivity/connModes';
import { Collapse } from '@/components/ui/collapse';

export function OfflineBanner() {
  const { status, retry } = useConnectivity();
  // Retain the last non-healthy variant so ConnBar keeps rendering its
  // tone/label while the strip animates closed (the bar would otherwise
  // disappear instantly and Collapse would slide an empty box out).
  const lastVariant = useRef<ConnBarVariant>('offline');
  if (status !== 'healthy') lastVariant.current = status;
  return (
    <Collapse open={status !== 'healthy'}>
      <ConnBar variant={lastVariant.current} onAction={retry} />
    </Collapse>
  );
}
