// Run AI review hints: build the diff + full-file context (capped), call the
// provider with the house reviewer prompt + the user's guidelines layered on
// top (hints only), validate with valibot, and clamp to the per-PR cap so a
// noisy model can't flood the diff (ADR 0026).

import * as v from 'valibot';
import type { GHPullRequestFile } from '@/github/types';
import type { FileContents } from '@/github/fetchPRFileContents';
import type { ProviderAdapter, TokenUsage } from '../provider';
import { buildContext, HINTS_LIMITS } from '../engine/context';
import { HINTS_SYSTEM, guidelinesLayer } from '../engine/basePrompt';
import { AI_HINTS_JSON_SCHEMA, AiHintsResultSchema, type AiHintData } from './schema';

const MAX_HINTS_PER_PR = 12;
const MAX_HINTS_PER_FILE = 3;

export interface HintsRun {
  hints: AiHintData[];
  usage: TokenUsage;
  model: string;
  capped: { analyzed: number; totalFiles: number } | null;
}

/** Enforce the output-contract caps client-side too (defense in depth). */
function clamp(hints: AiHintData[]): AiHintData[] {
  const perFile = new Map<string, number>();
  const out: AiHintData[] = [];
  // Highest severity first so the cap keeps the most important hints.
  const rank = { high: 0, warn: 1, info: 2 } as const;
  [...hints]
    .sort((a, b) => rank[a.severity] - rank[b.severity])
    .forEach((h) => {
      if (out.length >= MAX_HINTS_PER_PR) return;
      const n = perFile.get(h.path) ?? 0;
      if (n >= MAX_HINTS_PER_FILE) return;
      perFile.set(h.path, n + 1);
      out.push(h);
    });
  return out;
}

export async function runHints(
  adapter: ProviderAdapter,
  files: GHPullRequestFile[],
  contents: Map<string, FileContents> | undefined,
  guidelines: string,
  signal?: AbortSignal,
): Promise<HintsRun> {
  const ctx = buildContext(files, contents, HINTS_LIMITS);
  const instruction = `${HINTS_SYSTEM}${guidelinesLayer(guidelines)}`;

  const { data, usage, model } = await adapter.complete<unknown>({
    contextBlock: `Here is the pull request to review.\n\n${ctx.text}`,
    instruction,
    schema: AI_HINTS_JSON_SCHEMA,
    schemaName: 'ai_review_hints',
    maxTokens: 3072,
    signal,
  });

  const parsed = v.parse(AiHintsResultSchema, data);
  return { hints: clamp(parsed.hints), usage, model, capped: ctx.capped };
}
