// Shared, consolidated Filters + Sort controls for the Pull-requests
// screen — used by all three tabs (My PRs · Reviewing · Team) so the
// toolbar looks identical everywhere.
//
//   • FiltersButton — one outline pill that opens a dropdown of rows,
//     each a nested sub-menu of values. A count badge shows how many are
//     set off their default. Generic over an arbitrary field list.
//   • SortButton — one outline pill listing sort options with a leading
//     check on the active one.

import { useState } from 'react';
import {
  ArrowUpDownIcon,
  CheckIcon,
  ChevronDownIcon,
  SlidersHorizontalIcon,
  type LucideIcon,
} from 'lucide-react';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';

export interface FilterOption {
  value: string;
  label: string;
  count?: number;
}
export interface FilterField {
  key: string;
  icon: LucideIcon;
  label: string;
}

function labelFor(options: FilterOption[], value: string): string {
  return options.find((o) => o.value === value)?.label ?? 'Any';
}

export function FiltersButton({
  fields,
  values,
  options,
  defaults = {},
  onChange,
  onReset,
}: {
  fields: FilterField[];
  values: Record<string, string>;
  options: Record<string, FilterOption[]>;
  /** Per-field value that is NOT counted as active (default 'any'). */
  defaults?: Record<string, string>;
  onChange: (key: string, value: string) => void;
  onReset: () => void;
}) {
  const isActive = (key: string) => values[key] !== (defaults[key] ?? 'any');
  const count = fields.filter((f) => isActive(f.key)).length;
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          size="xs"
          className={cn(
            'gap-1.5 px-2.5 text-[12.5px]',
            count > 0 ? 'bg-accent text-foreground' : 'text-muted-foreground',
          )}
        >
          <SlidersHorizontalIcon />
          Filters
          {count > 0 && (
            <span className="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[9.5px] font-semibold tabular-nums text-primary-foreground">
              {count}
            </span>
          )}
          <ChevronDownIcon className="size-3 opacity-50" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-[240px]">
        <div className="flex items-center justify-between px-2 py-1">
          <DropdownMenuLabel className="p-0 text-[11px] uppercase tracking-wide text-muted-foreground">
            Filters
          </DropdownMenuLabel>
          {count > 0 && (
            <button
              type="button"
              onClick={onReset}
              className="text-[11px] font-medium text-muted-foreground hover:text-foreground"
            >
              Reset
            </button>
          )}
        </div>
        <DropdownMenuSeparator />
        {fields.map(({ key, icon: Icon, label }) => {
          const opts = options[key] ?? [];
          return (
            <DropdownMenuSub key={key}>
              <DropdownMenuSubTrigger className="gap-2.5">
                <Icon className="size-3.5 text-muted-foreground" />
                <span className="text-[12.5px]">{label}</span>
                <span
                  className={cn(
                    'ml-auto text-[12px]',
                    isActive(key)
                      ? 'font-medium text-foreground'
                      : 'text-muted-foreground',
                  )}
                >
                  {labelFor(opts, values[key])}
                </span>
              </DropdownMenuSubTrigger>
              <DropdownMenuSubContent className="max-h-[280px] w-[200px] overflow-auto">
                {opts.map((o) => (
                  <DropdownMenuItem
                    key={o.value}
                    onSelect={() => onChange(key, o.value)}
                    className={o.value === values[key] ? 'font-semibold' : ''}
                  >
                    <span className="flex-1 truncate">{o.label}</span>
                    {o.count !== undefined && (
                      <span className="text-[11px] tabular-nums text-muted-foreground">
                        {o.count}
                      </span>
                    )}
                    {o.value === values[key] && <CheckIcon className="size-3.5" />}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuSubContent>
            </DropdownMenuSub>
          );
        })}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

export function SortButton({
  options,
  value,
  onChange,
}: {
  options: FilterOption[];
  value: string;
  onChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="xs"
          className={cn(
            'gap-1.5 px-2.5 text-[12.5px]',
            open ? 'bg-accent text-foreground' : 'text-muted-foreground',
          )}
        >
          <ArrowUpDownIcon />
          Sort:{' '}
          <span className="font-semibold text-foreground">
            {labelFor(options, value)}
          </span>
          <ChevronDownIcon className="size-3 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-[184px] p-1.5">
        {options.map((o) => (
          <button
            key={o.value}
            type="button"
            onClick={() => {
              onChange(o.value);
              setOpen(false);
            }}
            className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-[12.5px] text-foreground hover:bg-accent"
          >
            <CheckIcon
              className={cn(
                'size-3.5',
                o.value === value ? 'text-foreground' : 'text-transparent',
              )}
            />
            {o.label}
          </button>
        ))}
      </PopoverContent>
    </Popover>
  );
}
