// Inline PR-title editor for the header (#13). Author-gated: the edit
// affordance (a hover pencil) appears only for the PR author, and the
// gate is authorship — not Viewer permission — so an author without
// repo write can still fix their own title. Body editing lives in the
// DescriptionTab; this is the title half. ⌘⏎ saves, esc cancels.

import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { CheckIcon, PencilIcon, XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { updatePullRequest } from '../../github/client';
import { invalidatePrLists } from '../../github/prQueries';
import type { GHPullRequest } from '../../github/types';

const TITLE_MAX = 256;

export function PRTitle({
  pr,
  owner,
  repo,
  canEdit,
}: {
  pr: GHPullRequest;
  owner: string;
  repo: string;
  canEdit: boolean;
}) {
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [value, setValue] = useState(pr.title);

  const save = useMutation({
    mutationFn: (title: string) =>
      updatePullRequest(owner, repo, pr.number, { title }),
    onSuccess: async () => {
      await Promise.all([
        // Detail surfaces (header, conversation) under the PR prefix…
        queryClient.invalidateQueries({
          queryKey: ['pr', owner, repo, pr.number],
        }),
        // …and the list rows (Mine/Reviewing/Team) that show the title.
        invalidatePrLists(queryClient),
      ]);
      toast.success('Title updated');
      setEditing(false);
    },
    onError: (err) =>
      toast.error(err instanceof Error ? err.message : 'Could not update title'),
  });

  if (!editing) {
    return (
      <span className="group/title inline-flex items-baseline gap-2">
        <h1 className="text-[18px] font-semibold leading-tight tracking-tight text-foreground">
          {pr.title}
        </h1>
        <span className="font-mono text-[14px] font-medium text-muted-foreground/70">
          #{pr.number}
        </span>
        {canEdit && (
          <button
            type="button"
            title="Edit title"
            aria-label="Edit title"
            onClick={() => {
              setValue(pr.title);
              setEditing(true);
            }}
            className="inline-flex size-6 items-center justify-center rounded-md text-muted-foreground opacity-0 transition-opacity hover:bg-muted hover:text-foreground group-hover/title:opacity-100"
          >
            <PencilIcon className="size-3.5" />
          </button>
        )}
      </span>
    );
  }

  const trimmed = value.trim();
  const dirty = trimmed.length > 0 && trimmed !== pr.title;
  const commit = () => {
    if (dirty && !save.isPending) save.mutate(trimmed);
  };

  return (
    <span className="inline-flex min-w-0 flex-1 items-center gap-1.5">
      <input
        autoFocus
        value={value}
        maxLength={TITLE_MAX}
        disabled={save.isPending}
        onChange={(e) => setValue(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
            e.preventDefault();
            commit();
          } else if (e.key === 'Escape') {
            e.preventDefault();
            setEditing(false);
          }
        }}
        className="min-w-0 flex-1 rounded-md border border-foreground bg-background px-2.5 py-1 text-[17px] font-semibold leading-tight tracking-tight text-foreground outline-none ring-2 ring-ring/20"
        style={{ minWidth: 320 }}
      />
      <span className="shrink-0 font-mono text-[14px] font-medium text-muted-foreground/70">
        #{pr.number}
      </span>
      <Button
        size="sm"
        disabled={!dirty || save.isPending}
        onClick={commit}
      >
        <CheckIcon className="size-3.5" />
        {save.isPending ? 'Saving…' : 'Save'}
      </Button>
      <Button
        variant="ghost"
        size="sm"
        disabled={save.isPending}
        onClick={() => setEditing(false)}
        aria-label="Cancel"
      >
        <XIcon className="size-3.5" />
      </Button>
    </span>
  );
}
