// Option lists for the secondary-filter controls. Every filter is now
// server-side, so the candidate values come from the facets query (a
// scope-filtered sample) rather than from the loaded results — there's
// no client-side filtering pass anymore.

import type { TeamFacets } from '../../github/teamLens';
import type { SecField, SecOption } from './RadarFilters';

const ANY: SecOption = { value: 'any', label: 'Any' };

/** Build the option list for every secondary-filter field from facets.
 * `status`, `ci`, and `updated` have fixed options (server qualifiers);
 * `repo`, `reviewer`, `label` come from the candidate pool. */
export function buildSecOptions(
  facets: TeamFacets,
): Record<SecField, SecOption[]> {
  const reviewers = [...new Set(facets.rows.map((r) => r.author))]
    .sort((a, b) => a.localeCompare(b))
    .map((login) => ({ value: login, label: login }));
  return {
    status: [
      { value: 'open', label: 'Open' },
      { value: 'draft', label: 'Draft' },
      { value: 'closed', label: 'Closed' },
      { value: 'merged', label: 'Merged' },
      { value: 'all', label: 'All' },
    ],
    repo: [ANY, ...facets.repos.map(([r, c]) => ({ value: r, label: r, count: c }))],
    reviewer: [ANY, ...reviewers],
    ci: [
      ANY,
      { value: 'success', label: 'Passing' },
      { value: 'failure', label: 'Failing' },
      { value: 'pending', label: 'Pending' },
    ],
    label: [ANY, ...facets.labels.map(([l, c]) => ({ value: l, label: l, count: c }))],
  };
}
