// AI grouping state machine + SHA-keyed cache (ADR 0026). The first async,
// non-deterministic grouping dimension: computed once on explicit trigger,
// cached per head SHA, kept-but-stale on a new commit (new files fall into
// an "Ungrouped · new" bucket until re-run). Produces the AiGroupingInput
// (assignments + per-group meta) that deriveArrangedView consumes, plus the
// panel status the rail renders.

import { useCallback, useMemo, useRef, useState } from 'react';
import type { GHPullRequestFile } from '@/github/types';
import type { FileContents } from '@/github/fetchPRFileContents';
import type { AiGroupingInput } from '@/pr/changes/grouping/arrange';
import { useAiSettings } from '../settings/useAiSettings';
import { adapterFor } from '../provider';
import { AiError, type AiErrorKind } from '../provider/types';
import { estimateCost, fmtCost, fmtTokens } from '../provider/models';
import { buildContext, GROUPING_LIMITS } from '../engine/context';
import { makeShaCache } from '../engine/shaCache';
import { runGrouping } from './runGrouping';
import type { AiGroupingResult } from './schema';

const cache = makeShaCache<AiGroupingResult>('grouping');

export type AiGroupingStatus =
  | 'locked'
  | 'idle'
  | 'loading'
  | 'grouped'
  | 'stale'
  | 'empty'
  | 'error';

export interface UseAiGrouping {
  status: AiGroupingStatus;
  input: AiGroupingInput;
  errorKind?: AiErrorKind;
  retryAfter?: number;
  capped: { analyzed: number; totalFiles: number } | null;
  /** Post-run actuals. */
  cost: { tokens: string; cost: string; secs: string } | null;
  /** Pre-run local estimate (always "~"). */
  estimate: { tokens: string; cost: string } | null;
  ranAt: number | null;
  run: () => void;
  cancel: () => void;
}

const EMPTY_INPUT: AiGroupingInput = { assignments: new Map(), groupMeta: new Map() };

function toInput(
  result: AiGroupingResult,
  currentFilenames: Set<string>,
  staleNewFiles: string[],
): AiGroupingInput {
  const assignments: AiGroupingInput['assignments'] = new Map();
  const groupMeta: AiGroupingInput['groupMeta'] = new Map();

  if (staleNewFiles.length > 0) {
    const gid = 'ai:__new__';
    groupMeta.set(gid, {
      name: 'Ungrouped · new',
      description: 'Added after the last run — re-run to sort.',
      kind: 'important',
    });
    staleNewFiles.forEach((f) =>
      assignments.set(f, { groupId: gid, groupLabel: 'Ungrouped · new', order: -1 }),
    );
  }

  result.groups.forEach((g, i) => {
    const gid = `ai:${i}`;
    groupMeta.set(gid, { name: g.name, description: g.description, kind: g.kind });
    const order = g.kind === 'important' ? i : 100 + i;
    g.files.forEach((f) => {
      if (currentFilenames.has(f) && !assignments.has(f)) {
        assignments.set(f, { groupId: gid, groupLabel: g.name, order });
      }
    });
  });

  return { assignments, groupMeta };
}

export function useAiGrouping(args: {
  active: boolean;
  owner: string | undefined;
  repo: string | undefined;
  number: number | undefined;
  headSha: string | undefined;
  files: GHPullRequestFile[];
  contents: Map<string, FileContents> | undefined;
}): UseAiGrouping {
  const { active, owner, repo, number, headSha, files, contents } = args;
  const { settings, ready, effectiveProvider } = useAiSettings();

  const [running, setRunning] = useState(false);
  const [errorKind, setErrorKind] = useState<AiErrorKind | undefined>();
  const [retryAfter, setRetryAfter] = useState<number | undefined>();
  const [cost, setCost] = useState<UseAiGrouping['cost']>(null);
  const [version, setVersion] = useState(0); // bump to re-read cache after a run
  const abortRef = useRef<AbortController | null>(null);

  const prId =
    owner && repo && number != null ? { owner, repo, number } : null;

  const cached = useMemo(() => {
    if (!active || !prId) return { status: 'none' as const };
    return cache.read(prId, headSha);
    // version forces a re-read after run() writes.

  }, [active, prId?.owner, prId?.repo, prId?.number, headSha, version]);

  const currentFilenames = useMemo(() => new Set(files.map((f) => f.filename)), [files]);

  const { input, status, capped, staleNew } = useMemo(() => {
    if (!active) return { input: EMPTY_INPUT, status: 'idle' as AiGroupingStatus, capped: null, staleNew: [] as string[] };
    if (running) return { input: EMPTY_INPUT, status: 'loading' as AiGroupingStatus, capped: null, staleNew: [] };
    if (errorKind) return { input: EMPTY_INPUT, status: 'error' as AiGroupingStatus, capped: null, staleNew: [] };
    if (!ready) return { input: EMPTY_INPUT, status: 'locked' as AiGroupingStatus, capped: null, staleNew: [] };

    if (cached.status === 'fresh' || cached.status === 'stale') {
      const result = cached.result;
      const grouped = new Set(result.groups.flatMap((g) => g.files));
      const staleNewFiles =
        cached.status === 'stale'
          ? files.map((f) => f.filename).filter((p) => !grouped.has(p))
          : [];
      const inp = toInput(result, currentFilenames, staleNewFiles);
      const st: AiGroupingStatus =
        cached.status === 'stale'
          ? 'stale'
          : result.groups.length === 0
            ? 'empty'
            : 'grouped';
      return { input: inp, status: st, capped: null, staleNew: staleNewFiles };
    }
    return { input: EMPTY_INPUT, status: 'idle' as AiGroupingStatus, capped: null, staleNew: [] };
  }, [active, running, errorKind, ready, cached, files, currentFilenames]);

  const estimate = useMemo(() => {
    if (!active || !effectiveProvider || (status !== 'idle' && status !== 'stale')) return null;
    const ctx = buildContext(files, contents, GROUPING_LIMITS);
    const tokens = Math.ceil(ctx.text.length / 4) + 400;
    return {
      tokens: fmtTokens(tokens),
      cost: fmtCost(estimateCost(effectiveProvider, tokens, 800)),
    };
  }, [active, effectiveProvider, status, files, contents]);

  const ranAt =
    cached.status === 'fresh' || cached.status === 'stale' ? cached.ranAt : null;

  const run = useCallback(() => {
    if (!prId || !headSha || !effectiveProvider) return;
    const adapter = adapterFor(effectiveProvider, settings);
    if (!adapter) return;
    const ctrl = new AbortController();
    abortRef.current = ctrl;
    setErrorKind(undefined);
    setRetryAfter(undefined);
    setRunning(true);
    const startedAt = Date.now();
    void runGrouping(adapter, files, contents, ctrl.signal)
      .then((res) => {
        if (ctrl.signal.aborted) return;
        cache.write(prId, headSha, res.result);
        const secs = ((Date.now() - startedAt) / 1000).toFixed(1);
        setCost({
          tokens: fmtTokens(res.usage.inputTokens + res.usage.outputTokens),
          cost: fmtCost(
            estimateCost(effectiveProvider, res.usage.inputTokens, res.usage.outputTokens),
          ),
          secs: `${secs}s`,
        });
        setVersion((v) => v + 1);
      })
      .catch((err: unknown) => {
        if (ctrl.signal.aborted) return;
        if (err instanceof AiError) {
          setErrorKind(err.kind);
          setRetryAfter(err.retryAfter);
        } else {
          setErrorKind('unknown');
        }
      })
      .finally(() => {
        if (!ctrl.signal.aborted) setRunning(false);
      });
  }, [prId, headSha, effectiveProvider, settings, files, contents]);

  const cancel = useCallback(() => {
    abortRef.current?.abort();
    setRunning(false);
  }, []);

  return { status, input, errorKind, retryAfter, capped, cost, estimate, ranAt, run, cancel };
}
