// Row primitives for the bespoke AI-grouped rail (ADR 0026 / design
// `ai-grouping.jsx`, tinted variant). A group folder is a TWO-LINE row — name
// line plus an inline one-line AI description — with its member files nested
// beneath. Restores the everyday rail affordances the @pierre/trees rail gives
// for free: per-type file icons, per-file loading spinner, a clickable viewed
// eye, a comment badge, and the diff-scroll "visible file" accent.

import {
  ChevronDownIcon,
  ChevronRightIcon,
  CircleDotIcon,
  FolderIcon,
  Loader2Icon,
  MessageCircleIcon,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { AiMark } from '@/ai/aikit';
import { FileTypeIcon } from './fileIcon';
import { ViewedEye, type EyeState } from './ViewedEye';

export type ViewedTri = 'unchecked' | 'partial' | 'checked';

// Per-file git status — same lane + letters @pierre/trees shows (A/M/D/R/C),
// tuned to the lib's hues (added green, modified amber, deleted red, rename/
// copy neutral, matching `--trees-git-*-color`). Sits last on the row, after
// the viewed eye, like pierre.
const GIT_STATUS: Record<string, { ch: string; cls: string; label: string }> = {
  added: { ch: 'A', cls: 'text-green-600 dark:text-green-500', label: 'added' },
  removed: { ch: 'D', cls: 'text-red-600 dark:text-red-500', label: 'removed' },
  renamed: { ch: 'R', cls: 'text-foreground/80', label: 'renamed' },
  copied: { ch: 'C', cls: 'text-foreground/80', label: 'copied' },
  modified: { ch: 'M', cls: 'text-amber-600 dark:text-amber-500', label: 'modified' },
  changed: { ch: 'M', cls: 'text-amber-600 dark:text-amber-500', label: 'modified' },
};

function GitStatusBadge({ status }: { status?: string }) {
  const s = (status && GIT_STATUS[status]) || GIT_STATUS.modified;
  return (
    <span title={`Git status: ${s.label}`} className={cn('w-3 shrink-0 text-center text-[10px] font-bold tabular-nums', s.cls)}>
      {s.ch}
    </span>
  );
}

const triToEye: Record<ViewedTri, EyeState> = {
  unchecked: 'open',
  partial: 'half',
  checked: 'closed',
};

// The viewed-toggle eye — same glyph the @pierre/trees rail uses, on files AND
// folders. `reveal` hides the open (not-viewed) eye until the row is hovered;
// the closed (viewed) eye stays visible so viewed rows read at a glance.
function ViewedEyeButton({
  state,
  onClick,
  title,
  reveal = false,
}: {
  state: EyeState;
  onClick?: () => void;
  title: string;
  reveal?: boolean;
}) {
  return (
    <button
      type="button"
      title={title}
      onClick={(e) => {
        e.stopPropagation();
        onClick?.();
      }}
      className={cn(
        'inline-flex size-4 shrink-0 items-center justify-center rounded text-muted-foreground transition-opacity hover:text-foreground',
        reveal && state === 'open' ? 'opacity-0 group-hover:opacity-70' : 'opacity-70',
      )}
    >
      <ViewedEye state={state} />
    </button>
  );
}

export function AiFileRow({
  path,
  add,
  del,
  status,
  viewed = false,
  loading = false,
  comments = 0,
  current = false,
  moved,
  onSelect,
  onToggleViewed,
}: {
  path: string;
  add: number;
  del: number;
  status?: string;
  viewed?: boolean;
  loading?: boolean;
  comments?: number;
  current?: boolean;
  moved?: string;
  onSelect?: () => void;
  onToggleViewed?: () => void;
}) {
  const base = path.split('/').pop() ?? path;
  return (
    <div
      role="button"
      tabIndex={0}
      data-ai-file={path}
      onClick={onSelect}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelect?.();
        }
      }}
      title={path}
      className={cn(
        'group flex h-7 w-full cursor-pointer items-center gap-1.5 pr-2.5 text-left text-[12.5px] outline-none transition-colors',
        current
          ? 'border-l-2 border-foreground bg-accent'
          : 'border-l-2 border-transparent hover:bg-accent/60',
        viewed && !current && 'opacity-55',
      )}
      style={{ paddingLeft: 26 }}
    >
      {loading ? (
        <Loader2Icon className="size-3.5 shrink-0 animate-spin text-violet-500" />
      ) : (
        <FileTypeIcon path={path} />
      )}
      <span className={cn('flex-1 truncate', current && 'font-semibold')}>{base}</span>
      {moved && <span className="shrink-0 font-mono text-[9.5px] text-muted-foreground/70">{moved}</span>}
      {comments > 0 && (
        <span className="inline-flex shrink-0 items-center gap-0.5 text-[10.5px] text-muted-foreground" title={`${comments} comment${comments === 1 ? '' : 's'}`}>
          <MessageCircleIcon className="size-3" />
          {comments}
        </span>
      )}
      <span className="shrink-0 font-mono text-[10px] tabular-nums">
        <span className="text-emerald-600 dark:text-emerald-500">+{add}</span>{' '}
        <span className="text-red-600 dark:text-red-500">−{del}</span>
      </span>
      {/* Per-file viewed toggle — same eye glyph as the older list. */}
      {onToggleViewed && (
        <ViewedEyeButton
          state={viewed ? 'closed' : 'open'}
          reveal
          onClick={onToggleViewed}
          title={viewed ? 'Mark not viewed' : 'Mark viewed'}
        />
      )}
      {/* Git status lane — last, after the eye (matches @pierre/trees). */}
      <GitStatusBadge status={status} />
    </div>
  );
}

export function AiGroupFolderRow({
  name,
  description,
  important,
  isNew = false,
  count,
  pct,
  viewedState,
  collapsed,
  onToggleCollapse,
  onToggleViewed,
}: {
  name: string;
  description: string;
  important: boolean;
  isNew?: boolean;
  count: number;
  pct?: string;
  viewedState: ViewedTri;
  collapsed: boolean;
  onToggleCollapse: () => void;
  onToggleViewed?: () => void;
}) {
  const tinted = important && !isNew;
  const Chevron = collapsed ? ChevronRightIcon : ChevronDownIcon;
  return (
    <div
      className={cn(
        'flex items-start gap-1.5 py-1.5 pr-2.5',
        isNew
          ? 'border-l-2 border-amber-400 bg-amber-50/50 dark:bg-amber-500/10'
          : tinted
            ? 'border-l-2 border-violet-400 bg-violet-50/40 dark:bg-violet-500/[0.08]'
            : 'border-l-2 border-transparent',
      )}
      style={{ paddingLeft: 8 }}
    >
      <button type="button" onClick={onToggleCollapse} aria-label={collapsed ? 'Expand group' : 'Collapse group'} className="mt-0.5 shrink-0">
        <Chevron className="size-3 text-muted-foreground" />
      </button>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          {isNew ? (
            <CircleDotIcon className="size-3.5 shrink-0 text-amber-500 dark:text-amber-400" />
          ) : (
            <FolderIcon className={cn('size-3.5 shrink-0', important ? 'text-violet-500 dark:text-violet-300' : 'text-muted-foreground/70')} />
          )}
          <span className={cn('truncate text-[12.5px] font-semibold', important || isNew ? 'text-foreground' : 'text-muted-foreground')}>
            {name}
          </span>
          <span className="shrink-0 rounded bg-muted px-1 text-[10px] font-medium tabular-nums text-muted-foreground">{count}</span>
          {pct && <span className="shrink-0 text-[10px] tabular-nums text-muted-foreground/70">{pct}</span>}
          {!important && !isNew && (
            <span className="shrink-0 text-[9.5px] font-medium uppercase tracking-wide text-muted-foreground/80">noise</span>
          )}
          <span className="ml-auto shrink-0">
            <ViewedEyeButton
              state={triToEye[viewedState]}
              onClick={onToggleViewed}
              title={viewedState === 'checked' ? 'Mark group not viewed' : 'Mark group viewed'}
            />
          </span>
        </div>
        {/* The one-line AI description — quiet, violet-tinted, with the mark so
            it reads as machine-written, not a folder name. */}
        <div className="mt-0.5 flex items-start gap-1 pr-1">
          <AiMark className={cn('mt-[2px] size-2.5 shrink-0', isNew ? 'text-amber-400' : 'text-violet-400 dark:text-violet-300/80')} />
          <span className={cn('text-[11px] leading-snug', important && !isNew ? 'text-violet-700/90 dark:text-violet-300/90' : 'text-muted-foreground')}>
            {description}
          </span>
        </div>
      </div>
    </div>
  );
}
