// Inline "install Pyor on more organizations" nudge.
//
// A GitHub-App token only sees repos from installed accounts, so PRs in
// un-installed orgs silently don't appear. This is the recurring affordance
// that widens that reach. Used by the inbox empty/partial states; the
// Settings Organizations section uses its own Button for prominence.

import { ExternalLink } from 'lucide-react';
import { APP_INSTALL_URL } from '../github/appInstall';
import { openExternalUrl } from '../desktop/openExternal';

export function InstallMoreOrgsLink({
  label = 'Missing a repo? Install Pyor on more organizations',
  className = '',
}: {
  label?: string;
  className?: string;
}) {
  return (
    <button
      type="button"
      onClick={() => openExternalUrl(APP_INSTALL_URL)}
      className={`inline-flex items-center gap-1 text-[12px] text-primary hover:underline ${className}`}
    >
      {label}
      <ExternalLink size={11} strokeWidth={2} />
    </button>
  );
}
