// AppNav context.
//
// App.tsx (the routing shell) is the source of truth for which top-level
// screen is active and how to navigate between them. Per-screen
// components read from this context to render the persistent
// AppSidebar with the right `active` highlight and shared
// collapse/handlers — without each screen having to know about the
// router or import App.tsx.
//
// Screens that opt into the new shell:
//   const nav = useAppNav();
//   <PyorWindow
//     appSidebar={nav && <AppSidebar {...nav} active="inbox" />}
//     appSidebarWidth={nav?.collapsed ? 52 : 220}
//   >
//
// A null context value means the screen isn't inside the app shell
// (Setup, error states) — so it doesn't render an AppSidebar at all.

import { createContext, useContext } from 'react';
import type { ReactNode } from 'react';
import type { AppNavKey } from './AppSidebar';

export interface AppNavCtx {
  /** Legacy imperative routing handler. The sidebar now navigates via
   * typed <Link>s (AppSidebar), so this is optional and unused by it. */
  onNavigate?: (key: AppNavKey) => void;
  /** Optional per-key counts for the sidebar's `SidebarMenuBadge`. */
  badges?: Partial<Record<AppNavKey, number>>;
}

const Ctx = createContext<AppNavCtx | null>(null);

export function AppNavProvider({
  value,
  children,
}: {
  value: AppNavCtx | null;
  children: ReactNode;
}) {
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

function useAppNav(): AppNavCtx | null {
  return useContext(Ctx);
}
