// Per-PR "last viewed" timestamp, persisted to localStorage — the basis
// for GitHub's "New changes since you last viewed" timeline marker.
//
// We store the epoch-ms instant the viewer last OPENED a PR's
// Conversation. On the next open we compare that baseline against each
// timeline item's time: anything newer is "new since you last viewed",
// and the Conversation timeline drops a divider before the first such
// commit/push.
//
// Keyed by `owner/repo/number` under one small map. Failures (private
// mode, quota) degrade to "no baseline" → no divider, never a crash.

const KEY = 'pyor:pr-last-viewed';

type ViewedMap = Record<string, number>;

function read(): ViewedMap {
  try {
    const raw = localStorage.getItem(KEY);
    return raw ? (JSON.parse(raw) as ViewedMap) : {};
  } catch {
    return {};
  }
}

function prKey(owner: string, repo: string, number: number): string {
  return `${owner}/${repo}/${number}`;
}

function getStored(owner: string, repo: string, number: number): number | null {
  const v = read()[prKey(owner, repo, number)];
  return typeof v === 'number' ? v : null;
}

function markViewed(
  owner: string,
  repo: string,
  number: number,
  ts: number,
): void {
  const map = read();
  map[prKey(owner, repo, number)] = ts;
  try {
    localStorage.setItem(KEY, JSON.stringify(map));
  } catch {
    // private mode / quota — the baseline just won't persist this session.
  }
}

// Session cache of the baseline captured on first view THIS session. The
// Conversation timeline remounts on every Conversation↔Files tab switch;
// without this cache each remount would re-read localStorage AND re-stamp
// "viewed = now", erasing the divider the moment you glance at another
// tab. Caching the first-seen baseline (and only stamping once) keeps the
// "new" marker stable for the whole session, then resets on app reload.
const sessionBaseline = new Map<string, number | null>();

/**
 * Capture (once per session per PR) the viewer's previous last-viewed
 * instant and mark the PR viewed as of now. Returns the PREVIOUS instant
 * — the baseline the timeline diffs against — or null on a PR never
 * viewed before (first visit shows no divider, matching GitHub).
 *
 * Safe to call during render: the module-level guard makes it idempotent
 * (and StrictMode-double-render safe), and it touches only localStorage.
 */
export function captureNewChangesBaseline(
  owner: string,
  repo: string,
  number: number,
  now: number,
): number | null {
  const k = prKey(owner, repo, number);
  if (!sessionBaseline.has(k)) {
    sessionBaseline.set(k, getStored(owner, repo, number));
    markViewed(owner, repo, number, now);
  }
  return sessionBaseline.get(k) ?? null;
}
