// CollapsingHeaderZone — the "smart header" behaviour.
//
// The FULL header (passed as `full`, rendered untouched) hides as you scroll
// DOWN and slides back in as you scroll UP — from anywhere on the page, not
// just at the very top (Headroom-style). A separate COMPACT header
// (`compact`) takes its place while the full header is hidden.
//
// Driven by a "hidden amount" `h ∈ [0, HF]` accumulated from scroll DELTAS:
//   scroll down → h grows (header scrolls up and away)
//   scroll up   → h shrinks (header slides back down — mid-page too)
//   clamped so h ≤ scrollTop (always fully shown at the top)
//
// From h:
//   zone height : max(HC, HF − h)        (HF→HC; the content rises as it hides)
//   full header : translateY(−h)         (scrolls up, clipped by the zone)
//   compact bar : slides −HC→0 + fades in over the last HC of hiding
//
// HF (full height) + HC (compact height) are measured so they track real
// content.

import { useEffect, useRef, type ReactNode } from 'react';
import {
  motion,
  useMotionValue,
  useMotionValueEvent,
  useTransform,
  type MotionValue,
} from 'motion/react';
import { useElementHeight } from './useElementHeight';

const clamp = (v: number, lo: number, hi: number) =>
  Math.max(lo, Math.min(hi, v));

export function CollapsingHeaderZone({
  scrollTop,
  wheelY,
  full,
  compact,
}: {
  scrollTop: MotionValue<number>;
  wheelY: MotionValue<number>;
  full: ReactNode;
  compact: ReactNode;
}) {
  const [fullRef, hf] = useElementHeight();
  const [compactRef, hcMeasured] = useElementHeight();
  const HC = hcMeasured || 36;
  const HF = hf || 0;

  // hidden amount, accumulated from WHEEL deltas (immune to the scroll-
  // container reflow feedback — see useHeaderScroll).
  const h = useMotionValue(0);
  const lastWheel = useRef(0);
  // Anchor to the current wheel total once the header height is known, so a
  // wheel during the unmeasured window isn't double-counted.
  useEffect(() => {
    if (HF) lastWheel.current = wheelY.get();
  }, [HF, wheelY]);
  useMotionValueEvent(wheelY, 'change', (w) => {
    if (!HF) return;
    const delta = w - lastWheel.current;
    lastWheel.current = w;
    // down (delta > 0) hides, up (delta < 0) reveals; clamp saturates a fast
    // flick. The at-top clamp lives in the scrollTop handler below.
    h.set(clamp(h.get() + delta, 0, HF));
  });
  // Keyboard / scrollbar scrolling has no wheel event — re-reveal at the top
  // by clamping h ≤ scrollTop (only reduces h, mid-page this never binds, so
  // it adds no feedback).
  useMotionValueEvent(scrollTop, 'change', (s) => {
    if (h.get() > s) h.set(s);
  });

  const zoneHeight = useTransform(h, (v) =>
    HF ? Math.max(HC, HF - v) : ('auto' as unknown as number),
  );
  const fullY = useTransform(h, (v) => -v);
  const slideStart = Math.max(0, HF - HC);
  const compactY = useTransform(h, (v) => {
    if (!HF) return -HC;
    const t = clamp((v - slideStart) / HC, 0, 1);
    return -HC + t * HC;
  });
  const compactOpacity = useTransform(h, (v) =>
    HF ? clamp((v - slideStart) / HC, 0, 1) : 0,
  );
  const compactPointer = useTransform(compactOpacity, (o) =>
    o > 0.6 ? 'auto' : 'none',
  );

  return (
    <motion.div
      className="relative shrink-0 overflow-hidden"
      style={{ height: zoneHeight }}
    >
      {/* full header — scrolls up on the way down, slides back on the way up */}
      <motion.div ref={fullRef} className="absolute inset-x-0 top-0" style={{ y: fullY }}>
        {full}
      </motion.div>
      {/* compact header — slides down into the vacated top, then pins */}
      <motion.div
        ref={compactRef}
        className="absolute inset-x-0 top-0 z-10"
        style={{ y: compactY, opacity: compactOpacity, pointerEvents: compactPointer }}
      >
        {compact}
      </motion.div>
    </motion.div>
  );
}
