// Refresh the GitHub-App user access token through the broker (ADR 0019).
//
// GitHub-App user-access tokens are short-lived (~8h); the credential also
// carries a long-lived (~6mo) refresh token. Nothing was calling this, so the
// access token quietly expired and the next request 401'd → "sign-in expired"
// every day. The github client now calls this proactively (near expiry) and
// reactively (on a 401) — see github/client.ts.
//
// Single-flight: a burst of queries on cold load all hit a stale token at once;
// share ONE in-flight refresh so the broker is called once, not N times.

import { broker } from './oauthBroker';
import { getCredential, setCredential, needsRefresh } from './tokenStore';

let inflight: Promise<boolean> | null = null;

/** Mint a fresh access token from the refresh token and store it. Returns true
 * when a new token is saved; false when there's nothing to refresh (PAT /
 * signed out / no refresh token) or the refresh failed (revoked token, SSO
 * re-approval) — in which case the caller lets the 401 surface as usual. */
export function refreshCredential(): Promise<boolean> {
  if (inflight) return inflight;
  inflight = (async () => {
    const cred = getCredential();
    if (!cred || cred.method !== 'github-app' || !cred.refreshToken) return false;
    try {
      const tokens = await broker.refresh(cred.refreshToken);
      setCredential({
        accessToken: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        expiresAt: tokens.expiresAt,
        method: 'github-app',
      });
      return true;
    } catch {
      return false;
    } finally {
      inflight = null;
    }
  })();
  return inflight;
}

/** Refresh only if the stored token is at/near expiry (sync predicate). */
export function refreshIfNeeded(): Promise<boolean> {
  return needsRefresh() ? refreshCredential() : Promise.resolve(false);
}
