// Per-language configuration for symbol navigation.
// Query files are vendored from nvim-treesitter (see queries/ATTRIBUTION.md) and
// inlined at build time via Vite's `?raw` import. WASM grammars are served from
// /tree-sitter/ (web/public/tree-sitter).

import type { SymLang, SymbolKind } from './types';

import ecmaLocals from './queries/ecma/locals.scm?raw';
import jsLocals from './queries/javascript/locals.scm?raw';
import tsLocals from './queries/typescript/locals.scm?raw';
import tsxLocals from './queries/tsx/locals.scm?raw';
import pyLocals from './queries/python/locals.scm?raw';

export interface LangConfig {
  /** grammar wasm filename under /tree-sitter/. */
  wasm: string;
  /** concatenated locals query (parents resolved, inherits flattened). */
  localsQuery: string;
  /** node types that count as a clickable identifier. */
  identifierTypes: ReadonlySet<string>;
  /** declaration node type -> outline kind (+ optional name field/child). */
  outline: ReadonlyArray<OutlineRule>;
}

export interface OutlineRule {
  /** AST node type of the declaration. */
  node: string;
  kind: SymbolKind;
  /** field name holding the name node (defaults to "name"). */
  nameField?: string;
}

const JS_IDENTIFIERS = new Set([
  'identifier',
  'property_identifier',
  'shorthand_property_identifier',
  'shorthand_property_identifier_pattern',
  'type_identifier',
  'private_property_identifier',
]);

const PY_IDENTIFIERS = new Set(['identifier']);

const JS_OUTLINE: OutlineRule[] = [
  { node: 'function_declaration', kind: 'function' },
  { node: 'generator_function_declaration', kind: 'function' },
  { node: 'class_declaration', kind: 'class' },
  { node: 'abstract_class_declaration', kind: 'class' },
  { node: 'method_definition', kind: 'method' },
  { node: 'interface_declaration', kind: 'interface' },
  { node: 'type_alias_declaration', kind: 'type' },
  { node: 'enum_declaration', kind: 'type' },
];

const PY_OUTLINE: OutlineRule[] = [
  { node: 'function_definition', kind: 'function' },
  { node: 'class_definition', kind: 'class' },
];

// Supplement: nvim-treesitter's ecma locals only treats `const x = …` as a
// definition (`variable_declarator name: (identifier)`). It misses destructuring
// — `const [a, b] = …`, `const { a } = …`, rest, and defaults — which is how
// every React hook binds (`const [v, setV] = useState()`). Capture those too so
// go-to-def works on destructured names. (Pyor addition, not vendored.)
const DESTRUCTURING_LOCALS = `
(variable_declarator
  name: (array_pattern (identifier) @local.definition.var))
(variable_declarator
  name: (array_pattern (assignment_pattern left: (identifier) @local.definition.var)))
(variable_declarator
  name: (array_pattern (rest_pattern (identifier) @local.definition.var)))
(variable_declarator
  name: (object_pattern (shorthand_property_identifier_pattern) @local.definition.var))
(variable_declarator
  name: (object_pattern (object_assignment_pattern
    left: (shorthand_property_identifier_pattern) @local.definition.var)))
(variable_declarator
  name: (object_pattern (pair_pattern value: (identifier) @local.definition.var)))
(variable_declarator
  name: (object_pattern (rest_pattern (identifier) @local.definition.var)))
`;

// nvim-treesitter inherits: typescript->ecma, javascript->ecma, tsx->typescript.
const ECMA = `${ecmaLocals}\n${DESTRUCTURING_LOCALS}`;
const TS = `${ECMA}\n${tsLocals}`;
const JS = `${ECMA}\n${jsLocals}`;
const TSX = `${TS}\n${tsxLocals}`;

export const LANGUAGES: Record<SymLang, LangConfig> = {
  typescript: {
    wasm: 'tree-sitter-typescript.wasm',
    localsQuery: TS,
    identifierTypes: JS_IDENTIFIERS,
    outline: JS_OUTLINE,
  },
  tsx: {
    wasm: 'tree-sitter-tsx.wasm',
    localsQuery: TSX,
    identifierTypes: JS_IDENTIFIERS,
    outline: JS_OUTLINE,
  },
  javascript: {
    wasm: 'tree-sitter-javascript.wasm',
    localsQuery: JS,
    identifierTypes: JS_IDENTIFIERS,
    outline: JS_OUTLINE,
  },
  jsx: {
    wasm: 'tree-sitter-javascript.wasm',
    localsQuery: JS,
    identifierTypes: JS_IDENTIFIERS,
    outline: JS_OUTLINE,
  },
  python: {
    wasm: 'tree-sitter-python.wasm',
    localsQuery: pyLocals,
    identifierTypes: PY_IDENTIFIERS,
    outline: PY_OUTLINE,
  },
};

/** Node types whose `left` field, when it is the clicked identifier, is a write. */
export const WRITE_PARENTS = new Set([
  'assignment_expression', // js/ts:  x = ...
  'augmented_assignment_expression', // js/ts:  x += ...
  'assignment', // python: x = ...
  'augmented_assignment', // python: x += ...
]);

/** Parent node types that always make their identifier child a write. */
export const WRITE_PARENTS_ALWAYS = new Set([
  'update_expression', // js/ts:  x++ / x--
]);

const EXT_TO_LANG: Record<string, SymLang> = {
  ts: 'typescript',
  mts: 'typescript',
  cts: 'typescript',
  tsx: 'tsx',
  js: 'javascript',
  mjs: 'javascript',
  cjs: 'javascript',
  jsx: 'jsx',
  py: 'python',
  pyi: 'python',
};

/** Resolve a file path to a supported language, or null. */
export function langForPath(path: string): SymLang | null {
  const m = /\.([a-z]+)$/i.exec(path);
  if (!m) return null;
  return EXT_TO_LANG[m[1].toLowerCase()] ?? null;
}
