// TanStack-Query-backed wrapper around the localStorage-persisted
// DiffPreferences store. Every consumer (ChangesTab, PRDetailScreen,
// SettingsScreen, WorkerPoolPrewarm) reads through the same query key
// so a write from SettingsScreen instantly propagates to the open
// Changes tab without a reload.
//
// Why a query + setQueryData instead of plain useSyncExternalStore?
//   - We already have a QueryClient at the root and the existing
//     persister round-trips Maps/Sets via tagged envelopes — fitting
//     prefs into the same pipe keeps the mental model unified.
//   - Setting `staleTime: Infinity` + no `queryFn` network work makes
//     it effectively a typed signal: write, broadcast, re-render.
//
// Keep the storage layer in diffPreferences.ts as the single source
// of truth for the localStorage shape; this hook only fans changes
// out across the React tree.

import { useQuery, useQueryClient } from '@tanstack/react-query';
import {
  DEFAULT_PREFS,
  loadPrefs,
  savePrefs,
  type DiffPreferences,
} from '../pr/changes/diffPreferences';

const PREFS_QUERY_KEY = ['prefs'] as const;

export function usePrefs(): {
  prefs: DiffPreferences;
  setPrefs: (patch: Partial<DiffPreferences>) => void;
} {
  const queryClient = useQueryClient();
  const query = useQuery({
    queryKey: PREFS_QUERY_KEY,
    queryFn: () => loadPrefs(),
    staleTime: Infinity,
    gcTime: Infinity,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
  });
  const setPrefs = (patch: Partial<DiffPreferences>) => {
    savePrefs(patch);
    // Re-read from storage so we benefit from the merge logic in
    // savePrefs (which already does loadPrefs+spread).
    queryClient.setQueryData<DiffPreferences>(PREFS_QUERY_KEY, loadPrefs());
  };
  // Spread DEFAULT_PREFS underneath so a stale persisted snapshot
  // (e.g. from a release before a new pref existed) gets that pref's
  // default backfilled instead of arriving as `undefined`. Cheap; the
  // object identity changes on real updates anyway.
  const prefs: DiffPreferences = { ...DEFAULT_PREFS, ...(query.data ?? {}) };
  return { prefs, setPrefs };
}
