// All of the Team radar's filter/scope state + the handlers that write
// it back to the URL. Every filter is a search param (server-side), so
// this hook is the single place that maps the URL ⇄ the `TeamFilters`
// the data layer consumes. Kept out of the screen to keep it lean.

import { useNavigate, useSearch } from '@tanstack/react-router';
import { cleanSearch, type PullsSearch, type RadarSortKey } from '../../router/search';
import {
  scopeFilters,
  type TeamCI,
  type TeamFilters,
  type TeamOrg,
} from '../../github/teamLens';
import { presetToSinceISO, type DateRangePreset } from '../../ui/DateRangeChip';
import type { SecField, SecValues } from './RadarFilters';
import type { PullsTabId } from '../PullsTabsBar';

export function useRadarFilters(orgs: TeamOrg[]) {
  const navigate = useNavigate();
  const search = useSearch({ from: '/pulls' });
  const patch = (next: Partial<PullsSearch>) =>
    void navigate({
      to: '/pulls',
      search: cleanSearch({ ...search, ...next }),
      replace: true,
    });

  const authors = new Set((search.authors ?? '').split(',').filter(Boolean));
  const sortKey: RadarSortKey = search.tsort ?? 'unblock';
  const searchQuery = search.q ?? '';
  // Default org = your FIRST org (not "all"); an unset URL resolves to it.
  const defaultOrg = orgs[0]?.key ?? 'all';
  const org = search.org ?? defaultOrg;
  const since = presetToSinceISO(search.date as DateRangePreset);

  // Full server-side filter set; the scope subset (org + status + date)
  // drives the facets that populate the controls.
  const filters: TeamFilters = {
    org,
    authors: [...authors],
    status: search.status,
    since,
    repo: search.repo ?? null,
    reviewer: search.reviewer ?? null,
    ci: (search.ci as TeamCI | undefined) ?? null,
    label: search.label ?? null,
    q: searchQuery || null,
  };
  const scope = scopeFilters(org, search.status, since);
  const secValues: SecValues = {
    status: search.status,
    repo: search.repo ?? 'any',
    reviewer: search.reviewer ?? 'any',
    ci: search.ci ?? 'any',
    label: search.label ?? 'any',
  };
  const anyScope = authors.size > 0 || org !== defaultOrg;

  const toggleAuthor = (a: string) => {
    const next = new Set(authors);
    next.has(a) ? next.delete(a) : next.add(a);
    patch({ authors: [...next].join(',') || undefined });
  };
  // Each secondary filter is a URL param; 'any' clears it. (Date is the
  // tab-bar chip, not a popover filter.)
  const setSecField = (field: SecField, value: string) => {
    const off = value === 'any' ? undefined : value;
    if (field === 'status') patch({ status: value as PullsSearch['status'] });
    else if (field === 'repo') patch({ repo: off });
    else if (field === 'reviewer') patch({ reviewer: off });
    else if (field === 'ci') patch({ ci: off as PullsSearch['ci'] });
    else if (field === 'label') patch({ label: off });
  };
  const resetSec = () =>
    patch({
      status: 'open',
      repo: undefined,
      reviewer: undefined,
      ci: undefined,
      label: undefined,
    });

  return {
    org,
    defaultOrg,
    authors,
    sortKey,
    searchQuery,
    filters,
    scope,
    secValues,
    anyScope,
    dateRange: search.date,
    setDate: (d: DateRangePreset) => patch({ date: d }),
    setSearch: (v: string) => patch({ q: v || undefined }),
    onOrgChange: (k: string) =>
      patch({ org: k === defaultOrg ? undefined : k, authors: undefined }),
    toggleAuthor,
    clearAuthors: () => patch({ authors: undefined }),
    // Clear scope → default (first) org, authors cleared.
    clearScope: () => patch({ org: undefined, authors: undefined }),
    // Widen to every org + drop all filters (empty-state escape hatch).
    showEverything: () =>
      patch({
        org: 'all',
        authors: undefined,
        q: undefined,
        status: 'open',
        date: '30d',
        repo: undefined,
        reviewer: undefined,
        ci: undefined,
        label: undefined,
      }),
    onPickSort: (slug: string) =>
      patch({ tsort: slug === 'unblock' ? undefined : (slug as RadarSortKey) }),
    setSecField,
    resetSec,
    selectTab: (id: PullsTabId) =>
      patch(
        id === 'team'
          ? { tab: 'team' }
          : {
              tab: id,
              org: undefined,
              authors: undefined,
              tsort: undefined,
              q: undefined,
            },
      ),
  };
}
