// The single per-org accessibility gate (ADR 0020 #4).
//
// A blocked org is HIDDEN everywhere: lenses, notifications, the comments
// dashboard, repo pickers. "Blocked" = an installed GitHub *Organization* in
// which the viewer holds no live seat (unpaid, seats-full, or not-claimed).
// Everything else stays visible — the viewer's personal account, an unknown
// owner (a public repo you're a reviewer on), and any seated org.
//
// List rows only carry an owner LOGIN (string); the entitlement carries seated
// org IDs (numeric). The installations list bridges the two (login ↔ id ↔ type),
// so the gate matches on id and exposes a login predicate the list sources use.
//
// Fail-open: until both the entitlement and the installations list have loaded,
// the blocked set is empty and everything is accessible — a transient gap never
// hides a paying member's PRs.

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { fetchUserInstallations, toAppInstallations } from '../github/client';
import { getCredential } from '../auth/tokenStore';
import { useEntitlement } from './entitlement';

export interface OrgGate {
  /** True unless `ownerLogin` is a known installed org without a live seat. */
  isOrgAccessible: (ownerLogin: string) => boolean;
  /** Lower-cased logins of installed orgs the viewer can't access. */
  blockedOrgLogins: Set<string>;
  /** GitHub org ids the viewer holds a seat in. */
  seatedOrgIds: Set<number>;
}

export function useOrgGate(): OrgGate {
  const method = getCredential()?.method ?? 'github-app';
  const ent = useEntitlement();
  const installs = useQuery({
    queryKey: ['installations'],
    queryFn: fetchUserInstallations,
    select: toAppInstallations,
    placeholderData: (prev) => prev,
    staleTime: 60_000,
    // PAT identities can't enumerate installations (and are personal-only under
    // ADR 0020) — there's nothing to gate, so don't fire the query.
    enabled: method === 'github-app',
  });

  return useMemo(() => {
    const seatedOrgIds = new Set((ent?.seats ?? []).map((s) => s.githubOrgId));
    // Fail-open until the entitlement is actually KNOWN. A null entitlement
    // means "not resolved yet" (cold start) or "resolve failed with no cache"
    // (fail-open-to-cache, ADR 0020 #9) — we must NOT hide orgs on an unknown,
    // or a paying member's PRs vanish during every cold load. A RESOLVED free
    // user has a truthy entitlement with seats:[], so their installed orgs are
    // still correctly blocked.
    const blockedOrgLogins = ent
      ? new Set(
          (installs.data ?? [])
            .filter(
              (a) =>
                a.account.type === 'Organization' &&
                !seatedOrgIds.has(a.account.id),
            )
            .map((a) => a.account.login.toLowerCase()),
        )
      : new Set<string>();
    return {
      seatedOrgIds,
      blockedOrgLogins,
      isOrgAccessible: (ownerLogin: string) =>
        !blockedOrgLogins.has(ownerLogin.toLowerCase()),
    };
  }, [ent, installs.data]);
}
