// Live mm:ss countdown to a target Date. Drives the rate-limit primary
// action ("Retry available in 11:42") off GitHub's real reset timestamp.
// Re-renders once a second while a target is in the future.

import { useEffect, useState } from 'react';

export interface Countdown {
  /** mm:ss (or h:mm:ss past an hour). Empty when no/elapsed target. */
  text: string;
  /** True once the target is reached (or there is no target). */
  done: boolean;
  /** Whole seconds remaining (0 when done). */
  secondsLeft: number;
}

function fmt(totalSeconds: number): string {
  const s = totalSeconds % 60;
  const m = Math.floor(totalSeconds / 60) % 60;
  const h = Math.floor(totalSeconds / 3600);
  const pad = (n: number) => String(n).padStart(2, '0');
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
}

export function useCountdown(target?: Date | null): Countdown {
  const [now, setNow] = useState(() => Date.now());
  const targetMs = target ? target.getTime() : null;

  useEffect(() => {
    if (targetMs == null) return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [targetMs]);

  if (targetMs == null) return { text: '', done: true, secondsLeft: 0 };
  const secondsLeft = Math.max(0, Math.round((targetMs - now) / 1000));
  return { text: secondsLeft > 0 ? fmt(secondsLeft) : '', done: secondsLeft <= 0, secondsLeft };
}
