// Keeps the diff code viewer's Shiki theme in lockstep with the app's
// light/dark mode: dark → github-dark-high-contrast, light →
// github-light-high-contrast.
//
// Rules:
//   • Fresh install (no saved theme) → adopt the mode-matched GitHub
//     High Contrast theme so the very first diff render matches the app
//     chrome.
//   • A saved mode-following variant (either GitHub High Contrast) is
//     flipped on a reload in the opposite mode to the matching variant
//     instead of rendering a dark theme on a light app.
//   • A saved off-default theme (the user picked Dracula, etc. in
//     Settings) is respected on load — but a deliberate light/dark
//     toggle still switches to the matching High Contrast theme, per
//     product intent ("when dark is switched to light, switch the diff
//     to the matching light theme").
//
// Mounted once near the app root (Shell), inside ThemeProvider +
// the prefs QueryClient. Renders nothing.

import { useEffect, useRef } from 'react';
import { useTheme } from './ThemeProvider';
import { usePrefs } from '../util/usePrefs';
import { peekSavedTheme } from '../pr/changes/diffPreferences';

const MODE_DARK = 'github-dark-high-contrast';
const MODE_LIGHT = 'github-light-high-contrast';

export function useDiffThemeSync(): void {
  const { dark } = useTheme();
  const { prefs, setPrefs } = usePrefs();
  // Track the previous mode so we only react to actual toggles, not
  // every render. `null` marks the not-yet-initialised first pass.
  const prevDark = useRef<boolean | null>(null);
  // Mirror the current theme in a ref so the toggle branch reads the
  // latest value without adding it to the effect deps (which would
  // re-run the effect — and risk a loop — on every theme write).
  const themeRef = useRef(prefs.theme);
  themeRef.current = prefs.theme;

  useEffect(() => {
    const want = dark ? MODE_DARK : MODE_LIGHT;

    if (prevDark.current === null) {
      // First pass after mount.
      prevDark.current = dark;
      const saved = peekSavedTheme();
      const followsMode =
        saved === null || saved === MODE_DARK || saved === MODE_LIGHT;
      if (followsMode && themeRef.current !== want) {
        setPrefs({ theme: want });
      }
      return;
    }

    if (prevDark.current !== dark) {
      prevDark.current = dark;
      if (themeRef.current !== want) setPrefs({ theme: want });
    }
  }, [dark, setPrefs]);
}
