/** A comment author's role *relative to this PR* — distinct from
 * GitHub's org-level `author_association` (OWNER / MEMBER / …). It drives
 * the header role pill in GhComment:
 *
 *   • the PR author always gets "Author";
 *   • anyone else commenting on a review surface (a review summary or an
 *     inline review thread — both inherently authored by a reviewer) gets
 *     "Reviewer".
 *
 * Returns null when neither applies (e.g. a bystander's issue comment), so
 * the caller can fall back to the org-association pill. */
export type PrRole = 'author' | 'reviewer';

export function prRoleFor(
  commentAuthor: string | undefined,
  prAuthorLogin: string | undefined,
  /** True for surfaces that are reviews by definition — review-summary
   * cards and inline review threads. Lets a non-author commenter there be
   * labelled "Reviewer". Plain issue comments pass false. */
  isReviewSurface = false,
): PrRole | null {
  if (!commentAuthor) return null;
  if (prAuthorLogin && commentAuthor === prAuthorLogin) return 'author';
  return isReviewSurface ? 'reviewer' : null;
}
