// React-Query-backed per-file viewed state.
//
// The `viewed-files` query (GraphQL `viewerViewedState`) IS the source of
// truth. GitHub is authoritative and the query cache is persisted to
// IndexedDB (Set-aware serializer, see main.tsx), so there's no separate
// localStorage store and no useState mirror — consumers read the query
// data directly and re-render when it changes.
//
// Mutation pipeline (optimistic, per-path serialised, rollback on
// failure):
//
//   1. `setQueryData` flips the cached Set immediately — the user sees
//      the checkbox change before any network roundtrip.
//   2. A per-path worker drains the latest "target" into GitHub via the
//      mark / unmark endpoints. Rapid toggles collapse: if the user
//      clicks the same file three times, only the final state is sent.
//      (Intermediate states would arrive out-of-order in the worst case
//      and leave the server diverged; collapsing avoids that.)
//   3. If the API call rejects AND the cache still reflects our
//      optimistic value AND no newer toggle is queued, we revert that
//      path. The user sees the change undo itself, matching the server.
//
// Why refetch-on-focus: marking a file viewed on github.com bumps
// neither the PR's `updated_at` nor its head SHA, so the metadata poll
// can't detect it — a window-focus refetch is the only signal that picks
// up a viewed toggle made in another tab.

import { useCallback, useMemo, useRef } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  BulkAbortError,
  BulkViewedError,
  getViewedFiles,
  markFileAsViewed,
  markFilesAsViewed,
  unmarkFileAsViewed,
} from '../github/client';
import { showViewedProgress } from '../components/ViewedProgressToast';

// Stable empty fallback so `viewed`'s identity doesn't churn while the
// query is disabled / still pending. Never mutated — every write builds
// a fresh Set.
const EMPTY: Set<string> = new Set();

function withPath(prev: Set<string>, path: string, viewed: boolean): Set<string> {
  const next = new Set(prev);
  if (viewed) next.add(path);
  else next.delete(path);
  return next;
}

function withPaths(
  prev: Set<string>,
  paths: string[],
  viewed: boolean,
): Set<string> {
  const next = new Set(prev);
  paths.forEach((p) => (viewed ? next.add(p) : next.delete(p)));
  return next;
}

function sameSet(a: Set<string>, b: Set<string>): boolean {
  return a.size === b.size && [...a].every((p) => b.has(p));
}

// Classify a thrown error so the toast can be specific. GitHub's
// secondary rate-limit responses come back as plain Errors with a
// "secondary rate limit" string in the message; we treat them as
// retryable. Anything else is logged but not retried automatically.
function isSecondaryRateLimit(e: unknown): boolean {
  const msg = String((e as { message?: string } | null)?.message ?? '');
  return /secondary rate limit/i.test(msg);
}

function describeError(e: unknown): string {
  const msg = String((e as { message?: string } | null)?.message ?? '');
  if (isSecondaryRateLimit(e)) {
    return 'GitHub rate-limited the burst. Try again in a few seconds.';
  }
  return msg || 'Unknown error';
}

function basename(path: string): string {
  const slash = path.lastIndexOf('/');
  return slash >= 0 ? path.slice(slash + 1) : path;
}

export interface ViewedHookValue {
  viewed: Set<string>;
  isViewed(path: string): boolean;
  toggle(path: string): void;
  setViewed(path: string, viewed: boolean): void;
  setMany(paths: string[], viewed: boolean): void;
}

interface SyncOpts {
  /** Enable GitHub sync. When false the query stays disabled (no
   * network) — local-only behaviour for tests + the spike. */
  sync?: boolean;
  /** Current PR head SHA. Part of the query key so a force-push
   * (head.sha changes) re-fetches the viewed state from GitHub — which
   * is the source of truth and clears viewed marks automatically when
   * the head moves. */
  headSha?: string;
}

export function useViewedState(
  owner: string,
  repo: string,
  number: number,
  opts: SyncOpts = {},
): ViewedHookValue {
  const queryClient = useQueryClient();
  const queryKey = useMemo(
    () => ['viewed-files', owner, repo, number, opts.headSha] as const,
    [owner, repo, number, opts.headSha],
  );

  const serverViewedQuery = useQuery({
    queryKey,
    queryFn: () => getViewedFiles(owner, repo, number),
    enabled: Boolean(opts.sync && owner && repo && number),
    // A viewed toggle on github.com doesn't bump updated_at/head SHA, so
    // the metadata poll can't see it — refetch on every window focus to
    // pick up changes made in another tab.
    refetchOnWindowFocus: 'always',
    staleTime: 5_000,
    // Keep the prior server snapshot while a headSha-keyed refetch is in
    // flight (force-push) so the viewed marks don't blank to undefined
    // and flash the diff back to "nothing viewed" mid-fetch.
    placeholderData: (prev) => prev,
    // Sets aren't covered by RQ's default deep-equal structural sharing,
    // so a no-op 'always' focus refetch would hand back a new reference
    // and re-render every consumer. Return the prior Set when the
    // contents match so unchanged focuses are free.
    structuralSharing: (oldData, newData) => {
      const o = oldData as Set<string> | undefined;
      const n = newData as Set<string>;
      return o && sameSet(o, n) ? o : n;
    },
  });

  const viewed = serverViewedQuery.data ?? EMPTY;

  // Optimistic cache write — flips the cached Set immediately. All
  // mutations funnel through here so reads/rollbacks share one path.
  const setOptimistic = useCallback(
    (mutate: (prev: Set<string>) => Set<string>) => {
      queryClient.setQueryData<Set<string>>(queryKey, (prev) =>
        mutate(prev ?? EMPTY),
      );
    },
    [queryClient, queryKey],
  );

  // Per-path mutation queue. Each entry holds the latest desired state
  // for that path; the worker drains them serially. New toggles arriving
  // while a request is in flight simply update `target` — the worker
  // re-reads it after each completion and sends only the final state.
  //
  // The ref identity is stable across renders, which keeps the callback
  // identities below equal.
  const pendingByPath = useRef<
    Map<string, { target: boolean; running: boolean }>
  >(new Map());

  // The in-flight bulk run (setMany), if any. A newer bulk op that touches
  // any of the same paths ABORTS this one first — otherwise mark-all then
  // unmark-all would run concurrently and interleave opposite mutations on
  // the same files (the two-toast race).
  const bulkRun = useRef<{
    controller: AbortController;
    paths: Set<string>;
  } | null>(null);

  const drainPath = useCallback(
    async (path: string) => {
      const entry = pendingByPath.current.get(path);
      if (!entry || entry.running) return;
      entry.running = true;
      try {
        // Loop until no newer target has been queued. One API call per
        // iteration; rapid toggles get absorbed into a single call when
        // the queue moves on faster than the network.
        // eslint-disable-next-line no-constant-condition
        while (true) {
          const target = entry.target;
          try {
            await (target
              ? markFileAsViewed(owner, repo, number, path)
              : unmarkFileAsViewed(owner, repo, number, path));
            // Latest still matches what we just sent → done.
            const latest = pendingByPath.current.get(path);
            if (!latest || latest.target === target) {
              pendingByPath.current.delete(path);
              return;
            }
            // A newer toggle arrived during the request — loop and send.
          } catch (e) {
            // eslint-disable-next-line no-console
            console.warn(
              `viewed mutation failed (${target ? 'mark' : 'unmark'} ${path}):`,
              e,
            );
            // Roll back only when the cache still holds the value we
            // attempted AND no newer toggle is queued — otherwise we'd
            // clobber an intent we haven't sent yet, or fight a fresh
            // refetch that already corrected the path.
            const latest = pendingByPath.current.get(path);
            const cur = queryClient.getQueryData<Set<string>>(queryKey);
            const stillOptimistic = (cur?.has(path) ?? false) === target;
            if (latest && latest.target === target && stillOptimistic) {
              setOptimistic((prev) => withPath(prev, path, !target));
            }
            pendingByPath.current.delete(path);
            // Surface the failure so the user knows the eye-icon bounced
            // back on its own. Retry offered for transient errors only.
            toast.error(
              `Couldn’t ${target ? 'mark' : 'unmark'} ${basename(path)} as viewed`,
              {
                description: describeError(e),
                action: isSecondaryRateLimit(e)
                  ? {
                      label: 'Retry',
                      onClick: () => {
                        pendingByPath.current.set(path, {
                          target,
                          running: false,
                        });
                        void drainPath(path);
                      },
                    }
                  : undefined,
              },
            );
            return;
          }
        }
      } finally {
        // entry.running stays true until delete; if we got here via throw
        // it was already cleared above. Defensive against unexpected exit.
        const live = pendingByPath.current.get(path);
        if (live) live.running = false;
      }
    },
    [owner, repo, number, queryClient, queryKey, setOptimistic],
  );

  // Enqueue the desired target for `path` and kick the worker. The
  // optimistic cache write has already happened at the call site; this
  // owns only the network side.
  const pushMutation = useCallback(
    (path: string, v: boolean) => {
      if (!opts.sync || !owner || !repo || !number) return;
      const existing = pendingByPath.current.get(path);
      if (existing) existing.target = v;
      else pendingByPath.current.set(path, { target: v, running: false });
      // A running worker will re-read the updated target itself.
      if (existing?.running) return;
      void drainPath(path);
    },
    [opts.sync, owner, repo, number, drainPath],
  );

  const isViewed = useCallback((path: string) => viewed.has(path), [viewed]);

  const toggle = useCallback(
    (path: string) => {
      // Read the freshest cached value (not the render-time `viewed`) so
      // rapid clicks within one tick compute the right next state.
      const cur = queryClient.getQueryData<Set<string>>(queryKey);
      const next = !(cur?.has(path) ?? false);
      setOptimistic((prev) => withPath(prev, path, next));
      pushMutation(path, next);
    },
    [queryClient, queryKey, setOptimistic, pushMutation],
  );

  const setViewed = useCallback(
    (path: string, v: boolean) => {
      setOptimistic((prev) => withPath(prev, path, v));
      pushMutation(path, v);
    },
    [setOptimistic, pushMutation],
  );

  const setMany = useCallback(
    (paths: string[], v: boolean) => {
      // Optimistically flip every path in the cache.
      setOptimistic((prev) => withPaths(prev, paths, v));
      if (!opts.sync || !owner || !repo || !number || paths.length === 0) {
        return;
      }
      // Supersede any in-flight run that touches the same files, so
      // mark-all then unmark-all don't run concurrently and interleave
      // opposite mutations on the same paths. The aborted run unwinds
      // silently; this run's optimistic flip is now the live state.
      const active = bulkRun.current;
      if (active && paths.some((p) => active.paths.has(p))) {
        active.controller.abort();
      }
      const controller = new AbortController();
      bulkRun.current = { controller, paths: new Set(paths) };

      // The progress toast (lazy reveal + throttle countdown + done/error
      // transitions) is owned by showViewedProgress; we just map the
      // mutation callbacks to its methods.
      const progress = showViewedProgress(v ? 'Mark' : 'Unmark', paths.length);

      void (async () => {
        try {
          await markFilesAsViewed(owner, repo, number, paths, v, {
            signal: controller.signal,
            onProgress: progress.progress,
            onThrottle: progress.throttle,
          });
          progress.succeed();
        } catch (e) {
          // Superseded by a newer overlapping run: that run owns the
          // optimistic state, so no rollback and no error — just dismiss.
          if (e instanceof BulkAbortError) {
            progress.dismiss();
            return;
          }
          // markFilesAsViewed reports the unconfirmed remainder on a
          // BulkViewedError; anything else (e.g. node-id lookup) means
          // nothing landed, so the whole set is unconfirmed.
          const remaining =
            e instanceof BulkViewedError ? [...e.remaining] : paths;
          const confirmed = paths.length - remaining.length;
          // eslint-disable-next-line no-console
          console.warn(
            `bulk viewed mutation failed (${v ? 'mark' : 'unmark'}, ${remaining.length}/${paths.length} unconfirmed):`,
            e,
          );
          // Roll back ONLY the unconfirmed paths that still hold our
          // optimistic value — the confirmed prefix stays flipped.
          const cur = queryClient.getQueryData<Set<string>>(queryKey) ?? EMPTY;
          const toRevert = remaining.filter((p) => cur.has(p) === v);
          if (toRevert.length > 0) {
            setOptimistic((prev) => withPaths(prev, toRevert, !v));
          }
          // Retry resumes the REMAINDER only — re-sending already-confirmed
          // chunks is what re-trips the secondary limit.
          progress.fail({
            headline:
              confirmed > 0
                ? `Stopped after ${confirmed}/${paths.length} — ${remaining.length} file${remaining.length === 1 ? '' : 's'} left`
                : `Couldn’t ${v ? 'mark' : 'unmark'} ${paths.length} file${paths.length === 1 ? '' : 's'} as viewed`,
            description: describeError(e),
            onRetry: () => setMany(remaining, v),
          });
        } finally {
          // Release the active-run slot if it's still ours (a superseding
          // run will have already replaced it).
          if (bulkRun.current?.controller === controller) {
            bulkRun.current = null;
          }
        }
      })();
    },
    // setMany references itself in the retry callback — disable
    // exhaustive-deps for the self-reference; the closure captures the
    // right values via the listed deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [opts.sync, owner, repo, number, queryClient, queryKey, setOptimistic],
  );

  return { viewed, isViewed, toggle, setViewed, setMany };
}
