// Generic diff-body surface - wraps @pierre/diffs's CodeView with the
// polish that the original `LiveDiffPane` accumulated:
//
//   - Sticky headers + critically-damped smooth scroll
//   - Scroll persistence (debounced) + visible-file detection (drives
//     the file rail's highlight without re-renders)
//   - Search-hit highlighter that walks each file's shadow DOM and
//     wraps matching tokens in <mark> elements
//   - Active-hit emphasis: pulse + tag the currently-focused match
//     across virtualized files
//   - Dev perf probe (?perf=1) and a tiny debug dump for visible-file
//     calibration (?pyorperf=1)
//   - WorkerPoolContextProvider theme + lineDiffType propagation -
//     critical because @pierre/diffs's FileRenderer delegates render
//     options to the pool, ignoring the `options.theme` we pass to
//     CodeView when a pool is mounted
//   - "Skipped files" notice that suppresses transient reasons while
//     content is still streaming
//   - Per-file diff-area skeleton during the cold-open window
//
// **All of this is GitHub-agnostic.** The component is generic over an
// annotation metadata type `AMeta` so it can render local-review
// comments, GitHub threads, or anything else a caller wants to attach
// to diff lines. Domain-specific bits - what to render per annotation,
// what to do on a gutter "+" click or a line-range selection, which
// pills to put in each file header, what content to stamp into the
// "permalink copied" toast - all flow in via callback props so the
// component itself has zero knowledge of GitHub vs local vs anything
// else.
//
// Callers (LiveDiffPane for GitHub PRs, LocalReviewSurface for
// pre-PR reviews) compose items + supply adapter callbacks. Future
// surfaces (e.g. a stand-alone snippet viewer) plug in the same way.

import {
  CodeView,
  useStableCallback,
  useWorkerPool,
} from '@pierre/diffs/react';
import type {
  CodeViewDiffItem,
  CodeViewHandle,
  CodeViewItem,
  DiffLineAnnotation,
  LineAnnotation,
  SelectedLineRange,
} from '@pierre/diffs/react';
import {
  forwardRef,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import type {
  CSSProperties,
  ForwardedRef,
  MouseEvent as ReactMouseEvent,
  ReactNode,
} from 'react';
import type { BuildResult } from '../github/buildDiff';
import { PaginatingCard } from '../pr/changes/loading/PaginatingCard';
import { markGithubPassthrough } from '../util/githubPassthrough';
import { DIFF_EMPHASIS_UNSAFE_CSS } from './diffEmphasisCss';

/** The lib wraps each option callback with a trailing context arg
 * carrying `{ type, item, instance? }`. The lib doesn't export the
 * named context type, so we mirror its shape here - narrow enough
 * to keep call sites type-safe without depending on internal
 * symbols that could rename. */
export type DiffBodyItemContext<AMeta> = {
  type: 'diff' | 'file';
  item: CodeViewItem<AMeta>;
  instance?: unknown;
};

/** One dot on the search overview-ruler. `frac` is the 0..1 vertical
 * position through the whole diff; `count` is how many raw matches
 * collapsed into this dot (nearby matches are bucketed so the rail
 * stays light even on PRs with thousands of hits); `matchIndex` is the
 * representative match to jump to on click; `active` flags the dot that
 * holds the currently-focused match. */
export interface SearchRulerMarker {
  frac: number;
  matchIndex: number;
  active: boolean;
  count: number;
}

/** Raw (un-bucketed) ruler marker - one per match, before near-coincident
 *  dots are collapsed for display. */
interface RawRulerMarker {
  frac: number;
  matchIndex: number;
  active: boolean;
}

/** Bucket width (fractional units) for collapsing nearby dots. ~250
 *  buckets across the full height keeps the rail light on PRs with
 *  thousands of hits without the dots visually merging. */
const RULER_BUCKET = 0.004;

/** Collapse near-coincident raw markers into display dots. An active marker
 *  always wins its bucket's representative (so the focused hit paints +
 *  jumps correctly); otherwise the lowest global index represents it. */
function bucketRulerMarkers(
  raw: readonly RawRulerMarker[],
): SearchRulerMarker[] {
  const buckets = new Map<number, SearchRulerMarker>();
  raw.forEach((r) => {
    const key = Math.round(r.frac / RULER_BUCKET);
    const ex = buckets.get(key);
    if (!ex) {
      buckets.set(key, { ...r, count: 1 });
      return;
    }
    ex.count += 1;
    if (r.active) {
      ex.active = true;
      ex.matchIndex = r.matchIndex;
    }
    if (!ex.active && r.matchIndex < ex.matchIndex) ex.matchIndex = r.matchIndex;
  });
  return Array.from(buckets.values()).sort((a, b) => a.frac - b.frac);
}

/** Renderer layout shared by both ruler layers: total content height plus each
 *  file's real top + rendered height, all in the scroller's content space. */
interface RulerLayout {
  totalH: number;
  topById: Map<string, number>;
  heightById: Map<string, number>;
}

/** Map one layer's matches (each a per-file `rowFrac`) onto the rail using the
 *  shared layout, then bucket near-coincident dots. Shared by the search and
 *  symbol layers so they position identically. */
function markersFromMatches(
  layout: RulerLayout,
  matches: readonly { filename: string; rowFrac: number }[] | undefined,
  activeIndex: number | undefined,
): SearchRulerMarker[] {
  if (!matches || matches.length === 0) return [];
  const raw: RawRulerMarker[] = [];
  matches.forEach((m, idx) => {
    const top = layout.topById.get(m.filename);
    if (top == null) return;
    const h = layout.heightById.get(m.filename) ?? 1;
    const y = top + m.rowFrac * h;
    raw.push({
      frac: Math.min(Math.max(y / layout.totalH, 0), 1),
      matchIndex: idx,
      active: idx === activeIndex,
    });
  });
  return bucketRulerMarkers(raw);
}

/** Both overview-ruler layers' display dots. `search` = amber, `symbol` =
 *  blue (the in-diff symbol-highlight colour). */
interface RulerLayerMarkers {
  search: SearchRulerMarker[];
  symbol: SearchRulerMarker[];
}
const EMPTY_RULER: RulerLayerMarkers = { search: [], symbol: [] };
function isRulerEmpty(r: RulerLayerMarkers): boolean {
  return r.search.length === 0 && r.symbol.length === 0;
}

/** Colour treatment for one ruler layer (base dot + focused dot). */
interface RulerPalette {
  baseBg: string;
  activeBg: string;
  baseShadow: string;
  activeShadow: string;
}
// Amber/orange - mirrors the in-diff search highlight.
const SEARCH_PALETTE: RulerPalette = {
  baseBg: 'hsl(48 96% 53% / 0.7)',
  activeBg: 'hsl(28 100% 58% / 0.95)',
  baseShadow: '0 0 0 0.5px hsl(0 0% 0% / 0.25)',
  activeShadow: '0 0 0 1px hsl(28 100% 70%)',
};
// Blue - mirrors the in-diff symbol-reference highlight (--sym read tint).
const SYMBOL_PALETTE: RulerPalette = {
  baseBg: 'hsl(210 90% 60% / 0.7)',
  activeBg: 'hsl(210 90% 56% / 0.95)',
  baseShadow: '0 0 0 0.5px hsl(0 0% 0% / 0.25)',
  activeShadow: '0 0 0 1px hsl(210 90% 72%)',
};

interface DiffBodyProps<AMeta> {
  /** Build result from `buildDiffItems` - drives the skipped notice. */
  build: BuildResult;
  /** Items to render, already composed with whatever annotations /
   * composer overlays the caller wants. The component is generic
   * over the annotation metadata shape. */
  items: CodeViewDiffItem<AMeta>[];
  /** True while a wave-2 content fetch is in flight. Suppresses
   * `no-contents` / `content-fetch-failed` skip reasons that clear
   * themselves as the stream completes. */
  isContentsLoading?: boolean;
  /** True while the files list itself is still loading. When set AND
   * `items` is empty we render a skeleton so the pane isn't blank. */
  isFilesLoading?: boolean;
  /** 'unified' = inline overlay, 'split' = side-by-side. */
  diffStyle?: 'unified' | 'split';
  /** Diff-search query. When non-empty, the post-render hook walks
   * each file's shadow DOM and wraps matching tokens in
   * `<mark data-pyor-search-hit>`. */
  searchQuery?: string | null;
  /** Coordinates of the currently-focused match. Located by
   * (filename, lineNumber, side, hitInLine) - robust against
   * virtualization. */
  activeMatch?: {
    filename: string;
    lineNumber: number;
    side: 'additions' | 'deletions';
    hitInLine: number;
  } | null;
  /** Search matches for the overview-ruler (the VSCode-style dots on the
   * scrollbar). Index-aligned with the caller's match list - `rowFrac` is
   * the match's position (0..1) within its file's rendered rows. DiffBody
   * positions each dot using the renderer's REAL per-file layout offset
   * (`getTopForItem`), so the rail tracks actual rendered heights (inline
   * threads, soft-wrap, collapsed regions) rather than a patch estimate.
   * Empty/omitted ⇒ no rail. */
  searchMatches?: readonly { filename: string; rowFrac: number }[];
  /** Global index of the currently-focused match (highlights its dot). */
  activeMatchIndex?: number;
  /** Click handler for a ruler dot - receives the match's global index
   * (into the caller's match list). Caller drives the scroll-to-match. */
  onSelectMatch?: (matchIndex: number) => void;
  /** Symbol-navigation occurrences for a SECOND ruler layer (the same rail,
   * a different colour). Same shape/semantics as `searchMatches`: each is a
   * `rowFrac` (0..1) within its file; DiffBody positions them with the same
   * real-layout math. Empty/omitted ⇒ no symbol dots. */
  symbolMatches?: readonly { filename: string; rowFrac: number }[];
  /** Index of the currently-focused occurrence (the cycled / clicked one). */
  activeSymbolIndex?: number;
  /** Click handler for a symbol dot - receives the occurrence index. */
  onSelectSymbolMarker?: (index: number) => void;
  /** Shiki theme name. Passed both as the lib's `options.theme` and
   * pushed into the worker pool's renderOptions so virtualised
   * FileDiffs pick up the new theme on remount. */
  shikiTheme?: string;
  /** Per-line diff algorithm. Maps 1:1 to the lib's `lineDiffType`. */
  lineDiffStyle?: 'word-alt' | 'word' | 'char' | 'none';
  /** Diff monospace size in CSS px. Flows into the
   * `--diffs-font-size` custom property the lib reads at its host. */
  fontSize?: number;
  /** Diff row height in CSS px. Flows into `--diffs-line-height`. */
  lineHeight?: number;
  /** Fires (debounced 250ms) whenever the diff scrolls - caller
   * persists this so reload restores the exact spot. */
  onScrollChange?: (scrollTop: number) => void;
  /** Fires (cheap, per scroll frame) whenever the topmost visible
   * file changes. Receivers must do DOM mutations only - setState
   * here re-renders the whole pane on every scroll frame. */
  onVisibleFileChange?: (path: string | null) => void;
  // ============================================================
  // Adapter - domain-specific surface area
  // ============================================================
  /** Whether to enable the "+" gutter widget at all. Usually true
   * when the caller wants to capture line-range clicks for a new-
   * comment composer. */
  enableGutterUtility?: boolean;
  /** Whether to enable text-line-range selection (e.g. for permalink
   * copy). False disables the lib's drag-to-select on text rows. */
  enableLineSelection?: boolean;
  /** Gutter "+" click handler - fires with the selected line range
   * + the file context. Adapter usually opens its composer here. */
  onGutterUtilityClick?: (
    range: SelectedLineRange,
    context: DiffBodyItemContext<AMeta>,
  ) => void;
  /** Line-range selection completion. GitHub adapter copies a
   * permalink to the clipboard; local adapter is a no-op. */
  onLineSelectionEnd?: (
    range: SelectedLineRange | null,
    context: DiffBodyItemContext<AMeta>,
  ) => void;
  /** Fires when the user clicks empty diff space - anywhere in the pane
   * that is NOT a diff line, gutter, annotation, file header, or
   * interactive control. Adapter usually clears the line selection +
   * URL anchor here. Detected via the click's composed path, so a click
   * landing inside a `<diffs-container>` shadow root is still classified
   * correctly. */
  onBackgroundClick?: () => void;
  /** Render an annotation (thread, composer, local comment, etc.).
   * Required - without this no overlays render. */
  renderAnnotation: (
    annotation: LineAnnotation<AMeta> | DiffLineAnnotation<AMeta>,
    item: CodeViewItem<AMeta>,
  ) => ReactNode;
  /** Render trailing badges in the file header (counts, viewed
   * checkbox, "Comment on file" pill, etc.). Adapter-driven. */
  renderHeaderMetadata?: (
    item: CodeViewItem<AMeta>,
    context: { isLoading: boolean },
  ) => ReactNode;
  /** Render leading affordance in the file header (typically the
   * collapse chevron). Adapter-driven. */
  renderHeaderPrefix?: (item: CodeViewItem<AMeta>) => ReactNode;
  /** Per-file post-render hook. The lib fires `onPostRender(node,
   * instance)` after every render cycle of a `FileDiff` - we forward
   * the instance to the adapter so it can do imperative things the
   * pure-data CodeView API doesn't cover (e.g. `expandHunk` to surface
   * a comment anchored to a context line outside the rendered hunks). */
  onItemPostRender?: (node: HTMLElement, instance: unknown) => void;
  /** Transient bottom-centre toast (e.g. "Permalink copied"). Pure
   * presentation - adapter owns the lifecycle. */
  toast?: string | null;
  /** Filenames whose stream item is a synthesised image placeholder.
   * Their containers get tagged `data-pyor-image` so the shadow-CSS
   * rule hides the synthetic code body, leaving only the file header
   * and the `image` annotation (the before/after preview). */
  imageFilenames?: ReadonlySet<string>;
  /** Filenames whose stream item is a synthesised rename/move placeholder
   * (pure rename, move, or mode-only change - no content delta). Their
   * containers get tagged `data-pyor-rename` so the shadow-CSS rule hides
   * the synthetic 1-line body and the bogus +1/-0 counts, leaving the
   * file header (old → new path) and the file-composer annotation. */
  renamedFilenames?: ReadonlySet<string>;
  /** Filenames whose stream item is a synthesised non-image-binary
   * placeholder (.wasm, compiled blobs, …). Their containers get tagged
   * `data-pyor-binary` so the shadow-CSS rule hides the synthetic 1-line
   * body and the bogus +1/-0 counts, leaving the file header and the
   * `binary-note` annotation (the "Binary file" card). */
  binaryFilenames?: ReadonlySet<string>;
}

/** Handle type for `forwardRef` - re-exported so callers can spell
 * `LiveDiffPaneHandle` / `DiffBodyHandle<AMeta>` consistently. */
type DiffBodyHandle<AMeta> = CodeViewHandle<AMeta>;

function DiffBodyInner<AMeta>(
  props: DiffBodyProps<AMeta>,
  ref: ForwardedRef<DiffBodyHandle<AMeta>>,
) {
  const {
    build,
    items,
    isContentsLoading = false,
    isFilesLoading = false,
    diffStyle = 'unified',
    searchQuery = null,
    activeMatch = null,
    searchMatches,
    activeMatchIndex,
    onSelectMatch,
    symbolMatches,
    activeSymbolIndex,
    onSelectSymbolMarker,
    shikiTheme,
    lineDiffStyle,
    fontSize,
    lineHeight,
    onScrollChange,
    onVisibleFileChange,
    enableGutterUtility = false,
    enableLineSelection = false,
    onGutterUtilityClick,
    onLineSelectionEnd,
    onBackgroundClick,
    renderAnnotation,
    renderHeaderMetadata,
    renderHeaderPrefix,
    onItemPostRender,
    toast,
    imageFilenames,
    renamedFilenames,
    binaryFilenames,
  } = props;

  // Internal handle to the CodeView, merged with the forwarded ref, so we
  // can read the renderer's REAL layout (per-file tops) for the search
  // ruler. useCallback([ref]) keeps the callback ref stable so React
  // doesn't detach/re-attach the handle every render.
  const cvHandleRef = useRef<CodeViewHandle<AMeta> | null>(null);
  const setCvRef = useCallback(
    (h: CodeViewHandle<AMeta> | null) => {
      cvHandleRef.current = h;
      if (typeof ref === 'function') ref(h);
      else if (ref) ref.current = h;
    },
    [ref],
  );
  // CodeView's own scroll root - its scrollHeight is the ruler's denominator
  // (total content height, the same space getTopForItem reports in).
  const rulerScrollerRef = useRef<HTMLDivElement | null>(null);

  // Bucketed ruler dots for BOTH layers (search + symbol), recomputed off the
  // render path from real layout whenever a match set / focused index changes
  // or a scroll settles. Each layer is positioned with the same layout math.
  const [rulerMarkers, setRulerMarkers] = useState<RulerLayerMarkers>(EMPTY_RULER);
  // Shared per-render layout: the renderer's real per-file top + height, in the
  // scroller's content space. Both layers map their `rowFrac` through this, so
  // it's built once per recompute rather than per layer.
  const buildRulerLayout = useStableCallback((): RulerLayout | null => {
    const inst = cvHandleRef.current?.getInstance();
    const scroller = rulerScrollerRef.current;
    if (!inst || !scroller) return null;
    const totalH = scroller.scrollHeight || 1;
    // Real per-file top from the renderer's layout - estimated for files not
    // yet measured, exact once they've been rendered. The lib tracks a `top`
    // for EVERY item (not just the on-screen window), so offscreen files get
    // positioned too; the scroll-settle refresh sharpens them as you go.
    const topById = new Map<string, number>();
    items.forEach((it) => {
      const t = inst.getTopForItem(it.id);
      if (typeof t === 'number') topById.set(it.id, t);
    });
    // A file's rendered height = gap to the next file with a known top
    // (last file to bottom of content). Single reverse pass carrying the
    // last-seen top, so this stays O(n) instead of an O(n^2) next-top scan
    // per file (matters on PRs with hundreds of files, since this runs on
    // every scroll-settle).
    const heightById = new Map<string, number>();
    let nextKnownTop = totalH;
    [...items]
      .reverse()
      .forEach((it) => {
        const top = topById.get(it.id);
        if (top == null) return;
        heightById.set(it.id, Math.max(nextKnownTop - top, 1));
        nextKnownTop = top;
      });
    return { totalH, topById, heightById };
  });
  const computeRulerMarkers = useStableCallback((): RulerLayerMarkers => {
    const layout = buildRulerLayout();
    if (!layout) return EMPTY_RULER;
    return {
      search: markersFromMatches(layout, searchMatches, activeMatchIndex),
      symbol: markersFromMatches(layout, symbolMatches, activeSymbolIndex),
    };
  });
  const refreshRuler = useStableCallback(() => {
    setRulerMarkers((prev) => {
      const next = computeRulerMarkers();
      // Avoid a needless re-render when there's nothing to show either way.
      if (isRulerEmpty(prev) && isRulerEmpty(next)) return prev;
      return next;
    });
  });
  // Recompute when either match set or focused index changes. Keyed on STABLE
  // primitives (query, counts, active indices) - NOT the matches / `items`
  // array references, which are rebuilt on most renders and would otherwise
  // re-run this effect every frame, cancelling its timer before it can fire
  // (the rail would never populate). A new search/selection rebuilds the diff
  // items; the renderer needs a few frames to lay them out before
  // getTopForItem returns real tops, so we retry over ~600ms until markers
  // appear (or give up), repainting as soon as the layout is ready.
  const matchCount = searchMatches?.length ?? 0;
  const symbolCount = symbolMatches?.length ?? 0;
  useEffect(() => {
    if (matchCount === 0 && symbolCount === 0) {
      setRulerMarkers((prev) => (isRulerEmpty(prev) ? prev : EMPTY_RULER));
      return;
    }
    // setTimeout (not requestAnimationFrame): rAF is paused in background
    // tabs, which would leave the rail unpopulated until the tab is focused.
    // A short timeout still lets the just-committed diff items lay out before
    // we read getTopForItem, and keeps working when hidden.
    let timer = 0;
    let tries = 0;
    const attempt = () => {
      const next = computeRulerMarkers();
      if (!isRulerEmpty(next) || tries >= 8) {
        setRulerMarkers(next);
        return;
      }
      tries += 1;
      timer = window.setTimeout(attempt, 80);
    };
    timer = window.setTimeout(attempt, 32);
    return () => window.clearTimeout(timer);
  }, [
    searchQuery,
    matchCount,
    activeMatchIndex,
    symbolCount,
    activeSymbolIndex,
    computeRulerMarkers,
  ]);

  // Debounced scroll-persist. The lib fires onScroll on every frame
  // during a scroll burst; we coalesce to 250ms so localStorage isn't
  // hammered. Wrapped in useStableCallback so the lib's options-
  // identity check stays happy across React renders.
  const scrollPersistTimerRef = useRef<number | null>(null);
  const pendingScrollTopRef = useRef<number>(0);
  // Last visible file we reported. Kept in a ref so we can compare
  // without triggering renders, and so the scroll handler stays
  // referentially stable across paints.
  const lastVisibleFileRef = useRef<string | null>(null);
  // The detection below walks every rendered item with
  // getBoundingClientRect on each scroll event - measured at ~19k rect
  // reads per 2s of fast scrolling. The rail highlight it feeds doesn't
  // need 60 Hz; run it at most every 100ms (the persisted scrollTop is
  // captured unconditionally above the gate, so nothing is lost).
  const lastVisibleRunRef = useRef(0);
  // Scroll container resolved once and reused; the getComputedStyle
  // walk only re-runs if the cached node left the DOM (remount).
  const scrollerRef = useRef<HTMLElement | null>(null);
  const persistScroll = useStableCallback(
    (scrollTop: number, viewer: unknown) => {
      pendingScrollTopRef.current = scrollTop;

      // Visible-file detection: ask the CodeView instance which items
      // are currently rendered (virtualised window). Pick the topmost
      // one whose header has crossed the scroll-container's top edge.
      const nowTs = performance.now();
      if (onVisibleFileChange && nowTs - lastVisibleRunRef.current >= 100) {
        lastVisibleRunRef.current = nowTs;
        // viewer is the @pierre/diffs CodeView instance; its API is
        // typed inside the lib but not exported by name. Duck-type it.
        const rendered = (
          viewer as {
            getRenderedItems?: () => {
              id: string;
              element?: HTMLElement;
            }[];
          }
        ).getRenderedItems?.();
        // ?pyorperf=1 - surface a debug dump for tuning thresholds.
        if (
          typeof window !== 'undefined' &&
          new URLSearchParams(window.location.search).get('pyorperf') === '1'
        ) {
          (window as unknown as { __pierVisDbg?: object }).__pierVisDbg = {
            scrollTop,
            renderedCount: rendered?.length ?? -1,
            rendered: rendered?.slice(0, 4).map((r) => ({
              id: r.id,
              boundingTop: r.element?.getBoundingClientRect().top,
            })),
          };
        }
        if (rendered && rendered.length > 0) {
          // The "file at the top" = the deepest rendered file whose
          // header has reached or scrolled past the diff's scroll
          // viewport top. Coordinates are scroll-container-relative,
          // not viewport-relative - empirically the rect of an item
          // whose header is exactly at the scroller top measures
          // boundingTop≈195, not 0, because the scroll container's
          // own boundingTop is also ~195. Subtracting the scroller's
          // top gives us the relative position.
          let scroller: HTMLElement | null = scrollerRef.current;
          if (!scroller || !scroller.isConnected) {
            scroller = rendered[0]?.element?.parentElement ?? null;
            while (scroller) {
              const cs = getComputedStyle(scroller);
              if (cs.overflowY === 'auto' || cs.overflowY === 'scroll') break;
              scroller = scroller.parentElement;
            }
            scrollerRef.current = scroller;
          }
          const scrollerTop = scroller?.getBoundingClientRect().top ?? 0;
          // TOP_SLACK absorbs sub-pixel positioning / sticky-bar
          // padding wobble so a file just clicked + scrolled to
          // align:'start' counts as "at the top" instead of falling
          // through to the fallback branch.
          const TOP_SLACK = 10;
          let candidate: { id: string; top: number } | null = null;
          for (const r of rendered) {
            const el = r.element;
            if (!el) continue;
            const relTop = el.getBoundingClientRect().top - scrollerTop;
            if (relTop <= TOP_SLACK) {
              if (!candidate || relTop > candidate.top) {
                candidate = { id: r.id, top: relTop };
              }
            }
          }
          if (!candidate) {
            // Fallback: no file has crossed the scroller top yet
            // (initial paint, top of the diff). Pick the file whose
            // header is closest to the top from below.
            for (const r of rendered) {
              const el = r.element;
              if (!el) continue;
              const relTop = el.getBoundingClientRect().top - scrollerTop;
              if (relTop > TOP_SLACK && (!candidate || relTop < candidate.top)) {
                candidate = { id: r.id, top: relTop };
              }
            }
          }
          const id = candidate?.id ?? null;
          if (id !== lastVisibleFileRef.current) {
            lastVisibleFileRef.current = id;
            // Fire synchronously - receiver is expected to do a DOM
            // mutation, not setState. Cheap.
            onVisibleFileChange(id);
          }
        }
      }

      // Persisted scroll position (debounced 250ms so localStorage
      // isn't hammered).
      if (onScrollChange) {
        if (scrollPersistTimerRef.current != null) return;
        scrollPersistTimerRef.current = window.setTimeout(() => {
          scrollPersistTimerRef.current = null;
          onScrollChange?.(pendingScrollTopRef.current);
        }, 250);
      }
    },
  );

  // Dev perf probe - wires the lib's onPostRender (fires after each
  // FileDiff render cycle) to a ring buffer on window.__pierPerf.
  // Gated behind `?perf=1` so production users pay nothing.
  const handlePostRender = useStableCallback(() => {
    type Probe = {
      ticks: number[];
      dump: () => Record<string, number | string | undefined>;
      reset: () => void;
    };
    const w = window as typeof window & { __pierPerf?: Probe };
    if (!w.__pierPerf) {
      w.__pierPerf = {
        ticks: [],
        dump() {
          const t = w.__pierPerf!.ticks;
          if (t.length < 2) return { count: t.length, note: 'need >= 2 ticks' };
          const ivs: number[] = [];
          for (let i = 1; i < t.length; i++) ivs.push(t[i] - t[i - 1]);
          ivs.sort((a, b) => a - b);
          const at = (p: number) => ivs[Math.floor(ivs.length * p)];
          return {
            count: t.length,
            window_ms: Math.round(t[t.length - 1] - t[0]),
            p50_ms: +at(0.5).toFixed(1),
            p90_ms: +at(0.9).toFixed(1),
            p99_ms: +at(0.99).toFixed(1),
            max_ms: +ivs[ivs.length - 1].toFixed(1),
          };
        },
        reset() {
          w.__pierPerf!.ticks = [];
        },
      };
    }
    const ticks = w.__pierPerf!.ticks;
    ticks.push(performance.now());
    if (ticks.length > 2000) ticks.splice(0, ticks.length - 2000);
  });
  const perfEnabled =
    typeof window !== 'undefined' &&
    new URLSearchParams(window.location.search).get('perf') === '1';

  // Search-hit highlighter - paints matches with the CSS Custom Highlight
  // API (CSS.highlights + Range) instead of mutating the DOM.
  //
  // The previous implementation wrapped each match in a <mark> element via
  // parent.replaceChild(). But @pierre/diffs renders the diff rows with
  // React inside every <diffs-container> shadow root, so those token text
  // nodes are React-managed. Swapping one out from under React orphans its
  // fiber.stateNode; the next commit that recycles/unmounts the row then
  // calls parentNode.removeChild(<the detached text node>) and throws
  // "NotFoundError: Failed to execute 'removeChild' … not a child of this
  // node", collapsing the whole screen into the error boundary. Typing then
  // clearing the search box churns the mounted file set fast enough to hit
  // this within a few keystrokes (repro: type a char, delete it, repeat).
  //
  // Range highlights never touch the node tree, so React's DOM stays
  // pristine and virtualization recycle / unmount can't corrupt it. The
  // lib re-runs onPostRender on every render cycle, so we rebuild the
  // ranges from the live DOM each time - no stale-mark bookkeeping needed.
  const HIGHLIGHT_API_SUPPORTED =
    typeof CSS !== 'undefined' &&
    'highlights' in CSS &&
    typeof Highlight !== 'undefined' &&
    typeof Range !== 'undefined';
  const SEARCH_HL = 'pyor-search-hit';
  const SEARCH_HL_ACTIVE = 'pyor-search-active';
  const HIGHLIGHT_CSS =
    `::highlight(${SEARCH_HL}){background-color:hsl(48 96% 53% / 0.55);color:inherit;}` +
    `::highlight(${SEARCH_HL_ACTIVE}){background-color:hsl(28 100% 58% / 0.95);color:inherit;}`;

  const searchQueryRef = useRef<string | null>(searchQuery);
  searchQueryRef.current = searchQuery;

  // Lazily-created global highlight registry entries + a constructable
  // stylesheet carrying the ::highlight() paint rules. The registry names
  // are global, so one shared pair serves the pane; `active` gets a higher
  // priority so it paints over the base background on the focused hit.
  const highlightsRef = useRef<{
    base: Highlight;
    active: Highlight;
    sheet: CSSStyleSheet;
  } | null>(null);
  const getHighlights = () => {
    if (!HIGHLIGHT_API_SUPPORTED) return null;
    if (!highlightsRef.current) {
      const base = new Highlight();
      const active = new Highlight();
      active.priority = 1;
      CSS.highlights.set(SEARCH_HL, base);
      CSS.highlights.set(SEARCH_HL_ACTIVE, active);
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(HIGHLIGHT_CSS);
      highlightsRef.current = { base, active, sheet };
    }
    return highlightsRef.current;
  };
  // ::highlight() rules don't cross shadow boundaries, so the sheet must
  // be adopted into every tree scope that can hold a highlighted range:
  // the document (light DOM) + each <diffs-container> shadow root.
  const adoptHighlightSheet = (
    scope: Document | ShadowRoot,
    sheet: CSSStyleSheet,
  ) => {
    try {
      if (!scope.adoptedStyleSheets.includes(sheet)) {
        scope.adoptedStyleSheets = [...scope.adoptedStyleSheets, sheet];
      }
    } catch {
      /* adoptedStyleSheets unsupported - ignore */
    }
  };
  // Input node + every reachable open shadow root.
  const collectScopes = (node: HTMLElement): (Element | ShadowRoot)[] => {
    const scopes: (Element | ShadowRoot)[] = [node];
    const hosts = node.querySelectorAll<HTMLElement>('*');
    for (const h of hosts) if (h.shadowRoot) scopes.push(h.shadowRoot);
    if (node.shadowRoot) scopes.push(node.shadowRoot);
    return scopes;
  };
  // Gate every match to ACTUAL diff code: the @pierre/diffs renderer wraps
  // each line's code in a `[data-content]` cell (inside a `[data-line]` row,
  // inside a `[data-additions]`/`[data-deletions]` column). The file header
  // - filename (`[data-title]`), change-type badge, our "N matches" pill -
  // lives OUTSIDE `[data-content]`, so requiring it keeps the highlighter
  // off the header chrome. The line-number gutter is a sibling of
  // `[data-content]` (not inside it), so it's excluded too; we keep the
  // explicit gutter check as defense in depth.
  const inCodeContent = (n: Node): boolean => {
    let p: Node | null = n.parentNode;
    while (p instanceof HTMLElement) {
      if (p.hasAttribute('data-content')) return true;
      p = p.parentNode;
    }
    return false;
  };
  // True for a text node inside a line-number gutter - matching "12"
  // there would highlight a line number rather than code.
  const inGutter = (n: Node): boolean => {
    let p: Node | null = n.parentNode;
    while (p instanceof HTMLElement) {
      const ds = p.dataset;
      if (
        ds?.lineNumber !== undefined ||
        ds?.role === 'line-number' ||
        p.hasAttribute('data-deletions-count') ||
        p.hasAttribute('data-additions-count')
      ) {
        return true;
      }
      p = p.parentNode;
    }
    return false;
  };
  // A text node is highlightable iff it's real code (in a content cell)
  // and not a line number.
  const isHighlightableText = (n: Node): boolean =>
    inCodeContent(n) && !inGutter(n);

  const handleSearchHighlight = useStableCallback((node: HTMLElement) => {
    const hl = getHighlights();
    if (!hl) return;
    const q = (searchQueryRef.current ?? '').trim();
    // Rebuild wholesale: virtualization recycles rows, so last frame's
    // ranges may point at reused/removed nodes. Clearing + repopulating
    // from the live DOM is both simplest and always correct. (Active
    // emphasis is re-applied by the caller after this runs.)
    hl.base.clear();
    // Bail BEFORE collecting scopes: collectScopes querySelectorAll('*')s
    // the whole file subtree, and this runs on every file post-render
    // during scroll - with no search active that walk bought nothing.
    if (!q) return;
    const scopes = collectScopes(node);
    adoptHighlightSheet(document, hl.sheet);
    for (const scope of scopes) {
      if (scope instanceof ShadowRoot) adoptHighlightSheet(scope, hl.sheet);
    }
    const qLower = q.toLowerCase();
    const qLen = q.length;
    for (const scope of scopes) {
      const walker = document.createTreeWalker(scope, NodeFilter.SHOW_TEXT, {
        acceptNode: (n) => {
          const t = n.nodeValue;
          if (!t || !t.toLowerCase().includes(qLower)) {
            return NodeFilter.FILTER_REJECT;
          }
          return isHighlightableText(n)
            ? NodeFilter.FILTER_ACCEPT
            : NodeFilter.FILTER_REJECT;
        },
      });
      let cur: Node | null;
      while ((cur = walker.nextNode())) {
        const lower = (cur.nodeValue ?? '').toLowerCase();
        let i = 0;
        while (i < lower.length) {
          const hit = lower.indexOf(qLower, i);
          if (hit === -1) break;
          const range = new Range();
          range.setStart(cur, hit);
          range.setEnd(cur, hit + qLen);
          hl.base.add(range);
          i = hit + qLen;
        }
      }
    }
  });

  // Active-match emphasis - locates the focused hit by its real
  // (filename, lineNumber, side, hitInLine) coordinates rather than
  // a global "N-th range in document order" index. The lib unmounts
  // offscreen files as you scroll; index-based approaches silently
  // break once the user jumps past a few matches. The focused hit is
  // painted with the higher-priority `active` highlight (no DOM edits).
  const activeMatchRef = useRef(activeMatch);
  activeMatchRef.current = activeMatch;
  // Resolve a match coordinate to a live Range over the focused hit,
  // falling back to the line's first hit if the ordinal overshoots.
  const findActiveRange = (
    paneNode: HTMLElement,
    match: NonNullable<typeof activeMatch>,
  ): Range | null => {
    const q = (searchQueryRef.current ?? '').trim();
    if (!q) return null;
    const qLower = q.toLowerCase();
    const qLen = q.length;
    const wantColumn =
      match.side === 'additions' ? 'data-additions' : 'data-deletions';
    const containers =
      paneNode.querySelectorAll<HTMLElement>('diffs-container');
    for (const dc of containers) {
      const root = dc.shadowRoot;
      if (!root) continue;
      const title = root
        .querySelector<HTMLElement>('[data-title]')
        ?.textContent?.trim();
      if (title !== match.filename) continue;
      const candidates: HTMLElement[] = Array.from(
        root.querySelectorAll<HTMLElement>(
          `[data-line="${match.lineNumber}"]`,
        ),
      );
      for (const a of root.querySelectorAll<HTMLElement>(
        `[data-alt-line="${match.lineNumber}"]`,
      )) {
        if (!candidates.includes(a)) candidates.push(a);
      }
      for (const line of candidates) {
        let col: HTMLElement | null = line;
        let matched = false;
        while (col && col !== (root.host as unknown as HTMLElement)) {
          if (col.hasAttribute('data-additions')) {
            matched = wantColumn === 'data-additions';
            break;
          }
          if (col.hasAttribute('data-deletions')) {
            matched = wantColumn === 'data-deletions';
            break;
          }
          col = col.parentElement;
        }
        if (!matched && col != null) continue;
        // Walk the line's text nodes for the hitInLine-th occurrence.
        const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT, {
          acceptNode: (n) => {
            const t = n.nodeValue;
            if (!t || !t.toLowerCase().includes(qLower)) {
              return NodeFilter.FILTER_REJECT;
            }
            return isHighlightableText(n)
              ? NodeFilter.FILTER_ACCEPT
              : NodeFilter.FILTER_REJECT;
          },
        });
        let ordinal = 0;
        let firstRange: Range | null = null;
        let cur: Node | null;
        while ((cur = walker.nextNode())) {
          const lower = (cur.nodeValue ?? '').toLowerCase();
          let i = 0;
          while (i < lower.length) {
            const hit = lower.indexOf(qLower, i);
            if (hit === -1) break;
            const r = new Range();
            r.setStart(cur, hit);
            r.setEnd(cur, hit + qLen);
            if (ordinal === match.hitInLine) return r;
            if (!firstRange) firstRange = r;
            ordinal++;
            i = hit + qLen;
          }
        }
        if (firstRange) return firstRange;
      }
    }
    return null;
  };
  const applyActiveMark = (
    node: HTMLElement,
    match: typeof activeMatch | null,
  ) => {
    const hl = getHighlights();
    if (!hl) return;
    hl.active.clear();
    if (!match) return;
    const range = findActiveRange(node, match);
    if (range) hl.active.add(range);
  };

  // Composite onPostRender - chains perf probe (when enabled), search
  // highlighter, active-mark tagger, and the "tag loading file
  // containers" pass that drives the unsafeCSS rule which hides the
  // synthetic +1/-0 counts on placeholder rows. The active-mark pass
  // runs against the pane wrapper (not the per-file `node`) so the
  // N-th mark counts globally across all rendered files.
  const paneWrapperRef = useRef<HTMLDivElement | null>(null);
  const loadingFilenamesRef = useRef(build.loadingFilenames);
  loadingFilenamesRef.current = build.loadingFilenames;
  const EMPTY_SET: ReadonlySet<string> = useMemo(() => new Set(), []);
  const imageFilenamesRef = useRef<ReadonlySet<string>>(
    imageFilenames ?? EMPTY_SET,
  );
  imageFilenamesRef.current = imageFilenames ?? EMPTY_SET;
  const renamedFilenamesRef = useRef<ReadonlySet<string>>(
    renamedFilenames ?? EMPTY_SET,
  );
  renamedFilenamesRef.current = renamedFilenames ?? EMPTY_SET;
  const binaryFilenamesRef = useRef<ReadonlySet<string>>(
    binaryFilenames ?? EMPTY_SET,
  );
  binaryFilenamesRef.current = binaryFilenames ?? EMPTY_SET;
  // Debounced re-highlight for the scroll path. The lib is virtualized
  // and fires onPostRender once per item as rows recycle in/out, so
  // calling the (heavy TreeWalker + Range rebuild) highlighter on every
  // render starves the main thread during a scroll burst → jank/freeze
  // on big PRs with many matches. Instead coalesce: schedule a single
  // trailing-edge rebuild against the WHOLE pane ~140ms after the last
  // onPostRender, so highlights catch up once scrolling settles (and one
  // pane-wide pass beats N per-file passes that each clobber the others'
  // ranges). The query-change effect and active-match effect still apply
  // immediately, keeping typing + next/prev navigation snappy.
  const searchHighlightTimerRef = useRef<number | null>(null);
  const scheduleSearchHighlight = useStableCallback(() => {
    if (searchHighlightTimerRef.current != null) {
      window.clearTimeout(searchHighlightTimerRef.current);
    }
    searchHighlightTimerRef.current = window.setTimeout(() => {
      searchHighlightTimerRef.current = null;
      const pane = paneWrapperRef.current;
      if (pane) handleSearchHighlight(pane);
      // Re-position the ruler too: scrolling measures previously-estimated
      // files, so their real tops (and the dots over them) sharpen here.
      refreshRuler();
    }, 140);
  });
  const composedPostRender = useStableCallback(
    (node: HTMLElement, instance: unknown) => {
      if (perfEnabled) handlePostRender();
      scheduleSearchHighlight();
      if (paneWrapperRef.current) {
        applyActiveMark(paneWrapperRef.current, activeMatchRef.current);
      }
      // Reconcile container tags from the WHOLE pane, not the per-file
      // `node` the lib hands us. The lib recycles `<diffs-container>`
      // hosts across files during virtualization, and `node` is a file's
      // inner content element - `node.querySelectorAll('diffs-container')`
      // can't reach the host that owns it, so a recycled host keeps a
      // stale `data-pyor-image` (hiding a text file's body) or never gets
      // tagged (showing an image file's synthetic line). Scanning the pane
      // re-derives every visible host's tag from its current title.
      const root = paneWrapperRef.current ?? node;
      tagContainers(root, loadingFilenamesRef.current, 'data-pyor-loading');
      tagContainers(root, imageFilenamesRef.current, 'data-pyor-image');
      tagContainers(root, renamedFilenamesRef.current, 'data-pyor-rename');
      tagContainers(root, binaryFilenamesRef.current, 'data-pyor-binary');
      onItemPostRender?.(node, instance);
    },
  );

  // Empty-space click → clear the line selection. The diff rows live in
  // each file's shadow root, so a click anywhere in a file retargets to
  // the `<diffs-container>` host in the light DOM - we can't read the
  // real target off `e.target`. Instead we walk the composed path (which
  // DOES include shadow nodes) from the clicked element up to this
  // wrapper, and only fire `onBackgroundClick` when none of those nodes
  // is real diff content / an interactive overlay. That makes a click on
  // the blank pane background (below the last file, or the gaps) clear,
  // while clicks on a line, the "+" gutter, an open composer, a thread,
  // or the file header are left alone.
  const handlePaneClick = useStableCallback(
    (e: ReactMouseEvent<HTMLDivElement>) => {
      if (!onBackgroundClick) return;
      const wrapper = paneWrapperRef.current;
      if (!wrapper) return;
      const path = e.nativeEvent.composedPath();
      if (path.length === 0) {
        // composedPath() is emptied once dispatch completes - fall back to
        // the (shadow-retargeted) light-DOM target. A click inside a file
        // retargets to its `<diffs-container>` host; the bare pane
        // background has no such ancestor, so treat that as empty space.
        const target = e.target as Element | null;
        if (target && target.closest(DIFF_CONTENT_FALLBACK_SELECTOR) == null) {
          onBackgroundClick();
        }
        return;
      }
      const stop = path.indexOf(wrapper);
      const scope = stop === -1 ? path : path.slice(0, stop);
      const hitContent = scope.some(
        (n) => n instanceof Element && n.matches(DIFF_CONTENT_SELECTOR),
      );
      if (!hitContent) onBackgroundClick();
    },
  );

  // When the search query changes the lib won't re-render the diff
  // body on its own - the options memo stays stable. Imperatively
  // walk the pane and re-apply marks so the highlight updates
  // without waiting for the next scroll/recycle.
  useEffect(() => {
    // The query changed: cancel any trailing scroll-debounced rebuild so
    // it can't fire stale after this immediate (rAF) re-apply, and also
    // covers unmount cleanup.
    if (searchHighlightTimerRef.current != null) {
      window.clearTimeout(searchHighlightTimerRef.current);
      searchHighlightTimerRef.current = null;
    }
    const id = requestAnimationFrame(() => {
      if (paneWrapperRef.current) {
        handleSearchHighlight(paneWrapperRef.current);
        applyActiveMark(paneWrapperRef.current, activeMatchRef.current);
      }
    });
    return () => {
      cancelAnimationFrame(id);
      if (searchHighlightTimerRef.current != null) {
        window.clearTimeout(searchHighlightTimerRef.current);
        searchHighlightTimerRef.current = null;
      }
    };
  }, [searchQuery, handleSearchHighlight]);

  // Re-tag loading containers whenever the loading set changes - the
  // lib's onPostRender only fires on scroll / virtualization, so a
  // file that finishes loading but stays in the viewport would
  // otherwise keep `data-pyor-loading` until the next scroll. RAF so
  // the tag-pass lands after React commits the new build.
  useEffect(() => {
    const id = requestAnimationFrame(() => {
      if (paneWrapperRef.current) {
        tagLoadingContainers(paneWrapperRef.current, build.loadingFilenames);
      }
    });
    return () => cancelAnimationFrame(id);
  }, [build.loadingFilenames]);

  // Re-tag-on-change pass for the synthetic-body containers (image /
  // rename / binary). Their bodies are hidden via a `data-pyor-*` host
  // attribute; `composedPostRender` re-derives those tags on every
  // library render, but the lib's onPostRender only fires on
  // scroll/virtualization — so a file already in the viewport whose set
  // changes (e.g. an image's `isBinary` flag landing in the second
  // content wave, or a streaming rebuild) needs an explicit pass. One
  // rAF re-tags all three; `tagContainers` is idempotent, so re-running
  // a kind whose set didn't change is a cheap no-op.
  useEffect(() => {
    const id = requestAnimationFrame(() => {
      const root = paneWrapperRef.current;
      if (!root) return;
      tagContainers(root, imageFilenames ?? EMPTY_SET, 'data-pyor-image');
      tagContainers(root, renamedFilenames ?? EMPTY_SET, 'data-pyor-rename');
      tagContainers(root, binaryFilenames ?? EMPTY_SET, 'data-pyor-binary');
    });
    return () => cancelAnimationFrame(id);
  }, [imageFilenames, renamedFilenames, binaryFilenames, EMPTY_SET]);

  // Re-apply the active tag whenever the match changes. Retry on
  // animation frames because the lib's scrollTo + virtualization may
  // not have rendered the target file yet.
  useEffect(() => {
    if (!activeMatch) {
      if (paneWrapperRef.current) {
        applyActiveMark(paneWrapperRef.current, null);
      }
      return;
    }
    let cancelled = false;
    let attempts = 0;
    const tryApply = () => {
      if (cancelled || !paneWrapperRef.current) return;
      const target = findActiveRange(paneWrapperRef.current, activeMatch);
      if (target) {
        applyActiveMark(paneWrapperRef.current, activeMatch);
        return;
      }
      attempts++;
      if (attempts < 30) requestAnimationFrame(tryApply);
    };
    requestAnimationFrame(tryApply);
    return () => {
      cancelled = true;
    };
    // findActiveMark + applyActiveMark are stable.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeMatch]);

  // Memoized options.
  const codeViewOptions = useMemo(
    () => ({
      stickyHeaders: true,
      // Soft-wrap long lines instead of horizontal scrolling (built-in
      // BaseCodeOptions). The lib measures wrapped row heights itself, so
      // the virtualizer stays accurate.
      overflow: 'wrap' as const,
      layout: { paddingTop: 0, paddingBottom: 24, gap: 0 },
      enableGutterUtility,
      enableLineSelection,
      diffStyle: (diffStyle === 'split' ? 'split' : 'unified') as
        | 'split'
        | 'unified',
      // Snappier critically-damped spring for j/k file-to-file jumps.
      // Default omega = 0.015 (~440ms settle) drags on 569-file PRs;
      // 0.04 gives ~165ms - fast without becoming a hard scroll.
      smoothScrollSettings: {
        omega: 0.04,
        positionEpsilon: 0.5,
        velocityEpsilon: 0.05,
      },
      ...(shikiTheme ? { theme: shikiTheme } : {}),
      ...(lineDiffStyle ? { lineDiffType: lineDiffStyle } : {}),
      // Keep the virtualizer's per-line height estimate aligned with
      // the rendered CSS line-height. The lib uses this estimate to
      // size the scroll-space *before* a hunk is measured; if it's
      // stale (e.g. user dropped to Compact = 15px while the lib's
      // default is 20px) the render window lags during fast scroll
      // and you see un-rendered gaps. Defaulting back to the lib's
      // 20px when no override is provided keeps existing behaviour
      // identical for callers that don't wire prefs.
      itemMetrics: { lineHeight: lineHeight ?? 20 },
      ...(onGutterUtilityClick ? { onGutterUtilityClick } : {}),
      ...(onLineSelectionEnd ? { onLineSelectionEnd } : {}),
      onPostRender: composedPostRender,
      // Injected into each FileDiff's shadow root. The `:host(...)`
      // selector matches when the host `<diffs-container>` carries
      // `data-pyor-loading` - applied per-file by tagLoadingContainers
      // below. Without this rule, placeholder rows show "+1 -0" from
      // the synthesised parseDiffFromFile('', ' \n') diff.
      unsafeCSS: PYOR_LOADING_UNSAFE_CSS,
    }),
    [
      enableGutterUtility,
      enableLineSelection,
      diffStyle,
      shikiTheme,
      lineDiffStyle,
      lineHeight,
      onGutterUtilityClick,
      onLineSelectionEnd,
      composedPostRender,
    ],
  );

  // Worker-pool theme + lineDiffType propagation.
  //
  // Critical: when WorkerPoolContextProvider is mounted, FileRenderer
  // delegates to `workerManager.getFileRenderOptions()` - meaning the
  // `theme` we pass via CodeView's top-level `options` is IGNORED in
  // favour of whatever the pool was constructed with. None of the
  // lib's components call workerManager.setRenderOptions when their
  // options change, so dropdown changes never reach the worker; the
  // diff keeps highlighting against the pool's initial theme.
  //
  // Fix: push (theme, lineDiffType) into the pool whenever they
  // change. The pool diffs against current renderOptions, broadcasts
  // to every worker, clears its AST caches, and calls
  // `instance.rerender()` on each subscribed FileDiff.
  const workerPool = useWorkerPool();
  useEffect(() => {
    if (!workerPool) return;
    const patch: Partial<{
      theme: string;
      lineDiffType: 'word-alt' | 'word' | 'char' | 'none';
    }> = {};
    if (shikiTheme) patch.theme = shikiTheme;
    if (lineDiffStyle) patch.lineDiffType = lineDiffStyle;
    if (Object.keys(patch).length === 0) return;
    void workerPool.setRenderOptions(patch);
  }, [workerPool, shikiTheme, lineDiffStyle]);

  // The diff lib reads its font size and row height from
  // `--diffs-font-size` / `--diffs-line-height` on its host root.
  // Setting them on this wrapper lets the Settings prefs cascade
  // straight in without touching the lib's options API.
  const typographyVars =
    fontSize !== undefined || lineHeight !== undefined
      ? ({
          ...(fontSize !== undefined
            ? { '--diffs-font-size': `${fontSize}px` }
            : null),
          ...(lineHeight !== undefined
            ? { '--diffs-line-height': `${lineHeight}px` }
            : null),
        } as CSSProperties)
      : undefined;
  return (
    <div
      ref={paneWrapperRef}
      onClick={onBackgroundClick ? handlePaneClick : undefined}
      // `position: relative` provides positioning context for the
      // absolute-positioned Toast.
      className="relative flex min-h-0 min-w-0 flex-1 flex-col bg-card"
      style={typographyVars}
    >
      {/* While wave-2 content fetch is in flight, two skip reasons
          are expected and shouldn't surface:
            - 'no-contents': file hasn't been touched yet
            - 'content-fetch-failed': sides resolve in different
              batches, one is null between them
          Both clear themselves. Once isContentsLoading flips false,
          genuinely-failed files resurface. Other reasons ('binary',
          'parse-error') always surface - those are terminal. */}
      {(() => {
        const transientReasons = new Set([
          'no-contents',
          'content-fetch-failed',
        ]);
        const visibleSkipped = isContentsLoading
          ? build.skipped.filter((s) => !transientReasons.has(s.reason))
          : build.skipped;
        return (
          visibleSkipped.length > 0 && (
            <SkippedBanner skipped={visibleSkipped} />
          )
        );
      })()}
      {/*
        CodeView's outer div IS the library's scroll root - the lib
        binds its scroll/wheel listeners to it and uses those events
        to drive virtualization, sticky-header offset math, and
        pointer-events-disable-during-scroll.

        Earlier we wrapped CodeView in our own `overflow: auto` div
        (per the Phase 0 spike). That moved the scrollbar onto the
        wrapper, which silently bypassed every one of those
        optimizations - measured FPS dropped to ~26 (p50 33ms, p90
        71ms) over a 569-file PR. Letting CodeView own the scroll
        restores native virtualization.
      */}
      {/* Diff-area skeleton while the files list is still loading.
          Without this the pane is visually blank between the surface
          shell mount and the first file landing.
          We toggle visibility via display rather than unmounting -
          the ref + worker-pool subscriptions stay alive, so the
          takeover when items arrive is a single render not a remount. */}
      {isFilesLoading && items.length === 0 && <PaginatingCard />}
      {/* CodeView keeps its own `overflow:auto` so the lib owns the
          scroll/virtualization listeners. The search overview-ruler is an
          ABSOLUTE overlay pinned to the right edge - i.e. on top of the
          scrollbar (VSCode-style) - not a wrapper around CodeView (wrapping
          it in an overflow:auto div tanked measured FPS). The overlay is
          transparent + pointer-events:none so the scrollbar shows through
          and stays draggable; only the dots opt back into pointer events.
          It mounts only when there are markers, so the non-search render is
          byte-identical. */}
      <div
        className="relative flex min-h-0"
        style={{
          flex: isFilesLoading && items.length === 0 ? 0 : 1,
          display:
            isFilesLoading && items.length === 0 ? 'none' : undefined,
        }}
      >
        <CodeView<AMeta>
          ref={setCvRef}
          containerRef={rulerScrollerRef}
          items={items}
          className="relative min-h-0 flex-1 overflow-auto"
          onScroll={
            onScrollChange || onVisibleFileChange ? persistScroll : undefined
          }
          options={codeViewOptions}
          renderHeaderPrefix={renderHeaderPrefix}
          renderHeaderMetadata={
            renderHeaderMetadata
              ? (item) =>
                  renderHeaderMetadata(item, {
                    isLoading: build.loadingFilenames.has(item.id),
                  })
              : undefined
          }
          renderAnnotation={renderAnnotation}
        />
        {!isRulerEmpty(rulerMarkers) && (
          <OverviewRuler
            layers={[
              {
                markers: rulerMarkers.search,
                palette: SEARCH_PALETTE,
                onSelect: onSelectMatch,
                label: (n) => (n > 1 ? `${n} matches` : '1 match'),
              },
              {
                markers: rulerMarkers.symbol,
                palette: SYMBOL_PALETTE,
                onSelect: onSelectSymbolMarker,
                label: (n) => (n > 1 ? `${n} references` : '1 reference'),
              },
            ]}
          />
        )}
      </div>
      {toast && <Toast message={toast} />}
    </div>
  );
}

/** forwardRef + generics is awkward - the cast preserves the generic
 * signature without needing to spell out the full ref type. Callers
 * use `<DiffBody<MyMeta> ref={...} ... />` and get full type safety. */
export const DiffBody = forwardRef(DiffBodyInner) as <AMeta>(
  props: DiffBodyProps<AMeta> & {
    ref?: ForwardedRef<DiffBodyHandle<AMeta>>;
  },
) => ReturnType<typeof DiffBodyInner>;

/** Composed-path selector for "real" diff content + interactive overlays.
 *  A click whose path (between the target and the pane wrapper) contains
 *  none of these is an empty-space click that clears the line selection.
 *  Covers the lib's shadow-DOM diff rows (`data-line`/`data-content`/
 *  `data-gutter`), the file header (`data-diffs-header`/`data-title`), the
 *  annotation rows that host threads + composers (`data-line-annotation`),
 *  and any focusable control inside a slotted overlay. */
const DIFF_CONTENT_SELECTOR =
  '[data-line],[data-alt-line],[data-content],[data-gutter],' +
  '[data-gutter-utility-slot],[data-line-annotation],' +
  '[data-diffs-header],[data-title],[data-separator],' +
  '[data-separator-wrapper],button,a,input,textarea,' +
  '[contenteditable="true"]';

/** Light-DOM-only fallback selector for the rare path where
 *  `composedPath()` is unavailable: a click inside a file retargets to its
 *  `<diffs-container>` host, so the presence of that ancestor (or a slotted
 *  control) means "not empty space". */
const DIFF_CONTENT_FALLBACK_SELECTOR =
  'diffs-container,button,a,input,textarea,[contenteditable="true"]';

interface RulerLayer {
  markers: readonly SearchRulerMarker[];
  palette: RulerPalette;
  onSelect?: (index: number) => void;
  /** Tooltip text given a dot's collapsed count (e.g. "3 matches"). */
  label: (count: number) => string;
}

/** Overview-ruler - a column of dots, one per match/occurrence cluster,
 *  painted at its fractional position through the whole diff (VSCode's
 *  scrollbar overview). It's an absolute overlay pinned to the scroller's
 *  RIGHT edge so the dots sit directly on the scrollbar track; the track
 *  represents the entire content (not the scrolled viewport), so the dots
 *  stay put as the user scrolls. The container is transparent +
 *  pointer-events:none so the native scrollbar shows through and stays
 *  draggable - only the dots re-enable pointer events, so clicking one jumps
 *  to it. Renders any number of LAYERS (search = amber, symbol refs = blue),
 *  each with its own palette + click handler, sharing one overlay. */
function OverviewRuler({ layers }: { layers: readonly RulerLayer[] }) {
  return (
    <div
      // Pinned over the scrollbar; transparent + click-through except the
      // dots. z below the Toast (z-[5]). The dots are jump shortcuts -
      // the canonical next/prev controls live in the toolbar.
      // `data-overview-ruler` lets symbol-nav's document click handler treat a
      // dot click as its own UI (so it jumps via the dot's onClick instead of
      // clearing the selection as an "off-token" click).
      data-overview-ruler=""
      className="pointer-events-none absolute inset-y-0 right-0 z-[4] w-3.5"
      aria-hidden
    >
      {layers.flatMap((layer, li) =>
        layer.markers.map((m) => (
          <button
            key={`${li}:${m.matchIndex}:${m.frac.toFixed(4)}`}
            type="button"
            tabIndex={-1}
            onClick={() => layer.onSelect?.(m.matchIndex)}
            title={layer.label(m.count)}
            className="pointer-events-auto absolute left-1/2 -translate-x-1/2 -translate-y-1/2 cursor-pointer rounded-full transition-[width,height,background-color]"
            style={{
              top: `${(m.frac * 100).toFixed(3)}%`,
              width: m.active ? 8 : 5,
              height: m.active ? 8 : 3,
              backgroundColor: m.active ? layer.palette.activeBg : layer.palette.baseBg,
              boxShadow: m.active ? layer.palette.activeShadow : layer.palette.baseShadow,
            }}
          />
        )),
      )}
    </div>
  );
}

function Toast({ message }: { message: string }) {
  return (
    <div className="pointer-events-none absolute bottom-4 left-1/2 z-[5] -translate-x-1/2 rounded-full bg-foreground px-3.5 py-1.5 font-sans text-[12.5px] font-medium text-card shadow-[0_1px_2px_rgba(0,0,0,0.12),0_8px_24px_rgba(0,0,0,0.18)]">
      {message}
    </div>
  );
}

/** Shadow-DOM CSS that hides the lib's auto-generated +/− counts
 *  inside a FileDiff whose host element carries `data-pyor-loading`.
 *  The lib's createFileHeaderElement always emits at least one
 *  count span (it has an `if (additions > 0 || deletions === 0)`
 *  branch that fires when both are zero), so we can't suppress the
 *  output by zeroing the hunks alone. visibility:hidden preserves
 *  layout - the spinner pill in the metadata slot stays in its
 *  expected column. */
const PYOR_LOADING_UNSAFE_CSS = `
  :host([data-pyor-loading]) [data-additions-count],
  :host([data-pyor-loading]) [data-deletions-count] {
    visibility: hidden;
  }

  /* Image files: the stream item is a synthesised 1-line placeholder
     diff whose body we never want to show - only the file header and
     the injected \`image\` annotation row (the before/after preview).
     Hide the synthetic code line(s), the line-number gutter, the
     hunk separators, and the bogus +1/−0 header counts. The annotation
     row ([data-line-annotation]) is a sibling of [data-line] inside
     [data-code], so hiding the lines leaves the preview intact. Force
     the annotation full-width so it spans both columns in split view. */
  :host([data-pyor-image]) [data-line],
  :host([data-pyor-image]) [data-gutter],
  :host([data-pyor-image]) [data-separator],
  :host([data-pyor-image]) [data-separator-wrapper],
  :host([data-pyor-image]) [data-no-newline],
  :host([data-pyor-image]) [data-additions-count],
  :host([data-pyor-image]) [data-deletions-count] {
    display: none !important;
  }
  /* Centre the before/after preview across the FULL diff width. In split
     view the lib lays the two code columns on one grid; the annotation's
     grid item is its [data-content] wrapper (NOT [data-line-annotation],
     which is nested inside it), so stretch that. Dropping the now-empty
     deletions column keeps the preview from being trapped in the
     additions half. Works in unified too (single column, no-op del). */
  :host([data-pyor-image]) [data-code][data-deletions] {
    display: none !important;
  }
  /* Two levels of grid to break out of: [data-content] is a grid item
     of the outer PRE (the split column layout) AND is itself a subgrid
     whose track the [data-line-annotation] sits in. Span both so the
     preview fills the entire diff width. */
  :host([data-pyor-image]) [data-content],
  :host([data-pyor-image]) [data-line-annotation] {
    grid-column: 1 / -1 !important;
  }

  /* Rename / move / mode-only files: the stream item is a synthesised
     1-line placeholder with no real content. Hide the synthetic code
     line, gutter, separators, and the bogus +1/−0 counts (true counts
     are 0/0). The file header (with the old → new path) stays, and the
     file-composer annotation - a [data-line-annotation] sibling of
     [data-line] - stays visible so the file remains commentable. */
  :host([data-pyor-rename]) [data-line],
  :host([data-pyor-rename]) [data-gutter],
  :host([data-pyor-rename]) [data-separator],
  :host([data-pyor-rename]) [data-separator-wrapper],
  :host([data-pyor-rename]) [data-no-newline],
  :host([data-pyor-rename]) [data-additions-count],
  :host([data-pyor-rename]) [data-deletions-count] {
    display: none !important;
  }
  :host([data-pyor-rename]) [data-code][data-deletions] {
    display: none !important;
  }
  :host([data-pyor-rename]) [data-content],
  :host([data-pyor-rename]) [data-line-annotation] {
    grid-column: 1 / -1 !important;
  }
  /* Header path treatment (design AB-1): the lib already renders the old
     path → new path. Mute the old path so the eye lands on the new one,
     and hide the lib's change-type icon - our RenamePill (prefix slot)
     already carries the kind glyph, so the lib icon would be a duplicate.
     The rename arrow ([data-rename-icon]) stays as the "→" separator. */
  :host([data-pyor-rename]) [data-prev-name] {
    color: hsl(var(--muted-foreground)) !important;
    font-weight: 400 !important;
  }
  :host([data-pyor-rename]) [data-change-icon] {
    display: none !important;
  }

  /* Non-image binary files (.wasm, compiled blobs, …): the stream item is a
     synthesised 1-line placeholder with no real content. Hide the synthetic
     code line, gutter, separators, and the bogus +1/−0 counts. The file
     header stays, and the binary-note annotation - a [data-line-annotation]
     sibling of [data-line] - stays visible so the "Binary file" card shows. */
  :host([data-pyor-binary]) [data-line],
  :host([data-pyor-binary]) [data-gutter],
  :host([data-pyor-binary]) [data-separator],
  :host([data-pyor-binary]) [data-separator-wrapper],
  :host([data-pyor-binary]) [data-no-newline],
  :host([data-pyor-binary]) [data-additions-count],
  :host([data-pyor-binary]) [data-deletions-count] {
    display: none !important;
  }
  :host([data-pyor-binary]) [data-code][data-deletions] {
    display: none !important;
  }
  :host([data-pyor-binary]) [data-content],
  :host([data-pyor-binary]) [data-line-annotation] {
    grid-column: 1 / -1 !important;
  }

  /* Keep split-view columns a true 50/50 even when an injected row -
     e.g. an inline comment thread - carries wide, hard-to-break content.
     The lib's hydrated grid gives each code column a \`1fr\` track, whose
     \`auto\` minimum grows to the column's min-content; with overflow:wrap
     a wide comment then stretches its side and crushes the other (the
     opposite column wraps one character per line). Pin the content track
     to \`minmax(0, 1fr)\` - exactly what the lib itself uses in its
     dehydrated state - so neither column can exceed its half and the
     content wraps inside it instead. */
  :is([data-diff], [data-file]) {
    --diffs-code-grid: var(--diffs-grid-number-column-width) minmax(0, 1fr) !important;
  }

  /* Flatten the header-prefix slot wrapper to a layout pass-through so the
     caller's prefix content (chevron/pill group + an order:1 copy-path span)
     becomes direct flex children of [data-header-content]. Without this the
     lib's <div slot=header-prefix> is itself the single flex item, so flex
     \`order\` on the copy span can't slide it past the path title. */
  ::slotted([slot="header-prefix"]) {
    display: contents !important;
  }

  /* Sticky file headers: the lib paints them with --diffs-bg, identical
     to the code body, so they vanish into the diff while scrolling. Give
     them a subtly tinted background + a separator border so each file's
     boundary stays legible. The --diffs-bg-* vars are light-dark()-aware,
     so this reads correctly in both themes. */
  [data-diffs-header][data-sticky],
  [data-diffs-header=default] {
    background-color: var(--diffs-bg-buffer) !important;
    border-bottom: 1px solid var(--diffs-bg-separator) !important;
  }

  /* Hunk separator rows (the "@@ … @@" / expand-context lines): the lib's
     default tints them a faint grey off --diffs-bg. Recolor to GitHub's
     light-blue hunk header instead. --diffs-bg-separator is computed from
     this override token, so setting it here repaints the separator content,
     the expand buttons, and the gutter wrapper in one shot. light-dark()
     follows the active diff theme (the lib sets color-scheme: light dark),
     matching GitHub's #ddf4ff (light) / translucent blue (dark). */
  :host {
    --diffs-bg-separator-override: light-dark(#ddf4ff, #13233a);
  }

  /* Intra-line word/char diff emphasis fix - see diffEmphasisCss.ts. */
  ${DIFF_EMPHASIS_UNSAFE_CSS}

  /* Slim the hunk separator rows: the lib hardcodes their height at 32px
     (no exposed token), which reads a touch tall against the diff body.
     Trim to 26px - the expand buttons + "@@ … @@" content stretch to the
     row height, so the whole separator shrinks in lockstep. */
  [data-separator=line-info],
  [data-separator=line-info-basic],
  [data-separator=metadata] {
    height: 26px !important;
  }
`;

/** Walk every `<diffs-container>` in the diff pane and toggle the
 *  `data-pyor-loading` host attribute based on whether that file is
 *  in `loadingFilenames`. We identify each container by reading the
 *  `[data-title]` text inside its shadow root (the path the lib
 *  rendered into its own header). Called from onPostRender so the
 *  attribute stays in sync as items virtualize in and out. */
function tagLoadingContainers(
  node: HTMLElement,
  loadingFilenames: ReadonlySet<string>,
) {
  tagContainers(node, loadingFilenames, 'data-pyor-loading');
}

/** Generic version of the above: toggle `attr` on every
 *  `<diffs-container>` host whose file path is in `paths`. Used for
 *  both the loading-state and image-file host markers, each of which
 *  drives a `:host([attr])` rule in the injected shadow CSS. */
function tagContainers(
  node: HTMLElement,
  paths: ReadonlySet<string>,
  attr: string,
) {
  const containers = node.querySelectorAll<HTMLElement>('diffs-container');
  containers.forEach((host) => {
    const titleEl = host.shadowRoot?.querySelector<HTMLElement>('[data-title]');
    const path = titleEl?.textContent?.trim();
    if (!path) return;
    if (paths.has(path)) {
      host.setAttribute(attr, '');
    } else if (host.hasAttribute(attr)) {
      host.removeAttribute(attr);
    }
  });
}

/** Diff-pane skeleton - visible during the brief window between the
 * surface shell mount and the first file landing. 6 rows of file-
 * header-shaped bars at varying widths. */
function DiffPaneSkeleton() {
  const widths = [320, 280, 360, 240, 300, 270];
  return (
    <div
      aria-busy
      aria-label="Loading files…"
      className="min-h-0 flex-1 overflow-hidden bg-card py-2"
    >
      {widths.map((w, i) => (
        <div
          key={i}
          className="flex items-center gap-2 border-b bg-card px-4 py-2.5"
        >
          <div className="size-3 rounded-sm bg-muted opacity-60" />
          <div
            className="h-2.5 rounded-sm bg-muted opacity-60"
            style={{ width: w }}
          />
          <div className="flex-1" />
          <div className="h-2.5 w-10 rounded-sm bg-muted opacity-40" />
        </div>
      ))}
    </div>
  );
}

/** Amber summary banner above the diff body. Lists how many files
 *  weren't rendered, broken down by category - matches the
 *  shell-pr-loading-skipped-files artboard. The per-file
 *  `SkippedBody` cards inside the diff stream are the detail; this
 *  banner is the top-level "you saw 4 fewer diffs than you expected"
 *  reassurance that the absence is deliberate.
 *
 *  The "Show all on GitHub →" link is a window.open hook into the
 *  PR's /files page on github.com; we read repo coords from the
 *  ancestor <PRDetail> via a custom event so the banner stays
 *  prop-light. Falls back to a no-op when the URL can't be derived. */
function SkippedBanner({ skipped }: { skipped: BuildResult['skipped'] }) {
  const counts: Record<string, number> = {};
  for (const s of skipped) {
    const bucket = s.reason.startsWith('parse-error:')
      ? 'parse-error'
      : s.reason;
    counts[bucket] = (counts[bucket] ?? 0) + 1;
  }
  const HUMAN: Record<string, string> = {
    binary: 'binary',
    'too-large': 'over render limit',
    'parse-failed': "Pyor couldn't parse",
    'parse-undefined': "Pyor couldn't parse",
    'parse-error': "Pyor couldn't parse",
    'no-contents': 'no content yet',
    'content-fetch-failed': 'content fetch failed',
  };
  const summary = Object.entries(counts)
    .map(([k, v]) => `${v} ${HUMAN[k] ?? k}`)
    .join(' · ');
  // Read the PR's GitHub URL off the body data attribute the
  // PRDetailScreen sets on first render. Banner stays prop-light.
  const githubUrl = (() => {
    if (typeof document === 'undefined') return null;
    const link = document.querySelector<HTMLAnchorElement>(
      'a[data-pyor-pr-html-url]',
    );
    return link?.getAttribute('href') ?? null;
  })();
  return (
    <div
      className="flex shrink-0 items-start gap-2.5 border-b border-amber-200 bg-amber-50/60 px-5 py-2 text-[12.5px] text-amber-900 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200"
      title={skipped.map((s) => `${s.filename}: ${s.reason}`).join('\n')}
    >
      <span className="mt-0.5 inline-flex size-4 shrink-0 items-center justify-center rounded-full bg-amber-200/70 text-[10px] font-semibold text-amber-900 dark:bg-amber-900/60 dark:text-amber-100">
        i
      </span>
      <div className="flex-1 leading-relaxed">
        <b className="font-semibold">
          {skipped.length} file{skipped.length === 1 ? '' : 's'} can't be rendered here.
        </b>{' '}
        <span className="text-amber-800/80 dark:text-amber-300/80">
          {summary}. Each is marked in the diff stream below.
        </span>
      </div>
      {githubUrl && (
        <button
          type="button"
          onClick={() =>
            window.open(markGithubPassthrough(`${githubUrl}/files`), '_blank')
          }
          className="shrink-0 text-[12px] font-medium text-amber-900 underline-offset-2 hover:underline dark:text-amber-200"
        >
          Show all on GitHub →
        </button>
      )}
    </div>
  );
}
