// React glue for the collapse store. Pattern mirrors useViewedState:
// store is the source of truth, React state is the notification
// channel, snapshots are fresh Map instances so identity-based
// memoization works.

import { useEffect, useMemo, useState } from 'react';
import {
  makeCollapseStore,
  type CollapseOverride,
  type CollapseStore,
} from './collapseStore';

export interface CollapseHookValue {
  /** Effective collapsed state for `path`, given the auto-derived
   * fallback (typically `isViewed`). */
  isCollapsed(path: string, autoCollapsed: boolean): boolean;
  /** Has the user manually overridden this path's collapse state? */
  hasOverride(path: string): boolean;
  /** Click handler — flips the effective state, persisting an
   * override that points the opposite direction from the current
   * effective value. */
  toggle(path: string, autoCollapsed: boolean): void;
  /** Collapse all `paths`. */
  collapseAll(paths: ReadonlyArray<string>): void;
  /** Expand all `paths`. */
  expandAll(paths: ReadonlyArray<string>): void;
  /** Drop all overrides — everything falls back to viewed-state. */
  resetAll(): void;
  /** The full snapshot — only useful for downstream memoization
   * deps. */
  overrides: Map<string, CollapseOverride>;
}

export function useCollapseState(
  owner: string,
  repo: string,
  number: number,
): CollapseHookValue {
  const store = useMemo<CollapseStore>(
    () => makeCollapseStore(owner, repo, number),
    [owner, repo, number],
  );
  const [overrides, setOverrides] = useState<Map<string, CollapseOverride>>(
    () => store.snapshot(),
  );

  // If PR coords change, re-seed overrides from the new store.
  useEffect(() => {
    setOverrides(store.snapshot());
  }, [store]);

  const value = useMemo<CollapseHookValue>(() => {
    const apply = (mutator: () => void) => {
      // No animation: synchronous state mutation. We previously
      // wrapped this in document.startViewTransition with per-file
      // view-transition-name tagging to get a "row grows downward"
      // effect, but tagging diffs-container elements interfered
      // with @pierre/diffs' virtualizer (it reuses container nodes
      // across scroll batches; stale view-transition-names on those
      // recycled nodes broke layout). The lib has no built-in
      // collapse animation hook, so for now we just snap.
      mutator();
      setOverrides(store.snapshot());
    };
    return {
      isCollapsed(path, autoCollapsed) {
        const override = overrides.get(path);
        if (override === 'open') return false;
        if (override === 'closed') return true;
        return autoCollapsed;
      },
      hasOverride(path) {
        return overrides.has(path);
      },
      toggle(path, autoCollapsed) {
        const current = overrides.get(path);
        const effective =
          current === 'open' ? false : current === 'closed' ? true : autoCollapsed;
        const nextOverride: CollapseOverride = effective ? 'open' : 'closed';
        // If the new override would just match the auto-derived
        // default, clear it instead so the user sees consistent
        // behaviour with mark-viewed.
        if (
          (nextOverride === 'closed' && autoCollapsed) ||
          (nextOverride === 'open' && !autoCollapsed)
        ) {
          apply(() => store.clear(path));
        } else {
          apply(() => store.set(path, nextOverride));
        }
      },
      collapseAll(paths) {
        apply(() => store.setMany(paths, 'closed'));
      },
      expandAll(paths) {
        apply(() => store.setMany(paths, 'open'));
      },
      resetAll() {
        apply(() => store.clearAll());
      },
      overrides,
    };
  }, [overrides, store]);

  return value;
}
