// An <img> that transparently routes private GitHub comment attachments
// through the api proxy (see web/src/github/attachments.ts). Used by the
// Markdown renderer's `img` mapping so pasted screenshots in private-repo
// comments load instead of CORS-failing.
//
// Non-proxiable sources (public CDN images, pyor-attachment:// local
// images, external hosts) render as a plain <img> with zero overhead. For
// proxiable ones we fetch the bytes via React Query (cached + deduped
// across re-renders, exactly like ImageDiffSection's image panes) and wrap
// the Blob in an object URL. On failure we fall back to the raw <img> so a
// misclassified-but-public image still gets a chance to load.
//
// Clicking an image opens the ORIGINAL source URL in a new tab (system
// browser on desktop), mirroring GitHub's own behaviour — a real, shareable
// link rather than the throwaway object URL. Private GitHub assets open
// fine in a browser already signed in to github.com (the redirect to the
// signed S3 URL is granted off the session cookie there).

import { type ImgHTMLAttributes } from 'react';
import { useQuery } from '@tanstack/react-query';
import { fetchAttachmentBlob, isProxiableGithubImage } from '../github/attachments';
import { openExternalUrl } from '../desktop/openExternal';
import { useObjectUrl } from '../util/useObjectUrl';
import { bridge } from '../desktop/electronBridge';

/** Parse a `pyor-attachment://<reviewId>/<commentId>/<filename>` URL
 * (the reviewId is the hostname). Returns null for any other scheme. */
function parseLocalAttachment(
  src: unknown,
): { reviewId: string; commentId: string; filename: string } | null {
  if (typeof src !== 'string' || !src.startsWith('pyor-attachment://')) {
    return null;
  }
  try {
    const u = new URL(src);
    const parts = u.pathname.split('/').filter(Boolean);
    if (parts.length < 2) return null;
    return {
      reviewId: u.hostname,
      commentId: parts[0],
      filename: decodeURIComponent(parts.slice(1).join('/')),
    };
  } catch {
    return null;
  }
}

export function ProxiedImg({
  src,
  ...rest
}: ImgHTMLAttributes<HTMLImageElement>) {
  const proxiable = typeof src === 'string' && isProxiableGithubImage(src);

  const query = useQuery({
    queryKey: ['attachment-blob', src],
    queryFn: () => fetchAttachmentBlob(src as string),
    enabled: proxiable,
    staleTime: Infinity,
    gcTime: 10 * 60_000,
    retry: 1,
  });

  // Local pre-PR review attachments (`pyor-attachment://`) — resolve the
  // bytes to a `data:` URL via the bridge. The custom protocol can't be
  // loaded by a plain <img> under the dev server's http origin, and the
  // IPC route is origin-agnostic, so we always go through it on desktop.
  const local = parseLocalAttachment(src);
  const localQuery = useQuery({
    queryKey: ['local-attachment', src],
    queryFn: () =>
      bridge()!.localReviewAttachmentRead(
        local!.reviewId,
        local!.commentId,
        local!.filename,
      ),
    enabled: !!local && !!bridge(),
    staleTime: Infinity,
    gcTime: 10 * 60_000,
    retry: 0,
  });

  // Guard `instanceof Blob`: a query restored from a persisted snapshot
  // could carry a non-Blob (a serialized Blob collapses to `{}`), which
  // would throw in createObjectURL. Persistence now excludes blob queries
  // (see lib/persistGate.ts), but the guard keeps render crash-proof.
  const blob = query.data instanceof Blob ? query.data : null;
  // Shared, ref-counted object URL: a remount (Virtuoso scroll-eviction,
  // <Collapse> flip, tab round-trip) reuses the same blob: URL instead of
  // re-minting one and re-loading the image. See util/useObjectUrl.
  const objectUrl = useObjectUrl(blob);

  // Render an <img> whose displayed bytes come from `displaySrc` but whose
  // click opens the original `src` in a new tab. The cursor + title signal
  // it's clickable. No-op when there's no usable source URL to open.
  const renderImg = (displaySrc: string | undefined) => (
    <img
      src={displaySrc}
      {...rest}
      onClick={
        typeof src === 'string'
          ? (e) => {
              e.preventDefault();
              openExternalUrl(src);
            }
          : undefined
      }
      title={rest.title ?? 'Open image in new tab'}
      className={`cursor-zoom-in ${rest.className ?? ''}`}
    />
  );
  const placeholder = (
    <span
      role="img"
      aria-label={typeof rest.alt === 'string' ? rest.alt : 'image'}
      className={`inline-block min-h-[1.5rem] min-w-[6rem] animate-pulse rounded-[4px] bg-muted ${
        rest.className ?? ''
      }`}
    />
  );

  // Local attachment: render the resolved data URL; show a placeholder
  // while it loads; fall back to the raw scheme on null/error (the
  // packaged protocol handler still serves it).
  if (local) {
    const dataUrl =
      typeof localQuery.data === 'string' ? localQuery.data : null;
    if (dataUrl) return renderImg(dataUrl);
    if (localQuery.isLoading) return placeholder;
    return renderImg(src);
  }

  // Plain passthrough: nothing to proxy, or the proxy failed (fall back to
  // the original URL — public images still load; private ones show the
  // browser's broken-image glyph, same as before this change).
  if (!proxiable || query.isError) return renderImg(src);

  // Proxied bytes ready → render them. While the fetch is in flight, render
  // a same-shaped placeholder so layout doesn't jump.
  if (objectUrl) return renderImg(objectUrl);
  return placeholder;
}
